INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('008f3c74-c6ad-414c-87a5-b8beb7f8d99f', 'Crispy Sweet Potato Röstis with Fresh Dill Emulsion', 'Golden, caramelized sweet potato cakes balancing natural sugars with savory seasoning, paired with a bright, herbaceous dill mayonnaise. The texture contrasts a crunchy exterior with a tender, melting interior.', 'appetizer', 'Fusion', 'Intermediate', '["r\u00f6sti", "sweet potato", "mayonnaise", "vegetarian", "fritters", "brunch"]', '[{"group_name": "R\u00f6stis", "items": [{"name": "sweet potatoes", "quantity": 800, "unit": "g", "preparation": "peeled", "notes": "approx. 2 large potatoes", "substitutions": [], "ingredient_id": "579039f4-fa1e-4c91-8355-9dd037d188cd", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 8, "unit": "g", "preparation": null, "notes": "plus extra for finishing", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 30, "unit": "g", "preparation": null, "notes": "makes it crispier than flour", "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "beaten", "notes": "approx. 100g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "spring onions", "quantity": 3, "unit": null, "preparation": "finely sliced", "notes": "approx. 45g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "Aggregated Public Data"}, {"name": "neutral oil", "quantity": 120, "unit": "ml", "preparation": null, "notes": "for frying (grapeseed or vegetable)", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Dill Mayonnaise", "items": [{"name": "egg yolk", "quantity": 1, "unit": null, "preparation": "room temperature", "notes": "approx. 18g", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 150, "unit": "ml", "preparation": null, "notes": "grapeseed or sunflower", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh dill", "quantity": 15, "unit": "g", "preparation": "finely chopped, stems removed", "notes": null, "substitutions": [], "ingredient_id": "4be2b047-475d-4c84-82d5-4883298c6121", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "grated into paste", "notes": "approx. 4g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Using the coarse side of a box grater, shred the peeled sweet potatoes. Toss them in a large bowl with the 8g of salt. Let stand for 15 minutes to draw out moisture.", "structured": {"action": "GRATE", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "While potatoes rest, prepare the mayonnaise. In a bowl, whisk the egg yolk, Dijon mustard, garlic, and half the lemon juice until smooth. Slowly stream in the oil, whisking constantly, until a thick emulsion forms. Fold in the chopped dill and season with salt and remaining lemon to taste. Refrigerate.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": ["If the mayonnaise splits, start with a fresh yolk in a clean bowl and slowly whisk the broken mixture into it."]}, {"step_number": 3, "phase": "prep", "text": "Transfer the salted sweet potatoes to a clean kitchen towel or cheesecloth. Twist and squeeze vigorously to remove as much liquid as possible. The drier the potato, the crispier the r\u00f6sti.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Potatoes should feel dry and clumps should fall apart easily"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "In a clean bowl, mix the dried sweet potato shreds with the beaten eggs, cornstarch, sliced spring onions, and a pinch of black pepper. Mix until just combined.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Heat the frying oil in a heavy skillet over medium heat to 170\u00b0C/340\u00b0F. Working in batches, place mounds of the mixture (approx 80g each) into the pan and flatten gently with a spatula to 1.5cm thickness.", "structured": {"action": "FRY", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Fry for 3-4 minutes per side until deep golden brown and crispy. Monitor heat carefully; sweet potatoes contain sugar and can burn before cooking through if the heat is too high.", "structured": {"action": "FRY", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Deep golden brown edges", "tactile": "Solid and crispy to the touch"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Transfer cooked r\u00f6stis to a wire rack and sprinkle immediately with flaky salt. Serve warm with the chilled dill mayonnaise on the side.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT15M", "total_time": "PT50M", "overnight_required": false, "yields": "8 r\u00f6stis", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Vegetarian", "Gluten-Free", "Dairy-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Infants under 12 months (if honey substituted)", "Pregnant individuals (raw egg yolk)"]}', '{"per_serving": {"calories": 591.49, "protein_g": 7.59, "carbohydrates_g": 49.01, "fat_g": 41.44, "saturated_fat_g": 6.62, "trans_fat_g": 0.01, "monounsaturated_fat_g": 1.48, "polyunsaturated_fat_g": 0.69, "fiber_g": 6.56, "sugar_g": 12.55, "sodium_mg": 993.01, "cholesterol_mg": 141.6, "potassium_mg": 1009.84, "calcium_mg": 121.5, "iron_mg": 2.76, "magnesium_mg": 78.26, "phosphorus_mg": 76.49, "zinc_mg": 1.33, "vitamin_a_mcg": 11397.2, "vitamin_c_mg": 13.07, "vitamin_d_mcg": 0.74, "vitamin_e_mg": 0.45, "vitamin_k_mcg": 23.41, "vitamin_b6_mg": 0.09, "vitamin_b12_mcg": 0.31, "thiamin_mg": 0.03, "riboflavin_mg": 0.16, "niacin_mg": 0.15, "folate_mcg": 31.93, "water_g": 39.41, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store r\u00f6stis and mayonnaise in separate airtight containers. R\u00f6stis will lose crispness.", "duration": "P3D"}, "freezer": {"notes": "Freeze cooked r\u00f6stis in a single layer. Reheat from frozen in oven.", "duration": "P1M"}, "reheating": "Reheat r\u00f6stis in an oven at 180\u00b0C/350\u00b0F for 10-12 minutes to restore crispness. Do not microwave.", "does_not_keep": false}', '[{"name": "Box grater or food processor", "required": true, "alternative": null}, {"name": "Clean kitchen towel or cheesecloth", "required": true, "alternative": null}, {"name": "Heavy-bottomed frying pan or cast iron skillet", "required": true, "alternative": null}, {"name": "Whisk or immersion blender", "required": true, "alternative": "Food processor"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Wire rack", "required": true, "alternative": "Paper towel lined plate"}]', '[{"symptom": "R\u00f6stis are soggy or falling apart", "likely_cause": "Excess moisture was not removed from the potatoes", "prevention": "Squeeze the grated potatoes in a cloth until absolutely no more water drips out", "fix": "Add another tablespoon of cornstarch to the remaining batter and ensure oil is hot enough before frying next batch"}]', '["Sweet potatoes burn faster than white potatoes due to higher sugar content. Maintain medium heat rather than high heat.", "Using cornstarch instead of flour creates a lighter, gluten-free crunch that stays crispy longer.", "For perfectly uniform r\u00f6stis, you can press the mixture into a ring mold directly in the pan, then carefully remove the mold before flipping.", "The dill mayonnaise can be made up to 2 days in advance; the flavor actually improves as it sits."]', '"While the R\u00f6sti is a quintessential Swiss dish traditionally made with starchy white potatoes and served as a breakfast peasant dish in Bern, this variation utilizes the New World sweet potato. This modification adds a complex sweetness and vibrant color, bridging Alpine technique with modern global flavor preferences."', 591.49);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('01b8d4e8-08ba-4402-9035-ea8067866bb1', 'Lemony Basil Pesto Orzo', 'A vibrant, aromatic pasta dish featuring tender orzo tossed in a zesty modification of classic Genovese pesto. The extra lemon zest cuts through the richness of the pine nuts and cheese, creating a bright finish perfect for a quick lunch.', 'lunch', 'Italian', 'Easy', '["italian", "pastas", "basil", "lemon zest", "orzo", "easy", "quick", "vegetarian", "lunch"]', '[{"group_name": "Lemon Pesto", "items": [{"name": "fresh basil leaves", "quantity": 60, "unit": "g", "preparation": "washed and dried", "notes": "approx 2 packed cups", "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}, {"name": "pine nuts", "quantity": 40, "unit": "g", "preparation": null, "notes": null, "substitutions": ["walnuts", "almonds"], "ingredient_id": "971298ad-a9d7-49f7-811b-46afedad18d4", "nutrition_source": "Aggregated Public Data"}, {"name": "parmesan cheese", "quantity": 50, "unit": "g", "preparation": "grated", "notes": "Use vegetarian hard cheese if strictly vegetarian", "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "peeled", "notes": "cloves, approx 8-10g total", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": null, "unit": null, "preparation": null, "notes": "zest of 2 large lemons, approx 6-8g", "substitutions": [], "ingredient_id": "a5fb6a2a-dcda-4ab2-8fe6-472d7fcc39d1", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 80, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pasta & Assembly", "items": [{"name": "orzo pasta", "quantity": 350, "unit": "g", "preparation": null, "notes": "dried risoni", "substitutions": [], "ingredient_id": "ce13a672-d253-42dd-9db6-124717412d53", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 3000, "unit": "ml", "preparation": null, "notes": "for boiling", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 30, "unit": "g", "preparation": null, "notes": "for pasta water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the pine nuts in a dry small frying pan over medium heat. Toast, shaking the pan frequently, for 2-3 minutes until golden brown and fragrant. Remove immediately to a plate to cool.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown color", "tactile": "Fragrant nutty aroma"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Bring a large pot of salted water to a rolling boil (100\u00b0C/212\u00b0F). Add the orzo and cook according to package directions, usually 7-9 minutes, until al dente.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT9M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "While the pasta cooks, combine cooled pine nuts, garlic, basil, parmesan, and lemon zest in a food processor. Pulse until coarsely chopped.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "With the processor running, slowly drizzle in the olive oil and lemon juice until a vibrant, emulsified paste forms. Season with a pinch of salt. Taste and adjust.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["If the mixture is too thick, wait to thin it with hot pasta water in the final step rather than adding more oil."]}, {"step_number": 5, "phase": "finish", "text": "Reserve 120ml (approx 1/2 cup) of the starchy pasta cooking water. Drain the orzo thoroughly.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Return the orzo to the warm pot (off the heat). Add the pesto and a splash (30ml) of the reserved pasta water. Stir vigorously until the sauce coats each grain of pasta, adding more pasta water if needed to create a glossy texture.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Serve immediately, garnished with extra cracked black pepper and a little extra lemon zest if desired.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 280}', '{"flags": ["Vegetarian", "Egg-Free", "Soy-Free"], "not_suitable_for": ["Nut allergies", "Celiac disease (contains wheat gluten)"]}', '{"per_serving": {"calories": 613.45, "protein_g": 16.56, "carbohydrates_g": 67.54, "fat_g": 32.34, "saturated_fat_g": 5.37, "trans_fat_g": null, "monounsaturated_fat_g": 15.56, "polyunsaturated_fat_g": 2.24, "fiber_g": 10.61, "sugar_g": 2.19, "sodium_mg": 3369.13, "cholesterol_mg": 8.5, "potassium_mg": 141.97, "calcium_mg": 262.03, "iron_mg": 5.48, "magnesium_mg": 47.01, "phosphorus_mg": 153.25, "zinc_mg": 1.1, "vitamin_a_mcg": 65.6, "vitamin_c_mg": 7.11, "vitamin_d_mcg": 0.06, "vitamin_e_mg": 3.04, "vitamin_k_mcg": 74.95, "vitamin_b6_mg": 0.07, "vitamin_b12_mcg": 0.15, "thiamin_mg": 0.02, "riboflavin_mg": 0.06, "niacin_mg": 0.2, "folate_mcg": 12.16, "water_g": 773.82, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Orzo absorbs liquid quickly; add a splash of water or oil when reheating.", "duration": "P3D"}, "freezer": {"notes": "Pesto freezes well separately, but mixed pasta may become mushy upon thawing.", "duration": "P1M"}, "reheating": "Gently warm on the stove with a splash of water to loosen the sauce.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Food processor", "required": true, "alternative": "Mortar and pestle"}, {"name": "Small frying pan", "required": true, "alternative": null}, {"name": "Microplane or fine grater", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "Pesto turns brown/dull quickly", "likely_cause": "Oxidation of basil leaves from heat or air exposure", "prevention": "Blanch basil leaves for 10 seconds in boiling water then shock in ice water before processing", "fix": "Taste is unaffected; serve immediately or mix in fresh chopped parsley for color"}, {"symptom": "Pasta is clumpy", "likely_cause": "Orzo sat in the colander too long without oil/sauce", "prevention": "Toss with sauce immediately after draining", "fix": "Add a tablespoon of hot water and stir vigorously to separate grains"}]', '["Orzo (Risoni) is rice-shaped pasta, but it cooks much faster than rice. Be careful not to overcook it, or the dish will become mushy.", "Using the zest of two full lemons might seem like a lot, but the oils in the zest provide the floral lemon flavor without the sourness of too much juice.", "For a protein boost, this dish pairs exceptionally well with grilled shrimp or chickpeas.", "Always grate your own Parmesan cheese; pre-grated varieties often contain anti-caking agents that prevent smooth melting."]', '"Pesto alla Genovese originates from Liguria, Italy, traditionally consisting of basil, garlic, pine nuts, olive oil, and cheese pounded with a mortar and pestle. This variation uses Orzo, a pasta shape popular in soups and grain-style salads, and amplifies the citrus notes to create a lighter, more modern profile suitable for quick dining."', 613.45);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('021f07ec-03ae-4ef2-9cce-34e825b68683', 'Quick-Pickled Swiss Chard Stems', 'Transform fibrous leftovers into crunchy, jewel-toned tangy batons. These quick pickles offer a sharp acidic bite balanced by aromatic mustard seeds and garlic, perfect for cutting through rich salads or adding texture to grain bowls.', 'condiment', 'Modern', 'Easy', '["condiments", "swiss chard", "vegetable stock", "vegan", "vegetarian", "pickle", "zero waste"]', '[{"group_name": "Vegetable", "items": [{"name": "swiss chard stems", "quantity": 250, "unit": "g", "preparation": "cleaned and trimmed", "notes": "Leaves reserved for another use; use rainbow or red for color", "substitutions": [], "ingredient_id": "cb0f8ccb-3b9d-416c-995f-d0a7924af74c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Brine", "items": [{"name": "apple cider vinegar", "quantity": 150, "unit": "ml", "preparation": null, "notes": "Or white wine vinegar for a cleaner look", "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 150, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "granulated sugar", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 10, "unit": "g", "preparation": null, "notes": "Non-iodized is best", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics", "items": [{"name": "garlic", "quantity": 1, "unit": null, "preparation": "smashed", "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow mustard seeds", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "69e2b7a1-7252-486e-841e-51655b028a97", "nutrition_source": "Aggregated Public Data"}, {"name": "black peppercorns", "quantity": 2, "unit": "g", "preparation": "whole", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "red chili flakes", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "cdb6f7a0-4167-42e8-ae15-b15e3bf9918f", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Wash the chard stems thoroughly to remove any grit. Trim off the very ends and cut the stems into uniform 5cm (2 inch) batons or 1cm (0.5 inch) slices, depending on preference.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "assemble", "text": "Pack the chard stems vertically (if using batons) or tightly into a clean heat-proof jar. Tuck the smashed garlic, mustard seeds, peppercorns, and optional chili flakes in among the stems.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a small saucepan, combine the vinegar, water, sugar, and salt. Bring to a boil over medium-high heat, stirring occasionally until the sugar and salt have completely dissolved.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT3M", "doneness_cues": {"visual": "Liquid is clear and bubbling vigorously", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Pour the hot brine directly over the stems in the jar, ensuring they are completely submerged. Tap the jar gently on the counter to release any trapped air bubbles.", "structured": {"action": "POUR", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Let the jar cool to room temperature (approx 20-25\u00b0C / 68-77\u00b0F) uncovered. Once cool, seal tightly and refrigerate. Allow to pickle for at least 12 hours before serving for optimal flavor.", "structured": {"action": "COOL", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT12H", "total_time": "PT12H15M", "overnight_required": true, "yields": "1 pint jar", "yield_count": 1, "serving_size_g": 30}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Fat-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 307.15, "protein_g": 6.14, "carbohydrates_g": 65.71, "fat_g": 1.83, "saturated_fat_g": 0.18, "trans_fat_g": null, "monounsaturated_fat_g": 0.11, "polyunsaturated_fat_g": 0.21, "fiber_g": 5.21, "sugar_g": 53.72, "sodium_mg": 4426.61, "cholesterol_mg": null, "potassium_mg": 1134.2, "calcium_mg": 161.81, "iron_mg": 5.14, "magnesium_mg": 216.27, "phosphorus_mg": 137.81, "zinc_mg": 1.06, "vitamin_a_mcg": 765.54, "vitamin_c_mg": 76.56, "vitamin_d_mcg": null, "vitamin_e_mg": 4.74, "vitamin_k_mcg": 2078.37, "vitamin_b6_mg": 0.32, "vitamin_b12_mcg": null, "thiamin_mg": 0.11, "riboflavin_mg": 0.24, "niacin_mg": 1.05, "folate_mcg": 35.49, "water_g": 525.66, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Keep submerged in brine.", "duration": "P3W"}, "freezer": {"notes": "Do not freeze; texture will degrade.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Heat-proof glass jar (500ml)", "required": true, "alternative": "Ceramic container with lid"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Stems are too soft or mushy", "likely_cause": "The stems were boiled in the brine rather than having brine poured over them", "prevention": "Keep stems raw and pour hot liquid over them to maintain crunch", "fix": "Cannot be fixed; use pureed in a dressing instead"}]', '["Using red chard stems will turn the brine a brilliant pink color after 24 hours.", "Do not discard the pickling liquid when the stems are gone; use it as a vinaigrette base or to pickle red onions.", "For a deeper, earthier flavor, swap 50ml of the water for filtered vegetable stock, though this may reduce clarity.", "Make sure the stems are dry after washing to prevent diluting the brine."]', '"Pickling vegetable scraps is a time-honored practice in kitchens worldwide to reduce waste and extend seasonality. While Swiss chard is Mediterranean in origin, this quick-pickle technique is a staple of modern zero-waste gastronomy."', 307.15);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('03156bb4-6869-4214-920e-fba0a5b9a64b', 'Chocolate Vanilla Impossible Cake', 'A gravity-defying culinary magic trick where a layer of tender vanilla buttermilk cake swaps places with a rich chocolate custard during baking. The result is a stunning two-tone dessert with a moist cake base and a silky, creamy flan topping, glazed in its own caramel sauce.', 'dessert', 'Mexican', 'Intermediate', '["southern", "custards and puddings", "bundt cake", "chocolate", "condensed milk", "evaporated milk", "dessert", "magic cake", "chocoflan"]', '[{"group_name": "Caramel Layer", "items": [{"name": "white granulated sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vanilla Cake Layer", "items": [{"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "white granulated sugar", "quantity": 200, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "large egg", "quantity": 1, "unit": null, "preparation": "room temperature", "notes": "approx 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "all-purpose flour", "quantity": 210, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 0.5 tsp", "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 4, "unit": "g", "preparation": null, "notes": "approx 0.75 tsp", "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "buttermilk", "quantity": 240, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "de1c3d44-e3e7-47d2-a315-83a46edfb165", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Chocolate Flan Layer", "items": [{"name": "evaporated milk", "quantity": 354, "unit": "ml", "preparation": null, "notes": "1 standard can", "substitutions": [], "ingredient_id": "684e9506-fd34-4087-bcbd-d3a263aa2ee5", "nutrition_source": "Aggregated Public Data"}, {"name": "sweetened condensed milk", "quantity": 397, "unit": "g", "preparation": null, "notes": "1 standard can", "substitutions": [], "ingredient_id": "d9d1435b-7445-46fd-a682-be48baaad067", "nutrition_source": "USDA FoodData Central"}, {"name": "cream cheese", "quantity": 115, "unit": "g", "preparation": "softened", "notes": null, "substitutions": [], "ingredient_id": "262c67de-76a4-4444-8c02-30ad4a179459", "nutrition_source": "USDA FoodData Central"}, {"name": "large eggs", "quantity": 4, "unit": null, "preparation": "room temperature", "notes": "approx 200g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "cocoa powder", "quantity": 45, "unit": "g", "preparation": null, "notes": "unsweetened", "substitutions": [], "ingredient_id": "c06a8e5a-163a-4f21-ad00-a6d90e34c38c", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 175\u00b0C (350\u00b0F). Grease the Bundt pan thoroughly with butter or non-stick cooking spray, ensuring every crevice is coated to prevent sticking.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Pour the sugar for the caramel into a saucepan over medium heat. Melt, stirring constantly once it begins to liquefy, until it turns a deep amber color. Immediately pour into the prepared Bundt pan and swirl to coat the bottom evenly. Work quickly as it hardens fast.", "structured": {"action": "CARAMELIZE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Deep amber color, completely liquid", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a stand mixer, cream the butter and 200g sugar until light and fluffy (about 3 minutes). Beat in the egg and 10ml vanilla extract until combined.", "structured": {"action": "CREAM", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In a separate bowl, whisk together flour, baking powder, baking soda, and salt. Add the dry ingredients to the butter mixture in three parts, alternating with the buttermilk, starting and ending with the flour. Mix just until combined. Spoon this batter into the Bundt pan over the hardened caramel and smooth the top.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "In a blender, combine evaporated milk, condensed milk, softened cream cheese, 4 eggs, cocoa powder, and 5ml vanilla. Blend on high until completely smooth, about 30-45 seconds.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT45S", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Slowly pour the chocolate flan mixture over the vanilla cake batter. Do not mix them. Even though it looks like the flan sits on top now, they will switch places in the oven.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Cover the Bundt pan loosely with foil. Place the Bundt pan inside the large roasting pan. Fill the roasting pan with hot water until it reaches about 2.5 cm (1 inch) up the side of the Bundt pan (bain-marie). Bake for 60 to 75 minutes.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT1H15M", "doneness_cues": {"visual": null, "tactile": "Cake surface springs back, toothpick inserted comes out clean"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove the Bundt pan from the water bath and let it cool on a wire rack to room temperature (about 1 hour). Then, refrigerate for at least 8 hours or overnight. This is crucial for the flan to set and release properly.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT8H", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "To serve, run a thin knife carefully around the edges. Place a large serving platter over the pan and invert quickly. The caramel will flow down over the chocolate flan, which is now sitting atop the vanilla cake.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT9H", "total_time": "PT9H45M", "overnight_required": true, "yields": "1 Bundt Cake (12 servings)", "yield_count": 12, "serving_size_g": 180}', '{"flags": ["Vegetarian"], "not_suitable_for": ["Vegans", "Gluten Intolerance", "Lactose Intolerance"]}', '{"per_serving": {"calories": 507.08, "protein_g": 12.36, "carbohydrates_g": 69.87, "fat_g": 20.84, "saturated_fat_g": 12.42, "trans_fat_g": 0.12, "monounsaturated_fat_g": 4.9, "polyunsaturated_fat_g": 1.03, "fiber_g": 1.86, "sugar_g": 54.2, "sodium_mg": 356.83, "cholesterol_mg": 119.83, "potassium_mg": 307.32, "calcium_mg": 183.68, "iron_mg": 1.22, "magnesium_mg": 37.14, "phosphorus_mg": 207.28, "zinc_mg": 1.1, "vitamin_a_mcg": 155.68, "vitamin_c_mg": 1.06, "vitamin_d_mcg": 0.48, "vitamin_e_mg": 0.6, "vitamin_k_mcg": 1.3, "vitamin_b6_mg": 0.08, "vitamin_b12_mcg": 0.41, "thiamin_mg": 0.07, "riboflavin_mg": 0.31, "niacin_mg": 0.41, "folate_mcg": 21.33, "water_g": 52.36, "alcohol_g": 0.43, "caffeine_mg": 8.63}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Keep covered to prevent the flan from absorbing fridge odors.", "duration": "P4D"}, "freezer": {"notes": "Freezing is not recommended as it ruins the texture of the flan layer.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Bundt pan (10-12 cup capacity)", "required": true, "alternative": null}, {"name": "Large roasting pan", "required": true, "alternative": "Any oven-safe pan large enough to hold the Bundt pan for a water bath"}, {"name": "Blender", "required": true, "alternative": null}, {"name": "Stand mixer or hand mixer", "required": true, "alternative": null}, {"name": "Saucepan", "required": true, "alternative": null}]', '[{"symptom": "Cake stuck to the pan upon inversion", "likely_cause": "Caramel hardened too much or pan wasn''t greased well enough", "prevention": "Grease the pan very thoroughly before adding caramel; ensure the cake is fully chilled before flipping", "fix": "Place the pan in a warm water bath for 2-3 minutes to loosen the caramel, then try flipping again"}, {"symptom": "Layers did not switch places distinctly", "likely_cause": "Oven temperature was too low or water bath was too cold, preventing the density exchange", "prevention": "Ensure oven is fully preheated and use hot water for the bath", "fix": "Cannot be fixed, but still edible and delicious as a marbled cake"}]', '["The ''magic'' works because the baking soda and powder in the cake batter make it less dense as it cooks, causing it to float, while the dense, egg-heavy flan sinks to the bottom of the mold.", "Do not skip the water bath (bain-marie). It regulates the heat gently, ensuring the custard cooks creamy and smooth without curdling while the cake rises.", "Patience is the most critical ingredient. If you try to unmold this warm, it will collapse. The caramel needs the cold fridge time to liquefy into a sauce.", "For the cleanest layers, ensure your cream cheese is very soft before blending to avoid lumps in the flan."]', '"Known as ''Pastel Imposible'' in Mexico, this dessert marries the Spanish heritage of flan with the modern popularity of cake. It has been warmly embraced by Southern US cuisine, where rich, custard-based desserts and bundt cakes are staples."', 507.08);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('03200730-85ce-41fc-bb11-c06f3dcd7d28', 'Irish Rhubarb Custard Flan', 'A celebration of Irish spring produce, featuring a buttery, crisp pâte sucrée shell filled with silky vanilla bean custard. Tart, crimson rhubarb purée is artfully swirled on top, providing a striking visual contrast and a sharp acidity to cut through the creaminess.', 'dessert', 'Irish', 'Intermediate', '["irish", "rhubarb", "dessert", "tart", "spring", "custard"]', '[{"group_name": "Sweet Shortcrust Pastry", "items": [{"name": "all-purpose flour", "quantity": 200, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 100, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "icing sugar", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "egg yolk", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 18g", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}, {"name": "cold water", "quantity": 15, "unit": "ml", "preparation": null, "notes": "add only if dough is too dry", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Rhubarb Swirl", "items": [{"name": "rhubarb", "quantity": 300, "unit": "g", "preparation": "chopped into 2cm pieces", "notes": "forced rhubarb yields best color", "substitutions": [], "ingredient_id": "293d2132-013e-4594-801e-4d86e1d04df0", "nutrition_source": "USDA FoodData Central"}, {"name": "caster sugar", "quantity": 75, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Custard Filling", "items": [{"name": "heavy cream", "quantity": 300, "unit": "ml", "preparation": null, "notes": "35% fat or higher", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 100, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "egg yolks", "quantity": 5, "unit": null, "preparation": null, "notes": "approx 90g", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}, {"name": "caster sugar", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla bean paste", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "90237166-b129-4858-8c9c-2f8a7ab9a301", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place flour, icing sugar, salt, and cold cubed butter in a food processor. Pulse briefly until the mixture resembles fine breadcrumbs. Add the egg yolk and pulse again until the dough just starts to clump together. If too dry, add cold water sparingly.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Turn dough onto a surface, gently bring it into a disc (do not knead), wrap in plastic, and chill in the refrigerator for at least 30 minutes.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Combine chopped rhubarb, 75g sugar, lemon juice, and water in a saucepan over medium heat. Simmer until the rhubarb completely breaks down and thickens significantly, about 15 minutes. Puree with a blender until smooth and let cool completely.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT15M", "doneness_cues": {"visual": "Thick, jam-like consistency", "tactile": "Soft and yielding"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Preheat oven to 190\u00b0C/375\u00b0F. Roll out the chilled pastry to 3mm thickness and line the tart tin. Prick the base with a fork, line with parchment paper, and fill with baking beans. Blind bake for 15 minutes.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Remove beans and parchment. Reduce oven to 170\u00b0C/340\u00b0F. Bake the pastry case for another 5-8 minutes until the base is sandy and dry to the touch.", "structured": {"action": "BAKE", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "While the shell cools slightly, whisk the egg yolks, 60g sugar, cream, milk, and vanilla paste together gently. Do not over-whisk; avoid creating air bubbles. Strain through a sieve to ensure smoothness.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Pour the custard mixture into the tart shell. Dollop spoonfuls of the cooled rhubarb puree onto the surface. Use a skewer or knife tip to gently swirl the rhubarb into the custard, creating a marbled effect.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Bake at 150\u00b0C/300\u00b0F for 30-35 minutes. The custard should be set around the edges but still have a slight wobbly jiggle in the very center. It will continue to set as it cools.", "structured": {"action": "BAKE", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": "PT35M", "doneness_cues": {"visual": "Slight wobble in center, edges set", "tactile": "Firm edges"}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Allow to cool completely in the tin at room temperature before slicing. This resting period is critical for the custard structure.", "structured": {"action": "COOL", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT2H30M", "total_time": "PT3H15M", "overnight_required": false, "yields": "1 23cm flan (8 servings)", "yield_count": 8, "serving_size_g": 165}', '{"flags": ["Vegetarian"], "not_suitable_for": ["Vegans", "Celiacs"]}', '{"per_serving": {"calories": 457.21, "protein_g": 6.63, "carbohydrates_g": 46.24, "fat_g": 27.98, "saturated_fat_g": 16.52, "trans_fat_g": 0.47, "monounsaturated_fat_g": 8.06, "polyunsaturated_fat_g": 1.7, "fiber_g": 1.35, "sugar_g": 25.41, "sodium_mg": 74.19, "cholesterol_mg": 216.3, "potassium_mg": 206.37, "calcium_mg": 95.7, "iron_mg": 0.8, "magnesium_mg": 14.91, "phosphorus_mg": 120.25, "zinc_mg": 0.68, "vitamin_a_mcg": 298.69, "vitamin_c_mg": 3.71, "vitamin_d_mcg": 1.49, "vitamin_e_mg": 1.11, "vitamin_k_mcg": 13.27, "vitamin_b6_mg": 0.09, "vitamin_b12_mcg": 0.4, "thiamin_mg": 0.08, "riboflavin_mg": 0.2, "niacin_mg": 0.47, "folate_mcg": 31.59, "water_g": 84.72, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Keep loosely covered to prevent pastry from softening too quickly.", "duration": "P3D"}, "freezer": {"notes": "Custard-based tarts do not freeze well as the texture separates.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "23cm loose-bottomed tart tin", "required": true, "alternative": null}, {"name": "Food processor", "required": false, "alternative": "Large mixing bowl and pastry cutter"}, {"name": "Rolling pin", "required": true, "alternative": null}, {"name": "Ceramic baking beans or uncooked rice", "required": true, "alternative": null}, {"name": "Saucepan", "required": true, "alternative": null}, {"name": "Fine mesh sieve", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}]', '[{"symptom": "Soggy pastry bottom", "likely_cause": "Under-baked during the blind baking stage or filling poured while pastry was too hot", "prevention": "Ensure the base is sandy and dry after removing baking beans before adding wet filling", "fix": "Cannot be fixed once baked; serve as is"}, {"symptom": "Custard has curdled or looks grainy", "likely_cause": "Oven temperature was too high or baked too long", "prevention": "Bake at low temperature (150\u00b0C) and remove while center still wobbles", "fix": "Cannot be fixed"}]', '["Use ''forced rhubarb'' (grown in dark sheds) early in the year for a sweeter flavor and a vibrant shocking pink color compared to field-grown rhubarb.", "When blind baking, ensure the pastry is pushed right into the corners of the tin. If it is stretched, it will shrink back down the sides during baking.", "Skim any foam off the top of the custard before baking for a glass-like, professional finish.", "For a cleaner slice, use a serrated knife for the crust edges and wipe the blade clean between every cut."]', '"Rhubarb, often called the ''pie plant,'' thrives in the cool, damp Irish climate and is a staple of country cooking. Traditionally paired with custard to balance its intense tartness, this refined tart elevates the humble backyard ingredient into a patisserie-style dessert."', 457.21);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('038edc03-3113-4ce0-9ee6-aaf500463078', 'Zesty Thai Lemongrass Chicken Noodle Stir-fry', 'A vibrant and aromatic stir-fry balancing the bright citrus notes of fresh lemongrass and kaffir lime leaves with the deep umami of shiitake mushrooms. Tender velveted chicken breast mingles with slippery rice noodles in a savory-sour sauce, finished with a fresh herb explosion perfect for summer evenings.', 'dinner', 'Thai', 'Intermediate', '["thai", "chicken breast", "lemongrass", "mushroom", "dinner", "main course", "summer", "dairy-free", "stir-fry", "noodles"]', '[{"group_name": "Chicken & Marinade", "items": [{"name": "chicken breast", "quantity": 500, "unit": "g", "preparation": "thinly sliced against grain", "notes": "boneless, skinless", "substitutions": [], "ingredient_id": "2b577d04-33ca-4919-938f-bfc8780a3a4b", "nutrition_source": "USDA FoodData Central"}, {"name": "soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": "light soy sauce", "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "cornstarch", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Aromatics & Vegetables", "items": [{"name": "dried rice noodles", "quantity": 200, "unit": "g", "preparation": "medium width (3-5mm)", "notes": null, "substitutions": [], "ingredient_id": "9f0e8ac0-732e-404a-ada2-c29791e7d269", "nutrition_source": "USDA FoodData Central"}, {"name": "lemongrass stalks", "quantity": 2, "unit": null, "preparation": "tender cores only, minced", "notes": "approx 30g prepared", "substitutions": [], "ingredient_id": "6dde667b-d122-48d9-a70f-a4f820fc5bd5", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh shiitake mushrooms", "quantity": 200, "unit": "g", "preparation": "sliced", "notes": null, "substitutions": [], "ingredient_id": "127ce8a8-238d-40e6-a4b0-c58c42a7c745", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "minced", "notes": "approx 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "red thai chilies", "quantity": 2, "unit": null, "preparation": "sliced", "notes": "adjust to taste", "substitutions": [], "ingredient_id": "5080eb9a-d555-4558-94e5-d5700e96ff9b", "nutrition_source": "Aggregated Public Data"}, {"name": "kaffir lime leaves", "quantity": 4, "unit": null, "preparation": "thinly sliced (chiffonade)", "notes": "remove central vein first", "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Stir-fry Sauce", "items": [{"name": "oyster sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "322ccc47-a56e-40df-b324-59f7944393b8", "nutrition_source": "Aggregated Public Data"}, {"name": "fish sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "95a9a747-50ee-4be0-84be-0dfc96111e2a", "nutrition_source": "Aggregated Public Data"}, {"name": "palm sugar", "quantity": 15, "unit": "g", "preparation": "shaved/grated", "notes": "can substitute light brown sugar", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Finishing", "items": [{"name": "vegetable oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "for frying", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "lime juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 15, "unit": "g", "preparation": "roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the dried rice noodles in a heat-proof bowl and cover with warm water (not boiling). Let soak for 15-20 minutes until pliable but still firm (al dente). Drain and set aside.", "structured": {"action": "SOAK", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": ["Do not boil the noodles; they will turn to mush in the wok.", "If noodles are sticking after draining, toss with a teaspoon of oil."]}, {"step_number": 2, "phase": "prep", "text": "In a mixing bowl, combine the sliced chicken breast with 15ml soy sauce, 5g cornstarch, and 5ml vegetable oil. Mix well and let sit for 10 minutes.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Whisk together oyster sauce, fish sauce, palm sugar, and water in a small bowl until the sugar dissolves completely.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Heat half the vegetable oil (15ml) in a wok over high heat. Add the chicken in a single layer. Sear undisturbed for 1 minute, then stir-fry until cooked through (internal temp 74\u00b0C/165\u00b0F). Remove chicken from wok and set aside.", "structured": {"action": "SEAR", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": "PT4M", "doneness_cues": {"visual": "Golden brown edges, opaque center", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Wipe the wok if needed. Add remaining oil (15ml) over medium-high heat. Add minced lemongrass, garlic, chilies, and shiitake mushrooms. Stir-fry for 2 minutes until mushrooms are tender and aromatics are fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Mushrooms browned", "tactile": "Aromatics fragrant but not burnt"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Add the drained noodles and the sauce mixture to the wok. Toss vigorously for 1-2 minutes to ensure the noodles absorb the sauce and heat through.", "structured": {"action": "STIR", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Return the chicken to the pan along with the kaffir lime leaves. Toss to combine. Remove from heat immediately.", "structured": {"action": "ASSEMBLY", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Stir in the fresh lime juice and chopped cilantro. Serve immediately.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT15M", "total_time": "PT40M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 380}', '{"flags": ["Dairy-Free", "Pescatarian", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 538.51, "protein_g": 31.22, "carbohydrates_g": 55.03, "fat_g": 20.96, "saturated_fat_g": 4.67, "trans_fat_g": 0.13, "monounsaturated_fat_g": 4.86, "polyunsaturated_fat_g": 2.53, "fiber_g": 2.34, "sugar_g": 6.07, "sodium_mg": 1380.19, "cholesterol_mg": 80, "potassium_mg": 575.15, "calcium_mg": 45.84, "iron_mg": 3.39, "magnesium_mg": 60.95, "phosphorus_mg": 375.14, "zinc_mg": 2.1, "vitamin_a_mcg": 111.25, "vitamin_c_mg": 11.84, "vitamin_d_mcg": 0.7, "vitamin_e_mg": 0.41, "vitamin_k_mcg": 0.08, "vitamin_b6_mg": 0.85, "vitamin_b12_mcg": 0.43, "thiamin_mg": 0.1, "riboflavin_mg": 0.24, "niacin_mg": 14.47, "folate_mcg": 13.62, "water_g": 151.81, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Reheat gently to avoid drying out chicken; noodles may lose some texture.", "duration": "P3D"}, "freezer": {"notes": "Rice noodles do not freeze well; texture becomes mealy.", "duration": null}, "reheating": "Stir-fry briefly in a pan with a splash of water, or microwave covered with a damp paper towel.", "does_not_keep": false}', '[{"name": "Wok or large skillet", "required": true, "alternative": "Large frying pan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Heat-proof bowl", "required": true, "alternative": "Pot for soaking noodles"}]', '[{"symptom": "Noodles are clumpy and sticky", "likely_cause": "Noodles were soaked too long or boiled", "prevention": "Soak in warm water only until pliable; do not boil.", "fix": "Add a splash of water or oil to the wok and toss vigorously to separate."}, {"symptom": "Dish is too salty", "likely_cause": "Brand differences in fish sauce or oyster sauce", "prevention": "Taste sauce mix before adding to wok.", "fix": "Add extra lime juice and a pinch of sugar to balance the salinity."}]', '["Velveting the chicken (coating with cornstarch and oil) protects the meat from high heat, keeping it juicy even if sliced thinly.", "Lemongrass can be fibrous; ensure you peel away the tough outer layers and use only the bottom third of the stalk, minced very finely.", "Kaffir lime leaves are tough to eat whole; slicing them into a fine chiffonade allows their aroma to distribute without being unpleasant to chew.", "Mise en place is critical for stir-fries. Have all ingredients chopped and sauces mixed before turning on the stove."]', '"While this specific recipe is a modern interpretation, it draws heavily on the flavor profile of ''Tom Yum'' (hot and sour) soups and ''Pad Kee Mao'' (Drunken Noodles). The use of medicinal aromatics like lemongrass and galangal reflects the Thai philosophy of food as medicine, balancing the four key flavors: salty, sweet, sour, and spicy."', 538.51);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('050efb9a-d9ee-4094-a63a-6cc09760c266', 'Velvety Potage Germiny (Cream of Sorrel Soup)', 'A sophisticated yet simple French classic where the sharp, lemony acidity of fresh sorrel is perfectly balanced by a rich liaison of egg yolks and cream. The soup boasts a pale green hue and a luxurious, velvety texture that coats the spoon.', 'soup', 'French', 'Intermediate', '["chicken stock", "egg", "five ingredient", "great leftovers", "sorrel", "soup", "weeknight", "appetizer", "side dish", "fall", "french", "gluten-free"]', '[{"group_name": "Base", "items": [{"name": "fresh sorrel leaves", "quantity": 300, "unit": "g", "preparation": "washed, stemmed, and shredded", "notes": "approx 3-4 large bunches", "substitutions": [], "ingredient_id": "765ed343-bfc0-4671-9d31-fb127e371872", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "chicken stock", "quantity": 1000, "unit": "ml", "preparation": "high quality", "notes": null, "substitutions": [], "ingredient_id": "7e254f45-046f-4812-bcdd-7e31c9bb59b8", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Liaison (Thickening Agent)", "items": [{"name": "egg yolks", "quantity": 4, "unit": null, "preparation": "large", "notes": "approx 72g", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 120, "unit": "ml", "preparation": "35% fat or higher", "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": "fine sea salt", "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the sorrel by removing tough stems and washing thoroughly. Stack the leaves, roll them tightly (cigar style), and slice thinly into a chiffonade.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a heavy-bottomed pot over medium heat, melt the butter. Add the shredded sorrel and saut\u00e9 until it wilts and turns an olive-drab color. This happens very quickly.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT3M", "doneness_cues": {"visual": "Leaves are fully wilted and volume is significantly reduced", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Pour the chicken stock into the pot with the sorrel. Bring to a boil, then reduce heat and simmer gently for 10 minutes to infuse the broth with the sorrel''s acidity.", "structured": {"action": "SIMMER", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "While the soup simmers, whisk the egg yolks and heavy cream together in a separate mixing bowl until smooth and pale yellow.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Temper the eggs: Remove the soup pot from the heat. Slowly ladle about 250ml (1 cup) of the hot broth into the egg mixture while whisking constantly and vigorously to raise the egg temperature without scrambling them.", "structured": {"action": "TEMPER", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Pour the tempered egg mixture back into the main soup pot. Return the pot to very low heat. Stir constantly with a spoon or spatula until the soup thickens slightly and coats the back of the spoon. Do not let it boil, or the eggs will curdle.", "structured": {"action": "MIX", "temperature": {"celsius": 82, "fahrenheit": 180}, "duration": null, "doneness_cues": {"visual": "Velvety consistency", "tactile": "Coats back of spoon (nappe)"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Season with salt to taste. Serve immediately in warmed bowls.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["The sorrel is naturally salty and tart, so taste before adding salt."]}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 300}', '{"flags": ["Gluten-Free", "Nut-Free", "Soy-Free", "Low-Carb", "Keto"], "not_suitable_for": ["Vegans", "Dairy-Free diets"]}', '{"per_serving": {"calories": 348.62, "protein_g": 11.56, "carbohydrates_g": 12.12, "fat_g": 28.21, "saturated_fat_g": 14.3, "trans_fat_g": 0.37, "monounsaturated_fat_g": 7.47, "polyunsaturated_fat_g": 1.56, "fiber_g": 2.59, "sugar_g": 3.48, "sodium_mg": 1031.98, "cholesterol_mg": 252.49, "potassium_mg": 50.86, "calcium_mg": 90.09, "iron_mg": 0.53, "magnesium_mg": 3.23, "phosphorus_mg": 90.3, "zinc_mg": 0.5, "vitamin_a_mcg": 1168.83, "vitamin_c_mg": 36.18, "vitamin_d_mcg": 1.45, "vitamin_e_mg": 1, "vitamin_k_mcg": 1.87, "vitamin_b6_mg": 0.08, "vitamin_b12_mcg": 0.42, "thiamin_mg": 0.04, "riboflavin_mg": 0.16, "niacin_mg": 0.03, "folate_mcg": 27.82, "water_g": 28.55, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Reheat very gently to avoid scrambling the eggs.", "duration": "P2D"}, "freezer": {"notes": "Do not freeze; the emulsion will break and texture will become grainy.", "duration": null}, "reheating": "Warm over low heat, stirring constantly. Do not let the soup simmer or boil.", "does_not_keep": false}', '[{"name": "Heavy-bottomed soup pot", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Ladle", "required": true, "alternative": null}]', '[{"symptom": "Soup has small grainy lumps", "likely_cause": "The eggs scrambled because the soup boiled or was not tempered correctly", "prevention": "Ensure the soup is off the heat when adding the egg mixture and never let it boil after the liaison is added", "fix": "Immediately strain through a fine-mesh sieve or blitz quickly with an immersion blender to smooth the texture"}]', '["Sorrel turns from bright green to army green/olive when heated due to the acid affecting the chlorophyll. This is normal and traditional for this soup.", "If you cannot find fresh sorrel, you can use spinach and add lemon juice to mimic the acidity, though the flavor profile will lack the specific herbal notes of sorrel.", "Serve with crusty baguette or croutons to add a textural crunch against the creamy soup.", "This technique implies a ''liaison,'' which replaces a flour-based roux for thickening. It provides a much cleaner, glossier mouthfeel."]', '"Often known as Potage Germiny, this dish was created by Chef Adolphe Dugl\u00e9r\u00e9 at the Caf\u00e9 Anglais in Paris in the 19th century. It highlights the French appreciation for sorrel''s unique tartness, softening it with the richness of a classic egg-cream liaison."', 348.62);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('051dbcad-7a6e-4cf4-82aa-2fb16a7f19d1', 'Cornell Chicken', 'A legendary upright barbecue chicken featuring a unique emulsified marinade of egg, vinegar, and oil. The sauce creates a glossy, tangy, and crisp lacquer while keeping the meat incredibly juicy.', 'dinner', 'American', 'Intermediate', '["american", "poultry", "chicken", "cider vinegar", "egg", "five ingredient", "plan-ahead", "vegetable oil", "dinner", "bbq", "grilling", "summer"]', '[{"group_name": "Chicken", "items": [{"name": "whole chicken", "quantity": 1500, "unit": "g", "preparation": "cut into halves or quarters", "notes": "approx. 3.3 lbs", "substitutions": [], "ingredient_id": "cdb1c974-22da-499b-8647-8302625c52fb", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Cornell Sauce", "items": [{"name": "vegetable oil", "quantity": 240, "unit": "ml", "preparation": null, "notes": "can use canola or other neutral oil", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "cider vinegar", "quantity": 120, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "large egg", "quantity": 1, "unit": null, "preparation": null, "notes": "approx. 50g, acts as emulsifier", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 18, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "poultry seasoning", "quantity": 5, "unit": "g", "preparation": null, "notes": "or 2g dried sage and 2g dried thyme", "substitutions": [], "ingredient_id": "1c9631c8-360d-4344-87fa-e04dbe816e85", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a blender or large bowl, combine the vegetable oil, cider vinegar, egg, salt, poultry seasoning, and black pepper. Blend or whisk vigorously until the mixture emulsifies into a creamy, yellow sauce similar to a thin mayonnaise.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Place the chicken halves or quarters into a large resealable bag or bowl. Pour enough sauce over the chicken to coat completely, reserving about 100ml of fresh sauce in a separate container for later basting (do not cross-contaminate). Seal and refrigerate for 24 hours (minimum 4 hours).", "structured": {"action": "MARINATE", "temperature": null, "duration": "P1D", "doneness_cues": null}, "tips": ["Turn the bag occasionally to ensure even coverage.", "Marinating for 24 hours is crucial for the signature texture."]}, {"step_number": 3, "phase": "cook", "text": "Preheat your grill for medium-high indirect heat (aiming for ambient temp of 175\u00b0C-200\u00b0C / 350\u00b0F-400\u00b0F). If using charcoal, bank coals to one side. If using gas, turn off one burner.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Remove chicken from the marinade and shake off excess. Discard the used marinade. Place chicken on the cool side of the grill (indirect heat), bone-side down first. Cover and cook.", "structured": {"action": "GRILL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Turn the chicken and baste with the reserved sauce every 10-15 minutes. Cook for approximately 45-60 minutes total. Monitor closely to prevent flare-ups.", "structured": {"action": "BASTE", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": ["Lightly sear the skin over direct heat for the last 2-3 minutes if it needs more crisping, but watch carefully as the oil in the sauce burns effectively."]}, {"step_number": 6, "phase": "cook", "text": "The chicken is done when an instant-read thermometer inserted into the thickest part of the thigh registers 74\u00b0C (165\u00b0F) and the juices run clear.", "structured": {"action": "MEASURE", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": null, "doneness_cues": {"visual": "Juices run clear, skin is golden-brown and crispy", "tactile": "Meat is firm"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Transfer chicken to a platter and let it rest for 10 minutes before serving to allow juices to redistribute.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "P1D", "total_time": "P1D0H30M", "overnight_required": true, "yields": "1 whole chicken (4 servings)", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Dairy-Free", "Gluten-Free", "Nut-Free", "Low-Carb", "Keto"], "not_suitable_for": ["Vegetarian", "Vegan"]}', '{"per_serving": {"calories": 1470.92, "protein_g": 80.5, "carbohydrates_g": 1.51, "fat_g": 125.05, "saturated_fat_g": 27.46, "trans_fat_g": 0.01, "monounsaturated_fat_g": 0.48, "polyunsaturated_fat_g": 0.27, "fiber_g": 0.27, "sugar_g": 0.19, "sodium_mg": 2061.94, "cholesterol_mg": 46.5, "potassium_mg": 857.21, "calcium_mg": 70.44, "iron_mg": 4.61, "magnesium_mg": 6.7, "phosphorus_mg": 30.08, "zinc_mg": 0.23, "vitamin_a_mcg": 195.52, "vitamin_c_mg": 6.9, "vitamin_d_mcg": 0.25, "vitamin_e_mg": 0.16, "vitamin_k_mcg": 10.92, "vitamin_b6_mg": 0.04, "vitamin_b12_mcg": 0.11, "thiamin_mg": 0.01, "riboflavin_mg": 0.06, "niacin_mg": 0.05, "folate_mcg": 7.69, "water_g": 37.85, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container.", "duration": "P3D"}, "freezer": {"notes": "Meat freezes well; texture of skin may soften upon reheating.", "duration": "P3M"}, "reheating": "Reheat in a 175\u00b0C (350\u00b0F) oven until warmed through to re-crisp the skin.", "does_not_keep": false}', '[{"name": "Blender or whisk", "required": true, "alternative": null}, {"name": "Large bowl or resealable bag", "required": true, "alternative": null}, {"name": "Grill (Charcoal preferred)", "required": true, "alternative": "Gas grill"}, {"name": "Basting brush", "required": true, "alternative": null}, {"name": "Instant-read thermometer", "required": true, "alternative": null}]', '[{"symptom": "Skin is burning or blackening too quickly", "likely_cause": "Heat is too high or chicken is over direct flame; the oil in the sauce is flammable", "prevention": "Maintain indirect heat and keep lid closed; only move to direct heat at the very end", "fix": "Immediately move chicken to the coolest part of the grill and cover"}, {"symptom": "Sauce separates before basting", "likely_cause": "Emulsion has broken while sitting", "prevention": "Whisk reserved sauce immediately before applying", "fix": "Whisk vigorously to re-emulsify"}]', '["The egg is the secret ingredient; it acts as an emulsifier that allows the oil and vinegar to cling to the chicken throughout the cooking process.", "Do not skip the long marinade time. The acidity of the vinegar tenderizes the meat significantly, but it needs time to penetrate.", "For the most authentic experience, use bone-in, skin-on chicken. Boneless cuts will cook too fast and miss out on the basting benefits.", "Always reserve clean sauce for basting before the raw chicken touches the mixture to avoid cross-contamination.", "Leftover cooked chicken makes excellent cold sandwiches or salads due to the vinegar cure."]', '"Developed in the 1950s by Dr. Robert C. Baker, a professor of food science at Cornell University, this recipe was designed to increase poultry consumption in New York State. It became a regional icon, famously sold at the New York State Fair and local fire department fundraisers."', 1470.92);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('05850f79-1d03-41bb-b88b-0d736feaaf78', 'Fennel and Oil-Cured Olive Risotto', 'A luxuriously creamy risotto balancing the sweet, aromatic anise notes of braised fennel with the intense, savory punch of oil-cured black olives. Finished with a bright lift of lemon zest and reserved fennel fronds.', 'main course', 'Italian', 'Intermediate', '["italian", "arborio rice", "fennel", "dinner", "quick", "main course", "vegetarian", "gluten-free"]', '[{"group_name": "Base & Soffritto", "items": [{"name": "arborio rice", "quantity": 300, "unit": "g", "preparation": "dry", "notes": "do not rinse", "substitutions": [], "ingredient_id": "2e654ed5-87a8-42bc-8533-90972c8137e1", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable stock", "quantity": 1200, "unit": "ml", "preparation": "hot", "notes": null, "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "fennel bulb", "quantity": 1, "unit": null, "preparation": "small dice", "notes": "approx 300g; reserve fronds", "substitutions": [], "ingredient_id": "a42d03de-0a8a-4a75-8299-5cf01d43b425", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 2, "unit": null, "preparation": "finely minced", "notes": "approx 60g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "036c7254-3de5-4c6e-a2e7-366ad4d05077", "nutrition_source": "Aggregated Public Data"}, {"name": "dry white wine", "quantity": 120, "unit": "ml", "preparation": null, "notes": "Pinot Grigio or Sauvignon Blanc", "substitutions": [], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Flavor & Finish", "items": [{"name": "oil-cured black olives", "quantity": 80, "unit": "g", "preparation": "pitted and roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "64bba522-5f65-435c-bc93-47f1218380c1", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "parmigiano-reggiano", "quantity": 50, "unit": "g", "preparation": "finely grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": "zested", "notes": "approx 3g", "substitutions": [], "ingredient_id": "9e54e651-2396-4bef-9625-00ed1c90838f", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, be careful with salty olives", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pour the vegetable stock into a medium saucepan and bring to a simmer over medium heat. Reduce heat to low to keep it hot but not boiling vigorously.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a heavy-bottomed pan, heat the olive oil over medium heat. Add the diced fennel and minced shallot. Saut\u00e9 for 5-7 minutes until the vegetables are soft and translucent, but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Translucent and soft", "tactile": "Yielding to pressure"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the Arborio rice to the pan. Toast the rice, stirring constantly, for 2-3 minutes. The grains should become semi-translucent at the edges with an opaque white center (the pearl) and feel hot to the touch.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Edges translucent, pearl center visible", "tactile": "Hot to the touch"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour in the white wine. Stir vigorously until the wine has completely evaporated and the smell of raw alcohol has dissipated.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Begin adding the hot stock one ladle (approx 100-150ml) at a time. Stir frequently, allowing the rice to absorb almost all the liquid before adding the next ladle. Adjust heat to maintain a gentle simmer.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT18M", "doneness_cues": {"visual": null, "tactile": "Rice is tender with a slight bite (al dente)"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "When the rice is al dente (usually after 18-20 minutes) and the texture is creamy but fluid (all''onda), remove the pan from the heat. Stir in the chopped olives.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Perform the ''mantecatura'': Add the cold cubed butter and grated Parmesan. Whip the risotto vigorously with a wooden spoon to emulsify the fats with the starch, creating a glossy sauce. Stir in the lemon zest.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Glossy, flowing lava-like texture", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Taste and adjust salt if necessary (the olives and cheese add significant salt). Divide onto warmed plates and garnish with the reserved fennel fronds.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT40M", "passive_time": "PT0M", "total_time": "PT40M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Vegetarian", "Gluten-Free", "Egg-Free", "Soy-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 644.82, "protein_g": 12.62, "carbohydrates_g": 75.71, "fat_g": 27.29, "saturated_fat_g": 9.7, "trans_fat_g": null, "monounsaturated_fat_g": 3.79, "polyunsaturated_fat_g": 0.68, "fiber_g": 4.92, "sugar_g": 8.39, "sodium_mg": 1907.62, "cholesterol_mg": 32.69, "potassium_mg": 555.29, "calcium_mg": 231.43, "iron_mg": 4.47, "magnesium_mg": 45.29, "phosphorus_mg": 236.6, "zinc_mg": 1.38, "vitamin_a_mcg": 218.39, "vitamin_c_mg": 12.61, "vitamin_d_mcg": 0.06, "vitamin_e_mg": 0.81, "vitamin_k_mcg": 48.3, "vitamin_b6_mg": 0.22, "vitamin_b12_mcg": 0.17, "thiamin_mg": 0.46, "riboflavin_mg": 0.11, "niacin_mg": 3.69, "folate_mcg": 199.81, "water_g": 93.89, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Texture will degrade significantly; best eaten fresh.", "duration": "P3D"}, "freezer": {"notes": "Freezing not recommended; rice becomes grainy.", "duration": null}, "reheating": "Reheat gently on stove with a splash of water or stock to loosen the starch matrix.", "does_not_keep": false}', '[{"name": "Heavy-bottomed saucepan or Dutch oven", "required": true, "alternative": null}, {"name": "Medium saucepan", "required": true, "alternative": "Microwave-safe bowl (for stock)"}, {"name": "Wooden spoon or silicone spatula", "required": true, "alternative": null}, {"name": "Ladle", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Microplane or zester", "required": true, "alternative": null}]', '[{"symptom": "Rice is crunchy in the middle", "likely_cause": "Undercooked or stock added too quickly", "prevention": "Keep stock hot and add gradually; taste frequently after 16 minutes", "fix": "Add a splash more hot water or stock and cook for 2-3 more minutes, stirring constantly"}, {"symptom": "Risotto is gummy or gluey", "likely_cause": "Rice was stirred too aggressively or overcooked", "prevention": "Stir frequently but not constantly; stop cooking when al dente", "fix": "Stir in a little extra hot stock to loosen texture immediately before serving"}, {"symptom": "Dish is too salty", "likely_cause": "Salty stock combined with salty olives and parmesan", "prevention": "Use low-sodium stock and taste before adding final salt", "fix": "Stir in a small splash of heavy cream or unsalted butter to mask the salinity, or add a squeeze of lemon juice"}]', '["The ''mantecatura'' step is non-negotiable. Using cold butter (not room temp) when the pot is off the heat helps create a tighter, glossier emulsion.", "Do not rinse the Arborio rice before cooking. The surface starch is essential for creating the creamy texture characteristic of risotto.", "If you cannot find oil-cured black olives, Kalamata olives are an acceptable substitute, though they lack the dense, meaty texture of the oil-cured variety.", "The consistency should be ''all''onda'' (like a wave)\u2014if you tilt the plate, the risotto should slowly flow, not stand stiffly in a pile.", "Lemon zest is critical here to bridge the gap between the sweet earthy fennel and the heavy, salty olives."]', '"Risotto is a staple of Northern Italian cuisine, particularly in Lombardy and Piedmont where rice paddies are abundant. This specific variation highlights the Italian love for contrasting flavors\u2014combining the ''dolce'' (sweet) of cooked fennel with the ''sapido'' (savory/salty) of cured olives."', 644.82);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('060f9e88-bdf4-4e41-b203-7282a760614c', 'Pan-Seared Sole with Mango Yogurt Sauce', 'Delicate, golden-crusted sole fillets resting on a bed of crisp greens, finished with a vibrant, sweet-tart creamy mango sauce that brightens the palate.', 'dinner', 'Fusion', 'Easy', '["lettuce", "mango", "sole", "dinner", "main course", "fusion", "light meal", "seafood"]', '[{"group_name": "Mango Yogurt Sauce", "items": [{"name": "ripe mango", "quantity": 1, "unit": null, "preparation": "peeled and pitted", "notes": "approx 200g flesh", "substitutions": [], "ingredient_id": "6ab51d7d-dea3-4f14-8253-76acb67bd2c8", "nutrition_source": "USDA FoodData Central"}, {"name": "greek yogurt", "quantity": 120, "unit": "g", "preparation": "plain, full-fat", "notes": null, "substitutions": [], "ingredient_id": "82632959-c937-4e83-9925-6511fb6eb9ae", "nutrition_source": "USDA FoodData Central"}, {"name": "lime juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "pinch to enhance flavor", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Salad Base", "items": [{"name": "butter lettuce", "quantity": 200, "unit": "g", "preparation": "washed and torn", "notes": null, "substitutions": [], "ingredient_id": "225f61d9-d916-4504-80f2-4fe2baf6c9b2", "nutrition_source": "Aggregated Public Data"}, {"name": "cucumber", "quantity": 100, "unit": "g", "preparation": "sliced", "notes": null, "substitutions": [], "ingredient_id": "457adec2-3e06-4efe-a26e-9e6ea9f84924", "nutrition_source": "USDA FoodData Central"}, {"name": "red onion", "quantity": 30, "unit": "g", "preparation": "thinly sliced", "notes": null, "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "lime juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sole", "items": [{"name": "sole fillets", "quantity": 4, "unit": null, "preparation": null, "notes": "approx 150g each, Dover or Lemon sole preferred", "substitutions": [], "ingredient_id": "3ae8ef3b-72ed-4956-8848-4b04a82dfe96", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 30, "unit": "g", "preparation": null, "notes": "for dredging", "substitutions": ["rice flour", "cornstarch"], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine mango flesh, Greek yogurt, 15ml lime juice, honey, and a pinch of salt in a blender. Puree until smooth and creamy.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": ["If the sauce is too thick, thin with a teaspoon of water or milk."]}, {"step_number": 2, "phase": "prep", "text": "In a large bowl, prepare the salad by tossing the lettuce, cucumber, and red onion with the olive oil and remaining 5ml lime juice just to coat. Set aside.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Pat the sole fillets dry with paper towels. Season both sides with salt and pepper, then lightly dredge in flour, shaking off any excess.", "structured": {"action": "DREDGE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Heat the vegetable oil and butter in a large non-stick skillet over medium-high heat until the butter foams but does not brown.", "structured": {"action": "HEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the fillets to the pan (work in batches if necessary). Sear for 2-3 minutes per side until golden brown and the flesh is opaque and flakes easily. Target internal temperature is 63\u00b0C/145\u00b0F.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Golden crust, opaque flesh", "tactile": "Flakes easily with fork"}}, "tips": ["Sole is very delicate; use a wide fish spatula to flip gently."]}, {"step_number": 6, "phase": "assemble", "text": "Divide the salad among plates. Place a warm sole fillet on top of the greens and drizzle generously with the mango yogurt sauce.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT0M", "total_time": "PT25M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 320}', '{"flags": ["Pescatarian", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Vegans", "Dairy allergies"]}', '{"per_serving": {"calories": 316, "protein_g": 23.54, "carbohydrates_g": 18.33, "fat_g": 16.94, "saturated_fat_g": 5.62, "trans_fat_g": 0.02, "monounsaturated_fat_g": 5.4, "polyunsaturated_fat_g": 1.25, "fiber_g": 1.85, "sugar_g": 9.1, "sodium_mg": 750.6, "cholesterol_mg": 85.43, "potassium_mg": 483.45, "calcium_mg": 94.89, "iron_mg": 1.07, "magnesium_mg": 38.66, "phosphorus_mg": 404.22, "zinc_mg": 0.66, "vitamin_a_mcg": 181.72, "vitamin_c_mg": 24.3, "vitamin_d_mcg": 4.2, "vitamin_e_mg": 2.14, "vitamin_k_mcg": 9.63, "vitamin_b6_mg": 0.24, "vitamin_b12_mcg": 1.71, "thiamin_mg": 0.07, "riboflavin_mg": 0.07, "niacin_mg": 2.04, "folate_mcg": 34.92, "water_g": 231.86, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Fish is best eaten immediately. Sauce keeps for 2 days. Salad must be stored undressed.", "duration": "P1D"}, "freezer": {"notes": "Texture of delicate fish and dairy sauce suffers significantly upon freezing.", "duration": null}, "reheating": "Gently reheat fish in a low oven; sauce should be served cold.", "does_not_keep": true}', '[{"name": "Large non-stick skillet", "required": true, "alternative": null}, {"name": "Blender or food processor", "required": true, "alternative": "Immersion blender"}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Fish spatula", "required": true, "alternative": "Wide flat turner"}]', '[{"symptom": "Fish falls apart when flipping", "likely_cause": "Fish stuck to pan or was flipped too early/roughly", "prevention": "Ensure pan is hot and non-stick; wait until crust forms before flipping", "fix": "Piece it together on the plate and cover the break with sauce"}]', '["Choose a firm, sweet mango (like Honey or Alphonso) for the best sauce flavor without needing extra sugar.", "Dredging the fish in flour is optional but recommended; it creates a protective barrier that keeps the delicate meat moist and adds a pleasant texture.", "If you cannot find sole, flounder or thin tilapia fillets are acceptable substitutes.", "Serve immediately; the warmth of the fish against the cool, crisp salad is key to the dish''s appeal."]', '"While sole meuni\u00e8re is a classic French preparation, this dish introduces a tropical twist with a mango-yogurt base, reflecting modern fusion cuisine''s focus on lighter, fruit-forward sauces that complement delicate seafood."', 316);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('061242b8-7a0f-47d7-886d-f4581b86a37f', 'Classic Pavlova with Lemon-Lime Curd and Passion Fruit', 'A showstopping dessert featuring a marshmallow-soft meringue center encased in a crisp, delicate shell. The sweetness is perfectly balanced by a sharp, buttery lemon-lime curd, unsweetened whipped cream, and the tropical crunch of fresh passion fruit.', 'dessert', 'Australian', 'Intermediate', '["pavlova", "lemon", "lime", "dessert", "meringue", "citrus", "gluten-free", "summer"]', '[{"group_name": "Meringue Base", "items": [{"name": "egg whites", "quantity": 4, "unit": null, "preparation": "room temperature", "notes": "approx. 140g total; reserve yolks for curd", "substitutions": [], "ingredient_id": "17645f6b-c1ea-4e82-a4b4-5ae8cb6a5a53", "nutrition_source": "Aggregated Public Data"}, {"name": "caster sugar", "quantity": 220, "unit": "g", "preparation": null, "notes": "superfine sugar", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 10, "unit": "g", "preparation": null, "notes": "cornflour", "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "white vinegar", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8d5bf07e-89a1-47ee-a6b7-d9cb03e96d64", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Lemon-Lime Curd", "items": [{"name": "egg yolks", "quantity": 4, "unit": null, "preparation": null, "notes": "approx. 70-80g", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 50, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "lime juice", "quantity": 30, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": "g", "preparation": null, "notes": "approx. 1 tsp", "substitutions": [], "ingredient_id": "03fb65be-9b62-44e7-a121-694de64cdec0", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 80, "unit": "g", "preparation": "cubed, cold", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "small pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Topping", "items": [{"name": "heavy whipping cream", "quantity": 300, "unit": "ml", "preparation": "cold", "notes": "min 35% fat", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla bean paste", "quantity": 5, "unit": "ml", "preparation": null, "notes": "or extract", "substitutions": [], "ingredient_id": "fa27169b-bdb5-4f0c-abab-0b67a3e924e6", "nutrition_source": "Aggregated Public Data"}, {"name": "passion fruit", "quantity": 4, "unit": null, "preparation": "halved", "notes": "pulp scooped out", "substitutions": [], "ingredient_id": "724121fd-5e4c-4afc-93ff-0fd9ec7d4ea0", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 150\u00b0C (300\u00b0F). Line a baking sheet with parchment paper and draw a 20cm circle on the underside as a guide.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a spotlessly clean, grease-free mixer bowl, whisk the egg whites on medium-high speed until soft peaks form.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": {"visual": "Soft peaks that droop slightly when whisk is lifted", "tactile": "Foamy structure"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "With the mixer running, add the caster sugar one tablespoon at a time, beating well after each addition. Continue whisking on high until the meringue is thick, glossy, and the sugar has completely dissolved (rub a bit between fingers to check for grit).", "structured": {"action": "WHISK", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Stiff glossy peaks", "tactile": "Smooth texture with no sugar grains"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Stop the mixer. Sift the cornstarch over the meringue and add the vinegar and vanilla. Gently fold using a rubber spatula just until combined.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Mound the meringue onto the parchment circle. Shape it into a disc, creating a slight depression in the center (like a nest) to hold the filling later.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Place in the oven and immediately reduce the temperature to 120\u00b0C (250\u00b0F). Bake for 75 to 90 minutes until the exterior is dry and crisp but not browned.", "structured": {"action": "BAKE", "temperature": {"celsius": 120, "fahrenheit": 248}, "duration": "PT1H15M", "doneness_cues": {"visual": "Pale and dry exterior", "tactile": "Hollow sound when tapped"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Turn the oven off and leave the pavlova inside to cool completely with the door slightly ajar. This prevents cracking.", "structured": {"action": "COOL", "temperature": null, "duration": "PT2H", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "While the meringue cools, make the curd. In a saucepan, whisk together egg yolks, granulated sugar, lemon juice, lime juice, lemon zest, and salt. Cook over low heat, stirring constantly, until the mixture thickens enough to coat the back of a spoon (approx 77\u00b0C/170\u00b0F).", "structured": {"action": "SIMMER", "temperature": {"celsius": 77, "fahrenheit": 171}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Remove from heat and whisk in the cold cubed butter one piece at a time until fully emulsified and glossy. Strain through a fine mesh sieve if desired, then cover with plastic wrap touching the surface and chill.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "assemble", "text": "Just before serving, whip the heavy cream and vanilla paste to soft, billowy peaks. Do not over-whip.", "structured": {"action": "WHIP", "temperature": null, "duration": null, "doneness_cues": {"visual": "Soft peaks", "tactile": null}}, "tips": []}, {"step_number": 11, "phase": "assemble", "text": "To assemble, carefully transfer the pavlova to a serving plate. Fill the center with the lemon-lime curd, top generously with whipped cream, and spoon fresh passion fruit pulp over the top.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT4H", "total_time": "PT4H45M", "overnight_required": false, "yields": "1 large pavlova (8 servings)", "yield_count": 8, "serving_size_g": 125}', '{"flags": ["Vegetarian", "Gluten-Free"], "not_suitable_for": ["Vegans", "Egg-Free diets"]}', '{"per_serving": {"calories": 409.3, "protein_g": 4.63, "carbohydrates_g": 44.96, "fat_g": 24.19, "saturated_fat_g": 14.57, "trans_fat_g": 0.47, "monounsaturated_fat_g": 6.85, "polyunsaturated_fat_g": 1.29, "fiber_g": 0.08, "sugar_g": 42.84, "sodium_mg": 94.66, "cholesterol_mg": 165.13, "potassium_mg": 117.38, "calcium_mg": 42.33, "iron_mg": 0.37, "magnesium_mg": 7.73, "phosphorus_mg": 65.89, "zinc_mg": 0.34, "vitamin_a_mcg": 261.92, "vitamin_c_mg": 6.75, "vitamin_d_mcg": 1.11, "vitamin_e_mg": 0.84, "vitamin_k_mcg": 2.03, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": 0.28, "thiamin_mg": 0.03, "riboflavin_mg": 0.22, "niacin_mg": 0.21, "folate_mcg": 18.51, "water_g": 61.66, "alcohol_g": 0.22, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store unassembled components separately. Curd keeps 1 week; meringue keeps 2 days in airtight container.", "duration": "P1D"}, "freezer": {"notes": "Meringue does not freeze well.", "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Stand mixer or electric hand whisk", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Rubber spatula", "required": true, "alternative": null}, {"name": "Fine mesh sieve", "required": false, "alternative": "Cheesecloth"}]', '[{"symptom": "Meringue is weeping (liquid oozing from bottom)", "likely_cause": "Sugar was not fully dissolved or the meringue was undercooked", "prevention": "Rub meringue between fingers during mixing to ensure zero grit remains; ensure vinegar/cornstarch are added", "fix": "Cannot be fixed once baked; serve immediately so the shell doesn''t soften"}, {"symptom": "Curd is runny", "likely_cause": "Undercooked egg yolks", "prevention": "Ensure mixture reaches 77\u00b0C (170\u00b0F) or coats the back of a spoon distinctly", "fix": "Return to low heat and cook longer while whisking constantly"}]', '["Humidity is the enemy of meringue. Avoid making this dessert on a rainy day, or the shell will absorb moisture and become chewy rather than crisp.", "Ensure your mixing bowl and whisk are wiped with vinegar or lemon juice before starting; even a trace of fat will prevent egg whites from whipping properly.", "For the cleanest slices, use a serrated knife dipped in hot water and wiped dry between cuts.", "The contrast between the sweet meringue and the tart curd is essential; do not add sugar to the whipped cream topping."]', '"Named after the Russian ballerina Anna Pavlova, this dessert is a subject of friendly rivalry between Australia and New Zealand, both claiming its invention in the 1920s. It represents the quintessential summer dessert in the Antipodes, celebrating the region''s abundance of fresh fruit and dairy."', 409.3);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('06a5c073-59cd-4e8d-964a-0a95b532205a', 'Fire & Snap Gingerbread Cookies', 'Intensely aromatic gingerbread with a serious spicy kick from fresh ginger and white pepper. These cookies bake flat with a structural snap, making them the ideal canvas for royal icing.', 'baked good', 'European', 'Intermediate', '["cardamom", "cinnamon", "clove", "cookie", "flour", "ginger", "nutmeg", "dessert", "christmas", "spicy", "baking"]', '[{"group_name": "Dry Mix", "items": [{"name": "all-purpose flour", "quantity": 420, "unit": "g", "preparation": null, "notes": "Plus extra for rolling", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 5g (1 tsp)", "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "ground ginger", "quantity": 10, "unit": "g", "preparation": null, "notes": "approx 1 tbsp + 1 tsp", "substitutions": [], "ingredient_id": "401ddd0b-3597-4b46-bb54-f3bc755048bb", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 6, "unit": "g", "preparation": null, "notes": "approx 2 tsp", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cloves", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 0.5 tsp", "substitutions": [], "ingredient_id": "7b3bf68a-3ae9-4dad-91f4-6c7a14ec5e0e", "nutrition_source": "USDA FoodData Central"}, {"name": "ground nutmeg", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 0.5 tsp", "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cardamom", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 0.5 tsp", "substitutions": [], "ingredient_id": "c56f6cd8-882c-487c-956f-3a91ee1fec07", "nutrition_source": "USDA FoodData Central"}, {"name": "white pepper", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 0.5 tsp; essential for the heat", "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wet Mix", "items": [{"name": "unsalted butter", "quantity": 145, "unit": "g", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "dark brown sugar", "quantity": 150, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "molasses", "quantity": 170, "unit": "g", "preparation": null, "notes": "unsulphured (not blackstrap)", "substitutions": [], "ingredient_id": "c76e81ce-ce17-4595-b9ff-30c87fb7c285", "nutrition_source": "USDA FoodData Central"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": "large, room temperature", "notes": "approx 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh ginger root", "quantity": 10, "unit": "g", "preparation": "finely grated/zested", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a medium bowl, sift together the flour, baking soda, salt, ground ginger, cinnamon, cloves, nutmeg, cardamom, and white pepper. Whisk thoroughly to distribute the spices evenly.", "structured": {"action": "SIFT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In the bowl of a stand mixer fitted with the paddle attachment, beat the softened butter and dark brown sugar on medium-high speed until light and fluffy, about 3 minutes.", "structured": {"action": "CREAM", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Reduce mixer speed to medium-low. Add the molasses, egg, and fresh grated ginger. Beat until combined, scraping down the sides of the bowl as necessary.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "With the mixer on low, gradually add the flour mixture in three batches. Mix only until no dry flour remains. Do not overmix, or the cookies will be tough.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Divide the dough in half. Shape each half into a flat disc, wrap tightly in plastic wrap, and refrigerate for at least 3 hours or overnight. This hydrates the flour and prevents spreading.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT3H", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Preheat your oven to 175\u00b0C (350\u00b0F). Line two baking sheets with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Remove one disc of dough from the fridge. On a lightly floured surface, roll the dough out to exactly 4mm (1/6 inch) thickness. Cut shapes with cookie cutters and place 2cm apart on prepared baking sheets. Place the baking sheet in the freezer for 5 minutes before baking to lock the shape.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Bake for 9-11 minutes. For maximum crispness, bake until the edges are slightly darkened and the centers feel firm to the touch. Rotate the pan halfway through.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT10M", "doneness_cues": {"visual": "Edges slightly darkened", "tactile": "Center is firm, not soft"}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Let the cookies cool on the baking sheet for 5 minutes to set, then transfer to a wire rack to cool completely. They will crisp up significantly as they cool.", "structured": {"action": "COOL", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT3H", "total_time": "PT3H45M", "overnight_required": false, "yields": "30 cookies", "yield_count": 30, "serving_size_g": 28}', '{"flags": ["Vegetarian", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 126.25, "protein_g": 1.77, "carbohydrates_g": 20.46, "fat_g": 4.28, "saturated_fat_g": 2.55, "trans_fat_g": null, "monounsaturated_fat_g": 1.21, "polyunsaturated_fat_g": 0.24, "fiber_g": 0.61, "sugar_g": 9.15, "sodium_mg": 91.51, "cholesterol_mg": 16.59, "potassium_mg": 116.19, "calcium_mg": 23.39, "iron_mg": 0.61, "magnesium_mg": 19.02, "phosphorus_mg": 22.79, "zinc_mg": 0.17, "vitamin_a_mcg": 35.77, "vitamin_c_mg": 0.06, "vitamin_d_mcg": 0.03, "vitamin_e_mg": 0.15, "vitamin_k_mcg": 0.55, "vitamin_b6_mg": 0.05, "vitamin_b12_mcg": 0.02, "thiamin_mg": 0.02, "riboflavin_mg": 0.02, "niacin_mg": 0.28, "folate_mcg": 4.78, "water_g": 5.37, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Dough can be stored in the fridge for up to 1 week before baking.", "duration": "P1W"}, "freezer": {"notes": "Baked cookies or raw dough disks freeze excellently.", "duration": "P3M"}, "reheating": "Not applicable", "does_not_keep": false}', '[{"name": "Stand mixer with paddle attachment", "required": true, "alternative": "Hand mixer and large bowl"}, {"name": "Rolling pin", "required": true, "alternative": null}, {"name": "Cookie cutters", "required": true, "alternative": null}, {"name": "Baking sheets", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}, {"name": "Microplane or zester", "required": true, "alternative": null}]', '[{"symptom": "Cookies are soft or chewy instead of crisp", "likely_cause": "Dough was rolled too thick or underbaked", "prevention": "Roll to exactly 4mm and bake until edges are visibly darker", "fix": "Return cooled cookies to a 150\u00b0C (300\u00b0F) oven for 5-8 minutes to dry out"}, {"symptom": "Cookies spread and lost their shape", "likely_cause": "Dough became too warm before baking", "prevention": "Chill cut shapes in the freezer for 5-10 minutes immediately before putting them in the oven", "fix": "Trim edges with a knife immediately upon removing from oven while still soft"}]', '["The addition of white pepper provides a lingering heat at the back of the throat that balances the sweetness of the molasses.", "For the cleanest edges when using intricate cutters, dip the cutter in flour before each press.", "Do not skip the chilling steps. Warm gingerbread dough is sticky and impossible to work with; keep the second disc in the fridge while working on the first.", "If you plan to decorate with royal icing, ensure the cookies are completely cool (room temperature) to prevent the icing from melting or running."]', '"Gingerbread has roots in medieval Europe, where ginger was used to preserve bread and mask strong flavors. This version leans into the ''Pepparkakor'' tradition of Scandinavia, emphasizing a thin, brittle snap and high spice profile rather than the soft, cake-like texture often found in American gingerbread men."', 126.25);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('06dd831b-801d-4ea3-bd40-74df0c8d9a24', 'Strawberry Mascarpone Swiss Roll', 'A feather-light genoise sponge tightly spiraled around a luxuriously smooth mascarpone Chantilly cream and fresh strawberry jewels. This dessert balances the airy texture of the cake with the richness of the filling and the tart brightness of seasonal berries.', 'dessert', 'French', 'Intermediate', '["swiss roll", "strawberry", "dessert", "cake", "cream", "tea time", "summer", "baking"]', '[{"group_name": "Sponge Cake", "items": [{"name": "large eggs", "quantity": 4, "unit": null, "preparation": "room temperature", "notes": "approx 220g total weight", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "granulated sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "cake flour", "quantity": 100, "unit": "g", "preparation": null, "notes": "low protein flour ensures tenderness", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "warm water", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "small pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Mascarpone Filling", "items": [{"name": "mascarpone cheese", "quantity": 250, "unit": "g", "preparation": "chilled", "notes": null, "substitutions": [], "ingredient_id": "fc428935-3bcd-4cef-8495-7ed35e7dae22", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 150, "unit": "ml", "preparation": "chilled", "notes": "min 35% fat", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "powdered sugar", "quantity": 60, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla bean paste", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fa27169b-bdb5-4f0c-abab-0b67a3e924e6", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Assembly", "items": [{"name": "fresh strawberries", "quantity": 200, "unit": "g", "preparation": "diced small", "notes": "dry thoroughly after washing", "substitutions": [], "ingredient_id": "b2199214-7c2d-4083-92ae-b0a8a044e25b", "nutrition_source": "USDA FoodData Central"}, {"name": "powdered sugar", "quantity": 10, "unit": "g", "preparation": null, "notes": "for dusting", "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 190\u00b0C/375\u00b0F. Grease the Swiss roll tin and line it with parchment paper, ensuring the paper extends slightly over the edges.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Sift the cake flour and salt together three times to aerate it. This is crucial for a light sponge.", "structured": {"action": "SIFT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a stand mixer, whisk eggs and granulated sugar on high speed for 5-7 minutes until the mixture triples in volume and reaches the ''ribbon stage'' (pale and thick enough to hold a trail).", "structured": {"action": "WHISK", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Pale, tripled in volume, holds a ribbon trail", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Gently fold in the vanilla and warm water. Then, sift the flour mixture over the egg foam in three batches, folding very gently with a spatula to retain air.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour the batter into the prepared tin. Gently tilt to spread evenly into corners. Bake for 10-12 minutes until the top is springy to the touch and pale golden.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT12M", "doneness_cues": {"visual": "Pale golden brown", "tactile": "Springs back when touched"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "While the cake bakes, lay a clean kitchen towel on the counter and dust it liberally with powdered sugar. Immediately upon removing the cake from the oven, invert it onto the towel. Peel off the parchment paper carefully.", "structured": {"action": "PREPARE_VEG", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "prep", "text": "Starting from a short end, roll the warm cake up tightly with the towel inside the spiral. Let it cool completely in this rolled shape on a wire rack.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Cool to the touch"}}, "tips": ["Rolling while hot trains the sponge''s memory, preventing cracks later."]}, {"step_number": 8, "phase": "prep", "text": "To make the filling, whisk the mascarpone, heavy cream, powdered sugar, and vanilla bean paste until stiff peaks form. Do not overbeat or the mascarpone may curdle.", "structured": {"action": "WHIP", "temperature": null, "duration": null, "doneness_cues": {"visual": "Stiff peaks", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "assemble", "text": "Once the cake is cool, gently unroll it. Spread the mascarpone cream evenly over the surface, leaving a 2cm border at the far end. Scatter the diced strawberries over the cream.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "assemble", "text": "Roll the cake back up (without the towel this time), using the towel to help lift and guide the sponge. Place seam-side down on a serving platter.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 11, "phase": "finish", "text": "Refrigerate for at least 2 hours to set the filling. Dust with powdered sugar and slice with a warm knife before serving.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT2H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT2H30M", "total_time": "PT3H15M", "overnight_required": false, "yields": "10 slices", "yield_count": 10, "serving_size_g": 95}', '{"flags": ["Vegetarian", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Vegans", "Lactose intolerance"]}', '{"per_serving": {"calories": 296.07, "protein_g": 5.61, "carbohydrates_g": 34.19, "fat_g": 18.17, "saturated_fat_g": 10.41, "trans_fat_g": 0.2, "monounsaturated_fat_g": 2.19, "polyunsaturated_fat_g": 0.73, "fiber_g": 0.87, "sugar_g": 20.69, "sodium_mg": 84.86, "cholesterol_mg": 98.79, "potassium_mg": 87.01, "calcium_mg": 80.7, "iron_mg": 0.61, "magnesium_mg": 8.57, "phosphorus_mg": 67.89, "zinc_mg": 0.42, "vitamin_a_mcg": 231.05, "vitamin_c_mg": 11.85, "vitamin_d_mcg": 0.68, "vitamin_e_mg": 0.43, "vitamin_k_mcg": 1.02, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": 0.22, "thiamin_mg": 0.03, "riboflavin_mg": 0.14, "niacin_mg": 0.23, "folate_mcg": 18.34, "water_g": 46.59, "alcohol_g": 0.17, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Keep covered to prevent the sponge from drying out. Best consumed within 24 hours.", "duration": "P3D"}, "freezer": {"notes": "Freeze without fresh strawberry garnish. Wrap tightly in plastic wrap then foil.", "duration": "P1M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Stand mixer or electric hand mixer", "required": true, "alternative": null}, {"name": "Swiss roll tin (approx 23x33cm / 9x13 inch)", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Clean kitchen towel", "required": true, "alternative": "Additional sheet of parchment paper dusted with sugar"}, {"name": "Fine mesh sieve", "required": true, "alternative": null}, {"name": "Offset spatula", "required": true, "alternative": null}, {"name": "Rubber spatula", "required": true, "alternative": null}]', '[{"symptom": "Sponge cracked when rolling", "likely_cause": "The cake was overbaked (too dry) or cooled down too much before the initial roll", "prevention": "Bake only until just set; roll immediately while piping hot", "fix": "Cover the cracks with extra whipped cream or a ganache coating to hide them"}, {"symptom": "Filling squirts out when slicing", "likely_cause": "Cake was not chilled long enough or filling was too soft", "prevention": "Chill for full 2 hours; ensure cream is whipped to stiff peaks", "fix": "Chill for an additional hour before attempting to slice again"}]', '["Room temperature eggs are non-negotiable for this recipe; they whip to a much greater volume than cold eggs, providing the sponge''s structure without baking powder.", "When folding flour, use a ''cut and fold'' motion. Cut down the center, scrape along the bottom, and fold over. Stop exactly when the flour streaks disappear to avoid deflating the batter.", "To get clean slices, dip your knife in hot water and wipe it dry between every single cut.", "The warm water added to the eggs helps emulsify the mixture and keeps the sponge pliable for rolling."]', '"Despite the name, the Swiss Roll likely originated in Central Europe or the UK in the 19th century, not Switzerland. It evolved from ''jelly cakes'' and became a staple of British tea time. This variation elevates the humble jam roll with Italian mascarpone for a richer, creamier finish."', 296.07);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('06ff1c50-c861-4585-a575-4ad9b9dd9707', 'Tamarind & Soy Marinated Bavette Steak', 'A robust, flavor-forward steak dish where the tart complexity of tamarind concentrate meets the deep umami of soy sauce. The bavette''s loose, coarse grain absorbs the marinade exceptionally well, resulting in a caramelized crust and tender interior.', 'dinner', 'Southeast Asian', 'Intermediate', '["steak", "tamarind", "soy sauce", "grill", "marinate", "beef", "dinner", "summer"]', '[{"group_name": "Marinade", "items": [{"name": "tamarind concentrate", "quantity": 40, "unit": "g", "preparation": "paste", "notes": "ensure it is the smooth concentrate, not the block with seeds", "substitutions": [], "ingredient_id": "c9dd70fa-d98b-459d-bd61-21b5778f1d4a", "nutrition_source": "USDA FoodData Central"}, {"name": "soy sauce", "quantity": 60, "unit": "ml", "preparation": null, "notes": "use light or all-purpose soy sauce", "substitutions": [], "ingredient_id": "1a157828-0624-4e67-815d-8e6bdf8b23c2", "nutrition_source": "USDA FoodData Central"}, {"name": "brown sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": "or palm sugar for authenticity", "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx. 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 10, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "vegetable or canola oil", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Steak", "items": [{"name": "bavette steak", "quantity": 800, "unit": "g", "preparation": "whole", "notes": "also known as flap steak; skirt steak is a viable alternative", "substitutions": [], "ingredient_id": "9eefd433-4f88-4921-a43c-fd1a1181ef62", "nutrition_source": "USDA FoodData Central"}, {"name": "flaky sea salt", "quantity": null, "unit": null, "preparation": "to taste", "notes": "for finishing", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a mixing bowl, combine the tamarind concentrate, soy sauce, brown sugar, minced garlic, grated ginger, neutral oil, and black pepper. Whisk vigorously until the sugar has completely dissolved.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Place the bavette steak in a shallow dish or resealable bag. Pour the marinade over the meat, ensuring it is thoroughly coated. Refrigerate for at least 2 hours, up to 8 hours. Flip halfway through if using a dish.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT2H", "doneness_cues": null}, "tips": ["Do not marinate longer than 12 hours, or the acid in the tamarind will make the meat texture mushy."]}, {"step_number": 3, "phase": "cook", "text": "Remove the steak from the refrigerator 30 minutes before cooking to take the chill off. Preheat your grill or grill pan to high heat (approx. 230\u00b0C/450\u00b0F).", "structured": {"action": "PREHEAT", "temperature": {"celsius": 230, "fahrenheit": 446}, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Remove the steak from the marinade and shake off excess liquid to prevent steaming. Grill the steak for 4-5 minutes per side, or until a deep char develops and the internal temperature reaches 52\u00b0C/125\u00b0F for medium-rare.", "structured": {"action": "GRILL", "temperature": {"celsius": 52, "fahrenheit": 126}, "duration": "PT10M", "doneness_cues": {"visual": "Deep brown char marks, no grey spots", "tactile": "Meat should feel soft with slight resistance (like the heel of your hand)"}}, "tips": ["The sugar in the marinade can burn quickly. If it flares up, move the steak to a cooler part of the grill."]}, {"step_number": 5, "phase": "finish", "text": "Transfer the steak to a cutting board and let it rest for 10 minutes. This allows the juices to redistribute throughout the muscle fibers.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Slice the steak thinly against the grain (perpendicular to the muscle fibers). This is critical for bavette to ensure tenderness. Finish with a sprinkle of flaky sea salt.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT2H10M", "total_time": "PT2H35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 220}', '{"flags": ["Dairy-Free", "Nut-Free", "Egg-Free"], "not_suitable_for": ["Gluten-Free (unless Tamari is substituted for Soy Sauce)"]}', '{"per_serving": {"calories": 418.54, "protein_g": 44.88, "carbohydrates_g": 16.79, "fat_g": 18.64, "saturated_fat_g": 5.25, "trans_fat_g": null, "monounsaturated_fat_g": 3.94, "polyunsaturated_fat_g": 0.43, "fiber_g": 0.84, "sugar_g": 11.43, "sodium_mg": 1332.96, "cholesterol_mg": 124, "potassium_mg": 851.93, "calcium_mg": 73.77, "iron_mg": 3.66, "magnesium_mg": 63.1, "phosphorus_mg": 437.08, "zinc_mg": 7.98, "vitamin_a_mcg": 0.34, "vitamin_c_mg": 1.65, "vitamin_d_mcg": null, "vitamin_e_mg": 0.63, "vitamin_k_mcg": 3.57, "vitamin_b6_mg": 1.29, "vitamin_b12_mcg": 2.12, "thiamin_mg": 0.2, "riboflavin_mg": 0.26, "niacin_mg": 14.04, "folate_mcg": 29.9, "water_g": 161.87, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store cooked steak in an airtight container.", "duration": "P3D"}, "freezer": {"notes": "Best frozen in marinade before cooking, rather than after cooking.", "duration": "P2M"}, "reheating": "Reheat gently in a skillet over low heat just until warm to prevent overcooking.", "does_not_keep": false}', '[{"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Outdoor grill or cast-iron grill pan", "required": true, "alternative": "Heavy skillet"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Instant-read thermometer", "required": true, "alternative": null}, {"name": "Sharp carving knife", "required": true, "alternative": null}]', '[{"symptom": "Steak is chewy or tough", "likely_cause": "The meat was sliced with the grain rather than against it", "prevention": "Identify the direction of the muscle fibers before cutting and position your knife at a 90-degree angle to them.", "fix": "Cut the existing slices into very small bite-sized pieces to minimize chewing effort."}]', '["Bavette has a very coarse, loose grain structure which makes it excellent for holding marinades but unforgiving if overcooked past medium.", "If you cannot find tamarind concentrate, you can substitute with a mix of lime juice and a dash of molasses, though the flavor profile will lack the specific earthy sourness of tamarind.", "Always pat the steak slightly dry before grilling; wet steak steams instead of searing, and you want that Maillard reaction for flavor.", "The marinade can be boiled down in a small saucepan for 5 minutes to create a safe, sticky glaze to brush on the sliced meat."]', '"This dish draws inspiration from the Thai dish ''Crying Tiger'' (Suea Rong Hai), which typically pairs grilled brisket or flank steak with a spicy, tart tamarind dipping sauce (Nam Jim Jaew). Here, the flavor profile is integrated directly into the marinade for a fusion approach that suits the grill."', 418.54);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('0784a634-3ab1-4686-804d-f4fd47eaf639', 'Classic Beef Burgers with Vibrant Beetroot & Carrot Slaw', 'Juicy, sear-crusted beef patties served on toasted brioche, balanced by a crunchy, acidic slaw of raw beetroot, carrot, and fresh herbs that cuts through the richness of the meat.', 'dinner', 'Modern American', 'Intermediate', '["burger", "beef", "slaw", "main course", "summer", "barbecue"]', '[{"group_name": "Burger Patties", "items": [{"name": "ground beef chuck (20% fat)", "quantity": 600, "unit": "g", "preparation": "cold", "notes": "Freshly ground is best", "substitutions": [], "ingredient_id": "6c7cf0a4-a53c-415a-8d1c-7c1fc55d1d95", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 6, "unit": "g", "preparation": null, "notes": "Approx 1 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "For searing (canola or grapeseed)", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}]}, {"group_name": "Beetroot & Carrot Slaw", "items": [{"name": "raw beetroot", "quantity": 200, "unit": "g", "preparation": "peeled", "notes": "Approx 2 medium beets", "substitutions": [], "ingredient_id": "a52110ce-565d-4ce2-adb7-82fe2dba4326", "nutrition_source": "USDA FoodData Central"}, {"name": "carrots", "quantity": 150, "unit": "g", "preparation": "peeled", "notes": "Approx 2 medium carrots", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "red onion", "quantity": 40, "unit": "g", "preparation": "thinly sliced", "notes": null, "substitutions": [], "ingredient_id": "1c270c6e-0acc-4c5c-9935-7eff3240fc4a", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "036c7254-3de5-4c6e-a2e7-366ad4d05077", "nutrition_source": "Aggregated Public Data"}, {"name": "dijon mustard", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "3e25e626-c9b4-4b62-9d08-7c650bcb3d2b", "nutrition_source": "Aggregated Public Data"}, {"name": "honey", "quantity": 15, "unit": "g", "preparation": null, "notes": "To balance earthiness", "substitutions": ["maple syrup"], "ingredient_id": "c28eb19b-d201-4613-8f48-6a449cc81c71", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Assembly", "items": [{"name": "brioche buns", "quantity": 4, "unit": null, "preparation": null, "notes": "Approx 80g each", "substitutions": [], "ingredient_id": "a6757b5b-57ed-49b1-ac42-1ff05554beca", "nutrition_source": "Aggregated Public Data"}, {"name": "mayonnaise", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "97b74a34-8c1f-4c58-b70e-42c1de6d12aa", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 20, "unit": "g", "preparation": "softened", "notes": "For toasting buns", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the slaw vegetables. Using the coarse side of a box grater or a food processor, grate the peeled beetroot and carrots into a large mixing bowl. Add the thinly sliced red onion and chopped parsley.", "structured": {"action": "GRATE", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Whisk together lemon juice, olive oil, Dijon mustard, honey, and a pinch of salt in a small bowl until emulsified. Pour over the grated vegetables and toss thoroughly. Set aside to marinate while cooking the beef.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Divide the cold ground beef into 4 equal portions (150g each). Gently form them into round patties about 2cm wider than your buns (they will shrink). Press a shallow indentation into the center of each patty with your thumb to prevent doming.", "structured": {"action": "SHAPE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": ["Do not overwork the meat or it will become tough.", "Keep meat cold until the moment it hits the pan."]}, {"step_number": 4, "phase": "cook", "text": "Preheat a cast iron skillet over medium-high heat. Spread softened butter on the cut sides of the brioche buns and toast them in the pan until golden brown, about 1-2 minutes. Remove buns and set aside.", "structured": {"action": "TOAST", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Increase heat to high until the pan smokes slightly. Pat beef patties dry if needed. Generously season only the exterior with salt and pepper immediately before placing in the pan. Sear for 3-4 minutes undisturbed to develop a dark crust.", "structured": {"action": "SEAR", "temperature": {"celsius": 230, "fahrenheit": 446}, "duration": "PT4M", "doneness_cues": {"visual": "Deep brown crust developed on bottom", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Flip the patties and cook for another 3-4 minutes. Check internal temperature with a digital thermometer. For standard safety, cook to 71\u00b0C (160\u00b0F).", "structured": {"action": "FRY", "temperature": {"celsius": 71, "fahrenheit": 160}, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove patties from the pan and let them rest for 5 minutes to redistribute juices. While resting, spread mayonnaise on the bottom buns.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Place the rested patty on the bottom bun. Top with a generous amount of drained beetroot slaw (or serve slaw on the side to prevent sogginess) and close with the top bun.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT15M", "total_time": "PT50M", "overnight_required": false, "yields": "4 burgers with side slaw", "yield_count": 4, "serving_size_g": 320}', '{"flags": ["Nut-Free", "Soy-Free"], "not_suitable_for": ["Vegans", "Vegetarians"]}', '{"per_serving": {"calories": 952.51, "protein_g": 33.87, "carbohydrates_g": 39.13, "fat_g": 69.97, "saturated_fat_g": 22.44, "trans_fat_g": 4.2, "monounsaturated_fat_g": 17, "polyunsaturated_fat_g": 7.71, "fiber_g": 3.97, "sugar_g": 12.08, "sodium_mg": 1202.63, "cholesterol_mg": 123.55, "potassium_mg": 820.96, "calcium_mg": 93.71, "iron_mg": 5.38, "magnesium_mg": 44.47, "phosphorus_mg": 339.87, "zinc_mg": 6.63, "vitamin_a_mcg": 533.09, "vitamin_c_mg": 11.39, "vitamin_d_mcg": 0.18, "vitamin_e_mg": 1.17, "vitamin_k_mcg": 74.37, "vitamin_b6_mg": 0.58, "vitamin_b12_mcg": 3.24, "thiamin_mg": 0.11, "riboflavin_mg": 0.28, "niacin_mg": 6.93, "folate_mcg": 78.41, "water_g": 191.89, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store slaw and cooked patties in separate airtight containers. Slaw may bleed color.", "duration": "P3D"}, "freezer": {"notes": "Raw formed patties can be frozen with wax paper separators. Do not freeze slaw.", "duration": "P3M"}, "reheating": "Reheat patties in a skillet over medium heat until heated through. Do not microwave bread.", "does_not_keep": false}', '[{"name": "Cast iron skillet", "required": true, "alternative": "Heavy-bottomed stainless steel pan"}, {"name": "Box grater", "required": true, "alternative": "Food processor with shredding disk"}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Digital instant-read thermometer", "required": true, "alternative": null}, {"name": "Spatula", "required": true, "alternative": null}]', '[{"symptom": "Burgers are tough and dry", "likely_cause": "The meat was overworked during forming or lean beef (<20% fat) was used", "prevention": "Handle ground beef as little as possible; use 80/20 chuck blend", "fix": "Add extra sauce or cheese to mask dryness; cannot be reversed"}, {"symptom": "Slaw is watery", "likely_cause": "Salt in the dressing drew moisture out of the vegetables during resting", "prevention": "Dress slaw closer to serving time", "fix": "Drain excess liquid using a colander before serving"}, {"symptom": "Burgers puffed up into balls", "likely_cause": "Patty centers were not indented before cooking", "prevention": "Press a thumbprint divot into the center of raw patties", "fix": "Press down gently with spatula (caution: releases juices)"}]', '["The secret to a great burger is the Maillard reaction. Ensure the pan is ripping hot and the meat surface is dry before searing.", "Beetroot stains everything. Wear gloves while peeling and grating if you want to avoid pink hands.", "Never mix salt into the burger meat; this cures the protein and creates a sausage-like rubbery texture. Season the surface only.", "The acid in the slaw is designed to cut through the heavy beef fat, acting as a palate cleanser with every bite."]', '"While the hamburger is an American icon, the addition of beetroot is a beloved staple in Australian ''Aussie Burger'' culture. This recipe deconstructs that concept, moving the earthiness of the beet into a bright, acid-forward slaw that modernizes the heavy classic profile."', 952.51);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('07870099-cb87-41ea-bec0-9b1559b5618a', 'Chili-Lime Salmon Tacos with Mango Avocado Salsa', 'Vibrant, tangy tacos featuring spiced pan-seared salmon (or Arctic Char) balanced by a sweet and spicy mango-avocado salsa. Designed to be equally delicious served warm from the pan or chilled for a refreshing summer lunch.', 'main course', 'Mexican-Fusion', 'Easy', '["tacos", "arctic char", "salmon", "salsa", "dinner", "easy", "lunch", "main course", "summer", "dairy-free", "gluten-free", "halal", "healthy", "kosher", "low sugar", "nut-free"]', '[{"group_name": "Spice Rub", "items": [{"name": "chili powder", "quantity": 5, "unit": "g", "preparation": null, "notes": "mild or medium heat", "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Fish", "items": [{"name": "salmon fillets", "quantity": 600, "unit": "g", "preparation": "skin removed", "notes": "Arctic Char is an excellent sustainable alternative", "substitutions": ["Arctic Char", "Steelhead Trout"], "ingredient_id": "6648fae7-4f63-45b3-b45d-19d927b57c2d", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "for searing", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Mango Avocado Salsa", "items": [{"name": "ripe mango", "quantity": 1, "unit": null, "preparation": "diced small", "notes": "approx 200g flesh", "substitutions": [], "ingredient_id": "6ab51d7d-dea3-4f14-8253-76acb67bd2c8", "nutrition_source": "USDA FoodData Central"}, {"name": "avocado", "quantity": 1, "unit": null, "preparation": "diced small", "notes": "firm but ripe", "substitutions": [], "ingredient_id": "35c8f26f-d008-407a-9bf3-48c8aa641729", "nutrition_source": "USDA FoodData Central"}, {"name": "red onion", "quantity": 40, "unit": "g", "preparation": "finely diced", "notes": null, "substitutions": [], "ingredient_id": "1c270c6e-0acc-4c5c-9935-7eff3240fc4a", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh jalape\u00f1o", "quantity": 1, "unit": null, "preparation": "seeded and minced", "notes": "optional for heat", "substitutions": [], "ingredient_id": "4253d4ec-8462-43c6-963a-ae1f94367e2b", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "lime juice", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Crunchy Cabbage Slaw", "items": [{"name": "red cabbage", "quantity": 250, "unit": "g", "preparation": "shredded thinly", "notes": null, "substitutions": [], "ingredient_id": "9a6d138d-1f4e-48f1-af70-ad08153ff908", "nutrition_source": "USDA FoodData Central"}, {"name": "lime juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Assembly", "items": [{"name": "corn tortillas", "quantity": 12, "unit": null, "preparation": "warmed", "notes": "approx 15cm diameter", "substitutions": [], "ingredient_id": "da963b85-8f0b-4c36-b9b1-c31e17b488ae", "nutrition_source": "Aggregated Public Data"}, {"name": "lime wedges", "quantity": 4, "unit": null, "preparation": "for serving", "notes": null, "substitutions": [], "ingredient_id": "d3d2677e-fe02-4404-add0-29d73df7e921", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine chili powder, cumin, smoked paprika, and salt in a small bowl. Pat the salmon fillets dry with paper towels and rub the spice mixture evenly over all sides of the fish.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a medium mixing bowl, combine the shredded red cabbage with 15ml of lime juice and a pinch of salt. Massage with clean hands for 30 seconds to soften the fibers slightly. Set aside to marinate.", "structured": {"action": "MIX", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a separate bowl, combine diced mango, diced avocado, red onion, jalape\u00f1o, cilantro, and 30ml lime juice. Stir gently to combine without mashing the avocado. Season with a pinch of salt to taste.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Heat olive oil in a large non-stick skillet over medium-high heat. Add salmon fillets. Cook for 3-4 minutes per side until well-browned and the internal temperature reaches 52\u00b0C (125\u00b0F) for medium-rare or 63\u00b0C (145\u00b0F) for fully cooked.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT8M", "doneness_cues": {"visual": "Opaque and flakes easily with a fork", "tactile": "Firm but yielding"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove salmon from heat. Using a fork, gently flake the fish into large chunks.", "structured": {"action": "SHRED", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["If serving cold later, transfer the flaked fish to a container and refrigerate now."]}, {"step_number": 6, "phase": "assemble", "text": "Warm the corn tortillas in a dry skillet or directly over a gas flame for 30 seconds until pliable. To assemble, place a bed of cabbage slaw on the tortilla, top with flaked salmon, and finish with a generous spoonful of mango-avocado salsa.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT10M", "total_time": "PT35M", "overnight_required": false, "yields": "12 tacos", "yield_count": 4, "serving_size_g": 320}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Whole30", "Paleo"], "not_suitable_for": []}', '{"per_serving": {"calories": 735.56, "protein_g": 44.78, "carbohydrates_g": 63.79, "fat_g": 49.76, "saturated_fat_g": 1.86, "trans_fat_g": null, "monounsaturated_fat_g": 5.97, "polyunsaturated_fat_g": 2.6, "fiber_g": 11.39, "sugar_g": 12.26, "sodium_mg": 3528.36, "cholesterol_mg": null, "potassium_mg": 675.64, "calcium_mg": 545.94, "iron_mg": 20.88, "magnesium_mg": 545.87, "phosphorus_mg": 773.98, "zinc_mg": 2.98, "vitamin_a_mcg": 560.3, "vitamin_c_mg": 68.76, "vitamin_d_mcg": null, "vitamin_e_mg": 3.22, "vitamin_k_mcg": 30.37, "vitamin_b6_mg": 0.47, "vitamin_b12_mcg": null, "thiamin_mg": 0.16, "riboflavin_mg": 0.18, "niacin_mg": 2.46, "folate_mcg": 54.79, "water_g": 200.77, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store salmon, slaw, and salsa in separate airtight containers. Assemble just before eating.", "duration": "P2D"}, "freezer": {"notes": "Only the cooked salmon can be frozen; fresh toppings will not freeze well.", "duration": "P2M"}, "reheating": "Enjoy cold, or reheat salmon gently in a skillet over low heat. Do not microwave fish to avoid texture degradation.", "does_not_keep": false}', '[{"name": "Large non-stick skillet", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Mixing bowls", "required": true, "alternative": "Large food storage containers"}, {"name": "Citrus juicer", "required": false, "alternative": null}]', '[{"symptom": "Salmon is dry", "likely_cause": "Overcooking; salmon cooks very quickly, especially skinless fillets", "prevention": "Remove from heat as soon as the center is just barely opaque; it will continue cooking with residual heat", "fix": "Mix the flaked salmon with a little extra lime juice and olive oil before serving to add moisture"}, {"symptom": "Tortillas are breaking/cracking", "likely_cause": "Corn tortillas were not warmed properly before assembly", "prevention": "Must heat corn tortillas to release natural oils and make them pliable", "fix": "Double up the tortillas (use two per taco) for structural support"}]', '["To make this a ''meal prep'' lunch, keep the salsa separate from the tortillas until ready to eat to prevent sogginess. The salmon and slaw hold up beautifully in the fridge.", "Arctic Char is a fantastic alternative to salmon; it has a similar fat content but often a milder flavor that pairs perfectly with fruit salsas.", "If you prefer a creamy element without dairy, blend half of the avocado with the lime juice and a splash of water to make a pourable sauce instead of a chunky salsa.", "For a lower carb version, swap the corn tortillas for large lettuce cups (Bibb or Romaine)."]', '"Baja-style fish tacos originated in Baja California, Mexico, typically featuring battered white fish. This version adapts that concept for a lighter, modern profile, utilizing the rich oils of salmon (or Arctic Char) and replacing heavy creams with the brightness of fruit salsas, a technique popular in coastal Californian cuisine."', 735.56);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('078dc5d6-5c1f-4746-8157-20d451b1c214', 'Sour Cherry & Walnut Whole Wheat Crumble', 'A rustic dessert featuring a vibrant, jammy interior of tart sour cherries balanced by a nutty, textural topping made from whole wheat flour, toasted walnuts, and buttery oats.', 'dessert', 'American', 'Easy', '["crumble", "sour cherry", "walnut", "whole wheat flour", "easy", "dessert", "baked good"]', '[{"group_name": "Sour Cherry Filling", "items": [{"name": "sour cherries", "quantity": 800, "unit": "g", "preparation": "pitted", "notes": "fresh or frozen (do not thaw if frozen)", "substitutions": ["sweet cherries (reduce sugar to 100g)", "cranberries"], "ingredient_id": "e741f4be-1c3e-4bba-8c4a-c3cbf5ec4ebd", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": "adjust slightly based on fruit tartness", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Walnut Whole Wheat Streusel", "items": [{"name": "whole wheat flour", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "af2661d8-b555-4fef-bdee-51a5190eda92", "nutrition_source": "USDA FoodData Central"}, {"name": "rolled oats", "quantity": 50, "unit": "g", "preparation": null, "notes": "old-fashioned, not instant", "substitutions": [], "ingredient_id": "11381622-c748-499c-b9c5-58fcb9d70fd3", "nutrition_source": "Aggregated Public Data"}, {"name": "brown sugar", "quantity": 100, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "walnuts", "quantity": 60, "unit": "g", "preparation": "roughly chopped", "notes": null, "substitutions": ["pecans", "almonds"], "ingredient_id": "ab4fe25a-a215-4af7-8109-055c28e0bef2", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 0.5 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 85, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": ["vegan butter block"], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 190\u00b0C (375\u00b0F) and set a rack in the middle position.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, toss the pitted sour cherries with granulated sugar, cornstarch, and vanilla extract until the fruit is evenly coated and no dry pockets of starch remain.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["If using frozen cherries, toss them while frozen; they will release liquid as they bake to create the sauce."]}, {"step_number": 3, "phase": "prep", "text": "Transfer the cherry mixture into the baking dish, spreading it into an even layer.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In a medium bowl, whisk together the whole wheat flour, rolled oats, brown sugar, chopped walnuts, cinnamon, and salt.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Add the cold, cubed butter to the dry ingredients. Use your fingertips to rub the butter into the mixture until it resembles coarse, wet sand with some pea-sized clumps remaining.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Coarse crumbs", "tactile": "Butter fully incorporated but clumpy"}}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Scatter the crumble topping generously over the fruit layer, squeezing some handfuls to create larger clusters for texture.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Bake for 40 to 45 minutes, or until the topping is deep golden brown and the cherry filling is vigorously bubbling around the edges and in the center.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT45M", "doneness_cues": {"visual": "Filling bubbling in the center, topping golden brown", "tactile": null}}, "tips": ["Bubbling in the center is crucial; it ensures the cornstarch has reached activation temperature to thicken the juices."]}, {"step_number": 8, "phase": "finish", "text": "Remove from the oven and let the crumble rest on a wire rack for at least 15-20 minutes before serving. This allows the filling to set and thicken.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT1H", "total_time": "PT1H20M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 220}', '{"flags": ["Vegetarian", "Egg-Free", "Soy-Free"], "not_suitable_for": ["Nut allergies (walnuts)", "Gluten intolerance"]}', '{"per_serving": {"calories": 502.92, "protein_g": 5.72, "carbohydrates_g": 82.09, "fat_g": 19.32, "saturated_fat_g": 8.02, "trans_fat_g": 0.08, "monounsaturated_fat_g": 4.37, "polyunsaturated_fat_g": 5.46, "fiber_g": 6.05, "sugar_g": 53.07, "sodium_mg": 141.57, "cholesterol_mg": 30.46, "potassium_mg": 399.51, "calcium_mg": 62.72, "iron_mg": 1.9, "magnesium_mg": 61.04, "phosphorus_mg": 147.58, "zinc_mg": 1.27, "vitamin_a_mcg": 182.38, "vitamin_c_mg": 13.48, "vitamin_d_mcg": null, "vitamin_e_mg": 0.59, "vitamin_k_mcg": 4.48, "vitamin_b6_mg": 0.14, "vitamin_b12_mcg": 0.02, "thiamin_mg": 0.13, "riboflavin_mg": 0.11, "niacin_mg": 1.57, "folate_mcg": 25.75, "water_g": 120.69, "alcohol_g": 0.29, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Cover tightly; reheat to restore crispness.", "duration": "P4D"}, "freezer": {"notes": "Freeze unbaked for best results, or baked and cooled.", "duration": "P3M"}, "reheating": "Reheat in a 175\u00b0C (350\u00b0F) oven for 10-15 minutes to re-crisp the topping.", "does_not_keep": false}', '[{"name": "Baking dish (23cm / 9-inch square or round)", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Medium mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": false, "alternative": "Fork"}]', '[{"symptom": "Filling is too runny after serving", "likely_cause": "The crumble was not baked long enough for the cornstarch to activate, or it was served too hot.", "prevention": "Ensure the fruit juices boil in the very center of the dish before removing from the oven.", "fix": "Let it cool completely; the pectin and starch will continue to gel as temperature drops."}]', '["Sour cherries have a high acid content which pairs beautifully with the earthy, nutty flavor of whole wheat flour and walnuts.", "If using sweet cherries (Bing or Rainier) instead of sour, reduce the sugar in the filling by 30-50g and add 15ml lemon juice to balance the acidity.", "For extra crunch, toast the walnuts briefly in a dry pan before adding them to the crumble topping.", "Serve warm with a scoop of vanilla ice cream or a pour of cold heavy cream to cut through the richness."]', '"While fruit crumbles originated in Britain during World War II as a flour-rationing alternative to pies, the use of sour cherries (often Montmorency) is distinctly tied to American baking traditions, particularly in the Midwest regions like Michigan."', 502.92);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('081efa84-48ac-4577-8fbb-9a267867d215', 'Classic Soft-Shell Crabs Meunière', 'Crisp, golden-fried soft-shell crabs served with a nutty, foaming brown butter and lemon sauce. The delicate sweetness of the crab is amplified by the toasted milk solids of the butter and brightened by fresh parsley and capers.', 'dinner', 'French', 'Intermediate', '["seafood", "brown butter", "crab", "dinner", "easy", "quick", "french", "summer"]', '[{"group_name": "Crabs", "items": [{"name": "soft-shell crabs", "quantity": 8, "unit": null, "preparation": "fresh or thawed", "notes": "cleaned, approx. 500g total", "substitutions": [], "ingredient_id": "2ce537a0-fad3-40b0-a1aa-1eac21539b1f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dredge", "items": [{"name": "all-purpose flour", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Frying", "items": [{"name": "neutral oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "grapeseed or canola", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Brown Butter Sauce", "items": [{"name": "unsalted butter", "quantity": 80, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "capers", "quantity": 15, "unit": "g", "preparation": "drained", "notes": null, "substitutions": [], "ingredient_id": "e7301d2c-b906-4ef8-917e-787be0b25880", "nutrition_source": "USDA FoodData Central"}, {"name": "flat-leaf parsley", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Clean the crabs if not pre-cleaned: Using shears, cut off the front of the face (behind the eyes). Lift the side points of the top shell and pull out the fibrous gills. Flip over and pull off the apron flap. Rinse briefly.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Ask your fishmonger to clean them for you to save time."]}, {"step_number": 2, "phase": "prep", "text": "Pat the crabs extremely dry with paper towels. Press gently to expel excess water from the legs and body cavities.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Moisture is the enemy of crispiness and causes dangerous oil splatter."]}, {"step_number": 3, "phase": "prep", "text": "In a shallow dish, combine the flour, salt, and black pepper. Dredge each crab lightly, shaking off all excess flour.", "structured": {"action": "DREDGE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Heat the neutral oil and frying butter (30g) in a large skillet over medium-high heat until the butter foams and subsides.", "structured": {"action": "HEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Place crabs in the pan, shell-side down (do not crowd; cook in batches if necessary). Sear until golden brown and crisp, about 3 minutes.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown crust", "tactile": null}}, "tips": ["Use a splatter screen as soft-shell crabs tend to pop and spit hot fat."]}, {"step_number": 6, "phase": "cook", "text": "Flip the crabs and cook the other side until crisp and cooked through, about 2 minutes. Transfer to a warm plate.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 63, "fahrenheit": 145}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Wipe out the skillet carefully. Add the sauce butter (80g) and melt over medium heat. Swirl constantly until the milk solids turn a hazelnut brown and smell nutty.", "structured": {"action": "CARAMELIZE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Golden-brown specks", "tactile": "Nutty aroma"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Immediately remove from heat. Stir in lemon juice, capers, and parsley (caution: it will sputter). Spoon the foaming sauce over the crabs and serve.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT0M", "total_time": "PT25M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 200}', '{"flags": ["Pescatarian", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Shellfish allergy", "Dairy allergy", "Gluten intolerance"]}', '{"per_serving": {"calories": 425.67, "protein_g": 26.26, "carbohydrates_g": 12.78, "fat_g": 31.41, "saturated_fat_g": 15.01, "trans_fat_g": null, "monounsaturated_fat_g": 6.46, "polyunsaturated_fat_g": 0.91, "fiber_g": 1.12, "sugar_g": 0.32, "sodium_mg": 1100.49, "cholesterol_mg": 59.13, "potassium_mg": 325.54, "calcium_mg": 122.39, "iron_mg": 2, "magnesium_mg": 7.43, "phosphorus_mg": 25.72, "zinc_mg": 0.18, "vitamin_a_mcg": 202.77, "vitamin_c_mg": 7.44, "vitamin_d_mcg": null, "vitamin_e_mg": 0.71, "vitamin_k_mcg": 44.71, "vitamin_b6_mg": 0.01, "vitamin_b12_mcg": 0.05, "thiamin_mg": 0.02, "riboflavin_mg": 0.02, "niacin_mg": 0.26, "folate_mcg": 10.22, "water_g": 15.1, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Texture degrades rapidly; best eaten immediately.", "duration": "P1D"}, "freezer": {"notes": "Do not freeze cooked soft-shell crabs.", "duration": null}, "reheating": "Reheat in a dry pan over medium heat to recrisp, but fresh is significantly better.", "does_not_keep": true}', '[{"name": "Kitchen shears", "required": true, "alternative": null}, {"name": "Large skillet", "required": true, "alternative": "Saut\u00e9 pan"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Shallow dish", "required": true, "alternative": null}, {"name": "Paper towels", "required": true, "alternative": null}, {"name": "Splatter screen", "required": false, "alternative": "Lid (slightly ajar)"}]', '[{"symptom": "Breading is soggy or falling off", "likely_cause": "Crabs were too wet or pan was overcrowded", "prevention": "Pat crabs very dry before dredging and leave space between them in the pan", "fix": "Place on a wire rack in a 200\u00b0C/400\u00b0F oven for 2-3 minutes to dry out"}, {"symptom": "Butter sauce tastes bitter", "likely_cause": "Butter solids were burned rather than browned", "prevention": "Remove pan from heat the moment the butter smells nutty and turns golden", "fix": "Cannot be fixed; discard and start sauce over"}]', '["Soft-shell crabs are blue crabs caught immediately after molting. Their season typically runs from late spring to early autumn.", "Beurre Noisette (brown butter) relies on residual heat; removing the pan from the burner before it looks fully done prevents burning.", "If the crabs are very large, you can prick the legs and claws with a pin before frying to release steam and reduce popping.", "Serve with crusty baguette to mop up the excess brown butter."]', '"This preparation is a variation of ''\u00e0 la Meuni\u00e8re'' (in the style of the miller''s wife), a classic French technique traditionally applied to sole. The dusting of flour protects the delicate protein while creating a crisp crust that absorbs the rich butter sauce."', 425.67);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('083a2990-1d4c-4603-888c-60f0b82ea611', 'Hunter''s Duck and Wild Mushroom Gumbo', 'A deep, smoky, and earthy variation of the Louisiana classic. This gumbo pairs the gaminess of dark-meat duck with the forest floor aroma of wild mushrooms and spicy Andouille sausage, brought together by a dark chocolate roux and finished with the herbal notes of filé powder.', 'soup', 'Cajun', 'Advanced', '["southern", "andouille sausage", "duck", "great leftovers", "wild mushrooms", "fall", "thanksgiving", "cajun", "stew"]', '[{"group_name": "Proteins", "items": [{"name": "duck legs (thigh and drumstick)", "quantity": 4, "unit": null, "preparation": "whole, skin-on", "notes": "approx. 1kg total weight", "substitutions": [], "ingredient_id": "5525ed3e-a663-4b6c-beee-5c2a1c7b0558", "nutrition_source": "Aggregated Public Data"}, {"name": "andouille sausage", "quantity": 400, "unit": "g", "preparation": "sliced into 1cm rounds", "notes": null, "substitutions": [], "ingredient_id": "81514dd5-808c-4be0-bbb9-913164ad1db8", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Roux & Fat", "items": [{"name": "vegetable oil or rendered duck fat", "quantity": 240, "unit": "ml", "preparation": null, "notes": "divided use", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "all-purpose flour", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables & Aromatics", "items": [{"name": "yellow onion", "quantity": 300, "unit": "g", "preparation": "diced", "notes": null, "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "green bell pepper", "quantity": 150, "unit": "g", "preparation": "diced", "notes": null, "substitutions": [], "ingredient_id": "73526a0d-a2c7-4cac-8f5e-a77e5faf659d", "nutrition_source": "USDA FoodData Central"}, {"name": "celery", "quantity": 150, "unit": "g", "preparation": "diced", "notes": null, "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "wild mushrooms (chanterelle, oyster, or hen-of-the-woods)", "quantity": 300, "unit": "g", "preparation": "cleaned and torn", "notes": "use cremini if wild unavailable", "substitutions": [], "ingredient_id": "59d83971-a3c1-4b9c-b949-625005657048", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 6, "unit": null, "preparation": "minced", "notes": "approx. 30g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Liquid & Seasoning", "items": [{"name": "duck or chicken stock", "quantity": 2000, "unit": "ml", "preparation": "warm", "notes": null, "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}, {"name": "worcestershire sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "aa552099-60a9-4267-a732-5870a271c28f", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh thyme sprigs", "quantity": 4, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "dried bay leaves", "quantity": 3, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eab2ef3a-7a0e-4188-b746-645b795ada1e", "nutrition_source": "USDA FoodData Central"}, {"name": "cajun seasoning blend", "quantity": 30, "unit": "g", "preparation": null, "notes": "adjust sodium based on stock used", "substitutions": [], "ingredient_id": "0bb6ae01-a6b4-4464-929b-a0b79f6e5ca5", "nutrition_source": "Aggregated Public Data"}, {"name": "cayenne pepper", "quantity": 5, "unit": "g", "preparation": null, "notes": "to taste for heat", "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "fil\u00e9 powder (ground sassafras)", "quantity": 15, "unit": "g", "preparation": null, "notes": "plus more for table service", "substitutions": [], "ingredient_id": "41fc1ca1-fe2a-4ec7-bb31-0bff8f637dc8", "nutrition_source": "Aggregated Public Data"}, {"name": "green onions", "quantity": 40, "unit": "g", "preparation": "sliced", "notes": null, "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "cooked white rice", "quantity": 800, "unit": "g", "preparation": "hot, for serving", "notes": null, "substitutions": [], "ingredient_id": "d8a2c73d-e2de-4182-b43b-6bdf55f00a87", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Season the duck legs generously with salt and pepper. In the Dutch oven over medium-high heat, sear the duck legs skin-side down until the skin is golden and crisp and the fat has rendered (about 8-10 minutes). Flip and sear the other side for 2 minutes. Remove duck and set aside. Pour off the rendered fat into a measuring cup.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT12M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In the same pot, add the sliced Andouille sausage. Fry until browned and the oils release. Remove sausage with a slotted spoon and set aside with the duck. Do not clean the pot.", "structured": {"action": "FRY", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Browned edges", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Check the amount of fat in the pot. Add enough reserved duck fat or vegetable oil to equal exactly 120ml total fat. Lower heat to medium. Sprinkle in the flour. Whisk constantly and slowly for 30-45 minutes. The roux must reach a dark chocolate color. Do not walk away.", "structured": {"action": "STIR", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT45M", "doneness_cues": {"visual": "Dark chocolate brown color", "tactile": "Smooth, slightly thinned consistency"}}, "tips": ["If black specks appear, the flour has burned. You must discard and start over.", "The darker the roux, the less thickening power it has, but the deeper the flavor."]}, {"step_number": 4, "phase": "cook", "text": "Immediately add the onion, celery, and bell pepper (the Trinity) to the dark roux to stop the cooking process. Stir vigorously. Cook for 5-7 minutes until vegetables are softened. Add the minced garlic and wild mushrooms; cook for another 3 minutes.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Vegetables softened", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Slowly whisk in the warm stock, a ladle at a time, to ensure no lumps form. Add the Worcestershire sauce, Cajun seasoning, thyme, bay leaves, and cayenne. Bring to a boil, then reduce to a gentle simmer.", "structured": {"action": "SIMMER", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Return the seared duck legs to the pot (keep the sausage aside for later). Cover the pot and simulate a low braise for 1.5 to 2 hours, or until the duck meat pulls away easily from the bone.", "structured": {"action": "BRAISE", "temperature": null, "duration": "PT2H", "doneness_cues": {"visual": null, "tactile": "Fork tender"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove the duck legs. Let them cool slightly, then remove and discard the skin and bones. Shred the meat into large chunks. Skim any excess oil from the surface of the gumbo.", "structured": {"action": "SHRED", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Return the shredded duck meat and the browned sausage to the pot. Simmer uncovered for 30 minutes to marry flavors and thicken slightly.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Turn off the heat completely. Remove bay leaves and thyme stems. Stir in the fil\u00e9 powder and green onions. Do not let the soup boil after adding fil\u00e9, or it will become stringy. Serve immediately over white rice.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Texture thickens slightly and becomes glossy"}}, "tips": []}]', '{"active_time": "PT1H15M", "passive_time": "PT2H30M", "total_time": "PT3H45M", "overnight_required": false, "yields": "8 generous bowls", "yield_count": 8, "serving_size_g": 350}', '{"flags": ["Dairy-Free", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 994.27, "protein_g": 53.42, "carbohydrates_g": 57.92, "fat_g": 86.74, "saturated_fat_g": 4.51, "trans_fat_g": null, "monounsaturated_fat_g": 0.14, "polyunsaturated_fat_g": 0.44, "fiber_g": 5.01, "sugar_g": 3.61, "sodium_mg": 11185.7, "cholesterol_mg": null, "potassium_mg": 502.27, "calcium_mg": 107.92, "iron_mg": 10.34, "magnesium_mg": 32.41, "phosphorus_mg": 205.61, "zinc_mg": 1.48, "vitamin_a_mcg": 25.85, "vitamin_c_mg": 24.8, "vitamin_d_mcg": 1.91, "vitamin_e_mg": 0.37, "vitamin_k_mcg": 18, "vitamin_b6_mg": 0.39, "vitamin_b12_mcg": null, "thiamin_mg": 0.31, "riboflavin_mg": 0.15, "niacin_mg": 3.71, "folate_mcg": 109.65, "water_g": 182.21, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves significantly after 24 hours.", "duration": "P4D"}, "freezer": {"notes": "Freeze without rice. Thaw completely before reheating.", "duration": "P3M"}, "reheating": "Reheat gently on the stovetop over medium-low heat. Do not boil vigorously once fil\u00e9 has been added.", "does_not_keep": false}', '[{"name": "Large Dutch oven (6L+)", "required": true, "alternative": "Heavy-bottomed stock pot"}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Ladles/Skimmers", "required": true, "alternative": null}]', '[{"symptom": "Burnt taste / Black specks in roux", "likely_cause": "Heat was too high or stirring stopped", "prevention": "Whisk constantly and control heat; patience is key", "fix": "Cannot be fixed. Discard and start roux over. Do not risk ruining expensive ingredients."}, {"symptom": "Gumbo is stringy or ropey", "likely_cause": "Fil\u00e9 powder was boiled", "prevention": "Only add fil\u00e9 after turning off the heat", "fix": "Dilute with more hot stock, though texture may remain compromised"}]', '["The color of the roux dictates the flavor profile. For this gumbo, push the roux to the color of dark chocolate; if you stop at peanut butter color, the flavor will lack the necessary depth to stand up to the duck.", "Fil\u00e9 powder (ground sassafras leaves) adds a unique root-beer-like herbal note and thickens without starch. It is crucial to add it off-heat.", "Using wild mushrooms like chanterelles adds a woody element that complements the gaminess of the duck perfectly. Regular button mushrooms are a poor substitute; use cremini or shiitake if wild are unavailable.", "Like most stews, this dish tastes significantly better the next day as the flavors meld. Reheat gently to avoid breaking the emulsion or overcooking the fil\u00e9."]', '"Gumbo is the quintessential dish of Louisiana, representing the intersection of West African, French, Spanish, and Choctaw cultures. This version leans towards the Cajun prairie style with its use of game (duck) and dark roux, combined with the Choctaw contribution of kombo fil\u00e9 (sassafras powder) as a primary thickener and flavoring agent."', 994.27);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('08971b98-aa7d-4f53-a645-8e7702783156', 'Summer Garden Orecchiette with Lemon and Herbs', 'A vibrant, light pasta dish that celebrates the peak of summer produce. The cup-shaped orecchiette catches the sweet corn kernels and burst cherry tomatoes, while a lemon-garlic emulsion creates a glossy, clinging sauce without heavy cream.', 'main course', 'Italian', 'Easy', '["mediterranean", "pastas", "orecchiette", "pasta", "summer vegetables", "lunch", "weeknight", "main course", "summer", "vegetarian", "quick"]', '[{"group_name": "Pasta and Base", "items": [{"name": "dried orecchiette pasta", "quantity": 400, "unit": "g", "preparation": null, "notes": "Or any short pasta shape like fusilli or penne", "substitutions": ["fusilli", "farfalle"], "ingredient_id": "52cdfe63-4362-4d80-9ed0-9fc7041f2721", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": "Plus extra for finishing", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "thinly sliced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "red pepper flakes", "quantity": null, "unit": null, "preparation": "dried", "notes": "Pinch to taste", "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Vegetables", "items": [{"name": "zucchini", "quantity": 300, "unit": "g", "preparation": "diced small", "notes": "About 2 medium zucchini", "substitutions": [], "ingredient_id": "c34b610f-8869-4d77-a9b3-e01849d703b5", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh corn kernels", "quantity": 150, "unit": "g", "preparation": "raw", "notes": "Cut from approx 1-2 cobs", "substitutions": ["frozen corn"], "ingredient_id": "46ca2aab-cb23-4397-9711-528c234b2cf8", "nutrition_source": "USDA FoodData Central"}, {"name": "cherry tomatoes", "quantity": 250, "unit": "g", "preparation": "halved", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Finishing", "items": [{"name": "lemon", "quantity": 1, "unit": null, "preparation": "whole", "notes": "Zest and juice kept separate", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "parmesan cheese", "quantity": 40, "unit": "g", "preparation": "grated", "notes": null, "substitutions": ["pecorino romano", "nutritional yeast (for vegan)"], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh basil leaves", "quantity": 15, "unit": "g", "preparation": "torn", "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "To taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "Freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Bring a large pot of salted water to a rolling boil. While waiting, dice the zucchini, slice the garlic, halve the tomatoes, and cut the corn from the cob.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add the orecchiette to the boiling water. Cook until 1 minute shy of al dente according to package directions (usually 9-11 minutes). Reserve 250ml (approx 1 cup) of starchy pasta water before draining.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": null, "tactile": "Slight resistance in the center"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "While pasta cooks, heat olive oil in the large skillet over medium-high heat. Add zucchini and corn. Saut\u00e9 undisturbed for 2-3 minutes to develop golden brown spots, then toss and cook for another 2 minutes.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Golden brown edges on vegetables", "tactile": null}}, "tips": ["Do not overcrowd the pan or the vegetables will steam instead of browning."]}, {"step_number": 4, "phase": "cook", "text": "Reduce heat to medium. Add the sliced garlic, red pepper flakes (if using), and halved cherry tomatoes. Cook for 2-3 minutes until garlic is fragrant and tomatoes just begin to soften and release their juices.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Tomatoes slightly slumped", "tactile": "Garlic soft but not burnt"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Add the drained pasta directly to the skillet along with 120ml of the reserved pasta water. Toss vigorously over medium heat for 1-2 minutes. The starch in the water will emulsify with the oil to create a creamy coating.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Glossy sauce coating the pasta", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove pan from heat. Stir in the lemon zest, lemon juice, grated parmesan, and torn basil. Taste and adjust with salt and generous black pepper. If the pasta looks dry, add a splash more pasta water.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT0M", "total_time": "PT25M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 371.69, "protein_g": 12.18, "carbohydrates_g": 39.15, "fat_g": 20.25, "saturated_fat_g": 4.18, "trans_fat_g": null, "monounsaturated_fat_g": 12.39, "polyunsaturated_fat_g": 2.46, "fiber_g": 3.46, "sugar_g": 7.27, "sodium_mg": 411.35, "cholesterol_mg": 47.8, "potassium_mg": 536.78, "calcium_mg": 167.51, "iron_mg": 2.32, "magnesium_mg": 58.31, "phosphorus_mg": 210.28, "zinc_mg": 1.33, "vitamin_a_mcg": 61.36, "vitamin_c_mg": 37.74, "vitamin_d_mcg": 0.05, "vitamin_e_mg": 2.4, "vitamin_k_mcg": 28.68, "vitamin_b6_mg": 0.28, "vitamin_b12_mcg": 0.22, "thiamin_mg": 0.28, "riboflavin_mg": 0.31, "niacin_mg": 2.39, "folate_mcg": 82.63, "water_g": 195.91, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Vegetables may soften upon reheating.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; vegetables will become mushy.", "duration": null}, "reheating": "Reheat gently in a pan with a splash of water to re-emulsify the sauce.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Large saut\u00e9 pan or skillet", "required": true, "alternative": "Wok or Dutch oven"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Microplane or zester", "required": true, "alternative": "Small side of box grater"}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "Pasta dish tastes dry or oily rather than creamy", "likely_cause": "The emulsion broke or not enough starchy water was used", "prevention": "Reserve plenty of pasta water; toss vigorously", "fix": "Add 2-3 tablespoons of hot water and toss rapidly off the heat to bring the sauce back together"}]', '["Orecchiette (''little ears'') is the ideal shape for this dish because the cup shape scoops up the corn kernels and sauce.", "Do not overcook the zucchini; retaining a slight crunch provides necessary texture contrast to the soft pasta.", "Finishing with acid (lemon juice) right at the end brightens the flavors and cuts through the starchiness of the pasta.", "For a vegan version, omit the parmesan and use a generous sprinkle of toasted breadcrumbs mixed with nutritional yeast for texture."]', '"This style of dish, often called ''Pasta Primavera'' in the US or ''Pasta all''Ortolana'' (Greengrocer''s pasta) in Italy, highlights the philosophy of cucina povera: using simple, seasonal ingredients available in the garden to create a filling meal. Orecchiette specifically hails from the Apulia region of Southern Italy."', 371.69);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('08be663f-d85e-4a63-8fb1-84863853ba8c', 'Mediterranean Lentil and Courgette Pasta Bake', 'A comforting, hands-off dinner where the pasta cooks directly in a rich tomato-herb sauce alongside earthy lentils and tender courgettes. Finished with salty blocks of baked feta and bright lemon zest.', 'dinner', 'Mediterranean', 'Easy', '["pasta", "lentils", "courgette", "feta", "one-dish", "bake", "mediterranean"]', '[{"group_name": "Vegetables & Legumes", "items": [{"name": "brown lentils", "quantity": 400, "unit": "g", "preparation": "canned", "notes": "rinsed and drained; weight is can net weight (approx 240g drained)", "substitutions": [], "ingredient_id": "fc77776c-fd4a-436e-a164-8fdf1198fea3", "nutrition_source": "Aggregated Public Data"}, {"name": "courgettes", "quantity": 2, "unit": null, "preparation": "diced into 2cm cubes", "notes": "approx 400g total", "substitutions": [], "ingredient_id": "d0aa0d47-cefe-4ece-a337-e656f79b74e9", "nutrition_source": "USDA FoodData Central"}, {"name": "red onion", "quantity": 1, "unit": null, "preparation": "finely chopped", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Base & Liquid", "items": [{"name": "dried short pasta", "quantity": 300, "unit": "g", "preparation": null, "notes": "fusilli, penne, or rigatoni", "substitutions": ["gluten-free pasta (reduce liquid by 50ml)"], "ingredient_id": "9acd8d49-8848-4e5f-90e4-33b9b31f83c9", "nutrition_source": "Aggregated Public Data"}, {"name": "crushed tomatoes", "quantity": 400, "unit": "g", "preparation": "canned", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable stock", "quantity": 600, "unit": "ml", "preparation": "hot", "notes": null, "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "tomato paste", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "1a1bddc5-66c3-4f44-bb24-72b8ac828ca6", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "adjust based on stock saltiness", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Topping", "items": [{"name": "feta cheese", "quantity": 200, "unit": "g", "preparation": "block or large crumble", "notes": null, "substitutions": [], "ingredient_id": "a9a8605c-3bf2-4ca3-8c58-80e87aff7cd8", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": null, "notes": "zest of 1 lemon", "substitutions": [], "ingredient_id": "03fb65be-9b62-44e7-a121-694de64cdec0", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh basil", "quantity": 10, "unit": "g", "preparation": "torn", "notes": "for garnish", "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 200\u00b0C (400\u00b0F).", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "assemble", "text": "In the baking dish, whisk together the hot vegetable stock, crushed tomatoes, tomato paste, olive oil, dried oregano, minced garlic, salt, and pepper until combined.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "assemble", "text": "Add the uncooked pasta, drained lentils, chopped red onion, and diced courgettes to the liquid. Stir well, ensuring the pasta is mostly submerged in the liquid to ensure even cooking.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["If the pasta is sticking out too much, press it down with the back of a spoon."]}, {"step_number": 4, "phase": "cook", "text": "Cover the dish tightly with aluminum foil or a lid. Bake for 35 minutes.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT35M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Remove the foil. Stir the pasta gently to release any starch. Break the feta cheese into large chunks and scatter them over the top. Return to the oven uncovered for 10-15 minutes, or until the pasta is tender and the feta is beginning to brown.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT15M", "doneness_cues": {"visual": "Feta edges are golden brown", "tactile": "Pasta is al dente when pierced with a fork"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove from the oven and let it rest for 5 minutes (the sauce will thicken as it cools). Sprinkle with fresh lemon zest and torn basil leaves before serving.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT45M", "total_time": "PT1H", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 675.31, "protein_g": 30.5, "carbohydrates_g": 93.11, "fat_g": 21.45, "saturated_fat_g": 8.4, "trans_fat_g": null, "monounsaturated_fat_g": 7.81, "polyunsaturated_fat_g": 1.13, "fiber_g": 14.4, "sugar_g": 13.59, "sodium_mg": 1810.29, "cholesterol_mg": 44.5, "potassium_mg": 1265.1, "calcium_mg": 342.58, "iron_mg": 7.22, "magnesium_mg": 119.49, "phosphorus_mg": 689.93, "zinc_mg": 5.27, "vitamin_a_mcg": 129.8, "vitamin_c_mg": 22.42, "vitamin_d_mcg": 0.2, "vitamin_e_mg": 1.44, "vitamin_k_mcg": 24.6, "vitamin_b6_mg": 0.32, "vitamin_b12_mcg": 0.85, "thiamin_mg": 0.11, "riboflavin_mg": 0.45, "niacin_mg": 0.65, "folate_mcg": 27.99, "water_g": 65.7, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Pasta may absorb more liquid over time.", "duration": "P4D"}, "freezer": {"notes": "Texture of courgettes may soften significantly upon thawing.", "duration": "P2M"}, "reheating": "Reheat in the oven at 175\u00b0C covered with foil to prevent drying out, or microwave with a splash of water.", "does_not_keep": false}', '[{"name": "Large baking dish (approx 23x33cm)", "required": true, "alternative": "Deep casserole dish or Dutch oven"}, {"name": "Aluminum foil", "required": true, "alternative": "Oven-safe lid"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Pasta is still hard after baking", "likely_cause": "The seal on the foil was not tight enough, allowing steam to escape, or the pasta wasn''t submerged.", "prevention": "Ensure a tight seal during the first phase of baking and keep pasta under the liquid line.", "fix": "Add 50-100ml of boiling water, stir, cover tightly again, and bake for another 5-10 minutes."}]', '["Use a block of feta in brine rather than pre-crumbled feta; the block retains moisture better and won''t dry out during baking.", "Cut the courgettes into medium chunks rather than small dice so they maintain some texture and don''t disappear into the sauce.", "The liquid ratio is key here. If you substitute gluten-free pasta, check it 5 minutes early as it tends to absorb water differently and can turn mushy quickly."]', '"This dish borrows from the Greek tradition of ''Yiouvetsi'' (meat and pasta baked in sauce) but adapts it into a vegetarian everyday meal. The combination of lentils and feta is a staple of Mediterranean peasant cooking, providing a complete protein profile with robust flavors."', 675.31);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('095b8a0d-b352-4792-95c1-fb2b22015e6c', 'Garlic Cumin Lamb Meatballs', 'Juicy, aromatic ground lamb meatballs spiced with earthy cumin, fresh garlic, and herbs. These meatballs are pan-seared to create a flavorful caramelized crust while remaining tender and moist on the inside.', 'dinner', 'Middle Eastern', 'Easy', '["ground lamb", "dinner", "main course", "middle eastern", "quick", "high protein"]', '[{"group_name": "Meat Base", "items": [{"name": "ground lamb", "quantity": 500, "unit": "g", "preparation": "chilled", "notes": null, "substitutions": [], "ingredient_id": "283a36a7-2de3-480f-a632-76e0445799dd", "nutrition_source": "USDA FoodData Central"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": "beaten", "notes": "approx 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "panko breadcrumbs", "quantity": 40, "unit": "g", "preparation": null, "notes": null, "substitutions": ["regular breadcrumbs", "gluten-free breadcrumbs", "almond flour (for keto)"], "ingredient_id": "84fbc204-4457-40ed-83c1-3e5a7bcd8f23", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Aromatics & Spices", "items": [{"name": "garlic", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 6, "unit": "g", "preparation": null, "notes": "approx 2 tsp", "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "onion", "quantity": 0.5, "unit": null, "preparation": "grated or finely minced", "notes": "approx 50g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "for frying", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the aromatics: grate the onion directly into the mixing bowl (to catch the juices), mince the garlic, and chop the parsley.", "structured": {"action": "GRATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Add the ground lamb, beaten egg, panko breadcrumbs, cumin, salt, pepper, and chopped parsley to the bowl with the onion and garlic.", "structured": {"action": "MEASURE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Gently mix the ingredients with your hands until just combined. Do not overwork the meat, or the meatballs will become tough.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Ingredients evenly distributed but mixture remains loose"}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Form the mixture into approximately 20 balls (about the size of a golf ball). If you have time, chill them in the refrigerator for 15 minutes to help them hold their shape.", "structured": {"action": "SHAPE", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": ["Wet your hands slightly with water or oil to prevent the meat from sticking while rolling."]}, {"step_number": 5, "phase": "cook", "text": "Heat the olive oil in a large skillet over medium-high heat. Once hot, add the meatballs in a single layer, ensuring they are not crowded (cook in batches if necessary).", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Sear the meatballs for 6-8 minutes, turning occasionally, until browned on all sides and cooked through. The internal temperature should reach at least 71\u00b0C (160\u00b0F).", "structured": {"action": "SEAR", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Deep golden brown crust", "tactile": "Firm to the touch"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Transfer the cooked meatballs to a plate lined with paper towels to drain excess fat before serving.", "structured": {"action": "REST", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT15M", "total_time": "PT40M", "overnight_required": false, "yields": "20 meatballs", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Dairy-Free", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 457.79, "protein_g": 24.38, "carbohydrates_g": 11.27, "fat_g": 34.74, "saturated_fat_g": 13.7, "trans_fat_g": 0.01, "monounsaturated_fat_g": 15.42, "polyunsaturated_fat_g": 3.02, "fiber_g": 1.05, "sugar_g": 1.39, "sodium_mg": 609.18, "cholesterol_mg": 137.75, "potassium_mg": 382.45, "calcium_mg": 58.36, "iron_mg": 3.68, "magnesium_mg": 38.17, "phosphorus_mg": 240.81, "zinc_mg": 4.61, "vitamin_a_mcg": 36.88, "vitamin_c_mg": 7.2, "vitamin_d_mcg": 0.38, "vitamin_e_mg": 1.01, "vitamin_k_mcg": 69.31, "vitamin_b6_mg": 0.26, "vitamin_b12_mcg": 3, "thiamin_mg": 0.17, "riboflavin_mg": 0.34, "niacin_mg": 7.63, "folate_mcg": 36.8, "water_g": 100.71, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container.", "duration": "P3D"}, "freezer": {"notes": "Freeze raw or cooked. If raw, flash freeze on a tray before bagging.", "duration": "P3M"}, "reheating": "Reheat in a 175\u00b0C oven for 10-15 minutes or simmer in sauce until hot.", "does_not_keep": false}', '[{"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Large skillet or frying pan", "required": true, "alternative": "Baking sheet"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Box grater", "required": false, "alternative": "Knife (for fine dicing)"}]', '[{"symptom": "Meatballs are falling apart in the pan", "likely_cause": "Mixture was too dry or handled too roughly before a crust formed", "prevention": "Ensure the egg and breadcrumbs are fully incorporated and let meatballs sear undisturbed for 1-2 minutes before turning", "fix": "Bake them in the oven at 200\u00b0C (400\u00b0F) for 15 minutes instead of flipping them in the pan"}]', '["Grating the onion instead of chopping it allows it to melt into the meat, providing moisture and preventing raw onion crunch in the quick-cooking meatball.", "For a gluten-free version, substitute the panko with almond flour or crushed gluten-free crackers.", "Serve these with a cool cucumber yogurt sauce (tzatziki) and warm pita bread to balance the richness of the lamb.", "If the mixture feels too sticky to roll, wet your hands with cold water or a little oil."]', '"These meatballs are inspired by Middle Eastern ''Kofta'' traditions, where ground meat is heavily spiced with cumin and herbs. Lamb is the preferred protein in many of these regions due to its rich flavor and prevalence in local agriculture."', 457.79);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('09ad606c-794a-42ce-a5f5-f4ed60d53e2a', 'Duck Confit and Wild Mushroom Pappardelle', 'Silky ribbons of egg pasta tossed in a luxurious ragu of tender shredded duck leg and earthy wild mushrooms. The sauce is emulsified with duck fat, white wine, and a touch of cream for a decadent finish.', 'dinner', 'Italian', 'Intermediate', '["italian", "pastas", "duck", "pappardelle", "wild mushrooms", "dinner", "main course", "date night"]', '[{"group_name": "Duck and Mushrooms", "items": [{"name": "duck confit legs", "quantity": 2, "unit": null, "preparation": "cooked", "notes": "approximately 450-500g total weight before cleaning", "substitutions": [], "ingredient_id": "5525ed3e-a663-4b6c-beee-5c2a1c7b0558", "nutrition_source": "Aggregated Public Data"}, {"name": "mixed wild mushrooms", "quantity": 300, "unit": "g", "preparation": "cleaned and sliced", "notes": "chanterelle, porcini, oyster, or shiitake", "substitutions": [], "ingredient_id": "59d83971-a3c1-4b9c-b949-625005657048", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics and Sauce", "items": [{"name": "shallots", "quantity": 2, "unit": null, "preparation": "finely diced", "notes": "approx. 60g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx. 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 4, "unit": null, "preparation": "whole sprigs", "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "dry white wine", "quantity": 120, "unit": "ml", "preparation": null, "notes": "Pinot Grigio or Sauvignon Blanc", "substitutions": [], "ingredient_id": "5e1efe68-ff2d-432c-9239-ff83f37c5e07", "nutrition_source": "Aggregated Public Data"}, {"name": "chicken stock", "quantity": 250, "unit": "ml", "preparation": null, "notes": "preferably low-sodium", "substitutions": [], "ingredient_id": "ba5595e6-e708-4989-9687-6837b15f9b83", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0568a393-d5cb-461f-97b5-66e29fdcbc79", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Pasta and Finish", "items": [{"name": "dried pappardelle pasta", "quantity": 350, "unit": "g", "preparation": null, "notes": null, "substitutions": ["fresh tagliatelle", "fettuccine"], "ingredient_id": "52cdfe63-4362-4d80-9ed0-9fc7041f2721", "nutrition_source": "USDA FoodData Central"}, {"name": "parmigiano reggiano", "quantity": 40, "unit": "g", "preparation": "freshly grated", "notes": null, "substitutions": [], "ingredient_id": "75aede38-b00a-4383-9000-06b67134eb61", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the duck: Remove the skin and bones from the confit legs. Shred the meat into bite-sized pieces. Reserve 1 tablespoon (approx 15ml) of the rendered duck fat surrounding the legs for cooking. Crisping the skin separately for garnish is optional but recommended.", "structured": {"action": "SHRED", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Bring a large pot of salted water to a boil for the pasta.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat the reserved duck fat in a large saut\u00e9 pan over medium-high heat. Add the sliced mushrooms and saut\u00e9 until golden brown and their moisture has evaporated, about 5-7 minutes. Do not crowd the pan.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Golden brown edges", "tactile": "Tender but not mushy"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Reduce heat to medium. Add the butter, shallots, garlic, and thyme sprigs to the mushrooms. Saut\u00e9 for 2-3 minutes until the shallots are translucent and aromatic.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Deglaze the pan with white wine, scraping up any fond (browned bits) from the bottom. Let the wine reduce by half, approximately 2 minutes.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Add the chicken stock and shredded duck meat. Bring to a simmer and let cook for 5 minutes to meld flavors. If using heavy cream, stir it in now and simmer for 1 additional minute.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT6M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Cook the pappardelle in the boiling water until just shy of al dente (usually 1-2 minutes less than package instructions). Reserve 120ml (1/2 cup) of starchy pasta water.", "structured": {"action": "BOIL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Transfer the pasta directly into the saut\u00e9 pan with the sauce using tongs. Add half the reserved pasta water. Increase heat to high and toss vigorously for 1-2 minutes until the sauce emulsifies and coats the noodles efficiently. Add more pasta water if the sauce looks dry.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Glossy sauce clinging to pasta", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove from heat. Discard thyme stems. Stir in the grated parmesan and parsley. Season with black pepper. Taste before adding salt, as the duck and cheese are already salty.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT10M", "total_time": "PT40M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 380}', '{"flags": ["Nut-Free", "Soy-Free"], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 641.33, "protein_g": 46.27, "carbohydrates_g": 35.61, "fat_g": 32.97, "saturated_fat_g": 4.53, "trans_fat_g": null, "monounsaturated_fat_g": 2.4, "polyunsaturated_fat_g": 1.05, "fiber_g": 2.96, "sugar_g": 3.99, "sodium_mg": 743.55, "cholesterol_mg": 54, "potassium_mg": 600.28, "calcium_mg": 182.5, "iron_mg": 13.97, "magnesium_mg": 43.83, "phosphorus_mg": 301.53, "zinc_mg": 2.46, "vitamin_a_mcg": 221.18, "vitamin_c_mg": 10.95, "vitamin_d_mcg": 3.83, "vitamin_e_mg": 0.22, "vitamin_k_mcg": 62.64, "vitamin_b6_mg": 0.24, "vitamin_b12_mcg": 0.21, "thiamin_mg": 0.23, "riboflavin_mg": 0.32, "niacin_mg": 2.93, "folate_mcg": 58.47, "water_g": 146.79, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. The sauce may separate upon reheating.", "duration": "P3D"}, "freezer": {"notes": "Not recommended as the cream sauce may split and pasta texture will degrade.", "duration": null}, "reheating": "Gently reheat in a pan with a splash of water or stock to re-emulsify the sauce.", "does_not_keep": false}', '[{"name": "Large stockpot", "required": true, "alternative": null}, {"name": "Large saut\u00e9 pan or skillet", "required": true, "alternative": "Dutch oven"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "Sauce is oily or separated", "likely_cause": "Broken emulsion from too much fat or insufficient agitation", "prevention": "Ensure you add starchy pasta water and toss vigorously at high heat", "fix": "Add a splash of hot water and toss the pasta rapidly to re-emulsify the fat and liquid"}, {"symptom": "Dish is too salty", "likely_cause": "Duck confit is inherently salty and additional salt was added too early", "prevention": "Taste the duck before cooking; do not salt the sauce until the very end", "fix": "Add a splash of unsalted cream or a squeeze of lemon juice to cut the saltiness"}]', '["Duck confit is very salty. Be extremely conservative with added salt until the final tasting step.", "For extra texture, fry the reserved duck skin in a separate small pan until crisp, chop it, and sprinkle over the finished dish as ''duck cracklings''.", "If you cannot find fresh wild mushrooms, rehydrate 30g of dried porcini mushrooms in hot water, chop them, and add them (along with their strained soaking liquid) to the sauce.", "The ''mantecatura'' step (tossing pasta with sauce, cheese, and water) is vital. It turns separate oily ingredients into a creamy, cohesive glaze."]', '"This dish draws inspiration from the rustic cooking of Northern Italy, specifically Veneto and Tuscany, where game birds and forest mushrooms are staples. While traditional rag\u00f9 often uses minced meat and tomato, this ''rag\u00f9 bianco'' (white ragu) highlights the delicate flavor of the duck and the earthiness of the mushrooms without masking them."', 641.33);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('09cf69a0-4ed3-4d85-bbe6-2a384b5ac6b0', 'Pan-Seared Brussels Sprouts with Bacon and Pine Nuts', 'Crisp-tender Brussels sprouts deeply caramelized in rendered bacon fat, finished with smoky bacon lardons and buttery toasted pine nuts. A textural masterpiece balancing savory richness with nutty warmth.', 'side dish', 'American', 'Easy', '["bacon", "brussels sprout", "pine nut", "weeknight", "side dish", "spring", "gluten-free"]', '[{"group_name": "Main", "items": [{"name": "brussels sprouts", "quantity": 500, "unit": "g", "preparation": "trimmed and halved", "notes": "Use similar sizes for even cooking", "substitutions": [], "ingredient_id": "2ee7388c-3256-477d-8d05-4ce09df9d8f1", "nutrition_source": "USDA FoodData Central"}, {"name": "thick-cut bacon", "quantity": 150, "unit": "g", "preparation": "diced", "notes": "approx 4-6 slices", "substitutions": [], "ingredient_id": "339a356e-8f77-48fe-9293-b8e35fed3e6c", "nutrition_source": "USDA FoodData Central"}, {"name": "pine nuts", "quantity": 40, "unit": "g", "preparation": "raw", "notes": null, "substitutions": [], "ingredient_id": "971298ad-a9d7-49f7-811b-46afedad18d4", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Seasoning", "items": [{"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "Only if bacon renders insufficient fat", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, be sparing as bacon is salty", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": "freshly squeezed, to finish", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the pine nuts in a dry, cold skillet. Turn heat to medium and toast, shaking the pan frequently, until golden brown and fragrant (about 2-3 minutes). Immediately transfer to a small bowl to stop cooking.", "structured": {"action": "TOAST", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown color", "tactile": "Fragrant aroma"}}, "tips": ["Pine nuts burn in seconds; do not walk away."]}, {"step_number": 2, "phase": "cook", "text": "Return the skillet to medium heat and add the diced bacon. Cook until the fat has rendered and the bacon is crispy. Use a slotted spoon to transfer bacon to a paper towel-lined plate, leaving the rendered fat in the pan.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT6M", "doneness_cues": {"visual": "Bacon is crispy", "tactile": "Fat is liquid and clear"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Increase heat to medium-high. Ensure there is enough fat to coat the pan bottom (add olive oil if needed). Place Brussels sprouts cut-side down in a single layer. Sear undisturbed for 3-4 minutes until deeply browned.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT4M", "doneness_cues": {"visual": "Deep golden-brown sear on cut side", "tactile": null}}, "tips": ["Crowding the pan causes steaming rather than searing. Cook in batches if necessary."]}, {"step_number": 4, "phase": "cook", "text": "Stir the sprouts, reduce heat to medium-low, and cover the pan (if you don''t have a lid, use a baking sheet). Cook for another 3-5 minutes until the sprouts are tender when pierced with a knife.", "structured": {"action": "STEAM", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": "PT4M", "doneness_cues": {"visual": null, "tactile": "Tender throughout"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove the lid. Add the crispy bacon and toasted pine nuts back to the pan. Toss to combine and warm through. Season with black pepper and a small squeeze of lemon juice. Taste before adding salt, as the bacon provides significant salinity.", "structured": {"action": "SEASON", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Transfer to a serving dish immediately while hot.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 150}', '{"flags": ["Gluten-Free", "Dairy-Free", "Paleo", "Whole30", "Keto", "Low-Carb"], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 359.5, "protein_g": 19.67, "carbohydrates_g": 13.1, "fat_g": 26.4, "saturated_fat_g": 6.67, "trans_fat_g": null, "monounsaturated_fat_g": 9.93, "polyunsaturated_fat_g": 2.41, "fiber_g": 5.25, "sugar_g": 2.97, "sodium_mg": 1046.94, "cholesterol_mg": 40.13, "potassium_mg": 755.67, "calcium_mg": 59.39, "iron_mg": 2.84, "magnesium_mg": 63.36, "phosphorus_mg": 330.25, "zinc_mg": 2.38, "vitamin_a_mcg": 51.69, "vitamin_c_mg": 106.74, "vitamin_d_mcg": null, "vitamin_e_mg": 1.77, "vitamin_k_mcg": 223.96, "vitamin_b6_mg": 0.39, "vitamin_b12_mcg": 0.44, "thiamin_mg": 0.31, "riboflavin_mg": 0.21, "niacin_mg": 4.9, "folate_mcg": 77.29, "water_g": 113.38, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Texture will soften slightly upon reheating.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; sprouts will become mushy.", "duration": null}, "reheating": "Reheat in a hot skillet for 2-3 minutes to restore crispiness.", "does_not_keep": false}', '[{"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": "Cast iron skillet"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Slotted spoon", "required": true, "alternative": null}]', '[{"symptom": "Sprouts are burnt on the outside but hard inside", "likely_cause": "Heat was too high during the searing phase", "prevention": "Sear at medium-high, then significantly lower the heat and cover to finish cooking the interior", "fix": "Add 30ml of water to the pan and cover immediately to steam them quickly without further burning"}]', '["Size matters: Try to buy sprouts of uniform size so they cook at the same rate. If you have some very large ones, quarter them instead of halving.", "Pine nut freshness: Pine nuts have a high oil content and go rancid quickly. Always taste one raw before toasting; if it tastes metallic or bitter, discard the batch.", "The cut side rule: Placing the sprouts cut-side down first creates a delicious Maillard reaction surface that defines the flavor profile of this dish."]', '"While Brussels sprouts originate from cultivation near Brussels, Belgium, in the 13th century, the combination with cured pork and nuts is a modern staple in American and British cuisine. This method transforms the vegetable from the boiled, sulfurous side dish of the past into a caramelized, savory delight."', 359.5);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('0b60c3b8-31a9-4f1c-b348-dac8f1dacb69', 'Crispy Spanish Chorizo & Corn Tortilla Pizza', 'A vibrant, thin-crust style pizza utilizing a tortilla base for maximum crispness. Smoky Spanish chorizo renders its paprika-rich oil into sweet corn kernels and roasted peppers, while a blend of Manchego and mozzarella provides a savory finish. ideal for casual entertaining or game day snacking.', 'appetizer', 'Spanish', 'Easy', '["spanish", "pizza and calzones", "corn", "sausage", "tomato", "appetizer", "side", "fall", "super bowl", "quick"]', '[{"group_name": "Base & Sauce", "items": [{"name": "flour tortillas", "quantity": 2, "unit": null, "preparation": "20cm/8in diameter", "notes": "approx 40g each", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "tomato passata", "quantity": 60, "unit": "ml", "preparation": null, "notes": "or thick pizza sauce", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Toppings", "items": [{"name": "spanish chorizo", "quantity": 60, "unit": "g", "preparation": "cured, thinly sliced", "notes": null, "substitutions": [], "ingredient_id": "fb587050-625f-40a7-aef3-fda0648af061", "nutrition_source": "Aggregated Public Data"}, {"name": "corn kernels", "quantity": 50, "unit": "g", "preparation": "fresh or frozen (thawed)", "notes": null, "substitutions": [], "ingredient_id": "46ca2aab-cb23-4397-9711-528c234b2cf8", "nutrition_source": "USDA FoodData Central"}, {"name": "red bell pepper", "quantity": 50, "unit": "g", "preparation": "diced small", "notes": null, "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "USDA FoodData Central"}, {"name": "cherry tomatoes", "quantity": 6, "unit": null, "preparation": "halved", "notes": "approx 60g total", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "low-moisture mozzarella", "quantity": 80, "unit": "g", "preparation": "shredded", "notes": null, "substitutions": [], "ingredient_id": "41aca251-8bbe-492d-9539-ba0ac6c15194", "nutrition_source": "USDA FoodData Central"}, {"name": "manchego cheese", "quantity": 30, "unit": "g", "preparation": "finely grated", "notes": null, "substitutions": [], "ingredient_id": "07b8c956-5844-45ae-9de2-125008e22fc4", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh oregano", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f0596861-6e9b-4e5d-9f5d-630c54cb3eb4", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 220\u00b0C (425\u00b0F). Place a wire rack over a baking sheet.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Lightly brush both sides of the tortillas with olive oil. Place them directly on the wire rack and bake for 3 minutes just to firm up the structure before topping.", "structured": {"action": "BAKE", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT3M", "doneness_cues": {"visual": "Slightly puffed", "tactile": "Firm to the touch"}}, "tips": ["Pre-baking is critical for tortilla pizzas to prevent the sauce from making the bread soggy."]}, {"step_number": 3, "phase": "assemble", "text": "Remove tortillas from the oven. Spread a thin layer of tomato passata on each, leaving a small border. Distribute the mozzarella and Manchego evenly.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Arrange the sliced chorizo, diced peppers, corn kernels, and halved cherry tomatoes on top of the cheese. Do not overcrowd.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Return the pizzas (still on the wire rack) to the oven. Bake for 8-10 minutes until the cheese is bubbling, the chorizo is crisp, and the edges of the tortilla are golden brown.", "structured": {"action": "BAKE", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT10M", "doneness_cues": {"visual": "Golden brown edges, bubbling cheese", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove from the oven and let cool for 2 minutes. Garnish with fresh oregano leaves and slice into wedges to serve.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT10M", "total_time": "PT25M", "overnight_required": false, "yields": "2 pizzas", "yield_count": 2, "serving_size_g": 180}', '{"flags": ["Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": ["Vegans", "Vegetarians"]}', '{"per_serving": {"calories": 548.24, "protein_g": 26.2, "carbohydrates_g": 42.04, "fat_g": 31.79, "saturated_fat_g": 8.21, "trans_fat_g": 0.29, "monounsaturated_fat_g": 6.1, "polyunsaturated_fat_g": 1.26, "fiber_g": 3.36, "sugar_g": 5.85, "sodium_mg": 752.77, "cholesterol_mg": 25.6, "potassium_mg": 633.6, "calcium_mg": 425.43, "iron_mg": 2.4, "magnesium_mg": 43.85, "phosphorus_mg": 368.85, "zinc_mg": 4.11, "vitamin_a_mcg": 135.04, "vitamin_c_mg": 41.98, "vitamin_d_mcg": 0.16, "vitamin_e_mg": 1.36, "vitamin_k_mcg": 4.95, "vitamin_b6_mg": 0.15, "vitamin_b12_mcg": 0.67, "thiamin_mg": 0.12, "riboflavin_mg": 0.2, "niacin_mg": 1.24, "folate_mcg": 43.2, "water_g": 65.65, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten fresh; crust will lose crispness upon reheating.", "duration": "P2D"}, "freezer": {"notes": "Not recommended for freezing.", "duration": null}, "reheating": "Reheat in a dry skillet or 200\u00b0C oven for 3-4 minutes to recrisp the bottom.", "does_not_keep": false}', '[{"name": "Wire cooling rack", "required": true, "alternative": "Perforated pizza pan"}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Tortilla base is soggy/floppy", "likely_cause": "Too much sauce or toppings overloaded the thin base", "prevention": "Use sauce sparingly and bake on a wire rack to allow air circulation underneath", "fix": "Place in a dry skillet over medium heat for 1-2 minutes to crisp the bottom"}]', '["Using a wire rack over a baking sheet allows hot air to circulate under the tortilla, mimicking a pizza stone''s effect and ensuring a crisp bite.", "If using fresh corn, you do not need to cook it beforehand; the high oven heat will steam-roast it perfectly in 10 minutes.", "Manchego adds a distinct salty, sheep-milk tang that pairs perfectly with the sweet corn, but Parmesan can be used as a substitute.", "Be careful with salt; the chorizo and Manchego are both naturally salty, so additional seasoning is rarely needed."]', '"While pizza is Italian, the ''Coca'' is a traditional Spanish flatbread from Catalonia often topped with roasted vegetables and cured meats. This recipe bridges the gap, using the convenience of a tortilla base to highlight classic Spanish flavor combinations like chorizo and sweet peppers."', 548.24);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('0db0bab4-966f-48f4-9e8d-dda278859956', 'Tropical Avocado-Coconut Ice Cream with Meringue Nests', 'A textural masterpiece featuring crisp, airy meringue clouds topped with a velvety, dairy-free avocado and coconut ice cream. Finished with juicy ripe mango and nutty toasted coconut flakes.', 'dessert', 'Tropical Fusion', 'Intermediate', '["meringue", "mango", "coconut", "avocado", "dessert", "gluten-free", "summer", "tropical"]', '[{"group_name": "Meringue Nests", "items": [{"name": "egg whites", "quantity": 100, "unit": "g", "preparation": "room temperature", "notes": "approximately 3 large eggs", "substitutions": [], "ingredient_id": "17645f6b-c1ea-4e82-a4b4-5ae8cb6a5a53", "nutrition_source": "USDA FoodData Central"}, {"name": "superfine sugar", "quantity": 200, "unit": "g", "preparation": null, "notes": "caster sugar", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "cream of tartar", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 0.5 tsp", "substitutions": [], "ingredient_id": "7514c048-9169-45bd-9758-b153c7d8a704", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Avocado-Coconut Ice Cream", "items": [{"name": "ripe avocados", "quantity": 2, "unit": null, "preparation": "pitted and peeled", "notes": "approx 300g flesh", "substitutions": [], "ingredient_id": "35c8f26f-d008-407a-9bf3-48c8aa641729", "nutrition_source": "USDA FoodData Central"}, {"name": "coconut cream", "quantity": 400, "unit": "ml", "preparation": "chilled", "notes": "use the thick solid part from the top of the can", "substitutions": [], "ingredient_id": "af6f629b-fa13-4f67-8338-e06af8c943cc", "nutrition_source": "USDA FoodData Central"}, {"name": "agave syrup", "quantity": 120, "unit": "ml", "preparation": null, "notes": "or honey if not strict vegan", "substitutions": ["honey", "maple syrup"], "ingredient_id": "9a5605bc-1e1c-4ea4-b1be-13d3287d849f", "nutrition_source": "Aggregated Public Data"}, {"name": "lime juice", "quantity": 30, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Assembly & Garnish", "items": [{"name": "ripe mango", "quantity": 2, "unit": null, "preparation": "diced", "notes": "approx 300g flesh", "substitutions": [], "ingredient_id": "6ab51d7d-dea3-4f14-8253-76acb67bd2c8", "nutrition_source": "USDA FoodData Central"}, {"name": "coconut flakes", "quantity": 30, "unit": "g", "preparation": "toasted", "notes": null, "substitutions": [], "ingredient_id": "6ad586af-5506-4915-a909-a190e601b143", "nutrition_source": "USDA FoodData Central"}, {"name": "lime zest", "quantity": 1, "unit": null, "preparation": null, "notes": "for garnish", "substitutions": [], "ingredient_id": "d3d2677e-fe02-4404-add0-29d73df7e921", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 100\u00b0C/212\u00b0F. Line a baking sheet with parchment paper. Clean your mixing bowl thoroughly with lemon juice or vinegar to remove any grease.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a stand mixer, whisk egg whites on medium speed until foamy. Add cream of tartar and increase speed to medium-high until soft peaks form.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": {"visual": "Soft peaks form and hold shape momentarily", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Gradually add sugar, one tablespoon at a time, while continuing to whisk. Once all sugar is added, whisk on high for 5-7 minutes until the meringue is glossy, stiff, and no sugar grains are felt when rubbed between fingers.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Glossy stiff peaks", "tactile": "Smooth texture, no grit"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Spoon or pipe the meringue into 6 equal mounds on the baking sheet. Use the back of a spoon to create a depression in the center of each mound (nest shape).", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Bake for 90 minutes at 100\u00b0C/212\u00b0F. The meringues should be crisp and dry on the outside but not browned. Turn off the oven and let them cool completely inside with the door slightly ajar.", "structured": {"action": "BAKE", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT1H30M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "While meringues bake, prepare the ice cream base. Blend the avocado flesh, lime juice, agave syrup, vanilla, and salt in a blender until perfectly smooth and vibrant green.", "structured": {"action": "BLEND", "temperature": null, "duration": null, "doneness_cues": {"visual": "Uniform green color, no lumps", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "prep", "text": "In a separate bowl, whip the chilled coconut cream (solids only) until aerated and fluffy. Gently fold the avocado puree into the whipped coconut cream until combined. Do not overmix.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Pour the mixture into a loaf pan, cover surface directly with plastic wrap to prevent ice crystals, and freeze for at least 4 hours.", "structured": {"action": "FREEZE", "temperature": null, "duration": "PT4H", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "prep", "text": "Toast the coconut flakes in a dry pan over medium heat for 2-3 minutes, stirring constantly until golden brown. Immediately transfer to a plate to stop cooking.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown edges", "tactile": "Crisp"}}, "tips": []}, {"step_number": 10, "phase": "assemble", "text": "To serve, place a meringue nest on a plate. Scoop a generous ball of avocado ice cream into the center. Top with diced mango, toasted coconut flakes, and fresh lime zest.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT5H30M", "total_time": "PT6H15M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 220}', '{"flags": ["Gluten-Free", "Vegetarian", "Dairy-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 536.59, "protein_g": 5.98, "carbohydrates_g": 67.45, "fat_g": 30.09, "saturated_fat_g": 22.96, "trans_fat_g": null, "monounsaturated_fat_g": 3.88, "polyunsaturated_fat_g": 1.15, "fiber_g": 5.38, "sugar_g": 55.25, "sodium_mg": 98.94, "cholesterol_mg": null, "potassium_mg": 591.11, "calcium_mg": 21.41, "iron_mg": 1.86, "magnesium_mg": 40.72, "phosphorus_mg": 117.13, "zinc_mg": 0.99, "vitamin_a_mcg": 32.22, "vitamin_c_mg": 33.92, "vitamin_d_mcg": null, "vitamin_e_mg": 1.79, "vitamin_k_mcg": 2.14, "vitamin_b6_mg": 0.15, "vitamin_b12_mcg": 0.02, "thiamin_mg": 0.05, "riboflavin_mg": 0.13, "niacin_mg": 1.31, "folate_mcg": 55.92, "water_g": 138.61, "alcohol_g": 0.29, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Assembled dish must be eaten immediately.", "duration": null}, "freezer": {"notes": "Ice cream keeps for 2 weeks tightly sealed; let soften before serving.", "duration": "P2W"}, "reheating": null, "does_not_keep": false}', '[{"name": "Stand mixer or electric hand whisk", "required": true, "alternative": "Balloon whisk and strong arm"}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Blender or food processor", "required": true, "alternative": null}, {"name": "Loaf pan or freezer-safe container", "required": true, "alternative": null}]', '[{"symptom": "Meringues are chewy or sticky", "likely_cause": "High humidity or removed from oven too early", "prevention": "Bake longer at low temp; cool completely in the oven to dry out", "fix": "Return to oven at 90\u00b0C/195\u00b0F for 30 minutes"}, {"symptom": "Ice cream is icy/hard", "likely_cause": "Water content too high or not enough fat", "prevention": "Ensure you use only the solid part of the coconut cream can", "fix": "Let sit at room temperature for 10-15 minutes before scooping"}, {"symptom": "Avocado mixture turned brown", "likely_cause": "Oxidation due to exposure to air", "prevention": "Ensure lime juice is thoroughly blended in immediately after cutting avocado", "fix": "Scrape off the top oxidized layer; the underneath should still be green"}]', '["Ensure your mixing bowl is absolutely free of fat or yolk before whipping egg whites, or they will never reach stiff peaks.", "For the coconut cream, chill the can in the fridge overnight. Flip it upside down before opening; pour off the liquid water (save for smoothies) and scoop out the hardened cream.", "The lime juice in the ice cream is functional as well as flavorful\u2014it prevents the avocado from oxidizing and turning brown.", "If the mango is very tart, you can macerate it in a teaspoon of sugar for 10 minutes before serving to balance the acidity."]', '"This dish is a tropical reimagining of the classic Eton Mess or Pavlova. While the original Pavlova is a subject of debate between Australia and New Zealand named after ballerina Anna Pavlova, this version incorporates Southeast Asian staples like coconut and mango for a lighter, dairy-free variation suitable for warm climates."', 536.59);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('0e7c863a-c7e5-41c2-91fe-f6e9a989fd4c', 'Roasted Tomato and Arbol Chili Salsa', 'A smoky, deep red salsa with a fiery kick. The char from roasted tomatoes and onions balances the sharp heat of toasted dried chilies, creating a rustic texture that coats chips perfectly.', 'condiment', 'Mexican', 'Easy', '["spanish", "condiments", "chili pepper", "garlic", "tomato", "appetizer", "spring", "mexican", "vegan", "dip", "roast"]', '[{"group_name": "Vegetables", "items": [{"name": "roma tomatoes", "quantity": 500, "unit": "g", "preparation": "whole", "notes": "approx. 4-5 medium tomatoes", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "white onion", "quantity": 100, "unit": "g", "preparation": "peeled and quartered", "notes": "approx. 1/2 medium onion", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "peeled", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Chilies & Seasoning", "items": [{"name": "dried chile de \u00e1rbol", "quantity": 5, "unit": null, "preparation": null, "notes": "approx. 3g; use 3 for mild, 10 for very hot", "substitutions": [], "ingredient_id": "83e9c1e8-cede-46e5-97e4-6cf9665ecf60", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "warm water", "quantity": 60, "unit": "ml", "preparation": null, "notes": "for soaking chilies", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh cilantro", "quantity": 10, "unit": "g", "preparation": "roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Wipe the dried chilies clean with a damp cloth and remove the stems. Shake out excess seeds if you prefer less heat.", "structured": {"action": "PREP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat a dry skillet over medium heat. Toast the dried chilies for 30-60 seconds, turning constantly, until they darken slightly and become fragrant. Do not burn them or they will taste bitter.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Darkened slightly", "tactile": "Crisp"}}, "tips": ["Ventilation is recommended as chili fumes can be irritating."]}, {"step_number": 3, "phase": "prep", "text": "Place the toasted chilies in a small bowl and cover with the warm water. Let them soak for 10-15 minutes to soften while you cook the vegetables.", "structured": {"action": "SOAK", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "In the same hot skillet, place the tomatoes, onion quarters, and garlic cloves. Roast the vegetables, turning occasionally. Remove garlic early (approx. 5 mins) to prevent burning, remove onions when softened and charred (approx. 10 mins), and roast tomatoes until blistered and soft (12-15 mins).", "structured": {"action": "ROAST", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": "Blackened spots on skin", "tactile": "Tomatoes soft to the touch"}}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Transfer the soaked chilies (and 1 tablespoon of the soaking liquid), roasted garlic, and salt to a blender. Blend on high until a smooth paste forms.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Add the roasted tomatoes (skin on) and onions to the blender. Pulse 4-6 times to combine while maintaining a chunky, rustic texture. Stir in chopped cilantro if using.", "structured": {"action": "PULSE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Chunky consistency", "tactile": null}}, "tips": ["If the salsa is too thick, add more water or tomato juice 1 tablespoon at a time."]}]', '{"active_time": "PT20M", "passive_time": "PT15M", "total_time": "PT35M", "overnight_required": false, "yields": "500ml", "yield_count": 16, "serving_size_g": 30}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Paleo", "Whole30", "Keto", "Low-Carb", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 10.07, "protein_g": 0.43, "carbohydrates_g": 2.13, "fat_g": 0.11, "saturated_fat_g": 0.02, "trans_fat_g": null, "monounsaturated_fat_g": null, "polyunsaturated_fat_g": null, "fiber_g": 0.74, "sugar_g": 1.5, "sodium_mg": 125.63, "cholesterol_mg": null, "potassium_mg": 93.25, "calcium_mg": 6.63, "iron_mg": 0.14, "magnesium_mg": 4.29, "phosphorus_mg": 11.02, "zinc_mg": 0.07, "vitamin_a_mcg": 12.65, "vitamin_c_mg": 5.09, "vitamin_d_mcg": null, "vitamin_e_mg": null, "vitamin_k_mcg": 0.04, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": null, "thiamin_mg": null, "riboflavin_mg": null, "niacin_mg": 0.01, "folate_mcg": 1.21, "water_g": 9.76, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight jar. Flavor improves after 24 hours.", "duration": "P1W"}, "freezer": {"notes": "Texture may become slightly watery upon thawing.", "duration": "P3M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Cast iron skillet or comal", "required": true, "alternative": "Heavy-bottomed frying pan or baking sheet"}, {"name": "Blender or Food Processor", "required": true, "alternative": "Molcajete (mortar and pestle)"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Small bowl", "required": true, "alternative": null}]', '[{"symptom": "Salsa tastes bitter", "likely_cause": "Chilies or garlic were burned during toasting/roasting", "prevention": "Watch chilies constantly and toast only for seconds; remove garlic before onions and tomatoes.", "fix": "Add a pinch of sugar or a splash of lime juice to mask the bitterness."}, {"symptom": "Salsa is too spicy", "likely_cause": "Too many seeds left in the Arbol chilies", "prevention": "Remove veins and seeds thoroughly before toasting.", "fix": "Roast 2 more tomatoes and blend them in to dilute the heat."}]', '["Leaving the blackened skins on the tomatoes is essential for the authentic ''tatemada'' (roasted) flavor profile.", "For a more traditional texture, use a Molcajete (volcanic stone mortar). Grind the salt, garlic, and chilies first, then mash in the onions and tomatoes.", "This salsa pairs exceptionally well with fatty meats like carnitas or barbacoa because the acidity cuts through the richness.", "Arbol chilies are potent; start with fewer if you have a low heat tolerance and add more gradually."]', '"Salsa Roja is a cornerstone of Mexican table condiments. This version mimics ''Salsa Tatemada'', where ingredients are roasted on a comal (griddle) to impart a smoky sweetness that boiling cannot achieve. It is ubiquitous in taquerias across Mexico."', 10.07);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('0f32c872-d955-4896-8da4-6eb291131fe9', 'Brioche-Crusted Brassica Gratin with Bright Salad', 'A comforting yet refined main course featuring tender broccoli and cauliflower enrobed in a sharp cheddar Mornay sauce. The dish is topped with cubes of buttery brioche that bake into a golden, crisp crust, contrasting perfectly with a cold, tangy side salad of crisp lettuce to cut through the richness.', 'main course', 'Modern French', 'Intermediate', '["bake", "broccoli", "cauliflower", "cheese", "brioche", "main course", "vegetable", "winter warmer"]', '[{"group_name": "Vegetable Base", "items": [{"name": "broccoli florets", "quantity": 300, "unit": "g", "preparation": "cut into bite-sized pieces", "notes": null, "substitutions": [], "ingredient_id": "b0a26615-a0a7-4b5c-9143-e9becf53b41a", "nutrition_source": "USDA FoodData Central"}, {"name": "cauliflower florets", "quantity": 300, "unit": "g", "preparation": "cut into bite-sized pieces", "notes": null, "substitutions": [], "ingredient_id": "2d9d5068-77e7-4dfc-b24b-8e6a6275cb33", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 2000, "unit": "ml", "preparation": null, "notes": "for blanching", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": null}, {"name": "salt", "quantity": 15, "unit": "g", "preparation": null, "notes": "for blanching water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Mornay Sauce", "items": [{"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 45, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 500, "unit": "ml", "preparation": "warmed", "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "sharp white cheddar cheese", "quantity": 150, "unit": "g", "preparation": "freshly grated", "notes": null, "substitutions": [], "ingredient_id": "6cc08e49-8e1b-4065-be23-f57782560a8b", "nutrition_source": "Aggregated Public Data"}, {"name": "dijon mustard", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "nutmeg", "quantity": 1, "unit": "g", "preparation": "ground", "notes": "small pinch", "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Brioche Topping", "items": [{"name": "brioche loaf", "quantity": 150, "unit": "g", "preparation": "cut into 2cm cubes", "notes": "preferably slightly stale", "substitutions": [], "ingredient_id": "b6c47adf-1713-4ed4-8222-436318619746", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 20, "unit": "g", "preparation": "melted", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Salad & Tangy Dressing", "items": [{"name": "gem lettuce heads", "quantity": 2, "unit": null, "preparation": null, "notes": "approx 250g total, leaves separated and washed", "substitutions": [], "ingredient_id": "312b8da7-52bd-406b-89d2-0853c0e37faa", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "036c7254-3de5-4c6e-a2e7-366ad4d05077", "nutrition_source": "Aggregated Public Data"}, {"name": "apple cider vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "wholegrain mustard", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a60cae45-41bd-42f4-b2e3-f280bc62bba1", "nutrition_source": "Aggregated Public Data"}, {"name": "honey", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 200\u00b0C (400\u00b0F). Bring a large pot of salted water to a rolling boil.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Blanch the broccoli and cauliflower florets in the boiling water for 3-4 minutes until vividly bright and slightly tender, but still firm (al dente). Drain thoroughly in a colander.", "structured": {"action": "BLANCH", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Bright vivid color", "tactile": "Knife pierces with slight resistance"}}, "tips": ["Do not overcook the vegetables at this stage, or they will turn to mush in the oven."]}, {"step_number": 3, "phase": "cook", "text": "In a medium saucepan over medium heat, melt the 45g of butter. Whisk in the flour and cook for 2 minutes until bubbly and pale (blonde roux) to cook out the raw flour taste.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Gradually whisk in the warmed milk, a splash at a time, ensuring the mixture is smooth before adding more. Simmer gently for 5 minutes until thickened.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Coats the back of a spoon (nappe consistency)", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Remove the sauce from heat. Stir in the grated cheddar, Dijon mustard, nutmeg, and black pepper until the cheese is fully melted and the sauce is glossy. Taste and adjust salt if needed.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Combine the drained vegetables and cheese sauce in the baking dish, tossing gently to coat. Scatter the cubed brioche over the top. Drizzle the brioche with the 20g of melted butter.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Bake on the middle rack for 20-25 minutes, until the sauce is bubbling at the edges and the brioche topping is deep golden brown and crisp.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT25M", "doneness_cues": {"visual": "Golden brown crust, bubbling sauce", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "While the bake finishes, whisk together the olive oil, apple cider vinegar, lemon juice, wholegrain mustard, and honey in a small bowl to make the dressing. Just before serving, toss the lettuce leaves with the dressing.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Serve the hot bake immediately with the cold, dressed salad on the side.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT25M", "total_time": "PT1H", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 380}', '{"flags": ["Vegetarian"], "not_suitable_for": ["Vegans (Dairy/Eggs)", "Celiacs (Gluten)"]}', '{"per_serving": {"calories": 687.33, "protein_g": 21.36, "carbohydrates_g": 38.67, "fat_g": 47.41, "saturated_fat_g": 19.88, "trans_fat_g": null, "monounsaturated_fat_g": 4.89, "polyunsaturated_fat_g": 0.99, "fiber_g": 5.81, "sugar_g": 13.13, "sodium_mg": 2083.61, "cholesterol_mg": 47.44, "potassium_mg": 846.43, "calcium_mg": 509.56, "iron_mg": 3.04, "magnesium_mg": 63.08, "phosphorus_mg": 406.42, "zinc_mg": 2.62, "vitamin_a_mcg": 563.92, "vitamin_c_mg": 106.53, "vitamin_d_mcg": 1.63, "vitamin_e_mg": 1.21, "vitamin_k_mcg": 154.24, "vitamin_b6_mg": 0.37, "vitamin_b12_mcg": 0.59, "thiamin_mg": 0.21, "riboflavin_mg": 0.4, "niacin_mg": 1.33, "folate_mcg": 185.46, "water_g": 315.4, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store salad and bake separately. Brioche topping may lose crispness; reheat in oven to restore texture.", "duration": "P3D"}, "freezer": {"notes": "Bake freezes well without the salad. Thaw overnight before reheating.", "duration": "P1M"}, "reheating": "Reheat bake in a 180\u00b0C oven for 15-20 minutes until heated through. Do not microwave if possible to preserve brioche texture.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": "Dutch oven"}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Medium saucepan", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Baking dish (approx 20x30cm)", "required": true, "alternative": "Casserole dish"}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Cheese sauce is grainy or oily", "likely_cause": "The sauce was boiled after adding the cheese, causing the proteins to tighten and fat to separate", "prevention": "Always remove the white sauce from heat before stirring in the cheese", "fix": "Whisk in a tablespoon of cold heavy cream or use an immersion blender to re-emulsify"}]', '["Dry your vegetables thoroughly after blanching. Excess water trapped in the broccoli florets will water down your cheese sauce.", "If your brioche is very fresh, leave the cubes on a tray on the counter for an hour to dry out, or toast them in the oven for 5 minutes before assembling. This ensures a crunchier topping.", "For the dressing, the high acidity is intentional. It acts as a palate cleanser to cut through the heavy fats of the cheese and brioche.", "Use block cheese and grate it yourself. Pre-grated cheese contains starch/cellulose preventing it from melting smoothly."]', '"This dish is a modern intersection of the French ''Gratin de Chou-fleur'' and the savory bread pudding concept. While gratins became a staple of French home cooking in the 19th century, the use of enriched brioche as a crust introduces a distinct Viennoiserie element, elevating a humble vegetable side into a substantial main course."', 687.33);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('0f59eb7f-4818-46c0-8ede-02cfb911d5d0', 'Spicy Red Lentil & Prosciutto Spaghettini', 'A rustic, protein-rich pasta dish where quick-cooking red lentils dissolve into a creamy, dairy-free ragù. Crispy prosciutto adds a savory crunch that contrasts with the tender spaghettini and the gentle heat of chili flakes.', 'dinner', 'Italian', 'Easy', '["italian", "pastas", "prosciutto", "red lentil", "spaghettini", "dinner", "weeknight", "dairy-free", "low cholesterol", "low-fat", "nut-free"]', '[{"group_name": "Base & Aromatics", "items": [{"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": "extra virgin", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "prosciutto", "quantity": 60, "unit": "g", "preparation": "thinly sliced, chopped", "notes": null, "substitutions": [], "ingredient_id": "6b3bd037-dea6-4a87-85dc-3b889880b65c", "nutrition_source": "Aggregated Public Data"}, {"name": "onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx. 100g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "carrot", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx. 70g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "celery stalk", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx. 50g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Lentil Sauce", "items": [{"name": "red lentils", "quantity": 150, "unit": "g", "preparation": "dried, rinsed", "notes": "split red lentils", "substitutions": [], "ingredient_id": "db2f5833-ac09-4e83-bb3d-10ef9d89f945", "nutrition_source": "Aggregated Public Data"}, {"name": "tomato paste", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "41400e7f-7a06-42d2-a625-072c380d60b2", "nutrition_source": "Aggregated Public Data"}, {"name": "crushed tomatoes", "quantity": 400, "unit": "g", "preparation": "canned", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable stock", "quantity": 500, "unit": "ml", "preparation": "low sodium", "notes": null, "substitutions": ["chicken stock", "water"], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "red chili flakes", "quantity": 2, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pasta & Finish", "items": [{"name": "spaghettini", "quantity": 320, "unit": "g", "preparation": null, "notes": "thin spaghetti", "substitutions": [], "ingredient_id": "3994b041-8c11-4992-adf0-a373b17e1aee", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "for pasta water and seasoning", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": null, "unit": null, "preparation": null, "notes": "from half a lemon", "substitutions": [], "ingredient_id": "03fb65be-9b62-44e7-a121-694de64cdec0", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Heat olive oil in a large Dutch oven over medium heat. Add the chopped prosciutto and cook until rendered and crispy, about 3-4 minutes. Remove half of the crispy prosciutto with a slotted spoon and set aside for garnish.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add the diced onion, carrot, and celery to the pot with the remaining prosciutto fat. Saut\u00e9 for 5-7 minutes until the vegetables are softened and the onion is translucent.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Onions are translucent", "tactile": "Vegetables are soft"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Stir in the minced garlic, tomato paste, red chili flakes, and dried oregano. Cook for 1 minute until fragrant and the tomato paste darkens slightly.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the rinsed red lentils, crushed tomatoes, and vegetable stock. Bring to a boil, then reduce heat to low and cover. Simmer for 15-20 minutes until the lentils are completely tender and have started to break down into a thick sauce.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT20M", "doneness_cues": {"visual": "Lentils are disintegrated", "tactile": "Thick porridge-like consistency"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "While the sauce simmers, bring a large pot of salted water to a boil. Add spaghettini and cook according to package directions until al dente (usually 1-2 minutes less than standard spaghetti). Reserve 120ml (approx. 1/2 cup) of pasta water before draining.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Add the drained spaghettini directly to the lentil sauce. Toss vigorously, adding the reserved pasta water a splash at a time, until the sauce coats the noodles silkenly. Taste and season with salt if needed.", "structured": {"action": "MIX", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Pasta is fully coated and glossy", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Serve immediately topped with the reserved crispy prosciutto, fresh chopped parsley, and optional lemon zest for brightness.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT20M", "total_time": "PT40M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 380}', '{"flags": ["Dairy-Free", "Nut-Free", "Egg-Free"], "not_suitable_for": ["Vegetarians (contains prosciutto)", "Vegans (contains prosciutto)"]}', '{"per_serving": {"calories": 307.03, "protein_g": 17.14, "carbohydrates_g": 45.71, "fat_g": 6.88, "saturated_fat_g": 1.23, "trans_fat_g": null, "monounsaturated_fat_g": 2.8, "polyunsaturated_fat_g": 0.56, "fiber_g": 8.41, "sugar_g": 8.37, "sodium_mg": 1008.06, "cholesterol_mg": null, "potassium_mg": 777.24, "calcium_mg": 62.17, "iron_mg": 3.24, "magnesium_mg": 50.3, "phosphorus_mg": 100.88, "zinc_mg": 0.82, "vitamin_a_mcg": 206.08, "vitamin_c_mg": 23.72, "vitamin_d_mcg": null, "vitamin_e_mg": 1, "vitamin_k_mcg": 53.02, "vitamin_b6_mg": 0.17, "vitamin_b12_mcg": null, "thiamin_mg": 0.28, "riboflavin_mg": 0.17, "niacin_mg": 1.85, "folate_mcg": 83.39, "water_g": 106.98, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Sauce thickens significantly; loosen with a splash of water when reheating.", "duration": "P3D"}, "freezer": {"notes": "Freeze sauce only; pasta is best cooked fresh.", "duration": "P2M"}, "reheating": "Reheat in a pan over medium heat with a splash of water or stock to restore consistency.", "does_not_keep": false}', '[{"name": "Large Dutch oven or heavy-bottomed pot", "required": true, "alternative": null}, {"name": "Large pot", "required": true, "alternative": "Stockpot for boiling pasta"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Sauce is too thick or dry", "likely_cause": "Lentils absorbed too much liquid or heat was too high", "prevention": "Keep the lid on while simmering; check liquid levels halfway through", "fix": "Stir in extra water or stock 50ml at a time until desired consistency is reached"}, {"symptom": "Lentils are crunchy", "likely_cause": "Undercooked or acidic ingredients (tomatoes) added before lentils softened (though red lentils are usually resilient)", "prevention": "Ensure lentils are simmering gently; extend cook time", "fix": "Add a splash of water and continue simmering for 5-10 minutes before adding pasta"}]', '["Red lentils are chosen specifically because they decorticate (break down) during cooking, creating a creamy mouthfeel without the need for dairy or heavy fats.", "Prosciutto is naturally salty. Be conservative when salting the sauce; taste it only after the lentils have cooked and the prosciutto flavor has melded.", "Spaghettini cooks faster than standard spaghetti. Watch it closely\u2014mushy pasta disappears into the thick lentil sauce, so al dente texture is crucial for contrast.", "If you prefer a smoother sauce closer to a traditional bolognese texture, you can use an immersion blender on the sauce before adding the pasta.", "The lemon zest at the end is technically optional but highly recommended to cut through the earthiness of the lentils."]', '"While lentils (lenticchie) are a staple in Italian cooking, often associated with New Year''s luck and abundance, pairing them with pasta in a rag\u00f9 style is a modern, health-conscious adaptation of peasant cooking (cucina povera). This dish bridges the gap between hearty legume stews and refined pasta courses."', 307.03);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('11115fa2-cad1-4e33-88e3-e480b038cfdc', 'Vibrant Herb & Caper Avocado Salad', 'A luscious interplay of creamy avocado and briny capers, brightened by a sharp red wine vinegar dressing. Fresh cilantro and parsley add herbaceous depth, while red onion provides a necessary crunch to cut through the richness.', 'salad', 'Mediterranean', 'Easy', '["avocado", "caper", "cilantro", "parsley", "red wine vinegar", "salad", "weeknight", "appetizer"]', '[{"group_name": "Vegetables", "items": [{"name": "avocados", "quantity": 3, "unit": null, "preparation": "ripe but firm", "notes": "approx. 600g flesh total", "substitutions": [], "ingredient_id": "35c8f26f-d008-407a-9bf3-48c8aa641729", "nutrition_source": "USDA FoodData Central"}, {"name": "english cucumber", "quantity": 200, "unit": "g", "preparation": "diced", "notes": null, "substitutions": [], "ingredient_id": "457adec2-3e06-4efe-a26e-9e6ea9f84924", "nutrition_source": "USDA FoodData Central"}, {"name": "red onion", "quantity": 60, "unit": "g", "preparation": "finely sliced", "notes": null, "substitutions": [], "ingredient_id": "1c270c6e-0acc-4c5c-9935-7eff3240fc4a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Dressing & Aromatics", "items": [{"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "red wine vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "9e1b7e74-fdcb-4836-8349-4f7ad86d62df", "nutrition_source": "USDA FoodData Central"}, {"name": "capers", "quantity": 30, "unit": "g", "preparation": "drained and roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "e7301d2c-b906-4ef8-917e-787be0b25880", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 15, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "grated or minced", "notes": "approx. 4g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a large mixing bowl, whisk together the red wine vinegar, grated garlic, and salt until the salt dissolves. Add the sliced red onion and toss to coat.", "structured": {"action": "MIX", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": ["Macerating the onions in vinegar first removes their harsh raw bite and turns them a vibrant pink."]}, {"step_number": 2, "phase": "prep", "text": "Let the onion mixture sit for 5 minutes, then whisk in the extra virgin olive oil until emulsified.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "While onions rest, chop the parsley, cilantro, and capers. Dice the cucumber into 1cm cubes.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Halve, pit, and peel the avocados. Cut them into 2cm chunks. Do this last to minimize oxidation.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Add the avocado, cucumber, herbs, capers, and black pepper to the bowl with the dressing. Gently fold everything together using a spatula or spoon to coat without mashing the avocado.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Be gentle; you want distinct chunks of avocado, not guacamole."]}, {"step_number": 6, "phase": "finish", "text": "Taste and adjust seasoning with more salt or vinegar if needed. Serve immediately.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT5M", "total_time": "PT20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 220}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Low-Carb", "Keto", "Paleo", "Whole30", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 333.58, "protein_g": 4.3, "carbohydrates_g": 16.2, "fat_g": 30.35, "saturated_fat_g": 5.06, "trans_fat_g": null, "monounsaturated_fat_g": 19.24, "polyunsaturated_fat_g": 4.14, "fiber_g": 9.46, "sugar_g": 5.21, "sodium_mg": 476.2, "cholesterol_mg": null, "potassium_mg": 682.28, "calcium_mg": 39.9, "iron_mg": 0.99, "magnesium_mg": 47.84, "phosphorus_mg": 77.45, "zinc_mg": 0.78, "vitamin_a_mcg": 105.28, "vitamin_c_mg": 33.77, "vitamin_d_mcg": null, "vitamin_e_mg": 6.26, "vitamin_k_mcg": 81, "vitamin_b6_mg": 0.16, "vitamin_b12_mcg": null, "thiamin_mg": 0.05, "riboflavin_mg": 0.11, "niacin_mg": 1.17, "folate_mcg": 63.5, "water_g": 196.43, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Avocado will brown over time; store with plastic wrap pressed directly against surface.", "duration": "P1D"}, "freezer": {"notes": "Do not freeze.", "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Small bowl", "required": false, "alternative": null}]', '[{"symptom": "Salad turned into mush/guacamole", "likely_cause": "Avocados were over-ripe or mixed too vigorously", "prevention": "Select avocados that yield slightly to pressure but aren''t squishy; fold gently", "fix": "Serve as a dip with crackers or toast instead of a salad"}]', '["The quality of olive oil matters immensely here as it is a raw dressing; choose a peppery variety to complement the herbs.", "If you find raw red onion too aggressive, the maceration step (Step 1) is crucial. You can also rinse the onions in cold water before adding to vinegar for an even milder flavor.", "For extra texture, toasted pine nuts or sunflower seeds make an excellent topping just before serving."]', '"While avocados are native to the Americas, this preparation borrows heavily from Mediterranean techniques, specifically the use of acid (vinegar/capers) to cut through fat (oil/avocado). It reflects a modern global fusion style common in California and coastal European cuisine."', 333.58);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('112aa2d8-4938-4163-95c7-d414f2bcbfc2', 'Classic Creamy Hummus', 'Velvety smooth and airy chickpea spread with rich nutty undertones from tahini and a bright kick of fresh lemon. This technique uses ice water to create a perfectly emulsified, cloud-like texture.', 'appetizer', 'Middle Eastern', 'Easy', '["middle eastern", "chickpea", "five ingredient", "hummus", "tahini", "appetizer", "vegan", "dip", "gluten-free"]', '[{"group_name": "Base", "items": [{"name": "canned chickpeas", "quantity": 425, "unit": "g", "preparation": "drained and rinsed", "notes": "1 standard can; save 30ml liquid (aquafaba) if desired, otherwise discard", "substitutions": [], "ingredient_id": "bc61d002-fe4c-464e-97fc-4323b3f26855", "nutrition_source": "Aggregated Public Data"}, {"name": "baking soda", "quantity": 3, "unit": "g", "preparation": null, "notes": "1/2 tsp; aids in softening skins for smoother texture", "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Emulsion", "items": [{"name": "tahini paste", "quantity": 120, "unit": "g", "preparation": "well-stirred", "notes": "Sesame paste; quality significantly affects flavor", "substitutions": [], "ingredient_id": "87ae6455-8e22-4c1b-bad7-89fa69c4dc57", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh lemon juice", "quantity": 60, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "peeled", "notes": "approx 5g; use 2 cloves for stronger flavor", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "ice water", "quantity": 45, "unit": "ml", "preparation": "very cold", "notes": "plus more if needed for consistency", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Garnish (Optional)", "items": [{"name": "extra virgin olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "paprika", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place drained chickpeas and baking soda in a small pot. Cover with water by 5cm and boil for 20 minutes until chickpeas are very soft and skins are falling off. Drain well.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT20M", "doneness_cues": {"visual": "Skins separating", "tactile": "Mushy when pressed"}}, "tips": ["Overcooking the chickpeas breaks down the pectin, ensuring a silky smooth dip without needing to peel them individually."]}, {"step_number": 2, "phase": "prep", "text": "While chickpeas boil, mince the garlic in the food processor. Add lemon juice and let sit for 5-10 minutes.", "structured": {"action": "MINCE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": ["Letting garlic sit in lemon juice neutralizes the sharp sulfur compounds, leaving the garlic flavor without the harsh bite."]}, {"step_number": 3, "phase": "cook", "text": "Add the tahini and salt to the lemon-garlic mixture in the food processor. Process until the mixture thickens and seizes up.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Thick, paste-like consistency", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "With the processor running, slowly drizzle in the ice water. Blend until the mixture turns pale, creamy, and aerated.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Color lightens significantly", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Add the warm chickpeas (and cumin if using) to the tahini base. Process for 3-5 minutes, scraping down sides occasionally, until ultra-smooth.", "structured": {"action": "PUREE", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "No visible graininess", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Taste and adjust salt or lemon if needed. Transfer to a serving bowl, create a swirl with a spoon, and drizzle with olive oil and paprika.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "500g", "yield_count": 8, "serving_size_g": 60}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 191.08, "protein_g": 8.14, "carbohydrates_g": 16.94, "fat_g": 11.79, "saturated_fat_g": 1.57, "trans_fat_g": null, "monounsaturated_fat_g": 1.41, "polyunsaturated_fat_g": 0.22, "fiber_g": 8.93, "sugar_g": 4.43, "sodium_mg": 701.96, "cholesterol_mg": null, "potassium_mg": 460.81, "calcium_mg": 194.73, "iron_mg": 5.61, "magnesium_mg": 54.31, "phosphorus_mg": 87.2, "zinc_mg": 0.78, "vitamin_a_mcg": 3.24, "vitamin_c_mg": 3.12, "vitamin_d_mcg": null, "vitamin_e_mg": 0.33, "vitamin_k_mcg": 1.25, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": null, "thiamin_mg": null, "riboflavin_mg": 0.01, "niacin_mg": 0.03, "folate_mcg": 1.61, "water_g": 12.95, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container; drizzle with olive oil to prevent a skin from forming.", "duration": "P5D"}, "freezer": {"notes": "Texture may change slightly; thaw in fridge and re-whip before serving.", "duration": "P3M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Food processor", "required": true, "alternative": "High-speed blender"}, {"name": "Small pot", "required": false, "alternative": "Microwave-safe bowl"}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Citrus juicer", "required": false, "alternative": null}]', '[{"symptom": "Texture is grainy or gritty", "likely_cause": "Chickpea skins were tough or processing time was too short", "prevention": "Boil canned chickpeas with baking soda as instructed", "fix": "Add 1 tablespoon of warm water and process for another 2-3 minutes"}, {"symptom": "Taste is too bitter", "likely_cause": "Low quality tahini or old garlic", "prevention": "Use premium Ethiopian or Levantine tahini", "fix": "Balance with a pinch more salt and a small drizzle of maple syrup or honey"}]', '["The Ice Water Secret: Adding ice-cold water to the fatty tahini creates a stable emulsion and whips air into the mixture, resulting in a lighter, creamier hummus similar to gelato.", "Order Matters: Processing the tahini, lemon, and garlic first creates a ''tahini sauce'' base that coats the starch of the chickpeas, preventing a gluey texture.", "Chickpea Quality: While this recipe uses canned for speed, over-boiling them with baking soda mimics the texture of home-cooked dried chickpeas.", "Flavor Balance: If your lemons are not very acidic, you may need to increase the quantity to cut through the rich fat of the tahini."]', '"Hummus bi tahini (chickpeas with tahini) is a staple Levantine dish with ancient roots, consumed across the Middle East for breakfast, mezze, or dinner. While its exact origins are debated among regional cultures, it represents a unifying culinary tradition centered on hospitality, sharing, and the maximization of humble, nutritious ingredients."', 191.08);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('116517fa-45ac-420f-b2f5-c8b220ccd9a9', 'Spaghetti with Artichokes, Anchovies, and Capers', 'A deeply savory Southern Italian pasta dish balancing the briny punch of capers and anchovies with earth-sweet artichoke hearts. Topped with garlicky toasted breadcrumbs for a crunchy textural contrast against the al dente pasta.', 'dinner', 'Italian', 'Intermediate', '["pasta", "artichoke", "italian", "quick-dinner", "pescatarian"]', '[{"group_name": "Crispy Breadcrumb Topping (Pangrattato)", "items": [{"name": "coarse breadcrumbs", "quantity": 60, "unit": "g", "preparation": "panko or homemade dry", "notes": null, "substitutions": [], "ingredient_id": "92441189-214a-4a8a-9cfc-dd578fe0d179", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pasta & Sauce Base", "items": [{"name": "spaghetti", "quantity": 400, "unit": "g", "preparation": "dried", "notes": "Linguine or bucatini also work well", "substitutions": ["Linguine", "Bucatini"], "ingredient_id": "3994b041-8c11-4992-adf0-a373b17e1aee", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": "Plus extra for finishing", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "anchovy fillets in oil", "quantity": 45, "unit": "g", "preparation": "drained", "notes": "approx 8-10 fillets", "substitutions": [], "ingredient_id": "be6d6563-a010-4028-863e-d518456aee98", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "thinly sliced", "notes": "approx 20g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "red chili flakes", "quantity": 2, "unit": "g", "preparation": "dried", "notes": "Adjust to taste", "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "artichoke hearts", "quantity": 300, "unit": "g", "preparation": "halved or quartered", "notes": "Canned or jarred in brine, drained well and patted dry", "substitutions": [], "ingredient_id": "4cb78e4f-64da-4303-a041-a9aef2ad7d5b", "nutrition_source": "Aggregated Public Data"}, {"name": "capers", "quantity": 30, "unit": "g", "preparation": "rinsed", "notes": "If salt-packed, soak for 10 mins", "substitutions": [], "ingredient_id": "e7301d2c-b906-4ef8-917e-787be0b25880", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": "zested and juiced", "notes": "approx 45ml juice", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Bring a large stockpot of water to a boil. Season with salt, but use less than usual (about 15g) as the anchovies and capers will add significant salinity later.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "While water heats, prepare the pangrattato. In a large saut\u00e9 pan, heat 15ml olive oil over medium heat. Add breadcrumbs and toast, stirring constantly, until golden brown and fragrant. Remove crumbs to a small bowl and wipe the pan clean.", "structured": {"action": "TOAST", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown color", "tactile": "Crispy texture"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In the same pan, heat the remaining 60ml olive oil over medium-low heat. Add the anchovy fillets and sliced garlic. Cook gently, mashing the anchovies with a wooden spoon until they dissolve completely into the oil and the garlic is pale gold.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Anchovies dissolved, garlic pale gold", "tactile": null}}, "tips": ["Do not burn the garlic; it will turn bitter. Keep heat low."]}, {"step_number": 4, "phase": "cook", "text": "Increase heat to medium-high. Add the drained artichoke hearts to the pan. Saut\u00e9 for 3-4 minutes until they develop a light golden sear on the edges. Stir in the chili flakes and capers.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Golden edges on artichokes", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add spaghetti to the boiling water. Cook until 2 minutes shy of al dente (the pasta will finish cooking in the sauce).", "structured": {"action": "BOIL", "temperature": null, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Transfer the pasta directly from the water to the saut\u00e9 pan using tongs. Ladle in about 120ml (approx 1/2 cup) of the starchy pasta water. Increase heat to high and toss vigorously to emulsify the oil and water into a creamy sauce.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Sauce is glossy and coats pasta", "tactile": "Pasta is al dente"}}, "tips": ["If the pan looks dry, add more pasta water 30ml at a time."]}, {"step_number": 7, "phase": "finish", "text": "Remove pan from heat. Stir in the lemon juice, lemon zest, and fresh parsley. Taste and adjust seasoning (you likely won''t need extra salt). Serve immediately, topped generously with the reserved crispy breadcrumbs.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT0M", "total_time": "PT25M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Pescatarian", "Dairy-Free", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 452.59, "protein_g": 15.65, "carbohydrates_g": 51.44, "fat_g": 20.67, "saturated_fat_g": 2.99, "trans_fat_g": null, "monounsaturated_fat_g": 14.04, "polyunsaturated_fat_g": 2.67, "fiber_g": 7.66, "sugar_g": 2.36, "sodium_mg": 583.35, "cholesterol_mg": 6.75, "potassium_mg": 368.58, "calcium_mg": 112.33, "iron_mg": 3.51, "magnesium_mg": 49.11, "phosphorus_mg": 109.8, "zinc_mg": 1.07, "vitamin_a_mcg": 25.61, "vitamin_c_mg": 27.14, "vitamin_d_mcg": null, "vitamin_e_mg": 3.1, "vitamin_k_mcg": 76.25, "vitamin_b6_mg": 0.19, "vitamin_b12_mcg": 0.12, "thiamin_mg": 0.48, "riboflavin_mg": 0.28, "niacin_mg": 4.63, "folate_mcg": 109.12, "water_g": 100.41, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Breadcrumbs will lose crunch; store separately if possible.", "duration": "P2D"}, "freezer": {"notes": "Pasta texture degrades significantly upon freezing.", "duration": null}, "reheating": "Reheat in a pan with a splash of water and olive oil to loosen the sauce.", "does_not_keep": false}', '[{"name": "Large stockpot", "required": true, "alternative": null}, {"name": "Large saut\u00e9 pan or skillet", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Microplane or zester", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "Dish tastes too salty", "likely_cause": "Pasta water was over-salted combined with salty anchovies/capers", "prevention": "Reduce salt in boiling water; rinse capers thoroughly", "fix": "Add a splash of water and more lemon juice to dilute; do not add cheese"}, {"symptom": "Sauce is oily and separated", "likely_cause": "Broken emulsion due to insufficient agitation or not enough starch water", "prevention": "Toss pasta vigorously with starchy water over high heat", "fix": "Add 30ml hot pasta water and shake/toss pan aggressively until creamy"}]', '["Dissolving the anchovies is the secret to the savory ''umami'' base; even people who dislike whole anchovies will love the depth they provide here.", "Pat the artichokes very dry before adding them to the oil. Excess moisture prevents searing and leads to steaming.", "The ''pangrattato'' (toasted breadcrumbs) is a classic ''poor man''s parmesan'' that adds essential crunch to an otherwise soft dish.", "Always reserve a mug of pasta water before draining if you aren''t using tongs to transfer; you may need more liquid than you think."]', '"This dish draws inspiration from the bold flavors of Southern Italy and Sicily, where pantry staples like preserved fish and vegetables are transformed into luxurious meals. While similar to Puttanesca, the focus here shifts to the interplay between the earthy artichoke and the briny sea flavors."', 452.59);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('11924d3e-fab3-4196-880c-c0e7c6a45886', 'Lemony Hashed Brussels Sprouts with Mustard Seeds', 'Vibrant ribbons of Brussels sprouts flash-fried with popping black mustard seeds and finished with aromatic lemon zest. This preparation transforms the dense vegetable into a light, crunchy, and intensely flavorful side dish with a distinct textural advantage over roasting.', 'side dish', 'Modern American', 'Easy', '["vegetables", "brussels sprout", "food processor", "lemon zest", "stovetop", "dinner", "quick", "side dish", "fall", "gluten-free", "vegetarian", "christmas", "new year\u2019s day", "rosh hashana", "thanksgiving", "vegan"]', '[{"group_name": "Vegetables", "items": [{"name": "brussels sprouts", "quantity": 450, "unit": "g", "preparation": "trimmed and shredded", "notes": "use slicing disk on food processor or slice thinly by hand", "substitutions": ["shredded cabbage", "shredded kale"], "ingredient_id": "2ee7388c-3256-477d-8d05-4ce09df9d8f1", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": null, "notes": "zest and juice separated", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "thinly sliced", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pantry", "items": [{"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "or neutral oil like grapeseed", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "black mustard seeds", "quantity": 4, "unit": "g", "preparation": null, "notes": "approx 1 tsp; brown mustard seeds also work", "substitutions": ["cumin seeds", "caraway seeds"], "ingredient_id": "6bc4809f-da0c-4b24-a7e4-09873d83ecc3", "nutrition_source": "Aggregated Public Data"}, {"name": "red pepper flakes", "quantity": 1, "unit": "g", "preparation": null, "notes": "optional, for heat", "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the Brussels sprouts. Trim the hard woody ends. Pass them through a food processor fitted with the slicing disk, or slice them thinly (approx 3mm) using a sharp knife. Zest the lemon and set the zest aside; reserve the lemon for juicing later.", "structured": {"action": "SHRED", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Use the slicing disk, not the grating disk, to preserve texture.", "Remove any discolored outer leaves before slicing."]}, {"step_number": 2, "phase": "cook", "text": "Heat the olive oil in a large skillet over medium-high heat. Add the black mustard seeds. Wait for them to sizzle and begin to pop (about 30-60 seconds). This step is crucial to remove bitterness and release their nutty aroma.", "structured": {"action": "TEMPER", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT1M", "doneness_cues": {"visual": "Seeds popping", "tactile": "Audible popping sound"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Immediately add the shredded Brussels sprouts, sliced garlic, and red pepper flakes (if using) to the pan. Toss quickly to coat in the hot oil. Saut\u00e9 vigorously for 4-5 minutes. The goal is to wilt the sprouts and get golden-brown charred edges while keeping them al dente.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Bright green with golden edges", "tactile": "Tender-crisp"}}, "tips": ["Do not overcrowd the pan too much or the sprouts will steam instead of fry. Use the largest pan you have."]}, {"step_number": 4, "phase": "finish", "text": "Remove from heat. Immediately stir in the lemon zest and squeeze about 1 tablespoon (15ml) of fresh lemon juice over the sprouts. Season with salt and black pepper. Toss to combine and serve immediately.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT0M", "total_time": "PT15M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 120}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Low-Carb", "Keto", "Paleo", "Whole30", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 130.35, "protein_g": 4.47, "carbohydrates_g": 13.12, "fat_g": 8.37, "saturated_fat_g": 1.16, "trans_fat_g": null, "monounsaturated_fat_g": 5.51, "polyunsaturated_fat_g": 1, "fiber_g": 5.15, "sugar_g": 3.12, "sodium_mg": 320.17, "cholesterol_mg": null, "potassium_mg": 488.85, "calcium_mg": 57.22, "iron_mg": 1.82, "magnesium_mg": 28.77, "phosphorus_mg": 84.45, "zinc_mg": 0.51, "vitamin_a_mcg": 48.23, "vitamin_c_mg": 107.55, "vitamin_d_mcg": null, "vitamin_e_mg": 2.18, "vitamin_k_mcg": 204.28, "vitamin_b6_mg": 0.29, "vitamin_b12_mcg": null, "thiamin_mg": 0.17, "riboflavin_mg": 0.11, "niacin_mg": 0.89, "folate_mcg": 71.32, "water_g": 116.6, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Texture softens significantly upon reheating.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; delicate shreds will become mushy.", "duration": null}, "reheating": "Briefly saut\u00e9 in a hot pan to restore texture; microwave will make them soggy.", "does_not_keep": false}', '[{"name": "Food Processor", "required": false, "alternative": "Chef''s Knife"}, {"name": "Large Skillet or Wok", "required": true, "alternative": null}, {"name": "Microplane or Zester", "required": true, "alternative": null}]', '[{"symptom": "Mustard seeds taste bitter", "likely_cause": "The seeds did not pop in the hot oil before the vegetables were added", "prevention": "Wait for the audible popping sound before adding other ingredients", "fix": "Cannot be fixed once cooked"}, {"symptom": "Sprouts are soggy", "likely_cause": "Pan was not hot enough or was overcrowded", "prevention": "Use a large skillet and high heat; cook in two batches if necessary", "fix": "Cannot be fixed, but can still be eaten"}]', '["Shredding Brussels sprouts drastically reduces cooking time and increases surface area for caramelization, eliminating the sulfurous flavor often associated with boiled whole sprouts.", "Black mustard seeds are smaller and more pungent than yellow ones. If you cannot find them, cumin seeds offer a different but equally delicious flavor profile.", "Add the garlic with the sprouts rather than with the oil to prevent it from burning while the mustard seeds pop.", "This dish is best served immediately. As it sits, the lemon juice will eventually discolor the vibrant green vegetables."]', '"While Brussels sprouts are a staple of Western holiday tables, this recipe borrows the Indian technique of ''tadka'' or tempering\u2014blooming spices in hot oil\u2014to unlock complex aromatics. This fusion approach brightens a heavy winter vegetable, making it appropriate for both Rosh Hashanah (symbolizing a wish for a good year) and Thanksgiving."', 130.35);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('119b3ee0-3f6c-4981-9660-88e5f4ebc25c', 'Warm Salad of Roasted Beetroot, Broad Beans, and Mozzarella', 'A vibrant composition featuring earthy roasted beets, jewel-bright broad beans, and crisp mange tout. The warmth of the vegetables slightly melts the milky mozzarella, while a zesty lemon-mint dressing ties the contrasting textures together.', 'salad', 'Modern European', 'Intermediate', '["salad", "warm salad", "broad beans", "mange tout", "beetroot", "mozzarella", "dressing", "spring", "vegetarian", "lunch"]', '[{"group_name": "Roasted Roots", "items": [{"name": "raw beetroot", "quantity": 400, "unit": "g", "preparation": "scrubbed and cut into wedges", "notes": "approx. 3 medium beets", "substitutions": [], "ingredient_id": "a52110ce-565d-4ce2-adb7-82fe2dba4326", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "for roasting", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Greens & Beans", "items": [{"name": "broad beans", "quantity": 250, "unit": "g", "preparation": "podded weight (approx. 1kg unpodded)", "notes": "frozen can be substituted", "substitutions": [], "ingredient_id": "f9ecd9f0-e667-4d13-a964-23e9e990dba3", "nutrition_source": "USDA FoodData Central"}, {"name": "mange tout", "quantity": 150, "unit": "g", "preparation": "trimmed", "notes": null, "substitutions": [], "ingredient_id": "4ec3f396-e9cc-4f96-b1fc-9a79353e2f8e", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "clove", "notes": "thinly sliced, approx 3g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dressing & Finish", "items": [{"name": "fresh mozzarella", "quantity": 125, "unit": "g", "preparation": "drained", "notes": "Buffalo mozzarella preferred", "substitutions": [], "ingredient_id": "f219ebe9-5ced-45e9-90b4-57fc34e327e8", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh mint leaves", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "17abecc0-a2a0-4478-8486-57b46e4305c9", "nutrition_source": "USDA FoodData Central"}, {"name": "hazelnuts", "quantity": 30, "unit": "g", "preparation": "toasted and roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "4a2947d7-4339-48a9-89b7-039c446295e4", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 200\u00b0C (400\u00b0F). Toss the beetroot wedges with 15ml olive oil and a pinch of salt on a baking sheet.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Roast the beetroot for 35-45 minutes until tender and slightly caramelized at the edges.", "structured": {"action": "ROAST", "temperature": null, "duration": "PT40M", "doneness_cues": {"visual": "Edges are browned", "tactile": "Knife slides through easily"}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "While beets roast, bring a medium saucepan of salted water to a boil. Blanch the broad beans for 2-3 minutes. Drain and rinse immediately under cold water. Once cool enough to handle, pop the bright green beans out of their grey outer skins (double-podding).", "structured": {"action": "BLANCH", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": ["Double-podding reveals the vibrant green color and removes the tough, bitter outer skin."]}, {"step_number": 4, "phase": "prep", "text": "Whisk together the extra virgin olive oil, lemon juice, chopped mint, salt, and pepper in a small bowl or jar to make the dressing.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Heat a frying pan over medium-high heat. Add a splash of oil and saut\u00e9 the mange tout and sliced garlic for 2 minutes until the mange tout is bright green but still crisp.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Bright green color", "tactile": "Crisp-tender"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Turn off the heat. Add the double-podded broad beans and roasted beetroot to the pan with the mange tout just to warm them through with the residual heat.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Transfer the warm vegetable mixture to a serving platter. Tear the fresh mozzarella over the top. Drizzle generously with the dressing and scatter toasted hazelnuts if using. Serve immediately.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT40M", "total_time": "PT1H05M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 230}', '{"flags": ["Vegetarian", "Gluten-Free", "Egg-Free", "Soy-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 328.56, "protein_g": 17.06, "carbohydrates_g": 22.37, "fat_g": 20.21, "saturated_fat_g": 2.54, "trans_fat_g": null, "monounsaturated_fat_g": 11, "polyunsaturated_fat_g": 1.85, "fiber_g": 7.73, "sugar_g": 8.59, "sodium_mg": 536.93, "cholesterol_mg": 5.63, "potassium_mg": 634.46, "calcium_mg": 356.71, "iron_mg": 3.35, "magnesium_mg": 77.37, "phosphorus_mg": 341.99, "zinc_mg": 2.17, "vitamin_a_mcg": 71.24, "vitamin_c_mg": 41.95, "vitamin_d_mcg": null, "vitamin_e_mg": 2.25, "vitamin_k_mcg": 10.15, "vitamin_b6_mg": 0.14, "vitamin_b12_mcg": 0.29, "thiamin_mg": 0.15, "riboflavin_mg": 0.21, "niacin_mg": 1.34, "folate_mcg": 175.57, "water_g": 163.11, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten immediately while warm. If stored, keep dressing separate.", "duration": "P1D"}, "freezer": {"notes": null, "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Medium saucepan", "required": true, "alternative": null}, {"name": "Large frying pan or skillet", "required": true, "alternative": null}, {"name": "Small bowl or jar", "required": true, "alternative": "Whisk"}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "Broad beans are bitter and tough", "likely_cause": "The outer grey skin was not removed", "prevention": "Ensure you perform the ''double podding'' step after blanching", "fix": "Cannot be fixed once mixed, but peeling them makes a huge difference in future attempts"}]', '["Timing is key for a warm salad; have your dressing ready and beans peeled before the beets finish roasting.", "If you cannot find fresh broad beans, frozen ones work excellently but still require the skins to be removed for the best texture.", "Tearing the mozzarella rather than slicing it creates more surface area to catch the dressing and looks more rustic.", "For extra earthiness, swap the hazelnuts for walnuts."]', '"This dish draws from modern Mediterranean cuisine, which emphasizes letting seasonal vegetables shine with minimal intervention. The combination of broad beans (fava) and fresh cheese is a classic Italian pairing often seen in the spring."', 328.56);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('12369f2d-b660-4b65-b230-83230fff97bb', 'Classic Graham Cracker Crust', 'A buttery, golden-brown foundation with a satisfying crunch and subtle molasses sweetness. Ideally textured to hold creamy custards, heavy cheesecakes, or silk pies without becoming soggy. The crumb is tight enough to slice cleanly yet tender enough to yield to a fork.', 'base', 'American', 'Easy', '["pastries", "graham cracker", "sugar", "dessert", "christmas", "thanksgiving", "base", "pie", "baking"]', '[{"group_name": "Dry Mix", "items": [{"name": "graham cracker crumbs", "quantity": 150, "unit": "g", "preparation": "fine crumbs", "notes": "approx. 9-10 full cracker sheets", "substitutions": ["digestive biscuit crumbs", "vanilla wafer crumbs"], "ingredient_id": "691bf5bd-8e84-4fc7-991e-758b5c811fd9", "nutrition_source": "Aggregated Public Data"}, {"name": "granulated sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "one pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Binder", "items": [{"name": "unsalted butter", "quantity": 85, "unit": "g", "preparation": "melted", "notes": null, "substitutions": ["vegan butter block", "coconut oil"], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 175\u00b0C/350\u00b0F. Ensure the rack is in the center position.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Combine the graham cracker crumbs, sugar, and salt in a medium mixing bowl. Whisk or stir until the sugar is evenly distributed to ensure structural integrity.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "assemble", "text": "Pour the melted butter over the crumb mixture. Stir thoroughly with a fork until the mixture resembles wet sand and holds together when squeezed in your palm.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "resembles wet sand", "tactile": "holds shape when squeezed"}}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Transfer the crumbs to the pie plate. Using the bottom of a measuring cup or glass, firmly press the crumbs into the bottom and up the sides of the dish. Pack it tightly to prevent crumbling later.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Start pressing from the center and work outward.", "Don''t press the rim too thin or it will burn."]}, {"step_number": 5, "phase": "cook", "text": "Bake for 10 minutes at 175\u00b0C/350\u00b0F until fragrant and slightly darkened. This sets the sugar and butter for a crisp crust.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT10M", "doneness_cues": {"visual": "slightly darkened", "tactile": "firm to touch"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove from the oven and allow to cool completely on a wire rack before adding any filling. Filling a hot crust may cause it to become soggy.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT20M", "total_time": "PT30M", "overnight_required": false, "yields": "1 9-inch crust", "yield_count": 8, "serving_size_g": 33}', '{"flags": ["Vegetarian", "Egg-Free", "Soy-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": ["Vegan (contains butter)", "Gluten-Free (unless GF crackers used)"]}', '{"per_serving": {"calories": 162.88, "protein_g": 1.22, "carbohydrates_g": 17.82, "fat_g": 12.09, "saturated_fat_g": 5.37, "trans_fat_g": null, "monounsaturated_fat_g": 2.49, "polyunsaturated_fat_g": 0.32, "fiber_g": 0.38, "sugar_g": 7.69, "sodium_mg": 133.33, "cholesterol_mg": 22.84, "potassium_mg": 2.64, "calcium_mg": 10.12, "iron_mg": 0.68, "magnesium_mg": 0.21, "phosphorus_mg": 2.55, "zinc_mg": 0.01, "vitamin_a_mcg": 72.68, "vitamin_c_mg": null, "vitamin_d_mcg": null, "vitamin_e_mg": 0.25, "vitamin_k_mcg": 0.74, "vitamin_b6_mg": null, "vitamin_b12_mcg": 0.02, "thiamin_mg": null, "riboflavin_mg": 0.01, "niacin_mg": null, "folate_mcg": 0.32, "water_g": 1.72, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store wrapped tightly if pre-baked; best filled within 24 hours.", "duration": "P3D"}, "freezer": {"notes": "Freeze unbaked or baked; wrap tightly in plastic.", "duration": "P3M"}, "reheating": "If frozen, thaw at room temperature for 10 minutes before filling.", "does_not_keep": false}', '[{"name": "9-inch Pie Plate", "required": true, "alternative": "Springform pan"}, {"name": "Medium mixing bowl", "required": true, "alternative": null}, {"name": "Flat-bottomed measuring cup", "required": false, "alternative": "Glass with flat bottom"}]', '[{"symptom": "Crust crumbles extensively when sliced", "likely_cause": "The crumbs were not pressed firmly enough into the pan, or insufficient butter was used.", "prevention": "Use a heavy flat-bottomed object to compress the crumbs with significant force.", "fix": "Cannot be fixed once baked and filled. Serve as a ''deconstructed'' crumble topping."}]', '["To create a ''No-Bake'' version, simply chill the pressed crust in the freezer for 20 minutes instead of baking. Note that the texture will be less crisp and more sandy.", "For a deeper flavor profile suitable for pumpkin or pecan pies, substitute the white sugar with light brown sugar.", "If using a springform pan for cheesecake, press the crumbs only halfway up the sides to create a cleaner look after unmolding.", "Ensure the butter is fully melted but not boiling hot; if the butter is too hot, it may separate from the solids before mixing is complete."]', '"The graham cracker was originally developed in the early 19th century by Sylvester Graham as part of a bland diet to suppress ''carnal urges.'' Ironically, it evolved into a staple of American dessert culture, becoming the definitive crust for indulgent treats like Key Lime Pie and New York Cheesecake."', 162.88);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('12942471-4842-4940-9f26-2cfb3e79095a', 'Silken Tofu & Watercress Salad with Sesame-Lime Yogurt', 'A refreshing study in textural contrasts: chilled, custard-like silken tofu sits against peppery watercress and crisp cucumber, finished with a bright, nutty yogurt dressing that bridges the gap between creamy and acidic.', 'salad', 'Modern Fusion', 'Easy', '["parsley", "salad", "sesame seed", "silken tofu", "watercress", "yogurt", "easy", "quick", "appetizer", "side dish", "vegetarian"]', '[{"group_name": "Sesame-Lime Yogurt Dressing", "items": [{"name": "plain greek yogurt", "quantity": 120, "unit": "g", "preparation": "chilled", "notes": "full fat preferred for texture", "substitutions": [], "ingredient_id": "2c5306ec-9f54-424e-880d-99546bbd9172", "nutrition_source": "USDA FoodData Central"}, {"name": "tahini", "quantity": 30, "unit": "g", "preparation": "well-stirred", "notes": null, "substitutions": [], "ingredient_id": "87ae6455-8e22-4c1b-bad7-89fa69c4dc57", "nutrition_source": "Aggregated Public Data"}, {"name": "lime juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "toasted sesame oil", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8fa9dd65-c49e-449c-b660-a9d9deb638b2", "nutrition_source": "Aggregated Public Data"}, {"name": "honey", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": ["maple syrup", "agave nectar"], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Salad Base", "items": [{"name": "silken tofu", "quantity": 300, "unit": "g", "preparation": "chilled", "notes": "handle very gently", "substitutions": [], "ingredient_id": "864e8f0d-90a8-481b-853c-ae1de43929de", "nutrition_source": "USDA FoodData Central"}, {"name": "watercress", "quantity": 100, "unit": "g", "preparation": "washed and thick stems removed", "notes": null, "substitutions": [], "ingredient_id": "3d74325b-824d-447d-b50c-93abd1539cb0", "nutrition_source": "USDA FoodData Central"}, {"name": "flat-leaf parsley", "quantity": 20, "unit": "g", "preparation": "leaves picked whole", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "cucumber", "quantity": 150, "unit": "g", "preparation": "sliced into thin half-moons", "notes": null, "substitutions": [], "ingredient_id": "457adec2-3e06-4efe-a26e-9e6ea9f84924", "nutrition_source": "USDA FoodData Central"}, {"name": "white sesame seeds", "quantity": 5, "unit": "g", "preparation": "toasted", "notes": null, "substitutions": [], "ingredient_id": "36a7664a-f96c-44b9-9b6d-cdd5e9e54f55", "nutrition_source": "Aggregated Public Data"}, {"name": "black sesame seeds", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36a7664a-f96c-44b9-9b6d-cdd5e9e54f55", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Carefully remove the silken tofu from its package. Wrap it gently in paper towels and place it on a plate tilted slightly to drain excess water. Let it sit for 10 minutes.", "structured": {"action": "DRAIN", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": ["Do not press silken tofu like firm tofu; it will collapse.", "Removing surface water prevents the dressing from becoming watery."]}, {"step_number": 2, "phase": "prep", "text": "In a small mixing bowl, combine the Greek yogurt, tahini, lime juice, sesame oil, honey, and salt. Whisk vigorously until the mixture is smooth and emulsified. Taste and adjust salt if necessary.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "If sesame seeds are raw, toast them in a dry pan over medium heat (175\u00b0C/350\u00b0F) for 2-3 minutes until fragrant and golden. Remove immediately to cool.", "structured": {"action": "TOAST", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown color", "tactile": "Fragrant nutty aroma"}}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Cut the drained silken tofu into large 2cm (1 inch) cubes using a sharp knife.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Spread a generous swoosh of the yogurt dressing on the bottom of a serving platter. Arrange the watercress, parsley, and cucumber slices on top. Nestle the tofu cubes gently among the greens. Drizzle with remaining dressing and garnish with toasted sesame seeds.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT10M", "total_time": "PT25M", "overnight_required": false, "yields": "4 appetizer servings", "yield_count": 4, "serving_size_g": 185}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Egg-Free"], "not_suitable_for": ["Infants under 12 months (honey)"]}', '{"per_serving": {"calories": 143.15, "protein_g": 9.74, "carbohydrates_g": 7.83, "fat_g": 8.81, "saturated_fat_g": 1.13, "trans_fat_g": null, "monounsaturated_fat_g": 0.49, "polyunsaturated_fat_g": 1, "fiber_g": 1.97, "sugar_g": 4.01, "sodium_mg": 246.53, "cholesterol_mg": 1.5, "potassium_mg": 250.85, "calcium_mg": 224.82, "iron_mg": 2.4, "magnesium_mg": 51.31, "phosphorus_mg": 110.03, "zinc_mg": 0.69, "vitamin_a_mcg": 63.3, "vitamin_c_mg": 19.59, "vitamin_d_mcg": null, "vitamin_e_mg": 0.31, "vitamin_k_mcg": 150.67, "vitamin_b6_mg": 0.07, "vitamin_b12_mcg": 0.23, "thiamin_mg": 0.05, "riboflavin_mg": 0.13, "niacin_mg": 0.22, "folate_mcg": 15, "water_g": 161.1, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Dressing can be stored separately for 3 days. Once assembled, the watercress will wilt and tofu may weep water.", "duration": "P1D"}, "freezer": {"duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Paper towels", "required": true, "alternative": "Clean kitchen cloth"}, {"name": "Small frying pan", "required": false, "alternative": "Toaster oven"}]', '[{"symptom": "Tofu fell apart while cutting", "likely_cause": "Knife was dull or handling was too rough for silken texture", "prevention": "Use a very sharp knife and minimize movement; cut directly on the serving board if possible", "fix": "Serve as a ''smashed'' tofu salad\u2014it is a legitimate style and tastes just as good"}, {"symptom": "Dressing is too thick", "likely_cause": "Tahini brand variances or very thick Greek yogurt", "prevention": "Add liquids slowly", "fix": "Whisk in 1 teaspoon of cold water or lime juice at a time until desired consistency is reached"}]', '["Temperature is crucial here. Ensure the tofu and cucumber are fridge-cold before plating to contrast with the warmth of the toasted seeds.", "For an extra layer of flavor, zest the lime directly over the finished dish to release essential oils just before serving.", "Watercress has a natural peppery bite; if you find it too strong, increase the honey in the dressing by 5g to balance the flavor profile."]', '"This dish riffs on the Japanese concept of ''Hiyayakko'' (chilled tofu), which is traditionally served simply with soy sauce and bonito flakes. Here, we introduce Middle Eastern elements (tahini, yogurt) and Western herbs for a modern, global appetizer."', 143.15);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('129a6bb6-2a81-4126-9203-fee774ad604f', 'Coastal Shrimp and Red Lentil Khichdi', 'A comforting, restorative one-pot meal featuring creamy spiced lentils and rice studded with succulent, turmeric-marinated shrimp. This coastal variation of the classic Indian staple offers a gentle warmth from ginger and whole spices.', 'main course', 'Indian', 'Intermediate', '["indian", "rice", "lentils", "shrimp", "comfort food", "gluten-free", "one-pot"]', '[{"group_name": "Grains & Lentils", "items": [{"name": "basmati rice", "quantity": 200, "unit": "g", "preparation": "rinsed", "notes": "can substitute with short-grain rice for creamier texture", "substitutions": [], "ingredient_id": "b671f3cd-cdec-4182-8911-82a06a22815a", "nutrition_source": "USDA FoodData Central"}, {"name": "red lentils (masoor dal)", "quantity": 100, "unit": "g", "preparation": "rinsed", "notes": null, "substitutions": [], "ingredient_id": "6fcd314d-ff4a-4f7a-8164-7621ee0d94e3", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 1200, "unit": "ml", "preparation": null, "notes": "adjust for desired consistency", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Shrimp Marinade", "items": [{"name": "shrimp", "quantity": 300, "unit": "g", "preparation": "peeled and deveined", "notes": "medium size", "substitutions": [], "ingredient_id": "a6bf7ab3-9b88-4c5b-a2fa-966c40a0e5a7", "nutrition_source": "USDA FoodData Central"}, {"name": "ground turmeric", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1/2 tsp", "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics & Spices", "items": [{"name": "ghee", "quantity": 30, "unit": "g", "preparation": "divided", "notes": "or vegetable oil/coconut oil", "substitutions": ["coconut oil", "vegetable oil"], "ingredient_id": "ae1e9713-8f4a-4a91-9619-baa177e12fc6", "nutrition_source": "USDA FoodData Central"}, {"name": "cumin seeds", "quantity": 4, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "medium size, approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "ginger garlic paste", "quantity": 15, "unit": "g", "preparation": null, "notes": "approx 1 tbsp", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "green chili", "quantity": 1, "unit": null, "preparation": "slit lengthwise", "notes": "optional for heat", "substitutions": [], "ingredient_id": "6cdb0615-378e-4bfa-b76d-f19bbd780e6c", "nutrition_source": "USDA FoodData Central"}, {"name": "tomato", "quantity": 1, "unit": null, "preparation": "chopped", "notes": "medium size, approx 100g", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "garam masala", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1/2 tsp", "substitutions": [], "ingredient_id": "8ffcea01-5f22-462b-94de-ad2a97049325", "nutrition_source": "Aggregated Public Data"}, {"name": "cilantro", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": "for garnish", "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Rinse the basmati rice and lentils together in a sieve under cold water until the water runs clear. Soak them in a bowl of clean water for 20 minutes while preparing other ingredients.", "structured": {"action": "PREPARE", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Toss the cleaned shrimp with turmeric and a pinch of salt. Set aside to marinate briefly.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat half the ghee in a heavy-bottomed pot over medium-high heat. Sear the shrimp quickly for 1-2 minutes per side until just pink but not fully cooked through. Remove shrimp from the pot and set aside.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT3M", "doneness_cues": {"visual": "Pink and opaque on outside", "tactile": "Still slightly soft"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the remaining ghee to the same pot. Add cumin seeds and let them sizzle for 30 seconds. Add the diced onion and saut\u00e9 until golden brown.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Onions are golden brown", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Stir in the ginger garlic paste and green chili. Cook for 1 minute until the raw smell disappears. Add the chopped tomatoes, remaining salt, and cook until tomatoes soften.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Drain the rice and lentils. Add them to the pot and toast slightly with the aromatics for 1 minute. Pour in 1200ml water. Bring to a boil.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Reduce heat to low, cover the pot, and simmer for 15-20 minutes, stirring occasionally to prevent sticking. The mixture should become creamy and porridge-like.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT20M", "doneness_cues": {"visual": "Grains are soft and broken down", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Once rice is cooked, stir in the seared shrimp and garam masala. Cover and let sit on low heat for 3-4 minutes until shrimp reaches an internal temperature of 63\u00b0C/145\u00b0F and is cooked through.", "structured": {"action": "FINISH", "temperature": {"celsius": 63, "fahrenheit": 145}, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Garnish with fresh cilantro and serve hot.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT25M", "total_time": "PT50M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Pescatarian", "Gluten-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Shellfish allergy"]}', '{"per_serving": {"calories": 423.36, "protein_g": 25.94, "carbohydrates_g": 62.87, "fat_g": 7.77, "saturated_fat_g": 4.17, "trans_fat_g": 0.25, "monounsaturated_fat_g": 2.02, "polyunsaturated_fat_g": 0.77, "fiber_g": 5, "sugar_g": 2.88, "sodium_mg": 350.68, "cholesterol_mg": 136.88, "potassium_mg": 618.08, "calcium_mg": 110.77, "iron_mg": 3.84, "magnesium_mg": 69.54, "phosphorus_mg": 323.78, "zinc_mg": 2.73, "vitamin_a_mcg": 105.06, "vitamin_c_mg": 15.15, "vitamin_d_mcg": null, "vitamin_e_mg": 0.32, "vitamin_k_mcg": 1.34, "vitamin_b6_mg": 0.28, "vitamin_b12_mcg": 0.01, "thiamin_mg": 0.2, "riboflavin_mg": 0.08, "niacin_mg": 1.33, "folate_mcg": 63.35, "water_g": 406.16, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Shrimp texture may degrade slightly upon reheating.", "duration": "P2D"}, "freezer": {"notes": "Texture becomes softer upon thawing; best consumed fresh.", "duration": "P1M"}, "reheating": "Reheat gently on the stove with a splash of water to loosen consistency. Avoid high heat to prevent rubbery shrimp.", "does_not_keep": false}', '[{"name": "Heavy-bottomed pot or Dutch oven", "required": true, "alternative": "Pressure cooker"}, {"name": "Fine-mesh sieve", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Shrimp is rubbery and tough", "likely_cause": "Shrimp was overcooked by boiling with the rice for too long", "prevention": "Sear shrimp separately first and only fold them back in at the very end to warm through", "fix": "Chop the rubbery shrimp into small pieces and mix back in to disguise the texture"}, {"symptom": "Khichdi is too dry or stiff", "likely_cause": "Rice absorbed more water than expected or heat was too high", "prevention": "Check water levels halfway through cooking", "fix": "Stir in 100-200ml of boiling water to loosen the consistency before serving"}]', '["Texture Control: Khichdi is meant to be soft and porridge-like, not fluffy like a pilaf. Do not be afraid of ''overcooking'' the rice.", "The Sear: Searing the shrimp first adds a depth of flavor to the pot (fond) that boiling alone cannot achieve.", "Acid Balance: If the dish feels too heavy, a squeeze of lime juice right before serving lifts the flavors immensely.", "Lentil Choice: Red lentils (masoor) dissolve quickly creating a creamy texture; for more bite, use yellow moong dal.", "Tempering: For an extra restaurant-style finish, pour a teaspoon of hot ghee with a pinch of paprika over the top just before serving."]', '"Khichdi is the ultimate Indian comfort food, often served to soothe the stomach or on rainy days. While traditional versions are vegetarian, coastal communities (like those in Bengal or the Konkan coast) frequently incorporate fresh catch like prawns, transforming a humble porridge into a savory, protein-rich feast."', 423.36);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('12a4f97c-8e1b-4353-bfdf-3d804410e05e', 'Spicy Roasted Carrot & Citrus Salad', 'Sweet, caramelized roasted carrots are tossed in a pungent, zesty lime and fish sauce dressing, balanced by juicy orange segments and buttery roasted cashews. A textural interplay of tender vegetables, crunch, and fresh herbs.', 'salad', 'Southeast Asian Fusion', 'Easy', '["vegetables", "carrot", "cashew", "chile", "fish sauce", "lime juice", "orange", "salad", "dinner", "appetizer", "side", "thanksgiving"]', '[{"group_name": "Roasted Carrots", "items": [{"name": "carrots", "quantity": 900, "unit": "g", "preparation": "peeled and halved lengthwise", "notes": "Use slim carrots or Dutch carrots for best presentation", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "grape seed or canola", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Nuoc Cham Dressing", "items": [{"name": "fresh lime juice", "quantity": 60, "unit": "ml", "preparation": null, "notes": "approx 2-3 limes", "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "fish sauce", "quantity": 45, "unit": "ml", "preparation": null, "notes": "high quality premium brand preferred", "substitutions": ["vegan fish sauce", "soy sauce (changes flavor profile)"], "ingredient_id": "95a9a747-50ee-4be0-84be-0dfc96111e2a", "nutrition_source": "Aggregated Public Data"}, {"name": "palm sugar", "quantity": 30, "unit": "g", "preparation": "finely chopped or grated", "notes": "can substitute brown sugar", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced or grated", "notes": "approx 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "bird''s eye chili", "quantity": 1, "unit": null, "preparation": "thinly sliced", "notes": "adjust for heat preference, approx 3g", "substitutions": [], "ingredient_id": "e40b2f32-1599-4b72-a829-b858329933e8", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Assembly", "items": [{"name": "navel oranges", "quantity": 2, "unit": null, "preparation": "peeled and segmented (supr\u00e8med)", "notes": "approx 350g whole weight", "substitutions": [], "ingredient_id": "a644a589-02d1-4b90-98c5-ec79373a767b", "nutrition_source": "USDA FoodData Central"}, {"name": "roasted cashews", "quantity": 80, "unit": "g", "preparation": "roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "6a1de566-9ddf-429b-a13a-a11d228738a5", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 15, "unit": "g", "preparation": "leaves picked", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh mint", "quantity": 15, "unit": "g", "preparation": "torn", "notes": null, "substitutions": [], "ingredient_id": "213e3d3b-d332-45a9-b35e-23ee29a27173", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 220\u00b0C (425\u00b0F). Place the peeled and halved carrots on a large rimmed baking sheet.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Toss the carrots with neutral oil and salt until thoroughly coated. Arrange them in a single layer without overcrowding to ensure roasting rather than steaming.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Roast the carrots for 30-35 minutes, turning halfway through, until they are tender and caramelized with golden-brown edges.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT35M", "doneness_cues": {"visual": "Golden-brown edges and blistered spots", "tactile": "Knife meets little resistance"}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "While carrots roast, prepare the dressing. In a small bowl, whisk together the lime juice, fish sauce, palm sugar, minced garlic, and sliced chili. Whisk vigorously until the sugar is fully dissolved.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["If using hard palm sugar, you can microwave the mixture for 10 seconds to help it dissolve."]}, {"step_number": 5, "phase": "prep", "text": "Using a sharp knife, cut the top and bottom off the oranges. Stand them upright and slice off the peel and pith following the curve of the fruit. Slice between the membranes to release the segments (supr\u00e8mes) into a bowl.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Place the warm roasted carrots in a large salad bowl. Drizzle with half the dressing and toss gently to let the carrots absorb the flavors while warm.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Add the orange segments, cilantro, mint, and roasted cashews. Add remaining dressing to taste and toss gently to combine. Serve immediately.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT35M", "total_time": "PT1H", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 320}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Egg-Free"], "not_suitable_for": ["Vegetarians (contains fish sauce)", "Vegans (contains fish sauce)"]}', '{"per_serving": {"calories": 402.47, "protein_g": 8.16, "carbohydrates_g": 60.8, "fat_g": 17.06, "saturated_fat_g": 2.72, "trans_fat_g": null, "monounsaturated_fat_g": 4.79, "polyunsaturated_fat_g": 1.82, "fiber_g": 17.13, "sugar_g": 19.71, "sodium_mg": 1161.38, "cholesterol_mg": null, "potassium_mg": 1129.54, "calcium_mg": 241.3, "iron_mg": 4.24, "magnesium_mg": 121.24, "phosphorus_mg": 224.99, "zinc_mg": 2.06, "vitamin_a_mcg": 2074.53, "vitamin_c_mg": 139.7, "vitamin_d_mcg": null, "vitamin_e_mg": 1.7, "vitamin_k_mcg": 36.65, "vitamin_b6_mg": 0.44, "vitamin_b12_mcg": null, "thiamin_mg": 0.26, "riboflavin_mg": 0.17, "niacin_mg": 2.52, "folate_mcg": 53.6, "water_g": 217.75, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store components separately. If mixed, consume within 24 hours as herbs will wilt and nuts will soften.", "duration": "P2D"}, "freezer": {"notes": "Not suitable for freezing.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Large rimmed baking sheet", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Large salad bowl", "required": true, "alternative": null}]', '[{"symptom": "Carrots are mushy or soggy", "likely_cause": "The baking sheet was overcrowded, causing the carrots to steam instead of roast", "prevention": "Use two baking sheets if necessary to ensure ample space between carrots", "fix": "Spread onto a fresh hot tray and blast under the broiler for 2-3 minutes to dry out surface"}]', '["Dress the carrots while they are still warm; the heat opens the vegetable''s pores allowing the salty-sour dressing to penetrate deeper.", "For maximum crunch, toast the cashews in a dry pan for 2-3 minutes just before serving, even if they were bought ''roasted''.", "The balance of the dressing is key: it should taste salty, sour, sweet, and spicy all at once. Adjust the sugar or lime juice to find your perfect equilibrium.", "If you cannot find palm sugar, light brown sugar mixed with a teaspoon of maple syrup makes a decent alternative for depth of flavor."]', '"This dish draws inspiration from the Thai flavor profile of ''yum'' (salad) dishes, specifically the balance of salty fish sauce (nam pla), sour lime, and spicy chilies known as Nuoc Cham in Vietnamese or Nam Jim in Thai contexts. While roasted carrots are a Western technique, the application of this dressing creates a vibrant fusion popular in modern Australasian and Californian cuisine."', 402.47);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('12cfb601-4304-4416-abb6-68c861571346', 'Miso-Sesame Chicken & Cabbage Salad', 'A vibrant, crunch-forward salad balancing tender poached chicken with shredded Napa cabbage and crisp Romaine. The creamy, savory miso-sesame dressing provides a rich umami backbone, lifted by fresh mint, cilantro, and zesty lime.', 'salad', 'Fusion', 'Easy', '["american", "poultry", "vegetables", "chicken", "cilantro", "cucumber", "mint", "romaine", "salad", "scallion", "dinner", "lunch", "weeknight", "main course", "healthy", "fusion", "high-protein", "summer"]', '[{"group_name": "Poached Chicken", "items": [{"name": "boneless skinless chicken breasts", "quantity": 600, "unit": "g", "preparation": "whole", "notes": "Or use rotisserie chicken", "substitutions": [], "ingredient_id": "2b577d04-33ca-4919-938f-bfc8780a3a4b", "nutrition_source": "USDA FoodData Central"}, {"name": "ginger", "quantity": 10, "unit": "g", "preparation": "sliced", "notes": "For poaching liquid aromatics", "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "scallion scraps", "quantity": null, "unit": null, "preparation": null, "notes": "White parts or root ends for aromatics", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Miso-Sesame Dressing", "items": [{"name": "white miso paste", "quantity": 45, "unit": "g", "preparation": null, "notes": "Shiro miso", "substitutions": [], "ingredient_id": "d168e605-2d7b-4f05-a666-09815022b674", "nutrition_source": "Aggregated Public Data"}, {"name": "rice vinegar", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fcbf5252-1be9-4dd4-8c22-4fda1dbdca28", "nutrition_source": "Aggregated Public Data"}, {"name": "toasted sesame oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a9a59164-d949-4acd-99da-689f0a32e2e7", "nutrition_source": "Aggregated Public Data"}, {"name": "soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["tamari", "coconut aminos"], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "honey", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": ["maple syrup", "brown sugar"], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 5, "unit": "g", "preparation": "finely grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "lime juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Salad Base", "items": [{"name": "napa cabbage", "quantity": 300, "unit": "g", "preparation": "thinly shredded", "notes": null, "substitutions": [], "ingredient_id": "771c0eca-db4a-4c97-b01d-ee14efc0d3aa", "nutrition_source": "Aggregated Public Data"}, {"name": "romaine lettuce", "quantity": 200, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "312b8da7-52bd-406b-89d2-0853c0e37faa", "nutrition_source": "USDA FoodData Central"}, {"name": "cucumber", "quantity": 150, "unit": "g", "preparation": "sliced into half-moons", "notes": null, "substitutions": [], "ingredient_id": "457adec2-3e06-4efe-a26e-9e6ea9f84924", "nutrition_source": "USDA FoodData Central"}, {"name": "scallions", "quantity": 3, "unit": null, "preparation": "thinly sliced", "notes": "about 45g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 15, "unit": "g", "preparation": "rough chopped leaves and tender stems", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh mint", "quantity": 10, "unit": "g", "preparation": "leaves picked and torn", "notes": null, "substitutions": [], "ingredient_id": "213e3d3b-d332-45a9-b35e-23ee29a27173", "nutrition_source": "USDA FoodData Central"}, {"name": "toasted sesame seeds", "quantity": 10, "unit": "g", "preparation": "garnish", "notes": null, "substitutions": [], "ingredient_id": "36a7664a-f96c-44b9-9b6d-cdd5e9e54f55", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Place chicken breasts in a saucepan with ginger slices, scallion scraps, and a pinch of salt. Cover with cold water by 2cm. Bring to a boil over medium-high heat, then immediately reduce to the lowest simmer, cover, and cook for 10-12 minutes until internal temperature reaches 74\u00b0C/165\u00b0F.", "structured": {"action": "POACH", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT15M", "doneness_cues": {"visual": "Opaque throughout", "tactile": "Firm to the touch"}}, "tips": ["Starting with cold water ensures even cooking.", "Do not let the water boil vigorously after the initial heat-up, or the chicken will become tough."]}, {"step_number": 2, "phase": "prep", "text": "Remove chicken from the water and let rest on a cutting board until cool enough to handle. Using two forks or your hands, shred into bite-sized pieces.", "structured": {"action": "SHRED", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a small bowl or jar, combine miso paste, rice vinegar, sesame oil, soy sauce, honey, grated ginger, and lime juice. Whisk vigorously until the miso is fully dissolved and the dressing is emulsified.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Smooth, creamy, uniform light brown color", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "In a large mixing bowl, combine the shredded cabbage, Romaine, cucumber, scallions, cilantro, mint, and shredded chicken. Drizzle half the dressing over the mixture.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Toss well to coat every leaf. Taste and add more dressing if desired. Transfer to serving bowls and garnish with toasted sesame seeds.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Ingredients evenly distributed and lightly coated", "tactile": null}}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT15M", "total_time": "PT40M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Dairy-Free", "Egg-Free", "Pescatarian"], "not_suitable_for": []}', '{"per_serving": {"calories": 406.98, "protein_g": 35.22, "carbohydrates_g": 15.63, "fat_g": 23.36, "saturated_fat_g": 4.08, "trans_fat_g": 0.15, "monounsaturated_fat_g": 5.75, "polyunsaturated_fat_g": 3.06, "fiber_g": 3.6, "sugar_g": 8.18, "sodium_mg": 1539.38, "cholesterol_mg": 96, "potassium_mg": 837.44, "calcium_mg": 120.88, "iron_mg": 3.04, "magnesium_mg": 85.71, "phosphorus_mg": 358.76, "zinc_mg": 2.21, "vitamin_a_mcg": 485.4, "vitamin_c_mg": 26.08, "vitamin_d_mcg": 0.6, "vitamin_e_mg": 0.56, "vitamin_k_mcg": 80.98, "vitamin_b6_mg": 0.87, "vitamin_b12_mcg": 0.51, "thiamin_mg": 0.15, "riboflavin_mg": 0.2, "niacin_mg": 15.2, "folate_mcg": 87.67, "water_g": 277.58, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store dressing and salad separately to prevent wilting. Chicken keeps for 3 days.", "duration": "P3D"}, "freezer": {"notes": "Do not freeze fresh salad vegetables.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Medium saucepan", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Small whisk", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Small jar or bowl", "required": true, "alternative": "Blender for smoother dressing"}]', '[{"symptom": "Dressing tastes too salty", "likely_cause": "The miso paste or soy sauce used was high-sodium", "prevention": "Taste miso before mixing; start with less soy sauce", "fix": "Dilute with a teaspoon of water or add a splash more lime juice and honey to balance"}, {"symptom": "Chicken is dry or rubbery", "likely_cause": "Boiled too vigorously or overcooked", "prevention": "Maintain a very gentle simmer (barely bubbling) and remove as soon as temp is reached", "fix": "Toss chicken in a little dressing separately 10 minutes before assembling to rehydrate"}]', '["For the crispest salad, soak the shredded cabbage and scallions in ice water for 10 minutes, then spin thoroughly dry before assembling.", "White miso (Shiro) is best for this recipe due to its mild, sweet flavor. Red miso (Aka) will be much stronger and saltier\u2014use half the amount if substituting.", "This salad is an excellent vessel for leftovers; it works beautifully with rotisserie chicken, leftover turkey, or even firm tofu for a vegetarian option."]', '"While ''Chinese Chicken Salad'' became a staple of American fusion cuisine in the mid-20th century (often attributed to Wolfgang Puck in the 80s), this iteration leans into Japanese pantry staples like miso and rice vinegar. It reflects the modern Californian approach to salads: nutrient-dense, texture-heavy, and driven by global umami flavors rather than heavy mayonnaise-based dressings."', 406.98);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('13c49417-c978-46a4-9ff9-773cd685304b', 'Shaved Zucchini and Fennel Carpaccio Salad', 'A vibrant, crisp salad highlighting raw summer vegetables. Paper-thin ribbons of zucchini and fennel are marinated briefly in lemon and olive oil, then finished with salty Pecorino Romano and fresh mint for a refreshing Italian-inspired side.', 'salad', 'Italian', 'Easy', '["fennel", "salad", "zucchini", "easy", "quick", "summer", "gluten-free", "vegetarian", "raw", "italian"]', '[{"group_name": "Vegetables", "items": [{"name": "zucchini", "quantity": 2, "unit": null, "preparation": "firm, medium size", "notes": "approx 350g total", "substitutions": [], "ingredient_id": "d0aa0d47-cefe-4ece-a337-e656f79b74e9", "nutrition_source": "USDA FoodData Central"}, {"name": "fennel bulb", "quantity": 1, "unit": null, "preparation": "trimmed", "notes": "approx 250g", "substitutions": [], "ingredient_id": "a42d03de-0a8a-4a75-8299-5cf01d43b425", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh mint leaves", "quantity": 15, "unit": "g", "preparation": "torn", "notes": null, "substitutions": [], "ingredient_id": "213e3d3b-d332-45a9-b35e-23ee29a27173", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dressing & Garnish", "items": [{"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": "high quality", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 30, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": null, "notes": "from 1 lemon", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "Aggregated Public Data"}, {"name": "pecorino romano", "quantity": 50, "unit": "g", "preparation": "shaved with vegetable peeler", "notes": null, "substitutions": [], "ingredient_id": "81b3c92a-2238-4534-907e-2feb05e22f4c", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, start with 2g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Wash the zucchini and trim the ends. Using a mandoline or vegetable peeler, shave the zucchini lengthwise into long, paper-thin ribbons. Discard the first strip if it is mostly skin.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Translucent ribbons", "tactile": null}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Trim the stalks and fronds from the fennel bulb (reserve fronds for garnish). Cut the bulb in half lengthwise and remove the tough core. Shave the fennel very thinly using the mandoline.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Paper-thin shavings", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a large mixing bowl, whisk together the lemon juice, half of the lemon zest, sea salt, and black pepper. Slowly drizzle in the olive oil while whisking to create an emulsion.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Add the shaved zucchini and fennel to the bowl with the dressing. Toss gently with your hands to coat every ribbon without breaking them. Let sit for 10 minutes to allow the vegetables to soften slightly and absorb flavors.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Transfer the salad to a serving platter. Scatter the shaved Pecorino Romano and torn mint leaves over the top. Finish with the remaining lemon zest and a final crack of black pepper.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT10M", "total_time": "PT30M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Low-Carb", "Keto"], "not_suitable_for": ["Vegans (contains dairy)"]}', '{"per_serving": {"calories": 219.76, "protein_g": 6.01, "carbohydrates_g": 9.39, "fat_g": 18.73, "saturated_fat_g": 4.28, "trans_fat_g": null, "monounsaturated_fat_g": 11.98, "polyunsaturated_fat_g": 1.79, "fiber_g": 3.25, "sugar_g": 4.54, "sodium_mg": 415.54, "cholesterol_mg": 13, "potassium_mg": 304.49, "calcium_mg": 174.52, "iron_mg": 0.87, "magnesium_mg": 19.77, "phosphorus_mg": 130.26, "zinc_mg": 0.5, "vitamin_a_mcg": 50.04, "vitamin_c_mg": 12.52, "vitamin_d_mcg": 0.06, "vitamin_e_mg": 2.57, "vitamin_k_mcg": 48.97, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": 0.14, "thiamin_mg": 0.02, "riboflavin_mg": 0.08, "niacin_mg": 0.49, "folate_mcg": 23.76, "water_g": 71.7, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten fresh; vegetables will soften and release water significantly after 2-3 hours.", "duration": "P1D"}, "freezer": {"duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Mandoline slicer", "required": true, "alternative": "Y-peeler or very sharp knife"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Vegetable peeler", "required": true, "alternative": null}]', '[{"symptom": "Salad is watery and soggy", "likely_cause": "Salad sat too long after dressing; salt draws out moisture from zucchini", "prevention": "Dress the salad no more than 15-20 minutes before serving", "fix": "Drain excess liquid from the bottom of the bowl before plating"}]', '["Use a mandoline slicer for consistent thickness; the texture relies on the vegetables being thin enough to be pliable but crisp.", "Select smaller, firm zucchini as they have fewer seeds and a tighter texture compared to large, watery ones.", "For a vegan variation, replace Pecorino with toasted pine nuts or almonds for savory depth and crunch.", "If preparing ahead, keep the shaved vegetables covered with a damp paper towel in the fridge and the dressing in a jar; toss just before serving."]', '"This salad (often called ''insalata di zucchine crude'') reflects the Italian philosophy of handling raw, high-quality seasonal produce with minimal intervention. The combination of raw fennel and zucchini is a staple in Mediterranean summer cooking, valued for its digestive properties and cooling effect."', 219.76);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('148413c5-de31-47ae-93bb-9a4b468a53fb', 'Classic French Grated Carrot Salad', 'A vibrant bistro staple combining sweet, crisp carrots with a sharp, mustardy vinaigrette. The fresh parsley adds an herbaceous lift, making it a perfect palate-cleansing side dish that improves as it marinates.', 'salad', 'French', 'Easy', '["salad", "vegetable", "carrot", "parsley", "french", "quick", "side dish", "picnic", "make-ahead"]', '[{"group_name": "Vegetables", "items": [{"name": "carrots", "quantity": 450, "unit": "g", "preparation": "peeled and ends trimmed", "notes": "approx. 4-5 medium carrots", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "leaves picked and chopped", "notes": "flat-leaf preferred", "substitutions": ["chives", "cilantro"], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "minced or grated", "notes": "approx. 4g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vinaigrette", "items": [{"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": "approx. 3 tablespoons", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 30, "unit": "ml", "preparation": "freshly squeezed", "notes": "approx. 2 tablespoons", "substitutions": ["white wine vinegar", "apple cider vinegar"], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 15, "unit": "g", "preparation": null, "notes": "approx. 1 tablespoon", "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "maple syrup", "quantity": 5, "unit": "ml", "preparation": null, "notes": "optional, to balance acidity", "substitutions": ["honey", "sugar"], "ingredient_id": "1358a800-6e05-4bfd-ab71-03e78728c0bc", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Grate the peeled carrots using the medium holes of a box grater or a food processor shredding disc. Aim for strands that are distinct, not mushy.", "structured": {"action": "GRATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Use long strokes for nicer texture.", "If using a food processor, use the medium disc, not fine."]}, {"step_number": 2, "phase": "prep", "text": "Finely chop the fresh parsley leaves and mince the garlic clove.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a large mixing bowl, combine the lemon juice, Dijon mustard, minced garlic, maple syrup (if using), salt, and pepper. Whisk vigorously while slowly streaming in the olive oil until the dressing emulsifies and thickens slightly.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Add the grated carrots and chopped parsley to the bowl with the vinaigrette. Toss well until every strand of carrot is evenly coated.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Let the salad rest in the refrigerator for at least 30 minutes before serving. This allows the carrots to soften slightly and absorb the flavors.", "structured": {"action": "MARINATE", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT30M", "doneness_cues": null}, "tips": ["Taste again just before serving; carrots can absorb salt, so you might need a final pinch."]}]', '{"active_time": "PT15M", "passive_time": "PT30M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 135}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Paleo"], "not_suitable_for": []}', '{"per_serving": {"calories": 156.42, "protein_g": 1.42, "carbohydrates_g": 13.08, "fat_g": 11.7, "saturated_fat_g": 1.6, "trans_fat_g": null, "monounsaturated_fat_g": 8.24, "polyunsaturated_fat_g": 1.31, "fiber_g": 3.5, "sugar_g": 6.4, "sodium_mg": 413.96, "cholesterol_mg": null, "potassium_mg": 403.83, "calcium_mg": 50.92, "iron_mg": 0.79, "magnesium_mg": 16.77, "phosphorus_mg": 44.1, "zinc_mg": 0.35, "vitamin_a_mcg": 955.23, "vitamin_c_mg": 14.84, "vitamin_d_mcg": null, "vitamin_e_mg": 2.4, "vitamin_k_mcg": 83.55, "vitamin_b6_mg": 0.18, "vitamin_b12_mcg": null, "thiamin_mg": 0.09, "riboflavin_mg": 0.07, "niacin_mg": 1.17, "folate_mcg": 28.65, "water_g": 110.17, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors meld and improve after 24 hours.", "duration": "P3D"}, "freezer": {"notes": null, "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Box grater", "required": true, "alternative": "Food processor with shredding disc"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": "Fork"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Salad is too dry", "likely_cause": "Carrots were old or low in moisture", "prevention": "Use firm, fresh carrots with tops attached if possible", "fix": "Add another tablespoon (15ml) of olive oil and a teaspoon (5ml) of water"}, {"symptom": "Flavor is bland", "likely_cause": "Insufficient salt or acid to cut through the carrot sweetness", "prevention": "Taste the dressing before adding carrots; it should taste too strong on its own", "fix": "Add a pinch more salt and a squeeze of fresh lemon juice"}]', '["The texture of the grate is crucial; too fine and it becomes a wet slaw, too thick and it''s hard to chew. The medium hole on a box grater is the gold standard.", "For an authentic French touch, toast 30g of cumin seeds or walnuts and sprinkle them over the top just before serving.", "This salad pairs exceptionally well with fatty dishes like quiche, roast chicken, or p\u00e2t\u00e9 because the acidity cuts through the richness.", "If preparing more than 2 days in advance, keep the parsley separate and stir it in fresh before serving to maintain its bright green color."]', '"Known as ''Carottes R\u00e2p\u00e9es'' in France, this dish is a ubiquitous classic found in school canteens, charcuteries, and bistro menus across the country. It exemplifies the French philosophy of elevating humble, fresh ingredients through proper technique and seasoning."', 156.42);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('14adf61d-8553-4a48-966a-4b4b46b6175e', 'Ethereal Pumpkin Amaretti Custard', 'A sophisticated yet comforting alternative to pumpkin pie. This silky, baked pumpkin custard (pot de crème) is infused with warm autumn spices and topped with a textural contrast of crunchy almond amaretti cookies and zesty crystallized ginger.', 'dessert', 'French-American Fusion', 'Intermediate', '["amaretti cookies", "crystalized ginger", "kid-friendly", "pumpkin pur\u00e9e", "dessert", "fall", "thanksgiving", "custard", "make-ahead"]', '[{"group_name": "Pumpkin Custard Base", "items": [{"name": "heavy cream", "quantity": 300, "unit": "ml", "preparation": "liquid, min 35% fat", "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 100, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "pumpkin puree", "quantity": 240, "unit": "g", "preparation": "canned or homemade", "notes": "ensure it is pure pumpkin, not pie filling", "substitutions": [], "ingredient_id": "d9c74a13-e1c6-488d-8214-ea685a0f6eb2", "nutrition_source": "USDA FoodData Central"}, {"name": "egg yolks", "quantity": 5, "unit": null, "preparation": "large", "notes": "approx 90g total", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}, {"name": "dark brown sugar", "quantity": 85, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "d9823951-2391-49ba-90b4-7d8272161b6f", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "ground ginger", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "401ddd0b-3597-4b46-bb54-f3bc755048bb", "nutrition_source": "USDA FoodData Central"}, {"name": "ground nutmeg", "quantity": 0.5, "unit": "g", "preparation": "freshly grated preferred", "notes": null, "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Crunchy Topping", "items": [{"name": "amaretti cookies", "quantity": 60, "unit": "g", "preparation": "coarsely crushed", "notes": null, "substitutions": ["gingersnaps", "biscoff cookies"], "ingredient_id": "ce379f4c-2420-445a-9d46-f35f59d2f181", "nutrition_source": "Aggregated Public Data"}, {"name": "crystallized ginger", "quantity": 30, "unit": "g", "preparation": "minced very fine", "notes": null, "substitutions": [], "ingredient_id": "94aa0dff-461d-4081-b1aa-bac372e8fc0d", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 120, "unit": "ml", "preparation": "cold, for whipping", "notes": "optional garnish base", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 150\u00b0C (300\u00b0F). Place six ramekins into a deep roasting pan. Prepare a kettle of boiling water.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a saucepan, combine heavy cream, milk, cinnamon, ground ginger, nutmeg, and salt. Heat over medium heat until it just begins to steam and simmer around the edges. Do not let it come to a rolling boil. Remove from heat.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": null, "doneness_cues": {"visual": "Steam rising, small bubbles at edges", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a heatproof mixing bowl, whisk together the egg yolks and dark brown sugar until the mixture is smooth and slightly lightened in color.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Slowly pour the hot cream mixture into the egg yolks while whisking constantly to temper the eggs. Once combined, whisk in the pumpkin puree and vanilla extract until uniform.", "structured": {"action": "TEMPER", "temperature": null, "duration": null, "doneness_cues": {"visual": "Uniform color, no cooked egg bits", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Pour the custard mixture through a fine-mesh sieve into a large pouring vessel (like a glass measuring jug). Discard any solids trapped in the sieve. This step is crucial for the ethereal texture.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Divide the custard evenly among the ramekins. Pour enough boiling water into the roasting pan to reach halfway up the sides of the ramekins (bain-marie). Cover the pan loosely with foil.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Bake for 35 to 45 minutes. The custards are done when the edges are set but the center still jiggles slightly like gelatin when gently shaken. They should not be liquid, nor puffed and cracked.", "structured": {"action": "BAKE", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": "PT40M", "doneness_cues": {"visual": "Jiggly center like Jell-O", "tactile": "Edges firm"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove ramekins from the water bath carefully. Let them cool to room temperature on a wire rack, then refrigerate for at least 3 hours or until completely chilled.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT3H", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "assemble", "text": "Just before serving, whip the optional cold cream to soft peaks. Top each custard with a dollop of cream, a generous layer of crushed amaretti cookies, and a sprinkle of minced crystallized ginger.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT4H", "total_time": "PT4H30M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 160}', '{"flags": ["Vegetarian", "Soy-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 429.35, "protein_g": 6.22, "carbohydrates_g": 28.02, "fat_g": 31.72, "saturated_fat_g": 17.93, "trans_fat_g": 0.87, "monounsaturated_fat_g": 8.28, "polyunsaturated_fat_g": 1.77, "fiber_g": 1.49, "sugar_g": 26.14, "sodium_mg": 105.96, "cholesterol_mg": 242.77, "potassium_mg": 210.85, "calcium_mg": 112.26, "iron_mg": 1.23, "magnesium_mg": 18.54, "phosphorus_mg": 128.52, "zinc_mg": 0.85, "vitamin_a_mcg": 663.78, "vitamin_c_mg": 2.12, "vitamin_d_mcg": 2.15, "vitamin_e_mg": 1.47, "vitamin_k_mcg": 8.9, "vitamin_b6_mg": 0.12, "vitamin_b12_mcg": 0.48, "thiamin_mg": 0.06, "riboflavin_mg": 0.26, "niacin_mg": 0.25, "folate_mcg": 30.58, "water_g": 99.7, "alcohol_g": 0.27, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store custards covered with plastic wrap. Add toppings only just before serving to maintain crunch.", "duration": "P3D"}, "freezer": {"notes": "Do not freeze; the emulsion will break and texture will become grainy.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Ramekins (150-180ml capacity)", "required": true, "alternative": null}, {"name": "Deep roasting pan", "required": true, "alternative": "Any baking dish deep enough to hold ramekins and water"}, {"name": "Fine-mesh sieve", "required": true, "alternative": "Cheesecloth"}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Saucepan", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}]', '[{"symptom": "Custard texture is grainy", "likely_cause": "The eggs scrambled slightly due to high heat or lack of straining", "prevention": "Temper the eggs slowly and always strain the mixture before baking", "fix": "Cannot be fixed once baked; serve with extra crunchy toppings to mask texture"}, {"symptom": "Custard is watery or soupy", "likely_cause": "Underbaked", "prevention": "Ensure the custard has a gelatin-like wobbly set before removing from oven", "fix": "Return to oven immediately if still warm; if chilled, it cannot be rebaked"}, {"symptom": "Surface is cracked and rubbery", "likely_cause": "Overbaked or oven temperature too high", "prevention": "Use a water bath and check early; remove when center is still wobbly", "fix": "Cover completely with whipped cream and crumbs"}]', '["The water bath (bain-marie) acts as a thermal buffer, ensuring the custard cooks gently and evenly to achieve a silky mouthfeel.", "Straining the mixture removes chalazae (egg cords) and fibrous pumpkin bits, resulting in a much more refined dessert than standard pie filling.", "If serving to very young children who might find crystallized ginger too spicy, you can steep the ginger in the hot cream during step 2 and strain it out, rather than using it as a topping.", "Amaretti cookies have a distinct almond flavor which pairs beautifully with pumpkin; if unavailable, gingersnaps are a great alternative."]', '"While pumpkin pie is a stalwart of American Thanksgiving, the technique here borrows from the French ''pot de cr\u00e8me'' (pot of cream). This fusion elevates the humble pumpkin with European refinement, using the almond notes of Italian Amaretti to bridge the gap between savory squash and sweet dessert."', 429.35);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('150b1ccb-9a13-440a-a538-ba7c5558726b', 'Sheet Pan Roasted Shrimp and Broccoli Rabe with Lemon and Chili', 'A vibrant, rapid weeknight meal where the characteristic bitterness of crispy broccoli rabe balances perfectly with sweet, tender shrimp. High-heat roasting creates caramelized edges while garlic, chili flakes, and a final burst of fresh lemon juice provide punchy, bright flavors.', 'dinner', 'Italian-American', 'Easy', '["broccoli rabe", "five ingredient", "shrimp", "dinner", "easy", "lunch", "quick", "main course", "sheet pan", "roasted", "gluten-free"]', '[{"group_name": "Vegetables & Protein", "items": [{"name": "shrimp", "quantity": 340, "unit": "g", "preparation": "peeled and deveined", "notes": "Large (16-20 count) preferred", "substitutions": [], "ingredient_id": "a6bf7ab3-9b88-4c5b-a2fa-966c40a0e5a7", "nutrition_source": "USDA FoodData Central"}, {"name": "broccoli rabe (rapini)", "quantity": 300, "unit": "g", "preparation": "trimmed", "notes": "Discard tough bottom 2cm of stems", "substitutions": [], "ingredient_id": "8229dcea-493c-43eb-b888-737ecd27bcbf", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics & Seasoning", "items": [{"name": "olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": "Divided use", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "thinly sliced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "red pepper flakes", "quantity": 2, "unit": "g", "preparation": null, "notes": "Adjust to heat preference", "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": null, "notes": "Zested and halved for juice", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "Kosher salt preferred", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 220\u00b0C/425\u00b0F. Ensure one rack is in the center position.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Wash the broccoli rabe thoroughly and pat very dry. Trim the tough woody ends (bottom 2-3 cm). If the stalks are very thick, slice them in half lengthwise.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a large bowl, toss the broccoli rabe with 30ml (2 tbsp) of olive oil, the sliced garlic, half of the salt, and the red pepper flakes until well coated.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Spread the broccoli rabe in a single layer on the baking sheet. Roast for 6-8 minutes, or until the leaves begin to crisp and char slightly at the edges.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT7M", "doneness_cues": {"visual": "Leaves crisping, slight char on stems", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "While the rabe roasts, toss the shrimp in the same mixing bowl with the remaining 15ml (1 tbsp) olive oil, lemon zest, and the remaining salt.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Remove the baking sheet from the oven. Push the rabe slightly to the side to create space, or nestle the shrimp among the greens in a single layer. Return to the oven and roast for another 3-5 minutes.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Roast until the shrimp are opaque, pink, and firm, reaching an internal temperature of 63\u00b0C/145\u00b0F. Be careful not to overcook.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": {"visual": "Shrimp opaque and pink", "tactile": "Firm to touch"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from the oven. Immediately squeeze fresh lemon juice over the entire tray. Toss gently to combine juices with the roasted oil and serve immediately.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT10M", "total_time": "PT25M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 350}', '{"flags": ["Gluten-Free", "Dairy-Free", "Pescatarian", "Paleo", "Whole30", "Keto", "Low-Carb", "Egg-Free", "Soy-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": ["Shellfish allergy"]}', '{"per_serving": {"calories": 405.59, "protein_g": 40.1, "carbohydrates_g": 11.93, "fat_g": 24.48, "saturated_fat_g": 3.47, "trans_fat_g": null, "monounsaturated_fat_g": 16.68, "polyunsaturated_fat_g": 3.11, "fiber_g": 5.93, "sugar_g": 1.82, "sodium_mg": 836.88, "cholesterol_mg": 273.7, "potassium_mg": 865.27, "calcium_mg": 301.92, "iron_mg": 4.79, "magnesium_mg": 101.02, "phosphorus_mg": 496.09, "zinc_mg": 3.58, "vitamin_a_mcg": 218, "vitamin_c_mg": 55.93, "vitamin_d_mcg": null, "vitamin_e_mg": 6.05, "vitamin_k_mcg": 352.12, "vitamin_b6_mg": 0.42, "vitamin_b12_mcg": null, "thiamin_mg": 0.28, "riboflavin_mg": 0.23, "niacin_mg": 2.03, "folate_mcg": 130.63, "water_g": 314.61, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Shrimp texture degrades quickly; best consumed immediately.", "duration": "P2D"}, "freezer": {"notes": "Not recommended; vegetables will become soggy.", "duration": null}, "reheating": "Gently saut\u00e9 in a pan over medium heat just until warm to avoid rubbery shrimp.", "does_not_keep": false}', '[{"name": "Large rimmed baking sheet", "required": true, "alternative": "Two smaller baking sheets"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Zester or microplane", "required": false, "alternative": null}]', '[{"symptom": "Broccoli rabe is burnt before shrimp cooks", "likely_cause": "Oven hot spots or rabe leaves were too dry/thin", "prevention": "Add shrimp earlier if rabe looks fragile, or cover rabe with foil when adding shrimp", "fix": "Remove burnt leaves; the stems are likely still good"}, {"symptom": "Shrimp is rubbery", "likely_cause": "Overcooking", "prevention": "Remove shrimp the moment they turn opaque; they cook very fast at high heat", "fix": "Chop up and mix into a grain salad or pasta to mask texture"}]', '["Pat the shrimp very dry with paper towels before tossing with oil; moisture creates steam and prevents that delicious roasted texture.", "If you find broccoli rabe too bitter, you can blanch it in boiling salted water for 1 minute before drying and roasting, though this adds a step and a pot.", "Do not crowd the pan. If scaling up, use two baking sheets. Crowding causes steaming, resulting in soggy greens rather than crispy ones.", "For extra richness, finish with a drizzle of high-quality extra virgin olive oil after plating.", "Sliced garlic roasts better than minced here; minced garlic may burn and turn acrid at these temperatures."]', '"The pairing of bitter greens and shellfish is a hallmark of Southern Italian coastal cuisine, specifically from regions like Puglia where Orecchiette con Cime di Rapa is iconic. This recipe adapts those classic flavors\u2014garlic, chili, and olive oil\u2014into an American sheet-pan format for speed and ease."', 405.59);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('16110568-4ff9-4f63-a618-2ccee5a475e7', 'Orange-Pistachio Glazed Beignets Soufflés', 'Airy, golden-fried choux pastry clouds with a crisp, delicate shell and a hollow interior. Finished with a vibrant blood orange glaze and the crunch of toasted Sicilian pistachios, offering a sophisticated balance of floral citrus notes and nutty richness.', 'dessert', 'French', 'Intermediate', '["pastry", "dessert", "sweet", "fried", "french", "choux"]', '[{"group_name": "Choux Pastry (P\u00e2te \u00e0 Choux)", "items": [{"name": "water", "quantity": 125, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "whole milk", "quantity": 125, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 100, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "caster sugar", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 150, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "large eggs", "quantity": 4, "unit": null, "preparation": "room temperature", "notes": "approx 200-220g total, lightly beaten", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "orange zest", "quantity": 1, "unit": null, "preparation": null, "notes": "finely grated zest of 1 orange", "substitutions": [], "ingredient_id": "c1a067e6-674f-4f68-9fe9-3eda4b074356", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Frying", "items": [{"name": "neutral oil", "quantity": 1500, "unit": "ml", "preparation": null, "notes": "Grapeseed or vegetable oil for deep frying", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}]}, {"group_name": "Orange Pistachio Glaze", "items": [{"name": "icing sugar", "quantity": 200, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh orange juice", "quantity": 45, "unit": "ml", "preparation": null, "notes": "adjust for consistency", "substitutions": [], "ingredient_id": "a15da11d-f8dd-46e3-9ac5-725a7912f1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "orange zest", "quantity": 1, "unit": null, "preparation": null, "notes": "zest of 1 orange", "substitutions": [], "ingredient_id": "c1a067e6-674f-4f68-9fe9-3eda4b074356", "nutrition_source": "Aggregated Public Data"}, {"name": "shelled pistachios", "quantity": 50, "unit": "g", "preparation": "finely chopped", "notes": "toasted", "substitutions": [], "ingredient_id": "59207580-65c8-4564-9467-eb7286b8e5a7", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine water, milk, butter, sugar, salt, and first measure of orange zest in a saucepan over medium heat. Bring to a rolling boil ensuring the butter is fully melted.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": {"visual": "Rolling boil with butter completely melted", "tactile": null}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Remove from heat and immediately dump in all the sifted flour at once. Beat vigorously with a wooden spoon until a dough forms.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Return the pan to medium-low heat. Cook the dough, stirring constantly, until it pulls away from the sides and a thin film forms on the bottom of the pan (drying the panade).", "structured": {"action": "COOK", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Thin film on pan bottom, dough forms a coherent ball", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Transfer dough to a bowl or stand mixer fitted with the paddle attachment. Mix on low speed for 1-2 minutes to cool the dough down to approximately 50\u00b0C/122\u00b0F.", "structured": {"action": "COOL", "temperature": {"celsius": 50, "fahrenheit": 122}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Add the beaten eggs gradually, a small amount at a time, mixing fully between additions. Stop adding eggs when the dough is smooth, glossy, and falls from the spoon in a ''V'' shape.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Dough is glossy and forms a V-shape when dropped from paddle", "tactile": null}}, "tips": ["You might not need all the eggs, or you might need a splash more. Judge by the texture.", "If the dough is too runny, the pastries will not hold their shape."]}, {"step_number": 6, "phase": "cook", "text": "Heat the neutral oil in a heavy pot to 170\u00b0C/340\u00b0F. Carefully pipe or spoon walnut-sized balls of dough into the hot oil. Do not overcrowd.", "structured": {"action": "FRY", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Fry for 6-8 minutes, turning frequently. They will puff up significantly and may crack open slightly. They are done when deep golden brown and feel light and hollow.", "structured": {"action": "FRY", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Deep golden brown color", "tactile": "Light weight, hollow sound when tapped"}}, "tips": ["If they brown too quickly but are raw inside, your oil is too hot.", "They must be fried long enough to dry out the interior structure so they don''t collapse."]}, {"step_number": 8, "phase": "finish", "text": "Remove pastries with a slotted spoon and drain on a wire rack lined with paper towels.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "prep", "text": "While pastries cool slightly, whisk icing sugar, orange juice, and remaining zest in a small bowl until smooth. The glaze should be thick but pourable.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Dip the top of each warm pastry into the glaze, allowing excess to drip off. Immediately sprinkle with chopped pistachios before the glaze sets.", "structured": {"action": "GLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT15M", "total_time": "PT1H", "overnight_required": false, "yields": "24 pastries", "yield_count": 24, "serving_size_g": 45}', '{"flags": ["Vegetarian", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Nut allergies (Pistachios)"]}', '{"per_serving": {"calories": 114.74, "protein_g": 2.34, "carbohydrates_g": 14.7, "fat_g": 5.35, "saturated_fat_g": 2.6, "trans_fat_g": null, "monounsaturated_fat_g": 1.81, "polyunsaturated_fat_g": 0.62, "fiber_g": 0.45, "sugar_g": 9.2, "sodium_mg": 79.68, "cholesterol_mg": 40.48, "potassium_mg": 52.34, "calcium_mg": 15.92, "iron_mg": 0.32, "magnesium_mg": 5.87, "phosphorus_mg": 39.26, "zinc_mg": 0.22, "vitamin_a_mcg": 45.06, "vitamin_c_mg": 1.73, "vitamin_d_mcg": 0.23, "vitamin_e_mg": 0.25, "vitamin_k_mcg": 0.35, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": 0.1, "thiamin_mg": 0.03, "riboflavin_mg": 0.06, "niacin_mg": 0.13, "folate_mcg": 7.7, "water_g": 19.7, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Not recommended; pastry will become soggy.", "duration": null}, "freezer": {"notes": "Freeze unglazed fried pastries. Reheat in oven 180\u00b0C for 5-7 mins.", "duration": "P1M"}, "reheating": "Best eaten fresh. If necessary, reheat unglazed in a 180\u00b0C oven for 3-5 minutes to recrisp.", "does_not_keep": true}', '[{"name": "Heavy-bottomed pot or Dutch oven", "required": true, "alternative": "Deep fryer"}, {"name": "Digital thermometer", "required": true, "alternative": null}, {"name": "Medium saucepan", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": null}, {"name": "Stand mixer or electric hand mixer", "required": false, "alternative": "Strong arm and whisk"}, {"name": "Piping bag with round tip (1cm)", "required": false, "alternative": "Two spoons"}, {"name": "Spider strainer or slotted spoon", "required": true, "alternative": null}, {"name": "Wire rack", "required": true, "alternative": null}]', '[{"symptom": "Pastries deflate shortly after removing from oil", "likely_cause": "Under-fried; the internal moisture wasn''t cooked out enough to set the structure", "prevention": "Fry at a steady 170\u00b0C for the full duration; do not rush the browning process", "fix": "If caught immediately, return to hot oil for 1-2 minutes, though texture may suffer"}, {"symptom": "Pastries are dense and heavy", "likely_cause": "Too much flour or not enough egg incorporated", "prevention": "Ensure the ''V'' drop consistency is achieved during egg addition", "fix": "Cannot be fixed once fried"}]', '["Drying the panade (step 3) is crucial; it gelatinizes the starch and removes excess moisture, allowing the dough to absorb more egg, which creates the steam needed for the puff.", "Use a thermometer for the oil. Choux is sensitive; too cool and it becomes greasy, too hot and it burns before puffing.", "For a more uniform shape, pipe onto small squares of parchment paper and drop the paper into the oil, removing it with tongs once the pastry floats free.", "The contrast between the warm, crispy pastry and the zesty glaze is time-sensitive; serve immediately."]', '"Similar to the French ''Pets de Nonne'' (Nun''s Farts) or Beignets Souffl\u00e9s, these fried choux pastries date back to Renaissance France. While traditional beignets use yeast, choux-based fritters rely on the high moisture content of the dough turning to steam to create their spectacular hollow rise."', 114.74);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('17e72793-f0b2-443d-85c5-8c27b63607ab', 'Vibrant Citrus Napa Slaw', 'A crisp and refreshing salad combining the delicate crunch of Napa cabbage with sweet red bell peppers and savory scallions. The bright citrus dressing, emulsified with high-quality olive oil, brings a zesty finish that cleanses the palate.', 'salad', 'Modern American', 'Easy', '["slaw", "salad", "citrus", "napa cabbage", "red pepper", "quick", "healthy", "vegan", "gluten-free", "winter"]', '[{"group_name": "Vegetables", "items": [{"name": "napa cabbage", "quantity": 400, "unit": "g", "preparation": "shredded", "notes": "approximately half a medium head", "substitutions": [], "ingredient_id": "771c0eca-db4a-4c97-b01d-ee14efc0d3aa", "nutrition_source": "Aggregated Public Data"}, {"name": "red bell pepper", "quantity": 150, "unit": "g", "preparation": "julienned", "notes": "1 large pepper", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "USDA FoodData Central"}, {"name": "scallions", "quantity": 30, "unit": "g", "preparation": "thinly sliced", "notes": "green and white parts", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Citrus Dressing", "items": [{"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "orange juice", "quantity": 30, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "a15da11d-f8dd-46e3-9ac5-725a7912f1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Remove any wilted outer leaves from the Napa cabbage. Cut the head in half lengthwise, remove the core, and shred the leaves into thin strips.", "structured": {"action": "SHRED", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Slice the red bell pepper into thin julienne strips and thinly slice the scallions on a bias.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Combine the shredded cabbage, julienned peppers, and sliced scallions in a large mixing bowl.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In a small bowl, whisk together the lemon juice, orange juice, salt, and pepper. Slowly drizzle in the olive oil while whisking continuously to emulsify.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Ensure ingredients are at room temperature for better emulsification."]}, {"step_number": 5, "phase": "assemble", "text": "Pour the dressing over the vegetables and toss thoroughly to coat. Taste and adjust salt if necessary before serving immediately.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT0M", "total_time": "PT15M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 160}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Low-Carb", "Paleo", "Whole30", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 130.43, "protein_g": 1.8, "carbohydrates_g": 7.01, "fat_g": 11.51, "saturated_fat_g": 1.63, "trans_fat_g": null, "monounsaturated_fat_g": 8.23, "polyunsaturated_fat_g": 1.25, "fiber_g": 1.67, "sugar_g": 3.9, "sodium_mg": 309.09, "cholesterol_mg": null, "potassium_mg": 375.19, "calcium_mg": 53.48, "iron_mg": 0.68, "magnesium_mg": 21.49, "phosphorus_mg": 54.5, "zinc_mg": 0.34, "vitamin_a_mcg": 253.44, "vitamin_c_mg": 79.61, "vitamin_d_mcg": null, "vitamin_e_mg": 2.27, "vitamin_k_mcg": 24.55, "vitamin_b6_mg": 0.12, "vitamin_b12_mcg": null, "thiamin_mg": 0.03, "riboflavin_mg": 0.04, "niacin_mg": 0.44, "folate_mcg": 25.09, "water_g": 146.43, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten fresh; cabbage will soften significantly over time.", "duration": "P1D"}, "freezer": {"notes": "Raw lettuce and cabbage do not freeze well.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": "Fork or jar with lid"}]', '[{"symptom": "Slaw is watery and soggy", "likely_cause": "The slaw sat for too long after dressing; salt drew moisture out of the cabbage", "prevention": "Wait to dress the salad until right before serving", "fix": "Drain the excess liquid from the bottom of the bowl and re-season slightly"}]', '["Napa cabbage is much more delicate than standard green cabbage; slice it slightly thicker (about 0.5cm) to maintain crunch.", "For the red bell pepper, cut on the flesh side rather than the skin side to prevent the knife from slipping.", "This dressing is a basic vinaigrette ratio (3 parts oil to 1 part acid). Since we are using orange juice which is less acidic than lemon, we slightly adjust the ratio to maintain brightness.", "To turn this into a main course, top with grilled tofu or chickpeas for added protein.", "Using freshly squeezed citrus makes a noticeable difference in aroma compared to bottled juice."]', '"While coleslaw is traditionally associated with heavy mayonnaise dressings in American cuisine, this iteration reflects modern Californian influences which prioritize fresh produce and lighter, vinaigrette-based dressings that highlight rather than mask the vegetables."', 130.43);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('1899b247-254d-4e14-a5f0-f0c3b348a068', 'Creamy Chana Dal with Garlic Tadka', 'Yellow split chickpeas simmered to a silky, smooth consistency, infused with turmeric and ginger, then crowned with a sizzling infusion of golden fried garlic, cumin, and blooming spices.', 'dinner', 'Indian', 'Easy', '["indian", "chickpea", "garlic", "spices", "dinner", "weeknight", "vegan", "vegetarian", "dal", "gluten-free"]', '[{"group_name": "Dal Base", "items": [{"name": "chana dal (split chickpeas)", "quantity": 250, "unit": "g", "preparation": "rinsed", "notes": "dry weight", "substitutions": [], "ingredient_id": "b4881fa6-deca-4ed8-9b3e-d7f3e395e1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 1200, "unit": "ml", "preparation": null, "notes": "plus more for soaking", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "ground turmeric", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 0.5 tsp", "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 10, "unit": "g", "preparation": "grated or crushed", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 6, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garlic Tempering (Tadka)", "items": [{"name": "neutral oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": "vegetable, canola, or mustard oil", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "cumin seeds", "quantity": 4, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "thinly sliced", "notes": "about 15-20g total", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "dried red chilies", "quantity": 2, "unit": null, "preparation": "whole", "notes": null, "substitutions": [], "ingredient_id": "a4bf8b34-30b2-4d24-a120-b5b191811f64", "nutrition_source": "Aggregated Public Data"}, {"name": "asafoetida (hing)", "quantity": 0.5, "unit": "g", "preparation": null, "notes": "generous pinch; essential for digestion", "substitutions": [], "ingredient_id": "57634c8d-8f26-4aa9-873a-eb84d045e7c4", "nutrition_source": "Aggregated Public Data"}, {"name": "kashmiri chili powder", "quantity": 2, "unit": "g", "preparation": null, "notes": "for color, mild heat", "substitutions": [], "ingredient_id": "a5db2139-313d-49e3-8b1c-2c84839faf83", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Finishing", "items": [{"name": "fresh coriander (cilantro)", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "8c7693be-b538-445c-80f9-3d5bf4c6dcc0", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": "approx half a lemon", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Rinse the chana dal under cold running water until the water runs clear. Soak in a bowl of fresh water for at least 30 minutes (helps soften the dense legume). Drain before cooking.", "structured": {"action": "SOAK", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Combine the drained dal, 1.2 liters of water, grated ginger, salt, and turmeric in a large heavy-bottomed pot. Bring to a boil over high heat, skim off any white foam (scum) that rises to the surface, then reduce heat to low. Cover and simmer gently until the lentils are completely soft and falling apart, about 45-60 minutes.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT50M", "doneness_cues": {"visual": "Lentils falling apart", "tactile": "Mashes easily against roof of mouth"}}, "tips": ["If using a pressure cooker: Cook on high pressure for 12-15 minutes, then allow natural release."]}, {"step_number": 3, "phase": "finish", "text": "Once cooked, remove from heat. Use an immersion blender to puree the dal directly in the pot until smooth and creamy. If you prefer some texture, pulse only a few times. Return to low heat to keep warm. Stir in the lemon juice if using.", "structured": {"action": "PUREE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Velvety smooth yellow consistency", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Prepare the tempering (tadka): Heat the oil in a small pan over medium-high heat. Add the dried red chilies and cumin seeds. Once the cumin crackles (about 30 seconds), add the sliced garlic. Fry until the garlic turns golden brown.", "structured": {"action": "FRY", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT2M", "doneness_cues": {"visual": "Garlic is golden brown", "tactile": "Spices are fragrant"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Turn off the heat under the small pan immediately. Stir in the asafoetida and Kashmiri chili powder (turning off the heat prevents burning the powder). Immediately pour the sizzling oil mixture over the pureed dal.", "structured": {"action": "TEMPER", "temperature": null, "duration": "PT10S", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Garnish with fresh chopped coriander and serve hot.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT45M", "total_time": "PT1H", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 300}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 323.51, "protein_g": 13.3, "carbohydrates_g": 33.72, "fat_g": 13.92, "saturated_fat_g": 1.66, "trans_fat_g": null, "monounsaturated_fat_g": 0.15, "polyunsaturated_fat_g": 0.05, "fiber_g": 6.79, "sugar_g": 0.29, "sodium_mg": 629.94, "cholesterol_mg": null, "potassium_mg": 644.05, "calcium_mg": 122.78, "iron_mg": 6.85, "magnesium_mg": 101.19, "phosphorus_mg": 333.7, "zinc_mg": 3.03, "vitamin_a_mcg": 3469.97, "vitamin_c_mg": 9.57, "vitamin_d_mcg": null, "vitamin_e_mg": 0.08, "vitamin_k_mcg": 0.23, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": null, "thiamin_mg": 0.02, "riboflavin_mg": 0.01, "niacin_mg": 0.11, "folate_mcg": 1.4, "water_g": 310.26, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Thicken significantly when cool; loosen with a splash of hot water when reheating.", "duration": "P4D"}, "freezer": {"notes": "Freezes excellently in airtight containers.", "duration": "P3M"}, "reheating": "Reheat on the stovetop over low heat, adding water to reach desired consistency.", "does_not_keep": false}', '[{"name": "Large heavy-bottomed pot", "required": true, "alternative": "Pressure cooker"}, {"name": "Immersion blender", "required": true, "alternative": "Standard blender or whisk"}, {"name": "Small frying pan or Tadka ladle", "required": true, "alternative": null}, {"name": "Fine mesh sieve", "required": true, "alternative": null}]', '[{"symptom": "Dal is taking forever to soften", "likely_cause": "The lentils are old or the water is hard/acidic", "prevention": "Soak longer (overnight) or use filtered water", "fix": "Add a pinch of baking soda (approx 1g) to the boiling water to accelerate softening"}, {"symptom": "Burnt taste in the tempering", "likely_cause": "Oil was too hot when adding garlic or spices", "prevention": "Have all spices measured and ready; remove pan from heat immediately if it smokes", "fix": "Discard the tempering oil and start that step again (do not pour it into the dal)"}]', '["The secret to a great tadka (tempering) is taking the garlic to the very edge of golden-brown without burning it; this provides a savory, almost meat-like depth.", "Asafoetida (Hing) smells pungent raw but mellows into an onion-leek flavor when fried; it is crucial for authentic Indian flavor and aids digestion of legumes.", "If the puree becomes too thick upon standing, whisk in 50-100ml of boiling water to restore the velvety consistency.", "For a richer finish, you can use vegan butter or ghee (if not vegan) instead of neutral oil for the tempering."]', '"This dish is a variation of ''Dal Tadka'', a staple comfort food across India. Chana Dal (split brown chickpeas) is prized for its low glycemic index and nutty flavor. Pureeing the dal is common in certain regions to create a soup-like consistency that coats rice or dips well with flatbreads."', 323.51);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('18fed3ba-fb3f-40e8-a3a1-51e399cad708', 'Sichuan Red Oil Pork Wontons (Hong You Chao Shou)', 'Silky, delicate wonton wrappers filled with juicy, bouncy pork, bathed in a complex sauce of aromatic chili oil, numbing Sichuan peppercorns, black vinegar, and garlic. The dish balances heat, savoriness, slight sweetness, and a tingling sensation.', 'appetizer', 'Chinese', 'Intermediate', '["chinese", "sichuan", "appetizer", "spicy", "dumplings", "chile paste", "sichuan peppercorn"]', '[{"group_name": "Wonton Filling", "items": [{"name": "ground pork", "quantity": 250, "unit": "g", "preparation": "fatty (approx 30% fat)", "notes": "lean pork results in dry wontons", "substitutions": [], "ingredient_id": "95b412ba-c68f-4b61-ae87-42b44000956b", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 10, "unit": "g", "preparation": "finely grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "scallions", "quantity": 2, "unit": null, "preparation": "finely minced (white and light green parts)", "notes": "approx 15g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "shaoxing wine", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["dry sherry"], "ingredient_id": "bb7adcb8-7e07-46ec-a3ac-e02f9ffb6f9f", "nutrition_source": "Aggregated Public Data"}, {"name": "light soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0f7f45d7-9cfa-49f9-b60e-5db3fa280254", "nutrition_source": "Aggregated Public Data"}, {"name": "white pepper powder", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "sesame oil", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a9a59164-d949-4acd-99da-689f0a32e2e7", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 45, "unit": "ml", "preparation": null, "notes": "ice cold", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Wrappers", "items": [{"name": "wonton wrappers", "quantity": 30, "unit": null, "preparation": "square, thin", "notes": "approx 250g pack", "substitutions": [], "ingredient_id": "309430c5-0bb0-47f4-92c9-768f163f5799", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 50, "unit": "ml", "preparation": "for sealing", "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Sichuan Red Oil Sauce", "items": [{"name": "sichuan chili oil with sediment", "quantity": 60, "unit": "ml", "preparation": null, "notes": "adjust to spice preference, ensure plenty of chili flakes/paste are included", "substitutions": [], "ingredient_id": "31637e18-796b-464f-a599-08e4a007f4e5", "nutrition_source": "Aggregated Public Data"}, {"name": "chinkiang vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": "black vinegar", "substitutions": ["balsamic vinegar mixed with rice vinegar"], "ingredient_id": "fcbf5252-1be9-4dd4-8c22-4fda1dbdca28", "nutrition_source": "Aggregated Public Data"}, {"name": "light soy sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0f7f45d7-9cfa-49f9-b60e-5db3fa280254", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "finely minced", "notes": "approx 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "sugar", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "sichuan peppercorn powder", "quantity": 2, "unit": "g", "preparation": null, "notes": "freshly toasted and ground is best", "substitutions": [], "ingredient_id": "b0a74768-ec94-44d0-a92a-99581cb5d2c0", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Garnish", "items": [{"name": "scallions", "quantity": 1, "unit": null, "preparation": "sliced (green parts)", "notes": "approx 10g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "toasted sesame seeds", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36a7664a-f96c-44b9-9b6d-cdd5e9e54f55", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a large bowl, combine the ground pork, grated ginger, minced scallions (whites), Shaoxing wine, soy sauce, white pepper, cornstarch, and sesame oil. Mix briefly to combine.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Add the ice-cold water to the pork mixture. Using your hand or chopsticks, whip the mixture vigorously in one direction until all liquid is absorbed and the meat becomes a sticky, pale paste with a bouncy texture (approximately 3-5 minutes). This emulsification is crucial for juicy wontons.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Pale color, fibers pulling together", "tactile": "Sticky and paste-like"}}, "tips": []}, {"step_number": 3, "phase": "assemble", "text": "Place a wonton wrapper in your palm. Place 1 teaspoon (approx 8-10g) of filling in the center. Moisten the edges with water. Fold in half into a rectangle or triangle, pressing out air. Bring the two bottom corners together, moisten one corner, and pinch them firmly to overlap, creating an ingot shape.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In a separate small bowl, whisk together the chili oil (with sediment), Chinkiang vinegar, soy sauce, minced garlic, sugar, and Sichuan peppercorn powder until the sugar is dissolved.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Bring a large pot of water to a rolling boil. Gently lower the wontons into the water. Stir gently with a utensil to prevent sticking to the bottom.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "When the water returns to a boil, reduce heat slightly to maintain a simmer. Cook until the wontons float completely to the surface and the wrappers are translucent, about 3-4 minutes. Ensure the internal temperature of the pork reaches at least 74\u00b0C/165\u00b0F.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Floating and translucent wrappers", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Drain the wontons well using a spider strainer and transfer immediately to a serving bowl. Pour the sauce over the hot wontons. Toss gently to coat.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Garnish with sliced scallion greens and toasted sesame seeds. Serve immediately.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT15M", "total_time": "PT1H", "overnight_required": false, "yields": "30 wontons", "yield_count": 4, "serving_size_g": 150}', '{"flags": ["Dairy-Free", "Nut-Free"], "not_suitable_for": ["Vegetarians", "Vegans", "Gluten-Free"]}', '{"per_serving": {"calories": 536.37, "protein_g": 18.3, "carbohydrates_g": 44.63, "fat_g": 31.05, "saturated_fat_g": 9.11, "trans_fat_g": null, "monounsaturated_fat_g": 6.04, "polyunsaturated_fat_g": 1.6, "fiber_g": 2.04, "sugar_g": 4.5, "sodium_mg": 1016.51, "cholesterol_mg": 50.63, "potassium_mg": 278.64, "calcium_mg": 65.05, "iron_mg": 3.07, "magnesium_mg": 32.6, "phosphorus_mg": 172.45, "zinc_mg": 1.92, "vitamin_a_mcg": 6.88, "vitamin_c_mg": 36.11, "vitamin_d_mcg": null, "vitamin_e_mg": 0.05, "vitamin_k_mcg": 12.99, "vitamin_b6_mg": 0.31, "vitamin_b12_mcg": 0.45, "thiamin_mg": 0.79, "riboflavin_mg": 0.39, "niacin_mg": 6.17, "folate_mcg": 61.29, "water_g": 89.44, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store cooked wontons separately from sauce if possible to prevent sogginess. Uncooked folded wontons can be refrigerated for 24 hours.", "duration": "P2D"}, "freezer": {"notes": "Freeze uncooked wontons in a single layer on a tray before transferring to a bag.", "duration": "P1M"}, "reheating": "Boil fresh or frozen wontons until floating. If already cooked, steam gently or microwave with a splash of water.", "does_not_keep": false}', '[{"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Large pot", "required": true, "alternative": null}, {"name": "Spider strainer or slotted spoon", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Microplane or fine grater", "required": true, "alternative": "Knife for mincing"}]', '[{"symptom": "Wontons burst open during boiling", "likely_cause": "Edges were not sealed properly or too much air was trapped inside", "prevention": "Use enough water on the edges and press firmly; press out air pockets around the meat before sealing", "fix": "Remove broken wontons immediately; the filling is still edible as a soup component"}, {"symptom": "Filling feels tough or rubbery", "likely_cause": "Meat was too lean or not enough water was beaten into the mixture", "prevention": "Use pork with at least 20-30% fat and do not skip the water addition step", "fix": "Cannot be fixed after cooking"}]', '["The secret to restaurant-quality wontons is the ''bounciness'' (Q-texture) of the filling. This is achieved by vigorously stirring water into the meat until it becomes a sticky emulsion.", "Do not overcrowd the pot when boiling. If cooking a large batch, do it in rounds to keep the water temperature stable.", "If you cannot find Chinkiang (black) vinegar, a mix of half balsamic and half rice vinegar is a passable substitute, though the authentic flavor profile relies on the smoky depth of the black vinegar.", "For the sauce, use a chili oil that contains ''sediment'' (crushed chili flakes) at the bottom of the jar for the best texture and heat."]', '"Originating from Sichuan province, this dish is known as ''Hong You Chao Shou'' (Red Oil Wontons). The name ''Chao Shou'' literally means ''folded hands,'' resembling the shape of the folded wonton or arms crossed in winter for warmth. Unlike Cantonese wontons which focus on a clear savory broth, these are defined by the bold, numbing-hot sauce."', 536.37);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('19d22fc6-33f9-4a27-963c-447c9cc76426', 'Pan-Seared Mackerel with Tangy Rhubarb Chutney', 'Crispy skin-on mackerel fillets rich in healthy oils, balanced perfectly by a sharp, sweet-and-sour rhubarb chutney and a peppery watercress salad. A celebration of seasonal contrast.', 'dinner', 'Modern British', 'Intermediate', '["mackerel", "rhubarb", "chutney", "salad", "fish", "seasonal", "british"]', '[{"group_name": "Rhubarb Chutney", "items": [{"name": "rhubarb", "quantity": 300, "unit": "g", "preparation": "chopped into 2cm pieces", "notes": null, "substitutions": [], "ingredient_id": "293d2132-013e-4594-801e-4d86e1d04df0", "nutrition_source": "USDA FoodData Central"}, {"name": "red onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx. 100g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "apple cider vinegar", "quantity": 80, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "light brown sugar", "quantity": 70, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 10, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "mustard seeds", "quantity": 3, "unit": "g", "preparation": null, "notes": "yellow seeds preferred", "substitutions": [], "ingredient_id": "69e2b7a1-7252-486e-841e-51655b028a97", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Mackerel", "items": [{"name": "mackerel fillets", "quantity": 4, "unit": null, "preparation": "skin-on, pin-boned", "notes": "approx. 120g each", "substitutions": [], "ingredient_id": "df215e79-f9d3-427b-a756-702f82997da2", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "flaky sea salt preferred", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly ground, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Salad", "items": [{"name": "watercress", "quantity": 80, "unit": "g", "preparation": "washed and dried", "notes": null, "substitutions": ["arugula", "rocket"], "ingredient_id": "1dc62ebd-8219-4e5a-b5f8-a9f3ca48971e", "nutrition_source": "USDA FoodData Central"}, {"name": "radishes", "quantity": 4, "unit": null, "preparation": "thinly sliced", "notes": "approx. 30g", "substitutions": [], "ingredient_id": "2d6f93d3-117b-49ab-9e11-1058462db7ce", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "036c7254-3de5-4c6e-a2e7-366ad4d05077", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine the diced red onion, grated ginger, mustard seeds, sugar, and vinegar in a heavy-bottomed saucepan.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Bring the mixture to a simmer over medium heat and cook for 5 minutes until the onion softens.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the chopped rhubarb. Continue to simmer gently for 10-15 minutes until the rhubarb breaks down and the mixture thickens to a jam-like consistency. Remove from heat and let cool.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": "Thick, glossy, rhubarb has broken down", "tactile": "Jam-like consistency"}}, "tips": ["Do not overstir once rhubarb is added if you prefer some chunks to remain."]}, {"step_number": 4, "phase": "prep", "text": "Pat the mackerel fillets thoroughly dry with paper towels. Using a sharp knife, make 3 shallow diagonal scores in the skin of each fillet to prevent curling.", "structured": {"action": "SCORE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Moisture is the enemy of crispy skin; ensure the skin is very dry."]}, {"step_number": 5, "phase": "cook", "text": "Season the fish generously with salt and pepper. Heat olive oil in a large non-stick frying pan over medium-high heat until shimmering.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Place fillets skin-side down in the pan. Press down gently with a spatula for 10 seconds to ensure even contact. Cook without moving for 3-4 minutes until the skin is golden and crispy, and the flesh is opaque 2/3 of the way up.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Skin is crispy brown, flesh turning white from bottom up", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Flip the fillets and cook for 30-60 seconds on the flesh side until just cooked through. The internal temperature should reach approx 60\u00b0C/140\u00b0F.", "structured": {"action": "SEAR", "temperature": {"celsius": 60, "fahrenheit": 140}, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "In a mixing bowl, toss watercress and sliced radishes with lemon juice and extra virgin olive oil. Season lightly with salt.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Plate the salad, place a mackerel fillet alongside (skin-side up to maintain crispiness), and spoon a generous amount of rhubarb chutney on the side.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT15M", "total_time": "PT50M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 303.67, "protein_g": 26.19, "carbohydrates_g": 25.65, "fat_g": 10.48, "saturated_fat_g": 1.55, "trans_fat_g": null, "monounsaturated_fat_g": 3.74, "polyunsaturated_fat_g": 1.09, "fiber_g": 2.41, "sugar_g": 20.07, "sodium_mg": 399.79, "cholesterol_mg": 63.6, "potassium_mg": 975.98, "calcium_mg": 144.37, "iron_mg": 2.89, "magnesium_mg": 62.91, "phosphorus_mg": 336.19, "zinc_mg": 0.88, "vitamin_a_mcg": 334.69, "vitamin_c_mg": 25.77, "vitamin_d_mcg": null, "vitamin_e_mg": 0.91, "vitamin_k_mcg": 133.65, "vitamin_b6_mg": 0.65, "vitamin_b12_mcg": 18.72, "thiamin_mg": 0.16, "riboflavin_mg": 0.66, "niacin_mg": 10.83, "folate_mcg": 38.51, "water_g": 231.8, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Fish is best eaten immediately; chutney keeps for 2 weeks.", "duration": "P2D"}, "freezer": {"notes": "Do not freeze cooked fish.", "duration": null}, "reheating": "Serve fish fresh. Chutney can be served room temperature or warm.", "does_not_keep": false}', '[{"name": "Heavy-bottomed saucepan", "required": true, "alternative": null}, {"name": "Large non-stick frying pan", "required": true, "alternative": null}, {"name": "Sharp knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Fish spatula", "required": false, "alternative": "Standard flexible spatula"}, {"name": "Mixing bowl", "required": true, "alternative": null}]', '[{"symptom": "Fish skin is soggy", "likely_cause": "Fish was not dried enough before cooking or pan was not hot enough", "prevention": "Pat skin bone-dry and wait for oil to shimmer before adding fish", "fix": "Cannot be fully fixed, but you can try searing briefly under a high broiler/grill"}, {"symptom": "Chutney is too runny", "likely_cause": "Not reduced long enough or rhubarb was very watery", "prevention": "Simmer longer until a trail remains when a spoon is dragged through", "fix": "Return to heat and reduce further"}]', '["Mackerel is an oily fish, which is why it pairs so beautifully with acidic ingredients like rhubarb and vinegar\u2014the acid cuts through the richness.", "If you cannot find fresh rhubarb, frozen works well; you may just need to reduce the chutney a few minutes longer.", "Always sear mackerel skin-side down for 80-90% of the cooking time. The flesh side needs very little heat."]', '"This pairing is a staple of modern British cuisine, utilizing the abundant seasonal catch of the Atlantic mackerel and the tart brightness of garden rhubarb, traditionally harvested in early spring to coincide with the return of the fish."', 303.67);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('1a8888bc-e433-4129-a54c-0a8a70529600', 'Rustic Rosemary Lamb & Parsnip Hotpot', 'A comforting one-pot British classic featuring tender chunks of lamb shoulder braised in a rich, rosemary-infused gravy with sweet parsnips. The dish is crowned with overlapping slices of golden, crispy potatoes that absorb the savory steam from below.', 'dinner', 'British', 'Intermediate', '["lamb", "hotpot", "rosemary", "parsnip", "potato", "one-pan", "british", "comfort food"]', '[{"group_name": "Lamb & Aromatics", "items": [{"name": "lamb shoulder", "quantity": 600, "unit": "g", "preparation": "diced into 3cm cubes", "notes": "Neck fillet also works well", "substitutions": ["lamb leg (requires less cooking time)", "beef chuck"], "ingredient_id": "27672021-dc31-45a5-9ce8-f08dbbae93b4", "nutrition_source": "Aggregated Public Data"}, {"name": "all-purpose flour", "quantity": 30, "unit": "g", "preparation": null, "notes": "For dusting", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 30, "unit": "ml", "preparation": "divided", "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "onion", "quantity": 2, "unit": null, "preparation": "sliced", "notes": "yellow or white, approx 300g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "parsnips", "quantity": 300, "unit": "g", "preparation": "peeled and sliced into 2cm rounds", "notes": null, "substitutions": [], "ingredient_id": "34436869-220b-4f51-85a9-71ea344acc17", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Gravy", "items": [{"name": "lamb stock", "quantity": 500, "unit": "ml", "preparation": "hot", "notes": null, "substitutions": ["chicken stock", "beef stock"], "ingredient_id": "f5c5df56-a96c-411b-8262-31b2585a4b2a", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh rosemary", "quantity": 2, "unit": null, "preparation": "sprigs", "notes": "keep whole for easy removal", "substitutions": [], "ingredient_id": "fa90a3a7-86cd-40de-8f8c-0464231925c2", "nutrition_source": "USDA FoodData Central"}, {"name": "worcestershire sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "aa552099-60a9-4267-a732-5870a271c28f", "nutrition_source": "Aggregated Public Data"}, {"name": "bay leaf", "quantity": 1, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Potato Crust", "items": [{"name": "waxy potatoes", "quantity": 700, "unit": "g", "preparation": "peeled and thinly sliced (3mm)", "notes": "Maris Piper, Yukon Gold, or Desiree", "substitutions": [], "ingredient_id": "de37c496-907a-4970-9fa2-09f3bb7a9595", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "melted", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": "to taste", "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 160\u00b0C (320\u00b0F) fan-assisted or 180\u00b0C (350\u00b0F) conventional. Prepare the potatoes by peeling and slicing them into thin, uniform rounds about 3mm thick. Keep them submerged in cold water until needed to prevent browning.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Toss the diced lamb shoulder with the flour, a generous pinch of salt, and pepper in a bowl until the meat is evenly coated.", "structured": {"action": "DREDGE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat half the vegetable oil in a large oven-proof pot (Dutch oven) over medium-high heat. Sear the lamb in batches until well-browned on all sides. Remove the browned lamb and set aside on a plate.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": {"visual": "Deep golden brown crust on meat", "tactile": "Meat releases easily from pan"}}, "tips": ["Do not overcrowd the pan, or the lamb will steam instead of sear."]}, {"step_number": 4, "phase": "cook", "text": "Add the remaining oil to the same pot. Add the sliced onions and parsnips. Saut\u00e9 for 5-6 minutes over medium heat until the onions are softened and picking up the fond (browned bits) from the bottom of the pot.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT6M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Stir in the minced garlic and cook for 1 minute until fragrant. Pour in a splash of the stock to deglaze the pan, scraping up any stuck bits with a wooden spoon.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Return the browned lamb (and any resting juices) to the pot. Add the remaining stock, Worcestershire sauce, rosemary sprigs, and bay leaf. Bring to a gentle simmer, then remove from heat.", "structured": {"action": "SIMMER", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Drain the potato slices and pat them dry completely. Arrange the potatoes over the meat and vegetables in a circular, overlapping pattern (like fish scales) until the top is fully covered.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Brush the potato layer with the melted butter and season with salt and pepper. Cover the pot with a lid and bake in the oven for 60 minutes.", "structured": {"action": "BAKE", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove the lid and increase the oven temperature to 200\u00b0C (400\u00b0F). Bake for another 30-40 minutes until the potatoes are golden brown and crisp, and the lamb is tender.", "structured": {"action": "ROAST", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT40M", "doneness_cues": {"visual": "Potatoes are golden and crispy", "tactile": "Knife slides into meat with no resistance"}}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Let the hotpot rest for 10 minutes before serving to allow the juices to settle and thicken slightly. Serve hot.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT1H45M", "total_time": "PT2H20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Nut-Free", "Peanut-Free"], "not_suitable_for": ["Celery allergy (if in stock)", "Gluten intolerance (contains flour)"]}', '{"per_serving": {"calories": 614.05, "protein_g": 40.04, "carbohydrates_g": 57.68, "fat_g": 26.14, "saturated_fat_g": 7.95, "trans_fat_g": null, "monounsaturated_fat_g": 1.86, "polyunsaturated_fat_g": 0.43, "fiber_g": 9, "sugar_g": 10.22, "sodium_mg": 596.78, "cholesterol_mg": 16.13, "potassium_mg": 1370.42, "calcium_mg": 79.07, "iron_mg": 3.07, "magnesium_mg": 79.6, "phosphorus_mg": 275.62, "zinc_mg": 3.37, "vitamin_a_mcg": 52.77, "vitamin_c_mg": 35.08, "vitamin_d_mcg": null, "vitamin_e_mg": 1.34, "vitamin_k_mcg": 23.68, "vitamin_b6_mg": 0.51, "vitamin_b12_mcg": 0.01, "thiamin_mg": 0.26, "riboflavin_mg": 0.12, "niacin_mg": 2.76, "folate_mcg": 98.65, "water_g": 272.74, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Potato crust may lose crispness; reheat in oven to restore texture.", "duration": "P3D"}, "freezer": {"notes": "Freeze without the potato topping if possible, or expect softer potatoes upon thawing.", "duration": "P2M"}, "reheating": "Reheat in a 180\u00b0C/350\u00b0F oven for 20-30 minutes until bubbling.", "does_not_keep": false}', '[{"name": "Dutch oven or heavy oven-proof pot with lid", "required": true, "alternative": "Deep casserole dish + skillet"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Mandoline or sharp knife", "required": true, "alternative": "Food processor with slicing disk"}, {"name": "Pastry brush", "required": false, "alternative": null}]', '[{"symptom": "Potatoes are sinking into the gravy", "likely_cause": "Too much liquid or potatoes sliced too small/randomly", "prevention": "Ensure potatoes overlap significantly; liquid level should just cover the meat, not the potatoes", "fix": "Carefully spoon out a little liquid if accessible, or add another layer of potatoes on top"}, {"symptom": "Meat is tough", "likely_cause": "Under-cooked; collagen hasn''t broken down", "prevention": "Ensure the initial 60-minute cook is done at a steady simmer/bake", "fix": "Cover again and return to oven at 160\u00b0C/320\u00b0F for another 30 minutes"}]', '["Uniformity is key for the potato topping. Using a mandoline ensures every slice cooks at the same rate and creates a professional finish.", "Lamb shoulder is preferred over leg because the higher fat and connective tissue content keeps it moist during the long braise.", "For extra depth, you can render a little diced bacon or pancetta with the onions in step 4.", "Drying the potato slices before arranging them is crucial for crispiness; wet potatoes will steam and become soggy."]', '"Originating from Lancashire in North West England, this hotpot was traditionally left to bake slowly all day while mill workers were on their shifts. It differs from other casseroles by using sliced potatoes rather than pastry for the lid, a nod to the region''s agricultural history."', 614.05);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('1a9fd972-0ffe-43c7-ae51-5162216a4ed3', 'Cumin & Coriander Crusted Barnsley Chops with Citrus', 'Thick-cut double loin lamb chops encrusted with warm, toasted earth spices. The rich, rendered fat is cut sharply by fresh lemon juice and floral orange zest, creating a sophisticated balance of savory and bright flavors.', 'dinner', 'Modern British', 'Intermediate', '["lamb", "chops", "spiced", "pan-fried", "quick", "british", "dinner", "date night", "high protein"]', '[{"group_name": "Lamb", "items": [{"name": "barnsley chops", "quantity": 2, "unit": null, "preparation": "room temperature", "notes": "approx. 300g each, thick cut", "substitutions": [], "ingredient_id": "fda3a5df-8a66-4233-ad64-f7ca20fa1a26", "nutrition_source": "Aggregated Public Data"}, {"name": "grapeseed oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "or other high smoke point oil", "substitutions": [], "ingredient_id": "00f43166-1b77-4e77-9e30-e912a59d118a", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Spice Crust", "items": [{"name": "cumin seeds", "quantity": 4, "unit": "g", "preparation": null, "notes": "whole", "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "coriander seeds", "quantity": 3, "unit": "g", "preparation": null, "notes": "whole", "substitutions": [], "ingredient_id": "9565bf3d-0e00-453f-8d46-4bcf0228680e", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt flakes", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black peppercorns", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "lemon", "quantity": 1, "unit": null, "preparation": "halved", "notes": "for juice", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "orange", "quantity": 1, "unit": null, "preparation": null, "notes": "for zest only", "substitutions": [], "ingredient_id": "c1a067e6-674f-4f68-9fe9-3eda4b074356", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place a dry frying pan over medium heat. Add cumin and coriander seeds and toast for 1-2 minutes until fragrant and slightly darkened. Remove immediately to stop cooking.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Seeds darken slightly", "tactile": "Aromatic"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Transfer toasted seeds and black peppercorns to a mortar and pestle. Crush coarsely\u2014do not grind to a fine powder; you want texture. Mix in the sea salt flakes.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": {"visual": "Coarse, cracked seeds", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Pat the lamb chops very dry with paper towels. Score the fat band vertically every 1cm to prevent curling. Press the spice mixture firmly onto all sides of the meat.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Heat the oil in the frying pan over medium heat. Using tongs, stand the chops vertically on their fat edge. Cook for 3-4 minutes to render the fat and crisp the skin.", "structured": {"action": "RENDER", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": "PT4M", "doneness_cues": {"visual": "Fat is golden and crispy", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Lay the chops flat. Sear for 3-4 minutes on the first side until a deep golden crust forms. Avoid moving them unnecessarily to maintain the spice crust.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Flip the chops. Add the cubed butter to the pan. Once foamy, tilt the pan and spoon the hot butter over the chops continuously (basting) for another 3-4 minutes.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Butter is foaming and nutty", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Check internal temperature. Remove chops when they reach 52\u00b0C (125\u00b0F) for medium-rare or 57\u00b0C (135\u00b0F) for medium. The temperature will rise during resting.", "structured": {"action": "MEASURE", "temperature": {"celsius": 54, "fahrenheit": 129}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Transfer chops to a warm plate and rest for at least 8 minutes. Just before serving, squeeze fresh lemon juice over the meat and grate fresh orange zest generously over the top.", "structured": {"action": "REST", "temperature": null, "duration": "PT8M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT10M", "total_time": "PT35M", "overnight_required": false, "yields": "2 chops", "yield_count": 2, "serving_size_g": 280}', '{"flags": ["Gluten-Free", "Low-Carb", "Keto", "Paleo", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 1199.81, "protein_g": 65.8, "carbohydrates_g": 8.37, "fat_g": 101.85, "saturated_fat_g": 42.26, "trans_fat_g": 4.32, "monounsaturated_fat_g": 27.06, "polyunsaturated_fat_g": 8.87, "fiber_g": 2, "sugar_g": 1.13, "sodium_mg": 1195.16, "cholesterol_mg": 275.25, "potassium_mg": 1057.44, "calcium_mg": 136.54, "iron_mg": 6.58, "magnesium_mg": 79.47, "phosphorus_mg": 604.65, "zinc_mg": 8.74, "vitamin_a_mcg": 162.26, "vitamin_c_mg": 27.1, "vitamin_d_mcg": 0.3, "vitamin_e_mg": 4.28, "vitamin_k_mcg": 2.8, "vitamin_b6_mg": 0.51, "vitamin_b12_mcg": 4.59, "thiamin_mg": 0.34, "riboflavin_mg": 0.56, "niacin_mg": 15.87, "folate_mcg": 6.47, "water_g": 193.2, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Reheat gently to avoid overcooking.", "duration": "P3D"}, "freezer": {"notes": "Texture may degrade upon thawing; fresh preparation is highly recommended.", "duration": "P2M"}, "reheating": "Reheat in a 150\u00b0C oven covered with foil until warmed through.", "does_not_keep": false}', '[{"name": "Heavy-bottomed frying pan", "required": true, "alternative": "Cast iron skillet"}, {"name": "Mortar and pestle", "required": true, "alternative": "Spice grinder or rolling pin"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Instant-read thermometer", "required": true, "alternative": null}, {"name": "Microplane or fine grater", "required": true, "alternative": null}]', '[{"symptom": "Spices are burnt and bitter", "likely_cause": "Pan was too hot when searing or spices were ground too fine", "prevention": "Use medium-high heat rather than high; keep spice grind coarse", "fix": "Scrape off the burnt crust and add fresh zest/salt"}, {"symptom": "Fat is chewy and white", "likely_cause": "Fat cap was not rendered long enough before searing the meat", "prevention": "Spend extra time standing the chop on its edge at the beginning", "fix": "Sear just the fat edge again briefly before serving"}]', '["Temper the meat: Take the chops out of the fridge 45 minutes before cooking to ensure even cooking.", "The Barnsley chop is a double-loin cut, meaning it is thicker than a standard chop. Basting with butter is essential to cook the center gently without burning the spice crust.", "Do not skip the orange zest; the oils in the zest bind with the coriander seeds to create a flavor profile similar to Belgian wheat beer, which cuts through the gaminess of the lamb.", "Resting is non-negotiable for this cut. If you cut into it immediately, the juices will run out and the meat will be dry.", "If the chops are exceptionally thick (over 4cm), you may need to finish them in a 180\u00b0C oven for 5 minutes after searing."]', '"The Barnsley chop originates from the mining town of Barnsley in Yorkshire, dating back to the mid-19th century. It serves as a hearty meal intended for hungry workers. This recipe modernizes the classic British cut with aromatic spices that nod to the historical spice trade routes influencing modern British cuisine."', 1199.81);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('1b80b189-9519-4b8c-8df4-01e8a5734e2c', 'Summer Watermelon & Heirloom Panzanella', 'A vibrant Southern twist on the Italian classic, featuring crisp toasted ciabatta soaking up the juices of sweet watermelon and savory heirloom tomatoes. The dish is unified by a bright, emulsified watermelon vinaigrette and finished with aromatic fresh basil.', 'salad', 'American', 'Easy', '["southern", "basil", "ciabatta", "cucumber", "heirloom tomato", "salad", "watermelon", "dinner", "lunch", "summer", "vegetarian"]', '[{"group_name": "Bread Base", "items": [{"name": "ciabatta bread", "quantity": 300, "unit": "g", "preparation": "cut into 2.5cm cubes", "notes": "Day-old bread works best", "substitutions": [], "ingredient_id": "9ca7b694-691f-4fb4-ac85-960ab71c8c9e", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "for coating bread", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "for seasoning bread", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Produce", "items": [{"name": "seedless watermelon", "quantity": 500, "unit": "g", "preparation": "cubed (2.5cm)", "notes": "Reserve 100g specifically for dressing", "substitutions": [], "ingredient_id": "c03dfaed-fb45-413c-84e7-4e2d267ed7b8", "nutrition_source": "USDA FoodData Central"}, {"name": "heirloom tomatoes", "quantity": 500, "unit": "g", "preparation": "cut into wedges or large chunks", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "cucumber", "quantity": 200, "unit": "g", "preparation": "sliced into half-moons", "notes": null, "substitutions": [], "ingredient_id": "457adec2-3e06-4efe-a26e-9e6ea9f84924", "nutrition_source": "USDA FoodData Central"}, {"name": "red onion", "quantity": 60, "unit": "g", "preparation": "very thinly sliced", "notes": "about 1/4 large onion", "substitutions": [], "ingredient_id": "1c270c6e-0acc-4c5c-9935-7eff3240fc4a", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh basil leaves", "quantity": 15, "unit": "g", "preparation": "torn", "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Watermelon Vinaigrette", "items": [{"name": "reserved watermelon cubes", "quantity": 100, "unit": "g", "preparation": "from produce list", "notes": null, "substitutions": [], "ingredient_id": "c03dfaed-fb45-413c-84e7-4e2d267ed7b8", "nutrition_source": "USDA FoodData Central"}, {"name": "red wine vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "9e1b7e74-fdcb-4836-8349-4f7ad86d62df", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "036c7254-3de5-4c6e-a2e7-366ad4d05077", "nutrition_source": "Aggregated Public Data"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 25g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 5, "unit": "g", "preparation": null, "notes": "helps emulsification", "substitutions": [], "ingredient_id": "3e25e626-c9b4-4b62-9d08-7c650bcb3d2b", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly ground, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 200\u00b0C (400\u00b0F). Toss the ciabatta cubes with 30ml olive oil and 2g salt on a baking sheet.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Bake the bread cubes until golden brown and very crisp, approximately 10-12 minutes. They must be thoroughly dried out to maintain texture later.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT12M", "doneness_cues": {"visual": "Golden brown edges", "tactile": "Hard and crisp to the touch"}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "While bread toasts, place the tomato wedges and 400g of the watermelon cubes in a colander set over a large bowl. Sprinkle generously with salt and toss. Let sit for 15 minutes to draw out excess liquid (save this liquid in the bowl).", "structured": {"action": "DRAIN", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Make the dressing: In a blender, combine the reserved 100g watermelon, red wine vinegar, minced shallot, Dijon mustard, and any tomato/watermelon juices collected in the bowl from Step 3. Blend until smooth. With the motor running, slowly stream in the extra virgin olive oil to emulsify. Season with salt and pepper.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "In a large serving bowl, combine the toasted bread (cooled slightly), drained tomatoes, drained watermelon, cucumber slices, and red onion.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Pour the dressing over the salad and toss gently to coat. Let the salad stand for 15 minutes before serving to allow the bread to absorb some dressing while retaining its crunch. Fold in fresh torn basil right before serving.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": ["If you enjoy cheese, crumbled Feta goes excellently with this dish."]}]', '{"active_time": "PT25M", "passive_time": "PT20M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Vegetarian", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 480.39, "protein_g": 8.15, "carbohydrates_g": 56.09, "fat_g": 24.5, "saturated_fat_g": 3.2, "trans_fat_g": null, "monounsaturated_fat_g": 5.55, "polyunsaturated_fat_g": 0.9, "fiber_g": 4.85, "sugar_g": 16.18, "sodium_mg": 679.49, "cholesterol_mg": null, "potassium_mg": 709.56, "calcium_mg": 74.85, "iron_mg": 2.68, "magnesium_mg": 39.7, "phosphorus_mg": 65.35, "zinc_mg": 0.52, "vitamin_a_mcg": 54.47, "vitamin_c_mg": 32.5, "vitamin_d_mcg": null, "vitamin_e_mg": 1.21, "vitamin_k_mcg": 28.89, "vitamin_b6_mg": 0.11, "vitamin_b12_mcg": null, "thiamin_mg": 0.07, "riboflavin_mg": 0.05, "niacin_mg": 0.37, "folate_mcg": 12.72, "water_g": 213.61, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten fresh; bread will become soggy if stored longer than 24 hours.", "duration": "P1D"}, "freezer": {"notes": "Do not freeze.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Blender or Food Processor", "required": true, "alternative": "Whisk and bowl"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Fine mesh sieve", "required": false, "alternative": null}]', '[{"symptom": "Bread turns to mush immediately", "likely_cause": "Bread was not toasted thoroughly enough or was tossed too early", "prevention": "Ensure bread is baked until rock-hard (crouton texture) before dressing", "fix": "Add fresh toasted bread right before eating for crunch"}]', '["The secret to a great Panzanella is the ''controlled soak.'' The bread should have a crisp exterior and a slightly softened, flavor-saturated interior.", "If your red onions are too pungent, soak the slices in ice water for 10 minutes before adding to the salad to tame the bite.", "Heirloom tomatoes are preferred for their superior flavor and lower water content compared to standard beefsteak tomatoes.", "Using the ''pot likker'' (the juice drained from the salted fruit) in the vinaigrette acts as a natural flavor amplifier."]', '"Panzanella originated in Tuscany as a peasant dish to repurpose stale bread. This variation incorporates Southern American summer staples\u2014watermelon and heirloom tomatoes\u2014creating a sweet-savory bridge between Mediterranean and Southern cuisine."', 480.39);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('1bc9b13a-90b1-4b9d-bf76-0b021a5774fc', 'Garlic Butter Steak Bites', 'Tender, bite-sized cubes of sirloin steak seared to a golden brown crust in cast iron, finishing with a rich, aromatic basting of garlic butter and fresh parsley. A savory, high-protein snack or main dish.', 'appetizer', 'American', 'Easy', '["american", "appetizer", "steak", "cast iron", "quick", "low-carb", "keto", "weeknight"]', '[{"group_name": "Steak & Marinade", "items": [{"name": "sirloin steak", "quantity": 600, "unit": "g", "preparation": "trimmed and cut into 2-3cm cubes", "notes": "Top sirloin or ribeye works best", "substitutions": [], "ingredient_id": "efea0192-784f-431e-bcc7-2dcf3714675e", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "for marinade", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "soy sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": "use tamari for gluten-free option", "substitutions": ["tamari", "coconut aminos"], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garlic Butter Finish", "items": [{"name": "neutral oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "grapeseed or canola for searing", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 4, "unit": null, "preparation": "minced", "notes": "approx 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine the steak cubes, olive oil, soy sauce, and black pepper in a mixing bowl. Toss well to coat.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": ["Let the steak sit at room temperature while marinating to ensure even cooking."]}, {"step_number": 2, "phase": "cook", "text": "Heat the neutral oil in a large cast iron skillet over high heat until just smoking.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 230, "fahrenheit": 446}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Place steak bites in the skillet in a single layer. Do not crowd the pan; cook in two batches if necessary. Sear undisturbed for 1-2 minutes until a deep brown crust forms.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Deep brown crust on bottom", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Flip the steak bites and sear the other side for another 1-2 minutes until browned but still tender (approx. 52\u00b0C/125\u00b0F internal for medium-rare).", "structured": {"action": "SEAR", "temperature": {"celsius": 52, "fahrenheit": 126}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Reduce heat to medium. Add the butter and minced garlic to the pan. Stir constantly for 30-60 seconds, tossing the steak in the foaming butter until the garlic is fragrant but not burnt.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove from heat immediately. Toss with fresh parsley and serve hot.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT20M", "total_time": "PT35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 150}', '{"flags": ["Low-Carb", "Keto", "Paleo", "Whole30", "Sugar-Free", "Dairy-Free"], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 432.81, "protein_g": 43.88, "carbohydrates_g": 3.11, "fat_g": 27.72, "saturated_fat_g": 10.65, "trans_fat_g": 0.42, "monounsaturated_fat_g": 9.64, "polyunsaturated_fat_g": 1.75, "fiber_g": 0.31, "sugar_g": 1.34, "sodium_mg": 1689.32, "cholesterol_mg": 147.19, "potassium_mg": 546.77, "calcium_mg": 22.87, "iron_mg": 5.19, "magnesium_mg": 39.08, "phosphorus_mg": 405.53, "zinc_mg": 7.97, "vitamin_a_mcg": 87.61, "vitamin_c_mg": 4.26, "vitamin_d_mcg": null, "vitamin_e_mg": 0.83, "vitamin_k_mcg": 46.42, "vitamin_b6_mg": 0.96, "vitamin_b12_mcg": 4.07, "thiamin_mg": 0.08, "riboflavin_mg": 0.34, "niacin_mg": 8.03, "folate_mcg": 4.31, "water_g": 98.54, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Butter may solidify.", "duration": "P3D"}, "freezer": {"notes": "Texture may degrade slightly upon thawing.", "duration": "P2M"}, "reheating": "Reheat gently in a warm skillet just until heated through to avoid overcooking.", "does_not_keep": false}', '[{"name": "Cast iron skillet", "required": true, "alternative": "Heavy-bottomed stainless steel pan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Steak bites are tough and chewy", "likely_cause": "The steak was overcooked or the pan was overcrowded, causing the meat to steam instead of sear.", "prevention": "Cook in batches to maintain high heat and remove from pan as soon as they are browned.", "fix": "Slice thinly against the grain if pieces are large enough, or use in a sauce to mask texture."}, {"symptom": "Garlic tastes bitter", "likely_cause": "Garlic was added too early or the heat was too high, causing it to burn.", "prevention": "Add garlic only in the final minute of cooking after reducing the heat.", "fix": "Cannot be fixed; burnt garlic flavor permeates the dish."}]', '["Pat the steak dry with paper towels before mixing with the marinade ingredients; excess moisture prevents a good crust.", "Do not use table salt in the marinade; the soy sauce provides sufficient salinity.", "For the most tender bites, ensure you are cutting the steak against the grain even when cubing.", "A cast iron skillet is essential here for heat retention, which creates that restaurant-style crust quickly without overcooking the center."]', '"A modern American steakhouse staple often found on appetizer menus, this dish deconstructs the classic steak dinner into a shareable, communal format. It highlights the Maillard reaction\u2014the chemical browning of food\u2014which creates the distinct savory flavor characteristic of American grilled meats."', 432.81);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('1c46ee4f-71a2-4123-a521-368f9a739a02', 'Shaved Asparagus and Radish Salad', 'A celebration of spring textures featuring crisp ribbons of raw asparagus and peppery radish slices. The salad is dressed in a bright lemon vinaigrette and finished with toasted pumpkin seeds for an earthy crunch and aromatic fresh herbs.', 'salad', 'Modern American', 'Easy', '["asparagus", "chive", "pumpkin seed", "radish", "dinner", "lunch", "quick", "raw", "spring", "healthy"]', '[{"group_name": "Vegetables & Herbs", "items": [{"name": "thick asparagus spears", "quantity": 500, "unit": "g", "preparation": "woody ends trimmed", "notes": "thicker spears are easier to shave", "substitutions": [], "ingredient_id": "8a2a9426-3755-4553-953a-fd9cf42cef90", "nutrition_source": "USDA FoodData Central"}, {"name": "radishes", "quantity": 150, "unit": "g", "preparation": "washed and trimmed", "notes": "approx. 6-8 large radishes", "substitutions": [], "ingredient_id": "2d6f93d3-117b-49ab-9e11-1058462db7ce", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh chives", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh mint leaves", "quantity": 10, "unit": "g", "preparation": "torn", "notes": null, "substitutions": [], "ingredient_id": "213e3d3b-d332-45a9-b35e-23ee29a27173", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Toppings", "items": [{"name": "pumpkin seeds", "quantity": 40, "unit": "g", "preparation": "raw", "notes": null, "substitutions": [], "ingredient_id": "cd426e8f-0a35-4b53-8e7a-d8cd5e108aa0", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Lemon Vinaigrette", "items": [{"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 30, "unit": "ml", "preparation": null, "notes": "freshly squeezed, approx 1 lemon", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 3, "unit": "g", "preparation": null, "notes": "from 1 lemon", "substitutions": [], "ingredient_id": "b12a6724-c04d-49f3-b12b-8a7fdd62afa9", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, start with 3g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the pumpkin seeds in a dry frying pan over medium heat. Toast, shaking the pan frequently, until they puff slightly and smell nutty. Transfer to a small plate to cool immediately.", "structured": {"action": "TOAST", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT4M", "doneness_cues": {"visual": "Seeds are lightly golden and puffed", "tactile": "Crisp texture"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Prepare the asparagus. Lay a spear flat on the cutting board. Holding the tip gently, use the vegetable peeler to shave thin ribbons from the stalk, moving from base to tip. Discard the very last thin woody piece that cannot be shaved. Repeat with all spears.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": {"visual": "Long, translucent ribbons", "tactile": null}}, "tips": ["If spears are snapping, ensure they are laying completely flat on the board rather than holding them in the air."]}, {"step_number": 3, "phase": "prep", "text": "Thinly slice the radishes using a sharp knife or a mandoline for uniform transparency.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In a large mixing bowl, whisk together the lemon juice, lemon zest, salt, and black pepper. Slowly stream in the olive oil while whisking vigorously to create an emulsion.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Add the shaved asparagus and radish slices to the bowl with the dressing. Toss gently with your hands to coat every ribbon without breaking them.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Transfer the dressed vegetables to a serving platter. Scatter the toasted pumpkin seeds, chopped chives, and torn mint leaves over the top. Serve immediately.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Paleo", "Whole30", "Low-Carb"], "not_suitable_for": []}', '{"per_serving": {"calories": 224.63, "protein_g": 6.27, "carbohydrates_g": 8.48, "fat_g": 20.16, "saturated_fat_g": 3.01, "trans_fat_g": 0.01, "monounsaturated_fat_g": 12.58, "polyunsaturated_fat_g": 3.78, "fiber_g": 4.25, "sugar_g": 3.41, "sodium_mg": 310.15, "cholesterol_mg": null, "potassium_mg": 454.86, "calcium_mg": 55.24, "iron_mg": 3.98, "magnesium_mg": 84.5, "phosphorus_mg": 199.86, "zinc_mg": 1.61, "vitamin_a_mcg": 69.32, "vitamin_c_mg": 18.86, "vitamin_d_mcg": null, "vitamin_e_mg": 3.81, "vitamin_k_mcg": 62.66, "vitamin_b6_mg": 0.16, "vitamin_b12_mcg": null, "thiamin_mg": 0.21, "riboflavin_mg": 0.21, "niacin_mg": 1.87, "folate_mcg": 84.57, "water_g": 161.68, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten immediately. If storing, keep dressing separate from vegetables to prevent wilting.", "duration": "P1D"}, "freezer": {"notes": "Raw vegetables do not freeze well.", "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Y-shaped vegetable peeler", "required": true, "alternative": "Mandoline slicer"}, {"name": "Small frying pan", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Asparagus ribbons are limp or soggy", "likely_cause": "Salad was dressed too early", "prevention": "Wait to toss the vegetables with the dressing until right before serving; salt draws out moisture rapidly", "fix": "Drain excess liquid and add fresh herbs to revive appearance"}]', '["Select the thickest asparagus spears available; pencil-thin asparagus will break when you try to shave it.", "For extra crunch, soak the shaved asparagus and sliced radishes in a bowl of ice water for 10 minutes, then spin completely dry before dressing.", "Shaved parmesan or pecorino cheese makes an excellent non-vegan addition to this dish.", "If the dressing tastes too sharp, a half-teaspoon of honey or maple syrup can balance the acidity."]', '"Shaved asparagus salads became popular in modern farm-to-table cuisine as a way to highlight the delicate, sweet flavor of raw spring produce without the need for heat. This preparation preserves the vegetable''s natural crunch and nutrients."', 224.63);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('1c5a8ca9-ce0d-440d-9912-28b25ef963e4', 'Apple & Red Currant Vinaigrette', 'A vibrant, jewel-toned dressing that balances the sharp, popping tartness of red currants with the crisp, floral sweetness of fresh apples. Perfect for drizzling over bitter greens, roasted squash, or grain salads.', 'sauce', 'French', 'Easy', '["condiments", "sauces and gravies", "apple", "currant", "vegan", "vegetarian", "raw", "summer", "autumn"]', '[{"group_name": "Base Vinaigrette", "items": [{"name": "apple cider vinegar", "quantity": 45, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 10, "unit": "g", "preparation": null, "notes": "ensure gluten-free if required", "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "maple syrup", "quantity": 15, "unit": "ml", "preparation": null, "notes": "adjust to taste depending on apple sweetness", "substitutions": [], "ingredient_id": "c9ca1f35-b107-46c2-92a3-4c1c620f3c11", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 120, "unit": "ml", "preparation": "liquid", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "fine sea salt", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Fresh Aromatics & Fruit", "items": [{"name": "shallot", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 20g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "apple", "quantity": 50, "unit": "g", "preparation": "finely diced (brunoise)", "notes": "sweet variety like Honeycrisp or Fuji", "substitutions": [], "ingredient_id": "9985672b-aa9f-4125-8a32-62d520c99d6f", "nutrition_source": "USDA FoodData Central"}, {"name": "red currants", "quantity": 40, "unit": "g", "preparation": "fresh or frozen", "notes": "removed from stems", "substitutions": [], "ingredient_id": "9f83c6a8-a2ac-4aac-ad24-02dbc16ffbd6", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the aromatics: Peel and mince the shallot. Finely dice the apple into tiny 2-3mm cubes (brunoise). Wash and destem the red currants.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Dicing the apple very small ensures it distributes evenly in the dressing rather than falling to the bottom."]}, {"step_number": 2, "phase": "prep", "text": "In a medium mixing bowl, combine the apple cider vinegar, Dijon mustard, maple syrup, salt, and pepper. Whisk vigorously until the salt is dissolved and the mixture is smooth.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "mix", "text": "Add the minced shallot and diced apple to the vinegar mixture immediately. Stir to coat.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Adding the apple to the acid immediately prevents it from oxidizing (turning brown)."]}, {"step_number": 4, "phase": "finish", "text": "While whisking continuously, slowly stream in the extra virgin olive oil to create an emulsion. The mixture should thicken slightly and become glossy.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Gently fold in the red currants. Lightly press a few currants against the side of the bowl with a spoon to burst them and release their pink juice, but keep most whole for texture.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT0M", "total_time": "PT15M", "overnight_required": false, "yields": "250ml", "yield_count": 8, "serving_size_g": 30}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Paleo"], "not_suitable_for": []}', '{"per_serving": {"calories": 147.83, "protein_g": 0.21, "carbohydrates_g": 3.44, "fat_g": 15.07, "saturated_fat_g": 2.08, "trans_fat_g": null, "monounsaturated_fat_g": 10.95, "polyunsaturated_fat_g": 1.59, "fiber_g": 0.52, "sugar_g": 2.39, "sodium_mg": 112.38, "cholesterol_mg": null, "potassium_mg": 40.67, "calcium_mg": 7.53, "iron_mg": 0.23, "magnesium_mg": 2.38, "phosphorus_mg": 5.04, "zinc_mg": 0.04, "vitamin_a_mcg": 0.32, "vitamin_c_mg": 2.54, "vitamin_d_mcg": null, "vitamin_e_mg": 2.18, "vitamin_k_mcg": 9.94, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.03, "niacin_mg": 0.02, "folate_mcg": 1.46, "water_g": 17.44, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Shake well before serving as separation is natural. Apples may soften slightly over time.", "duration": "P5D"}, "freezer": {"notes": "Not recommended; texture of fresh fruit will degrade.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Medium mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Measuring spoons/cups", "required": true, "alternative": null}]', '[{"symptom": "Vinaigrette has separated/broken", "likely_cause": "Oil was added too quickly or mixture sat for too long", "prevention": "Add oil in a very slow, steady stream while whisking rapidly", "fix": "Whisk vigorously again right before serving; vinaigrettes naturally separate over time"}, {"symptom": "Taste is too sharp or acidic", "likely_cause": "Currants were extra tart or vinegar was too strong", "prevention": "Taste the currants before adding", "fix": "Add an extra teaspoon of maple syrup or a splash more olive oil to balance"}]', '["If fresh red currants are unavailable, you can use frozen ones (thawed) or substitute with pomegranate arils for a similar jewel-like appearance, though the flavor will be sweeter.", "For a smoother dressing, you can blend all ingredients except the oil and currants, then stream in the oil, and stir the whole currants in at the end.", "This vinaigrette pairs exceptionally well with endive, radicchio, or kale, as the sweetness balances bitter greens perfectly."]', '"While the classic vinaigrette structure is distinctly French (3 parts oil to 1 part acid), the incorporation of whole fruits like currants and apples nods to modern ''agrodolce'' (sour-sweet) profiles popular in contemporary farm-to-table cuisine, celebrating autumn harvest ingredients."', 147.83);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('1d39cc9d-1ed0-411f-b6d8-12bc032c3bb7', 'Velvety Spiked Dark Hot Chocolate', 'A luxuriously thick and decadent European-style drinking chocolate. Deep, bittersweet cocoa notes are warmed by a generous splash of dark rum, balanced by a pinch of sea salt, and crowned with a cloud of cool, freshly whipped cream.', 'hot drink', 'European', 'Easy', '["winter", "christmas", "comfort food", "bittersweet chocolate", "hot drink"]', '[{"group_name": "Hot Chocolate Base", "items": [{"name": "whole milk", "quantity": 300, "unit": "ml", "preparation": "cold", "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 100, "unit": "ml", "preparation": null, "notes": "35% fat or higher", "substitutions": [], "ingredient_id": "c0632db1-0bb6-4224-8025-59c94c92a244", "nutrition_source": "Aggregated Public Data"}, {"name": "bittersweet chocolate", "quantity": 100, "unit": "g", "preparation": "finely chopped", "notes": "60-70% cocoa solids", "substitutions": [], "ingredient_id": "119741fa-b6ad-458d-9cbb-fe79c9d2d687", "nutrition_source": "Aggregated Public Data"}, {"name": "cocoa powder", "quantity": 10, "unit": "g", "preparation": "unsweetened", "notes": "Dutch-processed preferred", "substitutions": [], "ingredient_id": "c06a8e5a-163a-4f21-ad00-a6d90e34c38c", "nutrition_source": "USDA FoodData Central"}, {"name": "brown sugar", "quantity": 15, "unit": "g", "preparation": null, "notes": "adjust to taste based on chocolate bitterness", "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "generous pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "The Spike", "items": [{"name": "dark rum", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["bourbon", "brandy", "1 tsp rum extract (non-alcoholic)"], "ingredient_id": "fcfa2efa-bfc7-479b-9e45-790a71bf91f9", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Whipped Topping", "items": [{"name": "heavy cream", "quantity": 100, "unit": "ml", "preparation": "very cold", "notes": null, "substitutions": [], "ingredient_id": "c0632db1-0bb6-4224-8025-59c94c92a244", "nutrition_source": "Aggregated Public Data"}, {"name": "powdered sugar", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "dark chocolate shavings", "quantity": 5, "unit": "g", "preparation": null, "notes": "for garnish", "substitutions": [], "ingredient_id": "08395d12-1a43-46f7-b602-36c2d07ce259", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a cold mixing bowl, whip the heavy cream and powdered sugar until soft peaks form. Keep chilled in the refrigerator until ready to serve.", "structured": {"action": "WHIP", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Soft peaks that droop slightly when whisk is lifted", "tactile": "Aerated and thickened"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a medium saucepan, combine the whole milk, 100ml heavy cream, cocoa powder, sugar, and sea salt. Whisk vigorously to break up any cocoa lumps.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat the milk mixture over medium heat until it begins to steam and bubbles appear around the edges (approx 80\u00b0C/175\u00b0F). Do not let it come to a rolling boil.", "structured": {"action": "SIMMER", "temperature": {"celsius": 80, "fahrenheit": 176}, "duration": "PT5M", "doneness_cues": {"visual": "Steaming with small bubbles at the rim", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Reduce heat to low. Add the chopped bittersweet chocolate. Whisk constantly until the chocolate is completely melted and the mixture is glossy and thickened.", "structured": {"action": "MELT", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Glossy, uniform color, no specks of chocolate", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove the pan from the heat. Stir in the vanilla extract and dark rum immediately.", "structured": {"action": "STIR", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": ["Adding alcohol off the heat prevents it from evaporating too quickly."]}, {"step_number": 6, "phase": "assemble", "text": "Pour into mugs. Top generously with the prepared whipped cream and garnish with chocolate shavings.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT0M", "total_time": "PT15M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 320}', '{"flags": ["Vegetarian", "Gluten-Free"], "not_suitable_for": ["Children (contains alcohol)", "Individuals avoiding alcohol"]}', '{"per_serving": {"calories": 1117.5, "protein_g": 14.35, "carbohydrates_g": 56.52, "fat_g": 86.22, "saturated_fat_g": 15.75, "trans_fat_g": null, "monounsaturated_fat_g": 1.74, "polyunsaturated_fat_g": 0.35, "fiber_g": 8.45, "sugar_g": 43.07, "sodium_mg": 298.1, "cholesterol_mg": 15.15, "potassium_mg": 888.94, "calcium_mg": 335.37, "iron_mg": 5.84, "magnesium_mg": 45.33, "phosphorus_mg": 240.78, "zinc_mg": 1.42, "vitamin_a_mcg": 748.08, "vitamin_c_mg": null, "vitamin_d_mcg": 1.95, "vitamin_e_mg": 0.13, "vitamin_k_mcg": 0.76, "vitamin_b6_mg": 0.07, "vitamin_b12_mcg": 0.68, "thiamin_mg": 0.08, "riboflavin_mg": 0.27, "niacin_mg": 0.28, "folate_mcg": 9.18, "water_g": 148.74, "alcohol_g": 8.38, "caffeine_mg": 13.65}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store without whipped cream topping. Reheat gently on stove.", "duration": "P3D"}, "freezer": {"duration": null}, "reheating": "Warm over low heat on the stovetop, whisking constantly to re-emulsify. Do not boil.", "does_not_keep": false}', '[{"name": "Medium saucepan", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Hand mixer or stand mixer", "required": true, "alternative": "Balloon whisk and elbow grease"}, {"name": "Mixing bowl", "required": true, "alternative": null}]', '[{"symptom": "Hot chocolate is grainy or seized", "likely_cause": "Heat was too high or chocolate was added to boiling liquid", "prevention": "Never boil the mixture once chocolate is added; keep heat low", "fix": "Use an immersion blender to re-emulsify the mixture"}, {"symptom": "Mixture is too thin", "likely_cause": "Chocolate percentage too low or not enough cream", "prevention": "Use chocolate with at least 60% cocoa solids", "fix": "Whisk in another 15-20g of chopped chocolate"}]', '["Salt is the most important secret ingredient here; it cuts the richness and makes the chocolate flavor pop.", "For the best texture, use bar chocolate rather than chips. Chips often contain stabilizers that prevent smooth melting.", "If you strictly require a non-alcoholic version, swap the rum for 1/2 teaspoon of rum extract, or simply omit it for a classic French hot chocolate.", "Whip the cream to ''soft peaks'' rather than ''stiff peaks'' for a more elegant mouthfeel that blends with the hot liquid as you drink."]', '"While hot chocolate has ancient roots in Mesoamerica, this style mimics ''Chocolat Chaud'' found in Parisian cafes\u2014characterized by a high ratio of chocolate to milk and the absence of water, resulting in a dessert-like consistency."', 1117.5);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('1d3b7ef1-c12d-491d-ae3e-f26441b5348d', 'Roast Fillet of Beef with Dried Cherry Reduction and Horseradish Crème', 'A centerpiece British roast featuring center-cut beef tenderloin, seared for a caramelized crust and roasted to tender perfection. It is served with two contrasting sauces: a rich, tart red wine reduction studded with dried cherries, and a sharp, cooling horseradish cream.', 'dinner', 'British', 'Advanced', '["british", "sauces and gravies", "beef", "beef tenderloin", "dried cherry", "horseradish", "olive oil", "thyme", "dinner", "roast"]', '[{"group_name": "Beef Fillet", "items": [{"name": "beef tenderloin", "quantity": 1200, "unit": "g", "preparation": "center cut, trimmed and tied", "notes": "Bring to room temperature 1 hour before cooking", "substitutions": [], "ingredient_id": "a821f612-21c1-4514-969d-c3a2101cd8d5", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 6, "unit": null, "preparation": "whole sprigs", "notes": "approx 5g", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt flakes", "quantity": 10, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 5, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dried Cherry Reduction", "items": [{"name": "dry red wine", "quantity": 250, "unit": "ml", "preparation": null, "notes": "Cabernet Sauvignon or Merlot", "substitutions": [], "ingredient_id": "0fc93141-8ba8-42e0-ac8b-b5af3851554c", "nutrition_source": "USDA FoodData Central"}, {"name": "beef stock", "quantity": 300, "unit": "ml", "preparation": null, "notes": "high quality, low sodium", "substitutions": [], "ingredient_id": "390b2a8f-1613-4b2d-ae97-8403bbc9f505", "nutrition_source": "Aggregated Public Data"}, {"name": "dried cherries", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fc2b3924-abc5-498f-b917-8bb60e75b983", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "approx 25g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Horseradish Cr\u00e8me", "items": [{"name": "cr\u00e8me fra\u00eeche", "quantity": 150, "unit": "ml", "preparation": null, "notes": "or heavy cream", "substitutions": [], "ingredient_id": "d171100e-1088-4266-8d50-06cdedda7193", "nutrition_source": "USDA FoodData Central"}, {"name": "prepared horseradish", "quantity": 45, "unit": "g", "preparation": "drained", "notes": null, "substitutions": [], "ingredient_id": "72f7fb8a-7b34-41ea-9e5f-8fec2553cae8", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2f2247dc-52b3-4782-a330-b355c8c10e4f", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh chives", "quantity": 5, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Remove the beef from the refrigerator at least 45-60 minutes before cooking to allow it to come to room temperature. This ensures even roasting.", "structured": {"action": "REST", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Pat the beef thoroughly dry with paper towels. Rub all over with olive oil, sea salt, and freshly cracked black pepper. Tie the roast with butcher''s twine at 3cm intervals to maintain a uniform cylindrical shape.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Dry meat sears better. Moisture creates steam which inhibits browning."]}, {"step_number": 3, "phase": "cook", "text": "Preheat oven to 200\u00b0C/390\u00b0F. Heat a large cast-iron skillet over high heat until smoking. Add the beef and sear aggressively on all sides until deep brown, about 2-3 minutes per side. Add thyme sprigs to the pan during the last minute of searing.", "structured": {"action": "SEAR", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Transfer the beef (and thyme) to a roasting rack set over a tray. Roast in the oven until an instant-read thermometer inserted into the thickest part reads 52\u00b0C/125\u00b0F for medium-rare.", "structured": {"action": "ROAST", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT25M", "doneness_cues": {"visual": "Browned crust", "tactile": "Internal temp 52\u00b0C"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove beef from the oven. Transfer to a carving board and cover loosely with foil. Allow to rest for at least 15-20 minutes. This is critical for retaining juices.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "While beef rests, prepare the cherry sauce. In the saucepan, combine red wine, minced shallot, and dried cherries. Bring to a boil and reduce liquid by half.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Add beef stock to the wine mixture. Simmer until reduced to a sauce consistency that coats the back of a spoon (nappe). Remove from heat and whisk in the cold cubed butter to emulsify and add gloss. Season with salt to taste.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "prep", "text": "For the horseradish cr\u00e8me, whisk together cr\u00e8me fra\u00eeche, prepared horseradish, Dijon mustard, lemon juice, and chives in a small bowl. Season with a pinch of salt and pepper. Refrigerate until serving.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove twine from the beef. Slice into thick medallions (approx. 2-3cm). Serve with the warm dried cherry reduction poured over the meat and the cool horseradish cr\u00e8me on the side.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT1H15M", "total_time": "PT2H", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 250}', '{"flags": ["Gluten-Free", "Low-Carb", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 529.93, "protein_g": 48.41, "carbohydrates_g": 11.26, "fat_g": 29.94, "saturated_fat_g": 11.27, "trans_fat_g": 0.66, "monounsaturated_fat_g": 11.44, "polyunsaturated_fat_g": 2.04, "fiber_g": 1.51, "sugar_g": 3.67, "sodium_mg": 856.16, "cholesterol_mg": 142.6, "potassium_mg": 744.08, "calcium_mg": 83.48, "iron_mg": 5.9, "magnesium_mg": 45.48, "phosphorus_mg": 511.83, "zinc_mg": 7.39, "vitamin_a_mcg": 73.36, "vitamin_c_mg": 4.64, "vitamin_d_mcg": 0.25, "vitamin_e_mg": 1.34, "vitamin_k_mcg": 8.01, "vitamin_b6_mg": 1.27, "vitamin_b12_mcg": 7.07, "thiamin_mg": 0.15, "riboflavin_mg": 0.69, "niacin_mg": 9.66, "folate_mcg": 17.47, "water_g": 212.65, "alcohol_g": 3.88, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store beef and sauces in separate airtight containers.", "duration": "P3D"}, "freezer": {"notes": "Beef can be frozen but texture may suffer upon reheating. Sauces freeze well.", "duration": "P1M"}, "reheating": "Gently reheat beef slices in the cherry sauce over low heat just until warm. Do not overheat or the meat will toughen.", "does_not_keep": false}', '[{"name": "Large cast-iron skillet or heavy-bottomed frying pan", "required": true, "alternative": null}, {"name": "Roasting tray with rack", "required": true, "alternative": "Baking sheet with a wire cooling rack"}, {"name": "Digital probe thermometer", "required": true, "alternative": null}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Butchers twine", "required": true, "alternative": null}]', '[{"symptom": "Beef is tough or dry", "likely_cause": "Overcooking beyond medium-rare or not resting the meat", "prevention": "Use a probe thermometer to pull meat exactly at 52\u00b0C/125\u00b0F and rest for the full 20 minutes.", "fix": "Slice very thinly against the grain and serve with extra sauce to provide moisture."}]', '["Uniformity is key: Tying the beef with butcher''s twine ensures the roast is the same thickness throughout, preventing the ends from overcooking while the center is raw.", "The ''monter au beurre'' technique (whisking cold butter into the hot sauce off the heat) is essential for a glossy, professional finish on the cherry reduction.", "If your dried cherries are very hard or old, rehydrate them in the red wine for 15 minutes before starting the sauce.", "For the horseradish sauce, use fresh horseradish root grated on a microplane if available for a more potent, aromatic kick compared to jarred."]', '"Roast beef is the quintessence of British culinary identity, historically celebrated in ballads and patriotic songs. This recipe elevates the traditional Sunday lunch by pairing the earthy, iron-rich beef with a classic ''agrodolce'' style fruit sauce and the traditional sharp bite of horseradish."', 529.93);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('1eb06288-dba7-420e-bbac-b458ed50d361', 'Oven-Roasted BBQ Chicken Drumsticks with Potato Wedges & Creamy Slaw', 'Juicy, budget-friendly chicken drumsticks glazed in a sticky homemade barbecue sauce, served alongside crispy seasoned potato wedges and a refreshing, crunchy coleslaw to balance the richness. A complete, flavorful meal that maximizes value without sacrificing taste.', 'dinner', 'American', 'Intermediate', '["barbecue", "chicken", "potatoes", "coleslaw", "budget", "main course", "sheet pan meal"]', '[{"group_name": "Chicken", "items": [{"name": "chicken drumsticks", "quantity": 1000, "unit": "g", "preparation": "skin-on, bone-in", "notes": "approx 8-10 pieces", "substitutions": [], "ingredient_id": "9f802c81-04c1-45b3-be1a-c55787a528b0", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 15, "unit": "ml", "preparation": "liquid", "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic powder", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "177a312f-ef99-4398-9108-98f7a608a245", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Homemade BBQ Sauce", "items": [{"name": "ketchup", "quantity": 120, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "9b0c1201-83fa-43c7-b2a4-66c400bcb0fd", "nutrition_source": "Aggregated Public Data"}, {"name": "brown sugar", "quantity": 40, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "apple cider vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "worcestershire sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["soy sauce"], "ingredient_id": "aa552099-60a9-4267-a732-5870a271c28f", "nutrition_source": "Aggregated Public Data"}, {"name": "dijon mustard", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Potato Wedges", "items": [{"name": "russet potatoes", "quantity": 800, "unit": "g", "preparation": "scrubbed, cut into wedges", "notes": null, "substitutions": [], "ingredient_id": "a7db25be-476c-48fe-8cb8-2ea66fb91587", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "dried thyme", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "3b938244-d506-46b2-9027-21bed955bcc5", "nutrition_source": "USDA FoodData Central"}, {"name": "paprika", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Coleslaw", "items": [{"name": "green cabbage", "quantity": 400, "unit": "g", "preparation": "shredded", "notes": "approx half a medium head", "substitutions": [], "ingredient_id": "3665bd9f-fcae-44a3-a11d-16c4ca6e52bd", "nutrition_source": "Aggregated Public Data"}, {"name": "carrot", "quantity": 100, "unit": "g", "preparation": "grated", "notes": "approx 1 medium carrot", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "mayonnaise", "quantity": 80, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "97b74a34-8c1f-4c58-b70e-42c1de6d12aa", "nutrition_source": "USDA FoodData Central"}, {"name": "white vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["lemon juice"], "ingredient_id": "8d5bf07e-89a1-47ee-a6b7-d9cb03e96d64", "nutrition_source": "Aggregated Public Data"}, {"name": "sugar", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "celery seeds", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "30c3f84e-7e3c-43a2-affa-a10986bed987", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 200\u00b0C/400\u00b0F. Line two baking sheets with parchment paper or foil for easier cleanup.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a small bowl, whisk together the ketchup, brown sugar, apple cider vinegar, Worcestershire sauce, and Dijon mustard until smooth. Set aside half of this sauce for later glazing.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Pat the chicken drumsticks dry with paper towels. Toss them in a large bowl with oil, salt, pepper, garlic powder, and smoked paprika until evenly coated.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Patting chicken dry ensures the skin crisps up rather than steaming."]}, {"step_number": 4, "phase": "prep", "text": "Wash the potatoes and cut them into thick wedges. In a separate bowl, toss them with oil, salt, dried thyme, and paprika.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Arrange the chicken on one baking sheet and the potatoes on the other in single layers. Place both trays in the oven. Roast for 25 minutes.", "structured": {"action": "ROAST", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT25M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "While the oven works, combine the mayonnaise, vinegar, sugar, salt, and celery seeds in a large bowl. Add the shredded cabbage and carrots, tossing to coat. Refrigerate until serving.", "structured": {"action": "MIX", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "After 25 minutes, remove the chicken from the oven. Brush the drumsticks generously with the reserved BBQ sauce. Flip the potato wedges on the other tray.", "structured": {"action": "GLAZE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Return both trays to the oven (swap racks if possible for even cooking) and roast for another 15-20 minutes until the chicken reaches an internal temperature of 74\u00b0C/165\u00b0F and the glaze is sticky. Potatoes should be golden and tender.", "structured": {"action": "ROAST", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT20M", "doneness_cues": {"visual": "Chicken glaze is bubbly and sticky; potatoes are golden brown", "tactile": "Potatoes soft inside; chicken juices run clear"}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove from oven. Let the chicken rest for 5 minutes before serving alongside the hot wedges and cold coleslaw.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT50M", "total_time": "PT1H25M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 550}', '{"flags": ["Gluten-Free", "Dairy-Free", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 928.55, "protein_g": 52.02, "carbohydrates_g": 68.8, "fat_g": 49.98, "saturated_fat_g": 10.24, "trans_fat_g": 0.16, "monounsaturated_fat_g": 12.77, "polyunsaturated_fat_g": 14.07, "fiber_g": 6.76, "sugar_g": 25.27, "sodium_mg": 1921.13, "cholesterol_mg": 238.4, "potassium_mg": 1737.58, "calcium_mg": 137.27, "iron_mg": 5.69, "magnesium_mg": 114.99, "phosphorus_mg": 571.41, "zinc_mg": 5.67, "vitamin_a_mcg": 305.69, "vitamin_c_mg": 52.42, "vitamin_d_mcg": 0.29, "vitamin_e_mg": 1.73, "vitamin_k_mcg": 56.13, "vitamin_b6_mg": 1.62, "vitamin_b12_mcg": 1.35, "thiamin_mg": 0.39, "riboflavin_mg": 0.6, "niacin_mg": 14.61, "folate_mcg": 43.82, "water_g": 464.54, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store chicken and potatoes separate from coleslaw. Coleslaw may become watery after 24 hours.", "duration": "P3D"}, "freezer": {"notes": "Chicken freezes well. Potatoes and coleslaw do not freeze well.", "duration": "P2M"}, "reheating": "Reheat chicken and potatoes in oven at 175\u00b0C until hot. Coleslaw must be served cold.", "does_not_keep": false}', '[{"name": "Large rimmed baking sheet", "required": true, "alternative": "Roasting pan"}, {"name": "Second baking sheet", "required": true, "alternative": "Cast iron skillet"}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Pastry brush", "required": true, "alternative": "Spoon"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Chicken skin is rubbery under the sauce", "likely_cause": "Oven humidity was too high or chicken wasn''t dried enough", "prevention": "Ensure chicken is very dry before oiling; leave space between pieces on the tray", "fix": "Turn on the oven broiler (grill) for 2-3 minutes at the very end to caramelize the sauce and skin, watching closely to prevent burning"}, {"symptom": "Potatoes are sticking to the pan", "likely_cause": "Not enough oil or pan wasn''t lined", "prevention": "Use parchment paper or silicone mats; ensure potatoes are well-coated in oil", "fix": "Let the potatoes cool for 2-3 minutes on the pan; they often release as the steam dissipates"}]', '["Drumsticks are a forgiving cut; unlike breast meat, they remain juicy even if slightly overcooked, making them perfect for beginners.", "For the crispiest potato wedges, soak the cut potatoes in cold water for 30 minutes to remove excess starch, then dry thoroughly before oiling.", "The coleslaw tastes best if made at least 30 minutes ahead, allowing the cabbage to soften slightly and absorb the dressing flavors.", "This homemade BBQ sauce base can be adjusted: add chili flakes for heat or a splash of liquid smoke for that outdoor grill flavor."]', '"This meal represents the quintessential American family dinner\u2014hearty, sweet-savory, and comforting. While ''barbecue'' strictly refers to slow-smoking meat in Southern US tradition, this oven-roasted method adapts those signature flavors for the modern home kitchen, utilizing economical cuts like drumsticks that have been a staple of budget-conscious cooking for decades."', 928.55);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('1ff58a86-5498-4282-87e8-6c7e0de78133', 'Velvety Carrot and Honey Timbale', 'A sophisticated, airy vegetable custard highlighting the natural sweetness of carrots enhanced with a touch of honey and nutmeg. This light, vibrant orange dish offers a delicate melt-in-the-mouth texture.', 'side dish', 'French', 'Intermediate', '["french", "vegetarian", "gluten-free", "elegant", "make-ahead", "custard"]', '[{"group_name": "Vegetable Base", "items": [{"name": "carrots", "quantity": 500, "unit": "g", "preparation": "peeled and sliced into rounds", "notes": null, "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 250, "unit": "ml", "preparation": null, "notes": "for boiling", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "room temperature", "notes": "plus extra for greasing molds", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 15, "unit": "g", "preparation": null, "notes": "approx 1 tbsp", "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Custard", "items": [{"name": "heavy cream", "quantity": 120, "unit": "ml", "preparation": null, "notes": "35% fat or higher", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 3, "unit": null, "preparation": "large", "notes": "approx 150g total weight", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "ground nutmeg", "quantity": null, "unit": null, "preparation": null, "notes": "pinch, to taste", "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 4, "unit": "g", "preparation": null, "notes": "approx 3/4 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "white pepper", "quantity": null, "unit": null, "preparation": null, "notes": "pinch", "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 170\u00b0C/340\u00b0F. Generously grease 6 ramekins with butter to ensure easy unmolding later.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a saucepan over medium heat, combine the sliced carrots, water, butter, and honey. Cover and simmer until the carrots are extremely tender and the liquid has almost entirely evaporated.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT20M", "doneness_cues": {"visual": "Liquid mostly evaporated", "tactile": "Carrots mash easily with a fork"}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Transfer the cooked carrots to a blender. Add the heavy cream, eggs, nutmeg, salt, and white pepper. Blend on high speed until completely smooth and velvety.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Uniform orange color, no lumps", "tactile": null}}, "tips": ["For an ultra-refined texture, pass the mixture through a fine mesh sieve after blending."]}, {"step_number": 4, "phase": "cook", "text": "Pour the mixture evenly into the prepared ramekins. Place the ramekins into a roasting pan and pour boiling water into the pan until it reaches halfway up the sides of the ramekins (bain-marie).", "structured": {"action": "BAKE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Water level halfway up ramekins", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Bake carefully in the preheated oven for 30-40 minutes. The timbales are done when the centers are set but still wobble slightly when shaken, similar to gelatin.", "structured": {"action": "BAKE", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": "PT35M", "doneness_cues": {"visual": "Set but slightly jiggly center", "tactile": "Firm to the touch"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove the ramekins from the water bath and let them rest on a wire rack for 10 minutes. This rest period is crucial for the structure to firm up before unmolding.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Run a thin knife around the edge of each mold, invert onto a plate, and lift the ramekin off gently.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT55M", "total_time": "PT1H30M", "overnight_required": false, "yields": "6 timbales", "yield_count": 6, "serving_size_g": 140}', '{"flags": ["Vegetarian", "Gluten-Free", "Soy-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": ["Infants under 12 months (honey)", "Vegans"]}', '{"per_serving": {"calories": 182.05, "protein_g": 4.56, "carbohydrates_g": 10.89, "fat_g": 13.89, "saturated_fat_g": 7.95, "trans_fat_g": 0.26, "monounsaturated_fat_g": 3.92, "polyunsaturated_fat_g": 1.03, "fiber_g": 2.38, "sugar_g": 6.68, "sodium_mg": 358.78, "cholesterol_mg": 126.35, "potassium_mg": 323.28, "calcium_mg": 57.42, "iron_mg": 0.74, "magnesium_mg": 15.2, "phosphorus_mg": 91.89, "zinc_mg": 0.59, "vitamin_a_mcg": 852.24, "vitamin_c_mg": 5.07, "vitamin_d_mcg": 0.82, "vitamin_e_mg": 1.11, "vitamin_k_mcg": 12.07, "vitamin_b6_mg": 0.17, "vitamin_b12_mcg": 0.26, "thiamin_mg": 0.07, "riboflavin_mg": 0.21, "niacin_mg": 0.85, "folate_mcg": 28.66, "water_g": 147.1, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in airtight container; texture may become denser.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; custards tend to weep and separate upon thawing.", "duration": null}, "reheating": "Reheat gently in a water bath or steamer to preserve texture.", "does_not_keep": false}', '[{"name": "Ramekins (150ml capacity)", "required": true, "alternative": "Muffin tin or small silicone molds"}, {"name": "Roasting pan (for water bath)", "required": true, "alternative": null}, {"name": "Blender or Food Processor", "required": true, "alternative": null}, {"name": "Saucepan", "required": true, "alternative": null}, {"name": "Fine mesh sieve", "required": false, "alternative": "None (results in more rustic texture)"}]', '[{"symptom": "Timbale breaks apart when unmolding", "likely_cause": "Unmolded too hot or ramekins not greased enough", "prevention": "Ensure generous buttering of molds and allow the full 10-minute rest period", "fix": "Serve inside the ramekin instead of unmolding"}, {"symptom": "Texture is rubbery or curded", "likely_cause": "Oven temperature too high or water bath boiled vigorously", "prevention": "Maintain gentle oven heat and use a water bath to regulate temperature", "fix": "Cannot be fixed"}]', '["The water bath (bain-marie) is non-negotiable; it prevents the eggs from scrambling at the edges before the center cooks.", "If using older carrots which can be bitter, increase the honey slightly to balance the flavor.", "Serve alongside a light green salad with a lemon vinaigrette to cut through the richness of the custard.", "These can be made a day ahead and reheated gently, making them excellent for dinner parties."]', '"The timbale is a classic French preparation named after the drum-shaped metal mold (''timbale'') in which it was traditionally baked. While often associated with elaborate 19th-century cuisine involving pastry crusts, modern versions like this vegetable custard focus on purity of flavor and delicate texture, exemplifying the French respect for transforming simple garden ingredients into elegant courses."', 182.05);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('209b1592-bbb3-4f8a-a988-a7f0469f9200', 'Sake-Steamed Clam Soba with Ginger Broth', 'A comforting yet elegant weeknight meal featuring briny Manila clams steamed in sake and aromatics, served over nutty buckwheat noodles in a clear, savory dashi broth finished with toasted sesame oil.', 'dinner', 'Japanese', 'Intermediate', '["japanese", "clam", "sesame oil", "dinner", "weeknight", "soba", "seafood"]', '[{"group_name": "Clams & Aromatics", "items": [{"name": "manila clams", "quantity": 600, "unit": "g", "preparation": "live, scrubbed", "notes": "can substitute littleneck clams", "substitutions": [], "ingredient_id": "59545409-30d0-466b-9b6f-84ae890c0214", "nutrition_source": "USDA FoodData Central"}, {"name": "ginger", "quantity": 15, "unit": "g", "preparation": "julienned", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "sliced thinly", "notes": "approx. 8g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "scallions", "quantity": 2, "unit": null, "preparation": "thinly sliced", "notes": "approx. 30g; separate white and green parts", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 10, "unit": "ml", "preparation": null, "notes": "canola or vegetable", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Broth & Noodles", "items": [{"name": "dried buckwheat noodles", "quantity": 200, "unit": "g", "preparation": null, "notes": "Soba", "substitutions": [], "ingredient_id": "de9aff9c-391d-4c5a-a560-7bf644cd9599", "nutrition_source": "Aggregated Public Data"}, {"name": "sake", "quantity": 60, "unit": "ml", "preparation": null, "notes": "dry japanese rice wine", "substitutions": [], "ingredient_id": "1cfffbd2-7ea5-4cbc-bc35-c57e12233152", "nutrition_source": "USDA FoodData Central"}, {"name": "dashi stock", "quantity": 600, "unit": "ml", "preparation": null, "notes": "prepared from kombu and bonito", "substitutions": [], "ingredient_id": "49b409b2-eeb1-48f9-8fc6-ffc31b7bf260", "nutrition_source": "Aggregated Public Data"}, {"name": "soy sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": "light soy sauce (usukuchi) preferred for color", "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "mirin", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2a72c18d-8a1d-4259-8790-25d62f6fb5ba", "nutrition_source": "Aggregated Public Data"}, {"name": "toasted sesame oil", "quantity": 10, "unit": "ml", "preparation": "finishing", "notes": null, "substitutions": [], "ingredient_id": "8fa9dd65-c49e-449c-b660-a9d9deb638b2", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Purge the clams to remove sand. Submerge clams in cool water mixed with 3% salt (approx 15g salt per 500ml water) in a dark place for at least 1 hour. Discard any clams with broken shells or those that do not close when tapped.", "structured": {"action": "SOAK", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Bring a large pot of water to a boil. Add buckwheat noodles and cook according to package directions (usually 3-4 minutes) until al dente. Drain immediately and rinse vigorously under cold running water to remove excess starch and stop cooking. Set aside.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a deep saut\u00e9 pan, heat neutral oil over medium heat. Add garlic, ginger, and the white parts of the scallions. Saut\u00e9 briefly until fragrant, about 1 minute, being careful not to burn the garlic.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the drained clams and sake to the pan. Cover immediately with a tight-fitting lid to steam. Cook for 3-5 minutes until the clam shells have popped open.", "structured": {"action": "STEAM", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT4M", "doneness_cues": {"visual": "Shells are fully open", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Remove the lid. Discard any clams that did not open. Pour in the dashi stock, soy sauce, and mirin. Bring to a gentle simmer just to heat the broth through. Do not boil vigorously or the clams may become tough.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Divide the cooked noodles between serving bowls. Ladle the hot broth and clams over the noodles. Drizzle with toasted sesame oil and garnish with the green parts of the scallions.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT1H", "total_time": "PT1H25M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 550}', '{"flags": ["Pescatarian", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": ["Shellfish allergy"]}', '{"per_serving": {"calories": 1172.02, "protein_g": 68.26, "carbohydrates_g": 109.92, "fat_g": 22.16, "saturated_fat_g": 2.07, "trans_fat_g": 0.03, "monounsaturated_fat_g": 0.38, "polyunsaturated_fat_g": 0.6, "fiber_g": 0.7, "sugar_g": 24.21, "sodium_mg": 18182.4, "cholesterol_mg": 90, "potassium_mg": 598.08, "calcium_mg": 338.8, "iron_mg": 7.09, "magnesium_mg": 75.03, "phosphorus_mg": 635.02, "zinc_mg": 1.79, "vitamin_a_mcg": 277.5, "vitamin_c_mg": 4.45, "vitamin_d_mcg": null, "vitamin_e_mg": 2.15, "vitamin_k_mcg": 31.73, "vitamin_b6_mg": 0.1, "vitamin_b12_mcg": 33.9, "thiamin_mg": 0.05, "riboflavin_mg": 0.14, "niacin_mg": 1.22, "folate_mcg": 25.55, "water_g": 282.26, "alcohol_g": 4.83, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store broth and noodles separately to prevent swelling. Clams should be eaten immediately for best texture.", "duration": "P1D"}, "freezer": {"notes": "Freezing changes the texture of cooked clams and noodles significantly; not recommended.", "duration": null}, "reheating": "Gently warm the broth on the stovetop and pour over room-temperature noodles.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": "Dutch oven"}, {"name": "Deep saut\u00e9 pan with lid", "required": true, "alternative": "Wok with lid"}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Fine mesh strainer", "required": false, "alternative": "Cheesecloth"}]', '[{"symptom": "Broth is gritty or sandy", "likely_cause": "Clams were not purged sufficiently", "prevention": "Ensure clams soak in salted water in the dark for at least 1 hour before cooking", "fix": "Remove clams and noodles, decant the broth slowly leaving the sediment at the bottom, or strain through a coffee filter/fine mesh cloth"}, {"symptom": "Clams are rubbery", "likely_cause": "Overcooking", "prevention": "Remove clams from heat the moment they open", "fix": "Cannot be fixed"}, {"symptom": "Noodles are mushy or gummy", "likely_cause": "Failed to rinse starch after boiling", "prevention": "Rinse vigorously under cold water immediately after boiling", "fix": "Cannot be fixed"}]', '["Rinsing soba noodles is not optional; rubbing them gently under cold running water removes the surface starch that makes the broth slimy.", "For the dashi, a combination of kombu (kelp) and katsuobushi (bonito flakes) yields the best depth, but high-quality instant dashi packets are acceptable for a quick weeknight version.", "If using frozen clams, they are usually pre-cleaned and do not require purging, but verify the package instructions.", "The ''Usukuchi'' (light-colored) soy sauce is saltier than regular soy sauce but keeps the broth clear and golden; if using regular soy sauce, reduce quantity slightly and taste."]', '"This dish draws inspiration from ''Asari no Sakamushi'' (sake-steamed clams), a classic Japanese izakaya dish. By combining the resulting mineral-rich clam liquor with dashi and adding buckwheat noodles, it transforms a popular appetizer into a restorative main course often enjoyed in spring when clams are in season."', 1172.02);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('20d74a06-7963-4156-bd95-3d02cd3e389f', 'Braised Skillet Chicken with Olives and Lemon', 'Succulent chicken thighs and drumsticks braised until falling-off-the-bone tender in a bright, savory broth. Briny green olives and zesty lemon cut through the richness, while wilted hearty greens add texture and nutrition to this rustic one-pan meal.', 'dinner', 'Mediterranean', 'Intermediate', '["one pot", "poultry", "chicken drumstick", "chicken thigh", "cilantro", "green olive", "lemon juice", "skillet", "stovetop", "sturdy greens", "dinner", "easy", "main course", "fall", "winter"]', '[{"group_name": "Chicken & Aromatics", "items": [{"name": "chicken thighs and drumsticks", "quantity": 1200, "unit": "g", "preparation": "bone-in, skin-on", "notes": "approx 4 thighs and 4 drumsticks", "substitutions": ["chicken marylands", "whole chicken cut into pieces"], "ingredient_id": "d7fc1bf9-fc05-429b-bfa6-2ad857cb0bb6", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "for searing", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "sliced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "minced", "notes": "approx 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Braising Liquid & Vegetables", "items": [{"name": "chicken stock", "quantity": 250, "unit": "ml", "preparation": "unsalted or low-sodium", "notes": null, "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}, {"name": "green olives", "quantity": 120, "unit": "g", "preparation": "pitted", "notes": "Castelvetrano or Picholine preferred", "substitutions": [], "ingredient_id": "8628da64-fa1c-4c91-badf-515667dbe9b9", "nutrition_source": "USDA FoodData Central"}, {"name": "lacinato kale", "quantity": 200, "unit": "g", "preparation": "stems removed, roughly chopped", "notes": "or swiss chard", "substitutions": ["swiss chard", "spinach"], "ingredient_id": "bb6a90eb-f157-455a-b438-d2333c784c60", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "ground coriander", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "ground turmeric", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "lemon", "quantity": 1, "unit": null, "preparation": "zested and juiced", "notes": "approx 45ml juice", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 15, "unit": "g", "preparation": "roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, adjust based on olive salinity", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the chicken pieces completely dry with paper towels. Season liberally on all sides with salt and freshly cracked black pepper.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Dry skin is crucial for achieving a crispy sear."]}, {"step_number": 2, "phase": "cook", "text": "Heat olive oil in a large skillet over medium-high heat. Place chicken skin-side down and sear undisturbed until deep golden brown, about 6-8 minutes. Flip and sear the other side for 2 minutes. Remove chicken to a plate and set aside.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to medium. Add sliced onions to the rendered fat in the skillet. Saut\u00e9 for 4-5 minutes until softened. Add minced garlic, cumin, coriander, and turmeric; cook for 1 minute until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT6M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour in the chicken stock and half of the lemon juice. Scrape the bottom of the pan with a wooden spoon or spatula to release any browned bits (fond).", "structured": {"action": "DEGLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Return the chicken to the pan, skin-side up. Scatter the pitted olives around the chicken. The liquid should come about halfway up the chicken (do not submerge the crispy skin). Reduce heat to low, cover, and simmer for 25 minutes.", "structured": {"action": "BRAISE", "temperature": null, "duration": "PT25M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Remove the lid. Stir in the chopped kale around the chicken pieces. Increase heat slightly and simmer uncovered for 5-7 minutes until the sauce reduces slightly and the chicken reaches an internal temperature of 74\u00b0C/165\u00b0F.", "structured": {"action": "SIMMER", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": "PT7M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from heat. Stir in the remaining lemon juice and zest. Taste the sauce and adjust salt if needed (olives add significant salt). Garnish with fresh cilantro before serving.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT35M", "total_time": "PT55M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Gluten-Free", "Dairy-Free", "Paleo", "Whole30", "Low-Carb", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 538.9, "protein_g": 63.36, "carbohydrates_g": 12.57, "fat_g": 26.6, "saturated_fat_g": 5.05, "trans_fat_g": 0.06, "monounsaturated_fat_g": 13.74, "polyunsaturated_fat_g": 4.22, "fiber_g": 4.22, "sugar_g": 2.82, "sodium_mg": 3461.53, "cholesterol_mg": 282, "potassium_mg": 1072.83, "calcium_mg": 146.82, "iron_mg": 4.68, "magnesium_mg": 97.67, "phosphorus_mg": 602.8, "zinc_mg": 5.1, "vitamin_a_mcg": 206.98, "vitamin_c_mg": 34.99, "vitamin_d_mcg": null, "vitamin_e_mg": 3.16, "vitamin_k_mcg": 181.38, "vitamin_b6_mg": 1.51, "vitamin_b12_mcg": 1.83, "thiamin_mg": 0.35, "riboflavin_mg": 0.69, "niacin_mg": 17.29, "folate_mcg": 31.22, "water_g": 351.13, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. The greens may lose some vibrancy upon reheating.", "duration": "P3D"}, "freezer": {"notes": "Remove bones before freezing for easier storage. Greens may become soft upon thawing.", "duration": "P2M"}, "reheating": "Gently warm in a covered skillet over medium-low heat with a splash of water or stock to prevent drying.", "does_not_keep": false}', '[{"name": "Large deep skillet or braiser with lid", "required": true, "alternative": "Dutch oven"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Chicken skin became soggy", "likely_cause": "Liquid level was too high or lid was kept on too long", "prevention": "Ensure braising liquid only covers the bottom 2/3 of the chicken; finish cooking uncovered", "fix": "Place the skillet under a hot broiler for 2-3 minutes to crisp the skin (watch closely to prevent burning)"}]', '["Castelvetrano olives are recommended for their buttery, mild flavor and firm texture compared to softer, more acidic varieties.", "Be cautious with added salt; as the braising liquid reduces and olives release their brine, the dish becomes naturally salty.", "For a thicker sauce, you can mash a few of the cooked garlic cloves and onion pieces into the liquid before serving.", "Serve directly from the skillet for a rustic presentation that keeps the food warm.", "If using spinach instead of kale, add it only in the last 2 minutes of cooking as it wilts much faster."]', '"This dish draws inspiration from North African tagines and Mediterranean skillet meals, utilizing the classic preservation trinity of olives, lemons, and cured aromatics. The technique of braising bone-in poultry with fruit and brine is a hallmark of Moroccan cuisine, adapted here for the modern stovetop."', 538.9);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('20ed0258-63a0-46bf-bb7d-524c253b2264', 'Stir-Fried Chinese Broccoli with Anchovies and Garlic', 'Vibrant emerald greens meet a savory, deep umami punch from melted anchovies and golden garlic. The crisp stems and tender leaves absorb the complex salty-savory sauce, creating a quick vegetable dish that rivals restaurant quality.', 'side dish', 'Chinese', 'Easy', '["anchovy fillets", "chinese broccoli", "garlic", "quick", "dinner", "stir-fry", "side dish", "low-carb"]', '[{"group_name": "Vegetables", "items": [{"name": "chinese broccoli (gai lan)", "quantity": 500, "unit": "g", "preparation": "washed and trimmed", "notes": "Trim tough ends; separate leaves from thick stems if stems are very thick", "substitutions": [], "ingredient_id": "d76b34d6-ab24-47c9-95a6-fe49dc10c82f", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 5, "unit": null, "preparation": "minced", "notes": "approximately 20g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics & Seasoning", "items": [{"name": "anchovy fillets in oil", "quantity": 6, "unit": null, "preparation": "chopped", "notes": "approximately 18g; use high quality fillets", "substitutions": [], "ingredient_id": "cfdad407-c486-4fcc-9e47-7dd4cb32277c", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "vegetable, canola, or grapeseed oil", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "shaoxing rice wine", "quantity": 15, "unit": "ml", "preparation": null, "notes": "optional; replace with water or dry sherry for gluten-free if needed", "substitutions": [], "ingredient_id": "bb7adcb8-7e07-46ec-a3ac-e02f9ffb6f9f", "nutrition_source": "Aggregated Public Data"}, {"name": "sugar", "quantity": 2, "unit": "g", "preparation": null, "notes": "just a pinch to balance the saltiness", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 30, "unit": "ml", "preparation": null, "notes": "for steam-frying", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the Chinese broccoli by washing thoroughly. Cut off and discard the bottom 1-2 cm of the tough stems. Slice the remaining stems diagonally into bite-sized pieces and keep the leaves whole or halved. Keep stems and leaves separate.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat the wok or large skillet over medium heat. Add the oil and the chopped anchovies. Cook, stirring constantly, until the anchovies break down and dissolve into the oil, about 1-2 minutes.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT2M", "doneness_cues": {"visual": "Anchovies have dissolved into a paste", "tactile": "Oil is fragrant"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the minced garlic to the anchovy oil. Stir-fry for 30 seconds until fragrant and pale golden. Be careful not to burn the garlic.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT30S", "doneness_cues": {"visual": "Garlic is pale golden", "tactile": "Aromatic"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Increase heat to high. Add the broccoli stems first. Stir-fry for 1-2 minutes until they turn bright green and start to soften.", "structured": {"action": "STIR", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the broccoli leaves, the splash of Shaoxing wine (if using), sugar, and water. Immediately cover the pan with a lid or baking sheet to trap the steam. Cook for 1-2 minutes.", "structured": {"action": "STEAM", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Leaves are wilted and dark green", "tactile": "Stems are tender-crisp"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Uncover and toss everything together for a final 30 seconds to evaporate excess liquid. Serve immediately.", "structured": {"action": "SERVE", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT0M", "total_time": "PT15M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 130}', '{"flags": ["Pescatarian", "Dairy-Free", "Nut-Free", "Peanut-Free", "Low-Carb", "Keto"], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 118.45, "protein_g": 2.67, "carbohydrates_g": 8.18, "fat_g": 8.64, "saturated_fat_g": 1.28, "trans_fat_g": null, "monounsaturated_fat_g": 0.06, "polyunsaturated_fat_g": 0.45, "fiber_g": 3.36, "sugar_g": 1.65, "sodium_mg": 14.65, "cholesterol_mg": null, "potassium_mg": 377.75, "calcium_mg": 145.74, "iron_mg": 1.02, "magnesium_mg": 26.88, "phosphorus_mg": 71.89, "zinc_mg": 0.63, "vitamin_a_mcg": 107.5, "vitamin_c_mg": 38.56, "vitamin_d_mcg": null, "vitamin_e_mg": 0.63, "vitamin_k_mcg": 111.46, "vitamin_b6_mg": 0.15, "vitamin_b12_mcg": null, "thiamin_mg": 0.14, "riboflavin_mg": 0.19, "niacin_mg": 0.61, "folate_mcg": 130.15, "water_g": 126.18, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Texture may soften slightly upon reheating.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; freezing destroys the crisp texture of the greens.", "duration": null}, "reheating": "Briefly stir-fry over high heat or microwave for 30-45 seconds.", "does_not_keep": false}', '[{"name": "Wok or large skillet", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Stems are tough but leaves are mushy", "likely_cause": "The stems and leaves were cooked for the same amount of time", "prevention": "Always add the thick stems to the wok 1-2 minutes before the delicate leaves", "fix": "Pick out the stems and microwave them for 30 seconds, then return to the mix"}, {"symptom": "Dish tastes burnt or bitter", "likely_cause": "Garlic was burned during the initial saut\u00e9", "prevention": "Add garlic only after anchovies have melted and keep heat medium until vegetables are added", "fix": "Cannot be fixed; burnt garlic flavor permeates the oil. Start over."}]', '["Anchovies are a cheat code for instant depth. They don''t make the dish taste ''fishy'', but rather provide a rich savory backbone similar to shrimp paste or fish sauce.", "If your Chinese broccoli has very thick stems (over 1.5 cm), slice them in half lengthwise before cutting diagonally to ensure even cooking.", "High heat is crucial for the final toss to achieve ''wok hei'' (breath of the wok) and prevent the vegetables from stewing in their own juices.", "This technique works brilliantly with other greens like broccolini, kale, or choy sum."]', '"In Cantonese cuisine, stir-frying leafy greens with salted fish is a classic preparation used to add intense umami to simple vegetables. This recipe substitutes hard-to-find traditional salted fish with accessible anchovy fillets, replicating that signature savory depth found in homestyle Hong Kong cooking."', 118.45);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('213e19f4-2466-4fbe-b6e6-31f4a304c7cd', 'Garlic Potato Pancakes', 'Crispy, golden-brown fritters with a tender interior, featuring the earthy comfort of grated potatoes sharpened by a hint of fresh garlic and savory onion. Perfect for soaking up sour cream or applesauce.', 'side dish', 'Eastern European', 'Easy', '["eastern european", "five ingredient", "potato", "vegetable pancake", "side dish", "vegetarian", "hanukkah"]', '[{"group_name": "Vegetable Base", "items": [{"name": "potatoes", "quantity": 500, "unit": "g", "preparation": "peeled", "notes": "starchy variety like Russet or Maris Piper", "substitutions": [], "ingredient_id": "a87814d3-a635-474b-a78d-4d20b45066e5", "nutrition_source": "Aggregated Public Data"}, {"name": "onion", "quantity": 1, "unit": null, "preparation": "peeled", "notes": "medium size, approx 100g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 6-8g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Binder & Seasoning", "items": [{"name": "egg", "quantity": 1, "unit": null, "preparation": "beaten", "notes": "large, approx 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "all-purpose flour", "quantity": 30, "unit": "g", "preparation": null, "notes": "can substitute matzo meal or potato starch", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": null, "notes": "freshly ground", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Frying", "items": [{"name": "vegetable oil", "quantity": 120, "unit": "ml", "preparation": null, "notes": "neutral high-heat oil like canola or sunflower", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Grate the peeled potatoes and onion using the large holes of a box grater into a clean kitchen towel or cheesecloth.", "structured": {"action": "GRATE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Gather the towel corners and twist tightly over a sink to squeeze out as much liquid as possible from the potato-onion mixture. This is critical for crispiness.", "structured": {"action": "DRAIN", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": ["If you see white starch settle at the bottom of the discarded liquid, you can save it and add it back to the mix for extra binding."]}, {"step_number": 3, "phase": "prep", "text": "Transfer the dry potato mixture to a large bowl. Add the minced garlic, beaten egg, flour, salt, and black pepper. Mix with a fork until thoroughly combined.", "structured": {"action": "MIX", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Heat the vegetable oil in a heavy-bottomed skillet over medium-high heat until it reaches approximately 175\u00b0C/350\u00b0F (shimmering but not smoking).", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Scoop about 60ml (1/4 cup) of batter per pancake into the hot oil. Flatten gently with the back of a spatula to form a disc about 1cm thick. Do not overcrowd the pan.", "structured": {"action": "FRY", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": ["Fry in batches of 3-4 to maintain oil temperature."]}, {"step_number": 6, "phase": "cook", "text": "Fry for 3 to 4 minutes per side until deeply golden brown and crisp. Transfer to a wire rack or paper towel-lined plate to drain excess oil.", "structured": {"action": "FRY", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Deep golden brown edges and surface", "tactile": "Crisp exterior"}}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT5M", "total_time": "PT30M", "overnight_required": false, "yields": "8 pancakes", "yield_count": 8, "serving_size_g": 65}', '{"flags": ["Vegetarian", "Dairy-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 213.87, "protein_g": 2.73, "carbohydrates_g": 15.61, "fat_g": 15.87, "saturated_fat_g": 2.37, "trans_fat_g": null, "monounsaturated_fat_g": 0.24, "polyunsaturated_fat_g": 0.14, "fiber_g": 5.4, "sugar_g": 1.05, "sodium_mg": 253.71, "cholesterol_mg": 23.25, "potassium_mg": 317.86, "calcium_mg": 14.91, "iron_mg": 0.52, "magnesium_mg": 17.98, "phosphorus_mg": 58.34, "zinc_mg": 0.36, "vitamin_a_mcg": 10.03, "vitamin_c_mg": 13.11, "vitamin_d_mcg": 0.13, "vitamin_e_mg": 0.07, "vitamin_k_mcg": 0.3, "vitamin_b6_mg": 0.04, "vitamin_b12_mcg": 0.06, "thiamin_mg": 0.02, "riboflavin_mg": 0.04, "niacin_mg": 0.08, "folate_mcg": 6.34, "water_g": 16.95, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten fresh; texture degrades quickly in fridge.", "duration": "P2D"}, "freezer": {"notes": "Freeze in single layers, then bag. Reheat from frozen.", "duration": "P2M"}, "reheating": "Reheat in a 190\u00b0C (375\u00b0F) oven for 5-8 minutes until crisp. Do not microwave.", "does_not_keep": false}', '[{"name": "Box grater", "required": true, "alternative": "Food processor with grating disc"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Clean kitchen towel or cheesecloth", "required": true, "alternative": "Strong paper towels (use multiple layers)"}, {"name": "Heavy-bottomed skillet", "required": true, "alternative": "Cast iron pan"}, {"name": "Spatula", "required": true, "alternative": null}]', '[{"symptom": "Pancakes are falling apart in the pan", "likely_cause": "Too much moisture in the mixture or not enough binder", "prevention": "Squeeze potatoes very thoroughly before mixing", "fix": "Stir in an extra tablespoon of flour or starch to the remaining batter"}, {"symptom": "Pancakes are soggy or greasy", "likely_cause": "Oil temperature was too low", "prevention": "Ensure oil is shimmering (175\u00b0C/350\u00b0F) before adding batter", "fix": "Increase heat slightly for the next batch; pop current ones in a hot oven to crisp up"}]', '["Work quickly once the potatoes are grated to prevent oxidation (turning pink/grey). The onion helps delay this, but speed is key.", "For the ultimate texture, use starchy potatoes (Russets) rather than waxy ones. Starch creates the crispy exterior.", "Don''t skip the garlic; while traditional latkes often omit it, the garlic here adds a savory depth that elevates them as a side dish.", "Serve immediately with sour cream and chives for a savory route, or applesauce for a sweet-savory contrast."]', '"Potato pancakes, known as ''Latkes'' in Yiddish or ''Draniki'' in Belarusian/Russian, are a staple of Eastern European cuisine. They are famously associated with Hanukkah to celebrate the miracle of the oil, but are eaten year-round as a comforting peasant dish utilizing humble root vegetables."', 213.87);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('21ba6107-a38d-40e8-96ec-6f97628b1523', 'Crab and Roasted Red Pepper Quiche', 'A sophisticated tart featuring a buttery, flaky shortcrust pastry filled with a silky, trembling custard. Sweet lumps of crab meat and smoky strips of roasted red pepper provide a delicate balance of flavors without overpowering the rich cream base.', 'dinner', 'French', 'Intermediate', '["crab meat", "egg", "heavy cream", "dinner", "french", "seafood", "elegant"]', '[{"group_name": "Shortcrust Pastry", "items": [{"name": "all-purpose flour", "quantity": 250, "unit": "g", "preparation": "chilled", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 125, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "ice water", "quantity": 60, "unit": "ml", "preparation": null, "notes": "Use as needed to bind", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Filling", "items": [{"name": "lump crab meat", "quantity": 200, "unit": "g", "preparation": "picked over for shells", "notes": null, "substitutions": [], "ingredient_id": "b29ab9d7-8084-4759-a623-ec61e8148bf9", "nutrition_source": "USDA FoodData Central"}, {"name": "roasted red peppers", "quantity": 120, "unit": "g", "preparation": "drained, patted dry, and sliced into strips", "notes": null, "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "approx 25g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "gruy\u00e8re cheese", "quantity": 50, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "321085d2-bb82-45e1-8ae3-5a2ef5cea47f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh chives", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Custard Base", "items": [{"name": "heavy cream", "quantity": 300, "unit": "ml", "preparation": null, "notes": "min 35% fat", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 100, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 4, "unit": null, "preparation": "large, room temperature", "notes": "approx 200g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "white pepper", "quantity": 1, "unit": "g", "preparation": "ground", "notes": null, "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "USDA FoodData Central"}, {"name": "nutmeg", "quantity": 1, "unit": "g", "preparation": "freshly grated", "notes": null, "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pulse flour and salt in a food processor to combine. Add cold, cubed butter and pulse briefly until the mixture resembles coarse meal with some pea-sized pieces of butter remaining.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Drizzle in ice water one tablespoon at a time, pulsing just until the dough begins to clump together. Do not overwork.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Turn dough onto a clean surface, gather into a ball, and flatten into a disk. Wrap in plastic and refrigerate for at least 30 minutes.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Preheat oven to 200\u00b0C (400\u00b0F). Roll dough out on a floured surface to a 30cm (12-inch) circle. Transfer to the tart pan, trim edges, and prick the bottom with a fork.", "structured": {"action": "ROLL", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Line the pastry shell with parchment paper and fill with pie weights. Blind bake for 15 minutes, then remove weights and paper. Bake for another 5-8 minutes until the bottom is dry and pale gold. Remove and lower oven temperature to 160\u00b0C (325\u00b0F).", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "While the crust cools slightly, gently saut\u00e9 the minced shallot in a small pan with a drop of oil or butter until translucent, about 3 minutes. Set aside to cool.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Whisk together eggs, heavy cream, milk, salt, white pepper, and nutmeg until smooth and fully combined.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Scatter half the cheese (if using) onto the base of the crust. Distribute the crab meat, roasted red pepper strips, saut\u00e9ed shallots, and chives evenly. Top with remaining cheese.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "assemble", "text": "Pour the custard mixture carefully over the filling. Ensure the ingredients remain evenly distributed.", "structured": {"action": "POUR", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "cook", "text": "Bake at 160\u00b0C (325\u00b0F) for 35 to 45 minutes. The center should still have a slight wobble (like gelatin) when the pan is gently shaken; it will set as it cools.", "structured": {"action": "BAKE", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT40M", "doneness_cues": {"visual": "Edges set, center slightly wobbly", "tactile": "Firm edges, gelatinous center"}}, "tips": []}, {"step_number": 11, "phase": "finish", "text": "Let the quiche rest on a wire rack for at least 20 minutes before slicing. This is crucial for the custard to set properly for clean slices.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT1H30M", "total_time": "PT2H15M", "overnight_required": false, "yields": "8 slices", "yield_count": 8, "serving_size_g": 165}', '{"flags": ["Pescatarian", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": ["Shellfish allergy"]}', '{"per_serving": {"calories": 454.27, "protein_g": 14.96, "carbohydrates_g": 27.35, "fat_g": 31.81, "saturated_fat_g": 18.84, "trans_fat_g": 0.48, "monounsaturated_fat_g": 8.79, "polyunsaturated_fat_g": 1.96, "fiber_g": 1.35, "sugar_g": 2.82, "sodium_mg": 754.7, "cholesterol_mg": 190.34, "potassium_mg": 240.81, "calcium_mg": 143.5, "iron_mg": 1.2, "magnesium_mg": 35.47, "phosphorus_mg": 234.05, "zinc_mg": 2.9, "vitamin_a_mcg": 357.67, "vitamin_c_mg": 22.33, "vitamin_d_mcg": 1.3, "vitamin_e_mg": 1.25, "vitamin_k_mcg": 3.43, "vitamin_b6_mg": 0.18, "vitamin_b12_mcg": 3.34, "thiamin_mg": 0.09, "riboflavin_mg": 0.27, "niacin_mg": 0.95, "folate_mcg": 43.91, "water_g": 103.27, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Cover tightly with foil or plastic wrap.", "duration": "P3D"}, "freezer": {"notes": "Texture of the custard may become slightly spongy upon thawing.", "duration": "P1M"}, "reheating": "Reheat in a 150\u00b0C (300\u00b0F) oven for 15 minutes until warm. Do not microwave as the crust will become soggy.", "does_not_keep": false}', '[{"name": "9-inch Tart Pan", "required": true, "alternative": "9-inch Pie Dish"}, {"name": "Food Processor", "required": false, "alternative": "Large mixing bowl and pastry blender"}, {"name": "Rolling Pin", "required": true, "alternative": null}, {"name": "Pie Weights", "required": true, "alternative": "Dried beans or uncooked rice"}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Fine Mesh Sieve", "required": false, "alternative": "Colander"}]', '[{"symptom": "Custard is curdled or watery (weeping)", "likely_cause": "Overcooked or oven temperature was too high", "prevention": "Bake at 160\u00b0C (325\u00b0F) and remove when the center still wobbles slightly", "fix": "Cannot be fixed, but is still safe to eat"}, {"symptom": "Soggy bottom crust", "likely_cause": "Insufficient blind baking or filling added while crust was too hot", "prevention": "Ensure the bottom is dry and pale gold before adding wet filling", "fix": "Place on the lowest oven rack or a preheated baking stone for the last 10 minutes"}]', '["Always pick through the crab meat carefully with your fingers to ensure no shell fragments remain; nothing ruins a delicate custard faster than crunching on shell.", "Pat the roasted red peppers very dry with paper towels before adding them. Excess liquid from the peppers can dilute the custard and prevent it from setting properly.", "Do not skip the resting period. If you cut into the quiche straight from the oven, the custard will be too fluid and will flow out of the slice.", "For an ultra-smooth texture, strain the egg and cream mixture through a fine-mesh sieve before pouring it into the shell to remove chalazae and air bubbles."]', '"Quiche is a classic French dish originating from the Lorraine region, though this variation leans toward a coastal or ''Proven\u00e7al'' style with the inclusion of seafood and peppers. While traditionally a peasant dish utilizing leftover dough and eggs, modern interpretations elevate it with premium ingredients like lump crab for elegant dining."', 454.27);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('2295c24a-53d0-4929-b6c1-19f1a9c06ba2', 'Classic Golden Egg Fried Rice', 'A quintessential Chinese comfort food featuring fluffy, distinct rice grains coated in savory soy sauce and tender scrambled egg curds, accented with the fresh bite of scallions and a hint of garlic.', 'lunch', 'Chinese', 'Easy', '["fried rice", "chinese", "quick", "easy", "wok", "leftovers"]', '[{"group_name": "Main", "items": [{"name": "cooked jasmine rice", "quantity": 400, "unit": "g", "preparation": "cold, day-old", "notes": "Ideally refrigerated overnight to dry out grains", "substitutions": [], "ingredient_id": "d8a2c73d-e2de-4182-b43b-6bdf55f00a87", "nutrition_source": "USDA FoodData Central"}, {"name": "large eggs", "quantity": 3, "unit": null, "preparation": "beaten", "notes": "approx. 150g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "neutral oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "canola, vegetable, or peanut oil", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Aromatics & Seasoning", "items": [{"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx. 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "scallions", "quantity": 2, "unit": null, "preparation": "sliced thin", "notes": "separate whites and greens; approx. 30g total", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "light soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0f7f45d7-9cfa-49f9-b60e-5db3fa280254", "nutrition_source": "Aggregated Public Data"}, {"name": "white pepper", "quantity": 1, "unit": "g", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "USDA FoodData Central"}, {"name": "sesame oil", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a9a59164-d949-4acd-99da-689f0a32e2e7", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "adjust based on soy sauce salinity", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare your mise en place: beat the eggs with a pinch of salt in a small bowl, mince the garlic, slice scallions (keep whites and greens separate), and break up any large clumps in the cold rice with your hands.", "structured": {"action": "MEASURE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat half the oil (15ml) in a wok or large pan over medium-high heat until shimmering (approx. 190\u00b0C/375\u00b0F).", "structured": {"action": "PREHEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Pour in the beaten eggs and scramble quickly. As soon as they are mostly set but still slightly runny, remove them from the pan and set aside.", "structured": {"action": "SCRAMBLE", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Eggs are set but soft", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the remaining oil to the pan. Saut\u00e9 the garlic and scallion whites for 30 seconds until fragrant, being careful not to burn them.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT30S", "doneness_cues": {"visual": "Aromatics are sizzling and fragrant", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the cold rice to the pan. Turn heat to high. Stir-fry constantly, pressing down with the spatula to break up grains, until the rice is hot and slightly toasted.", "structured": {"action": "FRY", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT3M", "doneness_cues": null}, "tips": ["Listen for a popping or crackling sound, which indicates the rice is drying out properly (''wok hei'')."]}, {"step_number": 6, "phase": "cook", "text": "Return the eggs to the pan. Drizzle soy sauce around the edges of the wok (not directly on the rice) to sear the sauce. Add white pepper and toss everything to combine evenly.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from heat. Stir in the scallion greens and sesame oil. Taste and add extra salt if needed before serving.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT0M", "total_time": "PT15M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 300}', '{"flags": ["Vegetarian", "Pescatarian", "Dairy-Free", "Nut-Free"], "not_suitable_for": ["Gluten intolerance (unless using tamari)"]}', '{"per_serving": {"calories": 523.77, "protein_g": 16.4, "carbohydrates_g": 55.48, "fat_g": 25.48, "saturated_fat_g": 4.67, "trans_fat_g": 0.03, "monounsaturated_fat_g": 2.9, "polyunsaturated_fat_g": 1.64, "fiber_g": 2.51, "sugar_g": 1.33, "sodium_mg": 913.41, "cholesterol_mg": 279, "potassium_mg": 269.38, "calcium_mg": 97.95, "iron_mg": 5.3, "magnesium_mg": 31.21, "phosphorus_mg": 269.52, "zinc_mg": 1.81, "vitamin_a_mcg": 127.5, "vitamin_c_mg": 3.86, "vitamin_d_mcg": 1.5, "vitamin_e_mg": 0.9, "vitamin_k_mcg": 31.33, "vitamin_b6_mg": 0.5, "vitamin_b12_mcg": 0.67, "thiamin_mg": 0.47, "riboflavin_mg": 0.4, "niacin_mg": 4.78, "folate_mcg": 206.99, "water_g": 213.24, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Reheat thoroughly until steaming hot.", "duration": "P3D"}, "freezer": {"notes": "Texture may degrade slightly upon thawing.", "duration": "P1M"}, "reheating": "Stir-fry in a pan with a splash of water or microwave.", "does_not_keep": false}', '[{"name": "Wok or large frying pan", "required": true, "alternative": "Cast iron skillet"}, {"name": "Spatula", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Rice is mushy and clumpy", "likely_cause": "Rice was too fresh or too wet", "prevention": "Use day-old refrigerated rice; the retrogradation of starch helps grains stay separate", "fix": "Spread rice on a baking sheet and let it dry out in the fridge for 30 minutes before cooking, or cook longer on high heat"}]', '["Cold Rice is Key: Freshly cooked rice has too much moisture. If you must use fresh rice, spread it on a tray and freeze for 15 minutes to dry the surface.", "Wok Hei: To get that restaurant-style smoky flavor at home, cook in small batches and ensure your pan is very hot before adding ingredients.", "Seasoning Balance: Soy sauce provides color and umami, but too much makes the rice wet. Use salt for the primary salinity adjustment.", "Oil Management: Don''t skimp on oil; each grain of rice needs to be lightly lubricated to prevent sticking and achieve the correct texture."]', '"Fried rice (ch\u01ceof\u00e0n) originated in the Sui dynasty (589\u2013618 AD) as a way to avoid wasting leftover rice. What began as a humble peasant dish has evolved into a staple of Chinese cuisine, celebrated for its ability to transform simple leftovers into a satisfying meal through the art of ''wok hei'' (breath of the wok)."', 523.77);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('232ce669-3dad-4d7b-92d9-b22406940957', 'Citrus-Herb Roasted Turkey Thighs with Cranberry-Onion Quick Pickle', 'Succulent, dark-meat turkey thighs with shatteringly crisp, bronzed skin infused with garlic, thyme, and dual-citrus zest. Served with a vibrant, jewel-toned quick pickle that offers a sharp, tangy counterpoint to the savory richness of the roasted bird.', 'main course', 'American', 'Intermediate', '["american", "poultry", "budget", "cranberry", "garlic", "lemon", "lime", "thyme", "turkey", "main course", "fall", "thanksgiving"]', '[{"group_name": "Quick-Pickled Cranberries & Onions", "items": [{"name": "red onion", "quantity": 1, "unit": null, "preparation": "thinly sliced into half-moons", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "dried cranberries", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "788f186b-788f-4fcd-aff0-ab8983926e97", "nutrition_source": "USDA FoodData Central"}, {"name": "red wine vinegar", "quantity": 120, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "9e1b7e74-fdcb-4836-8349-4f7ad86d62df", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh lime juice", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "sugar", "quantity": 25, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Turkey Thighs", "items": [{"name": "turkey thighs", "quantity": 4, "unit": null, "preparation": "bone-in, skin-on", "notes": "approx. 1.2kg total", "substitutions": [], "ingredient_id": "4894b916-97da-4b23-9a6c-de2c72de5b3f", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "minced or grated", "notes": null, "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme leaves", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": null, "notes": "from 1 lemon", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "Aggregated Public Data"}, {"name": "lime zest", "quantity": 1, "unit": null, "preparation": null, "notes": "from 1 lime", "substitutions": [], "ingredient_id": "295e8d21-9ba3-4ab8-a118-b09b77defacc", "nutrition_source": "Aggregated Public Data"}, {"name": "kosher salt", "quantity": 12, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 3, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the pickling brine. In a small saucepan, combine red wine vinegar, water, sugar, and salt. Bring to a boil over medium-high heat until sugar and salt are fully dissolved.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Place sliced red onions and dried cranberries in a heat-proof bowl. Pour the hot brine over them, stir in the fresh lime juice, and let sit at room temperature to pickle while you cook the turkey.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": ["The heat hydrates the cranberries and takes the raw bite out of the onion."]}, {"step_number": 3, "phase": "prep", "text": "Preheat your oven to 200\u00b0C (400\u00b0F). While the oven heats, make the herb rub: In a small bowl, mix the olive oil, minced garlic, chopped thyme, lemon zest, lime zest, salt, and pepper into a paste.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Pat the turkey thighs thoroughly dry with paper towels\u2014this is critical for crispy skin. Gently loosen the skin from the meat with your fingers without detaching it completely.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Rub half of the herb mixture underneath the skin directly onto the meat. Rub the remaining mixture all over the outside of the skin and the underside of the thighs.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Place the thighs skin-side up on a rimmed baking sheet or roasting pan. Roast for 40-50 minutes, or until the skin is deep golden brown and an internal thermometer registers 74\u00b0C (165\u00b0F) at the thickest part without touching the bone.", "structured": {"action": "ROAST", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT45M", "doneness_cues": {"visual": "Deep golden brown, crispy skin", "tactile": "Internal temp 74\u00b0C/165\u00b0F"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove turkey from the oven and let it rest for 10 minutes to allow juices to redistribute. Serve topped with a generous spoonful of the drained pickled onions and cranberries.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT15M", "total_time": "PT1H20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Gluten-Free", "Dairy-Free", "Nut-Free", "Paleo", "Whole30", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 551.88, "protein_g": 62.8, "carbohydrates_g": 25.66, "fat_g": 22.62, "saturated_fat_g": 3.95, "trans_fat_g": 0.09, "monounsaturated_fat_g": 10.52, "polyunsaturated_fat_g": 3.41, "fiber_g": 2.27, "sugar_g": 18.99, "sodium_mg": 1880.55, "cholesterol_mg": 234, "potassium_mg": 935.88, "calcium_mg": 47.46, "iron_mg": 5.21, "magnesium_mg": 78.77, "phosphorus_mg": 556.76, "zinc_mg": 9.05, "vitamin_a_mcg": 63.62, "vitamin_c_mg": 11.38, "vitamin_d_mcg": 1.5, "vitamin_e_mg": 2.51, "vitamin_k_mcg": 9.4, "vitamin_b6_mg": 1.56, "vitamin_b12_mcg": 6.51, "thiamin_mg": 0.22, "riboflavin_mg": 0.97, "niacin_mg": 18.76, "folate_mcg": 30.44, "water_g": 318.38, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store turkey and pickles in separate airtight containers.", "duration": "P3D"}, "freezer": {"notes": "Meat freezes well; pickles lose texture and should be consumed fresh.", "duration": "P3M"}, "reheating": "Reheat turkey in a 175\u00b0C oven covered with foil to prevent drying, then uncover for the last 5 minutes to re-crisp skin.", "does_not_keep": false}', '[{"name": "Roasting pan or rimmed baking sheet", "required": true, "alternative": "Cast iron skillet"}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Microplane or zester", "required": true, "alternative": null}, {"name": "Meat thermometer", "required": true, "alternative": null}, {"name": "Heat-proof bowl", "required": true, "alternative": null}]', '[{"symptom": "Turkey skin is rubbery or flabby", "likely_cause": "Excess moisture on the skin before roasting or oven temperature too low", "prevention": "Pat skin extremely dry before seasoning; ensure oven is fully preheated to 200\u00b0C", "fix": "Turn on the oven broiler for 1-2 minutes, watching constantly to prevent burning"}]', '["Always roast dark meat like thighs to at least 74\u00b0C (165\u00b0F); unlike breast meat, thighs actually benefit from slightly higher temps (up to 80\u00b0C/175\u00b0F) as it breaks down collagen, making them more tender.", "For the smoothest rub application, use room temperature oil. If your kitchen is cold, microwave the oil for 10 seconds before mixing in herbs.", "The pickle improves with time. You can make the onion-cranberry mixture up to 3 days in advance and store it in the fridge; the cranberries will plump significantly.", "Save the roasted thigh bones. They are rich in collagen and make a superior turkey stock compared to breast bones."]', '"This recipe reimagines the American Thanksgiving centerpiece by addressing the common complaint of dry white meat. By focusing on the thigh\u2014the most flavorful and forgiving cut\u2014and brightening it with heavy citrus and acid, it shifts the profile from heavy comfort food to a more modern, palate-cleansing autumnal meal."', 551.88);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('2388d8a1-e508-40be-93a0-a8e852901321', 'Velvet Celeriac Puree', 'A sophisticated alternative to mashed potatoes, this puree offers a silky texture with the subtle, nutty flavor of celery root. Enriched with creaminess from a milk poach and finished with cold butter for a glossy sheen, it pairs exceptionally well with roasted meats or rich winter stews.', 'side dish', 'French', 'Intermediate', '["celery root", "five ingredient", "side dish", "winter", "vegetarian", "christmas", "french", "elegant"]', '[{"group_name": "Main", "items": [{"name": "celeriac", "quantity": 800, "unit": "g", "preparation": "peeled and diced into 2cm cubes", "notes": "approx. 1 large root; weigh after peeling", "substitutions": [], "ingredient_id": "2fcb3469-785d-4383-ac0d-773795c790f8", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 500, "unit": "ml", "preparation": null, "notes": "enough to just cover the vegetables", "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Using a sharp knife, cut away the thick, knobby skin of the celeriac until only the creamy white flesh remains. Dice into uniform 2cm cubes.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Be aggressive when peeling celeriac; the root end can trap dirt deep inside.", "Rub cut surfaces with lemon to prevent browning if not cooking immediately."]}, {"step_number": 2, "phase": "cook", "text": "Place the celeriac cubes, milk, and half the salt in a large saucepan. Ensure the milk just covers the vegetables (add a splash of water if necessary). Bring to a boil, then reduce heat immediately to a gentle simmer.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Simmer uncovered for 15-20 minutes until the celeriac is completely tender and offers no resistance when pierced with a knife.", "structured": {"action": "SIMMER", "temperature": null, "duration": null, "doneness_cues": {"visual": "Milk has reduced and thickened slightly", "tactile": "Mushy when pressed with a fork"}}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Drain the celeriac through a colander, reserving the hot cooking milk in a separate bowl. Do not discard the liquid.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Transfer the hot celeriac to a blender. Add the lemon juice and a small splash (about 30ml) of the reserved cooking milk. Puree on high speed.", "structured": {"action": "PUREE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "With the blender running, gradually add the cold butter cubes one by one to emulsify. Adjust consistency with more reserved milk if needed until it reaches a thick, velvety texture.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Adding cold butter creates a tighter, glossier emulsion than melted butter."]}, {"step_number": 7, "phase": "finish", "text": "For a Michelin-level texture, pass the puree through a fine-mesh sieve (chinois) into a warm serving bowl. Season with remaining salt to taste.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT20M", "total_time": "PT40M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 150}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Egg-Free", "Low-Carb"], "not_suitable_for": ["Vegans (contains dairy)", "Lactose intolerant"]}', '{"per_serving": {"calories": 268.35, "protein_g": 7.07, "carbohydrates_g": 24.58, "fat_g": 16.83, "saturated_fat_g": 10.06, "trans_fat_g": null, "monounsaturated_fat_g": 4.64, "polyunsaturated_fat_g": 1, "fiber_g": 3.61, "sugar_g": 9.59, "sodium_mg": 740.43, "cholesterol_mg": 44.75, "potassium_mg": 771.28, "calcium_mg": 231.3, "iron_mg": 1.45, "magnesium_mg": 52.96, "phosphorus_mg": 338.8, "zinc_mg": 1.14, "vitamin_a_mcg": 160.1, "vitamin_c_mg": 16.97, "vitamin_d_mcg": 1.63, "vitamin_e_mg": 1.16, "vitamin_k_mcg": 83.43, "vitamin_b6_mg": 0.39, "vitamin_b12_mcg": 0.59, "thiamin_mg": 0.17, "riboflavin_mg": 0.34, "niacin_mg": 1.52, "folate_mcg": 23.2, "water_g": 290.87, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Press plastic wrap directly onto the surface to prevent skin formation.", "duration": "P3D"}, "freezer": {"notes": "Texture may degrade slightly; reheat gently while whisking.", "duration": "P1M"}, "reheating": "Reheat gently in a saucepan over low heat, adding a splash of milk or water to loosen consistency.", "does_not_keep": false}', '[{"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Vegetable peeler", "required": true, "alternative": null}, {"name": "Large saucepan", "required": true, "alternative": null}, {"name": "High-speed blender", "required": true, "alternative": "Food processor or immersion blender"}, {"name": "Fine-mesh sieve (Chinois)", "required": false, "alternative": "Standard strainer"}]', '[{"symptom": "Texture is grainy or lumpy", "likely_cause": "Celeriac was undercooked or blender speed was too low", "prevention": "Cook until the vegetable falls apart when touched; use a high-speed blender", "fix": "Pass through a fine-mesh sieve twice to remove lumps"}, {"symptom": "Milk scorched on bottom of pan", "likely_cause": "Heat was too high during simmering", "prevention": "Simmer gently; milk boils over and burns easily at high temps", "fix": "Do not scrape the bottom of the pan when pouring out; taste the milk. If burnt, rinse celeriac and blend with fresh cream/milk"}]', '["To keep the puree snowy white, ensure you peel away all green parts of the root and cook entirely in milk rather than water.", "Celeriac absorbs liquid differently than potatoes. Add the reserved liquid slowly; you can always add more, but you cannot take it out.", "The lemon juice is critical not just for flavor balance, but to prevent the puree from oxidizing and turning grey as it sits.", "This dish is an excellent low-carb substitute for mashed potatoes on a holiday table."]', '"Known in France as Pur\u00e9e de C\u00e9leri-Rave, this dish highlights the often-overlooked celery root. It became a staple in French bistros as a winter accompaniment that offers the comfort of a starch with a more complex, herbaceous flavor profile suitable for cutting through rich sauces."', 268.35);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('23cd6196-a329-4f4a-814d-e6357923302f', 'Minted Lemon Pea Fritters', 'Vibrant, emerald-green fritters boasting a crispy golden exterior and a tender, sweet pea interior. Brightened with aromatic fresh mint and zesty lemon, these fritters offer a refreshing burst of spring flavors balanced by the salty tang of feta.', 'appetizer', 'Mediterranean', 'Easy', '["fritters", "pea", "vegetarian", "quick", "summer", "lunch"]', '[{"group_name": "Fritter Base", "items": [{"name": "green peas", "quantity": 400, "unit": "g", "preparation": "thawed if frozen", "notes": "Fresh or frozen work equally well", "substitutions": [], "ingredient_id": "881b19fa-ab56-40da-b76e-46e9098ff18f", "nutrition_source": "USDA FoodData Central"}, {"name": "scallions", "quantity": 3, "unit": null, "preparation": "finely sliced", "notes": "approx 45g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh mint leaves", "quantity": 15, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "213e3d3b-d332-45a9-b35e-23ee29a27173", "nutrition_source": "USDA FoodData Central"}, {"name": "feta cheese", "quantity": 100, "unit": "g", "preparation": "crumbled", "notes": null, "substitutions": [], "ingredient_id": "a9a8605c-3bf2-4ca3-8c58-80e87aff7cd8", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": "zested", "notes": "zest only needed", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Binder", "items": [{"name": "eggs", "quantity": 2, "unit": null, "preparation": "beaten", "notes": "large size (approx 100g total)", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "all-purpose flour", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": ["chickpea flour", "gluten-free all-purpose flour"], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Frying", "items": [{"name": "olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": "plus more as needed for shallow frying", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the peas in a food processor and pulse 3-4 times. You want a coarse texture with some whole peas remaining, not a smooth puree. Alternatively, mash roughly with a potato masher.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": {"visual": "Coarse, chunky texture", "tactile": "Not pureed"}}, "tips": []}, {"step_number": 2, "phase": "assemble", "text": "In a large mixing bowl, combine the crushed peas, beaten eggs, flour, baking powder, sliced scallions, chopped mint, lemon zest, crumbled feta, salt, and pepper. Mix until just combined into a thick batter.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Uniform batter holding its shape", "tactile": null}}, "tips": ["Do not overmix after adding flour to avoid tough fritters."]}, {"step_number": 3, "phase": "cook", "text": "Heat the olive oil in a large non-stick frying pan over medium heat (approx 175\u00b0C/350\u00b0F). Drop heaped tablespoons of the mixture into the pan, flattening them slightly with the back of the spoon. Do not overcrowd the pan.", "structured": {"action": "FRY", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Fry for 2-3 minutes per side until golden brown and crispy. Ensure the center is cooked through (internal temp should reach 74\u00b0C/165\u00b0F due to raw eggs).", "structured": {"action": "FRY", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Golden brown crust", "tactile": "Firm to the touch"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Transfer the fritters to a wire cooling rack or a paper towel-lined plate to drain excess oil. Serve immediately.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "12 fritters", "yield_count": 4, "serving_size_g": 160}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 381.4, "protein_g": 15.08, "carbohydrates_g": 36.66, "fat_g": 19.72, "saturated_fat_g": 5.78, "trans_fat_g": 0.01, "monounsaturated_fat_g": 10.35, "polyunsaturated_fat_g": 2.13, "fiber_g": 7.08, "sugar_g": 6.13, "sodium_mg": 752.77, "cholesterol_mg": 115.25, "potassium_mg": 378.96, "calcium_mg": 258.5, "iron_mg": 2.96, "magnesium_mg": 52.39, "phosphorus_mg": 303.66, "zinc_mg": 2.55, "vitamin_a_mcg": 122.91, "vitamin_c_mg": 44.1, "vitamin_d_mcg": 0.6, "vitamin_e_mg": 2.14, "vitamin_k_mcg": 55.87, "vitamin_b6_mg": 0.34, "vitamin_b12_mcg": 0.65, "thiamin_mg": 0.36, "riboflavin_mg": 0.49, "niacin_mg": 2.8, "folate_mcg": 102.93, "water_g": 129.21, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container with paper towels to absorb moisture.", "duration": "P3D"}, "freezer": {"notes": "Freeze in a single layer before bagging. Reheat from frozen.", "duration": "P1M"}, "reheating": "Reheat in a 180\u00b0C/350\u00b0F oven or dry skillet for 5-8 minutes to restore crispness.", "does_not_keep": false}', '[{"name": "Food processor", "required": false, "alternative": "Potato masher and large bowl"}, {"name": "Large non-stick frying pan", "required": true, "alternative": null}, {"name": "Spatula", "required": true, "alternative": null}, {"name": "Microplane or zester", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": false, "alternative": "Plate lined with paper towels"}]', '[{"symptom": "Fritters fall apart in the pan", "likely_cause": "Binder was too wet or fritters were flipped before the crust set", "prevention": "Ensure oil is hot before adding batter; wait for a clear golden crust before flipping", "fix": "Add 1 tablespoon of extra flour to the remaining batter"}, {"symptom": "Soggy fritters", "likely_cause": "Oil temperature too low", "prevention": "Use a thermometer or test with a small piece of batter; it should sizzle immediately", "fix": "Increase heat slightly and finish in a hot oven"}]', '["Frozen peas are actually preferred here over fresh unless they are just picked, as frozen peas retain sweetness and consistent texture.", "Serve with a simple dip of Greek yogurt, lemon juice, and a pinch of salt to cut through the richness.", "For a lighter texture, separate the egg whites, whip them to soft peaks, and fold them into the batter at the end.", "If using canned peas, drain and dry them very thoroughly, as they contain excess moisture that can ruin the batter consistency."]', '"Vegetable fritters, known as ''keftedes'' in Greece or similar variations across the Mediterranean, are a staple way to utilize seasonal produce. This recipe draws on those traditions, utilizing the classic pairing of sweet peas, salty cheese, and bright citrus common in Modern European bistro cooking."', 381.4);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('2471ec1d-9ee0-48da-ad23-adb9df6de5b4', 'Savory Miso-Lemon Tofu Ricotta', 'A velvety, plant-based essential that mimics the lactic tang and curd-like soft texture of traditional dairy ricotta. The inclusion of white miso provides a fermented depth that bridges the gap between simple tofu and a complex cheese alternative. Perfect for lasagna layers, stuffed shells, or as a protein-rich spread on crostini.', 'base', 'Fusion', 'Easy', '["dips and spreads", "extra-firm tofu", "food processor", "freezer friendly", "lemon zest", "miso", "nutritional yeast", "easy", "quick", "weeknight", "dairy-free", "gluten-free", "vegan", "vegetarian"]', '[{"group_name": "Base", "items": [{"name": "extra-firm tofu", "quantity": 400, "unit": "g", "preparation": "drained", "notes": "Standard 14oz/400g block", "substitutions": [], "ingredient_id": "1ba9238a-ce4f-4ca5-920d-7f483d9987aa", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Flavor Profile", "items": [{"name": "nutritional yeast", "quantity": 15, "unit": "g", "preparation": null, "notes": "Provides cheesy, nutty flavor", "substitutions": [], "ingredient_id": "96b2a5ce-e0e4-4571-94de-5e9fdc702561", "nutrition_source": "Aggregated Public Data"}, {"name": "extra virgin olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "Adds necessary fat for mouthfeel", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "white miso paste", "quantity": 18, "unit": "g", "preparation": null, "notes": "Shiro miso; for umami and fermentation funk", "substitutions": [], "ingredient_id": "46697260-96ba-4751-83c0-b40aebb81229", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": "finely grated", "notes": "zest of 1 medium lemon (approx 3g)", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "peeled", "notes": "small clove (approx 3g)", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "Adjust to taste depending on miso salinity", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Press the tofu to remove excess moisture. Wrap the block in a clean kitchen towel and place a heavy object (like a cast-iron skillet) on top for 15 minutes. This is crucial for preventing a watery final product.", "structured": {"action": "DRAIN", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "While tofu presses, zest the lemon and squeeze the juice. Peel the garlic clove.", "structured": {"action": "ZEST", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Break the pressed tofu into rough chunks and place into the food processor bowl. Add the nutritional yeast, olive oil, white miso, lemon juice, lemon zest, garlic, and salt.", "structured": {"action": "MEASURE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pulse the mixture 10-15 times. Stop to scrape down the sides with a spatula. Continue pulsing until the mixture resembles the crumbly yet spreadable texture of dairy ricotta. Do not over-process into a smooth paste unless a cream cheese texture is desired.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Resembles damp curds", "tactile": "Grainy but cohesive"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Taste and adjust seasoning. Add more lemon juice for brightness or a pinch more salt if the flavor feels flat. Transfer to a container and refrigerate for at least 30 minutes to let flavors meld before serving.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT15M", "total_time": "PT25M", "overnight_required": false, "yields": "450g", "yield_count": 9, "serving_size_g": 50}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": ["Soy allergy sufferers"]}', '{"per_serving": {"calories": 74.11, "protein_g": 4.73, "carbohydrates_g": 2.06, "fat_g": 5.65, "saturated_fat_g": 0.79, "trans_fat_g": null, "monounsaturated_fat_g": 2.93, "polyunsaturated_fat_g": 1.61, "fiber_g": 0.69, "sugar_g": 0.74, "sodium_mg": 211.39, "cholesterol_mg": null, "potassium_mg": 101.17, "calcium_mg": 161.42, "iron_mg": 2.91, "magnesium_mg": 36.8, "phosphorus_mg": 67.34, "zinc_mg": 3.75, "vitamin_a_mcg": 0.14, "vitamin_c_mg": 0.97, "vitamin_d_mcg": null, "vitamin_e_mg": 0.49, "vitamin_k_mcg": 4.03, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": null, "thiamin_mg": 0.04, "riboflavin_mg": 0.03, "niacin_mg": 0.11, "folate_mcg": 7.46, "water_g": 40.52, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Flavor improves after resting for 2-4 hours.", "duration": "P5D"}, "freezer": {"notes": "Texture may become slightly spongier upon thawing; best used in cooked applications like lasagna after freezing.", "duration": "P1M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Food processor", "required": true, "alternative": "High-speed blender (pulse carefully) or potato masher"}, {"name": "Tofu press", "required": false, "alternative": "Clean kitchen towel and heavy skillet"}, {"name": "Microplane or zester", "required": true, "alternative": null}, {"name": "Spatula", "required": true, "alternative": null}]', '[{"symptom": "Texture is too watery or runny", "likely_cause": "Tofu was not pressed sufficiently", "prevention": "Press tofu for at least 15 minutes under heavy weight", "fix": "Spread mixture on a clean towel or several layers of paper towel for 10 minutes to wick away moisture, then stir again"}, {"symptom": "Flavor tastes strongly of raw soy", "likely_cause": "Insufficient acid or salt to mask the tofu base", "prevention": "Ensure measurements for lemon and miso are accurate", "fix": "Add another teaspoon of lemon juice or a pinch of onion powder; letting it rest in the fridge for 2 hours also significantly reduces the bean flavor"}]', '["White Miso (Shiro Miso) is preferred here for its delicate, sweet flavor. Red miso will be too overpowering and will darken the color of the ''cheese''.", "For a variation used in lasagna, pulse in a handful of fresh basil leaves or spinach during the final blending step.", "If you need a strictly Gluten-Free recipe, double-check your miso paste and nutritional yeast labels, as some brands are processed with barley or wheat.", "This base accepts herbs beautifully. Fold in chopped chives, parsley, or dill after processing for a herbed spread."]', '"While Ricotta is a staple of Italian cheesemaking traditionally made from whey leftover from other cheeses, this plant-based adaptation utilizes the coagulation of soy proteins. It embraces the concept of ''kaiseki'' precision by using miso (fermented soybeans) to replicate the depth of aged fermentation found in dairy, effectively creating a fusion ingredient that honors Italian application with Japanese ingredients."', 74.11);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('253c12d7-b604-44a8-a726-75364723709a', 'Mediterranean Rice-Stuffed Tomatoes with Currants and Pine Nuts', 'Juicy, ripe tomatoes hollowed and filled with an aromatic mixture of rice, sweet currants, buttery pine nuts, and fresh mint. This dish balances savory, sweet, and tangy notes, creating a classic Mediterranean flavor profile that tastes even better the next day.', 'side dish', 'Mediterranean', 'Intermediate', '["rice", "tomato", "appetizer", "side dish", "vegetarian", "vegan", "mediterranean", "summer"]', '[{"group_name": "Tomatoes", "items": [{"name": "large beefsteak tomatoes", "quantity": 6, "unit": null, "preparation": "firm but ripe", "notes": "approx. 250-300g each", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Filling", "items": [{"name": "olive oil", "quantity": 80, "unit": "ml", "preparation": null, "notes": "divided use", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 2, "unit": null, "preparation": "finely diced", "notes": "approx. 200g total", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "pine nuts", "quantity": 40, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "971298ad-a9d7-49f7-811b-46afedad18d4", "nutrition_source": "Aggregated Public Data"}, {"name": "medium-grain rice", "quantity": 150, "unit": "g", "preparation": null, "notes": "rinsed; Arborio or Carolina", "substitutions": [], "ingredient_id": "d35782e6-8142-4414-b055-230d48cacc79", "nutrition_source": "USDA FoodData Central"}, {"name": "dried currants", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a5b09c92-80d2-4f02-b3e4-611ef6b0d557", "nutrition_source": "Aggregated Public Data"}, {"name": "tomato pulp", "quantity": null, "unit": null, "preparation": null, "notes": "reserved from scooping tomatoes", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 120, "unit": "ml", "preparation": null, "notes": "divided use", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh mint", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "213e3d3b-d332-45a9-b35e-23ee29a27173", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "ground allspice", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 0.5 tsp", "substitutions": [], "ingredient_id": "d0b9d4b4-744d-472b-bb19-a779a23d70c6", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 6, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 180\u00b0C (350\u00b0F). Wash and dry the tomatoes.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Slice the top 2cm off each tomato to create a lid and reserve. Using a spoon or melon baller, carefully scoop out the pulp and seeds into a bowl, leaving a shell about 0.5cm thick. Do not puncture the skin.", "structured": {"action": "CORE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Finely chop or pulse the scooped tomato pulp in a blender until it forms a chunky sauce.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Heat 60ml of olive oil in a large saut\u00e9 pan over medium heat. Add the diced onions and pine nuts. Saut\u00e9 for 5-7 minutes until the onions are translucent and the pine nuts are lightly golden.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT7M", "doneness_cues": {"visual": "Onions translucent, pine nuts golden", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the rinsed rice to the pan and stir for 1 minute to coat in the oil. Add the blended tomato pulp, currants, allspice, salt, pepper, and half of the water (60ml). Simmer gently until the liquid is mostly absorbed but the rice is only par-cooked (about 5-8 minutes).", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Liquid absorbed", "tactile": "Rice still has a hard center"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove the filling from heat. Stir in the chopped fresh mint and parsley.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Spoon the rice mixture into the hollowed tomato shells, filling them only 3/4 full to allow the rice to expand further during baking. Place the reserved tomato lids on top.", "structured": {"action": "STUFF", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Arrange the stuffed tomatoes snugly in a baking dish. Drizzle with the remaining olive oil (20ml) and pour the remaining water (60ml) into the bottom of the dish (not over the tomatoes).", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Bake for 60 to 75 minutes at 180\u00b0C (350\u00b0F). The tomato skins should wrinkle slightly and the rice should be tender. If the tops brown too quickly, cover loosely with foil halfway through.", "structured": {"action": "BAKE", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT1H15M", "doneness_cues": {"visual": "Skins wrinkled", "tactile": "Rice tender throughout"}}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Remove from oven and let cool for at least 30 minutes. The flavors settle and improve as the dish cools to room temperature.", "structured": {"action": "REST", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT1H15M", "total_time": "PT1H50M", "overnight_required": false, "yields": "6 stuffed tomatoes", "yield_count": 6, "serving_size_g": 280}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 350.7, "protein_g": 6.88, "carbohydrates_g": 42.94, "fat_g": 18.33, "saturated_fat_g": 2.53, "trans_fat_g": null, "monounsaturated_fat_g": 9.79, "polyunsaturated_fat_g": 1.47, "fiber_g": 7.93, "sugar_g": 18.93, "sodium_mg": 412.4, "cholesterol_mg": null, "potassium_mg": 1024.41, "calcium_mg": 64.66, "iron_mg": 2.1, "magnesium_mg": 72.39, "phosphorus_mg": 166.78, "zinc_mg": 1.42, "vitamin_a_mcg": 16.29, "vitamin_c_mg": 55.01, "vitamin_d_mcg": null, "vitamin_e_mg": 1.95, "vitamin_k_mcg": 49.71, "vitamin_b6_mg": 0.08, "vitamin_b12_mcg": null, "thiamin_mg": 0.04, "riboflavin_mg": 0.03, "niacin_mg": 0.53, "folate_mcg": 15.41, "water_g": 57.16, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves after resting overnight.", "duration": "P4D"}, "freezer": {"notes": "Not recommended; tomatoes become watery upon thawing.", "duration": null}, "reheating": "Gentle warming in oven or microwave, though traditionally served at room temperature.", "does_not_keep": false}', '[{"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Spoon or melon baller", "required": true, "alternative": "Small measuring spoon"}, {"name": "Large saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Blender or food processor", "required": false, "alternative": "Box grater"}, {"name": "Baking dish (ceramic or glass)", "required": true, "alternative": null}]', '[{"symptom": "Rice inside the tomato is crunchy", "likely_cause": "Rice wasn''t par-cooked enough or not enough liquid in the pan", "prevention": "Ensure the filling absorbs the tomato pulp liquid before stuffing; adding water to the baking dish creates steam.", "fix": "Add a splash more water to the baking dish, cover tightly with foil, and bake for an additional 15-20 minutes."}, {"symptom": "Tomatoes collapsed or burst", "likely_cause": "Oven too hot or tomatoes were overfilled", "prevention": "Fill only 3/4 full; use firm tomatoes.", "fix": "Cannot be fixed aesthetically, but still edible and delicious."}]', '["Choose tomatoes that are firm with thick walls. Beefsteak varieties hold their shape best during the long bake.", "Do not skip the resting period. Like many olive-oil-based dishes (Ladera), this tastes infinitely better warm or at room temperature than piping hot.", "If you have leftover filling, you can scatter it around the base of the tomatoes in the baking dish; it will cook in the juices.", "For a richer flavor, be generous with the olive oil. It is a main ingredient in the sauce, not just a cooking fat."]', '"This style of stuffed vegetable dish, known as ''Gemista'' in Greece or ''Dolma'' in Turkey, is a staple of Mediterranean cuisine. The specific inclusion of currants, pine nuts, and aromatic spices like allspice leans towards the ''Politiki'' (Constantinople-style) cuisine, reflecting the historical exchange of flavors between Greek and Ottoman cultures."', 350.7);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('262412e2-e849-4b6e-ab83-42753698ce10', 'Baked Lobster with Tarragon Cream', 'Succulent lobster tails and claws roasted in the shell, bathed in a velvety, anise-scented reduction of heavy cream, white wine, and fresh tarragon. The richness of the sauce perfectly complements the natural sweetness of the shellfish.', 'dinner', 'French', 'Intermediate', '["lobster", "french", "seafood", "date night", "gluten-free", "romantic"]', '[{"group_name": "Lobster", "items": [{"name": "whole lobster", "quantity": 2, "unit": null, "preparation": "raw or live", "notes": "approx. 600-700g each", "substitutions": [], "ingredient_id": "d7f5d7b9-9749-4b3f-9dba-2c124f36ca78", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "melted", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "white pepper", "quantity": null, "unit": null, "preparation": null, "notes": "pinch", "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Tarragon Cream Sauce", "items": [{"name": "heavy cream", "quantity": 250, "unit": "ml", "preparation": null, "notes": "minimum 35% fat", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 60, "unit": "ml", "preparation": null, "notes": "Sauvignon Blanc or Chardonnay", "substitutions": [], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "approx 30g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh tarragon leaves", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "d424d445-0a4e-45d1-9453-7523eb7b176b", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 220\u00b0C (425\u00b0F). Ensure the rack is in the center position.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Place the lobsters on a stable cutting board. Using a sharp, heavy knife, split them in half lengthwise from head to tail. Remove the stomach sac (behind the eyes) and the intestinal tract (running down the tail). Crack the claws slightly with the back of the knife to help heat penetrate.", "structured": {"action": "SCORE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["If using live lobster, kill humanely just before splitting by driving the knife point quickly through the cross on the head."]}, {"step_number": 3, "phase": "prep", "text": "Place lobster halves shell-side down on a baking sheet. Brush the exposed meat with 30g melted butter and season lightly with salt and white pepper.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Bake the lobsters for 8-10 minutes, until the shell turns bright red and the meat is opaque but slightly underdone in the center. (Target internal temp approx 55\u00b0C/130\u00b0F at this stage).", "structured": {"action": "BAKE", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT10M", "doneness_cues": {"visual": "Shells bright red, meat opaque", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "While lobsters bake, prepare the sauce. In a saucepan over medium heat, melt 15g butter. Add minced shallots and saut\u00e9 for 2 minutes until translucent but not browned. Add garlic and cook for another 30 seconds.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Deglaze the pan with white wine. Simmer rapidly until the liquid reduces by half.", "structured": {"action": "REDUCE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Liquid volume halved", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Pour in the heavy cream. Reduce heat to low and simmer gently for 5-7 minutes until the sauce thickens slightly and coats the back of a spoon. Whisk in the Dijon mustard (if using), lemon juice, and chopped tarragon. Season with salt to taste.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Coats back of spoon (nappe consistency)", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove lobsters from the oven. Spoon the tarragon cream sauce generously over the tail meat and into the head cavity. Return to the oven for 2-3 minutes to warm through and meld flavors. Final internal temperature should reach 63\u00b0C (145\u00b0F).", "structured": {"action": "BAKE", "temperature": {"celsius": 63, "fahrenheit": 145}, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Serve immediately, garnished with extra fresh tarragon sprigs if desired.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT15M", "total_time": "PT50M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 350}', '{"flags": ["Pescatarian", "Gluten-Free", "Egg-Free", "Soy-Free", "Keto", "Low-Carb"], "not_suitable_for": ["Shellfish allergy", "Dairy allergy"]}', '{"per_serving": {"calories": 1392.99, "protein_g": 139.47, "carbohydrates_g": 26.56, "fat_g": 73.69, "saturated_fat_g": 41.77, "trans_fat_g": 1.55, "monounsaturated_fat_g": 18.46, "polyunsaturated_fat_g": 6.49, "fiber_g": 1.07, "sugar_g": 5.51, "sodium_mg": 1609.3, "cholesterol_mg": 644.63, "potassium_mg": 1514.34, "calcium_mg": 477.38, "iron_mg": 10.02, "magnesium_mg": 290.86, "phosphorus_mg": 1638.57, "zinc_mg": 37.28, "vitamin_a_mcg": 710.65, "vitamin_c_mg": 20.22, "vitamin_d_mcg": 2, "vitamin_e_mg": 1.69, "vitamin_k_mcg": 5.74, "vitamin_b6_mg": 1.11, "vitamin_b12_mcg": 22.99, "thiamin_mg": 0.11, "riboflavin_mg": 0.58, "niacin_mg": 27.7, "folate_mcg": 18.38, "water_g": 575.5, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Seafood degrades quickly; best consumed immediately. Reheat gently to avoid rubbery texture.", "duration": "P1D"}, "freezer": {"notes": "Cream sauce may split and lobster texture will suffer upon thawing.", "duration": null}, "reheating": "Gently warm in a saucepan over low heat or in a 150\u00b0C oven, covered, just until warm.", "does_not_keep": true}', '[{"name": "Chef''s knife", "required": true, "alternative": "Heavy kitchen shears"}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Saucepan", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Pastry brush", "required": true, "alternative": null}]', '[{"symptom": "Lobster meat is rubbery and tough", "likely_cause": "Overcooking", "prevention": "Remove from oven immediately once the meat turns opaque; carry-over cooking will finish it.", "fix": "Cannot be fixed, but chopping the meat small and mixing with extra sauce helps mask the texture."}, {"symptom": "Sauce is too thin", "likely_cause": "Cream was not reduced enough or heat was too low", "prevention": "Simmer gently until it coats a spoon before adding lemon juice.", "fix": "Simmer for a few more minutes; if still thin, whisk in a small amount of cornstarch slurry."}]', '["Always use fresh tarragon for this dish; dried tarragon has a dusty flavor that dulls the delicate sweetness of the lobster.", "Do not boil the sauce aggressively after adding the lemon juice, as the acidity combined with high heat can sometimes cause the cream to curdle or look grainy.", "If the lobsters are very large, you can remove the claw meat halfway through cooking and add it to the sauce to prevent the tails from drying out while the claws finish.", "A dry, acidic white wine like Muscadet or Sauvignon Blanc works best to cut through the richness of the heavy cream."]', '"This dish draws inspiration from the classic French Lobster Thermidor, created in 1894 at Marie''s in Paris. While Thermidor typically involves a complex b\u00e9chamel and egg yolk thickening agent, this variation highlights the purity of the Breton flavor profile: cream, butter, and anise-scented herbs."', 1392.99);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('264a14ea-239a-44bc-b554-963ccf4bf88e', 'Strawberry Mascarpone Sablés', 'Butter-rich, melt-in-the-mouth shortbread rounds serving as a pedestal for a velvety mascarpone chantilly studded with fresh, ripe strawberries. The contrast between the crisp, delicate biscuit and the ethereal cream captures the essence of refined summer dining.', 'dessert', 'French', 'Intermediate', '["shortbread", "strawberry", "dessert", "summer", "tea time", "french inspired"]', '[{"group_name": "Shortbread Dough", "items": [{"name": "unsalted butter", "quantity": 200, "unit": "g", "preparation": "slightly softened", "notes": "high fat content (82%+) preferred", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "icing sugar", "quantity": 90, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 260, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 40, "unit": "g", "preparation": null, "notes": "adds tenderness", "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla bean paste", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Strawberry Mascarpone Cream", "items": [{"name": "mascarpone cheese", "quantity": 150, "unit": "g", "preparation": "chilled", "notes": null, "substitutions": [], "ingredient_id": "fc428935-3bcd-4cef-8495-7ed35e7dae22", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy whipping cream", "quantity": 150, "unit": "ml", "preparation": "chilled", "notes": "35% fat or higher", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "icing sugar", "quantity": 40, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh strawberries", "quantity": 100, "unit": "g", "preparation": "finely diced", "notes": "dried thoroughly with paper towel", "substitutions": [], "ingredient_id": "b2199214-7c2d-4083-92ae-b0a8a044e25b", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1/2 lemon", "substitutions": [], "ingredient_id": "03fb65be-9b62-44e7-a121-694de64cdec0", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Assembly", "items": [{"name": "fresh strawberries", "quantity": 6, "unit": null, "preparation": "halved or quartered", "notes": "approx 100g total for garnish", "substitutions": [], "ingredient_id": "b2199214-7c2d-4083-92ae-b0a8a044e25b", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh mint leaves", "quantity": null, "unit": null, "preparation": "small leaves", "notes": "for garnish", "substitutions": [], "ingredient_id": "17abecc0-a2a0-4478-8486-57b46e4305c9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Sift the all-purpose flour, cornstarch, and salt together into a medium bowl to ensure even distribution and remove lumps.", "structured": {"action": "SIFT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a stand mixer fitted with the paddle attachment, beat the softened butter, 90g icing sugar, and vanilla bean paste on medium-low speed just until smooth and combined. Do not aerate or whip until fluffy, as this causes the cookies to spread.", "structured": {"action": "CREAM", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": ["Stop mixing as soon as the butter and sugar are homogenous to maintain a dense, melt-in-mouth texture."]}, {"step_number": 3, "phase": "prep", "text": "Add the dry ingredients to the butter mixture. Mix on low speed briefly until the dough starts to clump together. Finish bringing the dough together by hand to avoid overworking the gluten.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "shape", "text": "Roll the dough out between two sheets of parchment paper to a thickness of 6mm (1/4 inch). Slide the parchment onto a baking sheet and refrigerate for at least 30 minutes to firm up.", "structured": {"action": "ROLL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "shape", "text": "Preheat oven to 160\u00b0C/320\u00b0F. Remove dough from fridge, peel off top parchment, and cut into rounds using a 6cm cutter. Arrange rounds on a lined baking sheet with 2cm spacing. Chill the cut rounds again for 15 minutes before baking.", "structured": {"action": "CUT", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": null, "doneness_cues": null}, "tips": ["Re-chilling the cut rounds is the secret to sharp edges and minimal spreading."]}, {"step_number": 6, "phase": "cook", "text": "Bake for 12-15 minutes at 160\u00b0C/320\u00b0F until the edges are barely set and very pale golden. They should remain mostly pale. Allow to cool completely on the tray before moving, as they are very fragile when hot.", "structured": {"action": "BAKE", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT15M", "doneness_cues": {"visual": "Pale surface with barely golden edges", "tactile": "Dry to the touch but soft"}}, "tips": []}, {"step_number": 7, "phase": "prep", "text": "While shortbread cools, prepare the cream. Place cold mascarpone, cold heavy cream, 40g icing sugar, and lemon zest in a chilled bowl. Whip until stiff peaks form.", "structured": {"action": "WHIP", "temperature": null, "duration": null, "doneness_cues": {"visual": "Stiff peaks that hold their shape", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "prep", "text": "Gently fold the 100g of finely diced strawberries into the cream mixture with a spatula. Ensure the strawberry pieces were patted dry to prevent the cream from seizing or weeping.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "assemble", "text": "Transfer the strawberry cream to a piping bag with a star nozzle. Pipe a generous rosette or mound of cream onto each cooled shortbread round.", "structured": {"action": "PIPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Top each cream mound with a fresh strawberry half and a small mint leaf. Serve immediately.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT1H15M", "total_time": "PT2H", "overnight_required": false, "yields": "12 servings", "yield_count": 12, "serving_size_g": 95}', '{"flags": ["Vegetarian", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 352.88, "protein_g": 3.47, "carbohydrates_g": 35.64, "fat_g": 23.54, "saturated_fat_g": 14.45, "trans_fat_g": 0.16, "monounsaturated_fat_g": 5.06, "polyunsaturated_fat_g": 0.81, "fiber_g": 1.05, "sugar_g": 12.94, "sodium_mg": 76.11, "cholesterol_mg": 49.96, "potassium_mg": 64.02, "calcium_mg": 45.47, "iron_mg": 0.39, "magnesium_mg": 8.24, "phosphorus_mg": 38.8, "zinc_mg": 0.22, "vitamin_a_mcg": 233.16, "vitamin_c_mg": 8.69, "vitamin_d_mcg": 0.2, "vitamin_e_mg": 0.56, "vitamin_k_mcg": 1.95, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": 0.05, "thiamin_mg": 0.03, "riboflavin_mg": 0.05, "niacin_mg": 0.35, "folate_mcg": 10.46, "water_g": 26.55, "alcohol_g": 0.14, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store components separately. Assembled tarts soften within 4 hours.", "duration": "P2D"}, "freezer": {"notes": "Raw dough discs can be frozen. Do not freeze the strawberry cream.", "duration": "P1M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Stand mixer or electric hand mixer", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Round cookie cutter (6cm)", "required": true, "alternative": null}, {"name": "Rolling pin", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}, {"name": "Piping bag with star nozzle", "required": true, "alternative": "Zip-top bag with corner cut"}]', '[{"symptom": "Shortbread spread and lost its shape", "likely_cause": "Dough was too warm when entering the oven or too much air was incorporated during creaming", "prevention": "Chill the cut rounds thoroughly before baking; mix butter and sugar only until combined, not fluffy", "fix": "Use a round cutter to trim the edges while the cookies are still hot and soft"}, {"symptom": "Cream filling is runny", "likely_cause": "Ingredients were too warm or strawberries added too much moisture", "prevention": "Ensure mascarpone and cream are fridge-cold; pat diced strawberries very dry", "fix": "Chill the mixture for 20 minutes to firm up; if still runny, serve as a ''dip'' rather than piped"}]', '["To achieve the ''sabl\u00e9'' (sandy) texture, use cornstarch in the dough; it inhibits gluten formation and creates a tender crumb.", "Do not over-bake. Shortbread should be pale. If it turns brown, the delicate butter flavor changes to a caramel flavor, which is delicious but not intended for this profile.", "Assemble these as close to serving time as possible. The moisture from the cream will eventually soften the crisp shortbread (though they are still delicious after 2 hours)."]', '"Shortbread originated in Scotland, evolving from medieval biscuit bread into a luxury treat rich in butter. This variation incorporates French p\u00e2tisserie techniques (the sabl\u00e9 dough and chantilly cream) to create a lighter, summer-focused dessert."', 352.88);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('26f75900-174b-4e2e-9e8b-7005abc2246a', 'Pâte Sucrée (French Sweet Tart Dough)', 'A classic French sweet shortcrust pastry characterized by its delicate, sandy texture and buttery richness. Enriched with almond flour for distinct crispness and flavor, this dough provides the structural foundation for fruit tarts, lemon tarts, and chocolate ganache.', 'base', 'French', 'Intermediate', '["french", "pastry", "base", "baking", "tart"]', '[{"group_name": "Dry Ingredients", "items": [{"name": "all-purpose flour", "quantity": 240, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "powdered sugar", "quantity": 90, "unit": "g", "preparation": null, "notes": "icing sugar yields a finer texture than granulated", "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "almond flour", "quantity": 30, "unit": "g", "preparation": null, "notes": "adds crispness and flavor", "substitutions": ["hazelnut flour", "equal weight all-purpose flour for nut-free"], "ingredient_id": "5bcbb4d4-6845-4825-bd21-1c13e52b989c", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wet Ingredients", "items": [{"name": "unsalted butter", "quantity": 120, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": "large", "notes": "approx 50g without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine flour, powdered sugar, almond flour, and salt in the bowl of a stand mixer fitted with the paddle attachment. Mix on low speed briefly to disperse ingredients.", "structured": {"action": "MIX", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Add the cold, cubed butter. Mix on low speed until the mixture resembles coarse, wet sand (sablage). There should be no large chunks of butter remaining, but the dough should not yet come together.", "structured": {"action": "MIX", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Sandy texture, pale yellow color", "tactile": " crumbly but holds shape when pressed"}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Add the egg. Mix on low speed just until the dough begins to clump together. Stop immediately before a cohesive ball forms to prevent gluten development.", "structured": {"action": "MIX", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Turn the crumbly dough out onto a clean work surface. Perform ''fraisage'' by using the heel of your hand to smear small portions of dough across the counter away from you. This ensures the butter is fully incorporated without overworking the gluten.", "structured": {"action": "KNEAD", "temperature": null, "duration": null, "doneness_cues": {"visual": "Homogenous dough without butter streaks", "tactile": null}}, "tips": ["Do not knead like bread; smear and gather only 2-3 times."]}, {"step_number": 5, "phase": "finish", "text": "Gather the dough into a cohesive ball and flatten it into a disc about 2cm thick. Wrap tightly in plastic wrap and refrigerate for at least 2 hours before rolling out.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT2H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT2H", "total_time": "PT2H25M", "overnight_required": false, "yields": "1 24cm (9.5 inch) tart shell", "yield_count": 8, "serving_size_g": 65}', '{"flags": ["Vegetarian"], "not_suitable_for": ["Gluten Intolerant", "Nut Allergies"]}', '{"per_serving": {"calories": 291.16, "protein_g": 4.8, "carbohydrates_g": 34.98, "fat_g": 14.93, "saturated_fat_g": 7.96, "trans_fat_g": null, "monounsaturated_fat_g": 4.95, "polyunsaturated_fat_g": 1.16, "fiber_g": 1.28, "sugar_g": 11.28, "sodium_mg": 108.39, "cholesterol_mg": 55.5, "potassium_mg": 72.06, "calcium_mg": 21.86, "iron_mg": 0.61, "magnesium_mg": 17.78, "phosphorus_mg": 66.41, "zinc_mg": 0.42, "vitamin_a_mcg": 112.6, "vitamin_c_mg": null, "vitamin_d_mcg": 0.13, "vitamin_e_mg": 1.39, "vitamin_k_mcg": 1.16, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": 0.08, "thiamin_mg": 0.05, "riboflavin_mg": 0.09, "niacin_mg": 0.52, "folate_mcg": 12.84, "water_g": 10.95, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Wrap tightly in plastic wrap to prevent absorbing odors.", "duration": "P3D"}, "freezer": {"notes": "Thaw overnight in the refrigerator before rolling out.", "duration": "P3M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Stand mixer with paddle attachment", "required": true, "alternative": "Large mixing bowl and pastry blender"}, {"name": "Digital scale", "required": true, "alternative": null}, {"name": "Rolling pin", "required": true, "alternative": null}, {"name": "Plastic wrap", "required": true, "alternative": null}, {"name": "Bench scraper", "required": false, "alternative": null}]', '[{"symptom": "Dough shrinks significantly during baking", "likely_cause": "Gluten was overworked during mixing or rolling, or the dough was not rested enough", "prevention": "Stop mixing as soon as ingredients combine; rest dough for full duration", "fix": "Cannot be fixed after baking; for next batch, ensure at least 2 hours rest time"}, {"symptom": "Dough is too sticky to roll", "likely_cause": "Butter has melted due to warm ambient temperature", "prevention": "Keep ingredients cold; work quickly", "fix": "Chill the dough for 15-20 minutes before attempting to roll again"}]', '["Always weigh ingredients carefully; pastry is chemistry.", "The ''fraisage'' step is the professional secret to a dough that is sturdy but melts in the mouth.", "If using for a tart that requires blind baking, freeze the lined tart shell for 20 minutes before baking to prevent slumping.", "Almond flour can be omitted for a nut-free version, but replace it with an equal weight of all-purpose flour."]', '"P\u00e2te Sucr\u00e9e is one of the three foundational French tart doughs, sitting between the neutral P\u00e2te Bris\u00e9e and the sandier P\u00e2te Sabl\u00e9e. Originating in French patisserie, the inclusion of sugar and egg creates a watertight seal that keeps the crust crisp even under moist fillings like pastry cream or fresh fruit."', 291.16);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('27a2eddc-3d65-41b1-8772-26e91005a744', 'Cervelle de Canut (Lyonnaise Herbed Cheese Spread)', 'A creamy, tangy, and deeply savory fresh cheese spread native to Lyon. Packed with sharp shallots, garlic, and a bouquet of fresh herbs, this ''silk worker\''s brain'' is a refreshing staple of the bouchon table, perfect for dipping crusty bread or crudités.', 'appetizer', 'French', 'Easy', '["french", "lyonnaise", "dips and spreads", "finger foods", "fromage blanc", "vegetarian", "gluten-free", "cold appetizer"]', '[{"group_name": "Dairy Base", "items": [{"name": "fromage blanc", "quantity": 400, "unit": "g", "preparation": "chilled", "notes": "or a mix of greek yogurt and ricotta if unavailable", "substitutions": [], "ingredient_id": "834a0c48-cc86-4458-b408-db4d1649ad26", "nutrition_source": "USDA FoodData Central"}, {"name": "cr\u00e8me fra\u00eeche", "quantity": 100, "unit": "g", "preparation": "chilled", "notes": "adds richness", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics", "items": [{"name": "shallots", "quantity": 2, "unit": null, "preparation": "finely minced", "notes": "approx 40g total", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "mashed to a paste", "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Herbs & Seasoning", "items": [{"name": "fresh chives", "quantity": 15, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": "flat-leaf preferred", "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh tarragon", "quantity": 5, "unit": "g", "preparation": "finely chopped", "notes": "essential for authentic flavor", "substitutions": [], "ingredient_id": "d424d445-0a4e-45d1-9453-7523eb7b176b", "nutrition_source": "Aggregated Public Data"}, {"name": "red wine vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "9e1b7e74-fdcb-4836-8349-4f7ad86d62df", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "036c7254-3de5-4c6e-a2e7-366ad4d05077", "nutrition_source": "Aggregated Public Data"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Finely mince the shallots and herbs. Mash the garlic into a paste using the side of a knife and a pinch of salt to prevent large raw chunks in the final dip.", "structured": {"action": "MINCE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a mixing bowl, combine the fromage blanc and cr\u00e8me fra\u00eeche. Whisk vigorously until the mixture is smooth, aerated, and uniform.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Smooth and slightly glossy", "tactile": "Creamy consistency without lumps"}}, "tips": []}, {"step_number": 3, "phase": "assemble", "text": "Add the minced shallots, garlic paste, chopped herbs (chives, parsley, tarragon), red wine vinegar, and olive oil to the cheese mixture.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Fold ingredients together gently but thoroughly. Season with salt and freshly cracked black pepper. Taste and adjust acidity or salt if necessary.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Cover the bowl and refrigerate for at least 2 hours to allow the flavors to meld and the shallots to soften in the acidity.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Serve chilled with toasted baguette slices or boiled potatoes.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT2H", "total_time": "PT2H15M", "overnight_required": false, "yields": "500g", "yield_count": 6, "serving_size_g": 85}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Egg-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 154.18, "protein_g": 8.17, "carbohydrates_g": 5.69, "fat_g": 11.19, "saturated_fat_g": 5.74, "trans_fat_g": 0.21, "monounsaturated_fat_g": 2.22, "polyunsaturated_fat_g": 0.35, "fiber_g": 0.59, "sugar_g": 2.62, "sodium_mg": 430.53, "cholesterol_mg": 27.5, "potassium_mg": 146.51, "calcium_mg": 65.41, "iron_mg": 0.66, "magnesium_mg": 12.61, "phosphorus_mg": 93.15, "zinc_mg": 0.33, "vitamin_a_mcg": 119, "vitamin_c_mg": 5.93, "vitamin_d_mcg": 0.27, "vitamin_e_mg": 0.2, "vitamin_k_mcg": 28.48, "vitamin_b6_mg": 0.09, "vitamin_b12_mcg": 0.38, "thiamin_mg": 0.03, "riboflavin_mg": 0.13, "niacin_mg": 0.15, "folate_mcg": 12.85, "water_g": 72.34, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Keep tightly covered. Some liquid may separate; stir before serving.", "duration": "P3D"}, "freezer": {"notes": "Do not freeze; the dairy emulsion will break and texture will become grainy.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": "Fork or spatula"}]', '[{"symptom": "Texture is too runny", "likely_cause": "Fromage blanc had high water content or was over-stirred", "prevention": "Drain excess liquid from the cheese before mixing", "fix": "Whisk in a spoonful of thick cr\u00e8me fra\u00eeche or strain through cheesecloth for 30 minutes"}, {"symptom": "Onion/Shallot flavor is overpowering", "likely_cause": "Shallots were too old or pungent", "prevention": "Soak minced shallots in the vinegar for 10 minutes before adding to the cheese", "fix": "Add more dairy to dilute the flavor"}]', '["If you cannot find fromage blanc, beat 250g cottage cheese until smooth in a blender and mix with 150g greek yogurt.", "Don''t skip the resting time; eating it immediately results in a disjointed flavor profile where the garlic bites too hard.", "For a true Lyonnaise experience, serve this as a ''cheese course'' after the main meal, not just as an appetizer.", "Walnut oil can be substituted for olive oil for a nuttier, earthier profile often found in Lyon."]', '"Cervelle de Canut translates to ''Silk Worker''s Brain.'' Originating in 19th-century Lyon, the silk capital of Europe, this dish was a poor worker''s substitute for lamb''s brains, which were a delicacy of the bourgeoisie. It remains a staple of ''Bouchons'' (traditional Lyonnaise bistros)."', 154.18);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('28056318-f2e3-46f1-9930-90d774cb26da', 'Cacio e Pepe', 'The quintessential Roman pasta dish featuring a creamy, emulsified sauce made strictly from Pecorino Romano cheese, starchy pasta water, and toasted black pepper. The result is a sharp, salty, and spicy masterpiece that relies on technique rather than heavy cream.', 'dinner', 'Italian', 'Intermediate', '["italian", "pastas", "black pepper", "five ingredient", "linguine", "parmesan", "pecorino", "spaghetti", "step by step", "dinner", "easy", "quick", "weeknight", "vegetarian", "roman"]', '[{"group_name": "Pasta & Base", "items": [{"name": "spaghetti", "quantity": 200, "unit": "g", "preparation": "dried", "notes": "Tonnarelli or Linguine are also acceptable", "substitutions": ["Linguine", "Bucatini", "Tonnarelli"], "ingredient_id": "931f2cf7-c04e-4814-a866-1c20f809d475", "nutrition_source": "Aggregated Public Data"}, {"name": "whole black peppercorns", "quantity": 4, "unit": "g", "preparation": "whole", "notes": "approx 2 tsp", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "Use less than normal; cheese is very salty", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Cheese Blend", "items": [{"name": "pecorino romano", "quantity": 60, "unit": "g", "preparation": "finely grated", "notes": "Must be very fine powder, not shreds", "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "parmigiano reggiano", "quantity": 40, "unit": "g", "preparation": "finely grated", "notes": "Optional; classic is 100% Pecorino, but a blend is smoother", "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Finely grate the cheeses using a microplane. The cheese must be light and airy like snow to melt properly without clumping.", "structured": {"action": "GRATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Do not buy pre-grated cheese; it often contains anti-caking agents that ruin the sauce."]}, {"step_number": 2, "phase": "prep", "text": "Crush the whole peppercorns coarsely using a mortar and pestle or the back of a heavy skillet.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Toast the crushed pepper in a large dry skillet over medium heat until fragrant, about 1-2 minutes. Add a small ladle (approx 50ml) of plain water to the pan to stop the cooking, then turn off heat.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Light smoke", "tactile": "Aromatic"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Bring a pot of water to a boil. Use less water than usual (approx 2 liters for 200g pasta) to maximize starch concentration. Salt lightly.", "structured": {"action": "BOIL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Starch is the binding agent; too much water dilutes it."]}, {"step_number": 5, "phase": "prep", "text": "While water boils, place the grated cheese in a small bowl. Gradually whisk in a ladle of hot (not boiling) starchy pasta water to create a thick, lump-free paste (the ''pastello'').", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Smooth paste like thick frosting", "tactile": "No lumps"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Cook the pasta until it is very al dente, about 2 minutes less than package instructions. Transfer pasta directly to the skillet with the pepper using tongs, carrying over some pasta water.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Turn the skillet heat to medium. Toss the pasta with the pepper water for 1 minute to finish cooking and coat the strands. Add more starchy water if the pan looks dry.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "CRITICAL STEP: Remove skillet from heat completely and wait 30 seconds. Pour in the cheese paste and vigorously stir/toss the pasta to emulsify the sauce into a cream. Add tiny splashes of pasta water if too thick.", "structured": {"action": "EMULSIFY", "temperature": {"celsius": 60, "fahrenheit": 140}, "duration": null, "doneness_cues": {"visual": "Glossy, creamy coating", "tactile": "Thickened sauce"}}, "tips": ["If the pan is too hot, the cheese proteins will seize and clump."]}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 260}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": ["Vegans (dairy)", "Gluten intolerance (wheat pasta)"]}', '{"per_serving": {"calories": 572.02, "protein_g": 31.01, "carbohydrates_g": 74.19, "fat_g": 14.12, "saturated_fat_g": 7.43, "trans_fat_g": null, "monounsaturated_fat_g": 3.78, "polyunsaturated_fat_g": 0.31, "fiber_g": 3.31, "sugar_g": 2.62, "sodium_mg": 1566.9, "cholesterol_mg": 34, "potassium_mg": 275.3, "calcium_mg": 618.51, "iron_mg": 2.72, "magnesium_mg": 25.45, "phosphorus_mg": 522.16, "zinc_mg": 1.41, "vitamin_a_mcg": 104.04, "vitamin_c_mg": null, "vitamin_d_mcg": 0.25, "vitamin_e_mg": 0.13, "vitamin_k_mcg": 4.13, "vitamin_b6_mg": 0.05, "vitamin_b12_mcg": 0.6, "thiamin_mg": 0.02, "riboflavin_mg": 0.17, "niacin_mg": 0.16, "folate_mcg": 3.84, "water_g": 15.26, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Sauce may separate upon reheating. Add a splash of water and heat very gently.", "duration": "P2D"}, "freezer": {"notes": null, "duration": null}, "reheating": "Reheat in a skillet over low heat with a splash of water, stirring constantly to re-emulsify.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Microplane or fine grater", "required": true, "alternative": "Food processor (powder consistency)"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Mortar and pestle", "required": false, "alternative": "Pepper grinder (set to coarse)"}, {"name": "Small mixing bowl", "required": true, "alternative": null}]', '[{"symptom": "Cheese clumped into a ball/stringy mess", "likely_cause": "Temperature shock: The pan was too hot when cheese was added", "prevention": "Remove pan from heat and wait before adding cheese; use the ''pastello'' (paste) method", "fix": "Add a splash of cold water and blend vigorously, though texture may remain grainy"}, {"symptom": "Sauce is too watery", "likely_cause": "Too much water added or not enough cheese/starch", "prevention": "Add pasta water very gradually", "fix": "Keep tossing off-heat; the sauce thickens as it cools. Do not return to high heat."}]', '["The secret to a creamy Cacio e Pepe is starch. Using a smaller pot of water concentrates the starch released by the pasta, which acts as the emulsifier.", "Removing the pan from the heat is non-negotiable. Pecorino coagulates at roughly 60-70\u00b0C (140-160\u00b0F). If the pan is boiling, the cheese will separate into protein and oil.", "Use aged Pecorino Romano (DOP if possible). Younger cheeses may melt too easily and become oily, while very old cheeses might be too dry.", "The ''pastello'' method (making a cheese paste first) is much more foolproof for home cooks than sprinkling dry cheese onto the pasta."]', '"Cacio e Pepe is one of the four holy pastas of Rome (alongside Carbonara, Amatriciana, and Gricia). Originating from shepherds who carried dried pasta, aged cheese, and black pepper during long migrations, it transforms non-perishable staples into a comforting, high-energy meal."', 572.02);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('2857721c-7d4a-49b8-a916-faa28e2039b9', 'Buttery Heritage Corn Muffins', 'A nostalgic homage to the early West Village bakery days, these muffins feature a rich, golden crumb studded with sweet corn kernels. They strike the perfect balance between savory and sweet, with a distinct buttery richness that pairs equally well with breakfast jam or a bowl of chili.', 'baked good', 'American', 'Easy', '["muffin", "breakfast", "brunch", "side", "corn", "baking"]', '[{"group_name": "Dry Ingredients", "items": [{"name": "all-purpose flour", "quantity": 190, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow cornmeal", "quantity": 120, "unit": "g", "preparation": "medium grind", "notes": "provides texture and color", "substitutions": [], "ingredient_id": "7fb6be00-5ba2-483a-af74-961f21de4055", "nutrition_source": "Aggregated Public Data"}, {"name": "granulated sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 12, "unit": "g", "preparation": null, "notes": "approx 1 tablespoon", "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 1/2 teaspoon", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wet Ingredients & Add-ins", "items": [{"name": "unsalted butter", "quantity": 170, "unit": "g", "preparation": "melted and slightly cooled", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 240, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "large, room temperature", "notes": "approx 100g total without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "corn kernels", "quantity": 150, "unit": "g", "preparation": "fresh, frozen (thawed), or canned (drained)", "notes": "adds texture and moisture", "substitutions": [], "ingredient_id": "46ca2aab-cb23-4397-9711-528c234b2cf8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 200\u00b0C (400\u00b0F). Generously grease the muffin tin cups with butter or insert paper liners.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, whisk together the flour, cornmeal, sugar, baking powder, and salt until uniformly combined.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a medium bowl, whisk the eggs and milk together. Slowly stream in the melted butter while whisking constantly to emulsify slightly.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": ["Ensure the butter is not hot, or it will cook the eggs."]}, {"step_number": 4, "phase": "assemble", "text": "Pour the wet ingredients into the dry ingredients. Using a silicone spatula, mix until just barely combined and streaks of flour remain.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Add the corn kernels and fold them gently into the batter. Stop mixing the moment no dry flour is visible.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Overmixing develops gluten, resulting in tough muffins. Lumps in the batter are fine."]}, {"step_number": 6, "phase": "cook", "text": "Divide the batter evenly among the 12 muffin cups. Bake in the center of the oven for 20-25 minutes, or until the tops are golden and a toothpick inserted into the center comes out clean.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT25M", "doneness_cues": {"visual": "Golden domed tops", "tactile": "Toothpick comes out clean"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from the oven and let the muffins cool in the pan for 10 minutes before transferring them to a wire rack to cool completely.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT30M", "total_time": "PT45M", "overnight_required": false, "yields": "12 muffins", "yield_count": 12, "serving_size_g": 95}', '{"flags": ["Vegetarian"], "not_suitable_for": ["Vegans (contains dairy, eggs)", "Celiacs (contains gluten)"]}', '{"per_serving": {"calories": 290.13, "protein_g": 4.79, "carbohydrates_g": 38.32, "fat_g": 13.61, "saturated_fat_g": 7.9, "trans_fat_g": null, "monounsaturated_fat_g": 3.85, "polyunsaturated_fat_g": 0.75, "fiber_g": 1.43, "sugar_g": 14.51, "sodium_mg": 233.11, "cholesterol_mg": 63.46, "potassium_mg": 121.11, "calcium_mg": 93.41, "iron_mg": 1.2, "magnesium_mg": 37.06, "phosphorus_mg": 135.03, "zinc_mg": 0.73, "vitamin_a_mcg": 122.76, "vitamin_c_mg": 0.85, "vitamin_d_mcg": 0.43, "vitamin_e_mg": 0.45, "vitamin_k_mcg": 1.16, "vitamin_b6_mg": 0.04, "vitamin_b12_mcg": 0.19, "thiamin_mg": 0.05, "riboflavin_mg": 0.09, "niacin_mg": 0.45, "folate_mcg": 14.71, "water_g": 37.7, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container to prevent drying out.", "duration": "P3D"}, "freezer": {"notes": "Wrap individually in plastic wrap, then place in a zip-top bag.", "duration": "P2M"}, "reheating": "Microwave for 15 seconds or warm in a 150\u00b0C oven for 5 minutes.", "does_not_keep": false}', '[{"name": "Standard 12-cup muffin tin", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Medium mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Silicone spatula", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}]', '[{"symptom": "Muffins are tough and dense", "likely_cause": "The batter was overmixed after adding the wet ingredients", "prevention": "Use a spatula instead of a whisk for the final mix; stop as soon as the flour disappears", "fix": "Cannot be fixed once baked; serve warm with extra butter to mask density"}, {"symptom": "Muffins have soggy bottoms", "likely_cause": "Left in the hot tin too long after baking", "prevention": "Remove from tin after exactly 10 minutes", "fix": "Place on a wire rack in a warm oven for 3-5 minutes to dry out the base"}]', '["For a true bakery-style ''muffin top'', fill the cups nearly to the brim. If you do this, place a baking sheet on the rack below to catch any potential drips.", "If using frozen corn, ensure it is completely thawed and patted dry to avoid adding excess water to the batter.", "These muffins are best served warm. If serving the next day, a quick toast revives the buttery edges.", "Yellow cornmeal is preferred over white for that classic golden hue and slightly nuttier flavor."]', '"Inspired by the early repertoire of NYC''s Magnolia Bakery in the 1990s, these muffins represent a shift in American baking where ''morning pastries'' moved away from purely sugary confections toward richer, savory-sweet comforts. The inclusion of whole kernels and a high butter content mimics the Southern-style spoonbread tradition adapted for an urban grab-and-go format."', 290.13);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('28d615f4-11cf-4f69-a5eb-2a4b329c5b04', 'Café Rhum Chantilly', 'Velvety, airy clouds of sweetened cream spiked with the dark warmth of aged rum and the roasted bitterness of espresso. This sophisticated topping transforms simple chocolate desserts, irish coffees, or morning waffles into a refined indulgence.', 'condiment', 'French', 'Easy', '["condiments", "heavy cream", "instant espresso", "rum", "dessert", "french", "topping", "quick"]', '[{"group_name": "Base", "items": [{"name": "heavy cream", "quantity": 240, "unit": "ml", "preparation": "very cold", "notes": "min 35% fat content", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "powdered sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": "icing sugar; sifted if lumpy", "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Flavor Infusion", "items": [{"name": "dark rum", "quantity": 15, "unit": "ml", "preparation": null, "notes": "aged or spiced rum works best", "substitutions": [], "ingredient_id": "1a607a45-2f40-47c4-a400-12536a1c3826", "nutrition_source": "Aggregated Public Data"}, {"name": "instant espresso powder", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "3df58f53-0c05-4d37-b2b2-e2239ef09add", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 2, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a small ramekin, combine the dark rum and instant espresso powder. Stir vigorously until the powder is completely dissolved into a dark syrup. This prevents grainy textures in the final cream.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Smooth, dark liquid with no visible granules", "tactile": null}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Pour the cold heavy cream into a large mixing bowl (preferably chilled). Add the powdered sugar, the espresso-rum syrup, and the vanilla extract (if using).", "structured": {"action": "MIX", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Whisk the mixture continuously. Start slowly to avoid splashing, then increase speed as the cream thickens. Look for the tracks of the whisk holding their shape.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Mixture thickens and volume increases", "tactile": null}}, "tips": ["If using an electric mixer, be careful not to over-mix, or you will make coffee butter."]}, {"step_number": 4, "phase": "finish", "text": "Stop whisking when the cream reaches medium-stiff peaks. The cream should stand up on the end of the whisk but the very tip should curl over slightly.", "structured": {"action": "WHIP", "temperature": null, "duration": null, "doneness_cues": {"visual": "Medium-stiff peaks", "tactile": "Firm but airy resistance"}}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT0M", "total_time": "PT10M", "overnight_required": false, "yields": "450ml volume", "yield_count": 12, "serving_size_g": 35}', '{"flags": ["Vegetarian", "Gluten-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Low-Sodium"], "not_suitable_for": ["Infants", "Individuals avoiding alcohol"]}', '{"per_serving": {"calories": 81.67, "protein_g": 0.59, "carbohydrates_g": 3.21, "fat_g": 7.22, "saturated_fat_g": 4.6, "trans_fat_g": 0.25, "monounsaturated_fat_g": 1.82, "polyunsaturated_fat_g": 0.31, "fiber_g": 0, "sugar_g": 3.05, "sodium_mg": 5.5, "cholesterol_mg": 22.6, "potassium_mg": 25.13, "calcium_mg": 13.48, "iron_mg": 0.03, "magnesium_mg": 1.94, "phosphorus_mg": 12.09, "zinc_mg": 0.05, "vitamin_a_mcg": 82.2, "vitamin_c_mg": 0.12, "vitamin_d_mcg": 0.32, "vitamin_e_mg": 0.18, "vitamin_k_mcg": 0.64, "vitamin_b6_mg": 0.01, "vitamin_b12_mcg": 0.03, "thiamin_mg": null, "riboflavin_mg": 0.04, "niacin_mg": 0.06, "folate_mcg": 0.8, "water_g": 11.64, "alcohol_g": 0.06, "caffeine_mg": 0.2}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best used immediately. If stored, may need a few whisk strokes to re-emulsify before serving.", "duration": "P2D"}, "freezer": {"notes": "Freezing alters texture significantly; not recommended.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Large mixing bowl", "required": true, "alternative": "Stand mixer bowl"}, {"name": "Balloon whisk", "required": true, "alternative": "Electric hand mixer"}, {"name": "Small ramekin", "required": true, "alternative": null}]', '[{"symptom": "Cream looks grainy or curdled", "likely_cause": "Over-whipping has caused the fat to separate (beginning of butter)", "prevention": "Stop whisking immediately once tracks appear and check consistency frequently", "fix": "Gently fold in 1-2 tablespoons of fresh cold liquid cream with a spatula to smooth it out"}]', '["Chill your bowl and whisk in the freezer for 10 minutes before starting; cold equipment helps the fat trap air faster and more stably.", "Dissolving the espresso in the alcohol is crucial. Adding dry powder directly to cold cream often results in speckled, bitter grit rather than a smooth infusion.", "For a non-alcoholic version, dissolve the espresso in 1 tsp of warm water and let it cool completely before adding to the cream.", "Use powdered sugar (icing sugar) rather than granulated sugar, as it contains a small amount of cornstarch which helps stabilize the whipped cream so it holds its shape longer."]', '"While sweetened whipped cream (Cr\u00e8me Chantilly) dates back to 17th-century France, possibly originating at the Ch\u00e2teau de Chantilly, the addition of spirits and coffee aligns it with the digestif tradition. This variation bridges the gap between a dessert topping and a standalone ''caf\u00e9 gourmand'' element."', 81.67);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('29a085ce-ba4c-4815-b502-45de18fe685e', 'Grilled Confit-Style Duck Legs with Frisée & Warm Liver Vinaigrette', 'Tender, slow-roasted duck legs finished over an open flame for smokiness and crisp skin. Accompanied by crisp, bitter frisée tossed in a luxurious, creamy vinaigrette made from seared duck livers and sherry vinegar.', 'main course', 'French', 'Intermediate', '["duck leg", "dinner", "main course", "french", "date night", "gluten-free"]', '[{"group_name": "Duck Legs", "items": [{"name": "duck legs", "quantity": 4, "unit": null, "preparation": "whole, bone-in, skin-on", "notes": "approx 250g each", "substitutions": [], "ingredient_id": "5525ed3e-a663-4b6c-beee-5c2a1c7b0558", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme sprigs", "quantity": 4, "unit": null, "preparation": null, "notes": "approx 2g", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "smashed", "notes": "approx 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Liver Vinaigrette", "items": [{"name": "fresh duck livers", "quantity": 100, "unit": "g", "preparation": "cleaned and trimmed", "notes": "can substitute chicken livers", "substitutions": [], "ingredient_id": "13478315-8da6-4268-be1a-d8928a6500e3", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 25g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "sherry vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "dcfa7371-7051-4604-a76e-4a46ae1f9e7b", "nutrition_source": "Aggregated Public Data"}, {"name": "dijon mustard", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "3e25e626-c9b4-4b62-9d08-7c650bcb3d2b", "nutrition_source": "Aggregated Public Data"}, {"name": "walnut oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["hazelnut oil", "neutral vegetable oil"], "ingredient_id": "82c98f0f-cf76-4f18-97ce-2a512217a798", "nutrition_source": "USDA FoodData Central"}, {"name": "duck fat", "quantity": 15, "unit": "ml", "preparation": null, "notes": "rendered from roasting pan", "substitutions": [], "ingredient_id": "8f0a81cf-ee6f-4b61-aabf-81c16f3c54c2", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Salad", "items": [{"name": "fris\u00e9e lettuce", "quantity": 2, "unit": null, "preparation": "washed and torn", "notes": "heads, approx 300g total", "substitutions": [], "ingredient_id": "746c5c66-b77f-4788-8535-19e20f8c04ba", "nutrition_source": "Aggregated Public Data"}, {"name": "chives", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Using a sharp knife, score the skin of the duck legs in a diamond pattern without cutting into the meat. Season generously with sea salt on all sides.", "structured": {"action": "SCORE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Place duck legs skin-side up on a rack in a roasting pan. Tuck thyme and smashed garlic underneath. Roast at 150\u00b0C/300\u00b0F for 2 to 2.5 hours, until the meat is very tender and pulls away from the bone. Reserve the rendered fat.", "structured": {"action": "ROAST", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": "PT2H30M", "doneness_cues": {"visual": "Skin golden, meat pulling from bone", "tactile": "Fork tender"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "While duck rests, heat 1 tbsp of reserved duck fat in a saut\u00e9 pan over medium-high heat. Season duck livers and sear quickly until browned but still pink in the center, about 2 minutes. Add shallots and cook for 1 minute more.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Transfer the warm livers and shallots to a blender. Add sherry vinegar, Dijon mustard, and walnut oil. Puree until smooth and creamy. Season with salt and pepper to taste. If too thick, thin with a teaspoon of warm water.", "structured": {"action": "PUREE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Preheat grill to high heat. Place the roasted duck legs skin-side down on the grill. Grill for 3-5 minutes to crisp the skin and add char. Watch carefully for flare-ups caused by dripping fat.", "structured": {"action": "GRILL", "temperature": {"celsius": 230, "fahrenheit": 446}, "duration": "PT5M", "doneness_cues": null}, "tips": ["Keep a cool zone on the grill to move the duck if flare-ups become uncontrollable."]}, {"step_number": 6, "phase": "assemble", "text": "In a large bowl, toss the fris\u00e9e with the warm liver dressing until evenly coated. Divide the salad among plates and top each with a grilled duck leg. Garnish with chopped chives.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT2H30M", "total_time": "PT3H15M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Gluten-Free", "Low-Carb", "Keto", "Paleo", "Dairy-Free"], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 717.98, "protein_g": 71.3, "carbohydrates_g": 8.14, "fat_g": 45.98, "saturated_fat_g": 1.39, "trans_fat_g": null, "monounsaturated_fat_g": 2.74, "polyunsaturated_fat_g": 7.29, "fiber_g": 2.9, "sugar_g": 1.32, "sodium_mg": 1347.93, "cholesterol_mg": 128.75, "potassium_mg": 300.55, "calcium_mg": 71.67, "iron_mg": 14.6, "magnesium_mg": 9.94, "phosphorus_mg": 77.57, "zinc_mg": 0.86, "vitamin_a_mcg": 3114.29, "vitamin_c_mg": 14.81, "vitamin_d_mcg": null, "vitamin_e_mg": 0.05, "vitamin_k_mcg": 1.79, "vitamin_b6_mg": 0.25, "vitamin_b12_mcg": 13.5, "thiamin_mg": 0.15, "riboflavin_mg": 0.23, "niacin_mg": 1.67, "folate_mcg": 186.94, "water_g": 25.03, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store duck and dressing separately. Dress salad immediately before serving.", "duration": "P3D"}, "freezer": {"notes": "Cooked duck freezes well; salad and dressing emulsion do not.", "duration": null}, "reheating": "Reheat duck in a 180\u00b0C oven until skin is crisp again. Serve dressing warm or room temperature.", "does_not_keep": false}', '[{"name": "Heavy roasting pan with rack", "required": true, "alternative": null}, {"name": "Outdoor grill (Gas or Charcoal)", "required": true, "alternative": "Cast iron skillet and broiler"}, {"name": "Blender or food processor", "required": true, "alternative": null}, {"name": "Small saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Duck skin is flabby, not crisp", "likely_cause": "Roasting temperature was too low or humidity was too high in oven", "prevention": "Ensure rack is used so air circulates; finish on high heat grill", "fix": "Grill skin-side down longer over direct heat, watching constantly"}, {"symptom": "Dressing is separated/oily", "likely_cause": "Oil added too quickly or mixture not warm enough to emulsify", "prevention": "Blend on high speed", "fix": "Add a teaspoon of warm water and blend again on high"}]', '["Pricking or scoring the skin is crucial; it allows the fat to render out, self-basting the meat while crisping the skin.", "The liver dressing adds a savory ''umami'' depth that mimics a warm p\u00e2t\u00e9; do not overcook the livers or the texture will become grainy.", "If you cannot find walnut oil, hazelnut oil is a great alternative, or use a high-quality extra virgin olive oil.", "This ''slow-roast then grill'' method mimics the texture of confit without requiring liters of extra duck fat.", "For safety, duck livers should be seared but can remain pink inside; however, immunocompromised individuals should cook them through."]', '"This dish draws inspiration from the classic French bistro salad ''Fris\u00e9e aux Lardons'' and the tradition of ''Salade P\u00e9rigourdine.'' It highlights the regional affinity for waterfowl and rich organ meats, balancing fatty richness with the sharp bitterness of chicory greens."', 717.98);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('29cdd9c1-fc32-4930-8be3-173110ac3ef5', 'Lime and Chive Salmon Carpaccio', 'Silky, translucent slices of fresh sashimi-grade salmon dressed in a vibrant citrus emulsion. The bright acidity of lime cuts through the rich, fatty texture of the fish, while delicate chives provide a mild allium finish. A refined, elegant appetizer that relies entirely on the quality of its five core ingredients.', 'appetizer', 'Fusion', 'Intermediate', '["chive", "five ingredient", "lime", "salmon fillet", "appetizer", "raw", "carpaccio", "fusion"]', '[{"group_name": "Salmon", "items": [{"name": "salmon fillet (sashimi-grade)", "quantity": 300, "unit": "g", "preparation": "skinless, center-cut", "notes": "Must be labeled sushi/sashimi grade for safety", "substitutions": [], "ingredient_id": "6648fae7-4f63-45b3-b45d-19d927b57c2d", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Vinaigrette & Garnish", "items": [{"name": "fresh chives", "quantity": 15, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}, {"name": "limes", "quantity": 2, "unit": null, "preparation": null, "notes": "yields approx 10g zest and 60ml juice", "substitutions": [], "ingredient_id": "d3d2677e-fe02-4404-add0-29d73df7e921", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": "use high quality finishing oil", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "flaky sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 3g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "white pepper", "quantity": null, "unit": null, "preparation": "ground", "notes": "optional pinch", "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the salmon fillet in the freezer for 15 to 20 minutes. This firms up the fat and flesh, making it significantly easier to slice thinly and evenly without tearing.", "structured": {"action": "FREEZE", "temperature": {"celsius": -18, "fahrenheit": 0}, "duration": "PT20M", "doneness_cues": null}, "tips": ["Do not freeze until rock solid; just firm to the touch."]}, {"step_number": 2, "phase": "prep", "text": "While the salmon chills, wash the limes. Zest both limes into a small mixing bowl using a microplane. Slice the limes and squeeze out the juice (approx 60ml) into the same bowl.", "structured": {"action": "ZEST", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Add the olive oil and half of the chopped chives to the lime mixture. Whisk vigorously until the vinaigrette emulsifies slightly. Season with a pinch of white pepper if using.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Remove salmon from freezer. Using a very sharp knife held at a 45-degree angle, slice the salmon against the grain into thin sheets (approx 3-5mm thick). Use long drawing motions with the knife rather than sawing.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Translucent, consistent thickness", "tactile": "Firm but yielding"}}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Arrange the salmon slices in a single layer on a chilled serving platter. Slight overlapping is acceptable.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Spoon the vinaigrette evenly over the salmon. Cover lightly with plastic wrap and refrigerate for 10 minutes. This chills the dish and allows the lime acid to slightly cure the surface of the fish.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from the refrigerator. Sprinkle with flaky sea salt and the remaining chopped chives. Serve immediately while cold.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT30M", "total_time": "PT50M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 90}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Low-Carb", "Keto", "Paleo", "Whole30", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 311.7, "protein_g": 18.88, "carbohydrates_g": 7.56, "fat_g": 30.57, "saturated_fat_g": 1.56, "trans_fat_g": null, "monounsaturated_fat_g": 8.22, "polyunsaturated_fat_g": 1.21, "fiber_g": 1.32, "sugar_g": 0.72, "sodium_mg": 1717.2, "cholesterol_mg": null, "potassium_mg": 54.72, "calcium_mg": 224.35, "iron_mg": 9.31, "magnesium_mg": 229.25, "phosphorus_mg": 235.05, "zinc_mg": 0.75, "vitamin_a_mcg": 228.63, "vitamin_c_mg": 14.58, "vitamin_d_mcg": null, "vitamin_e_mg": 1.71, "vitamin_k_mcg": 7.03, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.01, "niacin_mg": 0.09, "folate_mcg": 3.41, "water_g": 37.55, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best consumed immediately. Extended storage will cure the fish fully (ceviche style) and alter texture.", "duration": "PT4H"}, "freezer": {"notes": "Do not refreeze thawed raw fish intended for raw consumption.", "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Sharp Chef''s Knife or Sashimi Knife", "required": true, "alternative": "Very sharp slicing knife"}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Microplane or fine grater", "required": true, "alternative": null}, {"name": "Serving platter", "required": true, "alternative": null}]', '[{"symptom": "Salmon slices are tearing or ragged", "likely_cause": "Knife is dull or salmon is too warm", "prevention": "Sharpen knife before starting and ensure salmon is semi-frozen", "fix": "Cut slightly thicker slices or dice the salmon into a tartare instead"}, {"symptom": "Fish texture is chalky or mushy", "likely_cause": "Marinated too long in lime juice (acid cooked)", "prevention": "Do not let sit in dressing for more than 15-20 minutes before serving", "fix": "Cannot be fixed; serve immediately"}]', '["Safety is paramount: Ensure you buy fish specifically labeled for raw consumption (sashimi/sushi grade), which usually means it has been deep-frozen to kill parasites.", "For the cleanest cut, wipe your knife blade with a damp cloth between every few slices to remove sticky fish proteins.", "If the vinaigrette tastes too acidic, you can balance it with a tiny pinch of sugar or a drop of honey, though the fat of the salmon usually counteracts the lime sufficiently.", "Serve with thin crackers or toasted baguette points if you want to add a crunchy textural contrast."]', '"This dish draws from the Italian tradition of ''Carpaccio'' (originally raw beef, invented at Harry''s Bar in Venice in 1950) and Japanese ''Usuyukuri'' (thinly sliced sashimi). It represents a modern fusion style popular in coastal cuisine, highlighting the purity of fresh seafood through minimal intervention."', 311.7);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('29d83991-c2d6-4ae4-b7ea-7c5a9451595b', 'Salabat-Inspired Honey Ginger Loaf', 'A tender, aromatic loaf cake channeling the soothing warmth of Salabat (traditional Filipino ginger tea). The crumb is enriched with sour cream and brightened with lemon zest, while a double dose of fresh and ground ginger provides a gentle, spicy heat balanced by floral honey.', 'baked good', 'Filipino', 'Intermediate', '["filipino", "fresh ginger", "ground ginger", "honey", "lemon juice", "lemon zest", "loaf cake", "sour cream", "breakfast", "brunch", "dessert", "tea cake", "merienda"]', '[{"group_name": "Dry Ingredients", "items": [{"name": "all-purpose flour", "quantity": 240, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "ground ginger", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 2g (1 tsp), increase for more heat", "substitutions": [], "ingredient_id": "401ddd0b-3597-4b46-bb54-f3bc755048bb", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wet Ingredients", "items": [{"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 85, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "large, room temperature", "notes": "approx 100g total without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "sour cream", "quantity": 120, "unit": "g", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "d171100e-1088-4266-8d50-06cdedda7193", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 15, "unit": "g", "preparation": "peeled and finely grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": null, "notes": "zest of 1 lemon, approx 3-5g", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Honey Lemon Glaze (Optional)", "items": [{"name": "powdered sugar", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": "add more to reach desired consistency", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 175\u00b0C (350\u00b0F). Grease a 23x13 cm (9x5 inch) loaf pan with butter or oil and line the bottom with parchment paper for easy removal.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a medium bowl, whisk together the flour, ground ginger, baking powder, baking soda, and salt until well combined.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a large mixing bowl or stand mixer fitted with the paddle attachment, beat the room temperature butter and granulated sugar on medium-high speed until pale and fluffy, about 3-4 minutes.", "structured": {"action": "CREAM", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Pale yellow color", "tactile": "Fluffy and aerated texture"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Reduce mixer speed to medium. Add the honey, grated fresh ginger, and lemon zest. Beat until incorporated.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the eggs one at a time, beating well after each addition and scraping down the sides of the bowl to ensure even mixing.", "structured": {"action": "BEAT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Reduce speed to low. Add half of the dry ingredients, followed by the sour cream and lemon juice, then the remaining dry ingredients. Mix only until the flour streaks disappear. Do not overmix.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": {"visual": "No dry flour streaks remaining", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Pour the batter into the prepared loaf pan and smooth the top with a spatula. Bake in the center of the oven for 50-60 minutes, or until a toothpick inserted into the center comes out clean or with just a few moist crumbs.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT55M", "doneness_cues": {"visual": "Golden brown top with a center crack", "tactile": "Toothpick comes out clean"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Let the cake cool in the pan for 10 minutes, then transfer it to a wire rack to cool completely. If using the glaze, whisk the glaze ingredients together and drizzle over the completely cooled cake.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT1H", "total_time": "PT1H20M", "overnight_required": false, "yields": "1 standard loaf (10 slices)", "yield_count": 10, "serving_size_g": 85}', '{"flags": ["Vegetarian", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Infants under 12 months (honey)", "Vegans (eggs, dairy)", "Celiacs (gluten)"]}', '{"per_serving": {"calories": 314.85, "protein_g": 4.27, "carbohydrates_g": 48.86, "fat_g": 11.98, "saturated_fat_g": 7.06, "trans_fat_g": null, "monounsaturated_fat_g": 3.5, "polyunsaturated_fat_g": 0.69, "fiber_g": 0.75, "sugar_g": 29.28, "sodium_mg": 268.58, "cholesterol_mg": 66.6, "potassium_mg": 75.44, "calcium_mg": 49.56, "iron_mg": 0.62, "magnesium_mg": 9.48, "phosphorus_mg": 70.15, "zinc_mg": 0.41, "vitamin_a_mcg": 106.91, "vitamin_c_mg": 1.42, "vitamin_d_mcg": 0.22, "vitamin_e_mg": 0.44, "vitamin_k_mcg": 0.98, "vitamin_b6_mg": 0.04, "vitamin_b12_mcg": 0.14, "thiamin_mg": 0.04, "riboflavin_mg": 0.09, "niacin_mg": 0.36, "folate_mcg": 13.54, "water_g": 27.57, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container to maintain moisture.", "duration": "P1W"}, "freezer": {"notes": "Wrap individual slices tightly in plastic wrap and foil.", "duration": "P3M"}, "reheating": "Warm slices in a toaster oven or microwave for 10-15 seconds to revive the texture.", "does_not_keep": false}', '[{"name": "Loaf pan (23x13 cm / 9x5 inch)", "required": true, "alternative": null}, {"name": "Stand mixer or hand mixer", "required": true, "alternative": "Whisk and strong arm"}, {"name": "Microplane or fine grater", "required": true, "alternative": null}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}]', '[{"symptom": "Cake sinks in the middle", "likely_cause": "The oven door was opened too early or the cake was underbaked", "prevention": "Do not open the oven door during the first 45 minutes of baking; verify doneness with a skewer before removing", "fix": "If caught early, cover with foil and return to oven immediately; otherwise, fill the divot with extra glaze or fruit compote"}, {"symptom": "Texture is tough or rubbery", "likely_cause": "Overmixing the batter after adding the flour", "prevention": "Stop mixing as soon as the last streak of flour disappears", "fix": "Cannot be fixed"}]', '["Rub the lemon zest into the sugar with your fingertips before creaming it with the butter. This releases the lemon oils for a more potent citrus aroma.", "Ensure all dairy and eggs are at room temperature. Cold ingredients will cause the butter batter to seize and curdle, leading to a denser cake.", "If the top of the loaf is browning too quickly before the center is set (check around the 40-minute mark), tent it loosely with aluminum foil.", "For a stronger ginger kick evocative of authentic Salabat, double the fresh ginger quantity."]', '"This recipe draws inspiration from ''Salabat'', a traditional Filipino ginger tea served as a restorative tonic and breakfast staple. By incorporating the tea''s core elements\u2014warm ginger, soothing honey, and bright citrus\u2014this loaf translates a beloved beverage into a comforting baked good suitable for ''Merienda'' (afternoon snack)."', 314.85);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('2a087680-9e9f-4e3b-9d71-a9ddeedce448', 'Crispy Sweetcorn Fritters with Bacon and Tomato Salad', 'Golden, crispy-edged fritters bursting with sweet corn kernels and fresh herbs, served alongside salty, shatteringly crisp streaky bacon and a bright, acidic tomato salad to balance the richness.', 'brunch', 'Modern Australian', 'Easy', '["fritters", "sweetcorn", "bacon", "tomato", "main course", "quick", "brunch", "modern australian"]', '[{"group_name": "Fritter Batter", "items": [{"name": "all-purpose flour", "quantity": 150, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5c0b5fc8-b210-4e39-b3a6-479541ac45d2", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "room temperature", "notes": "approx. 100g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "whole milk", "quantity": 80, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Corn & Aromatics", "items": [{"name": "sweetcorn kernels", "quantity": 300, "unit": "g", "preparation": "fresh or canned", "notes": "if canned, drain very well", "substitutions": [], "ingredient_id": "1822ba09-009f-4201-8d2a-275087c21e76", "nutrition_source": "Aggregated Public Data"}, {"name": "spring onions", "quantity": 3, "unit": null, "preparation": "thinly sliced", "notes": "approx. 45g", "substitutions": [], "ingredient_id": "e6dff0ca-5931-41ba-8842-6ce2a100a026", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh coriander", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "8c7693be-b538-445c-80f9-3d5bf4c6dcc0", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": "for frying, divided use", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}]}, {"group_name": "To Serve", "items": [{"name": "streaky bacon", "quantity": 200, "unit": "g", "preparation": null, "notes": "about 6-8 rashers", "substitutions": [], "ingredient_id": "339a356e-8f77-48fe-9293-b8e35fed3e6c", "nutrition_source": "USDA FoodData Central"}, {"name": "cherry tomatoes", "quantity": 250, "unit": "g", "preparation": "halved", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine the flour, baking powder, smoked paprika, and salt in a large mixing bowl. Whisk to aerate and remove lumps.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Make a well in the center of the dry ingredients. Crack the eggs into the well and add the milk. Whisk gradually from the center outwards until a thick, smooth batter forms.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": {"visual": "Smooth consistency similar to thick pancake batter", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Fold the sweetcorn kernels, sliced spring onions, and chopped coriander into the batter until evenly distributed. Do not overwork.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Place the bacon rashers in a cold large frying pan. Turn heat to medium-high and cook for 5-8 minutes, flipping occasionally, until fat renders and bacon is crispy. Transfer to a paper towel-lined plate, keeping the rendered fat in the pan.", "structured": {"action": "FRY", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Golden brown and stiff", "tactile": "Crispy"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add vegetable oil to the bacon fat in the pan to ensure the bottom is generously coated. Heat over medium heat until the oil shimmers (approx. 175\u00b0C/350\u00b0F).", "structured": {"action": "HEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Spoon 1/4 cup mounds of batter into the pan. Flatten slightly with the back of the spoon. Fry for 3-4 minutes per side until deep golden brown and cooked through. Transfer to a wire rack.", "structured": {"action": "FRY", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Deep golden crust", "tactile": "Firm to the touch"}}, "tips": ["Do not overcrowd the pan; cook in batches if necessary."]}, {"step_number": 7, "phase": "assemble", "text": "While fritters rest, toss the halved cherry tomatoes with olive oil and freshly cracked black pepper in a small bowl.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Plate the warm fritters topped with crispy bacon and serve the fresh tomato salad on the side.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT0M", "total_time": "PT30M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 320}', '{"flags": ["Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 575.4, "protein_g": 28.88, "carbohydrates_g": 48.98, "fat_g": 30.06, "saturated_fat_g": 9.02, "trans_fat_g": 0.24, "monounsaturated_fat_g": 13.41, "polyunsaturated_fat_g": 3.55, "fiber_g": 4.33, "sugar_g": 5.48, "sodium_mg": 1449.82, "cholesterol_mg": 148.5, "potassium_mg": 909.62, "calcium_mg": 122.45, "iron_mg": 2.68, "magnesium_mg": 67.89, "phosphorus_mg": 535.15, "zinc_mg": 2.84, "vitamin_a_mcg": 253.15, "vitamin_c_mg": 16.46, "vitamin_d_mcg": 0.76, "vitamin_e_mg": 1.15, "vitamin_k_mcg": 3.78, "vitamin_b6_mg": 0.23, "vitamin_b12_mcg": 0.89, "thiamin_mg": 0.24, "riboflavin_mg": 0.3, "niacin_mg": 5.86, "folate_mcg": 23.83, "water_g": 49.88, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store fritters and bacon separately from tomatoes to maintain texture.", "duration": "P3D"}, "freezer": {"notes": "Freeze fritters only. Reheat in oven/toaster oven.", "duration": "P1M"}, "reheating": "Reheat fritters in a dry pan or oven at 180\u00b0C until crisp. Microwave will make them soggy.", "does_not_keep": false}', '[{"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Large frying pan or skillet", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Spatula", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": false, "alternative": "Paper towel-lined plate"}, {"name": "Knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Fritters are soggy", "likely_cause": "Oil temperature was too low or pan was overcrowded", "prevention": "Ensure oil is shimmering before adding batter and leave space between fritters", "fix": "Finish in a 200\u00b0C/400\u00b0F oven for 5 minutes to crisp up"}, {"symptom": "Fritters are burnt outside but raw inside", "likely_cause": "Heat was too high", "prevention": "Use medium heat rather than high heat", "fix": "Lower heat immediately and finish cooking currently frying batch in the oven"}]', '["If using canned corn, drain it thoroughly and pat dry with paper towels to prevent the batter from becoming too watery.", "For extra crispiness, replace 20% of the flour with cornstarch or rice flour.", "Rest the batter for 10-15 minutes if you have time; this relaxes the gluten and results in a tenderer crumb.", "Using the rendered bacon fat for frying the fritters adds a significant depth of savory flavor."]', '"Corn fritters are a staple of Modern Australian ''brekkie'' culture, often found in cafes across Sydney and Melbourne. While rooted in Native American and Southern US traditions, this version emphasizes fresh produce and light textures suitable for brunch."', 575.4);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('2a39b6ff-816b-4d2e-86a4-7c86bba6925a', 'Butter-Poached Lobster Succotash', 'A refined interpretation of the American summer classic. Sweet fresh corn, tender cranberry beans, and seared okra provide a textural backdrop for succulent, butter-poached lobster. The dish is finished with fresh herbs and a touch of lemon to cut the richness.', 'dinner', 'American', 'Intermediate', '["american", "summer", "seafood", "corn", "cranberry bean", "green bean", "romano bean", "okra", "lobster", "dinner", "appetizer", "gluten-free"]', '[{"group_name": "Lobster", "items": [{"name": "lobster meat", "quantity": 450, "unit": "g", "preparation": "raw, cut into large chunks", "notes": "tail and claw meat from approx. 2-3 lobsters", "substitutions": [], "ingredient_id": "34f2d550-b220-4b17-9c47-fc3e5674cc19", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": null}]}, {"group_name": "Vegetables", "items": [{"name": "fresh cranberry beans", "quantity": 200, "unit": "g", "preparation": "shelled", "notes": "weight after shelling; can substitute fresh lima beans", "substitutions": [], "ingredient_id": "ae46d1d7-1daf-4e9c-a788-2b74c1e107e6", "nutrition_source": "USDA FoodData Central"}, {"name": "corn kernels", "quantity": 300, "unit": "g", "preparation": "fresh cut from cob", "notes": "approx. 3-4 ears", "substitutions": [], "ingredient_id": "46ca2aab-cb23-4397-9711-528c234b2cf8", "nutrition_source": "USDA FoodData Central"}, {"name": "romano beans", "quantity": 150, "unit": "g", "preparation": "trimmed and cut into 2cm pieces", "notes": null, "substitutions": [], "ingredient_id": "ac9f40f9-bfb1-4fb0-94dc-e5a62068149c", "nutrition_source": "Aggregated Public Data"}, {"name": "green beans", "quantity": 150, "unit": "g", "preparation": "trimmed and cut into 2cm pieces", "notes": null, "substitutions": [], "ingredient_id": "8b7e6e4d-368f-454b-9f38-1d55c66b40e4", "nutrition_source": "USDA FoodData Central"}, {"name": "okra", "quantity": 100, "unit": "g", "preparation": "sliced into 1cm rounds", "notes": null, "substitutions": [], "ingredient_id": "4b2867df-2cef-4146-b0df-55b20994dc3c", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "minced", "notes": "about 40g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 2, "unit": null, "preparation": "minced", "notes": "about 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "red bell pepper", "quantity": 80, "unit": "g", "preparation": "small diced", "notes": null, "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "heavy cream", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh chives", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh tarragon", "quantity": 5, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "d424d445-0a4e-45d1-9453-7523eb7b176b", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the shelled cranberry beans in a small saucepan and cover with water by 2-3 cm. Bring to a boil, reduce heat, and simmer until tender but not mushy. Drain and set aside.", "structured": {"action": "SIMMER", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT20M", "doneness_cues": {"visual": null, "tactile": "Creamy interior, skin intact"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Bring a large pot of salted water to a boil. Blanch the Romano beans and green beans for 3 minutes until crisp-tender. Drain and immediately transfer to an ice bath to stop cooking. Drain again and set aside.", "structured": {"action": "BLANCH", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT3M", "doneness_cues": {"visual": "Bright green color", "tactile": "Slight crunch"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a large skillet over medium-high heat, add a small knob of butter (approx 15g). Once foaming, add the okra rounds in a single layer. Sear without moving for 2 minutes to brown, then flip and cook 1 more minute. Remove okra from pan and set aside.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown edges", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "In a separate small saucepan, prepare the butter bath (beurre mont\u00e9). Bring 30ml water to a boil, reduce heat to low, and whisk in the remaining 100g butter, one cube at a time, until emulsified. Do not let it boil.", "structured": {"action": "EMULSIFY", "temperature": {"celsius": 80, "fahrenheit": 176}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the raw lobster chunks to the butter emulsion. Poach gently over very low heat until the lobster is opaque and firm. Remove from heat and keep warm.", "structured": {"action": "POACH", "temperature": {"celsius": 60, "fahrenheit": 140}, "duration": "PT6M", "doneness_cues": {"visual": "Opaque white meat", "tactile": "Firm to touch"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "In the large skillet used for okra, add the diced shallot, red pepper, and corn kernels (add a splash of oil if dry). Saut\u00e9 over medium heat until the corn is tender and bright yellow.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Add the garlic to the skillet and cook for 30 seconds until fragrant. Stir in the cooked cranberry beans, blanched green/Romano beans, and heavy cream. Simmer for 2 minutes to marry flavors.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Gently fold in the seared okra and the poached lobster (along with a few spoonfuls of the poaching butter). Remove from heat. Stir in lemon juice, chives, and tarragon. Season with salt and pepper to taste.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT50M", "passive_time": "PT10M", "total_time": "PT1H", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Pescatarian", "Gluten-Free", "Soy-Free", "Egg-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": ["Shellfish allergy"]}', '{"per_serving": {"calories": 671.28, "protein_g": 39.01, "carbohydrates_g": 63.68, "fat_g": 31.73, "saturated_fat_g": 18.66, "trans_fat_g": 0.2, "monounsaturated_fat_g": 8.73, "polyunsaturated_fat_g": 2.17, "fiber_g": 22.24, "sugar_g": 9.39, "sodium_mg": 700.2, "cholesterol_mg": 221.64, "potassium_mg": 1405.58, "calcium_mg": 238.29, "iron_mg": 4.47, "magnesium_mg": 184.92, "phosphorus_mg": 496.15, "zinc_mg": 6.57, "vitamin_a_mcg": 338.74, "vitamin_c_mg": 46.23, "vitamin_d_mcg": 0.24, "vitamin_e_mg": 2.39, "vitamin_k_mcg": 28.18, "vitamin_b6_mg": 0.57, "vitamin_b12_mcg": 1.48, "thiamin_mg": 0.62, "riboflavin_mg": 0.27, "niacin_mg": 4.63, "folate_mcg": 387.06, "water_g": 255.28, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best enjoyed fresh; reheating may toughen the lobster.", "duration": "P2D"}, "freezer": {"notes": "Do not freeze; texture of lobster and vegetables will degrade.", "duration": null}, "reheating": "Gently warm in a skillet over low heat with a splash of water or butter, just until tepid.", "does_not_keep": false}', '[{"name": "Large saucepan", "required": true, "alternative": null}, {"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": "Wok"}, {"name": "Small saucepan", "required": true, "alternative": "Small skillet"}, {"name": "Slotted spoon", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Okra is slimy", "likely_cause": "Crowded pan or cooked at too low temperature", "prevention": "Sear in a single layer over high heat and do not over-stir", "fix": "Add a splash of vinegar or lemon juice to help cut the slime"}, {"symptom": "Lobster is rubbery", "likely_cause": "Overcooked in the butter bath", "prevention": "Keep temperature below 65\u00b0C/150\u00b0F and remove as soon as opaque", "fix": "Dice smaller and mix thoroughly with vegetables to mask texture; cannot be reversed"}]', '["To easily shell fresh cranberry beans, twist the pod to pop it open; if fresh ones aren''t available, canned borlotti beans are a decent substitute, just rinse them well.", "The butter poaching liquid (beurre mont\u00e9) is liquid gold. Do not discard it; drizzle any extra over the finished dish or use it to saut\u00e9 the corn.", "Romano beans are flatter and wider than green beans; if you can''t find them, simply double the quantity of regular green beans or use wax beans for color contrast.", "Ensure the okra is added at the very end. If it is simmered with the sauce too long, it will release mucilage and thicken the dish excessively."]', '"Succotash has roots in Native American cuisine, specifically the Narragansett word ''ms\u00edckquatash'' (boiled corn kernels). While traditionally a simple stew of corn and beans enriched with bear fat or salt pork, this version elevates the humble staple into a luxurious coastal feast by incorporating French butter-poaching techniques and sweet lobster."', 671.28);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('2aa2f206-8cc8-4564-ae26-9350c755da71', 'Mediterranean Lamb Burgers with Sautéed Peppers', 'Juicy, herb-infused lean lamb patties nestled in warm pita pockets, topped with sweet sautéed peppers and onions. A vibrant, protein-rich dinner that balances savory richness with fresh, zesty aromatics.', 'dinner', 'Greek', 'Easy', '["greek", "middle eastern", "burgers", "lamb", "olive", "red bell pepper", "tomato", "dinner", "weeknight", "main course", "healthy"]', '[{"group_name": "Lamb Patties", "items": [{"name": "lean ground lamb", "quantity": 500, "unit": "g", "preparation": "chilled", "notes": "at least 90% lean recommended for lower fat", "substitutions": [], "ingredient_id": "283a36a7-2de3-480f-a632-76e0445799dd", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": "minced", "notes": "about 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Saut\u00e9ed Vegetables", "items": [{"name": "red bell pepper", "quantity": 1, "unit": null, "preparation": "sliced into strips", "notes": "about 150g", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "Aggregated Public Data"}, {"name": "green bell pepper", "quantity": 1, "unit": null, "preparation": "sliced into strips", "notes": "about 150g", "substitutions": [], "ingredient_id": "627afa21-0392-4082-ab38-0f20446e190e", "nutrition_source": "Aggregated Public Data"}, {"name": "red onion", "quantity": 1, "unit": null, "preparation": "sliced into half-moons", "notes": "medium size, approx 150g", "substitutions": [], "ingredient_id": "1c270c6e-0acc-4c5c-9935-7eff3240fc4a", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "divided use", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Assembly & Garnish", "items": [{"name": "pita breads", "quantity": 4, "unit": null, "preparation": "warmed", "notes": "whole wheat preferred", "substitutions": [], "ingredient_id": "6bc4d0e9-228a-453e-8349-8169e84e7a7f", "nutrition_source": "Aggregated Public Data"}, {"name": "tzatziki sauce", "quantity": 120, "unit": "ml", "preparation": null, "notes": "store-bought or homemade", "substitutions": [], "ingredient_id": "d9a2dea7-8ccd-425e-87f5-d156b0d55925", "nutrition_source": "Aggregated Public Data"}, {"name": "tomato", "quantity": 1, "unit": null, "preparation": "sliced", "notes": "optional for freshness", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a large mixing bowl, gently combine the lean ground lamb, minced garlic, oregano, cumin, salt, and pepper. Use your hands to mix just until combined to ensure tenderness.", "structured": {"action": "MIX", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": ["Do not overmix the meat, or the burgers will become tough."]}, {"step_number": 2, "phase": "prep", "text": "Divide the lamb mixture into 4 equal portions. Shape each portion into an oval patty roughly the same shape as your pita pockets, about 1.5 cm (0.6 inches) thick.", "structured": {"action": "SHAPE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat half of the olive oil (7-8 ml) in a large skillet over medium-high heat. Add the lamb patties and cook for 3-4 minutes per side, or until browned and cooked through to an internal temperature of 71\u00b0C/160\u00b0F.", "structured": {"action": "SEAR", "temperature": {"celsius": 71, "fahrenheit": 160}, "duration": "PT8M", "doneness_cues": {"visual": "Deep brown crust", "tactile": "Firm to the touch"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Remove patties from the pan and set aside on a plate to rest. Drain excess fat from the pan if necessary, leaving a thin coating for flavor.", "structured": {"action": "REST", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the remaining olive oil to the same skillet. Add the sliced peppers and onions. Saut\u00e9 over medium-high heat until the vegetables are tender and slightly charred at the edges.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Softened with charred edges", "tactile": "Tender-crisp"}}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "While vegetables cook, warm the pita breads in a toaster or low oven. Slice open the tops to create pockets.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Spread a generous tablespoon of tzatziki inside each pita. Insert a lamb patty and top with the hot saut\u00e9ed pepper and onion mixture.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT10M", "total_time": "PT35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 320}', '{"flags": ["Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Vegans", "Vegetarians"]}', '{"per_serving": {"calories": 646.35, "protein_g": 29.78, "carbohydrates_g": 48.98, "fat_g": 36.6, "saturated_fat_g": 13.44, "trans_fat_g": null, "monounsaturated_fat_g": 14.88, "polyunsaturated_fat_g": 3.15, "fiber_g": 4.57, "sugar_g": 6.8, "sodium_mg": 1026.04, "cholesterol_mg": 91.25, "potassium_mg": 704.39, "calcium_mg": 130.05, "iron_mg": 4.99, "magnesium_mg": 64.57, "phosphorus_mg": 304.83, "zinc_mg": 5.14, "vitamin_a_mcg": 76.81, "vitamin_c_mg": 125.46, "vitamin_d_mcg": 0.13, "vitamin_e_mg": 1.69, "vitamin_k_mcg": 12.32, "vitamin_b6_mg": 0.33, "vitamin_b12_mcg": 2.89, "thiamin_mg": 0.56, "riboflavin_mg": 0.52, "niacin_mg": 10.89, "folate_mcg": 110.65, "water_g": 164.78, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store patties and peppers separately from pitas to prevent sogginess.", "duration": "P3D"}, "freezer": {"notes": "Cooked or raw patties freeze well; wrap individually.", "duration": "P2M"}, "reheating": "Reheat patties in a pan over medium heat or microwave gently; toast pitas fresh.", "does_not_keep": false}', '[{"name": "Large skillet or cast iron pan", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Burgers are tough or dry", "likely_cause": "Meat was overmixed or overcooked", "prevention": "Mix gently only until ingredients are incorporated and use a thermometer to pull exactly at 71\u00b0C/160\u00b0F", "fix": "Add extra tzatziki sauce to the pita to add moisture"}, {"symptom": "Burgers fall apart in the pan", "likely_cause": "Fat content too low or handled too roughly while flipping", "prevention": "Pack patties firmly (without overworking) and let a crust form before the first flip", "fix": " crumble the meat and serve as a \"loose meat\" pita filling"}]', '["Indent the center of each raw patty slightly with your thumb; this prevents them from puffing up into a ball while cooking.", "For a true low-fat version, drain the pan completely after cooking the lamb and use a quick spray of oil for the peppers instead of adding more liquid oil.", "If you have time, let the formed patties chill in the fridge for 20 minutes before cooking to help them hold their shape better."]', '"While the concept of a ground meat patty in bread is universal, this recipe draws heavily on the Greek ''bifteki'' tradition. The use of oregano, cumin, and garlic pairs classically with the cooling properties of yogurt-based tzatziki, reflecting the balance of heat and cool found in Eastern Mediterranean cuisine."', 646.35);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('2ab2908c-b4db-42cb-a62d-2e97f246400f', 'Spiced Tomato Salad with Cumin Yogurt & Dill Dressing', 'A vibrant, cooling salad featuring juicy ripe tomatoes atop a bed of rich, toasted-cumin yogurt, finished with a bright dill and white wine vinegar dressing. The earthiness of the cumin contrasts beautifully with the acidity of the tomatoes and the fresh grassy notes of dill.', 'salad', 'Modern Indian', 'Easy', '["indian", "dill", "greek yogurt", "salad", "tomato", "white wine vinegar", "easy", "quick", "side", "vegetarian", "summer"]', '[{"group_name": "Cumin Yogurt Base", "items": [{"name": "greek yogurt", "quantity": 250, "unit": "g", "preparation": "thick, cold", "notes": "full fat preferred", "substitutions": [], "ingredient_id": "61eae1a4-8517-4da8-8c29-34288cb7d8c7", "nutrition_source": "USDA FoodData Central"}, {"name": "cumin seeds", "quantity": 2, "unit": "g", "preparation": "whole", "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Tomatoes", "items": [{"name": "heirloom tomatoes", "quantity": 300, "unit": "g", "preparation": "sliced or wedges", "notes": "mixed colors if possible", "substitutions": ["cherry tomatoes", "vine tomatoes"], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "flaky sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "for finishing", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dill Herb Dressing", "items": [{"name": "fresh dill", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": "leaves and tender stems", "substitutions": [], "ingredient_id": "4be2b047-475d-4c84-82d5-4883298c6121", "nutrition_source": "USDA FoodData Central"}, {"name": "white wine vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b2f8f0c0-6da9-47aa-932a-c2747b64b807", "nutrition_source": "Aggregated Public Data"}, {"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "minced or grated", "notes": "small clove, approx 3g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the cumin seeds in a dry small frying pan over medium heat. Toast for 1-2 minutes until fragrant and slightly darkened, shaking the pan frequently to prevent burning.", "structured": {"action": "TOAST", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT2M", "doneness_cues": {"visual": "Seeds darken slightly", "tactile": "Aromatic"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Roughly crush the toasted cumin seeds using a mortar and pestle (or the back of a knife). In a mixing bowl, whisk the yogurt with the crushed cumin, lemon juice, and salt until smooth.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a small bowl or jar, whisk together the white wine vinegar, minced garlic, chopped dill, and a pinch of salt. Slowly stream in the olive oil while whisking to emulsify.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Slice the tomatoes into wedges or rounds of varying sizes. If using cherry tomatoes, halve them.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Spread the spiced yogurt generously across the bottom of two serving plates. Arrange the tomato slices on top of the yogurt.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Drizzle the dill dressing over the tomatoes and yogurt. Finish with flaky sea salt and freshly cracked black pepper. Serve immediately.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT0M", "total_time": "PT15M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 280}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Egg-Free", "Low-Carb"], "not_suitable_for": ["Vegan (contains dairy)"]}', '{"per_serving": {"calories": 336.62, "protein_g": 11.54, "carbohydrates_g": 22.67, "fat_g": 23.26, "saturated_fat_g": 3.25, "trans_fat_g": 0.02, "monounsaturated_fat_g": 16.66, "polyunsaturated_fat_g": 2.42, "fiber_g": 3.96, "sugar_g": 6.02, "sodium_mg": 635.49, "cholesterol_mg": 6.25, "potassium_mg": 428.46, "calcium_mg": 151.78, "iron_mg": 1.65, "magnesium_mg": 24.46, "phosphorus_mg": 47.78, "zinc_mg": 0.38, "vitamin_a_mcg": 87.58, "vitamin_c_mg": 40.66, "vitamin_d_mcg": null, "vitamin_e_mg": 3.29, "vitamin_k_mcg": 14.45, "vitamin_b6_mg": 0.04, "vitamin_b12_mcg": null, "thiamin_mg": 0.02, "riboflavin_mg": 0.02, "niacin_mg": 0.14, "folate_mcg": 8.73, "water_g": 109.44, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten immediately. Yogurt and dressing can be stored separately for 3 days.", "duration": "P1D"}, "freezer": {"notes": "Do not freeze.", "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Small frying pan", "required": true, "alternative": null}, {"name": "Mortar and pestle", "required": false, "alternative": "Spice grinder or rolling pin"}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}]', '[{"symptom": "Yogurt is too watery/runny", "likely_cause": "Low-fat yogurt used or yogurt not strained", "prevention": "Use Greek-style yogurt or strain regular yogurt through cheesecloth for 30 minutes", "fix": "Whisk in a teaspoon of tahini to thicken, or accept the thinner consistency"}]', '["Always season the tomatoes directly with salt just before serving; this draws out their juices which mix with the dressing for a better flavor.", "For a deeper flavor profile, bloom the minced garlic in the vinegar for 5-10 minutes before adding the oil.", "If you want extra crunch, garnish with toasted pine nuts or crispy fried shallots.", "Ensure the yogurt is very cold and the tomatoes are at room temperature for a delightful temperature contrast."]', '"This dish draws inspiration from Indian Raita, traditionally a cooling yogurt condiment, but reimagines it as a composed salad plate. The use of toasted cumin is the hallmark of Indian flavor profiles, while the composed plating style and vinaigrette lean towards modern European presentation."', 336.62);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('2c678300-092a-4477-aee4-a4beb110af91', 'Spiced Red Wine Poached Prunes', 'Luxuriously tender prunes steeped in a velvety red wine reduction. The natural sweetness of the fruit is balanced by tannic depth, bright orange zest, and a subtle, warming heat from black peppercorns.', 'dessert', 'French', 'Easy', '["fruity red wine", "prune", "dessert", "winter", "christmas", "french", "gluten-free", "vegan"]', '[{"group_name": "Fruit", "items": [{"name": "dried prunes", "quantity": 500, "unit": "g", "preparation": "pitted", "notes": "Ensure they are pliable, not rock hard", "substitutions": [], "ingredient_id": "1551c75d-7b61-4e60-ae0a-0944faf91353", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Poaching Liquid", "items": [{"name": "fruity red wine", "quantity": 500, "unit": "ml", "preparation": null, "notes": "Merlot, Zinfandel, or Grenache work best", "substitutions": [], "ingredient_id": "0fc93141-8ba8-42e0-ac8b-b5af3851554c", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "orange", "quantity": 1, "unit": null, "preparation": "whole", "notes": "Use peel for zest strips, reserve juice if desired", "substitutions": [], "ingredient_id": "a644a589-02d1-4b90-98c5-ec79373a767b", "nutrition_source": "USDA FoodData Central"}, {"name": "black peppercorns", "quantity": 1, "unit": "g", "preparation": "whole", "notes": "Approx. 10-12 peppercorns", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "cinnamon stick", "quantity": 1, "unit": null, "preparation": null, "notes": "Optional for extra winter warmth", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Using a vegetable peeler, remove the zest from the orange in wide strips, avoiding the bitter white pith.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a medium saucepan, combine the red wine, sugar, orange zest strips, whole peppercorns, and cinnamon stick (if using). Bring to a boil over medium-high heat, stirring until the sugar dissolves.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the prunes to the liquid. Ensure they are mostly submerged. Reduce heat to low and simmer gently for 15-20 minutes until the prunes are plump and tender, and the liquid has slightly reduced to a light syrup consistency.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT20M", "doneness_cues": {"visual": "Prunes appear swollen and glossy", "tactile": "Prunes are very soft but holding their shape"}}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Remove from heat. Let the prunes cool in the syrup. The liquid will continue to thicken as it cools. Remove the cinnamon stick before storing, but leave the orange zest and peppercorns for visual appeal.", "structured": {"action": "COOL", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT20M", "total_time": "PT35M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 120}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Low-Fat"], "not_suitable_for": []}', '{"per_serving": {"calories": 348.84, "protein_g": 2.25, "carbohydrates_g": 79.26, "fat_g": 0.39, "saturated_fat_g": null, "trans_fat_g": null, "monounsaturated_fat_g": null, "polyunsaturated_fat_g": null, "fiber_g": 8.52, "sugar_g": 26.81, "sodium_mg": 2.57, "cholesterol_mg": null, "potassium_mg": 660.64, "calcium_mg": 76.62, "iron_mg": 1.01, "magnesium_mg": 39.52, "phosphorus_mg": 62.63, "zinc_mg": 0.44, "vitamin_a_mcg": 59.92, "vitamin_c_mg": 29.49, "vitamin_d_mcg": null, "vitamin_e_mg": 0.01, "vitamin_k_mcg": 0.43, "vitamin_b6_mg": null, "vitamin_b12_mcg": null, "thiamin_mg": null, "riboflavin_mg": null, "niacin_mg": 0.01, "folate_mcg": 0.06, "water_g": 73.33, "alcohol_g": 7.75, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves significantly after 24 hours.", "duration": "P2W"}, "freezer": {"notes": "Texture may degrade slightly upon thawing.", "duration": null}, "reheating": "Serve warm, room temperature, or chilled.", "does_not_keep": false}', '[{"name": "Medium saucepan", "required": true, "alternative": null}, {"name": "Vegetable peeler", "required": true, "alternative": "Paring knife"}, {"name": "Wooden spoon", "required": true, "alternative": null}]', '[{"symptom": "Prunes are mushy and falling apart", "likely_cause": "Overcooked or boiled too vigorously", "prevention": "Maintain a very gentle simmer (barely bubbling) and check texture after 10 minutes", "fix": "Remove prunes immediately with a slotted spoon; reduce the syrup separately until thick, then pour over prunes"}, {"symptom": "Syrup is too thin/runny", "likely_cause": "Not enough reduction time or too much liquid", "prevention": "Measure wine accurately", "fix": "Remove prunes, boil liquid rapidly until it coats the back of a spoon, then recombine"}]', '["Select a fruit-forward red wine with low tannins for the best result; a heavily oaked Cabernet can turn bitter when reduced.", "These are exceptional when served warm over vanilla bean ice cream or cold alongside a sharp cheese plate.", "For a more complex flavor profile, add a star anise pod or a split vanilla bean during the simmering stage.", "If the prunes were very dry to begin with, you may need to add 50ml of water or orange juice to ensure they rehydrate fully without the syrup becoming dry."]', '"Inspired by the French classic ''Pruneaux au Vin Rouge,'' this dish transforms humble dried plums into a sophisticated dessert element. While often associated with the harvest, the warming spices make it a staple of winter holiday tables."', 348.84);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('2ca343ed-c9a6-45b9-8045-0e89974fbf48', 'Mediterranean Crispy Calamari Panzanella', 'A vibrant textural masterpiece combining golden, flash-fried calamari rings with rustic garlic-infused sourdough croutons. Sweet ripe tomatoes and biting red onion cut through the richness, all tied together with a zesty lemon-oregano vinaigrette.', 'salad', 'Mediterranean', 'Intermediate', '["mediterranean", "seafood", "country bread", "salad", "squid", "tomato", "dinner", "lunch", "appetizer", "dairy-free", "nut-free", "summer"]', '[{"group_name": "Vegetables", "items": [{"name": "mixed heirloom tomatoes", "quantity": 400, "unit": "g", "preparation": "cut into wedges", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "red onion", "quantity": 1, "unit": null, "preparation": "thinly sliced", "notes": "approx 100g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "cucumber", "quantity": 150, "unit": "g", "preparation": "sliced into half-moons", "notes": null, "substitutions": [], "ingredient_id": "457adec2-3e06-4efe-a26e-9e6ea9f84924", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garlic Bread Croutons", "items": [{"name": "country sourdough bread", "quantity": 200, "unit": "g", "preparation": "torn into 3cm chunks", "notes": "preferably day-old", "substitutions": [], "ingredient_id": "90f297c6-9ec3-45a6-850d-9aa9c65b45e7", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": "for frying bread", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": "crushed", "notes": "approx 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Calamari", "items": [{"name": "squid tubes", "quantity": 500, "unit": "g", "preparation": "cleaned, sliced into 1cm rings", "notes": null, "substitutions": [], "ingredient_id": "e126ab3d-72fc-463a-a50c-461c65ccdf4d", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "semolina flour", "quantity": 60, "unit": "g", "preparation": null, "notes": "for crunch", "substitutions": [], "ingredient_id": "276312e9-6353-4fa7-8538-bf43246ba74e", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 100, "unit": "ml", "preparation": null, "notes": "for shallow frying", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}]}, {"group_name": "Lemon Dressing", "items": [{"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "036c7254-3de5-4c6e-a2e7-366ad4d05077", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh lemon juice", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the sliced red onion in a small bowl and cover with cold water. Let sit for 10 minutes to remove the harsh raw bite, then drain and pat dry.", "structured": {"action": "SOAK", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Whisk together extra virgin olive oil, lemon juice, minced garlic, oregano, and a pinch of salt and pepper in a small bowl to create the dressing. Set aside.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat 45ml olive oil in a large skillet over medium heat. Add the crushed garlic cloves to infuse the oil for 1 minute, then remove them. Add the torn bread chunks. Fry, tossing frequently, until golden brown and very crisp. Remove bread to a plate lined with paper towels.", "structured": {"action": "FRY", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT5M", "doneness_cues": {"visual": "Golden brown", "tactile": "Crisp and rigid"}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In a shallow bowl, mix the all-purpose flour, semolina, and salt. Pat the squid rings very dry with paper towels to ensure the coating sticks.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Wipe the skillet clean and add the vegetable oil over medium-high heat. Toss the squid rings in the flour mixture, shaking off excess. Fry in batches (do not crowd the pan) for 2-3 minutes until golden and crisp. Transfer to fresh paper towels.", "structured": {"action": "FRY", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT3M", "doneness_cues": {"visual": "Golden coating, opaque meat", "tactile": null}}, "tips": ["Crowding the pan steams the squid instead of frying it, resulting in rubbery texture."]}, {"step_number": 6, "phase": "assemble", "text": "In a large bowl, combine the tomatoes, drained onions, cucumber, parsley, and garlic croutons. Add half the dressing and toss. Top with the hot crispy calamari, drizzle with the remaining dressing, and serve immediately.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT10M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 320}', '{"flags": ["Pescatarian", "Dairy-Free", "Nut-Free"], "not_suitable_for": ["Gluten intolerance (unless GF bread/flour used)"]}', '{"per_serving": {"calories": 628.94, "protein_g": 29, "carbohydrates_g": 59.95, "fat_g": 29.16, "saturated_fat_g": 4.17, "trans_fat_g": null, "monounsaturated_fat_g": 8.38, "polyunsaturated_fat_g": 1.94, "fiber_g": 5.09, "sugar_g": 6.61, "sodium_mg": 1097.86, "cholesterol_mg": 291.25, "potassium_mg": 730.13, "calcium_mg": 84.83, "iron_mg": 2.19, "magnesium_mg": 74.6, "phosphorus_mg": 362.35, "zinc_mg": 2.57, "vitamin_a_mcg": 30.59, "vitamin_c_mg": 31.55, "vitamin_d_mcg": null, "vitamin_e_mg": 3.28, "vitamin_k_mcg": 77.74, "vitamin_b6_mg": 0.18, "vitamin_b12_mcg": 1.63, "thiamin_mg": 0.08, "riboflavin_mg": 0.55, "niacin_mg": 3.09, "folate_mcg": 26.02, "water_g": 170.47, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store components separately if possible; bread and calamari will lose crunch.", "duration": "P1D"}, "freezer": {"notes": "Do not freeze.", "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Large heavy-bottomed skillet or frying pan", "required": true, "alternative": null}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Slotted spoon or spider", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}]', '[{"symptom": "Calamari coating is soggy or falling off", "likely_cause": "Squid was too wet before dredging or oil wasn''t hot enough", "prevention": "Pat squid extremely dry; ensure oil shimmers before adding", "fix": "Cannot fix current batch; increase heat for next batch"}, {"symptom": "Calamari is rubbery and tough", "likely_cause": "Overcooked", "prevention": "Cook for no more than 2-3 minutes; remove as soon as coating is gold", "fix": "Cannot be fixed"}]', '["The semolina is crucial here; it provides a ''sandy'' crunch that stays crispier longer than plain flour when in contact with the dressing.", "Using torn bread rather than cut cubes creates craggy edges that catch more of the dressing and garlic oil.", "This dish is best assembled \u00e0 la minute. If preparing ahead, keep the fried components, salad vegetables, and dressing in three separate containers.", "If your tomatoes are very juicy, salt them in a colander for 10 minutes first to concentrate their flavor and prevent a watery salad bottom."]', '"This dish is a coastal spin on the Tuscan ''Panzanella,'' a salad originally designed to use up stale bread and ripe summer produce. By adding fried calamari (a staple of Mediterranean coastal frying or ''fritto misto''), it bridges the gap between a light peasant lunch and a substantial seafood dinner."', 628.94);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('2d7fe1a3-dbb7-4632-9655-d5263c5d92bc', 'Glazed Lemon Blueberry Almond Cookies', 'Soft, pillowy cookies bursting with jammy blueberries and aromatic almond, finished with a zesty lemon glaze. These tender, cake-like treats balance the sweetness of almond confection with bright citrus acidity.', 'dessert', 'American', 'Easy', '["almond extract", "blueberry", "cookie", "egg yolk", "lemon juice", "lemon zest", "make-ahead", "dessert", "summer", "vegetarian"]', '[{"group_name": "Dough", "items": [{"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "room temperature softened", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 200, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 6g, from 1 large lemon", "substitutions": [], "ingredient_id": "03fb65be-9b62-44e7-a121-694de64cdec0", "nutrition_source": "Aggregated Public Data"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": "large, room temperature", "notes": "approx 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "egg yolk", "quantity": 1, "unit": null, "preparation": "large", "notes": "approx 18g", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}, {"name": "almond extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "39141299-c561-4745-8ff7-cf7c62c75675", "nutrition_source": "Aggregated Public Data"}, {"name": "all-purpose flour", "quantity": 260, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 6, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh blueberries", "quantity": 150, "unit": "g", "preparation": "washed and thoroughly dried", "notes": "small wild blueberries work best", "substitutions": [], "ingredient_id": "0f9f22a4-4f00-4950-9145-943d55b6dec8", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Lemon Glaze", "items": [{"name": "powdered sugar", "quantity": 120, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 30, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "milk", "quantity": 5, "unit": "ml", "preparation": null, "notes": "only if needed to thin", "substitutions": [], "ingredient_id": "c75fcd6a-414e-40b9-bc04-333fb15c0c38", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a large bowl or stand mixer, cream the softened butter, granulated sugar, and lemon zest together on medium-high speed until pale and fluffy (about 2-3 minutes). The zest is added here to release oils into the sugar.", "structured": {"action": "CREAM", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Add the whole egg, egg yolk, and almond extract. Beat on medium speed until well combined, scraping down the sides of the bowl as needed.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Add the flour, baking powder, and salt. Mix on low speed just until streaks of flour disappear. Do not overmix, or the cookies will become tough rather than cake-like.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Gently fold in the blueberries by hand using a spatula, taking care not to crush them.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Cover the bowl and chill the dough in the refrigerator for at least 30 minutes. This is crucial for flavor development and controlling the spread.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Preheat your oven to 175\u00b0C (350\u00b0F). Line baking sheets with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Scoop the dough into 30-40g portions (about 2 tablespoons each) and place them on the prepared baking sheets, spaced 5cm (2 inches) apart.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Bake for 12-14 minutes, or until the edges are just set and very lightly golden. The centers should still look soft and slightly underdone.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT13M", "doneness_cues": {"visual": "Edges set and pale golden", "tactile": "Centers soft but not raw"}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Allow cookies to cool on the baking sheet for 5 minutes, then transfer to a wire rack to cool completely. They are fragile while hot.", "structured": {"action": "COOL", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Whisk the powdered sugar and lemon juice together in a small bowl until smooth. Drizzle over the completely cooled cookies. Let the glaze set for 10 minutes before serving.", "structured": {"action": "GLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT50M", "total_time": "PT1H15M", "overnight_required": false, "yields": "24 cookies", "yield_count": 24, "serving_size_g": 45}', '{"flags": ["Vegetarian", "Peanut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 135.33, "protein_g": 1.6, "carbohydrates_g": 22.74, "fat_g": 4.42, "saturated_fat_g": 2.58, "trans_fat_g": null, "monounsaturated_fat_g": 1.3, "polyunsaturated_fat_g": 0.27, "fiber_g": 0.47, "sugar_g": 13.93, "sodium_mg": 79.55, "cholesterol_mg": 26.18, "potassium_mg": 23.54, "calcium_mg": 20.46, "iron_mg": 0.24, "magnesium_mg": 3.34, "phosphorus_mg": 26.4, "zinc_mg": 0.14, "vitamin_a_mcg": 39.25, "vitamin_c_mg": 1.09, "vitamin_d_mcg": 0.09, "vitamin_e_mg": 0.2, "vitamin_k_mcg": 1.59, "vitamin_b6_mg": 0.01, "vitamin_b12_mcg": 0.04, "thiamin_mg": 0.02, "riboflavin_mg": 0.02, "niacin_mg": 0.17, "folate_mcg": 5.67, "water_g": 10.67, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container; layers separated by parchment.", "duration": "P5D"}, "freezer": {"notes": "Freeze unglazed dough balls or baked cookies.", "duration": "P3M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Stand mixer or electric hand mixer", "required": true, "alternative": "Whisk and strong spatula"}, {"name": "Baking sheets", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Cookie scoop", "required": false, "alternative": "Two spoons"}, {"name": "Wire cooling rack", "required": true, "alternative": null}, {"name": "Small bowl", "required": true, "alternative": null}]', '[{"symptom": "Dough turned purple/grey", "likely_cause": "Blueberries were crushed during mixing or were frozen and thawed", "prevention": "Fold berries in very gently by hand at the very end; if using frozen, keep them frozen until the moment they hit the dough.", "fix": "Cosmetic issue only; cookies will still taste delicious."}, {"symptom": "Cookies spread too much and are flat", "likely_cause": "Butter was too warm or dough wasn''t chilled long enough", "prevention": "Ensure butter is cool-room-temp, not melting. Chill dough for the full 30 minutes.", "fix": "Chill the remaining dough longer before baking the next batch."}]', '["If using frozen blueberries, do not thaw them. Toss them in a teaspoon of flour before folding into the dough to prevent bleeding.", "For the most tender texture, stop mixing the dough the second you see the last streak of flour disappear.", "The almond extract is potent; if you prefer a subtler flavor, reduce to 2.5ml (1/2 tsp), but the pairing with blueberry is classic."]', '"This style of ''cake cookie'' (sometimes called a drop cake) bridges the gap between a muffin and a traditional cookie. The combination of blueberry and lemon is a staple of American summer baking, often associated with Maine, the largest producer of wild blueberries in the world."', 135.33);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('2d8c860b-d9c9-4cec-a22e-8990e1048579', 'Pastrami-Cured Duck Breast with Smacked Cucumber & Ginger Scallion Oil', 'A sophisticated fusion concept marrying the peppery, coriander-heavy crust of NYC deli pastrami with the richness of duck breast. Paired with a vibrant, jagged-textured Sichuan-style cucumber salad and a sizzling ginger-scallion oil to cut through the fat.', 'main course', 'Fusion', 'Advanced', '["duck", "pastrami", "fusion", "dinner party", "cured", "cucumber salad"]', '[{"group_name": "Duck & Cure", "items": [{"name": "duck breasts", "quantity": 4, "unit": null, "preparation": "boneless, skin-on", "notes": "approx. 200-250g each", "substitutions": [], "ingredient_id": "24c962a2-b4f8-49f7-9b30-2a6754d14b10", "nutrition_source": "Aggregated Public Data"}, {"name": "kosher salt", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "brown sugar", "quantity": 25, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic powder", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "177a312f-ef99-4398-9108-98f7a608a245", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pastrami Crust", "items": [{"name": "whole coriander seeds", "quantity": 20, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "whole black peppercorns", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "mustard seeds", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "69e2b7a1-7252-486e-841e-51655b028a97", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Ginger Scallion Oil", "items": [{"name": "fresh ginger", "quantity": 40, "unit": "g", "preparation": "finely grated or minced", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "scallions", "quantity": 4, "unit": null, "preparation": "finely minced", "notes": "greens and whites separated", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 80, "unit": "ml", "preparation": null, "notes": "grapeseed or canola", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "sherry vinegar", "quantity": 10, "unit": "ml", "preparation": null, "notes": "adds acid balance", "substitutions": [], "ingredient_id": "dcfa7371-7051-4604-a76e-4a46ae1f9e7b", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Smacked Cucumber Salad", "items": [{"name": "persian cucumbers", "quantity": 6, "unit": null, "preparation": "washed", "notes": "approx. 500g", "substitutions": [], "ingredient_id": "457adec2-3e06-4efe-a26e-9e6ea9f84924", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "for drawing water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "smashed and minced", "notes": "cloves", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "black vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": "Chinkiang vinegar preferred", "substitutions": ["10ml balsamic + 5ml rice vinegar"], "ingredient_id": "33ee5dde-8b35-4013-8a32-195777ccd5ef", "nutrition_source": "Aggregated Public Data"}, {"name": "sesame oil", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e74beff5-5295-4a3f-82fb-9f8ef1d5da59", "nutrition_source": "USDA FoodData Central"}, {"name": "sugar", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "chili crisp", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a4bf8b34-30b2-4d24-a120-b5b191811f64", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Score the duck skin in a cross-hatch pattern, being careful not to cut into the meat. Combine kosher salt, brown sugar, smoked paprika, and garlic powder in a small bowl.", "structured": {"action": "SCORE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Diamond pattern on skin without exposing red meat", "tactile": null}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Rub the cure mixture thoroughly over the duck breasts. Place on a rack or plate, cover loosely, and refrigerate for 12 to 24 hours to cure.", "structured": {"action": "CURE", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "P1D", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Preheat oven to 160\u00b0C/320\u00b0F. Toast coriander seeds, peppercorns, and mustard seeds in a dry pan until fragrant. Coarsely crack them in a mortar and pestle. Rinse the cure off the duck and pat extremely dry. Press the cracked spice mixture firmly into the skin side only.", "structured": {"action": "TOAST", "temperature": null, "duration": null, "doneness_cues": {"visual": "Spices are fragrant and slightly darkened", "tactile": "Coarse, gravel-like texture"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Place duck breasts skin-side down in a cold, dry skillet. Turn heat to medium-low. Cook slowly to render fat and crisp the skin (about 10-12 minutes). Do not flip yet.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT12M", "doneness_cues": {"visual": "Skin is dark golden and crispy", "tactile": "Fat layer has significantly reduced"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Flip the breasts and transfer the skillet to the oven (or transfer meat to a baking sheet). Roast until internal temperature reaches 54\u00b0C/129\u00b0F for medium-rare.", "structured": {"action": "ROAST", "temperature": {"celsius": 54, "fahrenheit": 129}, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "While duck rests (min 10 mins), prepare the cucumbers. Place cucumbers on a board and smack them with the flat of a cleaver or heavy pan until they split. Cut into bite-sized chunks. Toss with 5g salt and let sit for 10 minutes to drain excess water. Drain liquid before dressing.", "structured": {"action": "CRUSH", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Make the ginger oil: Place minced ginger and scallions in a heat-proof bowl with salt and white pepper. Heat neutral oil in a small pan until shimmering and just smoking, then carefully pour over the aromatics to sizzle. Stir in sherry vinegar.", "structured": {"action": "TEMPER", "temperature": null, "duration": null, "doneness_cues": {"visual": "Oil bubbles vigorously upon contact", "tactile": "Aromatics become instantly fragrant"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Whisk soy sauce, black vinegar, sesame oil, sugar, and garlic together. Toss with drained cucumbers and chili crisp. Slice duck breast thinly against the grain. Serve duck topped with ginger oil, with salad on the side.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT50M", "passive_time": "P1D", "total_time": "P1D0H50M", "overnight_required": true, "yields": "4 servings", "yield_count": 4, "serving_size_g": 320}', '{"flags": ["Dairy-Free", "Egg-Free", "Pescatarian", "Nut-Free", "Peanut-Free"], "not_suitable_for": ["Low-Sodium"]}', '{"per_serving": {"calories": 613.68, "protein_g": 44.85, "carbohydrates_g": 27.49, "fat_g": 37.05, "saturated_fat_g": 8.51, "trans_fat_g": null, "monounsaturated_fat_g": 4.73, "polyunsaturated_fat_g": 2.5, "fiber_g": 5.85, "sugar_g": 10.8, "sodium_mg": 4402.04, "cholesterol_mg": 173.25, "potassium_mg": 1134, "calcium_mg": 135.55, "iron_mg": 8.51, "magnesium_mg": 93.56, "phosphorus_mg": 545.74, "zinc_mg": 5.03, "vitamin_a_mcg": 99.51, "vitamin_c_mg": 23.82, "vitamin_d_mcg": 0.23, "vitamin_e_mg": 2.15, "vitamin_k_mcg": 65.22, "vitamin_b6_mg": 0.93, "vitamin_b12_mcg": 0.9, "thiamin_mg": 0.89, "riboflavin_mg": 1.11, "niacin_mg": 12.52, "folate_mcg": 77.66, "water_g": 308.82, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store duck and cucumbers separately. Cucumbers lose crunch after 24 hours.", "duration": "P3D"}, "freezer": {"notes": "Duck only. Freezing affects texture of cooked breast.", "duration": "P2M"}, "reheating": "Sear duck skin-side down briefly to warm; do not microwave.", "does_not_keep": false}', '[{"name": "Mortar and pestle", "required": true, "alternative": "Spice grinder or heavy skillet"}, {"name": "Large heavy-bottomed skillet", "required": true, "alternative": "Cast iron pan"}, {"name": "Wire rack set over baking sheet", "required": true, "alternative": null}, {"name": "Heavy chef''s knife or cleaver", "required": true, "alternative": null}, {"name": "Meat thermometer", "required": true, "alternative": null}]', '[{"symptom": "Duck skin is soggy or chewy", "likely_cause": "Pan was too hot initially (searing meat before fat rendered) or overcrowding", "prevention": "Start in a cold pan and use medium-low heat to allow gradual fat rendering", "fix": "Place skin-side up under a broiler for 1-2 minutes, watching closely to prevent burning spices"}, {"symptom": "Duck is too salty", "likely_cause": "Cure was not rinsed off thoroughly", "prevention": "Rinse under cold water for 30 seconds and pat completely dry", "fix": "Serve with unseasoned rice or increase the acidity in the cucumber salad to balance"}]', '["The ''smacking'' technique for cucumbers creates jagged edges that hold dressing far better than clean knife cuts.", "Do not discard the rendered duck fat from the pan; strain it and use it to roast potatoes or vegetables later.", "For the most authentic pastrami flavor, ensure the coriander and black pepper are cracked coarsely, not ground to a powder. You want texture.", "Resting the duck is critical. If sliced immediately, the juices will run out and the meat will be dry."]', '"This dish bridges the gap between the Jewish delicatessen and the Sichuan cold appetizer table. It treats the rich, fatty duck breast similarly to beef brisket, using the iconic coriander-pepper bark of pastrami, while the cooling smacked cucumbers and ginger oil provide the acidity and freshness typical of Chinese poultry dishes like ''Bai Zhan Ji'' (White Cut Chicken)."', 613.68);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('2df29d2c-b39c-4d67-8567-1fb44a2fb0d8', 'Marinated Summer Harvest Picnic Salad', 'A vibrant, crunchy textural delight featuring crisp haricots verts, sweet corn, and diced carrots. Tossed in a zesty cider-mustard vinaigrette, this sturdy salad resists wilting and develops a deeper, more cohesive flavor profile the longer it marinates.', 'salad', 'American', 'Easy', '["carrot", "corn", "green bean", "haricot vert", "picnic", "salad", "summer", "vegan", "vegetarian", "potluck", "make-ahead"]', '[{"group_name": "Vegetables", "items": [{"name": "fresh green beans (haricots verts)", "quantity": 400, "unit": "g", "preparation": "trimmed and cut into 2cm pieces", "notes": null, "substitutions": [], "ingredient_id": "8b7e6e4d-368f-454b-9f38-1d55c66b40e4", "nutrition_source": "USDA FoodData Central"}, {"name": "carrots", "quantity": 250, "unit": "g", "preparation": "peeled and diced (maize kernel size)", "notes": null, "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "corn kernels", "quantity": 300, "unit": "g", "preparation": "fresh or frozen", "notes": "approx. 2-3 cobs", "substitutions": [], "ingredient_id": "46ca2aab-cb23-4397-9711-528c234b2cf8", "nutrition_source": "USDA FoodData Central"}, {"name": "red onion", "quantity": 80, "unit": "g", "preparation": "finely minced", "notes": null, "substitutions": [], "ingredient_id": "1c270c6e-0acc-4c5c-9935-7eff3240fc4a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Vinaigrette", "items": [{"name": "apple cider vinegar", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "036c7254-3de5-4c6e-a2e7-366ad4d05077", "nutrition_source": "Aggregated Public Data"}, {"name": "dijon mustard", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "maple syrup", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c9ca1f35-b107-46c2-92a3-4c1c620f3c11", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "plus more for blanching water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh dill", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "4be2b047-475d-4c84-82d5-4883298c6121", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare an ice bath by filling a large bowl with cold water and ice cubes. Bring a large pot of heavily salted water to a rolling boil.", "structured": {"action": "PREPARE_BATH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["The water should taste like the sea to properly season the vegetables internally."]}, {"step_number": 2, "phase": "cook", "text": "Add the diced carrots to the boiling water. After 2 minutes, add the green beans. After another 2 minutes, add the corn kernels. Boil everything together for a final 1 minute (5 minutes total for carrots, 3 for beans, 1 for corn).", "structured": {"action": "BLANCH", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT5M", "doneness_cues": {"visual": "Vegetables are bright and vibrant", "tactile": "Tender-crisp, not mushy"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Immediately drain the vegetables in a colander and plunge them into the prepared ice bath to stop the cooking process. Let sit for 5 minutes until fully cold, then drain well and pat dry.", "structured": {"action": "SHOCK", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": ["Excess water will dilute the dressing, so ensure vegetables are thoroughly dried after the ice bath."]}, {"step_number": 4, "phase": "prep", "text": "In a large mixing bowl, whisk together the apple cider vinegar, olive oil, Dijon mustard, maple syrup, salt, pepper, and minced red onion.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Add the dried, blanched vegetables and chopped dill to the dressing. Toss thoroughly to coat.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Cover and refrigerate for at least 1 hour before serving to allow flavors to meld.", "structured": {"action": "MARINATE", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT1H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT1H", "total_time": "PT1H25M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 180}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 184.29, "protein_g": 3.58, "carbohydrates_g": 20.93, "fat_g": 11.05, "saturated_fat_g": 1.6, "trans_fat_g": null, "monounsaturated_fat_g": 0.24, "polyunsaturated_fat_g": 0.37, "fiber_g": 4.4, "sugar_g": 8.94, "sodium_mg": 393.69, "cholesterol_mg": null, "potassium_mg": 465.63, "calcium_mg": 54.29, "iron_mg": 1.37, "magnesium_mg": 42.51, "phosphorus_mg": 86.84, "zinc_mg": 0.53, "vitamin_a_mcg": 382.27, "vitamin_c_mg": 15.95, "vitamin_d_mcg": null, "vitamin_e_mg": 0.59, "vitamin_k_mcg": 34.86, "vitamin_b6_mg": 0.2, "vitamin_b12_mcg": null, "thiamin_mg": 0.16, "riboflavin_mg": 0.15, "niacin_mg": 1.81, "folate_mcg": 53.47, "water_g": 158.25, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor peaks after 24 hours. Stir well before serving.", "duration": "P4D"}, "freezer": {"notes": "Vegetables will lose crispness and become mushy upon thawing.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": "Salad spinner bowl"}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": "Fork and jar"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Vegetables are mushy", "likely_cause": "Overcooked during the blanching stage", "prevention": "Respect the staggered cooking times; carrots take longer than corn", "fix": "Cannot be fixed, but ensure salad is served very cold to maximize remaining crispness"}]', '["Uniformity is key to the aesthetic: try to cut the green beans and carrots to roughly the size of the corn kernels for a confetti-like appearance.", "If raw red onion is too pungent for your taste, soak the minced onion in the vinegar alone for 10 minutes before adding the oil; this pickles the onion slightly and removes the bite.", "This salad is practically indestructible and safe for outdoor picnics as it contains no mayonnaise or dairy."]', '"This dish is a modern evolution of the classic ''Three Bean Salad'' popular in American potlucks of the 1950s, refined with French blanching techniques (\u00e0 l''anglaise) to preserve the integrity of fresh market produce rather than using canned goods."', 184.29);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('2e7242f0-fe33-4abb-bcda-80e9f84511e0', 'Five-Spice Chicken & Bok Choy Stir-Fry', 'A vibrant, lean weeknight dinner featuring tender strips of chicken breast tossed in an aromatic five-spice and soy glaze, served alongside crisp-tender bok choy and a colorful medley of fresh vegetables.', 'dinner', 'Chinese-Fusion', 'Easy', '["asian", "bok choy", "chicken breast", "dinner", "easy", "weeknight", "low-fat", "stir-fry", "dairy-free"]', '[{"group_name": "Chicken & Marinade", "items": [{"name": "chicken breast", "quantity": 500, "unit": "g", "preparation": "sliced into thin strips against the grain", "notes": "boneless, skinless", "substitutions": [], "ingredient_id": "2b577d04-33ca-4919-938f-bfc8780a3a4b", "nutrition_source": "USDA FoodData Central"}, {"name": "soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": "low sodium preferred", "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "cornstarch", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "chinese five-spice powder", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "d1ea2b6c-ef58-4e15-b80d-9b3fc89c375f", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Vegetable Medley", "items": [{"name": "baby bok choy", "quantity": 300, "unit": "g", "preparation": "rinsed, ends trimmed, leaves separated", "notes": null, "substitutions": [], "ingredient_id": "562bdece-f897-4d03-be7a-94be5ef3f681", "nutrition_source": "Aggregated Public Data"}, {"name": "red bell pepper", "quantity": 150, "unit": "g", "preparation": "sliced into strips", "notes": "approx. 1 medium pepper", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "USDA FoodData Central"}, {"name": "carrot", "quantity": 100, "unit": "g", "preparation": "julienned or thinly sliced", "notes": null, "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "ginger", "quantity": 10, "unit": "g", "preparation": "minced or grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "minced", "notes": "cloves, approx. 12g total", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "divided use", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Stir-Fry Sauce", "items": [{"name": "chicken stock", "quantity": 60, "unit": "ml", "preparation": null, "notes": "or water", "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}, {"name": "soy sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "rice vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fcbf5252-1be9-4dd4-8c22-4fda1dbdca28", "nutrition_source": "Aggregated Public Data"}, {"name": "sesame oil", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a9a59164-d949-4acd-99da-689f0a32e2e7", "nutrition_source": "Aggregated Public Data"}, {"name": "cornstarch", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a bowl, toss the sliced chicken breast with 15ml soy sauce, 5g cornstarch, and the five-spice powder. Let it sit while preparing the vegetables.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Whisk together the sauce ingredients: chicken stock, 30ml soy sauce, rice vinegar, sesame oil, and 4g cornstarch in a small bowl until smooth.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat half the vegetable oil in a wok or large skillet over high heat. Add the chicken in a single layer (do this in batches if necessary to avoid crowding) and sear until golden and cooked through, reaching an internal temp of 74\u00b0C/165\u00b0F.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT5M", "doneness_cues": {"visual": "Golden brown edges", "tactile": "Firm to the touch"}}, "tips": ["Do not stir immediately; let the chicken develop a crust first.", "Ensure raw chicken does not touch cooked vegetables or ready-to-eat surfaces."]}, {"step_number": 4, "phase": "cook", "text": "Remove chicken from the pan and set aside. Wipe the pan if needed, add the remaining oil, and saut\u00e9 the ginger and garlic for 30 seconds until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the carrots and bell peppers. Stir-fry for 2-3 minutes. Then add the bok choy stems (if separated) or whole leaves, tossing for another 1-2 minutes until vibrant green and slightly wilted.", "structured": {"action": "STIR_FRY", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Vegetables are bright and glossy", "tactile": "Crisp-tender texture"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Return the chicken to the pan. Stir the sauce mixture once more to re-suspend the starch, then pour it over the chicken and vegetables. Toss everything together for 1 minute until the sauce thickens and coats the ingredients.", "structured": {"action": "GLAZE", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from heat immediately to prevent vegetables from becoming soggy. Serve hot.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT15M", "total_time": "PT40M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 320}', '{"flags": ["Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Low-Fat"], "not_suitable_for": ["Soy allergy sufferers", "Gluten sensitivity (unless Tamari is used)"]}', '{"per_serving": {"calories": 317.86, "protein_g": 28.37, "carbohydrates_g": 12.4, "fat_g": 17.2, "saturated_fat_g": 3.91, "trans_fat_g": 0.13, "monounsaturated_fat_g": 4.79, "polyunsaturated_fat_g": 2.55, "fiber_g": 2.96, "sugar_g": 5.7, "sodium_mg": 2465.63, "cholesterol_mg": 80, "potassium_mg": 656.6, "calcium_mg": 101.16, "iron_mg": 2.11, "magnesium_mg": 40.64, "phosphorus_mg": 241.73, "zinc_mg": 1.2, "vitamin_a_mcg": 403.75, "vitamin_c_mg": 74.91, "vitamin_d_mcg": 0.5, "vitamin_e_mg": 1.11, "vitamin_k_mcg": 5.19, "vitamin_b6_mg": 0.85, "vitamin_b12_mcg": 0.43, "thiamin_mg": 0.12, "riboflavin_mg": 0.17, "niacin_mg": 13.04, "folate_mcg": 27.37, "water_g": 147.44, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Reheat gently to avoid overcooking the chicken.", "duration": "P3D"}, "freezer": {"notes": "Vegetables may lose crunch upon thawing.", "duration": "P2M"}, "reheating": "Microwave on medium power or stir-fry quickly in a hot pan with a splash of water.", "does_not_keep": false}', '[{"name": "Wok or large skillet", "required": true, "alternative": "Deep saut\u00e9 pan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Tongs or spatula", "required": true, "alternative": null}]', '[{"symptom": "Vegetables are soggy and watery", "likely_cause": "Pan was not hot enough or was overcrowded, causing vegetables to steam instead of fry", "prevention": "Cook in batches or use a larger burner; ensure pan is smoking hot before adding veg", "fix": "Remove solids with a slotted spoon and boil the liquid down separately until thick, then recombine"}, {"symptom": "Chicken is dry or tough", "likely_cause": "Overcooked lean breast meat", "prevention": "Slice chicken evenly and remove from heat exactly when it hits 74\u00b0C/165\u00b0F; the ''velveting'' with cornstarch helps protect it", "fix": "Cannot be fixed, but adding a little extra sauce can mask the texture"}]', '["Slicing the chicken against the grain is crucial for tenderness; it shortens the muscle fibers.", "The cornstarch in the marinade creates a technique called ''velveting'', which keeps the chicken breast juicy even over high heat.", "Prep everything before you turn on the heat. Stir-frying happens fast, and you won''t have time to chop while cooking.", "If using larger bok choy, separate the thick white stems from the green leaves. Add the stems with the carrots, and the leaves at the very end."]', '"This dish utilizes the classic Chinese stir-fry technique ''chao'' (\u7092) and incorporates Five-Spice powder (wuxiang fen), a pillar of Chinese cuisine representing the five elements. While traditional versions might use fattier cuts like thigh or pork belly, this adaptation highlights the modern preference for lean proteins while retaining the bold, warming aromatic profile."', 317.86);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('2ee99d37-2efc-451d-8239-bf7e79700a06', 'Crispy Salt and Pepper Panko Squid', 'Tender squid rings encased in a shattering, golden panko crust heavily seasoned with toasted Sichuan peppercorns and sea salt. Paired with a fiery Thai-style green chili dip (Nam Jim) and a cooling cucumber-coriander salad to cut through the richness.', 'appetizer', 'Asian Fusion', 'Intermediate', '["squid", "seafood", "appetizer", "fried", "spicy", "asian", "party-food"]', '[{"group_name": "Squid & Marinade", "items": [{"name": "squid tubes", "quantity": 500, "unit": "g", "preparation": "cleaned and skin removed", "notes": "Score the inside in a diamond pattern", "substitutions": [], "ingredient_id": "e126ab3d-72fc-463a-a50c-461c65ccdf4d", "nutrition_source": "USDA FoodData Central"}, {"name": "shaoxing wine", "quantity": 15, "unit": "ml", "preparation": null, "notes": "or dry sherry", "substitutions": [], "ingredient_id": "c5b0a9e5-3d44-46bf-ae83-8682fcc6ce99", "nutrition_source": "Aggregated Public Data"}, {"name": "soy sauce", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "white pepper powder", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Salt & Pepper Breading", "items": [{"name": "panko breadcrumbs", "quantity": 120, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84fbc204-4457-40ed-83c1-3e5a7bcd8f23", "nutrition_source": "Aggregated Public Data"}, {"name": "sichuan peppercorns", "quantity": 8, "unit": "g", "preparation": "toasted and ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt flakes", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 5, "unit": "g", "preparation": "coarsely ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "beaten", "notes": "approx 100g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable oil", "quantity": 1000, "unit": "ml", "preparation": null, "notes": "for deep frying", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}]}, {"group_name": "Spicy Chilli Dip (Nam Jim Seafood Style)", "items": [{"name": "green bird''s eye chilies", "quantity": 6, "unit": null, "preparation": null, "notes": "approx 10g, adjust to taste", "substitutions": [], "ingredient_id": "e40b2f32-1599-4b72-a829-b858329933e8", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": null, "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "coriander roots", "quantity": 2, "unit": null, "preparation": "washed and chopped", "notes": "approx 5g", "substitutions": [], "ingredient_id": "8c7693be-b538-445c-80f9-3d5bf4c6dcc0", "nutrition_source": "USDA FoodData Central"}, {"name": "fish sauce", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "95a9a747-50ee-4be0-84be-0dfc96111e2a", "nutrition_source": "Aggregated Public Data"}, {"name": "lime juice", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "palm sugar", "quantity": 20, "unit": "g", "preparation": null, "notes": "or brown sugar", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Refreshing Coriander Salad", "items": [{"name": "fresh coriander leaves", "quantity": 40, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8c7693be-b538-445c-80f9-3d5bf4c6dcc0", "nutrition_source": "Aggregated Public Data"}, {"name": "cucumber", "quantity": 150, "unit": "g", "preparation": "julienned, seeds removed", "notes": null, "substitutions": [], "ingredient_id": "84cc106c-269c-44b7-af59-33b3c121e483", "nutrition_source": "USDA FoodData Central"}, {"name": "red shallot", "quantity": 30, "unit": "g", "preparation": "thinly sliced", "notes": null, "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "rice vinegar", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fcbf5252-1be9-4dd4-8c22-4fda1dbdca28", "nutrition_source": "Aggregated Public Data"}, {"name": "sesame oil", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a9a59164-d949-4acd-99da-689f0a32e2e7", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the squid: Open the tubes flat. Use a knife to lightly score the inside flesh in a criss-cross diamond pattern (do not cut all the way through). Slice into 3cm x 5cm rectangular bite-sized pieces.", "structured": {"action": "SCORE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Combine squid pieces with Shaoxing wine, soy sauce, and white pepper. Toss to coat and let marinate for 15 minutes.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Make the dipping sauce: In a mortar and pestle, pound the coriander roots, garlic, and chilies into a rough paste. Mix in the palm sugar, fish sauce, and lime juice until sugar dissolves. Set aside.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Prepare the salad: In a bowl, toss the julienned cucumber, coriander leaves, and sliced shallots with rice vinegar and sesame oil. Keep chilled.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Set up a breading station: Place cornstarch in one bowl. In a second bowl, whisk the eggs. In a third bowl, mix panko breadcrumbs with ground Sichuan pepper, black pepper, and sea salt flakes.", "structured": {"action": "MEASURE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Heat vegetable oil in a Dutch oven to 180\u00b0C/350\u00b0F. While oil heats, dredge squid pieces in cornstarch (shake off excess), dip in egg, then press firmly into the seasoned panko mixture.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Fry squid in small batches for 2-3 minutes until golden brown and curled. Internal temperature should reach 63\u00b0C/145\u00b0F, but visual cues of golden crust are most reliable here.", "structured": {"action": "FRY", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown crust", "tactile": "Crisp exterior"}}, "tips": ["Do not overcrowd the pot or the oil temperature will drop, making the squid greasy."]}, {"step_number": 8, "phase": "finish", "text": "Transfer fried squid to a wire rack to drain. Serve immediately with the spicy dip and coriander salad.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT15M", "total_time": "PT50M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 220}', '{"flags": ["Pescatarian", "Dairy-Free", "Nut-Free"], "not_suitable_for": ["Shellfish allergy sufferers (cross-reactivity)", "Gluten intolerance (unless GF panko used)"]}', '{"per_serving": {"calories": 390.31, "protein_g": 28.49, "carbohydrates_g": 55.03, "fat_g": 6.06, "saturated_fat_g": 1.32, "trans_fat_g": 0.01, "monounsaturated_fat_g": 1.09, "polyunsaturated_fat_g": 1.19, "fiber_g": 3.18, "sugar_g": 9.94, "sodium_mg": 2051.78, "cholesterol_mg": 384.25, "potassium_mg": 586.93, "calcium_mg": 97.57, "iron_mg": 3.91, "magnesium_mg": 74.47, "phosphorus_mg": 360.8, "zinc_mg": 2.52, "vitamin_a_mcg": 817.27, "vitamin_c_mg": 18.01, "vitamin_d_mcg": 0.5, "vitamin_e_mg": 1.84, "vitamin_k_mcg": 8.3, "vitamin_b6_mg": 0.22, "vitamin_b12_mcg": 1.85, "thiamin_mg": 0.07, "riboflavin_mg": 0.65, "niacin_mg": 2.85, "folate_mcg": 27.64, "water_g": 186.71, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Fried squid loses texture immediately; dip keeps for 3 days.", "duration": null}, "freezer": {"notes": "Not recommended.", "duration": null}, "reheating": "Re-fry at 190\u00b0C/375\u00b0F for 1 minute to restore crunch, though fresh is best.", "does_not_keep": true}', '[{"name": "Heavy-bottomed pot or Dutch oven", "required": true, "alternative": "Deep fryer"}, {"name": "Spider strainer", "required": true, "alternative": "Slotted spoon"}, {"name": "Mortar and pestle", "required": true, "alternative": "Small food processor"}, {"name": "Thermometer", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}]', '[{"symptom": "Squid is tough and rubbery", "likely_cause": "Overcooked or squid was not scored properly", "prevention": "Fry for no longer than 3 minutes; ensure diamond scoring cuts through the tough membrane", "fix": "Cut into smaller pieces to mask the texture; cannot be reversed"}, {"symptom": "Breading falls off during frying", "likely_cause": "Squid was too wet before dredging or oil was too cold", "prevention": "Pat squid dry before the cornstarch step; ensure oil maintains 180\u00b0C/350\u00b0F", "fix": "None"}]', '["Scoring the squid (cutting a diamond pattern) is crucial not just for presentation, but to tenderize the muscle fibers and help the breading adhere.", "For the most aromatic experience, toast whole Sichuan peppercorns in a dry pan until fragrant before grinding them for the breading mix.", "If you cannot find coriander roots for the dip, use the stems\u2014they hold more flavor than the leaves.", "Serve immediately. Squid has a very short window of perfection before it becomes chewy and the breading softens."]', '"This dish bridges the gap between Cantonese ''Jiu Yim Sin Yau'' (Salt and Pepper Squid) and Western-style breaded appetizers. While traditional recipes use a light starch dusting, this version uses Panko for a distinct crunch, paired with a Thai-inspired Nam Jim Seafood sauce that reflects the bold, acid-forward flavors favored in Southeast Asian seafood cuisine."', 390.31);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('2f11a20d-95ab-437b-a87c-643824a1c571', 'Lamb Tagine with Seckel Pears and Saffron', 'Tender chunks of lamb shoulder slow-braised in a fragrant sauce of turmeric, ginger, and saffron. Whole Seckel pears are poached directly in the stew, adding a honeyed sweetness that balances the savory, warming spices.', 'main course', 'Moroccan', 'Intermediate', '["moroccan", "lamb", "pear", "dinner", "main course", "stew", "slow cooker"]', '[{"group_name": "Lamb and Aromatics", "items": [{"name": "boneless lamb shoulder", "quantity": 1000, "unit": "g", "preparation": "cut into 4cm cubes", "notes": "Leg can be used but shoulder yields better texture", "substitutions": [], "ingredient_id": "27672021-dc31-45a5-9ce8-f08dbbae93b4", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onions", "quantity": 2, "unit": null, "preparation": "finely diced", "notes": "approx 300g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "minced", "notes": "approx 20g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 15, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Spice Blend", "items": [{"name": "ground turmeric", "quantity": 1, "unit": null, "preparation": "teaspoon", "notes": "approx 3g", "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 1, "unit": null, "preparation": "teaspoon", "notes": "approx 3g", "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "ground coriander", "quantity": 1, "unit": null, "preparation": "teaspoon", "notes": "approx 2g", "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "sweet paprika", "quantity": 1, "unit": null, "preparation": "teaspoon", "notes": "approx 3g", "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "cinnamon stick", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 5g", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "saffron threads", "quantity": 1, "unit": null, "preparation": null, "notes": "generous pinch, soaked in 15ml warm water", "substitutions": [], "ingredient_id": "7f9ec0c8-2db1-48ac-a2c9-9b1efce12cf3", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 10, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Liquids and Fruit", "items": [{"name": "lamb or chicken stock", "quantity": 500, "unit": "ml", "preparation": null, "notes": "low sodium preferred", "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}, {"name": "seckel pears", "quantity": 6, "unit": null, "preparation": null, "notes": "firm, approx 450g total", "substitutions": [], "ingredient_id": "ed5dd928-efa8-4c10-aeb3-3c08c94c62f8", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish", "items": [{"name": "blanched almonds", "quantity": 30, "unit": "g", "preparation": "toasted", "notes": null, "substitutions": [], "ingredient_id": "859f0247-6cc6-47f4-b38e-d2696789442f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 10, "unit": "g", "preparation": "roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the lamb cubes dry with paper towels and season generously with the salt and black pepper.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat the olive oil in the tagine base or Dutch oven over medium-high heat. Sear the lamb in batches until browned on all sides, then remove to a plate.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": {"visual": "Deep golden brown crust", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to medium. Add the onions to the pot and saut\u00e9 until softened and translucent, about 5-8 minutes.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Translucent and soft", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Stir in the garlic, grated ginger, turmeric, cumin, coriander, and paprika. Toast the spices for 1 minute until fragrant, being careful not to burn them.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Spices darken slightly", "tactile": "Very aromatic"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Return the lamb and its juices to the pot. Add the cinnamon stick, saffron (with its soaking water), and stock. Bring to a boil, then reduce heat to low, cover, and simmer for 1.5 hours.", "structured": {"action": "BRAISE", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT1H30M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "While the lamb simmers, peel the Seckel pears, leaving the stems intact for presentation. You may core them from the bottom if desired, but leaving them whole helps them hold their shape.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "After the lamb has cooked for 1.5 hours, uncover the pot. Stir in the honey, then nestle the peeled pears into the liquid. Cover and continue to simmer for another 20-30 minutes until pears are tender.", "structured": {"action": "STEW", "temperature": null, "duration": "PT30M", "doneness_cues": {"visual": null, "tactile": "Pears easily pierced with knife, lamb fork-tender"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Check the sauce consistency. If too thin, remove the pears and meat carefully and boil the liquid to reduce until it coats the back of a spoon. Discard the cinnamon stick.", "structured": {"action": "REDUCE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Sauce is glossy and thickened", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Return meat and pears to the sauce if separated. Garnish with toasted almonds and fresh cilantro. Serve hot.", "structured": {"action": "SERVE", "temperature": {"celsius": 70, "fahrenheit": 158}, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT2H", "total_time": "PT2H35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Dairy-Free", "Gluten-Free", "Egg-Free", "Soy-Free", "Paleo"], "not_suitable_for": ["Infants under 12 months (honey)"]}', '{"per_serving": {"calories": 659.49, "protein_g": 54.51, "carbohydrates_g": 38.28, "fat_g": 33.73, "saturated_fat_g": 6.21, "trans_fat_g": null, "monounsaturated_fat_g": 8.28, "polyunsaturated_fat_g": 1.96, "fiber_g": 7.29, "sugar_g": 20.94, "sodium_mg": 6031.05, "cholesterol_mg": null, "potassium_mg": 608.9, "calcium_mg": 84.21, "iron_mg": 3.36, "magnesium_mg": 60.24, "phosphorus_mg": 217.84, "zinc_mg": 4.21, "vitamin_a_mcg": 71.01, "vitamin_c_mg": 12.5, "vitamin_d_mcg": null, "vitamin_e_mg": 3.34, "vitamin_k_mcg": 11.81, "vitamin_b6_mg": 0.23, "vitamin_b12_mcg": null, "thiamin_mg": 0.08, "riboflavin_mg": 0.13, "niacin_mg": 0.76, "folate_mcg": 27.38, "water_g": 169.34, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors improve significantly after 24 hours.", "duration": "P3D"}, "freezer": {"notes": "Freeze without the pears if possible, as their texture may degrade upon thawing.", "duration": "P3M"}, "reheating": "Reheat gently on the stove over low heat, adding a splash of water if the sauce has thickened too much.", "does_not_keep": false}', '[{"name": "Tagine or Dutch Oven", "required": true, "alternative": "Heavy-bottomed pot with tight lid"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Vegetable peeler", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": null}]', '[{"symptom": "Sauce is too watery", "likely_cause": "Modern Dutch ovens trap moisture more efficiently than clay tagines, preventing reduction", "prevention": "Use slightly less stock initially", "fix": "Remove solids and boil sauce vigorously for 5-10 minutes to reduce"}, {"symptom": "Pears are falling apart", "likely_cause": "Added too early or heat was too high", "prevention": "Add pears only in the last 20-30 minutes of cooking", "fix": "Remove immediately and serve as a compote on the side"}]', '["Seckel pears are ideal because of their small size and firm texture. If unavailable, use firm Bosc pears, peeled, cored, and quartered.", "Browning the lamb thoroughly in step 2 is critical for developing the rich base flavor of the sauce (Maillard reaction).", "If using a traditional clay tagine, a heat diffuser is necessary on electric or gas stovetops to prevent the clay from cracking.", "This dish is best served with couscous or warm crusty bread to soak up the sauce."]', '"Tagine refers to both the conical earthenware pot and the stew cooked within it. This recipe balances ''hlu'' (sweet) and ''maleh'' (savory), a signature profile of Moroccan cuisine often reserved for celebrations and guests."', 659.49);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('2f5e8f08-ead5-43fd-9386-1e1148539267', 'Crispy Sweet and Sour Tofu', 'Golden, pan-fried tofu cubes tossed with crisp bell peppers and juicy pineapple chunks in a vibrant, glossy sauce. This dish balances tangy acidity with sweetness, offering a satisfying crunch and tender interior perfect for a quick weeknight dinner.', 'dinner', 'Chinese', 'Intermediate', '["tofu", "sweet and sour", "main course", "vegetables", "weeknight dinner", "vegan", "stir fry"]', '[{"group_name": "Tofu", "items": [{"name": "extra firm tofu", "quantity": 400, "unit": "g", "preparation": "pressed and cubed", "notes": "1 standard block", "substitutions": [], "ingredient_id": "c4eda7fb-2427-41ae-a450-5ba5546eb700", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 30, "unit": "g", "preparation": null, "notes": "for coating", "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": "for frying (canola or vegetable)", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables & Aromatics", "items": [{"name": "red bell pepper", "quantity": 150, "unit": "g", "preparation": "cut into chunks", "notes": null, "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "USDA FoodData Central"}, {"name": "green bell pepper", "quantity": 150, "unit": "g", "preparation": "cut into chunks", "notes": null, "substitutions": [], "ingredient_id": "627afa21-0392-4082-ab38-0f20446e190e", "nutrition_source": "Aggregated Public Data"}, {"name": "onion", "quantity": 100, "unit": "g", "preparation": "cut into petals/chunks", "notes": "1 medium onion", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "pineapple chunks", "quantity": 120, "unit": "g", "preparation": "fresh or canned", "notes": "drain if canned", "substitutions": [], "ingredient_id": "37da68de-6b6e-4619-9f28-52da1f26f4ce", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "cloves, approx 8g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "ginger", "quantity": 10, "unit": "g", "preparation": "minced", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sweet and Sour Sauce", "items": [{"name": "ketchup", "quantity": 60, "unit": "g", "preparation": null, "notes": "provides base color and tang", "substitutions": [], "ingredient_id": "9b0c1201-83fa-43c7-b2a4-66c400bcb0fd", "nutrition_source": "Aggregated Public Data"}, {"name": "rice vinegar", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fcbf5252-1be9-4dd4-8c22-4fda1dbdca28", "nutrition_source": "Aggregated Public Data"}, {"name": "light soy sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "aa4acdfc-3328-4c11-a5b2-15f9b03dff0b", "nutrition_source": "Aggregated Public Data"}, {"name": "sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": "white or brown sugar", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 60, "unit": "ml", "preparation": null, "notes": "or pineapple juice for extra fruitiness", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "cornstarch", "quantity": 5, "unit": "g", "preparation": null, "notes": "mixed with 15ml water for slurry", "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Press the tofu for at least 20 minutes to remove excess moisture. This is crucial for crispiness. Once pressed, cut into 2.5cm (1 inch) cubes.", "structured": {"action": "DRAIN", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a small bowl, whisk together ketchup, rice vinegar, soy sauce, sugar, and water/pineapple juice until the sugar dissolves. Set aside.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Toss the tofu cubes with salt and cornstarch in a mixing bowl until thoroughly and evenly coated. The cornstarch should form a dry layer on the outside.", "structured": {"action": "DREDGE", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Tofu is matte white and dry on surface", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Heat oil in a large skillet or wok over medium-high heat (approx 190\u00b0C/375\u00b0F). Add tofu cubes in a single layer, ensuring they don''t touch.", "structured": {"action": "FRY", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Fry the tofu for 2-3 minutes per side until golden brown and crispy. Remove from pan and set aside on a wire rack or paper towel.", "structured": {"action": "FRY", "temperature": null, "duration": "PT6M", "doneness_cues": {"visual": "Golden brown crust", "tactile": "Crispy exterior"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Wipe out excess oil, leaving about 15ml (1 tbsp) in the pan. Saut\u00e9 the minced garlic and ginger for 30 seconds until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Add the onion and bell peppers. Stir-fry for 2-3 minutes until the vegetables are bright and slightly tender but still crisp.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Pour in the sauce mixture and bring to a simmer. Stir in the cornstarch slurry (5g starch + 15ml water) and cook until the sauce thickens and turns glossy.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Sauce coats the back of a spoon", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Add the fried tofu and pineapple chunks back into the pan. Toss quickly to coat everything in the glaze and serve immediately.", "structured": {"action": "TOSS", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": ["Do not cook too long after adding tofu, or the crust will become soggy."]}]', '{"active_time": "PT25M", "passive_time": "PT20M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 280}', '{"flags": ["Vegetarian", "Vegan", "Dairy-Free", "Egg-Free", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 387.24, "protein_g": 19.78, "carbohydrates_g": 38.34, "fat_g": 20.32, "saturated_fat_g": 2.95, "trans_fat_g": null, "monounsaturated_fat_g": 1.94, "polyunsaturated_fat_g": 5.01, "fiber_g": 5.3, "sugar_g": 20.17, "sodium_mg": 809.4, "cholesterol_mg": null, "potassium_mg": 503.86, "calcium_mg": 704.8, "iron_mg": 3.4, "magnesium_mg": 79.97, "phosphorus_mg": 231.7, "zinc_mg": 1.89, "vitamin_a_mcg": 86.37, "vitamin_c_mg": 137.09, "vitamin_d_mcg": null, "vitamin_e_mg": 0.61, "vitamin_k_mcg": 2.19, "vitamin_b6_mg": 0.29, "vitamin_b12_mcg": null, "thiamin_mg": 0.22, "riboflavin_mg": 0.16, "niacin_mg": 0.96, "folate_mcg": 56.74, "water_g": 171.33, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Tofu will lose crispness; reheat in a pan or air fryer to restore texture.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; tofu texture changes significantly upon freezing.", "duration": null}, "reheating": "Reheat in a skillet over medium heat for 5-7 minutes or air fry at 180\u00b0C/350\u00b0F for 5 minutes.", "does_not_keep": false}', '[{"name": "Large skillet or wok", "required": true, "alternative": null}, {"name": "Tofu press", "required": false, "alternative": "Heavy plate and cans"}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Tofu is soggy, not crispy", "likely_cause": "Tofu wasn''t pressed enough or oil wasn''t hot enough", "prevention": "Press tofu for full 20 minutes and ensure oil shimmers before adding tofu", "fix": "Cannot be fixed once sauced; next time use more heat and space out tofu"}, {"symptom": "Sauce is too runny", "likely_cause": "Cornstarch slurry was insufficient or sauce didn''t boil", "prevention": "Allow sauce to bubble after adding slurry", "fix": "Mix another 2g cornstarch with 5ml water and add slowly while simmering"}]', '["Using pineapple juice instead of water in the sauce adds depth and natural sweetness.", "For the crispiest tofu, toss the cubes in cornstarch immediately before frying. If they sit too long, the moisture will absorb the starch and it won''t crisp up as well.", "Cut vegetables into similar sizes as the tofu cubes for uniform cooking and eating experience.", "If you want extra heat, add a pinch of dried chili flakes or a teaspoon of sriracha to the sauce."]', '"Sweet and Sour (Tangcu) is a classic Chinese flavor profile originating from Jiangsu province, traditionally used with pork ribs. This vegetarian adaptation utilizes the absorbent nature of tofu to hold the bold, vinegary glaze, making it a staple in modern Chinese-American home cooking."', 387.24);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('2f856299-721c-4807-b197-c8405158a60e', 'Baked Eggs with Tuna Pomodoro and Whipped Garlic Ricotta', 'A rustic, protein-rich Italian dish featuring eggs gently baked in a savory sauce of tomatoes, olive-oil-packed tuna, and aromatics. Finished with cool dollops of garlicky whipped ricotta for a striking contrast of temperatures and textures.', 'main course', 'Italian', 'Easy', '["baked eggs", "italian", "main course", "tuna", "ricotta", "brunch", "easy dinner"]', '[{"group_name": "Garlic Ricotta", "items": [{"name": "whole milk ricotta", "quantity": 120, "unit": "g", "preparation": "chilled", "notes": null, "substitutions": [], "ingredient_id": "7a68dbea-ec03-42ae-b0eb-983bf3d4c7b6", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "grated or pressed", "notes": "approx 3g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": null, "unit": null, "preparation": "freshly grated", "notes": "from half a lemon", "substitutions": [], "ingredient_id": "a5fb6a2a-dcda-4ab2-8fe6-472d7fcc39d1", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Tomato Tuna Base", "items": [{"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "thinly sliced", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "red chili flakes", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "canned tuna in olive oil", "quantity": 160, "unit": "g", "preparation": "drained", "notes": "solid pack preferred", "substitutions": [], "ingredient_id": "cf38e1f7-29ee-435e-b96b-f63164087af6", "nutrition_source": "USDA FoodData Central"}, {"name": "crushed tomatoes", "quantity": 400, "unit": "g", "preparation": "canned", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "dried oregano", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "To Finish", "items": [{"name": "large eggs", "quantity": 4, "unit": null, "preparation": null, "notes": "approx 200g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh parsley", "quantity": 5, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 200\u00b0C/400\u00b0F. Ensure the rack is in the center position.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a small bowl, whisk the ricotta, grated garlic, lemon zest (if using), 5ml olive oil, and sea salt until smooth and creamy. Refrigerate until serving.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Smooth, aerated texture", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat 15ml olive oil in an oven-safe skillet over medium heat. Saut\u00e9 the diced onion until softened and translucent.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT5M", "doneness_cues": {"visual": "Onions are translucent but not browned", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the sliced garlic and red chili flakes. Cook for 1 minute until fragrant, being careful not to burn the garlic.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Stir in the drained tuna, breaking up large chunks gently. Add the crushed tomatoes and dried oregano. Bring to a simmer and let cook for 5 minutes to thicken slightly.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT5M", "doneness_cues": {"visual": "Sauce has thickened enough to hold a depression", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Remove skillet from heat. Use the back of a spoon to make four indentations in the sauce. Crack one egg into each indentation.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Transfer the skillet to the preheated oven. Bake until the egg whites are set but the yolks are still runny. Monitor closely.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT8M", "doneness_cues": {"visual": "Whites opaque, yolks jiggle slightly when pan is shaken", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from oven. Immediately dollop the cold garlic ricotta over the hot sauce (avoiding the yolks). Garnish with fresh parsley and black pepper. Serve immediately.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT15M", "total_time": "PT30M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 380}', '{"flags": ["Pescatarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Low-Carb"], "not_suitable_for": ["Fish allergy", "Egg allergy", "Dairy allergy"]}', '{"per_serving": {"calories": 560.6, "protein_g": 43.64, "carbohydrates_g": 23.18, "fat_g": 32.93, "saturated_fat_g": 9.73, "trans_fat_g": 0.24, "monounsaturated_fat_g": 14.97, "polyunsaturated_fat_g": 5.68, "fiber_g": 6.06, "sugar_g": 11.73, "sodium_mg": 779.28, "cholesterol_mg": 415.8, "potassium_mg": 1090.89, "calcium_mg": 261.92, "iron_mg": 4.53, "magnesium_mg": 85.88, "phosphorus_mg": 622.67, "zinc_mg": 2.96, "vitamin_a_mcg": 276.74, "vitamin_c_mg": 39, "vitamin_d_mcg": 7.48, "vitamin_e_mg": 3.86, "vitamin_k_mcg": 91.66, "vitamin_b6_mg": 0.5, "vitamin_b12_mcg": 3.16, "thiamin_mg": 0.13, "riboflavin_mg": 0.79, "niacin_mg": 10.4, "folate_mcg": 74.45, "water_g": 241.01, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten fresh; yolks will harden upon reheating.", "duration": "P1D"}, "freezer": {"notes": "Do not freeze.", "duration": null}, "reheating": "Reheat gently in a covered skillet on low heat, though texture will change.", "does_not_keep": false}', '[{"name": "Oven-safe skillet (25cm)", "required": true, "alternative": "Standard skillet plus baking dish"}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": "Fork"}, {"name": "Knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Egg yolks are hard/chalky", "likely_cause": "Overcooked due to residual heat in the cast iron skillet", "prevention": "Remove the skillet from the oven when the whites are just barely set; they will continue to cook on the counter.", "fix": "Cannot be fixed, but sauce will still be delicious."}, {"symptom": "Sauce is too watery", "likely_cause": "Tomatoes were not reduced enough before adding eggs", "prevention": "Simmer sauce longer before cracking eggs; ensure tuna is well-drained.", "fix": "Serve with extra bread to soak up liquid."}]', '["Use tuna packed in olive oil (Tonno all''olio di oliva) rather than water; the fat carries the flavor and prevents the fish from becoming dry during baking.", "The contrast between the piping hot, acidic tomato sauce and the cold, creamy ricotta is essential to this dish. Do not add the ricotta before baking.", "Serve with toasted ciabatta or sourdough to ''fare la scarpetta'' (make the little shoe)\u2014the Italian act of mopping up sauce with bread.", "If you do not have an oven-safe skillet, you can transfer the sauce to a ceramic baking dish before cracking the eggs.", "For perfectly even cooking, ensure your eggs are at room temperature before cracking them into the hot sauce."]', '"This dish is a pescatarian riff on ''Uova al Purgatorio'' (Eggs in Purgatory), a Neapolitan classic. The addition of tuna transforms it into a robust main course, reflecting the ''cucina povera'' tradition of using pantry staples like canned fish and tomatoes to create nutritious, satisfying meals."', 560.6);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('2feae634-6a29-437c-8045-56e781e0ea5b', 'Lemon & Pine Nut Cornmeal Cookies', 'Golden, tender cookies with a delicate crumb somewhere between a buttery shortbread and a soft madeleine. The fine cornmeal adds a pleasing sunny hue and subtle texture, while lemon zest and toasted pine nuts provide a sophisticated, aromatic finish perfect for tea time.', 'dessert', 'Italian', 'Intermediate', '["butter", "cookie", "cornmeal", "lemon", "pine nut", "dessert", "tea time", "italian inspired"]', '[{"group_name": "Wet Ingredients", "items": [{"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "room temperature", "notes": "softened", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": "finely grated", "notes": "approx 6g", "substitutions": [], "ingredient_id": "03fb65be-9b62-44e7-a121-694de64cdec0", "nutrition_source": "Aggregated Public Data"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": "room temperature", "notes": "large, approx 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dry Ingredients & Mix-ins", "items": [{"name": "all-purpose flour", "quantity": 140, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "fine yellow cornmeal", "quantity": 65, "unit": "g", "preparation": null, "notes": "must be fine grind, not coarse polenta", "substitutions": [], "ingredient_id": "7fb6be00-5ba2-483a-af74-961f21de4055", "nutrition_source": "Aggregated Public Data"}, {"name": "baking powder", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "pine nuts", "quantity": 40, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "971298ad-a9d7-49f7-811b-46afedad18d4", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the pine nuts in a small dry skillet over medium-low heat. Toast, shaking the pan frequently, until fragrant and lightly golden (approx 3-4 minutes). Remove immediately to a cool plate to stop cooking.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Lightly golden brown", "tactile": "Fragrant"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a medium bowl, whisk together the flour, fine cornmeal, baking powder, and salt. Stir in the cooled pine nuts.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In the bowl of a stand mixer fitted with the paddle attachment, combine the softened butter, sugar, and lemon zest. Beat on medium-high speed until pale and fluffy, about 3-4 minutes. This aeration creates the madeleine-like texture.", "structured": {"action": "CREAM", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Pale yellow and increased volume", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Add the egg and vanilla extract to the butter mixture. Beat on medium speed until fully incorporated and smooth, scraping down the sides of the bowl as needed.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Reduce mixer speed to low. Add the dry ingredient mixture in two batches, mixing only until just combined and no streaks of flour remain. Do not overmix.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Uniform dough with no dry flour", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "Cover the bowl with plastic wrap and refrigerate the dough for at least 1 hour. This hydrates the cornmeal and ensures the cookies hold their shape.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Preheat the oven to 175\u00b0C (350\u00b0F). Line two baking sheets with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Scoop the chilled dough into tablespoon-sized mounds (approx 20g each) and roll into balls. Place on prepared baking sheets spaced 5cm (2 inches) apart. Flatten slightly with the palm of your hand.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Bake for 10-12 minutes, or until the edges are golden brown and the centers are set but soft. Rotate pans halfway through baking.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT12M", "doneness_cues": {"visual": "Golden edges, matte tops", "tactile": null}}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Allow cookies to cool on the baking sheet for 5 minutes before transferring to a wire rack to cool completely. They will firm up as they cool.", "structured": {"action": "COOL", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT1H15M", "total_time": "PT1H40M", "overnight_required": false, "yields": "24 cookies", "yield_count": 24, "serving_size_g": 22}', '{"flags": ["Vegetarian", "Soy-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 99.44, "protein_g": 1.5, "carbohydrates_g": 11.67, "fat_g": 5.24, "saturated_fat_g": 2.63, "trans_fat_g": null, "monounsaturated_fat_g": 1.2, "polyunsaturated_fat_g": 0.21, "fiber_g": 0.46, "sugar_g": 4.3, "sodium_mg": 55.3, "cholesterol_mg": 18.05, "potassium_mg": 29.29, "calcium_mg": 13.68, "iron_mg": 0.39, "magnesium_mg": 12.43, "phosphorus_mg": 37.25, "zinc_mg": 0.27, "vitamin_a_mcg": 36.7, "vitamin_c_mg": null, "vitamin_d_mcg": 0.04, "vitamin_e_mg": 0.14, "vitamin_k_mcg": 0.36, "vitamin_b6_mg": 0.01, "vitamin_b12_mcg": 0.03, "thiamin_mg": 0.01, "riboflavin_mg": 0.01, "niacin_mg": 0.08, "folate_mcg": 2.64, "water_g": 3.18, "alcohol_g": 0.07, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in airtight container; texture is best at room temperature.", "duration": "P1W"}, "freezer": {"notes": "Freeze raw dough balls or baked cookies.", "duration": "P3M"}, "reheating": "None required, but can be warmed briefly in a low oven if desired.", "does_not_keep": false}', '[{"name": "Stand mixer or electric hand mixer", "required": true, "alternative": null}, {"name": "Baking sheets", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Microplane or zester", "required": true, "alternative": null}, {"name": "Small skillet", "required": true, "alternative": "Oven tray for toasting nuts"}]', '[{"symptom": "Cookies spread flat and look greasy", "likely_cause": "Butter was too warm or dough wasn''t chilled long enough", "prevention": "Ensure butter is room temp (not melted) and chill dough for full hour", "fix": "Chill the remaining dough on the baking sheet for 15 minutes before baking"}, {"symptom": "Texture is gritty or crunchy rather than tender", "likely_cause": "Cornmeal grind was too coarse", "prevention": "Use ''fine'' cornmeal or corn flour, not coarse polenta grits", "fix": "Cannot be fixed after baking"}]', '["The grind of the cornmeal dictates the texture. For the requested ladyfinger/madeleine tenderness, look for ''fine'' stone-ground cornmeal or corn flour. Coarse grits will result in a hard crunch.", "Rubbing the lemon zest into the sugar with your fingers before creaming with the butter will release more essential oils and result in a more fragrant cookie.", "Pine nuts burn easily. Watch them closely while toasting in the skillet; they can go from golden to burnt in seconds.", "These cookies improve after 24 hours as the moisture from the butter softens the cornmeal further."]', '"These cookies draw inspiration from the Italian ''Paste di Meliga'', traditional Piedmontese cornmeal biscuits born from necessity when wheat prices rose. While traditional versions are often piped and crunchy, this variation incorporates the loftier, sponge-like texture found in French madeleines."', 99.44);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('301cc53c-82db-40a8-adea-1c7d2d74d4b4', 'Garlic Royale in Tomato Consommé', 'A silky, savory garlic-infused egg custard set gently in the center of a vibrant, emulsified tomato broth. Crowned with sweet pan-seared shrimp and diced red bell peppers for a textural contrast of crisp and creamy.', 'appetizer', 'Fusion', 'Intermediate', '["project", "chive", "egg", "garlic", "milk", "olive oil", "red bell pepper", "shrimp", "tomato juice", "fusion", "dinner party"]', '[{"group_name": "Garlic Custard (Royale)", "items": [{"name": "whole milk", "quantity": 250, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 4, "unit": null, "preparation": "crushed", "notes": "approx. 20g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "large", "notes": "approx. 100g liquid", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Tomato Broth", "items": [{"name": "tomato juice", "quantity": 300, "unit": "ml", "preparation": null, "notes": "high quality, unsalted preferred", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "extra virgin olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "smashed", "notes": "approx. 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish", "items": [{"name": "shrimp", "quantity": 12, "unit": null, "preparation": "peeled and deveined", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "a6bf7ab3-9b88-4c5b-a2fa-966c40a0e5a7", "nutrition_source": "USDA FoodData Central"}, {"name": "red bell pepper", "quantity": 60, "unit": "g", "preparation": "finely diced (brunoise)", "notes": null, "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "USDA FoodData Central"}, {"name": "chives", "quantity": 5, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "for saut\u00e9ing", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine milk, crushed garlic (4 cloves), and salt in a small saucepan. Bring to a bare simmer over medium heat, then remove from heat. Cover and let steep for 15 minutes to infuse the garlic flavor.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a mixing bowl, whisk the eggs gently to break them up without creating excess foam. Slowly pour the warm garlic-infused milk into the eggs while whisking constantly (tempering).", "structured": {"action": "TEMPER", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Strain the egg mixture through a fine mesh sieve into a measuring jug to remove garlic solids and chalaza. Divide the mixture evenly among 4 lightly oiled ramekins.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Place ramekins in a steamer basket over simmering water. Cover the ramekins with foil to prevent water dripping in. Steam on low heat until the custard is set but wobbles slightly in the center, like gelatin. Remove and let cool slightly.", "structured": {"action": "STEAM", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT12M", "doneness_cues": {"visual": "Surface is matte and flat", "tactile": "Wobbles slightly when shaken"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "While custards rest, combine tomato juice, 30ml olive oil, and 1 smashed garlic clove in a clean saucepan. Simmer gently until slightly reduced and emulsified. Season with salt to taste. Discard garlic clove.", "structured": {"action": "REDUCE", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Heat remaining 15ml olive oil in a skillet over medium-high heat. Saut\u00e9 the shrimp and diced red bell peppers. Cook shrimp until pink and opaque (approx. 2 minutes per side) and peppers are crisp-tender.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": "PT4M", "doneness_cues": {"visual": "Shrimp turn pink and opaque", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "To serve, run a thin knife around the edge of each custard and carefully invert it into the center of a shallow bowl. Pour the hot tomato broth around the custard. Top with saut\u00e9ed shrimp, peppers, and fresh chives.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT20M", "total_time": "PT55M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 220}', '{"flags": ["Pescatarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Low-Carb"], "not_suitable_for": ["Vegans (eggs, shrimp)", "Shellfish allergy"]}', '{"per_serving": {"calories": 232.29, "protein_g": 13.9, "carbohydrates_g": 9.13, "fat_g": 16.09, "saturated_fat_g": 3.57, "trans_fat_g": 0.01, "monounsaturated_fat_g": 9.67, "polyunsaturated_fat_g": 1.88, "fiber_g": 1.83, "sugar_g": 6.87, "sodium_mg": 500.68, "cholesterol_mg": 159.63, "potassium_mg": 454.36, "calcium_mg": 129.99, "iron_mg": 1.12, "magnesium_mg": 34.52, "phosphorus_mg": 214.44, "zinc_mg": 1.3, "vitamin_a_mcg": 100.48, "vitamin_c_mg": 32.15, "vitamin_d_mcg": 1.31, "vitamin_e_mg": 2.17, "vitamin_k_mcg": 7.88, "vitamin_b6_mg": 0.19, "vitamin_b12_mcg": 0.51, "thiamin_mg": 0.06, "riboflavin_mg": 0.24, "niacin_mg": 0.26, "folate_mcg": 21.96, "water_g": 121.01, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store custard and broth separately to prevent texture degradation.", "duration": "P2D"}, "freezer": {"notes": "Custard will separate and become spongy if frozen.", "duration": null}, "reheating": "Gently steam custard to warm; heat broth separately on stove.", "does_not_keep": false}', '[{"name": "Ramekins (120ml capacity)", "required": true, "alternative": null}, {"name": "Steamer or large pot with rack", "required": true, "alternative": "Deep roasting pan for water bath baking"}, {"name": "Fine mesh sieve", "required": true, "alternative": null}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Skillet", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}]', '[{"symptom": "Custard has bubbles or a honeycomb texture", "likely_cause": "Cooking temperature was too high (eggs curdled)", "prevention": "Steam on low heat; ensure water is barely simmering, not boiling aggressively", "fix": "Cannot be fixed, but still edible"}, {"symptom": "Custard is liquid in the center", "likely_cause": "Undercooked", "prevention": "Check earlier; if liquid, continue steaming in 2-minute intervals", "fix": "Return to steamer immediately"}]', '["Strain the custard mixture twice for the absolute smoothest, glass-like texture.", "If you find unmolding difficult, you can serve the custard directly in the ramekin and pour the broth over the top for a simpler presentation.", "Using high-quality tomato juice is key here; look for brands with no added sugar or celery salt for a pure flavor profile.", "For a clearer broth, you can strain the tomato juice through a coffee filter (tomato water technique), though this recipe uses the full juice for body."]', '"This dish borrows the technique of a French ''Royale'' (a garnish custard usually cut into shapes for consomm\u00e9) but elevates it to a main component. The pairing of garlic and tomato nods to Spanish gazpachos and garlic soups, while the texture mimics Japanese Chawanmushi."', 232.29);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('30fbabfa-3766-4873-9d73-a3ce75a93d3b', 'Quick Miso-Glazed Black Cod', 'A streamlined version of the iconic Japanese dish. Buttery, flakey black cod fillets are coated in a sweet and savory umami-packed glaze that caramelizes under the broiler, delivering restaurant-quality flavor in under an hour.', 'dinner', 'Japanese', 'Easy', '["asian", "fish", "five ingredient", "mirin", "miso", "dinner", "easy", "quick", "weeknight", "low-fat", "japanese", "seafood"]', '[{"group_name": "Fish", "items": [{"name": "black cod fillets", "quantity": 4, "unit": null, "preparation": "skin-on or off", "notes": "approx. 150g each (600g total), also known as Sablefish", "substitutions": ["Chilean Sea Bass", "Salmon fillets"], "ingredient_id": "229ccaef-c763-440b-b44f-6e22222d3fd1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Miso Glaze", "items": [{"name": "white miso paste", "quantity": 80, "unit": "g", "preparation": "smooth", "notes": "Shiro miso", "substitutions": [], "ingredient_id": "46697260-96ba-4751-83c0-b40aebb81229", "nutrition_source": "USDA FoodData Central"}, {"name": "mirin", "quantity": 30, "unit": "ml", "preparation": null, "notes": "sweet rice wine", "substitutions": [], "ingredient_id": "2a72c18d-8a1d-4259-8790-25d62f6fb5ba", "nutrition_source": "Aggregated Public Data"}, {"name": "sake", "quantity": 30, "unit": "ml", "preparation": null, "notes": "dry japanese rice wine", "substitutions": ["water", "dry sherry"], "ingredient_id": "1cfffbd2-7ea5-4cbc-bc35-c57e12233152", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 25, "unit": "g", "preparation": null, "notes": "dissolves easier than coarse sugar", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the black cod fillets completely dry with paper towels. Excess moisture will prevent the glaze from adhering and diluting the flavor.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a small bowl, whisk together the white miso, mirin, sake, and sugar until the sugar is fully dissolved and the texture is smooth.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Brush or spoon the glaze generously over the top and sides of each fillet. Let them sit at room temperature for 30 minutes. This allows the salt in the miso to cure the fish slightly and flavors to penetrate.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "While the fish marinates, preheat your oven to 200\u00b0C (400\u00b0F). Line a baking sheet with aluminum foil and lightly grease it to prevent sticking.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Place the fillets on the prepared baking sheet, skin-side down (if applicable). Bake for 10-12 minutes, or until the fish is opaque and begins to flake.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT12M", "doneness_cues": {"visual": "Fish is opaque", "tactile": "Flakes gently with pressure"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Switch the oven to ''Broil'' (High). Move the baking sheet to the upper rack and broil for 2-3 minutes. Watch closely\u2014the sugars in the miso can burn in seconds. You want a deep golden brown spotty caramelization (bubbling glaze).", "structured": {"action": "BROIL", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Deep golden brown spots, bubbling glaze", "tactile": null}}, "tips": ["Do not walk away during this step; miso goes from caramelized to charcoal very quickly."]}, {"step_number": 7, "phase": "finish", "text": "Remove from oven and let rest for 2 minutes before serving. The internal temperature should reach at least 63\u00b0C (145\u00b0F).", "structured": {"action": "REST", "temperature": {"celsius": 63, "fahrenheit": 145}, "duration": "PT2M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT30M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 170}', '{"flags": ["Pescatarian", "Dairy-Free", "Egg-Free", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 213.75, "protein_g": 29.32, "carbohydrates_g": 15.4, "fat_g": 2.21, "saturated_fat_g": 0.4, "trans_fat_g": null, "monounsaturated_fat_g": 0.36, "polyunsaturated_fat_g": 0.92, "fiber_g": 1.08, "sugar_g": 11, "sodium_mg": 849.98, "cholesterol_mg": 64.5, "potassium_mg": 663.5, "calcium_mg": 35.84, "iron_mg": 1.08, "magnesium_mg": 58.05, "phosphorus_mg": 336.75, "zinc_mg": 1.19, "vitamin_a_mcg": 18.8, "vitamin_c_mg": 1.5, "vitamin_d_mcg": 1.35, "vitamin_e_mg": 0.96, "vitamin_k_mcg": 6.01, "vitamin_b6_mg": 0.4, "vitamin_b12_mcg": 1.38, "thiamin_mg": 0.14, "riboflavin_mg": 0.15, "niacin_mg": 3.27, "folate_mcg": 14.3, "water_g": 136.28, "alcohol_g": 1.21, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best enjoyed immediately; reheat gently to avoid drying out.", "duration": "P2D"}, "freezer": {"notes": "Cooked fish does not freeze well; texture will degrade.", "duration": null}, "reheating": "Warm in a 150\u00b0C/300\u00b0F oven for 5-8 minutes.", "does_not_keep": false}', '[{"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Aluminum foil", "required": true, "alternative": "Parchment paper (caution under broiler)"}, {"name": "Whisk or fork", "required": true, "alternative": null}, {"name": "Pastry brush", "required": false, "alternative": "Spoon"}]', '[{"symptom": "Glaze is burnt/blackened", "likely_cause": "Broiled too close to the heating element or for too long", "prevention": "Watch constantly during the broiling step; keep rack 6 inches from heat", "fix": "Scrape off the burnt layer; the fish underneath is likely still moist"}, {"symptom": "Fish is rubbery or tough", "likely_cause": "Overcooked", "prevention": "Check for flakiness early; black cod is fatty and forgiving but can still dry out", "fix": "Cannot be fixed; flake into a salad or soup to mask texture"}]', '["While this ''quick'' version rests for 30 minutes, the traditional Nobu-style preparation involves marinating the fish for 2-3 days in the fridge. If you have time, extend the marinating step for deeper flavor.", "Black cod (Sablefish) is extremely rich in omega-3 fats, giving it a luxurious, buttery texture that is forgiving to cook. If unavailable, Chilean Sea Bass is the closest substitute.", "Make sure to use ''White Miso'' (Shiro Miso) rather than Red Miso. Red miso is too salty and robust for this delicate preparation."]', '"Gindara no Saikyo Yaki (Miso Marinated Black Cod) is a traditional Japanese dish originating from Kyoto, popularized globally by Chef Nobu Matsuhisa. The technique uses the preservation properties of miso and sake lees to cure the fatty fish."', 213.75);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('3106f3ad-de51-4925-8d64-aef8658d5651', 'Chicken Tikka Masala', 'A streamlined version of the global favorite, featuring tender charred chicken pieces simmered in a velvety, aromatic tomato-cream sauce. Balanced with earthy cumin, floral coriander, and the signature warmth of garam masala.', 'dinner', 'Indian', 'Intermediate', '["curry", "high protein", "comfort food", "weeknight"]', '[{"group_name": "Chicken & Marinade", "items": [{"name": "boneless skinless chicken thighs", "quantity": 600, "unit": "g", "preparation": "cut into 3cm cubes", "notes": null, "substitutions": [], "ingredient_id": "39d19921-3bf5-49b0-9e1c-4f498caa7d6a", "nutrition_source": "Aggregated Public Data"}, {"name": "plain whole milk yogurt", "quantity": 100, "unit": "g", "preparation": "whisked", "notes": null, "substitutions": [], "ingredient_id": "964528c1-9458-4782-98ec-6844ed14c47d", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "grated", "notes": "approx. 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "ginger", "quantity": 15, "unit": "g", "preparation": "fresh, grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "kashmiri chili powder", "quantity": 5, "unit": "g", "preparation": null, "notes": "or paprika for less heat", "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Masala Sauce", "items": [{"name": "ghee", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": ["neutral oil", "unsalted butter"], "ingredient_id": "f3bd3ed3-45ef-4469-9f4c-7fbd5c40d069", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "07bf825b-2bab-470e-95c2-1b0e31a50c98", "nutrition_source": "Aggregated Public Data"}, {"name": "tomato puree", "quantity": 400, "unit": "g", "preparation": null, "notes": "passata or smooth crushed tomatoes", "substitutions": [], "ingredient_id": "5ac1bb48-a455-44c0-b93d-af71d0808ea3", "nutrition_source": "Aggregated Public Data"}, {"name": "garam masala", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "71e63f61-8498-458c-9fdb-cb76a7f15723", "nutrition_source": "Aggregated Public Data"}, {"name": "ground coriander", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "ground turmeric", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "sugar", "quantity": 5, "unit": "g", "preparation": null, "notes": "to balance tomato acidity", "substitutions": [], "ingredient_id": "5ebb3e25-da7a-442b-be81-e098b7d79a00", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finish", "items": [{"name": "heavy cream", "quantity": 120, "unit": "ml", "preparation": null, "notes": "min 36% fat", "substitutions": [], "ingredient_id": "0568a393-d5cb-461f-97b5-66e29fdcbc79", "nutrition_source": "Aggregated Public Data"}, {"name": "dried fenugreek leaves (kasuri methi)", "quantity": 2, "unit": "g", "preparation": "crushed between fingers", "notes": null, "substitutions": [], "ingredient_id": "33c2f9bc-4ef2-431a-8539-ab8f0bbe4101", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh cilantro", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "90d50243-5217-4e50-836c-b2f624e2b58b", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a mixing bowl, combine yogurt, grated garlic, grated ginger, lemon juice, cumin, and chili powder. Add chicken cubes and toss to coat thoroughly. Let marinate while preparing the sauce ingredients (10-15 minutes).", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat ghee in a saucepan over medium heat. Add diced onion and saut\u00e9 until golden brown and soft, stirring frequently to prevent burning.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT8M", "doneness_cues": {"visual": "Golden brown edges", "tactile": "Soft and translucent"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Stir garam masala, coriander, and turmeric into the onions. Toast the spices for 30 seconds until fragrant, then pour in the tomato puree and sugar. Lower heat and simmer gently.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "While the sauce simmers, heat a large skillet over high heat. Add the marinated chicken in a single layer (do in batches if necessary). Sear undisturbed until well-charred on one side, then flip. Cook until charred on all sides and internal temperature reaches 74\u00b0C/165\u00b0F.", "structured": {"action": "SEAR", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT8M", "doneness_cues": {"visual": "Deep brown char marks", "tactile": null}}, "tips": ["Crowding the pan will cause the chicken to steam rather than sear.", "Ensure raw chicken does not contaminate other surfaces."]}, {"step_number": 5, "phase": "assemble", "text": "Transfer the cooked chicken pieces directly into the simmering sauce. Stir in the heavy cream and crushed fenugreek leaves. Simmer for 2 more minutes to marry the flavors.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove from heat. Garnish with fresh chopped cilantro and serve immediately.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT15M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 340}', '{"flags": ["Gluten-Free", "Egg-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Dairy-Free diets", "Vegan diets"]}', '{"per_serving": {"calories": 601.21, "protein_g": 40.54, "carbohydrates_g": 30.47, "fat_g": 37.62, "saturated_fat_g": 4.79, "trans_fat_g": null, "monounsaturated_fat_g": 0.49, "polyunsaturated_fat_g": 0.5, "fiber_g": 5.17, "sugar_g": 15.59, "sodium_mg": 255.72, "cholesterol_mg": 23.75, "potassium_mg": 1365.51, "calcium_mg": 182.6, "iron_mg": 6.6, "magnesium_mg": 59.74, "phosphorus_mg": 358.4, "zinc_mg": 4.78, "vitamin_a_mcg": 360.15, "vitamin_c_mg": 27.76, "vitamin_d_mcg": null, "vitamin_e_mg": 0.64, "vitamin_k_mcg": 9.34, "vitamin_b6_mg": 0.1, "vitamin_b12_mcg": 0.13, "thiamin_mg": 0.03, "riboflavin_mg": 0.08, "niacin_mg": 0.35, "folate_mcg": 6.2, "water_g": 31.25, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves after 24 hours as spices meld.", "duration": "P3D"}, "freezer": {"notes": "Cream-based sauces may separate slightly; reheat gently while whisking.", "duration": "P2M"}, "reheating": "Reheat gently on the stovetop over low heat to prevent the cream from splitting.", "does_not_keep": false}', '[{"name": "Large skillet", "required": true, "alternative": "Wok"}, {"name": "Saucepan", "required": true, "alternative": "Dutch oven"}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Sauce tastes metallic or acidic", "likely_cause": "Tomatoes were not cooked down sufficiently", "prevention": "Simmer the tomato base until the oil begins to separate from the solids before adding cream", "fix": "Add a pinch more sugar and 1 tablespoon of butter to round out the flavor"}, {"symptom": "Chicken is dry", "likely_cause": "Overcooked during the searing phase", "prevention": "Use chicken thighs instead of breast; remove from skillet immediately once 74\u00b0C is reached", "fix": "Shred the chicken into the sauce so it absorbs more liquid"}]', '["The ''char'' on the chicken is essential for authentic flavor. If you don''t have a hot skillet, you can broil the chicken on a wire rack in the oven.", "Kasuri methi (dried fenugreek leaves) provides the distinct ''restaurant'' aroma. Rubbing them between your palms releases their oils before adding.", "For a smoother sauce, you can use an immersion blender on the onion-tomato mixture before adding the chicken and cream.", "If using chicken breast, reduce cooking time significantly as it dries out faster than thighs."]', '"While its exact origins are debated\u2014often attributed to South Asian chefs in the UK adapting traditional dishes for local palates\u2014Chicken Tikka Masala has become a global ambassador for Indian flavors. It bridges the gap between the dry, roasted Tandoori styles and rich, gravy-based curries."', 601.21);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('316d26bc-911b-4536-a93d-72bdd669371e', 'Carciofi alla Romana (Roman-Style Braised Artichokes)', 'Tender globe artichokes braised stem-up in olive oil, water, and aromatic herbs until they melt in the mouth. A classic example of ''cucina povera'' where the interplay of mint, garlic, and high-quality olive oil transforms a thistle into a buttery, savory masterpiece.', 'appetizer', 'Italian', 'Intermediate', '["italian", "artichoke", "extra virgin olive oil", "five ingredient", "parsley", "appetizer", "vegan", "vegetarian", "gluten-free", "low-carb"]', '[{"group_name": "Artichokes & Prep", "items": [{"name": "globe artichokes", "quantity": 4, "unit": null, "preparation": "whole", "notes": "approx. 300g each before trimming; prefer ''Mammola'' or ''Violetto'' variety if available", "substitutions": [], "ingredient_id": "61ec9e3f-dbb8-4fb1-a954-50dbe6478be1", "nutrition_source": "USDA FoodData Central"}, {"name": "lemons", "quantity": 2, "unit": null, "preparation": "halved", "notes": "for acidulated water to prevent oxidation", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Stuffing (Battuto)", "items": [{"name": "fresh parsley", "quantity": 30, "unit": "g", "preparation": "finely chopped", "notes": "leaves and tender stems", "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh mint", "quantity": 15, "unit": "g", "preparation": "finely chopped", "notes": "essential for Roman style; ''mentuccia'' is traditional, spearmint is a valid substitute", "substitutions": [], "ingredient_id": "213e3d3b-d332-45a9-b35e-23ee29a27173", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 5, "unit": "g", "preparation": "plus more to taste", "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Braising Liquid", "items": [{"name": "extra virgin olive oil", "quantity": 120, "unit": "ml", "preparation": "high quality", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 240, "unit": "ml", "preparation": "warm", "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare a large bowl of cold water. Squeeze the juice of two lemons into the water and drop the spent lemon halves in. This acidulated water is critical to prevent the artichokes from turning brown (oxidizing).", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Clean the artichokes: Pull off the tough outer dark green leaves until you reach the pale yellow/light green inner leaves. Using a paring knife, trim the dark green skin from the base and the stem (do not cut the stem off; peel it like a carrot). Use a serrated knife to slice off the top 2-3 cm of the artichoke to remove the thorny tips.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Be aggressive with leaf removal. If the leaf snaps, it''s tough. If it bends, it''s tender.", "Rub cut surfaces with a lemon half immediately to stop browning."]}, {"step_number": 3, "phase": "prep", "text": "Gently pry open the center leaves. If there is a fuzzy purple ''choke'' in the center, use a small spoon to scrape it out completely without damaging the heart. Place finished artichokes immediately into the lemon water.", "structured": {"action": "CORE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Make the ''battuto'' (stuffing): In a small bowl, combine the minced parsley, mint, garlic, salt, and black pepper. Mix well to distribute the aromatics.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Drain the artichokes and pat them dry upside down. Using your fingers, firmly pack the herb mixture into the center cavity and between the leaves of each artichoke. Season the exterior lightly with extra salt.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Place the artichokes head-down (stem-up) in a deep pan. They should fit snugly so they remain upright. Pour the olive oil and water into the pan. The liquid should come up about halfway up the artichoke heads.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Cover the pan with a lid (or a parchment paper cartouche for professional results) and bring to a simmer over medium heat. Reduce heat to low and braise for 30-40 minutes.", "structured": {"action": "BRAISE", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT35M", "doneness_cues": {"visual": null, "tactile": "A knife should slide into the stem with zero resistance, like butter"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Once tender, uncover and increase heat to medium-high for 2-3 minutes to reduce the sauce and slightly brown the tops of the artichokes. Remove from heat and let cool in the liquid until warm or room temperature.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT35M", "total_time": "PT1H10M", "overnight_required": false, "yields": "4 artichokes", "yield_count": 4, "serving_size_g": 250}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Low-Carb", "Keto", "Paleo", "Whole30", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 327.33, "protein_g": 4.11, "carbohydrates_g": 13.82, "fat_g": 30.3, "saturated_fat_g": 4.21, "trans_fat_g": null, "monounsaturated_fat_g": 21.94, "polyunsaturated_fat_g": 3.26, "fiber_g": 6.49, "sugar_g": 1.2, "sodium_mg": 591.94, "cholesterol_mg": null, "potassium_mg": 476.71, "calcium_mg": 77.02, "iron_mg": 2.3, "magnesium_mg": 72.33, "phosphorus_mg": 108.46, "zinc_mg": 0.69, "vitamin_a_mcg": 40.73, "vitamin_c_mg": 25.75, "vitamin_d_mcg": null, "vitamin_e_mg": 4.59, "vitamin_k_mcg": 157.49, "vitamin_b6_mg": 0.19, "vitamin_b12_mcg": null, "thiamin_mg": 0.09, "riboflavin_mg": 0.1, "niacin_mg": 1.3, "folate_mcg": 87.51, "water_g": 162.82, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store immersed in their cooking liquid/oil. Flavor improves after 24 hours.", "duration": "P4D"}, "freezer": {"notes": "Not recommended; texture becomes mushy upon thawing.", "duration": null}, "reheating": "Gently warm in a covered pan with a splash of water, or serve at room temperature.", "does_not_keep": false}', '[{"name": "Large bowl", "required": true, "alternative": null}, {"name": "Paring knife", "required": true, "alternative": "Small curved tourn\u00e9 knife"}, {"name": "Serrated bread knife", "required": true, "alternative": null}, {"name": "Deep saut\u00e9 pan or Dutch oven", "required": true, "alternative": "Heavy-bottomed pot deep enough for upright artichokes"}, {"name": "Parchment paper", "required": false, "alternative": "Lid"}, {"name": "Small spoon", "required": true, "alternative": "Melon baller"}]', '[{"symptom": "Artichokes are tough and fibrous", "likely_cause": "Insufficient trimming of outer leaves", "prevention": "Remove more leaves than you think necessary; snap them back until the break point is low and the remaining leaf is pale yellow", "fix": "Peel off the tough outer cooked leaves on the plate and eat only the heart/inner leaves"}, {"symptom": "Artichokes turned dark brown/black", "likely_cause": "Oxidation during prep", "prevention": "Keep artichokes submerged in acidulated water (lemon water) continuously until the moment they hit the pan", "fix": "Cannot be fixed, but purely cosmetic; safe to eat"}]', '["Mentuccia (Lesser Calamint) is the traditional herb for this Roman dish. Since it is hard to find outside Italy, a mix of fresh mint and a pinch of dried oregano mimics the flavor profile well.", "Do not discard the stems! The stem is an extension of the heart and is the sweetest part. Just ensure you peel the fibrous green skin off deeply.", "Serve these with plenty of crusty bread to ''fare la scarpetta'' (sop up) the incredible mint-infused olive oil sauce.", "Using a ''cartouche'' (a circle of parchment paper with a hole in the center) directly on top of the artichokes helps steam them evenly while allowing the sauce to reduce slightly."]', '"Originating in the coastal region of Lazio, specifically Rome, this dish (Carciofi alla Romana) dates back centuries. It was a staple of Jewish-Roman cuisine before becoming a ubiquitous trattoria classic. Traditionally made with ''Carciofo Romanesco del Lazio'' (IGP), a variety that is round, violet-tinged, and spineless, allowing the whole flower to be eaten without removing a choke."', 327.33);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('31f2ce7e-55cb-4290-8671-b2df44142b2d', 'Star Anise Infused Cantaloupe Sorbet', 'A sophisticated frozen treat where the intense floral sweetness of ripe cantaloupe is elevated by the warm, licorice-like notes of star anise. The resulting texture is velvety and light, offering a refreshing palate cleanser or an elegant finish to a summer meal.', 'dessert', 'Fusion', 'Intermediate', '["cantaloupe", "five ingredient", "sorbet", "star anise", "sugar", "weeknight", "dessert", "summer", "dairy-free", "low-fat", "nut-free", "vegan", "fruit"]', '[{"group_name": "Anise Syrup", "items": [{"name": "water", "quantity": 150, "unit": "ml", "preparation": "cold", "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "granulated sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "star anise", "quantity": 3, "unit": null, "preparation": "whole pods", "notes": "approx 3g", "substitutions": [], "ingredient_id": "9010f167-112f-4c3b-80c3-b49783e568a1", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Fruit Base", "items": [{"name": "cantaloupe", "quantity": 800, "unit": "g", "preparation": "peeled, seeded, and cubed", "notes": "flesh from 1 large melon", "substitutions": [], "ingredient_id": "c3174cb9-d4cb-4497-890e-73f1325721e1", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 30, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "small pinch to enhance sweetness", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine water, sugar, and star anise pods in a small saucepan. Bring to a boil over medium heat, stirring until the sugar dissolves completely.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Remove the syrup from heat and let it steep at room temperature until fully cooled (approx 30 minutes). This allows the anise flavor to infuse deeply.", "structured": {"action": "COOL", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "While the syrup cools, place the cubed cantaloupe, lemon juice, and pinch of salt into a blender. Blend on high speed until completely smooth and aerated.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Smooth, uniform orange liquid with no chunks", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Discard the star anise pods from the cooled syrup. Pour the syrup into the blender with the melon puree and pulse briefly to combine.", "structured": {"action": "MIX", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Transfer the mixture to a container and chill in the refrigerator for at least 4 hours until it reaches 4\u00b0C/40\u00b0F. A cold base is crucial for proper churning.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT4H", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Pour the chilled base into your ice cream maker and churn according to the manufacturer''s instructions, usually until it resembles soft-serve ice cream.", "structured": {"action": "CHURN", "temperature": null, "duration": "PT20M", "doneness_cues": {"visual": "Thick, slushy consistency like soft serve", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Transfer the sorbet to a freezer-safe container. Press a piece of parchment paper directly onto the surface to prevent ice crystals, cover, and freeze for at least 4 hours to firm up.", "structured": {"action": "FREEZE", "temperature": {"celsius": -18, "fahrenheit": 0}, "duration": "PT4H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT8H", "total_time": "PT8H25M", "overnight_required": true, "yields": "1 Liter", "yield_count": 8, "serving_size_g": 120}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Low-Fat"], "not_suitable_for": []}', '{"per_serving": {"calories": 108.65, "protein_g": 0.92, "carbohydrates_g": 27.36, "fat_g": 0.26, "saturated_fat_g": 0.05, "trans_fat_g": null, "monounsaturated_fat_g": 0.04, "polyunsaturated_fat_g": 0.09, "fiber_g": 0.97, "sugar_g": 26.67, "sodium_mg": 65.25, "cholesterol_mg": null, "potassium_mg": 276.74, "calcium_mg": 12.24, "iron_mg": 0.36, "magnesium_mg": 13.05, "phosphorus_mg": 16.95, "zinc_mg": 0.21, "vitamin_a_mcg": 169.06, "vitamin_c_mg": 38.23, "vitamin_d_mcg": null, "vitamin_e_mg": 0.06, "vitamin_k_mcg": 2.5, "vitamin_b6_mg": 0.08, "vitamin_b12_mcg": null, "thiamin_mg": 0.04, "riboflavin_mg": 0.03, "niacin_mg": 0.75, "folate_mcg": 21.79, "water_g": 112.45, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Do not store in refrigerator; keep frozen.", "duration": null}, "freezer": {"notes": "Best consumed within 1 week for optimal texture; creates ice crystals over time.", "duration": "P1M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Blender or Food Processor", "required": true, "alternative": null}, {"name": "Ice Cream Maker", "required": true, "alternative": "Shallow metal pan and fork (for granita style)"}, {"name": "Fine mesh sieve", "required": true, "alternative": null}, {"name": "Airtight freezer container", "required": true, "alternative": null}]', '[{"symptom": "Sorbet is icy and hard as a rock", "likely_cause": "Low sugar content or slow freezing time", "prevention": "Ensure accurate sugar measurement; sugar lowers the freezing point", "fix": "Allow to sit at room temperature for 10-15 minutes before scooping, or re-blend firmly frozen sorbet in a food processor to fluff it up"}]', '["The sweetness of the fruit determines the final texture. If your cantaloupe is not very sweet, you may need to increase the sugar by 20-30g to prevent the sorbet from freezing too hard.", "For a strictly ''Five Ingredient'' recipe, the water and optional salt are generally considered pantry staples and do not count against the limit.", "To test if your sorbet base has the right sugar density, float a clean, raw egg (in its shell) in the liquid. If a patch of shell about the size of a dime (1.8cm) shows above the surface, the density is perfect.", "Star anise is potent; 3 pods provide a distinct flavor. For a subtle hint, use 1 pod or remove the pods from the syrup immediately after boiling rather than letting them steep."]', '"While sorbet is a staple of French glacerie, the technique originated from the Middle Eastern ''sharbat'', a cooling sweetened drink. This recipe bridges Western dessert technique with the Eastern spice profile of star anise (Illicium verum), native to Vietnam and China, highlighting the global evolution of frozen desserts."', 108.65);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('32ad8f44-e429-4508-a754-4d3ffa66a220', 'Creamy Celery and Tuscan Kale Risotto', 'A sophisticated vegetarian risotto that celebrates celery in two forms: a sweet, melting aromatic base and tender-crisp diced pieces for textural contrast. Paired with earthy kale and brightened with lemon zest, this dish transforms humble winter vegetables into a luxurious, creamy main course.', 'main course', 'Italian', 'Intermediate', '["italian", "arborio rice", "celery", "kale", "dinner", "main course", "winter", "gluten-free", "healthy", "low cholesterol", "low sugar", "nut-free", "vegetarian"]', '[{"group_name": "Broth", "items": [{"name": "vegetable broth", "quantity": 1500, "unit": "ml", "preparation": "hot", "notes": "low-sodium preferred", "substitutions": [], "ingredient_id": "ae6717c9-3978-4011-a0d9-33c30ab86f78", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Soffritto & Rice", "items": [{"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "small, approx 100g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "celery stalks", "quantity": 2, "unit": null, "preparation": "finely minced", "notes": "for the aromatic base, approx 80g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "arborio rice", "quantity": 320, "unit": "g", "preparation": null, "notes": null, "substitutions": ["carnaroli rice"], "ingredient_id": "d35782e6-8142-4414-b055-230d48cacc79", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 120, "unit": "ml", "preparation": null, "notes": "Pinot Grigio or Sauvignon Blanc", "substitutions": ["extra broth with a squeeze of lemon"], "ingredient_id": "0c041362-befe-4c15-88d2-ba97c8f46428", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables", "items": [{"name": "celery stalks", "quantity": 3, "unit": null, "preparation": "diced 1cm cubes", "notes": "for texture, approx 120g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "lacinato kale", "quantity": 150, "unit": "g", "preparation": "stemmed and shredded", "notes": "also known as Tuscan kale or dinosaur kale", "substitutions": ["dandelion greens", "curly kale"], "ingredient_id": "bb6a90eb-f157-455a-b438-d2333c784c60", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Mantecatura (Finish)", "items": [{"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "parmesan cheese", "quantity": 40, "unit": "g", "preparation": "freshly grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 3g", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "celery leaves", "quantity": null, "unit": null, "preparation": "fresh", "notes": "reserved from inner stalks for garnish", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pour the vegetable broth into a saucepan and bring to a gentle simmer. Keep it warm over low heat throughout the cooking process.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a heavy-bottomed pot, heat the olive oil over medium heat. Add the onion and the finely minced celery (the aromatic portion). Saut\u00e9 for 5-7 minutes until soft and translucent, but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT7M", "doneness_cues": {"visual": "Translucent and soft", "tactile": "Yielding texture"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the minced garlic and cook for another minute until fragrant. Add the rice and toast it, stirring constantly, for 2 minutes until the edges are translucent and the center remains opaque (the pearl).", "structured": {"action": "TOAST", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Rice edges are translucent, white dot in center", "tactile": "Rice sounds like glass beads hitting the pot"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour in the white wine to deglaze the pan. Stir vigorously until the wine has completely evaporated and the alcohol smell has dissipated.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Begin adding the hot broth one ladle at a time, stirring frequently. Wait until the liquid is almost absorbed before adding the next ladle. Adjust heat to maintain a gentle bubble.", "structured": {"action": "SIMMER", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "After about 10 minutes of cooking the rice, stir in the larger diced celery and the shredded kale. Continue adding broth and stirring for another 8-10 minutes.", "structured": {"action": "STIR", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Taste the rice. It should be tender but still have a slight bite (al dente). The texture should be fluid and creamy (all''onda), not stiff. If dry, add a final splash of broth. Remove from heat.", "structured": {"action": "TASTE", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Rice has slight resistance when bitten"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Vigorously stir in the cold cubed butter, grated parmesan, and lemon zest. Cover the pot and let it rest for 2 minutes to allow the emulsion to set.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": ["This step is called ''mantecatura'' and is essential for the creamy texture."]}, {"step_number": 9, "phase": "finish", "text": "Season with salt and plenty of freshly cracked black pepper to taste. Garnish with the reserved yellow celery leaves and serve immediately.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT5M", "total_time": "PT50M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": ["Vegans (contains dairy)"]}', '{"per_serving": {"calories": 780.52, "protein_g": 23.2, "carbohydrates_g": 124.25, "fat_g": 18.8, "saturated_fat_g": 6.86, "trans_fat_g": null, "monounsaturated_fat_g": 8.27, "polyunsaturated_fat_g": 2.19, "fiber_g": 17.12, "sugar_g": 2.13, "sodium_mg": 538.47, "cholesterol_mg": 22.93, "potassium_mg": 1181.54, "calcium_mg": 302.46, "iron_mg": 4.89, "magnesium_mg": 138.38, "phosphorus_mg": 412.24, "zinc_mg": 3.1, "vitamin_a_mcg": 1113.24, "vitamin_c_mg": 58.06, "vitamin_d_mcg": 0.05, "vitamin_e_mg": 1.64, "vitamin_k_mcg": 146.2, "vitamin_b6_mg": 0.62, "vitamin_b12_mcg": 0.13, "thiamin_mg": 0.56, "riboflavin_mg": 0.5, "niacin_mg": 6.47, "folate_mcg": 146.85, "water_g": 453.74, "alcohol_g": 2.67, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Texture will thicken significantly; reheat with a splash of water or broth.", "duration": "P3D"}, "freezer": {"notes": "Freezing is possible but not recommended as rice texture may become grainy.", "duration": "P1M"}, "reheating": "Gently warm on the stove with a splash of vegetable broth or water to restore creaminess.", "does_not_keep": false}', '[{"name": "Heavy-bottomed pot or Dutch oven", "required": true, "alternative": null}, {"name": "Saucepan", "required": true, "alternative": "Microwave-safe bowl (for stock)"}, {"name": "Wooden spoon", "required": true, "alternative": null}, {"name": "Ladle", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Rice is crunchy or chalky in the center", "likely_cause": "Undercooked; insufficient liquid or heat was too high causing evaporation before absorption", "prevention": "Keep stock hot; add liquid gradually; taste test frequently after 15 minutes", "fix": "Add more hot water or stock and continue cooking over low heat, stirring constantly, until tender"}, {"symptom": "Risotto is stiff and gloopy", "likely_cause": "Overcooked or too much starch released without enough liquid", "prevention": "Stop cooking when rice is al dente; keep the mixture fluid", "fix": "Stir in a small amount of hot broth or hot water immediately before serving to loosen the texture"}]', '["Using celery in two stages is key: the minced celery provides a savory background depth similar to onion, while the diced celery added later provides a clean, vegetal crunch to cut through the rich starch.", "If using dandelion greens instead of kale, blanch them quickly in boiling water before adding to the risotto to reduce their bitterness.", "The ''mantecatura'' (mounting with butter/cheese) must happen off the heat. If the pot is too hot, the butter will separate and make the dish greasy rather than creamy.", "For a true ''low cholesterol'' version, you can reduce the butter and cheese by half and finish with a drizzle of high-quality raw extra virgin olive oil instead."]', '"Risotto is a staple of Northern Italian cuisine, particularly in Lombardy and Piedmont where rice paddies are abundant. While celery is typically relegated to the ''soffritto'' (base), this recipe elevates it to a star ingredient, a technique often found in ''cucina povera'' (peasant cooking) where humble garden vegetables define the dish."', 780.52);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('32c0a3ad-b1f9-491a-985a-ec75db5bf795', 'Tahini Banana Date Cake with Mascarpone Cream', 'A surprisingly soft and tender crumb infused with the nutty warmth of tahini and natural sweetness of ripe bananas and sticky dates. Topped with a luscious, tangy mascarpone and cream cheese frosting that perfectly balances the earthy sesame notes.', 'dessert', 'Fusion', 'Intermediate', '["cakes", "banana", "cream cheese", "date", "mascarpone", "sesame seed", "tahini", "dessert"]', '[{"group_name": "Wet Ingredients", "items": [{"name": "ripe bananas", "quantity": 300, "unit": "g", "preparation": "mashed", "notes": "heavily spotted skins indicate sweetness", "substitutions": [], "ingredient_id": "d01cd7bd-9b20-4ccf-8475-27ca2843edf6", "nutrition_source": "USDA FoodData Central"}, {"name": "tahini", "quantity": 80, "unit": "g", "preparation": "well-stirred", "notes": "sesame paste", "substitutions": [], "ingredient_id": "87ae6455-8e22-4c1b-bad7-89fa69c4dc57", "nutrition_source": "Aggregated Public Data"}, {"name": "neutral oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": "grapeseed or vegetable oil", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "room temperature", "notes": "approx. 100g total without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "brown sugar", "quantity": 130, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dry Ingredients & Inclusions", "items": [{"name": "all-purpose flour", "quantity": 190, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "medjool dates", "quantity": 120, "unit": "g", "preparation": "pitted and roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "657c170c-11cc-41f7-a980-050a218a088e", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Mascarpone Cream Frosting", "items": [{"name": "mascarpone cheese", "quantity": 120, "unit": "g", "preparation": "chilled", "notes": null, "substitutions": [], "ingredient_id": "fc428935-3bcd-4cef-8495-7ed35e7dae22", "nutrition_source": "Aggregated Public Data"}, {"name": "cream cheese", "quantity": 80, "unit": "g", "preparation": "slightly softened", "notes": "full fat", "substitutions": [], "ingredient_id": "262c67de-76a4-4444-8c02-30ad4a179459", "nutrition_source": "USDA FoodData Central"}, {"name": "powdered sugar", "quantity": 40, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 30, "unit": "ml", "preparation": "chilled", "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "white sesame seeds", "quantity": 5, "unit": "g", "preparation": "toasted", "notes": "for garnish", "substitutions": [], "ingredient_id": "36a7664a-f96c-44b9-9b6d-cdd5e9e54f55", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 175\u00b0C (350\u00b0F). Grease a 20cm square cake pan and line the bottom and sides with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a medium bowl, whisk together the flour, baking powder, baking soda, and salt until uniform.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a large mixing bowl, whisk the mashed banana, brown sugar, tahini, oil, eggs, and vanilla extract vigorously until the mixture is emulsified and glossy.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour the dry ingredients into the wet mixture. Switch to a silicone spatula and gently fold until just a few streaks of flour remain. Do not overmix.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the chopped dates and fold gently 3-4 times to distribute them evenly without deflating the batter.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Pour the batter into the prepared pan and smooth the top. Bake for 35-40 minutes, or until a toothpick inserted into the center comes out clean or with a few moist crumbs.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT35M", "doneness_cues": {"visual": "Golden brown top", "tactile": "Springs back when touched lightly"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove cake from the oven and let it cool in the pan for 15 minutes, then transfer to a wire rack to cool completely.", "structured": {"action": "COOL", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "While the cake cools, prepare the frosting. In a bowl using an electric mixer, beat the mascarpone and cream cheese until smooth. Add powdered sugar and heavy cream, whipping until soft, spreadable peaks form.", "structured": {"action": "WHIP", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Spread the frosting generously over the cooled cake and sprinkle with toasted sesame seeds before slicing.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT1H15M", "total_time": "PT1H40M", "overnight_required": false, "yields": "1 20cm square cake (9 servings)", "yield_count": 9, "serving_size_g": 135}', '{"flags": ["Vegetarian"], "not_suitable_for": ["Vegans (contains dairy, eggs)", "Gluten intolerance"]}', '{"per_serving": {"calories": 447.46, "protein_g": 7.55, "carbohydrates_g": 58.08, "fat_g": 23.2, "saturated_fat_g": 8.04, "trans_fat_g": 0.15, "monounsaturated_fat_g": 1.53, "polyunsaturated_fat_g": 0.51, "fiber_g": 3.64, "sugar_g": 33.15, "sodium_mg": 310.77, "cholesterol_mg": 54.08, "potassium_mg": 329.63, "calcium_mg": 182.71, "iron_mg": 1.93, "magnesium_mg": 57.76, "phosphorus_mg": 131.97, "zinc_mg": 0.9, "vitamin_a_mcg": 132.26, "vitamin_c_mg": 2.92, "vitamin_d_mcg": 0.28, "vitamin_e_mg": 0.27, "vitamin_k_mcg": 0.92, "vitamin_b6_mg": 0.2, "vitamin_b12_mcg": 0.12, "thiamin_mg": 0.05, "riboflavin_mg": 0.12, "niacin_mg": 0.74, "folate_mcg": 20.46, "water_g": 45.9, "alcohol_g": 0.19, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container due to the dairy frosting.", "duration": "P4D"}, "freezer": {"notes": "Freeze cake base only, without frosting.", "duration": "P1M"}, "reheating": "If served refrigerated, allow to sit at room temperature for 20 minutes before eating to soften the crumb.", "does_not_keep": false}', '[{"name": "20cm (8-inch) square cake pan", "required": true, "alternative": "9-inch round cake pan"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Medium mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Silicone spatula", "required": true, "alternative": null}, {"name": "Electric hand mixer", "required": true, "alternative": "Stand mixer with paddle attachment"}]', '[{"symptom": "Cake is dense or gummy", "likely_cause": "Overmixing after adding the flour developed too much gluten", "prevention": "Stop mixing the moment the dry ingredients are incorporated; lumps are okay", "fix": "Cannot be fixed, but can be toasted and eaten as biscotti"}, {"symptom": "Frosting is runny", "likely_cause": "Mascarpone was overbeaten or too warm", "prevention": "Use chilled mascarpone and stop beating as soon as it holds shape", "fix": "Refrigerate for 30 minutes to firm up before spreading"}]', '["Ensure your tahini is well-stirred before measuring. The oil at the top of the jar is essential for the texture; dry, sludgy tahini from the bottom of the jar will make the cake dry.", "If your dates are very dry or hard, soak them in hot water for 10 minutes, then drain and pat thoroughly dry before chopping.", "The mascarpone adds a luxurious, milky flavor that is less acidic than pure cream cheese, which pairs beautifully with the subtle bitterness of tahini.", "For a warmer serving option, skip the frosting and serve the cake warm with a dollop of yogurt and a drizzle of honey."]', '"This cake borrows from the classic Middle Eastern flavor triad of sesame (tahini), dates, and honey/sugar. While banana bread is a Western staple, the substitution of butter with tahini creates a halva-like undertone that elevates the humble tea cake into a sophisticated dessert."', 447.46);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('33d1b55f-b202-4122-a58f-835f147ffb66', 'Mediterranean Roasted Cauliflower with Feta and Olives', 'Golden, caramelized cauliflower florets meet the salty tang of feta and brine-cured olives, finished with the crunch of toasted almonds. A vibrant, textural side dish that balances savory depth with bright Mediterranean flavors.', 'side dish', 'Mediterranean', 'Easy', '["vegetables", "almond", "cauliflower", "feta", "olive", "weeknight", "side dish", "fall", "spring", "winter", "christmas", "thanksgiving", "mediterranean", "gluten-free", "vegetarian"]', '[{"group_name": "Roasted Cauliflower", "items": [{"name": "cauliflower", "quantity": 1, "unit": null, "preparation": "cut into florets", "notes": "1 large head, approx. 800g-1kg", "substitutions": [], "ingredient_id": "2d9d5068-77e7-4dfc-b24b-8e6a6275cb33", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": "divided use", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx. 1/2 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Toppings & Assembly", "items": [{"name": "feta cheese", "quantity": 100, "unit": "g", "preparation": "crumbled", "notes": null, "substitutions": ["goat cheese", "vegan feta"], "ingredient_id": "a9a8605c-3bf2-4ca3-8c58-80e87aff7cd8", "nutrition_source": "USDA FoodData Central"}, {"name": "kalamata olives", "quantity": 60, "unit": "g", "preparation": "pitted and sliced", "notes": null, "substitutions": [], "ingredient_id": "a0555be5-08e9-4d8e-9c05-5f5063ebd6bc", "nutrition_source": "USDA FoodData Central"}, {"name": "sliced almonds", "quantity": 40, "unit": "g", "preparation": "raw", "notes": null, "substitutions": ["pine nuts", "walnuts"], "ingredient_id": "cc530a54-fc67-4fb1-8ece-569ae4388041", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh parsley", "quantity": 5, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": "freshly squeezed, about 1/2 lemon", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 220\u00b0C/425\u00b0F. High heat is essential for caramelization.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large bowl, toss the cauliflower florets with olive oil, kosher salt, black pepper, and dried oregano until evenly coated.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Spread the cauliflower in a single layer on a rimmed baking sheet. Ensure there is space between florets to avoid steaming.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT20M", "doneness_cues": {"visual": "Deep golden brown edges and tender stems", "tactile": null}}, "tips": ["Use two baking sheets if necessary to prevent overcrowding."]}, {"step_number": 4, "phase": "cook", "text": "While the cauliflower roasts, heat a small dry skillet over medium heat. Add the sliced almonds and toast, stirring constantly, until golden and fragrant (about 3-4 minutes). Remove from heat immediately.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Light golden brown color", "tactile": "Fragrant nutty aroma"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Roast the cauliflower for 20-25 minutes total, tossing halfway through, until tender and charred at the edges.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT25M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Transfer the hot roasted cauliflower to a serving dish. Immediately toss with the crumbled feta, sliced olives, toasted almonds, fresh parsley, and lemon juice.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Adding the feta while the cauliflower is hot helps it soften and meld with the other flavors."]}]', '{"active_time": "PT15M", "passive_time": "PT25M", "total_time": "PT40M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 220}', '{"flags": ["Vegetarian", "Gluten-Free", "Low-Carb", "Keto", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 298.62, "protein_g": 10.24, "carbohydrates_g": 15.81, "fat_g": 23.93, "saturated_fat_g": 5.89, "trans_fat_g": null, "monounsaturated_fat_g": 10.59, "polyunsaturated_fat_g": 1.5, "fiber_g": 6.23, "sugar_g": 4.81, "sodium_mg": 754.83, "cholesterol_mg": 22.25, "potassium_mg": 706.89, "calcium_mg": 220.3, "iron_mg": 2.79, "magnesium_mg": 67.86, "phosphorus_mg": 185.49, "zinc_mg": 1.39, "vitamin_a_mcg": 39.34, "vitamin_c_mg": 111.71, "vitamin_d_mcg": 0.1, "vitamin_e_mg": 2.15, "vitamin_k_mcg": 64.77, "vitamin_b6_mg": 0.52, "vitamin_b12_mcg": 0.42, "thiamin_mg": 0.15, "riboflavin_mg": 0.35, "niacin_mg": 1.44, "folate_mcg": 139.54, "water_g": 237.65, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Texture will soften upon reheating.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; cauliflower becomes mushy and feta texture degrades.", "duration": null}, "reheating": "Reheat in a 180\u00b0C/350\u00b0F oven for 5-10 minutes to restore crispness, or microwave briefly if texture is less important.", "does_not_keep": false}', '[{"name": "Large rimmed baking sheet", "required": true, "alternative": "Two smaller baking sheets"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Small skillet", "required": false, "alternative": "Baking sheet (for toasting almonds)"}]', '[{"symptom": "Cauliflower is mushy and pale instead of crispy", "likely_cause": "Overcrowding the baking sheet caused the vegetables to steam instead of roast", "prevention": "Ensure florets are in a single layer with air gaps between them; use two trays if needed", "fix": "Spread onto a second tray and return to oven on convection/fan mode for 5 minutes"}, {"symptom": "Almonds are burnt", "likely_cause": "Left unattended in the hot pan or oven", "prevention": "Watch nuts constantly while toasting; they go from raw to burnt in seconds", "fix": "Discard and re-toast a new batch; burnt nuts are unfixably bitter"}]', '["Cut the cauliflower florets into similar sizes (about 3-4cm) to ensure even cooking.", "For an extra depth of flavor, add a pinch of red chili flakes or lemon zest during the final toss.", "If you prefer a warm salad texture, allow the cauliflower to cool for 5 minutes before tossing with the feta to keep the cheese more distinct."]', '"This dish draws heavily from Eastern Mediterranean and Levantine cuisine, where the combination of salty cheese (feta/halloumi), rich olive oil, and bright citrus is a staple. Roasting vegetables to bring out their natural sweetness before pairing them with briny elements is a classic technique found in Greek and Turkish tables."', 298.62);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('33fcfbd5-208c-4a12-85dd-4f80ba240c47', 'Jeweled Cantaloupe & Celery Relish', 'A vibrant intersection of savory and sweet, featuring crisp celery, aromatic cantaloupe, and juicy grapes. Tossed in a sharp white balsamic vinaigrette with fresh mint, this raw relish offers a refreshing crunch that cuts through rich brunch dishes or grilled meats.', 'side dish', 'Modern American', 'Easy', '["cantaloupe", "celery", "grape", "brunch", "weeknight", "side dish", "summer", "raw", "vegan", "no-cook"]', '[{"group_name": "Produce Base", "items": [{"name": "cantaloupe", "quantity": 300, "unit": "g", "preparation": "small dice (0.5cm)", "notes": "firm, ripe melon holds shape best", "substitutions": [], "ingredient_id": "c3174cb9-d4cb-4497-890e-73f1325721e1", "nutrition_source": "USDA FoodData Central"}, {"name": "celery stalks", "quantity": 100, "unit": "g", "preparation": "brunoise (fine dice)", "notes": "approx. 2 large stalks, strings removed", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "red seedless grapes", "quantity": 150, "unit": "g", "preparation": "quartered lengthwise", "notes": null, "substitutions": [], "ingredient_id": "9e2140ae-bb3a-4780-b1b8-25f390658d9e", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 30, "unit": "g", "preparation": "minced", "notes": "about 1 medium shallot", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh mint leaves", "quantity": 10, "unit": "g", "preparation": "chiffonade", "notes": null, "substitutions": [], "ingredient_id": "17abecc0-a2a0-4478-8486-57b46e4305c9", "nutrition_source": "USDA FoodData Central"}, {"name": "jalape\u00f1o", "quantity": 15, "unit": "g", "preparation": "seeded and minced", "notes": "optional for heat, approx half a pepper", "substitutions": [], "ingredient_id": "4253d4ec-8462-43c6-963a-ae1f94367e2b", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Dressing", "items": [{"name": "white balsamic vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["apple cider vinegar", "champagne vinegar"], "ingredient_id": "767611a6-b108-4513-ae14-89e4de084388", "nutrition_source": "Aggregated Public Data"}, {"name": "extra virgin olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "036c7254-3de5-4c6e-a2e7-366ad4d05077", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon zest", "quantity": 3, "unit": "g", "preparation": null, "notes": "zest of half a lemon", "substitutions": [], "ingredient_id": "03fb65be-9b62-44e7-a121-694de64cdec0", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "flake salt preferred", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Wash all produce thoroughly. Peel the cantaloupe and remove seeds. Wash celery and grapes.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Precise knife work is crucial for the texture of this dish. Cut the cantaloupe into uniform 0.5cm cubes. Finely dice the celery (brunoise) to ensure it provides crunch without dominating the bite. Quarter the grapes lengthwise. Mince the shallot and jalape\u00f1o.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "assemble", "text": "In a large mixing bowl, combine the diced cantaloupe, celery, grapes, minced shallot, and jalape\u00f1o.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Add the white balsamic vinegar, olive oil, lemon zest, and salt. Gently toss to coat all ingredients evenly without bruising the fruit.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Allow the mixture to stand at room temperature for 20-30 minutes. This maceration period draws out juices and mellows the raw shallot. Just before serving, fold in the fresh mint chiffonade.", "structured": {"action": "REST", "temperature": {"celsius": 20, "fahrenheit": 68}, "duration": "PT30M", "doneness_cues": null}, "tips": ["Adding mint too early will cause it to brown from the vinegar''s acid."]}]', '{"active_time": "PT20M", "passive_time": "PT30M", "total_time": "PT50M", "overnight_required": false, "yields": "600g", "yield_count": 8, "serving_size_g": 75}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Paleo", "Whole30"], "not_suitable_for": []}', '{"per_serving": {"calories": 52.11, "protein_g": 0.74, "carbohydrates_g": 8.54, "fat_g": 2.03, "saturated_fat_g": 0.3, "trans_fat_g": null, "monounsaturated_fat_g": 0.01, "polyunsaturated_fat_g": 0.06, "fiber_g": 1.07, "sugar_g": 7.84, "sodium_mg": 165.04, "cholesterol_mg": null, "potassium_mg": 206.17, "calcium_mg": 18.17, "iron_mg": 0.46, "magnesium_mg": 10.66, "phosphorus_mg": 18.13, "zinc_mg": 0.14, "vitamin_a_mcg": 69.29, "vitamin_c_mg": 15.22, "vitamin_d_mcg": null, "vitamin_e_mg": 0.09, "vitamin_k_mcg": 7.78, "vitamin_b6_mg": 0.07, "vitamin_b12_mcg": null, "thiamin_mg": 0.04, "riboflavin_mg": 0.03, "niacin_mg": 0.37, "folate_mcg": 15.38, "water_g": 64.94, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Texture softens over time; drain excess liquid before serving leftovers.", "duration": "P3D"}, "freezer": {"notes": "Do not freeze; texture will be destroyed.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Microplane or Zester", "required": false, "alternative": "Small knife for mincing zest"}]', '[{"symptom": "Relish is too watery/soupy", "likely_cause": "Salt drew too much moisture out of the melon during resting", "prevention": "Serve immediately after resting time; do not over-macerate", "fix": "Use a slotted spoon to serve, leaving excess liquid behind (save the liquid for cocktail mixers)"}]', '["Uniformity is key: try to cut the cantaloupe and celery to consistent sizes so every spoonful has a balanced mix of flavors.", "The leftover liquid (''pot liquor'') is essentially a shrub. Mix it with gin or soda water for a refreshing bonus drink.", "If your cantaloupe is not very sweet, you can add 5ml of honey or agave syrup to the dressing to balance the vinegar.", "White balsamic is preferred over dark balsamic to keep the vibrant orange and green colors of the dish bright and unmuddy."]', '"While reminiscent of an Italian fruit ''mostarda'' or a Mexican ''pico de gallo'', this raw relish represents modern Californian cuisine\u2014focusing on seasonal produce, raw preparation, and the interplay of sweet and savory elements without heavy cooking."', 52.11);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('34752631-ec11-4560-94ca-2d3040504712', 'Rustic Plum & Almond Galette', 'A free-form French tart featuring a flaky, tender pastry crust encasing a layer of nutty almond frangipane and vibrant, tart-sweet seasonal plums. Infused with aromatic orange zest, this dessert balances richness with fresh summer acidity.', 'dessert', 'French', 'Intermediate', '["french", "plum", "dessert", "summer", "vegetarian", "halal", "kosher", "low-sodium", "healthy"]', '[{"group_name": "Almond Pastry Dough", "items": [{"name": "all-purpose flour", "quantity": 180, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "almond flour", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "chilled and cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "ice water", "quantity": 60, "unit": "ml", "preparation": null, "notes": "approximate, use just enough to bind", "substitutions": [], "ingredient_id": "de973e91-f602-4c8c-b99f-9aaf5b5ac726", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "just a pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Almond Frangipane Base", "items": [{"name": "almond flour", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "softened", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "orange zest", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "a644a589-02d1-4b90-98c5-ec79373a767b", "nutrition_source": "Aggregated Public Data"}, {"name": "all-purpose flour", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Fruit Filling & Assembly", "items": [{"name": "fresh plums", "quantity": 450, "unit": "g", "preparation": "pitted and sliced into wedges", "notes": "about 4-5 medium plums", "substitutions": [], "ingredient_id": "859da478-a8f2-4e69-8b67-30ea2524a9bd", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 15, "unit": "g", "preparation": null, "notes": "for sprinkling over fruit", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": "beaten", "notes": "approx 50g, for egg wash", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "demerara sugar", "quantity": 10, "unit": "g", "preparation": null, "notes": "coarse sugar for crust edge", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine flour, almond flour, sugar, and salt in a food processor. Pulse briefly to mix.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Add cold, cubed butter. Pulse until the mixture resembles coarse meal with pea-sized bits of butter remaining.", "structured": {"action": "MIX", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Coarse meal with pea-sized butter chunks", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Drizzle in ice water while pulsing just until the dough holds together when squeezed. Form into a disk, wrap in plastic, and refrigerate for at least 1 hour.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Prepare the frangipane by mixing softened butter, sugar, almond flour, 10g flour, and orange zest in a small bowl until a paste forms. Set aside.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Preheat your oven to 200\u00b0C (400\u00b0F). Line a baking sheet with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Roll the chilled dough out on a lightly floured surface into a rough circle about 30cm (12 inches) in diameter and 3mm thick. Transfer to the prepared baking sheet.", "structured": {"action": "ROLL", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Spread the frangipane mixture in the center of the dough, leaving a 4cm (1.5 inch) border clean.", "structured": {"action": "SPREAD", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Arrange the plum wedges in a decorative spiral or shingled pattern over the frangipane. Sprinkle the fruit with 15g of sugar.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "assemble", "text": "Fold the edges of the dough up and over the outer edge of the fruit, pleating as you go to create a rustic crust. The center of the tart remains open.", "structured": {"action": "SHAPE", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Brush the pastry border with the beaten egg and sprinkle with demerara sugar for crunch.", "structured": {"action": "GLAZE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 11, "phase": "cook", "text": "Bake for 35-45 minutes until the crust is deep golden brown and the fruit is tender and bubbling.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT40M", "doneness_cues": {"visual": "Deep golden brown crust, bubbling fruit juices", "tactile": null}}, "tips": []}, {"step_number": 12, "phase": "finish", "text": "Let cool on the baking sheet for at least 15 minutes to allow the filling to set before slicing.", "structured": {"action": "COOL", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT1H45M", "total_time": "PT2H20M", "overnight_required": false, "yields": "8 slices", "yield_count": 8, "serving_size_g": 135}', '{"flags": ["Vegetarian", "Low-Sodium", "Halal", "Kosher"], "not_suitable_for": ["Nut allergies", "Gluten intolerance"]}', '{"per_serving": {"calories": 346.03, "protein_g": 4.67, "carbohydrates_g": 47.65, "fat_g": 15.7, "saturated_fat_g": 9.41, "trans_fat_g": null, "monounsaturated_fat_g": 4.55, "polyunsaturated_fat_g": 0.82, "fiber_g": 1.8, "sugar_g": 21.01, "sodium_mg": 70.98, "cholesterol_mg": 62.22, "potassium_mg": 102.38, "calcium_mg": 20.01, "iron_mg": 0.99, "magnesium_mg": 11.58, "phosphorus_mg": 61.69, "zinc_mg": 0.38, "vitamin_a_mcg": 145.7, "vitamin_c_mg": 0.74, "vitamin_d_mcg": 0.13, "vitamin_e_mg": 0.66, "vitamin_k_mcg": 4.99, "vitamin_b6_mg": 0.04, "vitamin_b12_mcg": 0.09, "thiamin_mg": 0.06, "riboflavin_mg": 0.07, "niacin_mg": 0.6, "folate_mcg": 13.94, "water_g": 62.02, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Crust will lose crispness over time. Re-crisp in oven.", "duration": "P3D"}, "freezer": {"notes": "Freeze unbaked for best results. If baked, texture may suffer upon thawing.", "duration": "P2M"}, "reheating": "Warm in a 175\u00b0C (350\u00b0F) oven for 10-15 minutes to refresh the crust.", "does_not_keep": false}', '[{"name": "Food processor", "required": false, "alternative": "Pastry cutter and mixing bowl"}, {"name": "Rolling pin", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Microplane or Zester", "required": true, "alternative": null}]', '[{"symptom": "Soggy bottom crust", "likely_cause": "Plums released too much juice or oven floor heat was insufficient", "prevention": "Ensure the frangipane layer is spread evenly to absorb juices; bake on the lower rack of the oven", "fix": "Cover the top loosely with foil and bake for an extra 5-10 minutes on the lowest rack to crisp the bottom"}, {"symptom": "Pastry is tough rather than flaky", "likely_cause": "Dough was overworked or butter melted during handling", "prevention": "Keep ingredients very cold and handle the dough as little as possible", "fix": "Cannot be fixed after baking"}]', '["The almond flour in the dough reduces gluten formation, ensuring a more tender, ''short'' texture.", "If your plums are very tart, toss them with an extra tablespoon of sugar before arranging.", "The frangipane layer acts as a moisture barrier, preventing the plum juices from making the crust soggy.", "Chill the assembled galette for 10-15 minutes before baking if the dough feels soft; this helps it hold its shape in the oven."]', '"The galette is a staple of French country cooking (cuisine rustique), celebrated for its forgiving nature compared to formal tarts. While ''galette'' can refer to savory buckwheat cr\u00eapes in Brittany, this fruit-filled version highlights the French philosophy of prioritizing seasonal produce over intricate decoration."', 346.03);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('34ceb478-c4e3-44af-a0d2-7d64735cebab', 'Sausage and Broccoli Rabe Pizza on Bulgur Rustica Crust', 'A robust, textural twist on an Italian classic. The homemade dough incorporates soaked bulgur wheat for a nutty crunch that stands up to the savory fennel sausage and slightly bitter, garlic-infused broccoli rabe.', 'dinner', 'Italian', 'Intermediate', '["italian", "pizza", "sausage", "broccoli rabe", "dinner", "rustica", "whole grain"]', '[{"group_name": "Bulgur Rustica Dough", "items": [{"name": "bulgur wheat", "quantity": 50, "unit": "g", "preparation": "fine or medium grind", "notes": "dry weight", "substitutions": [], "ingredient_id": "c487e3f9-0a6f-4532-8b1e-06acff5fd6fc", "nutrition_source": "Aggregated Public Data"}, {"name": "boiling water", "quantity": 100, "unit": "ml", "preparation": null, "notes": "for soaking bulgur", "substitutions": [], "ingredient_id": "f6c955d4-a232-4b75-b391-c11f82b39685", "nutrition_source": "USDA FoodData Central"}, {"name": "warm water", "quantity": 180, "unit": "ml", "preparation": "40\u00b0C/105\u00b0F", "notes": "for yeast", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "active dry yeast", "quantity": 7, "unit": "g", "preparation": null, "notes": "1 standard packet", "substitutions": [], "ingredient_id": "b5658d19-b726-4ddb-b56e-74884c61e753", "nutrition_source": "USDA FoodData Central"}, {"name": "sugar", "quantity": 5, "unit": "g", "preparation": null, "notes": "to feed yeast", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "bread flour", "quantity": 350, "unit": "g", "preparation": null, "notes": "plus extra for dusting", "substitutions": [], "ingredient_id": "b3df44d9-3f17-4404-8315-336d6eb0900b", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "for dough", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 8, "unit": "g", "preparation": null, "notes": "fine sea salt", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Toppings", "items": [{"name": "italian sausage", "quantity": 250, "unit": "g", "preparation": "raw", "notes": "casings removed", "substitutions": [], "ingredient_id": "2ffe822c-daa1-413b-85d7-050f371656c3", "nutrition_source": "USDA FoodData Central"}, {"name": "broccoli rabe", "quantity": 300, "unit": "g", "preparation": "trimmed", "notes": "rapini", "substitutions": [], "ingredient_id": "8229dcea-493c-43eb-b888-737ecd27bcbf", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "thinly sliced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "low-moisture mozzarella cheese", "quantity": 200, "unit": "g", "preparation": "shredded", "notes": null, "substitutions": [], "ingredient_id": "41aca251-8bbe-492d-9539-ba0ac6c15194", "nutrition_source": "USDA FoodData Central"}, {"name": "pecorino romano", "quantity": 30, "unit": "g", "preparation": "finely grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "for drizzling/base", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "red chili flakes", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "cdb6f7a0-4167-42e8-ae15-b15e3bf9918f", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the dry bulgur wheat in a small bowl and pour the boiling water over it. Cover and let sit for 20-30 minutes until the water is absorbed and the grain is tender. Allow to cool to room temperature.", "structured": {"action": "MIX", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, combine warm water (approx 40\u00b0C/105\u00b0F), sugar, and active dry yeast. Let stand for 5-10 minutes until foamy.", "structured": {"action": "PROOF", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Add the cooled soaked bulgur, olive oil, and salt to the yeast mixture. Gradually mix in the bread flour until a shaggy dough forms. Knead on a floured surface for 8-10 minutes until smooth and elastic, though it will be slightly textured due to the grain.", "structured": {"action": "KNEAD", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Place dough in a lightly oiled bowl, cover with a damp cloth, and let rise in a warm place until doubled in size, about 1 hour.", "structured": {"action": "PROOF", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "While dough rises, bring a large pot of salted water to a boil. Blanch the broccoli rabe for 2 minutes, then drain and immediately rinse with cold water to stop cooking. Squeeze out excess moisture efficiently.", "structured": {"action": "BLANCH", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "In a skillet over medium heat, cook the Italian sausage, breaking it up with a spoon, until browned and cooked through (internal temp 74\u00b0C/165\u00b0F). Remove from heat.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": null, "doneness_cues": {"visual": "Browned and crumbled", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "prep", "text": "Preheat your oven to its highest setting (usually 250\u00b0C-260\u00b0C / 500\u00b0F). If using a pizza stone, place it in the oven now.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 260, "fahrenheit": 500}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Punch down the dough and divide into two balls. On a floured surface, stretch or roll each ball into a 30cm (12-inch) circle. The bulgur may make the edges slightly jagged; pinch any tears.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "assemble", "text": "Brush the dough base generously with olive oil and scatter the sliced garlic. Top evenly with mozzarella, cooked sausage, and blanched broccoli rabe. Sprinkle with Pecorino Romano and chili flakes.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "cook", "text": "Bake pizzas one at a time for 10-12 minutes, or until the crust is golden brown and cheese is bubbling and slightly browned spots appear.", "structured": {"action": "BAKE", "temperature": {"celsius": 260, "fahrenheit": 500}, "duration": "PT12M", "doneness_cues": {"visual": "Golden crust, bubbling cheese", "tactile": null}}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT1H30M", "total_time": "PT2H15M", "overnight_required": false, "yields": "2 medium pizzas (approx. 30cm)", "yield_count": 2, "serving_size_g": 200}', '{"flags": ["Egg-Free", "Soy-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": ["Gluten-Free diets", "Vegetarians (contains sausage)"]}', '{"per_serving": {"calories": 1738.89, "protein_g": 76.38, "carbohydrates_g": 158.78, "fat_g": 88.76, "saturated_fat_g": 29.14, "trans_fat_g": 0.87, "monounsaturated_fat_g": 43.17, "polyunsaturated_fat_g": 11.59, "fiber_g": 11.27, "sugar_g": 7.77, "sodium_mg": 3185.6, "cholesterol_mg": 160.45, "potassium_mg": 1063.67, "calcium_mg": 1134.96, "iron_mg": 17.41, "magnesium_mg": 164.06, "phosphorus_mg": 1181.12, "zinc_mg": 10.03, "vitamin_a_mcg": 519.55, "vitamin_c_mg": 32.65, "vitamin_d_mcg": 0.48, "vitamin_e_mg": 8.03, "vitamin_k_mcg": 356.49, "vitamin_b6_mg": 0.74, "vitamin_b12_mcg": 3.11, "thiamin_mg": 2.22, "riboflavin_mg": 2.04, "niacin_mg": 25.42, "folate_mcg": 576.92, "water_g": 421.04, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store slices in an airtight container. Reheat in a dry skillet or oven.", "duration": "P3D"}, "freezer": {"notes": "Wrap baked slices tightly in foil and plastic. Thaw before reheating.", "duration": "P1M"}, "reheating": "Reheat at 180\u00b0C/350\u00b0F for 5-7 minutes to restore crust crispness.", "does_not_keep": false}', '[{"name": "Small bowl", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Large pot", "required": true, "alternative": "Deep saucepan"}, {"name": "Skillet", "required": true, "alternative": "Frying pan"}, {"name": "Baking stone or steel", "required": false, "alternative": "Heavy baking sheet"}, {"name": "Pizza peel", "required": false, "alternative": "Back of a baking sheet/parchment paper"}]', '[{"symptom": "Pizza base is soggy", "likely_cause": "Broccoli rabe was not squeezed dry enough", "prevention": "After blanching and rinsing, wring out the greens tightly in a clean towel", "fix": "Bake for 2-3 extra minutes on the lowest rack"}, {"symptom": "Dough is too heavy/dense", "likely_cause": "Bulgur wasn''t fully hydrated before adding to flour", "prevention": "Ensure bulgur soaks for the full time and is soft before mixing", "fix": "Cannot be fixed after baking"}]', '["Squeezing the broccoli rabe is crucial; excess water will ruin the dough''s structural integrity.", "The bulgur adds a rustic texture similar to whole wheat but with a distinct chewiness; ensure it is cooled before adding to yeast to avoid killing the active culture.", "For a ''white pie'' approach, skip tomato sauce entirely; the garlic oil and fat from the sausage provide ample moisture.", "If you lack a pizza stone, bake on an inverted heavy baking sheet preheated in the oven for better crust bottom heat."]', '"This pairing of ''salsiccia e friarielli'' is a staple of Neapolitan cuisine, particularly in street food and sandwich culture. The addition of bulgur to the crust is a modern rustic variation, nodding to the ancient Roman use of cracked grains (''puls'') in early breads."', 1738.89);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('34e52f95-71c5-4073-a83f-ba5abed6be71', 'Italian Chicken Pastina Soup', 'A comforting, restorative bowl known as ''Italian Penicillin''. Tender poached chicken breast and tiny star-shaped pasta float in a golden, vegetable-rich broth. The soup is finished with a touch of lemon and parmesan for a silky mouthfeel and bright, savory finish.', 'soup', 'Italian', 'Easy', '["italian", "one pot", "chicken breast", "chicken soup", "orzo", "dinner", "easy", "lunch", "main course", "winter", "comfort food"]', '[{"group_name": "Base & Aromatics", "items": [{"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": "extra virgin", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "carrots", "quantity": 2, "unit": null, "preparation": "finely diced", "notes": "approx. 120g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "celery stalks", "quantity": 2, "unit": null, "preparation": "finely diced", "notes": "approx. 100g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Soup & Chicken", "items": [{"name": "chicken broth", "quantity": 1500, "unit": "ml", "preparation": "low sodium", "notes": null, "substitutions": [], "ingredient_id": "b7b1f4fd-8e57-472e-abae-d4f24d5b5c85", "nutrition_source": "Aggregated Public Data"}, {"name": "boneless skinless chicken breast", "quantity": 450, "unit": "g", "preparation": "whole", "notes": null, "substitutions": [], "ingredient_id": "2b577d04-33ca-4919-938f-bfc8780a3a4b", "nutrition_source": "USDA FoodData Central"}, {"name": "parmesan rind", "quantity": 1, "unit": null, "preparation": null, "notes": "optional, for flavor depth", "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "pastina", "quantity": 150, "unit": "g", "preparation": null, "notes": "stelline (stars) or orzo", "substitutions": ["orzo", "ditalini"], "ingredient_id": "62f1b505-be4d-49a8-9c61-783dd0672c21", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Finishing", "items": [{"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": "approx. half a lemon", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "parmesan cheese", "quantity": 30, "unit": "g", "preparation": "grated", "notes": "plus more for serving", "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Heat olive oil and butter in a large pot over medium heat. Once melted, add the diced onion, carrots, and celery. Saut\u00e9 until the vegetables are softened but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT6M", "doneness_cues": {"visual": "Onions are translucent", "tactile": "Vegetables are soft"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Add the minced garlic and cook for another minute until fragrant, being careful not to burn it.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Garlic is pale gold", "tactile": "Aromatic"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Pour in the chicken broth and add the Parmesan rind (if using). Increase heat to bring the liquid to a gentle boil.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the whole chicken breasts directly into the broth. Reduce heat to low, cover, and simmer gently until the chicken is fully cooked through with an internal temperature of 74\u00b0C/165\u00b0F.", "structured": {"action": "POACH", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT15M", "doneness_cues": {"visual": "Chicken is opaque", "tactile": "Internal temp 74\u00b0C"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Remove the chicken from the pot and set aside on a cutting board to rest. Remove and discard the Parmesan rind. Bring the broth back to a rolling boil.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Stir in the pastina (or orzo). Cook uncovered according to package directions (usually 6-8 minutes) until al dente.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": null, "tactile": "Pasta has a slight bite"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "While the pasta cooks, shred the chicken using two forks or dice it into bite-sized cubes. Return the chicken to the pot.", "structured": {"action": "SHRED", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Turn off the heat. Stir in the lemon juice, grated Parmesan cheese, and fresh parsley. Season with salt and black pepper to taste. Serve immediately.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT25M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 1710.02, "protein_g": 38.23, "carbohydrates_g": 225.32, "fat_g": 69.96, "saturated_fat_g": 25.38, "trans_fat_g": 0.11, "monounsaturated_fat_g": 8.54, "polyunsaturated_fat_g": 2.83, "fiber_g": 2.85, "sugar_g": 191.76, "sodium_mg": 51662.7, "cholesterol_mg": 85.5, "potassium_mg": 762.66, "calcium_mg": 188.57, "iron_mg": 3.03, "magnesium_mg": 44.48, "phosphorus_mg": 323.78, "zinc_mg": 1.36, "vitamin_a_mcg": 335.8, "vitamin_c_mg": 12.83, "vitamin_d_mcg": 0.49, "vitamin_e_mg": 1.25, "vitamin_k_mcg": 55.55, "vitamin_b6_mg": 0.75, "vitamin_b12_mcg": 0.49, "thiamin_mg": 0.12, "riboflavin_mg": 0.18, "niacin_mg": 11.65, "folate_mcg": 31.68, "water_g": 172.39, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Pasta will absorb broth over time; add splash of water or stock when reheating.", "duration": "P3D"}, "freezer": {"notes": "Texture of pasta may soften significantly upon thawing.", "duration": "P2M"}, "reheating": "Simmer gently on stove, adding liquid to adjust consistency.", "does_not_keep": false}', '[{"name": "Large Dutch oven or heavy-bottomed pot", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Soup has become thick and stew-like after sitting", "likely_cause": "The pastina continued to absorb broth while resting", "prevention": "Serve immediately or cook pasta separately if anticipating leftovers", "fix": "Stir in hot water or additional chicken broth to reach desired consistency"}, {"symptom": "Chicken is tough or dry", "likely_cause": "Chicken was boiled too vigorously instead of poached", "prevention": "Keep the heat low during the poaching step (Step 4); the liquid should barely bubble", "fix": "Dice the chicken very small to minimize the tough texture"}]', '["Cooking the pasta directly in the broth releases starch into the liquid, giving the soup a luxurious, silky texture without adding cream.", "If you prefer a golden hue and extra anti-inflammatory benefits, add 1/4 teaspoon of turmeric when saut\u00e9ing the vegetables.", "The parmesan rind is a secret weapon for umami; save rinds in your freezer specifically for brothy soups like this one.", "For the most authentic ''Italian Penicillin'' experience, cut the vegetables very small (brunoise) so they blend texturally with the tiny pastina."]', '"Known affectionately in Italy as ''minestrina'' or ''pastina in brodo'', this dish is the quintessential comfort food served to children and those feeling under the weather. It represents the Italian philosophy of healing through simple, digestible, and high-quality ingredients."', 1710.02);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('3559f65d-014e-4df1-aae7-a086be9deb13', 'Pan-Seared Sea Bass with Saffron Mussel Velouté', 'A refined composition featuring crispy-skinned sea bass fillets resting in a luxurious, saffron-infused creamy mussel broth. Accompanied by tender shaved courgette ribbons that add a delicate vegetal sweetness and textural contrast.', 'dinner', 'French', 'Advanced', '["sea bass", "mussels", "french", "fine dining", "gluten-free", "seafood", "dinner party"]', '[{"group_name": "Mussels & Velout\u00e9", "items": [{"name": "fresh mussels", "quantity": 500, "unit": "g", "preparation": "cleaned and debearded", "notes": "Discard any that do not close when tapped", "substitutions": [], "ingredient_id": "8724ea32-079e-407e-a9ae-1fe49557dc47", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "approx 30g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "smashed", "notes": null, "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 100, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 150, "unit": "ml", "preparation": null, "notes": "35% fat or higher", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "saffron threads", "quantity": 1, "unit": null, "preparation": null, "notes": "small pinch", "substitutions": [], "ingredient_id": "7f9ec0c8-2db1-48ac-a2c9-9b1efce12cf3", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sea Bass", "items": [{"name": "sea bass fillets", "quantity": 2, "unit": null, "preparation": "skin-on, descaled", "notes": "approx 140g each", "substitutions": [], "ingredient_id": "647f5154-7b54-476c-a330-9b215acbefc9", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "white pepper", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Courgette Ribbons", "items": [{"name": "courgette", "quantity": 2, "unit": null, "preparation": "washed", "notes": "approx 300g total", "substitutions": [], "ingredient_id": "c34b610f-8869-4d77-a9b3-e01849d703b5", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Using a mandoline or vegetable peeler, slice the courgettes lengthwise into long, thin ribbons. Avoid the very seedy center. Set aside.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In the large pot over medium-high heat, melt 15g butter. Saut\u00e9 the shallots and garlic for 2 minutes until softened but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Increase heat to high. Add the mussels and white wine. Cover tightly with a lid and steam for 3-4 minutes until mussels open. Discard any that remain closed.", "structured": {"action": "STEAM", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT4M", "doneness_cues": {"visual": "Shells are wide open", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Strain the mussels over a bowl to catch all the liquid (the fumet). Remove meat from shells and set aside (reserve a few in shells for garnish if desired). Discard shells and garlic.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Return the strained mussel liquid to the pot. Add saffron and simmer rapidly to reduce by half. Lower heat, stir in cream, and simmer gently until thickened slightly. Season with white pepper (salt likely unnecessary due to mussel brine). Keep warm.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Liquid coats the back of a spoon (nappe consistency)", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Pat sea bass skin extremely dry with paper towels. Season flesh side with salt. Score the skin lightly 3 times.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Heat olive oil in the non-stick skillet over medium-high heat until shimmering. Place fish skin-side down. Press firmly with a spatula for 30 seconds to prevent curling. Cook for 4-5 minutes until skin is crisp and golden. Do not move it.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Flip the fish. Cook for 1-2 minutes on the flesh side until internal temperature reaches 60\u00b0C/140\u00b0F. Remove from pan and rest.", "structured": {"action": "FRY", "temperature": {"celsius": 60, "fahrenheit": 140}, "duration": "PT2M", "doneness_cues": {"visual": null, "tactile": "Flesh flakes easily under gentle pressure"}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "While fish rests, wipe the skillet. Melt 10g butter over medium heat. Toss courgette ribbons with a splash of water and lemon juice for 60 seconds until pliable but still al dente. Add the reserved mussel meat to the warm soup to heat through.", "structured": {"action": "GLAZE", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "assemble", "text": "Ladle the frothy saffron mussel soup into shallow bowls. Arrange a nest of courgette ribbons in the center. Place the sea bass, skin-side up, atop the vegetables. Serve immediately.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT10M", "total_time": "PT55M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 450}', '{"flags": ["Pescatarian", "Gluten-Free", "Egg-Free", "Soy-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": ["Shellfish allergy"]}', '{"per_serving": {"calories": 879.57, "protein_g": 60.13, "carbohydrates_g": 20.85, "fat_g": 53.65, "saturated_fat_g": 26.49, "trans_fat_g": 0.93, "monounsaturated_fat_g": 17.11, "polyunsaturated_fat_g": 5.06, "fiber_g": 2.11, "sugar_g": 7.97, "sodium_mg": 1235.88, "cholesterol_mg": 239.03, "potassium_mg": 1689.49, "calcium_mg": 166.08, "iron_mg": 11.24, "magnesium_mg": 179.6, "phosphorus_mg": 880.93, "zinc_mg": 5.33, "vitamin_a_mcg": 593.22, "vitamin_c_mg": 50.35, "vitamin_d_mcg": 9.04, "vitamin_e_mg": 4.8, "vitamin_k_mcg": 14.79, "vitamin_b6_mg": 1.03, "vitamin_b12_mcg": 30.57, "thiamin_mg": 0.65, "riboflavin_mg": 0.98, "niacin_mg": 7.02, "folate_mcg": 157.29, "water_g": 514.13, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Seafood is best consumed immediately. Store soup and fish separately.", "duration": "P1D"}, "freezer": {"notes": "Cream-based soups and cooked white fish do not freeze well.", "duration": null}, "reheating": "Gently warm soup on stovetop. Reheat fish in a low oven to preserve skin texture.", "does_not_keep": false}', '[{"name": "Large heavy-bottomed pot", "required": true, "alternative": "Dutch oven"}, {"name": "Non-stick skillet", "required": true, "alternative": "Cast iron pan"}, {"name": "Fine mesh sieve", "required": true, "alternative": null}, {"name": "Mandoline", "required": true, "alternative": "Vegetable peeler"}, {"name": "Fish spatula", "required": true, "alternative": null}]', '[{"symptom": "Fish skin is soggy or stuck to pan", "likely_cause": "Skin was not dry enough or pan was not hot enough before adding fish", "prevention": "Scrape moisture off skin with a knife edge, pat with paper towel until bone-dry, ensure oil is shimmering", "fix": "Remove loose skin and serve flesh-side up (unfortunately loses the crispy texture)"}, {"symptom": "Soup is too salty", "likely_cause": "Mussel liquor was very saline and reduced too much", "prevention": "Taste the mussel liquor before reducing; dilute with a splash of water or unsalted stock if already very salty", "fix": "Add a splash of milk or more cream to dilute the salinity; squeeze of lemon juice helps balance it"}]', '["To achieve glass-like crispy skin, I recommend leaving the fish uncovered in the fridge for an hour before cooking to dry out the skin surface.", "Be very careful with salt in the soup base; mussels release ocean water which is naturally salty. Taste constantly.", "For an extra refined presentation, use an immersion blender to froth the soup just before serving (a technique called ''\u00e9cumer'').", "If using wild sea bass, the skin may be thicker; score it deeper to prevent curling during the sear."]', '"This dish draws heavily from the French coastal tradition of ''Mouclade'' (curried creamy mussels) but deconstructs it to highlight the sea bass. The combination of shellfish emulsion and white fish is a hallmark of Brittany and Normandy cuisine, celebrating the duality of the catch."', 879.57);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('35b72f66-31db-4435-a429-dfaecabff1d3', 'Crispy Zucchini and Feta Phyllo Tart', 'A sophisticated twist on white pizza featuring a shattering, multi-layered phyllo crust topped with a creamy ricotta-herb base, marinated zucchini ribbons, and charred red onions. The result is a textural masterpiece contrasting the crunch of pastry with the tenderness of summer squash.', 'dinner', 'Mediterranean', 'Intermediate', '["pizza and calzones", "green zucchini", "phyllo", "squash", "dinner", "lunch", "appetizer", "main course", "nut-free", "vegetarian"]', '[{"group_name": "Vegetable Prep", "items": [{"name": "green zucchini", "quantity": 350, "unit": "g", "preparation": "thinly sliced into rounds", "notes": "approx. 2 medium zucchini", "substitutions": [], "ingredient_id": "d0aa0d47-cefe-4ece-a337-e656f79b74e9", "nutrition_source": "Aggregated Public Data"}, {"name": "fine sea salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "for drawing out moisture", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "red onion", "quantity": 100, "unit": "g", "preparation": "very thinly sliced half-moons", "notes": null, "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Herb-Cheese Base", "items": [{"name": "whole milk ricotta", "quantity": 250, "unit": "g", "preparation": "strained if watery", "notes": null, "substitutions": [], "ingredient_id": "7a68dbea-ec03-42ae-b0eb-983bf3d4c7b6", "nutrition_source": "USDA FoodData Central"}, {"name": "feta cheese", "quantity": 100, "unit": "g", "preparation": "crumbled", "notes": null, "substitutions": [], "ingredient_id": "a9a8605c-3bf2-4ca3-8c58-80e87aff7cd8", "nutrition_source": "USDA FoodData Central"}, {"name": "parmesan cheese", "quantity": 30, "unit": "g", "preparation": "freshly grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh dill", "quantity": 5, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "4be2b047-475d-4c84-82d5-4883298c6121", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": null, "notes": "zest of 1 lemon", "substitutions": [], "ingredient_id": "03fb65be-9b62-44e7-a121-694de64cdec0", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "grated", "notes": "approx. 4g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": "beaten", "notes": "binder for cheese", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Phyllo Crust & Assembly", "items": [{"name": "phyllo dough sheets", "quantity": 10, "unit": null, "preparation": "thawed", "notes": "keep covered with damp towel", "substitutions": [], "ingredient_id": "c070937d-c91b-4f22-90f4-6ec707a13cd2", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 80, "unit": "ml", "preparation": "or melted unsalted butter", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Toss the sliced zucchini with the sea salt in a colander. Let sit for 15-20 minutes to draw out excess moisture. This step is critical to prevent a soggy crust.", "structured": {"action": "DRAIN", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Preheat your oven to 200\u00b0C (400\u00b0F). Ensure a rack is positioned in the center of the oven.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a mixing bowl, combine ricotta, crumbled feta, parmesan, chopped dill, lemon zest, grated garlic, and the beaten egg. Mix until thoroughly combined. Season with black pepper (salt is likely unnecessary due to the feta).", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Pat the salted zucchini slices very dry using a clean kitchen towel or paper towels. Press firmly to remove as much liquid as possible.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Lay one sheet of phyllo dough on a parchment-lined baking sheet. Brush lightly but completely with olive oil. Repeat this process, stacking 8-10 sheets on top of each other. Roll the edges inward slightly to create a 1-inch rustic crust border.", "structured": {"action": "LAMINATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Spread the cheese mixture evenly over the phyllo base, staying inside the rolled border. Arrange the dried zucchini slices and red onion half-moons in an overlapping shingled pattern on top of the cheese.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Bake for 20-25 minutes, or until the phyllo edges are deep golden brown and the zucchini is tender and slightly roasted. Rotate the pan halfway through cooking for even browning.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT25M", "doneness_cues": {"visual": "Deep golden brown edges, browned cheese spots", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from oven and let rest for 5 minutes to allow the filling to set. Slice into squares or wedges and serve warm.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT15M", "total_time": "PT45M", "overnight_required": false, "yields": "1 large tart (6 servings)", "yield_count": 6, "serving_size_g": 185}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Vegans (contains dairy)", "Gluten intolerant (contains wheat)"]}', '{"per_serving": {"calories": 334.45, "protein_g": 10.75, "carbohydrates_g": 18.47, "fat_g": 24.57, "saturated_fat_g": 8.04, "trans_fat_g": 0.14, "monounsaturated_fat_g": 12.93, "polyunsaturated_fat_g": 2.07, "fiber_g": 1.41, "sugar_g": 2.1, "sodium_mg": 734.01, "cholesterol_mg": 69.65, "potassium_mg": 169.39, "calcium_mg": 241.71, "iron_mg": 1.19, "magnesium_mg": 20.41, "phosphorus_mg": 193.2, "zinc_mg": 1.1, "vitamin_a_mcg": 97.78, "vitamin_c_mg": 2.16, "vitamin_d_mcg": 0.34, "vitamin_e_mg": 2.12, "vitamin_k_mcg": 9.75, "vitamin_b6_mg": 0.17, "vitamin_b12_mcg": 0.77, "thiamin_mg": 0.15, "riboflavin_mg": 0.4, "niacin_mg": 1.1, "folate_mcg": 33.33, "water_g": 70.26, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Phyllo will lose crispness; reheat in oven to restore texture.", "duration": "P2D"}, "freezer": {"notes": "Not recommended; zucchini releases too much water upon thawing.", "duration": null}, "reheating": "Reheat in a 180\u00b0C (350\u00b0F) oven for 10 minutes. Do not microwave.", "does_not_keep": false}', '[{"name": "Large baking sheet", "required": true, "alternative": null}, {"name": "Pastry brush", "required": true, "alternative": null}, {"name": "Mandoline or sharp chef''s knife", "required": true, "alternative": null}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Clean kitchen towel", "required": true, "alternative": "Paper towels"}]', '[{"symptom": "Phyllo crust is soggy", "likely_cause": "Zucchini released too much water during baking", "prevention": "Salt and drain zucchini longer, and squeeze very dry before assembling", "fix": "Bake on the bottom rack of the oven for an extra 5 minutes to crisp the bottom, or use a pizza stone"}]', '["Work quickly with the phyllo dough; keep the stack covered with a slightly damp towel while you work, as it dries out and becomes brittle in minutes.", "For an extra ''pizza'' flavor profile, add a pinch of dried oregano or red pepper flakes to the cheese mixture.", "Do not skip the egg in the cheese mixture; it stabilizes the ricotta so it doesn''t run out when the tart is sliced.", "If you have a pizza stone, preheat it and place the baking sheet directly on top of it for an even crispier bottom crust."]', '"While phyllo (filo) is traditionally associated with Greek spanakopita or baklava, this preparation borrows the concept of Italian ''pizza bianca'' (white pizza). It highlights the Mediterranean affinity for summer squash and fresh cheeses, serving as a lighter, flakier alternative to yeast-dough pizzas."', 334.45);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('35c8318a-75a9-4d10-a90b-412e7b40e4c4', 'Double Chocolate Peppermint Crunch Cookies', 'Intensely fudgy cookies featuring a masterful contrast of textures: crisp, chewy edges giving way to a soft, brownie-like interior. Studded with molten semisweet chocolate chunks and finished with the festive snap and cool resonance of crushed peppermint candies.', 'dessert', 'American', 'Intermediate', '["christmas cookie", "cocoa powder", "cookie", "make-ahead", "peppermint candy", "peppermint extract", "semisweet chocolate", "dessert", "winter", "christmas"]', '[{"group_name": "Wet Ingredients", "items": [{"name": "unsalted butter", "quantity": 225, "unit": "g", "preparation": "room temperature", "notes": "softened", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "dark brown sugar", "quantity": 200, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "white granulated sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "large, room temperature", "notes": "approx. 100g total without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "peppermint extract", "quantity": 3, "unit": "ml", "preparation": null, "notes": "adjust to taste, potency varies", "substitutions": [], "ingredient_id": "9825c0a6-9f41-4682-abe0-22c8a126da3d", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Dry Ingredients", "items": [{"name": "all-purpose flour", "quantity": 260, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "dutch-processed cocoa powder", "quantity": 60, "unit": "g", "preparation": null, "notes": "Dutch-process is crucial for fudgy texture and dark color", "substitutions": [], "ingredient_id": "c06a8e5a-163a-4f21-ad00-a6d90e34c38c", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Inclusions & Topping", "items": [{"name": "semisweet chocolate", "quantity": 250, "unit": "g", "preparation": "chopped chunks or chips", "notes": "reserve 50g for topping if desired", "substitutions": [], "ingredient_id": "3c3f1416-792f-41c8-9f23-d00d5149da29", "nutrition_source": "USDA FoodData Central"}, {"name": "peppermint candies or candy canes", "quantity": 60, "unit": "g", "preparation": "crushed", "notes": null, "substitutions": [], "ingredient_id": "dd9b7676-0289-41e4-93df-e6db3e03af57", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Sift the flour, cocoa powder, baking soda, and salt into a medium bowl to remove lumps and aerate.", "structured": {"action": "SIFT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In the bowl of a stand mixer fitted with the paddle attachment, cream the softened butter, brown sugar, and granulated sugar on medium-high speed until light and fluffy.", "structured": {"action": "CREAM", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Pale and aerated", "tactile": "Graininess significantly reduced"}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Add the eggs one at a time, mixing well after each addition. Mix in the vanilla and peppermint extracts.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Reduce mixer speed to low. Gradually add the dry ingredients, mixing only until streaks of flour disappear. Do not overmix.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": {"visual": "No dry flour pockets visible", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Fold in the semisweet chocolate chunks by hand using a spatula.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "Cover the dough and chill in the refrigerator for at least 1 hour (up to 72 hours). This solidifies the fat to prevent excessive spreading.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Preheat oven to 175\u00b0C/350\u00b0F. Line baking sheets with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Scoop dough into 45g balls (approx 2 tbsp) and place on baking sheets spaced 5cm apart. Bake until edges are set but centers remain soft.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT11M", "doneness_cues": {"visual": "Edges set, centers slightly puffy and underbaked", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Immediately upon removing from the oven, gently press the crushed peppermint candies into the tops of the soft cookies.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Adding candy after baking prevents the peppermint from melting and burning in the oven."]}, {"step_number": 10, "phase": "finish", "text": "Allow cookies to cool on the baking sheet for 5-10 minutes to set, then transfer to a wire rack to cool completely.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT1H15M", "total_time": "PT1H40M", "overnight_required": false, "yields": "24 cookies", "yield_count": 24, "serving_size_g": 48}', '{"flags": ["Vegetarian", "Nut-Free"], "not_suitable_for": ["Vegans", "Gluten Intolerant"]}', '{"per_serving": {"calories": 231.05, "protein_g": 2.74, "carbohydrates_g": 31.12, "fat_g": 11.36, "saturated_fat_g": 6.82, "trans_fat_g": 0.01, "monounsaturated_fat_g": 2.48, "polyunsaturated_fat_g": 0.42, "fiber_g": 1.97, "sugar_g": 19.51, "sodium_mg": 116.59, "cholesterol_mg": 35.99, "potassium_mg": 72.16, "calcium_mg": 20.26, "iron_mg": 0.94, "magnesium_mg": 16.35, "phosphorus_mg": 40.91, "zinc_mg": 0.31, "vitamin_a_mcg": 70.79, "vitamin_c_mg": null, "vitamin_d_mcg": 0.08, "vitamin_e_mg": 0.27, "vitamin_k_mcg": 0.76, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": 0.05, "thiamin_mg": 0.02, "riboflavin_mg": 0.03, "niacin_mg": 0.21, "folate_mcg": 5.94, "water_g": 6.75, "alcohol_g": 0.14, "caffeine_mg": 5.75}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in airtight container; texture is best at room temperature.", "duration": "P1W"}, "freezer": {"notes": "Freeze dough balls before baking for best results, or freeze baked cookies.", "duration": "P3M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Stand mixer or electric hand mixer", "required": true, "alternative": "Whisk and strong spatula"}, {"name": "Baking sheets", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": "Silicone baking mat"}, {"name": "Sieve or sifter", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}]', '[{"symptom": "Cookies spread too thin and are greasy", "likely_cause": "Butter was too warm/melted or dough wasn''t chilled long enough", "prevention": "Ensure butter is room temp (not melted) and chill dough for full hour", "fix": "Chill the remaining dough for another 30 minutes before baking the next batch"}]', '["For perfectly round cookies, place a large round cookie cutter over the hot cookie immediately after removing from the oven and swirl it gently to reshape the edges.", "Use Dutch-processed cocoa powder rather than natural cocoa; the lower acidity results in a darker color and fudgier texture.", "Crush the peppermint candy into varying sizes\u2014dust for distribution and larger shards for visual appeal and crunch.", "Do not skip the chilling step. The flour needs time to hydrate and the butter needs to resolidify to achieve the thick, chewy texture."]', '"Chocolate peppermint cookies are a staple of the modern American ''Christmas Cookie Box'' tradition, combining the European technique of butter-sugar creaming with the quintessential winter flavor pairing of dark chocolate and mint, popularized in the US in the mid-20th century."', 231.05);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('36706b29-8e57-4de1-97dd-a4fde2fecea5', 'Moroccan-Spiced Braised Pork Chops', 'Succulent bone-in pork chops rubbed with a warming blend of cumin, coriander, and cinnamon, seared to a golden crust, then gently braised in a savory, aromatic sauce of caramelized onions, garlic, and dried apricots. The result is tender meat balanced by sweet and tangy notes.', 'dinner', 'Fusion', 'Intermediate', '["pork chop", "dinner", "main course", "moroccan-inspired", "fusion", "braise", "one-pan"]', '[{"group_name": "Pork & Spice Rub", "items": [{"name": "bone-in pork chops", "quantity": 4, "unit": null, "preparation": "room temperature", "notes": "approx. 250g each, 2-3cm thick", "substitutions": [], "ingredient_id": "8a301973-01d1-48b5-94b8-c9a6c7df3a37", "nutrition_source": "Aggregated Public Data"}, {"name": "ground cumin", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "ground coriander", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "ground turmeric", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 6, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Braising Sauce", "items": [{"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "thinly sliced", "notes": "approx. 200g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "minced", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 10, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "chicken stock", "quantity": 250, "unit": "ml", "preparation": null, "notes": "sodium-free or low-sodium preferred", "substitutions": [], "ingredient_id": "8585fa9c-24ea-415d-9556-61af2f0f42c3", "nutrition_source": "USDA FoodData Central"}, {"name": "dried apricots", "quantity": 60, "unit": "g", "preparation": "halved", "notes": null, "substitutions": ["golden raisins", "prunes"], "ingredient_id": "804037f0-34fa-4bdd-b031-e9523a502430", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the pork chops dry with paper towels. In a small bowl, combine cumin, coriander, smoked paprika, cinnamon, turmeric, salt, and black pepper. Rub the spice mixture thoroughly over both sides of the pork chops.", "structured": {"action": "SEASON", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat the olive oil in a large skillet over medium-high heat. Once the oil is shimmering, add the pork chops. Sear for 3-4 minutes per side until a deep golden-brown crust forms. Remove chops from the pan and set aside on a plate (they will not be cooked through yet).", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT8M", "doneness_cues": {"visual": "Deep golden-brown crust", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to medium. Add the sliced onions to the same pan. Saut\u00e9 for 5-6 minutes, stirring frequently to pick up any browned bits (fond) from the bottom of the pan, until the onions are softened and beginning to brown.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT6M", "doneness_cues": {"visual": "Softened and translucent onions", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the minced garlic and grated ginger. Cook for 1 minute until fragrant, being careful not to burn the garlic.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Fragrant aromatics", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour in the chicken stock and lemon juice, scraping the bottom of the pan to fully deglaze. Stir in the dried apricots. Bring the liquid to a gentle simmer.", "structured": {"action": "DEGLAZE", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Return the pork chops and any accumulated juices to the pan, nestling them into the onion mixture. Cover the pan, reduce heat to low, and simmer for 10-15 minutes, or until the internal temperature of the thickest part of the chop reaches 63\u00b0C (145\u00b0F).", "structured": {"action": "BRAISE", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT15M", "doneness_cues": {"visual": "Internal temp 63\u00b0C/145\u00b0F", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove the pan from heat. Let the chops rest in the pan for 5 minutes. Garnish with fresh chopped cilantro before serving.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT25M", "total_time": "PT50M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Gluten-Free", "Dairy-Free", "Paleo", "Whole30", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 653.81, "protein_g": 52.61, "carbohydrates_g": 21.03, "fat_g": 39.89, "saturated_fat_g": 12.02, "trans_fat_g": 0.2, "monounsaturated_fat_g": 18.51, "polyunsaturated_fat_g": 5.97, "fiber_g": 3.74, "sugar_g": 11.49, "sodium_mg": 853.22, "cholesterol_mg": 159.38, "potassium_mg": 1158.07, "calcium_mg": 147.03, "iron_mg": 4.07, "magnesium_mg": 69.99, "phosphorus_mg": 583.15, "zinc_mg": 6.89, "vitamin_a_mcg": 124.99, "vitamin_c_mg": 6.88, "vitamin_d_mcg": 1.75, "vitamin_e_mg": 2.75, "vitamin_k_mcg": 7.47, "vitamin_b6_mg": 1.27, "vitamin_b12_mcg": 1.38, "thiamin_mg": 1.32, "riboflavin_mg": 0.88, "niacin_mg": 18.46, "folate_mcg": 16.19, "water_g": 283.54, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container with plenty of sauce to keep meat moist.", "duration": "P3D"}, "freezer": {"notes": "Texture of onions may soften further upon thawing.", "duration": "P2M"}, "reheating": "Reheat gently in a skillet over low heat with a splash of water or broth, covered, until warmed through.", "does_not_keep": false}', '[{"name": "Large heavy-bottomed skillet or braiser with lid", "required": true, "alternative": "Dutch oven"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Pork chops are dry and tough", "likely_cause": "Overcooked during the braising stage", "prevention": "Use a digital meat thermometer and remove from heat exactly when they reach 63\u00b0C (145\u00b0F); carryover cooking will finish them.", "fix": "Slice thinly and toss with extra sauce to mask dryness; cannot be fully reversed."}]', '["Patting the pork dry is crucial for a good sear. Moisture creates steam, which prevents the Maillard reaction (browning) that develops deep flavor.", "If using boneless chops, reduce the braising time by 3-5 minutes as they cook faster than bone-in cuts.", "For added complexity, a teaspoon of Harissa paste added with the garlic provides a lovely background heat.", "Serve this dish over couscous, quinoa, or roasted cauliflower to soak up the aromatic sauce."]', '"While pork is not traditional in Moroccan cuisine due to Islamic dietary laws, this fusion recipe borrows the region''s signature flavor profile\u2014mixing savory spices like cumin and coriander with the sweetness of dried fruit (often found in tagines)\u2014and applies it to a Western-style pork chop preparation."', 653.81);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('3698c0db-edd8-4d95-aff0-2668515ff845', 'Creamy Lemon and Fresh Chive Linguine', 'A vibrant and silky pasta dish where bright lemon zest cuts through rich heavy cream, finished with the delicate onion bite of fresh chives. This five-ingredient masterpiece balances acidity and creaminess for a sophisticated yet rapid weeknight dinner.', 'dinner', 'Italian', 'Easy', '["pasta", "vegetarian", "quick", "weeknight", "italian", "spring", "linguine"]', '[{"group_name": "Pasta Base", "items": [{"name": "linguine", "quantity": 450, "unit": "g", "preparation": "dried", "notes": "Spaghetti or fettuccine also work well", "substitutions": [], "ingredient_id": "52cdfe63-4362-4d80-9ed0-9fc7041f2721", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 4000, "unit": "ml", "preparation": null, "notes": "for boiling", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 30, "unit": "g", "preparation": null, "notes": "for pasta water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Lemon Cream Sauce", "items": [{"name": "heavy cream", "quantity": 240, "unit": "ml", "preparation": null, "notes": "minimum 35% fat", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": null, "notes": "zest and juice separated; approx 100g whole fruit", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "parmesan cheese", "quantity": 60, "unit": "g", "preparation": "finely grated", "notes": "plus extra for garnish", "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh chives", "quantity": 20, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Bring a large pot of salted water to a rolling boil. While waiting, zest the lemon completely and juice it, keeping the two separated. Finely chop the fresh chives.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add the linguine to the boiling water and cook for 1-2 minutes less than the package instructions for al dente. Reserve 120ml (approx. 1/2 cup) of starchy pasta water before draining.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT8M", "doneness_cues": null}, "tips": ["Undercooking the pasta is crucial as it will finish cooking in the sauce."]}, {"step_number": 3, "phase": "cook", "text": "About 3 minutes before the pasta is done, add the heavy cream and lemon zest to a large skillet over medium heat. Simmer gently until slightly thickened.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT3M", "doneness_cues": {"visual": "Cream bubbles gently and coats the back of a spoon", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Transfer the drained pasta directly into the skillet with the cream. Add half the reserved pasta water. Toss continuously with tongs over medium heat for 1 minute until the sauce clings to the noodles.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove the skillet from the heat. Immediately sprinkle in the grated parmesan and pour in the lemon juice. Toss vigorously to emulsify into a smooth, glossy sauce. Add more pasta water if the sauce looks too dry.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Adding lemon juice and cheese off the heat prevents the sauce from curdling or becoming grainy."]}, {"step_number": 6, "phase": "finish", "text": "Stir in the chopped chives and season with freshly cracked black pepper. Serve immediately.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT0M", "total_time": "PT15M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 419.06, "protein_g": 13.51, "carbohydrates_g": 31.49, "fat_g": 27.5, "saturated_fat_g": 16.5, "trans_fat_g": 0.75, "monounsaturated_fat_g": 7.17, "polyunsaturated_fat_g": 1.64, "fiber_g": 0.95, "sugar_g": 2.4, "sodium_mg": 3222.33, "cholesterol_mg": 124.13, "potassium_mg": 155.98, "calcium_mg": 262.96, "iron_mg": 1.79, "magnesium_mg": 41.58, "phosphorus_mg": 205.09, "zinc_mg": 1.11, "vitamin_a_mcg": 329.86, "vitamin_c_mg": 16.52, "vitamin_d_mcg": 1.03, "vitamin_e_mg": 0.63, "vitamin_k_mcg": 3, "vitamin_b6_mg": 0.11, "vitamin_b12_mcg": 0.39, "thiamin_mg": 0.22, "riboflavin_mg": 0.36, "niacin_mg": 1.52, "folate_mcg": 54.66, "water_g": 1138.73, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Sauce may thicken significantly; reheat gently with a splash of water.", "duration": "P3D"}, "freezer": {"notes": "Cream-based sauces tend to split when thawed.", "duration": null}, "reheating": "Warm in a pan over low heat with a splash of water or milk to re-emulsify the sauce.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": "Wok"}, {"name": "Microplane or fine grater", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "Sauce looks curdled or grainy", "likely_cause": "The acidity of the lemon juice reacted with the hot cream, or the heat was too high when adding cheese", "prevention": "Always remove the pan from heat before adding lemon juice and cheese", "fix": "Add a splash of reserved pasta water and whisk vigorously; the starch may help bring it back together"}, {"symptom": "Pasta is mushy", "likely_cause": "Overcooked in the boiling water before finishing in the sauce", "prevention": "Drain pasta 2 minutes before it is fully cooked", "fix": "Cannot be fixed"}]', '["Always grate your own parmesan. Pre-grated cheese contains anti-caking agents that prevent it from melting into a smooth emulsion.", "The starch in the pasta water is the secret ingredient; it acts as a binder between the water content in the lemon juice and the fat in the cream.", "For an extra layer of flavor, lightly toast whole peppercorns in a dry pan before crushing them for the garnish.", "If you want to use Cr\u00e8me Fra\u00eeche instead of heavy cream, skip the lemon juice as the cr\u00e8me fra\u00eeche already provides acidity."]', '"This dish is a variation of Pasta al Limone, a staple of Southern Italian cooking, particularly in the Amalfi Coast and Sicily where lemons grow in abundance. The addition of chives introduces a mild allium note common in modern continental cuisine, bridging the gap between a rustic Italian summer dish and a French cream sauce."', 419.06);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('3748754c-cf48-446f-833b-5c1c20ff9307', 'Pan-Seared Pork Chops with Apple & Tomato Pan Sauce', 'Juicy, golden-crusted pork chops rest beneath a vibrant medley of caramelized apples and blistered cherry tomatoes. The savory pan sauce brings together the tart sweetness of fruit with rich meat drippings for a perfectly balanced weeknight dinner.', 'dinner', 'American', 'Intermediate', '["apple", "pork chop", "tomato", "dinner", "weeknight", "main course", "american"]', '[{"group_name": "Pork", "items": [{"name": "bone-in pork chops", "quantity": 2, "unit": null, "preparation": "room temperature, thick-cut (2-3cm)", "notes": "approx. 250g each", "substitutions": ["boneless pork chops", "pork loin steaks"], "ingredient_id": "8a301973-01d1-48b5-94b8-c9a6c7df3a37", "nutrition_source": "Aggregated Public Data"}, {"name": "kosher salt", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["grapeseed oil", "canola oil"], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Aromatics & Produce", "items": [{"name": "apple", "quantity": 1, "unit": null, "preparation": "cored and sliced into 1cm wedges", "notes": "Granny Smith or Honeycrisp, approx. 180g", "substitutions": [], "ingredient_id": "9985672b-aa9f-4125-8a32-62d520c99d6f", "nutrition_source": "USDA FoodData Central"}, {"name": "cherry tomatoes", "quantity": 150, "unit": "g", "preparation": "whole", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx. 30g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx. 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 4, "unit": null, "preparation": "sprigs", "notes": "approx. 2g", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Pan Sauce", "items": [{"name": "apple cider vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["dry white wine"], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "chicken stock", "quantity": 120, "unit": "ml", "preparation": "unsalted or low sodium", "notes": null, "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the pork chops thoroughly dry with paper towels and season liberally on all sides with salt and black pepper.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Dry meat sears better; moisture creates steam which prevents browning."]}, {"step_number": 2, "phase": "cook", "text": "Heat vegetable oil in a large skillet over medium-high heat until shimmering. Carefully place the chops in the pan.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Sear the pork chops undisturbed until a deep golden-brown crust forms, approximately 4-5 minutes.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Deep golden brown crust", "tactile": "Release easily from pan"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Flip the chops and cook the other side until the internal temperature reaches 63\u00b0C/145\u00b0F at the thickest part.", "structured": {"action": "SEAR", "temperature": {"celsius": 63, "fahrenheit": 145}, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove pork chops from the pan and transfer to a plate to rest. Do not wipe out the pan.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Reduce heat to medium. Add apple wedges and minced shallot to the rendered pork fat. Saut\u00e9 until apples begin to brown and soften.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Add the cherry tomatoes, minced garlic, and thyme sprigs. Cook until the tomato skins begin to blister and burst.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Pour in the apple cider vinegar to deglaze, scraping up the browned bits (fond) from the bottom of the pan with a wooden spoon.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Add the chicken stock and simmer rapidly until the liquid reduces by half.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Remove pan from heat. Discard thyme stems. Swirl in the cold butter cubes until fully melted and emulsified into a glossy sauce.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Adding butter off-heat prevents the sauce from breaking/separating."]}, {"step_number": 11, "phase": "assemble", "text": "Return the pork chops and any accumulated resting juices to the pan, turning them once to coat in the sauce before serving.", "structured": {"action": "GLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT10M", "total_time": "PT35M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 350}', '{"flags": ["Gluten-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 755.49, "protein_g": 51.95, "carbohydrates_g": 20.49, "fat_g": 52, "saturated_fat_g": 19.41, "trans_fat_g": 0.2, "monounsaturated_fat_g": 15.8, "polyunsaturated_fat_g": 5.38, "fiber_g": 4.45, "sugar_g": 13.57, "sodium_mg": 3358.15, "cholesterol_mg": 189.75, "potassium_mg": 1090.28, "calcium_mg": 125.07, "iron_mg": 2.52, "magnesium_mg": 63.53, "phosphorus_mg": 566.43, "zinc_mg": 6.71, "vitamin_a_mcg": 122.95, "vitamin_c_mg": 18.15, "vitamin_d_mcg": 1.75, "vitamin_e_mg": 1.05, "vitamin_k_mcg": 4.84, "vitamin_b6_mg": 1.21, "vitamin_b12_mcg": 1.4, "thiamin_mg": 1.29, "riboflavin_mg": 0.82, "niacin_mg": 16.92, "folate_mcg": 8.96, "water_g": 277.05, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store pork and sauce in an airtight container.", "duration": "P3D"}, "freezer": {"notes": "Texture of tomatoes and apples may degrade slightly upon thawing.", "duration": "P2M"}, "reheating": "Reheat gently in a skillet over low heat with a splash of water or stock to prevent drying out.", "does_not_keep": false}', '[{"name": "Large stainless steel skillet or cast iron pan", "required": true, "alternative": "Non-stick pan (will produce less fond)"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Instant-read thermometer", "required": true, "alternative": null}]', '[{"symptom": "Pork chops are tough and dry", "likely_cause": "Overcooking beyond 63\u00b0C/145\u00b0F or failure to rest the meat", "prevention": "Use an instant-read thermometer and pull the meat exactly when it hits temp.", "fix": "Slice the meat very thinly against the grain and toss generously in the sauce to disguise dryness."}, {"symptom": "Sauce is greasy or separated", "likely_cause": "Butter was added while the pan was too hot", "prevention": "Remove pan from heat completely before swirling in cold butter.", "fix": "Whisk in a teaspoon of warm water or stock vigorously to re-emulsify."}]', '["Select bone-in pork chops for this recipe; the bone insulates the meat near it, keeping it juicier, and contributes flavor to the pan drippings.", "Do not overcrowd the pan during the searing step. If your pan is small, sear the chops one at a time to ensure they brown rather than steam.", "If using a stainless steel pan, the ''fond'' (browned bits stuck to the bottom) is the most critical flavor component. Ensure you scrape it all up during deglazing.", "Granny Smith apples provide a necessary tartness to cut through the rich pork fat, but Honeycrisp is a great alternative if you prefer a sweeter finish."]', '"Pork and apples is a timeless pairing rooted in Northern European and American agriculture, where the autumn harvest of apples coincides with traditional livestock processing. This iteration incorporates tomatoes, adding an umami-rich acidity typical of modern bistro cuisine."', 755.49);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('38686247-5ff5-4a65-be09-22b9ed3b9b34', 'Cheesy Wild Mushroom & Sweet Onion Quesadillas', 'Crispy golden tortillas filled with a savory mixture of finely chopped wild mushrooms and sweet caramelized onions, held together by a gooey blend of mild cheeses. The mushrooms are cooked down to a meaty, nutty consistency that appeals even to texture-sensitive eaters.', 'lunch', 'Mexican', 'Easy', '["mexican", "kid-friendly", "mushroom", "quesadilla", "brunch", "lunch", "quick"]', '[{"group_name": "Mushroom & Onion Filling", "items": [{"name": "mixed mushrooms", "quantity": 300, "unit": "g", "preparation": "cleaned and finely chopped", "notes": "Cremini, oyster, or shiitake mix", "substitutions": ["white button mushrooms", "portobello mushrooms"], "ingredient_id": "59d83971-a3c1-4b9c-b949-625005657048", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx. 1/2 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic powder", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx. 1/2 tsp, optional for milder taste", "substitutions": [], "ingredient_id": "177a312f-ef99-4398-9108-98f7a608a245", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Assembly", "items": [{"name": "flour tortillas", "quantity": 4, "unit": null, "preparation": null, "notes": "large (20-25cm diameter)", "substitutions": ["corn tortillas (for gluten-free)", "whole wheat tortillas"], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "monterey jack cheese", "quantity": 100, "unit": "g", "preparation": "shredded", "notes": null, "substitutions": [], "ingredient_id": "d43cedd3-da5c-4ca6-b806-8dc759a47a86", "nutrition_source": "Aggregated Public Data"}, {"name": "mild cheddar cheese", "quantity": 100, "unit": "g", "preparation": "shredded", "notes": null, "substitutions": [], "ingredient_id": "6cc08e49-8e1b-4065-be23-f57782560a8b", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 20, "unit": "g", "preparation": null, "notes": "for frying", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Clean the mushrooms and chop them very finely (almost like ground meat) to ensure a kid-friendly texture. Finely dice the onion.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat olive oil in a large skillet over medium heat (approx. 175\u00b0C/350\u00b0F). Add the onions and saut\u00e9 for 5-6 minutes until soft and translucent.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT6M", "doneness_cues": {"visual": "Onions are translucent and slightly golden", "tactile": "Soft with no crunch"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the chopped mushrooms, salt, and garlic powder to the skillet. Cook for 8-10 minutes, stirring occasionally, until all liquid released by the mushrooms has evaporated and they start to brown.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Pan is dry, mushrooms are deep brown", "tactile": "Mushrooms are slightly crispy, not soggy"}}, "tips": ["Evaporating the liquid is crucial to prevent soggy quesadillas."]}, {"step_number": 4, "phase": "prep", "text": "Remove the mushroom mixture from the pan and set aside in a bowl. Wipe the skillet clean carefully with a paper towel.", "structured": {"action": "REST", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Melt a small knob of butter in the skillet over medium-low heat. Place a tortilla in the pan. Sprinkle cheese over the whole tortilla, spread a thin layer of mushroom mixture on one half, then fold the tortilla over to close it.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Cook for 2-3 minutes per side until the tortilla is golden brown and crispy, and the cheese is fully melted. Repeat with remaining tortillas.", "structured": {"action": "FRY", "temperature": null, "duration": "PT6M", "doneness_cues": {"visual": "Golden brown spots on tortilla", "tactile": "Crispy exterior"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from pan and let cool for 1 minute before slicing into wedges. Serve warm.", "structured": {"action": "SERVE", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT0M", "total_time": "PT25M", "overnight_required": false, "yields": "4 quesadillas", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 490.78, "protein_g": 20.4, "carbohydrates_g": 47.11, "fat_g": 25.05, "saturated_fat_g": 12.69, "trans_fat_g": null, "monounsaturated_fat_g": 4, "polyunsaturated_fat_g": 1.08, "fiber_g": 4.13, "sugar_g": 2.25, "sodium_mg": 619.17, "cholesterol_mg": 10.75, "potassium_mg": 465.75, "calcium_mg": 411.19, "iron_mg": 10.16, "magnesium_mg": 43.12, "phosphorus_mg": 446.15, "zinc_mg": 3.63, "vitamin_a_mcg": 248.95, "vitamin_c_mg": 2.78, "vitamin_d_mcg": 3.83, "vitamin_e_mg": 0.7, "vitamin_k_mcg": 2.91, "vitamin_b6_mg": 0.18, "vitamin_b12_mcg": 0.01, "thiamin_mg": 0.14, "riboflavin_mg": 0.19, "niacin_mg": 2.37, "folate_mcg": 27.26, "water_g": 107.41, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container; texture will soften.", "duration": "P3D"}, "freezer": {"notes": "Freeze separated by parchment paper.", "duration": "P1M"}, "reheating": "Reheat in a dry skillet over medium heat to restore crispness, or air fry at 180\u00b0C for 3-4 minutes.", "does_not_keep": false}', '[{"name": "Large skillet or griddle", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Spatula", "required": true, "alternative": null}, {"name": "Box grater", "required": false, "alternative": "Pre-shredded cheese"}]', '[{"symptom": "Quesadillas are soggy", "likely_cause": "Mushrooms were not cooked long enough to release their water", "prevention": "Cook mushrooms until the pan is completely dry and they begin to sizzle/fry in their own oil", "fix": "Place finished quesadillas on a wire rack in a 180\u00b0C oven for 5 minutes to crisp up"}]', '["Finely chopping the mushrooms mimics the texture of ground meat, making this an excellent ''gateway'' vegetable dish for children.", "Using a blend of Monterey Jack (for melting) and Cheddar (for flavor) ensures the quesadilla holds together while tasting delicious.", "If serving to very selective eaters, you can puree the mushroom mixture into a smooth paste to hide the texture completely.", "Serve with mild salsa, sour cream, or guacamole for dipping to add extra fun for kids."]', '"While the quesadilla is a staple of Mexican cuisine traditionally made with corn masa, the flour tortilla version filled with melting cheese (Quesadilla Sincronizada style) has become a beloved comfort food globally. This version incorporates wild mushrooms (hongos), a common filling in central Mexican quesadillas."', 490.78);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('389c91d6-1ffa-4d29-a76f-be34b98d0773', 'Caramelized Whole Roasted Garlic', 'Whole heads of garlic slow-roasted until the cloves transform into a sweet, golden, buttery paste. The harsh bite of raw garlic vanishes, replaced by a deep, nutty mellowness perfect for spreading on crusty bread or enriching mashed potatoes.', 'condiment', 'Mediterranean', 'Easy', '["condiments", "dips and spreads", "garlic", "olive oil", "roasted", "base", "vegetarian", "gluten-free"]', '[{"group_name": "Garlic", "items": [{"name": "whole garlic heads", "quantity": 4, "unit": null, "preparation": "intact", "notes": "approx 200-240g total weight", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "approx 1 tsp per head", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "flaky sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "large pinch per head", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme sprigs", "quantity": 4, "unit": null, "preparation": null, "notes": "one per packet", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 200\u00b0C (400\u00b0F). Position a rack in the center of the oven.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Remove the loose, papery outer layers from the garlic bulbs, leaving the skins of the individual cloves intact so the head holds together. Using a sharp knife, slice 5-10mm off the top of each head to expose the tops of the raw cloves.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Place the garlic heads on squares of aluminum foil (one square per head). Drizzle the olive oil generously over the exposed cloves, allowing it to seep down between them. Season with flaky sea salt and top with a sprig of thyme if using.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Gather the corners of the foil and twist tightly to create sealed parcels. Place these parcels on a baking sheet and roast for 40 to 50 minutes. The garlic is done when the cloves are completely soft and yield easily to a gentle squeeze.", "structured": {"action": "ROAST", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT45M", "doneness_cues": {"visual": "Cloves are deep golden brown", "tactile": "Cloves feel like soft butter when squeezed"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove from the oven and carefully open the foil packets (beware of hot steam). Let the garlic cool for at least 10 minutes until safe to handle. To serve or store, squeeze the bottom of the bulb to push the caramelized cloves out of their skins.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT5M", "passive_time": "PT45M", "total_time": "PT50M", "overnight_required": false, "yields": "4 heads", "yield_count": 4, "serving_size_g": 30}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Keto", "Paleo", "Whole30", "Low-Sodium", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 149.76, "protein_g": 3.58, "carbohydrates_g": 18.57, "fat_g": 7.8, "saturated_fat_g": 1.09, "trans_fat_g": null, "monounsaturated_fat_g": 5.48, "polyunsaturated_fat_g": 0.93, "fiber_g": 1.37, "sugar_g": 0.55, "sodium_mg": 203.64, "cholesterol_mg": null, "potassium_mg": 229.8, "calcium_mg": 105.82, "iron_mg": 1.24, "magnesium_mg": 16.16, "phosphorus_mg": 85.74, "zinc_mg": 0.67, "vitamin_a_mcg": 3.57, "vitamin_c_mg": 19.56, "vitamin_d_mcg": null, "vitamin_e_mg": 1.13, "vitamin_k_mcg": 5.45, "vitamin_b6_mg": 0.69, "vitamin_b12_mcg": null, "thiamin_mg": 0.11, "riboflavin_mg": 0.07, "niacin_mg": 0.41, "folate_mcg": 2.33, "water_g": 33.21, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Squeeze cloves out of skins and store in an airtight container submerged in olive oil. WARNING: Do not store at room temperature due to botulism risk.", "duration": "P2W"}, "freezer": {"notes": "Freeze individual cloves on a tray, then transfer to a bag, or freeze the paste in ice cube trays.", "duration": "P3M"}, "reheating": "Not required, but can be warmed gently in a pan if used as a spread.", "does_not_keep": false}', '[{"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Aluminum foil", "required": true, "alternative": "Oven-safe ramekin with lid or parchment paper inside foil"}, {"name": "Baking sheet", "required": true, "alternative": null}]', '[{"symptom": "Cloves are hard or rubbery", "likely_cause": "Undercooked; oven temperature too low or heads were very large", "prevention": "Test doneness by squeezing (with a towel) before removing from oven", "fix": "Reseal foil and return to oven for 10-15 minute increments"}, {"symptom": "Garlic is burnt or bitter", "likely_cause": "Oven too hot or foil seal was broken allowing moisture to escape", "prevention": "Ensure foil is sealed tight to steam the garlic while it roasts", "fix": "Discard burnt tops; scoop out the softer bottom parts if salvageable. Otherwise, cannot be fixed."}]', '["Safety First: Never store roasted garlic in oil at room temperature. This creates an anaerobic environment perfect for botulism bacteria. Always refrigerate immediately.", "Flavor Maximization: For a deeper, more caramelized flavor, open the foil packets for the last 10 minutes of roasting to brown the tops.", "Usage: Mash this paste into butter for instant garlic bread, whisk into vinaigrettes for a creamy emulsifier, or stir into mashed potatoes for rich depth without the spicy bite of raw garlic.", "Waste Reduction: Don''t throw away the oil left in the foil packets; it is essentially ''roasted garlic oil'' and is delicious dripped over vegetables."]', '"Roasting whole heads of garlic is a staple technique in Mediterranean cuisine, particularly in Provence and Italy, where garlic is treated as a vegetable rather than just a spice. The slow cooking process breaks down allicin, the compound responsible for garlic''s pungency, converting it into sweet, complex sugars."', 149.76);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('3a87b74c-8cde-4882-aa63-63447591188a', 'Olive Oil & Sea Salt Lemon Bars', 'A refined evolution of the classic tart, balancing sharp, aromatic lemon curd against a grassy, rich olive oil shortbread. Finished with flaky sea salt to accentuate the citrus acidity and buttery undertones.', 'dessert', 'American', 'Intermediate', '["bar cookie", "lemon", "snack", "dessert", "thanksgiving", "citrus", "fusion"]', '[{"group_name": "Olive Oil Shortbread Crust", "items": [{"name": "all-purpose flour", "quantity": 170, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "confectioners'' sugar", "quantity": 45, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 85, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "use a high-quality fruity oil", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Lemon Olive Oil Curd", "items": [{"name": "large eggs", "quantity": 4, "unit": null, "preparation": "room temperature", "notes": "approx. 200g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "granulated sugar", "quantity": 250, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 10, "unit": "g", "preparation": null, "notes": "from about 3 lemons", "substitutions": [], "ingredient_id": "a5fb6a2a-dcda-4ab2-8fe6-472d7fcc39d1", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh lemon juice", "quantity": 120, "unit": "ml", "preparation": "strained", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 30, "unit": "g", "preparation": null, "notes": "for thickening", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "flaky sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "Maldon or similar, for finishing", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "confectioners'' sugar", "quantity": null, "unit": null, "preparation": null, "notes": "for dusting", "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 175\u00b0C (350\u00b0F). Line a 23cm (9-inch) square baking pan with parchment paper, leaving an overhang on two sides for easy removal.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "For the crust: In a large bowl or stand mixer, combine 170g flour, 45g confectioners'' sugar, and 3g fine sea salt. Add the cold cubed butter and 30ml olive oil.", "structured": {"action": "MEASURE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Mix on low speed or rub with fingertips until the mixture resembles coarse, damp sand. It should hold together when clumped but remain crumbly.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Coarse damp sand texture", "tactile": "Clumps when pressed"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Press the crust mixture firmly and evenly into the bottom of the prepared pan. Bake for 20 minutes or until the edges are lightly golden brown.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT20M", "doneness_cues": {"visual": "Lightly golden edges", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "While the crust bakes, prepare the filling. Whisk together eggs and granulated sugar until well combined. Whisk in the 30g flour, lemon zest, lemon juice, and 15ml olive oil until smooth and emulsified.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Pour the filling directly onto the hot crust immediately after taking it out of the oven. This helps seal the crust and prevents sogginess.", "structured": {"action": "POUR", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Return the pan to the oven. Bake for 20-25 minutes, or until the center is set but still jiggles slightly like firm gelatin when the pan is nudged.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT25M", "doneness_cues": {"visual": "Center jiggles slightly, edges set", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from oven and allow to cool completely at room temperature on a wire rack (about 1-2 hours). Then, refrigerate for at least 1 hour to fully set before cutting.", "structured": {"action": "COOL", "temperature": null, "duration": "PT2H", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Lift the bars out using the parchment overhang. Dust lightly with confectioners'' sugar if desired, then slice into 16 squares. Sprinkle generously with flaky sea salt immediately before serving.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT3H", "total_time": "PT3H30M", "overnight_required": false, "yields": "16 bars", "yield_count": 16, "serving_size_g": 65}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 203.33, "protein_g": 2.94, "carbohydrates_g": 29.62, "fat_g": 8.45, "saturated_fat_g": 3.49, "trans_fat_g": 0.01, "monounsaturated_fat_g": 3.77, "polyunsaturated_fat_g": 0.75, "fiber_g": 0.43, "sugar_g": 19.56, "sodium_mg": 140.23, "cholesterol_mg": 57.92, "potassium_mg": 41.07, "calcium_mg": 11.73, "iron_mg": 0.41, "magnesium_mg": 4.9, "phosphorus_mg": 40.2, "zinc_mg": 0.26, "vitamin_a_mcg": 56.36, "vitamin_c_mg": 3.71, "vitamin_d_mcg": 0.25, "vitamin_e_mg": 0.68, "vitamin_k_mcg": 2.14, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": 0.12, "thiamin_mg": 0.02, "riboflavin_mg": 0.07, "niacin_mg": 0.18, "folate_mcg": 10.87, "water_g": 19.32, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container to prevent absorbing fridge odors.", "duration": "P5D"}, "freezer": {"notes": "Freeze cut bars without salt garnish; thaw in fridge overnight.", "duration": "P3M"}, "reheating": null, "does_not_keep": false}', '[{"name": "23x23cm (9x9 inch) baking pan", "required": true, "alternative": "20x20cm (8x8 inch) pan (increase bake time slightly)"}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Stand mixer or hand mixer", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Fine mesh sieve", "required": false, "alternative": "Cheesecloth"}, {"name": "Zester or microplane", "required": true, "alternative": null}]', '[{"symptom": "Filling has a white, foamy layer on top", "likely_cause": "Over-aeration of the eggs during mixing", "prevention": "Whisk ingredients just until combined rather than beating them vigorously", "fix": "Dust heavily with confectioners'' sugar to hide the texture"}, {"symptom": "Crust is soggy", "likely_cause": "Filling was poured onto a cool crust", "prevention": "Always pour the lemon filling onto the crust while the crust is piping hot from the oven", "fix": "Cannot be fixed"}]', '["The quality of olive oil matters immensely here. Use a fresh, grassy Extra Virgin Olive Oil for the best contrast with the lemon.", "Pouring the filling onto the hot crust is a professional technique that ''seals'' the shortbread, preventing the liquid filling from soaking in.", "For the cleanest cuts, wipe your knife with a warm, damp cloth between every single slice.", "If you prefer a sharper curd, reduce the sugar in the filling by 25g, but note this will slightly alter the texture."]', '"While the lemon bar is a quintessential 20th-century American bake sale staple (popularized by a 1963 Chicago Tribune recipe), this iteration borrows from Mediterranean dessert traditions where olive oil and citrus are frequently paired, offering a more complex, savory-sweet profile suitable for modern palates."', 203.33);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('3ae2648c-908f-4114-b1d5-20273d728cf3', 'Spiced Mango and Date Chutney', 'A vibrant, sticky condiment offering a kaleidoscope of flavors: the tropical sweetness of ripe mangoes contrasts with the sharp tang of cider vinegar, the earthy sweetness of dates, and a heavy hand of warming spices. The texture balances between jammy and chunky, customizable to your preference.', 'condiment', 'Indian', 'Easy', '["condiments", "cider vinegar", "date", "garlic", "ginger", "mango", "mustard oil", "red pepper flake", "south asian", "stovetop", "vegan"]', '[{"group_name": "Fresh Aromatics & Fruit", "items": [{"name": "ripe mangoes", "quantity": 3, "unit": null, "preparation": "peeled, pitted, and diced (approx. 600g flesh)", "notes": "Alphonso or Honey mangoes are best", "substitutions": [], "ingredient_id": "6ab51d7d-dea3-4f14-8253-76acb67bd2c8", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 25, "unit": "g", "preparation": "finely grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx. 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Spices & Oil", "items": [{"name": "mustard oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["grapeseed oil", "vegetable oil"], "ingredient_id": "71a6eb9b-27fb-43d3-8e41-394612198076", "nutrition_source": "USDA FoodData Central"}, {"name": "whole nigella seeds (kalonji)", "quantity": 1, "unit": null, "preparation": null, "notes": "approx. 3g (1 tsp)", "substitutions": [], "ingredient_id": "75bffc23-976f-4af7-9dba-740b605b5248", "nutrition_source": "Aggregated Public Data"}, {"name": "whole cumin seeds", "quantity": 1, "unit": null, "preparation": null, "notes": "approx. 3g (1 tsp)", "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "Aggregated Public Data"}, {"name": "whole fennel seeds", "quantity": 1, "unit": null, "preparation": null, "notes": "approx. 3g (1 tsp)", "substitutions": [], "ingredient_id": "4251d6cd-aa2f-41d7-ad78-02d98bfbaeea", "nutrition_source": "Aggregated Public Data"}, {"name": "red pepper flakes", "quantity": 2, "unit": null, "preparation": null, "notes": "approx. 4g, adjust for heat", "substitutions": [], "ingredient_id": "bd455fb1-7139-4b89-bec6-5432272a6646", "nutrition_source": "Aggregated Public Data"}, {"name": "ground turmeric", "quantity": 2, "unit": null, "preparation": null, "notes": "approx. 2g (1/2 tsp)", "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sweet & Sour Base", "items": [{"name": "apple cider vinegar", "quantity": 120, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "brown sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": ["jaggery", "white sugar"], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "dates", "quantity": 60, "unit": "g", "preparation": "pitted and roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "657c170c-11cc-41f7-a980-050a218a088e", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Peel the mangoes and cut the flesh into 1-2 cm cubes. Discard the pits. Peel and mince the garlic; peel and grate the ginger. Chop the dates into small pieces.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a heavy-bottomed saucepan over medium-high heat, heat the mustard oil until it just begins to smoke (approx. 200\u00b0C/390\u00b0F) to remove the raw pungency. Immediately turn off the heat and let it cool for 30 seconds to prevent burning the spices.", "structured": {"action": "HEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Turn the heat back to low. Add the nigella, cumin, and fennel seeds. Stir gently until they crackle and release their aroma, about 30 to 60 seconds. Do not burn.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the grated ginger, minced garlic, and red pepper flakes. Saut\u00e9 for 1 minute until fragrant but not browned. Stir in the ground turmeric.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the chopped mangoes, dates, brown sugar, salt, and apple cider vinegar. Stir well to combine all ingredients.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Bring the mixture to a boil over medium heat, then reduce heat to low to maintain a gentle simmer. Cook uncovered, stirring occasionally to prevent sticking, for 40 to 50 minutes.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT45M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "The chutney is done when it is thick, sticky, and most of the liquid has evaporated. The mango pieces should be translucent. If you prefer a smoother texture, mash some fruit with the back of the spoon against the pot.", "structured": {"action": "REDUCE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Thick, glossy, jam-like consistency", "tactile": "Coats back of spoon"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from heat and let cool completely in the pan. The mixture will thicken further as it cools. Transfer to sterilized glass jars.", "structured": {"action": "COOL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT50M", "total_time": "PT1H15M", "overnight_required": false, "yields": "600ml (approx. 2 jars)", "yield_count": 20, "serving_size_g": 30}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 64.59, "protein_g": 0.49, "carbohydrates_g": 12.53, "fat_g": 1.76, "saturated_fat_g": 0.21, "trans_fat_g": null, "monounsaturated_fat_g": 0.97, "polyunsaturated_fat_g": 0.35, "fiber_g": 0.88, "sugar_g": 11.02, "sodium_mg": 102.18, "cholesterol_mg": null, "potassium_mg": 104.51, "calcium_mg": 16.77, "iron_mg": 0.36, "magnesium_mg": 7.73, "phosphorus_mg": 12.09, "zinc_mg": 0.08, "vitamin_a_mcg": 17.3, "vitamin_c_mg": 11.39, "vitamin_d_mcg": null, "vitamin_e_mg": 0.28, "vitamin_k_mcg": 1.38, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.02, "niacin_mg": 0.29, "folate_mcg": 13.6, "water_g": 32.85, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Keep in a sterilized, airtight jar. Always use a clean spoon.", "duration": "P1M"}, "freezer": {"notes": "Texture may become slightly softer upon thawing.", "duration": "P3M"}, "reheating": "Serve at room temperature.", "does_not_keep": false}', '[{"name": "Heavy-bottomed saucepan", "required": true, "alternative": "Dutch oven"}, {"name": "Wooden spoon", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Glass jars with lids", "required": true, "alternative": null}]', '[{"symptom": "Chutney is too runny after cooling", "likely_cause": "Insufficient evaporation of vinegar or water content from fruit", "prevention": "Simmer for the full duration until the bottom of the pan is visible when scraping a spoon through", "fix": "Return to pot and simmer on low heat for another 10-15 minutes"}]', '["Mustard oil is traditional and provides a unique wasabi-like punch, but it must be heated to smoking point first. If unavailable or too strong, neutral oil works fine.", "The sweetness of mangoes varies wildly. Taste your fruit first; if very sweet, reduce sugar by 20g; if tart, add 20g more.", "For the best flavor development, let the chutney sit in the jar for at least 24 hours before eating to allow the spices and vinegar to meld.", "If you cannot find whole nigella (kalonji) seeds, you can use black sesame seeds for visual similarity, though the onion-like flavor will be missing."]', '"This recipe draws from the Indian tradition of sweet and sour chutneys (khatte-meethe), often served as a condiment to cut through rich curries or fried snacks. While traditional recipes might use sugarcane vinegar or malt vinegar, this version utilizes apple cider vinegar for a fruity acidity that complements the mango."', 64.59);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('3ae39086-eaad-477b-b76f-ff4ced41d2fc', 'Gambas au Cognac (Shrimp in Creamy Cognac Sauce)', 'Succulent large shrimp enveloped in a velvety, ivory-hued sauce rich with heavy cream and the complex, caramel-oak notes of Cognac. A classic French bistro indulgence balanced by a hint of tomato and fresh lemon acidity.', 'dinner', 'French', 'Intermediate', '["french", "seafood", "date night", "gluten-free", "cream sauce", "shrimp", "dinner"]', '[{"group_name": "Seafood", "items": [{"name": "large shrimp", "quantity": 500, "unit": "g", "preparation": "peeled and deveined, tail-on optional", "notes": "16-20 count size preferred", "substitutions": [], "ingredient_id": "a6bf7ab3-9b88-4c5b-a2fa-966c40a0e5a7", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics & Fat", "items": [{"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "divided", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "approx 30g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sauce", "items": [{"name": "cognac", "quantity": 60, "unit": "ml", "preparation": null, "notes": "or high-quality brandy", "substitutions": [], "ingredient_id": "db4bfda4-18fd-4428-a410-465e89398474", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 180, "unit": "ml", "preparation": "35% fat or higher", "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "tomato paste", "quantity": 15, "unit": "g", "preparation": null, "notes": "adds depth and color", "substitutions": [], "ingredient_id": "41400e7f-7a06-42d2-a625-072c380d60b2", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 5, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 3g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the shrimp thoroughly dry with paper towels and season generously with salt and black pepper on both sides.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat half the butter (15g) in a large skillet over medium-high heat until foaming. Add shrimp in a single layer, ensuring not to overcrowd the pan.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Sear the shrimp for 1-2 minutes per side until pink and opaque but slightly underdone in the center. Remove shrimp from the pan and set aside on a plate.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Pink exterior, slightly translucent center", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Reduce heat to medium. Add the remaining butter to the same pan. Saut\u00e9 the minced shallots for 2 minutes until softened, then add garlic and cook for another 30 seconds until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Stir in the tomato paste and cook for 1 minute to darken slightly and caramelize the sugars.", "structured": {"action": "CARAMELIZE", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Remove pan from heat (or turn off gas burner). Pour in the Cognac. Carefully ignite with a long lighter or return to heat and tilt pan to ignite vapors (flamb\u00e9). Shake pan gently until flames subside.", "structured": {"action": "FLAMB\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Flames die down completely", "tactile": null}}, "tips": ["If you are uncomfortable flamb\u00e9ing, simply simmer the alcohol rapidly for 2 minutes to evaporate the harsh edge."]}, {"step_number": 7, "phase": "cook", "text": "Pour in the heavy cream. Bring to a simmer and reduce for 3-5 minutes until the sauce coats the back of a spoon (nappe consistency).", "structured": {"action": "REDUCE", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT4M", "doneness_cues": {"visual": "Thickened, coats spoon", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Return the shrimp and any accumulated juices to the pan. Simmer for 1 minute to reheat the shrimp and reach an internal temperature of 63\u00b0C/145\u00b0F. Stir in lemon juice and fresh parsley. Adjust salt to taste.", "structured": {"action": "SIMMER", "temperature": {"celsius": 63, "fahrenheit": 145}, "duration": "PT1M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT0M", "total_time": "PT25M", "overnight_required": false, "yields": "2 main servings", "yield_count": 2, "serving_size_g": 350}', '{"flags": ["Pescatarian", "Gluten-Free", "Low-Carb", "Keto"], "not_suitable_for": []}', '{"per_serving": {"calories": 716.03, "protein_g": 53.93, "carbohydrates_g": 8.29, "fat_g": 46.04, "saturated_fat_g": 28.55, "trans_fat_g": 1.12, "monounsaturated_fat_g": 11.94, "polyunsaturated_fat_g": 2.26, "fiber_g": 1.06, "sugar_g": 5.15, "sodium_mg": 913.63, "cholesterol_mg": 536.45, "potassium_mg": 908.47, "calcium_mg": 241.95, "iron_mg": 2.06, "magnesium_mg": 103.3, "phosphorus_mg": 612.29, "zinc_mg": 3.75, "vitamin_a_mcg": 488.86, "vitamin_c_mg": 8.47, "vitamin_d_mcg": 1.44, "vitamin_e_mg": 1.22, "vitamin_k_mcg": 45.92, "vitamin_b6_mg": 0.12, "vitamin_b12_mcg": 0.17, "thiamin_mg": 0.04, "riboflavin_mg": 0.19, "niacin_mg": 0.14, "folate_mcg": 13.61, "water_g": 273.89, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Reheat gently to avoid separating the cream sauce.", "duration": "P2D"}, "freezer": {"notes": "Not recommended; cream sauce texture degrades significantly upon thawing.", "duration": null}, "reheating": "Warm gently in a skillet over low heat, adding a splash of water if the sauce has thickened too much.", "does_not_keep": false}', '[{"name": "Large stainless steel skillet", "required": true, "alternative": "Cast iron pan"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Sauce looks oily or separated", "likely_cause": "The sauce was boiled too vigorously after adding the cream, causing the fat to break out", "prevention": "Keep the heat at a gentle simmer, never a hard boil, once cream is added", "fix": "Remove from heat immediately and whisk in a teaspoon of cold water or cold cream to re-emulsify"}]', '["Patting the shrimp dry is critical; wet shrimp will steam rather than sear, preventing the development of a flavorful fond on the bottom of the pan.", "For a truly decadent finish, you can mount the sauce with an extra knob of cold butter right at the end (monter au beurre), though the heavy cream usually provides enough richness.", "Serve immediately with crusty baguette slices or over rice pilaf to catch the sauce.", "Do not skip the tomato paste; while small in quantity, it provides umami and a beautiful sunset hue to the sauce."]', '"This dish is a staple of French bistro cuisine, often listed as ''Gambas Flamb\u00e9es''. It relies on the technique of deglazing to capture the ''suc'' (caramelized proteins) from the pan, using Cognac\u2014a brandy from the Charente region of France\u2014to impart a distinctive woody and vanilla aromatic profile."', 716.03);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('3b13c918-5229-4c58-b9b1-aa77ba144ef6', 'New Mexico Red Chile Braised Turkey Thighs', 'Succulent turkey thighs slow-braised in a vibrant, earthy sauce made from dried New Mexico chiles. The meat becomes fall-off-the-bone tender while absorbing the complex sweet-heat of the peppers, garlic, and cumin.', 'dinner', 'New Mexican', 'Intermediate', '["southwestern", "roasts", "garlic", "dinner", "lunch", "main course", "thanksgiving", "new mexican", "braise", "comfort food"]', '[{"group_name": "Red Chile Sauce", "items": [{"name": "dried new mexico red chiles", "quantity": 80, "unit": "g", "preparation": "stems and seeds removed", "notes": "approx 10-12 pods; use Guajillo if unavailable", "substitutions": [], "ingredient_id": "04e25096-2354-47fb-8109-ed574c64615c", "nutrition_source": "USDA FoodData Central"}, {"name": "boiling water", "quantity": 750, "unit": "ml", "preparation": null, "notes": "for soaking", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "white onion", "quantity": 150, "unit": "g", "preparation": "roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 6, "unit": null, "preparation": "peeled", "notes": "approx 25g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "dried mexican oregano", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "apple cider vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "chicken stock", "quantity": 250, "unit": "ml", "preparation": null, "notes": "plus more if needed", "substitutions": [], "ingredient_id": "7e254f45-046f-4812-bcdd-7e31c9bb59b8", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Turkey", "items": [{"name": "turkey thighs", "quantity": 4, "unit": null, "preparation": "bone-in, skin-on", "notes": "approx 1.5kg total weight", "substitutions": [], "ingredient_id": "4894b916-97da-4b23-9a6c-de2c72de5b3f", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "or lard for traditional flavor", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "kosher salt", "quantity": 10, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Heat a dry Dutch oven over medium heat. Toast the cleaned chile pods in batches for 30-60 seconds per side until fragrant and slightly darkened, being careful not to burn them. Transfer to a heatproof bowl.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Slightly darkened spots", "tactile": "Pliable"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Pour the boiling water over the toasted chiles. Weight them down with a plate to keep submerged and let soak for 20 minutes until completely soft.", "structured": {"action": "SOAK", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Drain the chiles, reserving 120ml of the soaking liquid. In a blender, combine the softened chiles, reserved soaking liquid, onion, garlic, cumin, oregano, vinegar, and chicken stock. Blend on high until completely smooth. For a silkier sauce, strain through a fine mesh sieve; otherwise leave rustic.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Preheat oven to 160\u00b0C/325\u00b0F. Pat turkey thighs very dry and season generously with salt and pepper. Add oil to the Dutch oven over medium-high heat. Sear turkey skin-side down until golden brown and crispy, about 6-8 minutes. Flip and sear the other side for 2 minutes. Remove turkey to a plate.", "structured": {"action": "SEAR", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT10M", "doneness_cues": {"visual": "Deep golden brown skin", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour the chile sauce into the Dutch oven, scraping up any fond (browned bits) from the bottom. Bring the sauce to a simmer. Return the turkey thighs to the pot, skin-side up, ensuring they are mostly submerged but the skin remains visible.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Cover the pot and transfer to the oven. Braise for 1 hour 30 minutes, or until the meat is very tender and pulling away from the bone. Internal temperature should reach at least 74\u00b0C/165\u00b0F, though for braising, higher is preferred for texture.", "structured": {"action": "BRAISE", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT1H30M", "doneness_cues": {"visual": null, "tactile": "Fork tender"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from oven. If the sauce is too thin, remove turkey and simmer sauce on the stove to reduce. Taste sauce and adjust salt. Serve turkey ladled with generous amounts of sauce.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT1H30M", "total_time": "PT2H15M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 375}', '{"flags": ["Gluten-Free", "Dairy-Free", "Paleo", "Whole30", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 576.22, "protein_g": 80.35, "carbohydrates_g": 13.12, "fat_g": 22.67, "saturated_fat_g": 4.07, "trans_fat_g": 0.11, "monounsaturated_fat_g": 3, "polyunsaturated_fat_g": 2.78, "fiber_g": 1.79, "sugar_g": 5.39, "sodium_mg": 1890.26, "cholesterol_mg": 292.5, "potassium_mg": 1197.85, "calcium_mg": 69.34, "iron_mg": 7.03, "magnesium_mg": 100.74, "phosphorus_mg": 702.13, "zinc_mg": 11.34, "vitamin_a_mcg": 98.62, "vitamin_c_mg": 10.22, "vitamin_d_mcg": 1.88, "vitamin_e_mg": 1.83, "vitamin_k_mcg": 7.99, "vitamin_b6_mg": 2.03, "vitamin_b12_mcg": 8.14, "thiamin_mg": 0.28, "riboflavin_mg": 1.24, "niacin_mg": 23.61, "folate_mcg": 39.95, "water_g": 529.71, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors improve significantly the next day.", "duration": "P4D"}, "freezer": {"notes": "Freeze in airtight containers with plenty of sauce.", "duration": "P3M"}, "reheating": "Gently reheat in a covered pot on the stove over low heat, adding a splash of water or stock if the sauce has thickened too much.", "does_not_keep": false}', '[{"name": "Dutch oven or heavy-bottomed braiser", "required": true, "alternative": "Deep oven-safe skillet with lid"}, {"name": "High-speed blender", "required": true, "alternative": "Standard blender or food processor"}, {"name": "Fine mesh sieve", "required": false, "alternative": "Food mill"}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Sauce tastes bitter", "likely_cause": "Chiles were burnt during toasting or unseeded pith was left in", "prevention": "Toast only until fragrant (seconds, not minutes) and remove all seeds/stems", "fix": "Stir in a small amount of honey or agave syrup (5-10ml) to counteract bitterness"}, {"symptom": "Meat is tough", "likely_cause": "Not braised long enough", "prevention": "Ensure pot is sealed and cook time is sufficient for connective tissue breakdown", "fix": "Return to oven for another 30 minutes; add a splash of water if sauce is dry"}]', '["New Mexico chiles come in varying heat levels (Mild, Medium, Hot, Extra Hot). Choose based on your tolerance, or mix Guajillo (mild) with Arbol (hot) to customize.", "For the best texture, remove the skin after braising and shred the meat into the sauce, essentially making a turkey ''carne adovada''.", "If using raw turkey legs/drums instead of thighs, increase the braising time by 15-20 minutes as the tendons take longer to break down.", "Wear gloves when handling the dried chiles to prevent capsaicin burns on your hands or eyes."]', '"This dish is a poultry adaptation of ''Carne Adovada'', a signature New Mexican dish traditionally made with pork. It relies heavily on the native red chile of the region (often from Hatch or Chimay\u00f3), which provides a distinctive earthy flavor that is fundamentally different from standard chili powder."', 576.22);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('3bcb9ed8-1207-41d3-864f-f0aa9911ee8e', 'Lemon-Mustard Brassica & Red Bean Skillet', 'A vibrant, textural winter supper featuring caramelized Brussels sprouts and cauliflower florets tossed with creamy red kidney beans. The dish is brought together by a zesty emulsion of Dijon mustard and fresh lemon, balancing the earthiness of the brassicas.', 'dinner', 'American', 'Easy', '["brussels sprout", "cauliflower", "red bean", "dinner", "easy", "main course", "winter", "dairy-free", "gluten-free", "healthy", "high fiber", "low cholesterol", "nut-free", "vegan", "vegetarian", "one-pan"]', '[{"group_name": "Vegetables & Protein", "items": [{"name": "brussels sprouts", "quantity": 450, "unit": "g", "preparation": "trimmed and halved", "notes": "Quarter if very large", "substitutions": [], "ingredient_id": "2ee7388c-3256-477d-8d05-4ce09df9d8f1", "nutrition_source": "USDA FoodData Central"}, {"name": "cauliflower", "quantity": 400, "unit": "g", "preparation": "cut into small bite-sized florets", "notes": null, "substitutions": [], "ingredient_id": "2d9d5068-77e7-4dfc-b24b-8e6a6275cb33", "nutrition_source": "USDA FoodData Central"}, {"name": "dark red kidney beans", "quantity": 425, "unit": "g", "preparation": "cooked", "notes": "1 standard can; rinsed and drained (approx 240g drained weight)", "substitutions": [], "ingredient_id": "c47acd32-84b1-49d8-bb34-ee2a51c96683", "nutrition_source": "USDA FoodData Central"}, {"name": "red onion", "quantity": 1, "unit": null, "preparation": "sliced into wedges", "notes": "approx 150g", "substitutions": [], "ingredient_id": "1c270c6e-0acc-4c5c-9935-7eff3240fc4a", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "divided use", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Lemon-Mustard Sauce", "items": [{"name": "dijon mustard", "quantity": 30, "unit": "g", "preparation": "smooth or grainy", "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 30, "unit": "ml", "preparation": null, "notes": "freshly squeezed, approx half a large lemon", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": "g", "preparation": null, "notes": "zest of 1 lemon", "substitutions": [], "ingredient_id": "a5fb6a2a-dcda-4ab2-8fe6-472d7fcc39d1", "nutrition_source": "USDA FoodData Central"}, {"name": "maple syrup", "quantity": 10, "unit": "ml", "preparation": null, "notes": "optional, to balance acidity", "substitutions": [], "ingredient_id": "1358a800-6e05-4bfd-ab71-03e78728c0bc", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish", "items": [{"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Whisk together the Dijon mustard, lemon juice, lemon zest, maple syrup (if using), minced garlic, salt, and pepper in a small bowl until emulsified. Set aside.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat 20ml of olive oil in a large skillet over medium-high heat. Once the oil is shimmering, arrange the Brussels sprouts cut-side down in a single layer. Scatter the cauliflower florets around them.", "structured": {"action": "HEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Sear undisturbed for 4-5 minutes until the sprouts and cauliflower develop a deep golden-brown char on the bottom.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Deep golden brown char on cut surfaces", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the red onion wedges and the remaining 10ml of olive oil. Stir well to flip the vegetables. Continue to saut\u00e9 for another 5-7 minutes, stirring occasionally, until the vegetables are tender-crisp.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": null, "tactile": "Fork-tender but retaining a snap"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Reduce heat to medium-low. Add the drained red kidney beans to the skillet and toss gently to warm through, about 2 minutes.", "structured": {"action": "MIX", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Pour the prepared mustard-lemon sauce over the mixture. Toss rapidly for 30 seconds to coat everything evenly and warm the sauce without breaking the emulsion. Remove from heat immediately.", "structured": {"action": "GLAZE", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Garnish with fresh chopped parsley and serve immediately.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT0M", "total_time": "PT25M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 320}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "High-Fiber"], "not_suitable_for": []}', '{"per_serving": {"calories": 199.86, "protein_g": 7.74, "carbohydrates_g": 23.71, "fat_g": 10.38, "saturated_fat_g": 1.95, "trans_fat_g": null, "monounsaturated_fat_g": 6.46, "polyunsaturated_fat_g": 1.21, "fiber_g": 7.45, "sugar_g": 7.87, "sodium_mg": 437.7, "cholesterol_mg": 2.4, "potassium_mg": 1099.78, "calcium_mg": 107.85, "iron_mg": 3.82, "magnesium_mg": 66.15, "phosphorus_mg": 179.25, "zinc_mg": 1.13, "vitamin_a_mcg": 53.35, "vitamin_c_mg": 152.38, "vitamin_d_mcg": null, "vitamin_e_mg": 2.19, "vitamin_k_mcg": 260.58, "vitamin_b6_mg": 0.47, "vitamin_b12_mcg": 0.01, "thiamin_mg": 0.28, "riboflavin_mg": 0.22, "niacin_mg": 1.63, "folate_mcg": 150.85, "water_g": 287.36, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. The vegetables may lose some crispness upon reheating.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; brassicas will become mushy upon thawing.", "duration": null}, "reheating": "Reheat quickly in a hot skillet for 2-3 minutes to restore texture.", "does_not_keep": false}', '[{"name": "Large skillet (12-inch or larger)", "required": true, "alternative": "Wok or large saut\u00e9 pan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": "Fork"}]', '[{"symptom": "Vegetables are mushy or soggy", "likely_cause": "The pan was overcrowded or the heat was too low, causing the vegetables to steam instead of sear.", "prevention": "Use a very large pan or cook the vegetables in two batches. Ensure oil is hot before adding vegetables.", "fix": "Remove beans, spread vegetables on a baking sheet, and place under a broiler for 2-3 minutes to dry out slightly."}]', '["The key to this dish is the ''hard sear.'' Do not disturb the Brussels sprouts for the first few minutes; that caramelization provides the savory depth that replaces meat.", "If using a cast-iron skillet, the residual heat is significant. Remove the pan from the burner before adding the sauce to prevent the mustard from becoming bitter.", "For extra protein, you can add hemp seeds or sunflower seeds as a crunchy topping right before serving.", "Ensure the cauliflower florets are cut small (approx 2-3 cm) so they cook at the same rate as the halved Brussels sprouts."]', '"Skillet suppers are a staple of modern American home cooking, prioritizing efficiency and cleanup without sacrificing flavor. This dish highlights winter brassicas, which sweeten after frost, pairing them with the brightness of citrus\u2014a classic technique to cut through the sulfurous notes of cabbage-family vegetables."', 199.86);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('3c38f16d-3593-4447-8761-ac262dcc4c4f', 'Pecan Pesto Marinated Artichokes', 'Tender, earth-sweet artichoke hearts bathed in a vibrant, nutty pesto made from toasted pecans and fresh basil. The buttery richness of the pecans complements the vegetal notes of the artichokes for a quintessential spring side dish.', 'side dish', 'Italian', 'Intermediate', '["artichoke", "side dish", "spring", "vegetarian", "gluten-free", "italian-inspired"]', '[{"group_name": "Artichokes", "items": [{"name": "fresh baby artichokes", "quantity": 1000, "unit": "g", "preparation": "whole", "notes": "choose firm, heavy heads with tight leaves", "substitutions": [], "ingredient_id": "071d7551-8bef-45ef-9c43-9fca9dd2ecae", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 2, "unit": null, "preparation": "halved", "notes": "approx 120g total", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 3000, "unit": "ml", "preparation": null, "notes": "for boiling", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": null}, {"name": "salt", "quantity": 15, "unit": "g", "preparation": null, "notes": "for boiling water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pecan Pesto", "items": [{"name": "pecan halves", "quantity": 100, "unit": "g", "preparation": "raw", "notes": null, "substitutions": [], "ingredient_id": "a5c5ee79-2bcd-4ab2-aed5-b09d0a3df4b5", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh basil leaves", "quantity": 40, "unit": "g", "preparation": "picked", "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}, {"name": "parmesan cheese", "quantity": 50, "unit": "g", "preparation": "grated", "notes": "ensure vegetarian rennet if strict vegetarian", "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "peeled", "notes": "approx 8g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 120, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 30, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Fill a large bowl with cold water and squeeze the juice of one lemon into it. Drop the spent lemon halves into the water. This acidulated water will prevent the artichokes from oxidizing and turning brown.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Prepare the baby artichokes: snap off the tough outer dark green leaves until you reach the pale yellow center. Cut off the top third of the artichoke and trim the stem end. Slice each artichoke in half lengthwise and immediately submerge in the lemon water.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["If using larger artichokes, you may need to scoop out the fuzzy choke with a spoon."]}, {"step_number": 3, "phase": "cook", "text": "Bring a large pot of salted water to a boil. Drain the artichokes and add them to the boiling water. Cook for 10-15 minutes until tender when pierced with a knife tip. Drain well and let cool slightly.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT15M", "doneness_cues": {"visual": null, "tactile": "tender when pierced with knife"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "While artichokes cook, place pecans in a dry skillet over medium heat. Toast, tossing frequently, until fragrant and slightly darkened, about 3-5 minutes. Remove from heat immediately to prevent burning.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "slightly darkened", "tactile": "fragrant"}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "In a food processor, combine the toasted pecans, basil, parmesan cheese, garlic, lemon juice, salt, and pepper. Pulse until coarsely chopped.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "With the motor running, slowly stream in the olive oil until the pesto emulsifies into a thick, rich sauce. Taste and adjust salt if necessary.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Place the warm, drained artichokes in a large bowl. Pour the pecan pesto over them and toss gently to coat every piece thoroughly.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Tossing while warm helps the artichokes absorb the flavors."]}, {"step_number": 8, "phase": "finish", "text": "Let the artichokes marinate at room temperature for at least 1 hour before serving to allow flavors to meld.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT1H", "total_time": "PT1H45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 185}', '{"flags": ["Vegetarian", "Gluten-Free", "Low-Carb", "Keto", "Egg-Free", "Soy-Free"], "not_suitable_for": ["Tree Nut allergies", "Milk allergies"]}', '{"per_serving": {"calories": 685.71, "protein_g": 12.59, "carbohydrates_g": 51.78, "fat_g": 51.34, "saturated_fat_g": 7.56, "trans_fat_g": null, "monounsaturated_fat_g": 33.06, "polyunsaturated_fat_g": 8.7, "fiber_g": 7.53, "sugar_g": 26, "sodium_mg": 1905.57, "cholesterol_mg": 8.5, "potassium_mg": 1277.13, "calcium_mg": 232.06, "iron_mg": 9.98, "magnesium_mg": 88.47, "phosphorus_mg": 365.46, "zinc_mg": 1.91, "vitamin_a_mcg": 55.89, "vitamin_c_mg": 31.5, "vitamin_d_mcg": 0.06, "vitamin_e_mg": 5.32, "vitamin_k_mcg": 61.34, "vitamin_b6_mg": 0.34, "vitamin_b12_mcg": 0.15, "thiamin_mg": 0.69, "riboflavin_mg": 0.24, "niacin_mg": 3.72, "folate_mcg": 50.58, "water_g": 243.68, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. The olive oil may solidify; let stand at room temperature for 20 minutes before serving.", "duration": "P4D"}, "freezer": {"notes": "Not recommended; texture of artichokes and pesto will degrade.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Food processor", "required": true, "alternative": "Mortar and pestle"}, {"name": "Large bowl", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Small skillet", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "Artichokes turned brown/grey", "likely_cause": "Oxidation occurred before boiling", "prevention": "Ensure artichokes are submerged in lemon water (acidulated water) immediately after cutting", "fix": "Cosmetic only; safe to eat but cannot be reversed"}]', '["Baby artichokes are preferred for this recipe because they often have no developed choke, making prep significantly faster and waste lower.", "Pecans have a higher fat content than pine nuts or walnuts, resulting in a creamier, sweeter pesto that balances the slight bitterness of the artichoke.", "Don''t throw away the parmesan rind; save it to flavor soups or stocks later.", "Ensure the artichokes are very well drained after boiling; excess water will water down the pesto."]', '"While pesto Genovese is strictly basil and pine nuts, Italian cuisine has a long tradition of ''pesto'' (meaning ''to pound'') variations using local nuts and produce. This recipe bridges the gap between Italian technique and Southern US ingredients (pecans), highlighting the artichoke, a vegetable celebrated in Roman cuisine since ancient times."', 685.71);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('3c5c3799-b99e-4533-9df4-b1f642dd6c77', 'Golden Spiced Persimmon Loaf', 'A deeply moist, dense quick bread celebrating the honey-like sweetness of ripe Hachiya persimmons. Warmed with cinnamon, ginger, and nutmeg, this loaf offers a comforting, custard-like crumb perfect for winter mornings.', 'bread', 'American', 'Easy', '["flour", "persimmon", "spices", "dessert", "winter", "halal", "healthy", "kosher", "vegetarian", "dairy-free"]', '[{"group_name": "Fruit Puree", "items": [{"name": "ripe hachiya persimmons", "quantity": 3, "unit": null, "preparation": "flesh scooped out", "notes": "yields approx 300g pulp; must be jelly-soft", "substitutions": [], "ingredient_id": "eec6d43e-72a9-4c47-93d2-8d658cf3c29a", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": "preserves color", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wet Ingredients", "items": [{"name": "eggs", "quantity": 2, "unit": null, "preparation": "large, room temperature", "notes": "approx 100g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "neutral oil", "quantity": 120, "unit": "ml", "preparation": null, "notes": "vegetable, canola, or light olive oil", "substitutions": ["melted coconut oil", "melted unsalted butter"], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "dark brown sugar", "quantity": 130, "unit": "g", "preparation": null, "notes": "packed", "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": "alcohol-free for strict Halal", "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dry Ingredients", "items": [{"name": "all-purpose flour", "quantity": 210, "unit": "g", "preparation": null, "notes": null, "substitutions": ["white whole wheat flour"], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "ground ginger", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "401ddd0b-3597-4b46-bb54-f3bc755048bb", "nutrition_source": "USDA FoodData Central"}, {"name": "ground nutmeg", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat oven to 175\u00b0C (350\u00b0F). Grease the loaf pan lightly with oil or butter and dust with flour, or line with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Scoop the flesh from the persimmons, discarding skins and seeds. Puree the flesh with the lemon juice until smooth.", "structured": {"action": "PUREE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["If persimmons are perfectly ripe, they can be mashed by hand, but a blender ensures a uniform crumb."]}, {"step_number": 3, "phase": "prep", "text": "In a large bowl, whisk together the eggs, oil, brown sugar, and vanilla until well combined and the sugar begins to dissolve.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Stir the persimmon puree into the egg mixture until fully incorporated.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "In a separate medium bowl, sift together the flour, baking soda, salt, cinnamon, ginger, and nutmeg.", "structured": {"action": "SIFT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "Fold the dry ingredients into the wet mixture using a spatula. Mix only until no streaks of flour remain.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Do not overmix. Overworking the gluten will make the bread tough rather than dense and moist."]}, {"step_number": 7, "phase": "cook", "text": "Pour the batter into the prepared loaf pan. Bake for 55 to 65 minutes, or until a toothpick inserted into the center comes out clean or with a few moist crumbs.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT1H", "doneness_cues": {"visual": "Deep golden brown crust, cracked top", "tactile": "Skewer inserted in center comes out clean"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Let the bread cool in the pan for 10 minutes, then turn out onto a wire rack to cool completely before slicing.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT1H10M", "total_time": "PT1H30M", "overnight_required": false, "yields": "1 standard loaf", "yield_count": 10, "serving_size_g": 95}', '{"flags": ["Vegetarian", "Dairy-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 270.95, "protein_g": 3.66, "carbohydrates_g": 35.04, "fat_g": 13.26, "saturated_fat_g": 2.11, "trans_fat_g": null, "monounsaturated_fat_g": 0.4, "polyunsaturated_fat_g": 0.29, "fiber_g": 1.91, "sugar_g": 16.55, "sodium_mg": 272.12, "cholesterol_mg": 37.2, "potassium_mg": 107.85, "calcium_mg": 26.63, "iron_mg": 0.65, "magnesium_mg": 10.63, "phosphorus_mg": 48.98, "zinc_mg": 0.33, "vitamin_a_mcg": 40.37, "vitamin_c_mg": 2.46, "vitamin_d_mcg": 0.2, "vitamin_e_mg": 0.35, "vitamin_k_mcg": 1, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": 0.09, "thiamin_mg": 0.04, "riboflavin_mg": 0.06, "niacin_mg": 0.34, "folate_mcg": 12.92, "water_g": 35.18, "alcohol_g": 0.17, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Wrap tightly in plastic wrap to maintain moisture.", "duration": "P5D"}, "freezer": {"notes": "Slice before freezing for easy reheating.", "duration": "P3M"}, "reheating": "Toast lightly or microwave for 15 seconds to restore warmth.", "does_not_keep": false}', '[{"name": "Loaf pan (23x13cm / 9x5 inch)", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Medium mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Silicone spatula", "required": true, "alternative": null}, {"name": "Blender or Food Processor", "required": true, "alternative": "Potato masher (for very soft fruit)"}, {"name": "Wire cooling rack", "required": true, "alternative": null}]', '[{"symptom": "Bread has a chalky, astringent taste", "likely_cause": "Under-ripe Hachiya persimmons were used", "prevention": "Ensure Hachiyas feel like water balloons and have no firmness before using", "fix": "Cannot be fixed"}, {"symptom": "Center is raw or gummy after baking time", "likely_cause": "High moisture content in fruit or oven temperature too high (cooking outside too fast)", "prevention": "Weigh the pulp (300g max); tent foil over bread if browning too fast and continue baking", "fix": "Cover with foil and bake for 10-15 minute increments"}]', '["Hachiya persimmons (acorn-shaped) are essential here. Do not substitute with Fuyu (tomato-shaped) unless you cook the Fuyus down into a puree first, as Fuyus are crisp.", "For a healthier profile, you can swap 50% of the all-purpose flour for whole wheat flour, though the loaf will be denser.", "This recipe is naturally dairy-free (Pareve for Kosher tables) and suitable for Halal diets (ensure vanilla is alcohol-free).", "Toasted walnuts or pecans (80g) make an excellent addition if nut allergies are not a concern."]', '"Quick breads originated in the United States during the 19th century with the advent of chemical leavening agents. Persimmon bread is a classic American usage of the Hachiya persimmon, often gifted during the holidays in California and the Midwest where the fruit ripens in late autumn."', 270.95);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('3cdbc11f-164e-464c-9e21-62bba5339963', 'Warm Citrus Salmon Salad', 'Succulent pan-seared salmon fillets served atop tender roasted baby potatoes and crisp asparagus, tossed with fresh greens and a zesty orange-lemon vinaigrette.', 'salad', 'Mediterranean', 'Easy', '["salmon", "salad", "citrus", "quick", "easy", "dinner", "healthy", "warm salad"]', '[{"group_name": "Roasted Vegetables", "items": [{"name": "baby potatoes", "quantity": 250, "unit": "g", "preparation": "halved", "notes": null, "substitutions": [], "ingredient_id": "41f30ad1-82e5-4826-9de0-cd33ecd578c1", "nutrition_source": "USDA FoodData Central"}, {"name": "asparagus spears", "quantity": 150, "unit": "g", "preparation": "woody ends trimmed", "notes": "approx 10-12 spears", "substitutions": [], "ingredient_id": "8a2a9426-3755-4553-953a-fd9cf42cef90", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "for roasting", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 2g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Salmon", "items": [{"name": "salmon fillets", "quantity": 300, "unit": "g", "preparation": "skin-on or skinless", "notes": "2 fillets, approx 150g each", "substitutions": [], "ingredient_id": "671c418a-0b74-45a8-a8b9-e4fd2f40e8ff", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 10, "unit": "ml", "preparation": null, "notes": "for searing", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "generous pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Citrus Dressing", "items": [{"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "036c7254-3de5-4c6e-a2e7-366ad4d05077", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh orange juice", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a15da11d-f8dd-46e3-9ac5-725a7912f1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": ["maple syrup"], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Assembly", "items": [{"name": "mixed salad greens", "quantity": 80, "unit": "g", "preparation": "washed and dried", "notes": "spinach, arugula, or mesclun", "substitutions": [], "ingredient_id": "f84cf2f5-c8cc-4095-8c77-aedf16352c61", "nutrition_source": "Aggregated Public Data"}, {"name": "avocado", "quantity": 1, "unit": null, "preparation": "sliced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "2f40a31e-80a0-4265-b6f3-99ed88ee4c24", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 200\u00b0C (400\u00b0F). Toss the halved baby potatoes with 15ml olive oil, salt, and pepper on a large baking sheet.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Roast the potatoes for 15 minutes initially. While they roast, prepare the asparagus by trimming the woody ends.", "structured": {"action": "ROAST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Remove the baking sheet from the oven, push potatoes to one side, and add the asparagus. Return to the oven for another 10-12 minutes until vegetables are tender and slightly browned.", "structured": {"action": "ROAST", "temperature": null, "duration": "PT12M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "While vegetables finish roasting, whisk together extra virgin olive oil, orange juice, lemon juice, honey, and Dijon mustard in a small bowl or jar until emulsified. Season with salt and pepper to taste.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pat salmon fillets dry and season generously with salt. Heat 10ml olive oil in a skillet over medium-high heat. Sear salmon (skin-side down first if applicable) for 3-4 minutes per side until golden and cooked to your preference (aim for 52\u00b0C/125\u00b0F internal for medium).", "structured": {"action": "SEAR", "temperature": {"celsius": 52, "fahrenheit": 126}, "duration": "PT8M", "doneness_cues": {"visual": "Opaque and flakes easily with a fork", "tactile": "Firm but yielding to touch"}}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Arrange a bed of mixed greens on plates. Top with the warm roasted potatoes, asparagus, and avocado slices.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Place the warm salmon fillet on top of the salad. Drizzle generously with the citrus dressing and serve immediately.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT25M", "total_time": "PT45M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 450}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Infants under 12 months (honey)"]}', '{"per_serving": {"calories": 1237.56, "protein_g": 43.07, "carbohydrates_g": 121.04, "fat_g": 66.87, "saturated_fat_g": 11.16, "trans_fat_g": null, "monounsaturated_fat_g": 22.16, "polyunsaturated_fat_g": 8.76, "fiber_g": 14.65, "sugar_g": 12.33, "sodium_mg": 791.55, "cholesterol_mg": 82.5, "potassium_mg": 2486.82, "calcium_mg": 145.2, "iron_mg": 4.71, "magnesium_mg": 167.87, "phosphorus_mg": 662.54, "zinc_mg": 2.25, "vitamin_a_mcg": 241.59, "vitamin_c_mg": 37.53, "vitamin_d_mcg": 16.5, "vitamin_e_mg": 9.86, "vitamin_k_mcg": 56.06, "vitamin_b6_mg": 2.2, "vitamin_b12_mcg": 4.85, "thiamin_mg": 0.78, "riboflavin_mg": 0.5, "niacin_mg": 19.51, "folate_mcg": 176.19, "water_g": 251.39, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store dressing separately from greens to prevent wilting. Salmon and roasted vegetables keep well.", "duration": "P2D"}, "freezer": {"notes": "Not recommended for salad components.", "duration": null}, "reheating": "Gently reheat salmon and roasted vegetables in a pan or microwave before assembling with cold greens.", "does_not_keep": false}', '[{"name": "Large baking sheet", "required": true, "alternative": null}, {"name": "Non-stick skillet", "required": true, "alternative": "Cast iron pan"}, {"name": "Small jar or whisking bowl", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Salmon is dry or tough", "likely_cause": "Overcooking; salmon continues to cook after being removed from heat", "prevention": "Remove salmon from the pan when it is slightly underdone in the center (translucent pink)", "fix": "Flake the fish into smaller pieces and toss thoroughly with extra dressing to add moisture"}, {"symptom": "Dressing tastes too acidic", "likely_cause": "Imbalanced ratio of vinegar/citrus to oil", "prevention": "Measure liquids carefully", "fix": "Add a small amount of extra honey or olive oil to balance the acidity"}]', '["Pat the salmon very dry with paper towels before searing to ensure a crispy crust rather than steaming the fish.", "If using skin-on salmon, sear about 80% of the time on the skin side to get it crispy, then flip just to finish.", "The contrast between the warm fish/vegetables and the cool, crisp greens is key to this dish; do not assemble until just before eating.", "For extra crunch, garnish with toasted sliced almonds or pine nuts."]', '"Warm salads are a staple of modern bistro dining, bridging the gap between light fare and comforting meals. This recipe highlights the Mediterranean tradition of pairing oily fish with bright citrus acids to cut through the richness."', 1237.56);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('3d42e878-1d5f-456b-8505-6af16eaa6b80', 'Midnight Peanut Butter Fudgy Bars', 'Deeply chocolatey, dense bars featuring a stark contrast of salty-sweet peanut butter ribbons. The texture bridges the gap between a chewy cookie and a decadent brownie, utilizing Dutch-process cocoa for a pitch-black hue perfect for Halloween or elegant entertaining.', 'dessert', 'American', 'Easy', '["bar cookie", "chocolate", "cocoa powder", "make-ahead", "peanut butter", "plan-ahead", "easy", "dessert", "halloween"]', '[{"group_name": "Chocolate Fudgy Base", "items": [{"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "melted and warm", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 250, "unit": "g", "preparation": null, "notes": "provides the glossy crust and dense texture", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "dutch-process cocoa powder", "quantity": 80, "unit": "g", "preparation": null, "notes": "essential for dark color and lowered acidity", "substitutions": [], "ingredient_id": "c06a8e5a-163a-4f21-ad00-a6d90e34c38c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "fine sea salt", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "cold", "notes": "large, approx 100g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "all-purpose flour", "quantity": 70, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Peanut Butter Swirl", "items": [{"name": "creamy peanut butter", "quantity": 130, "unit": "g", "preparation": null, "notes": "commercial stabilized style works best", "substitutions": [], "ingredient_id": "e77517b2-ae7b-426e-b848-ee30221e3129", "nutrition_source": "USDA FoodData Central"}, {"name": "powdered sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 15, "unit": "g", "preparation": "melted", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "flaky sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "for finishing", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 165\u00b0C/325\u00b0F. Line a 20cm (8-inch) square baking pan with parchment paper, leaving an overhang on two sides for easy removal.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 165, "fahrenheit": 329}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a small bowl, combine the peanut butter, powdered sugar, and the small amount of melted butter (15g). Stir vigorously until smooth and slightly stiffened. Set aside.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a large heatproof bowl, combine the warm melted butter (115g), granulated sugar, cocoa powder, and fine salt. Whisk vigorously for 1 minute until the mixture looks gritty but cohesive.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the vanilla extract and cold eggs one at a time, whisking hard after each addition until the batter becomes shiny, thick, and pulls away from the sides of the bowl.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": {"visual": "Batter becomes glossy and thick", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Switch to a spatula. Add the flour and fold gently just until no streaks of white remain. Do not overmix.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Pour the chocolate batter into the prepared pan and smooth the top. Drop teaspoon-sized dollops of the peanut butter mixture over the surface. Use a knife or skewer to swirl the peanut butter into the chocolate, creating a marbled effect.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Bake for 30-35 minutes. A toothpick inserted into the center should come out with moist crumbs attached, not wet batter. Do not overbake, or they will lose their fudgy texture.", "structured": {"action": "BAKE", "temperature": {"celsius": 165, "fahrenheit": 329}, "duration": "PT35M", "doneness_cues": {"visual": null, "tactile": "Toothpick has moist crumbs, not wet batter"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Sprinkle flaky sea salt over the hot bars immediately upon removing from the oven. Let cool completely in the pan on a wire rack for at least 2 hours before slicing.", "structured": {"action": "COOL", "temperature": null, "duration": "PT2H", "doneness_cues": null}, "tips": ["Cutting these while warm will result in a messy collapse; patience is key for clean slices."]}]', '{"active_time": "PT20M", "passive_time": "PT2H35M", "total_time": "PT2H55M", "overnight_required": false, "yields": "16 bars", "yield_count": 16, "serving_size_g": 45}', '{"flags": ["Vegetarian"], "not_suitable_for": ["Peanut allergy sufferers"]}', '{"per_serving": {"calories": 211.77, "protein_g": 4.09, "carbohydrates_g": 25.63, "fat_g": 12.09, "saturated_fat_g": 5.55, "trans_fat_g": 0.01, "monounsaturated_fat_g": 4.47, "polyunsaturated_fat_g": 1.42, "fiber_g": 2.37, "sugar_g": 18.45, "sodium_mg": 109.51, "cholesterol_mg": 40.72, "potassium_mg": 137.43, "calcium_mg": 16.76, "iron_mg": 1.01, "magnesium_mg": 40.52, "phosphorus_mg": 82.99, "zinc_mg": 0.67, "vitamin_a_mcg": 65.58, "vitamin_c_mg": null, "vitamin_d_mcg": 0.13, "vitamin_e_mg": 1, "vitamin_k_mcg": 0.75, "vitamin_b6_mg": 0.05, "vitamin_b12_mcg": 0.07, "thiamin_mg": 0.02, "riboflavin_mg": 0.06, "niacin_mg": 1.24, "folate_mcg": 12.99, "water_g": 7.02, "alcohol_g": 0.11, "caffeine_mg": 11.5}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Texture becomes denser and more fudge-like when chilled.", "duration": "P1W"}, "freezer": {"notes": "Wrap individually in foil before freezing.", "duration": "P3M"}, "reheating": "Microwave for 10-15 seconds to restore gooey texture.", "does_not_keep": false}', '[{"name": "Square baking pan (20cm / 8-inch)", "required": true, "alternative": "23cm / 9-inch square pan (reduce baking time by 5 minutes)"}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Heatproof mixing bowl", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Silicone spatula", "required": true, "alternative": null}]', '[{"symptom": "Bars are dry or cakey", "likely_cause": "Overbaking or overmixing the flour", "prevention": "Remove from oven when crumbs are still moist; stop mixing immediately after flour disappears", "fix": "Serve warm with ice cream or milk to mask dryness"}, {"symptom": "Peanut butter swirl sunk to the bottom", "likely_cause": "Peanut butter mixture was too heavy/dense compared to batter", "prevention": "Ensure the powdered sugar is mixed in well to stiffen the peanut butter slightly", "fix": "Cannot be fixed, but still tastes delicious"}]', '["Using cold eggs is a specific technique here; it shocks the warm butter, helping to create that dense, fudgy core rather than a fluffy cake crumb.", "Dutch-process cocoa is non-negotiable for the ''Midnight'' look and flavor; natural cocoa is too acidic and will change the texture.", "These bars are actually better on day two, making them the perfect make-ahead treat for events.", "If you want a cleaner cut, chill the fully cooled pan in the fridge for 30 minutes before slicing."]', '"While brownies are a quintessential American invention from the late 19th century, the combination of chocolate and peanut butter gained massive popularity in the mid-20th century, particularly in the Midwest (home of the Buckeye candy). This recipe deconstructs the Buckeye concept into a tray-bake format."', 211.77);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('3d72a7c4-7ba1-46c2-858e-331daaae2948', 'Chicken Manchurian', 'A quintessential Indo-Chinese favorite featuring crispy, batter-fried chicken chunks tossed in a glossy, spicy, sweet, and tangy sauce loaded with aromatics, bell peppers, and green onions. The texture offers a delightful contrast between the crunch of the coating and the sticky, umami-rich glaze.', 'dinner', 'Fusion', 'Intermediate', '["chinese", "indian", "pakistani", "poultry", "chicken breast", "chile", "cornstarch", "egg", "ketchup", "dinner", "weeknight", "main course", "indo-chinese", "fusion"]', '[{"group_name": "Chicken Marinade", "items": [{"name": "chicken breast", "quantity": 500, "unit": "g", "preparation": "cut into 2.5cm cubes", "notes": "boneless, skinless", "substitutions": [], "ingredient_id": "2b577d04-33ca-4919-938f-bfc8780a3a4b", "nutrition_source": "USDA FoodData Central"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": "beaten", "notes": "approx 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "ginger garlic paste", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Frying", "items": [{"name": "vegetable oil", "quantity": 500, "unit": "ml", "preparation": null, "notes": "quantity varies based on pot size, for deep frying", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Sauce Base", "items": [{"name": "vegetable oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 15, "unit": "g", "preparation": "finely minced", "notes": null, "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "ginger", "quantity": 10, "unit": "g", "preparation": "finely minced", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "green chilies", "quantity": 2, "unit": null, "preparation": "sliced", "notes": "Thai bird''s eye or serrano, approx 4g", "substitutions": [], "ingredient_id": "6cdb0615-378e-4bfa-b76d-f19bbd780e6c", "nutrition_source": "USDA FoodData Central"}, {"name": "red onion", "quantity": 100, "unit": "g", "preparation": "large dice", "notes": null, "substitutions": [], "ingredient_id": "1c270c6e-0acc-4c5c-9935-7eff3240fc4a", "nutrition_source": "Aggregated Public Data"}, {"name": "green bell pepper", "quantity": 100, "unit": "g", "preparation": "large dice", "notes": null, "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sauce Liquids", "items": [{"name": "ketchup", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "9b0c1201-83fa-43c7-b2a4-66c400bcb0fd", "nutrition_source": "Aggregated Public Data"}, {"name": "red chili sauce", "quantity": 30, "unit": "g", "preparation": null, "notes": "Sambal Oelek or Indian-style chili garlic sauce", "substitutions": [], "ingredient_id": "180ad647-bd4a-4ec3-af84-05e7e3e5a4b3", "nutrition_source": "Aggregated Public Data"}, {"name": "soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "white vinegar", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8d5bf07e-89a1-47ee-a6b7-d9cb03e96d64", "nutrition_source": "Aggregated Public Data"}, {"name": "sugar", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "chicken stock or water", "quantity": 120, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}, {"name": "cornstarch", "quantity": 5, "unit": "g", "preparation": null, "notes": "dissolved in 15ml water", "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish", "items": [{"name": "spring onions", "quantity": 20, "unit": "g", "preparation": "finely chopped", "notes": "green parts only", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a mixing bowl, combine chicken cubes with beaten egg, soy sauce, ginger garlic paste, black pepper, cornstarch, and all-purpose flour. Mix thoroughly until the chicken is evenly coated in a sticky batter.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat frying oil in a deep pot to 180\u00b0C/350\u00b0F. Carefully drop chicken pieces into the oil one by one to prevent sticking. Fry in batches for 5-6 minutes until golden brown, crisp, and cooked through (internal temp 74\u00b0C/165\u00b0F). Drain on a wire rack.", "structured": {"action": "FRY", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT6M", "doneness_cues": {"visual": "Golden brown and crispy coating", "tactile": "Firm to the touch"}}, "tips": ["Do not overcrowd the pan, or the oil temperature will drop and the chicken will become greasy."]}, {"step_number": 3, "phase": "cook", "text": "In a wok or large skillet, heat 30ml oil over high heat. Add minced garlic, ginger, and green chilies. Saut\u00e9 for 30-60 seconds until fragrant but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Garlic turns slightly pale gold", "tactile": "Aromatic"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the diced onion and bell pepper. Stir-fry vigorously on high heat for 2 minutes. The vegetables should remain crunchy and vibrant.", "structured": {"action": "STIR_FRY", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Peppers are glossy", "tactile": "Vegetables are crisp-tender"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Lower heat to medium. Add ketchup, red chili sauce, soy sauce, vinegar, sugar, and the chicken stock (or water). Simmer for 1-2 minutes until bubbling.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Stir in the cornstarch slurry (mix the 5g cornstarch with 15ml water first). Cook for 30-60 seconds until the sauce thickens and becomes glossy.", "structured": {"action": "THICKEN", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Sauce coats the back of a spoon", "tactile": "Viscous consistency"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Add the fried chicken to the wok. Toss quickly to coat every piece in the sauce. Turn off the heat immediately to preserve crispness.", "structured": {"action": "TOSS", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Garnish generously with chopped spring onions and serve immediately.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT30M", "total_time": "PT1H05M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 250}', '{"flags": ["Dairy-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 428.97, "protein_g": 30.3, "carbohydrates_g": 28.99, "fat_g": 21.2, "saturated_fat_g": 4.85, "trans_fat_g": 0.13, "monounsaturated_fat_g": 5.26, "polyunsaturated_fat_g": 2.79, "fiber_g": 1.87, "sugar_g": 8.91, "sodium_mg": 2587.9, "cholesterol_mg": 126.5, "potassium_mg": 472.83, "calcium_mg": 46.51, "iron_mg": 1.76, "magnesium_mg": 43.41, "phosphorus_mg": 269, "zinc_mg": 1.37, "vitamin_a_mcg": 102.98, "vitamin_c_mg": 43.42, "vitamin_d_mcg": 0.75, "vitamin_e_mg": 0.93, "vitamin_k_mcg": 12.67, "vitamin_b6_mg": 0.83, "vitamin_b12_mcg": 0.54, "thiamin_mg": 0.11, "riboflavin_mg": 0.21, "niacin_mg": 12.86, "folate_mcg": 28.64, "water_g": 155.88, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Coating will lose crispness; reheat in oven or air fryer to restore texture.", "duration": "P3D"}, "freezer": {"notes": "Not recommended as the texture of the vegetables and batter degrades significantly.", "duration": null}, "reheating": "Reheat in an oven at 180\u00b0C/350\u00b0F for 10-15 minutes or use a skillet over medium heat.", "does_not_keep": false}', '[{"name": "Wok or large skillet", "required": true, "alternative": null}, {"name": "Deep frying pan or pot", "required": true, "alternative": "Wok"}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": false, "alternative": null}, {"name": "Slotted spoon", "required": true, "alternative": null}, {"name": "Knife and cutting board", "required": true, "alternative": null}]', '[{"symptom": "Chicken coating is soggy", "likely_cause": "Chicken sat in the sauce too long before serving, or oil was not hot enough during frying", "prevention": "Fry at 180\u00b0C/350\u00b0F and toss chicken in sauce only seconds before plating", "fix": "Cannot be fixed once soggy; eat immediately"}, {"symptom": "Sauce is too thin", "likely_cause": "Not enough cornstarch or didn''t boil long enough after adding slurry", "prevention": "Ensure slurry is fully dissolved and bring sauce to a bubble", "fix": "Make a little more cornstarch slurry and add gradually while simmering"}]', '["The key to authentic ''Desi Chinese'' flavor is the specific combination of Indian red chili sauce and ketchup; do not substitute with Sriracha alone as it lacks the necessary sweetness and garlic profile.", "Double-frying the chicken (frying once at a lower temp, then flash frying at high heat) yields the ultimate restaurant-style crunch that stands up better to the sauce.", "Keep your wok extremely hot when stir-frying the vegetables to impart a slight ''wok hei'' (breath of the wok) smoky flavor without overcooking them.", "For a ''gravy'' version to eat with rice, double the liquid ingredients (stock, soy, chili sauce, ketchup) and cornstarch."]', '"Chicken Manchurian is the creation of Nelson Wang, a third-generation Chinese chef born in Kolkata, India. In the 1970s, he invented this dish by experimenting with Indian ingredients (garlic, ginger, chili) and Chinese cooking techniques (soy sauce, cornstarch thickening), effectively birthing the now-massive culinary genre known as Indo-Chinese cuisine."', 428.97);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('3de84a9f-6108-4da4-884a-5c8d9c8ebf2f', 'Piperade-Style Orzo Salad with Feta', 'A vibrant, picnic-ready pasta salad where the dressing is the vegetable base itself. Sweet bell peppers, onions, and tomatoes are stewed into a luscious Basque-style piperade sauce, then tossed with tender orzo and finished with salty crumbled feta and fresh basil.', 'salad', 'Mediterranean', 'Easy', '["american", "basil", "bell pepper", "feta", "make-ahead", "orzo", "pasta salad", "picnic", "tomato", "dinner", "easy", "lunch", "side dish", "summer", "vegetarian"]', '[{"group_name": "Pasta Base", "items": [{"name": "orzo pasta", "quantity": 300, "unit": "g", "preparation": "dry", "notes": null, "substitutions": [], "ingredient_id": "52cdfe63-4362-4d80-9ed0-9fc7041f2721", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "to coat pasta after draining", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Piperade Sauce", "items": [{"name": "olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "red bell pepper", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "Aggregated Public Data"}, {"name": "yellow bell pepper", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "b8ed9fc6-8806-4baf-a073-89a5b79f63f0", "nutrition_source": "Aggregated Public Data"}, {"name": "red onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "1c270c6e-0acc-4c5c-9935-7eff3240fc4a", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "canned diced tomatoes", "quantity": 400, "unit": "g", "preparation": "with juices", "notes": null, "substitutions": [], "ingredient_id": "18e8bb95-d862-47aa-a252-b454fd860e7e", "nutrition_source": "Aggregated Public Data"}, {"name": "smoked paprika", "quantity": 5, "unit": "g", "preparation": null, "notes": "piment d''Espelette preferred if available", "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "sherry vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["red wine vinegar"], "ingredient_id": "dcfa7371-7051-4604-a76e-4a46ae1f9e7b", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 3-5g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Assembly", "items": [{"name": "feta cheese", "quantity": 150, "unit": "g", "preparation": "crumbled", "notes": null, "substitutions": [], "ingredient_id": "a9a8605c-3bf2-4ca3-8c58-80e87aff7cd8", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh basil leaves", "quantity": 15, "unit": "g", "preparation": "chiffonade", "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}, {"name": "freshly cracked black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Bring a large pot of salted water to a boil. Add the orzo and cook according to package instructions until al dente (usually 7-9 minutes). Drain and immediately rinse with cold water to stop cooking and remove excess starch. Toss with 15ml olive oil to prevent sticking and set aside.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a large skillet, heat 45ml olive oil over medium heat. Add the diced onion, red pepper, and yellow pepper. Saut\u00e9 until the vegetables are softened and onions are translucent, but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT10M", "doneness_cues": {"visual": "Onions translucent, peppers softened", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Stir in the minced garlic and smoked paprika (or piment d''Espelette). Cook for 1 minute until fragrant. Add the canned tomatoes with their juices and the sherry vinegar. Simmer for 10-15 minutes until the mixture thickens into a saucy consistency. Season with salt to taste.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT15M", "doneness_cues": {"visual": "Thickened sauce, liquid reduced", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Remove the piperade sauce from heat and let it cool for at least 10 minutes. If mixing hot sauce with cold pasta, the pasta may absorb too much liquid and become mushy.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "In a large mixing bowl, combine the cooled orzo and the piperade sauce. Toss gently to coat. Fold in the crumbled feta and half of the fresh basil. Taste and adjust salt or vinegar if needed.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Top with the remaining fresh basil and cracked black pepper before serving. Can be served at room temperature or chilled.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT20M", "total_time": "PT55M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 250}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 276.33, "protein_g": 8.4, "carbohydrates_g": 26.13, "fat_g": 16.68, "saturated_fat_g": 4.96, "trans_fat_g": null, "monounsaturated_fat_g": 8.73, "polyunsaturated_fat_g": 1.58, "fiber_g": 4.79, "sugar_g": 10.29, "sodium_mg": 635.65, "cholesterol_mg": 42.75, "potassium_mg": 947.68, "calcium_mg": 182.08, "iron_mg": 4.71, "magnesium_mg": 61.63, "phosphorus_mg": 196.76, "zinc_mg": 1.73, "vitamin_a_mcg": 361.98, "vitamin_c_mg": 97.77, "vitamin_d_mcg": 0.1, "vitamin_e_mg": 2.15, "vitamin_k_mcg": 19.04, "vitamin_b6_mg": 0.29, "vitamin_b12_mcg": 0.47, "thiamin_mg": 0.15, "riboflavin_mg": 0.34, "niacin_mg": 1.47, "folate_mcg": 49.7, "water_g": 120.04, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors improve after sitting for a few hours. Stir before serving as pasta absorbs moisture.", "duration": "P4D"}, "freezer": {"notes": "Not recommended; texture of peppers and pasta will degrade.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}]', '[{"symptom": "Salad is dry after refrigeration", "likely_cause": "Orzo absorbed all the moisture from the sauce", "prevention": "Reserve a little pasta water or tomato juice to add back later", "fix": "Stir in a splash of olive oil and a teaspoon of water or vinegar to loosen"}]', '["Rinsing the pasta is controversial in hot dishes but essential here; it stops the cooking process and washes away surface starch that would otherwise make the salad clumpy.", "For a true Basque flavor profile, use Piment d''Espelette instead of smoked paprika. It offers a milder, fruitier heat.", "This salad is an excellent candidate for meal prep. Store the basil separately and add it just before eating to keep it bright green and aromatic.", "If you prefer a smoother sauce, you can pulse the piperade mixture in a food processor before tossing with the pasta, though the rustic chunks add great texture."]', '"Piperade is a traditional dish from the Basque Country (bordering France and Spain) centered on the local pepper varieties stewed with onions and tomatoes. While traditionally served as a main course with eggs or ham, this recipe adapts those sweet and savory flavors into a durable pasta salad format suitable for modern American-style picnics."', 276.33);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('3e1d7d4d-c278-4a92-b49a-d832df0b43bb', 'Sesame Scallion Wheat Berries', 'A rustic yet refined grain bowl featuring chewy, nut-flavored wheat berries dressed in a classic aromatic vinaigrette. The warmth of the grains activates the toasted sesame oil and soy sauce, creating a deeply savory profile balanced by the fresh, oniony bite of sliced scallions.', 'side dish', 'East Asian', 'Easy', '["asian", "five ingredient", "scallion", "wheat berry", "side dish", "winter", "vegan", "vegetarian", "high fiber"]', '[{"group_name": "Grains", "items": [{"name": "wheat berries", "quantity": 200, "unit": "g", "preparation": "dried", "notes": "hard red or soft white", "substitutions": ["farro", "spelt", "barley"], "ingredient_id": "bce9eafe-c121-4513-abc5-1e74615efedd", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 1000, "unit": "ml", "preparation": null, "notes": "for boiling", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "for cooking water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dressing & Aromatics", "items": [{"name": "soy sauce", "quantity": 30, "unit": "ml", "preparation": "light or all-purpose", "notes": null, "substitutions": ["tamari (for wheat-free, though grain is wheat)", "coconut aminos"], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "toasted sesame oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "dark variety", "substitutions": [], "ingredient_id": "a9a59164-d949-4acd-99da-689f0a32e2e7", "nutrition_source": "Aggregated Public Data"}, {"name": "scallions", "quantity": 4, "unit": null, "preparation": "fresh", "notes": "approx. 60g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "toasted sesame seeds", "quantity": 5, "unit": "g", "preparation": null, "notes": "for garnish", "substitutions": [], "ingredient_id": "36a7664a-f96c-44b9-9b6d-cdd5e9e54f55", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Rinse the wheat berries thoroughly under cold water in a fine-mesh sieve until the water runs clear.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Combine wheat berries, water, and salt in a medium saucepan. Bring to a rolling boil over high heat.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to low, cover, and simmer until the grains are tender but still retain a chewy bite (al dente). This typically takes 45 to 60 minutes depending on the age and variety of the grain.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT1H", "doneness_cues": {"visual": null, "tactile": "Chewy but no hard chalky center"}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "While grains cook, thinly slice the scallions, separating the white parts from the green tops.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Drain any excess water from the cooked wheat berries. Immediately transfer the hot grains to a mixing bowl.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Add the soy sauce, toasted sesame oil, and the white parts of the scallions to the hot grains. Toss vigorously to combine. The heat will help the grains absorb the dressing.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Garnish with the green scallion tops and optional sesame seeds. Serve warm, or let cool to room temperature.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT1H", "total_time": "PT1H10M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 160}', '{"flags": ["Vegetarian", "Vegan", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Sugar-Free"], "not_suitable_for": ["Celiacs (Wheat)"]}', '{"per_serving": {"calories": 221.68, "protein_g": 7.46, "carbohydrates_g": 38.37, "fat_g": 5.67, "saturated_fat_g": 0.23, "trans_fat_g": null, "monounsaturated_fat_g": 0.18, "polyunsaturated_fat_g": 0.5, "fiber_g": 0.57, "sugar_g": 1.63, "sodium_mg": 1657.15, "cholesterol_mg": null, "potassium_mg": 258.25, "calcium_mg": 45.29, "iron_mg": 2.17, "magnesium_mg": 81.9, "phosphorus_mg": 259.55, "zinc_mg": 2.14, "vitamin_a_mcg": 7.5, "vitamin_c_mg": 2.82, "vitamin_d_mcg": null, "vitamin_e_mg": 0.08, "vitamin_k_mcg": 31.05, "vitamin_b6_mg": 0.22, "vitamin_b12_mcg": null, "thiamin_mg": 0.22, "riboflavin_mg": 0.07, "niacin_mg": 3.45, "folate_mcg": 31.1, "water_g": 268.92, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors meld and improve over time. Can be eaten cold or reheated.", "duration": "P5D"}, "freezer": {"notes": "Freeze in airtight containers. Thaw overnight in refrigerator.", "duration": "P3M"}, "reheating": "Microwave gently or saut\u00e9 in a pan with a splash of water to refresh texture.", "does_not_keep": false}', '[{"name": "Medium saucepan with lid", "required": true, "alternative": null}, {"name": "Fine-mesh sieve or colander", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}]', '[{"symptom": "Wheat berries are tough even after 1 hour", "likely_cause": "Grains are old or very dry", "prevention": "Soak grains overnight to reduce cooking time", "fix": "Add 100ml more water and continue simmering, checking every 10 minutes"}]', '["Dressing Timing: Always dress grains while they are hot. As the starch cools, it retrogrades and closes up; dressing them hot ensures the flavor penetrates deep into the kernel.", "Texture Profile: Wheat berries are prized for their ''pop''. Do not cook them until mushy like oatmeal; they should offer resistance similar to al dente pasta.", "Serving Suggestions: This dish is incredibly versatile. Top with a fried egg for breakfast, serve as a base for grilled tofu, or mix into a larger green salad for texture.", "Soaking: If you wish to reduce the active boiling time, soak the berries in cold water for at least 8 hours. This reduces cooking time by approximately 50%."]', '"Wheat has been a staple crop in Northern China for millennia, often consumed as noodles or buns. Eating the whole berry (grain) in this manner highlights the ingredient''s natural nuttiness and connects to the ''cu fan'' (coarse food) tradition of appreciating unprocessed grains, seasoned here with the holy trinity of East Asian pantry staples."', 221.68);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('400b9fa0-adb2-4dfe-9200-f143433e4452', 'Pollo alla Cacciatora in Bianco', 'A rustic Umbrian hunter''s style chicken braised without tomatoes. The dish features a sharp, appetizing tang from white wine vinegar and lemon, balanced by the earthiness of rosemary, sage, and the briny depth of green olives and capers.', 'dinner', 'Italian', 'Intermediate', '["italian", "umbrian", "chicken", "olive", "rosemary", "caper", "rustic", "gluten-free optional"]', '[{"group_name": "Chicken", "items": [{"name": "chicken thighs and drumsticks", "quantity": 1200, "unit": "g", "preparation": "bone-in, skin-on", "notes": "approx. 8 pieces", "substitutions": [], "ingredient_id": "d7fc1bf9-fc05-429b-bfa6-2ad857cb0bb6", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 6, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 30, "unit": "g", "preparation": null, "notes": "optional, for light dusting", "substitutions": ["rice flour", "cornstarch"], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": "extra virgin", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Braising Liquid & Aromatics", "items": [{"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "smashed and peeled", "notes": "approx 20g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh rosemary", "quantity": 2, "unit": null, "preparation": "whole sprigs", "notes": "approx 4g", "substitutions": [], "ingredient_id": "fa90a3a7-86cd-40de-8f8c-0464231925c2", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh sage", "quantity": 4, "unit": null, "preparation": "leaves", "notes": "approx 2g", "substitutions": [], "ingredient_id": "2babed06-aae7-4e90-8b4a-14acbde2f522", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 120, "unit": "ml", "preparation": null, "notes": "Pinot Grigio or Verdicchio", "substitutions": [], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "white wine vinegar", "quantity": 45, "unit": "ml", "preparation": null, "notes": "provides the signature tang", "substitutions": [], "ingredient_id": "b2f8f0c0-6da9-47aa-932a-c2747b64b807", "nutrition_source": "Aggregated Public Data"}, {"name": "green olives", "quantity": 100, "unit": "g", "preparation": "pitted", "notes": "Castelvetrano or Cerignola", "substitutions": [], "ingredient_id": "8628da64-fa1c-4c91-badf-515667dbe9b9", "nutrition_source": "USDA FoodData Central"}, {"name": "capers", "quantity": 30, "unit": "g", "preparation": "rinsed", "notes": null, "substitutions": [], "ingredient_id": "e7301d2c-b906-4ef8-917e-787be0b25880", "nutrition_source": "USDA FoodData Central"}, {"name": "chicken stock", "quantity": 120, "unit": "ml", "preparation": null, "notes": "low sodium", "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": "zested and juiced", "notes": "approx 45ml juice", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the chicken pieces dry with paper towels. Season generously with salt and pepper. If using flour, lightly dust the chicken, shaking off any excess.", "structured": {"action": "SEASON", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": ["Dry skin ensures a better sear.", "The flour helps thicken the sauce later but can be omitted for a lighter dish."]}, {"step_number": 2, "phase": "cook", "text": "Heat the olive oil in a large Dutch oven over medium-high heat. Working in batches if necessary, sear the chicken skin-side down until deep golden brown and crispy, about 5-6 minutes. Flip and brown the other side for 2 minutes. Transfer chicken to a plate.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT10M", "doneness_cues": {"visual": "Deep golden brown skin", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to medium. Add the smashed garlic, rosemary sprigs, and sage leaves to the rendered fat. Saut\u00e9 for 1-2 minutes until fragrant, being careful not to burn the garlic.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT2M", "doneness_cues": {"visual": "Garlic is light gold", "tactile": "Herbs are fragrant"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour in the white wine and white wine vinegar. Scrape the bottom of the pan with a wooden spoon or tongs to release any browned bits (fond). Let the liquid bubble vigorously for 2 minutes to cook off the harsh alcohol.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Return the chicken to the pan, skin-side up. Add the chicken stock, olives, and capers. Bring to a boil, then reduce heat to low. Cover and simmer for 30-35 minutes.", "structured": {"action": "BRAISE", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT35M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Uncover the pan. Stir in the lemon juice. Increase heat to medium-high and cook for 5-10 minutes to reduce the sauce until it coats the back of a spoon. The internal temperature of the chicken must reach at least 74\u00b0C/165\u00b0F.", "structured": {"action": "REDUCE", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": "PT10M", "doneness_cues": {"visual": "Sauce is glossy and thickened", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from heat. Garnish with fresh lemon zest and serve immediately.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT45M", "total_time": "PT1H10M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Dairy-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Low-Carb"], "not_suitable_for": []}', '{"per_serving": {"calories": 565.77, "protein_g": 61.6, "carbohydrates_g": 12.5, "fat_g": 24.65, "saturated_fat_g": 4.92, "trans_fat_g": 0.06, "monounsaturated_fat_g": 12.83, "polyunsaturated_fat_g": 4.04, "fiber_g": 2.44, "sugar_g": 1.23, "sodium_mg": 2636.65, "cholesterol_mg": 282, "potassium_mg": 815.43, "calcium_mg": 66.02, "iron_mg": 3.28, "magnesium_mg": 82.61, "phosphorus_mg": 577.35, "zinc_mg": 4.95, "vitamin_a_mcg": 28.33, "vitamin_c_mg": 13.53, "vitamin_d_mcg": null, "vitamin_e_mg": 2.69, "vitamin_k_mcg": 16.34, "vitamin_b6_mg": 1.45, "vitamin_b12_mcg": 1.83, "thiamin_mg": 0.31, "riboflavin_mg": 0.63, "niacin_mg": 16.96, "folate_mcg": 20.09, "water_g": 277.19, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors often improve after 24 hours.", "duration": "P3D"}, "freezer": {"notes": "Sauce may separate slightly; reheat gently.", "duration": "P2M"}, "reheating": "Warm in a covered skillet over medium-low heat with a splash of water.", "does_not_keep": false}', '[{"name": "Large Dutch oven or heavy-bottomed deep skillet with lid", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Sauce is too thin/watery", "likely_cause": "Not enough reduction time or too much liquid added", "prevention": "Measure liquids carefully", "fix": "Remove chicken to a warm plate and boil the sauce vigorously over high heat until it reaches desired consistency"}, {"symptom": "Chicken skin is soggy", "likely_cause": "Pot was covered for the entire duration or liquid level was too high", "prevention": "Ensure liquid only comes halfway up the chicken; do not submerge skin", "fix": "Place the pan under a hot broiler for 2-3 minutes to re-crisp skin (watch carefully)"}, {"symptom": "Dish tastes too acidic", "likely_cause": "Vinegar or lemon juice did not cook down enough or was over-measured", "prevention": "Ensure the initial vinegar boil-off in step 4 is thorough", "fix": "Stir in a small knob of cold butter or a pinch of sugar to round out the acidity"}]', '["The combination of vinegar and chicken (Pollo all''Aceto) is a staple of rustic Italian cooking; do not skip the vinegar, as it tenderizes the meat.", "For the best flavor, use bone-in, skin-on chicken. Boneless breasts will dry out with this braising method.", "If you can find Taggiasca olives, they are an excellent, authentic alternative to Castelvetrano.", "Serve this with crusty bread (pane sciocco) to mop up the acidic, savory sauce.", "The sauce emulsifies better if you swirl the pan gently during the reduction phase."]', '"Originating from the ''green heart of Italy'', Umbria, this ''in bianco'' (white) version of Cacciatora predates the widespread use of tomatoes in Italy. It reflects the hunter''s preparation (cacciatore means hunter), using preserved pantry staples like vinegar, wine, and cured olives to flavor wild game or farm birds."', 565.77);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('4155e1ab-ab53-4b94-ad86-595c833e6ded', 'Crispy Honey-Feta Tortilla Flatbreads', 'Golden, crunchy flour tortillas baked with bubbly mozzarella, topped with a cool, crisp salad of cucumbers and tomatoes, salty feta, and a savory garlic yogurt sauce. A drizzle of honey adds an addictive sweet-salty finish.', 'lunch', 'Mediterranean Fusion', 'Easy', '["vegetables", "cucumber", "flour tortilla", "kid-friendly", "tomato", "vegetarian", "mediterranean", "quick lunch"]', '[{"group_name": "Cheesy Base", "items": [{"name": "flour tortillas", "quantity": 4, "unit": null, "preparation": "medium size (approx 20cm)", "notes": "approx 160g total", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": "for brushing", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "shredded mozzarella cheese", "quantity": 150, "unit": "g", "preparation": "low moisture", "notes": null, "substitutions": [], "ingredient_id": "f219ebe9-5ced-45e9-90b4-57fc34e327e8", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Fresh Toppings", "items": [{"name": "cherry tomatoes", "quantity": 150, "unit": "g", "preparation": "quartered", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "cucumber", "quantity": 150, "unit": "g", "preparation": "diced small", "notes": null, "substitutions": [], "ingredient_id": "457adec2-3e06-4efe-a26e-9e6ea9f84924", "nutrition_source": "USDA FoodData Central"}, {"name": "feta cheese", "quantity": 100, "unit": "g", "preparation": "crumbled", "notes": null, "substitutions": [], "ingredient_id": "a9a8605c-3bf2-4ca3-8c58-80e87aff7cd8", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh dill", "quantity": 5, "unit": "g", "preparation": "chopped", "notes": "optional", "substitutions": [], "ingredient_id": "4be2b047-475d-4c84-82d5-4883298c6121", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garlic Sauce & Finish", "items": [{"name": "greek yogurt", "quantity": 120, "unit": "g", "preparation": "plain, full fat", "notes": null, "substitutions": [], "ingredient_id": "61eae1a4-8517-4da8-8c29-34288cb7d8c7", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "grated", "notes": "approx 3g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": "pinch", "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 30, "unit": "g", "preparation": null, "notes": "for drizzling", "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 200\u00b0C (400\u00b0F). Line a baking sheet with parchment paper if desired for easier cleanup.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Brush one side of each tortilla lightly with olive oil. Place them oil-side down on the baking sheet. Sprinkle the shredded mozzarella evenly over the top of each tortilla, leaving a small rim at the edge.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Bake in the preheated oven for 8-10 minutes, or until the cheese is bubbly and golden, and the edges of the tortillas are crisp and brown.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT10M", "doneness_cues": {"visual": "Cheese bubbly and golden spots", "tactile": "Tortilla edges stiff and crisp"}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "While the tortillas bake, prepare the sauce. In a small bowl, whisk together the Greek yogurt, grated garlic, lemon juice, and a pinch of salt until smooth.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Remove the tortillas from the oven. Immediately top them with the diced cucumber, quartered cherry tomatoes, and crumbled feta cheese.", "structured": {"action": "TOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Drizzle the garlic yogurt sauce over the vegetables, followed by a generous drizzle of honey. Garnish with fresh dill if using and serve immediately while the base is warm and toppings are cool.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "4 flatbreads", "yield_count": 4, "serving_size_g": 250}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": ["Infants under 12 months (honey)"]}', '{"per_serving": {"calories": 358.98, "protein_g": 22.58, "carbohydrates_g": 45.8, "fat_g": 9.69, "saturated_fat_g": 3.95, "trans_fat_g": null, "monounsaturated_fat_g": 3.96, "polyunsaturated_fat_g": 0.73, "fiber_g": 2.89, "sugar_g": 8.95, "sodium_mg": 674.93, "cholesterol_mg": 30.5, "potassium_mg": 259.53, "calcium_mg": 530.66, "iron_mg": 1.11, "magnesium_mg": 36.03, "phosphorus_mg": 393.82, "zinc_mg": 2.65, "vitamin_a_mcg": 101.78, "vitamin_c_mg": 11.22, "vitamin_d_mcg": 0.1, "vitamin_e_mg": 0.68, "vitamin_k_mcg": 9.59, "vitamin_b6_mg": 0.18, "vitamin_b12_mcg": 0.77, "thiamin_mg": 0.11, "riboflavin_mg": 0.36, "niacin_mg": 0.87, "folate_mcg": 27.07, "water_g": 104.67, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten immediately. Components can be stored separately for 2 days.", "duration": null}, "freezer": {"notes": null, "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Pastry brush", "required": false, "alternative": "Back of a spoon"}]', '[{"symptom": "Tortilla is soggy in the middle", "likely_cause": "The oven wasn''t hot enough or the tomatoes released juice too quickly", "prevention": "Ensure oven is fully preheated; assemble toppings immediately before eating", "fix": "Place back in oven for 2 minutes on a wire rack (without sauce)"}]', '["To prevent watery toppings, you can salt the diced cucumber and tomatoes in a colander for 10 minutes and pat dry before using, though this adds prep time.", "For extra flavor, rub the warm baked crust with a raw garlic clove before adding toppings.", "Use full-fat Greek yogurt for the sauce; low-fat varieties can be too runny and tart for this balance."]', '"This dish borrows the concept of a tostada from Mexican cuisine and pairs it with the classic flavor profile of the Eastern Mediterranean (feta, honey, oregano/dill). The contrast between the hot, salty cheese and the cold, sweet-savory toppings makes it a popular modern cafe lunch item."', 358.98);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('41b4b387-6c92-4aa7-94dc-062ebe266dce', 'Wild Rice, Mushroom, and Pecan Latkes', 'An earthy, sophisticated twist on the Hanukkah classic. Nutty wild rice and toasted pecans provide a satisfying chew, while sautéed mushrooms add deep umami savory notes, all bound in a crisp, golden fried disk.', 'side dish', 'Jewish Fusion', 'Intermediate', '["jewish", "mushroom", "pecan", "dinner", "winter", "kosher", "hanukkah", "wild rice"]', '[{"group_name": "Wild Rice Base", "items": [{"name": "wild rice", "quantity": 100, "unit": "g", "preparation": "raw", "notes": "yields approx 300g cooked", "substitutions": [], "ingredient_id": "e99f7d25-554d-4078-b6af-e2b53484a492", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 400, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics & Fillings", "items": [{"name": "cremini mushrooms", "quantity": 250, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "fdd23eb2-a71c-46d1-932b-295adf7d5ae5", "nutrition_source": "Aggregated Public Data"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx 100g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "pecans", "quantity": 60, "unit": "g", "preparation": "toasted and chopped", "notes": null, "substitutions": [], "ingredient_id": "a5c5ee79-2bcd-4ab2-aed5-b09d0a3df4b5", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme leaves", "quantity": 2, "unit": "g", "preparation": "picked", "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Binder & Frying", "items": [{"name": "large eggs", "quantity": 2, "unit": null, "preparation": null, "notes": "approx 100g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "matzo meal", "quantity": 45, "unit": "g", "preparation": null, "notes": null, "substitutions": ["breadcrumbs", "all-purpose flour"], "ingredient_id": "ba4dc343-44a8-4365-a655-e5be9f495ff4", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 120, "unit": "ml", "preparation": null, "notes": "for frying, such as grapeseed or canola", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine wild rice, water, and first portion of salt in a saucepan. Bring to a boil, reduce to low, cover, and simmer until tender and grains have burst. Drain any excess liquid and let cool slightly.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT45M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "While rice cooks, heat 15ml of the oil in a skillet over medium-high heat. Add mushrooms and onions. Saut\u00e9 until the mushrooms release their liquid and become dry and browned. Add garlic and thyme in the last minute of cooking.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Mushrooms are dark brown and pan is dry", "tactile": null}}, "tips": ["Removing moisture from mushrooms is critical to prevent soggy latkes."]}, {"step_number": 3, "phase": "assemble", "text": "In a large mixing bowl, combine the cooked wild rice, saut\u00e9ed mushroom mixture, toasted pecans, beaten eggs, matzo meal, salt, and pepper. Mix until the mixture holds together when squeezed.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Wipe out the skillet and add remaining oil to a depth of about 0.5cm. Heat over medium-high heat until the oil shimmers (approx 180\u00b0C/350\u00b0F).", "structured": {"action": "PREHEAT", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Scoop roughly 60ml (1/4 cup) portions of the mixture. Press firmly between hands to compact into flat disks. Carefully place in hot oil. Fry for 3-4 minutes per side until deeply golden and crispy.", "structured": {"action": "FRY", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Dark golden brown crust", "tactile": "Solid and crispy exterior"}}, "tips": ["Do not crowd the pan; fry in batches to maintain oil temperature."]}, {"step_number": 6, "phase": "finish", "text": "Transfer latkes to a wire rack set over a baking sheet or paper towels to drain excess oil. Season immediately with a pinch of salt while hot.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT0M", "total_time": "PT45M", "overnight_required": false, "yields": "12 latkes", "yield_count": 12, "serving_size_g": 110}', '{"flags": ["Vegetarian", "Dairy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 187.43, "protein_g": 3.72, "carbohydrates_g": 11.9, "fat_g": 14.52, "saturated_fat_g": 2.03, "trans_fat_g": null, "monounsaturated_fat_g": 2.36, "polyunsaturated_fat_g": 1.3, "fiber_g": 1.41, "sugar_g": 1.15, "sodium_mg": 273.6, "cholesterol_mg": 31, "potassium_mg": 174.28, "calcium_mg": 18.23, "iron_mg": 0.65, "magnesium_mg": 24.42, "phosphorus_mg": 73.13, "zinc_mg": 0.86, "vitamin_a_mcg": 13.99, "vitamin_c_mg": 1.07, "vitamin_d_mcg": 0.17, "vitamin_e_mg": 0.23, "vitamin_k_mcg": 0.54, "vitamin_b6_mg": 0.07, "vitamin_b12_mcg": 0.07, "thiamin_mg": 0.05, "riboflavin_mg": 0.07, "niacin_mg": 0.64, "folate_mcg": 14.62, "water_g": 48.3, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container with paper towels to absorb excess oil.", "duration": "P3D"}, "freezer": {"notes": "Freeze in a single layer, then transfer to bags. Reheat directly from frozen.", "duration": "P1M"}, "reheating": "Reheat on a wire rack in a 190\u00b0C (375\u00b0F) oven for 5-8 minutes until crisp.", "does_not_keep": false}', '[{"name": "Heavy-bottomed frying pan or cast iron skillet", "required": true, "alternative": null}, {"name": "Saucepan", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}, {"name": "Slotted spatula", "required": true, "alternative": null}]', '[{"symptom": "Latkes are falling apart in the oil", "likely_cause": "The mixture is too dry or wasn''t compressed enough", "prevention": "Ensure the mushroom mixture is dry, but don''t skip the eggs. Press latkes firmly before frying.", "fix": "Add another beaten egg or a tablespoon more matzo meal to the remaining batter and mix well."}]', '["If using raw pecans, toast them in a dry pan for 3-5 minutes before chopping to release their natural oils.", "Wild rice varies significantly in cooking time; ''cracked'' wild rice cooks faster than whole grain. Adjust Step 1 accordingly.", "Serve these with a savory topping like sour cream mixed with chives, or a dollop of apple chutney for a sweet-savory contrast.", "Ensure the oil is hot enough before adding the latkes; if the oil is too cool, they will absorb grease rather than frying."]', '"While potato latkes (levivot) are the Ashkenazi standard for Hanukkah to celebrate the miracle of the oil, the tradition of frying food spans the Jewish diaspora. This recipe incorporates North American ingredients like wild rice and pecans, creating a modern ''New World'' interpretation of the holiday staple that remains pareve (meat/dairy neutral)."', 187.43);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('41e20459-77d1-4209-ba67-c73029013c58', 'Klassisk Svensk Råbiff (Classic Swedish Steak Tartare)', 'A pristine execution of the Nordic classic featuring hand-cut raw beef tenderloin. The rich, velvety meat is contrasted by the earthy acidity of pickled beets, the bite of horseradish and red onion, and the salty crunch of capers. Served with homemade potato crisps for texture.', 'appetizer', 'Swedish', 'Intermediate', '["beef", "beet", "nordic", "potato", "appetizer", "winter", "christmas", "raw", "low-carb"]', '[{"group_name": "Beef", "items": [{"name": "beef tenderloin", "quantity": 400, "unit": "g", "preparation": "trimmed", "notes": "Must be extremely fresh, sushi-grade quality", "substitutions": [], "ingredient_id": "334395ff-58e3-42c0-93c0-e0b9e83a369b", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 20, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "worcestershire sauce", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "aa552099-60a9-4267-a732-5870a271c28f", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 3g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Accompaniments", "items": [{"name": "pickled beetroots", "quantity": 60, "unit": "g", "preparation": "whole", "notes": null, "substitutions": [], "ingredient_id": "fbc7ce7a-1590-45b1-8779-0edfe3523cc3", "nutrition_source": "USDA FoodData Central"}, {"name": "red onion", "quantity": 40, "unit": "g", "preparation": "finely diced", "notes": null, "substitutions": [], "ingredient_id": "1c270c6e-0acc-4c5c-9935-7eff3240fc4a", "nutrition_source": "Aggregated Public Data"}, {"name": "capers", "quantity": 30, "unit": "g", "preparation": "drained", "notes": null, "substitutions": [], "ingredient_id": "e7301d2c-b906-4ef8-917e-787be0b25880", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh horseradish", "quantity": 20, "unit": "g", "preparation": "whole root", "notes": null, "substitutions": [], "ingredient_id": "3435f8a5-626e-4cb0-b00e-b0d87515ba9e", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh chives", "quantity": 10, "unit": "g", "preparation": "finely minced", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}, {"name": "egg yolks", "quantity": 4, "unit": null, "preparation": null, "notes": "pasteurized recommended", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Potato Crisps", "items": [{"name": "waxy potatoes", "quantity": 200, "unit": "g", "preparation": "scrubbed", "notes": null, "substitutions": [], "ingredient_id": "4920385c-ae78-4023-8318-c5dfe051fecc", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 500, "unit": "ml", "preparation": null, "notes": "for frying (rapeseed or sunflower)", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}, {"name": "flaky sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "for finishing", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the beef tenderloin in the freezer for 15-20 minutes. This firms up the fat and muscle fibers, making it significantly easier to dice precisely by hand.", "structured": {"action": "CHILL", "temperature": {"celsius": -18, "fahrenheit": 0}, "duration": "PT20M", "doneness_cues": null}, "tips": ["Do not freeze solid; just enough to firm the texture."]}, {"step_number": 2, "phase": "prep", "text": "While beef chills, prepare the garnishes. Finely dice the pickled beets and red onion into uniform 2-3mm brunoise. Rinse and dry the capers. Finely mince the chives. Set all aside in separate small bowls.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Using a mandoline, slice the potatoes into paper-thin rounds (approx 1mm). Rinse them in cold water to remove starch, then pat completely dry with kitchen towels.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Any moisture left on the potatoes will cause dangerous splattering when frying."]}, {"step_number": 4, "phase": "cook", "text": "Heat the neutral oil in a heavy-bottomed pot to 160\u00b0C/320\u00b0F. Fry the potato slices in small batches until golden and crisp, about 3-4 minutes. Remove with a slotted spoon, drain on paper towels, and season immediately with salt.", "structured": {"action": "FRY", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT4M", "doneness_cues": {"visual": "Golden brown", "tactile": "Crisp"}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Remove beef from freezer. With a very sharp knife, slice the beef into thin sheets, then julienne into strips, and finally cross-cut into a fine dice (approx 3-5mm). Do not mince into a paste; distinct texture is required.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Never use a food processor, as it damages the meat fibers and creates a mushy texture."]}, {"step_number": 6, "phase": "assemble", "text": "In a mixing bowl, gently toss the diced beef with the Dijon mustard, Worcestershire sauce, salt, and black pepper. Taste a small amount to check seasoning.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Shape the meat into four round patties and place on chilled serving plates. Create a small indentation in the center of each patty and carefully place a raw egg yolk in the well.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Arrange small mounds of diced beets, red onion, capers, and chives around the meat. Grate fresh horseradish generously over the dish just before serving. Serve with the potato crisps on the side.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT15M", "total_time": "PT50M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Dairy-Free", "Gluten-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Paleo", "Low-Carb"], "not_suitable_for": ["Pregnant women (raw meat/egg)", "Infants (raw meat/egg)", "Immunocompromised individuals (raw meat/egg)"]}', '{"per_serving": {"calories": 252.77, "protein_g": 25.61, "carbohydrates_g": 13.9, "fat_g": 10.97, "saturated_fat_g": 4.11, "trans_fat_g": 0.12, "monounsaturated_fat_g": 3.76, "polyunsaturated_fat_g": 1.01, "fiber_g": 2.3, "sugar_g": 3.31, "sodium_mg": 807.89, "cholesterol_mg": 241.6, "potassium_mg": 651.01, "calcium_mg": 48.98, "iron_mg": 3.45, "magnesium_mg": 41.73, "phosphorus_mg": 307.2, "zinc_mg": 2.96, "vitamin_a_mcg": 91.31, "vitamin_c_mg": 7.24, "vitamin_d_mcg": 1.02, "vitamin_e_mg": 1.12, "vitamin_k_mcg": 3.22, "vitamin_b6_mg": 0.44, "vitamin_b12_mcg": 2.11, "thiamin_mg": 0.12, "riboflavin_mg": 0.24, "niacin_mg": 4.68, "folate_mcg": 39.64, "water_g": 149, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Must be consumed immediately upon preparation for safety and quality.", "duration": null}, "freezer": {"duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Sharp Chef''s Knife", "required": true, "alternative": "Santoku knife"}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Mandoline or vegetable peeler", "required": true, "alternative": null}, {"name": "Heavy-bottomed pot", "required": true, "alternative": "Deep fryer"}, {"name": "Kitchen thermometer", "required": true, "alternative": null}, {"name": "Microplane or fine grater", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}]', '[{"symptom": "Meat texture is mushy or pasty", "likely_cause": "Knife was dull or meat was chopped too aggressively/warm", "prevention": "Use a razor-sharp knife and keep meat partially frozen during cutting", "fix": "Cannot be fixed; serve as is but note for next time"}, {"symptom": "Meat turns brown/gray quickly", "likely_cause": "Oxidation from air exposure", "prevention": "Cut meat immediately before serving and keep covered", "fix": "Remove oxidized surface layer if shallow"}]', '["Safety is paramount. Buy meat from a trusted butcher, inform them it is for tartare, and keep it below 4\u00b0C until the moment of plating.", "The ''Swedish'' distinction often lies in the separation of ingredients (deconstructed) rather than mixing everything in, allowing the diner to customize every bite.", "Pickled beets are the signature component of Swedish tartare, providing a sweet and acidic counterpoint to the rich beef.", "For a festive Christmas touch, you can add a pinch of ground allspice to the meat seasoning."]', '"R\u00e5biff (raw steak) became popular in Swedish restaurants in the late 19th century, inspired by French tartare but adapted with local staple ingredients like pickled beets and horseradish. It remains a sophisticated staple on Swedish bistro menus, often served as a ''halva'' (starter) or ''hela'' (main with fries)."', 252.77);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('41fcee31-e9fc-4ce1-a550-6e50414abedc', 'Strawberry Red Wine Matzo Layer Bars', 'A sweet, custardy Passover dessert reminiscent of a fruity lasagna or kugel. Layers of matzo softened in a spiced red wine egg batter alternate with sticky strawberry preserves, finished with a rich honey-butter glaze that caramelizes the edges.', 'dessert', 'Jewish', 'Intermediate', '["pastries", "matzo", "red wine", "dessert", "passover", "jewish holiday", "baked good"]', '[{"group_name": "Red Wine Egg Batter", "items": [{"name": "large eggs", "quantity": 4, "unit": null, "preparation": "beaten", "notes": "approx. 200g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "sweet red wine", "quantity": 80, "unit": "ml", "preparation": null, "notes": "Kosher sweet wine (e.g., Manischewitz) or Ruby Port", "substitutions": [], "ingredient_id": "0fc93141-8ba8-42e0-ac8b-b5af3851554c", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx. 1 tsp", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Layers", "items": [{"name": "matzo sheets", "quantity": 6, "unit": null, "preparation": null, "notes": "plain, unsalted", "substitutions": [], "ingredient_id": "bce3d6d8-f342-4519-b3b7-5f3461243243", "nutrition_source": "USDA FoodData Central"}, {"name": "strawberry preserves", "quantity": 250, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "635edf1d-bc9a-412f-8753-b3a2370297ae", "nutrition_source": "Aggregated Public Data"}, {"name": "ground cinnamon", "quantity": 1, "unit": "g", "preparation": null, "notes": "for dusting layers", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Honey-Butter Glaze", "items": [{"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 60, "unit": "ml", "preparation": null, "notes": "approx. 85g", "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "sweet red wine", "quantity": 15, "unit": "ml", "preparation": null, "notes": "optional splash for color", "substitutions": [], "ingredient_id": "0fc93141-8ba8-42e0-ac8b-b5af3851554c", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 175\u00b0C (350\u00b0F). Grease a 20cm (8-inch) square baking dish with butter or neutral oil.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a wide shallow bowl, whisk together eggs, 80ml sweet red wine, vanilla extract, 3g cinnamon, and salt until completely thoroughly combined.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "assemble", "text": "Dip a sheet of matzo into the egg mixture, letting it soak for about 30 seconds per side until slightly pliable but not falling apart. Break pieces if necessary to fit a single layer into the bottom of the baking dish.", "structured": {"action": "SOAK", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Spread a thin layer of strawberry preserves (about 2 tablespoons) over the soaked matzo base. Repeat the dipping and layering process until all matzo is used, ending with a soaked matzo layer on top. Do not top the final layer with jam.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour any remaining egg batter over the assembled layers. Bake for 30-35 minutes, or until the custard is set and the top is beginning to brown.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT35M", "doneness_cues": {"visual": "Top is golden brown and puffed", "tactile": "Center is firm to the touch"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "While the bars bake, combine butter, honey, and the optional splash of wine in a small saucepan over medium heat. Simmer for 2-3 minutes until the mixture foams and slightly thickens.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Immediately upon removing the dish from the oven, pour the hot honey-butter glaze evenly over the surface. Let the bars cool completely in the pan to allow the layers to set before slicing.", "structured": {"action": "GLAZE", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT45M", "total_time": "PT1H10M", "overnight_required": false, "yields": "9 bars", "yield_count": 9, "serving_size_g": 110}', '{"flags": ["Vegetarian", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Infants under 12 months (honey)"]}', '{"per_serving": {"calories": 256.98, "protein_g": 5.14, "carbohydrates_g": 42.6, "fat_g": 6.42, "saturated_fat_g": 3.33, "trans_fat_g": 0.01, "monounsaturated_fat_g": 1.98, "polyunsaturated_fat_g": 0.57, "fiber_g": 1.06, "sugar_g": 22.2, "sodium_mg": 80.44, "cholesterol_mg": 93.42, "potassium_mg": 74.97, "calcium_mg": 26.65, "iron_mg": 1.77, "magnesium_mg": 14.25, "phosphorus_mg": 86.66, "zinc_mg": 0.6, "vitamin_a_mcg": 69.82, "vitamin_c_mg": 1.44, "vitamin_d_mcg": 0.44, "vitamin_e_mg": 0.36, "vitamin_k_mcg": 0.56, "vitamin_b6_mg": 0.04, "vitamin_b12_mcg": 0.21, "thiamin_mg": 0.01, "riboflavin_mg": 0.11, "niacin_mg": 0.03, "folate_mcg": 10.75, "water_g": 28.5, "alcohol_g": 1.17, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container; texture becomes denser when chilled.", "duration": "P4D"}, "freezer": {"notes": "Freeze individually wrapped; thaw in refrigerator.", "duration": "P2M"}, "reheating": "Warm gently in a 150\u00b0C oven for 5-10 minutes to crisp the top.", "does_not_keep": false}', '[{"name": "Square baking dish (20cm / 8-inch)", "required": true, "alternative": null}, {"name": "Wide shallow bowl", "required": true, "alternative": "Pie dish"}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Pastry brush", "required": false, "alternative": null}]', '[{"symptom": "Bars are soggy or falling apart", "likely_cause": "Matzo was soaked too long in the batter before baking", "prevention": "Dip matzo only until it begins to soften (30-45 seconds max); do not let it turn into mush before layering.", "fix": "Bake for an additional 10-15 minutes at a lower temperature (150\u00b0C/300\u00b0F) to dry out excess moisture."}]', '["Using sweet red wine (like Manischewitz or a Ruby Port) in the batter mimics the flavor profile of Charoset and adds a beautiful purple hue to the interior.", "If your strawberry preserves are very chunky, pulse them briefly in a blender or mash them with a fork for easier spreading between delicate matzo layers.", "These bars cut most cleanly after being chilled in the refrigerator for at least 2 hours, though they are delicious served warm.", "For a crunchy texture variation, sprinkle crushed walnuts or pecans on top of the glaze immediately after pouring (if nuts are permitted)."]', '"This recipe riffs on the concept of ''Matzo Mina'' (a Sephardic layered pie) and sweet Matzo Brei. It incorporates the symbolic use of wine and unleavened bread central to Passover, transforming humble pantry staples into a rich, sticky confection."', 256.98);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('439561f7-4028-4c78-b766-a54f957d6b43', 'Bittersweet Chocolate Cluster Granola', 'Deeply chocolatey, dangerously snackable granola featuring large, craggy clusters. The combination of Dutch-process cocoa and chopped dark chocolate provides a sophisticated bittersweet profile, while the ''no-stir'' method creates a cookie-like crunch.', 'breakfast', 'American', 'Easy', '["cocoa powder", "freezer friendly", "granola", "great leftovers", "nut", "rolled oat", "seeds", "breakfast", "snack", "vegetarian"]', '[{"group_name": "Dry Mix", "items": [{"name": "old-fashioned rolled oats", "quantity": 300, "unit": "g", "preparation": "raw", "notes": "do not use quick oats", "substitutions": [], "ingredient_id": "4490fcb6-a551-427f-885d-b3589c1c21c2", "nutrition_source": "USDA FoodData Central"}, {"name": "raw pecans", "quantity": 120, "unit": "g", "preparation": "roughly chopped", "notes": null, "substitutions": ["walnuts", "almonds", "hazelnuts"], "ingredient_id": "a5c5ee79-2bcd-4ab2-aed5-b09d0a3df4b5", "nutrition_source": "USDA FoodData Central"}, {"name": "pumpkin seeds", "quantity": 40, "unit": "g", "preparation": "raw", "notes": "pepitas", "substitutions": ["sunflower seeds"], "ingredient_id": "a3032561-6f55-4103-a6f6-b13cd6bd9b3c", "nutrition_source": "Aggregated Public Data"}, {"name": "unsweetened cocoa powder", "quantity": 30, "unit": "g", "preparation": null, "notes": "Dutch-process preferred for darker color", "substitutions": [], "ingredient_id": "c06a8e5a-163a-4f21-ad00-a6d90e34c38c", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 4, "unit": "g", "preparation": null, "notes": "flakey salt works best", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wet Binder", "items": [{"name": "maple syrup", "quantity": 160, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": ["honey", "agave nectar"], "ingredient_id": "1358a800-6e05-4bfd-ab71-03e78728c0bc", "nutrition_source": "Aggregated Public Data"}, {"name": "coconut oil", "quantity": 80, "unit": "ml", "preparation": "melted", "notes": null, "substitutions": ["melted unsalted butter", "olive oil"], "ingredient_id": "bfc74b81-e1e0-4607-9eec-8d0eff76d78c", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Add-ins", "items": [{"name": "dark chocolate (70%)", "quantity": 100, "unit": "g", "preparation": "chopped into chunks", "notes": "aim for 1cm chunks", "substitutions": [], "ingredient_id": "08395d12-1a43-46f7-b602-36c2d07ce259", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 150\u00b0C/300\u00b0F. Line a large rimmed baking sheet with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large bowl, combine oats, chopped pecans, pumpkin seeds, cocoa powder, and sea salt. Stir until the cocoa powder evenly coats the dry ingredients.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a smaller bowl or jug, whisk together the maple syrup, melted coconut oil, and vanilla extract until emulsified.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Pour the wet mixture over the dry ingredients. Mix thoroughly with a spatula for 1-2 minutes until every oat flake is dark and glossy.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Take your time here; dry pockets of cocoa powder will burn."]}, {"step_number": 5, "phase": "cook", "text": "Transfer the mixture to the prepared baking sheet. Spread it out, then use the back of the spatula to firmly press and compact the mixture into a single, even layer. This compression is critical for cluster formation.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Bake for 40-45 minutes. Do not stir. The granola is done when it smells nutty and feels dry to the touch, though it will still be soft until cooled.", "structured": {"action": "BAKE", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": "PT45M", "doneness_cues": {"visual": "Dry appearance", "tactile": "Firm but soft if pressed"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from the oven and let cool completely on the pan without touching it, about 1 hour. It will crisp up significantly as it cools.", "structured": {"action": "COOL", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Once fully cooled and hardened, break the sheet into large chunks. scatter the chopped dark chocolate over the clusters and toss gently to combine.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT2H", "total_time": "PT2H15M", "overnight_required": false, "yields": "Approx. 800g", "yield_count": 16, "serving_size_g": 50}', '{"flags": ["Vegetarian", "Vegan", "Dairy-Free", "Egg-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 250.7, "protein_g": 5.36, "carbohydrates_g": 24.84, "fat_g": 15.53, "saturated_fat_g": 6.56, "trans_fat_g": 0.01, "monounsaturated_fat_g": 4.59, "polyunsaturated_fat_g": 2.27, "fiber_g": 4.05, "sugar_g": 8.6, "sodium_mg": 99.8, "cholesterol_mg": 0.38, "potassium_mg": 217.03, "calcium_mg": 29.64, "iron_mg": 1.97, "magnesium_mg": 79.56, "phosphorus_mg": 179.89, "zinc_mg": 1.72, "vitamin_a_mcg": 0.44, "vitamin_c_mg": 0.13, "vitamin_d_mcg": null, "vitamin_e_mg": 0.15, "vitamin_k_mcg": 0.79, "vitamin_b6_mg": 0.04, "vitamin_b12_mcg": 0.01, "thiamin_mg": 0.2, "riboflavin_mg": 0.04, "niacin_mg": 0.36, "folate_mcg": 12.75, "water_g": 2.11, "alcohol_g": 0.11, "caffeine_mg": 9.69}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Not recommended; humidity softens the clusters.", "duration": null}, "freezer": {"notes": "Store in an airtight bag; eat straight from freezer for extra crunch.", "duration": "P3M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Rimmed baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": "Silicone baking mat"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Spatula", "required": true, "alternative": null}]', '[{"symptom": "Granola is loose and powdery (no clusters)", "likely_cause": "The mixture was stirred during baking or not packed down firmly enough before baking.", "prevention": "Press the mixture firmly into the pan before baking and let it cool completely undisturbed.", "fix": "Enjoy as a loose muesli-style topping for yogurt."}, {"symptom": "Granola tastes burnt or bitter", "likely_cause": "Oven temperature was too high or cocoa powder scorched.", "prevention": "Stick to 150\u00b0C/300\u00b0F and monitor closely near the end.", "fix": "Cannot be fixed."}]', '["The secret to giant clusters is ''compression and patience''. Press the raw mixture down firmly, and absolutely do not touch it until it is 100% cool.", "Use a high-quality chocolate bar for the chunks rather than chocolate chips. Chips contain stabilizers that give them a waxy texture, while bar chocolate melts pleasantly on the tongue.", "If you prefer the chocolate slightly melted onto the clusters, sprinkle the chocolate chunks over the granola 5 minutes after taking it out of the oven, while it is still warm but not piping hot.", "Salt is essential here to bridge the gap between the earthy oats and the bittersweet cocoa; do not skip it."]', '"Granola originated in the United States in the late 19th century as a health food called ''Granula'', invented by Dr. James Caleb Jackson. While originally a dry, bland whole grain product, the 1960s counterculture movement revitalized it with sweeteners and fats, transforming it into the indulgent, cluster-filled snack we recognize today."', 250.7);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('4443910a-61d9-4586-9173-a7819ad4ae15', 'Spring Morel and Asparagus Frittata', 'A celebration of spring terroir, combining the deep, earthy umami of morel mushrooms with the bright, grassy crunch of fresh asparagus. Encased in a velvety, Parmesan-enriched egg custard that puffs beautifully in the oven.', 'main course', 'Italian', 'Intermediate', '["asparagus", "egg", "morel", "dinner", "appetizer", "main course", "vegetarian", "italian", "spring", "gluten-free"]', '[{"group_name": "Vegetables & Aromatics", "items": [{"name": "fresh morel mushrooms", "quantity": 150, "unit": "g", "preparation": "cleaned and halved lengthwise", "notes": "Ensure all grit is removed; if using dried, rehydrate 30g", "substitutions": [], "ingredient_id": "59d83971-a3c1-4b9c-b949-625005657048", "nutrition_source": "USDA FoodData Central"}, {"name": "asparagus spears", "quantity": 200, "unit": "g", "preparation": "woody ends trimmed, cut into 3cm pieces", "notes": null, "substitutions": [], "ingredient_id": "8a2a9426-3755-4553-953a-fd9cf42cef90", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "approx 30g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "divided", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Custard Base", "items": [{"name": "large eggs", "quantity": 8, "unit": null, "preparation": null, "notes": "approx 400g total weight", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 60, "unit": "ml", "preparation": "cold", "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "parmigiano reggiano", "quantity": 60, "unit": "g", "preparation": "freshly grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh chives", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven''s broiler (grill setting) to high. Position the rack about 15cm (6 inches) from the heat source.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 260, "fahrenheit": 500}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large bowl, vigorously whisk eggs, heavy cream, grated Parmesan, chives, salt, and pepper until the mixture is aerated and uniform.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat 20g of butter in the oven-safe skillet over medium heat. Add the minced shallot and saut\u00e9 until softened and translucent, about 2-3 minutes.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the morel mushrooms and remaining 10g butter to the skillet. Cook undisturbed for 2 minutes to brown, then stir. Continue cooking until the mushrooms are tender and any liquid they released has completely evaporated. Morels must be thoroughly cooked for safety.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT6M", "doneness_cues": {"visual": "Mushrooms browned, pan dry", "tactile": "Mushrooms tender"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the asparagus pieces and minced garlic. Saut\u00e9 for another 2-3 minutes until the asparagus is bright green and crisp-tender.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Reduce heat to medium-low. Pour the egg mixture over the vegetables. Use a spatula to gently distribute the vegetables evenly. Let cook undisturbed on the stovetop until the edges begin to set and pull away from the pan, but the center is still runny.", "structured": {"action": "COOK", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Edges set, center loose", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Transfer the skillet to the oven under the broiler. Broil until the frittata is puffed, golden brown on top, and the center is set (internal temperature should reach 74\u00b0C/165\u00b0F). Watch closely to prevent burning.", "structured": {"action": "BROIL", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from oven (handle will be hot). Let rest for 5 minutes to allow the residual heat to finish setting the custard before slicing.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT10M", "total_time": "PT35M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 180}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Keto", "Low-Carb"], "not_suitable_for": []}', '{"per_serving": {"calories": 224.56, "protein_g": 14.07, "carbohydrates_g": 4.95, "fat_g": 16.72, "saturated_fat_g": 8.43, "trans_fat_g": 0.15, "monounsaturated_fat_g": 5.29, "polyunsaturated_fat_g": 1.77, "fiber_g": 1.66, "sugar_g": 1.73, "sodium_mg": 416.66, "cholesterol_mg": 276.85, "potassium_mg": 309.21, "calcium_mg": 187.63, "iron_mg": 5.14, "magnesium_mg": 24.87, "phosphorus_mg": 279.74, "zinc_mg": 1.89, "vitamin_a_mcg": 226.28, "vitamin_c_mg": 3.56, "vitamin_d_mcg": 2.82, "vitamin_e_mg": 1.31, "vitamin_k_mcg": 15.24, "vitamin_b6_mg": 0.22, "vitamin_b12_mcg": 0.74, "thiamin_mg": 0.1, "riboflavin_mg": 0.46, "niacin_mg": 0.99, "folate_mcg": 53.92, "water_g": 118.35, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Good cold or reheated.", "duration": "P3D"}, "freezer": {"notes": "Texture may become slightly spongy upon thawing.", "duration": "P1M"}, "reheating": "Warm gently in a low oven (150\u00b0C) or microwave in short bursts to avoid rubbery eggs.", "does_not_keep": false}', '[{"name": "Oven-safe skillet (25-30cm)", "required": true, "alternative": "Cast iron pan"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}]', '[{"symptom": "Frittata is watery or weeps liquid", "likely_cause": "Vegetables were not cooked down enough before adding eggs", "prevention": "Ensure all moisture from the mushrooms and asparagus has evaporated in the skillet before pouring in the egg mixture", "fix": "Drain excess liquid from the plate; cannot be fixed in the pan"}, {"symptom": "Bottom is burnt before top is set", "likely_cause": "Stovetop heat was too high", "prevention": "Lower heat to medium-low once eggs are added", "fix": "Trim the burnt bottom off before serving"}]', '["Morel cleaning: Morels have a honeycomb structure that traps dirt. Slice them lengthwise and rinse briefly but thoroughly immediately before cooking, then pat very dry.", "Texture tip: Adding the dairy (cream) prevents the protein structure of the eggs from tightening too much, ensuring a creamy rather than rubbery texture.", "Serving: This dish is excellent served warm, but arguably better at room temperature when the flavors have had time to meld.", "Substitutions: If wild morels are unavailable, rehydrated dried porcini or fresh shiitake mushrooms make excellent earthy alternatives.", "Safety: Never eat morels raw; they contain hydrazine toxins which are eliminated through thorough cooking."]', '"The frittata is a cornerstone of Italian ''cucina povera'' (peasant cooking), traditionally used to rescue leftovers. However, this version elevates the humble template into a luxurious dish by utilizing highly prized seasonal ingredients\u2014morels and spring asparagus\u2014highlighting the Italian reverence for fresh, seasonal produce."', 224.56);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('44b1bcca-cb2a-4e47-84c8-3bebb07d26cc', 'Lebanese Maghmour (Eggplant and Chickpea Stew)', 'A comforting, silky stew often called ''Lebanese Moussaka.'' Tender roasted eggplant cubes and nutty chickpeas melt into a rich tomato sauce, finished with a bright streak of pomegranate molasses and zesty sumac.', 'dinner', 'Lebanese', 'Easy', '["vegetables", "chickpea", "crushed canned tomato", "eggplant", "pomegranate molasses", "sumac", "dinner", "easy", "weeknight", "main course", "side dish", "fall", "spring", "summer", "winter", "vegetarian", "vegan", "lebanese"]', '[{"group_name": "Roasted Eggplant", "items": [{"name": "eggplant", "quantity": 2, "unit": null, "preparation": "cut into 2.5cm cubes", "notes": "approx. 700g total", "substitutions": [], "ingredient_id": "77c14307-dacf-4ab2-85d1-3594bff0ec99", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Stew Base", "items": [{"name": "onion", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "minced", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "dried mint", "quantity": 2, "unit": "g", "preparation": null, "notes": "crushed", "substitutions": [], "ingredient_id": "a55f18a7-6ba1-4fa7-8bde-b8d2e2d13e84", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "crushed canned tomatoes", "quantity": 400, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "49a62ca7-db63-4d23-9f6f-2cf873fba8a3", "nutrition_source": "Aggregated Public Data"}, {"name": "chickpeas", "quantity": 240, "unit": "g", "preparation": "cooked/canned", "notes": "drained weight", "substitutions": [], "ingredient_id": "145073f5-45bb-493b-bc45-ce71653e9f26", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 120, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Finish", "items": [{"name": "pomegranate molasses", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "9fbf5b84-64fe-449a-aa4e-5ed59a0cfd69", "nutrition_source": "Aggregated Public Data"}, {"name": "sumac", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a5373aa1-db38-4196-af5e-07242d66489f", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 200\u00b0C (400\u00b0F). Toss the cubed eggplant with 45ml olive oil and salt on a large baking sheet, arranging them in a single layer.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Roast the eggplant for 25-30 minutes, turning halfway through, until golden brown and completely tender.", "structured": {"action": "ROAST", "temperature": null, "duration": "PT30M", "doneness_cues": {"visual": "Golden brown edges", "tactile": "Soft interior"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "While eggplant roasts, heat 15ml olive oil in a Dutch oven over medium heat. Saut\u00e9 the diced onion for 5-7 minutes until translucent and soft.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Translucent onion", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add minced garlic, dried mint, and cinnamon. Stir constantly for 1 minute until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour in the crushed tomatoes, water, and drained chickpeas. Bring to a simmer.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Gently fold in the roasted eggplant cubes. Cover and simmer on low heat for 15 minutes to meld flavors without breaking the eggplant.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from heat. Stir in the pomegranate molasses. Taste and adjust salt if needed.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Transfer to a serving dish and garnish generously with sumac and fresh chopped parsley.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT40M", "total_time": "PT1H", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 321.87, "protein_g": 8.54, "carbohydrates_g": 37.61, "fat_g": 17.74, "saturated_fat_g": 2.32, "trans_fat_g": null, "monounsaturated_fat_g": 11.29, "polyunsaturated_fat_g": 2.34, "fiber_g": 12.91, "sugar_g": 15.25, "sodium_mg": 846.97, "cholesterol_mg": null, "potassium_mg": 909.75, "calcium_mg": 131.33, "iron_mg": 4.13, "magnesium_mg": 69.89, "phosphorus_mg": 145.33, "zinc_mg": 1.1, "vitamin_a_mcg": 75.56, "vitamin_c_mg": 20.48, "vitamin_d_mcg": null, "vitamin_e_mg": 2.9, "vitamin_k_mcg": 58.47, "vitamin_b6_mg": 0.31, "vitamin_b12_mcg": null, "thiamin_mg": 0.12, "riboflavin_mg": 0.1, "niacin_mg": 1.36, "folate_mcg": 80.98, "water_g": 269, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors improve significantly after resting overnight.", "duration": "P4D"}, "freezer": {"notes": "Texture of eggplant may become slightly softer upon thawing.", "duration": "P3M"}, "reheating": "Reheat gently on the stove or serve at room temperature.", "does_not_keep": false}', '[{"name": "Large baking sheet", "required": true, "alternative": null}, {"name": "Dutch oven or heavy-bottomed pot", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}]', '[{"symptom": "Eggplant is tough or spongy", "likely_cause": "Undercooked during the roasting phase", "prevention": "Ensure eggplant is thoroughly golden and soft before adding to the stew", "fix": "Add a splash more water to the stew and simmer covered for an extra 10-15 minutes until tender"}]', '["Maghmour is traditionally served warm or at room temperature; the flavors are actually better the next day, making it an excellent meal-prep candidate.", "If your canned tomatoes are very acidic, add a pinch of sugar to balance the flavors before adding the pomegranate molasses.", "Roasting the eggplant instead of the traditional deep-frying makes this dish lighter and easier for weeknight cooking, but ensure you use enough oil so it doesn''t dry out.", "Serve with warm pita bread or vermicelli rice to soak up the sauce."]', '"Maghmour is a staple Levantine dish, often referred to as ''The Moussaka of Lebanon.'' Unlike the Greek version which contains meat and b\u00e9chamel, the Lebanese version is naturally vegan and focuses on the harmony between the earthiness of eggplant and the brightness of tomato and pomegranate."', 321.87);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('46047a29-5679-448b-86c5-7b0684181de2', 'Quick 5-Ingredient Leftover Fried Rice', 'A rapid, texture-focused technique to revive cold leftovers into a cohesive, savory meal. Cold rice grains are revitalized in a hot wok to achieve a nutty aroma and chewy texture, bound together with fluffy egg and savory soy sauce.', 'lunch', 'Fusion', 'Easy', '["five ingredient", "meat", "rice", "vegetables", "easy", "lunch", "quick", "leftovers"]', '[{"group_name": "Main Components", "items": [{"name": "cooked rice", "quantity": 400, "unit": "g", "preparation": "cold, preferably day-old", "notes": "Jasmine or short-grain works best", "substitutions": ["quinoa", "brown rice"], "ingredient_id": "d8a2c73d-e2de-4182-b43b-6bdf55f00a87", "nutrition_source": "USDA FoodData Central"}, {"name": "cooked meat", "quantity": 150, "unit": "g", "preparation": "diced small", "notes": "Leftover chicken, beef, or pork", "substitutions": ["tofu", "tempeh"], "ingredient_id": "0258ca78-fe20-439b-94bc-30619460372b", "nutrition_source": "USDA FoodData Central"}, {"name": "mixed vegetables", "quantity": 100, "unit": "g", "preparation": "diced or frozen", "notes": "Peas, carrots, corn, or leftover roasted veg", "substitutions": [], "ingredient_id": "38e3e2ee-2b9c-4edd-b22f-9e83ea59ed65", "nutrition_source": "Aggregated Public Data"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "beaten", "notes": "approx 100g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Pantry Staples", "items": [{"name": "soy sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": "Light soy sauce preferred", "substitutions": ["tamari", "coconut aminos"], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "High smoke point oil", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Heat vegetable oil in a wok or large skillet over high heat until shimmering.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add the diced cooked meat and vegetables. Stir-fry rapidly to remove excess moisture and heat them through.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Vegetables look bright; meat edges crisping", "tactile": "Sizzling sound"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Push the meat and vegetables to one side of the pan. Pour the beaten eggs into the empty space and scramble quickly until just set but still moist.", "structured": {"action": "SCRAMBLE", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Curds formed but glossy", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the cold cooked rice, breaking up any clumps with the spatula. Toss everything together to combine.", "structured": {"action": "MIX", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": ["Cold rice is crucial; warm fresh rice will turn mushy in the pan."]}, {"step_number": 5, "phase": "finish", "text": "Drizzle the soy sauce around the perimeter of the hot pan (not directly on the rice) to caramelize it instantly. Toss rapidly to coat every grain evenly. Ensure internal temperature reaches at least 74\u00b0C/165\u00b0F.", "structured": {"action": "SEASON", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Rice is uniformly golden brown", "tactile": "Steaming hot throughout"}}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT0M", "total_time": "PT10M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 350}', '{"flags": ["Dairy-Free", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 635, "protein_g": 33.24, "carbohydrates_g": 62.21, "fat_g": 26.62, "saturated_fat_g": 8.04, "trans_fat_g": 0.89, "monounsaturated_fat_g": 8.25, "polyunsaturated_fat_g": 1.49, "fiber_g": 3.85, "sugar_g": 4.18, "sodium_mg": 2633.25, "cholesterol_mg": 252.75, "potassium_mg": 580.5, "calcium_mg": 118.08, "iron_mg": 6.95, "magnesium_mg": 39, "phosphorus_mg": 360.5, "zinc_mg": 5.85, "vitamin_a_mcg": 475.58, "vitamin_c_mg": 4.65, "vitamin_d_mcg": 1, "vitamin_e_mg": 0.64, "vitamin_k_mcg": 2.4, "vitamin_b6_mg": 0.73, "vitamin_b12_mcg": 2.55, "thiamin_mg": 0.48, "riboflavin_mg": 0.42, "niacin_mg": 8.3, "folate_mcg": 195.25, "water_g": 220.75, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Fried rice made from leftovers should not be reheated a second time for food safety reasons.", "duration": "P1D"}, "freezer": {"notes": "Texture degrades significantly upon freezing.", "duration": null}, "reheating": "Microwave with a splash of water or stir-fry briefly to restore temperature.", "does_not_keep": false}', '[{"name": "Wok or large skillet", "required": true, "alternative": "Cast iron pan"}, {"name": "Spatula", "required": true, "alternative": null}]', '[{"symptom": "Rice is mushy or sticky", "likely_cause": "Rice was too fresh or warm when added, or pan was overcrowded", "prevention": "Always use day-old cold rice; cook in batches if scaling up", "fix": "Spread rice thin in pan and let sit on high heat without stirring to crisp up the bottom"}]', '["The secret to restaurant-style fried rice is high heat and cold rice. The cold starch structure prevents the grains from sticking together.", "Pouring soy sauce down the sides of the hot wok creates a ''wok hei'' smoky flavor as the sugars caramelize before touching the rice.", "Since the protein is already cooked, add it late in the process just to warm through so it doesn''t become tough.", "Any neutral oil works, but a drop of sesame oil at the very end (off heat) adds great aroma."]', '"Fried rice originated in China as a way to avoid food waste, turning leftover cold rice into a filling meal. Every Asian culture has its own variation, from Nasi Goreng in Indonesia to Chaahan in Japan, all united by the principle of efficient resourcefulness."', 635);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('461f0743-7b4c-4e5d-93bf-88fa5f6bdd38', 'Roasted Carrots with Encacahuatado', 'Sweet, caramelized roasted carrots served over a bed of wilted spinach and smothered in Encacahuatado, a rich, smoky Mexican peanut mole. The sauce combines the earthiness of toasted peanuts with the complex, mild heat of Ancho and Guajillo chilies.', 'side dish', 'Mexican', 'Intermediate', '["vegetables", "ancho chile", "carrot", "ground cumin", "guajillo chile", "party", "peanut", "spinach", "vegetable broth", "dinner", "side dish", "dairy-free", "gluten-free", "healthy", "vegan", "vegetarian"]', '[{"group_name": "Roasted Carrots", "items": [{"name": "carrots", "quantity": 800, "unit": "g", "preparation": "peeled and halved lengthwise", "notes": "use slender carrots for best presentation", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Encacahuatado (Peanut Sauce)", "items": [{"name": "dried ancho chilies", "quantity": 2, "unit": null, "preparation": null, "notes": "stemmed and seeded, approx 30g", "substitutions": [], "ingredient_id": "31d5e9d5-d288-426a-920a-a7b77822dc2f", "nutrition_source": "Aggregated Public Data"}, {"name": "dried guajillo chilies", "quantity": 2, "unit": null, "preparation": null, "notes": "stemmed and seeded, approx 15g", "substitutions": [], "ingredient_id": "a6e13bb7-a70a-4480-a3f2-0be6330e4d34", "nutrition_source": "Aggregated Public Data"}, {"name": "roasted unsalted peanuts", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "ba36d967-879c-446b-ba1e-b1fa36e475db", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable broth", "quantity": 400, "unit": "ml", "preparation": null, "notes": "ensure gluten-free certified", "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "white onion", "quantity": 100, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": null, "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "cinnamon stick", "quantity": 1, "unit": null, "preparation": null, "notes": "small piece, approx 2cm", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "Aggregated Public Data"}, {"name": "apple cider vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "grapeseed or canola", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Spinach Bed", "items": [{"name": "fresh spinach", "quantity": 300, "unit": "g", "preparation": "washed", "notes": null, "substitutions": [], "ingredient_id": "4734440a-226d-4d26-a110-3ed5c3bde93f", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat oven to 220\u00b0C (425\u00b0F). In a dry skillet over medium heat, toast the dried Ancho and Guajillo chilies for 30-60 seconds per side until fragrant but not black. Transfer to a heat-proof bowl and cover with boiling water. Let soak for 15 minutes.", "structured": {"action": "TOAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT15M", "doneness_cues": {"visual": "Skins turn slightly lighter red", "tactile": "Pliable after soaking"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Toss carrots with 30ml olive oil and 5g salt on a baking sheet. Roast for 25-30 minutes, turning halfway through, until tender and caramelized at the edges.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT30M", "doneness_cues": {"visual": "Golden brown edges", "tactile": "Fork tender"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "While carrots roast and chilies soak, heat 15ml neutral oil in the saucepan over medium heat. Saut\u00e9 chopped onion, garlic, and cinnamon stick until the onions are soft and translucent, about 5-7 minutes. Stir in cumin and cook for 30 seconds until fragrant. Remove cinnamon stick.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Translucent onions", "tactile": "Soft texture"}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Drain the chilies (discard soaking water). In a blender, combine the softened chilies, saut\u00e9ed onion mixture, peanuts, vegetable broth, and apple cider vinegar. Blend on high until completely smooth and creamy.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Smooth, uniform orange-brown color", "tactile": "Velvety texture"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Pour the sauce back into the saucepan. Simmer over low heat for 5-10 minutes to thicken and marry the flavors. Season with salt to taste. If too thick, add a splash more broth or water.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT10M", "doneness_cues": {"visual": "Coats the back of a spoon (nappe)", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Just before serving, heat 10ml olive oil in the skillet. Add fresh spinach and a pinch of salt. Toss quickly over medium-high heat until just wilted (about 1-2 minutes).", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Bright green and collapsed", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Spread the wilted spinach on a platter. Arrange roasted carrots on top. Generously ladle the hot peanut sauce over the carrots. Garnish with chopped peanuts or cilantro if desired.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT15M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": ["Nut allergies", "Peanut allergies"]}', '{"per_serving": {"calories": 285.57, "protein_g": 6.54, "carbohydrates_g": 34, "fat_g": 15.57, "saturated_fat_g": 2.17, "trans_fat_g": null, "monounsaturated_fat_g": 7.51, "polyunsaturated_fat_g": 1.43, "fiber_g": 10.31, "sugar_g": 13.92, "sodium_mg": 1363.5, "cholesterol_mg": null, "potassium_mg": 1349.3, "calcium_mg": 185.07, "iron_mg": 4.92, "magnesium_mg": 101.84, "phosphorus_mg": 146.47, "zinc_mg": 1.15, "vitamin_a_mcg": 3271.65, "vitamin_c_mg": 36.69, "vitamin_d_mcg": null, "vitamin_e_mg": 4.35, "vitamin_k_mcg": 395.06, "vitamin_b6_mg": 0.51, "vitamin_b12_mcg": null, "thiamin_mg": 0.23, "riboflavin_mg": 0.28, "niacin_mg": 2.62, "folate_mcg": 188.52, "water_g": 273.3, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store sauce and vegetables separately if possible to maintain texture.", "duration": "P4D"}, "freezer": {"notes": "Sauce freezes perfectly; fresh carrots and spinach do not freeze well after cooking.", "duration": "P3M"}, "reheating": "Gently warm sauce on stovetop, thinning with water if needed. Reheat carrots in oven.", "does_not_keep": false}', '[{"name": "Baking sheet", "required": true, "alternative": null}, {"name": "High-speed blender", "required": true, "alternative": "Food processor"}, {"name": "Medium saucepan", "required": true, "alternative": null}, {"name": "Skillet", "required": true, "alternative": null}, {"name": "Heat-proof bowl", "required": true, "alternative": null}]', '[{"symptom": "Sauce tastes bitter", "likely_cause": "Chilies were toasted too long and burned", "prevention": "Toast chilies only until fragrant; do not let them turn black", "fix": "Add a teaspoon of sugar or agave syrup and a squeeze of lime to mask the bitterness"}, {"symptom": "Sauce is grainy", "likely_cause": "Blender not powerful enough or blended too briefly", "prevention": "Use a high-speed blender or soak nuts beforehand", "fix": "Pass the sauce through a fine-mesh sieve"}]', '["Discard the chili soaking water as it can be bitter; use fresh vegetable broth for the liquid base to ensure a clean flavor profile.", "The sauce (Encacahuatado) is traditional to central Mexico and should have a consistency similar to heavy cream\u2014thick enough to cling to the carrots but fluid enough to pour.", "For extra depth, you can roast the garlic and onion in the oven alongside the carrots instead of saut\u00e9ing them.", "If you cannot find Ancho or Guajillo chilies, a blend of dried New Mexico chilies or Pasilla chilies can work, though the flavor nuances will shift."]', '"This dish is inspired by ''Encacahuatado'', a traditional Mexican mole made primarily from peanuts (''cacahuates'') and dried chilies. While often served with chicken or pork, the rich, nutty profile pairs exceptionally well with the natural sweetness of roasted root vegetables, highlighting the plant-based versatility of Mexican cuisine."', 285.57);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('465c9d1f-f720-4c53-89bc-11323c7c4866', 'Braised Beef with Comté Macaroni Gratin', 'Fork-tender chunks of beef chuck braised slowly in red wine and aromatics, paired with a luxurious macaroni gratin featuring nutty, aged Comté cheese and a golden, bubbling crust. A comforting French bistro classic.', 'dinner', 'French', 'Intermediate', '["beef", "braised", "macaroni", "cheese", "gratin", "comfort food", "french", "winter"]', '[{"group_name": "Braised Beef", "items": [{"name": "beef chuck roast", "quantity": 800, "unit": "g", "preparation": "cut into 4-5cm cubes", "notes": "remove large pieces of hard fat", "substitutions": [], "ingredient_id": "27a10c91-ef42-419e-be1e-3cf0405d2048", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "generous pinch for seasoning beef", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "onion", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "carrot", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx 100g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "celery stalk", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx 50g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "tomato paste", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "1a1bddc5-66c3-4f44-bb24-72b8ac828ca6", "nutrition_source": "Aggregated Public Data"}, {"name": "dry red wine", "quantity": 250, "unit": "ml", "preparation": null, "notes": "Cabernet Sauvignon or Merlot", "substitutions": [], "ingredient_id": "0fc93141-8ba8-42e0-ac8b-b5af3851554c", "nutrition_source": "USDA FoodData Central"}, {"name": "beef stock", "quantity": 500, "unit": "ml", "preparation": null, "notes": "low sodium preferred", "substitutions": [], "ingredient_id": "e20ba364-d350-445a-8498-9efaa678213a", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh thyme", "quantity": 4, "unit": null, "preparation": null, "notes": "sprigs", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "bay leaf", "quantity": 1, "unit": null, "preparation": null, "notes": "dried or fresh", "substitutions": [], "ingredient_id": "eab2ef3a-7a0e-4188-b746-645b795ada1e", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Comt\u00e9 Macaroni", "items": [{"name": "elbow macaroni", "quantity": 300, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "be98e6d4-2aef-4704-bb27-df939336265b", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 600, "unit": "ml", "preparation": "warmed", "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "comt\u00e9 cheese", "quantity": 200, "unit": "g", "preparation": "grated", "notes": "divided into 150g for sauce, 50g for topping", "substitutions": [], "ingredient_id": "8fa9c047-8cf9-49a3-ac27-36e69e66635a", "nutrition_source": "Aggregated Public Data"}, {"name": "dijon mustard", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "6bcca9cc-172f-4b2a-a4f9-6ca7000000eb", "nutrition_source": "Aggregated Public Data"}, {"name": "ground nutmeg", "quantity": null, "unit": null, "preparation": null, "notes": "1/4 tsp or to taste", "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 160\u00b0C/320\u00b0F. Pat the beef cubes dry with paper towels and season generously with salt and pepper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat vegetable oil in a Dutch oven over medium-high heat. Sear the beef in batches until deeply browned on all sides, about 8-10 minutes total. Remove beef and set aside.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Deep brown crust developed", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to medium. Add onions, carrots, and celery to the pot. Saut\u00e9 for 5-6 minutes until softened. Stir in minced garlic and tomato paste, cooking for 1 minute until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT7M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour in the red wine to deglaze, scraping up the browned bits from the bottom of the pot. Let it simmer for 3 minutes to reduce slightly.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Return the beef and any resting juices to the pot. Add beef stock, thyme sprigs, and bay leaf. Bring to a simmer, cover with a lid, and transfer to the preheated oven (160\u00b0C/320\u00b0F). Braise for 2.5 to 3 hours until the beef is very tender.", "structured": {"action": "BRAISE", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT3H", "doneness_cues": {"visual": null, "tactile": "Fork-tender, falling apart with gentle pressure"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "When the beef has 30 minutes left, increase oven temperature to 200\u00b0C/400\u00b0F (do this only if your pot can handle the heat change, otherwise remove beef to rest). Bring a large pot of salted water to a boil and cook macaroni 2 minutes less than package directions (al dente). Drain.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "In a saucepan, melt butter over medium heat. Whisk in flour and cook for 1-2 minutes to form a roux, ensuring it doesn''t burn. Gradually whisk in warmed milk until smooth. Simmer for 5 minutes until thickened.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Thick enough to coat the back of a spoon", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Remove sauce from heat. Stir in 150g of the grated Comt\u00e9, Dijon mustard, nutmeg, salt, and pepper until cheese melts. Fold in the cooked macaroni.", "structured": {"action": "MIX", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Transfer the cheesy pasta to a baking dish. Top with the remaining 50g of Comt\u00e9. Bake at 200\u00b0C/400\u00b0F for 15-20 minutes until bubbling and golden brown. Serve hot alongside the braised beef.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT20M", "doneness_cues": {"visual": "Golden brown crust and bubbling edges", "tactile": null}}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT3H", "total_time": "PT3H45M", "overnight_required": false, "yields": "4 generous servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": [], "not_suitable_for": ["Gluten-Intolerant", "Lactose-Intolerant", "Vegetarians"]}', '{"per_serving": {"calories": 1312.23, "protein_g": 81.08, "carbohydrates_g": 85.99, "fat_g": 61.58, "saturated_fat_g": 10.38, "trans_fat_g": null, "monounsaturated_fat_g": 4.26, "polyunsaturated_fat_g": 1.11, "fiber_g": 5.56, "sugar_g": 13.36, "sodium_mg": 1735.54, "cholesterol_mg": 41.88, "potassium_mg": 1819.68, "calcium_mg": 707.86, "iron_mg": 9.05, "magnesium_mg": 77.09, "phosphorus_mg": 335.7, "zinc_mg": 1.75, "vitamin_a_mcg": 391.8, "vitamin_c_mg": 8.88, "vitamin_d_mcg": 1.95, "vitamin_e_mg": 0.62, "vitamin_k_mcg": 8.94, "vitamin_b6_mg": 0.29, "vitamin_b12_mcg": 0.7, "thiamin_mg": 0.91, "riboflavin_mg": 0.7, "niacin_mg": 6.15, "folate_mcg": 236.23, "water_g": 267.23, "alcohol_g": 5.81, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store beef and macaroni in separate airtight containers to maintain texture.", "duration": "P3D"}, "freezer": {"notes": "The beef freezes excellently. The macaroni can be frozen but texture may become grainy upon reheating.", "duration": "P2M"}, "reheating": "Reheat beef gently in a pot with a splash of water. Reheat macaroni in the oven covered with foil at 160\u00b0C/320\u00b0F.", "does_not_keep": false}', '[{"name": "Dutch oven or heavy-bottomed pot with lid", "required": true, "alternative": null}, {"name": "Large saucepan", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Baking dish (approx 20x30cm)", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "Beef is still tough after 3 hours", "likely_cause": "The cut of beef had particularly dense connective tissue or oven temperature runs low", "prevention": "Ensure pot lid is tight-fitting and verify oven temperature", "fix": "Add a splash more liquid if dry, cover tightly, and continue braising in 30-minute increments until tender"}]', '["Choose a Comt\u00e9 cheese aged 12-18 months for the best balance of meltability and nutty flavor. Younger cheese is too mild; very old cheese may split.", "For the beef, ''Chuck'' is the gold standard for braising due to its fat and collagen content. Lean cuts like round will dry out.", "The macaroni is cooked under al dente because it absorbs moisture from the sauce while baking. Fully cooking it in water first will result in mushy pasta."]', '"This dish marries the rustic French technique of ''Daube de B\u0153uf'' (Proven\u00e7al beef stew) with ''Gratin de Coquillettes'', a beloved French childhood staple often served in bistros. The use of Comt\u00e9, an Alpine cheese made from unpasteurized cow''s milk in the Franche-Comt\u00e9 region, elevates the pasta from a simple side to a gastronomic delight."', 1312.23);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('46f12c1f-5d86-492e-8ef5-2d650b2c6b9f', 'Ginger Sesame Baked White Fish', 'A virtuous and aromatic preparation for firm white fish that balances the nutty richness of toasted sesame oil with the zesty heat of fresh ginger. The finish of pickled ginger adds a bright, palate-cleansing acidity that cuts through the savory marinade.', 'dinner', 'Japanese', 'Easy', '["japanese", "cod", "ginger", "sesame seed", "dinner", "quick", "healthy", "gluten-free", "dairy-free", "low-carb"]', '[{"group_name": "Fish & Marinade", "items": [{"name": "firm white fish fillets", "quantity": 600, "unit": "g", "preparation": "pat dry", "notes": "Cod, Halibut, or Rockfish", "substitutions": ["Sea Bass", "Pollock"], "ingredient_id": "4ee613b2-b5c4-498b-a747-44157d0fb8c3", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 30, "unit": "g", "preparation": "grated or finely minced", "notes": "About a 5cm piece", "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "toasted sesame oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a9a59164-d949-4acd-99da-689f0a32e2e7", "nutrition_source": "Aggregated Public Data"}, {"name": "tamari or soy sauce", "quantity": 45, "unit": "ml", "preparation": null, "notes": "Use Tamari for Gluten-Free", "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "rice vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": "Unseasoned", "substitutions": [], "ingredient_id": "fcbf5252-1be9-4dd4-8c22-4fda1dbdca28", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish", "items": [{"name": "scallions", "quantity": 2, "unit": null, "preparation": "thinly sliced", "notes": "approx 30g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "toasted sesame seeds", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36a7664a-f96c-44b9-9b6d-cdd5e9e54f55", "nutrition_source": "Aggregated Public Data"}, {"name": "pickled ginger (gari)", "quantity": 30, "unit": "g", "preparation": "drained", "notes": null, "substitutions": [], "ingredient_id": "5cf94206-2d9c-4791-9758-31b05b6fa51a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 200\u00b0C (400\u00b0F). While the oven heats, grate the ginger and slice the scallions.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a small mixing bowl, whisk together the grated ginger, toasted sesame oil, tamari (or soy sauce), and rice vinegar until emulsified.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Place the fish fillets in the baking dish. Pour the marinade over the fish, turning the fillets to ensure they are evenly coated. Let stand at room temperature for 15-20 minutes.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": ["Do not marinate longer than 30 minutes, or the acid in the vinegar may begin to cure the fish texture."]}, {"step_number": 4, "phase": "cook", "text": "Bake the fish on the center rack for 10-12 minutes. The fish is done when it flakes easily with a fork and reaches an internal temperature of 63\u00b0C (145\u00b0F).", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT12M", "doneness_cues": {"visual": "Flesh is opaque and flakes easily", "tactile": "Firm but yielding"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Transfer the fish to serving plates. Garnish generously with toasted sesame seeds, sliced scallions, and a small mound of pickled ginger on the side.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT20M", "total_time": "PT35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Pescatarian", "Dairy-Free", "Egg-Free", "Gluten-Free", "Nut-Free", "Low-Carb", "Keto"], "not_suitable_for": ["Sesame allergy"]}', '{"per_serving": {"calories": 240.23, "protein_g": 26.11, "carbohydrates_g": 5.5, "fat_g": 12.36, "saturated_fat_g": 0.7, "trans_fat_g": null, "monounsaturated_fat_g": 1.08, "polyunsaturated_fat_g": 1.24, "fiber_g": 0.91, "sugar_g": 2.75, "sodium_mg": 2069.15, "cholesterol_mg": 61.5, "potassium_mg": 624.57, "calcium_mg": 141.65, "iron_mg": 2.49, "magnesium_mg": 58.81, "phosphorus_mg": 320.48, "zinc_mg": 1.18, "vitamin_a_mcg": 80.25, "vitamin_c_mg": 1.79, "vitamin_d_mcg": null, "vitamin_e_mg": 0.08, "vitamin_k_mcg": 15.7, "vitamin_b6_mg": 0.32, "vitamin_b12_mcg": 3, "thiamin_mg": 0.03, "riboflavin_mg": 0.11, "niacin_mg": 1.9, "folate_mcg": 28.2, "water_g": 139.13, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best stored in an airtight container. Flavor improves slightly, but texture is best fresh.", "duration": "P2D"}, "freezer": {"notes": "Not recommended; cooked white fish becomes watery upon thawing.", "duration": null}, "reheating": "Gently steam or microwave on low power to avoid drying out.", "does_not_keep": false}', '[{"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Microplane or ginger grater", "required": true, "alternative": "Chef''s knife (for mincing)"}, {"name": "Baking dish", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Fish is dry or rubbery", "likely_cause": "Overcooking", "prevention": "Check the fish at the 10-minute mark; thin fillets cook very quickly.", "fix": "Flake the fish into a bowl and toss with extra warm sesame oil or soy sauce to add moisture."}, {"symptom": "Fish lacks flavor", "likely_cause": "Under-seasoning or insufficient marinade coverage", "prevention": "Ensure the marinade coats all sides of the fish before baking.", "fix": "Drizzle with additional tamari or sprinkle with flakey sea salt before serving."}]', '["Pat the fish very dry with paper towels before marinating. Excess surface water dilutes the marinade and steams the fish instead of roasting it.", "For a crispier finish, you can switch the oven to ''Broil'' for the final 60 seconds, but watch closely to prevent burning the marinade sugars.", "The pickled ginger is not just a garnish; its acidity is essential to balance the richness of the sesame oil.", "If using rockfish or thinner fillets, reduce cooking time by 2-3 minutes."]', '"This preparation draws on the Japanese concept of ''Wafu'' (Japanese-style) cooking, where traditional ingredients like soy, ginger, and sesame are applied to Western-style preparations or simple proteins. The inclusion of ''gari'' (pickled ginger), typically reserved for sushi, acts as a palate cleanser to refresh the mouth between bites of the rich, oily fish."', 240.23);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('47be2dba-bd88-4315-b27c-1bf308391902', 'Umami Mushroom and Miso Sausage Rolls', 'Deeply savory vegetarian rolls featuring a texturally complex blend of shiitake, oyster, and cremini mushrooms. Enriched with fermented miso paste and sharp cheddar for a moist, meat-like interior that contrasts perfectly with shatteringly crisp, golden puff pastry.', 'appetizer', 'Modern British', 'Intermediate', '["finger foods", "vegetables", "freezer friendly", "make-ahead", "party", "picnic", "appetizer", "vegetarian", "christmas", "new year''s day"]', '[{"group_name": "Mushroom Filling", "items": [{"name": "cremini mushrooms", "quantity": 200, "unit": "g", "preparation": "cleaned and roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "fdd23eb2-a71c-46d1-932b-295adf7d5ae5", "nutrition_source": "Aggregated Public Data"}, {"name": "oyster mushrooms", "quantity": 150, "unit": "g", "preparation": "tough stems removed", "notes": null, "substitutions": [], "ingredient_id": "4fb0a923-94d7-4be9-9f04-c4fa16aa1b64", "nutrition_source": "USDA FoodData Central"}, {"name": "shiitake mushrooms", "quantity": 150, "unit": "g", "preparation": "stems removed", "notes": null, "substitutions": [], "ingredient_id": "127ce8a8-238d-40e6-a4b0-c58c42a7c745", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "brown onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme leaves", "quantity": 5, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "USDA FoodData Central"}, {"name": "white miso paste", "quantity": 30, "unit": "g", "preparation": null, "notes": "Shiro miso preferred for balance", "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "92441189-214a-4a8a-9cfc-dd578fe0d179", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Binding & Assembly", "items": [{"name": "panko breadcrumbs", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "6cc08e49-8e1b-4065-be23-f57782560a8b", "nutrition_source": "Aggregated Public Data"}, {"name": "sharp cheddar cheese", "quantity": 100, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "USDA FoodData Central"}, {"name": "large egg", "quantity": 1, "unit": null, "preparation": "beaten", "notes": "for binding filling", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "puff pastry sheets", "quantity": 2, "unit": null, "preparation": "thawed if frozen", "notes": "approx 500g total weight", "substitutions": [], "ingredient_id": "49bd8974-0750-40ca-80a7-7f195cdc662b", "nutrition_source": "USDA FoodData Central"}, {"name": "egg wash", "quantity": 1, "unit": null, "preparation": null, "notes": "1 egg beaten with 15ml milk", "substitutions": [], "ingredient_id": "36a7664a-f96c-44b9-9b6d-cdd5e9e54f55", "nutrition_source": "Aggregated Public Data"}, {"name": "sesame seeds", "quantity": 10, "unit": "g", "preparation": null, "notes": "white or black, for garnish", "substitutions": [], "ingredient_id": "0edc9256-6bac-4718-9f80-12351b1bc941", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the cremini, oyster, and shiitake mushrooms in a food processor. Pulse in short bursts until the mushrooms resemble ground meat or coarse gravel. Do not over-process into a paste.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Process mushrooms in two batches if your machine is small to ensure even size."]}, {"step_number": 2, "phase": "cook", "text": "Heat butter in a large skillet over medium-high heat. Add the diced onion and saut\u00e9 until softened and translucent, about 5 minutes.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the processed mushrooms and garlic to the pan. Cook, stirring frequently, until the mushrooms have released their liquid and the pan is nearly dry. This step is critical for texture.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Volume reduced by half, no pooling liquid", "tactile": "Mixture begins to brown and sizzle"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Stir in the miso paste, soy sauce, and fresh thyme. Cook for 1 more minute to activate the aromatics, then transfer the mixture to a large mixing bowl to cool slightly (about 10 minutes).", "structured": {"action": "MIX", "temperature": null, "duration": "PT11M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Once the mushroom mixture is warm (not hot), fold in the breadcrumbs, grated cheddar, and the beaten binding egg. Mix until a cohesive, moldable dough forms. If too wet, add 10g more breadcrumbs.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Preheat oven to 200\u00b0C/400\u00b0F. Lay out puff pastry sheets on a clean surface. Cut each square sheet in half to form two long rectangles.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Divide the filling into 4 equal parts. Shape each part into a long sausage log along the length of each pastry strip. Brush one long edge of the pastry with egg wash.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Roll the pastry over the filling, sealing it on the egg-washed edge. Place seam-side down. Cut each log into 6 smaller rolls. Score the tops diagonally with a sharp knife.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Place rolls on a parchment-lined baking sheet. Brush tops with egg wash and sprinkle with sesame seeds. Bake for 20-25 minutes until the pastry is puffed and deep golden brown.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT25M", "doneness_cues": {"visual": "Deep golden brown pastry", "tactile": "Pastry feels firm and crisp"}}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT35M", "total_time": "PT1H20M", "overnight_required": false, "yields": "24 mini rolls", "yield_count": 24, "serving_size_g": 45}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Vegans (contains egg and dairy)", "Gluten sensitivity"]}', '{"per_serving": {"calories": 168.55, "protein_g": 4.08, "carbohydrates_g": 12.67, "fat_g": 11.59, "saturated_fat_g": 3.37, "trans_fat_g": null, "monounsaturated_fat_g": 5.09, "polyunsaturated_fat_g": 1.27, "fiber_g": 1.1, "sugar_g": 1.07, "sodium_mg": 277.62, "cholesterol_mg": 25.94, "potassium_mg": 119.56, "calcium_mg": 51.5, "iron_mg": 1.2, "magnesium_mg": 16.31, "phosphorus_mg": 57.81, "zinc_mg": 0.45, "vitamin_a_mcg": 25.8, "vitamin_c_mg": 0.99, "vitamin_d_mcg": 0.19, "vitamin_e_mg": 0.21, "vitamin_k_mcg": 3.54, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": 0.06, "thiamin_mg": 0.11, "riboflavin_mg": 0.13, "niacin_mg": 1.5, "folate_mcg": 24.68, "water_g": 24.04, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container to prevent pastry from softening.", "duration": "P3D"}, "freezer": {"notes": "Freeze unbaked rolls on a tray, then bag. Bake from frozen adding 5-10 minutes to cook time.", "duration": "P3M"}, "reheating": "Reheat in a 180\u00b0C/350\u00b0F oven for 10 minutes to re-crisp pastry. Microwave not recommended.", "does_not_keep": false}', '[{"name": "Food processor", "required": true, "alternative": "Sharp knife and patience"}, {"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Pastry brush", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}]', '[{"symptom": "Soggy pastry bottom", "likely_cause": "Mushrooms were not cooked down enough, releasing water during baking", "prevention": "Ensure the mushroom pan is completely dry and sizzling before removing from heat", "fix": "Bake on a wire rack over a tray for the last 5 minutes to circulate air underneath"}, {"symptom": "Filling spilling out", "likely_cause": "Pastry was not sealed tightly or filled too loosely", "prevention": "Press the seam firmly and chill the rolls for 15 minutes before baking", "fix": "Push filling back in with a spoon immediately after baking while soft"}]', '["The secret to a ''meaty'' vegetarian roll is the differing textures of mushrooms. Using a mix of Shiitake (chewy), Oyster (fibrous), and Cremini (soft) creates a complex mouthfeel.", "Allow the filling to cool completely before rolling. Hot filling will melt the butter layers in the puff pastry before it hits the oven, resulting in a greasy, flat crust.", "Miso is the key salinity driver here. If you substitute the miso, you must increase the salt content, but you will lose the deep umami background note.", "For cleaner cuts when portioning the rolls, wipe your knife with a damp cloth between slices."]', '"Sausage rolls are a quintessential British and Australian party food, traditionally filled with pork meat. This modern adaptation utilizes the Japanese culinary concept of ''kokumi'' (mouthfulness) via the interaction of aged cheese and fermented miso to replicate the satisfaction of the original meat version."', 168.55);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('497ac4ec-8bd3-4c2c-90ce-22f873a10518', 'Everyday Whole Wheat Roti (Chapati)', 'Soft, tender, and nutty unleavened flatbreads that are a staple in Indian homes. These discs are cooked on a dry griddle until speckled, then briefly toasted over an open flame to puff up with steam, finished with a glaze of aromatic ghee.', 'bread', 'Indian', 'Intermediate', '["indian", "five ingredient", "flatbread", "ghee", "step by step", "whole wheat flour", "dinner", "side", "vegetarian"]', '[{"group_name": "Dough", "items": [{"name": "whole wheat flour (atta)", "quantity": 250, "unit": "g", "preparation": "finely ground", "notes": "Indian Atta flour is recommended for texture; western whole wheat is coarser", "substitutions": [], "ingredient_id": "af2661d8-b555-4fef-bdee-51a5190eda92", "nutrition_source": "USDA FoodData Central"}, {"name": "warm water", "quantity": 160, "unit": "ml", "preparation": null, "notes": "approximate; humidity affects absorption", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable oil", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "ghee", "quantity": 15, "unit": "g", "preparation": "melted", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "whole wheat flour", "quantity": 30, "unit": "g", "preparation": null, "notes": "for dusting", "substitutions": [], "ingredient_id": "af2661d8-b555-4fef-bdee-51a5190eda92", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a mixing bowl, combine the flour and salt. Gradually pour in warm water while mixing with your fingers until a rough, shaggy dough forms.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Add the vegetable oil and knead the dough firmly for 8-10 minutes. The dough should transform from sticky to soft, smooth, and pliable.", "structured": {"action": "KNEAD", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": null, "tactile": "Soft, smooth, springs back slightly when pressed"}}, "tips": ["If the dough sticks to your hands, add a sprinkle of flour. If it cracks, wet your hands with water."]}, {"step_number": 3, "phase": "prep", "text": "Cover the dough with a damp kitchen towel or plastic wrap and let it rest at room temperature. This relaxes the gluten.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Divide the rested dough into 8 equal portions. Roll each portion between your palms to form a smooth, crack-free ball, then flatten slightly into a disc.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Heat a tawa or cast iron skillet over medium-high heat. While it heats, dip a dough disc into dry flour and roll it out into a thin circle, about 15cm (6 inches) in diameter. Rotate frequently to ensure even thickness.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": {"visual": "Approx 1-2mm thickness", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Place the rolled dough onto the hot skillet. Cook for 30-40 seconds until small bubbles appear on the surface and the color changes slightly.", "structured": {"action": "TOAST", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT40S", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Flip the roti. Cook the second side for about 30 seconds until brown speckles appear.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Using tongs, lift the roti off the skillet and place it directly over the open gas flame. It should puff up into a balloon immediately. Flip quickly to spot the other side, then remove from heat. (If using electric stove, press gently with a folded cloth on the skillet to encourage puffing instead).", "structured": {"action": "GRILL", "temperature": null, "duration": "PT10S", "doneness_cues": {"visual": "Fully puffed and speckled brown", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Brush the hot roti immediately with melted ghee and place in an insulated container or wrap in a cloth to keep soft. Repeat with remaining dough.", "structured": {"action": "GLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT20M", "total_time": "PT50M", "overnight_required": false, "yields": "8 flatbreads", "yield_count": 8, "serving_size_g": 45}', '{"flags": ["Vegetarian", "Egg-Free", "Soy-Free", "Nut-Free", "Peanut-Free", "Sugar-Free"], "not_suitable_for": ["Vegans (contains ghee, unless swapped for oil)"]}', '{"per_serving": {"calories": 135.17, "protein_g": 3.38, "carbohydrates_g": 26.08, "fat_g": 2.83, "saturated_fat_g": 1.19, "trans_fat_g": null, "monounsaturated_fat_g": 0.54, "polyunsaturated_fat_g": 0.47, "fiber_g": 4.59, "sugar_g": 0.36, "sodium_mg": 98.76, "cholesterol_mg": 4.03, "potassium_mg": 138.47, "calcium_mg": 12.47, "iron_mg": 1.3, "magnesium_mg": 41.19, "phosphorus_mg": 113.5, "zinc_mg": 1.04, "vitamin_a_mcg": 12.83, "vitamin_c_mg": null, "vitamin_d_mcg": null, "vitamin_e_mg": 0.23, "vitamin_k_mcg": 0.8, "vitamin_b6_mg": 0.07, "vitamin_b12_mcg": null, "thiamin_mg": 0.11, "riboflavin_mg": 0.07, "niacin_mg": 1.87, "folate_mcg": 9.86, "water_g": 24.64, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container or zipper-lock bag. Reheat on a warm skillet.", "duration": "P2D"}, "freezer": {"notes": "Stack with parchment paper between layers.", "duration": "P1M"}, "reheating": "Reheat on a hot skillet for 30 seconds per side or wrap in damp paper towel and microwave for 10 seconds.", "does_not_keep": false}', '[{"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Rolling pin", "required": true, "alternative": "Clean glass bottle"}, {"name": "Tawa or Cast Iron Skillet", "required": true, "alternative": "Heavy-bottomed frying pan"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Clean kitchen towel", "required": true, "alternative": null}, {"name": "Insulated container", "required": false, "alternative": null}]', '[{"symptom": "Roti is hard or chewy like a cracker", "likely_cause": "Dough was too dry or cooked too long at low heat", "prevention": "Ensure dough is soft (high hydration) and cook on medium-high heat quickly", "fix": "Brush generously with water or ghee immediately and stack in a closed container to steam soften"}, {"symptom": "Roti does not puff", "likely_cause": "Uneven rolling or holes in the dough allow steam to escape", "prevention": "Roll with even pressure and avoid folding the dough while rolling", "fix": "Gently press the flat areas with a cloth while on the skillet to force steam into the unpuffed areas"}]', '["The hydration of ''Atta'' flour varies by brand. Add water slowly; the dough should be softer than pizza dough but not sticky.", "Resting the dough is non-negotiable. It relaxes the gluten, preventing the roti from shrinking back while rolling.", "If you do not have a gas flame, the ''pressing method'' on the skillet works well: after flipping to the second side, wait for bubbles, flip again, and press gently with a clean cloth."]', '"Roti (or Chapati) is the daily bread for millions in North India. Traditionally made fresh for every meal, it serves as the utensil for scooping up curries and dals. The art of making a perfectly round, puffed roti is often considered a rite of passage in Indian culinary education."', 135.17);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('49e3202d-98e7-40fd-8d6e-b4b94381f5da', 'Savory Turkey Patties with Tangy Dijon Pan Sauce', 'Succulent, herb-infused turkey burgers seared to golden perfection and bathed in a quick, zesty sauce made from pan drippings, shallots, and two types of mustard. A healthy, high-protein dinner ready in under 30 minutes.', 'dinner', 'American', 'Easy', '["burgers", "dijon mustard", "ground turkey", "shallot", "dinner", "main course", "low-fat", "high-protein", "quick meals"]', '[{"group_name": "Turkey Patties", "items": [{"name": "ground turkey", "quantity": 500, "unit": "g", "preparation": "chilled", "notes": "93% lean preferred for balance of moisture and fat", "substitutions": ["ground chicken", "lean ground pork"], "ingredient_id": "e249d5fe-71d4-4703-a054-7f5b828f930b", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx. 40g, divided use", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "panko breadcrumbs", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": ["gluten-free breadcrumbs", "almond flour"], "ingredient_id": "84fbc204-4457-40ed-83c1-3e5a7bcd8f23", "nutrition_source": "Aggregated Public Data"}, {"name": "dijon mustard", "quantity": 15, "unit": "g", "preparation": null, "notes": "approx. 1 tbsp", "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": "beaten", "notes": "large size, approx. 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "for searing", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Tangy Mustard Sauce", "items": [{"name": "chicken broth", "quantity": 120, "unit": "ml", "preparation": "low-sodium", "notes": null, "substitutions": [], "ingredient_id": "b7b1f4fd-8e57-472e-abae-d4f24d5b5c85", "nutrition_source": "Aggregated Public Data"}, {"name": "dijon mustard", "quantity": 30, "unit": "g", "preparation": null, "notes": "approx. 2 tbsp", "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "whole grain mustard", "quantity": 15, "unit": "g", "preparation": null, "notes": "approx. 1 tbsp", "substitutions": [], "ingredient_id": "ae60af51-f87a-4c0e-9f21-e14266340838", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Mince the shallot, keeping half (approx. 20g) separate for the sauce. Finely chop the parsley.", "structured": {"action": "MINCE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, combine the ground turkey, half of the minced shallot, panko breadcrumbs, egg, 15g (1 tbsp) Dijon mustard, chopped parsley, salt, and pepper. Gently mix with your hands just until combined\u2014do not overwork.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Overmixing ground meat leads to tough, rubbery burgers."]}, {"step_number": 3, "phase": "prep", "text": "Divide the mixture into 4 equal portions and shape them into patties approximately 2cm thick. Press a small indentation into the center of each patty to prevent bulging during cooking.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Heat the olive oil in a large skillet over medium-high heat. Once the oil shimmers, carefully add the patties.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Cook the patties for 4-5 minutes per side, or until a golden crust forms and the internal temperature reaches 74\u00b0C (165\u00b0F). Remove patties to a plate and cover loosely with foil to keep warm.", "structured": {"action": "SEAR", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": "PT10M", "doneness_cues": {"visual": "Golden brown crust", "tactile": "Firm to the touch"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Reduce heat to medium. Add the remaining minced shallot to the skillet (add a splash more oil if the pan is completely dry) and saut\u00e9 for 1 minute until softened and fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Pour in the chicken broth to deglaze the pan, scraping up any browned bits (fond) from the bottom with a spoon.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Whisk in the remaining 30g Dijon mustard and the whole grain mustard. Simmer for 2-3 minutes until the sauce reduces slightly and thickens. Stir in the optional lemon juice if using.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Spoon the hot mustard sauce generously over the rested turkey patties and serve immediately.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT0M", "total_time": "PT25M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 160}', '{"flags": ["Dairy-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 381.19, "protein_g": 28.57, "carbohydrates_g": 23.71, "fat_g": 19.15, "saturated_fat_g": 4.95, "trans_fat_g": 0.13, "monounsaturated_fat_g": 6.59, "polyunsaturated_fat_g": 3.43, "fiber_g": 1.25, "sugar_g": 16.72, "sodium_mg": 4673.09, "cholesterol_mg": 132.75, "potassium_mg": 400.13, "calcium_mg": 56.2, "iron_mg": 2.44, "magnesium_mg": 35.91, "phosphorus_mg": 289.75, "zinc_mg": 3.2, "vitamin_a_mcg": 55.78, "vitamin_c_mg": 4.77, "vitamin_d_mcg": 0.75, "vitamin_e_mg": 0.83, "vitamin_k_mcg": 43.84, "vitamin_b6_mg": 0.76, "vitamin_b12_mcg": 1.36, "thiamin_mg": 0.11, "riboflavin_mg": 0.27, "niacin_mg": 8.5, "folate_mcg": 22.38, "water_g": 114.53, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store patties and sauce in separate airtight containers if possible to maintain texture.", "duration": "P3D"}, "freezer": {"notes": "Freeze cooked patties without sauce. Thaw overnight before reheating.", "duration": "P2M"}, "reheating": "Gently reheat patties in a skillet over low heat with a splash of water or broth to prevent drying out.", "does_not_keep": false}', '[{"name": "Large skillet or frying pan", "required": true, "alternative": "Griddle"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Measuring spoons", "required": true, "alternative": null}, {"name": "Instant-read thermometer", "required": true, "alternative": "Knife tip test (less accurate)"}]', '[{"symptom": "Patties are dry and crumbly", "likely_cause": "Overcooking or using extremely lean turkey (99% fat-free) without added moisture", "prevention": "Use 93% lean turkey and use an instant-read thermometer to pull exactly at 74\u00b0C/165\u00b0F", "fix": "Slice the patties and toss them directly in the sauce to absorb moisture before serving"}, {"symptom": "Patties stick to the pan", "likely_cause": "Pan was not hot enough or oil was insufficient", "prevention": "Ensure oil is shimmering and pan is preheated before adding meat", "fix": "Do not force them; let them cook a minute longer until the crust releases naturally"}]', '["Using two types of mustard (Dijon and Whole Grain) provides a complex flavor profile: Dijon adds heat and creaminess, while grains add textural pop.", "If you want a creamier sauce without high fat, whisk in a tablespoon of plain Greek yogurt off the heat just before serving.", "The ''fond'' (browned bits stuck to the pan after searing) is flavor gold. Never wash the pan between the burgers and the sauce.", "Turkey is much leaner than beef and dries out faster. The indentation in the center helps it cook evenly without puffing up into a ball."]', '"While the hamburger is an American icon, the turkey burger emerged in the late 20th century as a health-conscious alternative. This preparation borrows technique from French bistro cooking, utilizing a classic ''pan sauce'' method where aromatics and liquids are reduced in the same vessel used to sear the protein."', 381.19);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('4aa8b546-f2aa-4b5c-9403-e6b10cf64948', 'Stout-Braised Beef Brisket with Cannellini Bean Mash', 'Succulent beef brisket braised for hours in a robust stout and herb gravy until fork-tender, paired with a velvety, garlic-infused white bean mash that offers a lighter, creamy alternative to potatoes.', 'dinner', 'British', 'Intermediate', '["beef", "brisket", "slow cooker", "stout", "cannellini beans", "mash", "comfort food", "winter"]', '[{"group_name": "Beef Brisket", "items": [{"name": "beef brisket", "quantity": 1500, "unit": "g", "preparation": "whole piece, trimmed of excess fat", "notes": "Flat cut preferred for uniform slicing", "substitutions": [], "ingredient_id": "e445dfeb-af0d-4690-8f92-be1168d84429", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 10, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 5, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 30, "unit": "ml", "preparation": "vegetable or grapeseed", "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Stout Gravy Base", "items": [{"name": "onion", "quantity": 2, "unit": null, "preparation": "roughly chopped", "notes": "approx. 300g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "carrot", "quantity": 2, "unit": null, "preparation": "cut into chunks", "notes": "approx. 200g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "celery stalk", "quantity": 2, "unit": null, "preparation": "chopped", "notes": "approx. 100g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 4, "unit": null, "preparation": "smashed", "notes": "approx. 20g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "tomato paste", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "d0a34229-249b-49e5-a653-227bd7afb7fc", "nutrition_source": "Aggregated Public Data"}, {"name": "stout beer", "quantity": 440, "unit": "ml", "preparation": null, "notes": "Guinness or similar dry stout", "substitutions": [], "ingredient_id": "b53cdbe9-79b7-43ff-b7f1-e7f4202b3292", "nutrition_source": "Aggregated Public Data"}, {"name": "beef stock", "quantity": 250, "unit": "ml", "preparation": "low sodium", "notes": null, "substitutions": [], "ingredient_id": "d5096f91-a6b8-408e-809e-de02179b315c", "nutrition_source": "Aggregated Public Data"}, {"name": "brown sugar", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 4, "unit": null, "preparation": "sprigs", "notes": "approx. 4g", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "bay leaf", "quantity": 2, "unit": null, "preparation": null, "notes": "dried", "substitutions": [], "ingredient_id": "eab2ef3a-7a0e-4188-b746-645b795ada1e", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 15, "unit": "g", "preparation": null, "notes": "mixed with 30ml water for thickening", "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Cannellini Mash", "items": [{"name": "cannellini beans", "quantity": 800, "unit": "g", "preparation": "canned, drained and rinsed", "notes": "2 standard 400g tins", "substitutions": [], "ingredient_id": "42a46c6e-f3fd-4f05-9192-3ffa111b561d", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx. 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh rosemary", "quantity": 1, "unit": null, "preparation": "sprig", "notes": "approx. 2g", "substitutions": [], "ingredient_id": "fa90a3a7-86cd-40de-8f8c-0464231925c2", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the brisket completely dry with paper towels and season generously on all sides with salt and black pepper.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat oil in a large frying pan over high heat. Sear the brisket until deeply browned on all sides, about 4-5 minutes per side. Transfer the meat to the slow cooker bowl.", "structured": {"action": "SEAR", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT10M", "doneness_cues": {"visual": "Deep dark brown crust", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In the same pan, reduce heat to medium and add onions, carrots, and celery. Saut\u00e9 for 5 minutes until softening. Add smashed garlic and tomato paste, cooking for another minute until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": "PT6M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Deglaze the pan with the stout, scraping up any browned bits (fond) from the bottom. Stir in the beef stock and brown sugar. Bring to a simmer.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour the vegetable and liquid mixture over the brisket in the slow cooker. Add thyme sprigs and bay leaves. Cover and cook on LOW for 8 hours (or HIGH for 4-5 hours) until the meat is fork-tender.", "structured": {"action": "BRAISE", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT8H", "doneness_cues": {"visual": null, "tactile": "Fork slides in with no resistance"}}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "About 20 minutes before serving, prepare the mash. Melt butter in a saucepan over medium heat. Add minced garlic and the rosemary sprig, cooking gently for 1-2 minutes without browning the garlic.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Add the drained cannellini beans and heavy cream to the saucepan. Simmer gently for 5 minutes to warm through and infuse flavors. Remove the rosemary sprig.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Puree the bean mixture using an immersion blender (or mash by hand) until smooth. Stir in lemon juice and season with salt and pepper to taste. Keep warm.", "structured": {"action": "PUREE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Smooth, creamy consistency similar to hummus", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove brisket from the slow cooker and rest on a cutting board for 10 minutes. Skim excess fat from the sauce. If a thicker gravy is desired, whisk in the cornstarch slurry and cook on high for 5-10 minutes until thickened. Slice meat against the grain.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT8H", "total_time": "PT8H45M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 350}', '{"flags": ["Nut-Free", "Peanut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": ["Celiacs (stout contains gluten)", "Lactose Intolerant (butter/cream)"]}', '{"per_serving": {"calories": 967.62, "protein_g": 60.17, "carbohydrates_g": 50.78, "fat_g": 55.22, "saturated_fat_g": 20.25, "trans_fat_g": 0.12, "monounsaturated_fat_g": 20.64, "polyunsaturated_fat_g": 1.8, "fiber_g": 14.72, "sugar_g": 14.99, "sodium_mg": 3787.98, "cholesterol_mg": 162.42, "potassium_mg": 2204.78, "calcium_mg": 143.75, "iron_mg": 9.61, "magnesium_mg": 63.75, "phosphorus_mg": 440.1, "zinc_mg": 11.13, "vitamin_a_mcg": 389.56, "vitamin_c_mg": 80.15, "vitamin_d_mcg": 0.16, "vitamin_e_mg": 0.56, "vitamin_k_mcg": 11.78, "vitamin_b6_mg": 0.92, "vitamin_b12_mcg": 4.48, "thiamin_mg": 0.17, "riboflavin_mg": 0.48, "niacin_mg": 9.67, "folate_mcg": 36.41, "water_g": 268.09, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store meat in the gravy to keep it moist.", "duration": "P3D"}, "freezer": {"notes": "Mash freezes okay but may separate; brisket freezes beautifully.", "duration": "P3M"}, "reheating": "Reheat brisket gently in sauce on stovetop. Reheat mash with a splash of water or milk to loosen.", "does_not_keep": false}', '[{"name": "Slow Cooker", "required": true, "alternative": "Heavy Dutch Oven (cook at 150\u00b0C/300\u00b0F for 4-5 hours)"}, {"name": "Large Frying Pan", "required": true, "alternative": null}, {"name": "Saucepan", "required": true, "alternative": null}, {"name": "Immersion Blender", "required": false, "alternative": "Potato masher or food processor"}]', '[{"symptom": "Brisket is tough or chewy", "likely_cause": "Undercooked; collagen hasn''t broken down yet", "prevention": "Ensure full cooking time; verify temperature is low and consistent", "fix": "Return to slow cooker and cook for another 60-90 minutes"}]', '["Searing the meat aggressively is crucial\u2014it builds the foundation of the sauce''s flavor through the Maillard reaction.", "If your stout is very bitter, balance it with a little extra brown sugar or a splash of balsamic vinegar at the end.", "Slice brisket against the grain (perpendicular to the muscle fibers) to ensure the bite is tender, not stringy.", "The acid (lemon juice) in the bean mash is essential to cut through the richness of the beef and gravy."]', '"Beef braised in stout is a classic comfort dish in the British Isles, particularly Ireland, where the deep roasted malt flavors of stouts like Guinness complement the savory richness of beef. Pairing it with a bean mash offers a modern, lighter, and more rustic twist on the traditional ''meat and potatoes'' formula."', 967.62);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('4d9b31d8-4d0d-4708-bdcd-6b88d540a4bc', 'Classic Gruyère and Chive Soufflé', 'A quintessential French masterpiece featuring a savory, velvety béchamel base enriched with nutty Gruyère and fresh chives. It rises dramatically in the oven to create a golden, airy crust with a creamy, cloud-like interior.', 'dinner', 'French', 'Intermediate', '["french", "chive", "egg", "gruy\u00e8re", "parmesan", "brunch", "dinner", "vegetarian", "classic", "savoury"]', '[{"group_name": "Mold Preparation", "items": [{"name": "unsalted butter", "quantity": 15, "unit": "g", "preparation": "softened", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "parmesan cheese", "quantity": 20, "unit": "g", "preparation": "finely grated", "notes": "for coating the dish", "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "B\u00e9chamel Base", "items": [{"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 45, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 250, "unit": "ml", "preparation": "cold or room temperature", "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "white pepper", "quantity": null, "unit": null, "preparation": null, "notes": "pinch to taste", "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "Aggregated Public Data"}, {"name": "nutmeg", "quantity": null, "unit": null, "preparation": null, "notes": "pinch of freshly grated", "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Enrichment & Lift", "items": [{"name": "egg yolks", "quantity": 4, "unit": null, "preparation": "room temperature", "notes": "approx 72g", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}, {"name": "gruy\u00e8re cheese", "quantity": 100, "unit": "g", "preparation": "shredded", "notes": null, "substitutions": [], "ingredient_id": "321085d2-bb82-45e1-8ae3-5a2ef5cea47f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh chives", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}, {"name": "egg whites", "quantity": 5, "unit": null, "preparation": "room temperature", "notes": "approx 150g", "substitutions": [], "ingredient_id": "17645f6b-c1ea-4e82-a4b4-5ae8cb6a5a53", "nutrition_source": "Aggregated Public Data"}, {"name": "cream of tartar", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "7514c048-9169-45bd-9758-b153c7d8a704", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place a baking sheet on the lower-middle rack and preheat the oven to 200\u00b0C (400\u00b0F). High heat is needed initially for the rise.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Generously grease the inside of the souffl\u00e9 dish with softened butter using upward strokes. Add the grated Parmesan and rotate the dish to coat the bottom and sides completely, shaking out excess. This gives the souffl\u00e9 something to grip as it climbs.", "structured": {"action": "COAT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Melt the 45g butter in a medium saucepan over medium heat. Whisk in the flour and cook for 2 minutes until bubbling but not browned (a blonde roux) to cook out the raw flour taste.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Pale and bubbling", "tactile": "Smooth paste"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Gradually whisk in the milk to avoid lumps. Bring to a simmer while whisking constantly. Cook for 2-3 minutes until the mixture thickens significantly into a smooth b\u00e9chamel. Remove from heat.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Thick glossy sauce", "tactile": "Coats back of spoon"}}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Whisk the salt, white pepper, nutmeg, and Dijon mustard into the hot b\u00e9chamel. Let it cool for 5 minutes, then whisk in the egg yolks one at a time until fully incorporated.", "structured": {"action": "TEMPER", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Stir in the shredded Gruy\u00e8re and chopped chives. The residual heat will melt the cheese.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "prep", "text": "In a clean, dry bowl, beat the egg whites (and cream of tartar if using) on medium-high speed until stiff, glossy peaks form. Do not overbeat until dry or clumpy.", "structured": {"action": "WHIP", "temperature": null, "duration": null, "doneness_cues": {"visual": "Stiff peaks that stand straight", "tactile": "Smooth and glossy"}}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Add one-third of the egg whites to the cheese base and whisk vigorously to lighten the batter. Then, gently fold in the remaining egg whites in two batches using a spatula, cutting through the center and sweeping up the sides, retaining as much air as possible.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "assemble", "text": "Pour the mixture into the prepared dish. Run your thumb around the inside rim of the dish to create a small groove (the ''top hat'' technique), which helps it rise evenly.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "cook", "text": "Place dish on the hot baking sheet in the oven. Immediately reduce temperature to 190\u00b0C (375\u00b0F). Bake for 20-25 minutes. Do NOT open the oven door during baking.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT25M", "doneness_cues": {"visual": "Puffed, golden brown top", "tactile": "Slight wobble in center"}}, "tips": []}, {"step_number": 11, "phase": "finish", "text": "Serve immediately. The souffl\u00e9 will begin to deflate within minutes of leaving the oven.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT25M", "total_time": "PT55M", "overnight_required": false, "yields": "1 large souffl\u00e9 (serves 4)", "yield_count": 4, "serving_size_g": 140}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Vegans"]}', '{"per_serving": {"calories": 390.18, "protein_g": 19.6, "carbohydrates_g": 13.25, "fat_g": 28.58, "saturated_fat_g": 15.97, "trans_fat_g": null, "monounsaturated_fat_g": 9.01, "polyunsaturated_fat_g": 1.84, "fiber_g": 0.47, "sugar_g": 3.69, "sodium_mg": 642.52, "cholesterol_mg": 263.8, "potassium_mg": 260.04, "calcium_mg": 417.72, "iron_mg": 0.88, "magnesium_mg": 26.66, "phosphorus_mg": 331.99, "zinc_mg": 1.89, "vitamin_a_mcg": 294.39, "vitamin_c_mg": 1.49, "vitamin_d_mcg": 1.96, "vitamin_e_mg": 0.95, "vitamin_k_mcg": 2.16, "vitamin_b6_mg": 0.12, "vitamin_b12_mcg": 1.16, "thiamin_mg": 0.1, "riboflavin_mg": 0.46, "niacin_mg": 0.28, "folate_mcg": 37.24, "water_g": 110.92, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"duration": null}, "freezer": {"duration": null}, "reheating": "Not recommended; souffl\u00e9s lose structure immediately after cooling.", "does_not_keep": true}', '[{"name": "Souffl\u00e9 dish (1.5L / 6-cup capacity)", "required": true, "alternative": "4-6 individual ramekins"}, {"name": "Medium saucepan", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Stand mixer or electric hand mixer", "required": true, "alternative": "Large balloon whisk and copper bowl"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Silicone spatula", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}]', '[{"symptom": "Souffl\u00e9 collapses immediately in the oven or doesn''t rise", "likely_cause": "Oven door was opened too early or egg whites were over-whipped/deflated during folding", "prevention": "Keep oven door closed until the full time has passed; fold whites gently until just combined", "fix": "Cannot be fixed"}, {"symptom": "Lopsided rise", "likely_cause": "Oven heat is uneven or the rim wasn''t cleaned", "prevention": "Use the ''top hat'' thumb trick on the rim before baking", "fix": "Still edible, just serve quickly"}]', '["The ''Top Hat'' Technique: Running your thumb around the inside rim of the dish removes batter from the very edge, allowing the souffl\u00e9 to push up straight rather than getting stuck on the lip.", "Egg Temperature: Separate eggs while cold, but let whites come to room temperature before whipping for maximum volume.", "Cheese Choice: Gruy\u00e8re is classic for its melting qualities and nutty flavor, but Comt\u00e9 or Emmental work equally well.", "Base Consistency: Ensure the b\u00e9chamel base is thick enough (like thick oatmeal) before adding yolks; if it''s too runny, the souffl\u00e9 will be wet.", "Timing: Guests wait for the souffl\u00e9; the souffl\u00e9 waits for no one. Time the baking so everyone is seated when it comes out."]', '"Originating in early 18th-century France, the souffl\u00e9 (meaning ''blown'' or ''puffed'') is a testament to the mastery of egg whites in French cuisine. While often feared by home cooks, it was historically a practical way to turn a small amount of savory leftovers into an elegant, voluminous main course."', 390.18);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('4dfb3e6d-18e5-489a-92c6-7bcca1355cbe', 'Tarragon Infused Lobster Bisque', 'A velvety, sophisticated soup that captures the essence of the ocean. Roasted lobster shells create a deep, amber stock thickened with rice for a gluten-free silkiness, while fresh tarragon and shallots add an aromatic anise sweetness that cuts through the rich cream.', 'soup', 'French', 'Advanced', '["new england", "project", "lobster", "shallot", "soup", "tarragon", "appetizer", "side dish", "winter", "french", "dinner party"]', '[{"group_name": "Lobster & Shell Stock", "items": [{"name": "whole live lobsters", "quantity": 2, "unit": null, "preparation": "approx 700g each", "notes": "total weight 1.4kg", "substitutions": [], "ingredient_id": "34f2d550-b220-4b17-9c47-fc3e5674cc19", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "carrot", "quantity": 100, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "celery", "quantity": 100, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "tomato paste", "quantity": 45, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "brandy or cognac", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "812e4827-eb36-4cb7-8c85-c59b54541641", "nutrition_source": "Aggregated Public Data"}, {"name": "dry white wine", "quantity": 120, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5e1efe68-ff2d-432c-9239-ff83f37c5e07", "nutrition_source": "Aggregated Public Data"}, {"name": "fish stock", "quantity": 1500, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["water", "vegetable stock"], "ingredient_id": "3912e04d-71a3-4a31-b033-cc5c5aa4452d", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh thyme", "quantity": 4, "unit": null, "preparation": null, "notes": "sprigs", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Bisque Base", "items": [{"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "shallots", "quantity": 60, "unit": "g", "preparation": "minced", "notes": null, "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": null, "notes": "cloves, smashed", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "white rice", "quantity": 50, "unit": "g", "preparation": null, "notes": "uncooked, for thickening", "substitutions": [], "ingredient_id": "d35782e6-8142-4414-b055-230d48cacc79", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh tarragon", "quantity": 15, "unit": "g", "preparation": "divided (stems vs leaves)", "notes": null, "substitutions": [], "ingredient_id": "d424d445-0a4e-45d1-9453-7523eb7b176b", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 180, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "cayenne pepper", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Bring a large pot of water to a boil. Plunge lobsters in head-first and boil for 5 minutes (par-cooked). Remove and immediately shock in an ice bath to stop cooking.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Once cool, separate the claws and tails. Remove the meat from the shells, cover, and refrigerate the meat. Crush the empty shells and bodies into smaller pieces using a mallet or rolling pin. Save any tomalley (green liver) if desired for extra richness.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": {"visual": "Shells broken into 2-inch pieces", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat olive oil in the Dutch oven over high heat. Add the crushed shells. Saut\u00e9 vigorously until they turn bright red and smell toasted.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT8M", "doneness_cues": {"visual": "Shells are bright red", "tactile": "Aromatic toasty smell"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Lower heat to medium. Add carrots, celery, and thyme. Cook for 5 minutes until softened. Stir in tomato paste and cook for 2 minutes to darken its color (pinc\u00e9).", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT7M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Deglaze with brandy, scraping the bottom of the pot. (Safety: Remove from heat if using gas flame to avoid flare-ups). Add white wine and reduce liquid by half. Pour in fish stock (or water) to cover shells. Simmer gently for 45 minutes.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT45M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Strain the stock through a colander into a bowl, pressing hard on the shells to extract all flavor. Discard the shells. Wipe out the pot.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "In the clean pot, melt butter over medium heat. Saut\u00e9 shallots, garlic, and tarragon stems (reserve leaves) until translucent. Add the uncooked rice and stir for 1 minute.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Pour the strained lobster stock back into the pot with the rice. Simmer until the rice is completely overcooked and mushy, about 20-25 minutes.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT25M", "doneness_cues": {"visual": null, "tactile": "Rice grains are falling apart"}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove tarragon stems. Working in batches, transfer soup to a high-speed blender (fill only halfway and vent lid carefully). Blend until perfectly smooth. Strain through a fine-mesh sieve for a velvet texture.", "structured": {"action": "BLEND", "temperature": null, "duration": null, "doneness_cues": {"visual": "Homogenous orange liquid", "tactile": null}}, "tips": ["Cover the blender lid with a kitchen towel to prevent steam burns."]}, {"step_number": 10, "phase": "finish", "text": "Return soup to low heat. Whisk in heavy cream and cayenne. Chop reserved lobster meat into bite-sized chunks and add to the soup just to warm through (2 minutes). Finish with lemon juice and minced fresh tarragon leaves.", "structured": {"action": "SIMMER", "temperature": {"celsius": 75, "fahrenheit": 167}, "duration": "PT2M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT1H", "passive_time": "PT1H", "total_time": "PT2H", "overnight_required": false, "yields": "4 bowls", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Pescatarian", "Gluten-Free", "Egg-Free", "Soy-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": ["Shellfish allergy", "Dairy allergy"]}', '{"per_serving": {"calories": 814.26, "protein_g": 75.65, "carbohydrates_g": 21.3, "fat_g": 41.5, "saturated_fat_g": 19.14, "trans_fat_g": 0.59, "monounsaturated_fat_g": 13.02, "polyunsaturated_fat_g": 2.99, "fiber_g": 2.39, "sugar_g": 4.99, "sodium_mg": 2123.18, "cholesterol_mg": 519.54, "potassium_mg": 2037.49, "calcium_mg": 408.15, "iron_mg": 3.05, "magnesium_mg": 170.33, "phosphorus_mg": 643.23, "zinc_mg": 12.88, "vitamin_a_mcg": 496.3, "vitamin_c_mg": 11.32, "vitamin_d_mcg": 0.72, "vitamin_e_mg": 5.12, "vitamin_k_mcg": 17.72, "vitamin_b6_mg": 0.53, "vitamin_b12_mcg": 4.47, "thiamin_mg": 0.13, "riboflavin_mg": 0.18, "niacin_mg": 6.22, "folate_mcg": 58.61, "water_g": 375.27, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store lobster meat separately from soup to prevent it from becoming rubbery.", "duration": "P2D"}, "freezer": {"notes": "Texture may separate slightly upon thawing; blend gently while reheating.", "duration": "P1M"}, "reheating": "Reheat soup base gently on stove; add meat only at the very end to warm through.", "does_not_keep": false}', '[{"name": "Large Dutch oven or stockpot", "required": true, "alternative": null}, {"name": "High-speed blender", "required": true, "alternative": "Immersion blender"}, {"name": "Fine mesh sieve or chinoise", "required": true, "alternative": null}, {"name": "Rolling pin or mallet", "required": true, "alternative": "Heavy pan"}, {"name": "Kitchen shears", "required": true, "alternative": null}]', '[{"symptom": "Soup has a gritty texture", "likely_cause": "Shell fragments remained or rice wasn''t blended fully", "prevention": "Strain through a very fine mesh sieve (chinoise) after blending", "fix": "Pass through a fine sieve or cheesecloth again"}, {"symptom": "Lobster meat is rubbery", "likely_cause": "Overcooked during par-boil or reheating", "prevention": "Only par-boil initially; warm gently at the very end", "fix": "Chop meat finer to disguise texture"}]', '["Using rice to thicken (a technique called ''bisque li\u00e9'') is traditional and keeps the soup gluten-free while providing a lighter, silkier texture than flour roux.", "Don''t skip the resting time after roasting the shells; pressing on the solids during straining extracts the ''olies'' (flavorful oils) that carry the lobster essence.", "If you cannot find live lobster, use high-quality frozen tails. Roast the shells from the tails just as described to build the base flavor.", "Tarragon has a strong profile; add the finishing leaves gradually to ensure it doesn''t overpower the delicate lobster sweetness."]', '"While ''Bisque'' is a French creation originally thickened with crustacean shells ground into a paste, this version adapts the technique for the modern kitchen using rice. The inclusion of tarragon and shallots bridges the gap between classic French technique and the herbal freshness often found in New England coastal cuisine."', 814.26);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('4e2beed7-eb45-4756-93c0-49c10016f984', 'Creamy Paprika Veal with Capers & Rosemary', 'Tender veal scallops quickly seared and finished in a velvety, tangy paprika and yogurt sauce. The brightness of capers and piney aroma of rosemary cut through the richness, creating a sophisticated yet effortless dinner.', 'dinner', 'European', 'Easy', '["veal", "quick", "dinner", "nut-free", "gluten-free", "high-protein"]', '[{"group_name": "Veal & Aromatics", "items": [{"name": "veal scallops", "quantity": 600, "unit": "g", "preparation": "thinly pounded", "notes": "approx 5mm thick", "substitutions": ["turkey breast slices", "chicken breast cutlets"], "ingredient_id": "ef7319e9-935b-47d4-95b3-d711e7489fd8", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "thinly sliced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh rosemary", "quantity": 2, "unit": null, "preparation": "leaves chopped", "notes": "sprigs", "substitutions": [], "ingredient_id": "fa90a3a7-86cd-40de-8f8c-0464231925c2", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika", "quantity": 8, "unit": "g", "preparation": null, "notes": "approx 2 tsp", "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, start with 3g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Sauce", "items": [{"name": "plain yogurt", "quantity": 150, "unit": "g", "preparation": "room temperature", "notes": "full fat Greek style preferred", "substitutions": [], "ingredient_id": "ba236210-8230-458e-a809-4c025a1bf020", "nutrition_source": "USDA FoodData Central"}, {"name": "capers", "quantity": 30, "unit": "g", "preparation": "drained", "notes": null, "substitutions": [], "ingredient_id": "e7301d2c-b906-4ef8-917e-787be0b25880", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable stock", "quantity": 60, "unit": "ml", "preparation": null, "notes": "or water", "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the veal scallops dry with paper towels and season both sides generously with salt and black pepper.", "structured": {"action": "SEASON", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat olive oil in a large skillet over medium-high heat. Once shimmering, add the veal (in batches if necessary to avoid overcrowding) and sear for 1-2 minutes per side until golden brown. Remove veal and set aside on a plate.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT4M", "doneness_cues": {"visual": "Golden brown crust", "tactile": null}}, "tips": ["Do not overcrowd the pan or the meat will steam instead of sear."]}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to medium. Add sliced onions to the same pan and saut\u00e9 for 5 minutes until softened and translucent.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT5M", "doneness_cues": {"visual": "Translucent and soft", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Stir in the chopped rosemary and smoked paprika. Cook for 30 seconds until fragrant, being careful not to burn the paprika.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT30S", "doneness_cues": {"visual": "Fragrant aroma", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Deglaze the pan with vegetable stock, scraping up any browned bits from the bottom. Let it simmer for 1 minute to reduce slightly.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Reduce heat to low. Stir in the capers and plain yogurt. Mix well to create a creamy sauce. Do not let the sauce boil.", "structured": {"action": "MIX", "temperature": {"celsius": 80, "fahrenheit": 176}, "duration": null, "doneness_cues": null}, "tips": ["If the heat is too high, the yogurt will curdle."]}, {"step_number": 7, "phase": "finish", "text": "Return the veal and any resting juices to the pan. Turn the meat to coat in the sauce and warm through for 1 minute. Serve immediately.", "structured": {"action": "WARM", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT0M", "total_time": "PT25M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 225}', '{"flags": ["Nut-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 380.51, "protein_g": 32.45, "carbohydrates_g": 7.45, "fat_g": 24.33, "saturated_fat_g": 7.36, "trans_fat_g": 0.62, "monounsaturated_fat_g": 13.09, "polyunsaturated_fat_g": 1.62, "fiber_g": 1.82, "sugar_g": 3.74, "sodium_mg": 706.66, "cholesterol_mg": 93.38, "potassium_mg": 539.43, "calcium_mg": 88.66, "iron_mg": 2.08, "magnesium_mg": 80.6, "phosphorus_mg": 388.47, "zinc_mg": 3.43, "vitamin_a_mcg": 65.72, "vitamin_c_mg": 3.67, "vitamin_d_mcg": 2.59, "vitamin_e_mg": 2.21, "vitamin_k_mcg": 10.55, "vitamin_b6_mg": 1.01, "vitamin_b12_mcg": 3.83, "thiamin_mg": 0.16, "riboflavin_mg": 0.52, "niacin_mg": 10.27, "folate_mcg": 18.36, "water_g": 177.87, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Sauce may separate upon reheating; heat gently.", "duration": "P2D"}, "freezer": {"notes": "Dairy-based sauces do not freeze well.", "duration": null}, "reheating": "Reheat gently on the stove over low heat; do not boil.", "does_not_keep": false}', '[{"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Sauce looks grainy or separated", "likely_cause": "The yogurt curdled because the heat was too high or the yogurt was cold", "prevention": "Use room temperature full-fat yogurt and keep heat very low after adding it", "fix": "Remove from heat and whisk in a teaspoon of warm water vigorously; texture may remain slightly grainy but taste will be fine"}]', '["Veal dries out quickly; ensure the initial sear is fast and high-heat.", "For a thicker sauce, you can dust the veal in flour before searing, which will help thicken the yogurt mixture later.", "Smoked paprika adds a ''meatier'' flavor profile than sweet paprika, pairing excellently with the tangy capers.", "If you strictly avoid veal, turkey cutlets are a perfect 1:1 substitution for this recipe."]', '"This dish draws inspiration from Central European ''Paprikash'' styles and Mediterranean piccata traditions. The use of yogurt instead of heavy cream lightens the dish while maintaining a luxurious mouthfeel, a technique common in modern European bistro cooking."', 380.51);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('4e3e9f0f-6de4-457e-8ee2-976f22c17387', 'Oven-Baked Zucchini and Feta Fritters', 'Crisp on the outside and tender on the inside, these Mediterranean-inspired fritters avoid the heavy oil of frying while delivering robust flavor through fresh herbs and salty feta. A versatile base that works as a light lunch, side dish, or appetizer.', 'appetizer', 'Mediterranean', 'Intermediate', '["fritters", "courgette", "baked", "vegetarian", "mediterranean", "healthy"]', '[{"group_name": "Vegetable Base", "items": [{"name": "zucchini", "quantity": 500, "unit": "g", "preparation": "grated", "notes": "approx. 2 medium zucchini", "substitutions": [], "ingredient_id": "d0aa0d47-cefe-4ece-a337-e656f79b74e9", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "for drawing out moisture", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "green onions", "quantity": 3, "unit": null, "preparation": "finely chopped", "notes": "about 45g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "about 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Binder & Flavor", "items": [{"name": "large eggs", "quantity": 2, "unit": null, "preparation": "lightly beaten", "notes": "approx. 100g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "feta cheese", "quantity": 100, "unit": "g", "preparation": "crumbled", "notes": null, "substitutions": [], "ingredient_id": "a9a8605c-3bf2-4ca3-8c58-80e87aff7cd8", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh dill", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "4be2b047-475d-4c84-82d5-4883298c6121", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": null, "notes": "zest of 1 lemon", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "Aggregated Public Data"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Dry Ingredients", "items": [{"name": "all-purpose flour", "quantity": 70, "unit": "g", "preparation": null, "notes": "can substitute chickpea flour for gluten-free", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 4, "unit": "g", "preparation": null, "notes": "approx. 1 tsp", "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Cooking", "items": [{"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "for brushing", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the grated zucchini in a colander set over a bowl or sink. Toss with the salt and let sit for 10-15 minutes to draw out excess moisture.", "structured": {"action": "DRAIN", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Preheat the oven to 200\u00b0C/400\u00b0F. Line a baking sheet with parchment paper and lightly brush it with a portion of the olive oil.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Transfer the salted zucchini to a clean kitchen towel. Twist and squeeze firmly to extract as much liquid as possible. The zucchini should feel dry and compact.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Zucchini pulp feels very dry and clumps together"}}, "tips": ["Do not skip this step. Wet zucchini will result in mushy fritters that fall apart."]}, {"step_number": 4, "phase": "assemble", "text": "In a large mixing bowl, combine the squeezed zucchini, green onions, garlic, crumbled feta, dill, parsley, lemon zest, beaten eggs, and black pepper. Mix well to combine.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Sprinkle the flour and baking powder over the zucchini mixture. Fold until just combined and no dry pockets of flour remain.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Scoop roughly 60ml (1/4 cup) portions of the mixture onto the prepared baking sheet. Flatten slightly with the back of a spoon to create patties about 1.5cm thick.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Brush the tops of the fritters generously with the remaining olive oil. Bake for 12-15 minutes until the bottoms are golden brown.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT12M", "doneness_cues": {"visual": "Bottoms are golden brown", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Flip the fritters carefully. Bake for another 10-12 minutes until deeply golden on both sides and firm to the touch.", "structured": {"action": "BAKE", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Deep golden brown on both sides", "tactile": "Firm to the touch"}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove from the oven and let rest on the tray for 5 minutes to firm up before serving.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT15M", "total_time": "PT40M", "overnight_required": false, "yields": "12 fritters", "yield_count": 12, "serving_size_g": 110}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 87.79, "protein_g": 3.5, "carbohydrates_g": 7.13, "fat_g": 5.26, "saturated_fat_g": 1.73, "trans_fat_g": null, "monounsaturated_fat_g": 2.53, "polyunsaturated_fat_g": 0.5, "fiber_g": 0.76, "sugar_g": 1.07, "sodium_mg": 309.85, "cholesterol_mg": 38.42, "potassium_mg": 48.58, "calcium_mg": 72.96, "iron_mg": 0.51, "magnesium_mg": 5.96, "phosphorus_mg": 61.81, "zinc_mg": 0.43, "vitamin_a_mcg": 33.87, "vitamin_c_mg": 3.47, "vitamin_d_mcg": 0.2, "vitamin_e_mg": 0.48, "vitamin_k_mcg": 22.36, "vitamin_b6_mg": 0.07, "vitamin_b12_mcg": 0.22, "thiamin_mg": 0.03, "riboflavin_mg": 0.12, "niacin_mg": 0.21, "folate_mcg": 12.68, "water_g": 18, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container with paper towels between layers to absorb moisture.", "duration": "P4D"}, "freezer": {"notes": "Freeze on a baking sheet first, then transfer to a bag.", "duration": "P3M"}, "reheating": "Reheat in a 180\u00b0C/350\u00b0F oven or air fryer for 5-8 minutes until crisp. Microwave is not recommended as they will become soggy.", "does_not_keep": false}', '[{"name": "Box grater", "required": true, "alternative": null}, {"name": "Clean kitchen towel or nut milk bag", "required": true, "alternative": "Cheesecloth"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}]', '[{"symptom": "Fritters are soggy or mushy inside", "likely_cause": "Insufficient moisture was removed from the zucchini", "prevention": "Squeeze the zucchini until your hands actually hurt; the volume should reduce by nearly half.", "fix": "Bake for an additional 5-10 minutes on a wire rack set over the baking sheet to circulate air."}]', '["Squeezing the zucchini is the single most important step. If you measure the liquid extracted, it should be close to 150ml-200ml for this amount of zucchini.", "For a gluten-free version, chickpea flour (gram flour) is an excellent binder that adds a nutty flavor and extra protein.", "Serve these with a cool tzatziki or a simple lemon-garlic yogurt dip to contrast the hot, savory fritter.", "If the mixture feels too wet to hold its shape before baking, add another tablespoon of flour. If too dry, add a splash of milk."]', '"Vegetable fritters, known as ''kolokithokeftedes'' in Greece or ''m\u00fccver'' in Turkey, are a staple of Mediterranean cuisine designed to utilize the abundant summer squash harvest. While traditionally fried in olive oil, baking offers a lighter preparation that highlights the fresh herbs and salty cheese common to the region."', 87.79);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('4ec1271e-8df7-476e-bac9-6c3beaf61a3b', 'Braised Veal Shoulder with Cardamom Spinach Velvet', 'A luxurious roast-style braise where the veal shoulder transforms into meltingly tender meat with a rich, gelatinous glaze. It pairs with a striking emerald-green spinach puree, where the floral, citrusy warmth of green cardamom cuts through the richness of the meat.', 'main course', 'French', 'Advanced', '["roasts", "cardamom", "spinach", "veal", "dinner", "main course", "winter", "french", "elegant"]', '[{"group_name": "Veal Roast", "items": [{"name": "boneless veal shoulder", "quantity": 1000, "unit": "g", "preparation": "rolled and tied", "notes": "Ask butcher to roll for roasting", "substitutions": [], "ingredient_id": "154b7714-319a-47a1-802a-416797db0752", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 8, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "grapeseed oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Braising Aromatics", "items": [{"name": "onion", "quantity": 1, "unit": null, "preparation": "roughly chopped", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "carrot", "quantity": 1, "unit": null, "preparation": "roughly chopped", "notes": "approx 100g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "celery stalk", "quantity": 1, "unit": null, "preparation": "roughly chopped", "notes": "approx 50g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "smashed", "notes": "approx 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 200, "unit": "ml", "preparation": null, "notes": "Sauvignon Blanc or Pinot Grigio", "substitutions": [], "ingredient_id": "0c041362-befe-4c15-88d2-ba97c8f46428", "nutrition_source": "USDA FoodData Central"}, {"name": "veal stock", "quantity": 500, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["chicken stock"], "ingredient_id": "75bb51d6-9275-4c11-9fff-65bd7ed4b5b2", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 4, "unit": null, "preparation": "sprigs", "notes": "approx 2g", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "bay leaf", "quantity": 1, "unit": null, "preparation": null, "notes": "dried", "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Cardamom Spinach Puree", "items": [{"name": "heavy cream", "quantity": 150, "unit": "ml", "preparation": null, "notes": "35% fat or higher", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "green cardamom pods", "quantity": 8, "unit": null, "preparation": "crushed", "notes": "approx 2g", "substitutions": [], "ingredient_id": "c56f6cd8-882c-487c-956f-3a91ee1fec07", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh spinach", "quantity": 600, "unit": "g", "preparation": "washed and stemmed", "notes": null, "substitutions": [], "ingredient_id": "4734440a-226d-4d26-a110-3ed5c3bde93f", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 40, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, start with 2g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the veal shoulder dry with paper towels and season generously on all sides with salt and cracked black pepper. Preheat the oven to 150\u00b0C (300\u00b0F).", "structured": {"action": "SEASON", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a small saucepan over low heat, combine heavy cream and crushed cardamom pods. Bring to a bare simmer, then remove from heat and let infuse for at least 20 minutes.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat grapeseed oil in the Dutch oven over medium-high heat. Sear the veal shoulder on all sides until deeply golden brown, about 3-4 minutes per side.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": "Deep golden brown crust", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Remove meat and set aside. Reduce heat to medium, add the 30g butter, onion, carrot, celery, and smashed garlic. Saut\u00e9 until softened and lightly browned.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Deglaze the pan with white wine, scraping up the fond (browned bits) from the bottom. Reduce the wine by half.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Return the veal to the pot. Add stock, thyme, and bay leaf. The liquid should come about halfway up the meat. Bring to a simmer, cover tightly, and transfer to the oven for 2.5 to 3 hours, or until the meat is fork-tender.", "structured": {"action": "BRAISE", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": "PT3H", "doneness_cues": {"visual": null, "tactile": "Fork slides in with no resistance"}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "While the meat rests, bring a large pot of salted water to a rolling boil. Prepare an ice water bath. Blanch the spinach for 30 seconds only, then immediately transfer to the ice bath to shock it.", "structured": {"action": "BLANCH", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT30S", "doneness_cues": null}, "tips": ["Shocking locks in the chlorophyll for a bright green color."]}, {"step_number": 8, "phase": "finish", "text": "Squeeze as much water as possible out of the spinach using a clean kitchen towel. Strain the infused cream to remove cardamom pods.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Place spinach and infused cream into a high-speed blender. Blend until perfectly smooth. Add the cold cubed butter (40g) while blending to emulsify. Season with salt.", "structured": {"action": "BLEND", "temperature": null, "duration": null, "doneness_cues": {"visual": "Glossy, vibrant green puree", "tactile": null}}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Remove veal from pot and rest loosely covered. Strain the braising liquid into a saucepan and reduce over high heat until it coats the back of a spoon (napp\u00e9 consistency).", "structured": {"action": "REDUCE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Glaze consistency", "tactile": null}}, "tips": []}, {"step_number": 11, "phase": "assemble", "text": "Slice the veal into thick rounds. Plate atop a swoosh of cardamom spinach puree and spoon the reduced braising glaze over the meat.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT3H", "total_time": "PT3H45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Gluten-Free", "Keto", "Low-Carb", "Nut-Free", "Peanut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 987.95, "protein_g": 98.61, "carbohydrates_g": 20.36, "fat_g": 52.86, "saturated_fat_g": 23.49, "trans_fat_g": 0.47, "monounsaturated_fat_g": 13.36, "polyunsaturated_fat_g": 3.01, "fiber_g": 5.26, "sugar_g": 4.71, "sodium_mg": 1450.05, "cholesterol_mg": 443.75, "potassium_mg": 2291.01, "calcium_mg": 307.63, "iron_mg": 8.54, "magnesium_mg": 232.08, "phosphorus_mg": 962.77, "zinc_mg": 14.6, "vitamin_a_mcg": 1190.54, "vitamin_c_mg": 48.91, "vitamin_d_mcg": 0.6, "vitamin_e_mg": 5.21, "vitamin_k_mcg": 743.66, "vitamin_b6_mg": 1.95, "vitamin_b12_mcg": 5.29, "thiamin_mg": 0.44, "riboflavin_mg": 1.53, "niacin_mg": 33.76, "folate_mcg": 368.55, "water_g": 533.63, "alcohol_g": 4.45, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store meat in its braising liquid to prevent drying out. Spinach puree loses vibrant color after 24 hours.", "duration": "P3D"}, "freezer": {"notes": "Meat freezes well in sauce; spinach puree texture may degrade upon thawing.", "duration": "P2M"}, "reheating": "Reheat meat gently in sauce on stove. Reheat spinach in a double boiler to prevent scorching.", "does_not_keep": false}', '[{"name": "Dutch oven or heavy-bottomed braiser with lid", "required": true, "alternative": null}, {"name": "High-speed blender", "required": true, "alternative": null}, {"name": "Fine-mesh sieve", "required": true, "alternative": "Regular strainer"}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Large pot", "required": true, "alternative": "For blanching spinach"}, {"name": "Ice bath bowl", "required": true, "alternative": null}, {"name": "Kitchen twine", "required": true, "alternative": null}]', '[{"symptom": "Spinach puree is brown/olive instead of bright green", "likely_cause": "Overcooked during blanching or acid exposure (lemon/vinegar) in puree", "prevention": "Blanch quickly (30s) and shock in ice immediately; do not add acid to the green puree", "fix": "Cannot be fixed color-wise; serve as is, the flavor remains"}, {"symptom": "Veal is tough after 3 hours", "likely_cause": "The cut contains dense connective tissue that hasn''t fully gelatinized", "prevention": "Ensure oven temp is consistent; ensure lid is tight", "fix": "Return to oven for another 30-45 minutes; add a splash more liquid if needed"}]', '["Squeezing the spinach dry is crucial. If the spinach is too wet, the puree will be watery and separate on the plate.", "For the ultimate smooth texture, pass the finished spinach puree through a fine-mesh sieve (tamis) using a ladle.", "Resting the meat for at least 20 minutes before slicing allows the juices to redistribute, preventing them from leaking out onto the plate.", "The cardamom should be a subtle background note, not a dominant spice. Taste the infused cream before adding it to the spinach."]', '"This dish applies classic French braising techniques to veal, a protein prized in European gastronomy for its delicate flavor. The addition of cardamom introduces a subtle Scandinavian or Middle Eastern aromatic profile, modernizing the traditional roast dinner."', 987.95);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('5038f33a-d90f-405a-a6b9-9949e861d514', 'Warm Spanish Chickpea Salad', 'A vibrant, aromatic salad bridging the gap between a light side and a hearty main. Tender chickpeas are warmed in a smoky paprika and cumin-infused oil, then tossed with crisp red onions, juicy tomatoes, and bright sherry vinegar. Ideally served warm or at room temperature.', 'salad', 'Spanish', 'Easy', '["spanish", "one pot", "chickpea", "great leftovers", "dinner", "side dish", "gluten-free", "low-fat", "vegan", "quick"]', '[{"group_name": "Aromatics & Base", "items": [{"name": "extra virgin olive oil", "quantity": 15, "unit": "ml", "preparation": "liquid", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "red onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "1c270c6e-0acc-4c5c-9935-7eff3240fc4a", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "cooked chickpeas", "quantity": 800, "unit": "g", "preparation": "rinsed and drained", "notes": "2 standard 400g cans", "substitutions": [], "ingredient_id": "9e76f37b-da5c-4dc8-8e18-6b9b92ef6094", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Spices", "items": [{"name": "smoked paprika", "quantity": 5, "unit": "g", "preparation": null, "notes": "piment\u00f3n de la vera", "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 4, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Fresh Finish", "items": [{"name": "cherry tomatoes", "quantity": 250, "unit": "g", "preparation": "halved", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "sherry vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": "or red wine vinegar", "substitutions": ["red wine vinegar", "lemon juice"], "ingredient_id": "dcfa7371-7051-4604-a76e-4a46ae1f9e7b", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Rinse and drain the chickpeas thoroughly. Chop the red onion, mince the garlic, halve the cherry tomatoes, and chop the parsley.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat the olive oil in a large skillet over medium heat (approx. 175\u00b0C/350\u00b0F). Add the diced red onion and a pinch of salt. Saut\u00e9 for 5-7 minutes until the onion is soft and translucent but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT7M", "doneness_cues": {"visual": "Onions are translucent", "tactile": "Soft texture"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the minced garlic, smoked paprika, and cumin to the skillet. Stir constantly for 30-60 seconds until the spices are fragrant, being careful not to burn the garlic.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Spices darken slightly", "tactile": "Aromatic release"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the chickpeas to the skillet. Stir well to coat them in the spiced oil mixture. Cook for 3-4 minutes, stirring occasionally, until the chickpeas are warmed through.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Chickpeas are glossy and coated", "tactile": "Hot to the touch"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove the skillet from the heat. Immediately stir in the sherry vinegar, scraping up any fond (browned bits) from the bottom of the pan. Gently fold in the cherry tomatoes and half of the parsley.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Taste and adjust seasoning with additional salt or vinegar if needed. Transfer to a serving dish and garnish with the remaining parsley. Serve warm or at room temperature.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 280}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Low-Fat"], "not_suitable_for": []}', '{"per_serving": {"calories": 402.85, "protein_g": 19.32, "carbohydrates_g": 64.21, "fat_g": 9.48, "saturated_fat_g": 1.13, "trans_fat_g": null, "monounsaturated_fat_g": 4.04, "polyunsaturated_fat_g": 2.85, "fiber_g": 17.73, "sugar_g": 13.84, "sodium_mg": 411.58, "cholesterol_mg": null, "potassium_mg": 879.55, "calcium_mg": 138.65, "iron_mg": 7.61, "magnesium_mg": 110.91, "phosphorus_mg": 365.83, "zinc_mg": 3.34, "vitamin_a_mcg": 49.09, "vitamin_c_mg": 18.69, "vitamin_d_mcg": null, "vitamin_e_mg": 1.66, "vitamin_k_mcg": 73.26, "vitamin_b6_mg": 0.35, "vitamin_b12_mcg": null, "thiamin_mg": 0.26, "riboflavin_mg": 0.14, "niacin_mg": 1.3, "folate_mcg": 350.52, "water_g": 159.06, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors improve after resting. Eat cold or gently reheat.", "duration": "P4D"}, "freezer": {"notes": "Fresh tomatoes do not freeze well.", "duration": null}, "reheating": "Microwave gently or let come to room temperature.", "does_not_keep": false}', '[{"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": "Wok or large saucepan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Salad tastes bland", "likely_cause": "Under-seasoning or canned chickpeas retaining metallic taste", "prevention": "Taste the chickpeas after rinsing; ensure salt is added during the onion saut\u00e9 step.", "fix": "Add more salt and a squeeze of fresh lemon juice or splash of vinegar to brighten the flavors."}, {"symptom": "Garlic tastes bitter", "likely_cause": "Garlic was burned during the spice blooming step", "prevention": "Do not let garlic cook for more than 1 minute before adding chickpeas.", "fix": "Difficult to fix completely; adding a pinch of sugar or more tomato acidity can mask slight bitterness."}]', '["Using smoked paprika (Piment\u00f3n de la Vera) is non-negotiable for authentic Spanish flavor; generic paprika lacks the depth required here.", "This dish keeps exceptionally well. The chickpea skins become more permeable as they sit in the vinegar dressing, absorbing flavor overnight.", "For a texture contrast, you can reserve a handful of chickpeas, pat them very dry, and fry them separately until crispy to use as a garnish.", "If using dried chickpeas instead of canned, soak them overnight and simmer with a bay leaf until tender before starting this recipe."]', '"Legumes are a cornerstone of Spanish cuisine, often appearing in ''platos de cuchara'' (spoon dishes). This salad is reminiscent of an ''Empedrat'' (Catalan bean salad) but uses the warm spice profile typical of Andalusian cooking, highlighting the Moorish influence through the use of cumin and chickpeas."', 402.85);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('517fc62b-bb95-4e47-bb5e-7afed06303cf', 'Lemon-Fire Cornmeal Fried Chicken', 'Golden, shatteringly crisp chicken thighs encasing succulent meat, marinated in a vibrant, high-acid blend of fresh lemon juice and aged hot sauce. The coarse cornmeal crust provides a distinct textural crunch that stands up to the zesty, spicy heat.', 'main course', 'American', 'Intermediate', '["american", "chicken", "cornmeal", "lemon juice", "dinner", "main course", "southern", "fried", "spicy"]', '[{"group_name": "Chicken & Marinade", "items": [{"name": "chicken thighs", "quantity": 1000, "unit": "g", "preparation": "bone-in, skin-on", "notes": "approx. 6-8 pieces", "substitutions": [], "ingredient_id": "d7fc1bf9-fc05-429b-bfa6-2ad857cb0bb6", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 80, "unit": "ml", "preparation": "freshly squeezed", "notes": "about 2 lemons", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "cayenne pepper hot sauce", "quantity": 80, "unit": "ml", "preparation": null, "notes": "Frank''s RedHot or Crystal style", "substitutions": [], "ingredient_id": "f41f3bc3-3ea8-4cba-9158-e69cef32219f", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 60, "unit": "ml", "preparation": null, "notes": "to dilute acidity slightly", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Cornmeal Crust", "items": [{"name": "yellow cornmeal", "quantity": 150, "unit": "g", "preparation": "medium grind", "notes": null, "substitutions": [], "ingredient_id": "7fb6be00-5ba2-483a-af74-961f21de4055", "nutrition_source": "Aggregated Public Data"}, {"name": "all-purpose flour", "quantity": 150, "unit": "g", "preparation": null, "notes": "essential for binding the cornmeal", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic powder", "quantity": 6, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "177a312f-ef99-4398-9108-98f7a608a245", "nutrition_source": "USDA FoodData Central"}, {"name": "onion powder", "quantity": 6, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4f8e972-beb6-438b-aa1b-4129031597a3", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 3, "unit": "g", "preparation": "ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Frying", "items": [{"name": "neutral oil", "quantity": 1500, "unit": "ml", "preparation": null, "notes": "peanut, canola, or vegetable; enough for 5cm depth", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "beaten", "notes": "approx 100g, binder for coating", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Whisk together lemon juice, hot sauce, water, and the first measure of salt (10g) in a large bowl. Add the chicken thighs, tossing to coat thoroughly. Cover and refrigerate.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT4H", "doneness_cues": null}, "tips": ["Do not marinate longer than 6 hours or the high acidity will degrade the meat texture."]}, {"step_number": 2, "phase": "prep", "text": "In a shallow dish, combine cornmeal, flour, garlic powder, onion powder, smoked paprika, black pepper, and the remaining salt (5g). In a separate bowl, whisk the eggs.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "assemble", "text": "Remove chicken from marinade, letting excess liquid drip off. Dip each piece into the beaten eggs, then press firmly into the cornmeal mixture to coat all sides. Place on a wire rack set over a baking sheet.", "structured": {"action": "DREDGE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Pressing the chicken into the flour ensures the cornmeal adheres properly."]}, {"step_number": 4, "phase": "prep", "text": "Let the coated chicken rest on the rack at room temperature for 15-20 minutes. This hydration period ''glues'' the crust to the skin.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Fill a Dutch oven with 5cm of neutral oil. Heat over medium-high heat until the oil reaches 175\u00b0C (350\u00b0F).", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Carefully lower chicken into the oil (fry in batches of 2-3 to avoid overcrowding). Maintain oil temperature between 160\u00b0C-170\u00b0C (320\u00b0F-340\u00b0F) during cooking.", "structured": {"action": "FRY", "temperature": {"celsius": 165, "fahrenheit": 329}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Fry for 12-15 minutes, turning occasionally, until the crust is deep golden brown and the internal temperature at the thickest part reaches 74\u00b0C (165\u00b0F).", "structured": {"action": "FRY", "temperature": null, "duration": "PT14M", "doneness_cues": {"visual": "Deep golden brown crust", "tactile": "Internal temp 74\u00b0C"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Transfer fried chicken to a clean wire rack to drain. Sprinkle immediately with a pinch of salt while hot.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT4H", "total_time": "PT4H45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 672.95, "protein_g": 60.78, "carbohydrates_g": 71.36, "fat_g": 14.62, "saturated_fat_g": 3.81, "trans_fat_g": 0.06, "monounsaturated_fat_g": 4.73, "polyunsaturated_fat_g": 3.08, "fiber_g": 4.81, "sugar_g": 1.56, "sodium_mg": 1880.1, "cholesterol_mg": 328, "potassium_mg": 898.44, "calcium_mg": 58.74, "iron_mg": 6.13, "magnesium_mg": 171.3, "phosphorus_mg": 750.22, "zinc_mg": 6.08, "vitamin_a_mcg": 106.95, "vitamin_c_mg": 8.99, "vitamin_d_mcg": 0.5, "vitamin_e_mg": 1.08, "vitamin_k_mcg": 9.54, "vitamin_b6_mg": 1.25, "vitamin_b12_mcg": 1.75, "thiamin_mg": 0.3, "riboflavin_mg": 0.65, "niacin_mg": 14.53, "folate_mcg": 37.78, "water_g": 247.87, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Crust will lose crispness; reheat in oven/air fryer.", "duration": "P3D"}, "freezer": {"notes": "Freeze on a tray first, then bag. Reheat from frozen.", "duration": "P2M"}, "reheating": "Reheat in an oven at 190\u00b0C (375\u00b0F) on a wire rack for 15-20 minutes until crisp.", "does_not_keep": false}', '[{"name": "Dutch oven or heavy-bottomed pot", "required": true, "alternative": "Deep fryer"}, {"name": "Kitchen thermometer", "required": true, "alternative": "Candy thermometer"}, {"name": "Wire cooling rack", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}]', '[{"symptom": "Coating falls off during frying", "likely_cause": "Chicken was too wet or didn''t rest after dredging", "prevention": "Ensure you rest the breaded chicken for 15 minutes before frying to let the gluten hydrate", "fix": "Handle very gently; cannot be re-adhered"}, {"symptom": "Crust burns before meat is cooked", "likely_cause": "Oil temperature is too high", "prevention": "Use a thermometer to monitor oil; reduce heat once chicken is added", "fix": "Remove from oil, place on rack, and finish cooking in a 175\u00b0C (350\u00b0F) oven"}]', '["The acidity in the lemon and hot sauce acts as a tenderizer similar to buttermilk, but faster. Do not exceed the marinating time.", "Medium-grind cornmeal offers the best texture; fine cornmeal can become pasty, while coarse grind may not adhere well.", "Always fry bone-in chicken thighs for this recipe; breast meat dries out too quickly with the longer fry times required for a thick cornmeal crust."]', '"This recipe marries the Southern US tradition of cornmeal-crusted catfish with classic fried chicken techniques. The lemon-heavy marinade nods to ''lemon pepper'' flavor profiles popular in Atlanta, while the cornmeal provides a heritage grain crunch distinct from standard flour batters."', 672.95);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('51b118c0-9cef-407a-a261-4af7a616d4a4', 'Rustic Skillet Hash with Ham and Eggs', 'A comforting, textural masterpiece featuring crispy cubed potatoes, savory diced ham, and sweet bell peppers, crowned with perfectly steamed-fried eggs. The yolk creates a rich sauce that binds the caramelized hash together.', 'breakfast', 'American', 'Easy', '["potato", "ham", "egg", "quick", "easy", "breakfast", "main course"]', '[{"group_name": "Hash Base", "items": [{"name": "waxy potatoes (e.g., yukon gold)", "quantity": 350, "unit": "g", "preparation": "diced into 1cm cubes", "notes": "scrubbed, skin-on preferred for texture", "substitutions": [], "ingredient_id": "a9d640ff-a969-4f0a-9a92-974f376ac272", "nutrition_source": "Aggregated Public Data"}, {"name": "cooked ham", "quantity": 150, "unit": "g", "preparation": "diced into 1cm cubes", "notes": "thick-cut steak ham or leftovers", "substitutions": [], "ingredient_id": "36d68213-c154-4ada-817e-01a3d979ee9f", "nutrition_source": "Aggregated Public Data"}, {"name": "red bell pepper", "quantity": 100, "unit": "g", "preparation": "diced", "notes": "approx. 1/2 large pepper", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 80, "unit": "g", "preparation": "diced", "notes": "approx. 1/2 medium onion", "substitutions": [], "ingredient_id": "cc868876-7ceb-46a8-b72a-c3e8a743ee97", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Fats & Seasoning", "items": [{"name": "unsalted butter", "quantity": 20, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "adjust to taste based on ham saltiness", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Topping", "items": [{"name": "large eggs", "quantity": 4, "unit": null, "preparation": null, "notes": "approx 200g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh chives", "quantity": 5, "unit": "g", "preparation": "finely chopped", "notes": "for garnish", "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Dice the potatoes, ham, onion, and bell pepper into uniform 1cm (1/2 inch) cubes. Uniformity ensures even cooking.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat olive oil and butter in a large skillet over medium-high heat (approx. 190\u00b0C/375\u00b0F) until the butter foams.", "structured": {"action": "HEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the diced potatoes in a single layer. Cook undisturbed for 4-5 minutes to develop a golden crust, then stir and cook for another 3-4 minutes until tender-crisp.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Golden brown edges", "tactile": "Knife pierces with slight resistance"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Reduce heat to medium. Add the onions, peppers, and ham. Saut\u00e9 for 5-6 minutes until the vegetables are soft and the ham has caramelized slightly. Season with smoked paprika, salt, and pepper.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT6M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Create four small wells (indentations) in the hash mixture using the back of a spoon. Crack an egg into each well.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Cover the skillet with a lid or baking sheet. Cook for 3-5 minutes until the whites are set but the yolks remain runny (or to preference). Target internal egg temperature of 74\u00b0C/165\u00b0F for full safety, or remove earlier for culinary preference.", "structured": {"action": "STEAM", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Opaque whites, jiggly yolks", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from heat immediately to stop cooking. Garnish with fresh chives and serve directly from the skillet.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT5M", "total_time": "PT30M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 380}', '{"flags": ["Gluten-Free", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 579.28, "protein_g": 32.37, "carbohydrates_g": 45.63, "fat_g": 31, "saturated_fat_g": 10.59, "trans_fat_g": 0.04, "monounsaturated_fat_g": 11.5, "polyunsaturated_fat_g": 3.17, "fiber_g": 8.48, "sugar_g": 7.73, "sodium_mg": 1585.91, "cholesterol_mg": 393.5, "potassium_mg": 1695.1, "calcium_mg": 112.71, "iron_mg": 4.46, "magnesium_mg": 113.15, "phosphorus_mg": 580.03, "zinc_mg": 3.41, "vitamin_a_mcg": 347.99, "vitamin_c_mg": 114.34, "vitamin_d_mcg": 2, "vitamin_e_mg": 3.45, "vitamin_k_mcg": 9.59, "vitamin_b6_mg": 0.34, "vitamin_b12_mcg": 0.91, "thiamin_mg": 0.07, "riboflavin_mg": 0.52, "niacin_mg": 0.67, "folate_mcg": 70.88, "water_g": 124.1, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten fresh. Reheated eggs will become rubbery.", "duration": "P2D"}, "freezer": {"notes": null, "duration": null}, "reheating": "Reheat hash in a skillet until crispy; fry a fresh egg to serve on top.", "does_not_keep": false}', '[{"name": "Large cast iron skillet or heavy-bottomed frying pan", "required": true, "alternative": "Non-stick frying pan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Spatula", "required": true, "alternative": null}, {"name": "Lid or baking sheet", "required": true, "alternative": "Aluminum foil"}]', '[{"symptom": "Potatoes are burnt on the outside but raw inside", "likely_cause": "Heat was too high or potato cubes were too large", "prevention": "Keep dice size under 1cm and use medium-high, not high heat", "fix": "Add 2 tablespoons of water and cover tightly to steam them rapidly before adding other veg"}]', '["Use a waxy potato like Yukon Gold or Red Bliss; starchy Russets may disintegrate when stirred vigorously.", "Do not salt the potatoes immediately upon adding them to the pan; salt draws out moisture which inhibits browning. Season in step 4.", "If using leftover honey-baked ham, reduce the added salt, as the reduction of the ham juices will intensify the salinity.", "For a spicy kick, add a pinch of cayenne or red pepper flakes with the paprika."]', '"This dish is a derivative of the American ''Denver Omelet'' flavor profile deconstructed into a hash. Historically, hashes were a method to utilize leftover Sunday roast meat and root vegetables, becoming a staple of diner culture and farmhouse breakfasts across the United States."', 579.28);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('51ea8fb1-8b78-4351-ab26-e6b18477969c', 'Golden Buttermilk Roast Chicken', 'A transformative approach to roast chicken using a 24-hour buttermilk brine. The lactic acid tenderizes the meat while breaking down proteins to retain incredible moisture, and the milk sugars caramelize under high heat to create a deeply bronzed, mahogany skin. Minimal effort yields restaurant-quality results.', 'dinner', 'American', 'Easy', '["american", "poultry", "buttermilk", "five ingredient", "plan-ahead", "roast chicken", "whole chicken", "dinner", "main course", "thanksgiving"]', '[{"group_name": "Main", "items": [{"name": "whole chicken", "quantity": 1800, "unit": "g", "preparation": "raw", "notes": "approx 1.8kg - 2kg bird", "substitutions": [], "ingredient_id": "cdb1c974-22da-499b-8647-8302625c52fb", "nutrition_source": "Aggregated Public Data"}, {"name": "buttermilk", "quantity": 500, "unit": "ml", "preparation": "shaken", "notes": "full fat preferred", "substitutions": [], "ingredient_id": "de1c3d44-e3e7-47d2-a315-83a46edfb165", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 30, "unit": "g", "preparation": null, "notes": "Diamond Crystal preferred; reduce by half if using table salt", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 5, "unit": "g", "preparation": "coarsely cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 5, "unit": null, "preparation": "smashed", "notes": "approx 25g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "The day before roasting, combine buttermilk, kosher salt, black pepper, and smashed garlic in a large resealable bag or bowl. Stir or squish the bag to dissolve the salt thoroughly.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Place the chicken into the brine, ensuring it is fully coated. Expel as much air as possible if using a bag, or weigh down with a plate if using a bowl. Refrigerate for 18 to 24 hours.", "structured": {"action": "MARINATE", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "P1D", "doneness_cues": null}, "tips": ["Rotate the chicken halfway through the marinating time if not fully submerged."]}, {"step_number": 3, "phase": "cook", "text": "Remove the chicken from the refrigerator 1 hour before cooking to temper. Preheat oven to 220\u00b0C (425\u00b0F). Move a rack to the center position.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Remove chicken from the bag and gently wipe off the excess buttermilk drippings with your hands. Do not rinse. Place the chicken in a cast iron skillet or roasting pan. Tie the legs together with twine for even cooking.", "structured": {"action": "TRUSS", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Leaving a thin film of buttermilk helps the browning; leaving too much causes black spots."]}, {"step_number": 5, "phase": "cook", "text": "Roast for approximately 60 minutes. Rotate the pan halfway through if browning unevenly. The chicken is done when the skin is deeply brown and the internal temperature reaches 74\u00b0C (165\u00b0F) at the thickest part of the thigh.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT1H", "doneness_cues": {"visual": "Deep mahogany skin, juices run clear", "tactile": "Legs move freely in sockets"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove from oven and let rest in the pan for at least 15 minutes before carving. This allows the juices to redistribute throughout the meat.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "P1D1H15M", "total_time": "P1D1H35M", "overnight_required": true, "yields": "1 whole chicken", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Gluten-Free", "Keto", "Low-Carb", "Nut-Free", "Egg-Free", "Soy-Free"], "not_suitable_for": ["Vegans", "Vegetarians"]}', '{"per_serving": {"calories": 1155.95, "protein_g": 99.17, "carbohydrates_g": 8.86, "fat_g": 77.91, "saturated_fat_g": 22.9, "trans_fat_g": null, "monounsaturated_fat_g": 0.32, "polyunsaturated_fat_g": 0.07, "fiber_g": 0.45, "sugar_g": 6.77, "sodium_mg": 3451.81, "cholesterol_mg": 5, "potassium_mg": 1194.04, "calcium_mg": 217.65, "iron_mg": 4.82, "magnesium_mg": 17.52, "phosphorus_mg": 122.79, "zinc_mg": 0.62, "vitamin_a_mcg": 226.32, "vitamin_c_mg": 11.3, "vitamin_d_mcg": null, "vitamin_e_mg": 0.08, "vitamin_k_mcg": 2.28, "vitamin_b6_mg": 0.12, "vitamin_b12_mcg": 0.28, "thiamin_mg": 0.05, "riboflavin_mg": 0.2, "niacin_mg": 0.14, "folate_mcg": 6.65, "water_g": 116.46, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store meat off the bone in an airtight container for best moisture retention.", "duration": "P3D"}, "freezer": {"notes": "Best frozen in broth or sauce; plain roasted meat may dry out upon thawing.", "duration": "P3M"}, "reheating": "Gently warm in a covered skillet with a splash of broth to prevent drying.", "does_not_keep": false}', '[{"name": "Large resealable plastic bag or non-reactive bowl", "required": true, "alternative": "Ceramic pot"}, {"name": "Cast iron skillet or roasting pan", "required": true, "alternative": null}, {"name": "Kitchen twine", "required": false, "alternative": "Unwaxed dental floss"}, {"name": "Instant-read thermometer", "required": true, "alternative": null}]', '[{"symptom": "Skin is browning too quickly before meat is cooked", "likely_cause": "Sugar content in buttermilk caramelizing rapidly or oven hot spots", "prevention": "Wipe off excess buttermilk more thoroughly before roasting", "fix": "Tent the dark areas loosely with aluminum foil and reduce oven temperature to 205\u00b0C (400\u00b0F)"}]', '["The 24-hour brine is non-negotiable for the ''unbelievably juicy'' result; the salt modifies the protein structure to hold water while cooking.", "If you have a convection setting, use it but reduce the temperature to 200\u00b0C (400\u00b0F) to prevent burning the milk solids.", "Position the chicken in the oven so the legs point toward the back left or back right corners, which are typically the hottest parts of a standard oven, helping the dark meat cook as fast as the breast."]', '"While buttermilk fried chicken is a Southern staple, roasting chicken in buttermilk was popularized globally by Chef Samin Nosrat. It bridges the gap between traditional American Sunday roast and Southern brining techniques, utilizing the acidity of cultured milk to replicate the tenderness usually reserved for slow-cooking."', 1155.95);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('522fa3f0-f8d6-4a00-aa7e-ac94dd2c1fef', 'Velvet Midnight Chocolate Cake with Cloud Cream Cheese Frosting', 'A deeply moist, almost fudgy chocolate cake crumb achieved through a hot-liquid blooming technique, paired with a remarkably light, airy whipped cream cheese frosting that balances the intense cocoa richness.', 'dessert', 'American', 'Intermediate', '["american", "chocolate", "chocolate cake", "cocoa powder", "dark brown sugar", "dessert", "birthday", "baking"]', '[{"group_name": "Dry Ingredients", "items": [{"name": "all-purpose flour", "quantity": 250, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 200, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "dark brown sugar", "quantity": 100, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "dutch-process cocoa powder", "quantity": 65, "unit": "g", "preparation": null, "notes": "Standard unsweetened cocoa works but is less rich", "substitutions": [], "ingredient_id": "c06a8e5a-163a-4f21-ad00-a6d90e34c38c", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 6, "unit": "g", "preparation": null, "notes": "approx 1.5 tsp", "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 7, "unit": "g", "preparation": null, "notes": "approx 1.5 tsp", "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wet Ingredients", "items": [{"name": "eggs", "quantity": 2, "unit": null, "preparation": "room temperature", "notes": "large, approx 100g total without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "buttermilk", "quantity": 240, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "de1c3d44-e3e7-47d2-a315-83a46edfb165", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 120, "unit": "ml", "preparation": null, "notes": "or any neutral oil like grapeseed", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "hot coffee", "quantity": 240, "unit": "ml", "preparation": "boiling", "notes": "freshly brewed strong coffee or boiling water", "substitutions": [], "ingredient_id": "66c40267-7054-400b-9897-5176b1dccf63", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Whipped Cream Cheese Frosting", "items": [{"name": "cream cheese", "quantity": 340, "unit": "g", "preparation": "cold", "notes": "full-fat block style, not tub", "substitutions": [], "ingredient_id": "262c67de-76a4-4444-8c02-30ad4a179459", "nutrition_source": "USDA FoodData Central"}, {"name": "powdered sugar", "quantity": 120, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy whipping cream", "quantity": 240, "unit": "ml", "preparation": "very cold", "notes": "min 35% fat", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla paste", "quantity": 5, "unit": "ml", "preparation": null, "notes": "extract is also fine", "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 175\u00b0C (350\u00b0F). Grease two 9-inch round cake pans with butter or oil spray and line the bottoms with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Sift the flour, cocoa powder, granulated sugar, brown sugar, baking powder, baking soda, and salt into a large mixing bowl. Whisk briefly to ensure the leavening agents are evenly distributed.", "structured": {"action": "SIFT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a separate jug or bowl, whisk together the eggs, buttermilk, vegetable oil, and vanilla extract until fully emulsified.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Pour the egg mixture into the dry ingredients and mix on low speed until just combined. The batter will be thick.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Slowly pour in the boiling hot coffee while mixing on the lowest speed. Be careful of splashes. Mix only until the batter is uniform; it will be very liquid and runny. This is normal.", "structured": {"action": "MIX", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": null, "doneness_cues": null}, "tips": ["The hot liquid blooms the cocoa powder, releasing more flavor.", "Do not overmix once the liquid is added to prevent gluten development."]}, {"step_number": 6, "phase": "cook", "text": "Divide the batter evenly between the two prepared pans. Bake for 30-35 minutes at 175\u00b0C (350\u00b0F), or until a toothpick inserted into the center comes out with a few moist crumbs attached.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT35M", "doneness_cues": {"visual": "Cake pulls away slightly from edges", "tactile": "Springs back when touched"}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Remove from the oven and let cool in the pans for 20 minutes, then invert onto a wire rack to cool completely. The cakes must be cool to the touch (approx 20-25\u00b0C/68-77\u00b0F) before frosting.", "structured": {"action": "COOL", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "For the frosting: In a chilled bowl, beat the cold cream cheese and powdered sugar on medium speed until smooth and creamy, about 2 minutes. Do not overbeat or it may become runny.", "structured": {"action": "BEAT", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Gradually stream in the cold heavy cream while the mixer is running. Once added, increase speed to high and whip until fluffy, stiff peaks form. Add vanilla towards the end.", "structured": {"action": "WHIP", "temperature": null, "duration": null, "doneness_cues": {"visual": "Holds stiff peaks like whipped cream", "tactile": "Firm but airy"}}, "tips": ["Stop immediately once stiff peaks form. If you go too far, the mixture will curdle."]}, {"step_number": 10, "phase": "assemble", "text": "Place one cake layer on a serving plate. Spread a thick layer of frosting over the top. Place the second layer on top and frost the top and sides with the remaining frosting.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT1H45M", "total_time": "PT2H30M", "overnight_required": false, "yields": "12 slices", "yield_count": 12, "serving_size_g": 160}', '{"flags": ["Vegetarian"], "not_suitable_for": ["Vegans", "Gluten-Free", "Lactose Intolerant"]}', '{"per_serving": {"calories": 502.8, "protein_g": 7.27, "carbohydrates_g": 57.3, "fat_g": 28.92, "saturated_fat_g": 12.63, "trans_fat_g": 0.58, "monounsaturated_fat_g": 4.97, "polyunsaturated_fat_g": 1.01, "fiber_g": 2.57, "sugar_g": 37.56, "sodium_mg": 515.07, "cholesterol_mg": 83.02, "potassium_mg": 226.13, "calcium_mg": 115.93, "iron_mg": 1.35, "magnesium_mg": 40.4, "phosphorus_mg": 150.43, "zinc_mg": 0.91, "vitamin_a_mcg": 185.6, "vitamin_c_mg": 0.32, "vitamin_d_mcg": 0.49, "vitamin_e_mg": 0.55, "vitamin_k_mcg": 1.5, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": 0.21, "thiamin_mg": 0.05, "riboflavin_mg": 0.22, "niacin_mg": 0.49, "folate_mcg": 15.9, "water_g": 74.16, "alcohol_g": 0.43, "caffeine_mg": 20.46}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight cake carrier to prevent the frosting from absorbing fridge odors.", "duration": "P4D"}, "freezer": {"notes": "Freeze unfrosted layers wrapped tightly. Frosted cake freezes well if flash-frozen first.", "duration": "P3M"}, "reheating": "Eat cold or let sit at room temperature for 20 minutes before serving.", "does_not_keep": false}', '[{"name": "9-inch round cake pans", "required": true, "alternative": null}, {"name": "Stand mixer or hand mixer", "required": true, "alternative": "Strong whisk and arm endurance"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Sifter or fine-mesh sieve", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}, {"name": "Offset spatula", "required": true, "alternative": "Back of a spoon"}]', '[{"symptom": "Frosting is soupy or runny", "likely_cause": "Cream cheese was too warm or mixture was over-mixed, breaking the emulsion", "prevention": "Use cold ingredients and stop whipping the moment stiff peaks form", "fix": "Refrigerate for 20 minutes, then whisk briefly by hand; if broken, it cannot be fully fixed but can serve as a glaze"}, {"symptom": "Cake sunk in the middle", "likely_cause": "Oven door was opened too early or underbaked", "prevention": "Do not open oven until at least 25 minutes have passed; verify temp with thermometer", "fix": "Fill the depression with extra frosting or fruit compote"}]', '["Using hot coffee is the secret weapon here; it doesn''t make the cake taste like coffee, but it amplifies the chocolate notes significantly.", "This frosting is a hybrid between a chantilly and a cheesecake batter. It is much less sweet than traditional buttercream and must be kept cool.", "If you want a darker, Oreo-like color, use ''black'' cocoa powder for 50% of the cocoa requirement.", "The batter is extremely liquid compared to standard cakes. Don''t panic; this high moisture content is what keeps the cake tender for days."]', '"The ''Devil''s Food'' style cake emerged in the United States in the early 20th century as a counterpart to the white ''Angel Food'' cake. The use of hot liquid to bloom cocoa is a distinctly American home-baking innovation that maximizes the solubility of cocoa solids, resulting in the iconic dark, dense, and moist texture associated with classic American birthday cakes."', 502.8);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('5343a702-01f7-487a-b9a6-8fbb41aae859', 'Pan-Seared Sea Bream with Sweetcorn Velouté and Chilli Butter', 'Crispy-skinned sea bream fillets seasoned with earthy toasted spices, resting on a pool of silky, sweet corn purée, and finished with a piquant, nutty chilli-lime butter that cuts through the richness.', 'dinner', 'Contemporary', 'Intermediate', '["fish", "seafood", "spicy", "main course", "gluten-free", "dinner party", "sophisticated"]', '[{"group_name": "Spice Blend", "items": [{"name": "fennel seeds", "quantity": 5, "unit": "g", "preparation": "toasted and ground", "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "coriander seeds", "quantity": 5, "unit": "g", "preparation": "toasted and ground", "notes": null, "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 3g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sweetcorn Velout\u00e9", "items": [{"name": "sweetcorn kernels", "quantity": 500, "unit": "g", "preparation": "fresh or frozen", "notes": "reserve 50g whole for garnish", "substitutions": [], "ingredient_id": "46ca2aab-cb23-4397-9711-528c234b2cf8", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "finely chopped", "notes": "approx 30g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "minced", "notes": null, "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable stock", "quantity": 300, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 100, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sea Bream", "items": [{"name": "sea bream fillets", "quantity": 4, "unit": null, "preparation": "skin-on, descaled, pin-boned", "notes": "approx 140g each", "substitutions": [], "ingredient_id": "6a48f21f-c58c-4584-a81e-600a6cd4b283", "nutrition_source": "Aggregated Public Data"}, {"name": "grapeseed oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "or other high heat neutral oil", "substitutions": [], "ingredient_id": "00f43166-1b77-4e77-9e30-e912a59d118a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Chilli Butter", "items": [{"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "red chilli", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "deseeded if preferred mild", "substitutions": [], "ingredient_id": "5080eb9a-d555-4558-94e5-d5700e96ff9b", "nutrition_source": "Aggregated Public Data"}, {"name": "aleppo pepper", "quantity": 2, "unit": "g", "preparation": null, "notes": "or standard chilli flakes", "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}, {"name": "lime juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the spice blend by mixing the toasted ground fennel, coriander, smoked paprika, and salt in a small bowl. Pat the fish fillets completely dry with paper towels. Score the skin lightly 3 times without cutting into the flesh.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "For the velout\u00e9, melt 30g butter in a saucepan over medium heat. Saut\u00e9 the shallots and garlic until soft but not browned (about 3 minutes).", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add 450g of corn kernels (reserve 50g) to the pan. Add vegetable stock and bring to a simmer. Cook for 8-10 minutes until corn is tender. Add heavy cream and simmer for 2 more minutes.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT12M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Transfer the corn mixture to a high-speed blender. Blend on high until extremely smooth. Pass through a fine mesh sieve into a clean pan, pressing on solids to extract all liquid. Season with salt to taste and keep warm.", "structured": {"action": "BLEND", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "For the chilli butter, melt 60g butter in a small saucepan over medium heat. Continue cooking until the butter foams and smells nutty (beurre noisette). Remove from heat immediately. Stir in the diced fresh chilli, Aleppo pepper, reserved corn kernels, and lime juice. Set aside in a warm place.", "structured": {"action": "TEMPER", "temperature": null, "duration": null, "doneness_cues": {"visual": "Golden brown solids", "tactile": "Nutty aroma"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Heat grapeseed oil in a heavy frying pan over medium-high heat. Rub the flesh side of the fish with the spice blend. Salt the skin side. Place fillets skin-side down in the hot oil. Press firmly with a spatula for 10 seconds to prevent curling.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Cook undisturbed for 4-5 minutes until the skin is crisp and the flesh is opaque 2/3 of the way up. Flip carefully and cook on the flesh side for 1 minute or until cooked through (internal temp 60\u00b0C/140\u00b0F).", "structured": {"action": "FRY", "temperature": null, "duration": "PT6M", "doneness_cues": {"visual": "Opaque flesh", "tactile": "Flakes gently"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "To serve, spoon a generous amount of sweetcorn velout\u00e9 into the center of a warm plate. Place the fish atop the sauce, skin-side up. Spoon the warm chilli butter and reserved corn kernels over and around the fish.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT0M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 320}', '{"flags": ["Gluten-Free", "Pescatarian", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 581.27, "protein_g": 30.6, "carbohydrates_g": 29.29, "fat_g": 41.28, "saturated_fat_g": 18.35, "trans_fat_g": 0.31, "monounsaturated_fat_g": 9.65, "polyunsaturated_fat_g": 7.08, "fiber_g": 3.8, "sugar_g": 10.27, "sodium_mg": 836.27, "cholesterol_mg": 76.63, "potassium_mg": 869.77, "calcium_mg": 112.21, "iron_mg": 2.79, "magnesium_mg": 94.33, "phosphorus_mg": 478.43, "zinc_mg": 1.27, "vitamin_a_mcg": 316.5, "vitamin_c_mg": 21.22, "vitamin_d_mcg": 0.4, "vitamin_e_mg": 3.35, "vitamin_k_mcg": 3.72, "vitamin_b6_mg": 0.19, "vitamin_b12_mcg": 0.08, "thiamin_mg": 0.22, "riboflavin_mg": 0.15, "niacin_mg": 2.44, "folate_mcg": 58.03, "water_g": 123.35, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store components separately. Fish best eaten fresh.", "duration": "P2D"}, "freezer": {"notes": "Sauce freezes well; fish does not.", "duration": "P1M"}, "reheating": "Gently reheat sauce on stovetop. Fish is best prepared fresh, but can be warmed in oven at 150\u00b0C/300\u00b0F.", "does_not_keep": false}', '[{"name": "Heavy-bottomed frying pan", "required": true, "alternative": "Cast iron skillet"}, {"name": "Saucepan", "required": true, "alternative": null}, {"name": "High-speed blender", "required": true, "alternative": "Immersion blender"}, {"name": "Fine mesh sieve (chinois)", "required": true, "alternative": "Standard strainer"}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Fish spatula", "required": true, "alternative": "Wide flat spatula"}]', '[{"symptom": "Fish skin is soggy or sticking", "likely_cause": "Pan was not hot enough or fish skin was wet before cooking", "prevention": "Dry skin thoroughly with paper towels and ensure oil is shimmering hot before adding fish", "fix": "Do not attempt to move the fish until it releases naturally; increase heat slightly"}, {"symptom": "Sauce is grainy", "likely_cause": "Corn hulls not pulverized or mixture not strained", "prevention": "Blend longer and always pass through a fine sieve", "fix": "Strain again through a finer mesh or cheesecloth"}]', '["Passing the corn sauce through a sieve is the difference between a rustic chowder and a Michelin-style velout\u00e9. Don''t skip it.", "When making the chilli butter, the lime juice is crucial to arrest the cooking of the butter so it doesn''t burn, and to provide acid balance.", "If you cannot find Sea Bream, Red Snapper or Branzino (European Sea Bass) are excellent alternatives with similar skin textures.", "Pressing the fish down with a spatula for the first few seconds of cooking is the secret to perfectly flat, evenly cooked fillets."]', '"This dish draws from modern European coastal cuisine, pairing the Mediterranean staple of Sea Bream (Dorade) with the sweetness of corn and the heat of chilli, reflecting a fusion style popular in contemporary London and Australian dining scenes."', 581.27);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('537472d3-d87f-4a19-b2d0-a98ca931890f', 'Classic Simple Marinara Sauce', 'A vibrant, ruby-red tomato sauce balancing the natural sweetness of San Marzano tomatoes with aromatic garlic and peppery olive oil. The texture is rustic yet velvety, coating pasta perfectly with a bright, fresh flavor profile distinct from heavy, long-simmered meat sauces.', 'sauce', 'Italian', 'Easy', '["italian", "garlic", "tomato", "dinner", "easy", "gluten-free", "vegan", "vegetarian", "sauce", "pasta"]', '[{"group_name": "Aromatics", "items": [{"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": "room temperature", "notes": "use high quality oil", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "thinly sliced", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "red pepper flakes", "quantity": 1, "unit": "g", "preparation": null, "notes": "optional, for heat", "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Tomatoes & Seasoning", "items": [{"name": "whole peeled tomatoes", "quantity": 800, "unit": "g", "preparation": "canned", "notes": "San Marzano variety preferred", "substitutions": ["crushed tomatoes"], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 60, "unit": "ml", "preparation": null, "notes": "to rinse the tomato can", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh basil", "quantity": 1, "unit": null, "preparation": "whole sprig", "notes": "plus fresh leaves for garnish", "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pour the canned tomatoes with their juices into a bowl and crush them by hand until chunky. Remove any hard stem ends or skins that feel tough.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": {"visual": "Tomatoes are broken into bite-sized chunks", "tactile": "No large whole tomatoes remain"}}, "tips": ["Hand crushing yields the best rustic texture compared to a blender."]}, {"step_number": 2, "phase": "cook", "text": "Combine olive oil and sliced garlic in a cold pot. Turn heat to medium-low and cook slowly, stirring often, until the garlic is pale golden and fragrant. Do not brown.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": "PT3M", "doneness_cues": {"visual": "Garlic is pale gold, bubbles gently", "tactile": "Garlic is soft"}}, "tips": ["Starting in cold oil infuses the garlic flavor more thoroughly and prevents burning."]}, {"step_number": 3, "phase": "cook", "text": "Add the red pepper flakes (if using), then immediately pour in the crushed tomatoes. Swirl the water in the empty tomato can to catch remaining juices and pour into the pot. Add the salt and whole basil sprig.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Ingredients are fully combined", "tactile": "Liquid level rises"}}, "tips": ["Be careful of splatter when adding tomatoes to hot oil."]}, {"step_number": 4, "phase": "cook", "text": "Increase heat to bring to a gentle bubble, then reduce to low. Simmer uncovered, stirring occasionally, until the sauce thickens and oil droplets appear on the surface.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT20M", "doneness_cues": {"visual": "Sauce has reduced slightly and turned a deeper red", "tactile": "Spoon leaves a trail that slowly fills back in"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove and discard the wilted basil sprig. Taste the sauce and adjust salt if needed. Stir in fresh basil leaves just before serving.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": {"visual": "Sauce is glossy and rich", "tactile": "Flavor is balanced"}}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT20M", "total_time": "PT30M", "overnight_required": false, "yields": "800ml", "yield_count": 6, "serving_size_g": 130}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Paleo", "Whole30", "Low-Carb", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 116.73, "protein_g": 1.43, "carbohydrates_g": 6.04, "fat_g": 10.33, "saturated_fat_g": 1.43, "trans_fat_g": null, "monounsaturated_fat_g": 7.31, "polyunsaturated_fat_g": 1.08, "fiber_g": 2.54, "sugar_g": 5.25, "sodium_mg": 201.65, "cholesterol_mg": null, "potassium_mg": 338.01, "calcium_mg": 23.89, "iron_mg": 0.58, "magnesium_mg": 17.79, "phosphorus_mg": 37.53, "zinc_mg": 0.28, "vitamin_a_mcg": 12.82, "vitamin_c_mg": 19.66, "vitamin_d_mcg": null, "vitamin_e_mg": 1.52, "vitamin_k_mcg": 20.89, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.01, "niacin_mg": 0.06, "folate_mcg": 2.65, "water_g": 14.45, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container.", "duration": "P5D"}, "freezer": {"notes": "Freeze in portions. Thaw overnight in the fridge before reheating.", "duration": "P6M"}, "reheating": "Simmer gently on the stove over low heat until warmed through.", "does_not_keep": false}', '[{"name": "Large heavy-bottomed pot or Dutch oven", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": null}, {"name": "Bowl", "required": true, "alternative": "Use the pot directly if careful"}, {"name": "Knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Sauce tastes bitter", "likely_cause": "The garlic was burned during the saut\u00e9 step", "prevention": "Start garlic in cold oil and keep heat low; if it turns brown, it is burnt", "fix": "Cannot be fixed; the burnt flavor permeates the oil. You must start over."}, {"symptom": "Sauce is too watery", "likely_cause": "Tomatoes had high water content or simmer time was too short", "prevention": "Simmer uncovered to allow evaporation", "fix": "Continue simmering for another 5-10 minutes"}]', '["San Marzano tomatoes are non-negotiable for a true Italian flavor profile; they have fewer seeds and sweeter flesh.", "Do not skimp on the olive oil. The quantity may seem high, but it emulsifies with the tomatoes to create a velvety, rich mouthfeel.", "For a smoother sauce, you can pass the finished product through a food mill, but the rustic chunky texture is traditional for marinara.", "The basil sprig added during cooking infuses a subtle herbal background, while fresh leaves at the end provide the aromatic punch."]', '"Marinara (''mariner''s style'') originated in Naples, Italy. Historically, it was a meal for sailors returning from sea, relying on ingredients that stored well on long voyages like dried pasta, garlic, and oil, combined with fresh local tomatoes."', 116.73);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('54240a3b-3525-4d6e-bca1-5fae3b2bf934', 'Creamy Sausage and Radicchio Gnocchi', 'A luxurious interplay of textures and flavors where the savory richness of browned Italian sausage is cut by the sophisticated bitterness of wilted radicchio, all bound together by a velvety, Parmesan-enriched cream sauce clinging to pillowy potato dumplings.', 'dinner', 'Italian', 'Intermediate', '["gnocchi", "sausage", "radicchio", "italian-inspired", "comfort food", "winter", "pasta"]', '[{"group_name": "Main Components", "items": [{"name": "potato gnocchi", "quantity": 500, "unit": "g", "preparation": "fresh or shelf-stable", "notes": "High quality store-bought or homemade", "substitutions": [], "ingredient_id": "62efb2b2-9ab0-4ba5-8dd6-5d5b2fa90886", "nutrition_source": "Aggregated Public Data"}, {"name": "italian sausage", "quantity": 450, "unit": "g", "preparation": "casings removed", "notes": "Mild or spicy depending on preference", "substitutions": [], "ingredient_id": "62fcde4d-d123-4d87-8460-70bf9a3a0b9c", "nutrition_source": "USDA FoodData Central"}, {"name": "radicchio di chioggia", "quantity": 1, "unit": null, "preparation": "cored and shredded", "notes": "approx 300g head", "substitutions": [], "ingredient_id": "5d8e2872-e1dd-48d7-b21e-07bce7ae8147", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sauce & Aromatics", "items": [{"name": "heavy cream", "quantity": 200, "unit": "ml", "preparation": "min 35% fat", "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 60, "unit": "ml", "preparation": null, "notes": "Pinot Grigio or Sauvignon Blanc", "substitutions": [], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "approx 30g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "parmigiano reggiano", "quantity": 40, "unit": "g", "preparation": "freshly grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 2, "unit": "g", "preparation": "leaves picked", "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Bring a large pot of salted water to a boil. Meanwhile, core the radicchio and slice it into 1cm thick ribbons. Remove sausage meat from casings if necessary.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a large deep skillet, heat the olive oil over medium-high heat. Add the sausage meat, breaking it up with a wooden spoon into bite-sized chunks. Cook until well-browned and caramelized.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT6M", "doneness_cues": {"visual": "Deep golden brown crust on meat", "tactile": "Meat is firm and crumbled"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to medium. Add the minced shallot and garlic to the pan with the sausage, cooking for 1 minute until fragrant. Add the sliced radicchio and thyme. Saut\u00e9 until the radicchio has wilted and reduced in volume by half.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Radicchio is wilted and darkened", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Deglaze the pan with the white wine, scraping up any browned bits (fond) from the bottom. Let the wine reduce by half to concentrate the flavor.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Liquid reduced by 50%", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour in the heavy cream and bring to a gentle simmer. Let it bubble gently while you cook the gnocchi.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Add the gnocchi to the boiling water. Cook only until they float to the surface (usually 2-3 minutes). Do not overcook.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Gnocchi floating on surface", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Using a spider strainer, transfer the gnocchi directly from the water into the skillet with the sauce. Add 60ml (approx 1/4 cup) of the starchy pasta water to the skillet.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Toss the gnocchi vigorously in the sauce over medium heat for 1 minute to emulsify. Remove from heat and stir in the grated Parmesan cheese until melted and creamy. Season with black pepper.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Sauce is glossy and coats the gnocchi (napp\u00e9)", "tactile": null}}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT5M", "total_time": "PT30M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 360}', '{"flags": ["Nut-Free", "Egg-Free", "Soy-Free"], "not_suitable_for": ["Vegetarians", "Vegans", "Dairy intolerance"]}', '{"per_serving": {"calories": 935.81, "protein_g": 26.68, "carbohydrates_g": 46.76, "fat_g": 73.02, "saturated_fat_g": 28.18, "trans_fat_g": 0.62, "monounsaturated_fat_g": 27.4, "polyunsaturated_fat_g": 5.73, "fiber_g": 4.71, "sugar_g": 3.95, "sodium_mg": 1878.78, "cholesterol_mg": 143.18, "potassium_mg": 819.38, "calcium_mg": 224.37, "iron_mg": 3.12, "magnesium_mg": 35.01, "phosphorus_mg": 258.42, "zinc_mg": 3.04, "vitamin_a_mcg": 301.13, "vitamin_c_mg": 11.61, "vitamin_d_mcg": 1.64, "vitamin_e_mg": 2.98, "vitamin_k_mcg": 198, "vitamin_b6_mg": 0.19, "vitamin_b12_mcg": 0.69, "thiamin_mg": 0.45, "riboflavin_mg": 0.33, "niacin_mg": 4.09, "folate_mcg": 52.89, "water_g": 159.69, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Sauce will thicken significantly; loosen with a splash of water or milk when reheating.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; cream sauces tend to split and gnocchi texture degrades.", "duration": null}, "reheating": "Reheat gently on the stove over low heat with a splash of water to re-emulsify the sauce.", "does_not_keep": false}', '[{"name": "Large deep skillet or saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Large pot", "required": true, "alternative": "Dutch oven"}, {"name": "Spider strainer or slotted spoon", "required": true, "alternative": "Colander"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Microplane or cheese grater", "required": true, "alternative": null}]', '[{"symptom": "Sauce is split or oily", "likely_cause": "The emulsion broke due to excessive heat after adding cheese or insufficient starch", "prevention": "Remove pan from heat before adding cheese; ensure pasta water is added", "fix": "Add a splash of cold water or cream and whisk vigorously off the heat"}, {"symptom": "Dish is too bitter", "likely_cause": "Radicchio was not cooked long enough or was naturally very potent", "prevention": "Saut\u00e9 radicchio thoroughly to caramelize slightly", "fix": "Add a teaspoon of honey or balsamic glaze to counterbalance the bitterness"}]', '["Radicchio will turn a brownish-purple when cooked. This is visually less vibrant than raw, but essential for taming its aggressive bitterness.", "Do not drain the gnocchi in a colander in the sink. Transferring them wet brings essential starch into the sauce, acting as a natural thickener.", "If using store-bought gnocchi, look for brands found in the refrigerated pasta section rather than the shelf-stable vacuum packs for a lighter texture.", "For an extra depth of flavor, add a pinch of freshly grated nutmeg when adding the cream.", "Browning the sausage is the most critical step for flavor; do not rush this phase, as the fond created on the pan forms the base of the sauce."]', '"The pairing of rich pork products with bitter greens is a hallmark of Northern Italian cuisine, particularly in the Veneto and Friuli-Venezia Giulia regions. This dish balances the ''dolce'' (sweet) richness of the sausage and cream with the ''amaro'' (bitter) notes of the radicchio, a flavor profile highly prized in Italian gastronomy."', 935.81);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('545ad8df-c06c-42aa-b277-5c112c711a5a', 'Gingery Pork Meatballs with Lime-Glazed Peaches', 'Juicy, savory pork meatballs spiked with fresh ginger and garlic, pan-seared and finished in a vibrant sauce with sweet summer peaches and zesty lime. The aromatic basil adds a fresh, peppery finish that ties the sweet and savory elements together.', 'main course', 'Fusion', 'Easy', '["meat", "meatballs", "basil", "garlic", "ginger", "great leftovers", "peach", "pork", "dinner", "weeknight", "main course", "summer", "fusion"]', '[{"group_name": "Meatballs", "items": [{"name": "ground pork", "quantity": 500, "unit": "g", "preparation": "chilled", "notes": null, "substitutions": [], "ingredient_id": "95b412ba-c68f-4b61-ae87-42b44000956b", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 20, "unit": "g", "preparation": "finely grated", "notes": "approx. 4cm piece", "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx. 6-8g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "panko breadcrumbs", "quantity": 30, "unit": "g", "preparation": null, "notes": "use gluten-free breadcrumbs if required", "substitutions": [], "ingredient_id": "92441189-214a-4a8a-9cfc-dd578fe0d179", "nutrition_source": "USDA FoodData Central"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": "large", "notes": null, "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["tamari", "coconut aminos"], "ingredient_id": "1a157828-0624-4e67-815d-8e6bdf8b23c2", "nutrition_source": "USDA FoodData Central"}, {"name": "sesame oil", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e74beff5-5295-4a3f-82fb-9f8ef1d5da59", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Glaze & Assembly", "items": [{"name": "neutral oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "vegetable or canola", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}, {"name": "peaches", "quantity": 2, "unit": null, "preparation": "pitted and cut into wedges", "notes": "approx. 300g total; ripe but firm", "substitutions": [], "ingredient_id": "101334cc-5917-44f9-80c1-2dddfb1a77c9", "nutrition_source": "USDA FoodData Central"}, {"name": "lime juice", "quantity": 30, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "fish sauce", "quantity": 5, "unit": "ml", "preparation": null, "notes": "adds savory depth", "substitutions": [], "ingredient_id": "95a9a747-50ee-4be0-84be-0dfc96111e2a", "nutrition_source": "Aggregated Public Data"}, {"name": "honey", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh basil leaves", "quantity": 10, "unit": "g", "preparation": "torn", "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the meatball mixture. In a large bowl, combine the ground pork, grated ginger, minced garlic, panko breadcrumbs, egg, soy sauce, sesame oil, salt, and black pepper. Mix gently with your hands until just combined.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": ["Do not overmix, or the meatballs will become tough and rubbery."]}, {"step_number": 2, "phase": "prep", "text": "Shape the mixture into balls approximately 3-4cm in diameter (roughly golf-ball sized). You should get about 16-20 meatballs.", "structured": {"action": "SHAPE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": ["Wet your hands slightly with water or oil to prevent the meat from sticking to your skin."]}, {"step_number": 3, "phase": "cook", "text": "Heat the neutral oil in a large skillet over medium-high heat. Add the meatballs in a single layer (work in batches if necessary) and sear until browned on all sides, about 6-8 minutes total.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT8M", "doneness_cues": {"visual": "Golden brown crust on all sides", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Once browned, reduce heat to medium. Ensure meatballs are cooked through (internal temperature should reach 71\u00b0C/160\u00b0F). Push the meatballs to one side of the pan.", "structured": {"action": "COOK", "temperature": {"celsius": 71, "fahrenheit": 160}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the peach wedges to the empty side of the skillet. Sear briefly for 1-2 minutes until they just start to soften and caramelize at the edges.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Pour in the lime juice, honey, and fish sauce (if using). Gently toss the meatballs and peaches together in the bubbling sauce to coat. Cook for 1 more minute to let the flavors meld.", "structured": {"action": "GLAZE", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from heat. Immediately stir in the fresh basil leaves so they wilt slightly but retain their bright green color and aroma. Serve immediately.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT5M", "total_time": "PT30M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 225}', '{"flags": ["Dairy-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 441.17, "protein_g": 25.09, "carbohydrates_g": 18.55, "fat_g": 29.62, "saturated_fat_g": 10.53, "trans_fat_g": 0.01, "monounsaturated_fat_g": 12.9, "polyunsaturated_fat_g": 3.41, "fiber_g": 1.77, "sugar_g": 10.18, "sodium_mg": 747.76, "cholesterol_mg": 136.5, "potassium_mg": 602.3, "calcium_mg": 55.04, "iron_mg": 2.22, "magnesium_mg": 42.94, "phosphorus_mg": 282.15, "zinc_mg": 3.24, "vitamin_a_mcg": 41.39, "vitamin_c_mg": 9.43, "vitamin_d_mcg": 0.25, "vitamin_e_mg": 0.76, "vitamin_k_mcg": 13.52, "vitamin_b6_mg": 0.57, "vitamin_b12_mcg": 1.01, "thiamin_mg": 1.02, "riboflavin_mg": 0.41, "niacin_mg": 6.74, "folate_mcg": 26.82, "water_g": 170.52, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. The peaches may soften further upon reheating.", "duration": "P3D"}, "freezer": {"notes": "Meatballs freeze well, but the texture of the peaches will degrade significantly. Freezing not recommended for the full dish.", "duration": "P1M"}, "reheating": "Reheat gently in a skillet over low heat until warmed through, or microwave in short intervals.", "does_not_keep": false}', '[{"name": "Large skillet or frying pan", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Microplane or grater", "required": true, "alternative": null}]', '[{"symptom": "Peaches turned into mush", "likely_cause": "Peaches were too ripe or cooked for too long", "prevention": "Use firm-ripe peaches and add them only at the very end of the cooking process", "fix": "Cannot be fixed structurally, but will still taste delicious as a sauce component"}]', '["Select peaches that are fragrant but firm to the touch. If they are too soft, they will disintegrate in the pan.", "If you want a spicy kick, add a sliced fresh chili or a pinch of chili flakes when adding the lime juice.", "This dish relies on the balance of fat (pork), acid (lime), and sugar (peach/honey). Taste the pan sauce at the end and adjust lime or honey if your peaches are particularly sour or sweet.", "Thai basil is an excellent substitute for sweet basil if you want a more anise-forward flavor profile.", "Serve over jasmine rice or rice noodles to soak up the juices."]', '"While not a traditional dish from a specific country, this recipe borrows from Southeast Asian culinary principles where pork is frequently paired with fruit, aromatics like ginger, and high-acid dressings to balance the richness of the meat."', 441.17);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('546d27cb-2853-44f2-abda-c4555f7093be', 'One-Pot Umami Mushroom & Leek Orecchiette', 'A deeply savory, creamy pasta dish built on the foundation of golden-brown mushrooms and sweet, melted leeks. The one-pot ''risottata'' method releases pasta starch directly into the sauce, creating a velvety coating enriched with fresh ricotta.', 'dinner', 'Italian', 'Easy', '["one pot", "pasta", "leek", "mushroom", "orecchiette", "penne", "ricotta", "dinner", "easy", "main course", "vegetarian"]', '[{"group_name": "Vegetables & Aromatics", "items": [{"name": "mixed mushrooms (cremini, shiitake, or oyster)", "quantity": 450, "unit": "g", "preparation": "cleaned and sliced", "notes": "Use a mix for best flavor complexity", "substitutions": [], "ingredient_id": "8a4fb37c-f8db-4c2f-b14d-f2dc7aef4c24", "nutrition_source": "USDA FoodData Central"}, {"name": "leeks", "quantity": 2, "unit": null, "preparation": "white and light green parts only, sliced into half-moons", "notes": "approx. 300g trimmed weight", "substitutions": [], "ingredient_id": "f0bddafa-51db-4e56-954b-18624daa6fa4", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme leaves", "quantity": 1, "unit": null, "preparation": "picked", "notes": "approx. 1 tbsp", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Pantry & Base", "items": [{"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "dried orecchiette pasta", "quantity": 350, "unit": "g", "preparation": null, "notes": null, "substitutions": ["penne", "fusilli"], "ingredient_id": "44a505c6-0cdd-4972-844f-a2329a525f70", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable stock", "quantity": 850, "unit": "ml", "preparation": "hot", "notes": null, "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "dry white wine", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["extra vegetable stock", "splash of vinegar"], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "soy sauce", "quantity": 10, "unit": "ml", "preparation": null, "notes": "secret ingredient for umami depth", "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Finish", "items": [{"name": "whole milk ricotta cheese", "quantity": 120, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "7a68dbea-ec03-42ae-b0eb-983bf3d4c7b6", "nutrition_source": "USDA FoodData Central"}, {"name": "parmesan cheese", "quantity": 40, "unit": "g", "preparation": "freshly grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": "zest only", "notes": "for brightness", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "generous amount to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Clean the leeks thoroughly. Slice them into half-moons and submerge in a bowl of cold water to release grit. Lift them out (leaving grit at the bottom) and pat dry.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat olive oil in a Dutch oven over medium-high heat. Add the mushrooms in a single layer (work in two batches if necessary) and cook undisturbed until deep golden brown. Stir and cook for another 2-3 minutes.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT8M", "doneness_cues": {"visual": "Deep golden brown edges", "tactile": "Reduced in size, crispy edges"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to medium. Add the butter to the pot with the mushrooms. Add the leeks and a pinch of salt. Saut\u00e9 until the leeks are very soft and sweet, but not burnt.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT6M", "doneness_cues": {"visual": "Leeks are translucent and melting", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Stir in the minced garlic and thyme, cooking for 1 minute until fragrant. Deglaze the pan with white wine, scraping up any browned bits (fond) from the bottom.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the vegetable stock, soy sauce, and the dry pasta. Ensure the pasta is mostly submerged. Bring to a boil, then reduce heat to a simmer.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT12M", "doneness_cues": {"visual": "Most liquid absorbed", "tactile": "Pasta is al dente"}}, "tips": ["Stir frequently to prevent pasta from sticking to the bottom."]}, {"step_number": 6, "phase": "finish", "text": "Once pasta is cooked and a creamy starchy sauce remains, turn off the heat. Fold in the ricotta, parmesan, and lemon zest. Season generously with black pepper. If too thick, add a splash of water.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": {"visual": "Glossy, creamy sauce coating the pasta", "tactile": null}}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT10M", "total_time": "PT35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Vegetarian", "Nut-Free", "Egg-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 637.88, "protein_g": 23.77, "carbohydrates_g": 87.28, "fat_g": 21.56, "saturated_fat_g": 8.41, "trans_fat_g": 0.1, "monounsaturated_fat_g": 8.79, "polyunsaturated_fat_g": 1.42, "fiber_g": 5.48, "sugar_g": 10.84, "sodium_mg": 1577.6, "cholesterol_mg": 37.63, "potassium_mg": 802.1, "calcium_mg": 312.63, "iron_mg": 4.97, "magnesium_mg": 48.46, "phosphorus_mg": 256.88, "zinc_mg": 1.18, "vitamin_a_mcg": 260.12, "vitamin_c_mg": 25.66, "vitamin_d_mcg": 0.34, "vitamin_e_mg": 1.36, "vitamin_k_mcg": 6.41, "vitamin_b6_mg": 0.21, "vitamin_b12_mcg": 0.43, "thiamin_mg": 0.11, "riboflavin_mg": 0.59, "niacin_mg": 4.2, "folate_mcg": 24.1, "water_g": 151.5, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Pasta may absorb more liquid; add a splash of water when reheating.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; ricotta sauce will separate and texture will suffer.", "duration": null}, "reheating": "Gently reheat on the stove with a splash of water or milk to loosen the sauce.", "does_not_keep": false}', '[{"name": "Dutch oven or large heavy-bottomed pot", "required": true, "alternative": "Deep saut\u00e9 pan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": null}]', '[{"symptom": "Pasta is still hard but liquid is gone", "likely_cause": "Heat was too high (evaporation) or pasta shape requires more hydration", "prevention": "Keep a lid partially on during simmering or use lower heat", "fix": "Add 50-100ml of hot water or stock and continue cooking for 2-3 minutes"}]', '["Do not salt the mushrooms until after they have browned; salting early draws out moisture and causes them to steam rather than sear.", "Orecchiette is ideal here because the little cup shapes catch the creamy ricotta sauce and mushroom bits.", "The soy sauce is not traditional Italian, but it adds a crucial ''meatiness'' to the mushroom base that mimics beef stock.", "If using Penne instead of Orecchiette, you may need slightly more liquid (approx. 50ml extra) as the tubes absorb heavily.", "Washing leeks is the most critical prep step; sand ruins the texture instantly."]', '"While based on the Italian ''pasta risottata'' technique where pasta is cooked in its own sauce like rice, this specific combination highlights the modern focus on vegetable-forward, umami-dense comfort food suitable for weeknight cooking."', 637.88);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('57a80a52-eb6f-4fad-a6d5-6586bdee67ef', 'Sizzling Chicken Fajitas with Fresh Guacamole', 'Tender strips of marinated chicken charred to perfection, tossed with sweet blistered bell peppers and onions. Served in warm flour tortillas with a side of bright, creamy guacamole for a vibrant textural contrast.', 'dinner', 'Mexican', 'Intermediate', '["fajitas", "mexican", "chicken", "quick meal", "dinner", "tex-mex"]', '[{"group_name": "Marinade", "items": [{"name": "vegetable oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": "divided use", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "lime juice", "quantity": 30, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "chili powder", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 9g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": "adds savory depth/browning", "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Fajita Filling", "items": [{"name": "boneless skinless chicken thighs", "quantity": 600, "unit": "g", "preparation": "trimmed of excess fat", "notes": null, "substitutions": [], "ingredient_id": "d7fc1bf9-fc05-429b-bfa6-2ad857cb0bb6", "nutrition_source": "USDA FoodData Central"}, {"name": "red bell pepper", "quantity": 1, "unit": null, "preparation": "sliced into strips", "notes": "approx 150g", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "Aggregated Public Data"}, {"name": "yellow bell pepper", "quantity": 1, "unit": null, "preparation": "sliced into strips", "notes": "approx 150g", "substitutions": [], "ingredient_id": "b8ed9fc6-8806-4baf-a073-89a5b79f63f0", "nutrition_source": "Aggregated Public Data"}, {"name": "red onion", "quantity": 1, "unit": null, "preparation": "sliced into strips", "notes": "approx 150g", "substitutions": [], "ingredient_id": "1c270c6e-0acc-4c5c-9935-7eff3240fc4a", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Fresh Guacamole", "items": [{"name": "ripe avocados", "quantity": 2, "unit": null, "preparation": null, "notes": "approx 400g total weight", "substitutions": [], "ingredient_id": "35c8f26f-d008-407a-9bf3-48c8aa641729", "nutrition_source": "USDA FoodData Central"}, {"name": "lime juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "cilantro", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, start with 2g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Serving", "items": [{"name": "flour tortillas", "quantity": 8, "unit": null, "preparation": null, "notes": "15cm diameter", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Whisk together 30ml of the vegetable oil, lime juice, cumin, smoked paprika, chili powder, minced garlic, and soy sauce in a small bowl.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Place the whole chicken thighs in a large bag or dish and pour the marinade over them. Massage to coat ensuring even coverage. Let sit at room temperature.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": ["Room temperature marinating helps the chicken cook more evenly.", "Do not marinate longer than 2 hours as the lime juice will break down the meat texture too much."]}, {"step_number": 3, "phase": "prep", "text": "While chicken marinates, cut the avocados in half, remove pits, and scoop flesh into a bowl. Mash with 15ml lime juice, chopped cilantro, and salt until desired consistency is reached.", "structured": {"action": "MIX", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Heat a large cast iron skillet over high heat until smoking hot. Add the remaining 15ml oil.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 230, "fahrenheit": 446}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Remove chicken from marinade (discard excess liquid) and place in the hot skillet. Sear undisturbed for 4-5 minutes until deeply browned.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Flip chicken and cook for another 3-4 minutes until the internal temperature reaches 74\u00b0C/165\u00b0F. Remove chicken to a clean board to rest.", "structured": {"action": "COOK", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": "PT4M", "doneness_cues": {"visual": "Deep brown crust", "tactile": "Firm to touch"}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "In the same hot skillet (do not wipe out), add the sliced onions and peppers. Saut\u00e9 vigorously, scraping up the browned bits from the bottom, until vegetables are tender-crisp and charred in spots.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Charred edges on peppers", "tactile": "Softened but retaining crunch"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Slice the rested chicken against the grain into strips. Return the chicken and any accumulated juices to the skillet with the vegetables. Toss briefly to combine and reheat.", "structured": {"action": "SLICE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Warm tortillas in a dry pan or directly over a gas flame for 10-15 seconds per side. Serve immediately with the skillet mixture and fresh guacamole.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT30M", "total_time": "PT1H5M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Dairy-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 713.47, "protein_g": 41.07, "carbohydrates_g": 74.03, "fat_g": 29.14, "saturated_fat_g": 5.46, "trans_fat_g": 0.03, "monounsaturated_fat_g": 8.07, "polyunsaturated_fat_g": 3.69, "fiber_g": 10.57, "sugar_g": 6.9, "sodium_mg": 1255.08, "cholesterol_mg": 141, "potassium_mg": 1135.98, "calcium_mg": 77.21, "iron_mg": 4.14, "magnesium_mg": 93.89, "phosphorus_mg": 431.57, "zinc_mg": 3.63, "vitamin_a_mcg": 181.14, "vitamin_c_mg": 140.13, "vitamin_d_mcg": null, "vitamin_e_mg": 4.48, "vitamin_k_mcg": 9.72, "vitamin_b6_mg": 1.05, "vitamin_b12_mcg": 0.92, "thiamin_mg": 0.3, "riboflavin_mg": 0.46, "niacin_mg": 10.95, "folate_mcg": 88.57, "water_g": 315.85, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store filling and guacamole separately. Guacamole will brown; press plastic wrap directly onto surface.", "duration": "P3D"}, "freezer": {"notes": "Chicken and peppers freeze well; do not freeze guacamole or tortillas.", "duration": "P2M"}, "reheating": "Reheat chicken and pepper mixture in a hot skillet for best texture. Warm tortillas fresh.", "does_not_keep": false}', '[{"name": "Cast iron skillet", "required": true, "alternative": "Heavy-bottomed stainless steel pan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Large zip-top bag or bowl", "required": true, "alternative": "Glass baking dish for marinating"}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Vegetables are soggy instead of charred", "likely_cause": "The pan was overcrowded or the heat was too low", "prevention": "Use the largest skillet possible and keep heat on high; cook in two batches if necessary", "fix": "Remove vegetables, drain excess liquid from pan, reheat pan until smoking, and return vegetables briefly to char"}]', '["Slicing the chicken after cooking rather than before ensures it stays juicy and prevents it from drying out in the high heat.", "The soy sauce in the marinade is not traditional, but it adds a crucial ''umami'' depth and helps the chicken brown beautifully.", "Warm tortillas are essential. Cold tortillas are brittle and unappetizing. Wrap warmed tortillas in a clean tea towel to keep them soft at the table.", "For extra smoke flavor, you can let the peppers char undisturbed for 60 seconds before tossing them."]', '"Fajitas originated in the Rio Grande Valley of Texas, where Mexican ranch workers were often paid partly in meat, receiving the ''fajas'' or little belts (skirt steak) of the cow. While skirt steak is the traditional cut, the concept has evolved to include chicken and shrimp, becoming a staple of Tex-Mex cuisine defined by the theatrical sizzling skillet."', 713.47);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('57d34285-fc29-43b3-9df5-2c86b1a3b0b2', 'Tropical Gingersnap & Caramelized Pineapple Cheesecake Bars', 'A vibrant no-bake dessert featuring a spicy, crunchy gingersnap base topped with ultra-creamy coconut-lime cheesecake. Swirls of jammy, golden-caramelized pineapple cut through the richness, finishing with a tropical aromatic lift.', 'dessert', 'Tropical Fusion', 'Intermediate', '["bar cookie", "cheesecake", "coconut milk", "cream cheese", "ginger", "pineapple", "plan-ahead", "snack", "dessert", "thanksgiving"]', '[{"group_name": "Caramelized Pineapple Jam", "items": [{"name": "fresh pineapple", "quantity": 300, "unit": "g", "preparation": "finely diced", "notes": "canned works if drained very well", "substitutions": [], "ingredient_id": "37da68de-6b6e-4619-9f28-52da1f26f4ce", "nutrition_source": "USDA FoodData Central"}, {"name": "brown sugar", "quantity": 45, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "lime juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Gingersnap Crust", "items": [{"name": "gingersnap cookies", "quantity": 250, "unit": "g", "preparation": null, "notes": "crispy variety, not soft", "substitutions": [], "ingredient_id": "0070830f-d44d-4937-ba83-bc785ef4887a", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 90, "unit": "g", "preparation": "melted", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "ground ginger", "quantity": 2, "unit": "g", "preparation": null, "notes": "optional for extra kick", "substitutions": [], "ingredient_id": "401ddd0b-3597-4b46-bb54-f3bc755048bb", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Coconut Lime Filling", "items": [{"name": "full-fat cream cheese", "quantity": 450, "unit": "g", "preparation": "room temperature", "notes": "brick style, not tub", "substitutions": [], "ingredient_id": "262c67de-76a4-4444-8c02-30ad4a179459", "nutrition_source": "USDA FoodData Central"}, {"name": "powdered sugar", "quantity": 110, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "coconut cream", "quantity": 120, "unit": "ml", "preparation": "chilled", "notes": "thick solid part from top of can only", "substitutions": [], "ingredient_id": "af6f629b-fa13-4f67-8338-e06af8c943cc", "nutrition_source": "USDA FoodData Central"}, {"name": "lime zest", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 2 limes", "substitutions": [], "ingredient_id": "295e8d21-9ba3-4ab8-a118-b09b77defacc", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "toasted coconut flakes", "quantity": 30, "unit": "g", "preparation": null, "notes": "for garnish", "substitutions": [], "ingredient_id": "22ca2249-2951-4843-8ed0-fed51cf8338c", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the pineapple jam: Combine diced pineapple, brown sugar, lime juice (15ml), and salt in a small saucepan over medium heat. Cook, stirring occasionally, until the liquid evaporates and the pineapple turns golden and sticky. Remove from heat and cool completely.", "structured": {"action": "REDUCE", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT15M", "doneness_cues": {"visual": "Golden brown, no liquid pooling at bottom of pan", "tactile": "Sticky and jam-like"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Line a 20cm (8-inch) square pan with parchment paper, leaving an overhang on two sides for easy removal later.", "structured": {"action": "MEASURE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Make the crust: Pulse gingersnaps and ground ginger in a food processor until fine crumbs form. Add melted butter and pulse until the mixture resembles wet sand. Press firmly and evenly into the bottom of the prepared pan. Freeze for 10 minutes to set.", "structured": {"action": "CRUSH", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "In a stand mixer fitted with the paddle attachment, beat the room temperature cream cheese and powdered sugar on medium speed until completely smooth and free of lumps. Scrape down the bowl.", "structured": {"action": "BEAT", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the thick coconut cream (solids only), lime zest, and vanilla. Beat on medium-high until the mixture is thickened and airy. Do not overbeat to the point of separation.", "structured": {"action": "WHIP", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Thick, holds peaks", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Spread half of the cheesecake mixture over the chilled crust. Dollop half of the cooled pineapple jam randomly over the surface. Swirl gently with a knife. Repeat with the remaining cheesecake and pineapple.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Cover tightly and refrigerate for at least 8 hours (preferably overnight) to set. Before serving, lift the bars out using the parchment overhang, garnish with toasted coconut, and slice into 16 squares.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT8H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT8H", "total_time": "PT8H45M", "overnight_required": true, "yields": "16 bars", "yield_count": 16, "serving_size_g": 115}', '{"flags": ["Vegetarian", "Egg-Free", "Peanut-Free"], "not_suitable_for": ["Vegans (contains dairy)", "Coeliacs (contains gluten)"]}', '{"per_serving": {"calories": 286.08, "protein_g": 3.4, "carbohydrates_g": 27.13, "fat_g": 18.98, "saturated_fat_g": 11.22, "trans_fat_g": 0.33, "monounsaturated_fat_g": 4.77, "polyunsaturated_fat_g": 0.84, "fiber_g": 1.48, "sugar_g": 15.54, "sodium_mg": 201.69, "cholesterol_mg": 40.5, "potassium_mg": 144.74, "calcium_mg": 57.25, "iron_mg": 1.44, "magnesium_mg": 21.14, "phosphorus_mg": 68.61, "zinc_mg": 0.42, "vitamin_a_mcg": 125.68, "vitamin_c_mg": 9.45, "vitamin_d_mcg": null, "vitamin_e_mg": 0.53, "vitamin_k_mcg": 1.51, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": 0.07, "thiamin_mg": 0.06, "riboflavin_mg": 0.12, "niacin_mg": 0.71, "folate_mcg": 21.53, "water_g": 37.78, "alcohol_g": 0.11, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Keep tightly covered to prevent absorbing fridge odors.", "duration": "P4D"}, "freezer": {"notes": "Freeze individual bars wrapped in parchment and foil. Thaw in fridge for 2 hours.", "duration": "P1M"}, "reheating": null, "does_not_keep": false}', '[{"name": "20cm (8-inch) square baking pan", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Food processor or sealed bag/rolling pin", "required": true, "alternative": "Mortar and pestle"}, {"name": "Stand mixer or electric hand mixer", "required": true, "alternative": null}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Rubber spatula", "required": true, "alternative": null}]', '[{"symptom": "Cheesecake mixture is runny or won''t set", "likely_cause": "Used liquid coconut milk instead of the solid cream, or cream cheese was too warm/soft", "prevention": "Only use the solid white cream from a chilled can of full-fat coconut milk; ensure cream cheese is room temp but not melting", "fix": "Freeze the bars for 2-3 hours and serve as a frozen treat instead of refrigerated bars"}, {"symptom": "Pineapple mixture is watery and making the filling weep", "likely_cause": "Pineapple wasn''t cooked down enough to evaporate natural juices", "prevention": "Cook pineapple until the pan is almost dry and the fruit is sticky", "fix": "Cannot be fixed once assembled"}]', '["To get the thickest coconut cream, place a can of full-fat coconut milk in the fridge the night before. Open it carefully and scoop off only the hard white layer at the top.", "For the cleanest slices, wipe your knife with a warm, damp cloth between every single cut.", "If you cannot find gingersnaps, Biscoff cookies or graham crackers mixed with 1 tsp of ground ginger make excellent substitutes.", "Ensure the pineapple jam is completely cool (room temperature or colder) before adding to the cheese mixture, or it will melt the fat and ruin the structure.", "This recipe relies on the stiffness of full-fat brick cream cheese. Do not use ''spreadable'' or ''whipped'' tub varieties."]', '"This dessert bridges the gap between the mid-century American ''icebox cake'' tradition and tropical flavor profiles often found in Tiki culture. The use of gingersnap crust nods to the European speculoos tradition while providing a spicy counterpoint to the Caribbean-inspired lime and coconut pairing."', 286.08);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('5861cd0f-3d26-427b-bf1b-c77e69760bc8', 'Sicilian-Style Pasta with Sardines and Fennel', 'A pantry-friendly interpretation of the classic Pasta con le Sarde. This dish balances the rich umami of sardines and anchovies with the aromatic sweetness of fennel, raisins, and saffron, finished with crunchy toasted breadcrumbs for texture.', 'dinner', 'Italian', 'Intermediate', '["italian", "pasta", "anchovy", "canned sardine", "fennel", "dinner", "sicilian", "pescatarian"]', '[{"group_name": "Preparation", "items": [{"name": "raisins", "quantity": 40, "unit": "g", "preparation": "dried", "notes": "golden raisins preferred", "substitutions": [], "ingredient_id": "4e6af4a3-1bf3-47bd-9761-7bb6a77323dd", "nutrition_source": "USDA FoodData Central"}, {"name": "saffron threads", "quantity": 1, "unit": null, "preparation": null, "notes": "generous pinch", "substitutions": [], "ingredient_id": "7f9ec0c8-2db1-48ac-a2c9-9b1efce12cf3", "nutrition_source": "USDA FoodData Central"}, {"name": "hot water", "quantity": 60, "unit": "ml", "preparation": null, "notes": "for soaking", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Crunchy Topping (Muddica)", "items": [{"name": "panko or coarse breadcrumbs", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "92441189-214a-4a8a-9cfc-dd578fe0d179", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pasta & Sauce Base", "items": [{"name": "bucatini or spaghetti", "quantity": 400, "unit": "g", "preparation": "dry", "notes": null, "substitutions": [], "ingredient_id": "3994b041-8c11-4992-adf0-a373b17e1aee", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "fennel bulb", "quantity": 1, "unit": null, "preparation": "diced, fronds reserved", "notes": "approx 250g", "substitutions": [], "ingredient_id": "a42d03de-0a8a-4a75-8299-5cf01d43b425", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "anchovy fillets", "quantity": 4, "unit": null, "preparation": null, "notes": "oil-packed", "substitutions": [], "ingredient_id": "cfdad407-c486-4fcc-9e47-7dd4cb32277c", "nutrition_source": "USDA FoodData Central"}, {"name": "pine nuts", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "971298ad-a9d7-49f7-811b-46afedad18d4", "nutrition_source": "Aggregated Public Data"}, {"name": "canned sardines in olive oil", "quantity": 240, "unit": "g", "preparation": "drained", "notes": "2 standard tins", "substitutions": [], "ingredient_id": "0b42bade-d37f-492e-81eb-43773534a6a6", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the raisins and saffron threads in a small bowl. Pour the hot water over them and let them steep for at least 10 minutes to bloom the saffron and plump the fruit.", "structured": {"action": "SOAK", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large dry skillet over medium heat (175\u00b0C/350\u00b0F), combine the breadcrumbs and 15ml olive oil. Toast, stirring constantly, until golden brown. Remove immediately to a bowl to prevent burning.", "structured": {"action": "TOAST", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": {"visual": "Golden brown color", "tactile": "Crispy texture"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Bring a large pot of salted water to a boil. Add the pasta and cook for 2 minutes less than the package instructions (it will finish cooking in the sauce). Reserve 250ml of starchy pasta water before draining.", "structured": {"action": "BOIL", "temperature": null, "duration": null, "doneness_cues": {"visual": "Very al dente", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "While pasta cooks, wipe out the skillet and heat 60ml olive oil over medium heat (175\u00b0C/350\u00b0F). Add the diced fennel and onion. Saut\u00e9 for 8-10 minutes until soft and beginning to caramelize.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the anchovy fillets and pine nuts to the skillet. Stir and mash the anchovies into the oil until they dissolve completely.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Pour the raisin and saffron mixture (including the liquid) into the skillet. Add the drained sardines, breaking them up slightly into large chunks (do not mash them into a paste). Simmer for 1 minute.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Add the drained pasta and 100ml of the reserved pasta water to the skillet. Increase heat to high. Toss vigorously for 1-2 minutes until the liquid emulsifies into a glossy sauce that clings to the pasta. Add more pasta water if the pan looks dry.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from heat. Serve immediately topped with the toasted breadcrumbs and reserved fennel fronds.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT10M", "total_time": "PT40M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 425}', '{"flags": ["Pescatarian", "Dairy-Free", "Egg-Free", "Nut-Free"], "not_suitable_for": ["Shellfish allergy (check anchovy/sardine processing)"]}', '{"per_serving": {"calories": 622.99, "protein_g": 29.03, "carbohydrates_g": 56.85, "fat_g": 31.36, "saturated_fat_g": 4.38, "trans_fat_g": null, "monounsaturated_fat_g": 16.22, "polyunsaturated_fat_g": 5.55, "fiber_g": 6.16, "sugar_g": 4.96, "sodium_mg": 323.17, "cholesterol_mg": 85.2, "potassium_mg": 765.43, "calcium_mg": 310.82, "iron_mg": 4.54, "magnesium_mg": 95.7, "phosphorus_mg": 464.51, "zinc_mg": 2.17, "vitamin_a_mcg": 49.27, "vitamin_c_mg": 11.02, "vitamin_d_mcg": 2.88, "vitamin_e_mg": 4.31, "vitamin_k_mcg": 53.07, "vitamin_b6_mg": 0.28, "vitamin_b12_mcg": 5.41, "thiamin_mg": 0.51, "riboflavin_mg": 0.4, "niacin_mg": 6.37, "folate_mcg": 125.91, "water_g": 202.75, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Breadcrumbs will lose crunch; store topping separately if possible.", "duration": "P2D"}, "freezer": {"notes": "Not recommended; pasta texture degrades.", "duration": null}, "reheating": "Saut\u00e9 gently in a pan with a splash of water to re-emulsify the sauce.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": "Wok"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Small bowl", "required": true, "alternative": null}]', '[{"symptom": "The dish tastes dry or oily rather than saucy", "likely_cause": "The emulsion broke or not enough starchy water was used", "prevention": "Reserve plenty of pasta water and toss vigorously over high heat at the end", "fix": "Add a splash of hot water and toss rapidly to re-emulsify"}, {"symptom": "Sardines have disappeared into the sauce", "likely_cause": "Added too early or stirred too aggressively", "prevention": "Add sardines at the very last moment before the pasta", "fix": "Cannot be fixed, but flavor will still be good"}]', '["The ''muddica'' (toasted breadcrumbs) acts as the ''cheese'' in this dish. Traditional Sicilian seafood pasta rarely uses parmesan, as the dairy clashes with the fish oils.", "Do not rinse the sardines excessively; the oil they are packed in is flavorful. Just drain the excess.", "Bucatini is the ideal shape because the hole running through the center traps the flavorful saffron sauce, but spaghetti or linguine are acceptable substitutes.", "If you can find wild fennel fronds, use them in abundance; they have a more potent anise flavor than the cultivated bulb."]', '"Based on the iconic Sicilian dish ''Pasta con le Sarde'', this recipe reflects the island''s Arab-influenced history by combining savory seafood with sweet notes from raisins and saffron (agrodolce). It was traditionally a seasonal dish made during the sardine migration in spring."', 622.99);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('59cf99a0-e6d6-4315-a1af-3a418aef409d', 'Handmade Spaghetti al Pomodoro e Basilico', 'Silky, golden strands of handmade egg pasta tossed in a vibrant, sweet tomato sauce. The dish highlights the purity of ripe summer tomatoes and fragrant fresh basil, finished with a glossy olive oil emulsion.', 'dinner', 'Italian', 'Intermediate', '["pastas", "garlic", "spaghetti", "tomato", "dinner", "vegetarian", "italian", "fresh pasta"]', '[{"group_name": "Fresh Pasta Dough", "items": [{"name": "00 flour", "quantity": 400, "unit": "g", "preparation": "room temperature", "notes": "plus extra for dusting", "substitutions": ["all-purpose flour"], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "large eggs", "quantity": 4, "unit": null, "preparation": "room temperature", "notes": "approx 220g total weight", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "semolina flour", "quantity": null, "unit": null, "preparation": null, "notes": "for dusting finished pasta to prevent sticking", "substitutions": [], "ingredient_id": "276312e9-6353-4fa7-8538-bf43246ba74e", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Pomodoro Sauce & Finish", "items": [{"name": "ripe tomatoes", "quantity": 800, "unit": "g", "preparation": "fresh", "notes": "San Marzano or vine-ripened varieties preferred", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": "divided use", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "whole, smashed", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh basil leaves", "quantity": 20, "unit": "g", "preparation": "whole or hand-torn", "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}, {"name": "parmigiano-reggiano", "quantity": null, "unit": null, "preparation": null, "notes": "freshly grated, to taste", "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "On a clean work surface, mound the flour and create a deep well in the center. Crack the eggs into the well.", "structured": {"action": "MEASURE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Using a fork, gently whisk the eggs, slowly incorporating flour from the inner walls of the well until a shaggy dough forms. Use a bench scraper to fold in remaining flour.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Knead the dough vigorously by hand for 10 minutes until smooth, elastic, and slightly tacky but not sticky. Wrap tightly in plastic wrap and rest at room temperature for 30 minutes.", "structured": {"action": "KNEAD", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": ["If the dough is too dry, wet your hands and continue kneading. If too wet, dust with small amounts of flour."]}, {"step_number": 4, "phase": "prep", "text": "While dough rests, prepare the tomatoes. Roughly chop them into 2cm chunks. If a smoother sauce is desired, blanch and peel them first.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Heat 40ml of olive oil in a large saut\u00e9 pan over medium heat. Add the smashed garlic cloves and cook until golden and fragrant, then remove the garlic.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": null, "doneness_cues": {"visual": "Garlic is golden brown", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Add the chopped tomatoes and a pinch of salt to the pan. Simmer over medium-low heat for 15-20 minutes until the tomatoes break down into a sauce. Mash larger pieces with a spoon.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "prep", "text": "Cut the rested dough into 4 pieces. Flatten one piece (keep others covered) and roll it through a pasta machine on progressively thinner settings until about 1-2mm thick. Cut into spaghetti strands using the cutter attachment or by hand. Dust with semolina/flour.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Bring a large pot of salted water to a rolling boil. Add the fresh spaghetti and boil for 2-3 minutes until al dente (fresh pasta cooks much faster than dried).", "structured": {"action": "BOIL", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": null, "tactile": "Tender with a slight bite"}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Transfer the pasta directly into the tomato sauce using tongs (carrying over some pasta water). Add half the basil. Toss vigorously over medium heat for 1 minute to emulsify the sauce.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Remove from heat. Drizzle with the remaining 20ml olive oil and garnish with fresh basil leaves. Serve immediately.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT50M", "passive_time": "PT30M", "total_time": "PT1H20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 643.49, "protein_g": 21.1, "carbohydrates_g": 88.16, "fat_g": 22.63, "saturated_fat_g": 4.56, "trans_fat_g": 0.02, "monounsaturated_fat_g": 13.34, "polyunsaturated_fat_g": 3.09, "fiber_g": 6.58, "sugar_g": 8.36, "sodium_mg": 329.52, "cholesterol_mg": 207.15, "potassium_mg": 695.91, "calcium_mg": 125.96, "iron_mg": 3.05, "magnesium_mg": 57.8, "phosphorus_mg": 303.54, "zinc_mg": 1.97, "vitamin_a_mcg": 108.96, "vitamin_c_mg": 29.47, "vitamin_d_mcg": 1.12, "vitamin_e_mg": 2.85, "vitamin_k_mcg": 30.38, "vitamin_b6_mg": 0.19, "vitamin_b12_mcg": 0.54, "thiamin_mg": 0.16, "riboflavin_mg": 0.32, "niacin_mg": 1.37, "folate_mcg": 55.63, "water_g": 61.74, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten fresh. If storing, store sauce and pasta separately if possible, or toss with extra oil to prevent clumping.", "duration": "P2D"}, "freezer": {"notes": "Uncooked pasta nests can be frozen on a tray then bagged. Cook frozen (do not thaw).", "duration": "P1M"}, "reheating": "Gently reheat in a pan with a splash of water to loosen the sauce.", "does_not_keep": false}', '[{"name": "Large wooden board or clean countertop", "required": true, "alternative": "Large mixing bowl"}, {"name": "Pasta machine", "required": false, "alternative": "Rolling pin and knife"}, {"name": "Large stockpot", "required": true, "alternative": null}, {"name": "Large saut\u00e9 pan or skillet", "required": true, "alternative": null}, {"name": "Bench scraper", "required": false, "alternative": null}]', '[{"symptom": "Pasta strands clump together while cooking", "likely_cause": "Insufficient flouring after cutting or pot was not at a rolling boil", "prevention": "Dust cut pasta generously with semolina and ensure water is boiling violently before adding pasta", "fix": "Try to gently separate with a fork in the water; toss with oil immediately after draining"}, {"symptom": "Dough is too tough to roll", "likely_cause": "Insufficient resting time allowing gluten to relax", "prevention": "Rest dough for at least 30 minutes wrapped air-tight", "fix": "Re-wrap and let rest for another 15-20 minutes"}]', '["The hydration of the dough depends on humidity and egg size. Trust your hands: the dough should feel like a firm stress ball\u2014not sticky, but pliable.", "Do not rinse the pasta. The starch on the surface is crucial for binding the tomato sauce to the noodles.", "For the most aromatic result, tear the basil by hand rather than chopping it with a knife to prevent bruising and oxidation.", "Mantecare (the final tossing step) is the secret to restaurant-quality pasta; the agitation mixes starch water and oil into a creamy emulsion."]', '"Spaghetti al Pomodoro is the emblem of Italian culinary philosophy: exceptional ingredients prepared simply. While its roots are in Naples where tomatoes first thrived in Italian soil, this specific iteration highlights the artisanal tradition of ''pasta fatta in casa'' (homemade pasta), turning a quick weeknight meal into a celebration of craft."', 643.49);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('59e1e014-9f60-4c4b-8747-7893b34d1b8b', 'Rustic Vegetable Beef Soup', 'A deeply comforting, hearty soup featuring melt-in-your-mouth beef chunks and tender russet potatoes in a robust tomato-beef broth. Packed with sweet corn, garden peas, and green beans, this one-pot meal balances savory depth with vegetable sweetness.', 'soup', 'American', 'Easy', '["beef stew meat", "canned tomato", "carrot", "corn", "freezer friendly", "great leftovers", "green bean", "pea", "russet potato", "soup", "stovetop", "dinner", "main course", "fall", "winter", "dairy-free", "gluten-free"]', '[{"group_name": "Beef & Aromatics", "items": [{"name": "beef stew meat (chuck roast)", "quantity": 700, "unit": "g", "preparation": "cut into 2cm cubes", "notes": "trim excess hard fat", "substitutions": [], "ingredient_id": "aebf4219-b6a4-45b0-bd82-11203774257f", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": "divided", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx. 200g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "celery stalks", "quantity": 2, "unit": null, "preparation": "diced", "notes": "approx. 100g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx. 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Broth Base", "items": [{"name": "beef broth", "quantity": 1500, "unit": "ml", "preparation": null, "notes": "ensure gluten-free certified if required", "substitutions": [], "ingredient_id": "4058eb05-f1ce-43a7-81d8-f73141c89b46", "nutrition_source": "USDA FoodData Central"}, {"name": "canned diced tomatoes", "quantity": 400, "unit": "g", "preparation": "undrained", "notes": null, "substitutions": [], "ingredient_id": "0ba01b79-628f-4d68-be62-dab1fbbd087c", "nutrition_source": "Aggregated Public Data"}, {"name": "gluten-free worcestershire sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e3b693e4-5eb2-4dfd-988f-cbca12ac6cb7", "nutrition_source": "USDA FoodData Central"}, {"name": "dried thyme", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "3b938244-d506-46b2-9027-21bed955bcc5", "nutrition_source": "USDA FoodData Central"}, {"name": "bay leaf", "quantity": 1, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eab2ef3a-7a0e-4188-b746-645b795ada1e", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables", "items": [{"name": "russet potatoes", "quantity": 500, "unit": "g", "preparation": "peeled and cut into 2cm cubes", "notes": null, "substitutions": [], "ingredient_id": "a7db25be-476c-48fe-8cb8-2ea66fb91587", "nutrition_source": "USDA FoodData Central"}, {"name": "carrots", "quantity": 3, "unit": null, "preparation": "sliced into rounds", "notes": "approx. 200g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "frozen green beans", "quantity": 150, "unit": "g", "preparation": "cut into 2cm lengths", "notes": null, "substitutions": [], "ingredient_id": "ea789b38-e002-476a-b47e-8cf806dd4f7c", "nutrition_source": "USDA FoodData Central"}, {"name": "frozen corn kernels", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5307852d-0f25-4efa-bd06-4cbce70383a2", "nutrition_source": "USDA FoodData Central"}, {"name": "frozen peas", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fa661e9d-c4df-42f0-99c8-ca41610251a9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Seasoning", "items": [{"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, start with 5g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": "for garnish", "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the beef cubes dry with paper towels and season generously with salt and pepper. This ensures a proper sear rather than steaming.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat half the olive oil in the Dutch oven over medium-high heat. Sear the beef in batches until deeply browned on all sides, about 3-5 minutes per batch. Remove beef to a plate.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT10M", "doneness_cues": {"visual": "Deep brown crust developed", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Lower heat to medium. Add remaining oil, onions, carrots, and celery. Saut\u00e9 for 5-7 minutes until onions are translucent and fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT7M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add minced garlic and dried thyme. Stir constantly for 1 minute until aromatic, being careful not to burn the garlic.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour in a splash of the beef broth to deglaze the pot, scraping up the browned bits (fond) from the bottom. Add the remaining broth, diced tomatoes (with juices), Worcestershire sauce, bay leaf, and the browned beef with its resting juices.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Bring to a boil, then reduce heat to low. Cover and simmer gently for 45-60 minutes, or until the beef is beginning to get tender but still offers some resistance.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Add the cubed potatoes. Continue to simmer, covered, for another 15-20 minutes until potatoes are fork-tender.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT20M", "doneness_cues": {"visual": null, "tactile": "Potatoes pierce easily with a fork"}}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Stir in the frozen green beans, corn, and peas. Simmer for 5 minutes until vegetables are heated through and bright.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove the bay leaf. Taste and adjust seasoning with additional salt and pepper if needed. Garnish with fresh parsley before serving.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT1H30M", "total_time": "PT2H", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 450}', '{"flags": ["Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 434.24, "protein_g": 30.9, "carbohydrates_g": 36.84, "fat_g": 19.74, "saturated_fat_g": 6.99, "trans_fat_g": 0.81, "monounsaturated_fat_g": 10.78, "polyunsaturated_fat_g": 1.43, "fiber_g": 6.28, "sugar_g": 8.11, "sodium_mg": 1447.96, "cholesterol_mg": 80.5, "potassium_mg": 1267.87, "calcium_mg": 114.95, "iron_mg": 5.89, "magnesium_mg": 77.86, "phosphorus_mg": 376.48, "zinc_mg": 9.67, "vitamin_a_mcg": 326.38, "vitamin_c_mg": 22.65, "vitamin_d_mcg": 0.12, "vitamin_e_mg": 1.44, "vitamin_k_mcg": 87.22, "vitamin_b6_mg": 0.96, "vitamin_b12_mcg": 3.36, "thiamin_mg": 0.3, "riboflavin_mg": 0.36, "niacin_mg": 9.23, "folate_mcg": 68.1, "water_g": 524.28, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves the next day as ingredients meld.", "duration": "P4D"}, "freezer": {"notes": "Russet potatoes may soften slightly upon thawing but remain palatable.", "duration": "P3M"}, "reheating": "Reheat gently on the stovetop over medium heat until steaming.", "does_not_keep": false}', '[{"name": "Dutch oven or large heavy-bottomed pot", "required": true, "alternative": "Large stockpot"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Wooden spoon or spatula", "required": true, "alternative": null}]', '[{"symptom": "Beef is tough or chewy", "likely_cause": "Not cooked long enough to break down connective tissue", "prevention": "Test a piece of beef before adding vegetables; extend initial simmer time if needed", "fix": "Add a splash more broth and continue simmering on low heat until tender (vegetables may soften further)"}, {"symptom": "Soup lacks depth of flavor", "likely_cause": "Insufficient browning of meat or lack of salt", "prevention": "Ensure deep browning during step 2 and fully deglaze the pot", "fix": "Add a teaspoon of vinegar or lemon juice to brighten, or a pinch more salt"}]', '["Patting the beef dry is crucial. Wet meat steams instead of searing, causing you to lose the Maillard reaction flavor base.", "Russet potatoes are starchy and will naturally thicken the soup slightly as they cook. If you prefer firm potato chunks that hold shape perfectly, swap for Yukon Golds.", "Cut all vegetables to roughly the same size as the beef cubes (or slightly smaller) to ensure every spoonful has a balanced mix of ingredients.", "For an extra layer of umami without gluten, ensure your Worcestershire sauce is specifically labeled gluten-free, or substitute with gluten-free tamari."]', '"This style of vegetable beef soup is a staple of North American home cooking, often associated with frugal utilization of pantry staples and garden vegetables. It evolved from European pot-au-feu and stew traditions but adapted to include New World ingredients like corn and tomatoes."', 434.24);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('5a5d2b5a-bc78-4e62-ae83-4c4d2a7bd68b', 'Classic Roast Dinner Pot Pie', 'The ultimate comfort food transformation: tender chunks of leftover roast meat and vegetables enrobed in a rich, savory gravy and capped with a flaky, buttery homemade pastry crust. Golden, bubbling, and deeply satisfying.', 'dinner', 'British', 'Intermediate', '["pie", "leftovers", "main course", "pastry", "british", "comfort food"]', '[{"group_name": "Flaky Pastry", "items": [{"name": "all-purpose flour", "quantity": 250, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 125, "unit": "g", "preparation": "cold, cubed", "notes": "Keep as cold as possible", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "fine sea salt", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "ice water", "quantity": 80, "unit": "ml", "preparation": null, "notes": "approximate, add gradually", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Filling Base", "items": [{"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "for saut\u00e9ing", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "onion", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 30, "unit": "g", "preparation": "for roux", "notes": "omit if using leftover thick gravy", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Leftovers & Liquids", "items": [{"name": "cooked meat", "quantity": 400, "unit": "g", "preparation": "cubed or shredded", "notes": "chicken, beef, lamb, or pork", "substitutions": [], "ingredient_id": "9368fce5-d330-4f6a-8b85-285b39dcbf8e", "nutrition_source": "Aggregated Public Data"}, {"name": "cooked vegetables", "quantity": 300, "unit": "g", "preparation": "chopped", "notes": "potatoes, carrots, parsnips, peas", "substitutions": [], "ingredient_id": "3e055dc3-b6c5-4bf6-94ea-87d55f97dc6d", "nutrition_source": "USDA FoodData Central"}, {"name": "stock or leftover gravy", "quantity": 400, "unit": "ml", "preparation": null, "notes": "chicken or beef stock depending on meat", "substitutions": [], "ingredient_id": "78019ad1-1007-4609-adfd-386901ea9ccd", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Assembly", "items": [{"name": "egg", "quantity": 1, "unit": null, "preparation": "beaten", "notes": "for wash", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place flour and salt in a mixing bowl. Add cold cubed butter and rub into the flour with fingertips until the mixture resembles coarse breadcrumbs with some pea-sized chunks of butter remaining.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Add ice water one tablespoon at a time, mixing gently with a knife or hand until the dough just comes together. Do not overwork. Wrap in plastic and chill for at least 30 minutes.", "structured": {"action": "REST", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Melt 30g butter in a skillet over medium heat. Saut\u00e9 the diced onion until softened but not browned, about 5 minutes. Add garlic and cook for 1 minute.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT6M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Sprinkle the 30g of flour over the onions and stir constantly for 2 minutes to cook out the raw taste. Gradually whisk in the stock (or gravy) until smooth and thickened.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Sauce coats the back of a spoon", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Fold the leftover meat, vegetables, and parsley into the sauce. Season with salt and pepper. Pour mixture into the pie dish and let it cool slightly (warm filling will melt the pastry before baking).", "structured": {"action": "COOL", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": ["If the filling is too thick, add a splash of water. If too thin, simmer longer."]}, {"step_number": 6, "phase": "assemble", "text": "Preheat oven to 200\u00b0C/400\u00b0F. Roll out the chilled pastry on a floured surface to 3-4mm thickness, slightly larger than your pie dish.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Place the pastry over the pie dish. Trim excess, crimp the edges to seal against the rim. Cut two slits in the center for steam to escape. Brush the top with beaten egg.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Bake for 30-35 minutes until the pastry is puffed and deep golden brown, and the filling is bubbling. Ensure internal temperature reaches 74\u00b0C/165\u00b0F.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT35M", "doneness_cues": {"visual": "Pastry is deep golden brown", "tactile": "Filling is bubbling hot"}}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT1H15M", "total_time": "PT2H", "overnight_required": false, "yields": "1 large pie (6 servings)", "yield_count": 6, "serving_size_g": 350}', '{"flags": ["Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 669.13, "protein_g": 17.28, "carbohydrates_g": 61.25, "fat_g": 39.63, "saturated_fat_g": 13.62, "trans_fat_g": null, "monounsaturated_fat_g": 7.12, "polyunsaturated_fat_g": 1.82, "fiber_g": 5.23, "sugar_g": 3.35, "sodium_mg": 776.82, "cholesterol_mg": 80.34, "potassium_mg": 489.68, "calcium_mg": 71.38, "iron_mg": 7.43, "magnesium_mg": 55.6, "phosphorus_mg": 322.79, "zinc_mg": 4.95, "vitamin_a_mcg": 301.38, "vitamin_c_mg": 5.93, "vitamin_d_mcg": 0.13, "vitamin_e_mg": 0.91, "vitamin_k_mcg": 41.17, "vitamin_b6_mg": 0.12, "vitamin_b12_mcg": 0.1, "thiamin_mg": 0.13, "riboflavin_mg": 0.17, "niacin_mg": 1.53, "folate_mcg": 40.85, "water_g": 153.31, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Ensure leftovers are cooled quickly after the initial meal and this second cooking.", "duration": "P3D"}, "freezer": {"notes": "Can be frozen unbaked or baked. Thaw in fridge overnight before reheating.", "duration": "P3M"}, "reheating": "Reheat in a 180\u00b0C/350\u00b0F oven for 20-30 minutes until hot through to the center. Microwave not recommended for pastry.", "does_not_keep": false}', '[{"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Pie dish (23cm/9inch)", "required": true, "alternative": null}, {"name": "Rolling pin", "required": true, "alternative": null}, {"name": "Pastry brush", "required": true, "alternative": null}, {"name": "Large skillet or frying pan", "required": true, "alternative": null}, {"name": "Plastic wrap", "required": true, "alternative": null}]', '[{"symptom": "Pastry is soggy on the bottom/underside", "likely_cause": "Filling was too hot when the pastry was placed on top, melting the butter instantly.", "prevention": "Ensure the filling is cooled to room temperature before topping with pastry.", "fix": "Cannot be fixed once baked; scoop off the top crust and eat it with the filling."}, {"symptom": "Pastry shrinks away from the edges", "likely_cause": "Dough was overworked or not rested enough.", "prevention": "Handle dough minimally and rest in fridge for full 30 mins to relax gluten.", "fix": "Cannot be fixed"}]', '["Temperature Contrast: Keep your pastry ingredients (especially butter and water) ice cold, but ensure your oven is fully preheated and hot. This shock creates the flaky layers.", "Flavor Revival: Leftovers can taste dull. Always add fresh aromatics like saut\u00e9ed onions, fresh herbs (parsley/thyme), or a splash of Worcestershire sauce to the filling to wake up the flavors.", "Sauce consistency: The filling should be looser than you think before baking; the pastry absorbs some moisture and the starch will thicken it further as it cools.", "Vegetable sizing: Cut any large leftover roast potatoes or chunks of meat into bite-sized pieces so the pie eats well."]', '"The ''Monday Pie'' is a stalwart of British home cooking, traditionally created to ensure nothing from the Sunday Roast went to waste. It represents the thrifty, hearty nature of farmhouse cookery, transforming ''bits and bobs'' into a centerpiece meal."', 669.13);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('5a7f0bef-2593-42cd-bbc5-f82d9b6a5815', 'Soy-Mustard Pork Tenderloin with Shiitake Pan Sauce', 'A robust savory dinner featuring tender pork medallions seared to perfection, finished with an earthy, umami-rich sauce of fresh shiitake mushrooms, sake, and mirin. This dairy-free pan sauce balances the tang of mustard with the sweetness of mirin.', 'dinner', 'Japanese Fusion', 'Intermediate', '["meat", "mirin", "pork tenderloin", "sake", "shiitake", "dinner", "main course", "fall", "dairy-free"]', '[{"group_name": "Pork & Marinade", "items": [{"name": "pork tenderloin", "quantity": 500, "unit": "g", "preparation": "trimmed of silverskin", "notes": "Whole loin or large medallions", "substitutions": [], "ingredient_id": "1f451df4-63db-4326-97e6-9e8a9aef9a64", "nutrition_source": "USDA FoodData Central"}, {"name": "soy sauce", "quantity": 30, "unit": "ml", "preparation": "liquid", "notes": null, "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "dijon mustard", "quantity": 15, "unit": "g", "preparation": "smooth", "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable oil", "quantity": 15, "unit": "ml", "preparation": "liquid", "notes": "for searing", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Shiitake Sauce", "items": [{"name": "fresh shiitake mushrooms", "quantity": 150, "unit": "g", "preparation": "sliced", "notes": "stems removed", "substitutions": [], "ingredient_id": "127ce8a8-238d-40e6-a4b0-c58c42a7c745", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx. 30g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx. 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "sake", "quantity": 60, "unit": "ml", "preparation": "dry", "notes": null, "substitutions": [], "ingredient_id": "1cfffbd2-7ea5-4cbc-bc35-c57e12233152", "nutrition_source": "USDA FoodData Central"}, {"name": "mirin", "quantity": 30, "unit": "ml", "preparation": "sweet rice wine", "notes": null, "substitutions": [], "ingredient_id": "2a72c18d-8a1d-4259-8790-25d62f6fb5ba", "nutrition_source": "Aggregated Public Data"}, {"name": "chicken stock", "quantity": 120, "unit": "ml", "preparation": "unsalted", "notes": null, "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}, {"name": "scallion", "quantity": 1, "unit": null, "preparation": "thinly sliced", "notes": "green parts only, for garnish", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Whisk together the soy sauce, Dijon mustard, and black pepper in a small bowl. Rub this mixture over the pork tenderloin. Let it sit at room temperature for at least 15 minutes to marinate.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat the vegetable oil in a heavy-bottomed skillet over medium-high heat. Once the oil shimmers, add the pork tenderloin. Sear undisturbed for 3-4 minutes until a deep brown crust forms.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Rotate the pork and continue searing all sides until browned and the internal temperature reaches 63\u00b0C/145\u00b0F at the thickest part. If the pork is browning too fast before cooking through, lower the heat and cover the pan for a few minutes.", "structured": {"action": "COOK", "temperature": {"celsius": 63, "fahrenheit": 145}, "duration": null, "doneness_cues": {"visual": "Golden brown crust", "tactile": "Internal temp 63C"}}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Transfer the pork to a cutting board and tent loosely with foil to rest. Do not clean the skillet.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "In the same skillet over medium heat, add the sliced shiitake mushrooms. Saut\u00e9 for 4-5 minutes until golden and tender. Add the minced shallot and garlic, cooking for another minute until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Pour in the sake to deglaze the pan, scraping up any browned bits (fond) from the bottom with a wooden spoon or tongs. Let the liquid bubble for 1 minute to cook off the harsh alcohol.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Stir in the mirin and chicken stock. Increase heat to bring to a boil, then reduce to a simmer. Cook for 3-5 minutes until the sauce reduces by half and slightly thickens.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Sauce coats the back of a spoon", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Slice the rested pork into 2cm thick medallions. Arrange on plates and spoon the mushroom sauce generously over the meat. Garnish with sliced scallions.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT15M", "total_time": "PT40M", "overnight_required": false, "yields": "3 servings", "yield_count": 3, "serving_size_g": 225}', '{"flags": ["Dairy-Free", "Nut-Free", "Egg-Free"], "not_suitable_for": ["Gluten intolerance (unless tamari is used)"]}', '{"per_serving": {"calories": 327.74, "protein_g": 31.55, "carbohydrates_g": 17.9, "fat_g": 12.64, "saturated_fat_g": 2.67, "trans_fat_g": null, "monounsaturated_fat_g": 2.42, "polyunsaturated_fat_g": 1.77, "fiber_g": 2.06, "sugar_g": 8.81, "sodium_mg": 4234.07, "cholesterol_mg": 78.33, "potassium_mg": 1197.75, "calcium_mg": 42.96, "iron_mg": 2.46, "magnesium_mg": 50.44, "phosphorus_mg": 68.24, "zinc_mg": 2.93, "vitamin_a_mcg": 1.43, "vitamin_c_mg": 4.23, "vitamin_d_mcg": 0.2, "vitamin_e_mg": 0.02, "vitamin_k_mcg": 6.38, "vitamin_b6_mg": 0.2, "vitamin_b12_mcg": null, "thiamin_mg": 0.02, "riboflavin_mg": 0.12, "niacin_mg": 1.99, "folate_mcg": 11.67, "water_g": 196.01, "alcohol_g": 3.22, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store pork and sauce in an airtight container. Reheat gently to avoid drying out the meat.", "duration": "P3D"}, "freezer": {"notes": "Texture of mushrooms may change slightly upon thawing.", "duration": "P2M"}, "reheating": "Reheat in a skillet over low heat with a splash of water, or microwave at 50% power.", "does_not_keep": false}', '[{"name": "Heavy-bottomed skillet", "required": true, "alternative": "Stainless steel frying pan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Meat thermometer", "required": true, "alternative": null}]', '[{"symptom": "Pork is dry and tough", "likely_cause": "Overcooking; pork tenderloin is very lean and dries out instantly past 63\u00b0C (145\u00b0F)", "prevention": "Use a meat thermometer and pull the meat exactly when it hits 63\u00b0C (145\u00b0F) or even 60\u00b0C (140\u00b0F) as it will carry-over cook while resting.", "fix": "Slice very thinly against the grain and toss directly in the sauce to rehydrate slightly."}, {"symptom": "Sauce is too thin", "likely_cause": "Did not reduce long enough or stock was too watery", "prevention": "Allow vigorous boiling during the reduction phase.", "fix": "Mix 1 tsp cornstarch with 1 tsp cold water and stir into the simmering sauce to thicken instantly."}]', '["Always clean mushrooms with a damp cloth or paper towel rather than washing them under running water, which makes them soggy and prevents browning.", "Removing the ''silverskin'' (the tough white connective tissue) from the tenderloin is crucial. If left on, it shrinks during cooking and warps the meat, making it chewy.", "If you do not have sake, a dry sherry or Chinese Shaoxing wine makes a suitable substitute, though the flavor profile will shift slightly.", "For an even better crust, ensure the pork is patted very dry before applying the marinade, and shake off excess liquid before placing it in the hot pan."]', '"This dish represents modern Japanese Y\u014dshoku (Western-influenced) cooking styles, where traditional ingredients like sake, mirin, and soy sauce are applied to Western techniques like pan-roasting and deglazing. The use of Dijon mustard bridges the gap between European roast pork traditions and Asian flavor profiles."', 327.74);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('5acd3e59-8919-42d8-b053-15f371b8e824', 'Peruvian Halibut & Shrimp Chupe', 'A vibrant, hearty, and creamy Andean-style chowder (Chupe) featuring firm halibut and sweet shrimp. The rich fish stock is infused with sun-ripened aji amarillo peppers, simmered with potatoes and corn, and finished with a touch of milk for a velvety texture.', 'soup', 'Peruvian', 'Intermediate', '["latin american", "one pot", "corn", "fish", "halibut", "soup", "dinner", "lunch", "appetizer", "summer", "gluten-free"]', '[{"group_name": "Aromatics & Base", "items": [{"name": "vegetable oil", "quantity": 30, "unit": "ml", "preparation": "neutral", "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "red onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 4, "unit": null, "preparation": "minced", "notes": "approx 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "aji amarillo paste", "quantity": 60, "unit": "g", "preparation": null, "notes": "Peruvian yellow chili paste; adjust to heat preference", "substitutions": [], "ingredient_id": "ea894e36-e10f-4097-a6f2-7ececf6bf89d", "nutrition_source": "Aggregated Public Data"}, {"name": "dried oregano", "quantity": 2, "unit": "g", "preparation": "rubbed", "notes": null, "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "tomato paste", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "1a1bddc5-66c3-4f44-bb24-72b8ac828ca6", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Broth & Vegetables", "items": [{"name": "fish stock", "quantity": 1000, "unit": "ml", "preparation": "rich, homemade or high-quality", "notes": null, "substitutions": [], "ingredient_id": "3912e04d-71a3-4a31-b033-cc5c5aa4452d", "nutrition_source": "Aggregated Public Data"}, {"name": "yukon gold potatoes", "quantity": 400, "unit": "g", "preparation": "peeled and cut into 2cm cubes", "notes": null, "substitutions": [], "ingredient_id": "a9d640ff-a969-4f0a-9a92-974f376ac272", "nutrition_source": "Aggregated Public Data"}, {"name": "corn kernels", "quantity": 200, "unit": "g", "preparation": "fresh or frozen", "notes": null, "substitutions": [], "ingredient_id": "46ca2aab-cb23-4397-9711-528c234b2cf8", "nutrition_source": "USDA FoodData Central"}, {"name": "zucchini", "quantity": 200, "unit": "g", "preparation": "diced into 2cm half-moons", "notes": null, "substitutions": [], "ingredient_id": "c34b610f-8869-4d77-a9b3-e01849d703b5", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 8, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Proteins & Finish", "items": [{"name": "halibut fillets", "quantity": 400, "unit": "g", "preparation": "skin removed, cut into 4cm chunks", "notes": null, "substitutions": [], "ingredient_id": "827bb16e-2155-49d8-a5df-0c0620559d27", "nutrition_source": "USDA FoodData Central"}, {"name": "raw shrimp", "quantity": 250, "unit": "g", "preparation": "peeled and deveined", "notes": null, "substitutions": [], "ingredient_id": "a6bf7ab3-9b88-4c5b-a2fa-966c40a0e5a7", "nutrition_source": "USDA FoodData Central"}, {"name": "evaporated milk", "quantity": 120, "unit": "ml", "preparation": null, "notes": "or heavy cream for richness", "substitutions": [], "ingredient_id": "684e9506-fd34-4087-bcbd-d3a263aa2ee5", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh cilantro", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "lime wedges", "quantity": 4, "unit": null, "preparation": null, "notes": "for serving", "substitutions": [], "ingredient_id": "d3d2677e-fe02-4404-add0-29d73df7e921", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Heat vegetable oil in a large Dutch oven over medium heat. Add the diced red onion and a pinch of salt. Saut\u00e9 until the onion is soft and translucent, about 5 minutes.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT5M", "doneness_cues": {"visual": "Onions are translucent but not browned", "tactile": "Soft texture"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add the minced garlic, aji amarillo paste, tomato paste, dried oregano, and cumin. Cook for another 3-4 minutes, stirring frequently, until the paste darkens slightly and the oil separates from the solids.", "structured": {"action": "FRY", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Oil splits and turns orange/red", "tactile": "Thickened paste"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Pour in the fish stock and bring to a gentle boil. Add the potato cubes. Lower the heat and simmer for 10 minutes until potatoes are halfway cooked.", "structured": {"action": "SIMMER", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the corn kernels and diced zucchini to the pot. Continue simmering for 5-7 minutes until the vegetables are tender.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": null, "tactile": "Potatoes pierce easily with a fork"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Gently place the halibut chunks into the broth. Poach for 3 minutes without stirring vigorously to keep the fish intact.", "structured": {"action": "POACH", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Add the shrimp and the evaporated milk. Simmer gently for 2-3 minutes until the shrimp turn pink and opaque, and the fish flakes easily. The internal temperature of the fish should reach 63\u00b0C (145\u00b0F).", "structured": {"action": "SIMMER", "temperature": {"celsius": 63, "fahrenheit": 145}, "duration": "PT3M", "doneness_cues": {"visual": "Shrimp are pink, fish is opaque white", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from heat immediately. Stir in the fresh cilantro and serve hot with lime wedges on the side.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT20M", "total_time": "PT50M", "overnight_required": false, "yields": "4 generous bowls", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Pescatarian", "Gluten-Free"], "not_suitable_for": ["Shellfish allergy", "Dairy intolerance"]}', '{"per_serving": {"calories": 552.28, "protein_g": 51.21, "carbohydrates_g": 47.81, "fat_g": 19.6, "saturated_fat_g": 5.75, "trans_fat_g": null, "monounsaturated_fat_g": 1.52, "polyunsaturated_fat_g": 1.34, "fiber_g": 6.6, "sugar_g": 14.04, "sodium_mg": 1741.29, "cholesterol_mg": 172.63, "potassium_mg": 2345.56, "calcium_mg": 136.35, "iron_mg": 2.6, "magnesium_mg": 130.27, "phosphorus_mg": 561.3, "zinc_mg": 2.03, "vitamin_a_mcg": 143.17, "vitamin_c_mg": 51.89, "vitamin_d_mcg": null, "vitamin_e_mg": 2.14, "vitamin_k_mcg": 5.72, "vitamin_b6_mg": 0.61, "vitamin_b12_mcg": 1.78, "thiamin_mg": 0.2, "riboflavin_mg": 0.17, "niacin_mg": 7, "folate_mcg": 57.7, "water_g": 257.12, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Reheat gently; seafood texture degrades with reheating.", "duration": "P2D"}, "freezer": {"notes": "Not recommended; dairy can split and potatoes become grainy.", "duration": null}, "reheating": "Warm on low heat on the stove to 70\u00b0C/158\u00b0F. Do not boil.", "does_not_keep": false}', '[{"name": "Dutch oven or heavy-bottomed pot", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Ladle", "required": true, "alternative": null}]', '[{"symptom": "Fish has disintegrated into the soup", "likely_cause": "Soup was boiled too vigorously or stirred too much after adding fish", "prevention": "Keep heat at a bare simmer (poach) once protein is added and swirl pot instead of stirring", "fix": "Cannot be fixed, but flavor will still be excellent. Serve as a rustic chowder."}, {"symptom": "Soup looks curdled", "likely_cause": "Evaporated milk was added to boiling liquid or acid (lime) was added too early", "prevention": "Lower heat before adding milk; serve lime on the side", "fix": "Blend a small amount of boiled potato with broth and whisk back in to stabilize emulsion"}]', '["Aji Amarillo is the soul of this dish. If you cannot find the paste, you can blend hydrated dried yellow chilies, but do not substitute with standard hot sauce.", "For an even richer stock, simmer the shrimp shells in the fish stock for 20 minutes and strain before using.", "Cut the zucchini slightly larger than the potatoes as they cook faster; adding them with the corn prevents them from turning to mush.", "If you prefer a thicker stew, mash two or three cooked potato cubes against the side of the pot before adding the fish."]', '"This dish is inspired by the Peruvian ''Chupe'', a hearty chowder tradition from the Arequipa region. While Chupes often include eggs, cheese, and crayfish, this coastal variation highlights the delicacy of halibut while maintaining the signature creamy, spicy aji amarillo base."', 552.28);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('5b1c739a-45ae-433d-8f86-b05f884ad846', 'Sesame-Ginger Brown Rice & Wakame Salad', 'A vibrant, nourishing bowl featuring nutty short-grain brown rice and tender wakame seaweed tossed in a zesty ginger-sesame dressing. Crisp cucumbers and shelled edamame add fresh crunch, creating a perfect balance of earthy, oceanic, and savory flavors.', 'salad', 'Japanese', 'Easy', '["grains and rice", "brown rice", "salad", "seaweed", "easy", "vegan", "vegetarian", "healthy", "lunch"]', '[{"group_name": "Rice Base", "items": [{"name": "short-grain brown rice", "quantity": 200, "unit": "g", "preparation": "uncooked", "notes": "Short grain offers a better chew for salads than long grain", "substitutions": [], "ingredient_id": "c20a6cd5-c5d0-4f17-8381-0aa3fe526ce4", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 500, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables & Seaweed", "items": [{"name": "dried wakame seaweed", "quantity": 15, "unit": "g", "preparation": null, "notes": "Expands significantly when soaked", "substitutions": [], "ingredient_id": "f79d73ee-226d-4dcb-899c-bd67dde0b113", "nutrition_source": "Aggregated Public Data"}, {"name": "persian cucumbers", "quantity": 2, "unit": null, "preparation": "sliced into half-moons", "notes": "approx. 150g total", "substitutions": [], "ingredient_id": "457adec2-3e06-4efe-a26e-9e6ea9f84924", "nutrition_source": "USDA FoodData Central"}, {"name": "shelled edamame", "quantity": 150, "unit": "g", "preparation": "thawed if frozen", "notes": "cooked", "substitutions": [], "ingredient_id": "62308e3b-89d7-4c1b-8fb2-b191a6f47082", "nutrition_source": "Aggregated Public Data"}, {"name": "carrot", "quantity": 1, "unit": null, "preparation": "julienned or grated", "notes": "approx. 80g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "green onions", "quantity": 2, "unit": null, "preparation": "thinly sliced", "notes": "approx. 30g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Dressing", "items": [{"name": "soy sauce", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["tamari (for gluten-free)", "coconut aminos"], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "rice vinegar", "quantity": 30, "unit": "ml", "preparation": "unseasoned", "notes": null, "substitutions": [], "ingredient_id": "fcbf5252-1be9-4dd4-8c22-4fda1dbdca28", "nutrition_source": "Aggregated Public Data"}, {"name": "toasted sesame oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8fa9dd65-c49e-449c-b660-a9d9deb638b2", "nutrition_source": "Aggregated Public Data"}, {"name": "maple syrup", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c9ca1f35-b107-46c2-92a3-4c1c620f3c11", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 10, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "toasted sesame seeds", "quantity": 15, "unit": "g", "preparation": "for garnish", "notes": null, "substitutions": [], "ingredient_id": "05a632f9-d310-4dc1-aa03-2f2ac26f30c8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Rinse the brown rice thoroughly under cold water. Combine rice, water, and salt in a saucepan. Bring to a boil, then reduce heat to low, cover tightly, and simmer for 40-45 minutes until water is absorbed and rice is tender. Remove from heat and let sit covered for 10 minutes.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT55M", "doneness_cues": {"visual": "Water fully absorbed", "tactile": "Grains are tender with a slight chew"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "While rice cooks, place dried wakame in a small bowl and cover with cold water. Let it soak for 5-10 minutes until soft and expanded. Drain well and squeeze out excess water. Roughly chop if pieces are too large.", "structured": {"action": "SOAK", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Seaweed has expanded significantly and turned silky green", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Spread the cooked rice onto a baking sheet or large plate to cool it down to room temperature quickly. This prevents the salad from becoming gummy.", "structured": {"action": "COOL", "temperature": {"celsius": 22, "fahrenheit": 72}, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In a small bowl, whisk together soy sauce, rice vinegar, sesame oil, maple syrup, and grated ginger until emulsified.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "In a large mixing bowl, combine the cooled brown rice, rehydrated wakame, sliced cucumber, shelled edamame, carrots, and green onions.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Pour the dressing over the salad and toss gently to combine. Sprinkle with toasted sesame seeds before serving.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT50M", "total_time": "PT1H15M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 320}', '{"flags": ["Vegan", "Vegetarian", "Dairy-Free", "Egg-Free", "Peanut-Free", "Nut-Free"], "not_suitable_for": ["Sesame allergy sufferers"]}', '{"per_serving": {"calories": 337.61, "protein_g": 10.51, "carbohydrates_g": 55.38, "fat_g": 9.71, "saturated_fat_g": 1.46, "trans_fat_g": null, "monounsaturated_fat_g": 1.21, "polyunsaturated_fat_g": 1.32, "fiber_g": 5.48, "sugar_g": 6.61, "sodium_mg": 2280.1, "cholesterol_mg": null, "potassium_mg": 551.11, "calcium_mg": 39.84, "iron_mg": 1.42, "magnesium_mg": 94.12, "phosphorus_mg": 231.65, "zinc_mg": 2.08, "vitamin_a_mcg": 176.79, "vitamin_c_mg": 3.88, "vitamin_d_mcg": null, "vitamin_e_mg": 3.48, "vitamin_k_mcg": 27.57, "vitamin_b6_mg": 0.13, "vitamin_b12_mcg": null, "thiamin_mg": 0.11, "riboflavin_mg": 0.17, "niacin_mg": 4.41, "folate_mcg": 25.6, "water_g": 190.96, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves after resting for a few hours. Texture remains good.", "duration": "P3D"}, "freezer": {"notes": null, "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Medium saucepan with lid", "required": true, "alternative": "Rice cooker"}, {"name": "Fine-mesh sieve", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Small bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}]', '[{"symptom": "Salad tastes bland", "likely_cause": "Brown rice absorbs a lot of dressing, or rice was not salted during cooking", "prevention": "Always salt the cooking water for the rice", "fix": "Add a splash more soy sauce or a pinch of salt and toss again"}, {"symptom": "Rice texture is mushy", "likely_cause": "Rice was overcooked or mixed with dressing while still hot", "prevention": "Ensure rice is fully cooled to room temperature before tossing", "fix": "Spread rice out to dry slightly, or add crunchy toppings (seeds, nuts) to mask texture"}]', '["Short-grain brown rice is superior for salads because it remains plump and chewy, whereas long-grain can become dry and separate.", "Make sure to squeeze the water out of the wakame thoroughly; otherwise, it will dilute your dressing.", "This salad is excellent for meal prep as the flavors meld together over time, though the cucumber may lose some crunch after 2 days.", "For extra protein, add cubes of firm tofu or tempeh.", "If you cannot find dried wakame, you can use a high-quality seaweed salad mix, but reduce the dressing quantity as the mix is usually pre-seasoned."]', '"This dish draws inspiration from Japanese ''sunomono'' (vinegared dishes) and macrobiotic dietary principles, which emphasize whole grains like brown rice combined with sea vegetables for a balanced, restorative meal. While not a traditional Japanese classic, it represents modern Japanese-style healthy home cooking."', 337.61);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('5b1f7882-8820-415f-9127-abe2b3c83dd6', 'Baked Stuffed Mussels with Herb and Parmesan Gratin', 'Plump, saline mussels topped with a rich, textural crust of buttery breadcrumbs, nutty Parmesan, and aromatic garlic-parsley butter. The contrast between the tender shellfish and the golden, crispy topping makes for an elegant, savory bite.', 'appetizer', 'French', 'Intermediate', '["mussels", "seafood", "appetizer", "baked", "french", "dinner party", "pescatarian"]', '[{"group_name": "Mussels & Steaming Liquid", "items": [{"name": "fresh mussels", "quantity": 1000, "unit": "g", "preparation": "live", "notes": "de-bearded and scrubbed", "substitutions": [], "ingredient_id": "8724ea32-079e-407e-a9ae-1fe49557dc47", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 120, "unit": "ml", "preparation": null, "notes": "Sauvignon Blanc or Pinot Grigio", "substitutions": [], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "approx 25g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Herb & Cheese Gratin", "items": [{"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": "softened", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "panko breadcrumbs", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "92441189-214a-4a8a-9cfc-dd578fe0d179", "nutrition_source": "USDA FoodData Central"}, {"name": "parmesan cheese", "quantity": 30, "unit": "g", "preparation": "finely grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced to paste", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "flat-leaf parsley", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": null, "notes": "zest of 1 lemon, approx 3g", "substitutions": [], "ingredient_id": "a5fb6a2a-dcda-4ab2-8fe6-472d7fcc39d1", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Inspect the mussels. Discard any with broken shells or open shells that do not close when tapped. Remove the fibrous beard by pulling it firmly towards the hinge of the shell.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Use a stiff brush under cold running water to remove sand or barnacles."]}, {"step_number": 2, "phase": "cook", "text": "In a large pot over high heat, combine the white wine and minced shallot. Bring to a boil.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the mussels to the pot, cover tightly with a lid, and steam for 3-4 minutes, shaking the pot occasionally, until the shells just open. Do not overcook.", "structured": {"action": "STEAM", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Shells have opened wide", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Drain the mussels and let them cool slightly. Discard any mussels that remain closed. Twist off and discard the empty top half of each shell. Loosen the meat from the bottom shell but leave it resting inside.", "structured": {"action": "SHUCK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "In a mixing bowl, combine softened butter, breadcrumbs, grated Parmesan, minced garlic, parsley, lemon zest, salt, and pepper. Mash with a fork until well combined and crumbly.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Arrange the mussels on the half-shell on a baking sheet. Spoon roughly 1 teaspoon of the butter mixture onto each mussel, pressing gently to adhere.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Bake in a preheated oven at 220\u00b0C/425\u00b0F (or use the broiler/grill setting) for 4-5 minutes until the topping is golden brown and bubbling.", "structured": {"action": "BROIL", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT5M", "doneness_cues": {"visual": "Golden brown crust, bubbling butter", "tactile": null}}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT0M", "total_time": "PT35M", "overnight_required": false, "yields": "24-30 mussels", "yield_count": 4, "serving_size_g": 250}', '{"flags": ["Pescatarian", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Shellfish allergy", "Dairy allergy", "Gluten intolerance"]}', '{"per_serving": {"calories": 455.84, "protein_g": 34.6, "carbohydrates_g": 21.14, "fat_g": 20.35, "saturated_fat_g": 9.9, "trans_fat_g": null, "monounsaturated_fat_g": 5.49, "polyunsaturated_fat_g": 2.29, "fiber_g": 1.02, "sugar_g": 1.81, "sodium_mg": 1093.96, "cholesterol_mg": 107.35, "potassium_mg": 880.31, "calcium_mg": 190.69, "iron_mg": 10.83, "magnesium_mg": 97.46, "phosphorus_mg": 576.76, "zinc_mg": 4.48, "vitamin_a_mcg": 248.74, "vitamin_c_mg": 25.26, "vitamin_d_mcg": 0.04, "vitamin_e_mg": 1.78, "vitamin_k_mcg": 43.74, "vitamin_b6_mg": 0.19, "vitamin_b12_mcg": 30.16, "thiamin_mg": 0.54, "riboflavin_mg": 0.61, "niacin_mg": 4.92, "folate_mcg": 125.46, "water_g": 215.7, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best consumed immediately. Texture of crumb topping degrades rapidly in storage.", "duration": "P1D"}, "freezer": {"notes": "Do not freeze after cooking.", "duration": null}, "reheating": "Reheat under a broiler for 2-3 minutes to crisp the topping, though fresh is significantly superior.", "does_not_keep": true}', '[{"name": "Large pot with lid", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Stiff brush", "required": true, "alternative": "Clean scouring pad"}]', '[{"symptom": "Mussels are rubbery", "likely_cause": "Overcooked during the initial steaming or baked too long", "prevention": "Remove mussels from the steam exactly when they open; they will cook further in the oven.", "fix": "Cannot be fixed"}, {"symptom": "Gritty texture when eating", "likely_cause": "Sand left inside the mussel or beard not fully removed", "prevention": "Scrub shells thoroughly and purge in cold salted water for 20 minutes before cooking if they are wild-harvested.", "fix": "Cannot be fixed"}]', '["Select mussels that feel heavy for their size; light mussels may be dead or dehydrated.", "The breadcrumb mixture can be made a day in advance and stored in the fridge to save time.", "If using a broiler, watch the tray constantly as the transition from golden to burnt happens in seconds.", "Save the steaming liquid! Strain it through cheesecloth to remove grit and use it as a base for a seafood chowder or pasta sauce."]', '"Baked mussels, often known as ''Moules Farcies'' in France, are a bistro staple that transforms the humble, inexpensive mussel into a luxurious appetizer. This preparation method dates back to classic Proven\u00e7al cooking, where garlic, herbs, and breadcrumbs are used to extend and enhance fresh seafood catches."', 455.84);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('5b5baaf8-159e-4e1d-bc0e-cad1fc618f63', 'Hand-Torn Rustic Sourdough Croutons', 'Aggressively crunchy, golden-brown nuggets of sourdough with jagged, hand-torn edges that trap pockets of herb-infused olive oil. These croutons offer a superior textural experience—shattering crispness on the exterior with a savory, airy interior—far surpassing uniform machine-cut cubes.', 'condiment', 'Mediterranean', 'Easy', '["sourdough", "country bread", "salad topper", "zero waste", "vegan", "rustic"]', '[{"group_name": "Bread Base", "items": [{"name": "sourdough bread", "quantity": 350, "unit": "g", "preparation": "stale or day-old", "notes": "Approximately half a large round loaf; country loaf also works excellently", "substitutions": [], "ingredient_id": "190c3a6a-9abe-4ebc-af2c-cae4bbc8912c", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Seasoning Oil", "items": [{"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": "liquid", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic powder", "quantity": 3, "unit": "g", "preparation": null, "notes": "Using powder prevents burning at high heat", "substitutions": [], "ingredient_id": "177a312f-ef99-4398-9108-98f7a608a245", "nutrition_source": "USDA FoodData Central"}, {"name": "dried thyme", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "3b938244-d506-46b2-9027-21bed955bcc5", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "flaky sea salt", "quantity": 4, "unit": "g", "preparation": null, "notes": "Adjust to taste based on bread salinity", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 190\u00b0C (375\u00b0F). Place a rack in the center position.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Tear the sourdough bread by hand into uneven chunks ranging from 2cm to 4cm. Do not use a knife; the jagged, torn edges are essential for texture and catching the oil.", "structured": {"action": "TEAR", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Include crust pieces for variety in texture.", "Remove any extremely large air bubbles if they make the piece too fragile."]}, {"step_number": 3, "phase": "prep", "text": "In a large mixing bowl, whisk together the olive oil, garlic powder, dried thyme, dried oregano, salt, and pepper until the spices are suspended in the oil.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Add the torn bread chunks to the bowl. Toss vigorously with your hands or a spatula, ensuring every nook and cranny of the torn bread is lightly coated with the seasoned oil.", "structured": {"action": "TOSS", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Spread the bread evenly on a baking sheet in a single layer. Do not overcrowd; give the pieces space to breathe so they crisp rather than steam.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT15M", "doneness_cues": {"visual": "Golden brown edges", "tactile": "Hard to the touch"}}, "tips": ["Rotate the pan and flip the croutons halfway through baking (around the 8-minute mark)."]}, {"step_number": 6, "phase": "finish", "text": "Remove from the oven and let the croutons cool completely on the baking sheet. They will continue to harden and crisp up as they cool.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT25M", "total_time": "PT35M", "overnight_required": false, "yields": "300g croutons", "yield_count": 10, "serving_size_g": 30}', '{"flags": ["Vegetarian", "Vegan", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 145.13, "protein_g": 2.42, "carbohydrates_g": 18.3, "fat_g": 6.4, "saturated_fat_g": 0.84, "trans_fat_g": null, "monounsaturated_fat_g": 4.38, "polyunsaturated_fat_g": 0.63, "fiber_g": 0.66, "sugar_g": 0.01, "sodium_mg": 155.6, "cholesterol_mg": null, "potassium_mg": 30.41, "calcium_mg": 8.98, "iron_mg": 1.01, "magnesium_mg": 0.9, "phosphorus_mg": 1.75, "zinc_mg": 0.02, "vitamin_a_mcg": 0.3, "vitamin_c_mg": 0.48, "vitamin_d_mcg": null, "vitamin_e_mg": 0.89, "vitamin_k_mcg": 6.11, "vitamin_b6_mg": 0.01, "vitamin_b12_mcg": null, "thiamin_mg": null, "riboflavin_mg": null, "niacin_mg": 0.01, "folate_mcg": 0.67, "water_g": 0.05, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Do not refrigerate; humidity will destroy texture.", "duration": null}, "freezer": {"notes": "Freeze in airtight bag; refresh in oven for 5 minutes before using.", "duration": "P1M"}, "reheating": "Re-crisp in a 180\u00b0C/350\u00b0F oven for 3-5 minutes if they become stale.", "does_not_keep": false}', '[{"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": false, "alternative": "Fork"}]', '[{"symptom": "Croutons are chewy in the center", "likely_cause": "Bread was too fresh or pieces were too large", "prevention": "Use day-old bread or bake at a slightly lower temperature (175\u00b0C/350\u00b0F) for longer", "fix": "Return to oven at 150\u00b0C/300\u00b0F for 5-10 minutes to dry out without burning"}, {"symptom": "Spices taste burnt or bitter", "likely_cause": "Oven temperature too high or dried herbs burned", "prevention": "Ensure bread is well-coated in oil which protects the herbs; check oven calibration", "fix": "Cannot be fixed"}]', '["Tearing the bread exposes more gluten strands and surface area than cutting, creating ''micro-caves'' that hold onto the dressing when added to salads.", "If using very fresh sourdough, leave the torn chunks on the counter for 30 minutes before seasoning to dry out the surface slightly.", "For a ''Polenta'' variation, toss the oiled croutons in 20g of fine cornmeal before baking for an extra shatteringly crisp crust.", "Store in a paper bag or a container with the lid slightly ajar if you live in a humid climate to maintain crispness."]', '"While ''crouton'' comes from the French ''cro\u00fbte'' (crust), the practice of repurposing stale bread is universal across European peasantry. This rustic, hand-torn style mimics the ''panzanella'' tradition of Tuscany, prioritizing resourcefulness and texture over the uniform precision found in industrial manufacturing."', 145.13);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('5b891f49-4472-4d71-9b2c-489fda63a02c', 'Quick Thai Red Turkey Curry', 'A vibrant and creamy curry utilizing pre-cooked turkey for speed. The richness of coconut milk balances the heat of red curry paste, while fresh spinach adds color and nutrition to this 20-minute meal.', 'dinner', 'Thai', 'Easy', '["easy", "quick", "leftovers", "thai-inspired", "one-pot"]', '[{"group_name": "Aromatics & Base", "items": [{"name": "vegetable oil", "quantity": 15, "unit": "ml", "preparation": "neutral oil", "notes": null, "substitutions": ["coconut oil", "canola oil"], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "red curry paste", "quantity": 60, "unit": "g", "preparation": null, "notes": "Store-bought or homemade", "substitutions": ["yellow curry paste", "massaman paste"], "ingredient_id": "e714e2f1-2295-4e8c-8ccf-65c38381e71e", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 10, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Liquids", "items": [{"name": "coconut milk", "quantity": 400, "unit": "ml", "preparation": "full-fat canned", "notes": "Shake can well before opening", "substitutions": [], "ingredient_id": "c037ee7e-e3ed-4340-b8fb-d8ad284ba96e", "nutrition_source": "USDA FoodData Central"}, {"name": "chicken stock", "quantity": 120, "unit": "ml", "preparation": "low-sodium", "notes": null, "substitutions": [], "ingredient_id": "7e254f45-046f-4812-bcdd-7e31c9bb59b8", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Protein & Vegetables", "items": [{"name": "cooked turkey", "quantity": 400, "unit": "g", "preparation": "cubed or shredded", "notes": "Perfect for leftovers", "substitutions": [], "ingredient_id": "2832be8b-a0d1-4d8b-b3f1-107f508a32ff", "nutrition_source": "Aggregated Public Data"}, {"name": "baby spinach", "quantity": 150, "unit": "g", "preparation": "fresh washed", "notes": null, "substitutions": [], "ingredient_id": "4734440a-226d-4d26-a110-3ed5c3bde93f", "nutrition_source": "USDA FoodData Central"}, {"name": "red bell pepper", "quantity": 1, "unit": null, "preparation": "sliced into thin strips", "notes": "approx 150g", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Seasoning & Garnish", "items": [{"name": "fish sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["soy sauce", "tamari"], "ingredient_id": "95a9a747-50ee-4be0-84be-0dfc96111e2a", "nutrition_source": "Aggregated Public Data"}, {"name": "brown sugar", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": ["palm sugar"], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "lime juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": null, "unit": null, "preparation": "chopped", "notes": "for garnish", "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare your ingredients: dice the cooked turkey into bite-sized pieces, slice the red bell pepper into strips, mince the garlic, and grate the ginger.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat the vegetable oil in a large skillet or wok over medium heat (approx 175\u00b0C/350\u00b0F). Add the red curry paste, minced garlic, and grated ginger. Saut\u00e9 for 2 minutes until the paste darkens slightly and becomes very fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT2M", "doneness_cues": {"visual": "Paste darkens", "tactile": "Aromatics are fragrant"}}, "tips": ["Frying the paste is essential to ''wake up'' the spices and remove the raw flavor."]}, {"step_number": 3, "phase": "cook", "text": "Pour in the coconut milk and chicken stock. Stir well to dissolve the curry paste into the liquid. Bring the mixture to a gentle simmer.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the sliced red bell peppers, fish sauce, and brown sugar. Simmer for 3-4 minutes until the peppers are slightly tender but still crisp.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the cooked turkey. Simmer for another 2-3 minutes, just long enough to heat the turkey through to 74\u00b0C/165\u00b0F. Avoid boiling vigorously to keep the turkey tender.", "structured": {"action": "SIMMER", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Turn off the heat. Stir in the fresh spinach and lime juice. The residual heat will wilt the spinach in about 30 seconds. Taste and adjust salt (fish sauce) or sweetness (sugar) if needed.", "structured": {"action": "STIR", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": ["Adding lime juice after turning off the heat preserves its fresh, zesty flavor."]}, {"step_number": 7, "phase": "finish", "text": "Serve immediately over steamed rice, garnished with fresh cilantro if desired.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT5M", "total_time": "PT20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 320}', '{"flags": ["Dairy-Free", "Gluten-Free", "Pescatarian"], "not_suitable_for": []}', '{"per_serving": {"calories": 500.67, "protein_g": 34.45, "carbohydrates_g": 23.95, "fat_g": 33.31, "saturated_fat_g": 22.79, "trans_fat_g": null, "monounsaturated_fat_g": 2.34, "polyunsaturated_fat_g": 0.86, "fiber_g": 11.94, "sugar_g": 9.57, "sodium_mg": 411.55, "cholesterol_mg": null, "potassium_mg": 1001.17, "calcium_mg": 156.55, "iron_mg": 7.23, "magnesium_mg": 115.27, "phosphorus_mg": 187, "zinc_mg": 1.7, "vitamin_a_mcg": 273.15, "vitamin_c_mg": 63.19, "vitamin_d_mcg": null, "vitamin_e_mg": 5.3, "vitamin_k_mcg": 198.08, "vitamin_b6_mg": 0.26, "vitamin_b12_mcg": null, "thiamin_mg": 0.11, "riboflavin_mg": 0.14, "niacin_mg": 1.93, "folate_mcg": 115.13, "water_g": 144.08, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Sauce may thicken when cold.", "duration": "P3D"}, "freezer": {"notes": "Coconut milk may separate slightly upon thawing; whisk vigorously when reheating.", "duration": "P1M"}, "reheating": "Gently reheat on the stove over low heat to prevent the coconut milk from splitting.", "does_not_keep": false}', '[{"name": "Large skillet or Wok", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Measuring spoons", "required": true, "alternative": null}]', '[{"symptom": "Curry is too spicy", "likely_cause": "Curry paste brands vary significantly in heat levels", "prevention": "Start with half the amount of paste and add more to taste", "fix": "Add a splash more coconut milk or a teaspoon of extra sugar to counteract the heat"}, {"symptom": "Turkey tastes dry", "likely_cause": "Turkey was overcooked in the sauce", "prevention": "Since the turkey is pre-cooked, only add it at the very end to warm through", "fix": "Ensure plenty of sauce is served with each bite to mask the texture"}]', '["Use full-fat coconut milk for a velvety texture; ''lite'' versions will result in a watery sauce.", "This recipe is an excellent vehicle for clearing out the fridge\u2014bamboo shoots, green beans, or snap peas are great additions alongside the peppers.", "If using leftover roast turkey that was seasoned with sage or rosemary, rinse the meat briefly before adding, or ensure those herbs complement the curry profile."]', '"Based on the Thai ''Kaeng Phet'' (Red Curry), this dish adapts the traditional method of frying curry paste in coconut cream. While authentic versions often use duck or chicken, turkey provides a lean protein alternative popular in Western adaptations, particularly after holidays."', 500.67);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('5b976829-9f66-47d2-801f-9825869f3cca', 'Arroz con Cerdo y Garbanzos (Spanish Pork & Chickpea Rice)', 'A comforting, hearty one-pot meal bridging the gap between paella and stew. Tender bites of pork shoulder mingle with creamy chickpeas and sweet red peppers, all bound together by saffron-scented, tomato-rich rice. Smoky paprika provides a deep, savory backbone perfect for autumn evenings.', 'main course', 'Spanish', 'Intermediate', '["spanish", "grains and rice", "chickpea", "pork", "red pepper", "short-grain rice", "dinner", "weeknight", "main course", "fall"]', '[{"group_name": "Protein & Produce", "items": [{"name": "pork shoulder (boston butt)", "quantity": 500, "unit": "g", "preparation": "trimmed and cut into 2cm cubes", "notes": "Choose well-marbled cuts for tenderness", "substitutions": [], "ingredient_id": "f52704e4-0f51-4792-86a1-84e4668cc856", "nutrition_source": "USDA FoodData Central"}, {"name": "red bell pepper", "quantity": 1, "unit": null, "preparation": "diced (approx 1cm)", "notes": "about 180g", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "Aggregated Public Data"}, {"name": "onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "medium size, about 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "minced", "notes": "about 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "chickpeas", "quantity": 400, "unit": "g", "preparation": "canned", "notes": "drain and rinse; net weight approx 240g", "substitutions": [], "ingredient_id": "145073f5-45bb-493b-bc45-ce71653e9f26", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pantry & Aromatics", "items": [{"name": "short-grain rice", "quantity": 300, "unit": "g", "preparation": "dry", "notes": "Bomba or Calasparra preferred; Arborio is a distinct alternative", "substitutions": [], "ingredient_id": "24663b2d-5fab-4384-8385-1532a901babd", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": "divided use", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika (piment\u00f3n de la vera)", "quantity": 5, "unit": "g", "preparation": "powder", "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "saffron threads", "quantity": 0.5, "unit": "g", "preparation": "crumbled", "notes": "a generous pinch", "substitutions": [], "ingredient_id": "7f9ec0c8-2db1-48ac-a2c9-9b1efce12cf3", "nutrition_source": "USDA FoodData Central"}, {"name": "tomato puree", "quantity": 100, "unit": "g", "preparation": "or grated fresh tomato", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "chicken stock", "quantity": 950, "unit": "ml", "preparation": "hot", "notes": "low-sodium preferred", "substitutions": [], "ingredient_id": "7e254f45-046f-4812-bcdd-7e31c9bb59b8", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Season the pork cubes generously with salt and pepper. Measure out all ingredients, as the cooking process moves quickly once started.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat 30ml of olive oil in the wide pan over medium-high heat. Add the pork cubes in a single layer (work in batches if necessary to avoid crowding). Sear until deeply browned on all sides, about 6-8 minutes. Remove pork to a plate, leaving the rendered fat in the pan.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT8M", "doneness_cues": {"visual": "Deep golden brown crust on pork", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Lower heat to medium. Add the remaining 15ml oil, diced onion, and red pepper to the pan. Saut\u00e9 for 8 minutes until the onions are translucent and peppers are soft. Add the minced garlic and cook for 1 minute until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT9M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Stir in the smoked paprika and tomato puree. Cook for 2-3 minutes, stirring constantly, until the tomato mixture darkens and thickens into a paste (making a sofrito).", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Mixture becomes brick-red and oil begins to separate", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the rice to the pan. Stir well to coat every grain in the sofrito oil. Toast the rice for 2 minutes. This helps the grains maintain their structure.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Pour in the hot chicken stock and sprinkle in the saffron. Stir gently to distribute ingredients evenly. Return the pork (and any resting juices) and the drained chickpeas to the pan. Distribute them evenly.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Bring the liquid to a boil, then reduce heat to a simmer. Cook uncovered for 18-20 minutes. DO NOT STIR during this time. Stirring releases starch and makes the rice mushy. If the liquid evaporates too fast, add a splash of hot water.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT20M", "doneness_cues": {"visual": "Liquid absorbed, rice visible on surface", "tactile": "Rice tender with slight bite in center"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove the pan from the heat. Cover with a clean kitchen towel or lid and let it rest for 5-10 minutes. This completes the cooking process gently and ensures the rice texture is perfect.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT25M", "total_time": "PT55M", "overnight_required": false, "yields": "4 hearty servings", "yield_count": 4, "serving_size_g": 380}', '{"flags": ["Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 965.78, "protein_g": 50.7, "carbohydrates_g": 99.39, "fat_g": 39.79, "saturated_fat_g": 10.18, "trans_fat_g": 0.19, "monounsaturated_fat_g": 18.84, "polyunsaturated_fat_g": 5.03, "fiber_g": 8.94, "sugar_g": 11, "sodium_mg": 1104.57, "cholesterol_mg": 122.5, "potassium_mg": 815.99, "calcium_mg": 102.57, "iron_mg": 4.59, "magnesium_mg": 87.21, "phosphorus_mg": 453.66, "zinc_mg": 7.82, "vitamin_a_mcg": 104.94, "vitamin_c_mg": 64.95, "vitamin_d_mcg": 1.5, "vitamin_e_mg": 3.15, "vitamin_k_mcg": 13.58, "vitamin_b6_mg": 1.05, "vitamin_b12_mcg": 1.16, "thiamin_mg": 0.76, "riboflavin_mg": 0.57, "niacin_mg": 6.81, "folate_mcg": 81.15, "water_g": 222.24, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. The rice will absorb remaining moisture, becoming thicker upon reheating.", "duration": "P3D"}, "freezer": {"notes": "Rice texture may become slightly softer upon thawing.", "duration": "P1M"}, "reheating": "Reheat gently in a pan with a splash of water or stock to loosen the grains.", "does_not_keep": false}', '[{"name": "Paella pan or wide shallow skillet", "required": true, "alternative": "Large Dutch oven"}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": null}]', '[{"symptom": "Rice is still crunchy but liquid is gone", "likely_cause": "Heat was too high or pan was too wide, causing rapid evaporation", "prevention": "Maintain a steady, gentle simmer and use correct pan size", "fix": "Sprinkle 50-100ml of hot water or stock over the rice, cover tightly with foil, and cook on very low heat for 5 more minutes"}]', '["Use Spanish smoked paprika (Piment\u00f3n de la Vera) specifically; generic paprika lacks the essential smoky depth for this dish.", "Do not wash Spanish short-grain rice before cooking. The surface starch is needed to create the correct texture, unlike Asian rice dishes.", "If you want a ''socarrat'' (crispy bottom layer), turn the heat up to high for the final 60 seconds of cooking before removing from heat\u2014listen for a crackling sound.", "Pork shoulder is preferred over loin because the intramuscular fat keeps it tender during the 20-minute simmer; loin would become dry."]', '"While Paella Valenciana is the most famous Spanish rice dish, ''arroz'' dishes vary wildly across regions. This variation, combining meat and legumes (chickpeas), reflects the rustic ''cocina de aprovechamiento'' (cooking of utilization) common in inland Spain, where hearty ingredients provided fuel for agricultural labor."', 965.78);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('5cbb1f63-1496-45d6-af80-2bf01085634d', 'Fire-Snap Gingerbread Cookies', 'An aggressively spiced, structural gingerbread cookie designed for the serious ginger enthusiast. These cookies omit leavening agents to ensure zero spread, resulting in a perfectly flat surface for royal icing and a satisfyingly hard, crisp snap. The heat comes from a heavy hand of ginger and a surprise kick of black pepper.', 'baked good', 'European', 'Intermediate', '["cardamom", "cinnamon", "clove", "cookie", "flour", "ginger", "nutmeg", "dessert", "christmas", "baking", "spicy"]', '[{"group_name": "Dry Spices & Flour", "items": [{"name": "all-purpose flour", "quantity": 440, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "ground ginger", "quantity": 15, "unit": "g", "preparation": null, "notes": "approx. 2.5 tbsp for extra heat", "substitutions": [], "ingredient_id": "401ddd0b-3597-4b46-bb54-f3bc755048bb", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 6, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cardamom", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c56f6cd8-882c-487c-956f-3a91ee1fec07", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cloves", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "7b3bf68a-3ae9-4dad-91f4-6c7a14ec5e0e", "nutrition_source": "USDA FoodData Central"}, {"name": "ground nutmeg", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}, {"name": "ground black pepper", "quantity": 1, "unit": "g", "preparation": null, "notes": "fine grind, essential for the ''fire'' kick", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wet Ingredients", "items": [{"name": "unsalted butter", "quantity": 170, "unit": "g", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "dark brown sugar", "quantity": 150, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "molasses", "quantity": 230, "unit": "g", "preparation": null, "notes": "unsulphured", "substitutions": [], "ingredient_id": "c76e81ce-ce17-4595-b9ff-30c87fb7c285", "nutrition_source": "USDA FoodData Central"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": "large", "notes": "approx. 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a medium bowl, whisk together the flour, ginger, cinnamon, cardamom, cloves, nutmeg, black pepper, and salt until completely uniform.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In the bowl of a stand mixer fitted with the paddle attachment, beat the softened butter and dark brown sugar on medium speed until fluffy and lightened in color.", "structured": {"action": "CREAM", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Add the molasses and egg to the butter mixture. Mix on low speed until combined, scraping down the sides of the bowl as needed to ensure no butter streaks remain.", "structured": {"action": "MIX", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "With the mixer on low, gradually add the dry spice mixture. Mix only until no flour pockets remain. Do not overmix, or the cookies will be tough rather than crisp.", "structured": {"action": "MIX", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Divide the dough into two discs, flatten them, wrap tightly in plastic wrap, and refrigerate for at least 2 hours. This is crucial for hydration and shape retention.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT2H", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Preheat your oven to 175\u00b0C (350\u00b0F). Line two baking sheets with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "prep", "text": "Roll out one disc of dough on a lightly floured surface to a thickness of 3-4mm. Cut into shapes with cookie cutters and transfer to the prepared baking sheets, spacing them 2cm apart.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["If the dough gets too soft to handle, pop it back in the fridge for 10 minutes."]}, {"step_number": 8, "phase": "cook", "text": "Bake for 9-12 minutes depending on cookie size. For maximum crispness, bake until the edges are just slightly darker than the center.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT11M", "doneness_cues": {"visual": "Edges slightly darkened", "tactile": "Firm to the touch"}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Allow cookies to cool on the baking sheet for 5 minutes to set, then transfer to a wire rack to cool completely. They will harden significantly as they cool.", "structured": {"action": "COOL", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT2H", "total_time": "PT2H45M", "overnight_required": false, "yields": "30 cookies", "yield_count": 30, "serving_size_g": 35}', '{"flags": ["Vegetarian", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 140.63, "protein_g": 1.85, "carbohydrates_g": 22.5, "fat_g": 4.97, "saturated_fat_g": 2.97, "trans_fat_g": null, "monounsaturated_fat_g": 1.41, "polyunsaturated_fat_g": 0.27, "fiber_g": 0.64, "sugar_g": 10.65, "sodium_mg": 46.69, "cholesterol_mg": 18.38, "potassium_mg": 147.51, "calcium_mg": 27.9, "iron_mg": 0.74, "magnesium_mg": 24.24, "phosphorus_mg": 24.43, "zinc_mg": 0.18, "vitamin_a_mcg": 41.48, "vitamin_c_mg": 0.03, "vitamin_d_mcg": 0.03, "vitamin_e_mg": 0.17, "vitamin_k_mcg": 0.66, "vitamin_b6_mg": 0.07, "vitamin_b12_mcg": 0.02, "thiamin_mg": 0.02, "riboflavin_mg": 0.02, "niacin_mg": 0.32, "folate_mcg": 4.97, "water_g": 5.77, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Dough can be refrigerated for up to a week before baking.", "duration": "P1W"}, "freezer": {"notes": "Freeze baked cookies or raw dough disks.", "duration": "P3M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Stand mixer or electric hand mixer", "required": true, "alternative": null}, {"name": "Rolling pin", "required": true, "alternative": null}, {"name": "Baking sheets", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Cookie cutters", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}]', '[{"symptom": "Cookies spread and lost their sharp edges", "likely_cause": "Dough was too warm when it went into the oven", "prevention": "Chill cut shapes in the freezer for 10 minutes before baking", "fix": "Re-cut warm cookies immediately upon exiting oven while soft"}, {"symptom": "Cookies are soft/chewy instead of crisp", "likely_cause": "Underbaked or rolled too thick", "prevention": "Roll to exactly 3mm and bake until edges darken", "fix": "Return to a low oven (150\u00b0C/300\u00b0F) for 5-10 minutes to dry out"}]', '["By omitting baking soda and baking powder, these cookies do not puff up. This creates a perfectly flat canvas for professional-looking royal icing decorations.", "The black pepper is a secret weapon; it doesn''t taste like ''pepper'' in the final cookie but provides a lingering warmth that amplifies the ginger.", "For the cleanest edges, dip your cookie cutters in flour before each cut.", "These cookies are hygroscopic (they absorb moisture from the air). If they soften over time, re-crisp them in a warm oven for 5 minutes.", "This dough is sturdy enough to be used for constructing gingerbread houses."]', '"While gingerbread has medieval European roots, the tradition of crisp, heavily spiced cookies specifically for decoration and construction became prominent in Germany (Lebkuchenhaus) and later Victorian England. The spices were historically a display of wealth and celebration during the winter solstice."', 140.63);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('5cdb6a69-fecf-43f5-8b34-14dc6acf96b2', 'Tangy Romaine Sandwich Slaw', 'A crisp, high-acid shredded salad designed specifically to cut through rich sandwich fillings. The sharp red wine vinaigrette and bite of raw garlic make this the ultimate topping for po'' boys, subs, or burgers.', 'salad', 'American Southern', 'Easy', '["southern", "garlic", "red onion", "romaine", "salad", "easy", "raw", "vegetarian", "sandwich topping", "lunch"]', '[{"group_name": "Vegetables", "items": [{"name": "romaine lettuce heart", "quantity": 1, "unit": null, "preparation": "fresh", "notes": "approx 250g", "substitutions": [], "ingredient_id": "312b8da7-52bd-406b-89d2-0853c0e37faa", "nutrition_source": "Aggregated Public Data"}, {"name": "red onion", "quantity": 0.25, "unit": null, "preparation": "peeled", "notes": "approx 40g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Tangy Garlic Vinaigrette", "items": [{"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "red wine vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "9e1b7e74-fdcb-4836-8349-4f7ad86d62df", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "fresh", "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "or to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Finely shred the Romaine lettuce horizontally (shaved style, about 3-5mm thick). Thinly slice the red onion into half-moons.", "structured": {"action": "SHRED", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["For sandwiches, a finer shred holds dressing better and doesn''t slide out of the bun."]}, {"step_number": 2, "phase": "prep", "text": "Wash the shredded lettuce in cold water and dry thoroughly using a salad spinner. It must be bone-dry for the vinaigrette to adhere.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Grate or mince the garlic into a paste. Combine with red wine vinegar, dried oregano, salt, and pepper in a small bowl. Whisk while slowly streaming in the olive oil to emulsify.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Letting the garlic sit in the vinegar for 5 minutes before adding oil mellows its harsh raw bite."]}, {"step_number": 4, "phase": "assemble", "text": "Place the lettuce and red onion in a large bowl. Pour the vinaigrette over the vegetables and toss aggressively until every strand is coated and glossy.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Taste and adjust salt if needed. Serve immediately as a salad or pile high onto sandwiches.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT10M", "total_time": "PT25M", "overnight_required": false, "yields": "4 sandwich servings", "yield_count": 4, "serving_size_g": 75}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Paleo", "Keto", "Whole30"], "not_suitable_for": []}', '{"per_serving": {"calories": 119.32, "protein_g": 1.03, "carbohydrates_g": 3.93, "fat_g": 11.49, "saturated_fat_g": 1.59, "trans_fat_g": null, "monounsaturated_fat_g": 8.23, "polyunsaturated_fat_g": 1.3, "fiber_g": 1.79, "sugar_g": 1.2, "sodium_mg": 297.61, "cholesterol_mg": null, "potassium_mg": 186.71, "calcium_mg": 35.04, "iron_mg": 0.96, "magnesium_mg": 12.15, "phosphorus_mg": 25.3, "zinc_mg": 0.2, "vitamin_a_mcg": 272.99, "vitamin_c_mg": 3.68, "vitamin_d_mcg": null, "vitamin_e_mg": 1.8, "vitamin_k_mcg": 74.11, "vitamin_b6_mg": 0.08, "vitamin_b12_mcg": null, "thiamin_mg": 0.05, "riboflavin_mg": 0.05, "niacin_mg": 0.24, "folate_mcg": 88.17, "water_g": 75.94, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten immediately. Undressed components keep for 2 days.", "duration": "P1D"}, "freezer": {"notes": "Do not freeze lettuce.", "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Small whisk or jar with lid", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Salad spinner", "required": false, "alternative": "Clean kitchen towels"}]', '[{"symptom": "Salad is watery and dressing slid off", "likely_cause": "Lettuce was not dried thoroughly after washing", "prevention": "Use a salad spinner or roll lettuce in towels until completely dry to the touch", "fix": "Tilt the bowl to drain excess water, add a pinch more salt and a splash of oil"}]', '["This recipe mimics the ''dressed'' component of a New Orleans Po'' Boy or an Italian Grinder; it is seasoned more aggressively than a side salad to stand up to bread and meats.", "If you find raw red onion too overpowering, soak the sliced onions in ice water for 10 minutes before drying and adding to the salad.", "For an even closer approximation to sub-shop style, add a pinch of dried chili flakes or a teaspoon of pickled pepper juice to the dressing."]', '"In the American South and East Coast deli culture, lettuce on a sandwich is rarely just a garnish\u2014it is often a dressed salad in its own right. This technique, often called ''Shredduce'' in modern kitchens, ensures the acid and seasoning permeate every bite of the sandwich rather than sitting on top."', 119.32);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('5d2f015d-b47a-4368-9aa7-76b30781bde4', 'Apricot Dijon Ham on Pumpernickel', 'Elegant finger sandwiches balancing the deep, earthy notes of pumpernickel with salty cured ham and a vibrant sweet-tart apricot mustard glaze. A classic tea-time appetizer perfect for spring gatherings.', 'appetizer', 'American', 'Easy', '["apricot preserve", "bread", "five ingredient", "ham", "appetizer", "spring", "easter", "tea sandwich"]', '[{"group_name": "Sandwich Components", "items": [{"name": "pumpernickel bread", "quantity": 8, "unit": null, "preparation": "sliced", "notes": "approx. 250g total; square cocktail slices preferred", "substitutions": [], "ingredient_id": "e056bad2-dcc6-4889-8e26-79ef420739eb", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "softened", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "apricot preserves", "quantity": 60, "unit": "g", "preparation": null, "notes": "fruit-heavy, high quality", "substitutions": [], "ingredient_id": "169d2f29-93de-4df0-826f-57629d5839bc", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 30, "unit": "g", "preparation": "smooth", "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "black forest ham", "quantity": 150, "unit": "g", "preparation": "thinly sliced", "notes": null, "substitutions": [], "ingredient_id": "b109239b-101a-4dd5-83a7-7e4c274c63f1", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a small mixing bowl, whisk together the apricot preserves and Dijon mustard until smooth and fully emulsified to create the glaze.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "assemble", "text": "Lay out the pumpernickel slices on a cutting board. Spread a thin, even layer of softened butter on one side of every slice. This hydrophobic barrier prevents the bread from becoming soggy.", "structured": {"action": "SPREAD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "assemble", "text": "Spread the apricot-mustard mixture over the buttered side of half the bread slices. Arrange the ham on top of the glazed slices, folding the meat to create volume rather than laying it flat.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Top with the remaining buttered bread slices. Using a serrated knife, gently saw off the crusts (if using standard loaf) to create clean squares, then cut each sandwich into three equal rectangular fingers.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Clean, sharp edges with visible layers", "tactile": null}}, "tips": ["Wipe the knife blade with a damp cloth between cuts to keep the bread face clean."]}]', '{"active_time": "PT15M", "passive_time": "PT0M", "total_time": "PT15M", "overnight_required": false, "yields": "12 finger sandwiches", "yield_count": 6, "serving_size_g": 85}', '{"flags": ["Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 201.02, "protein_g": 8.83, "carbohydrates_g": 26.76, "fat_g": 6.98, "saturated_fat_g": 2.84, "trans_fat_g": null, "monounsaturated_fat_g": 1.77, "polyunsaturated_fat_g": 0.96, "fiber_g": 2.9, "sugar_g": 4.81, "sodium_mg": 569.63, "cholesterol_mg": 27.5, "potassium_mg": 177.22, "calcium_mg": 38.28, "iron_mg": 1.73, "magnesium_mg": 28, "phosphorus_mg": 151.67, "zinc_mg": 1.22, "vitamin_a_mcg": 35.2, "vitamin_c_mg": 0.88, "vitamin_d_mcg": null, "vitamin_e_mg": 0.4, "vitamin_k_mcg": 0.68, "vitamin_b6_mg": 0.12, "vitamin_b12_mcg": 0.07, "thiamin_mg": 0.15, "riboflavin_mg": 0.19, "niacin_mg": 2.18, "folate_mcg": 40.5, "water_g": 38.05, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten fresh; if storing, cover tightly with damp paper towel and plastic wrap to prevent drying.", "duration": "P1D"}, "freezer": {"duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Serrated bread knife", "required": true, "alternative": "Very sharp chef''s knife"}, {"name": "Offset spatula", "required": false, "alternative": "Butter knife"}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Bread becomes soggy", "likely_cause": "Butter barrier was skipped or too thin", "prevention": "Ensure bread is completely coated with butter before adding wet ingredients", "fix": "Cannot be fixed"}, {"symptom": "Sandwiches fall apart when cut", "likely_cause": "Knife is dull or too much downward pressure applied", "prevention": "Use a serrated knife and let the sawing motion do the work; do not press down", "fix": "Secure with cocktail picks"}]', '["Folding the ham (chiffonade or ribbon style) creates a lighter mouthfeel than stacking flat slices.", "For the cleanest presentation, freeze the assembled sandwiches for 10-15 minutes before cutting the crusts off.", "If the apricot preserves are very chunky, quickly chop them or snip with kitchen shears before mixing with the mustard.", "Pumpernickel is dense; ensure slices are thin (approx 5-7mm) to maintain a balanced bite."]', '"While pumpernickel has Westphalian German roots, the combination of fruit preserves, mustard, and cured meats on crustless bread is a staple of the Anglo-American ''tea sandwich'' tradition, often served at spring luncheons and Easter gatherings."', 201.02);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('5dc663b3-b8c9-4a72-9492-c24377a03c56', 'Giant Brown Sugar Anise Crinkle Cookies', 'These oversized, bakery-style cookies feature crisp, sugar-crusted edges and a soft, chewy center rich with molasses notes. The optional crushed anise seeds provide a sophisticated, fragrant licorice warmth that pairs beautifully with the brown sugar, making them excellent standalone snacks or elegant accompaniments to lemon sorbet or vanilla ice cream.', 'baked good', 'American', 'Easy', '["american", "anise", "aniseed", "brown sugar", "butter", "cookie", "flour", "vanilla", "snack", "dessert"]', '[{"group_name": "Aromatics", "items": [{"name": "anise seeds", "quantity": 4, "unit": "g", "preparation": "whole", "notes": "approx 2 tsp; lightly crushed to release oils", "substitutions": ["fennel seeds", "ground cinnamon", "omit entirely for plain vanilla"], "ingredient_id": "9010f167-112f-4c3b-80c3-b49783e568a1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wet Ingredients", "items": [{"name": "unsalted butter", "quantity": 225, "unit": "g", "preparation": "room temperature, softened", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "dark brown sugar", "quantity": 200, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "large egg", "quantity": 1, "unit": null, "preparation": "room temperature", "notes": "approx 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "egg yolk", "quantity": 1, "unit": null, "preparation": "room temperature", "notes": "approx 18g; adds chewiness", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dry Ingredients", "items": [{"name": "all-purpose flour", "quantity": 320, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 4, "unit": "g", "preparation": null, "notes": "approx 3/4 tsp", "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 1/2 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 175\u00b0C (350\u00b0F). Line two large baking sheets with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "If using anise seeds, lightly crush them in a mortar and pestle just enough to break the outer husks and release fragrance. Do not grind to a powder.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a large bowl or stand mixer fitted with the paddle attachment, cream the softened butter, brown sugar, and granulated sugar together on medium-high speed until light, fluffy, and pale.", "structured": {"action": "CREAM", "temperature": null, "duration": "PT4M", "doneness_cues": null}, "tips": ["Scrape down the sides of the bowl halfway through mixing to ensure even incorporation."]}, {"step_number": 4, "phase": "prep", "text": "Add the whole egg, extra egg yolk, vanilla extract, and crushed anise seeds (if using). Mix on medium speed until well combined.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Add the flour, baking soda, and salt. Mix on low speed just until no streaks of dry flour remain. Do not overmix, or the cookies will be tough.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Scoop the dough into large mounds (approx 75g each) using a large cookie scoop. Place them on the baking sheets spaced at least 8cm (3 inches) apart, as they will spread significantly.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Bake one sheet at a time for 11-13 minutes. The edges should be set and golden brown, but the centers should still look slightly soft and underbaked.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT12M", "doneness_cues": {"visual": "Golden brown edges, puffy but slightly raw-looking centers", "tactile": null}}, "tips": ["For crinkled edges, lift the baking sheet 10cm and drop it flat onto the oven rack halfway through baking."]}, {"step_number": 8, "phase": "finish", "text": "Allow the cookies to cool on the baking sheet for at least 10 minutes to set before transferring to a wire rack to cool completely.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT15M", "total_time": "PT35M", "overnight_required": false, "yields": "12 large cookies", "yield_count": 12, "serving_size_g": 75}', '{"flags": ["Vegetarian", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 341.4, "protein_g": 3.75, "carbohydrates_g": 45.4, "fat_g": 16.32, "saturated_fat_g": 9.79, "trans_fat_g": null, "monounsaturated_fat_g": 4.77, "polyunsaturated_fat_g": 0.83, "fiber_g": 0.77, "sugar_g": 24.7, "sodium_mg": 202.44, "cholesterol_mg": 72.01, "potassium_mg": 68.8, "calcium_mg": 28.99, "iron_mg": 0.68, "magnesium_mg": 8.99, "phosphorus_mg": 49.58, "zinc_mg": 0.32, "vitamin_a_mcg": 140.69, "vitamin_c_mg": 0.07, "vitamin_d_mcg": 0.16, "vitamin_e_mg": 0.53, "vitamin_k_mcg": 1.42, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": 0.1, "thiamin_mg": 0.04, "riboflavin_mg": 0.05, "niacin_mg": 0.38, "folate_mcg": 11.84, "water_g": 10.87, "alcohol_g": 0.29, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Dough can be chilled for up to 3 days before baking for deeper flavor.", "duration": "P1W"}, "freezer": {"notes": "Freeze shaped dough balls; bake from frozen adding 2-3 minutes to cook time.", "duration": "P3M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Stand mixer or electric hand mixer", "required": true, "alternative": null}, {"name": "Baking sheets", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Mortar and pestle", "required": false, "alternative": "Spice grinder or heavy pan on cutting board"}, {"name": "Large cookie scoop (approx 60ml capacity)", "required": true, "alternative": "Two large spoons"}, {"name": "Wire cooling rack", "required": true, "alternative": null}]', '[{"symptom": "Cookies spread too thin and became flat lace", "likely_cause": "The butter was too warm (melted rather than softened) or the baking sheet was hot from a previous batch.", "prevention": "Ensure butter is at cool room temperature (plastic indentable but not greasy). Cool baking sheets under cold water between batches.", "fix": "Chill the remaining dough in the refrigerator for 20 minutes before baking the next batch."}]', '["The anise flavor intensifies slightly the day after baking as the oils distribute through the fats.", "If you omit the anise, you can roll the dough balls in cinnamon sugar before baking for a classic snickerdoodle twist.", "To achieve a perfectly round shape, place a large round cookie cutter or glass over the hot cookie immediately after removing from the oven and gently swirl it in a circular motion to nudge the edges in.", "Using an extra egg yolk is the secret to the chewy, fudge-like texture in the center of the cookie."]', '"While anise is traditionally associated with Italian Pizzelle or German Springerle cookies, this recipe adapts that classic Old World flavor profile into the beloved American ''drop cookie'' format. This creates a bridge between the comforting texture of a modern bakery cookie and the aromatic sophistication of traditional European spice blends."', 341.4);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('5e31c07b-6697-4bc7-931f-6bbd66cfedfc', 'Salted Tahini Dark Chocolate Cookies', 'A sophisticated evolution of the classic cookie, marrying the earthy, nutty depth of sesame paste with pools of bitter dark chocolate. The texture offers a crispy edge with a fudge-like center, finished with flaky salt to heighten the savory-sweet contrast.', 'dessert', 'Israeli Fusion', 'Intermediate', '["chocolate chip", "chocolate chip cookie", "israeli", "plan-ahead", "tahini", "snack", "dessert"]', '[{"group_name": "Wet Ingredients", "items": [{"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "room temperature", "notes": "pliable but not melting", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "tahini", "quantity": 120, "unit": "g", "preparation": "well-stirred", "notes": "smooth, runny sesame paste; avoid the stiff bottom sediment", "substitutions": [], "ingredient_id": "87ae6455-8e22-4c1b-bad7-89fa69c4dc57", "nutrition_source": "Aggregated Public Data"}, {"name": "granulated sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "light brown sugar", "quantity": 100, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": "large", "notes": "approx 50g without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dry Ingredients", "items": [{"name": "all-purpose flour", "quantity": 160, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Inclusions & Finish", "items": [{"name": "dark chocolate", "quantity": 150, "unit": "g", "preparation": "chopped chunks", "notes": "70% cocoa solids preferred", "substitutions": ["semisweet chocolate chips"], "ingredient_id": "08395d12-1a43-46f7-b602-36c2d07ce259", "nutrition_source": "USDA FoodData Central"}, {"name": "flaky sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "Maldon or similar, for garnishing", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Cream the room temperature butter, well-stirred tahini, granulated sugar, and brown sugar on medium speed until light, fluffy, and aerated (about 3-4 minutes).", "structured": {"action": "CREAM", "temperature": null, "duration": "PT4M", "doneness_cues": null}, "tips": ["Ensure the tahini is thoroughly mixed in its jar before measuring; oil separation can cause greasy cookies."]}, {"step_number": 2, "phase": "prep", "text": "Add the egg and vanilla extract to the butter mixture. Beat for another minute until fully incorporated and the mixture looks creamy.", "structured": {"action": "BEAT", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a separate bowl, whisk together the flour, baking soda, baking powder, and fine sea salt. Add this to the wet ingredients and mix on low speed just until streaks of flour disappear.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Fold in the dark chocolate chunks by hand using a spatula to avoid overworking the gluten.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Cover the bowl or portion the dough into balls immediately. Refrigerate for at least 12 hours (overnight is best) to hydrate the flour and develop deep toffee notes.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "P1D", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Preheat oven to 175\u00b0C (350\u00b0F). Line baking sheets with parchment paper. Arrange chilled dough balls 5cm (2 inches) apart.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Bake for 11-13 minutes. The edges should be golden brown and set, but the centers should still look slightly underbaked and soft.", "structured": {"action": "BAKE", "temperature": null, "duration": "PT12M", "doneness_cues": {"visual": "Golden edges, pale center", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Immediately upon removing from the oven, sprinkle generously with flaky sea salt. Allow to cool on the tray for 5 minutes before transferring to a wire rack.", "structured": {"action": "COOL", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": ["If cookies lost their round shape, use a large round cookie cutter to scoot them into circles while still hot on the tray."]}]', '{"active_time": "PT25M", "passive_time": "P1D", "total_time": "P1D25M", "overnight_required": true, "yields": "16 large cookies", "yield_count": 16, "serving_size_g": 55}', '{"flags": ["Vegetarian"], "not_suitable_for": ["Sesame allergy", "Gluten intolerance"]}', '{"per_serving": {"calories": 242.13, "protein_g": 3.71, "carbohydrates_g": 25.76, "fat_g": 14.03, "saturated_fat_g": 6.46, "trans_fat_g": 0.01, "monounsaturated_fat_g": 2.88, "polyunsaturated_fat_g": 0.43, "fiber_g": 1.98, "sugar_g": 15.86, "sodium_mg": 208.21, "cholesterol_mg": 27.64, "potassium_mg": 116.34, "calcium_mg": 90.99, "iron_mg": 1.69, "magnesium_mg": 46.11, "phosphorus_mg": 88.09, "zinc_mg": 0.74, "vitamin_a_mcg": 54.44, "vitamin_c_mg": null, "vitamin_d_mcg": 0.06, "vitamin_e_mg": 0.26, "vitamin_k_mcg": 1.22, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": 0.06, "thiamin_mg": 0.02, "riboflavin_mg": 0.03, "niacin_mg": 0.22, "folate_mcg": 4.35, "water_g": 5.11, "alcohol_g": 0.11, "caffeine_mg": 8.06}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store unbaked dough in the fridge for up to 3 days for best flavor development.", "duration": "P3D"}, "freezer": {"notes": "Freeze scooped dough balls; bake from frozen adding 2 minutes to cook time.", "duration": "P3M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Stand mixer or electric hand mixer", "required": true, "alternative": "Large bowl and sturdy whisk/spatula"}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}, {"name": "Cookie scoop", "required": false, "alternative": "Two spoons"}]', '[{"symptom": "Cookies spread too much and became flat lace", "likely_cause": "The dough was too warm entering the oven or the tahini was too oily", "prevention": "Strictly adhere to the overnight chilling time; ensure oven is fully preheated", "fix": "Chill remaining dough for another hour; if already baked, crumble over ice cream"}]', '["Tahini brands vary significantly in viscosity. Use a runny, high-quality Middle Eastern brand (like Soom or Al Arz) rather than the stiff paste found in health food jars.", "The 24-hour rest is not just for convenience; it allows the enzymes in the flour to break down starches into sugars, resulting in significantly better browning and flavor complexity.", "For perfectly round, Instagram-worthy cookies, sprinkle a few reserved chocolate chunks on top of the dough balls just before baking."]', '"Tahini (sesame paste) is a staple of Israeli and Levantine cuisine, traditionally used in savory hummus and baba ganoush. Its introduction into sweets, particularly halva, dates back centuries, but its use in Western-style cookies creates a modern fusion that highlights the region''s love for balancing sweetness with earthy, roasted flavors."', 242.13);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('5e32a244-9b7d-4e3d-a14e-5233969cfccd', 'Classic Hearthside Minestrone', 'A robust, warming Italian vegetable soup deeply flavored with a tomato-herb broth and enriched with beans and pasta. This recipe is designed as a flexible blueprint to utilize seasonal produce while maintaining a cohesive savory profile.', 'soup', 'Italian', 'Easy', '["soup", "minestrone", "vegetable", "easy", "quick", "italian", "vegetarian", "winter"]', '[{"group_name": "Soffritto & Aromatics", "items": [{"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "diced small", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "carrots", "quantity": 2, "unit": null, "preparation": "peeled and diced small", "notes": "approx. 120g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "celery stalks", "quantity": 2, "unit": null, "preparation": "diced small", "notes": "approx. 100g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "minced", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "tomato paste", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Broth & Base", "items": [{"name": "vegetable stock", "quantity": 1500, "unit": "ml", "preparation": null, "notes": "use low-sodium to control salinity", "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "canned crushed tomatoes", "quantity": 400, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b6a8f276-0e66-4a80-ba52-1dbe3b1a4e5f", "nutrition_source": "Aggregated Public Data"}, {"name": "parmesan cheese rind", "quantity": 1, "unit": null, "preparation": "whole", "notes": "optional, for depth", "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "bay leaf", "quantity": 1, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Hearty Additions", "items": [{"name": "potato", "quantity": 200, "unit": "g", "preparation": "peeled and diced 1cm cubes", "notes": null, "substitutions": [], "ingredient_id": "5bf06478-4785-465e-9842-f70a24e22054", "nutrition_source": "USDA FoodData Central"}, {"name": "zucchini", "quantity": 200, "unit": "g", "preparation": "diced 1cm cubes", "notes": null, "substitutions": [], "ingredient_id": "c34b610f-8869-4d77-a9b3-e01849d703b5", "nutrition_source": "USDA FoodData Central"}, {"name": "cannellini beans", "quantity": 400, "unit": "g", "preparation": "cooked or canned", "notes": "drained and rinsed", "substitutions": [], "ingredient_id": "338d5b1f-5e90-4e7f-b286-e827b78558e9", "nutrition_source": "Aggregated Public Data"}, {"name": "small pasta", "quantity": 120, "unit": "g", "preparation": null, "notes": "ditalini, macaroni, or small shells", "substitutions": ["broken spaghetti", "rice", "farro"], "ingredient_id": "9acd8d49-8848-4e5f-90e4-33b9b31f83c9", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh spinach", "quantity": 100, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "4734440a-226d-4d26-a110-3ed5c3bde93f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Seasoning", "items": [{"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, start with 5g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Heat olive oil in a large Dutch oven over medium heat. Add the onion, carrots, and celery (the soffritto) along with a pinch of salt.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT8M", "doneness_cues": {"visual": "Onions are translucent and vegetables are softened", "tactile": "Soft but not browned"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Stir in the minced garlic, tomato paste, and dried oregano. Cook while stirring frequently until the tomato paste darkens slightly and becomes aromatic.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Paste turns brick red", "tactile": "Aromatic scent released"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the diced potatoes, crushed tomatoes, vegetable stock, bay leaf, and the parmesan rind (if using). Increase heat to bring to a boil, then reduce to a gentle simmer.", "structured": {"action": "SIMMER", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT15M", "doneness_cues": {"visual": "Potatoes are tender when pierced with a knife", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Stir in the zucchini, drained beans, and pasta. Continue simmering until the pasta is al dente and the zucchini is tender.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Pasta is cooked through but firm", "tactile": "Vegetables yield to pressure"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove the pot from heat. Discard the bay leaf and parmesan rind. Stir in the fresh spinach until wilted. Season with salt, black pepper, and a splash of lemon juice to brighten the flavors.", "structured": {"action": "SEASON", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT35M", "total_time": "PT1H", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 400}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 384.2, "protein_g": 19.78, "carbohydrates_g": 68.58, "fat_g": 9.36, "saturated_fat_g": 1.53, "trans_fat_g": null, "monounsaturated_fat_g": 5.5, "polyunsaturated_fat_g": 0.91, "fiber_g": 13.06, "sugar_g": 10.15, "sodium_mg": 1995.61, "cholesterol_mg": 0.09, "potassium_mg": 1433.52, "calcium_mg": 199.35, "iron_mg": 7.65, "magnesium_mg": 158.74, "phosphorus_mg": 294.54, "zinc_mg": 3.06, "vitamin_a_mcg": 333.71, "vitamin_c_mg": 27.97, "vitamin_d_mcg": null, "vitamin_e_mg": 1.71, "vitamin_k_mcg": 96.73, "vitamin_b6_mg": 0.27, "vitamin_b12_mcg": null, "thiamin_mg": 0.07, "riboflavin_mg": 0.11, "niacin_mg": 0.93, "folate_mcg": 61.63, "water_g": 132.49, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Pasta will continue to absorb liquid; add a splash of water when reheating.", "duration": "P4D"}, "freezer": {"notes": "Freeze without pasta for best texture; cook fresh pasta when reheating.", "duration": "P3M"}, "reheating": "Simmer gently on stove until heated through (75\u00b0C).", "does_not_keep": false}', '[{"name": "Large heavy-bottomed pot or Dutch oven", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": null}, {"name": "Vegetable peeler", "required": true, "alternative": null}]', '[{"symptom": "Soup tastes bland or watery", "likely_cause": "Insufficient salt or lack of acidity", "prevention": "Use good quality stock and season in layers", "fix": "Add salt 1g at a time; add the optional lemon juice or a dash of vinegar; grate parmesan cheese on top"}, {"symptom": "Pasta is mushy", "likely_cause": "Overcooked or added too early", "prevention": "Add pasta only in the final 10-12 minutes of cooking", "fix": "Cannot be fixed strictly, but serving immediately prevents further softening"}]', '["The ''soffritto'' (onion, carrot, celery) is the foundation of flavor. Do not rush step 1; sweating these vegetables slowly releases sweetness that balances the tomatoes.", "If you plan to freeze the soup, omit the pasta during the cooking process. Cook pasta separately and add it to bowls upon serving to prevent it from disintegrating in the freezer.", "A parmesan rind is a secret weapon for Italian soups. It releases umami and thickens the broth slightly without making it cheesy. Save your rinds in the freezer for this exact purpose.", "This recipe is infinitely adaptable. Hard root vegetables go in with the potatoes; softer vegetables like green beans or peas go in with the zucchini."]', '"Minestrone is the quintessential Italian peasant soup (''cucina povera''), historically designed to use up leftover vegetables and stale pasta. There is no single ''correct'' recipe, as it varies by region and season\u2014lighter in spring with peas and broad beans, heavier in winter with root vegetables and beans."', 384.2);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('5ef97ba1-9a4c-4720-8989-1a0fa4d4553c', 'Home-Cured Maple Pork Tenderloin Ham', 'A transformative charcuterie project converting a humble pork tenderloin into a sweet-savory, rosy-pink ham. The lean meat cures quickly in a maple-infused brine, resulting in a tender texture perfect for slicing thin on holidays or searing for breakfast.', 'main course', 'American', 'Intermediate', '["project", "ham", "pork", "breakfast", "brunch", "dinner", "lunch", "appetizer", "main course", "christmas", "new year''s day"]', '[{"group_name": "The Meat", "items": [{"name": "pork tenderloin", "quantity": 500, "unit": "g", "preparation": "trimmed of silverskin", "notes": "one whole fillet", "substitutions": [], "ingredient_id": "1f451df4-63db-4326-97e6-9e8a9aef9a64", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Curing Brine", "items": [{"name": "water", "quantity": 500, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "kosher salt", "quantity": 25, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "maple syrup", "quantity": 30, "unit": "g", "preparation": null, "notes": "real maple syrup preferred", "substitutions": ["brown sugar"], "ingredient_id": "c9ca1f35-b107-46c2-92a3-4c1c620f3c11", "nutrition_source": "USDA FoodData Central"}, {"name": "prague powder #1", "quantity": 1.5, "unit": "g", "preparation": null, "notes": "pink curing salt; crucial for ham flavor and safety", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black peppercorns", "quantity": 2, "unit": "g", "preparation": "whole", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "bay leaf", "quantity": 1, "unit": null, "preparation": "dried", "notes": null, "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "smashed", "notes": null, "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Glaze (Optional)", "items": [{"name": "maple syrup", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c9ca1f35-b107-46c2-92a3-4c1c620f3c11", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the brine by combining 250ml of the water with salt, maple syrup, Prague Powder #1, peppercorns, bay leaf, and garlic in a saucepan. Heat over medium until salts dissolve completely.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Remove brine from heat and add the remaining 250ml of cold water to lower the temperature. Chill in the refrigerator until the liquid is completely cold (below 4\u00b0C/40\u00b0F). Never add raw meat to hot brine.", "structured": {"action": "COOL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": null, "doneness_cues": null}, "tips": ["To speed up cooling, replace the remaining water with 250g of ice."]}, {"step_number": 3, "phase": "prep", "text": "Place the trimmed pork tenderloin in a non-reactive container or resealable bag. Pour the cold brine over it, ensuring the meat is fully submerged. Seal and refrigerate for 24 to 48 hours. Turn the bag once halfway through.", "structured": {"action": "BRINE", "temperature": null, "duration": "P2D", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Remove pork from brine and rinse thoroughly under cold water to remove excess surface salt. Pat very dry with paper towels. Place on a wire rack uncovered in the fridge for 2-4 hours to form a pellicle (a tacky surface layer).", "structured": {"action": "PAT_DRY", "temperature": null, "duration": "PT2H", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Preheat oven to 110\u00b0C/225\u00b0F. Place the pork on a wire rack over a baking sheet. Bake until the internal temperature reaches 63\u00b0C/145\u00b0F. If using glaze, brush it on during the last 10 minutes.", "structured": {"action": "ROAST", "temperature": {"celsius": 110, "fahrenheit": 230}, "duration": null, "doneness_cues": {"visual": "Internal thermometer reads target temp", "tactile": "Firm but yielding"}}, "tips": ["Low and slow cooking ensures the texture remains tender and ham-like.", "Alternatively, smoke at the same temperature with apple or hickory wood."]}, {"step_number": 6, "phase": "finish", "text": "Remove from oven and let rest for at least 20 minutes before slicing. The meat will be pink; this is the result of the curing salt, not undercooking.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "P1D2H", "total_time": "P1D2H30M", "overnight_required": true, "yields": "1 cured tenderloin", "yield_count": 4, "serving_size_g": 125}', '{"flags": ["Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Individuals sensitive to nitrites"]}', '{"per_serving": {"calories": 173.05, "protein_g": 21.73, "carbohydrates_g": 10.85, "fat_g": 4.88, "saturated_fat_g": 1.46, "trans_fat_g": null, "monounsaturated_fat_g": 1.82, "polyunsaturated_fat_g": 1.32, "fiber_g": 0.27, "sugar_g": 6.99, "sodium_mg": 3345.78, "cholesterol_mg": 58.75, "potassium_mg": 774.4, "calcium_mg": 42.71, "iron_mg": 1.65, "magnesium_mg": 31.34, "phosphorus_mg": 2.6, "zinc_mg": 1.87, "vitamin_a_mcg": 0.91, "vitamin_c_mg": 2.18, "vitamin_d_mcg": null, "vitamin_e_mg": 0.01, "vitamin_k_mcg": 0.84, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.14, "niacin_mg": 0.02, "folate_mcg": 0.12, "water_g": 222.28, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store tightly wrapped or vacuum sealed.", "duration": "P1W"}, "freezer": {"notes": "Best frozen as a whole piece rather than slices to prevent drying.", "duration": "P3M"}, "reheating": "Gentle pan-fry or eat cold.", "does_not_keep": false}', '[{"name": "Non-reactive container", "required": true, "alternative": "Large resealable plastic bag"}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Wire rack and baking sheet", "required": true, "alternative": null}, {"name": "Digital meat thermometer", "required": true, "alternative": null}, {"name": "Kitchen scale", "required": true, "alternative": "Standard measuring cups (less precise)"}]', '[{"symptom": "Meat is gray inside instead of pink", "likely_cause": "The curing brine did not penetrate to the center", "prevention": "Ensure the full 48-hour cure time for thick tenderloins", "fix": "Meat is still safe to eat as roast pork, but lacks ham flavor"}, {"symptom": "Ham is too salty", "likely_cause": "Meat was not rinsed well enough after brining", "prevention": "Soak the cured meat in fresh water for 30 minutes before roasting", "fix": "Serve with unsalted sides or in a dish with creamy sauce"}]', '["Prague Powder #1 (Pink Curing Salt) is non-negotiable for this recipe. It prevents botulism during low-temp cooking and provides the distinct ''ham'' flavor and color.", "Do not confuse Prague Powder #1 with Himalayan pink salt; they are chemically different and not interchangeable.", "Trim the silverskin (the tough white connective tissue) completely before curing, or the ham will curl and be chewy.", "This ''ham'' makes incredible Eggs Benedict or can be diced into omelets.", "For a festive presentation, roll the tenderloin in cracked black pepper or dried herbs before roasting."]', '"While traditional hams are made from the hind leg of the pig and cured for weeks, this ''quick ham'' utilizes the tenderloin (often called Canadian Bacon when smoked) to replicate the flavor profile in a fraction of the time. It brings the preservation techniques of European charcuterie into the modern home kitchen."', 173.05);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('5fd4cd51-4f89-433e-a28e-527aad2d6b2f', 'Glazed Meatloaf Burgers', 'All the comfort of a classic Sunday meatloaf condensed into a juicy, seared patty. These burgers feature a tender crumb-soaked interior and are finished with a sticky, tangy tomato-brown sugar glaze that caramelizes on the grill or skillet.', 'dinner', 'American', 'Easy', '["american", "burgers", "bacon", "beef", "dijon mustard", "ground beef", "ketchup", "dinner", "easy", "lunch", "quick", "weeknight", "main course"]', '[{"group_name": "Meatloaf Patties", "items": [{"name": "ground beef (80/20)", "quantity": 500, "unit": "g", "preparation": "chilled", "notes": "higher fat content ensures juicy burgers", "substitutions": [], "ingredient_id": "6c7cf0a4-a53c-415a-8d1c-7c1fc55d1d95", "nutrition_source": "USDA FoodData Central"}, {"name": "panko breadcrumbs", "quantity": 40, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84fbc204-4457-40ed-83c1-3e5a7bcd8f23", "nutrition_source": "Aggregated Public Data"}, {"name": "whole milk", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "onion", "quantity": 0.5, "unit": null, "preparation": "finely grated or minced", "notes": "approx 60g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": null, "notes": "large size, approx 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "worcestershire sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "aa552099-60a9-4267-a732-5870a271c28f", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Tangy Glaze", "items": [{"name": "ketchup", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "9b0c1201-83fa-43c7-b2a4-66c400bcb0fd", "nutrition_source": "Aggregated Public Data"}, {"name": "brown sugar", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "apple cider vinegar", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Assembly", "items": [{"name": "bacon slices", "quantity": 4, "unit": null, "preparation": "cooked crispy", "notes": "optional topping", "substitutions": [], "ingredient_id": "339a356e-8f77-48fe-9293-b8e35fed3e6c", "nutrition_source": "USDA FoodData Central"}, {"name": "burger buns", "quantity": 4, "unit": null, "preparation": "toasted", "notes": null, "substitutions": [], "ingredient_id": "3e054cb4-7cda-44f0-8b28-6066c1dfddaa", "nutrition_source": "Aggregated Public Data"}, {"name": "neutral oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "for frying", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a large mixing bowl, combine the breadcrumbs and milk. Let this mixture (a panade) sit for 5 minutes until the breadcrumbs absorb the liquid and become mushy. This ensures the burgers remain tender.", "structured": {"action": "SOAK", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "While the panade rests, whisk together the ketchup, brown sugar, Dijon mustard, and apple cider vinegar in a small bowl to create the glaze. Set aside.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Add the ground beef, grated onion, minced garlic, egg, Worcestershire sauce, salt, and pepper to the bowl with the soaked breadcrumbs. Gently mix with your hands just until combined. Do not overwork the meat.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Divide the mixture into 4 equal portions. Shape them into patties slightly wider than your buns, making a small indentation in the center of each with your thumb to prevent them from puffing up into balls during cooking.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Heat the neutral oil in a cast iron skillet over medium-high heat. Once the oil shimmers, add the patties. Cook for 4-5 minutes on the first side until a deep brown crust forms.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Flip the patties. Immediately brush a generous amount of the prepared glaze onto the seared side. Cook for another 3-4 minutes. If using cheese (optional), add it now over the glaze.", "structured": {"action": "GLAZE", "temperature": null, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Verify doneness. The internal temperature should reach 71\u00b0C/160\u00b0F for safe consumption of ground beef. The glaze should be sticky and caramelized.", "structured": {"action": "CHECK_TEMP", "temperature": {"celsius": 71, "fahrenheit": 160}, "duration": null, "doneness_cues": {"visual": "Glaze is bubbly and sticky", "tactile": "Patty is firm to touch"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove patties from the heat and let them rest for 5 minutes. Assemble on toasted buns with crispy bacon and extra glaze if desired.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT5M", "total_time": "PT30M", "overnight_required": false, "yields": "4 burgers", "yield_count": 4, "serving_size_g": 210}', '{"flags": ["Nut-Free", "Peanut-Free"], "not_suitable_for": ["Gluten intolerant (breadcrumbs)", "Vegans"]}', '{"per_serving": {"calories": 645.78, "protein_g": 30.49, "carbohydrates_g": 30.53, "fat_g": 35.34, "saturated_fat_g": 12.1, "trans_fat_g": 1.48, "monounsaturated_fat_g": 13.37, "polyunsaturated_fat_g": 1.37, "fiber_g": 1.34, "sugar_g": 11.15, "sodium_mg": 1124.7, "cholesterol_mg": 146.38, "potassium_mg": 528.24, "calcium_mg": 94.47, "iron_mg": 3.99, "magnesium_mg": 30.52, "phosphorus_mg": 289.94, "zinc_mg": 5.8, "vitamin_a_mcg": 44.42, "vitamin_c_mg": 3.04, "vitamin_d_mcg": 0.57, "vitamin_e_mg": 0.39, "vitamin_k_mcg": 3.25, "vitamin_b6_mg": 0.49, "vitamin_b12_mcg": 2.96, "thiamin_mg": 0.11, "riboflavin_mg": 0.3, "niacin_mg": 6.3, "folate_mcg": 18.57, "water_g": 116.63, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store patties separate from buns to prevent sogginess.", "duration": "P3D"}, "freezer": {"notes": "Freeze raw patties on parchment paper before bagging.", "duration": "P3M"}, "reheating": "Reheat gently in a skillet with a splash of water, covered, to steam through without drying.", "does_not_keep": false}', '[{"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Cast iron skillet or griddle", "required": true, "alternative": "Heavy-bottomed non-stick pan"}, {"name": "Spatula", "required": true, "alternative": null}, {"name": "Pastry brush", "required": true, "alternative": "Spoon"}]', '[{"symptom": "Burgers are tough or rubbery", "likely_cause": "The meat mixture was overmixed, developing the protein strands too much", "prevention": "Mix gently with your hands only until ingredients are just incorporated", "fix": "Cannot be fixed, serve with extra sauce to mask texture"}, {"symptom": "Patties fall apart in the pan", "likely_cause": "Panade (milk/bread mixture) was too wet or patties weren''t compacted enough", "prevention": "Ensure breadcrumbs fully absorb the milk; if mixture feels too wet, add dry breadcrumbs teaspoon by teaspoon", "fix": "Press pieces together and melt cheese over the top to bind them visually"}]', '["The ''panade'' (milk and breadcrumb paste) is the secret to keeping these burgers moist, mimicking the texture of a slow-baked meatloaf in a fraction of the time.", "Grating the onion instead of chopping it allows the onion flavor to permeate the meat more evenly and prevents raw crunchy bits in the quickly cooked burger.", "Do not skip the resting period; cutting into the burger immediately will cause all the juices to run out, resulting in a dry patty.", "For a true diner-style experience, butter and griddle your buns until golden brown before assembly."]', '"Meatloaf is an icon of mid-20th-century American comfort food, born from the Great Depression necessity of stretching protein with fillers like grains. This recipe adapts that Sunday dinner staple into the ubiquitous American burger format, bridging the gap between slow-cooked comfort and fast-food convenience."', 645.78);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('60bc33b9-b8fd-40d6-b692-5648f281fa0a', 'Blistered & Smashed Cherry Tomato Salad', 'Sweet cherry tomatoes are charred under high heat until bursting, then gently crushed to release their warm juices into a vibrant vinaigrette. A rustic, intensely flavorful side that balances smoky sweetness with bright acidity and fresh herbs.', 'side dish', 'Mediterranean', 'Easy', '["five ingredient", "tomato", "dinner", "easy", "lunch", "quick", "side", "summer", "vegetarian", "vegan", "gluten-free"]', '[{"group_name": "Vegetables", "items": [{"name": "cherry tomatoes", "quantity": 500, "unit": "g", "preparation": "whole", "notes": "mixture of colors preferred", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh basil leaves", "quantity": 15, "unit": "g", "preparation": "torn", "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pantry & Dressing", "items": [{"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": "divided use", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "sherry vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["red wine vinegar", "balsamic vinegar"], "ingredient_id": "dcfa7371-7051-4604-a76e-4a46ae1f9e7b", "nutrition_source": "Aggregated Public Data"}, {"name": "flaky sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 3g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Move the oven rack to the highest position (about 10-15cm from the element) and preheat the broiler to high.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 260, "fahrenheit": 500}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "On a rimmed baking sheet, toss the whole cherry tomatoes with 15ml of the olive oil and a pinch of salt. Ensure they are in a single layer.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Broil the tomatoes until the skins are blistered, blackened in spots, and some have begun to burst, approximately 5 to 8 minutes. Watch closely to prevent total incineration.", "structured": {"action": "BROIL", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Skins blackened and split", "tactile": "Tomatoes are soft and collapsing"}}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "While tomatoes broil, whisk the remaining 30ml olive oil, sherry vinegar, minced garlic, and black pepper in a large heat-proof bowl.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Transfer the hot tomatoes and all accumulated juices from the baking sheet directly into the bowl with the dressing. The heat of the tomatoes will mellow the raw garlic.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Using a potato masher or fork, gently squash the tomatoes until they flatten and release more juice, creating a rustic sauce. Fold in the torn basil and serve immediately.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT10M", "total_time": "PT20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 140}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Paleo", "Whole30", "Low-Carb", "Keto"], "not_suitable_for": []}', '{"per_serving": {"calories": 128.34, "protein_g": 1.34, "carbohydrates_g": 6.69, "fat_g": 11.54, "saturated_fat_g": 1.6, "trans_fat_g": null, "monounsaturated_fat_g": 8.22, "polyunsaturated_fat_g": 1.21, "fiber_g": 2.4, "sugar_g": 4.91, "sodium_mg": 299.54, "cholesterol_mg": null, "potassium_mg": 316.83, "calcium_mg": 23.25, "iron_mg": 0.96, "magnesium_mg": 16.96, "phosphorus_mg": 34.79, "zinc_mg": 0.26, "vitamin_a_mcg": 9.97, "vitamin_c_mg": 18.27, "vitamin_d_mcg": null, "vitamin_e_mg": 1.65, "vitamin_k_mcg": 22.77, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": null, "thiamin_mg": null, "riboflavin_mg": 0.01, "niacin_mg": 0.05, "folate_mcg": 2.64, "water_g": 4.37, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves after resting, but basil may discolor. Store in an airtight container.", "duration": "P3D"}, "freezer": {"notes": "Texture degrades significantly upon thawing; do not freeze.", "duration": null}, "reheating": "Serve at room temperature or gently warm in a pan over low heat.", "does_not_keep": false}', '[{"name": "Rimmed baking sheet", "required": true, "alternative": "Cast iron skillet"}, {"name": "Oven with broiler function", "required": true, "alternative": null}, {"name": "Potato masher", "required": true, "alternative": "Large fork"}, {"name": "Mixing bowl", "required": true, "alternative": null}]', '[{"symptom": "Tomatoes are raw inside but burnt outside", "likely_cause": "Broiler was too close or tomatoes were very large/cold", "prevention": "Use room temperature tomatoes; lower rack slightly for larger tomatoes", "fix": "Finish baking at 200\u00b0C/400\u00b0F for 3-5 minutes on a lower rack"}, {"symptom": "Sauce is too watery", "likely_cause": "Tomatoes had very high water content", "prevention": "None (seasonal variance)", "fix": "Serve with crusty bread to soak it up, or strain juice and reduce in a small pan"}]', '["Sherry vinegar is preferred over balsamic here as it provides acidity without overwhelming the sweetness of the tomatoes with too much sugar.", "Do not skip the bread; the ''pot liquor'' created by the tomato water and olive oil is the best part of the dish.", "If using a cast iron skillet, you can serve the dish directly in the skillet for a rustic presentation, adding the dressing to the pan instead of a bowl.", "This technique works best with ripe, in-season tomatoes. If using winter supermarket tomatoes, add a pinch of sugar to the dressing."]', '"This preparation draws on Mediterranean traditions where vegetables are often treated with high heat to concentrate flavor, then dressed simply with high-quality oil and vinegar. It mimics the flavor profile of ''Pan con Tomate'' but in a deconstructed, salad-like format."', 128.34);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('60d2a5ef-c43e-479c-8027-85e603fcaece', 'Traditional Scottish Tablet', 'A beloved Scottish confection often mistaken for fudge, but distinguished by its brittle, crumbly texture and intense sweetness. It melts in the mouth with a sandy, crystalline finish and rich caramel notes.', 'confection', 'Scottish', 'Intermediate', '["confectionery", "dessert", "sweet", "scottish", "traditional", "gift"]', '[{"group_name": "Base", "items": [{"name": "caster sugar", "quantity": 900, "unit": "g", "preparation": "white", "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 250, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "sweetened condensed milk", "quantity": 397, "unit": "g", "preparation": null, "notes": "1 standard tin", "substitutions": [], "ingredient_id": "d79dd43f-17cf-4dcc-a208-fa7b0ad13461", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Grease a deep baking tray (approximately 30cm x 20cm) generously with butter.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a large, heavy-bottomed saucepan, combine the caster sugar and whole milk. Heat gently over low heat, stirring occasionally, until the sugar has completely dissolved. Do not let it boil until no sugar crystals remain on the spoon.", "structured": {"action": "SIMMER", "temperature": {"celsius": 60, "fahrenheit": 140}, "duration": null, "doneness_cues": null}, "tips": ["Rub a little mixture between your fingers; if it feels gritty, keep heating gently."]}, {"step_number": 3, "phase": "cook", "text": "Add the butter and sweetened condensed milk to the pan. Increase heat to medium-high and bring to a boil while stirring constantly to prevent sticking.", "structured": {"action": "BOIL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Boil the mixture vigorously until it reaches 120\u00b0C (248\u00b0F) on a candy thermometer (soft-ball stage). You must stir constantly, scraping the bottom of the pot, as the mixture will darken and can easily burn.", "structured": {"action": "BOIL", "temperature": {"celsius": 120, "fahrenheit": 248}, "duration": "PT15M", "doneness_cues": {"visual": "Mixture turns a light caramel color and thickens significantly", "tactile": "Soft ball forms when dropped in cold water"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove the pan from the heat immediately. Allow the mixture to settle for 2-3 minutes.", "structured": {"action": "REST", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Add vanilla extract (if using) and beat the mixture vigorously with a wooden spoon or electric hand mixer. Continue beating for 5-10 minutes until the mixture thickens, loses its glossy shine, becomes matte/opaque, and feels slightly gritty.", "structured": {"action": "BEAT", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Changes from glossy caramel to matte light brown", "tactile": "Feels sandy and thick against the spoon"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Quickly pour the mixture into the prepared tin before it sets completely. Tilt the tin to level it out; do not scrape the very bottom of the pot if it looks burnt.", "structured": {"action": "POUR", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Let it cool for about 20-30 minutes until firm but still slightly warm. Score into squares with a sharp knife.", "structured": {"action": "SCORE", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Allow to cool completely in the tin (at least 3-4 hours) before removing and breaking along the scored lines.", "structured": {"action": "COOL", "temperature": null, "duration": "PT4H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT4H", "total_time": "PT4H45M", "overnight_required": false, "yields": "64 pieces", "yield_count": 64, "serving_size_g": 25}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Egg-Free"], "not_suitable_for": ["Diabetics"]}', '{"per_serving": {"calories": 89.83, "protein_g": 0.63, "carbohydrates_g": 17.64, "fat_g": 2.12, "saturated_fat_g": 0.98, "trans_fat_g": null, "monounsaturated_fat_g": 0.45, "polyunsaturated_fat_g": 0.06, "fiber_g": 0, "sugar_g": 17.62, "sodium_mg": 2.03, "cholesterol_mg": 4.25, "potassium_mg": 25.21, "calcium_mg": 21.12, "iron_mg": 0.01, "magnesium_mg": 0.44, "phosphorus_mg": 3.72, "zinc_mg": 0.02, "vitamin_a_mcg": 14.09, "vitamin_c_mg": null, "vitamin_d_mcg": 0.05, "vitamin_e_mg": 0.04, "vitamin_k_mcg": 0.14, "vitamin_b6_mg": null, "vitamin_b12_mcg": 0.02, "thiamin_mg": null, "riboflavin_mg": 0.01, "niacin_mg": null, "folate_mcg": 0.25, "water_g": 3.78, "alcohol_g": 0.03, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"duration": null}, "freezer": {"duration": null}, "reheating": "Do not reheat.", "does_not_keep": false}', '[{"name": "Large heavy-bottomed saucepan", "required": true, "alternative": "Preserving pan"}, {"name": "Wooden spoon", "required": true, "alternative": null}, {"name": "Candy thermometer", "required": true, "alternative": "Cold water test method"}, {"name": "Baking tray (approx 30x20cm)", "required": true, "alternative": null}, {"name": "Electric hand mixer", "required": false, "alternative": "Strong arm and wooden spoon"}]', '[{"symptom": "Tablet didn''t set (too soft or runny)", "likely_cause": "The mixture did not reach the correct temperature (120\u00b0C) during the boiling phase.", "prevention": "Use a reliable candy thermometer and ensure it hits the full soft-ball stage.", "fix": "Scrape back into the pot, add a splash of milk, and re-boil to 120\u00b0C, then re-beat."}, {"symptom": "Burnt specks in the final product", "likely_cause": "The high sugar content caught on the bottom of the pan during the boil.", "prevention": "Use a heavy-bottomed pot and stir constantly, ensuring you scrape the entire base.", "fix": "Do not scrape the burnt layer into the tray when pouring; leave the bottom layer in the pot."}]', '["The ''beating'' phase is the most critical step. This process creates small sugar crystals, giving tablet its signature sandy texture rather than the smooth texture of fudge.", "Be extremely careful when boiling sugar; sugar burns are severe. Keep a bowl of ice water nearby for emergencies.", "If using whisky for flavoring, add 30ml alongside the butter, but be aware it may slightly lower the boiling point, so ensure you hit 120\u00b0C firmly.", "Clean your pot immediately by filling it with water and boiling it; the hardened sugar will dissolve effortlessly."]', '"Tablet is a Scottish culinary institution dating back to the early 18th century. Unlike English fudge, which is soft and pliable, tablet is semi-hard and brittle due to its crystallization process. It is a staple at Scottish weddings, celebrations, and tea times."', 89.83);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('61e3abcd-ed03-458d-ad50-a758e8f3a76f', 'Crispy Brown Butter Parsnip Ribbons', 'Earth meets elegance in this simple side dish where the natural nutty sweetness of parsnips is intensified by frying them into delicate, golden ribbons. Finished with a toss of rich butter and sea salt, they offer a satisfying crunch comparable to potato chips but with a complex, autumnal flavor profile.', 'side dish', 'British', 'Easy', '["butter", "five ingredient", "parsnip", "easy", "quick", "side dish", "fall", "vegetarian"]', '[{"group_name": "Vegetables", "items": [{"name": "parsnips", "quantity": 500, "unit": "g", "preparation": "washed and scrubbed", "notes": "choose medium-sized parsnips", "substitutions": [], "ingredient_id": "34436869-220b-4f51-85a9-71ea344acc17", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Frying & Seasoning", "items": [{"name": "neutral vegetable oil", "quantity": 500, "unit": "ml", "preparation": null, "notes": "for shallow frying (grapeseed or canola)", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt flakes", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 5g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme leaves", "quantity": 2, "unit": "g", "preparation": null, "notes": "optional, stripped from stem", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Using a vegetable peeler, peel the outer skin of the parsnips and discard. Continue peeling the parsnip lengthways to create long, thin ribbons. Rotate the parsnip as you work. Stop when you reach the woody central core.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Pat the parsnip ribbons thoroughly dry with paper towels. Excess moisture will lower the oil temperature and prevent crisping.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Pour the vegetable oil into a large high-sided skillet to a depth of about 2cm. Heat over medium-high heat until the oil reaches 175\u00b0C/350\u00b0F. If you don''t have a thermometer, a test ribbon should sizzle vigorously immediately upon contact.", "structured": {"action": "HEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Fry the ribbons in small batches to avoid overcrowding the pan. Cook for 2-3 minutes, turning occasionally with a slotted spoon, until they are curled, crisp, and golden brown.", "structured": {"action": "FRY", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown and curled", "tactile": "Rigid and crisp"}}, "tips": ["Do not walk away; parsnips have high sugar content and can burn in seconds."]}, {"step_number": 5, "phase": "cook", "text": "Remove fried parsnips with a slotted spoon and drain on a paper towel-lined plate or wire rack.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "While the parsnips are still hot, add the butter to the hot pan (after turning off the heat) or melt separately, and lightly drizzle over the crisps, then immediately season generously with sea salt and fresh thyme leaves.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 100}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 148.03, "protein_g": 1.59, "carbohydrates_g": 22.63, "fat_g": 6.47, "saturated_fat_g": 3.85, "trans_fat_g": null, "monounsaturated_fat_g": 1.89, "polyunsaturated_fat_g": 0.29, "fiber_g": 6.2, "sugar_g": 6.01, "sodium_mg": 498.37, "cholesterol_mg": 16.13, "potassium_mg": 473.7, "calcium_mg": 49.13, "iron_mg": 0.83, "magnesium_mg": 37.21, "phosphorus_mg": 91.08, "zinc_mg": 0.76, "vitamin_a_mcg": 52.49, "vitamin_c_mg": 22.05, "vitamin_d_mcg": null, "vitamin_e_mg": 2.04, "vitamin_k_mcg": 28.65, "vitamin_b6_mg": 0.12, "vitamin_b12_mcg": 0.01, "thiamin_mg": 0.11, "riboflavin_mg": 0.07, "niacin_mg": 0.89, "folate_mcg": 84.2, "water_g": 100.92, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Not recommended; texture will become soggy immediately.", "duration": null}, "freezer": {"notes": "Do not freeze.", "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Y-Peeler or Vegetable Peeler", "required": true, "alternative": "Mandoline slicer"}, {"name": "Large high-sided skillet or Dutch oven", "required": true, "alternative": null}, {"name": "Slotted spoon or spider strainer", "required": true, "alternative": null}, {"name": "Paper towels", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": false, "alternative": null}]', '[{"symptom": "Parsnips are soggy or limp", "likely_cause": "Oil temperature was too low or pan was overcrowded", "prevention": "Monitor temperature with a thermometer and fry in smaller batches", "fix": "Refry briefly at proper temperature, though texture may be compromised"}, {"symptom": "Parsnips taste burnt", "likely_cause": "High sugar content in the vegetable caramelized too quickly", "prevention": "Remove from oil the moment they turn light gold; they continue cooking slightly after removal", "fix": "Cannot be fixed"}]', '["The core of large parsnips can be woody and fibrous. Stop peeling when you feel resistance or see a distinct textural change in the center.", "Seasoning immediately while the oil is still on the surface helps the salt adhere to the chips.", "For a deeper flavor profile, you can brown the butter separately before drizzling, adding a nutty aroma that complements the parsnips.", "Ensure the parsnips are as dry as possible before frying to prevent dangerous oil splatter."]', '"Parsnips are a quintessential cool-weather root vegetable, historically a staple in Europe before the arrival of the potato. This preparation highlights their natural sweetness, a technique often seen in modern British gastropubs as a garnish or refined bar snack."', 148.03);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('62eb0f2e-d7ca-4782-b88e-38b1ebb45225', 'Late Summer Trio Refrigerator Jam', 'A vibrant, low-commitment small-batch jam that captures the fleeing flavors of summer. Sweet nectarines, honeyed figs, and tart blueberries melt together with a hint of balsamic vinegar. No canning equipment required; this is designed for immediate gratification.', 'preserve', 'French', 'Easy', '["condiments", "dips and spreads", "blueberry", "fig", "nectarine", "quick", "side dish", "summer", "gluten-free", "vegan"]', '[{"group_name": "Fruit Base", "items": [{"name": "fresh nectarines", "quantity": 250, "unit": "g", "preparation": "pitted and diced small", "notes": "about 2 medium fruits, skin on", "substitutions": [], "ingredient_id": "d699ed69-8d97-460f-8fbb-99b73a9fbf19", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh blueberries", "quantity": 150, "unit": "g", "preparation": "washed and dried", "notes": null, "substitutions": [], "ingredient_id": "0f9f22a4-4f00-4950-9145-943d55b6dec8", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh figs", "quantity": 100, "unit": "g", "preparation": "stems removed and chopped", "notes": "about 2-3 large figs", "substitutions": [], "ingredient_id": "a61155f9-cf75-4c40-89b1-8e7092290e2c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Flavor & Structure", "items": [{"name": "granulated sugar", "quantity": 200, "unit": "g", "preparation": null, "notes": "adjust to 150g for tarter jam", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": "about half a lemon", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "balsamic vinegar", "quantity": 10, "unit": "ml", "preparation": null, "notes": "adds depth to the figs", "substitutions": [], "ingredient_id": "767611a6-b108-4513-ae14-89e4de084388", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "tiny pinch to pop flavor", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine the diced nectarines, blueberries, chopped figs, sugar, lemon juice, and salt in a heavy-bottomed saucepan. Stir well to coat the fruit in sugar.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Let the mixture sit at room temperature for 10-15 minutes to macerate. This draws out the juices and helps dissolve the sugar before cooking.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Place the saucepan over medium-high heat. Bring the mixture to a rolling boil while stirring frequently to prevent scorching.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": {"visual": "Sugar is fully dissolved and mixture is bubbling vigorously", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Reduce heat to medium-low to maintain a steady simmer. Cook for 15-20 minutes, stirring occasionally. As the fruit softens, use a potato masher or fork to crush the nectarines and blueberries to your desired consistency.", "structured": {"action": "SIMMER", "temperature": {"celsius": 104, "fahrenheit": 219}, "duration": "PT20M", "doneness_cues": null}, "tips": ["If you prefer a chunky jam, skip the mashing.", "The figs will naturally break down more than the nectarines."]}, {"step_number": 5, "phase": "finish", "text": "Check the consistency. The jam should coat the back of a spoon and drip slowly. If using balsamic vinegar, stir it in now and cook for 1 additional minute.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove from heat and transfer immediately to a clean glass jar. Let it cool completely to room temperature before sealing and refrigerating. It will thicken significantly as it cools.", "structured": {"action": "COOL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT1H", "total_time": "PT1H15M", "overnight_required": false, "yields": "400g (approx 1.5 cups)", "yield_count": 26, "serving_size_g": 15}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 40.6, "protein_g": 0.18, "carbohydrates_g": 10.39, "fat_g": 0.06, "saturated_fat_g": 0.01, "trans_fat_g": null, "monounsaturated_fat_g": 0.01, "polyunsaturated_fat_g": 0.02, "fiber_g": 0.42, "sugar_g": 9.8, "sodium_mg": 15.33, "cholesterol_mg": null, "potassium_mg": 34.56, "calcium_mg": 2.66, "iron_mg": 0.07, "magnesium_mg": 2.02, "phosphorus_mg": 3.97, "zinc_mg": 0.03, "vitamin_a_mcg": 2.08, "vitamin_c_mg": 1.38, "vitamin_d_mcg": null, "vitamin_e_mg": 0.11, "vitamin_k_mcg": 1.51, "vitamin_b6_mg": 0.01, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.01, "niacin_mg": 0.15, "folate_mcg": 1.17, "water_g": 16.86, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Keep in a clean, airtight jar.", "duration": "P3W"}, "freezer": {"notes": "Leave 2cm headspace in jar for expansion.", "duration": "P3M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Heavy-bottomed saucepan", "required": true, "alternative": null}, {"name": "Wooden spoon or silicone spatula", "required": true, "alternative": null}, {"name": "Potato masher", "required": false, "alternative": "Fork"}, {"name": "Glass jar with lid", "required": true, "alternative": null}]', '[{"symptom": "Jam is too runny after cooling", "likely_cause": "Did not cook long enough to evaporate excess water", "prevention": "Perform the ''frozen plate test'' (put a drop on a cold plate; if it wrinkles when pushed, it is ready) before stopping heat", "fix": "Pour back into pot and simmer for another 5-10 minutes"}]', '["This trio works because of the texture variance: nectarines provide body (pectin), blueberries give color and acidity, and figs add a luxurious, jammy sweetness.", "Do not reduce the sugar by more than 20%. Sugar is not just for sweetness; it is essential for the gel structure and preservation, even for short-term fridge jams.", "Serve this on a cheese board with brie or goat cheese for a savory application, or swirl into yogurt for breakfast.", "Leaving the skins on the nectarines adds a beautiful sunset-orange hue and reduces prep time."]', '"While fruit preserves have been a method of survival for centuries, the ''refrigerator jam'' represents a modern culinary shift toward freshness over longevity. This specific combination mimics the harvest crossover in late August and early September in temperate climates, where stone fruits overlap with late berries and the first crop of autumn figs."', 40.6);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('637157f4-b774-4ca8-b307-665723935c69', 'Potato and Sorrel Gratin Pie', 'A rustic, savory dish bridging the gap between a creamy gratin and a structured vegetable pie. The bright, lemony acidity of fresh sorrel cuts through the richness of the egg-and-cheese custard, while thin layers of potato provide a tender foundation. It slices beautifully after resting.', 'side dish', 'French', 'Intermediate', '["mediterranean", "dinner", "lunch", "fall", "winter", "gluten-free", "halal", "healthy", "kosher", "low sugar", "nut-free", "vegetarian"]', '[{"group_name": "Vegetables", "items": [{"name": "waxy potatoes (yukon gold or charlotte)", "quantity": 1000, "unit": "g", "preparation": "peeled and sliced 3mm thick", "notes": "Avoid starchy russets if possible", "substitutions": [], "ingredient_id": "a9d640ff-a969-4f0a-9a92-974f376ac272", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh sorrel leaves", "quantity": 200, "unit": "g", "preparation": "washed, stems removed, shredded", "notes": "Substitute spinach with lemon zest if unavailable", "substitutions": [], "ingredient_id": "765ed343-bfc0-4671-9d31-fb127e371872", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "halved", "notes": "approx 5g, for rubbing the dish", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Custard Base", "items": [{"name": "large eggs", "quantity": 4, "unit": null, "preparation": null, "notes": "approx 200g total weight", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "whole milk", "quantity": 250, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 100, "unit": "ml", "preparation": null, "notes": "35% fat or higher", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "nutmeg", "quantity": null, "unit": null, "preparation": null, "notes": "freshly grated, to taste (approx 1/4 tsp)", "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 6, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Cheese & Finish", "items": [{"name": "gruy\u00e8re cheese", "quantity": 150, "unit": "g", "preparation": "grated", "notes": "Use vegetarian rennet version if strictly vegetarian", "substitutions": [], "ingredient_id": "321085d2-bb82-45e1-8ae3-5a2ef5cea47f", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 20, "unit": "g", "preparation": "softened", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 180\u00b0C/355\u00b0F. Rub the inside of the baking dish vigorously with the cut side of the garlic clove, then grease generously with the softened butter.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Peel the potatoes and slice them into uniform rounds approximately 3mm thick. Do not rinse the slices after cutting, as the starch helps bind the layers.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Wash the sorrel, remove tough central ribs, and slice into ribbons (chiffonade). In a bowl, whisk together the eggs, milk, cream, salt, pepper, and nutmeg until fully combined.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Arrange a layer of potato slices in the bottom of the dish, slightly overlapping. Scatter a handful of sorrel ribbons and a sprinkling of grated Gruy\u00e8re over the potatoes. Repeat this layering process until all vegetables are used, finishing with a neat layer of potatoes topped with the remaining cheese.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Slowly pour the egg and milk mixture over the layered potatoes. Tilt the dish gently from side to side to ensure the liquid penetrates to the bottom layers. Press down gently with a spatula.", "structured": {"action": "POUR", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Bake in the preheated oven for 45-50 minutes. The top should be deep golden brown, and a knife inserted into the center should meet no resistance from the potatoes.", "structured": {"action": "BAKE", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT50M", "doneness_cues": {"visual": "Deep golden brown top", "tactile": "Knife slides through potatoes easily"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from the oven and let rest for at least 15 minutes before slicing. This resting period is critical for the custard to set so it can be sliced like a pie.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT50M", "total_time": "PT1H20M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 250}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Low-Sugar"], "not_suitable_for": ["Vegans (contains dairy/eggs)"]}', '{"per_serving": {"calories": 418.25, "protein_g": 18.22, "carbohydrates_g": 39.39, "fat_g": 21.8, "saturated_fat_g": 12.09, "trans_fat_g": 0.22, "monounsaturated_fat_g": 6.36, "polyunsaturated_fat_g": 1.52, "fiber_g": 7.1, "sugar_g": 5.15, "sodium_mg": 667.01, "cholesterol_mg": 181.67, "potassium_mg": 1218.53, "calcium_mg": 375.51, "iron_mg": 1.93, "magnesium_mg": 92.68, "phosphorus_mg": 420.53, "zinc_mg": 1.62, "vitamin_a_mcg": 631.65, "vitamin_c_mg": 51.61, "vitamin_d_mcg": 1.63, "vitamin_e_mg": 0.68, "vitamin_k_mcg": 2.23, "vitamin_b6_mg": 0.11, "vitamin_b12_mcg": 0.92, "thiamin_mg": 0.06, "riboflavin_mg": 0.33, "niacin_mg": 0.11, "folate_mcg": 21.16, "water_g": 81.1, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Reheat gently to prevent eggs from becoming rubbery.", "duration": "P3D"}, "freezer": {"notes": "Texture of potatoes may change slightly upon thawing.", "duration": "P1M"}, "reheating": "Cover with foil and bake at 150\u00b0C/300\u00b0F until warmed through.", "does_not_keep": false}', '[{"name": "Round baking dish or deep pie dish (23-25cm)", "required": true, "alternative": null}, {"name": "Mandoline or sharp chef''s knife", "required": true, "alternative": "Food processor with slicing disk"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "The gratin is watery when sliced", "likely_cause": "The sorrel released too much liquid or the dish didn''t rest long enough", "prevention": "Ensure the sorrel is spun dry after washing; always rest the dish for 15+ minutes", "fix": "Let it cool longer; the liquids will reabsorb as the starch sets"}, {"symptom": "Top is burning before potatoes are soft", "likely_cause": "Oven rack too high or temperature calibration off", "prevention": "Bake in the middle or lower third of the oven", "fix": "Cover loosely with aluminum foil and continue baking until tender"}]', '["Sorrel has a distinct lemony tang due to oxalic acid. If you find pure sorrel too intense, mix it 50/50 with fresh spinach.", "Waxy potatoes hold their shape, giving this dish its ''pie'' structure. If you use starchy potatoes (like russets), it will be delicious but much softer and harder to slice cleanly.", "Do not rinse the potatoes after slicing. The surface starch is essential for binding the layers together with the egg custard.", "This dish is excellent served warm or at room temperature, making it perfect for lunch buffets."]', '"Sorrel (Oseille) is a beloved herb in French cooking, particularly in the spring and autumn. While often paired with salmon, its use in potato gratins is a rustic farmhouse tradition where the herb''s acidity balances the heavy dairy, much like lemon juice would in other cuisines."', 418.25);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('63fa3a22-48f1-45be-a839-d3c8cac2c1c6', 'Curau de Milho (Brazilian Corn & Coconut Pudding)', 'A silky, vibrant yellow custard crafted from the starch and milk of fresh sweet corn, enriched with creamy coconut milk. This traditional Brazilian dessert balances the earthy sweetness of field corn with tropical richness, finished with a classic dusting of cinnamon.', 'dessert', 'Brazilian', 'Intermediate', '["brazilian", "coconut", "corn", "dessert", "gluten-free", "vegan", "summer"]', '[{"group_name": "Corn Base", "items": [{"name": "fresh corn on the cob", "quantity": 5, "unit": null, "preparation": "raw", "notes": "approx. 6-7 ears depending on size; need ~700g kernels", "substitutions": [], "ingredient_id": "b408622e-f1b7-4f90-90c5-e956cd32ab63", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 250, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Custard", "items": [{"name": "coconut milk", "quantity": 400, "unit": "ml", "preparation": "full fat", "notes": "canned", "substitutions": [], "ingredient_id": "c037ee7e-e3ed-4340-b8fb-d8ad284ba96e", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish", "items": [{"name": "ground cinnamon", "quantity": null, "unit": null, "preparation": null, "notes": "generous dusting", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Stand each ear of corn vertically on a cutting board and slice downwards with a sharp knife to remove the kernels. Scrape the cob with the back of the knife to extract the milky starch residue.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Combine the corn kernels, cob scrapings, and water in a blender. Blend on high speed for 2-3 minutes until completely pulverized and smooth.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Pour the corn mixture through a fine mesh sieve (or nut milk bag) into a heavy-bottomed saucepan. Press firmly on the solids to extract as much liquid (corn juice) as possible; discard the dry fibrous solids.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the coconut milk, sugar, and salt to the saucepan with the strained corn juice. Whisk to combine.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Cook over medium heat (approx. 85\u00b0C/185\u00b0F), whisking constantly to prevent lumps. The mixture will begin to thicken rapidly as the corn starch activates.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": null, "doneness_cues": {"visual": "Thickened to pudding consistency", "tactile": "Coats back of spoon heavily"}}, "tips": ["Constant whisking is crucial once the heat is on; corn starch sets very quickly at the bottom."]}, {"step_number": 6, "phase": "cook", "text": "Reduce heat to low and continue cooking for 10-15 minutes, stirring frequently, to cook out the raw starch flavor and reach a glossy, creamy texture.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Pour the hot mixture into individual ramekins or a large serving dish. Allow to cool to room temperature, then refrigerate for at least 2 hours to set.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT2H", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Dust generously with ground cinnamon before serving.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT2H", "total_time": "PT2H35M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 180}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Soy-Free", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 351.04, "protein_g": 5.29, "carbohydrates_g": 51.06, "fat_g": 17.25, "saturated_fat_g": 14.28, "trans_fat_g": null, "monounsaturated_fat_g": 1.08, "polyunsaturated_fat_g": 0.83, "fiber_g": 4.75, "sugar_g": 30.94, "sodium_mg": 158.15, "cholesterol_mg": null, "potassium_mg": 492.15, "calcium_mg": 16.66, "iron_mg": 1.74, "magnesium_mg": 68.4, "phosphorus_mg": 170.66, "zinc_mg": 0.98, "vitamin_a_mcg": 0.04, "vitamin_c_mg": 9.81, "vitamin_d_mcg": null, "vitamin_e_mg": 0.19, "vitamin_k_mcg": 0.5, "vitamin_b6_mg": 0.09, "vitamin_b12_mcg": null, "thiamin_mg": 0.25, "riboflavin_mg": 0.08, "niacin_mg": 2.49, "folate_mcg": 64.35, "water_g": 175.43, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Cover surface directly with plastic wrap to prevent skin formation.", "duration": "P3D"}, "freezer": {"notes": "Freezing will destroy the custard texture; do not freeze.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "High-powered blender", "required": true, "alternative": null}, {"name": "Fine mesh sieve or nut milk bag", "required": true, "alternative": "Cheesecloth"}, {"name": "Heavy-bottomed saucepan", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Ramekins or serving dishes", "required": true, "alternative": null}]', '[{"symptom": "Pudding is lumpy", "likely_cause": "Stopped whisking during the thickening phase", "prevention": "Whisk constantly, especially when the mixture first starts to bubble", "fix": "Use an immersion blender or pass through a sieve again immediately while hot"}]', '["Select the freshest corn possible; older corn has less milk and more starch, which can make the texture pasty rather than creamy.", "Do not skip scraping the cobs after cutting the kernels; the ''milk'' in the cob contains the sweetest flavor and essential thickening starches.", "The thickness depends entirely on the natural starch content of your specific corn. If it is too thin after 15 minutes, you can simmer longer to reduce, or whisk in a tiny slurry of commercial cornstarch (though this shouldn''t be necessary with good corn).", "For a warm variation, this can be eaten immediately after cooking, similar to porridge."]', '"Curau de Milho is a staple of Brazilian Festas Juninas (June Festivals), which celebrate the harvest and rural life. It highlights maize, an indigenous crop central to Brazilian culinary history, transforming simple field ingredients into a refined, custard-like delicacy."', 351.04);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('63fefef2-d266-4fe7-ae9a-385961bf0f22', 'Spicy Anchovy and Peanut Crunch (Ikan Bilis Goreng)', 'A highly addictive Southeast Asian bar snack balancing the deep umami of crispy dried anchovies with the earthiness of roasted peanuts. The heat from dried chilies and the sweetness of a caramelized glaze create a complex textural interplay of crunch and shatter.', 'snack', 'Malaysian', 'Intermediate', '["asian", "anchovy", "dried red chili", "appetizer", "gluten-free", "snack", "malaysian", "high-protein"]', '[{"group_name": "Main Components", "items": [{"name": "dried anchovies (ikan bilis)", "quantity": 150, "unit": "g", "preparation": "peeled and split", "notes": "Select high-grade, whitish-blue dried anchovies for best texture", "substitutions": [], "ingredient_id": "cfdad407-c486-4fcc-9e47-7dd4cb32277c", "nutrition_source": "Aggregated Public Data"}, {"name": "raw peanuts", "quantity": 200, "unit": "g", "preparation": "skin-on", "notes": "Spanish peanuts work best", "substitutions": [], "ingredient_id": "033645df-fab2-4821-be6d-1744f9f55816", "nutrition_source": "Aggregated Public Data"}, {"name": "neutral oil", "quantity": 500, "unit": "ml", "preparation": "for frying", "notes": "Peanut, canola, or vegetable oil", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}]}, {"group_name": "Aromatics & Seasoning", "items": [{"name": "dried red chilies", "quantity": 15, "unit": "g", "preparation": "deseeded and cut into 2cm lengths", "notes": "Adjust quantity for heat preference", "substitutions": [], "ingredient_id": "a4bf8b34-30b2-4d24-a120-b5b191811f64", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "thinly sliced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "white sugar", "quantity": 20, "unit": "g", "preparation": null, "notes": "Superfine sugar dissolves best", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "Use sparingly as anchovies are naturally salty", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Rinse the dried anchovies thoroughly in cold water to remove excess salt and dust. Drain immediately and pat extremely dry with paper towels or air dry for 10 minutes. Moisture is the enemy of crispiness.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": ["If the anchovies are wet when they hit the oil, they will steam instead of fry and become chewy."]}, {"step_number": 2, "phase": "cook", "text": "Heat the oil in a wok to 160\u00b0C/320\u00b0F. Add the raw peanuts. Fry gently, stirring constantly, until they turn light golden brown and the bubbling subsides. Remove with a spider strainer and drain on paper towels.", "structured": {"action": "FRY", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT5M", "doneness_cues": {"visual": "Light golden brown color", "tactile": "Bubbling around peanuts reduces significantly"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Increase oil heat to 180\u00b0C/350\u00b0F. Fry the dried anchovies in batches. They will bubble aggressively at first. Fry until the bubbling almost stops and they are golden and light. Remove and drain.", "structured": {"action": "FRY", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown", "tactile": "Crisp and light"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Turn off the heat but leave the oil warm. Quickly flash-fry the dried chilies and garlic slices for 10-15 seconds until fragrant but not burnt. Remove immediately.", "structured": {"action": "FRY", "temperature": null, "duration": "PT15S", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove all but 1 tablespoon (15ml) of oil from the wok. Heat over low heat. Add the fried peanuts, anchovies, chilies, and garlic back to the pan. Sprinkle with sugar and salt. Toss continuously for 1-2 minutes until the sugar melts slightly and coats the mixture.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Spread the mixture onto a flat tray lined with baking paper to cool completely. The mixture will crisp up further as it cools.", "structured": {"action": "COOL", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT15M", "total_time": "PT40M", "overnight_required": false, "yields": "4 cups", "yield_count": 8, "serving_size_g": 40}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Egg-Free"], "not_suitable_for": ["Shellfish allergy sufferers (cross-contamination risk in dried fish processing)", "Individuals with nut allergies"]}', '{"per_serving": {"calories": 182.93, "protein_g": 10.31, "carbohydrates_g": 7.77, "fat_g": 13.28, "saturated_fat_g": 1.9, "trans_fat_g": null, "monounsaturated_fat_g": null, "polyunsaturated_fat_g": 0.01, "fiber_g": 2.56, "sugar_g": 3.51, "sodium_mg": 142.72, "cholesterol_mg": null, "potassium_mg": 283.31, "calcium_mg": 53.57, "iron_mg": 2.27, "magnesium_mg": 49.97, "phosphorus_mg": 146.18, "zinc_mg": 1.1, "vitamin_a_mcg": 0.01, "vitamin_c_mg": 1.71, "vitamin_d_mcg": null, "vitamin_e_mg": null, "vitamin_k_mcg": 0.03, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": null, "thiamin_mg": null, "riboflavin_mg": null, "niacin_mg": 0.01, "folate_mcg": 0.06, "water_g": 1.1, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Do not refrigerate; humidity ruins the texture.", "duration": null}, "freezer": {"duration": null}, "reheating": "Re-crisp in a dry pan or low oven if softened.", "does_not_keep": false}', '[{"name": "Wok or deep frying pan", "required": true, "alternative": null}, {"name": "Spider strainer or slotted spoon", "required": true, "alternative": null}, {"name": "Paper towel-lined baking sheet", "required": true, "alternative": null}, {"name": "Fine mesh sieve", "required": true, "alternative": null}]', '[{"symptom": "Anchovies are chewy or tough", "likely_cause": "Oil temperature was too low or anchovies were not dried properly before frying", "prevention": "Ensure oil is 180\u00b0C (350\u00b0F) and anchovies are bone-dry before frying", "fix": "Refry them briefly in hot oil for 30 seconds"}, {"symptom": "Garlic or chilies taste bitter", "likely_cause": "Burnt during the flash-fry step", "prevention": "Fry them in residual heat or for only seconds; they carry over cook significantly", "fix": "Pick out the burnt aromatics; do not serve them"}]', '["Grade Matters: Look for ''Ikan Bilis Mata Biru'' (Blue Eye Anchovy) from Pangkor or Langkawi for the premium, less salty experience.", "The Cold Start: If you are unsure about frying peanuts, start them in cold oil and bring the heat up together. This ensures the center is cooked before the skin burns.", "Storage: This must be stored in an absolute airtight container with a silica gel packet if possible. Humidity makes the sugar sticky and the fish soft within hours."]', '"Known as Ikan Bilis Goreng in Malaysia and Indonesia, this is a foundational element of Nasi Lemak but stands alone as a popular beer snack or appetizer. It showcases the Southeast Asian mastery of texture, balancing the shatter-crisp of dried seafood with the dense crunch of legumes."', 182.93);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('64014345-ccfa-4114-a678-2fb26295e6d4', 'Roasted Tomatillo Salsa Verde', 'A vibrant, zesty salsa balancing the tart acidity of roasted tomatillos with the smoky heat of blistered jalapeños. Fresh cilantro and crisp white onion provide a bright, herbaceous finish.', 'condiment', 'Mexican', 'Easy', '["condiments", "jalape\u00f1o", "tomatillo", "summer", "dairy-free", "gluten-free", "halal", "healthy", "kosher", "low calorie", "low-carb", "low cholesterol", "low-fat", "low sugar", "nut-free", "vegan", "vegetarian"]', '[{"group_name": "Base Vegetables", "items": [{"name": "tomatillos", "quantity": 450, "unit": "g", "preparation": "husked and rinsed", "notes": "approx 8-10 medium tomatillos", "substitutions": [], "ingredient_id": "5e6c5eb7-cabd-41cc-b0e6-c48db933110e", "nutrition_source": "USDA FoodData Central"}, {"name": "jalape\u00f1o peppers", "quantity": 2, "unit": null, "preparation": "whole", "notes": "approx 40g total; use 1 for mild heat", "substitutions": [], "ingredient_id": "4253d4ec-8462-43c6-963a-ae1f94367e2b", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": "unpeeled", "notes": "approx 8g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Fresh Aromatics", "items": [{"name": "white onion", "quantity": 40, "unit": "g", "preparation": "roughly chopped", "notes": "about 1/4 small onion", "substitutions": [], "ingredient_id": "ee82a9b0-15f7-45cd-bd5f-ba0b65eb1100", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh cilantro", "quantity": 15, "unit": "g", "preparation": "leaves and tender stems", "notes": "approx 1/2 cup packed", "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "lime juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Set your oven broiler to high. Arrange the husked tomatillos, whole jalape\u00f1os, and unpeeled garlic cloves on a baking sheet lined with foil for easy cleanup.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 260, "fahrenheit": 500}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Broil the vegetables for 5-7 minutes, flipping halfway through, until the tomatillos are blistered and charred in spots and the peppers have softened.", "structured": {"action": "BROIL", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Blackened spots on skins", "tactile": "Tomatillos are soft to the touch"}}, "tips": ["Watch the garlic closely; remove it earlier if it starts to burn."]}, {"step_number": 3, "phase": "prep", "text": "Remove from the oven and let cool for 10 minutes. Once handleable, squeeze the roasted garlic out of its skin and discard the skin. If a milder salsa is desired, remove the seeds and ribs from the jalape\u00f1os.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Place the roasted tomatillos (including any juices on the pan), roasted jalape\u00f1os, peeled roasted garlic, fresh white onion, cilantro, lime juice, and salt into a blender or food processor.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Pulse until combined but still slightly chunky. Do not puree until completely smooth unless a distinct sauce texture is desired.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT30S", "doneness_cues": {"visual": "Uniformly chopped with visible flecks of cilantro and char", "tactile": null}}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT15M", "total_time": "PT30M", "overnight_required": false, "yields": "500ml", "yield_count": 16, "serving_size_g": 30}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Paleo", "Whole30", "Keto", "Low-Carb", "Sugar-Free", "Low-Sodium"], "not_suitable_for": ["Individuals with nightshade sensitivity"]}', '{"per_serving": {"calories": 9.33, "protein_g": 0.44, "carbohydrates_g": 2.09, "fat_g": 0.08, "saturated_fat_g": 0.01, "trans_fat_g": null, "monounsaturated_fat_g": 0.01, "polyunsaturated_fat_g": 0.02, "fiber_g": 0.46, "sugar_g": 1.39, "sodium_mg": 77.18, "cholesterol_mg": null, "potassium_mg": 75.35, "calcium_mg": 5.8, "iron_mg": 0.16, "magnesium_mg": 3.39, "phosphorus_mg": 9.42, "zinc_mg": 0.03, "vitamin_a_mcg": 27.99, "vitamin_c_mg": 7.27, "vitamin_d_mcg": null, "vitamin_e_mg": 0.11, "vitamin_k_mcg": 2.86, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": null, "thiamin_mg": 0.02, "riboflavin_mg": 0.01, "niacin_mg": 0.15, "folate_mcg": 2.64, "water_g": 27.3, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors meld and improve after 24 hours.", "duration": "P1W"}, "freezer": {"notes": "Texture may become slightly more watery upon thawing; blend briefly to re-emulsify.", "duration": "P3M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Food processor or Blender", "required": true, "alternative": "Molcajete (mortar and pestle)"}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Salsa is too sour or acidic", "likely_cause": "Tomatillos were underripe or naturally very tart", "prevention": "Choose tomatillos that fill their husks completely", "fix": "Stir in 1/2 teaspoon of sugar or agave syrup to neutralize the acidity"}, {"symptom": "Salsa is too thick or gelatinous", "likely_cause": "Natural pectin in tomatillos gelling after cooling", "prevention": "Normal behavior for tomatillos", "fix": "Stir in 1 tablespoon of water or extra lime juice to thin it out"}]', '["Washing tomatillos is crucial; they have a sticky residue under the husk containing saponins which can taste bitter if not rinsed off with warm water.", "For the most authentic flavor, use fresh white onion rather than yellow or red; the sharp bite cuts through the richness of the roasted tomatillos.", "This salsa serves as an excellent base (simmered) for Chilaquiles Verdes or Enchiladas Suizas.", "Roasting the garlic in its skin prevents it from turning acrid and burnt under the broiler, resulting in a sweet, mellow garlic flavor."]', '"Salsa Verde dates back to the Aztec empire, utilizing the tomatillo (Physalis philadelphica), a staple distinct from the red tomato. While often eaten raw (cruda), this roasted version deepens the flavors, a technique common in Central Mexican cuisine to reduce acidity and increase savory notes."', 9.33);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('64530f74-b963-49a1-8783-3c818f26a2b3', 'Sweet And Spicy Cayenne Lime Peanuts', 'Crunchy peanuts encased in a brittle, glass-like sugar shell spiked with fiery cayenne pepper and finished with fresh, aromatic lime zest. A perfect balance of heat, sweet, acid, and salt.', 'snack', 'Fusion', 'Intermediate', '["cayenne pepper", "five ingredient", "sugar", "snack", "appetizer", "dairy-free", "gluten-free", "vegetarian", "vegan", "party food"]', '[{"group_name": "Glazed Peanuts", "items": [{"name": "roasted unsalted peanuts", "quantity": 250, "unit": "g", "preparation": "whole", "notes": "skin-on or skin-off works", "substitutions": ["raw peanuts (increase cook time)", "cashews", "almonds"], "ingredient_id": "0b96132d-e25c-4f05-9124-98e1af158be1", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 100, "unit": "g", "preparation": "white", "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 60, "unit": "ml", "preparation": null, "notes": "for dissolving sugar", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "cayenne pepper", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 1 tsp; adjust for heat preference", "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 4, "unit": "g", "preparation": null, "notes": "flaky salt is best for finishing", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "lime", "quantity": 1, "unit": null, "preparation": "zested", "notes": "approx 3-4g zest; use fruit for garnish wedges", "substitutions": [], "ingredient_id": "d3d2677e-fe02-4404-add0-29d73df7e921", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare a baking sheet by lining it with parchment paper. Zest the lime into a small bowl and mix with the cayenne pepper and sea salt. Have this spice mixture ready by the stove.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Mise en place is crucial here as the sugar caramelizes quickly at the end."]}, {"step_number": 2, "phase": "cook", "text": "In a large heavy-bottomed skillet, combine sugar and water. Place over medium-high heat and bring to a boil. Do not stir initially, just swirl the pan until the sugar dissolves.", "structured": {"action": "BOIL", "temperature": {"celsius": 110, "fahrenheit": 230}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the peanuts to the boiling syrup. Stir continuously with a spatula. The water will evaporate, and the sugar will eventually crystallize, looking like dry white sand coating the nuts.", "structured": {"action": "STIR", "temperature": null, "duration": null, "doneness_cues": {"visual": "Sugar turns sandy and dry", "tactile": null}}, "tips": ["Don''t panic when it looks dry and sandy; this is a necessary stage before caramelization."]}, {"step_number": 4, "phase": "cook", "text": "Lower the heat to medium. Continue stirring the sandy nuts constantly. The sugar will begin to melt again and turn into a glossy amber caramel. Coat the nuts evenly in this liquid caramel.", "structured": {"action": "CARAMELIZE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Glossy amber coating", "tactile": "Smooth glaze"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Immediately remove the pan from heat. Sprinkle the reserved lime zest, cayenne, and salt mixture over the hot nuts and toss vigorously to distribute evenly.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Pour the nuts onto the prepared baking sheet. Quickly separate them using two forks before they harden into a cluster. Allow to cool completely (about 20-30 minutes).", "structured": {"action": "COOL", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": ["Caution: The sugar coating is extremely hot (over 170\u00b0C/338\u00b0F). Do not touch with bare hands."]}]', '{"active_time": "PT20M", "passive_time": "PT30M", "total_time": "PT50M", "overnight_required": false, "yields": "300g", "yield_count": 10, "serving_size_g": 30}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 148.57, "protein_g": 8.53, "carbohydrates_g": 18.66, "fat_g": 5.54, "saturated_fat_g": 0.77, "trans_fat_g": null, "monounsaturated_fat_g": 2.73, "polyunsaturated_fat_g": 1.76, "fiber_g": 4.21, "sugar_g": 10.12, "sodium_mg": 155.92, "cholesterol_mg": null, "potassium_mg": 352.79, "calcium_mg": 35.36, "iron_mg": 1.25, "magnesium_mg": 12.9, "phosphorus_mg": 129.03, "zinc_mg": 1.51, "vitamin_a_mcg": 6.37, "vitamin_c_mg": 2.08, "vitamin_d_mcg": null, "vitamin_e_mg": 0.1, "vitamin_k_mcg": 0.28, "vitamin_b6_mg": 0.09, "vitamin_b12_mcg": null, "thiamin_mg": 0.12, "riboflavin_mg": 0.05, "niacin_mg": 2.91, "folate_mcg": 34.08, "water_g": 13.61, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Do not refrigerate; humidity will make the coating sticky.", "duration": null}, "freezer": {"duration": null}, "reheating": "Not recommended", "does_not_keep": false}', '[{"name": "Large heavy-bottomed skillet or wok", "required": true, "alternative": "Wide saucepan"}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": "Silicone baking mat"}, {"name": "Heat-resistant spatula", "required": true, "alternative": "Wooden spoon"}, {"name": "Microplane or zester", "required": true, "alternative": null}]', '[{"symptom": "Sugar coating is grainy and white, not glossy", "likely_cause": "Stopped cooking too early (at the sandy stage)", "prevention": "Keep cooking after the sugar turns sandy; it will re-melt into caramel", "fix": "Return pan to heat and stir until sugar melts"}, {"symptom": "Burnt taste", "likely_cause": "Heat was too high during the final melting stage", "prevention": "Lower heat to medium once sugar crystallizes and stir constantly", "fix": "Cannot be fixed"}, {"symptom": "Nuts are sticky after cooling", "likely_cause": "High humidity environment or undercooked caramel", "prevention": "Cook sugar to a deeper amber color; store with silica packet", "fix": "Place in 150\u00b0C/300\u00b0F oven for 5-10 minutes to dry out"}]', '["Fresh lime zest contains essential oils that provide aroma; dried peel will not have the same punch.", "If you prefer a milder snack, add the cayenne to the syrup at the beginning\u2014the heat degrades slightly during cooking.", "Serve with fresh lime wedges on the side for guests to squeeze over immediately before eating for a sticky, extra-tangy experience.", "For the cleanest look, use blanched peanuts (no skins), though skin-on peanuts provide a nice rustic texture."]', '"This recipe adapts the classic French technique of ''pralines'' (crystallizing then caramelizing nuts) but infuses it with the bold flavor profile of American bar snacks and Latin American street food, where chili, lime, and salt are a ubiquitous trio."', 148.57);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('647434b3-5e04-48d1-a43a-21b9d20b4d0a', 'Delhi Matar Kulcha', 'The quintessential North Indian street food pairing. Earthy, dried white peas are simmered into a buttery, tangy, and spicy ragout, served alongside pillowy, soft leavened flatbreads toasted with nigella seeds and coriander. The dish balances the heat of green chilies with the sour punch of tamarind and dried mango.', 'lunch', 'Indian', 'Intermediate', '["indian", "vegetarian", "street food", "high protein", "bread", "curry"]', '[{"group_name": "Dried Peas (Matar)", "items": [{"name": "dried white peas (safed vatana)", "quantity": 250, "unit": "g", "preparation": "dried", "notes": "Must be soaked overnight", "substitutions": [], "ingredient_id": "4fd38ba1-cc26-411e-8637-89f4eb3fc2db", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 750, "unit": "ml", "preparation": null, "notes": "For boiling", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "turmeric powder", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pea Tempering & Spices", "items": [{"name": "red onion", "quantity": 100, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "tomato", "quantity": 100, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "green chili", "quantity": 2, "unit": null, "preparation": "minced", "notes": "about 6g", "substitutions": [], "ingredient_id": "6cdb0615-378e-4bfa-b76d-f19bbd780e6c", "nutrition_source": "Aggregated Public Data"}, {"name": "ginger", "quantity": 10, "unit": "g", "preparation": "julienned", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "roasted cumin powder", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "chaat masala", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "db4e60df-9a95-46ce-b433-dad1e8347383", "nutrition_source": "Aggregated Public Data"}, {"name": "dry mango powder (amchur)", "quantity": 5, "unit": "g", "preparation": null, "notes": "Essential for authentic flavor", "substitutions": [], "ingredient_id": "e4857e92-3b09-4ffc-b0f5-3f5ea0eae64d", "nutrition_source": "USDA FoodData Central"}, {"name": "tamarind paste", "quantity": 15, "unit": "g", "preparation": null, "notes": "Dissolved in 30ml warm water", "substitutions": [], "ingredient_id": "3f12d740-bf37-400e-82b1-c5b9dcda810b", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh coriander", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "8c7693be-b538-445c-80f9-3d5bf4c6dcc0", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Kulcha (Flatbread) Dough", "items": [{"name": "all-purpose flour (maida)", "quantity": 300, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "plain yogurt", "quantity": 60, "unit": "g", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "ba236210-8230-458e-a809-4c025a1bf020", "nutrition_source": "USDA FoodData Central"}, {"name": "warm water", "quantity": 140, "unit": "ml", "preparation": "approx 35\u00b0C", "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "sugar", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "instant yeast", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b5658d19-b726-4ddb-b56e-74884c61e753", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "nigella seeds (kalonji)", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "75bffc23-976f-4af7-9dba-740b605b5248", "nutrition_source": "Aggregated Public Data"}, {"name": "ghee or butter", "quantity": 30, "unit": "g", "preparation": "melted", "notes": null, "substitutions": [], "ingredient_id": "ae1e9713-8f4a-4a91-9619-baa177e12fc6", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Rinse the dried white peas thoroughly and soak them in ample water for at least 8 hours or overnight. Drain before cooking.", "structured": {"action": "SOAK", "temperature": null, "duration": "PT8H", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a mixing bowl, combine warm water (35\u00b0C/95\u00b0F), sugar, and instant yeast. Let sit for 5 minutes until frothy. Add flour, salt, baking powder, yogurt, and oil. Mix to form a shaggy dough.", "structured": {"action": "MIX", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Knead the dough on a clean surface for 8-10 minutes until smooth and elastic. Place in a greased bowl, cover with a damp cloth, and proof in a warm spot until doubled in size.", "structured": {"action": "PROOF", "temperature": {"celsius": 25, "fahrenheit": 77}, "duration": "PT1H30M", "doneness_cues": {"visual": "Doubled in volume", "tactile": "Indentation springs back slowly"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Place soaked peas, 750ml fresh water, turmeric, and salt in a pressure cooker. Cook on high heat for 4-5 whistles, then lower heat and cook 5 more minutes. If using a pot, boil for 45-60 mins until soft. The peas should be completely tender and buttery but retain their shape.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Once peas are cooked, gently mash a small portion (about 10%) against the side of the pot to thicken the gravy. Stir in the tamarind water, roasted cumin, chaat masala, and dry mango powder. Simmer for 2 minutes to meld flavors.", "structured": {"action": "SIMMER", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Just before serving, fold the raw chopped onions, tomatoes, green chilies, and ginger julienne into the hot peas. This retains their crunch and freshness against the soft peas.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Punch down the proofed dough and divide into 8 equal balls. Roll each into an oval or round shape about 5mm thick. Sprinkle nigella seeds and coriander leaves on top, pressing them gently into the dough.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Heat a heavy skillet or tawa over medium-high heat. Place a dough disc (seeded side up) on the pan. When bubbles appear (approx 1 minute), flip and cook the other side until golden brown spots appear. Brush immediately with ghee or butter.", "structured": {"action": "TOAST", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown blister spots", "tactile": "Soft and pliable"}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Serve the hot, buttered kulchas immediately alongside the warm spiced peas. Garnish the peas with extra coriander and a squeeze of lemon if desired.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT1H", "passive_time": "PT9H", "total_time": "PT10H", "overnight_required": true, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 485.25, "protein_g": 14.06, "carbohydrates_g": 78.96, "fat_g": 12.02, "saturated_fat_g": 4.91, "trans_fat_g": 0.25, "monounsaturated_fat_g": 2.01, "polyunsaturated_fat_g": 0.61, "fiber_g": 6.57, "sugar_g": 5.58, "sodium_mg": 1285.02, "cholesterol_mg": 18.08, "potassium_mg": 828.65, "calcium_mg": 97.9, "iron_mg": 5.32, "magnesium_mg": 108.04, "phosphorus_mg": 363.35, "zinc_mg": 3.16, "vitamin_a_mcg": 331.02, "vitamin_c_mg": 11.09, "vitamin_d_mcg": 0.02, "vitamin_e_mg": 0.37, "vitamin_k_mcg": 1.4, "vitamin_b6_mg": 0.1, "vitamin_b12_mcg": 0.07, "thiamin_mg": 0.23, "riboflavin_mg": 0.11, "niacin_mg": 1.51, "folate_mcg": 50.62, "water_g": 275.29, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store peas and bread separately. Reheat bread in a pan; peas can be microwaved.", "duration": "P3D"}, "freezer": {"notes": "Freezing cooked peas is fine; frozen cooked kulchas may lose fluffiness.", "duration": "P1M"}, "reheating": "Steam or pan-fry kulchas with a drop of water to fluff them up.", "does_not_keep": false}', '[{"name": "Pressure cooker or Dutch oven", "required": true, "alternative": "Heavy-bottomed pot (increases cooking time significantly)"}, {"name": "Cast iron skillet or Tawa", "required": true, "alternative": "Non-stick pan"}, {"name": "Rolling pin", "required": true, "alternative": null}, {"name": "Mixing bowls", "required": true, "alternative": null}]', '[{"symptom": "Peas are still hard after cooking", "likely_cause": "Old dried peas or insufficient soaking time", "prevention": "Add a pinch of baking soda during the soaking or boiling stage", "fix": "Add water and pressure cook for another 2-3 whistles"}, {"symptom": "Kulchas are dense or tough", "likely_cause": "Yeast was inactive or dough was overworked", "prevention": "Test yeast viability in warm water first; do not add too much flour during kneading", "fix": "Cannot be fixed once cooked; let dough rest longer before rolling next time"}]', '["The secret to the ''Matar'' is the texture contrast: the peas must be hot and soft, but the onions and tomatoes stirred in at the end must remain raw and crunchy.", "If you don''t have a pressure cooker, soaking the peas with a pinch of baking soda will significantly reduce the boiling time.", "Amchur (dry mango powder) is non-negotiable for this dish; it provides the specific earthy tartness that lemon juice alone cannot replicate.", "For a restaurant-style ''fluffy'' kulcha, allow the shaped dough balls to rest for 10 minutes before rolling them out."]', '"Matar Kulcha is a legendary street food staple of Delhi and Northern India. Unlike heavy cream-based curries, the pea stew is water-based and relies on the complex interplay of dried spices and tangy tamarind. It was traditionally a working-class lunch due to its affordability and high protein content."', 485.25);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('6513adc5-1d47-4b81-a6f9-6361b02f7105', 'Classic Hearth Chili Con Carne', 'A robust, deep-flavored chili featuring well-browned beef, smoky spices, and tender kidney beans. This recipe builds layers of flavor through proper searing and a slow simmer, resulting in a rich texture that tastes even better the next day.', 'dinner', 'Tex-Mex', 'Easy', '["chili", "great leftovers", "ground beef", "spices", "tomato", "dinner", "for one", "main course", "tex-mex", "comfort food"]', '[{"group_name": "Aromatics & Meat", "items": [{"name": "neutral oil", "quantity": 15, "unit": "ml", "preparation": "liquid", "notes": null, "substitutions": ["beef tallow", "olive oil"], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "ground beef", "quantity": 500, "unit": "g", "preparation": "raw", "notes": "20% fat preferred for flavor", "substitutions": ["ground turkey", "plant-based mince"], "ingredient_id": "696b2887-6464-4698-a80a-6860f8633185", "nutrition_source": "Aggregated Public Data"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "red bell pepper", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx 120g", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Spice Blend", "items": [{"name": "chili powder blend", "quantity": 15, "unit": "g", "preparation": null, "notes": "Standard mild American blend, not pure cayenne", "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 2, "unit": "g", "preparation": null, "notes": "Mexican oregano preferred if available", "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "cocoa powder", "quantity": 3, "unit": "g", "preparation": "powder", "notes": "unsweetened, adds depth", "substitutions": [], "ingredient_id": "c06a8e5a-163a-4f21-ad00-a6d90e34c38c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Base & Liquids", "items": [{"name": "tomato paste", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "d0a34229-249b-49e5-a653-227bd7afb7fc", "nutrition_source": "Aggregated Public Data"}, {"name": "beef stock", "quantity": 250, "unit": "ml", "preparation": null, "notes": "low sodium", "substitutions": [], "ingredient_id": "d5096f91-a6b8-408e-809e-de02179b315c", "nutrition_source": "Aggregated Public Data"}, {"name": "crushed tomatoes", "quantity": 400, "unit": "g", "preparation": "canned", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "kidney beans", "quantity": 400, "unit": "g", "preparation": "canned, drained and rinsed", "notes": "approx 240g drained weight", "substitutions": ["black beans", "pinto beans"], "ingredient_id": "af4864fd-b705-4c2b-b266-1130d7916989", "nutrition_source": "Aggregated Public Data"}, {"name": "apple cider vinegar", "quantity": 5, "unit": "ml", "preparation": null, "notes": "for finishing", "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare your vegetables: dice the onion and red bell pepper into uniform 1cm pieces, and mince the garlic.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat the oil in a Dutch oven over medium-high heat. Add the ground beef and spread it into a single layer. Let it sear undisturbed for 3-4 minutes until deeply browned, then break it apart with a wooden spoon and cook until no pink remains (74\u00b0C/165\u00b0F).", "structured": {"action": "SEAR", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": "PT8M", "doneness_cues": {"visual": "Deep brown crust on bottom", "tactile": "Meat is firm and separated"}}, "tips": ["Do not overcrowd the pan; brown in batches if necessary.", "That brown crust on the bottom (fond) is pure flavor."]}, {"step_number": 3, "phase": "cook", "text": "Lower heat to medium. Add the diced onion and bell pepper to the beef. Saut\u00e9 for 5-6 minutes until the onions are translucent and softened.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT6M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the minced garlic, chili powder, cumin, paprika, oregano, salt, pepper, and optional cocoa powder. Stir constantly for 1 minute to bloom the spices.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Spices darken slightly", "tactile": "Aromatic oils released"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Stir in the tomato paste and cook for 1 more minute, coating the meat and vegetables, until the paste turns a rusty red color.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Pour in the beef stock and use the wooden spoon to scrape up any browned bits stuck to the bottom of the pot (deglazing). Stir in the crushed tomatoes and drained kidney beans.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Bring the mixture to a boil, then reduce heat to low. Cover and simmer gently for 45 minutes, stirring occasionally to prevent sticking.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT45M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove the lid and simmer for an additional 15 minutes to thicken to your desired consistency. Stir in the apple cider vinegar to brighten the flavors. Taste and adjust salt if needed.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": ["If the chili is too thick, add a splash of water.", "The vinegar cuts through the richness and wakes up the spices."]}]', '{"active_time": "PT25M", "passive_time": "PT1H5M", "total_time": "PT1H30M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 522.01, "protein_g": 61.61, "carbohydrates_g": 54.07, "fat_g": 23.55, "saturated_fat_g": 7.86, "trans_fat_g": null, "monounsaturated_fat_g": 0.37, "polyunsaturated_fat_g": 0.52, "fiber_g": 15.93, "sugar_g": 15.16, "sodium_mg": 1043.36, "cholesterol_mg": null, "potassium_mg": 1702.87, "calcium_mg": 177.08, "iron_mg": 9.99, "magnesium_mg": 56.2, "phosphorus_mg": 424.7, "zinc_mg": 11.36, "vitamin_a_mcg": 153.22, "vitamin_c_mg": 61.16, "vitamin_d_mcg": null, "vitamin_e_mg": 2.42, "vitamin_k_mcg": 10.67, "vitamin_b6_mg": 0.29, "vitamin_b12_mcg": null, "thiamin_mg": 0.06, "riboflavin_mg": 0.1, "niacin_mg": 1.02, "folate_mcg": 24.31, "water_g": 64.79, "alcohol_g": null, "caffeine_mg": 1.73}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves significantly after 24 hours.", "duration": "P5D"}, "freezer": {"notes": "Freeze in individual portions for easy reheating.", "duration": "P3M"}, "reheating": "Reheat gently on the stove over medium-low heat, adding a splash of water if the texture is too thick.", "does_not_keep": false}', '[{"name": "Dutch oven or heavy-bottomed pot", "required": true, "alternative": "Large deep skillet"}, {"name": "Wooden spoon", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Chili tastes flat or dull", "likely_cause": "Lack of salt or acidity", "prevention": "Taste frequently during the final simmer", "fix": "Add salt 1g at a time, or a teaspoon of vinegar/lime juice"}, {"symptom": "Burnt taste", "likely_cause": "Heat was too high during simmer and bottom scorched", "prevention": "Use a heavy-bottomed pot and low heat; stir occasionally", "fix": "Do not scrape the bottom. Carefully ladle the unburnt top layer into a fresh pot."}]', '["Blooming the spices (Step 4) in the hot fat before adding liquid is critical for releasing fat-soluble flavor compounds.", "The optional cocoa powder does not make the dish taste like chocolate; it adds an earthy richness that mimics traditional mole flavors.", "This recipe scales down perfectly for single diners, but making a full batch is recommended as chili flavor improves significantly after a night in the fridge."]', '"While the origins of chili con carne are often debated between Texas and Northern Mexico, it has become a quintessential staple of American comfort food. Historically a ''poor man''s dish'' made to extend meager meat rations with peppers and spices, it has evolved into a globally recognized stew."', 522.01);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('651fbb8e-5ed7-47de-8504-e14e85cfdcb9', 'Greek Lamb Chops with Feta and Lemon', 'Juicy, tender lamb chops seared to perfection with a fragrant crust of dried oregano and garlic. The dish is finished with a bright splash of fresh lemon juice and a generous scattering of salty, creamy feta cheese that slightly melts over the warm meat.', 'dinner', 'Greek', 'Easy', '["greek", "feta", "five ingredient", "lamb chop", "dinner", "main course", "gluten-free", "low-carb"]', '[{"group_name": "Lamb", "items": [{"name": "lamb rib chops", "quantity": 8, "unit": null, "preparation": "room temperature", "notes": "approx. 800g total weight; French trimmed preferred", "substitutions": [], "ingredient_id": "fb22111e-96e0-45a6-8145-36b92c1aa73a", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 5g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly ground, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Aromatics & Finish", "items": [{"name": "garlic", "quantity": 4, "unit": null, "preparation": "minced", "notes": "approx 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 4, "unit": "g", "preparation": null, "notes": "approx 2 tsp; Greek oregano is best", "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 45, "unit": "ml", "preparation": "freshly squeezed", "notes": "about 1 large lemon", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "feta cheese", "quantity": 100, "unit": "g", "preparation": "crumbled", "notes": null, "substitutions": [], "ingredient_id": "a9a8605c-3bf2-4ca3-8c58-80e87aff7cd8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the lamb chops very dry with paper towels. Season both sides generously with salt, pepper, and the dried oregano. Press the seasoning gently into the meat.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat olive oil in a large skillet over medium-high heat until shimmering but not smoking.", "structured": {"action": "HEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the lamb chops to the pan in a single layer (work in batches if necessary). Sear undisturbed until a golden-brown crust forms, about 3-4 minutes.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Flip the chops. Add the minced garlic to the pan (avoiding direct high heat spots so it doesn''t burn) and cook the second side for another 2-3 minutes. Aim for an internal temperature of 57\u00b0C (135\u00b0F) for medium-rare or 63\u00b0C (145\u00b0F) for medium.", "structured": {"action": "SEAR", "temperature": {"celsius": 57, "fahrenheit": 135}, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown crust", "tactile": "Firm with slight give"}}, "tips": ["If the garlic starts to brown too quickly, place it on top of the chops."]}, {"step_number": 5, "phase": "finish", "text": "Remove the pan from the heat. Immediately pour the lemon juice over the chops and into the pan juices to deglaze slightly. Sprinkle the crumbled feta over the hot lamb so it warms through.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Transfer chops to a serving platter and rest for 5-10 minutes before serving. Drizzle any remaining pan juices over the top.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT10M", "total_time": "PT30M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 220}', '{"flags": ["Gluten-Free", "Low-Carb", "Keto", "Nut-Free", "Egg-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": ["Vegans", "Vegetarians"]}', '{"per_serving": {"calories": 613.4, "protein_g": 45.92, "carbohydrates_g": 3.75, "fat_g": 46.98, "saturated_fat_g": 20.39, "trans_fat_g": 2.2, "monounsaturated_fat_g": 6.64, "polyunsaturated_fat_g": 0.96, "fiber_g": 0.65, "sugar_g": 0.36, "sodium_mg": 909.12, "cholesterol_mg": 22.25, "potassium_mg": 436.54, "calcium_mg": 147.95, "iron_mg": 3.89, "magnesium_mg": 65.74, "phosphorus_mg": 356.01, "zinc_mg": 4.6, "vitamin_a_mcg": 34.64, "vitamin_c_mg": 5.31, "vitamin_d_mcg": 0.1, "vitamin_e_mg": 1.33, "vitamin_k_mcg": 12.06, "vitamin_b6_mg": 0.16, "vitamin_b12_mcg": 0.42, "thiamin_mg": 0.05, "riboflavin_mg": 0.22, "niacin_mg": 0.33, "folate_mcg": 12.8, "water_g": 26.11, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store lamb and feta separately if possible to maintain texture.", "duration": "P3D"}, "freezer": {"notes": "Freeze cooked lamb without the feta topping.", "duration": "P2M"}, "reheating": "Gently reheat in a skillet over low heat until warm. Do not microwave if possible to avoid toughening the meat.", "does_not_keep": false}', '[{"name": "Heavy-bottomed skillet or Cast iron pan", "required": true, "alternative": "Grill pan"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Meat thermometer", "required": false, "alternative": "Instant-read thermometer"}]', '[{"symptom": "Lamb is tough or chewy", "likely_cause": "Overcooking", "prevention": "Use a meat thermometer and pull the meat from the heat 2-3 degrees before your target temperature (it rises while resting).", "fix": "Slice thinly against the grain and serve with extra sauce to mask dryness; cannot be reversed."}, {"symptom": "Garlic is bitter and black", "likely_cause": "Garlic was added too early or heat was too high", "prevention": "Add garlic only after flipping the meat, during the last few minutes of cooking.", "fix": "Scrape burnt garlic off the meat before serving."}]', '["Bring the lamb chops to room temperature for 20 minutes before cooking. Cold meat seizes up in a hot pan, cooking unevenly.", "Use a block of feta in brine and crumble it yourself. Pre-crumbled feta often contains anti-caking agents that prevent it from softening pleasantly.", "For a true ''five ingredient'' meal (excluding staples like oil, salt, and pepper), this recipe shines because the lemon acidity cuts through the rich lamb fat while the feta adds the necessary salt punch.", "If you have fresh oregano, use it for garnish at the end, but stick to dried oregano for the searing crust as it withstands high heat better without becoming bitter."]', '"Lamb is a cornerstone of Greek cuisine, often celebrated at Easter and family gatherings. The pairing of oregano (rigani) and lemon (lemono) is the quintessential Greek flavor profile, known as ''Ladolemono'' when mixed with olive oil. This preparation reflects the rustic simplicity of Greek taverna cooking."', 613.4);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('65bc337b-725c-4a07-a3a8-d7dbb012f6f9', 'Penne al Pomodoro Fresco', 'A vibrant and classic summer pasta dish celebrating the sweetness of ripe, fresh tomatoes. The sauce is cooked quickly to preserve the bright acidity and texture of the fruit, emulsified with starchy pasta water and finished with fragrant fresh basil.', 'dinner', 'Italian', 'Easy', '["italian", "pastas", "basil", "penne", "tomato", "dinner", "easy", "quick", "summer", "vegetarian"]', '[{"group_name": "Pasta", "items": [{"name": "penne rigate", "quantity": 320, "unit": "g", "preparation": "dried", "notes": "bronze-die cut preferred for better sauce adhesion", "substitutions": [], "ingredient_id": "4b1266bd-0436-4393-9f4f-34ca038ad90e", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 4000, "unit": "ml", "preparation": null, "notes": "for boiling", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt", "quantity": 40, "unit": "g", "preparation": null, "notes": "for pasta water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sauce", "items": [{"name": "fresh ripe tomatoes", "quantity": 600, "unit": "g", "preparation": "diced", "notes": "Roma, San Marzano, or sweet cherry tomatoes", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": "high quality", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "smashed and peeled", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh basil", "quantity": 15, "unit": "g", "preparation": "whole or torn", "notes": "save some for garnish", "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Wash and dice the tomatoes into 2cm cubes. Peel and smash the garlic cloves with the flat side of a knife.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Bring a large pot of water to a rolling boil. Once boiling, add the 40g of salt.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "While water heats, add olive oil and smashed garlic to a large cold skillet. Turn heat to medium and saut\u00e9 gently until the garlic is golden and fragrant, about 2-3 minutes. Do not burn.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Garlic is golden brown", "tactile": "Oil is fragrant"}}, "tips": ["Starting garlic in cold oil infuses the flavor more deeply without burning."]}, {"step_number": 4, "phase": "cook", "text": "Remove the garlic cloves (optional). Add the diced tomatoes and a pinch of salt to the skillet. Increase heat to medium-high and cook for 8-10 minutes, stirring occasionally, until tomatoes release their juices and soften but still hold some shape.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the penne to the boiling water. Cook for 1-2 minutes less than the package instructions indicate for al dente.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT9M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Reserve about 120ml (half a cup) of starchy pasta water. Drain the penne.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Transfer the pasta directly into the skillet with the tomatoes. Add a splash (approx 30-50ml) of the reserved pasta water. Toss vigorously over medium heat for 1 minute to emulsify the oil and water into a creamy coating.", "structured": {"action": "TOSS", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Sauce looks glossy and clings to pasta", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from heat. Stir in the fresh basil leaves. Season with salt and black pepper to taste. Serve immediately.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Vegetarian", "Vegan", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 447.16, "protein_g": 11.25, "carbohydrates_g": 66.29, "fat_g": 16.95, "saturated_fat_g": 2.12, "trans_fat_g": null, "monounsaturated_fat_g": 10.96, "polyunsaturated_fat_g": 1.6, "fiber_g": 6.89, "sugar_g": 7.5, "sodium_mg": 4117.11, "cholesterol_mg": null, "potassium_mg": 387.91, "calcium_mg": 122.05, "iron_mg": 2.16, "magnesium_mg": 30.18, "phosphorus_mg": 43.09, "zinc_mg": 0.33, "vitamin_a_mcg": 9.97, "vitamin_c_mg": 22.16, "vitamin_d_mcg": null, "vitamin_e_mg": 2.19, "vitamin_k_mcg": 25.05, "vitamin_b6_mg": 0.04, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.01, "niacin_mg": 0.06, "folate_mcg": 2.68, "water_g": 1005.27, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Reheat gently with a splash of water.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; fresh tomato texture degrades significantly upon freezing.", "duration": null}, "reheating": "Warm in a pan over low heat with a splash of water to re-emulsify the sauce.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": "Dutch oven"}, {"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": "Wide saucepan"}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Sauce is too watery and doesn''t stick to pasta", "likely_cause": "Tomatoes released too much water or not enough emulsion occurred", "prevention": "Cook tomatoes at high enough heat to evaporate excess water; ensure vigorous tossing with pasta water", "fix": "Continue tossing over medium-high heat until the liquid reduces and coats the pasta"}]', '["Use the highest quality olive oil you have; in simple dishes with few ingredients, the fat carries the flavor.", "If your tomatoes are not in season or lack sweetness, a pinch of sugar or a teaspoon of tomato paste can balance the acidity.", "Tearing basil by hand rather than cutting it with a knife prevents the edges from bruising and turning black.", "Removing the garlic cloves before adding tomatoes provides a milder flavor; leave them in if you prefer a rustic, garlicky kick."]', '"This style of ''pasta al pomodoro'' emphasizes the freshness of the ingredients, typical of Southern Italian summer cooking. Unlike a rag\u00f9 or slow-cooked sugo, this preparation (often called ''al filetto'' when using cherry tomatoes) relies on the rapid cooking of ripe fruit to maintain a vibrant, fresh profile."', 447.16);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('661bbc84-dd97-42da-ba47-4de365a2205c', 'Ginger Coconut Whole Wheat Scones', 'Nutty, tender scones featuring the earthy depth of whole wheat pastry flour, brightened by zesty crystallized ginger and the subtle, creamy sweetness of coconut.', 'baked good', 'British', 'Intermediate', '["scone", "dessert", "healthy", "nut-free", "vegetarian", "breakfast", "whole grain"]', '[{"group_name": "Dry Ingredients", "items": [{"name": "whole wheat pastry flour", "quantity": 260, "unit": "g", "preparation": null, "notes": "spooned and leveled", "substitutions": [], "ingredient_id": "af2661d8-b555-4fef-bdee-51a5190eda92", "nutrition_source": "USDA FoodData Central"}, {"name": "cane sugar", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 12, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "ground ginger", "quantity": 2, "unit": "g", "preparation": null, "notes": "dried powder", "substitutions": [], "ingredient_id": "401ddd0b-3597-4b46-bb54-f3bc755048bb", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "unsweetened shredded coconut", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "dbd3e1d1-e181-4364-b869-f2e9c0f15317", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Cold Fats & Mix-ins", "items": [{"name": "unsalted butter", "quantity": 85, "unit": "g", "preparation": "very cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "crystallized ginger", "quantity": 40, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "94aa0dff-461d-4081-b1aa-bac372e8fc0d", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Wet Ingredients", "items": [{"name": "coconut milk", "quantity": 120, "unit": "ml", "preparation": "cold, full-fat canned", "notes": "plus 15ml for brushing", "substitutions": ["heavy cream"], "ingredient_id": "c037ee7e-e3ed-4340-b8fb-d8ad284ba96e", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Topping", "items": [{"name": "turbinado sugar", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 205\u00b0C (400\u00b0F). Line a baking sheet with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 205, "fahrenheit": 401}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, whisk together the whole wheat pastry flour, cane sugar, baking powder, ground ginger, salt, and shredded coconut until well combined.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Add the cold, cubed butter to the dry ingredients. Use a pastry blender or your fingertips to cut the butter into the flour until the mixture resembles coarse crumbs with some pea-sized pieces of butter remaining.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Coarse crumbs, pea-sized butter bits", "tactile": "Cold and sandy"}}, "tips": ["If the butter starts melting, put the bowl in the freezer for 5 minutes."]}, {"step_number": 4, "phase": "prep", "text": "Toss the chopped crystallized ginger into the flour mixture ensuring the pieces are coated and not stuck together.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Make a well in the center. Pour in the cold coconut milk and vanilla extract. Stir gently with a spatula just until a shaggy dough forms. Do not overmix.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Shaggy dough, no dry flour pockets", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Turn the dough onto a lightly floured surface. Gently pat it into a circle approximately 2.5cm (1 inch) thick. Use a bench scraper or knife to cut the circle into 8 equal wedges.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Transfer wedges to the prepared baking sheet, spacing them 5cm apart. Brush the tops with the reserved coconut milk and sprinkle with turbinado sugar.", "structured": {"action": "GLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Bake for 18-22 minutes, or until the tops are golden brown and the edges look set.", "structured": {"action": "BAKE", "temperature": {"celsius": 205, "fahrenheit": 401}, "duration": "PT20M", "doneness_cues": {"visual": "Golden brown tops", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove from the oven and transfer to a wire rack to cool slightly before serving.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT40M", "overnight_required": false, "yields": "8 scones", "yield_count": 8, "serving_size_g": 75}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Vegans (contains butter)", "Gluten intolerance"]}', '{"per_serving": {"calories": 296.11, "protein_g": 3.84, "carbohydrates_g": 39.06, "fat_g": 15.11, "saturated_fat_g": 8.68, "trans_fat_g": null, "monounsaturated_fat_g": 2.73, "polyunsaturated_fat_g": 0.74, "fiber_g": 5.44, "sugar_g": 10.27, "sodium_mg": 311.02, "cholesterol_mg": 22.84, "potassium_mg": 174.76, "calcium_mg": 106.39, "iron_mg": 1.7, "magnesium_mg": 44.81, "phosphorus_mg": 155.83, "zinc_mg": 1.08, "vitamin_a_mcg": 72.68, "vitamin_c_mg": 0.42, "vitamin_d_mcg": null, "vitamin_e_mg": 0.44, "vitamin_k_mcg": 1.38, "vitamin_b6_mg": 0.07, "vitamin_b12_mcg": 0.02, "thiamin_mg": 0.1, "riboflavin_mg": 0.07, "niacin_mg": 1.88, "folate_mcg": 11.85, "water_g": 16.32, "alcohol_g": 0.22, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container; texture is best fresh.", "duration": "P3D"}, "freezer": {"notes": "Freeze unbaked wedges for best results, baking from frozen with added time.", "duration": "P3M"}, "reheating": "Warm in a 150\u00b0C/300\u00b0F oven for 5-8 minutes to restore crispness.", "does_not_keep": false}', '[{"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Pastry blender", "required": false, "alternative": "Two knives or fingertips"}, {"name": "Bench scraper or sharp knife", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}]', '[{"symptom": "Scones are tough or dense", "likely_cause": "Overworking the dough developed too much gluten", "prevention": "Stop mixing as soon as the dough comes together; it should look shaggy/rough before patting out.", "fix": "Cannot be fixed once baked; serve warm with plenty of butter or jam."}, {"symptom": "Scones spread too much and are flat", "likely_cause": "Butter became too warm before baking", "prevention": "Keep ingredients cold; chill shaped scones in the fridge for 15 minutes before baking if your kitchen is warm.", "fix": "None"}]', '["Using whole wheat pastry flour is crucial here; regular whole wheat flour has a higher protein content that will result in a tough, heavy scone.", "Canned full-fat coconut milk provides the best tenderness due to its fat content. If using carton coconut beverage, the scones will be drier and less rich.", "Ensure your baking powder is fresh. Whole wheat flour is heavier than white flour and requires active leavening to achieve a good rise."]', '"Scones originated in Scotland in the early 1500s as quick breads cooked on griddles. This variation incorporates modern health-conscious ingredients like whole grains and tropical influences via coconut, bridging traditional British tea time with global flavor profiles."', 296.11);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('66d3764c-d8fe-43f5-8542-25843a525fd2', 'Sichuan-Style Garlic Eggplant with Minced Pork', 'Silky, melt-in-your-mouth eggplant batons braised with crispy ground pork in a glossy, savory, spicy, and slightly tangy garlic sauce. A classic balance of textures and bold umami flavors.', 'side dish', 'Chinese', 'Intermediate', '["asian", "eggplant", "side", "sichuan", "spicy", "stir-fry"]', '[{"group_name": "Vegetables", "items": [{"name": "chinese eggplants", "quantity": 500, "unit": "g", "preparation": "cut into batons", "notes": "long purple variety preferred", "substitutions": ["globe eggplant (cubed)"], "ingredient_id": "77c14307-dacf-4ab2-85d1-3594bff0ec99", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "for sweating eggplant", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 15, "unit": "g", "preparation": null, "notes": "for coating eggplant", "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": "divided use", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Pork & Aromatics", "items": [{"name": "ground pork", "quantity": 150, "unit": "g", "preparation": "minced", "notes": null, "substitutions": ["ground chicken", "finely chopped mushrooms (vegan option)"], "ingredient_id": "95b412ba-c68f-4b61-ae87-42b44000956b", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 4, "unit": null, "preparation": "minced", "notes": "approx 20g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 10, "unit": "g", "preparation": "minced", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "scallions", "quantity": 2, "unit": null, "preparation": "sliced", "notes": "whites and greens separated", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "doubanjiang", "quantity": 30, "unit": "g", "preparation": null, "notes": "spicy broad bean paste", "substitutions": ["chili garlic sauce"], "ingredient_id": "93076b4f-80eb-42d8-a5a0-78d680761a26", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Sauce", "items": [{"name": "soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "chinkiang vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": "black vinegar", "substitutions": ["balsamic vinegar", "rice vinegar"], "ingredient_id": "0cc677c9-e55b-478e-b6b1-8d1d2066cb94", "nutrition_source": "Aggregated Public Data"}, {"name": "sugar", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 60, "unit": "ml", "preparation": null, "notes": "or chicken stock", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "cornstarch", "quantity": 5, "unit": "g", "preparation": null, "notes": "dissolved in 10ml water for slurry", "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Toss the eggplant batons with the salt in a colander. Let sit for 15 minutes to draw out excess moisture and reduce bitterness.", "structured": {"action": "DRAIN", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": ["This step prevents the eggplant from absorbing too much oil during cooking."]}, {"step_number": 2, "phase": "prep", "text": "Rinse the salt off the eggplant thoroughly and pat very dry with paper towels. Dust lightly with the 15g of cornstarch.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a small bowl, whisk together soy sauce, Chinkiang vinegar, sugar, and water/stock to create the sauce base.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Heat 30ml of oil in a wok over medium-high heat (approx. 190\u00b0C/375\u00b0F). Pan-fry the eggplant in a single layer until golden brown and tender. Remove and set aside.", "structured": {"action": "FRY", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT5M", "doneness_cues": {"visual": "Golden brown edges", "tactile": "Soft center"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the remaining 15ml oil to the wok. Add ground pork and stir-fry until crispy and cooked through (internal temp 71\u00b0C/160\u00b0F), breaking up clumps with a spatula.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 71, "fahrenheit": 160}, "duration": null, "doneness_cues": {"visual": "Pork is browned and crispy", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Push pork to the side. Add minced garlic, ginger, scallion whites, and Doubanjiang (bean paste) to the center. Fry for 30 seconds until the oil turns red and aromatic.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Pour in the sauce mixture and bring to a simmer. Return the cooked eggplant to the pan. Stir gently to coat.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Stir in the cornstarch slurry. Toss until the sauce thickens and clings to the eggplant. Garnish with scallion greens and serve immediately.", "structured": {"action": "THICKEN", "temperature": null, "duration": null, "doneness_cues": {"visual": "Sauce is glossy and coats the spoon", "tactile": null}}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT15M", "total_time": "PT40M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Dairy-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": ["Vegetarians", "Vegans", "Gluten-Free diets (unless using tamari and GF bean paste)"]}', '{"per_serving": {"calories": 283.89, "protein_g": 8.82, "carbohydrates_g": 18.85, "fat_g": 19.9, "saturated_fat_g": 4.63, "trans_fat_g": null, "monounsaturated_fat_g": 3.57, "polyunsaturated_fat_g": 0.84, "fiber_g": 4.56, "sugar_g": 8.36, "sodium_mg": 1307.47, "cholesterol_mg": 27, "potassium_mg": 445.79, "calcium_mg": 32.19, "iron_mg": 0.92, "magnesium_mg": 28.76, "phosphorus_mg": 107.57, "zinc_mg": 1.13, "vitamin_a_mcg": 5.75, "vitamin_c_mg": 6.11, "vitamin_d_mcg": null, "vitamin_e_mg": 0.43, "vitamin_k_mcg": 19.99, "vitamin_b6_mg": 0.32, "vitamin_b12_mcg": 0.26, "thiamin_mg": 0.34, "riboflavin_mg": 0.15, "niacin_mg": 2.54, "folate_mcg": 34.6, "water_g": 165.35, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Texture softens significantly upon reheating.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; eggplant becomes mushy.", "duration": null}, "reheating": "Reheat gently in a skillet over low heat or microwave.", "does_not_keep": false}', '[{"name": "Wok or large skillet", "required": true, "alternative": "Deep saut\u00e9 pan"}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Paper towels", "required": true, "alternative": null}]', '[{"symptom": "Eggplant is greasy or oily", "likely_cause": "Eggplant was not salted or dried properly, or oil was too cool", "prevention": "Ensure thorough salting, drying, and cornstarch coating before frying", "fix": "Place cooked eggplant on paper towels to drain before mixing with sauce"}, {"symptom": "Dish is too salty", "likely_cause": "Doubanjiang and soy sauce are salty; eggplant wasn''t rinsed well", "prevention": "Rinse eggplant thoroughly after salting; use low-sodium stock", "fix": "Add a splash of water and a pinch more sugar to balance"}]', '["The secret to the bright purple color is cooking the eggplant quickly at high heat. Acid (vinegar) in the sauce also helps stabilize anthocyanins.", "Doubanjiang (broad bean chili paste) is the soul of this dish. Look for the Pixian variety for authentic depth.", "Do not skip the cornstarch coating on the eggplant; it creates a barrier that prevents oil absorption and helps the sauce cling later.", "If you prefer a softer texture, you can steam the eggplant for 10 minutes instead of frying, though you lose the caramelized flavor."]', '"Inspired by the Sichuan classic ''Yu Xiang Qie Zi'' (Fish-Fragrant Eggplant). Despite the name, it contains no fish; the ''fish fragrance'' comes from the specific combination of garlic, ginger, scallions, sugar, and vinegar traditionally used in Sichuan fish cookery."', 283.89);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('672fdce4-1ac7-40be-9946-0d4d146c6ba7', 'Golden Almond and Raisin Pilaf', 'A fragrant, jewel-toned basmati rice dish balancing the natural sweetness of golden raisins with the nutty crunch of toasted slivered almonds. Infused with turmeric and cinnamon, this pilaf is fluffy, aromatic, and visually stunning.', 'side dish', 'Middle Eastern', 'Easy', '["almond", "raisin", "rice", "easy", "quick", "side dish", "middle eastern", "vegan", "gluten-free"]', '[{"group_name": "Base", "items": [{"name": "basmati rice", "quantity": 300, "unit": "g", "preparation": "uncooked", "notes": "long grain is essential", "substitutions": [], "ingredient_id": "1cfffbd2-7ea5-4cbc-bc35-c57e12233152", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": "divided use", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx 100g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable broth", "quantity": 480, "unit": "ml", "preparation": "hot", "notes": null, "substitutions": ["chicken broth", "water"], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Aromatics & Add-ins", "items": [{"name": "slivered almonds", "quantity": 50, "unit": "g", "preparation": "raw", "notes": null, "substitutions": [], "ingredient_id": "5bcbb4d4-6845-4825-bd21-1c13e52b989c", "nutrition_source": "USDA FoodData Central"}, {"name": "golden raisins", "quantity": 60, "unit": "g", "preparation": null, "notes": "sultanas work well too", "substitutions": [], "ingredient_id": "786501db-965f-429e-94a0-ce2cdc06c667", "nutrition_source": "USDA FoodData Central"}, {"name": "ground turmeric", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1/2 tsp", "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "cinnamon stick", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 5g", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "adjust based on broth salinity", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Rinse the basmati rice in a fine mesh sieve under cold running water until the water runs clear (about 1-2 minutes). Shake off excess water and set aside.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Rinsing removes surface starch, ensuring the grains separate and don''t become gummy."]}, {"step_number": 2, "phase": "prep", "text": "In a dry pot over medium heat, toast the slivered almonds, stirring constantly until they turn golden brown and fragrant. Remove immediately to a small bowl to stop cooking.", "structured": {"action": "TOAST", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown color", "tactile": "Crisp texture"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In the same pot, heat the olive oil over medium heat. Add the diced onion and saut\u00e9 for 5-6 minutes until softened and translucent, but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the rinsed rice, turmeric, cinnamon stick, and salt to the onions. Stir gently for 1-2 minutes to toast the rice grains and coat them in the oil and spices.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Rice grains turn opaque and yellow", "tactile": null}}, "tips": ["Toasting the rice helps the grains hold their shape during steaming."]}, {"step_number": 5, "phase": "cook", "text": "Pour in the hot vegetable broth and add the raisins. Increase heat to high to bring to a rolling boil. Once boiling, immediately reduce heat to the lowest possible setting, cover with a tight-fitting lid, and simmer gently.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Turn off the heat. Do not open the lid. Let the pot sit undisturbed on the warm burner (or a trivet) for 5-10 minutes to finish steaming.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": ["This resting period is critical for fluffy rice; opening the lid releases necessary steam."]}, {"step_number": 7, "phase": "finish", "text": "Remove the lid and discard the cinnamon stick. Fluff the rice gently with a fork to separate the grains. Fold in the toasted almonds just before serving.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT20M", "total_time": "PT30M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 308.57, "protein_g": 4.31, "carbohydrates_g": 23.99, "fat_g": 13.95, "saturated_fat_g": 1.61, "trans_fat_g": null, "monounsaturated_fat_g": 9.44, "polyunsaturated_fat_g": 2.35, "fiber_g": 3.26, "sugar_g": 12.82, "sodium_mg": 1065.84, "cholesterol_mg": null, "potassium_mg": 311.94, "calcium_mg": 72.44, "iron_mg": 1.31, "magnesium_mg": 49.72, "phosphorus_mg": 95.08, "zinc_mg": 0.55, "vitamin_a_mcg": 32.01, "vitamin_c_mg": 3.16, "vitamin_d_mcg": null, "vitamin_e_mg": 4.36, "vitamin_k_mcg": 5.6, "vitamin_b6_mg": 0.1, "vitamin_b12_mcg": null, "thiamin_mg": 0.04, "riboflavin_mg": 0.18, "niacin_mg": 0.68, "folate_mcg": 10.88, "water_g": 84.06, "alcohol_g": 12.08, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Rice can dry out, so sprinkle with water before reheating.", "duration": "P3D"}, "freezer": {"notes": "Freeze in portions. Thaw overnight in the refrigerator.", "duration": "P1M"}, "reheating": "Microwave with a splash of water for 1-2 minutes or steam on stovetop.", "does_not_keep": false}', '[{"name": "Heavy-bottomed pot with tight-fitting lid", "required": true, "alternative": "Dutch oven or Deep skillet with lid"}, {"name": "Fine mesh sieve", "required": true, "alternative": null}, {"name": "Small frying pan", "required": false, "alternative": "Use the main pot before cooking rice"}, {"name": "Fork", "required": true, "alternative": null}]', '[{"symptom": "Rice is mushy or gummy", "likely_cause": "Rice wasn''t rinsed enough or too much water was added", "prevention": "Rinse until water runs clear and measure liquids precisely", "fix": "Spread rice on a baking sheet to let moisture evaporate"}, {"symptom": "Rice is crunchy or undercooked", "likely_cause": "Lid was loose allowing steam to escape, or heat was too high causing water to evaporate too fast", "prevention": "Use a heavy lid and keep heat on lowest setting", "fix": "Add 30-50ml hot water, cover tightly, and cook on very low for 5 more minutes"}]', '["For extra flavor, soak the raisins in warm water or orange juice for 10 minutes before adding them, though adding them directly to the broth works well for a simpler version.", "Using hot stock instead of cold helps the rice cook more evenly and prevents the temperature from dropping drastically when added.", "If you enjoy a richer dish, finish with a small knob of butter or ghee when fluffing the rice."]', '"This dish draws inspiration from Middle Eastern and Persian ''Polow'' or pilaf traditions, where rice is treated as a canvas for dried fruits, nuts, and spices. The combination of sweet (raisins) and savory (onions/broth) is a hallmark of the region''s culinary profile."', 308.57);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('67ab859d-29d8-4117-84f2-a845d9e7e476', 'Savory Buttermilk Cornbread Muffins with Fresh Corn & Coriander', 'Golden, tender muffins bursting with fresh corn kernels and speckled with bright, grassy coriander. The buttermilk provides a moist crumb and subtle tang, while the savory profile makes them an ideal companion for hearty stews or holiday spreads.', 'side dish', 'American', 'Easy', '["buttermilk", "corn", "cornmeal", "great leftovers", "muffin", "side dish", "kwanzaa", "thanksgiving"]', '[{"group_name": "Dry Ingredients", "items": [{"name": "yellow cornmeal", "quantity": 150, "unit": "g", "preparation": "medium grind", "notes": "provides texture", "substitutions": [], "ingredient_id": "7fb6be00-5ba2-483a-af74-961f21de4055", "nutrition_source": "Aggregated Public Data"}, {"name": "all-purpose flour", "quantity": 150, "unit": "g", "preparation": null, "notes": "unbleached preferred", "substitutions": ["gluten-free all-purpose flour blend"], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": "for balance, not sweetness", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "fine sea salt", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wet Ingredients", "items": [{"name": "buttermilk", "quantity": 240, "unit": "ml", "preparation": "room temperature", "notes": "shake well before measuring", "substitutions": [], "ingredient_id": "de1c3d44-e3e7-47d2-a315-83a46edfb165", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 85, "unit": "g", "preparation": "melted and cooled", "notes": null, "substitutions": ["vegetable oil", "bacon fat"], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "room temperature, large", "notes": "approx 100g total without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Add-ins", "items": [{"name": "fresh corn kernels", "quantity": 150, "unit": "g", "preparation": "raw, cut from cob", "notes": "approx 1-2 ears", "substitutions": ["frozen corn (thawed and drained)", "canned corn (drained and patted dry)"], "ingredient_id": "46ca2aab-cb23-4397-9711-528c234b2cf8", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh coriander (cilantro)", "quantity": 10, "unit": "g", "preparation": "finely chopped leaves and tender stems", "notes": null, "substitutions": [], "ingredient_id": "8c7693be-b538-445c-80f9-3d5bf4c6dcc0", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 200\u00b0C/400\u00b0F. Generously grease the muffin tin cups with butter or cooking spray.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, whisk together the cornmeal, flour, sugar, baking powder, baking soda, and salt until thoroughly combined and free of lumps.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a medium bowl, whisk the room temperature buttermilk, eggs, and melted cooled butter until the mixture is uniform and emulsified.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Ensure the butter is not hot, or it will scramble the eggs."]}, {"step_number": 4, "phase": "cook", "text": "Pour the wet ingredients into the dry ingredients. Using a silicone spatula, gently fold the mixture until it is barely combined and streaks of flour remain.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the fresh corn kernels and chopped coriander. Fold gently just until the flour streaks disappear and the add-ins are distributed. Do not overmix.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Overmixing develops gluten, leading to tough muffins rather than a tender crumb."]}, {"step_number": 6, "phase": "cook", "text": "Divide the batter evenly among the 12 muffin cups. They should be nearly full.", "structured": {"action": "MEASURE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Bake for 15 to 18 minutes, or until the tops are golden brown and a toothpick inserted into the center comes out clean.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT15M", "doneness_cues": {"visual": "Golden brown dome", "tactile": "Springs back lightly when touched"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Let the muffins cool in the pan for 5 minutes, then transfer them to a wire rack to cool completely.", "structured": {"action": "COOL", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT20M", "total_time": "PT35M", "overnight_required": false, "yields": "12 muffins", "yield_count": 12, "serving_size_g": 75}', '{"flags": ["Vegetarian", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Vegans (contains dairy, eggs)", "Coeliacs (contains wheat)"]}', '{"per_serving": {"calories": 196.2, "protein_g": 4.67, "carbohydrates_g": 28.28, "fat_g": 7.49, "saturated_fat_g": 4.09, "trans_fat_g": null, "monounsaturated_fat_g": 2.08, "polyunsaturated_fat_g": 0.49, "fiber_g": 1.55, "sugar_g": 4.63, "sodium_mg": 370.5, "cholesterol_mg": 47.03, "potassium_mg": 130.93, "calcium_mg": 82.79, "iron_mg": 1.32, "magnesium_mg": 42.91, "phosphorus_mg": 139.53, "zinc_mg": 0.81, "vitamin_a_mcg": 124.69, "vitamin_c_mg": 1.28, "vitamin_d_mcg": 0.17, "vitamin_e_mg": 0.28, "vitamin_k_mcg": 0.62, "vitamin_b6_mg": 0.04, "vitamin_b12_mcg": 0.13, "thiamin_mg": 0.04, "riboflavin_mg": 0.08, "niacin_mg": 0.4, "folate_mcg": 13.63, "water_g": 37.32, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container to prevent drying out.", "duration": "P1W"}, "freezer": {"notes": "Wrap individually in foil and place in a freezer bag.", "duration": "P3M"}, "reheating": "Warm in a 150\u00b0C/300\u00b0F oven for 5-8 minutes or microwave briefly.", "does_not_keep": false}', '[{"name": "12-cup standard muffin tin", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Medium mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Silicone spatula", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}]', '[{"symptom": "Muffins are tough or rubbery", "likely_cause": "Batter was overmixed after adding liquid", "prevention": "Stop mixing as soon as the dry ingredients are moistened; lumps are okay.", "fix": "Cannot be fixed after baking; serve warm with extra butter to mask texture."}, {"symptom": "Muffins didn''t rise well", "likely_cause": "Leavening agents (baking powder/soda) are expired", "prevention": "Check expiration dates on baking powder and soda before starting.", "fix": "Cannot be fixed."}]', '["Using medium-grind cornmeal provides a pleasant crunch and rustic texture that distinguishes these from cake-like muffins.", "For the best corn flavor, cut the kernels off the cob vertically, then scrape the cob with the back of your knife to release the corn milk into the batter.", "Room temperature ingredients are crucial here; cold buttermilk or eggs will solidify the melted butter instantly, creating clumpy batter and uneven baking."]', '"Cornbread is a foundational pillar of American Southern cuisine, tracing its roots to Native American maize preparations adopted by early settlers and enslaved Africans. It holds a significant place in Soul Food traditions and is a staple at communal gatherings like Thanksgiving and Kwanzaa."', 196.2);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('69687b01-c849-4ee5-8cb7-655a1afc3008', 'Velouté of White Asparagus with Sautéed Morels', 'A sophisticated, velvety soup capturing the fleeting magic of spring. The delicate, slightly bitter sweetness of white asparagus is enriched with heavy cream and contrasted by the earthy, nutty depth of pan-seared morel mushrooms.', 'soup', 'French', 'Intermediate', '["asparagus", "great leftovers", "heavy cream", "morel", "soup", "appetizer", "side", "spring", "summer", "gluten-free"]', '[{"group_name": "Soup Base", "items": [{"name": "white asparagus", "quantity": 1000, "unit": "g", "preparation": "thick spears preferred", "notes": "weight before peeling", "substitutions": [], "ingredient_id": "c60484d6-2ff3-4138-8887-99930087a52c", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 40, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "shallots", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx. 60g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "leek", "quantity": 1, "unit": null, "preparation": "white part only, sliced", "notes": "approx. 100g", "substitutions": [], "ingredient_id": "f0bddafa-51db-4e56-954b-18624daa6fa4", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable stock", "quantity": 800, "unit": "ml", "preparation": null, "notes": "high quality, low sodium", "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 150, "unit": "ml", "preparation": "35% fat or higher", "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, kosher preferred", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "white pepper", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Morel Garnish", "items": [{"name": "fresh morel mushrooms", "quantity": 200, "unit": "g", "preparation": "cleaned thoroughly", "notes": null, "substitutions": ["30g dried morels (rehydrated)", "chanterelles"], "ingredient_id": "59d83971-a3c1-4b9c-b949-625005657048", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh chives", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the asparagus: Snap off the woody bottom ends (about 2-3 cm). Using a vegetable peeler, peel the stalks starting from just below the tip all the way to the bottom. Cut into 2 cm pieces, reserving the tips separately.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["White asparagus has a tough, fibrous skin that must be removed entirely, or the soup will be stringy.", "Save the peels and woody ends to make a quick asparagus stock if desired."]}, {"step_number": 2, "phase": "prep", "text": "Clean the morels: Slice larger morels in half lengthwise. Rinse quickly under cold water to remove sand, then pat immediately and thoroughly dry with paper towels.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Do not soak fresh morels for too long or they become waterlogged."]}, {"step_number": 3, "phase": "cook", "text": "In a large pot, melt 40g butter over medium heat. Add minced shallots and sliced leeks. Sweat for 5-7 minutes without browning until translucent.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT7M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the asparagus pieces (reserving the tips) to the pot. Cook for 3 minutes, stirring to coat in butter. Pour in vegetable stock and bring to a simmer. Cook for 15-20 minutes until asparagus is very tender.", "structured": {"action": "SIMMER", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "While the soup simmers, blanch the reserved asparagus tips in boiling salted water for 3 minutes until tender-crisp. Drain and set aside for garnish.", "structured": {"action": "BLANCH", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove soup from heat. Puree in a high-speed blender until smooth. Important: Pass the puree through a fine mesh sieve into a clean pot to remove any remaining fibers. This ensures a silky texture.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Use a ladle to push the mixture through the sieve."]}, {"step_number": 7, "phase": "finish", "text": "Return the strained soup to low heat. Whisk in heavy cream. Season with salt, white pepper, and lemon juice. Keep warm but do not boil.", "structured": {"action": "SEASON", "temperature": {"celsius": 80, "fahrenheit": 176}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "In a saut\u00e9 pan, melt 30g butter over medium-high heat. Add the prepared morels. Saut\u00e9 vigorously for 5-8 minutes until browned and tender. Season with a pinch of salt.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Golden brown edges", "tactile": "Firm but tender"}}, "tips": ["Morels contain small amounts of hydrazine toxins which are destroyed by thorough cooking. Never eat them raw."]}, {"step_number": 9, "phase": "assemble", "text": "Ladle soup into warmed bowls. Garnish with saut\u00e9ed morels, blanched asparagus tips, and fresh chives.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT40M", "passive_time": "PT0M", "total_time": "PT40M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 300}', '{"flags": ["Gluten-Free", "Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Vegans (contains dairy)"]}', '{"per_serving": {"calories": 361.32, "protein_g": 10.8, "carbohydrates_g": 24.1, "fat_g": 28.78, "saturated_fat_g": 17.6, "trans_fat_g": 0.47, "monounsaturated_fat_g": 7.54, "polyunsaturated_fat_g": 1.34, "fiber_g": 8.18, "sugar_g": 10.4, "sodium_mg": 1198.93, "cholesterol_mg": 80, "potassium_mg": 1420.03, "calcium_mg": 201.78, "iron_mg": 17.74, "magnesium_mg": 96.77, "phosphorus_mg": 411.07, "zinc_mg": 3.91, "vitamin_a_mcg": 485.58, "vitamin_c_mg": 38.64, "vitamin_d_mcg": 3.15, "vitamin_e_mg": 0.76, "vitamin_k_mcg": 2.55, "vitamin_b6_mg": 0.14, "vitamin_b12_mcg": 0.09, "thiamin_mg": 0.05, "riboflavin_mg": 0.18, "niacin_mg": 1.19, "folate_mcg": 12.14, "water_g": 83.57, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store soup and mushrooms in separate airtight containers to maintain texture.", "duration": "P3D"}, "freezer": {"notes": "Freeze the soup base only; the cream may separate upon thawing (blend to re-emulsify). Do not freeze cooked morels.", "duration": "P2M"}, "reheating": "Gently reheat soup on stove over low heat. Re-crisp mushrooms in a pan with a little butter.", "does_not_keep": false}', '[{"name": "High-speed blender", "required": true, "alternative": "Immersion blender"}, {"name": "Fine mesh sieve (Chinois)", "required": true, "alternative": "Standard strainer lined with cheesecloth"}, {"name": "Vegetable peeler", "required": true, "alternative": null}, {"name": "Large pot (Dutch oven)", "required": true, "alternative": null}, {"name": "Saut\u00e9 pan", "required": true, "alternative": null}]', '[{"symptom": "Soup has a fibrous or stringy texture", "likely_cause": "Asparagus was not peeled thoroughly enough or soup was not passed through a fine sieve", "prevention": "Peel white asparagus aggressively; always use a chinois/fine sieve", "fix": "Pass the soup through the finest sieve you have again"}, {"symptom": "Sand or grit in the garnish", "likely_cause": "Morels were not cleaned properly", "prevention": "Rinse morels well or use a pastry brush for crevices; if using dried, strain the soaking liquid", "fix": "Cannot be fixed once added to soup"}]', '["White asparagus must be kept in the dark while growing to prevent photosynthesis, which turns it green and bitter. This recipe relies on that delicate, milder flavor.", "If using dried morels, rehydrate them in warm water for 20 minutes. The strained soaking liquid is ''liquid gold''\u2014add it to the vegetable stock for intense mushroom flavor.", "For an ultra-luxurious finish (Michelin style), whisk 30g of cold butter cubes into the soup just before serving (mounting with butter)."]', '"White asparagus, often called ''white gold'' in Europe, is celebrated with near-religious fervor during ''Spargelzeit'' (asparagus season) in Germany and France. Pairing it with morels, another spring ephemeral, is a classic French technique that highlights the terroir of the season."', 361.32);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('6a7a0391-0f9c-4c09-90c3-cf82a4cb1368', 'Honey-Chili Glazed Lamb with Orange Herb Couscous', 'Succulent lamb chops pan-seared and coated in a sticky, spicy honey-chili glaze, served atop light, fluffy couscous brightened with fresh orange zest, juice, and a generous handful of aromatic soft herbs.', 'dinner', 'Mediterranean', 'Intermediate', '["lamb", "couscous", "dinner", "mediterranean", "spicy", "date night"]', '[{"group_name": "Lamb & Glaze", "items": [{"name": "lamb rib chops", "quantity": 8, "unit": null, "preparation": "room temperature, pat dry", "notes": "approx. 800g total weight", "substitutions": [], "ingredient_id": "21732d70-c203-4b79-b6e5-35a241ceb018", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c28eb19b-d201-4613-8f48-6a449cc81c71", "nutrition_source": "Aggregated Public Data"}, {"name": "red chili", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "seeds removed for less heat if desired", "substitutions": [], "ingredient_id": "3c3f97d4-c951-43fd-865c-88fa8b445739", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx. 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Citrus Herb Couscous", "items": [{"name": "dried couscous", "quantity": 200, "unit": "g", "preparation": "medium grain", "notes": null, "substitutions": [], "ingredient_id": "98ca56e9-68ee-4dd1-aab7-c26cca367098", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable stock", "quantity": 250, "unit": "ml", "preparation": "boiling", "notes": null, "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "oranges", "quantity": 2, "unit": null, "preparation": "zested and segmented", "notes": "reserve all juice released during segmentation", "substitutions": [], "ingredient_id": "4ad45ba2-5b03-41b7-8c75-b6ffde938100", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh mint", "quantity": 15, "unit": "g", "preparation": "leaves picked and roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "17abecc0-a2a0-4478-8486-57b46e4305c9", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "leaves picked and roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Season the lamb chops generously on both sides with salt and freshly ground black pepper. Allow them to sit at room temperature for 10-15 minutes.", "structured": {"action": "SEASON", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a small bowl, whisk together the honey, minced chili, minced garlic, ground cumin, and half of the orange zest. Set aside.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Place the dried couscous in a heatproof bowl. Pour the boiling vegetable stock over the couscous, cover tightly with cling film or a plate, and let stand for 5 minutes.", "structured": {"action": "SOAK", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "While couscous steams, heat olive oil in a large skillet over medium-high heat. Add lamb chops and sear until golden brown, about 3-4 minutes per side.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT8M", "doneness_cues": {"visual": "Golden brown crust", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Reduce heat to medium-low. Pour the honey-chili mixture into the pan. Baste the chops repeatedly with the bubbling glaze for 2 minutes until the sauce thickens and the lamb reaches an internal temperature of 57\u00b0C/135\u00b0F for medium-rare.", "structured": {"action": "GLAZE", "temperature": {"celsius": 57, "fahrenheit": 135}, "duration": "PT2M", "doneness_cues": {"visual": "Glaze is sticky and coats the back of a spoon", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove lamb from the pan and set aside to rest on a warm plate for 5 minutes. Reserve the pan juices.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Uncover the couscous and fluff with a fork. Fold in the remaining orange zest, orange segments (and their juice), chopped mint, chopped parsley, and extra virgin olive oil.", "structured": {"action": "MIX", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Serve the lamb chops over a bed of the herb couscous. Drizzle the remaining sticky glaze from the skillet over the meat.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT10M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Dairy-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Infants under 12 months (honey)", "Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 914.84, "protein_g": 54.8, "carbohydrates_g": 61.94, "fat_g": 43.05, "saturated_fat_g": 18.7, "trans_fat_g": null, "monounsaturated_fat_g": 8.4, "polyunsaturated_fat_g": 1.4, "fiber_g": 4.95, "sugar_g": 19.15, "sodium_mg": 943.46, "cholesterol_mg": null, "potassium_mg": 890.66, "calcium_mg": 98.35, "iron_mg": 5.85, "magnesium_mg": 80.34, "phosphorus_mg": 445.8, "zinc_mg": 6.13, "vitamin_a_mcg": 118.09, "vitamin_c_mg": 43.99, "vitamin_d_mcg": null, "vitamin_e_mg": 1.83, "vitamin_k_mcg": 69.7, "vitamin_b6_mg": 0.15, "vitamin_b12_mcg": null, "thiamin_mg": 0.17, "riboflavin_mg": 0.09, "niacin_mg": 2.22, "folate_mcg": 32.64, "water_g": 76.64, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store lamb and couscous in separate airtight containers.", "duration": "P3D"}, "freezer": {"notes": null, "duration": null}, "reheating": "Reheat lamb gently in a pan over low heat; steam or microwave couscous with a splash of water.", "does_not_keep": false}', '[{"name": "Large heavy-bottomed skillet", "required": true, "alternative": null}, {"name": "Heatproof bowl", "required": true, "alternative": "Saucepan with lid"}, {"name": "Microplane or zester", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Glaze burned in the pan", "likely_cause": "Heat was too high after adding the honey", "prevention": "Honey burns at low temperatures; always reduce heat to low before adding the glaze mixture.", "fix": "Do not serve the burnt glaze. Make a quick fresh batch in a clean small pot if ingredients allow."}, {"symptom": "Couscous is mushy or clumpy", "likely_cause": "Too much liquid or over-agitated while hot", "prevention": "Measure liquid ratio precisely and only fluff with a fork once absorbed.", "fix": "Spread onto a baking sheet to let steam escape and dry out slightly."}]', '["To segment the orange (supreme), cut off the top and bottom, stand it up, and slice off the skin and pith following the curve of the fruit. Then slice between the membranes to release the segments.", "If using a thicker cut of lamb (like loin chops), you may need to finish them in the oven for 5 minutes after glazing.", "For extra texture, toasted pine nuts or pistachios make an excellent addition to the couscous.", "Do not skip resting the meat; it allows the juices to redistribute so they don''t run out when you cut into the chop."]', '"This dish draws inspiration from Moroccan cuisine, where the pairing of savory meat with sweet fruit (honey, orange) and spicy heat is a classic flavor profile known as ''agrodolce'' in the Mediterranean or ''tagine'' style combinations in North Africa."', 914.84);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('6a820440-3e8d-4f47-ba27-293c0a529ac0', 'Nectarine and Blackberry Oat Crisp', 'A celebration of summer produce featuring juicy, floral nectarines and tart blackberries beneath a golden, crunchy topping of buttery oats and brown sugar. The filling bubbles into a jammy consistency while the crust remains distinct and crisp.', 'dessert', 'American', 'Easy', '["blackberry", "crisp", "nectarine", "rolled oat", "dessert", "summer", "baked good", "comfort food"]', '[{"group_name": "Fruit Filling", "items": [{"name": "nectarines", "quantity": 800, "unit": "g", "preparation": "sliced into wedges", "notes": "approximately 6-7 medium fruits, pitted but skins left on", "substitutions": [], "ingredient_id": "d699ed69-8d97-460f-8fbb-99b73a9fbf19", "nutrition_source": "USDA FoodData Central"}, {"name": "blackberries", "quantity": 300, "unit": "g", "preparation": "whole, washed and dried", "notes": null, "substitutions": [], "ingredient_id": "ce7c9c9b-08d3-4496-8b7f-e45c2ee8d6bf", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": "adjust slightly based on fruit sweetness", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 25, "unit": "g", "preparation": null, "notes": "thickening agent", "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Oat Crumble Topping", "items": [{"name": "all-purpose flour", "quantity": 120, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "old-fashioned rolled oats", "quantity": 90, "unit": "g", "preparation": null, "notes": "do not use instant oats for best texture", "substitutions": [], "ingredient_id": "11381622-c748-499c-b9c5-58fcb9d70fd3", "nutrition_source": "Aggregated Public Data"}, {"name": "light brown sugar", "quantity": 150, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 1/2 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "cold and cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 190\u00b0C (375\u00b0F). Lightly grease a 2-liter baking dish with a small amount of butter.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, gently toss the sliced nectarines and blackberries with the granulated sugar, cornstarch, lemon juice, and vanilla extract until the fruit is evenly coated and no dry pockets of starch remain.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Be gentle with the blackberries to avoid crushing them before baking."]}, {"step_number": 3, "phase": "prep", "text": "In a medium bowl, whisk together the flour, rolled oats, brown sugar, cinnamon, and salt. Add the cold cubed butter and work it into the dry ingredients using your fingertips or a pastry blender until the mixture resembles coarse wet sand with pea-sized clumps of butter remaining.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Coarse wet sand texture", "tactile": "Mixture holds together when squeezed"}}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Transfer the fruit mixture into the prepared baking dish, spreading it into an even layer. Sprinkle the oat crumble topping generously over the fruit, covering it completely.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Bake in the preheated oven for 45 to 50 minutes. The topping should be deep golden brown, and the fruit filling must be bubbling vigorously, not just at the edges but in the center of the dish.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT50M", "doneness_cues": {"visual": "Filling bubbling in the center, topping golden brown", "tactile": null}}, "tips": ["If the topping browns too quickly before the filling bubbles, tent loosely with aluminum foil."]}, {"step_number": 6, "phase": "finish", "text": "Remove from the oven and place on a wire rack. Allow the crisp to rest for at least 20 minutes before serving. This rest period allows the fruit juices to thicken into a sauce.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT1H10M", "total_time": "PT1H30M", "overnight_required": false, "yields": "8 servings", "yield_count": 8, "serving_size_g": 180}', '{"flags": ["Vegetarian", "Egg-Free", "Soy-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 394.79, "protein_g": 4.78, "carbohydrates_g": 67.56, "fat_g": 13.11, "saturated_fat_g": 7.43, "trans_fat_g": 0.11, "monounsaturated_fat_g": 3.49, "polyunsaturated_fat_g": 0.71, "fiber_g": 5.4, "sugar_g": 40.67, "sodium_mg": 154.19, "cholesterol_mg": 30.91, "potassium_mg": 351.22, "calcium_mg": 47.85, "iron_mg": 1.38, "magnesium_mg": 37.74, "phosphorus_mg": 101.53, "zinc_mg": 0.91, "vitamin_a_mcg": 119.49, "vitamin_c_mg": 14.01, "vitamin_d_mcg": null, "vitamin_e_mg": 1.56, "vitamin_k_mcg": 10.75, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": 0.03, "thiamin_mg": 0.06, "riboflavin_mg": 0.06, "niacin_mg": 1.59, "folate_mcg": 19.28, "water_g": 127.39, "alcohol_g": 0.22, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Cover tightly; topping may soften over time. Re-crisp in oven.", "duration": "P3D"}, "freezer": {"notes": "Bake from frozen if unbaked, or thaw and reheat if baked.", "duration": "P3M"}, "reheating": "Reheat in a 175\u00b0C (350\u00b0F) oven for 10-15 minutes to restore crispness.", "does_not_keep": false}', '[{"name": "Baking dish (2 liter capacity)", "required": true, "alternative": "9x9 inch square pan or 10-inch cast iron skillet"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Medium mixing bowl", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Pastry blender", "required": false, "alternative": "Forks or fingertips"}]', '[{"symptom": "Filling is too runny/watery", "likely_cause": "The crisp was not baked long enough for the cornstarch to activate, or it was cut while too hot.", "prevention": "Ensure the filling bubbles in the absolute center of the dish before removing from the oven.", "fix": "Let it cool completely to thicken; next time bake longer."}]', '["Leave the skins on the nectarines; they provide beautiful color and help the fruit slices maintain their structure during baking.", "Temperature of the butter is crucial for the topping. If the butter melts before baking, the topping will be dense rather than crumbly. Keep it cold.", "Serve warm with a scoop of vanilla bean ice cream or a dollop of cr\u00e8me fra\u00eeche to balance the sweetness.", "If your stone fruit is very hard and under-ripe, add an extra tablespoon of sugar and macerate (let sit in sugar) for 20 minutes before assembling."]', '"The fruit crisp is a quintessential North American dessert, popularized in the early 20th century as a simpler, crustless alternative to pie. While often confused with cobblers (biscuit topping) or crumbles (UK origin, usually no oats), the defining feature of a ''crisp'' is the inclusion of oats in the streusel topping, which crisp up during baking."', 394.79);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('6bf985a8-b6fe-4e98-a9d5-8a697ac1d2a1', 'Pan-Seared Lamb Medallions with Leek and Tarragon Crème', 'Succulent, pink-centered lamb loin medallions resting in a velvety sauce of melted leeks and anise-scented fresh tarragon. The sweetness of the slow-cooked leeks perfectly balances the earthy richness of the lamb for a sophisticated bistro-style dinner.', 'dinner', 'French', 'Intermediate', '["lamb", "leek", "dinner", "main course", "french", "date night", "gluten-free"]', '[{"group_name": "Lamb", "items": [{"name": "lamb loin fillets", "quantity": 600, "unit": "g", "preparation": "trimmed of silverskin", "notes": "Backstrap or boneless loin", "substitutions": ["lamb noisettes", "tenderloin"], "ingredient_id": "e14ce29f-d014-4606-b7ba-39e73c5a3678", "nutrition_source": "USDA FoodData Central"}, {"name": "grapeseed oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "or any high heat neutral oil", "substitutions": [], "ingredient_id": "00f43166-1b77-4e77-9e30-e912a59d118a", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 5g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Leek & Tarragon Sauce", "items": [{"name": "leeks", "quantity": 2, "unit": null, "preparation": "white and light green parts only, washed thoroughly and sliced into thin rounds", "notes": "approx 300g sliced", "substitutions": [], "ingredient_id": "f0bddafa-51db-4e56-954b-18624daa6fa4", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 80, "unit": "ml", "preparation": null, "notes": "Sauvignon Blanc or Pinot Grigio", "substitutions": ["chicken stock with splash of vinegar"], "ingredient_id": "0c041362-befe-4c15-88d2-ba97c8f46428", "nutrition_source": "USDA FoodData Central"}, {"name": "chicken stock", "quantity": 120, "unit": "ml", "preparation": null, "notes": "low sodium", "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 150, "unit": "ml", "preparation": null, "notes": "minimum 35% fat", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh tarragon leaves", "quantity": 10, "unit": "g", "preparation": "roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "d424d445-0a4e-45d1-9453-7523eb7b176b", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Slice the lamb loin into medallions approximately 3-4cm thick. Pat them dry with paper towels and season liberally with salt and pepper on both sides. Allow to sit at room temperature while preparing the vegetables.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Room temperature meat cooks more evenly than fridge-cold meat."]}, {"step_number": 2, "phase": "cook", "text": "In a large skillet, melt the butter over medium-low heat. Add the sliced leeks and a pinch of salt. Cook gently, stirring occasionally, until the leeks are completely soft and sweet but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Leeks are translucent and collapsed", "tactile": "Very soft resistance"}}, "tips": ["If the pan gets too dry, add a splash of water to steam the leeks slightly."]}, {"step_number": 3, "phase": "cook", "text": "Add the minced garlic to the leeks and cook for another 1 minute until fragrant. Remove the leek mixture from the pan and set aside in a bowl.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Wipe the pan out if needed or use a clean one. Heat the grapeseed oil over high heat until shimmering. Carefully place the lamb medallions in the pan. Sear undisturbed to develop a crust.", "structured": {"action": "SEAR", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Flip the medallions and sear the other side. Cook until an instant-read thermometer inserted into the center reads 52\u00b0C (125\u00b0F) for medium-rare or 57\u00b0C (135\u00b0F) for medium. Transfer lamb to a warm plate to rest loosely covered with foil.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Deep golden brown crust", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Discard excess fat from the pan but leave the browned bits (fond). Pour in the white wine to deglaze, scraping the bottom of the pan with a wooden spoon. Let the wine reduce by half.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Add the chicken stock and heavy cream to the pan. Bring to a simmer and let it reduce until slightly thickened (nappant consistency).", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Sauce coats the back of a spoon", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Return the cooked leeks to the sauce to warm through. Stir in the fresh tarragon and lemon juice. Taste and adjust seasoning with salt if necessary. Any resting juices from the lamb plate should be poured into the sauce.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "assemble", "text": "Spoon the creamy leek sauce onto plates. Arrange the lamb medallions on top of the sauce. Garnish with a sprig of fresh tarragon if desired.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT10M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 300}', '{"flags": ["Gluten-Free", "Low-Carb", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": ["Vegans", "Vegetarians"]}', '{"per_serving": {"calories": 569.53, "protein_g": 33.51, "carbohydrates_g": 15.66, "fat_g": 41.5, "saturated_fat_g": 19.22, "trans_fat_g": 0.84, "monounsaturated_fat_g": 10.27, "polyunsaturated_fat_g": 6.81, "fiber_g": 1.63, "sugar_g": 3.93, "sodium_mg": 1827.86, "cholesterol_mg": 165.56, "potassium_mg": 741.65, "calcium_mg": 125.3, "iron_mg": 4.68, "magnesium_mg": 66.73, "phosphorus_mg": 333.31, "zinc_mg": 4.25, "vitamin_a_mcg": 337.52, "vitamin_c_mg": 10.86, "vitamin_d_mcg": 0.6, "vitamin_e_mg": 3.1, "vitamin_k_mcg": 2.42, "vitamin_b6_mg": 0.27, "vitamin_b12_mcg": 2.93, "thiamin_mg": 0.19, "riboflavin_mg": 0.3, "niacin_mg": 8.14, "folate_mcg": 2.17, "water_g": 148.36, "alcohol_g": 1.78, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store sauce and meat separately if possible to prevent overcooking the lamb upon reheating.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; cream sauce may split and leek texture degrades.", "duration": null}, "reheating": "Gently warm sauce on stovetop over low heat. Slice cold lamb thinly to eat cold, or flash-warm in the sauce for 30 seconds only.", "does_not_keep": false}', '[{"name": "Large stainless steel skillet or cast iron pan", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Instant-read thermometer", "required": true, "alternative": "Touch test method (less accurate)"}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Leeks taste gritty", "likely_cause": "Sand trapped in the leek layers was not washed out properly", "prevention": "Slice leeks first, then submerge in a bowl of cold water and lift them out, leaving sediment at the bottom", "fix": "Cannot be fixed once cooked into the sauce"}, {"symptom": "Sauce splits (looks oily)", "likely_cause": "Boiled too vigorously after adding high-fat ingredients or reduction went too far", "prevention": "Maintain a gentle simmer, not a rolling boil, when reducing cream", "fix": "Add a teaspoon of cold water or cream and whisk vigorously off the heat"}]', '["The secret to tender medallions is the rest period. Do not cut into the meat immediately after searing, or the juices will run out, leaving the meat dry.", "If you cannot find lamb loin fillets, a rack of lamb can be cut into double chops and cooked similarly, though the timing may increase slightly due to the bone.", "Tarragon has a strong anise flavor; if you are sensitive to it, start with half the amount and add more to taste, or substitute with chives for a milder onion profile.", "Ensure the leeks are cooked ''fondue'' style\u2014slowly until they melt. They should provide a texture contrast to the firm sear of the meat."]', '"This dish draws heavily from French bistro cooking, specifically the pairing of ''agneau'' (lamb) with ''estragon'' (tarragon), a classic flavor affinity in French gastronomy. The use of a cream reduction with leeks (poireaux) reflects the cooking of Northern France, where dairy and alliums are staples."', 569.53);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('6cb85aa3-0523-430f-83ff-462e4c0ab96d', 'Aerial Chocolate Raspberry Sponge', 'A feather-light, fatless chocolate sponge that relies on aerated eggs rather than butter for its cloud-like lift. Filled with a sharp, ruby-red raspberry compote that cuts through the cocoa richness, serving as both the filling and a vibrant drizzle. An elegant, guilt-free finish to a meal.', 'dessert', 'French', 'Intermediate', '["chocolate", "cake", "raspberry", "dessert", "low-fat", "sponge", "dairy-free"]', '[{"group_name": "Fatless Chocolate Sponge", "items": [{"name": "large eggs", "quantity": 4, "unit": null, "preparation": "room temperature", "notes": "approx 200g total without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "caster sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "cake flour", "quantity": 80, "unit": "g", "preparation": null, "notes": "low protein flour ensures tenderness", "substitutions": ["all-purpose flour"], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "dutch-process cocoa powder", "quantity": 25, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c06a8e5a-163a-4f21-ad00-a6d90e34c38c", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Raspberry Compote & Drizzle", "items": [{"name": "fresh raspberries", "quantity": 300, "unit": "g", "preparation": null, "notes": null, "substitutions": ["frozen raspberries"], "ingredient_id": "f4f5b84c-c364-40cd-b737-375755e481f9", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 40, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Garnish", "items": [{"name": "icing sugar", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh raspberries", "quantity": 8, "unit": null, "preparation": null, "notes": "whole, for topping", "substitutions": [], "ingredient_id": "f4f5b84c-c364-40cd-b737-375755e481f9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 170\u00b0C/340\u00b0F. Line the bottom of a 20cm round cake tin with parchment paper. Do not grease the sides of the tin; the batter needs to grip the sides to rise properly.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Sift the cake flour and cocoa powder together three times. This aerates the dry ingredients to prevent clumps from deflating the egg foam later.", "structured": {"action": "SIFT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Combine eggs, caster sugar, and vanilla in a large heatproof bowl set over a pan of simmering water (bain-marie). Whisk constantly until the sugar dissolves and the mixture is warm to the touch (about 40\u00b0C/105\u00b0F).", "structured": {"action": "WHISK", "temperature": {"celsius": 40, "fahrenheit": 104}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Remove from heat and whisk on high speed using an electric mixer until the mixture has tripled in volume, is pale, and reaches the ''ribbon stage'' (where a trail of batter stays on the surface for a few seconds before sinking). This takes about 5-7 minutes.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT6M", "doneness_cues": {"visual": "Pale, tripled volume, ribbon stage", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Gently fold the sifted flour and cocoa into the egg foam in three batches. Use a metal spoon or spatula to cut down the center and fold over the top. Be extremely gentle to retain the air bubbles.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Do not overmix or the cake will be rubbery and flat."]}, {"step_number": 6, "phase": "cook", "text": "Pour the batter into the prepared tin and bake immediately for 20-25 minutes. The cake is done when the top springs back when lightly pressed and the sides pull away slightly from the tin.", "structured": {"action": "BAKE", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": "PT25M", "doneness_cues": {"visual": "Sides pulling away from tin", "tactile": "Springs back when touched"}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "While the cake bakes, combine raspberries, granulated sugar, lemon juice, and water in a small saucepan. Simmer over medium heat until the fruit breaks down and the sauce thickens slightly, about 10 minutes. Strain half for a smooth drizzle, keep the other half chunky for filling. Let cool completely.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Once the cake is cool, remove from the tin. Slice horizontally into two layers. Spread the chunky raspberry compote in the middle. Top with the second sponge layer.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Dust the top with icing sugar and drizzle with the smooth raspberry coulis. Garnish with fresh raspberries before serving.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT1H", "total_time": "PT1H35M", "overnight_required": false, "yields": "8 slices", "yield_count": 8, "serving_size_g": 85}', '{"flags": ["Vegetarian", "Dairy-Free", "Nut-Free", "Soy-Free", "Low-Sodium"], "not_suitable_for": []}', '{"per_serving": {"calories": 172.57, "protein_g": 5.28, "carbohydrates_g": 32.73, "fat_g": 3.17, "saturated_fat_g": 1.06, "trans_fat_g": 0.01, "monounsaturated_fat_g": 1.09, "polyunsaturated_fat_g": 0.69, "fiber_g": 4.06, "sugar_g": 20.15, "sodium_mg": 37.07, "cholesterol_mg": 93, "potassium_mg": 156.44, "calcium_mg": 29.99, "iron_mg": 1.28, "magnesium_mg": 29.87, "phosphorus_mg": 95.12, "zinc_mg": 0.78, "vitamin_a_mcg": 40.81, "vitamin_c_mg": 11.1, "vitamin_d_mcg": 0.5, "vitamin_e_mg": 0.63, "vitamin_k_mcg": 3.34, "vitamin_b6_mg": 0.08, "vitamin_b12_mcg": 0.22, "thiamin_mg": 0.04, "riboflavin_mg": 0.15, "niacin_mg": 0.46, "folate_mcg": 24.11, "water_g": 58.45, "alcohol_g": 0.22, "caffeine_mg": 7.19}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container to prevent drying out.", "duration": "P2D"}, "freezer": {"notes": "Freeze sponge layers without filling only.", "duration": "P1M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Stand mixer or electric hand whisk", "required": true, "alternative": null}, {"name": "20cm (8 inch) round cake tin", "required": true, "alternative": null}, {"name": "Large metal spoon or spatula", "required": true, "alternative": "Silicone spatula"}, {"name": "Sieve", "required": true, "alternative": null}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}]', '[{"symptom": "The cake collapsed or turned out dense and rubbery", "likely_cause": "The air was knocked out of the eggs during the folding stage, or the dry ingredients were not folded in gently enough.", "prevention": "Fold using a ''cut and turn'' motion and stop exactly when no flour streaks remain.", "fix": "Cannot be fixed. Use dense cake pieces for a trifle."}]', '["Warming the eggs and sugar before whisking helps dissolve the sugar and relaxes the egg proteins, allowing them to whip to a greater volume.", "Because there is no fat (butter or oil) in the sponge, this cake is best eaten on the day it is made. It relies on the moisture from the filling to stay palatable.", "If using frozen raspberries for the compote, you may need to simmer for an extra 2-3 minutes to evaporate the excess water content.", "Dutch-process cocoa is essential here; natural cocoa is more acidic and can react with the egg foam structure unpredictably in this specific chemical-leavener-free formula."]', '"This recipe is a variation of the ''Genoise'' sponge, a fundamental building block of French p\u00e2tisserie named after the city of Genoa. While traditional Genoise often contains melted butter, this fatless version (Biscuit de Savoie style) was historically favored for its lightness and ability to soak up syrups and liqueurs without becoming heavy."', 172.57);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('6d0cb817-8210-4d9b-9d9f-eb96d93409e6', 'Stuffed Baby Squid with Fennel and Chard', 'Tender baby squid tubes filled with a savory rustic mixture of chopped tentacles, sweet fennel, earthy chard, and toasted almonds for crunch. The stuffed calamari are braised in a vibrant fresh tomato sauce until meltingly soft, creating a harmony of coastal Italian flavors.', 'main course', 'Italian', 'Intermediate', '["squid", "seafood", "italian", "main course", "tomato sauce", "dinner party"]', '[{"group_name": "Squid", "items": [{"name": "baby squid", "quantity": 800, "unit": "g", "preparation": "whole, cleaned", "notes": "Separate bodies and tentacles; reserve tentacles for stuffing", "substitutions": [], "ingredient_id": "e126ab3d-72fc-463a-a50c-461c65ccdf4d", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Stuffing", "items": [{"name": "fennel bulb", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx 200g, save fronds for garnish", "substitutions": [], "ingredient_id": "a42d03de-0a8a-4a75-8299-5cf01d43b425", "nutrition_source": "USDA FoodData Central"}, {"name": "swiss chard", "quantity": 150, "unit": "g", "preparation": "leaves only, washed", "notes": null, "substitutions": [], "ingredient_id": "cb0f8ccb-3b9d-416c-995f-d0a7924af74c", "nutrition_source": "USDA FoodData Central"}, {"name": "almonds", "quantity": 40, "unit": "g", "preparation": "skinned and roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "5bcbb4d4-6845-4825-bd21-1c13e52b989c", "nutrition_source": "USDA FoodData Central"}, {"name": "dry breadcrumbs", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "92441189-214a-4a8a-9cfc-dd578fe0d179", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": "beaten", "notes": "medium size, approx 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Fresh Tomato Sauce", "items": [{"name": "ripe plum tomatoes", "quantity": 800, "unit": "g", "preparation": "diced", "notes": "Peeling optional but recommended for smoother sauce", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "sliced", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5e1efe68-ff2d-432c-9239-ff83f37c5e07", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "red pepper flakes", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, start with 3g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Finely chop the reserved squid tentacles. Blanch the Swiss chard leaves in boiling water for 1 minute, drain thoroughly, squeeze out excess water, and chop finely.", "structured": {"action": "BLANCH", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Toast the chopped almonds in a small frying pan over medium heat until golden and fragrant, about 3 minutes. Set aside to cool.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown", "tactile": "Fragrant"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat 15ml of olive oil in the skillet over medium heat. Saut\u00e9 the diced fennel and minced garlic for 5 minutes until softened. Add the chopped tentacles and cook for another 2 minutes.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT7M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Transfer the fennel mixture to a mixing bowl. Add the prepared chard, toasted almonds, breadcrumbs, and beaten egg. Mix well to combine. Season with a pinch of salt.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Carefully stuff each squid body with the mixture using a small spoon or piping bag. Fill only to 2/3 capacity as the squid will shrink and the filling will expand. Secure the opening of each squid with a toothpick.", "structured": {"action": "STUFF", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Do not overfill or the squid will burst during cooking."]}, {"step_number": 6, "phase": "cook", "text": "Wipe out the skillet. Heat the remaining 30ml olive oil over medium heat. Add sliced garlic and optional red pepper flakes, sizzling for 30 seconds. Add the diced tomatoes and white wine. Bring to a simmer.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Nestle the stuffed squid into the tomato sauce. Cover the skillet and simmer gently on low heat for 25-30 minutes, turning the squid halfway through, until the squid is tender.", "structured": {"action": "BRAISE", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT30M", "doneness_cues": {"visual": null, "tactile": "Squid pierces easily with a fork"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove the toothpicks before serving. Garnish with reserved fennel fronds and serve warm.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT50M", "passive_time": "PT30M", "total_time": "PT1H20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Pescatarian", "Dairy-Free"], "not_suitable_for": ["Shellfish allergy", "Tree nut allergy", "Gluten intolerance"]}', '{"per_serving": {"calories": 517.94, "protein_g": 39.85, "carbohydrates_g": 31.77, "fat_g": 25.24, "saturated_fat_g": 3.84, "trans_fat_g": 0.01, "monounsaturated_fat_g": 14.97, "polyunsaturated_fat_g": 4.49, "fiber_g": 7.7, "sugar_g": 11.7, "sodium_mg": 605.86, "cholesterol_mg": 512.5, "potassium_mg": 1458.09, "calcium_mg": 191.88, "iron_mg": 4.33, "magnesium_mg": 163.39, "phosphorus_mg": 633.75, "zinc_mg": 4.35, "vitamin_a_mcg": 183.95, "vitamin_c_mg": 55.18, "vitamin_d_mcg": 0.25, "vitamin_e_mg": 8.34, "vitamin_k_mcg": 352.79, "vitamin_b6_mg": 0.28, "vitamin_b12_mcg": 2.76, "thiamin_mg": 0.21, "riboflavin_mg": 1.1, "niacin_mg": 6.08, "folate_mcg": 52.76, "water_g": 249.63, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best stored in an airtight container with the sauce covering the squid to prevent drying.", "duration": "P2D"}, "freezer": {"notes": "Texture of the squid may become slightly tougher upon thawing.", "duration": "P1M"}, "reheating": "Gently reheat in a covered saucepan over low heat with a splash of water until warmed through.", "does_not_keep": false}', '[{"name": "Large skillet with lid", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Toothpicks", "required": true, "alternative": "Kitchen twine"}, {"name": "Small frying pan", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}]', '[{"symptom": "Squid bodies split open during cooking", "likely_cause": "The squid was overfilled", "prevention": "Fill tubes only 2/3 full to allow for meat shrinkage and filling expansion", "fix": "Keep the split squid together on the plate; the flavor remains unaffected"}, {"symptom": "Squid is rubbery and tough", "likely_cause": "Undercooked or cooked at too high a boil", "prevention": "Simmer gently for the full duration; squid needs time to tenderize after the initial tightening", "fix": "Continue simmering gently for another 10-15 minutes adding water if sauce dries out"}]', '["If using larger squid, the cooking time may need to be extended by 10-15 minutes.", "Using fresh breadcrumbs rather than dried fine crumbs provides a lighter texture to the stuffing.", "The fennel fronds make an excellent garnish that reinforces the anise flavor profile.", "Ensure the chard is very dry before mixing to prevent the stuffing from becoming soggy.", "To peel fresh tomatoes easily, score an X on the bottom and blanch in boiling water for 30 seconds."]', '"Stuffed squid (Calamari Ripieni) is a classic dish found throughout coastal Italy, particularly in Sicily and Campania. This variation uses almonds and fennel, ingredients characteristic of Sicilian cuisine which often pairs seafood with nuts and earthy vegetables."', 517.94);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('6f5adc6f-b42f-4b84-b88c-eb73adefe93a', 'Wild Mushroom and Fennel Pappardelle', 'A luxuriously creamy autumnal pasta where earth meets anise. Golden-seared wild mushrooms and caramelized fennel are enrobed in a white wine cream sauce, brightened with lemon zest and clinging to broad ribbons of egg pasta.', 'dinner', 'Italian', 'Intermediate', '["pasta", "fennel", "wild mushrooms", "dinner", "main course", "fall", "vegetarian", "italian"]', '[{"group_name": "Vegetables & Aromatics", "items": [{"name": "mixed wild mushrooms", "quantity": 400, "unit": "g", "preparation": "cleaned and torn/sliced", "notes": "chanterelle, shiitake, oyster, or cremini", "substitutions": [], "ingredient_id": "59d83971-a3c1-4b9c-b949-625005657048", "nutrition_source": "USDA FoodData Central"}, {"name": "fennel bulb", "quantity": 1, "unit": null, "preparation": "thinly sliced", "notes": "approx 300g, reserve fronds for garnish", "substitutions": [], "ingredient_id": "a42d03de-0a8a-4a75-8299-5cf01d43b425", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 50g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 5, "unit": "g", "preparation": "leaves picked", "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pasta & Sauce", "items": [{"name": "dried pappardelle pasta", "quantity": 400, "unit": "g", "preparation": null, "notes": "or tagliatelle", "substitutions": [], "ingredient_id": "9acd8d49-8848-4e5f-90e4-33b9b31f83c9", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 120, "unit": "ml", "preparation": null, "notes": "Pinot Grigio or Sauvignon Blanc", "substitutions": [], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable stock", "quantity": 120, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 240, "unit": "ml", "preparation": null, "notes": "min 35% fat", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "parmigiano reggiano", "quantity": 60, "unit": "g", "preparation": "finely grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "lemon", "quantity": 1, "unit": null, "preparation": "zested and juiced", "notes": null, "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "generous amount", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Bring a large stockpot of heavily salted water to a rolling boil. While heating, ensure mushrooms are cleaned (brushed, not washed) and torn into bite-sized pieces. Slice the fennel bulb thinly, removing the hard core.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In the large skillet, heat half the butter and half the olive oil over medium-high heat. Add the mushrooms in a single layer (work in batches if necessary) and sear without moving them for 2-3 minutes until golden brown, then toss and cook 2 more minutes. Remove mushrooms and set aside.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Deep golden brown edges", "tactile": "Crisp exterior, tender interior"}}, "tips": ["Crowding the pan causes mushrooms to steam rather than sear. Give them space."]}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to medium. Add remaining butter and oil to the same pan. Add sliced fennel and shallots. Saut\u00e9 for 6-8 minutes until the fennel is tender and beginning to caramelize. Add garlic and thyme, cooking for 1 minute until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Fennel is translucent and golden", "tactile": "Soft and yielding"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Deglaze the pan with white wine, scraping up any browned bits (fond) from the bottom. Allow the wine to reduce by half. Add vegetable stock and simmer for 2 minutes.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the pasta to the boiling water. Cook until 1 minute shy of al dente (about 1-2 minutes less than package instructions).", "structured": {"action": "BOIL", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Firm bite in the center"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "While pasta boils, pour heavy cream into the skillet with the fennel. Bring to a gentle simmer. Return the seared mushrooms to the pan. Simmer until slightly thickened.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Transfer the pasta directly from the water to the skillet using tongs (carrying over some pasta water is good). Add the grated parmesan and toss vigorously over low heat to emulsify the sauce. Add pasta water 1 tablespoon at a time if the sauce is too thick.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Glossy sauce coating noodles", "tactile": "Creamy consistency"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from heat. Stir in lemon zest, a squeeze of lemon juice (approx 10ml), and chopped fennel fronds. Season with salt and generous black pepper to taste. Serve immediately.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT10M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 420}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 910.71, "protein_g": 26.21, "carbohydrates_g": 91.62, "fat_g": 45.73, "saturated_fat_g": 23.67, "trans_fat_g": 0.75, "monounsaturated_fat_g": 14.81, "polyunsaturated_fat_g": 2.76, "fiber_g": 9.07, "sugar_g": 9.87, "sodium_mg": 607.52, "cholesterol_mg": 102.19, "potassium_mg": 1344.07, "calcium_mg": 367.07, "iron_mg": 16.2, "magnesium_mg": 157.81, "phosphorus_mg": 763.19, "zinc_mg": 5.69, "vitamin_a_mcg": 401.95, "vitamin_c_mg": 24.99, "vitamin_d_mcg": 6.14, "vitamin_e_mg": 2.41, "vitamin_k_mcg": 55.97, "vitamin_b6_mg": 0.33, "vitamin_b12_mcg": 0.3, "thiamin_mg": 0.12, "riboflavin_mg": 0.41, "niacin_mg": 2.92, "folate_mcg": 40.43, "water_g": 230.19, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Sauce will thicken significantly; reheat with a splash of water.", "duration": "P3D"}, "freezer": {"notes": "Cream sauces do not freeze well; texture may split.", "duration": null}, "reheating": "Gently warm in a pan over low heat with a splash of water or milk to re-emulsify.", "does_not_keep": false}', '[{"name": "Large stockpot", "required": true, "alternative": null}, {"name": "Large heavy-bottomed skillet", "required": true, "alternative": "Dutch oven"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Microplane or fine grater", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "Sauce is split or oily", "likely_cause": "Heat was too high after adding cheese, or sauce reduced too much", "prevention": "Lower heat before adding cheese; keep pasta water handy", "fix": "Add 2-3 tablespoons of hot starchy pasta water and whisk/toss vigorously to re-bind the emulsion"}, {"symptom": "Mushrooms are soggy and gray", "likely_cause": "Pan was overcrowded or heat was too low", "prevention": "Cook mushrooms in batches with high heat", "fix": "Cannot be fixed once cooked; proceed, flavor will still be good but texture compromised"}]', '["Reserve at least 250ml of starchy pasta water before draining; it is the ''liquid gold'' required to achieve the perfect sauce consistency.", "Do not wash wild mushrooms under running water as they act like sponges. Clean them with a brush or damp cloth to ensure a good sear.", "The anise flavor of fennel mellows significantly upon cooking, becoming sweet and savory. Do not fear the quantity.", "For extra depth, rehydrate 10g of dried porcini mushrooms in hot water, chop them, and add the soaking liquid (strained) along with the vegetable stock."]', '"While pasta with mushrooms (Pasta ai Funghi) is a staple across Italy, the addition of fennel is characteristic of Southern Italian and Sicilian influence, where wild fennel grows abundantly. This dish celebrates the ''bosco'' (forest) flavors typical of the autumn harvest season."', 910.71);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('70141bce-f02b-400a-a9ea-0c1f34785b18', 'Nonettes de Dijon (Honey Cakes with Orange Marmalade)', 'Traditional French gingerbread cakes from Dijon featuring a tender, spiced honey crumb and a molten core of bitter orange marmalade, finished with a delicate citrus glaze.', 'baked good', 'French', 'Intermediate', '["cake", "honey cake", "nonettes", "dessert", "bake", "french", "gingerbread"]', '[{"group_name": "Honey Spiced Syrup", "items": [{"name": "honey", "quantity": 275, "unit": "g", "preparation": "liquid", "notes": "dark flower honey or chestnut honey is traditional", "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 100, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 75, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "brown sugar", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dry Mix", "items": [{"name": "all-purpose flour", "quantity": 200, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "rye flour", "quantity": 75, "unit": "g", "preparation": null, "notes": "adds traditional earthy depth; substitute AP flour if unavailable", "substitutions": ["all-purpose flour"], "ingredient_id": "fe914538-d1b3-49f2-9978-a3468f18bce3", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 1, "unit": null, "preparation": null, "notes": "approx. 3g or 1 tsp", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "ground ginger", "quantity": 1, "unit": null, "preparation": null, "notes": "approx. 2g or 1/2 tsp", "substitutions": [], "ingredient_id": "401ddd0b-3597-4b46-bb54-f3bc755048bb", "nutrition_source": "USDA FoodData Central"}, {"name": "ground nutmeg", "quantity": 0.5, "unit": null, "preparation": null, "notes": "approx. 1g or 1/4 tsp", "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}, {"name": "ground anise", "quantity": 0.5, "unit": null, "preparation": null, "notes": "approx. 1g or 1/4 tsp", "substitutions": [], "ingredient_id": "9010f167-112f-4c3b-80c3-b49783e568a1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Filling & Glaze", "items": [{"name": "bitter orange marmalade", "quantity": 150, "unit": "g", "preparation": "thick", "notes": null, "substitutions": [], "ingredient_id": "086edec1-968e-4cf0-94b0-64261e4408cf", "nutrition_source": "Aggregated Public Data"}, {"name": "powdered sugar", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a small saucepan, combine the honey, water, butter, and brown sugar. Heat gently over medium heat just until the butter is melted and sugar is dissolved. Do not boil. Remove from heat and let cool until lukewarm.", "structured": {"action": "HEAT", "temperature": {"celsius": 50, "fahrenheit": 122}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Sift the all-purpose flour, rye flour, baking powder, cinnamon, ginger, nutmeg, and anise into a large mixing bowl to remove lumps and aerate.", "structured": {"action": "SIFT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Pour the lukewarm honey mixture into the dry ingredients. Whisk constantly until a smooth, thick batter forms. Do not overmix once combined.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": {"visual": "Smooth, glossy, caramel-colored batter", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Cover the bowl and let the batter rest in the refrigerator for at least 30 minutes (up to 24 hours). This allows the rye flour to hydrate and the spices to infuse.", "structured": {"action": "REST", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Preheat your oven to 200\u00b0C/390\u00b0F. Grease the muffin tin liberally with butter or use cupcake liners.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Fill each muffin cup about one-third full with batter. Place a generous teaspoon (approx 10-12g) of orange marmalade in the center. Cover with remaining batter until cups are two-thirds full.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Bake for 15-20 minutes. The cakes should be dark golden brown and spring back when lightly touched. A skewer inserted into the cake part (avoiding the jam center) should come out clean.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "While cakes are baking, whisk powdered sugar and lemon juice to create a thin glaze. As soon as the cakes come out of the oven, brush the glaze over the hot cakes.", "structured": {"action": "GLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Allow cakes to cool in the tin for 10 minutes before transferring to a wire rack. They are best eaten after cooling completely or waiting 24 hours.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT1H", "total_time": "PT1H30M", "overnight_required": false, "yields": "12 cakes", "yield_count": 12, "serving_size_g": 70}', '{"flags": ["Vegetarian", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Infants under 12 months (honey)"]}', '{"per_serving": {"calories": 262.86, "protein_g": 2.59, "carbohydrates_g": 53.88, "fat_g": 5.37, "saturated_fat_g": 3.22, "trans_fat_g": null, "monounsaturated_fat_g": 1.5, "polyunsaturated_fat_g": 0.3, "fiber_g": 1.38, "sugar_g": 35.46, "sodium_mg": 114.34, "cholesterol_mg": 13.44, "potassium_mg": 72.14, "calcium_mg": 77.31, "iron_mg": 0.63, "magnesium_mg": 8.43, "phosphorus_mg": 48.04, "zinc_mg": 0.28, "vitamin_a_mcg": 42.88, "vitamin_c_mg": 2.5, "vitamin_d_mcg": null, "vitamin_e_mg": 0.21, "vitamin_k_mcg": 0.94, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": 0.01, "thiamin_mg": 0.04, "riboflavin_mg": 0.02, "niacin_mg": 0.32, "folate_mcg": 6.82, "water_g": 17.28, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. The texture improves and becomes softer after 24-48 hours.", "duration": "P2W"}, "freezer": {"notes": "Freeze without the glaze for best results.", "duration": "P3M"}, "reheating": "Eat at room temperature or warm slightly in a microwave for 10 seconds.", "does_not_keep": false}', '[{"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Muffin tin (12 holes)", "required": true, "alternative": "Nonette rings or silicone molds"}, {"name": "Sieve", "required": true, "alternative": null}, {"name": "Pastry brush", "required": true, "alternative": null}]', '[{"symptom": "Marmalade sank to the bottom and leaked", "likely_cause": "Batter was too warm or fluid when filling, or the marmalade was too heavy/liquid.", "prevention": "Ensure batter is chilled and rested before filling. Use a thick, high-pectin marmalade.", "fix": "Serve upside down or trim the sticky bottom; they will still taste delicious."}, {"symptom": "Cakes are tough or rubbery", "likely_cause": "Overmixing the batter developed too much gluten.", "prevention": "Stop whisking as soon as the flour streaks disappear.", "fix": "Warm slightly before serving to soften texture."}]', '["The secret to authentic Nonettes is patience; the flavor and texture improve significantly after storing them in an airtight container for 2-3 days.", "Use a high-quality bitter orange marmalade for the best contrast against the sweet honey crumb.", "If you don''t have rye flour, you can use 100% all-purpose flour, but the cake will be slightly lighter and less earthy.", "The glaze is traditional but optional; it seals moisture into the hot cake and adds a nice sheen."]', '"Nonettes are a beloved specialty of Dijon, France, historically made by nuns (hence ''nonettes''). Originally created to use up leftover gingerbread dough, they evolved into a distinct delicacy filled with marmalade and are a staple of Burgundy culinary heritage."', 262.86);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('703fe65a-f159-400d-8df3-760611d06c04', 'Blueberry Teff & Oat Power Pancakes', 'Hearty, nutrient-packed pancakes featuring the nutty, malty flavor of ancient teff grain paired with the texture of rolled oats. These are fluffier than typical whole-grain pancakes thanks to the buttermilk reaction, bursting with jammy blueberries in every bite.', 'breakfast', 'American', 'Easy', '["pancakes", "buttermilk", "flour", "freezer friendly", "great leftovers", "kid-friendly", "make-ahead", "breakfast", "easy", "healthy", "vegetarian"]', '[{"group_name": "Dry Ingredients", "items": [{"name": "teff flour", "quantity": 100, "unit": "g", "preparation": "brown or ivory", "notes": "approx 3/4 cup", "substitutions": [], "ingredient_id": "af2661d8-b555-4fef-bdee-51a5190eda92", "nutrition_source": "USDA FoodData Central"}, {"name": "whole wheat flour", "quantity": 60, "unit": "g", "preparation": null, "notes": "approx 1/2 cup", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "old-fashioned rolled oats", "quantity": 50, "unit": "g", "preparation": null, "notes": "do not use steel cut", "substitutions": [], "ingredient_id": "4490fcb6-a551-427f-885d-b3589c1c21c2", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 8, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5c0b5fc8-b210-4e39-b3a6-479541ac45d2", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wet Ingredients", "items": [{"name": "buttermilk", "quantity": 360, "unit": "ml", "preparation": "shaken", "notes": null, "substitutions": [], "ingredient_id": "de1c3d44-e3e7-47d2-a315-83a46edfb165", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "large", "notes": "approx 100g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": "melted and cooled", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "maple syrup", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c9ca1f35-b107-46c2-92a3-4c1c620f3c11", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Mix-ins & Cooking", "items": [{"name": "fresh blueberries", "quantity": 150, "unit": "g", "preparation": "washed and dried", "notes": null, "substitutions": ["frozen blueberries (do not thaw)"], "ingredient_id": "0f9f22a4-4f00-4950-9145-943d55b6dec8", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 10, "unit": "g", "preparation": null, "notes": "for greasing pan", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a large mixing bowl, whisk together the teff flour, whole wheat flour, rolled oats, baking powder, baking soda, salt, and cinnamon until well combined.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a medium bowl, whisk the buttermilk, eggs, melted butter, maple syrup, and vanilla extract until smooth.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Pour the wet ingredients into the dry ingredients. Mix gently with a spatula just until no dry flour streaks remain. Do not overmix; the batter should be slightly lumpy. Let the batter rest for 10 minutes to allow the teff and oats to hydrate.", "structured": {"action": "MIX", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": ["Resting is crucial for teff flour to soften and absorb liquid, preventing a gritty texture."]}, {"step_number": 4, "phase": "cook", "text": "Preheat a skillet or griddle over medium heat (approx 190\u00b0C/375\u00b0F). Brush the surface lightly with butter.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Ladle 60ml (1/4 cup) portions of batter onto the hot skillet. Immediately press a small handful of blueberries onto the top of each pancake.", "structured": {"action": "POUR", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Placing berries on top rather than mixing them in prevents the batter from turning grey."]}, {"step_number": 6, "phase": "cook", "text": "Cook for 2-3 minutes until bubbles form on the surface and the edges look set and dry. Flip carefully.", "structured": {"action": "FRY", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Bubbles on surface, set edges", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Cook on the second side for another 1-2 minutes until golden brown and the center springs back when lightly pressed.", "structured": {"action": "FRY", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": null, "tactile": "Springs back when pressed"}}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT10M", "total_time": "PT30M", "overnight_required": false, "yields": "12 pancakes", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 404.96, "protein_g": 12.61, "carbohydrates_g": 54.85, "fat_g": 16.13, "saturated_fat_g": 8.62, "trans_fat_g": 0.01, "monounsaturated_fat_g": 4.74, "polyunsaturated_fat_g": 1.65, "fiber_g": 6.22, "sugar_g": 13.62, "sodium_mg": 602.53, "cholesterol_mg": 126.16, "potassium_mg": 593.69, "calcium_mg": 241.29, "iron_mg": 2.5, "magnesium_mg": 72.71, "phosphorus_mg": 437.52, "zinc_mg": 2.19, "vitamin_a_mcg": 147.85, "vitamin_c_mg": 4.56, "vitamin_d_mcg": 0.5, "vitamin_e_mg": 1, "vitamin_k_mcg": 9.04, "vitamin_b6_mg": 0.16, "vitamin_b12_mcg": 0.45, "thiamin_mg": 0.25, "riboflavin_mg": 0.44, "niacin_mg": 1.9, "folate_mcg": 36.84, "water_g": 143.11, "alcohol_g": 0.43, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container.", "duration": "P3D"}, "freezer": {"notes": "Freeze in a single layer before stacking with parchment paper in between.", "duration": "P2M"}, "reheating": "Toaster or oven at 175\u00b0C (350\u00b0F) until warmed through.", "does_not_keep": false}', '[{"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Medium mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Non-stick skillet or Griddle", "required": true, "alternative": "Cast iron skillet"}, {"name": "Spatula", "required": true, "alternative": null}]', '[{"symptom": "Pancakes are dark on the outside but raw/gummy inside", "likely_cause": "Heat is too high, causing the sugar and teff to burn before the interior cooks", "prevention": "Lower the heat to medium-low after the skillet is preheated", "fix": "Finish cooking the remaining pancakes in a 175\u00b0C/350\u00b0F oven for 3-5 minutes"}]', '["Teff flour is technically gluten-free, but because it is a heavy grain, we use a portion of wheat flour in this recipe to ensure the pancakes hold together well. If strict gluten-free is required, replace the wheat flour with a 1:1 GF baking blend.", "If using frozen blueberries, do not thaw them beforehand, or they will bleed excessive juice into the batter.", "The resting step (Step 3) is non-negotiable when working with whole grains like teff and oats; skipping it will result in flat, gritty pancakes.", "Leftovers can be popped directly into a toaster from the freezer for a quick weekday breakfast."]', '"Teff is an ancient grain originating from Ethiopia and Eritrea, traditionally fermented to make Injera. In this modern American breakfast application, its mild, malty flavor pairs exceptionally well with the rustic texture of oats, providing a high-iron, high-fiber alternative to standard refined flour pancakes."', 404.96);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('7057e0e3-b0f5-48f3-bdd5-34f5bc77b101', 'Golden Gazpacho with Cucumber Granita & Crispy Serrano', 'A sophisticated interplay of temperature and texture. Sweet, sun-ripened yellow tomatoes form a velvety, chilled emulsion, contrasted by the icy, herbaceous bite of cucumber granita. Finished with the saline crunch of oven-dried Serrano ham.', 'soup', 'Spanish', 'Intermediate', '["spanish", "cucumber", "gazpacho", "granita", "serrano", "yellow tomato", "lunch", "appetizer", "summer"]', '[{"group_name": "Cucumber Granita", "items": [{"name": "english cucumbers", "quantity": 500, "unit": "g", "preparation": "chopped, skin on", "notes": null, "substitutions": [], "ingredient_id": "84cc106c-269c-44b7-af59-33b3c121e483", "nutrition_source": "USDA FoodData Central"}, {"name": "lime juice", "quantity": 30, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "sugar syrup", "quantity": 45, "unit": "ml", "preparation": null, "notes": "1:1 ratio water to sugar", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Yellow Tomato Gazpacho", "items": [{"name": "yellow heirloom tomatoes", "quantity": 1000, "unit": "g", "preparation": "cored and roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "0ba01b79-628f-4d68-be62-dab1fbbd087c", "nutrition_source": "Aggregated Public Data"}, {"name": "yellow bell pepper", "quantity": 150, "unit": "g", "preparation": "seeded and chopped", "notes": null, "substitutions": [], "ingredient_id": "b8ed9fc6-8806-4baf-a073-89a5b79f63f0", "nutrition_source": "USDA FoodData Central"}, {"name": "cucumber", "quantity": 100, "unit": "g", "preparation": "peeled and seeded", "notes": null, "substitutions": [], "ingredient_id": "84cc106c-269c-44b7-af59-33b3c121e483", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 30, "unit": "g", "preparation": "peeled", "notes": null, "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "germ removed", "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "sherry vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": "Reserva quality preferred", "substitutions": [], "ingredient_id": "dcfa7371-7051-4604-a76e-4a46ae1f9e7b", "nutrition_source": "Aggregated Public Data"}, {"name": "extra virgin olive oil", "quantity": 80, "unit": "ml", "preparation": null, "notes": "plus extra for garnish", "substitutions": [], "ingredient_id": "036c7254-3de5-4c6e-a2e7-366ad4d05077", "nutrition_source": "Aggregated Public Data"}, {"name": "stale white bread", "quantity": 40, "unit": "g", "preparation": "crusts removed", "notes": "soaked in water then squeezed dry", "substitutions": [], "ingredient_id": "4984ed41-b79d-4372-8336-32815e469548", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 8, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Crispy Garnishes", "items": [{"name": "serrano ham", "quantity": 4, "unit": null, "preparation": "thin slices", "notes": "approx 60g total", "substitutions": [], "ingredient_id": "565caea8-c9b2-4494-9e3d-3fbd9bc3b686", "nutrition_source": "USDA FoodData Central"}, {"name": "white bread", "quantity": 50, "unit": "g", "preparation": "diced into 5mm cubes", "notes": null, "substitutions": [], "ingredient_id": "9558fc03-7eaf-4128-b1dd-0088074d48c2", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "for frying croutons", "substitutions": [], "ingredient_id": "036c7254-3de5-4c6e-a2e7-366ad4d05077", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "For the granita: Blend the chopped English cucumbers with lime juice, sugar syrup, and salt until completely liquid.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Strain the cucumber liquid through a fine mesh sieve into a shallow freezer-safe container. Press on the solids to extract all flavor, then discard solids.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Place the container in the freezer. Every 30 minutes, scrape the mixture with a fork to create fluffy ice crystals. Repeat for 3-4 hours until fully frozen and flaky.", "structured": {"action": "FREEZE", "temperature": {"celsius": -18, "fahrenheit": 0}, "duration": "PT4H", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "While granita freezes, combine tomatoes, yellow pepper, peeled cucumber, shallot, garlic, bread (if using), and vinegar in a blender. Blend on high until smooth.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "With the blender running on low, slowly stream in the 80ml olive oil to emulsify. The soup should turn glossy and opaque.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Pass the soup through a clean fine mesh sieve, pushing firmly to extract liquid. Discard skins and seeds. Season with salt. Chill for at least 2 hours.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT2H", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Preheat oven to 180\u00b0C (350\u00b0F). Lay Serrano ham slices flat on a parchment-lined baking sheet. Bake until fat renders and meat darkens slightly, about 10-12 minutes. Cool to crisp.", "structured": {"action": "BAKE", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT12M", "doneness_cues": {"visual": "Deep red color, rendered fat", "tactile": "Stiff and brittle when cooled"}}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Toss bread cubes with 15ml olive oil. Toast in a pan over medium heat until golden brown and crunchy.", "structured": {"action": "TOAST", "temperature": null, "duration": null, "doneness_cues": {"visual": "Golden brown", "tactile": "Crispy"}}, "tips": []}, {"step_number": 9, "phase": "assemble", "text": "Pour chilled soup into bowls. Spoon a mound of cucumber granita into the center. Top with a shard of crispy Serrano ham and a scattering of croutons. Serve immediately.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT4H", "total_time": "PT4H45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 320}', '{"flags": ["Dairy-Free", "Nut-Free", "Egg-Free", "Soy-Free"], "not_suitable_for": ["Vegetarians (contains ham)", "Vegans (contains ham)"]}', '{"per_serving": {"calories": 428.7, "protein_g": 10.62, "carbohydrates_g": 41.73, "fat_g": 26.78, "saturated_fat_g": 3.49, "trans_fat_g": 0.01, "monounsaturated_fat_g": 0.07, "polyunsaturated_fat_g": 0.16, "fiber_g": 6.08, "sugar_g": 21.62, "sodium_mg": 1341.9, "cholesterol_mg": null, "potassium_mg": 338.64, "calcium_mg": 117.43, "iron_mg": 2.02, "magnesium_mg": 28.26, "phosphorus_mg": 60.84, "zinc_mg": 0.49, "vitamin_a_mcg": 9.9, "vitamin_c_mg": 77.04, "vitamin_d_mcg": null, "vitamin_e_mg": 0.11, "vitamin_k_mcg": 11.89, "vitamin_b6_mg": 0.19, "vitamin_b12_mcg": null, "thiamin_mg": 0.13, "riboflavin_mg": 0.1, "niacin_mg": 0.99, "folate_mcg": 49.96, "water_g": 198.04, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store soup and garnishes separately. Granita must be frozen.", "duration": "P2D"}, "freezer": {"notes": "Granita only. Soup does not freeze well due to emulsion.", "duration": "P1W"}, "reheating": null, "does_not_keep": false}', '[{"name": "High-speed blender", "required": true, "alternative": null}, {"name": "Fine mesh sieve", "required": true, "alternative": null}, {"name": "Shallow freezer-safe container", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Fork", "required": true, "alternative": "Whisk"}]', '[{"symptom": "Granita is a solid block of ice", "likely_cause": "Forgot to scrape periodically or freezer is too cold", "prevention": "Set a timer for every 30 minutes during freezing", "fix": "Leave at room temperature for 10 minutes, then scrape vigorously with a heavy fork or pulse quickly in a blender"}, {"symptom": "Soup texture is watery or separated", "likely_cause": "Insufficient olive oil emulsion or tomatoes were too watery", "prevention": "Stream oil very slowly while blending; use bread as a binder", "fix": "Blend in a small amount of xanthan gum (0.5g) or another slice of soaked bread"}]', '["Use the highest quality sherry vinegar you can find; the acidity cuts the sweetness of the yellow tomatoes.", "Chill your serving bowls beforehand. This dish relies entirely on remaining cold until the moment it is eaten.", "If you cannot find yellow tomatoes, red works, but the flavor profile will be more acidic and less floral.", "The sugar syrup in the granita is not just for sweetness; it interferes with ice crystal formation to prevent it from freezing into a rock."]', '"Originating in the southern Spanish region of Andalusia, Gazpacho was traditionally a peasant food made of stale bread, garlic, olive oil, and vinegar. Tomatoes were added later after arriving from the Americas. This variation uses yellow tomatoes for a modern, sweeter profile and borrows the Italian ''granita'' technique for a refreshing temperature contrast."', 428.7);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('707cc79b-6404-456b-a119-6098e6081f66', 'Rustic Summer Fruit Mostarda with Ginger', 'A jewel-toned Northern Italian condiment that balances the concentrated sweetness of dried summer fruits with the sharp, nasal heat of mustard and warming candied ginger. Ideally paired with sharp cheeses or roasted meats.', 'condiment', 'Italian', 'Intermediate', '["italian", "dips and spreads", "candied ginger", "dried fruit", "white wine", "summer", "preserve", "cheese accompaniment"]', '[{"group_name": "Fruit Base", "items": [{"name": "dried apricots", "quantity": 100, "unit": "g", "preparation": "sliced into strips", "notes": null, "substitutions": [], "ingredient_id": "804037f0-34fa-4bdd-b031-e9523a502430", "nutrition_source": "USDA FoodData Central"}, {"name": "dried figs", "quantity": 100, "unit": "g", "preparation": "stemmed and quartered", "notes": null, "substitutions": [], "ingredient_id": "39bd219f-1334-4209-ab42-616a0c4ada10", "nutrition_source": "USDA FoodData Central"}, {"name": "golden raisins", "quantity": 50, "unit": "g", "preparation": "whole", "notes": null, "substitutions": [], "ingredient_id": "786501db-965f-429e-94a0-ce2cdc06c667", "nutrition_source": "USDA FoodData Central"}, {"name": "candied ginger", "quantity": 60, "unit": "g", "preparation": "finely diced", "notes": null, "substitutions": [], "ingredient_id": "c152276a-6b59-4995-8015-d4b54c38f05a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Syrup", "items": [{"name": "dry white wine", "quantity": 250, "unit": "ml", "preparation": null, "notes": "Pinot Grigio or Sauvignon Blanc", "substitutions": [], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "granulated sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 100, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Mustard Slurry", "items": [{"name": "dry mustard powder", "quantity": 25, "unit": "g", "preparation": null, "notes": "Colman''s or similar hot variety", "substitutions": [], "ingredient_id": "db158165-0dc2-4368-ad1d-35f8de6f76de", "nutrition_source": "Aggregated Public Data"}, {"name": "white wine vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b2f8f0c0-6da9-47aa-932a-c2747b64b807", "nutrition_source": "Aggregated Public Data"}, {"name": "yellow mustard seeds", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "6bc4809f-da0c-4b24-a7e4-09873d83ecc3", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the fruit by slicing the apricots into strips, quartering the figs, and dicing the candied ginger. Ensure all pieces are relatively uniform in size.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a heavy-bottomed saucepan, combine the white wine, water, and sugar. Bring to a boil over medium-high heat, stirring until the sugar dissolves completely.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the prepared dried fruits, raisins, candied ginger, and whole mustard seeds to the syrup. Reduce heat to low and simmer gently for 20-30 minutes until the fruit is plump and the syrup has thickened to a honey-like consistency (approx 105\u00b0C/221\u00b0F).", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT30M", "doneness_cues": {"visual": "Syrup coats the back of a spoon; fruit is translucent", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "While the fruit simmers, create the mustard slurry. In a small bowl, whisk the dry mustard powder with the white wine vinegar until smooth. Let this sit for 10 minutes to allow the enzymatic reaction to develop heat.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove the saucepan from the heat. Allow it to cool for 5 minutes (to approx 80\u00b0C/176\u00b0F). Stir in the mustard slurry thoroughly. Do not boil after adding the mustard, or it will lose its pungency.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Transfer the mostarda into sterilized jars. Let cool completely at room temperature before sealing and refrigerating.", "structured": {"action": "COOL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT1H", "total_time": "PT1H30M", "overnight_required": false, "yields": "500ml (2 small jars)", "yield_count": 16, "serving_size_g": 30}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 115.07, "protein_g": 1.12, "carbohydrates_g": 21.97, "fat_g": 0.55, "saturated_fat_g": 0.03, "trans_fat_g": null, "monounsaturated_fat_g": 0.01, "polyunsaturated_fat_g": 0.02, "fiber_g": 1.04, "sugar_g": 19.38, "sodium_mg": 5.05, "cholesterol_mg": null, "potassium_mg": 132.94, "calcium_mg": 10.03, "iron_mg": 0.43, "magnesium_mg": 10.91, "phosphorus_mg": 25.03, "zinc_mg": 0.16, "vitamin_a_mcg": 11.84, "vitamin_c_mg": 0.44, "vitamin_d_mcg": null, "vitamin_e_mg": 0.28, "vitamin_k_mcg": 0.72, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": null, "thiamin_mg": null, "riboflavin_mg": 0.02, "niacin_mg": 0.24, "folate_mcg": 0.78, "water_g": 13.01, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves after resting for 24 hours.", "duration": "P1M"}, "freezer": {"notes": "Not recommended as texture becomes grainy.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Heavy-bottomed saucepan", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Sterilized jars", "required": true, "alternative": null}]', '[{"symptom": "Mustard flavor is weak or non-existent", "likely_cause": "The mustard was added while the syrup was boiling, destroying the volatile heat compounds", "prevention": "Always remove the pot from heat and wait 5 minutes before stirring in the mustard slurry", "fix": "Stir in a teaspoon of fresh mustard powder mixed with a little water after the mixture has fully cooled"}, {"symptom": "Syrup crystallized after cooling", "likely_cause": "Sugar was not fully dissolved before boiling or the mixture was agitated too much during cooking", "prevention": "Ensure sugar is fully dissolved before adding fruit; wash down sides of pot with water brush", "fix": "Gently reheat the mixture with a splash of wine to dissolve crystals, then cool again"}]', '["Mostarda flavor peaks after 2-3 days in the fridge as the mustard heat permeates the fruit.", "If you can find ''Mustard Essential Oil'' (typical in Italy), use 2-3 drops instead of the powder for a clearer syrup and intense kick, but handle with extreme care as it is a potent irritant.", "Serve this alongside a cheese board featuring Pecorino, Gorgonzola, or Taleggio to cut through the richness.", "For a glossier finish, you can add a teaspoon of glucose syrup or corn syrup to the boiling liquid."]', '"Originating in Northern Italy, particularly Cremona and Mantua, ''Mostarda'' is a traditional condiment born from the need to preserve harvest fruits for winter. Unlike the standard yellow condiment, Italian Mostarda suspends candied fruit in a spicy mustard-infused syrup, creating a sophisticated interplay of sugar and spice often served with Bollito Misto (boiled meats)."', 115.07);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('70a5e091-f7c1-4bd7-936d-3de132c9a059', 'Saffron-Glazed Shrimp with Velvet Aioli', 'Succulent shrimp seared in garlic butter and finished with a fragrant saffron reduction, served alongside a rich, golden citrus mayonnaise. The dual application of saffron creates a luxurious floral aroma balanced by the sweetness of the seafood.', 'dinner', 'Mediterranean', 'Easy', '["seafood", "saffron", "shrimp", "easy", "quick", "tapas", "gluten-free"]', '[{"group_name": "Saffron Bloom", "items": [{"name": "saffron threads", "quantity": 0.2, "unit": "g", "preparation": "dry", "notes": "a very generous pinch", "substitutions": [], "ingredient_id": "7f9ec0c8-2db1-48ac-a2c9-9b1efce12cf3", "nutrition_source": "USDA FoodData Central"}, {"name": "hot water", "quantity": 30, "unit": "ml", "preparation": "not boiling", "notes": "approx 60-70\u00b0C", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Velvet Aioli", "items": [{"name": "high-quality mayonnaise", "quantity": 120, "unit": "g", "preparation": "chilled", "notes": null, "substitutions": [], "ingredient_id": "97b74a34-8c1f-4c58-b70e-42c1de6d12aa", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "grated into paste", "notes": "approx 3g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Shrimp", "items": [{"name": "large shrimp", "quantity": 500, "unit": "g", "preparation": "peeled and deveined, tail-on optional", "notes": "raw weight", "substitutions": ["prawns", "scallops"], "ingredient_id": "a6bf7ab3-9b88-4c5b-a2fa-966c40a0e5a7", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "thinly sliced", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 5, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Crush the saffron threads into a fine powder using a mortar and pestle. Add the hot water and let it steep for 5-10 minutes to release the vibrant yellow color and floral aroma. This is the ''bloom''.", "structured": {"action": "CRUSH", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a small mixing bowl, whisk together the mayonnaise, grated garlic, lemon juice, and exactly half (15ml) of the saffron bloom liquid. Season with a pinch of salt if needed. Refrigerate until serving.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Thoroughly pat the shrimp dry with paper towels. This step is crucial for achieving a sear rather than steaming them. Season evenly with the salt and smoked paprika.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Heat the olive oil in a large skillet over medium-high heat (approx 190\u00b0C/375\u00b0F). Add the shrimp in a single layer. Cook without moving them for 1-2 minutes until pink and golden on the bottom.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT2M", "doneness_cues": {"visual": "Golden brown edges on the bottom side", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Flip the shrimp. Immediately lower the heat to medium and add the butter and sliced garlic. Saut\u00e9 for 1 minute until the garlic is fragrant but not brown.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Pour the remaining half of the saffron bloom liquid into the pan. Toss the shrimp vigorously to coat in the emulsifying butter-saffron sauce. Cook for 30 seconds or until shrimp internal temperature reaches 63\u00b0C/145\u00b0F.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT30S", "doneness_cues": {"visual": "Shrimp are opaque throughout", "tactile": "Firm to the touch"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from heat immediately. Garnish with chopped parsley and serve hot alongside the chilled saffron aioli.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT5M", "total_time": "PT25M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 185}', '{"flags": ["Pescatarian", "Gluten-Free", "Low-Carb", "Keto"], "not_suitable_for": ["Shellfish allergy", "Egg allergy (mayonnaise)"]}', '{"per_serving": {"calories": 402.82, "protein_g": 25.74, "carbohydrates_g": 1.39, "fat_g": 33, "saturated_fat_g": 7.96, "trans_fat_g": 0.06, "monounsaturated_fat_g": 9.65, "polyunsaturated_fat_g": 14.27, "fiber_g": 0.27, "sugar_g": 0.29, "sodium_mg": 632.85, "cholesterol_mg": 229.98, "potassium_mg": 367.43, "calcium_mg": 91.64, "iron_mg": 0.96, "magnesium_mg": 46.57, "phosphorus_mg": 281.56, "zinc_mg": 1.79, "vitamin_a_mcg": 73.68, "vitamin_c_mg": 2.9, "vitamin_d_mcg": 0.06, "vitamin_e_mg": 1.86, "vitamin_k_mcg": 72.62, "vitamin_b6_mg": 0.04, "vitamin_b12_mcg": 0.05, "thiamin_mg": 0.01, "riboflavin_mg": 0.02, "niacin_mg": 0.09, "folate_mcg": 4.24, "water_g": 116.83, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store shrimp and aioli in separate airtight containers.", "duration": "P2D"}, "freezer": {"notes": "Not recommended; texture of shrimp degrades and mayonnaise emulsion will break.", "duration": null}, "reheating": "Gently warm shrimp in a skillet over low heat just until warmed through. Do not microwave. Serve aioli cold.", "does_not_keep": false}', '[{"name": "Large skillet or frying pan", "required": true, "alternative": "Wok"}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Mortar and pestle", "required": true, "alternative": "Small bowl and back of a spoon"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Shrimp is rubbery and tough", "likely_cause": "Overcooking", "prevention": "Remove shrimp from the pan the second they turn opaque and form a C-shape. Total cook time is usually under 4 minutes.", "fix": "Cannot be fixed. Chop into small pieces and mix into the aioli for a shrimp salad spread."}, {"symptom": "Saffron flavor is metallic or medicinal", "likely_cause": "Too much saffron used or low quality saffron", "prevention": "Measure carefully; saffron is potent. Use high-grade threads (like Sargol or Coupe) rather than powder.", "fix": "Add more mayonnaise and lemon juice to the aioli to dilute the flavor."}, {"symptom": "Shrimp are steaming instead of searing", "likely_cause": "Pan overcrowded or shrimp were wet", "prevention": "Pat shrimp very dry and cook in batches if your pan is small.", "fix": "Remove accumulated liquid, increase heat to boil it off, then add butter."}]', '["Saffron releases its flavor best in heat and liquid. Never skip the blooming step (steeping in hot water), or the flavor will be weak and uneven.", "For the aioli base, use a neutral mayonnaise or make your own. Avoid olive oil-heavy mayonnaise bases as they can clash with the saffron''s subtle earthiness.", "Garlic is used two ways here: grated raw into the mayo for a sharp bite, and sliced in the pan for a sweet, mellow finish. Do not mince the pan garlic, or it will burn before the shrimp are done.", "Serve this dish with crusty baguette slices to mop up the saffron-butter pan sauce."]', '"This dish draws heavily from the Spanish ''tapas'' tradition, specifically ''Gambas al Ajillo'' (Garlic Shrimp), but incorporates a French influence with the creamy emulsion. Saffron, the ''red gold,'' was introduced to Spain by the Moors in the 10th century and remains a cornerstone of Mediterranean spice profiles."', 402.82);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('70cebc03-dce3-41ed-92b7-f096aebc35af', 'Indian Turkey Feast: Creamy Curry, Bombay Potatoes & Crispy Pakoras', 'A lavish family spread featuring tender turkey thigh simmered in a aromatic tomato-coconut sauce, accompanied by golden turmeric-spiced potatoes and crunchy onion fritters (bhajis). Ideally suited for raw turkey or repurposing roast leftovers.', 'dinner', 'Indian', 'Advanced', '["turkey", "curry", "indian", "bombay potatoes", "pakora", "leftovers", "family meal"]', '[{"group_name": "Turkey Curry Base", "items": [{"name": "turkey thigh fillets", "quantity": 600, "unit": "g", "preparation": "diced into 3cm cubes", "notes": "can substitute with leftover roast turkey (add at end)", "substitutions": [], "ingredient_id": "d7fc1bf9-fc05-429b-bfa6-2ad857cb0bb6", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "brown onions", "quantity": 2, "unit": null, "preparation": "finely chopped", "notes": "approx 300g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "ginger garlic paste", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "ground coriander", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "ground turmeric", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "kashmiri chili powder", "quantity": 3, "unit": "g", "preparation": null, "notes": "mild heat, adjust to taste", "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "crushed tomatoes", "quantity": 400, "unit": "g", "preparation": "canned", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "coconut milk", "quantity": 200, "unit": "ml", "preparation": "full fat", "notes": null, "substitutions": [], "ingredient_id": "c037ee7e-e3ed-4340-b8fb-d8ad284ba96e", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 100, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Bombay Potatoes", "items": [{"name": "waxy potatoes", "quantity": 500, "unit": "g", "preparation": "peeled and cubed into 2cm pieces", "notes": null, "substitutions": [], "ingredient_id": "5bf06478-4785-465e-9842-f70a24e22054", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "mustard seeds", "quantity": 5, "unit": "g", "preparation": "black", "notes": null, "substitutions": [], "ingredient_id": "69e2b7a1-7252-486e-841e-51655b028a97", "nutrition_source": "Aggregated Public Data"}, {"name": "ground turmeric", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "cumin seeds", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Onion Pakoras", "items": [{"name": "gram flour (chickpea flour)", "quantity": 150, "unit": "g", "preparation": null, "notes": "Besan", "substitutions": [], "ingredient_id": "2dd4045d-1f2e-460d-99ba-238c1f07eb5a", "nutrition_source": "Aggregated Public Data"}, {"name": "red onion", "quantity": 2, "unit": null, "preparation": "thinly sliced", "notes": "approx 200g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh spinach", "quantity": 50, "unit": "g", "preparation": "chopped roughly", "notes": null, "substitutions": [], "ingredient_id": "4734440a-226d-4d26-a110-3ed5c3bde93f", "nutrition_source": "USDA FoodData Central"}, {"name": "green chili", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "optional", "substitutions": [], "ingredient_id": "6cdb0615-378e-4bfa-b76d-f19bbd780e6c", "nutrition_source": "USDA FoodData Central"}, {"name": "garam masala", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ffcea01-5f22-462b-94de-ad2a97049325", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 80, "unit": "ml", "preparation": null, "notes": "add gradually", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "oil for frying", "quantity": 500, "unit": "ml", "preparation": null, "notes": "neutral oil with high smoke point", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the cubed potatoes in a pot of salted cold water. Bring to a boil and cook until just tender but holding their shape (par-boiled). Drain and let steam dry.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": null, "tactile": "Fork pierces easily but potato does not crumble"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "For the curry: Heat oil in the heavy pot. Add chopped onions and saut\u00e9 over medium heat until golden brown.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT10M", "doneness_cues": {"visual": "Deep golden brown color", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add ginger-garlic paste to the onions, cook for 1 minute, then add cumin, coriander, turmeric, and chili powder. Stir constantly for 30 seconds to toast spices.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the raw turkey cubes. Stir to coat in the spices and sear slightly on the outside.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour in crushed tomatoes, coconut milk, and water. Bring to a simmer, reduce heat to low, cover, and cook until turkey is tender. (Check internal temp reaches 74\u00b0C/165\u00b0F).", "structured": {"action": "SIMMER", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT25M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "While curry simmers, make Bombay Potatoes: Heat oil in the frying pan. Add mustard seeds; when they pop, add cumin seeds, turmeric, and the par-boiled potatoes. Fry until potatoes develop a crispy crust.", "structured": {"action": "FRY", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "prep", "text": "Prepare Pakora batter: In a bowl, mix sliced onions, spinach, gram flour, chili, garam masala, and salt. Gradually add water while mixing by hand until a thick, sticky batter coats the vegetables.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Sticky, not runny"}}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Heat frying oil to 180\u00b0C/350\u00b0F. Drop tablespoons of batter into the oil. Fry in batches until dark golden brown and crispy.", "structured": {"action": "FRY", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "assemble", "text": "Finish the curry with fresh cilantro. Serve the curry alongside the hot Bombay potatoes and crispy pakoras.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT1H15M", "passive_time": "PT15M", "total_time": "PT1H30M", "overnight_required": false, "yields": "4 generous servings", "yield_count": 4, "serving_size_g": 550}', '{"flags": ["Gluten-Free", "Dairy-Free", "Pescatarian"], "not_suitable_for": []}', '{"per_serving": {"calories": 756.66, "protein_g": 46.59, "carbohydrates_g": 61.98, "fat_g": 37.37, "saturated_fat_g": 14.6, "trans_fat_g": 0.03, "monounsaturated_fat_g": 3.25, "polyunsaturated_fat_g": 1.82, "fiber_g": 14.11, "sugar_g": 15.09, "sodium_mg": 259.21, "cholesterol_mg": 141, "potassium_mg": 1958.94, "calcium_mg": 171.22, "iron_mg": 11.34, "magnesium_mg": 256.51, "phosphorus_mg": 709.65, "zinc_mg": 6.07, "vitamin_a_mcg": 85.22, "vitamin_c_mg": 53.98, "vitamin_d_mcg": null, "vitamin_e_mg": 1.07, "vitamin_k_mcg": 67.04, "vitamin_b6_mg": 1.29, "vitamin_b12_mcg": 0.92, "thiamin_mg": 0.28, "riboflavin_mg": 0.44, "niacin_mg": 10.56, "folate_mcg": 85.05, "water_g": 428.25, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store curry, potatoes, and pakoras in separate airtight containers. Pakoras will lose crispness.", "duration": "P3D"}, "freezer": {"notes": "Curry freezes well. Potatoes and pakoras do not freeze well.", "duration": "P2M"}, "reheating": "Reheat curry and potatoes on stove. Reheat pakoras in an oven or air fryer at 180\u00b0C to recrisp.", "does_not_keep": false}', '[{"name": "Heavy-bottomed pot (Dutch oven)", "required": true, "alternative": null}, {"name": "Large frying pan", "required": true, "alternative": null}, {"name": "Deep frying pan or Wok", "required": true, "alternative": null}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Slotted spoon", "required": true, "alternative": null}, {"name": "Thermometer", "required": true, "alternative": null}]', '[{"symptom": "Pakoras are soggy and oily", "likely_cause": "Oil temperature was too low when batter was added", "prevention": "Use a thermometer to ensure oil is 180\u00b0C/350\u00b0F before frying", "fix": "Increase heat and fry remaining batches; reheat soggy ones in air fryer"}, {"symptom": "Turkey is dry", "likely_cause": "Overcooked or lean breast meat used instead of thigh", "prevention": "Use thigh meat and do not boil vigorously; gentle simmer only", "fix": "Shred the meat into the sauce and let it sit for 10 minutes to absorb moisture"}]', '["If using leftover roast turkey, skip the ''searing'' step for the meat. Make the sauce fully first, then fold in the cooked turkey in the last 5 minutes just to warm through.", "For the Bombay potatoes, ensure the potatoes are completely dry after boiling before adding to the hot oil to ensure they crisp up rather than steam.", "Gram flour (besan) is naturally gluten-free and high in protein, making the pakoras a substantial side dish.", "To test oil temperature without a thermometer, drop a small piece of bread in; it should sizzle and brown in 30 seconds."]', '"This spread represents a classic Anglo-Indian family feast structure. The curry utilizes a ''Bhuna'' style technique where spices are fried in oil to release essential oils, while the Pakoras (or Bhajis) are a quintessential street food snack from the Indian subcontinent, often served with chai or as an appetizer."', 756.66);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('712d1e01-a761-47cb-bfb3-2911ce5c15a4', 'Classic San Marzano Pomodoro', 'A vibrant, velvety foundation sauce balancing the natural sweetness of sun-ripened tomatoes with the savory depth of garlic and fruity olive oil. The texture is rustic yet cohesive, perfect for coating pasta or using as a pizza base.', 'sauce', 'Italian', 'Easy', '["condiments", "canned tomato", "dinner", "italian", "sauce", "staple", "vegan"]', '[{"group_name": "Base", "items": [{"name": "whole peeled tomatoes", "quantity": 800, "unit": "g", "preparation": "canned", "notes": "San Marzano variety preferred for sweetness", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": "Use high quality oil", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 4, "unit": null, "preparation": "thinly sliced", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Seasoning & Aromatics", "items": [{"name": "fresh basil", "quantity": 2, "unit": null, "preparation": "whole sprigs", "notes": "approx. 10g", "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 4, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "red pepper flakes", "quantity": 1, "unit": "g", "preparation": null, "notes": "for a gentle heat", "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pour the canned tomatoes and their juices into a large bowl. Using clean hands, crush the tomatoes into coarse chunks, removing any hard stem ends or tough skins if present.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Tomatoes are broken down but still chunky"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Combine the olive oil and sliced garlic in a heavy-bottomed saucepan. Turn the heat to medium-low. Cook gently, stirring occasionally, until the garlic is fragrant and pale gold, about 2-3 minutes. Do not let it brown.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": "PT3M", "doneness_cues": {"visual": "Garlic is pale gold", "tactile": "Fragrant aroma"}}, "tips": ["Starting garlic in cold oil infuses the oil more effectively than dropping it into hot oil.", "If using red pepper flakes, add them during the last 30 seconds of this step."]}, {"step_number": 3, "phase": "cook", "text": "Carefully pour the crushed tomatoes and juices into the pan (watch for splatter). Add the basil sprigs and salt. Stir to combine.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Increase heat to medium to bring to a gentle bubble, then reduce heat to low to maintain a steady simmer. Cook uncovered for 45 minutes, stirring occasionally, until the sauce has thickened and the oil separates slightly from the tomatoes.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT45M", "doneness_cues": {"visual": "Oil pools on surface, sauce coats the back of a spoon", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove and discard the wilted basil sprigs. Taste the sauce. If it tastes too acidic, add a pinch of sugar (optional). Add more salt if needed.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT45M", "total_time": "PT55M", "overnight_required": false, "yields": "800ml", "yield_count": 6, "serving_size_g": 130}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Paleo", "Whole30"], "not_suitable_for": []}', '{"per_serving": {"calories": 116.29, "protein_g": 1.37, "carbohydrates_g": 5.99, "fat_g": 10.32, "saturated_fat_g": 1.43, "trans_fat_g": null, "monounsaturated_fat_g": 7.31, "polyunsaturated_fat_g": 1.08, "fiber_g": 2.51, "sugar_g": 5.24, "sodium_mg": 265.99, "cholesterol_mg": null, "potassium_mg": 332.44, "calcium_mg": 20.41, "iron_mg": 0.52, "magnesium_mg": 16.49, "phosphorus_mg": 36.48, "zinc_mg": 0.27, "vitamin_a_mcg": 7.87, "vitamin_c_mg": 19.32, "vitamin_d_mcg": null, "vitamin_e_mg": 1.51, "vitamin_k_mcg": 13.1, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": null, "thiamin_mg": null, "riboflavin_mg": 0.01, "niacin_mg": 0.04, "folate_mcg": 1.37, "water_g": 2.72, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container once fully cooled.", "duration": "P5D"}, "freezer": {"notes": "Leave 2cm headspace in container for expansion.", "duration": "P3M"}, "reheating": "Simmer gently over low heat, adding a splash of water if too thick.", "does_not_keep": false}', '[{"name": "Heavy-bottomed saucepan or Dutch oven", "required": true, "alternative": "Large skillet with high sides"}, {"name": "Wooden spoon", "required": true, "alternative": null}, {"name": "Large bowl", "required": true, "alternative": null}]', '[{"symptom": "Sauce tastes metallic or overly acidic", "likely_cause": "Tomatoes were under-ripe or lower quality canning", "prevention": "Use DOP certified San Marzano tomatoes", "fix": "Stir in a pinch of baking soda (neutralizes acid) or 2g of sugar (masks acid)"}, {"symptom": "Garlic tastes bitter", "likely_cause": "Garlic was burned during the saut\u00e9 step", "prevention": "Start garlic in cold oil and keep heat low", "fix": "Cannot be fixed; the burnt flavor permeates the oil. You must restart the base."}]', '["Hand-crushing the tomatoes results in a superior rustic texture compared to using a blender, which can aerate the sauce and turn it orange.", "The ''oil slick'' that appears on top at the end is a sign of a properly cooked sauce; stir it back in before serving for a glossy finish.", "For a smooth ''passata'' style sauce, you can pass the finished product through a food mill, but remove the basil first.", "If you have a parmesan rind, add it during the simmer step for extra umami, but remove before serving."]', '"Known simply as ''Sugo di Pomodoro'' in Italy, this is the mother sauce of Southern Italian cooking. While tomatoes originated in the Americas, this specific technique of slow-simmering them with a soffritto of garlic and oil became a Neapolitan staple in the late 18th century."', 116.29);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('7171dae3-4232-4038-b8a7-ee4b821b1981', 'Miniature Almond Tortes with Duo Toppings', 'Luxuriously moist and dense cakes featuring a velvety almond crumb that dissolves on the tongue. These gluten-free jewels are finished with two distinct toppings: a lustrous bittersweet chocolate ganache for richness, and a tart cherry jam to cut the sweetness. Best enjoyed fresh to preserve their delicate texture.', 'dessert', 'French', 'Intermediate', '["cakes", "almond flour", "bittersweet chocolate", "cream", "dessert", "gluten-free", "birthday", "father''s day", "mother''s day", "valentine''s day"]', '[{"group_name": "Almond Cake Base", "items": [{"name": "superfine almond flour", "quantity": 200, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "softened", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 4, "unit": null, "preparation": "room temperature, separated", "notes": "approx. 200g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "almond extract", "quantity": 2, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "39141299-c561-4745-8ff7-cf7c62c75675", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a5fb6a2a-dcda-4ab2-8fe6-472d7fcc39d1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Bittersweet Ganache", "items": [{"name": "bittersweet chocolate (70%)", "quantity": 85, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "08395d12-1a43-46f7-b602-36c2d07ce259", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 80, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Fruit Finish", "items": [{"name": "cherry jam", "quantity": 80, "unit": "g", "preparation": "high quality", "notes": null, "substitutions": [], "ingredient_id": "09e72f52-a141-43da-82f5-02f70d0c07d1", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 175\u00b0C (350\u00b0F). Generously grease the muffin tin with butter or cooking spray.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Separate the eggs. Place yolks in a large mixing bowl and whites in a separate clean bowl.", "structured": {"action": "MEASURE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Beat the egg yolks and 100g of the sugar together until pale yellow and creamy. Add the softened butter, almond extract, and lemon zest (if using), beating until smooth.", "structured": {"action": "BEAT", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Pale yellow and creamy", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Stir the almond flour and salt into the yolk mixture until fully combined. The batter will be thick.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "In the separate bowl, whip the egg whites until soft peaks form. Gradually add the remaining 50g of sugar and whip until glossy, stiff peaks form.", "structured": {"action": "WHIP", "temperature": null, "duration": null, "doneness_cues": {"visual": "Glossy stiff peaks", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Gently fold one-third of the egg whites into the almond batter to lighten it. Fold in the remaining whites carefully to preserve air bubbles.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Divide the batter evenly among the 12 muffin cups. Bake for 20-25 minutes, or until the tops are golden and spring back when lightly touched.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT25M", "doneness_cues": {"visual": "Golden brown tops", "tactile": "Springs back when touched"}}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "While cakes cool, place chopped chocolate in a heatproof bowl. Heat heavy cream in a saucepan until just simmering, then pour over chocolate. Let sit for 1 minute, then whisk until glossy.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": {"visual": "Glossy and smooth", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Once cakes are cool, remove from tin. Top six cakes with a spoonful of ganache and the remaining six with a spoonful of cherry jam. Serve immediately.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT50M", "total_time": "PT1H25M", "overnight_required": false, "yields": "12 mini cakes", "yield_count": 12, "serving_size_g": 75}', '{"flags": ["Gluten-Free", "Vegetarian", "Soy-Free"], "not_suitable_for": ["Tree Nut Allergies"]}', '{"per_serving": {"calories": 277.16, "protein_g": 4.54, "carbohydrates_g": 32.18, "fat_g": 14.64, "saturated_fat_g": 8.48, "trans_fat_g": 0.09, "monounsaturated_fat_g": 4.29, "polyunsaturated_fat_g": 0.87, "fiber_g": 1.06, "sugar_g": 18.3, "sodium_mg": 92.36, "cholesterol_mg": 90.56, "potassium_mg": 90.16, "calcium_mg": 23.31, "iron_mg": 0.95, "magnesium_mg": 18.82, "phosphorus_mg": 75.6, "zinc_mg": 0.55, "vitamin_a_mcg": 119.83, "vitamin_c_mg": 0.32, "vitamin_d_mcg": 0.44, "vitamin_e_mg": 0.51, "vitamin_k_mcg": 1.49, "vitamin_b6_mg": 0.04, "vitamin_b12_mcg": 0.19, "thiamin_mg": 0.03, "riboflavin_mg": 0.1, "niacin_mg": 0.29, "folate_mcg": 12.74, "water_g": 20.31, "alcohol_g": null, "caffeine_mg": 6.09}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Texture degrades rapidly; best consumed within 8 hours of baking.", "duration": "P1D"}, "freezer": {"notes": "Freezing changes the delicate crumb structure; not recommended.", "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Standard 12-cup muffin tin", "required": true, "alternative": null}, {"name": "Stand mixer or electric hand mixer", "required": true, "alternative": null}, {"name": "Small saucepan", "required": true, "alternative": "Microwave-safe bowl"}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}, {"name": "Sieve", "required": true, "alternative": null}]', '[{"symptom": "Cakes are dense or flat", "likely_cause": "Egg whites were deflated during folding or over-mixed", "prevention": "Fold gently using a ''cut and fold'' motion; do not stir vigorously once whites are added", "fix": "Serve anyway; they will still taste delicious but texture will be fudge-like"}]', '["The 8-hour rule is critical: almond flour has high oil content which can make the cakes heavy or greasy if they sit too long at room temperature.", "Ensure your almond flour is ''superfine'' or ''blanched''. If you only have almond meal (with skins), the texture will be rustic and coarser.", "For the ganache, use chocolate with at least 60% cocoa solids to balance the richness of the almond cake.", "If the cherry jam is very stiff, warm it slightly in a microwave for 10 seconds to make it spoonable."]', '"These miniature tortes are a gluten-free adaptation of the French ''Financier'' or ''Pain de G\u00eanes'', historically baked by French nuns or Swiss pastry chefs to utilize high quantities of almonds. The rich, dense texture mimics marzipan but with a lighter, cake-like crumb."', 277.16);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('71d92c7f-7139-4393-982b-254f5400e037', 'Classic Dutch Apple Pie with Walnut Streusel', 'A comforting masterpiece featuring tender, spiced apples bathed in a touch of heavy cream for a luxurious mouthfeel. The dish combines a flaky, butter-rich bottom crust with a generous, crackly walnut streusel topping that delivers crunch in every bite.', 'dessert', 'American', 'Intermediate', '["american", "new england", "project", "apple", "apple pie", "brown sugar", "freezer friendly", "heavy cream", "make-ahead", "party", "pie dough", "walnut", "dessert", "fall", "thanksgiving"]', '[{"group_name": "Single Crust Pastry", "items": [{"name": "all-purpose flour", "quantity": 160, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "sugar", "quantity": 12, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "ice water", "quantity": 60, "unit": "ml", "preparation": null, "notes": "approximate, add gradually", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Creamy Apple Filling", "items": [{"name": "baking apples", "quantity": 6, "unit": null, "preparation": "peeled, cored, sliced 6mm thick", "notes": "approx. 1.1kg; Granny Smith and Honeycrisp mix", "substitutions": [], "ingredient_id": "9985672b-aa9f-4125-8a32-62d520c99d6f", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 60, "unit": "ml", "preparation": null, "notes": "min 35% fat", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 25, "unit": "g", "preparation": null, "notes": "for thickening", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 1, "unit": null, "preparation": null, "notes": "tsp (approx 2.5g)", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "ground nutmeg", "quantity": 0.5, "unit": null, "preparation": null, "notes": "tsp (approx 1g)", "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Walnut Streusel Topping", "items": [{"name": "all-purpose flour", "quantity": 95, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "brown sugar", "quantity": 100, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 85, "unit": "g", "preparation": "melted and slightly cooled", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "walnuts", "quantity": 85, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "ab4fe25a-a215-4af7-8109-055c28e0bef2", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine flour, sugar, and salt in a processor. Pulse in cold butter until the mixture resembles coarse meal with pea-sized bits.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Drizzle in ice water one tablespoon at a time, pulsing until the dough just begins to clump together. Do not overwork.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["If the dough looks dry but holds together when squeezed, it is ready."]}, {"step_number": 3, "phase": "prep", "text": "Form dough into a disk, wrap in plastic, and refrigerate for at least 60 minutes to relax the gluten.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Roll out the chilled dough on a floured surface to a 30cm circle. Transfer to the pie dish, trim, and crimp edges. Freeze the shell for 15 minutes.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Preheat oven to 200\u00b0C/400\u00b0F. Place a baking sheet on the lower rack to catch drips and conduct heat.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "Toss peeled apple slices with lemon juice in a large bowl. In a separate small bowl, whisk sugar, flour, cinnamon, and nutmeg.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Add the dry mixture and the heavy cream to the apples. Toss vigorously until the apples are evenly coated in a creamy, spiced batter.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Layer apples tightly into the chilled pie shell, mounding them slightly in the center to account for shrinkage.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "prep", "text": "For the streusel: Combine flour, brown sugar, and walnuts in a bowl. Pour in melted butter and mix with a fork until large, moist crumbs form.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "assemble", "text": "Sprinkle the streusel generously over the apples, covering them completely.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 11, "phase": "cook", "text": "Bake on the preheated baking sheet at 200\u00b0C/400\u00b0F for 20 minutes. Then reduce heat to 175\u00b0C/350\u00b0F and bake for another 40-50 minutes.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT50M", "doneness_cues": {"visual": "Filling bubbling thick juices near the center; topping deep golden brown", "tactile": "Apples tender when pierced with a knife"}}, "tips": ["If the topping browns too quickly, tent loosely with aluminum foil after 30 minutes."]}, {"step_number": 12, "phase": "finish", "text": "Remove from oven and cool on a wire rack for at least 3 hours. This is critical for the filling to set.", "structured": {"action": "COOL", "temperature": null, "duration": "PT3H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT4H", "total_time": "PT4H45M", "overnight_required": false, "yields": "1 9-inch pie (8 slices)", "yield_count": 8, "serving_size_g": 180}', '{"flags": ["Vegetarian", "Egg-Free", "Soy-Free"], "not_suitable_for": ["Nut allergies", "Gluten intolerance", "Dairy intolerance"]}', '{"per_serving": {"calories": 576.66, "protein_g": 6.05, "carbohydrates_g": 74.07, "fat_g": 30.54, "saturated_fat_g": 15.13, "trans_fat_g": 0.09, "monounsaturated_fat_g": 7.53, "polyunsaturated_fat_g": 6.1, "fiber_g": 5.16, "sugar_g": 41.06, "sodium_mg": 156.46, "cholesterol_mg": 62.23, "potassium_mg": 265.25, "calcium_mg": 49.09, "iron_mg": 1.02, "magnesium_mg": 34.12, "phosphorus_mg": 101.15, "zinc_mg": 0.68, "vitamin_a_mcg": 206.11, "vitamin_c_mg": 7.25, "vitamin_d_mcg": 0.12, "vitamin_e_mg": 1, "vitamin_k_mcg": 5.51, "vitamin_b6_mg": 0.14, "vitamin_b12_mcg": 0.06, "thiamin_mg": 0.11, "riboflavin_mg": 0.1, "niacin_mg": 0.72, "folate_mcg": 25.3, "water_g": 140.12, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Cover loosely with foil or plastic wrap.", "duration": "P4D"}, "freezer": {"notes": "Freeze baked pie wrapped tightly; thaw in fridge overnight.", "duration": "P3M"}, "reheating": "Warm in a 175\u00b0C oven for 10-15 minutes to re-crisp the streusel.", "does_not_keep": false}', '[{"name": "9-inch pie dish", "required": true, "alternative": "Deep-dish tart pan"}, {"name": "Food processor", "required": false, "alternative": "Pastry blender or fork"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Rolling pin", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": "Pizza stone"}]', '[{"symptom": "Pie filling is runny/soupy when sliced", "likely_cause": "The pie was cut while still warm, or apples released too much water without enough thickener", "prevention": "Allow to cool completely (3+ hours) so pectin and starch can gel", "fix": "Refrigerate the pie to help solidify the filling before serving"}]', '["Using a mix of Granny Smith (tart, holds shape) and Honeycrisp or Braeburn (sweet, breaks down slightly) creates the best texture and flavor profile.", "The addition of heavy cream to the filling creates a ''custard-like'' coating around the apples, mimicking the richness of a scoop of ice cream inside the pie.", "Chilling the pie shell before baking helps prevent shrinkage and keeps the crimped edges sharp.", "Place the pie on a preheated baking sheet to ensure the bottom crust cooks through and becomes crispy rather than soggy.", "Don''t skip the rest period. A warm fruit pie will always fall apart; it needs time for the starches to retrograde and set."]', '"While ''Dutch Apple Pie'' typically refers to the crumb-topping style popularized by Pennsylvania Dutch communities in the US, the concept of spicing apples and wrapping them in dough dates back to medieval Europe. This version emphasizes the American tradition of abundance with a towering streusel topping."', 576.66);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('71edd3eb-523e-4911-9c53-a26357439857', 'Rustic Mango Basque Cheesecake', 'A striking variation of the San Sebastián classic, featuring a deeply caramelized, burnished top and a molten, custard-like center infused with concentrated mango. The tropical fruit acidity cuts through the rich, creamy interior for a sophisticated balance.', 'dessert', 'Spanish', 'Intermediate', '["mango", "heavy cream", "egg", "egg yolk", "cheesecake", "dessert", "bake", "cream cheese", "vegetarian", "plan-ahead", "food processor"]', '[{"group_name": "Mango Reduction", "items": [{"name": "fresh ripe mango flesh", "quantity": 400, "unit": "g", "preparation": "diced", "notes": "Will be reduced to approx 200g", "substitutions": [], "ingredient_id": "6ab51d7d-dea3-4f14-8253-76acb67bd2c8", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Cheesecake Base", "items": [{"name": "cream cheese", "quantity": 600, "unit": "g", "preparation": "room temperature", "notes": "Full fat is essential", "substitutions": [], "ingredient_id": "262c67de-76a4-4444-8c02-30ad4a179459", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 200, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 4, "unit": null, "preparation": "large, room temperature", "notes": "approx 200g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "egg yolks", "quantity": 2, "unit": null, "preparation": "room temperature", "notes": "approx 36g total", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 280, "unit": "ml", "preparation": null, "notes": "Min 35% fat", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 25, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 240\u00b0C (465\u00b0F). Position the rack in the middle of the oven.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 240, "fahrenheit": 464}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Prepare the springform pan by lining it with two large sheets of parchment paper. Crumple the paper first, then press it into the pan, ensuring it extends at least 5cm (2 inches) above the rim. Pleats and folds are desired.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Puree the mango flesh until smooth. Transfer to a saucepan and simmer over medium heat, stirring frequently, until reduced by half (you should have about 200g/200ml). Allow to cool completely.", "structured": {"action": "REDUCE", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT15M", "doneness_cues": {"visual": "Thickened and reduced by half volume", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In the food processor, combine the room-temperature cream cheese and sugar. Pulse until completely smooth and creamy, scraping down the sides to remove lumps.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Smooth, no lumps", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Add the whole eggs and extra yolks one at a time while the machine runs on low speed (or pulse), ensuring each is incorporated before adding the next.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "Pour in the cooled mango reduction, heavy cream, lemon juice, vanilla, and salt. Process until combined.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "prep", "text": "Sift the flour over the batter. Pulse 2-3 times just to incorporate. Do not overmix.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Pour the batter into the prepared pan. Bake for 30-35 minutes. The top should be dark brown (bordering on black in spots) and the center should still be very jiggly, like unset gelatin.", "structured": {"action": "BAKE", "temperature": {"celsius": 240, "fahrenheit": 464}, "duration": "PT35M", "doneness_cues": {"visual": "Deeply bronzed top", "tactile": "Significant wobble in the center"}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove from the oven. Let cool in the pan at room temperature until fully set (about 2-3 hours), then refrigerate for at least 3-4 hours before slicing.", "structured": {"action": "COOL", "temperature": null, "duration": "PT6H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT6H", "total_time": "PT6H35M", "overnight_required": true, "yields": "1 23cm cake (10 servings)", "yield_count": 10, "serving_size_g": 160}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 457.55, "protein_g": 8.17, "carbohydrates_g": 32.42, "fat_g": 33.78, "saturated_fat_g": 19.57, "trans_fat_g": 1.06, "monounsaturated_fat_g": 9.11, "polyunsaturated_fat_g": 1.9, "fiber_g": 0.71, "sugar_g": 28.7, "sodium_mg": 343.19, "cholesterol_mg": 205.52, "potassium_mg": 209.39, "calcium_mg": 97.69, "iron_mg": 0.65, "magnesium_mg": 14.61, "phosphorus_mg": 142.49, "zinc_mg": 0.77, "vitamin_a_mcg": 367.2, "vitamin_c_mg": 15.12, "vitamin_d_mcg": 1.04, "vitamin_e_mg": 1.44, "vitamin_k_mcg": 3.93, "vitamin_b6_mg": 0.14, "vitamin_b12_mcg": 0.43, "thiamin_mg": 0.05, "riboflavin_mg": 0.32, "niacin_mg": 0.39, "folate_mcg": 39.23, "water_g": 99.73, "alcohol_g": 0.17, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Keep loosely covered to maintain the texture of the burnt top.", "duration": "P4D"}, "freezer": {"notes": "Freezing is not recommended as it alters the creamy texture.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Food processor", "required": true, "alternative": null}, {"name": "23cm (9-inch) springform pan", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": "None - essential for the rustic shape"}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Sieve", "required": false, "alternative": null}]', '[{"symptom": "Cake is soupy in the middle after slicing", "likely_cause": "The cake was sliced while still warm or didn''t chill long enough", "prevention": "Basque cheesecake relies on residual heat and refrigeration to set the custard center. Must chill completely.", "fix": "Return to the fridge for 2-4 hours to firm up."}, {"symptom": "Top isn''t burning/browning enough", "likely_cause": "Oven temperature too low", "prevention": "Ensure oven is fully preheated to 240\u00b0C; use an oven thermometer.", "fix": "Move to the top rack for the last 2-3 minutes of baking."}]', '["Temperature is critical: All dairy ingredients must be at room temperature before mixing to prevent lumps.", "The mango reduction step is mandatory. Using raw puree adds too much water, which prevents the cheesecake from setting properly.", "Do not be afraid of the dark color. The ''burnt'' flavor creates a caramel bitterness that counteracts the richness of the cream and the sweetness of the mango.", "Serve with a pinch of flaky sea salt on top to pop the flavors.", "For the cleanest slices, dip a sharp knife in hot water and wipe dry between every cut."]', '"Originating from the La Vi\u00f1a bar in San Sebasti\u00e1n, Spain, the Basque cheesecake (Tarta de Queso) defies traditional baking rules by baking at extreme heat for a burnt crust and creamy core. This variation introduces mango, a fruit popular in modern Spanish fusion cuisine, adding a bright, tropical dimension to the rustic classic."', 457.55);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('72132baa-82df-40bf-b511-a627adc8aa23', 'Szechuan Cold Sesame Chicken (Bang Bang Chicken)', 'Tender, poached chicken shreds served chilled over crisp cucumber matchsticks, drenched in a nutty, savory, and spicy sesame sauce. This classic Szechuan dish balances the richness of sesame paste with the zing of black vinegar and chili oil.', 'lunch', 'Chinese', 'Intermediate', '["poultry", "chicken", "ginger", "peanut", "scallion", "dinner", "weeknight", "sichuan", "cold dish", "picnic"]', '[{"group_name": "Poached Chicken", "items": [{"name": "chicken breast", "quantity": 500, "unit": "g", "preparation": "boneless, skinless", "notes": "approx 2 large breasts", "substitutions": [], "ingredient_id": "2b577d04-33ca-4919-938f-bfc8780a3a4b", "nutrition_source": "USDA FoodData Central"}, {"name": "ginger", "quantity": 15, "unit": "g", "preparation": "sliced", "notes": "about 3 slices", "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "scallion", "quantity": 2, "unit": null, "preparation": "whole", "notes": "approx 30g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "shaoxing wine", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "bb7adcb8-7e07-46ec-a3ac-e02f9ffb6f9f", "nutrition_source": "Aggregated Public Data"}, {"name": "sichuan peppercorns", "quantity": 2, "unit": "g", "preparation": null, "notes": "whole", "substitutions": [], "ingredient_id": "e6c536be-e3e6-4620-8f0a-e66e55284408", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Sesame Sauce", "items": [{"name": "chinese sesame paste", "quantity": 45, "unit": "g", "preparation": null, "notes": null, "substitutions": ["tahini mixed with peanut butter"], "ingredient_id": "a7f0ef81-bdc6-4458-be17-be1741e7f2b7", "nutrition_source": "USDA FoodData Central"}, {"name": "soy sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": "light soy sauce", "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "chinkiang vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": "black vinegar", "substitutions": ["balsamic vinegar"], "ingredient_id": "fcbf5252-1be9-4dd4-8c22-4fda1dbdca28", "nutrition_source": "Aggregated Public Data"}, {"name": "chili oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "with sediment", "substitutions": [], "ingredient_id": "31637e18-796b-464f-a599-08e4a007f4e5", "nutrition_source": "Aggregated Public Data"}, {"name": "sugar", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 8g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "chicken poaching liquid", "quantity": 30, "unit": "ml", "preparation": "cooled", "notes": null, "substitutions": [], "ingredient_id": null, "nutrition_source": null}]}, {"group_name": "Assembly", "items": [{"name": "cucumber", "quantity": 300, "unit": "g", "preparation": "julienned", "notes": "Persian or English cucumber preferred", "substitutions": [], "ingredient_id": "457adec2-3e06-4efe-a26e-9e6ea9f84924", "nutrition_source": "USDA FoodData Central"}, {"name": "roasted peanuts", "quantity": 30, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "ba36d967-879c-446b-ba1e-b1fa36e475db", "nutrition_source": "Aggregated Public Data"}, {"name": "toasted sesame seeds", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36a7664a-f96c-44b9-9b6d-cdd5e9e54f55", "nutrition_source": "Aggregated Public Data"}, {"name": "scallion", "quantity": 1, "unit": null, "preparation": "sliced", "notes": "green parts only", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Place chicken breasts, sliced ginger, whole scallions, Shaoxing wine, and Sichuan peppercorns in a pot. Cover with cold water by 2cm. Bring to a boil over medium-high heat.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Once boiling, cover the pot with a tight lid, remove immediately from heat, and let stand undisturbed. The residual heat will gently poach the chicken to an internal temperature of 74\u00b0C/165\u00b0F. This prevents the meat from drying out.", "structured": {"action": "POACH", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": "PT20M", "doneness_cues": {"visual": "Opaque throughout", "tactile": "Firm but yielding"}}, "tips": ["Do not lift the lid during this time or heat will escape."]}, {"step_number": 3, "phase": "prep", "text": "While chicken poaches, prepare an ice water bath. Once the chicken is cooked, transfer it immediately to the ice bath to stop cooking and firm up the meat texture.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In a mixing bowl, whisk together sesame paste, soy sauce, black vinegar, sugar, minced garlic, and chili oil. Gradually whisk in 20-40ml of the poaching liquid (once cooled slightly) until the sauce reaches a creamy, pourable consistency.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Pat the cooled chicken dry. Lightly pound the thickest parts with a rolling pin to loosen the fibers (the traditional ''bang bang'' method). Shred the meat into bite-sized strips by hand or with forks.", "structured": {"action": "SHRED", "temperature": null, "duration": null, "doneness_cues": {"visual": "Uniform strips", "tactile": "Fibers separated"}}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Arrange the julienned cucumbers at the bottom of a serving dish. Pile the shredded chicken on top. Pour the sauce generously over the chicken. Garnish with chopped peanuts, toasted sesame seeds, and sliced scallions.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT45M", "total_time": "PT1H15M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 250}', '{"flags": ["Dairy-Free", "Pescatarian"], "not_suitable_for": ["Peanut allergy", "Sesame allergy", "Soy allergy", "Gluten intolerance (unless tamari is used)"]}', '{"per_serving": {"calories": 399.77, "protein_g": 29.25, "carbohydrates_g": 13.12, "fat_g": 25.26, "saturated_fat_g": 6.12, "trans_fat_g": 0.13, "monounsaturated_fat_g": 6.83, "polyunsaturated_fat_g": 4.85, "fiber_g": 2.15, "sugar_g": 5.85, "sodium_mg": 1255.15, "cholesterol_mg": 80, "potassium_mg": 481.55, "calcium_mg": 96.21, "iron_mg": 1.8, "magnesium_mg": 60.15, "phosphorus_mg": 327.86, "zinc_mg": 1.75, "vitamin_a_mcg": 39.96, "vitamin_c_mg": 5.45, "vitamin_d_mcg": 0.5, "vitamin_e_mg": 0.43, "vitamin_k_mcg": 31.49, "vitamin_b6_mg": 0.75, "vitamin_b12_mcg": 0.43, "thiamin_mg": 0.25, "riboflavin_mg": 0.2, "niacin_mg": 13.22, "folate_mcg": 27.67, "water_g": 171.05, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store sauce and chicken separately for best texture. Assemble just before serving.", "duration": "P3D"}, "freezer": {"notes": "Do not freeze; cucumber will spoil and emulsion may break.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Meat thermometer", "required": true, "alternative": null}, {"name": "Rolling pin or meat mallet", "required": true, "alternative": "Heavy pan base"}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Ice bath", "required": true, "alternative": null}]', '[{"symptom": "Chicken is dry and stringy", "likely_cause": "Water boiled too vigorously or chicken sat in hot water too long", "prevention": "Remove from heat immediately after boiling and trust the steeping method", "fix": "Shred very finely and toss with extra chili oil and sauce to mask dryness"}, {"symptom": "Sauce is seized or clumpy", "likely_cause": "Sesame paste was too dry or water was added too quickly", "prevention": "Add liquid one tablespoon at a time while whisking", "fix": "Whisk in warm water 1 teaspoon at a time until smooth"}]', '["The name ''Bang Bang Chicken'' comes from the traditional method of pounding the meat with a wooden stick to tenderize the fibers before shredding.", "If you cannot find Chinese sesame paste, use a 50/50 blend of tahini and unsweetened smooth peanut butter. Pure tahini is too bitter; pure peanut butter is too sweet.", "For picnics, keep the sauce in a jar and the chicken/cucumber in a container. Dress immediately before eating to keep the cucumbers crisp.", "The poaching liquid is a light chicken stock\u2014don''t throw it away! It can be used as a base for egg drop soup."]', '"Originating from Sichuan province, Bang Bang Chicken (Bang Bang Ji) is a street food classic dating back to the early 20th century. The vendors would rhythmically beat the chicken with wooden batons, creating a distinct sound that gave the dish its name. It highlights the Sichuan love for ''ma la'' (numbing and spicy) flavors balanced with nutty richness."', 399.77);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('721e7fe5-c342-4e39-ac65-22d9319b7505', 'Frozen Banana Pops', 'Creamy frozen bananas coated in a crisp dark chocolate shell or tangy yogurt, finished with a crunch of roasted nuts or freeze-dried fruit. A refreshing, wholesome treat that perfectly balances natural sweetness with rich textures.', 'dessert', 'American', 'Easy', '["dessert", "snack", "healthy", "fruit", "kid-friendly", "summer", "gluten-free"]', '[{"group_name": "Base", "items": [{"name": "bananas", "quantity": 4, "unit": null, "preparation": "ripe but firm", "notes": "approx. 120g each", "substitutions": [], "ingredient_id": "d01cd7bd-9b20-4ccf-8475-27ca2843edf6", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Chocolate Coating Option", "items": [{"name": "dark chocolate", "quantity": 200, "unit": "g", "preparation": "chopped or chips", "notes": "70% cocoa recommended", "substitutions": ["milk chocolate", "semi-sweet chocolate"], "ingredient_id": "08395d12-1a43-46f7-b602-36c2d07ce259", "nutrition_source": "USDA FoodData Central"}, {"name": "coconut oil", "quantity": 15, "unit": "g", "preparation": null, "notes": "helps thin the chocolate", "substitutions": [], "ingredient_id": "bfc74b81-e1e0-4607-9eec-8d0eff76d78c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Yogurt Coating Option", "items": [{"name": "greek yogurt", "quantity": 250, "unit": "g", "preparation": "plain or vanilla", "notes": null, "substitutions": [], "ingredient_id": "61eae1a4-8517-4da8-8c29-34288cb7d8c7", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 30, "unit": "g", "preparation": null, "notes": "optional sweetener", "substitutions": ["maple syrup"], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Toppings", "items": [{"name": "chopped nuts", "quantity": 50, "unit": "g", "preparation": "toasted", "notes": "almonds, walnuts, or pecans", "substitutions": [], "ingredient_id": "b1a964a3-2955-4a56-be6a-02d8b0106c1d", "nutrition_source": "Aggregated Public Data"}, {"name": "desiccated coconut", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "dbd3e1d1-e181-4364-b869-f2e9c0f15317", "nutrition_source": "Aggregated Public Data"}, {"name": "freeze-dried strawberries", "quantity": 15, "unit": "g", "preparation": "crushed", "notes": null, "substitutions": [], "ingredient_id": "d2794d57-7747-4b9c-86d0-e474f29d600a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Line a baking sheet with parchment paper. Peel the bananas and slice them in half crosswise. Insert a popsicle stick about halfway into the cut end of each banana half.", "structured": {"action": "PREPARE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Bananas are securely skewered", "tactile": null}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Place the skewered bananas on the lined baking sheet. Freeze for 20 minutes. This \"flash freeze\" ensures the bananas are cold enough to set the coating quickly but not frozen solid yet.", "structured": {"action": "FREEZE", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Prepare your chosen coating. For Chocolate: Combine chocolate and coconut oil in a microwave-safe bowl. Heat in 30-second intervals, stirring between each, until completely smooth (approx 45\u00b0C/113\u00b0F). For Yogurt: Whisk yogurt and honey together in a small bowl.", "structured": {"action": "TEMPER", "temperature": {"celsius": 45, "fahrenheit": 113}, "duration": null, "doneness_cues": null}, "tips": ["Pour the coating into a tall glass to make dipping easier."]}, {"step_number": 4, "phase": "assemble", "text": "Dip each chilled banana into the coating, tilting the glass to cover the fruit completely. Allow excess coating to drip off for a few seconds.", "structured": {"action": "DREDGE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Immediately sprinkle your toppings of choice over the wet coating before it sets. If using chocolate, you must work quickly as the cold banana hardens the shell instantly.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Return the decorated pops to the parchment-lined baking sheet. Freeze for at least 2 hours until completely solid.", "structured": {"action": "FREEZE", "temperature": null, "duration": "PT2H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT2H", "total_time": "PT2H20M", "overnight_required": false, "yields": "8 pops", "yield_count": 8, "serving_size_g": 85}', '{"flags": ["Vegetarian", "Gluten-Free", "Egg-Free", "Peanut-Free"], "not_suitable_for": ["Infants under 12 months (if using honey)"]}', '{"per_serving": {"calories": 323.72, "protein_g": 5.95, "carbohydrates_g": 37.96, "fat_g": 17.73, "saturated_fat_g": 7.76, "trans_fat_g": 0.02, "monounsaturated_fat_g": 3.02, "polyunsaturated_fat_g": 0.38, "fiber_g": 4.98, "sugar_g": 22.06, "sodium_mg": 14.46, "cholesterol_mg": 3.06, "potassium_mg": 402.89, "calcium_mg": 55.57, "iron_mg": 2.07, "magnesium_mg": 75.45, "phosphorus_mg": 107.29, "zinc_mg": 0.98, "vitamin_a_mcg": 19.43, "vitamin_c_mg": 8.96, "vitamin_d_mcg": null, "vitamin_e_mg": 0.21, "vitamin_k_mcg": 2.11, "vitamin_b6_mg": 0.23, "vitamin_b12_mcg": 0.05, "thiamin_mg": 0.03, "riboflavin_mg": 0.06, "niacin_mg": 0.62, "folate_mcg": 12.08, "water_g": 70.78, "alcohol_g": null, "caffeine_mg": 21.5}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Will melt; must be kept frozen.", "duration": null}, "freezer": {"notes": "Store in an airtight container separated by parchment paper.", "duration": "P1M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Popsicle sticks", "required": true, "alternative": "Wooden skewers (blunt ends)"}, {"name": "Microwave-safe bowl", "required": true, "alternative": null}, {"name": "Tall glass or jar", "required": true, "alternative": "Narrow bowl (for dipping)"}]', '[{"symptom": "Banana slips off the stick while dipping", "likely_cause": "Banana was too soft or stick was not inserted deep enough", "prevention": "Use firm-ripe bananas and freeze them for the full 20 minutes before dipping", "fix": "Use a spoon to pour coating over the banana instead of dipping"}, {"symptom": "Chocolate coating is too thick or clumpy", "likely_cause": "Chocolate seized from moisture or wasn''t thinned enough", "prevention": "Ensure all bowls are bone-dry and do not skip the coconut oil", "fix": "Stir in an extra teaspoon of coconut oil and gently reheat"}]', '["Ripe but firm bananas (yellow with no brown spots) work best; overripe bananas will be mushy when thawed slightly.", "Refined coconut oil is neutral in flavor, while unrefined will add a subtle tropical coconut taste.", "For the yogurt version, thicker Greek yogurt creates a better shell than regular yogurt, which may run off.", "These are sometimes called ''Monkey Tails'' and make excellent meal-prep snacks for kids."]', '"A modern staple of healthy snacking, frozen bananas gained pop-culture fame in the US via the TV show ''Arrested Development'', but they have long been a favorite summertime treat at boardwalks and fairs for offering a guilt-free alternative to ice cream."', 323.72);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('732b4cdf-d611-4bf6-8cdd-1e594d93c892', 'Zuppa alla Pavese', 'A comforting, rustic Italian soup originating from Pavia, consisting of rich hot broth poured over butter-fried bread and a perfectly poached egg, finished with a generous dusting of Parmesan.', 'soup', 'Italian', 'Easy', '["italian", "bread", "chicken broth", "egg", "lunch", "weeknight", "dinner", "comfort food", "quick"]', '[{"group_name": "Broth", "items": [{"name": "chicken broth", "quantity": 600, "unit": "ml", "preparation": "high quality", "notes": "homemade or low-sodium preferred", "substitutions": [], "ingredient_id": "2b577d04-33ca-4919-938f-bfc8780a3a4b", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Toast & Toppings", "items": [{"name": "crusty white bread", "quantity": 2, "unit": null, "preparation": "sliced 2cm thick", "notes": "approx. 40-50g per slice", "substitutions": [], "ingredient_id": "c4052e66-d9d4-41e7-a365-cd88abcd9202", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "fresh, room temperature", "notes": "approx. 60g each", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "parmesan cheese", "quantity": 30, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh chives", "quantity": 5, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Heat the chicken broth in a medium saucepan over medium heat until it reaches a gentle simmer.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "While broth heats, melt butter in a frying pan over medium heat. Fry the bread slices until golden brown and crispy on both sides.", "structured": {"action": "FRY", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT4M", "doneness_cues": {"visual": "Golden brown", "tactile": "Crispy"}}, "tips": []}, {"step_number": 3, "phase": "assemble", "text": "Place one slice of toasted bread into the bottom of each serving bowl. Sprinkle half of the grated Parmesan cheese directly onto the hot toast.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Crack the eggs directly into the simmering broth. Poach gently for about 3 minutes until the whites are set but the yolks remain runny.", "structured": {"action": "POACH", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT3M", "doneness_cues": {"visual": "Opaque whites", "tactile": "Soft yolk"}}, "tips": ["Crack eggs into a small ramekin first to avoid shell fragments.", "Ensure broth is not boiling vigorously or it will break the eggs."]}, {"step_number": 5, "phase": "finish", "text": "Carefully ladle a poached egg onto each slice of bread, then pour the hot broth around it. Garnish with remaining Parmesan, chives, and black pepper. Serve immediately.", "structured": {"action": "SERVE", "temperature": {"celsius": 70, "fahrenheit": 158}, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT0M", "total_time": "PT15M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 350}', '{"flags": ["Nut-Free", "Peanut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": ["Vegans", "Vegetarians (if using chicken broth)"]}', '{"per_serving": {"calories": 900.03, "protein_g": 79.61, "carbohydrates_g": 25.72, "fat_g": 51.2, "saturated_fat_g": 20, "trans_fat_g": 0.33, "monounsaturated_fat_g": 18.66, "polyunsaturated_fat_g": 8.51, "fiber_g": 1.44, "sugar_g": 3.04, "sodium_mg": 694.63, "cholesterol_mg": 458.1, "potassium_mg": 829.88, "calcium_mg": 304.16, "iron_mg": 4.97, "magnesium_mg": 102.28, "phosphorus_mg": 796.7, "zinc_mg": 3.93, "vitamin_a_mcg": 318.07, "vitamin_c_mg": 1.46, "vitamin_d_mcg": 2.48, "vitamin_e_mg": 1.94, "vitamin_k_mcg": 3.43, "vitamin_b6_mg": 1.73, "vitamin_b12_mcg": 1.77, "thiamin_mg": 0.4, "riboflavin_mg": 0.76, "niacin_mg": 31.59, "folate_mcg": 88.55, "water_g": 274.86, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best consumed immediately; bread becomes soggy and eggs do not reheat well.", "duration": null}, "freezer": {"duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Medium saucepan", "required": true, "alternative": null}, {"name": "Frying pan", "required": true, "alternative": null}, {"name": "Soup bowls", "required": true, "alternative": null}, {"name": "Ladle", "required": true, "alternative": null}]', '[{"symptom": "Egg whites spread too much in the broth", "likely_cause": "Broth was boiling too hard or eggs were not fresh", "prevention": "Keep broth at a very gentle simmer and use the freshest eggs possible", "fix": "Use a slotted spoon to gather stray whites before serving"}]', '["The quality of this dish relies entirely on the quality of the broth. Use a rich homemade stock or a high-quality bone broth for the best result.", "For an authentic touch, rub a clove of raw garlic on the toasted bread before placing it in the bowl.", "This dish is sometimes served by placing the raw egg on the bread and pouring boiling broth over it to cook it (Zuppa alla Pavese style), but poaching in the pot ensures consistent food safety and texture.", "If using store-bought broth, taste for salinity before adding extra salt, as the Parmesan and butter add significant sodium."]', '"Legend has it that King Francis I of France invented this dish after losing the Battle of Pavia in 1525. Seeking refuge in a peasant farmhouse, he was served this simple soup made from the limited ingredients available: stale bread, eggs, and broth."', 900.03);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('733d46e9-c6b6-4022-ac95-62fc97184519', 'Warm Potato and Leek Salad with Mustard Vinaigrette', 'A sophisticated yet rustic salad featuring creamy baby potatoes and tender, sweet melted leeks tossed in a sharp, tangy mustard vinaigrette. The contrast between the warm, earthy vegetables and the bright dressing makes this an ideal light main or elegant side dish.', 'salad', 'French', 'Easy', '["leek", "potato", "easy", "weeknight", "side dish", "gluten-free", "healthy", "vegetarian", "vegan", "french"]', '[{"group_name": "Vegetables", "items": [{"name": "baby potatoes", "quantity": 750, "unit": "g", "preparation": "whole or halved if large", "notes": "waxy variety like Yukon Gold or Red Bliss holds shape best", "substitutions": [], "ingredient_id": "41f30ad1-82e5-4826-9de0-cd33ecd578c1", "nutrition_source": "USDA FoodData Central"}, {"name": "leeks", "quantity": 2, "unit": null, "preparation": "sliced into half-moons", "notes": "large size, white and light green parts only, approx 300g prepared", "substitutions": [], "ingredient_id": "f0bddafa-51db-4e56-954b-18624daa6fa4", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vinaigrette & Saut\u00e9", "items": [{"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": "divided use: 15ml for cooking, 45ml for dressing", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "white wine vinegar", "quantity": 30, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "b2f8f0c0-6da9-47aa-932a-c2747b64b807", "nutrition_source": "Aggregated Public Data"}, {"name": "dijon mustard", "quantity": 15, "unit": "g", "preparation": "smooth", "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 3g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "approx 5g total, to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the baby potatoes in a large pot and cover with cold water by at least 2cm (1 inch). Season generously with salt.", "structured": {"action": "MEASURE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": ["Starting potatoes in cold water ensures they cook evenly from skin to center."]}, {"step_number": 2, "phase": "cook", "text": "Bring the water to a boil, then reduce heat to maintain a simmer. Cook until potatoes are tender when pierced with a knife, approximately 15 minutes.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT15M", "doneness_cues": {"visual": null, "tactile": "Fork or knife slides in with no resistance"}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "While potatoes cook, thoroughly wash the sliced leeks in a bowl of cold water to remove any grit, then drain and pat dry.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Leeks often trap dirt between layers; submersion is the most effective cleaning method."]}, {"step_number": 4, "phase": "cook", "text": "In a saut\u00e9 pan, heat 15ml (1 tbsp) of olive oil over medium heat. Saut\u00e9 the leeks with a pinch of salt until soft and sweet, but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT8M", "doneness_cues": {"visual": "Leeks are translucent and bright green", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "In a small mixing bowl, whisk together the minced garlic, Dijon mustard, white wine vinegar, and the remaining 45ml (3 tbsp) of olive oil until emulsified. Season with salt and pepper.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Drain the potatoes and let them steam dry for 2 minutes. If large, slice them in half while still warm.", "structured": {"action": "DRAIN", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "In a large bowl, gently toss the warm potatoes and saut\u00e9ed leeks with the vinaigrette. Allow the salad to sit for 5-10 minutes to absorb the flavors.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": ["Dressing potatoes while warm allows them to absorb the vinaigrette better than when cold."]}, {"step_number": 8, "phase": "finish", "text": "Garnish with freshly chopped parsley before serving.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT10M", "total_time": "PT35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 250}', '{"flags": ["Vegetarian", "Gluten-Free", "Vegan", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 851.52, "protein_g": 14.35, "carbohydrates_g": 166.93, "fat_g": 16.03, "saturated_fat_g": 2.25, "trans_fat_g": null, "monounsaturated_fat_g": 10.98, "polyunsaturated_fat_g": 1.87, "fiber_g": 12.8, "sugar_g": 9.51, "sodium_mg": 647.89, "cholesterol_mg": null, "potassium_mg": 2038.36, "calcium_mg": 173.82, "iron_mg": 4.58, "magnesium_mg": 144.68, "phosphorus_mg": 342.06, "zinc_mg": 1.16, "vitamin_a_mcg": 109.55, "vitamin_c_mg": 20.86, "vitamin_d_mcg": null, "vitamin_e_mg": 2.66, "vitamin_k_mcg": 71.36, "vitamin_b6_mg": 1.46, "vitamin_b12_mcg": null, "thiamin_mg": 0.44, "riboflavin_mg": 0.1, "niacin_mg": 6.64, "folate_mcg": 52.68, "water_g": 16.02, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves after a few hours; bring to room temperature before serving.", "duration": "P3D"}, "freezer": {"notes": "Do not freeze; potatoes will become grainy and leeks mushy.", "duration": null}, "reheating": "Gently warm in a pan over low heat or serve at room temperature.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Leeks feel gritty", "likely_cause": "Insufficient washing", "prevention": "Slice leeks first, then submerge in water and agitate to release dirt trapped in layers", "fix": "Cannot be fixed once cooked into the dish"}, {"symptom": "Potatoes are mushy/falling apart", "likely_cause": "Overcooking or wrong potato variety", "prevention": "Use waxy potatoes (new/baby potatoes) and check often after 12 minutes", "fix": "Mash them lightly and serve as a rustic crushed potato salad"}]', '["Always dress potatoes while they are warm; as the starch cools, it retrogrades and won''t absorb the vinaigrette as effectively.", "For extra texture, you can add 30g of toasted walnuts or pine nuts just before serving.", "If you prefer a creamier dressing without dairy, blend a small amount of the cooked potato into the vinaigrette.", "The white and light green parts of the leek are sweetest; save the dark green tops for stock."]', '"This dish is reminiscent of ''Poireaux Vinaigrette'', a classic Parisian bistro starter, but fortified with potatoes to make it substantial. It highlights the humble leek, a vegetable celebrated in French cuisine for its delicate onion flavor and melting texture."', 851.52);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('7354ab2a-f039-4088-9783-1d6e4115e57d', 'Seared Scallop and Asparagus Stir-Fry', 'Sweet, dry-packed sea scallops are seared to golden perfection and tossed with crisp-tender asparagus in a savory, garlic-ginger glaze. Finished with nutty toasted sesame seeds for a textural contrast.', 'dinner', 'Chinese', 'Intermediate', '["asian", "asparagus", "scallop", "sesame seed", "dinner", "easy", "quick", "main course", "summer", "stir-fry", "seafood"]', '[{"group_name": "Proteins & Vegetables", "items": [{"name": "sea scallops", "quantity": 300, "unit": "g", "preparation": "dry-packed, side muscle removed", "notes": "approx 10-12 large scallops", "substitutions": [], "ingredient_id": "19ba63d0-dcaf-4888-a975-8ef4817b1208", "nutrition_source": "USDA FoodData Central"}, {"name": "asparagus", "quantity": 250, "unit": "g", "preparation": "woody ends trimmed, cut into 5cm pieces", "notes": null, "substitutions": [], "ingredient_id": "8a2a9426-3755-4553-953a-fd9cf42cef90", "nutrition_source": "USDA FoodData Central"}, {"name": "ginger", "quantity": 10, "unit": "g", "preparation": "julienned or minced", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 30, "unit": "ml", "preparation": "grapeseed or vegetable", "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Stir-Fry Sauce", "items": [{"name": "soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "oyster sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "322ccc47-a56e-40df-b324-59f7944393b8", "nutrition_source": "Aggregated Public Data"}, {"name": "shaoxing wine", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["dry sherry"], "ingredient_id": "bb7adcb8-7e07-46ec-a3ac-e02f9ffb6f9f", "nutrition_source": "Aggregated Public Data"}, {"name": "sesame oil", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a9a59164-d949-4acd-99da-689f0a32e2e7", "nutrition_source": "Aggregated Public Data"}, {"name": "cornstarch", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "white pepper", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish", "items": [{"name": "toasted sesame seeds", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36a7664a-f96c-44b9-9b6d-cdd5e9e54f55", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Thoroughly pat the scallops dry with paper towels. This is critical for a good sear. Season lightly with salt.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a small bowl, whisk together soy sauce, oyster sauce, Shaoxing wine, sesame oil, water, cornstarch, and white pepper until smooth.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat half the oil (15ml) in the wok or skillet over high heat until shimmering. Carefully place scallops in the pan without overcrowding. Sear undisturbed for 2 minutes until golden brown.", "structured": {"action": "SEAR", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT2M", "doneness_cues": {"visual": "Deep golden brown crust on one side", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Flip the scallops and sear for 1 more minute. Remove scallops immediately to a plate (they should be slightly undercooked in the center).", "structured": {"action": "SEAR", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Wipe out the wok if needed. Add the remaining oil, then add asparagus, ginger, and garlic. Stir-fry vigorously for 2-3 minutes until asparagus is bright green and crisp-tender.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Asparagus turns bright green", "tactile": "Crisp-tender texture"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Whisk the sauce again to suspend starch, then pour over the asparagus. Once the sauce bubbles and thickens (about 30 seconds), return the scallops and their juices to the pan. Toss gently to coat and warm through.", "structured": {"action": "GLAZE", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Sauce is glossy and clings to ingredients", "tactile": null}}, "tips": ["Aim for an internal temperature of 52-54\u00b0C (125-130\u00b0F) for medium-rare scallops for best texture, though FDA guidelines recommend 63\u00b0C (145\u00b0F)."]}, {"step_number": 7, "phase": "finish", "text": "Remove from heat immediately. Sprinkle with toasted sesame seeds and serve.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT5M", "total_time": "PT25M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 320}', '{"flags": ["Pescatarian", "Dairy-Free", "Nut-Free"], "not_suitable_for": ["Shellfish allergy"]}', '{"per_serving": {"calories": 257.36, "protein_g": 5.59, "carbohydrates_g": 18.09, "fat_g": 19.31, "saturated_fat_g": 2.29, "trans_fat_g": null, "monounsaturated_fat_g": 0.03, "polyunsaturated_fat_g": 0.21, "fiber_g": 5.09, "sugar_g": 7.53, "sodium_mg": 1447.84, "cholesterol_mg": null, "potassium_mg": 579.75, "calcium_mg": 99.65, "iron_mg": 4.17, "magnesium_mg": 64.55, "phosphorus_mg": 137.75, "zinc_mg": 1.18, "vitamin_a_mcg": 64, "vitamin_c_mg": 35.3, "vitamin_d_mcg": null, "vitamin_e_mg": 1.63, "vitamin_k_mcg": 57.01, "vitamin_b6_mg": 0.32, "vitamin_b12_mcg": null, "thiamin_mg": 0.28, "riboflavin_mg": 0.23, "niacin_mg": 2.19, "folate_mcg": 110.69, "water_g": 271.19, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Seafood degrades quickly; best consumed immediately.", "duration": "P1D"}, "freezer": {"notes": "Do not freeze after cooking; texture will become rubbery.", "duration": null}, "reheating": "Gently warm in a skillet over low heat just until warm; do not microwave to avoid toughening the scallops.", "does_not_keep": false}', '[{"name": "Wok or Cast Iron Skillet", "required": true, "alternative": "Large stainless steel frying pan"}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Paper towels", "required": true, "alternative": "Clean kitchen cloth"}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Scallops are boiling/steaming instead of searing", "likely_cause": "Scallops were too wet or the pan was overcrowded", "prevention": "Pat scallops extremely dry with paper towels; cook in batches if pan is small", "fix": "Remove liquid, add oil, increase heat, but texture may be compromised"}, {"symptom": "Sauce is too thick or gloopy", "likely_cause": "Too much cornstarch or heat was too high during reduction", "prevention": "Measure starch precisely", "fix": "Add 15ml of water or stock to thin it out"}]', '["Always buy ''dry'' scallops if possible. ''Wet'' scallops are treated with phosphates (STP) that cause them to absorb water, making them impossible to sear properly.", "If your asparagus spears are very thick, slice them on a steep bias to increase surface area and reduce cooking time.", "Prep everything before you turn on the heat. Stir-frying happens too fast to chop ingredients while cooking.", "The residual heat in the sauce will finish cooking the scallops. Do not leave them in the pan too long after combining or they will become rubbery."]', '"This dish draws from Cantonese wok techniques (stir-frying) which emphasizes ''wok hei'' or the ''breath of the wok''\u2014adding a smoky complexity to fresh ingredients. Scallops symbolize new horizons and opening up to good fortune in Chinese culture."', 257.36);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('738f5f35-1f2e-427e-bc0d-be72f5bc6ff3', 'Beef Carpaccio with Shallot-Anchovy Vinaigrette', 'Paper-thin slices of raw beef tenderloin dressed in a piquant vinaigrette of red wine vinegar, minced shallots, and anchovies. Topped with crisp shaved fennel, peppery arugula, salty capers, and shards of Parmesan for a luxurious, textural appetizer.', 'appetizer', 'Italian', 'Intermediate', '["beef", "appetizer", "italian", "raw", "summer", "fancy", "gluten-free", "keto"]', '[{"group_name": "Beef", "items": [{"name": "beef tenderloin", "quantity": 320, "unit": "g", "preparation": "center cut, trimmed", "notes": "Must be very fresh, high-quality beef suitable for raw consumption", "substitutions": [], "ingredient_id": "334395ff-58e3-42c0-93c0-e0b9e83a369b", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vinaigrette", "items": [{"name": "shallot", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "approx. 20g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "anchovy fillets", "quantity": 3, "unit": null, "preparation": "minced to a paste", "notes": "approx. 10g, oil-packed", "substitutions": [], "ingredient_id": "cfdad407-c486-4fcc-9e47-7dd4cb32277c", "nutrition_source": "USDA FoodData Central"}, {"name": "red wine vinegar", "quantity": 20, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "9e1b7e74-fdcb-4836-8349-4f7ad86d62df", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 5, "unit": "g", "preparation": null, "notes": "optional, helps emulsion", "substitutions": [], "ingredient_id": "3e25e626-c9b4-4b62-9d08-7c650bcb3d2b", "nutrition_source": "Aggregated Public Data"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Salad & Garnish", "items": [{"name": "fennel bulb", "quantity": 100, "unit": "g", "preparation": "shaved paper thin", "notes": null, "substitutions": [], "ingredient_id": "a42d03de-0a8a-4a75-8299-5cf01d43b425", "nutrition_source": "USDA FoodData Central"}, {"name": "baby arugula", "quantity": 60, "unit": "g", "preparation": "washed and dried", "notes": null, "substitutions": [], "ingredient_id": "5cd3639d-c908-4325-8962-18beeabb26ee", "nutrition_source": "USDA FoodData Central"}, {"name": "capers", "quantity": 15, "unit": "g", "preparation": "drained", "notes": null, "substitutions": [], "ingredient_id": "e7301d2c-b906-4ef8-917e-787be0b25880", "nutrition_source": "USDA FoodData Central"}, {"name": "parmesan cheese", "quantity": 30, "unit": "g", "preparation": "shaved into ribbons", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon wedges", "quantity": 4, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Tightly wrap the beef tenderloin in plastic wrap and place it in the freezer for 45 minutes to 1 hour. This firms the meat, making it significantly easier to slice thinly.", "structured": {"action": "FREEZE", "temperature": {"celsius": -18, "fahrenheit": 0}, "duration": "PT45M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "While the beef chills, prepare the vinaigrette. In a small bowl, whisk together the minced shallot, anchovy paste, red wine vinegar, and Dijon mustard. Slowly drizzle in the olive oil while whisking constantly to emulsify. Season with black pepper. (Salt is likely unnecessary due to anchovies).", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Shave the fennel bulb as thinly as possible using a mandoline or sharp knife. Place the shavings in a bowl of ice water for 10 minutes to make them extra crisp and curl slightly, then drain and pat dry thoroughly.", "structured": {"action": "SLICE", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": ["If you don''t have a mandoline, use a vegetable peeler to create thin ribbons."]}, {"step_number": 4, "phase": "cook", "text": "Remove beef from freezer. Using a very sharp knife, slice the beef across the grain as thinly as possible (aim for 2-3mm).", "structured": {"action": "SLICE", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "To achieve the classic paper-thin texture, place each slice of beef between two sheets of plastic wrap. Gently pound with the flat side of a meat mallet or the bottom of a heavy pan until the meat is translucent and doubled in surface area.", "structured": {"action": "POUND", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": ["Be gentle; you want to thin the meat, not tear it."]}, {"step_number": 6, "phase": "assemble", "text": "Arrange the pounded beef slices on four chilled serving plates, covering the surface in a single layer without overlapping too much.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "In a mixing bowl, lightly toss the arugula and shaved fennel with half of the vinaigrette. Pile this salad in the center of the beef.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Drizzle the remaining vinaigrette directly over the exposed beef. Scatter capers and shaved Parmesan over the dish. Serve immediately with lemon wedges if desired.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT45M", "total_time": "PT1H10M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 140}', '{"flags": ["Gluten-Free", "Low-Carb", "Keto", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": ["Pregnant women (raw meat)", "Immunocompromised individuals (raw meat)", "Infants (raw meat)"]}', '{"per_serving": {"calories": 298.14, "protein_g": 21.22, "carbohydrates_g": 4.54, "fat_g": 22.17, "saturated_fat_g": 5.21, "trans_fat_g": 0.1, "monounsaturated_fat_g": 12.95, "polyunsaturated_fat_g": 1.93, "fiber_g": 1.59, "sugar_g": 1.92, "sodium_mg": 258.84, "cholesterol_mg": 51.5, "potassium_mg": 495.93, "calcium_mg": 138.49, "iron_mg": 2.66, "magnesium_mg": 38.1, "phosphorus_mg": 246.55, "zinc_mg": 2.28, "vitamin_a_mcg": 52.95, "vitamin_c_mg": 9.81, "vitamin_d_mcg": 0.12, "vitamin_e_mg": 2.92, "vitamin_k_mcg": 42.38, "vitamin_b6_mg": 0.27, "vitamin_b12_mcg": 1.52, "thiamin_mg": 0.06, "riboflavin_mg": 0.15, "niacin_mg": 3.51, "folate_mcg": 25.24, "water_g": 114.54, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best consumed immediately. Raw meat oxidizes and loses texture quickly.", "duration": "P1D"}, "freezer": {"notes": "Do not refreeze thawed raw meat intended for raw consumption.", "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Chef''s knife", "required": true, "alternative": "Slicing knife"}, {"name": "Plastic wrap", "required": true, "alternative": null}, {"name": "Meat mallet", "required": true, "alternative": "Heavy bottomed sauce pan"}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Mandoline slicer", "required": false, "alternative": "Vegetable peeler"}]', '[{"symptom": "Beef tears while slicing", "likely_cause": "Knife is dull or meat is too warm", "prevention": "Sharpen knife before starting and ensure meat is partially frozen", "fix": "Freeze for another 15 minutes; slice slightly thicker and rely on the pounding step to thin it out"}, {"symptom": "Dish tastes too salty", "likely_cause": "Combination of anchovies, capers, and parmesan", "prevention": "Do not add salt to the vinaigrette; rinse capers if they are salt-packed", "fix": "Add a squeeze of fresh lemon juice or more oil to cut the saltiness"}]', '["Safety first: Inform your butcher you intend to eat the beef raw (carpaccio). They can often provide a trimmed piece from the center of the tenderloin.", "Chill your plates in the refrigerator for 20 minutes before serving; this keeps the fat in the beef firm and pleasant on the palate.", "For the Parmesan, use a vegetable peeler on a block of Parmigiano-Reggiano to get nice, wide curls rather than grated dust."]', '"Invented in 1950 by Giuseppe Cipriani at Harry''s Bar in Venice, Carpaccio was named after the Venetian painter Vittore Carpaccio, whose works featured the characteristic deep red and white colors found in the dish. Originally served with a mayo-based sauce, this vinaigrette variation offers a lighter, brighter acid profile."', 298.14);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('7393c4fb-0ce6-4d14-a7fe-cf0b6b28821e', 'Zesty Thai-Style Marinated Squid Salad', 'A vibrant and refreshing salad featuring tender poached squid tossed in a spicy, tart dressing infused with lemongrass, ginger, and fresh herbs. The crisp vegetables and bright citrus flavors make this a perfect light appetizer or low-calorie meal.', 'salad', 'Thai', 'Intermediate', '["cilantro", "ginger", "green pepper", "iceberg lettuce", "lemon juice", "lemongrass", "lime juice", "red bell pepper", "seafood", "squid", "weeknight", "appetizer", "low calorie", "low-fat"]', '[{"group_name": "Squid", "items": [{"name": "fresh squid tubes", "quantity": 400, "unit": "g", "preparation": "cleaned", "notes": "tubes only, or mix of tubes and tentacles", "substitutions": [], "ingredient_id": "e126ab3d-72fc-463a-a50c-461c65ccdf4d", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 2000, "unit": "ml", "preparation": "boiling", "notes": "for blanching", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Vegetables & Aromatics", "items": [{"name": "iceberg lettuce", "quantity": 150, "unit": "g", "preparation": "torn or shredded", "notes": "crisp leaves", "substitutions": [], "ingredient_id": "e869ed52-458f-4fc2-967a-2f8ddb0bd9f3", "nutrition_source": "USDA FoodData Central"}, {"name": "red bell pepper", "quantity": 80, "unit": "g", "preparation": "julienned", "notes": "approx half a pepper", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "USDA FoodData Central"}, {"name": "green bell pepper", "quantity": 80, "unit": "g", "preparation": "julienned", "notes": "approx half a pepper", "substitutions": [], "ingredient_id": "627afa21-0392-4082-ab38-0f20446e190e", "nutrition_source": "Aggregated Public Data"}, {"name": "lemongrass", "quantity": 1, "unit": null, "preparation": "thinly sliced", "notes": "approx 15g, bottom white part only", "substitutions": [], "ingredient_id": "6dde667b-d122-48d9-a70f-a4f820fc5bd5", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 15, "unit": "g", "preparation": "julienned or minced", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 15, "unit": "g", "preparation": "roughly chopped", "notes": "leaves and tender stems", "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "shallot", "quantity": 30, "unit": "g", "preparation": "thinly sliced", "notes": null, "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Zesty Dressing", "items": [{"name": "lime juice", "quantity": 45, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "fish sauce", "quantity": 45, "unit": "ml", "preparation": null, "notes": "check for GF certification if needed", "substitutions": [], "ingredient_id": "95a9a747-50ee-4be0-84be-0dfc96111e2a", "nutrition_source": "Aggregated Public Data"}, {"name": "palm sugar", "quantity": 15, "unit": "g", "preparation": "grated", "notes": "or brown sugar", "substitutions": ["brown sugar", "white sugar", "honey"], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "bird''s eye chili", "quantity": 1, "unit": null, "preparation": "finely chopped", "notes": "adjust to taste", "substitutions": [], "ingredient_id": "e40b2f32-1599-4b72-a829-b858329933e8", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the squid by slicing the tubes open to form flat sheets. Use a sharp knife to lightly score the inside surface in a crosshatch (diamond) pattern without cutting all the way through. Slice into bite-sized rectangular pieces (approx 3x5 cm).", "structured": {"action": "SCORE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Diamond pattern visible on flesh", "tactile": null}}, "tips": ["Scoring helps the dressing cling to the squid and ensures it curls up beautifully when cooked."]}, {"step_number": 2, "phase": "prep", "text": "Bring a large pot of water to a rolling boil. Prepare an ice bath nearby by filling a bowl with cold water and ice.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Blanch the squid in the boiling water for 30 to 60 seconds. Remove immediately with a spider strainer as soon as the pieces curl up and turn opaque white.", "structured": {"action": "BLANCH", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT45S", "doneness_cues": {"visual": "Squid curls tightly and turns opaque white", "tactile": "Firm but tender"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Immediately plunge the cooked squid into the ice bath to stop the cooking process. Let sit for 2 minutes, then drain thoroughly and pat dry.", "structured": {"action": "COOL", "temperature": {"celsius": 0, "fahrenheit": 32}, "duration": "PT2M", "doneness_cues": null}, "tips": ["Residual heat will make the squid rubbery if not shocked in ice water immediately."]}, {"step_number": 5, "phase": "assemble", "text": "In a large mixing bowl, whisk together the lime juice, lemon juice, fish sauce, palm sugar, and chopped chili until the sugar is fully dissolved.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Add the drained squid, sliced lemongrass, ginger, shallot, red bell pepper, green bell pepper, and half the cilantro to the dressing bowl. Toss well to combine.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Arrange the torn iceberg lettuce on a serving platter. Mound the marinated squid salad on top and garnish with the remaining cilantro. Serve immediately.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT5M", "total_time": "PT30M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 280}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Nut-Free", "Low-Fat", "Low-Carb", "Paleo"], "not_suitable_for": ["Shellfish allergy sufferers (due to fish sauce/squid cross-reactivity)"]}', '{"per_serving": {"calories": 296.06, "protein_g": 35.13, "carbohydrates_g": 31.64, "fat_g": 3.24, "saturated_fat_g": 0.81, "trans_fat_g": null, "monounsaturated_fat_g": 0.25, "polyunsaturated_fat_g": 1.18, "fiber_g": 3.58, "sugar_g": 13.91, "sodium_mg": 1156.21, "cholesterol_mg": 466, "potassium_mg": 1041.16, "calcium_mg": 125.39, "iron_mg": 5.59, "magnesium_mg": 132.68, "phosphorus_mg": 509.88, "zinc_mg": 3.7, "vitamin_a_mcg": 273.71, "vitamin_c_mg": 151.84, "vitamin_d_mcg": null, "vitamin_e_mg": 3.25, "vitamin_k_mcg": 20.3, "vitamin_b6_mg": 0.34, "vitamin_b12_mcg": 2.6, "thiamin_mg": 0.11, "riboflavin_mg": 0.89, "niacin_mg": 4.96, "folate_mcg": 59.83, "water_g": 1311.03, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten fresh; acids will toughen squid over time.", "duration": "P1D"}, "freezer": {"notes": "Do not freeze after dressing.", "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Ice bath bowl", "required": true, "alternative": "Bowl of very cold water"}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Spider strainer or slotted spoon", "required": true, "alternative": null}]', '[{"symptom": "Squid is rubbery and tough", "likely_cause": "Overcooked during blanching", "prevention": "Cook for no longer than 60 seconds; remove immediately when curled and opaque", "fix": "Cannot be fixed, but slicing very thinly may help palatability"}, {"symptom": "Salad tastes watery", "likely_cause": "Squid was not drained properly after the ice bath", "prevention": "Pat squid completely dry with paper towels before adding to dressing", "fix": "Add more fish sauce and lime juice to re-balance flavor"}]', '["To clean lemongrass, peel away the tough outer layers until you reach the pale, tender center before slicing.", "If you cannot find palm sugar, brown sugar adds a nice caramel depth that complements the fish sauce better than white sugar.", "For maximum flavor penetration, you can let the squid sit in the dressing for 10 minutes before adding the fresh herbs and lettuce, but don''t wait too long or the acids will toughen the meat."]', '"Inspired by the Thai dish ''Yam Pla Muek'', this salad balances the four pillars of Thai cuisine: sour (lime), salty (fish sauce), spicy (chili), and sweet (sugar). It is typically enjoyed as an appetizer or part of a shared meal with rice to offset the intense flavors."', 296.06);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('73d53443-cd8d-40e8-934b-2306643b4cbe', 'Spaghetti with Mackerel, Blistered Tomatoes & Lemon Crumbs', 'A rustic, Sicilian-inspired pasta dish balancing rich, oily fish with the sweetness of jammy, oven-roasted tomatoes. Finished with ''pangrattato''—crispy, spicy breadcrumbs that add essential texture and brightness.', 'dinner', 'Italian', 'Easy', '["pasta", "fish", "quick", "easy", "spaghetti", "mackerel", "italian", "pescatarian"]', '[{"group_name": "Roasted Tomatoes", "items": [{"name": "cherry tomatoes", "quantity": 300, "unit": "g", "preparation": "whole", "notes": "on the vine if available for flavor", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "smashed", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "extra virgin", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Lemon-Chilli Breadcrumbs (Pangrattato)", "items": [{"name": "panko breadcrumbs", "quantity": 40, "unit": "g", "preparation": null, "notes": "or coarse fresh breadcrumbs", "substitutions": [], "ingredient_id": "92441189-214a-4a8a-9cfc-dd578fe0d179", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "dried chilli flakes", "quantity": 2, "unit": "g", "preparation": null, "notes": "adjust to heat preference", "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": "freshly grated", "notes": "zest of 1 lemon", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pasta & Assembly", "items": [{"name": "spaghetti", "quantity": 200, "unit": "g", "preparation": null, "notes": "or linguine", "substitutions": [], "ingredient_id": "c3d19c9d-f603-44a1-b9e4-cbff540218ef", "nutrition_source": "USDA FoodData Central"}, {"name": "tinned mackerel fillets in oil", "quantity": 125, "unit": "g", "preparation": "drained", "notes": "reserve oil if high quality", "substitutions": [], "ingredient_id": "46c8b04b-7073-4d2b-b1cb-616b834e4e36", "nutrition_source": "USDA FoodData Central"}, {"name": "parsley", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 220\u00b0C (430\u00b0F). Arrange the cherry tomatoes and smashed garlic on a baking tray. Drizzle with 15ml olive oil and season generously with salt.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Roast the tomatoes for 15-18 minutes until the skins burst and some charring appears. This mimics slow-roasting in a fraction of the time.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT15M", "doneness_cues": {"visual": "Skins burst and slightly charred", "tactile": "Soft and yielding"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "While tomatoes roast, bring a large pot of salted water to a boil. Add spaghetti and cook until al dente (usually 1-2 minutes less than package instructions).", "structured": {"action": "BOIL", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Al dente - slight resistance in center"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Heat 15ml olive oil in a small frying pan over medium heat. Add breadcrumbs and toast, stirring constantly, until golden brown. Remove from heat immediately and stir in lemon zest, chilli flakes, and a pinch of salt.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown", "tactile": "Crispy"}}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Drain the pasta, reserving 60ml (approx. 1/4 cup) of the starchy pasta water. Return pasta to the pot.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Add the roasted tomatoes (including all tray juices) and the mackerel fillets to the pasta. Gently toss to combine, adding reserved pasta water splash by splash to create a light glossy coating. The mackerel should break into bite-sized chunks.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Glossy sauce coating noodles", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Stir in the chopped parsley. Plate immediately and top generously with the lemon-chilli breadcrumbs.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT15M", "total_time": "PT30M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 350}', '{"flags": ["Pescatarian", "Dairy-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 716.77, "protein_g": 32, "carbohydrates_g": 96.93, "fat_g": 22.02, "saturated_fat_g": 3.84, "trans_fat_g": null, "monounsaturated_fat_g": 12.76, "polyunsaturated_fat_g": 3.68, "fiber_g": 7.44, "sugar_g": 9.96, "sodium_mg": 817.13, "cholesterol_mg": 49.38, "potassium_mg": 801.17, "calcium_mg": 239.77, "iron_mg": 6.58, "magnesium_mg": 106.14, "phosphorus_mg": 456.94, "zinc_mg": 2.73, "vitamin_a_mcg": 117.12, "vitamin_c_mg": 29.77, "vitamin_d_mcg": 4.57, "vitamin_e_mg": 3.36, "vitamin_k_mcg": 93.63, "vitamin_b6_mg": 0.36, "vitamin_b12_mcg": 4.41, "thiamin_mg": 1.13, "riboflavin_mg": 0.63, "niacin_mg": 12.57, "folate_mcg": 269.71, "water_g": 62.49, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Breadcrumbs will lose crunch; store separately if possible.", "duration": "P2D"}, "freezer": {"notes": "Not recommended; texture of fish and pasta degrades.", "duration": null}, "reheating": "Gently warm in a pan with a splash of water; add fresh breadcrumbs after heating.", "does_not_keep": false}', '[{"name": "Large stockpot", "required": true, "alternative": null}, {"name": "Baking sheet or roasting tray", "required": true, "alternative": null}, {"name": "Small frying pan", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "Pasta dish feels dry", "likely_cause": "Tomatoes didn''t release enough juice or pasta absorbed moisture", "prevention": "Always reserve pasta water before draining", "fix": "Stir in a tablespoon of hot water or extra olive oil and toss vigorously"}, {"symptom": "Breadcrumbs are burnt", "likely_cause": "Pan was too hot or crumbs were left unattended", "prevention": "Watch breadcrumbs constantly; they burn in seconds", "fix": "Discard and start over; burnt garlic/bread flavor cannot be masked"}]', '["If the mackerel is packed in high-quality extra virgin olive oil, use that oil to roast the tomatoes for extra flavor.", "Do not add the lemon zest to the hot pan while the heat is on; the delicate oils will burn. Add it off-heat.", "For a true ''slow-roasted'' texture in a rush, squash the tomatoes flat with a fork halfway through roasting to release their juices faster."]', '"This dish draws heavily from Sicilian ''cucina povera'' (peasant cooking), specifically ''Pasta con le Sarde''. Since fresh sardines were seasonal, preserved fish and stale bread (mollica) were used as clever, shelf-stable substitutes to create depth and texture."', 716.77);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('73f06820-acf1-4573-b91e-44058af609de', 'Kashmiri Lamb Rogan Josh with Bombay Potatoes', 'A rich, aromatic Kashmiri lamb stew featuring tender shoulder meat braised in a vibrant red sauce of yogurt, Kashmiri chilies, and fennel. Paired with Bombay Potatoes—crispy, golden cubes spiced with turmeric, mustard seeds, and fresh coriander.', 'dinner', 'Indian', 'Intermediate', '["lamb", "indian", "spicy", "stew", "potatoes", "main course", "curry", "comfort food"]', '[{"group_name": "Lamb Rogan Josh Base", "items": [{"name": "lamb shoulder", "quantity": 800, "unit": "g", "preparation": "diced into 3cm cubes", "notes": "Shoulder is preferred for fat content and tenderness", "substitutions": [], "ingredient_id": "27672021-dc31-45a5-9ce8-f08dbbae93b4", "nutrition_source": "Aggregated Public Data"}, {"name": "ghee", "quantity": 45, "unit": "g", "preparation": "solid", "notes": "Can substitute vegetable oil", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "onion", "quantity": 2, "unit": null, "preparation": "finely sliced", "notes": "approx 300g total", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "minced", "notes": "approx 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "ginger root", "quantity": 15, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "plain yogurt", "quantity": 200, "unit": "g", "preparation": "whisked", "notes": "Full fat Greek style works best", "substitutions": [], "ingredient_id": "9fe1e178-d1e1-4483-ac91-df893649cbc3", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Rogan Josh Spices", "items": [{"name": "kashmiri chili powder", "quantity": 15, "unit": "g", "preparation": null, "notes": "Mild heat, vibrant red color. Substitute paprika mixed with cayenne if unavailable.", "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "ground fennel seeds", "quantity": 8, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "4251d6cd-aa2f-41d7-ad78-02d98bfbaeea", "nutrition_source": "USDA FoodData Central"}, {"name": "ground coriander", "quantity": 8, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "green cardamom pods", "quantity": 6, "unit": null, "preparation": "slightly crushed", "notes": null, "substitutions": [], "ingredient_id": "c56f6cd8-882c-487c-956f-3a91ee1fec07", "nutrition_source": "USDA FoodData Central"}, {"name": "cinnamon stick", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 5cm length", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "cloves", "quantity": 4, "unit": null, "preparation": "whole", "notes": null, "substitutions": [], "ingredient_id": "7b3bf68a-3ae9-4dad-91f4-6c7a14ec5e0e", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 400, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Bombay Potatoes", "items": [{"name": "baby potatoes", "quantity": 600, "unit": "g", "preparation": "halved", "notes": "Waxy variety preferred", "substitutions": [], "ingredient_id": "5bf06478-4785-465e-9842-f70a24e22054", "nutrition_source": "USDA FoodData Central"}, {"name": "mustard seeds", "quantity": 5, "unit": "g", "preparation": "black or brown", "notes": null, "substitutions": [], "ingredient_id": "69e2b7a1-7252-486e-841e-51655b028a97", "nutrition_source": "Aggregated Public Data"}, {"name": "turmeric powder", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "cumin seeds", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "green chili", "quantity": 1, "unit": null, "preparation": "finely sliced", "notes": "approx 10g", "substitutions": [], "ingredient_id": "e40b2f32-1599-4b72-a829-b858329933e8", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh coriander", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": "Leaves and tender stems", "substitutions": [], "ingredient_id": "8c7693be-b538-445c-80f9-3d5bf4c6dcc0", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Heat ghee in a Dutch oven over medium-high heat. Add cinnamon stick, cloves, and cardamom pods, frying for 30 seconds until fragrant.", "structured": {"action": "TEMPER", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add sliced onions and saut\u00e9 for 10-12 minutes until they turn a deep golden brown.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT12M", "doneness_cues": {"visual": "Deep golden brown color", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Stir in garlic and ginger, cooking for 1 minute. Add the diced lamb and sear for 5-7 minutes, turning occasionally until browned on all sides.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Meat browned, not grey", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Reduce heat to low. Stir in Kashmiri chili powder, ground fennel, and coriander. Immediately add the whisked yogurt one tablespoon at a time, stirring vigorously to prevent curdling.", "structured": {"action": "EMULSIFY", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour in water, season with salt (approx 5g), and bring to a gentle simmer. Cover and cook on low heat for 80-90 minutes until lamb is tender.", "structured": {"action": "BRAISE", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT1H30M", "doneness_cues": {"visual": null, "tactile": "Fork-tender meat"}}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "While lamb cooks, place potatoes in a saucepan, cover with cold water and a pinch of salt. Boil for 10-12 minutes until just tender but not falling apart. Drain and let steam dry.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT12M", "doneness_cues": {"visual": null, "tactile": "Knife pierces easily with slight resistance"}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Heat vegetable oil in a large skillet over medium heat. Add mustard seeds and cumin seeds. When they crackle, add green chili and turmeric.", "structured": {"action": "TEMPER", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Add the boiled potatoes to the skillet. Toss gently to coat in spices and fry for 5-8 minutes until edges are crisp and golden.", "structured": {"action": "FRY", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Golden crust on edges", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Fold fresh coriander into the potatoes. Adjust salt to taste. Serve the hot lamb curry alongside the spiced potatoes.", "structured": {"action": "SERVE", "temperature": {"celsius": 65, "fahrenheit": 149}, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT1H30M", "total_time": "PT2H15M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Gluten-Free", "Egg-Free", "Peanut-Free", "Soy-Free", "Low-Carb"], "not_suitable_for": []}', '{"per_serving": {"calories": 650.75, "protein_g": 48.25, "carbohydrates_g": 38.6, "fat_g": 34.94, "saturated_fat_g": 11.35, "trans_fat_g": null, "monounsaturated_fat_g": 3.64, "polyunsaturated_fat_g": 0.88, "fiber_g": 9.78, "sugar_g": 7.3, "sodium_mg": 213.52, "cholesterol_mg": 27.19, "potassium_mg": 1279.03, "calcium_mg": 247.32, "iron_mg": 9.37, "magnesium_mg": 96.76, "phosphorus_mg": 304.94, "zinc_mg": 4.53, "vitamin_a_mcg": 395.95, "vitamin_c_mg": 28.97, "vitamin_d_mcg": null, "vitamin_e_mg": 1.88, "vitamin_k_mcg": 6.12, "vitamin_b6_mg": 0.62, "vitamin_b12_mcg": 0.3, "thiamin_mg": 0.13, "riboflavin_mg": 0.25, "niacin_mg": 2.44, "folate_mcg": 47.64, "water_g": 345.55, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors deepen significantly the next day.", "duration": "P3D"}, "freezer": {"notes": "Freeze the lamb stew only; potatoes texture may degrade upon thawing.", "duration": "P2M"}, "reheating": "Reheat lamb gently on the stove. Re-crisp potatoes in a hot skillet.", "does_not_keep": false}', '[{"name": "Dutch oven or heavy-bottomed pot", "required": true, "alternative": null}, {"name": "Large saucepan", "required": true, "alternative": null}, {"name": "Large skillet or frying pan", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Yogurt sauce has curdled/split", "likely_cause": "Heat was too high or yogurt added too quickly", "prevention": "Temper yogurt by mixing a spoon of hot sauce into it before adding to pot, or add starch", "fix": "Remove meat, blitz sauce with an immersion blender to re-emulsify, return meat"}]', '["For the deepest red color without excessive heat, use authentic Kashmiri chili powder. If using standard chili powder, reduce quantity by half and add paprika for color.", "Allowing the boiled potatoes to steam dry completely before frying is crucial for getting crispy edges; wet potatoes will just steam in the skillet.", "The ''Rogan'' (oil) rising to the top of the curry is a sign of a well-cooked dish; do not skim this off as it carries the flavor essence.", "If the lamb is tough after the allotted time, add a splash more water and continue simmering. Shoulder cuts vary in connective tissue density."]', '"Rogan Josh is a signature dish of Kashmiri cuisine (Wazwan), traditionally owing its vibrant red hue to dried cockscomb flowers or Kashmiri chilies. It reflects the heavy Persian influence on North Indian cooking, while Bombay Potatoes (Bombay Aloo) are a staple British-Indian restaurant side dish, showcasing how humble tubers can be elevated with simple tempering techniques."', 650.75);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('758e48f9-d3df-4c2a-badb-a6f59deda92a', 'Classic Tex-Mex Beef Tacos', 'Flavor-dense ground beef simmered in a robust, homemade spice blend, nestled in warm tortillas and topped with sharp cheddar and zesty salsa. A nostalgic classic elevated by proper blooming of spices and textural balance.', 'dinner', 'Tex-Mex', 'Easy', '["tex-mex", "family friendly", "quick dinner", "ground beef", "gluten-free option"]', '[{"group_name": "Beef Filling", "items": [{"name": "lean ground beef", "quantity": 500, "unit": "g", "preparation": "85/15 or 90/10 ratio preferred", "notes": null, "substitutions": [], "ingredient_id": "c61d5296-4ece-4642-a33b-7277a3b2fa04", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "07bf825b-2bab-470e-95c2-1b0e31a50c98", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "tomato paste", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "1a1bddc5-66c3-4f44-bb24-72b8ac828ca6", "nutrition_source": "Aggregated Public Data"}, {"name": "beef broth or water", "quantity": 120, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f236daf6-7cc7-47be-b10a-356b70a3bf44", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Spice Blend", "items": [{"name": "chili powder", "quantity": 8, "unit": "g", "preparation": null, "notes": "mild American style", "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 1, "unit": "g", "preparation": "crushed", "notes": null, "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 4, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f0a6986f-fb44-4088-b9de-ccfa1558f88c", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Assembly", "items": [{"name": "corn tortillas", "quantity": 12, "unit": null, "preparation": "warmed", "notes": "15cm diameter", "substitutions": [], "ingredient_id": "ff16cf84-9e7e-4010-903b-84c52fb3866c", "nutrition_source": "Aggregated Public Data"}, {"name": "sharp cheddar cheese", "quantity": 120, "unit": "g", "preparation": "freshly shredded", "notes": null, "substitutions": [], "ingredient_id": "c5948fd5-2804-4d18-98e4-da7884e00680", "nutrition_source": "USDA FoodData Central"}, {"name": "salsa roja", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "60e4a68c-3351-42d6-9891-3dbcf336cb3e", "nutrition_source": "USDA FoodData Central"}, {"name": "iceberg lettuce", "quantity": 100, "unit": "g", "preparation": "shredded", "notes": null, "substitutions": [], "ingredient_id": "03c4b727-ca92-4632-a796-88bde7ed11b7", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Heat a large skillet over medium-high heat. Add the ground beef and cook, breaking it apart vigorously with a wooden spoon, until mostly browned, about 5-6 minutes. Ensure internal temperature reaches at least 71\u00b0C/160\u00b0F.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT6M", "doneness_cues": {"visual": "Beef is browned with no pink remaining", "tactile": "Meat is crumbled into small, even pieces"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add the diced onion to the beef fat in the pan. Saut\u00e9 for 3-4 minutes until softened and translucent.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Onions are translucent", "tactile": null}}, "tips": ["If using very lean beef (95/5), add 5ml of oil before onions to prevent sticking."]}, {"step_number": 3, "phase": "cook", "text": "Stir in the minced garlic, tomato paste, chili powder, cumin, paprika, oregano, salt, and pepper. Cook for 1 minute while stirring constantly to bloom the spices and caramelize the tomato paste slightly.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Spices are fragrant and tomato paste darkens slightly", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour in the beef broth (or water). Reduce heat to low and simmer uncovered for 3-5 minutes, or until the liquid has reduced to a glossy sauce that clings to the meat without being runny.", "structured": {"action": "REDUCE", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT5M", "doneness_cues": {"visual": "Mixture is moist but not soupy; trail remains when spoon is dragged through", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "While the meat simmers, warm the tortillas. Heat a separate dry skillet over high heat and toast tortillas for 15-20 seconds per side until pliable and slightly charred.", "structured": {"action": "TOAST", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": {"visual": null, "tactile": "Tortillas are flexible and warm"}}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Assemble the tacos by spooning the beef mixture into the warm tortillas. Top immediately with shredded cheese, followed by salsa and lettuce.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT5M", "total_time": "PT30M", "overnight_required": false, "yields": "12 tacos", "yield_count": 4, "serving_size_g": 320}', '{"flags": ["Gluten-Free", "Nut-Free", "Egg-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 671.44, "protein_g": 32.56, "carbohydrates_g": 78.37, "fat_g": 27.43, "saturated_fat_g": 10.72, "trans_fat_g": 1.01, "monounsaturated_fat_g": 10.58, "polyunsaturated_fat_g": 2.51, "fiber_g": 10.29, "sugar_g": 12.49, "sodium_mg": 9632.36, "cholesterol_mg": 59.4, "potassium_mg": 1131.28, "calcium_mg": 313.03, "iron_mg": 6.07, "magnesium_mg": 140.65, "phosphorus_mg": 694.75, "zinc_mg": 4.37, "vitamin_a_mcg": 175.84, "vitamin_c_mg": 8.27, "vitamin_d_mcg": 0.09, "vitamin_e_mg": 2.77, "vitamin_k_mcg": 41.92, "vitamin_b6_mg": 0.42, "vitamin_b12_mcg": 2.26, "thiamin_mg": 0.34, "riboflavin_mg": 0.47, "niacin_mg": 6.54, "folate_mcg": 72.64, "water_g": 143.72, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store meat filling and toppings in separate airtight containers.", "duration": "P3D"}, "freezer": {"notes": "Beef filling freezes excellently; thaw overnight in refrigerator before reheating.", "duration": "P3M"}, "reheating": "Reheat beef in a skillet over medium heat with a splash of water to restore moisture.", "does_not_keep": false}', '[{"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Wooden spoon or heat-proof spatula", "required": true, "alternative": null}]', '[{"symptom": "Taco filling is too watery/runny", "likely_cause": "Liquid was not reduced enough or onions released excess water", "prevention": "Allow the mixture to simmer uncovered for longer", "fix": "Increase heat slightly and cook for an additional 2-3 minutes to evaporate moisture"}, {"symptom": "Meat is dry or gritty", "likely_cause": "Overcooked lean beef without enough added moisture", "prevention": "Do not drain all fat if using lean meat; ensure broth is added", "fix": "Stir in 15-30ml of warm water or broth and cover for 1 minute"}]', '["Blooming spices (cooking them briefly in fat) before adding liquid releases fat-soluble flavor compounds, creating a much deeper flavor profile than simply boiling them.", "Shred your own cheese from a block. Pre-shredded cheese contains anti-caking agents (cellulose) that prevent it from melting smoothly into the hot beef.", "For a ''hard shell'' experience without the stale box taste, shallow fry the corn tortillas in 1cm of oil, folding them over with tongs as they crisp.", "Leftover filling makes an excellent base for nachos or a taco salad bowl the next day."]', '"While tacos have ancient indigenous roots in Mexico, this specific iteration\u2014ground beef, cheddar cheese, and cumin-heavy spice blends\u2014evolved in the early 20th century in the American Southwest (Texas and California). It became a staple of ''Tex-Mex'' cuisine, democratizing the dish for home cooks across North America."', 671.44);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('76d4edbd-1b5f-4909-bb34-dbae8c1473f4', 'Golden Spiced Gingerbread Cake', 'A refined take on traditional gingerbread, offering a surprisingly light and tender crumb while retaining the deep, warming notes of treacle and ginger. Finished with a zesty lemon glaze that cuts through the spice, making it an ideal centerpiece for afternoon tea.', 'dessert', 'British', 'Intermediate', '["cake", "gingerbread", "parkin", "dessert", "bake"]', '[{"group_name": "Dry Ingredients", "items": [{"name": "all-purpose flour", "quantity": 250, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "ground ginger", "quantity": 10, "unit": "g", "preparation": null, "notes": "approx 2 tsp", "substitutions": [], "ingredient_id": "401ddd0b-3597-4b46-bb54-f3bc755048bb", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 5, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cloves", "quantity": 1, "unit": "g", "preparation": null, "notes": "approx 1/4 tsp", "substitutions": [], "ingredient_id": "7b3bf68a-3ae9-4dad-91f4-6c7a14ec5e0e", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 5, "unit": "g", "preparation": null, "notes": "1 tsp; essential for reacting with molasses", "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "1/2 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wet Ingredients", "items": [{"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "room temperature, softened", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "dark brown sugar", "quantity": 100, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "molasses", "quantity": 170, "unit": "g", "preparation": null, "notes": "or black treacle", "substitutions": [], "ingredient_id": "c76e81ce-ce17-4595-b9ff-30c87fb7c285", "nutrition_source": "USDA FoodData Central"}, {"name": "large egg", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 50g, room temperature", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "hot water", "quantity": 240, "unit": "ml", "preparation": "boiling", "notes": "activates the baking soda", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Lemon Glaze", "items": [{"name": "powdered sugar", "quantity": 120, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 30, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 175\u00b0C (350\u00b0F). Grease a 23cm (9-inch) square baking pan and line the bottom with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Whisk together the flour, ginger, cinnamon, cloves, baking soda, and salt in a medium bowl until thoroughly combined.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a large bowl or stand mixer, beat the softened butter and brown sugar together on medium speed until creamy and pale.", "structured": {"action": "CREAM", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the egg and molasses to the butter mixture. Beat until smooth, scraping down the sides of the bowl as needed.", "structured": {"action": "BEAT", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Gradually add the dry ingredients to the wet mixture, mixing on low speed until just combined. The batter will be thick.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Carefully pour the boiling water into the batter while mixing on the lowest speed. Mix only until the water is incorporated and the batter is smooth and thin.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": ["The batter will look very liquid at this stage; this is normal and ensures a moist crumb."]}, {"step_number": 7, "phase": "cook", "text": "Pour the batter into the prepared pan. Bake for 35-40 minutes, or until a toothpick inserted into the center comes out clean and the top springs back when lightly pressed.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT35M", "doneness_cues": {"visual": "Toothpick comes out clean", "tactile": "Springs back when pressed"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Allow the cake to cool in the pan for 10 minutes, then transfer to a wire rack to cool completely.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "While the cake cools, whisk the powdered sugar and lemon juice together in a small bowl until smooth. Drizzle over the cooled cake before slicing.", "structured": {"action": "GLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT45M", "total_time": "PT1H10M", "overnight_required": false, "yields": "12 servings", "yield_count": 12, "serving_size_g": 75}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Gluten-Free diets", "Vegans"]}', '{"per_serving": {"calories": 266.75, "protein_g": 2.87, "carbohydrates_g": 45.83, "fat_g": 8.44, "saturated_fat_g": 5.03, "trans_fat_g": null, "monounsaturated_fat_g": 2.42, "polyunsaturated_fat_g": 0.47, "fiber_g": 0.94, "sugar_g": 28.63, "sodium_mg": 227.35, "cholesterol_mg": 36.1, "potassium_mg": 264.8, "calcium_mg": 50.07, "iron_mg": 1.26, "magnesium_mg": 42.91, "phosphorus_mg": 39.73, "zinc_mg": 0.29, "vitamin_a_mcg": 72.3, "vitamin_c_mg": 0.99, "vitamin_d_mcg": 0.08, "vitamin_e_mg": 0.3, "vitamin_k_mcg": 1, "vitamin_b6_mg": 0.12, "vitamin_b12_mcg": 0.05, "thiamin_mg": 0.03, "riboflavin_mg": 0.03, "niacin_mg": 0.5, "folate_mcg": 8.4, "water_g": 32.89, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container to maintain moisture.", "duration": "P5D"}, "freezer": {"notes": "Freeze without the glaze for best results.", "duration": "P3M"}, "reheating": "Serve at room temperature or warm slightly in a microwave for 10 seconds.", "does_not_keep": false}', '[{"name": "Square baking pan (23cm / 9 inch)", "required": true, "alternative": "Round cake tin"}, {"name": "Stand mixer or electric hand mixer", "required": true, "alternative": "Whisk and strong arm"}, {"name": "Sieve", "required": true, "alternative": null}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Wire rack", "required": true, "alternative": null}]', '[{"symptom": "Cake sunk in the middle", "likely_cause": "Oven door was opened too early or underbaked", "prevention": "Do not open the oven door during the first 25 minutes of baking; ensure toothpick test passes", "fix": "Fill the depression with extra glaze or whipped cream; it will still taste delicious"}, {"symptom": "Texture is tough or rubbery", "likely_cause": "Overmixing after adding flour", "prevention": "Mix dry ingredients until just combined before adding the hot water", "fix": "Cannot be fixed"}]', '["The boiling water is the secret weapon here; it blooms the spices and activates the baking soda immediately for a lighter texture.", "For a more intense ''Parkin-style'' flavor without the heaviness, wrap the cooled cake in plastic wrap and let it sit for 24 hours before glazing. The flavors will deepen significantly.", "Use fresh ginger in addition to ground ginger (about 1 tsp grated) if you want a sharper spicy kick."]', '"Gingerbread has been a staple of British baking since the medieval period, originally evolving from preserved ginger imported from the East. While ''Parkin'' traditionally refers to a denser, oat-based cake from Northern England eaten on Guy Fawkes Night, this recipe borrows the flavor profile but uses a sponge method to achieve the light, airy texture favored in modern tea cakes."', 266.75);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('76f81478-69bd-4edc-94e1-339ba05d22f1', 'Mediterranean Tuna and Olive Penne', 'A vibrant, savory pasta dish bringing together the pantry staples of canned tuna and briny Kalamata olives in a rich, garlic-infused tomato sauce. Quick, satisfying, and packed with umami.', 'dinner', 'Italian', 'Easy', '["pastas", "budget", "canned tuna", "farfalle", "kalamata olive", "penne", "spaghetti", "tomato sauce", "dinner", "main course", "quick", "italian", "pantry"]', '[{"group_name": "Pasta", "items": [{"name": "penne pasta", "quantity": 350, "unit": "g", "preparation": "dry", "notes": "Can substitute with Farfalle or Spaghetti", "substitutions": ["farfalle", "fusilli", "spaghetti"], "ingredient_id": "c3d19c9d-f603-44a1-b9e4-cbff540218ef", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 4000, "unit": "ml", "preparation": null, "notes": "for boiling", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt", "quantity": 30, "unit": "g", "preparation": null, "notes": "for pasta water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sauce Base", "items": [{"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx. 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "red chili flakes", "quantity": 2, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Main Components", "items": [{"name": "canned crushed tomatoes", "quantity": 400, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "canned tuna in olive oil", "quantity": 250, "unit": "g", "preparation": "drained", "notes": "approx. 2 standard tins", "substitutions": [], "ingredient_id": "ad194522-be98-46e9-8c73-8822a37cc0a3", "nutrition_source": "Aggregated Public Data"}, {"name": "kalamata olives", "quantity": 80, "unit": "g", "preparation": "pitted and halved", "notes": null, "substitutions": [], "ingredient_id": "d018fb0f-3c49-492f-814a-5a9d81cb522e", "nutrition_source": "Aggregated Public Data"}, {"name": "capers", "quantity": 15, "unit": "g", "preparation": "rinsed", "notes": "optional but recommended for brine", "substitutions": [], "ingredient_id": "e7301d2c-b906-4ef8-917e-787be0b25880", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finish", "items": [{"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste (min 1g)", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Bring a large pot of salted water to a rolling boil (100\u00b0C/212\u00b0F). Add the pasta and cook according to package instructions until al dente.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": {"visual": null, "tactile": "Firm to the bite but cooked through"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "While the pasta cooks, heat olive oil in a large skillet over medium heat. Add the minced garlic and red chili flakes, saut\u00e9ing briefly until fragrant but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Garlic is pale gold", "tactile": "Aromatic"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Pour in the crushed tomatoes. Increase heat to medium-high to bring to a simmer, then reduce heat and let it bubble gently for about 5-7 minutes to thicken slightly.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT7M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Stir in the drained tuna, pitted olives, and capers (if using). Break up larger chunks of tuna with a wooden spoon. Simmer for another 2 minutes to warm everything through.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Reserve 60ml (approx. 1/4 cup) of pasta cooking water, then drain the pasta. Add the pasta directly to the skillet with the sauce. Toss well to coat.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["If the sauce feels too thick or dry, add the reserved pasta water a tablespoon at a time."]}, {"step_number": 6, "phase": "finish", "text": "Remove from heat. Stir in the chopped parsley and season with freshly cracked black pepper. Taste and add salt only if needed (tuna and olives are naturally salty). Serve immediately.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Pescatarian", "Dairy-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 581.18, "protein_g": 35.6, "carbohydrates_g": 72.53, "fat_g": 17.7, "saturated_fat_g": 2.28, "trans_fat_g": null, "monounsaturated_fat_g": 5.65, "polyunsaturated_fat_g": 1.35, "fiber_g": 5.72, "sugar_g": 6.37, "sodium_mg": 3400.05, "cholesterol_mg": null, "potassium_mg": 664.03, "calcium_mg": 81.55, "iron_mg": 4.6, "magnesium_mg": 98.28, "phosphorus_mg": 435.36, "zinc_mg": 2.11, "vitamin_a_mcg": 38.5, "vitamin_c_mg": 18.92, "vitamin_d_mcg": null, "vitamin_e_mg": 1.39, "vitamin_k_mcg": 47.4, "vitamin_b6_mg": 0.19, "vitamin_b12_mcg": null, "thiamin_mg": 0.79, "riboflavin_mg": 0.37, "niacin_mg": 6.41, "folate_mcg": 212.72, "water_g": 1016.28, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. If pasta absorbs too much sauce, add a splash of water when reheating.", "duration": "P3D"}, "freezer": {"notes": "Not recommended as the pasta texture deteriorates.", "duration": null}, "reheating": "Microwave or stovetop with a splash of water to loosen the sauce.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Sauce is too dry", "likely_cause": "Tomatoes reduced too much or pasta absorbed moisture", "prevention": "Lower heat during simmering; reserve pasta water", "fix": "Stir in reserved pasta water or a splash of hot water until creamy"}]', '["Use tuna packed in olive oil rather than water for a richer, less chalky texture.", "Do not add salt to the sauce until the very end; the olives, capers, and canned tuna bring significant sodium.", "For an extra zest, grate a little lemon peel over the finished dish to cut through the richness.", "This dish is a variation of the classic ''Pasta al Tonno'', a staple in Italian pantry cooking."]', '"This dish draws heavily from Southern Italian ''cucina povera'' (peasant cooking), where pantry staples like cured fish and preserved vegetables were transformed into satisfying meals. While similar to the Roman ''Alla Puttanesca'', the focus here is specifically on the tuna, a protein often relied upon when fresh meat or fish was unavailable."', 581.18);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('77617a87-c795-4bc5-8842-c134e1a85318', 'Peanut Butter and Dill Pickle Sandwich', 'A polarizing yet surprisingly harmonious cult classic. The creamy, fatty richness of peanut butter creates a perfect backdrop for the sharp, acidic bite and textural snap of cold dill pickles. The contrast between warm toasted bread and cold, crunchy pickles elevates this simple pantry meal.', 'lunch', 'American', 'Easy', '["american", "sandwiches", "five ingredient", "peanut butter", "pickle", "school lunch", "for one", "lunch", "quick", "vegetarian"]', '[{"group_name": "Sandwich Base", "items": [{"name": "white sandwich bread", "quantity": 2, "unit": null, "preparation": "sliced", "notes": "approx. 60g total; sourdough also works well", "substitutions": [], "ingredient_id": "c4052e66-d9d4-41e7-a365-cd88abcd9202", "nutrition_source": "Aggregated Public Data"}, {"name": "creamy peanut butter", "quantity": 45, "unit": "g", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "c6784b8e-2622-4f15-b962-a521694a1b31", "nutrition_source": "USDA FoodData Central"}, {"name": "dill pickle chips", "quantity": 50, "unit": "g", "preparation": "cold", "notes": "approximately 6-8 slices", "substitutions": [], "ingredient_id": "3df7ea0a-852c-4fcc-aba9-3f7dc38481c1", "nutrition_source": "Aggregated Public Data"}, {"name": "hot sauce", "quantity": 2, "unit": "ml", "preparation": null, "notes": "sriracha or crystal style", "substitutions": [], "ingredient_id": "1d3ad934-930f-42de-83f5-7fc063eda5dd", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Toast the bread slices to a light golden brown. This provides structural integrity and a warm temperature contrast to the cold pickles.", "structured": {"action": "TOAST", "temperature": null, "duration": null, "doneness_cues": {"visual": "Light golden brown", "tactile": "Crisp surface"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Remove the pickle chips from the brine and arrange them on a paper towel. Pat them thoroughly dry to prevent the sandwich from becoming soggy.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "assemble", "text": "Spread half of the peanut butter onto one slice of toast, and the remaining half onto the second slice. Coating both slices creates a hydrophobic moisture barrier against the pickle juice.", "structured": {"action": "SPREAD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Layer the dried pickle chips on top of one peanut butter-coated slice in a single, slightly overlapping layer. Add a dash of hot sauce if using.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Close the sandwich with the second slice of bread, press down gently to adhere, and slice diagonally. Serve immediately.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT5M", "passive_time": "PT0M", "total_time": "PT5M", "overnight_required": false, "yields": "1 sandwich", "yield_count": 1, "serving_size_g": 160}', '{"flags": ["Vegetarian", "Vegan", "Dairy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 448.82, "protein_g": 15.61, "carbohydrates_g": 44.21, "fat_g": 25.67, "saturated_fat_g": 5.1, "trans_fat_g": 0.03, "monounsaturated_fat_g": 12.14, "polyunsaturated_fat_g": 6.88, "fiber_g": 4.98, "sugar_g": 9.27, "sodium_mg": 1940.76, "cholesterol_mg": 0.6, "potassium_mg": 358.59, "calcium_mg": 93.93, "iron_mg": 3.11, "magnesium_mg": 93.7, "phosphorus_mg": 222.98, "zinc_mg": 1.54, "vitamin_a_mcg": 45.48, "vitamin_c_mg": 5.48, "vitamin_d_mcg": null, "vitamin_e_mg": 4.24, "vitamin_k_mcg": 2.18, "vitamin_b6_mg": 0.24, "vitamin_b12_mcg": 0.01, "thiamin_mg": 0.32, "riboflavin_mg": 0.29, "niacin_mg": 8.26, "folate_mcg": 101.55, "water_g": 18.79, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best consumed immediately; bread will become soggy if stored.", "duration": null}, "freezer": {"duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Toaster", "required": false, "alternative": "Skillet"}, {"name": "Butter knife", "required": true, "alternative": null}, {"name": "Paper towels", "required": true, "alternative": null}]', '[{"symptom": "Sandwich is soggy", "likely_cause": "Excess brine left on the pickles soaked into the bread", "prevention": "Pat pickles completely dry with paper towels before assembly", "fix": "Cannot be fixed once soggy"}]', '["Flavor Balance: The success of this sandwich relies on the interaction between fat (peanut butter) and acid (pickles). Do not use low-fat peanut butter, as the mouthfeel will be too dry.", "Pickle Choice: While Bread and Butter pickles offer a sweeter profile, Dill pickles are preferred for the classic sharp contrast. Garlic dill varieties add excellent depth.", "Technique: Spreading peanut butter on both slices of bread is crucial. It acts as a sealant, keeping the bread crisp even with the moist pickles inside."]', '"Originating during the Great Depression as an affordable, high-protein meal, the peanut butter and pickle sandwich has remained a quiet staple in American households, particularly in the South and among NY Times food enthusiasts. It is often cited as a prime example of unexpected flavor pairing success."', 448.82);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('77f2862d-e8e1-4207-bfbd-52c0f5b3e184', 'Creamy Risotto with Tender Baby Artichokes', 'A luxurious Italian classic balancing the nutty, earthiness of fresh baby artichokes with the rich creaminess of perfectly cooked Arborio rice. Finished with a bright hint of lemon and savory Parmigiano Reggiano.', 'main course', 'Italian', 'Intermediate', '["italian", "one pot", "arborio rice", "baby artichoke", "dry white wine", "dinner", "main course", "spring", "vegetarian"]', '[{"group_name": "Artichoke Prep", "items": [{"name": "baby artichokes", "quantity": 8, "unit": null, "preparation": "whole", "notes": "approx 400g before trimming", "substitutions": ["frozen artichoke hearts (300g)", "canned artichoke hearts in water"], "ingredient_id": "071d7551-8bef-45ef-9c43-9fca9dd2ecae", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": "halved", "notes": "for acidulated water", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 1000, "unit": "ml", "preparation": "cold", "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Risotto Base", "items": [{"name": "vegetable stock", "quantity": 1200, "unit": "ml", "preparation": "hot", "notes": "low-sodium preferred", "substitutions": ["chicken stock"], "ingredient_id": "93b5bf35-1f82-4ec2-a12c-5d219f15f241", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "divided use", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "shallots", "quantity": 2, "unit": null, "preparation": "finely chopped", "notes": "approx 60g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 4g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "arborio rice", "quantity": 320, "unit": "g", "preparation": null, "notes": null, "substitutions": ["carnaroli rice", "vialone nano rice"], "ingredient_id": "d8a2c73d-e2de-4182-b43b-6bdf55f00a87", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 120, "unit": "ml", "preparation": null, "notes": "Pinot Grigio or Sauvignon Blanc", "substitutions": [], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Mantecatura (Finishing)", "items": [{"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "parmigiano reggiano", "quantity": 60, "unit": "g", "preparation": "finely grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh mint", "quantity": 5, "unit": "g", "preparation": "chopped", "notes": "optional", "substitutions": [], "ingredient_id": "17abecc0-a2a0-4478-8486-57b46e4305c9", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare a bowl of cold water and squeeze the lemon juice into it (drop the lemon halves in as well). This acidulated water prevents the artichokes from turning brown.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Trim the baby artichokes: snap off the tough outer dark green leaves until you reach the pale yellow tender leaves. Cut off the top third of the artichoke. Trim the stem end, peel the stem, and quarter the artichoke lengthwise. Remove any fuzzy choke if present (usually minimal in baby varieties). Immediately drop into lemon water.", "structured": {"action": "TRIM", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Be aggressive when removing outer leaves; if they feel tough to your thumb, they will be tough to eat."]}, {"step_number": 3, "phase": "prep", "text": "Pour the vegetable stock into the medium saucepan and bring to a gentle simmer. Keep it hot throughout the cooking process.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "In the heavy-bottomed pot, heat 30g of butter and the olive oil over medium heat. Drain the artichokes and add them to the pot along with the shallots. Saut\u00e9 for 5-7 minutes until the shallots are soft and artichokes begin to brown slightly.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT7M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the minced garlic and Arborio rice. Toast the rice, stirring constantly, for 2 minutes until the edges of the grains are translucent and the center remains opaque (the ''pearl'').", "structured": {"action": "TOAST", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Pour in the white wine to deglaze the pan. Stir vigorously to release any fond from the bottom. Cook until the smell of alcohol dissipates and the liquid is almost entirely evaporated.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Begin adding the hot stock, one ladle at a time (approx 150ml). Stir frequently. Wait until the liquid is mostly absorbed before adding the next ladle. Regulate heat to maintain a steady, gentle simmer.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT18M", "doneness_cues": {"visual": "Rice looks creamy but distinct", "tactile": "Rice is al dente with a slight bite"}}, "tips": ["Constant stirring releases the starch from the rice, creating the signature creamy texture."]}, {"step_number": 8, "phase": "finish", "text": "Once the rice is tender but still has a slight bite (al dente) and the texture is fluid (not stiff), remove the pot from the heat. If it is too dry, add a final half-ladle of stock.", "structured": {"action": "REST", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Perform the ''mantecatura'': Vigorously stir in the cold cubed butter (45g), grated Parmesan, parsley, and mint. Season with salt and pepper to taste. Let sit for 2 minutes before serving.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT5M", "total_time": "PT50M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Gluten-Free", "Vegetarian", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 476.22, "protein_g": 12.26, "carbohydrates_g": 47.62, "fat_g": 23.58, "saturated_fat_g": 12.28, "trans_fat_g": null, "monounsaturated_fat_g": 8.32, "polyunsaturated_fat_g": 1.15, "fiber_g": 3.65, "sugar_g": 11.92, "sodium_mg": 1299.02, "cholesterol_mg": 50.51, "potassium_mg": 725.76, "calcium_mg": 255.59, "iron_mg": 6.04, "magnesium_mg": 41.25, "phosphorus_mg": 247.13, "zinc_mg": 0.97, "vitamin_a_mcg": 173.64, "vitamin_c_mg": 22.91, "vitamin_d_mcg": 0.08, "vitamin_e_mg": 1.26, "vitamin_k_mcg": 45.47, "vitamin_b6_mg": 0.31, "vitamin_b12_mcg": 0.21, "thiamin_mg": 0.4, "riboflavin_mg": 0.14, "niacin_mg": 3.3, "folate_mcg": 92.04, "water_g": 426.62, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Texture will degrade; risotto is best eaten immediately.", "duration": "P3D"}, "freezer": {"notes": "Freezing is not recommended as rice will become grainy and mushy.", "duration": null}, "reheating": "Reheat gently on the stove with a splash of water or stock to loosen the starch structure.", "does_not_keep": false}', '[{"name": "Heavy-bottomed pot or Dutch oven", "required": true, "alternative": "Large deep saut\u00e9 pan"}, {"name": "Medium saucepan", "required": true, "alternative": "Microwave-safe bowl (for stock)"}, {"name": "Wooden spoon", "required": true, "alternative": null}, {"name": "Ladle", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Bowl", "required": true, "alternative": null}]', '[{"symptom": "Rice is crunchy in the middle", "likely_cause": "Undercooked or heat was too high causing liquid to evaporate before penetrating the grain", "prevention": "Maintain a gentle simmer and taste test frequently after 15 minutes", "fix": "Add another ladle of hot stock or water and cook for 2-3 more minutes, stirring constantly"}, {"symptom": "Risotto is gummy or gluey", "likely_cause": "Rice was stirred too aggressively or overcooked", "prevention": "Stir frequently but not violently; stop cooking when rice is al dente", "fix": "Stir in a splash of hot stock to loosen the texture immediately before serving"}]', '["The ''Mantecatura'' (Step 9) is the most critical step for texture. Using cold butter helps create a glossy, stable emulsion.", "Do not wash the rice before cooking; you need the surface starch to achieve the creamy consistency.", "If baby artichokes are unavailable, frozen artichoke hearts are a reliable substitute. Defrost and pat them dry before saut\u00e9ing.", "Serve on a flat plate rather than a deep bowl; the risotto should slowly spread outwards (all''onda) rather than sit in a pile."]', '"Risotto is a staple of Northern Italian cuisine, particularly in regions like Lombardy and Piedmont where rice paddies are abundant. This specific variation celebrates spring produce, pairing the bitterness of artichokes (carciofi) with the sweetness of dairy, a combination deeply rooted in Roman and Tuscan traditions."', 476.22);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('78412153-b116-4ed5-9b2d-c64f005cb0ac', 'Raspberry and Orange Brioche Bread and Butter Pudding', 'A luxurious twist on a British classic, featuring buttery brioche soaked in a rich vanilla custard, studded with tart fresh raspberries and bright, aromatic orange zest. The top bakes to a golden, sugary crunch while the interior remains creamy and tender.', 'dessert', 'British', 'Intermediate', '["dessert", "brioche", "raspberry", "pudding", "baked", "sweet", "british"]', '[{"group_name": "Base", "items": [{"name": "brioche loaf", "quantity": 350, "unit": "g", "preparation": "sliced and halved", "notes": "stale brioche works best for absorption", "substitutions": [], "ingredient_id": "a6757b5b-57ed-49b1-ac42-1ff05554beca", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 50, "unit": "g", "preparation": "softened", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh raspberries", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4f5b84c-c364-40cd-b737-375755e481f9", "nutrition_source": "USDA FoodData Central"}, {"name": "orange zest", "quantity": 1, "unit": null, "preparation": "finely grated", "notes": "zest of 1 large orange", "substitutions": [], "ingredient_id": "fcee57fc-f714-49de-808f-c70853f04c2a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Custard", "items": [{"name": "whole milk", "quantity": 250, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 250, "unit": "ml", "preparation": null, "notes": "double cream", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 3, "unit": null, "preparation": null, "notes": "large, approx 150g without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "caster sugar", "quantity": 75, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Topping", "items": [{"name": "demerara sugar", "quantity": 20, "unit": "g", "preparation": null, "notes": "for sprinkling", "substitutions": [], "ingredient_id": "5ebb3e25-da7a-442b-be81-e098b7d79a00", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Grease the baking dish lightly. Butter the brioche slices generously on one side, then cut them into triangles or halves.", "structured": {"action": "PREPARE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "assemble", "text": "Arrange half the buttered brioche in the dish, scattering half the raspberries and half the orange zest over the top. Repeat with the remaining brioche, raspberries, and zest.", "structured": {"action": "LAYER", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a saucepan, combine the milk and cream. Heat gently over medium heat until it just begins to simmer (do not boil), then remove from heat.", "structured": {"action": "SCALD", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "In a mixing bowl, whisk together the eggs, caster sugar, and vanilla extract until pale and slightly thickened.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Slowly pour the hot milk mixture into the eggs while whisking constantly to temper the eggs and prevent scrambling.", "structured": {"action": "TEMPER", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Pour the custard evenly over the brioche layers. Press the bread down gently with a spatula to ensure it is submerged.", "structured": {"action": "SOAK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "prep", "text": "Let the pudding stand at room temperature for 30 minutes to allow the brioche to absorb the custard. Preheat the oven to 170\u00b0C (340\u00b0F) during this time.", "structured": {"action": "REST", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Sprinkle the demerara sugar over the top of the pudding for a crunchy crust.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Bake for 35-40 minutes until the top is golden brown and the custard is set but still has a slight wobble in the center.", "structured": {"action": "BAKE", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": "PT40M", "doneness_cues": {"visual": "Golden brown crust", "tactile": "Slight wobble in center"}}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Remove from the oven and let cool for 10 minutes before serving to allow the custard to set further.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT1H10M", "total_time": "PT1H30M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 220}', '{"flags": ["Vegetarian"], "not_suitable_for": ["Vegans (contains dairy, eggs)", "Gluten intolerant (contains wheat)"]}', '{"per_serving": {"calories": 539.41, "protein_g": 10.61, "carbohydrates_g": 40.91, "fat_g": 35.19, "saturated_fat_g": 19.15, "trans_fat_g": 2.28, "monounsaturated_fat_g": 7.01, "polyunsaturated_fat_g": 1.57, "fiber_g": 2.48, "sugar_g": 22.27, "sodium_mg": 284.89, "cholesterol_mg": 162.17, "potassium_mg": 240.26, "calcium_mg": 124.64, "iron_mg": 1.87, "magnesium_mg": 16.74, "phosphorus_mg": 163.38, "zinc_mg": 0.9, "vitamin_a_mcg": 410.21, "vitamin_c_mg": 8.39, "vitamin_d_mcg": 1.71, "vitamin_e_mg": 1.09, "vitamin_k_mcg": 4.07, "vitamin_b6_mg": 0.09, "vitamin_b12_mcg": 0.49, "thiamin_mg": 0.05, "riboflavin_mg": 0.28, "niacin_mg": 0.24, "folate_mcg": 21, "water_g": 103.31, "alcohol_g": 0.29, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Cover tightly with cling film or store in an airtight container.", "duration": "P3D"}, "freezer": {"notes": "Not recommended as the texture of the custard can separate upon thawing.", "duration": null}, "reheating": "Warm gently in a 160\u00b0C oven for 15 minutes or microwave in short bursts.", "does_not_keep": false}', '[{"name": "Ceramic baking dish (approx. 20x30cm)", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Saucepan", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Zester or fine grater", "required": true, "alternative": null}, {"name": "Knife", "required": true, "alternative": null}]', '[{"symptom": "Custard has curdled or separated", "likely_cause": "Oven temperature was too high or pudding was baked too long", "prevention": "Ensure oven is at 170\u00b0C and check for the ''wobble'' at the 30-minute mark", "fix": "Cannot be fixed, but can still be eaten if the texture isn''t too grainy"}, {"symptom": "Pudding is soggy in the middle", "likely_cause": "Bread didn''t soak long enough or custard was undercooked", "prevention": "Allow the full 30-minute soak time; bake until center is set", "fix": "Return to oven for 5-10 minutes, covering top with foil if browning too much"}]', '["Using slightly stale brioche is superior to fresh bread as it absorbs the custard without disintegrating.", "The 30-minute soak is crucial; if you skip this, the custard will separate from the bread rather than creating a unified texture.", "For an extra decadent touch, glaze the finished pudding with a little warmed apricot jam.", "If the top begins to brown too quickly before the custard is set, cover loosely with aluminum foil."]', '"Bread and butter pudding is a traditional British dessert dating back to the early 18th century, originally designed as a frugal way to use up stale bread. This version elevates the humble nursery food with French brioche and citrus notes, moving it from leftover status to a centerpiece dessert."', 539.41);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('79df9a86-1c5a-41d0-b50f-f01beebcbf9b', 'Zucchini and Summer Squash Caponata Agrodolce', 'A vibrant Sicilian-style appetizer balancing the sweet and sour notes of agrodolce. Tender zucchini and yellow squash replace traditional eggplant, mingling with briny capers and buttery green olives. Best served at room temperature on crusty bread.', 'appetizer', 'Italian', 'Intermediate', '["italian", "finger foods", "caper", "green olive", "squash", "zucchini", "brunch", "lunch", "appetizer", "summer", "vegetarian", "vegan"]', '[{"group_name": "Vegetables", "items": [{"name": "zucchini", "quantity": 300, "unit": "g", "preparation": "medium dice (1cm cubes)", "notes": null, "substitutions": [], "ingredient_id": "d0aa0d47-cefe-4ece-a337-e656f79b74e9", "nutrition_source": "Aggregated Public Data"}, {"name": "yellow squash", "quantity": 300, "unit": "g", "preparation": "medium dice (1cm cubes)", "notes": null, "substitutions": [], "ingredient_id": "78f47d04-2579-43be-9b47-b179d0108805", "nutrition_source": "Aggregated Public Data"}, {"name": "yellow onion", "quantity": 150, "unit": "g", "preparation": "finely diced", "notes": null, "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "celery", "quantity": 100, "unit": "g", "preparation": "finely diced", "notes": null, "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics & Sauce", "items": [{"name": "green olives", "quantity": 80, "unit": "g", "preparation": "pitted and roughly chopped", "notes": "Castelvetrano or Cerignola preferred", "substitutions": [], "ingredient_id": "8628da64-fa1c-4c91-badf-515667dbe9b9", "nutrition_source": "USDA FoodData Central"}, {"name": "capers", "quantity": 30, "unit": "g", "preparation": "rinsed", "notes": "use salted capers if available", "substitutions": [], "ingredient_id": "e7301d2c-b906-4ef8-917e-787be0b25880", "nutrition_source": "USDA FoodData Central"}, {"name": "tomato pur\u00e9e", "quantity": 150, "unit": "ml", "preparation": "passata", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": "divided use", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "red wine vinegar", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "9e1b7e74-fdcb-4836-8349-4f7ad86d62df", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 25, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 3-5g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish (Optional)", "items": [{"name": "fresh mint", "quantity": 5, "unit": "g", "preparation": "torn", "notes": null, "substitutions": [], "ingredient_id": "17abecc0-a2a0-4478-8486-57b46e4305c9", "nutrition_source": "USDA FoodData Central"}, {"name": "pine nuts", "quantity": 20, "unit": "g", "preparation": "toasted", "notes": null, "substitutions": [], "ingredient_id": "971298ad-a9d7-49f7-811b-46afedad18d4", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Wash and dice the zucchini and yellow squash into uniform 1cm cubes. Dice the onion and celery to a slightly smaller size.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat 40ml of olive oil in a large skillet over medium-high heat (approx 190\u00b0C/375\u00b0F). Add the zucchini and yellow squash in a single layer (do this in batches if necessary to avoid steaming).", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Fry the squash for 6-8 minutes until golden brown and tender but not mushy. Remove with a slotted spoon and set aside in a bowl.", "structured": {"action": "FRY", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Golden brown edges", "tactile": "Tender but holds shape"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "In the same pan, add the remaining 20ml olive oil. Add the onion and celery. Saut\u00e9 over medium heat (160\u00b0C/320\u00b0F) until softened and translucent.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Stir in the tomato pur\u00e9e, chopped olives, and capers. Simmer gently for 5 minutes to meld the flavors.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Pour in the red wine vinegar and sprinkle the sugar over the mixture. Stir well and cook for 2-3 minutes until the vinegar pungency evaporates and the sauce thickens slightly.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Return the fried zucchini and squash to the pan. Fold gently to coat the vegetables in the sauce without crushing them. Cook for 1 minute to warm through.", "structured": {"action": "FOLD", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from heat and transfer to a serving dish. Let the caponata cool completely to room temperature (at least 1 hour) to allow the sweet and sour flavors to penetrate the vegetables. Garnish with torn mint and toasted pine nuts before serving.", "structured": {"action": "REST", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT1H", "total_time": "PT1H35M", "overnight_required": false, "yields": "600g (approx. 12 servings on crostini)", "yield_count": 12, "serving_size_g": 50}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 91.6, "protein_g": 1.42, "carbohydrates_g": 6.44, "fat_g": 7.21, "saturated_fat_g": 0.97, "trans_fat_g": null, "monounsaturated_fat_g": 4.41, "polyunsaturated_fat_g": 0.63, "fiber_g": 1.5, "sugar_g": 4.41, "sodium_mg": 303.45, "cholesterol_mg": null, "potassium_mg": 161.26, "calcium_mg": 13.43, "iron_mg": 0.53, "magnesium_mg": 19.32, "phosphorus_mg": 34.65, "zinc_mg": 0.17, "vitamin_a_mcg": 8.19, "vitamin_c_mg": 7.88, "vitamin_d_mcg": null, "vitamin_e_mg": 1.02, "vitamin_k_mcg": 6.21, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.02, "niacin_mg": 0.08, "folate_mcg": 6.59, "water_g": 30.11, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors improve significantly after 24 hours.", "duration": "P5D"}, "freezer": {"notes": "Not recommended; vegetables will lose texture.", "duration": null}, "reheating": "Serve at room temperature. Do not reheat.", "does_not_keep": false}', '[{"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Slotted spoon", "required": true, "alternative": null}]', '[{"symptom": "Vegetables are mushy or disintegrating", "likely_cause": "Overcrowded pan during the initial frying step caused steaming instead of searing", "prevention": "Fry the squash in batches so they have space to brown quickly", "fix": "Cannot be fixed structurally, but serve as a spread or dip for crusty bread rather than a fork dish"}]', '["The secret to a great caponata is the ''agrodolce'' balance. Taste the sauce before adding the vegetables back in; it should trigger both salivation (sour) and satisfaction (sweet). Adjust vinegar or sugar by 5g increments if needed.", "Do not skip the cooling step. Hot caponata tastes disjointed; room temperature caponata is harmonious.", "For a true finger food experience, serve spoonfuls of this mixture atop toasted baguette slices rubbed with a raw garlic clove.", "If using salted capers, soak them in water for 10 minutes and rinse thoroughly to control the sodium level."]', '"Originating from Sicily, Caponata is a testament to the island''s complex history, blending Italian vegetables with Arab influences like sugar, citrus, and sour notes. While eggplant is the traditional star, summer squash versions (''Caponata di Zucchine'') are a common seasonal variation in Italian households when gardens are overflowing with zucchini."', 91.6);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('7a1a2a99-c45a-496f-a1b4-ee67fab1996d', 'Pan-Seared Salmon with Lime Herb Butter', 'Succulent, crispy-skinned salmon fillets melting under a crown of zesty lime and fresh dill compound butter. The brightness of the citrus cuts through the rich, flaky fish for a perfectly balanced finish.', 'dinner', 'Modern American', 'Easy', '["easy", "quick", "seafood", "keto", "gluten-free", "weeknight dinner", "citrus"]', '[{"group_name": "Compound Butter", "items": [{"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": "softened to room temperature", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "lime zest", "quantity": 1, "unit": null, "preparation": null, "notes": "zest of 1 lime, approx 2g", "substitutions": [], "ingredient_id": "295e8d21-9ba3-4ab8-a118-b09b77defacc", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh lime juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh dill", "quantity": 5, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "4be2b047-475d-4c84-82d5-4883298c6121", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 5, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "minced or grated", "notes": "approx 3-5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Salmon", "items": [{"name": "salmon fillets", "quantity": 4, "unit": null, "preparation": "skin-on, pin bones removed", "notes": "approx 150g each, 600g total", "substitutions": [], "ingredient_id": "6648fae7-4f63-45b3-b45d-19d927b57c2d", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "for searing", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 4, "unit": "g", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a small mixing bowl, combine the softened butter, lime zest, lime juice, chopped dill, parsley, minced garlic, and a pinch of salt. Mash with a fork until thoroughly combined. Set aside at room temperature.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Pat the salmon fillets completely dry with paper towels. Moisture prevents searing. Season the flesh side generously with salt and black pepper.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat the olive oil in a heavy-bottomed skillet over medium-high heat. When the oil shimmers but is not smoking, carefully place the salmon fillets into the pan, skin-side down. Press gently with a spatula for 10 seconds to prevent curling.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Cook undisturbed for about 4-5 minutes until the skin is crispy and golden brown, and the opaque color has cooked about 2/3 of the way up the side of the fillet.", "structured": {"action": "FRY", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Skin is golden brown, flesh opaque halfway up", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Flip the fillets and cook for another 1-2 minutes until the internal temperature reaches 50\u00b0C (122\u00b0F) for medium-rare or 54\u00b0C (129\u00b0F) for medium. Do not overcook.", "structured": {"action": "FRY", "temperature": {"celsius": 52, "fahrenheit": 126}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove the pan from heat. Immediately place a generous spoonful of the lime herb butter on top of each fillet, allowing it to melt over the fish. Transfer to a plate and rest for 2 minutes before serving.", "structured": {"action": "REST", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT5M", "total_time": "PT20M", "overnight_required": false, "yields": "4 fillets", "yield_count": 4, "serving_size_g": 175}', '{"flags": ["Pescatarian", "Gluten-Free", "Low-Carb", "Keto", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": ["Dairy-Free", "Vegan", "Vegetarian"]}', '{"per_serving": {"calories": 540.67, "protein_g": 37.21, "carbohydrates_g": 6.66, "fat_g": 54.36, "saturated_fat_g": 8.1, "trans_fat_g": null, "monounsaturated_fat_g": 6.26, "polyunsaturated_fat_g": 0.86, "fiber_g": 0.22, "sugar_g": 0.1, "sodium_mg": 3435.46, "cholesterol_mg": 32.25, "potassium_mg": 30.97, "calcium_mg": 424.09, "iron_mg": 18.05, "magnesium_mg": 452.51, "phosphorus_mg": 457.43, "zinc_mg": 1.41, "vitamin_a_mcg": 519.3, "vitamin_c_mg": 3.79, "vitamin_d_mcg": null, "vitamin_e_mg": 0.91, "vitamin_k_mcg": 24.25, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": 0.03, "thiamin_mg": 0.01, "riboflavin_mg": 0.01, "niacin_mg": 0.06, "folate_mcg": 4.55, "water_g": 7.49, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store salmon and butter separately if possible.", "duration": "P2D"}, "freezer": {"notes": "Compound butter freezes well; cooked salmon texture degrades.", "duration": "P1M"}, "reheating": "Gently reheat salmon in a low oven; add fresh butter after heating.", "does_not_keep": false}', '[{"name": "Heavy-bottomed skillet", "required": true, "alternative": "Non-stick frying pan"}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Fish spatula", "required": true, "alternative": "Standard spatula"}, {"name": "Microplane or zester", "required": true, "alternative": null}]', '[{"symptom": "Salmon skin sticks to the pan", "likely_cause": "Pan wasn''t hot enough or oil wasn''t shimmering before adding fish", "prevention": "Wait until the oil shimmers and barely smokes before adding fish; do not move it once placed", "fix": "Let it cook a minute longer; the skin often releases naturally once crisp. If stuck, slide a thin metal spatula firmly underneath to separate"}]', '["Pat the skin extremely dry before cooking; this is the secret to glass-like crispiness.", "If the butter separates when mixing in the lime juice, just keep whipping; the milk solids will eventually emulsify the liquid.", "For thicker fillets, you can sear the skin and then finish in a 200\u00b0C (400\u00b0F) oven for 3-4 minutes to ensure even cooking without burning the skin.", "Leftover compound butter is excellent on roasted vegetables, steak, or grilled corn."]', '"Compound butters (beurre compos\u00e9) are a staple of classic French cuisine used to instantly create sauce-like richness. This recipe adapts the technique with bright New World flavors\u2014lime and cilantro/dill\u2014popular in contemporary coastal American dining."', 540.67);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('7a2b5ab4-02e9-45d4-a5bc-34c507f5a917', 'Classic Greek Pastitsio', 'A deeply comforting architectural masterpiece featuring layers of tubular pasta bound with cheese, a robust beef ragù aromatic with cinnamon and cloves, and a crown of velvety, golden-brown béchamel custard.', 'dinner', 'Greek', 'Intermediate', '["beef", "pasta", "pie", "comfort food", "greek", "casserole", "baked"]', '[{"group_name": "Aromatic Beef Rag\u00f9", "items": [{"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "ground beef", "quantity": 750, "unit": "g", "preparation": "lean (85/15)", "notes": null, "substitutions": [], "ingredient_id": "696b2887-6464-4698-a80a-6860f8633185", "nutrition_source": "Aggregated Public Data"}, {"name": "red onion", "quantity": 2, "unit": null, "preparation": "finely diced", "notes": "approx. 300g total", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx. 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "tomato paste", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "d0a34229-249b-49e5-a653-227bd7afb7fc", "nutrition_source": "Aggregated Public Data"}, {"name": "red wine", "quantity": 120, "unit": "ml", "preparation": null, "notes": "dry varietal like Cabernet or Merlot", "substitutions": [], "ingredient_id": "0fc93141-8ba8-42e0-ac8b-b5af3851554c", "nutrition_source": "USDA FoodData Central"}, {"name": "canned crushed tomatoes", "quantity": 400, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "49a62ca7-db63-4d23-9f6f-2cf873fba8a3", "nutrition_source": "Aggregated Public Data"}, {"name": "cinnamon stick", "quantity": 1, "unit": null, "preparation": null, "notes": "approx. 3g", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "whole cloves", "quantity": 3, "unit": null, "preparation": null, "notes": "optional, remove before baking", "substitutions": [], "ingredient_id": "7b3bf68a-3ae9-4dad-91f4-6c7a14ec5e0e", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 1, "unit": null, "preparation": null, "notes": "approx. 2g", "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "B\u00e9chamel Custard", "items": [{"name": "unsalted butter", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 1000, "unit": "ml", "preparation": "warmed", "notes": null, "substitutions": [], "ingredient_id": "c75fcd6a-414e-40b9-bc04-333fb15c0c38", "nutrition_source": "USDA FoodData Central"}, {"name": "nutmeg", "quantity": 1, "unit": null, "preparation": "freshly grated", "notes": "approx. 0.5g", "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}, {"name": "kefalotyri cheese", "quantity": 100, "unit": "g", "preparation": "finely grated", "notes": "substitute with Parmesan or Pecorino Romano", "substitutions": ["Parmesan", "Pecorino Romano"], "ingredient_id": "75aede38-b00a-4383-9000-06b67134eb61", "nutrition_source": "USDA FoodData Central"}, {"name": "egg yolks", "quantity": 2, "unit": null, "preparation": "room temperature", "notes": "approx. 40g", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pasta Base", "items": [{"name": "bucatini or ziti pasta", "quantity": 500, "unit": "g", "preparation": null, "notes": "No. 2 macaroni is traditional", "substitutions": [], "ingredient_id": "6b7d03cf-262e-4a03-89d1-ecb4ac3556b5", "nutrition_source": "Aggregated Public Data"}, {"name": "kefalotyri cheese", "quantity": 50, "unit": "g", "preparation": "grated", "notes": "for binding pasta", "substitutions": [], "ingredient_id": "75aede38-b00a-4383-9000-06b67134eb61", "nutrition_source": "USDA FoodData Central"}, {"name": "egg whites", "quantity": 2, "unit": null, "preparation": null, "notes": "reserved from b\u00e9chamel eggs", "substitutions": [], "ingredient_id": "17645f6b-c1ea-4e82-a4b4-5ae8cb6a5a53", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 180\u00b0C/350\u00b0F. Ensure a rack is positioned in the center.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In the Dutch oven, saut\u00e9 the onions in olive oil over medium heat until soft and translucent, about 5-7 minutes. Add the minced garlic and cook for another minute until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Increase heat to medium-high and add the ground beef. Cook, breaking it up with a spoon, until fully browned and no pink remains.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Meat is browned, fat rendered", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Stir in tomato paste and cook for 2 minutes to caramelize. Deglaze with red wine, scraping the bottom of the pot. Add crushed tomatoes, cinnamon stick, cloves, oregano, salt, and pepper. Simmer uncovered on low heat until thick and most liquid has evaporated, about 30 minutes. Remove cinnamon and cloves.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT35M", "doneness_cues": null}, "tips": ["The meat sauce must be thick, not watery, to prevent the pie from collapsing."]}, {"step_number": 5, "phase": "cook", "text": "While beef simmers, bring a large pot of salted water to a boil. Cook pasta 2-3 minutes less than package instructions (very al dente). Drain and return to the pot.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "Toss the drained pasta with the reserved egg whites and 50g of grated cheese. This creates a binding layer that helps the base hold its shape when sliced.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "For the b\u00e9chamel, melt butter in the saucepan over medium heat. Whisk in flour and cook for 2-3 minutes until pale and sandy (a white roux). Do not let it brown.", "structured": {"action": "STIR", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Gradually whisk in the warmed milk, a ladle at a time, ensuring the mixture is smooth before adding more. Simmer gently for 5-7 minutes until thickened enough to coat the back of a spoon.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove b\u00e9chamel from heat. Stir in nutmeg, most of the 100g cheese (save a handful for the top), and salt to taste. Rapidly whisk in the egg yolks one by one to temper them without curdling.", "structured": {"action": "TEMPER", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "assemble", "text": "Grease the baking dish. Layer the pasta mixture evenly at the bottom. Spread the meat sauce over the pasta, pressing down gently to compact the layers.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 11, "phase": "assemble", "text": "Pour the b\u00e9chamel over the meat, spreading it to the edges. Sprinkle the remaining grated cheese on top.", "structured": {"action": "GLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 12, "phase": "cook", "text": "Bake for 45-50 minutes until the top is golden brown and bubbling. If it browns too quickly, tent loosely with foil.", "structured": {"action": "BAKE", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT45M", "doneness_cues": {"visual": "Golden brown crust, bubbling edges", "tactile": null}}, "tips": []}, {"step_number": 13, "phase": "finish", "text": "Remove from oven and let rest for at least 30 minutes before slicing. This allows the layers to set; slicing too early will cause the pie to fall apart.", "structured": {"action": "REST", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT1H", "passive_time": "PT1H15M", "total_time": "PT2H15M", "overnight_required": false, "yields": "9 generous servings", "yield_count": 9, "serving_size_g": 350}', '{"flags": [], "not_suitable_for": ["Gluten intolerance", "Lactose intolerance", "Egg allergy"]}', '{"per_serving": {"calories": 692.23, "protein_g": 37.99, "carbohydrates_g": 68.45, "fat_g": 27.43, "saturated_fat_g": 12.1, "trans_fat_g": null, "monounsaturated_fat_g": 6.74, "polyunsaturated_fat_g": 1.19, "fiber_g": 3.57, "sugar_g": 10.64, "sodium_mg": 679.76, "cholesterol_mg": 87.44, "potassium_mg": 853.2, "calcium_mg": 319.02, "iron_mg": 5.08, "magnesium_mg": 96.12, "phosphorus_mg": 508.21, "zinc_mg": 6.32, "vitamin_a_mcg": 186.4, "vitamin_c_mg": 9.21, "vitamin_d_mcg": 1.68, "vitamin_e_mg": 1.02, "vitamin_k_mcg": 5.5, "vitamin_b6_mg": 0.15, "vitamin_b12_mcg": 0.81, "thiamin_mg": 0.11, "riboflavin_mg": 0.27, "niacin_mg": 0.36, "folate_mcg": 26.78, "water_g": 153.47, "alcohol_g": 1.24, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Cover tightly with foil or transfer to airtight containers.", "duration": "P4D"}, "freezer": {"notes": "Freeze in portions. Thaw overnight in refrigerator before reheating.", "duration": "P3M"}, "reheating": "Reheat in a 160\u00b0C oven covered with foil for 20 minutes, or microwave individual portions until hot.", "does_not_keep": false}', '[{"name": "Large Dutch oven or deep skillet", "required": true, "alternative": null}, {"name": "Large saucepan", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "9x13 inch (approx 23x33cm) baking dish", "required": true, "alternative": null}, {"name": "Large pot for pasta", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "Pie collapses when sliced", "likely_cause": "The pie was sliced while too hot", "prevention": "Allow the dish to rest for at least 30-45 minutes after baking to let the b\u00e9chamel and starches set", "fix": "Let it cool longer; it will firm up as it approaches room temperature"}, {"symptom": "B\u00e9chamel is lumpy", "likely_cause": "Milk was added too quickly or was too cold", "prevention": "Add warm milk slowly, whisking constantly between additions", "fix": "Pass the sauce through a fine-mesh sieve or use an immersion blender before adding cheese/eggs"}]', '["The secret to a neat slice is the ''cementing'' of the pasta layer. Tossing the cooked pasta with egg whites and cheese creates a structure that binds the tubes together during baking.", "For a truly authentic flavor profile, the cinnamon is non-negotiable. It provides the signature warmth that distinguishes Greek meat sauce from Italian rag\u00f9.", "If using bucatini, try to align the noodles in the pan running the same direction for a stunning cross-section when sliced.", "Do not rinse the pasta after boiling; the surface starch helps the egg and cheese mixture adhere to the noodles."]', '"Pastitsio is a staple of Greek cuisine, often described as ''Greek Lasagna''. While its name derives from the Italian ''pasticcio'' (a mess or pie), the modern version with b\u00e9chamel was popularized in the early 20th century by Nikolaos Tselementes, a French-trained Greek chef who integrated classic French sauces into Greek cooking."', 692.23);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('7a5e48ca-9ef7-4fca-a535-bfa7807104c0', 'Brown Butter & Chocolate-Hazelnut Swirl Banana Bread', 'A decadent twist on a classic, featuring nutty, aromatic browned butter that deepens the sweetness of ripe bananas. Ribbons of rich chocolate-hazelnut spread create pockets of molten indulgence, transforming this loaf from a simple snack into a dessert-worthy treat.', 'baked good', 'American', 'Intermediate', '["banana", "banana bread", "brown butter", "great leftovers", "nutella", "snack", "dessert", "thanksgiving", "comfort food"]', '[{"group_name": "Brown Butter", "items": [{"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dry Ingredients", "items": [{"name": "all-purpose flour", "quantity": 250, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 4, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 1/2 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wet Ingredients", "items": [{"name": "very ripe bananas", "quantity": 3, "unit": null, "preparation": "peeled", "notes": "approx 350g weighed without peel", "substitutions": [], "ingredient_id": "d01cd7bd-9b20-4ccf-8475-27ca2843edf6", "nutrition_source": "USDA FoodData Central"}, {"name": "light brown sugar", "quantity": 150, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "large, room temperature", "notes": "approx 100g liquid weight", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "plain greek yogurt", "quantity": 60, "unit": "g", "preparation": null, "notes": "or sour cream", "substitutions": [], "ingredient_id": "2c5306ec-9f54-424e-880d-99546bbd9172", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Swirl", "items": [{"name": "chocolate-hazelnut spread", "quantity": 150, "unit": "g", "preparation": null, "notes": "e.g., Nutella", "substitutions": [], "ingredient_id": "d7121ae0-364b-401b-8b2e-4f0f38007449", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place an oven rack in the middle position and preheat the oven to 175\u00b0C (350\u00b0F). Grease a 23x13cm (9x5 inch) loaf pan or line it with parchment paper leaving an overhang for easy removal.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Melt the butter in a light-colored saucepan over medium heat. Cook, swirling the pan occasionally, until the butter foams, the milk solids turn golden brown, and it smells nutty. Immediately pour into a heatproof bowl to stop the cooking and let cool for 10-15 minutes.", "structured": {"action": "HEAT", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Golden brown milk solids", "tactile": "Nutty aroma"}}, "tips": ["Use a light-colored pan to easily see when the milk solids change color to avoid burning."]}, {"step_number": 3, "phase": "prep", "text": "Whisk the flour, baking soda, salt, and cinnamon together in a medium bowl.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In a large bowl, mash the bananas thoroughly until smooth. Whisk in the brown sugar, eggs, vanilla, yogurt, and the cooled brown butter until fully combined.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Gently fold the dry ingredients into the wet mixture using a spatula just until no flour streaks remain. Do not overmix.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "If the chocolate-hazelnut spread is stiff, microwave it for 10-20 seconds to loosen. Pour half of the banana batter into the prepared pan. Dollop half of the spread over the batter and swirl gently with a knife. Repeat with the remaining batter and spread, swirling the top layer to create a marbled effect.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Bake for 55 to 65 minutes, or until a tester inserted into the center comes out clean (avoiding the chocolate swirls where possible). If the top browns too quickly, tent loosely with aluminum foil after 40 minutes.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT1H", "doneness_cues": {"visual": null, "tactile": "Tester comes out clean"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Let the bread cool in the pan for 15 minutes, then transfer to a wire rack to cool completely before slicing. Slicing while hot may cause the bread to crumble.", "structured": {"action": "COOL", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT1H30M", "total_time": "PT2H", "overnight_required": false, "yields": "1 Loaf (10 slices)", "yield_count": 10, "serving_size_g": 95}', '{"flags": ["Vegetarian"], "not_suitable_for": ["Nut allergy sufferers", "Gluten intolerance", "Lactose intolerance"]}', '{"per_serving": {"calories": 364.08, "protein_g": 5.7, "carbohydrates_g": 51.01, "fat_g": 15.61, "saturated_fat_g": 7.29, "trans_fat_g": 0.01, "monounsaturated_fat_g": 3.09, "polyunsaturated_fat_g": 0.67, "fiber_g": 2.13, "sugar_g": 23.54, "sodium_mg": 252.42, "cholesterol_mg": 62.23, "potassium_mg": 234.82, "calcium_mg": 43.79, "iron_mg": 1.08, "magnesium_mg": 24.66, "phosphorus_mg": 79.55, "zinc_mg": 0.59, "vitamin_a_mcg": 95.88, "vitamin_c_mg": 3.05, "vitamin_d_mcg": 0.2, "vitamin_e_mg": 0.43, "vitamin_k_mcg": 1.12, "vitamin_b6_mg": 0.17, "vitamin_b12_mcg": 0.15, "thiamin_mg": 0.05, "riboflavin_mg": 0.1, "niacin_mg": 0.59, "folate_mcg": 19.12, "water_g": 44.26, "alcohol_g": 0.17, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container to maintain moisture.", "duration": "P5D"}, "freezer": {"notes": "Wrap individual slices tightly in plastic wrap and foil.", "duration": "P3M"}, "reheating": "Microwave for 15-20 seconds to melt the chocolate swirl slightly.", "does_not_keep": false}', '[{"name": "Loaf pan (23x13cm / 9x5 inch)", "required": true, "alternative": null}, {"name": "Saucepan (light-colored interior)", "required": true, "alternative": "Stainless steel skillet"}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Silicone spatula", "required": true, "alternative": null}, {"name": "Butter knife or skewer", "required": true, "alternative": "Chopstick"}]', '[{"symptom": "Bread is soggy in the middle but dark on top", "likely_cause": "Oven temperature too high or pan material conducts heat too fast", "prevention": "Tent with foil after 40 minutes; ensure oven is calibrated", "fix": "Cover loosely with foil and continue baking in 5-minute intervals"}, {"symptom": "Butter burned black instead of brown", "likely_cause": "Heat was too high or left on heat too long", "prevention": "Remove from heat immediately once golden aroma appears", "fix": "Cannot be fixed; discard and start butter over to avoid bitter taste"}]', '["Using bananas that are heavily spotted or even black ensures the highest sugar content and strongest banana flavor.", "Browning the butter evaporates its water content, so the resulting fat is pure flavor. This nutty profile compliments the roasted hazelnuts in the spread.", "Do not over-swirl the chocolate spread; too much swirling will mix it into the batter turning it gray rather than leaving distinct ribbons.", "Room temperature eggs emulsify better with the butter and sugar, creating a more uniform crumb structure."]', '"Banana bread became a household staple in the United States during the Great Depression as resourceful cooks sought to use overripe fruit. This version elevates the humble classic with European influences, utilizing the French technique of beurre noisette (brown butter) and Italy''s iconic gianduja-style spread."', 364.08);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('7a806659-5b36-4c70-b5be-ba8e57102a9f', 'Classic Roasted Cherry Tomatoes', 'Sweet, vibrant cherry tomatoes roasted until bursting, concentrating their natural sugars and creating a rich, jammy texture. Aromatic garlic and fresh herbs elevate this simple dish into a versatile summer staple.', 'side dish', 'Italian', 'Easy', '["italian", "cherry tomato", "five ingredient", "olive oil", "salt", "easy", "side dish", "summer", "vegetarian", "vegan", "roast"]', '[{"group_name": "Produce", "items": [{"name": "cherry tomatoes", "quantity": 500, "unit": "g", "preparation": "whole", "notes": "on the vine or loose; grape tomatoes also work", "substitutions": ["grape tomatoes", "cocktail tomatoes"], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "smashed", "notes": "approx 9g; leave skins on for softer roast or peel for caramelization", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 4, "unit": null, "preparation": "whole sprigs", "notes": "approx 2g", "substitutions": ["dried thyme (2g)", "fresh rosemary", "fresh oregano"], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Pantry", "items": [{"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "extra virgin preferred", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 3, "unit": "g", "preparation": "flaky or coarse", "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 200\u00b0C (400\u00b0F). Line a rimmed baking sheet with parchment paper for easier cleanup.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Wash the cherry tomatoes and pat them thoroughly dry. Any excess water will cause them to steam rather than roast.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "On the baking sheet, combine tomatoes, smashed garlic cloves, olive oil, salt, pepper, and thyme sprigs. Toss gently with your hands until every tomato is glistening with oil.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Arrange the tomatoes in a single layer, ensuring they are not crowded together.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Crowding the pan creates steam, preventing browning."]}, {"step_number": 5, "phase": "cook", "text": "Roast in the preheated oven for 20-25 minutes. The tomatoes are done when the skins have wrinkled and burst, and some juices have caramelized on the pan.", "structured": {"action": "ROAST", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT25M", "doneness_cues": {"visual": "Skins wrinkled and burst, light charring", "tactile": "Soft and yielding"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove from the oven. Discard the hard stems of the thyme and the garlic skins (if left on). Transfer to a serving dish, pouring the flavorful pan juices over the top.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT5M", "passive_time": "PT25M", "total_time": "PT30M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 130}', '{"flags": ["Vegetarian", "Vegan", "Pescatarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Low-Sodium", "Low-Carb", "Keto", "Paleo", "Whole30", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 93.29, "protein_g": 1.3, "carbohydrates_g": 5.89, "fat_g": 7.78, "saturated_fat_g": 1.08, "trans_fat_g": null, "monounsaturated_fat_g": 5.48, "polyunsaturated_fat_g": 0.8, "fiber_g": 2.43, "sugar_g": 4.9, "sodium_mg": 297.88, "cholesterol_mg": null, "potassium_mg": 311.78, "calcium_mg": 19.96, "iron_mg": 0.53, "magnesium_mg": 15.55, "phosphorus_mg": 34.37, "zinc_mg": 0.25, "vitamin_a_mcg": 1.26, "vitamin_c_mg": 18.63, "vitamin_d_mcg": null, "vitamin_e_mg": 1.09, "vitamin_k_mcg": 4.96, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.01, "niacin_mg": 0.03, "folate_mcg": 0.34, "water_g": 1.68, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container; the oil may solidify but will melt upon reheating.", "duration": "P5D"}, "freezer": {"notes": "Texture will soften significantly; best used for sauces or soups after freezing.", "duration": "P3M"}, "reheating": "Warm gently in a pan over low heat or in the microwave for 30-60 seconds.", "does_not_keep": false}', '[{"name": "Rimmed baking sheet", "required": true, "alternative": "Roasting pan"}, {"name": "Parchment paper", "required": false, "alternative": "Silicone baking mat"}, {"name": "Knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Tomatoes are soggy instead of roasted", "likely_cause": "The pan was overcrowded or the oven temperature was too low", "prevention": "Use a large baking sheet to ensure space between tomatoes and verify oven temperature", "fix": "Drain excess liquid and roast for another 5-10 minutes on the convection setting if available"}]', '["Do not discard the oil left in the pan; it is essentially a quick tomato-infused dressing perfect for dipping bread.", "If using different colored tomatoes (red, yellow, purple), note that yellow tomatoes tend to be sweeter and lower in acid.", "For a confit-style variation (softer, creamier texture), lower the temperature to 150\u00b0C (300\u00b0F) and roast for 45-60 minutes.", "Leftovers make an incredible pasta sauce base\u2014just smash them with a fork and toss with spaghetti."]', '"While tomatoes originated in the Americas, they became a cornerstone of Italian cuisine in the 16th century. This simple preparation highlights the Italian philosophy of ''cucina povera''\u2014taking simple, high-quality ingredients and treating them with minimal intervention to maximize flavor."', 93.29);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('7aada9de-7eff-49df-9ff3-da06b2193fa4', 'Bún Thịt Nướng (Vietnamese Grilled Pork Vermicelli)', 'A vibrant, textural masterpiece featuring smoky, lemongrass-charred pork atop cool, slippery rice vermicelli. The dish creates a perfect harmony of temperatures and flavors: savory hot meat, crisp fresh herbs, tangy pickled carrots, and the quintessential salty-sweet-sour nuance of Nuoc Cham sauce.', 'main course', 'Vietnamese', 'Intermediate', '["vietnamese", "noodles", "carrot", "lime", "pork chop", "rice noodle", "dinner", "lunch", "quick", "weeknight", "main course", "gluten-free"]', '[{"group_name": "Lemongrass Pork", "items": [{"name": "pork shoulder or pork neck", "quantity": 600, "unit": "g", "preparation": "sliced thinly (3-4mm)", "notes": "Choose a cut with good fat content for grilling", "substitutions": [], "ingredient_id": "074f9812-c3dd-4b65-9e90-6b668e6c71fe", "nutrition_source": "USDA FoodData Central"}, {"name": "lemongrass stalks", "quantity": 2, "unit": null, "preparation": "white part only, minced", "notes": "approx 30g", "substitutions": [], "ingredient_id": "6dde667b-d122-48d9-a70f-a4f820fc5bd5", "nutrition_source": "USDA FoodData Central"}, {"name": "shallots", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 50g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fish sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": "choose a high-protein variety (35\u00b0N or higher)", "substitutions": [], "ingredient_id": "95a9a747-50ee-4be0-84be-0dfc96111e2a", "nutrition_source": "Aggregated Public Data"}, {"name": "tamari or gluten-free soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "brown sugar or palm sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "vegetable or canola", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Nuoc Cham (Dressing)", "items": [{"name": "warm water", "quantity": 120, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "white sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "fish sauce", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "95a9a747-50ee-4be0-84be-0dfc96111e2a", "nutrition_source": "Aggregated Public Data"}, {"name": "lime juice", "quantity": 30, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "bird''s eye chili", "quantity": 1, "unit": null, "preparation": "thinly sliced", "notes": "adjust to heat preference", "substitutions": [], "ingredient_id": "6cdb0615-378e-4bfa-b76d-f19bbd780e6c", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Noodles & Vegetables", "items": [{"name": "dried rice vermicelli (b\u00fan)", "quantity": 300, "unit": "g", "preparation": null, "notes": "thin round noodles, not flat pho noodles", "substitutions": [], "ingredient_id": "d8a2c73d-e2de-4182-b43b-6bdf55f00a87", "nutrition_source": "USDA FoodData Central"}, {"name": "carrots", "quantity": 150, "unit": "g", "preparation": "julienned", "notes": null, "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "cucumber", "quantity": 150, "unit": "g", "preparation": "julienned", "notes": null, "substitutions": [], "ingredient_id": "457adec2-3e06-4efe-a26e-9e6ea9f84924", "nutrition_source": "USDA FoodData Central"}, {"name": "bean sprouts", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "6d29b2fe-d48e-4143-b38e-919c67febaea", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh mint", "quantity": 20, "unit": "g", "preparation": "leaves picked", "notes": null, "substitutions": [], "ingredient_id": "17abecc0-a2a0-4478-8486-57b46e4305c9", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 20, "unit": "g", "preparation": "rough chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "roasted peanuts", "quantity": 40, "unit": "g", "preparation": "crushed", "notes": null, "substitutions": ["toasted sesame seeds"], "ingredient_id": "ba36d967-879c-446b-ba1e-b1fa36e475db", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Quick Pickle Liquid", "items": [{"name": "white vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8d5bf07e-89a1-47ee-a6b7-d9cb03e96d64", "nutrition_source": "Aggregated Public Data"}, {"name": "sugar", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine minced lemongrass, shallots, garlic (3 cloves), fish sauce (30ml), tamari, brown sugar, black pepper, and neutral oil in a food processor or mortar. Process into a coarse paste.", "structured": {"action": "BLEND", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Massage the marinade paste thoroughly into the thinly sliced pork. Cover and let marinate at room temperature for 30 minutes, or refrigerate up to 24 hours for deeper flavor.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "While pork marinates, dissolve 15g sugar and 2g salt in 30ml vinegar. Toss the julienned carrots in this mixture and set aside to quick-pickle.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Prepare the Nuoc Cham sauce: In a small bowl, dissolve 30g sugar in 120ml warm water. Stir in 45ml fish sauce, lime juice, remaining minced garlic, and chili. Adjust to taste\u2014it should be a bold balance of salty, sweet, and sour.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Bring a large pot of water to a rolling boil. Cook the rice vermicelli according to package instructions (usually 3-5 minutes) until white and soft but not mushy. Drain immediately and rinse thoroughly under cold running water to stop cooking and remove excess starch.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Preheat a grill pan or heavy skillet over medium-high heat. working in batches, sear the pork slices. Cook for 2-3 minutes per side until well-charred and cooked through (internal temp 63\u00b0C/145\u00b0F minimum, though texture benefits from slight caramelization).", "structured": {"action": "GRILL", "temperature": {"celsius": 63, "fahrenheit": 145}, "duration": null, "doneness_cues": {"visual": "Deep brown char marks", "tactile": "Firm edges"}}, "tips": ["Do not overcrowd the pan, or the meat will steam instead of searing."]}, {"step_number": 7, "phase": "assemble", "text": "To serve, divide noodles among bowls. Top with a pile of grilled pork, pickled carrots (drained), fresh cucumber, bean sprouts, mint, and cilantro.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Garnish with crushed peanuts and serve with the Nuoc Cham sauce on the side to be poured over just before eating.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT40M", "passive_time": "PT30M", "total_time": "PT1H10M", "overnight_required": false, "yields": "4 bowls", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Gluten-Free", "Dairy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 496.94, "protein_g": 35.26, "carbohydrates_g": 54.24, "fat_g": 15.1, "saturated_fat_g": 4.37, "trans_fat_g": null, "monounsaturated_fat_g": 4.92, "polyunsaturated_fat_g": 1.34, "fiber_g": 3.55, "sugar_g": 23.99, "sodium_mg": 1782.71, "cholesterol_mg": 100.5, "potassium_mg": 992.38, "calcium_mg": 100.44, "iron_mg": 7.31, "magnesium_mg": 86.26, "phosphorus_mg": 408.62, "zinc_mg": 5.62, "vitamin_a_mcg": 431.75, "vitamin_c_mg": 16.99, "vitamin_d_mcg": null, "vitamin_e_mg": 0.33, "vitamin_k_mcg": 20.58, "vitamin_b6_mg": 0.95, "vitamin_b12_mcg": 1.26, "thiamin_mg": 1.56, "riboflavin_mg": 0.56, "niacin_mg": 8.89, "folate_mcg": 104.1, "water_g": 308.37, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store meat, noodles, herbs, and sauce in separate containers.", "duration": "P3D"}, "freezer": {"notes": "Marinated raw pork can be frozen. Cooked noodles do not freeze well.", "duration": "P1M"}, "reheating": "Reheat pork in a pan or microwave. Serve noodles and vegetables room temperature or cold.", "does_not_keep": false}', '[{"name": "Food processor or Mortar and Pestle", "required": true, "alternative": "Chef''s knife and patience"}, {"name": "Grill pan or Heavy Skillet", "required": true, "alternative": "Outdoor BBQ Grill"}, {"name": "Large pot", "required": true, "alternative": null}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "Pork is tough or dry", "likely_cause": "Slices were too thick or cooked too long at too low heat", "prevention": "Freeze pork for 20 minutes before slicing to get paper-thin cuts; cook hot and fast", "fix": "Cut cooked meat into smaller bite-sized strips and mix well with the dressing to rehydrate"}, {"symptom": "Noodles are gummy and stuck together", "likely_cause": "Insufficient rinsing after boiling", "prevention": "Rinse vigorously under cold water until noodles feel cool to the touch", "fix": "Briefly rinse under warm water to separate, then cold water again"}]', '["The secret to authentic flavor is ''blackening'' the sugar in the marinade slightly during cooking\u2014don''t fear the dark char marks on the pork; that is where the flavor lives.", "Nuoc Cham strength varies by fish sauce brand (Red Boat is saltier/purer than Squid brand). Add fish sauce gradually and taste as you go.", "For a true restaurant finish, make a quick Scallion Oil (M\u1ee1 H\u00e0nh) by pouring hot oil over chopped green onions and spooning this over the assembled bowl.", "If using wooden skewers on an outdoor grill, soak them in water for 30 minutes beforehand to prevent burning."]', '"B\u00fan Th\u1ecbt N\u01b0\u1edbng is a staple of Southern Vietnam, particularly popular in Ho Chi Minh City. Unlike the broth-heavy Ph\u1edf, this is a ''dry'' noodle salad that relies on the contrast between hot, savory grilled meat and cold, refreshing noodles and herbs, tied together by the ubiquitous Nuoc Cham sauce."', 496.94);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('7abb77b5-ff9f-42f5-a81b-a66560fe4990', 'Pan-Fried Chicken Livers with Mushroom Ragu and Spinach Noodles', 'Rich, creamy pan-seared chicken livers served atop vibrant green spinach noodles, coated in a robust, earthy tomato-mushroom sauce. A rustic, iron-rich dinner that balances the mineral intensity of the liver with the sweetness of tomatoes and savory mushrooms.', 'dinner', 'Italian', 'Intermediate', '["chicken liver", "mushroom", "dinner", "weeknight", "main course", "pasta", "italian-inspired"]', '[{"group_name": "Chicken Livers", "items": [{"name": "chicken livers", "quantity": 500, "unit": "g", "preparation": "cleaned and trimmed", "notes": "lobes separated", "substitutions": [], "ingredient_id": "b7fa6814-4883-4625-851a-4af4e4c2715e", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 30, "unit": "g", "preparation": null, "notes": "for dredging", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 2g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly ground", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Mushroom Tomato Sauce", "items": [{"name": "cremini mushrooms", "quantity": 250, "unit": "g", "preparation": "sliced", "notes": null, "substitutions": [], "ingredient_id": "fdd23eb2-a71c-46d1-932b-295adf7d5ae5", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "crushed tomatoes", "quantity": 400, "unit": "g", "preparation": null, "notes": "canned", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "tomato paste", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "d0a34229-249b-49e5-a653-227bd7afb7fc", "nutrition_source": "Aggregated Public Data"}, {"name": "dry red wine", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["chicken stock", "beef stock"], "ingredient_id": "0fc93141-8ba8-42e0-ac8b-b5af3851554c", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Base & Garnish", "items": [{"name": "spinach noodles", "quantity": 350, "unit": "g", "preparation": "dried", "notes": "fettuccine or tagliatelle style", "substitutions": [], "ingredient_id": "745dbe43-2afc-4b69-bd1a-ddfa386dd1c2", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "parmesan cheese", "quantity": null, "unit": null, "preparation": "grated", "notes": "for serving", "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the cleaned chicken livers thoroughly dry with paper towels. Season generously with salt and pepper. If using flour, lightly dredge the livers and shake off excess.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Moisture is the enemy of a good sear. Ensure livers are very dry."]}, {"step_number": 2, "phase": "cook", "text": "Heat 30ml olive oil in a large skillet over medium heat. Add the diced onion and cook until softened and translucent, about 5 minutes.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Increase heat to medium-high. Add sliced mushrooms to the onions. Cook undisturbed for 2-3 minutes to brown, then stir and cook until mushrooms release their liquid and it evaporates.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT6M", "doneness_cues": {"visual": "Mushrooms are golden brown and dry", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Stir in the tomato paste, minced garlic, and oregano. Cook for 1 minute until fragrant. Deglaze the pan with red wine, scraping up any browned bits from the bottom.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the crushed tomatoes. Reduce heat to low and simmer the sauce gently for 15-20 minutes to thicken flavors. Season with salt and pepper to taste.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "While sauce simmers, bring a large pot of salted water to a boil. Add spinach noodles and cook according to package directions (usually 8-10 minutes) until al dente. Drain and keep warm.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "In a separate clean skillet (or after setting sauce aside), heat butter and 15ml olive oil over high heat until butter foams and subsides. Add chicken livers in a single layer. Do not crowd the pan; work in batches if necessary.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Sear livers for 2-3 minutes per side until deep golden brown on the outside but still slightly pink in the center (internal temp 74\u00b0C/165\u00b0F for full safety, though 70\u00b0C/158\u00b0F is often preferred for texture).", "structured": {"action": "SEAR", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Deep brown crust", "tactile": "Slight resistance but yielding"}}, "tips": []}, {"step_number": 9, "phase": "assemble", "text": "Toss the drained spinach noodles with a ladle of the mushroom tomato sauce. Plate the noodles, top with the pan-fried livers, and spoon remaining sauce over the top.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Garnish with fresh chopped parsley and grated parmesan cheese if desired. Serve immediately.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT10M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 380}', '{"flags": ["Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Pregnant women (high Vitamin A)", "Individuals with gout"]}', '{"per_serving": {"calories": 844.36, "protein_g": 34.58, "carbohydrates_g": 88.14, "fat_g": 38.85, "saturated_fat_g": 11.75, "trans_fat_g": null, "monounsaturated_fat_g": 18.06, "polyunsaturated_fat_g": 5.44, "fiber_g": 9.51, "sugar_g": 7.05, "sodium_mg": 788.44, "cholesterol_mg": 589.91, "potassium_mg": 1069.1, "calcium_mg": 145.7, "iron_mg": 16.45, "magnesium_mg": 111.15, "phosphorus_mg": 462.21, "zinc_mg": 4.75, "vitamin_a_mcg": 347.94, "vitamin_c_mg": 35.72, "vitamin_d_mcg": 0.02, "vitamin_e_mg": 3.16, "vitamin_k_mcg": 52.09, "vitamin_b6_mg": 0.78, "vitamin_b12_mcg": 10.49, "thiamin_mg": 1.06, "riboflavin_mg": 2.21, "niacin_mg": 15.39, "folate_mcg": 630.24, "water_g": 143.21, "alcohol_g": 1.4, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Livers may become tougher upon reheating. Store sauce and pasta separately if possible.", "duration": "P2D"}, "freezer": {"notes": "Sauce freezes well; cooked livers and pasta texture will degrade significantly.", "duration": "P1M"}, "reheating": "Gently reheat sauce in a pan. Warm livers separately over low heat just until hot to avoid overcooking.", "does_not_keep": false}', '[{"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Large pot", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Livers are dry, grainy, and chalky", "likely_cause": "Overcooking", "prevention": "Cook over high heat for a short time; remove from pan immediately once seared.", "fix": "Chop them up finely and mix into the sauce to create a ragu texture; the sauce will mask the dryness."}]', '["To remove the metallic taste some find objectionable in liver, soak the cleaned livers in milk for 30 minutes before patting dry and cooking.", "Be very careful when searing livers; they can ''pop'' or explode due to internal steam pockets. Use a splatter screen if available.", "The spinach noodles add a subtle earthiness that pairs perfectly with the iron in the liver; if unavailable, plain fettuccine works, but add a handful of fresh spinach to the sauce.", "Do not salt the livers until right before they hit the pan, as salt draws out moisture and prevents browning."]', '"This dish draws inspiration from rustic Italian ''Cucina Povera'' traditions, where organ meats (quinto quarto) were celebrated. The combination of earthy mushrooms and iron-rich liver with pasta is a classic flavor profile found in various forms across Tuscany and Emilia-Romagna."', 844.36);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('7ade8dad-d983-4ecb-b19e-4096ea411cd9', 'Gingered Lemon Banana Jam', 'A luscious, golden preserve combining the creamy sweetness of ripe bananas with the bright zest of lemon and the warming spice of fresh ginger. This small-batch refrigerator jam offers a texture similar to fruit butter, perfect for toast or swirling into yogurt.', 'preserve', 'International', 'Easy', '["condiments", "banana", "lemon", "sugar", "preserve", "spread", "breakfast", "vegetarian", "vegan", "gluten-free"]', '[{"group_name": "Fruit Base", "items": [{"name": "ripe bananas", "quantity": 400, "unit": "g", "preparation": "peeled", "notes": "weighed after peeling; heavily spotted bananas are best", "substitutions": [], "ingredient_id": "d01cd7bd-9b20-4ccf-8475-27ca2843edf6", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh lemon juice", "quantity": 45, "unit": "ml", "preparation": null, "notes": "approx 1 large lemon", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 3, "unit": "g", "preparation": null, "notes": "finely grated", "substitutions": [], "ingredient_id": "03fb65be-9b62-44e7-a121-694de64cdec0", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh ginger", "quantity": 10, "unit": "g", "preparation": "grated or minced", "notes": "peeled", "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sweetener & Seasoning", "items": [{"name": "white sugar", "quantity": 180, "unit": "g", "preparation": null, "notes": null, "substitutions": ["light brown sugar"], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "small pinch to enhance flavor", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Mash the peeled bananas in a bowl or directly in the saucepan using a potato masher or fork until chunky-smooth.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": {"visual": "Thick puree with small lumps", "tactile": null}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Combine the mashed bananas, sugar, lemon juice, lemon zest, grated ginger, and salt in a heavy-bottomed saucepan. Stir well to dissolve the sugar.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Place the saucepan over medium heat. Bring the mixture to a bubbling boil, stirring frequently to prevent scorching on the bottom.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Reduce heat to low and simmer for 15-20 minutes. Stir constantly, scraping the bottom and sides, until the mixture thickens, darkens slightly, and tracks are left when the spatula is pulled through.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT20M", "doneness_cues": {"visual": "Glossy, thickened, coats the back of a spoon", "tactile": null}}, "tips": ["Be careful of hot splatters as the mixture thickens.", "The jam will thicken further as it cools."]}, {"step_number": 5, "phase": "finish", "text": "Remove from heat and let cool for 10 minutes. Transfer into a clean glass jar. Allow to cool completely to room temperature before sealing and refrigerating.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT25M", "total_time": "PT40M", "overnight_required": false, "yields": "400g (approx 1 medium jar)", "yield_count": 20, "serving_size_g": 20}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Diabetics (high sugar content)"]}', '{"per_serving": {"calories": 53.68, "protein_g": 0.24, "carbohydrates_g": 13.83, "fat_g": 0.08, "saturated_fat_g": 0.02, "trans_fat_g": null, "monounsaturated_fat_g": 0.01, "polyunsaturated_fat_g": 0.02, "fiber_g": 0.55, "sugar_g": 11.49, "sodium_mg": 19.79, "cholesterol_mg": null, "potassium_mg": 76.42, "calcium_mg": 1.32, "iron_mg": 0.06, "magnesium_mg": 5.77, "phosphorus_mg": 4.75, "zinc_mg": 0.03, "vitamin_a_mcg": 0.6, "vitamin_c_mg": 2.64, "vitamin_d_mcg": null, "vitamin_e_mg": 0.03, "vitamin_k_mcg": 0.1, "vitamin_b6_mg": 0.08, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.02, "niacin_mg": 0.14, "folate_mcg": 4.51, "water_g": 17.45, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Keep in an airtight, clean jar. Consume within 2 weeks.", "duration": "P2W"}, "freezer": {"notes": "Leave 1-2cm headspace in the container for expansion.", "duration": "P3M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Heavy-bottomed saucepan", "required": true, "alternative": "Non-stick pot"}, {"name": "Potato masher", "required": true, "alternative": "Fork"}, {"name": "Silicone spatula", "required": true, "alternative": null}, {"name": "Glass jar with lid", "required": true, "alternative": "Airtight plastic container"}, {"name": "Microplane or grater", "required": true, "alternative": null}]', '[{"symptom": "Jam is scorching/burning on the bottom", "likely_cause": "Heat was too high or stirring was insufficient", "prevention": "Use a heavy-bottomed pot and stir constantly once the mixture thickens", "fix": "Immediately stop stirring the bottom layer. Pour the unburnt top layer into a clean pot and continue cooking on lower heat. Discard the burnt residue."}, {"symptom": "Jam is too runny after cooling", "likely_cause": "Undercooked; insufficient water evaporation", "prevention": "Cook until the mixture holds its shape on a chilled spoon", "fix": "Return to the pot and simmer for another 5-10 minutes"}]', '["Use bananas that are heavily spotted with brown; green or yellow bananas lack the necessary sugar content and aroma for a good jam.", "This is a refrigerator jam, not a shelf-stable canned preserve. Because bananas are low-acid fruit, traditional water-bath canning is risky without precise pH testing.", "Try serving warm over vanilla ice cream or swirled into oatmeal for a comforting breakfast.", "The ginger flavor will mellow slightly over time; add a pinch more at the end if you prefer a spicy kick."]', '"Banana jam is a popular confection in tropical regions like the Philippines (minatamis na saging) and the Caribbean, often used as a way to preserve bountiful harvests of rapidly ripening fruit. This version incorporates Western preserving techniques with the zest of lemon and ginger for a brighter profile."', 53.68);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('7ae98cb5-edad-4a95-a30e-1988e33adb22', 'Velvet Cocoa Fudge Sauce', 'A deeply intense, glossy chocolate sauce with a luxurious mouthfeel. Balanced sweetness and a pinch of salt highlight the complex cocoa notes, making it an essential topping for vanilla bean ice cream or profiteroles.', 'sauce', 'French', 'Easy', '["sauce", "chocolate", "dessert topping", "gluten-free", "quick"]', '[{"group_name": "Dry Mix", "items": [{"name": "granulated sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "unsweetened cocoa powder", "quantity": 50, "unit": "g", "preparation": null, "notes": "Dutch-processed preferred for darker color", "substitutions": [], "ingredient_id": "c06a8e5a-163a-4f21-ad00-a6d90e34c38c", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "large pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wet Base", "items": [{"name": "heavy cream", "quantity": 180, "unit": "ml", "preparation": "cold or room temperature", "notes": "35% fat or higher", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 40, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a medium saucepan (off heat), whisk together the sugar, cocoa powder, and salt until no large lumps of cocoa remain.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add the heavy cream and cubed butter to the pan. Turn the heat to medium.", "structured": {"action": "MIX", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Bring the mixture to a gentle boil while whisking constantly. Once bubbling, reduce heat to low and simmer for 3 to 4 minutes, stirring frequently with a spatula to prevent scorching on the bottom.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "glossy and slightly thickened", "tactile": "coats the back of a spoon"}}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Remove the saucepan from the heat. Stir in the vanilla extract immediately. The alcohol will evaporate slightly, leaving a warm aroma.", "structured": {"action": "STIR", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Allow the sauce to cool for at least 5 minutes before serving. It will thicken considerably as it cools.", "structured": {"action": "COOL", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT5M", "total_time": "PT15M", "overnight_required": false, "yields": "300ml", "yield_count": 10, "serving_size_g": 30}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Egg-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 160.77, "protein_g": 1.53, "carbohydrates_g": 18.47, "fat_g": 10.43, "saturated_fat_g": 6.56, "trans_fat_g": 0.22, "monounsaturated_fat_g": 2.8, "polyunsaturated_fat_g": 0.43, "fiber_g": 1.85, "sugar_g": 15.65, "sodium_mg": 45.35, "cholesterol_mg": 28.94, "potassium_mg": 95.11, "calcium_mg": 19.47, "iron_mg": 0.72, "magnesium_mg": 26.35, "phosphorus_mg": 48.13, "zinc_mg": 0.39, "vitamin_a_mcg": 101.34, "vitamin_c_mg": 0.11, "vitamin_d_mcg": 0.29, "vitamin_e_mg": 0.26, "vitamin_k_mcg": 0.98, "vitamin_b6_mg": 0.01, "vitamin_b12_mcg": 0.04, "thiamin_mg": 0.01, "riboflavin_mg": 0.05, "niacin_mg": 0.12, "folate_mcg": 2.44, "water_g": 11.45, "alcohol_g": 0.17, "caffeine_mg": 11.5}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Solidifies when cold; reheat gently before serving.", "duration": "P2W"}, "freezer": {"notes": "Thaw in refrigerator overnight.", "duration": "P3M"}, "reheating": "Microwave in short 15-second bursts or warm gently over low heat on the stove.", "does_not_keep": false}', '[{"name": "Medium saucepan", "required": true, "alternative": null}, {"name": "Balloon whisk", "required": true, "alternative": null}, {"name": "Heatproof spatula", "required": true, "alternative": null}, {"name": "Glass jar with lid", "required": true, "alternative": "Airtight container"}]', '[{"symptom": "Sauce is grainy", "likely_cause": "Sugar did not fully dissolve", "prevention": "Ensure the mixture comes to a gentle boil and simmer long enough", "fix": "Add 15ml of water and heat gently while stirring until smooth"}, {"symptom": "Sauce is too thick after cooling", "likely_cause": "Simmered too long or too much evaporation", "prevention": "Adhere strictly to simmering times", "fix": "Whisk in warm milk or water 15ml at a time until desired consistency is reached"}]', '["Use Dutch-processed cocoa powder for a darker color and mellower, less acidic flavor profile.", "This sauce makes an excellent mocha base; simply stir 30ml into hot coffee or milk.", "Do not walk away while simmering; chocolate burns easily and becomes bitter."]', '"While chocolate sauces trace back to early Aztec cacao preparations, this rich, butter-fortified version (often called ''hot fudge'' in America) borrows from French ganache techniques to create a stable, pourable emulsion ideal for desserts."', 160.77);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('7d4a78d3-efe5-4562-97ff-6033e2b32e09', 'Indian-Style Spiced Spinach Puree (Saag)', 'A vibrant, emerald-green side dish that balances the earthy mineral notes of fresh spinach with the sweet depth of caramelized onions and aromatic warmth of ginger and garlic. Silky smooth and comforting.', 'side dish', 'Indian', 'Easy', '["indian", "onion", "spinach", "easy", "quick", "vegetarian", "side dish", "gluten-free"]', '[{"group_name": "Vegetables & Aromatics", "items": [{"name": "fresh spinach", "quantity": 500, "unit": "g", "preparation": "washed and tough stems removed", "notes": "Spinach reduces significantly when cooked", "substitutions": [], "ingredient_id": "4734440a-226d-4d26-a110-3ed5c3bde93f", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "finely chopped", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 15, "unit": "g", "preparation": "minced or grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "green chili", "quantity": 1, "unit": null, "preparation": "slit lengthwise", "notes": "optional, adjust for heat preference", "substitutions": [], "ingredient_id": "6cdb0615-378e-4bfa-b76d-f19bbd780e6c", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Fat & Spices", "items": [{"name": "ghee", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": ["vegetable oil", "coconut oil"], "ingredient_id": "f3bd3ed3-45ef-4469-9f4c-7fbd5c40d069", "nutrition_source": "USDA FoodData Central"}, {"name": "cumin seeds", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "turmeric powder", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "garam masala", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ffcea01-5f22-462b-94de-ad2a97049325", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare an ice bath in a large bowl with cold water and plenty of ice. Bring a large pot of water to a rolling boil.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": ["The ice bath is non-negotiable for keeping the spinach bright green."]}, {"step_number": 2, "phase": "cook", "text": "Blanch the spinach in the boiling water for exactly 2 minutes until wilted and bright green, then immediately transfer to the ice bath to stop the cooking.", "structured": {"action": "BLANCH", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Bright vibrant green", "tactile": "Soft and wilted"}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Once cold, drain the spinach well, squeezing out excess water with your hands. Coarsely chop.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Damp sponge consistency"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Heat ghee in a pan over medium heat. Add cumin seeds and toast until they sizzle and darken slightly.", "structured": {"action": "TEMPER", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the chopped onion, green chili (if using), and salt. Saut\u00e9 until the onions are soft and beginning to turn golden brown.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Golden brown edges", "tactile": "Softened texture"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Add the minced garlic, ginger, and turmeric. Cook for another 1-2 minutes until the raw smell of garlic disappears.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Transfer the cooked aromatic mixture (remove the chili if you want less heat) and the blanched spinach to a blender. Blend to a smooth puree. You may add 15-30ml of water if needed to help the blades catch.", "structured": {"action": "PUREE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Uniform smooth paste", "tactile": "Silky texture"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Pour the puree back into the pan on low heat. Stir in the garam masala and simmer gently for 2 minutes to marry the flavors. Check salt and serve immediately.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT2M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT5M", "total_time": "PT25M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 150}', '{"flags": ["Vegetarian", "Gluten-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Low-Carb", "Keto"], "not_suitable_for": []}', '{"per_serving": {"calories": 127.08, "protein_g": 4.59, "carbohydrates_g": 11.12, "fat_g": 8.33, "saturated_fat_g": 4.62, "trans_fat_g": null, "monounsaturated_fat_g": 0.13, "polyunsaturated_fat_g": 0.57, "fiber_g": 3.93, "sugar_g": 2.4, "sodium_mg": 394.87, "cholesterol_mg": 22.5, "potassium_mg": 828.61, "calcium_mg": 148.56, "iron_mg": 4.38, "magnesium_mg": 109.59, "phosphorus_mg": 85.76, "zinc_mg": 0.89, "vitamin_a_mcg": 588.5, "vitamin_c_mg": 46.59, "vitamin_d_mcg": null, "vitamin_e_mg": 2.63, "vitamin_k_mcg": 604.51, "vitamin_b6_mg": 0.36, "vitamin_b12_mcg": null, "thiamin_mg": 0.14, "riboflavin_mg": 0.26, "niacin_mg": 1.07, "folate_mcg": 251.02, "water_g": 155.62, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Color may darken slightly upon reheating.", "duration": "P3D"}, "freezer": {"notes": "Texture remains good, but freshness of flavor diminishes.", "duration": "P2M"}, "reheating": "Gently warm on the stovetop over low heat; add a splash of water if too thick.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Large bowl", "required": true, "alternative": "Clean sink basin"}, {"name": "Saut\u00e9 pan or skillet", "required": true, "alternative": null}, {"name": "Blender or Food Processor", "required": true, "alternative": "Immersion blender"}]', '[{"symptom": "Puree looks dull olive or brown instead of bright green", "likely_cause": "Overcooked spinach or acid (lemon/tomato) was added during cooking", "prevention": "Shock spinach in ice water immediately after blanching; do not cover pot when reheating", "fix": "Cannot fix color, but flavor will still be good. Garnish with cream or fresh herbs to brighten appearance"}, {"symptom": "Texture is watery", "likely_cause": "Spinach was not squeezed dry enough before blending", "prevention": "Squeeze blanched spinach firmly", "fix": "Simmer in the pan longer to evaporate excess moisture"}]', '["Squeezing the water out of the spinach is critical. If you leave too much water, the puree will separate on the plate rather than holding a nice shape.", "For a richer restaurant-style finish, stir in 30ml of heavy cream or a tablespoon of butter at the very end.", "If you want this to be a main dish, you can add cubes of paneer cheese, tofu, or boiled potatoes during the final simmer.", "Do not cover the pan during the final simmer; trapping the steam can cause the chlorophyll to break down and turn the vibrant green color brown."]', '"This dish is a simplified version of ''Saag,'' a staple in North Indian cuisine traditionally made with mustard greens and spinach. While traditional preparation involves slow-cooking the greens for hours in an earthen pot, this technique utilizes blanching to retain the fresh flavor and nutritional profile of the spinach while achieving the characteristic silky texture."', 127.08);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('7e68c72d-648a-4af6-9eb8-f2f5ecae9b4f', 'Balinese-Style Slow-Grilled Spareribs (Iga Babi Bakar)', 'Succulent pork spareribs marinated in a pungent, savory fish sauce and aromatic turmeric brine, then slow-cooked over charcoal for a smoky flavor and tender texture. Finished with a sweet and spicy glaze.', 'dinner', 'Indonesian', 'Advanced', '["indonesian", "bali", "bbq", "pork", "summer", "grilling", "dinner"]', '[{"group_name": "Meat", "items": [{"name": "pork spareribs", "quantity": 1500, "unit": "g", "preparation": "membrane removed", "notes": "St. Louis style or baby back ribs", "substitutions": [], "ingredient_id": "ba191fa4-098e-4855-9095-9b32f8dcf84f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatic Paste (Bumbu)", "items": [{"name": "shallots", "quantity": 60, "unit": "g", "preparation": "peeled", "notes": null, "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 30, "unit": "g", "preparation": "peeled", "notes": null, "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "ginger", "quantity": 25, "unit": "g", "preparation": "peeled", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "turmeric", "quantity": 15, "unit": "g", "preparation": "fresh or 5g powder", "notes": null, "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "coriander seeds", "quantity": 8, "unit": "g", "preparation": "toasted", "notes": null, "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "white pepper", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Fish Sauce Brine", "items": [{"name": "fish sauce", "quantity": 80, "unit": "ml", "preparation": null, "notes": "premium quality", "substitutions": [], "ingredient_id": "95a9a747-50ee-4be0-84be-0dfc96111e2a", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 100, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "palm sugar", "quantity": 50, "unit": "g", "preparation": "shaved", "notes": "can substitute brown sugar", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "lime juice", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Glaze", "items": [{"name": "kecap manis", "quantity": 80, "unit": "ml", "preparation": null, "notes": "Indonesian sweet soy sauce", "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "neutral oil", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "bird''s eye chili", "quantity": 2, "unit": null, "preparation": "finely minced", "notes": "optional, approx 4g", "substitutions": [], "ingredient_id": "e40b2f32-1599-4b72-a829-b858329933e8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine shallots, garlic, ginger, turmeric, coriander seeds, and white pepper in a food processor. Pulse until a fine paste forms.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a bowl, mix the fish sauce, water, shaved palm sugar, and lime juice until the sugar dissolves. Stir in the aromatic paste.", "structured": {"action": "MIX", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Place the ribs in a large non-reactive container or ziplock bag. Pour the marinade over the ribs, massaging it into the meat. Refrigerate for at least 6 hours, preferably overnight.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT12H", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Prepare a charcoal grill for indirect heat. Bank the coals to one side to create a cool zone. Aim for an ambient temperature of 110\u00b0C-120\u00b0C (230\u00b0F-250\u00b0F).", "structured": {"action": "PREHEAT", "temperature": {"celsius": 115, "fahrenheit": 239}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Remove ribs from marinade (reserve marinade). Place ribs on the cool side of the grill, bone side down. Close the lid and cook for 2.5 to 3 hours, maintaining steady low heat. Add more charcoal as needed.", "structured": {"action": "ROAST", "temperature": null, "duration": "PT3H", "doneness_cues": {"visual": "Meat pulls back from bone ends by 1cm", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "While ribs cook, boil the reserved marinade in a small saucepan for 5 minutes to kill bacteria. Strain it, then whisk in the Kecap Manis, oil, and minced chili (if using) to create the finishing glaze.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Move the ribs directly over the coals. Brush generously with the glaze. Sear for 2-3 minutes per side until the sugars caramelize and char slightly. Watch closely to prevent burning.", "structured": {"action": "GRILL", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT5M", "doneness_cues": {"visual": "Glossy, charred exterior", "tactile": "Internal temp reaches 85\u00b0C/185\u00b0F+"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove ribs from heat and let rest for 10 minutes before slicing between the bones.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT12H", "total_time": "PT16H", "overnight_required": true, "yields": "4 servings", "yield_count": 4, "serving_size_g": 400}', '{"flags": ["Dairy-Free", "Nut-Free", "Egg-Free"], "not_suitable_for": ["Halal diets", "Kosher diets"]}', '{"per_serving": {"calories": 953.03, "protein_g": 71.44, "carbohydrates_g": 29.01, "fat_g": 59.95, "saturated_fat_g": 19.09, "trans_fat_g": 0.12, "monounsaturated_fat_g": 25.92, "polyunsaturated_fat_g": 6.99, "fiber_g": 2.81, "sugar_g": 17.59, "sodium_mg": 4231.26, "cholesterol_mg": 258.75, "potassium_mg": 1454.97, "calcium_mg": 90.08, "iron_mg": 8.46, "magnesium_mg": 123.13, "phosphorus_mg": 776.41, "zinc_mg": 8.99, "vitamin_a_mcg": 6.04, "vitamin_c_mg": 9.01, "vitamin_d_mcg": 2.63, "vitamin_e_mg": 1.2, "vitamin_k_mcg": 3.06, "vitamin_b6_mg": 2.04, "vitamin_b12_mcg": 2.51, "thiamin_mg": 2.36, "riboflavin_mg": 1, "niacin_mg": 17.97, "folate_mcg": 18.84, "water_g": 301.35, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Reheat gently to avoid drying out.", "duration": "P3D"}, "freezer": {"notes": "Best frozen without the final glaze if possible.", "duration": "P2M"}, "reheating": "Wrap in foil and heat in an oven at 150\u00b0C until warmed through.", "does_not_keep": false}', '[{"name": "Charcoal grill", "required": true, "alternative": "Smoker or gas grill with smoker box"}, {"name": "Food processor or mortar and pestle", "required": true, "alternative": null}, {"name": "Meat thermometer", "required": true, "alternative": null}, {"name": "Basting brush", "required": true, "alternative": null}, {"name": "Large non-reactive container", "required": true, "alternative": "Large ziplock bag"}]', '[{"symptom": "Meat is tough or chewy", "likely_cause": "Cooked too fast at too high a temperature", "prevention": "Maintain grill temperature below 120\u00b0C (250\u00b0F) for the majority of the cook time", "fix": "Wrap ribs tightly in foil with a splash of water/apple juice and continue cooking until tender"}, {"symptom": "Glaze is burnt/bitter", "likely_cause": "Applied glaze too early or heat was too high during searing", "prevention": "Only apply the sugar-heavy glaze in the final 5 minutes", "fix": "Scrape off burnt sections and re-apply fresh glaze"}]', '["To ensure even tenderness, remove the silver skin (membrane) from the back of the ribs before marinating. Lift a corner with a butter knife and pull it off with a paper towel.", "If you cannot maintain low charcoal temperatures, you can roast the ribs in an oven at 140\u00b0C (285\u00b0F) for 2.5 hours, then finish them on a hot grill for the smoky flavor.", "The fish sauce provides deep umami, not just saltiness. Do not substitute it with soy sauce in the brine phase, as the enzymatic properties of fish sauce also help tenderize the meat.", "Kecap Manis is thicker and sweeter than regular soy sauce. If unavailable, simulate it by reducing equal parts soy sauce and brown sugar until syrupy."]', '"While Indonesia is a majority Muslim country where pork is rare, the island of Bali is predominantly Hindu and famous for its pork dishes like Babi Guling. This recipe is inspired by Balinese ''Iga Babi Bakar,'' showcasing the region''s love for complex spice pastes (bumbu) and open-fire cooking."', 953.03);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('7ee5a48b-f9f6-4e6c-af2e-cec788084965', 'Charred Shishito and Raw Corn Salad', 'A vibrant textural study contrasting smoky, blistered shishito peppers against the sweet, crisp pop of raw summer corn. Tied together with a zesty cumin-lime vinaigrette and salty crumbles of cotija cheese.', 'salad', 'Mexican-Fusion', 'Easy', '["vegetables", "cilantro", "corn", "cotija", "cumin", "jalape\u00f1o", "lime", "red onion", "salad", "shishito", "brunch", "dinner", "lunch", "appetizer", "side dish", "summer", "fall", "weeknight"]', '[{"group_name": "Salad Base", "items": [{"name": "shishito peppers", "quantity": 225, "unit": "g", "preparation": "whole", "notes": "approx. 20-25 peppers", "substitutions": ["green bell peppers (sliced)", "padron peppers"], "ingredient_id": "ebcc5c6c-8973-4351-9507-ee1d3c463c7a", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh corn on the cob", "quantity": 2, "unit": null, "preparation": "kernels removed", "notes": "yields approx 200g kernels; do not cook", "substitutions": [], "ingredient_id": "46ca2aab-cb23-4397-9711-528c234b2cf8", "nutrition_source": "USDA FoodData Central"}, {"name": "red onion", "quantity": 40, "unit": "g", "preparation": "finely diced", "notes": null, "substitutions": [], "ingredient_id": "1c270c6e-0acc-4c5c-9935-7eff3240fc4a", "nutrition_source": "Aggregated Public Data"}, {"name": "cotija cheese", "quantity": 60, "unit": "g", "preparation": "crumbled", "notes": null, "substitutions": ["feta cheese", "queso fresco"], "ingredient_id": "8ac005dc-dfb4-4067-bc69-5bbfb71c3abf", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh cilantro", "quantity": 15, "unit": "g", "preparation": "roughly chopped", "notes": null, "substitutions": ["fresh mint"], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "jalape\u00f1o", "quantity": 1, "unit": null, "preparation": "seeded and minced", "notes": "optional for consistent heat, approx 15g", "substitutions": [], "ingredient_id": "4253d4ec-8462-43c6-963a-ae1f94367e2b", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 10, "unit": "ml", "preparation": null, "notes": "for searing peppers", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Cumin-Lime Vinaigrette", "items": [{"name": "lime juice", "quantity": 45, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 2, "unit": "g", "preparation": null, "notes": "toasted if possible", "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 5, "unit": "g", "preparation": null, "notes": "optional to balance acidity", "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Using a sharp knife, slice the corn kernels off the cobs into a large bowl. Ensure you do not cut too deep into the woody cob.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat neutral oil in a cast iron skillet over high heat until just smoking (approx. 200\u00b0C/400\u00b0F). Add the whole shishito peppers in a single layer.", "structured": {"action": "HEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Sear the peppers undisturbed for 2 minutes until blistered and charred on one side. Toss and cook for another 1-2 minutes until softened but not mushy. Remove from heat.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Blackened blisters on skin", "tactile": "Softened flesh with some resistance"}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Once the peppers are cool enough to handle, remove the stems and roughly chop them into 2cm pieces. Seeds can be left in for texture or removed.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "In a small jar or bowl, whisk together the lime juice, olive oil, ground cumin, honey (if using), and salt until emulsified.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Add the chopped shishitos, red onion, jalape\u00f1o (if using), and cilantro to the bowl with the corn. Pour the vinaigrette over the vegetables and toss to combine.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Transfer to a serving platter and top generously with crumbled cotija cheese. Serve immediately.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 160}', '{"flags": ["Vegetarian", "Gluten-Free", "Egg-Free", "Soy-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 245.08, "protein_g": 6.41, "carbohydrates_g": 15.85, "fat_g": 19.09, "saturated_fat_g": 2.09, "trans_fat_g": null, "monounsaturated_fat_g": 8.5, "polyunsaturated_fat_g": 1.45, "fiber_g": 2.33, "sugar_g": 6.38, "sodium_mg": 514.55, "cholesterol_mg": null, "potassium_mg": 205.77, "calcium_mg": 129.55, "iron_mg": 0.73, "magnesium_mg": 27.53, "phosphorus_mg": 158.95, "zinc_mg": 0.86, "vitamin_a_mcg": 163, "vitamin_c_mg": 7.23, "vitamin_d_mcg": null, "vitamin_e_mg": 1.7, "vitamin_k_mcg": 7.02, "vitamin_b6_mg": 0.05, "vitamin_b12_mcg": null, "thiamin_mg": 0.08, "riboflavin_mg": 0.03, "niacin_mg": 0.93, "folate_mcg": 22.2, "water_g": 57.37, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten fresh as the corn loses its crispness and peppers soften.", "duration": "P1D"}, "freezer": {"duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Cast iron skillet or heavy-bottomed pan", "required": true, "alternative": "Stainless steel frying pan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Whisk or jar", "required": true, "alternative": null}]', '[{"symptom": "Shishitos are soggy instead of charred", "likely_cause": "Pan was not hot enough or pan was overcrowded", "prevention": "Use a heavy skillet on high heat and cook in batches if necessary", "fix": "Cannot be fixed, serve as is but note texture will be softer"}, {"symptom": "Salad is too spicy", "likely_cause": "Unlucky ''hot'' shishito or spicy jalape\u00f1o seeds", "prevention": "Taste peppers before adding; remove veins and seeds from jalape\u00f1o", "fix": "Add more corn, avocado, or a dollop of crema/sour cream to mitigate heat"}]', '["Approximately one in ten shishito peppers is surprisingly spicy. This ''roulette'' aspect is part of the fun, but be warned if serving to heat-sensitive guests.", "Do not cook the corn. Raw summer corn is milky, sweet, and crisp, providing a crucial textural contrast to the soft cooked peppers.", "If shishitos are unavailable, green bell peppers cut into strips and charred in the same manner make a decent substitute, though the flavor is less complex.", "For an aromatic twist, swap half the cilantro for fresh mint, which pairs exceptionally well with the cumin and lime."]', '"This dish draws inspiration from Mexican ''esquites'' (street corn salad) and Japanese izakaya culture where blistered shishitos are a staple snack. It bridges the two cuisines through their shared love of charred vegetables and bright, acidic seasonings."', 245.08);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('7efe9997-7c90-4c48-9ef4-e8b397cac4de', 'Fresh Oysters with Ginger-Soy Vinaigrette', 'Briny, pristine ocean freshness meets the sharp tang of rice vinegar and the warming bite of fresh ginger. This Asian-inspired mignonette balances the creaminess of the oysters with a bright, savory acidity.', 'appetizer', 'Asian Fusion', 'Intermediate', '["asian", "five ingredient", "fresh ginger", "oyster", "seafood", "easy", "appetizer", "raw"]', '[{"group_name": "Oysters", "items": [{"name": "fresh live oysters", "quantity": 12, "unit": null, "preparation": "chilled", "notes": "approx. 1kg whole weight", "substitutions": [], "ingredient_id": "920550b5-ab98-4d81-a6e7-5806abf83033", "nutrition_source": "USDA FoodData Central"}, {"name": "crushed ice", "quantity": 500, "unit": "g", "preparation": "for serving", "notes": null, "substitutions": [], "ingredient_id": "ace33db4-8651-416e-85b7-5d2d0e12fa6b", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Ginger-Soy Vinaigrette", "items": [{"name": "rice vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fcbf5252-1be9-4dd4-8c22-4fda1dbdca28", "nutrition_source": "Aggregated Public Data"}, {"name": "soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["tamari for gluten-free"], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh ginger", "quantity": 10, "unit": "g", "preparation": "finely minced or grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "scallion", "quantity": 1, "unit": null, "preparation": "finely chopped", "notes": "approx. 15g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "sesame oil", "quantity": 2, "unit": "ml", "preparation": null, "notes": "just a few drops", "substitutions": [], "ingredient_id": "a9a59164-d949-4acd-99da-689f0a32e2e7", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Scrub the oyster shells under cold running water with a stiff brush to remove grit and mud. Discard any oysters that are open and do not close when tapped.", "structured": {"action": "PEEL", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Combine rice vinegar, soy sauce, minced ginger, chopped scallion, and sesame oil in a small bowl. Stir to combine and set aside to let flavors meld.", "structured": {"action": "MIX", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Prepare a serving platter with a bed of crushed ice to hold the shucked oysters stable and cold.", "structured": {"action": "PREPARE_GARNISH", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Hold an oyster cup-side down in a folded towel. Insert the tip of the oyster knife into the hinge. Twist firmly until the hinge pops. Slide the knife along the top shell to sever the muscle, remove the top shell, and inspect for shell fragments.", "structured": {"action": "SHUCK", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": ["Keep the oyster level to avoid spilling the brine (liquor).", "Sever the bottom muscle so the oyster slides easily for the guest."]}, {"step_number": 5, "phase": "finish", "text": "Nestle the shucked oysters immediately into the crushed ice. Spoon about 5ml (1 tsp) of the vinaigrette over each oyster or serve the sauce on the side.", "structured": {"action": "SERVE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT10M", "total_time": "PT35M", "overnight_required": false, "yields": "12 oysters", "yield_count": 4, "serving_size_g": 60}', '{"flags": ["Pescatarian", "Dairy-Free", "Egg-Free", "Nut-Free", "Low-Carb", "Keto", "Sugar-Free"], "not_suitable_for": ["Infants", "Pregnant individuals (raw shellfish)", "Immunocompromised individuals (raw shellfish)"]}', '{"per_serving": {"calories": 59.07, "protein_g": 8.27, "carbohydrates_g": 2.48, "fat_g": 1.93, "saturated_fat_g": 0.46, "trans_fat_g": null, "monounsaturated_fat_g": 0.48, "polyunsaturated_fat_g": 0.24, "fiber_g": 0.21, "sugar_g": 1.82, "sodium_mg": 615.85, "cholesterol_mg": 27.38, "potassium_mg": 132.1, "calcium_mg": 5.35, "iron_mg": 1.52, "magnesium_mg": 9.7, "phosphorus_mg": 78.74, "zinc_mg": 1.37, "vitamin_a_mcg": 1.88, "vitamin_c_mg": 0.83, "vitamin_d_mcg": null, "vitamin_e_mg": 0.1, "vitamin_k_mcg": 7.77, "vitamin_b6_mg": 0.2, "vitamin_b12_mcg": 1.84, "thiamin_mg": 0.08, "riboflavin_mg": 0.11, "niacin_mg": 1.79, "folate_mcg": 5.68, "water_g": 33.69, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Oysters must be kept alive on ice until shucking. Once shucked, consume immediately. Sauce keeps for 3 days.", "duration": "PT2H"}, "freezer": {"notes": "Do not freeze raw oysters in shell.", "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Oyster knife", "required": true, "alternative": "Strong, short-bladed dull knife (risky)"}, {"name": "Clean kitchen towel or cut-resistant glove", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Stiff bristle brush", "required": true, "alternative": "New sponge"}, {"name": "Serving platter with crushed ice", "required": true, "alternative": null}]', '[{"symptom": "Oyster shell shatters while shucking", "likely_cause": "Applying force to the wrong point or brittle shell", "prevention": "Ensure knife is securely in the hinge before twisting; do not pry the side of the shell", "fix": "Carefully pick out all shell fragments with a clean towel or discard if too fragmented"}, {"symptom": "Oyster smells sulfurous or ''off''", "likely_cause": "Oyster is dead and spoiling", "prevention": "Purchase from reputable fishmongers; check tag dates", "fix": "Cannot be fixed. Discard immediately to prevent food poisoning."}]', '["Safety First: Never force the oyster knife. If it slips, it can cause serious injury. Use a proper guard or thick towel.", "The ''Liquor'': Try to retain the clear, salty liquid inside the oyster shell; it contains the essence of the oyster''s flavor.", "Temperature: Oysters must be kept very cold. If not serving immediately, keep them on ice in the fridge.", "Ginger Tip: For the finest texture in the sauce, use a microplane to grate the ginger rather than chopping it.", "Variety: This sauce works best with Pacific oysters (Crassostrea gigas) which have a creamy, vegetal profile that stands up to the soy and ginger."]', '"While the classic French mignonette relies on red wine vinegar and shallots, this variation draws on East Asian flavor profiles. The combination of ginger and vinegar is traditionally used in Chinese cuisine to balance the ''cooling'' nature of seafood (yin) with ''warming'' ingredients (yang)."', 59.07);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('7f1551ea-0f67-44a9-a689-7f2a7ce94176', 'Classic Sticky Toffee Pudding', 'A quintessentially British dessert featuring a moist, dark sponge sweetened with dates and black treacle, drenched in a rich, salty-sweet toffee sauce. The texture is dense yet soft, with deep notes of caramel and molasses.', 'dessert', 'British', 'Intermediate', '["dessert", "pudding", "sticky toffee", "cake", "british", "comfort food", "baking"]', '[{"group_name": "Date Sponge", "items": [{"name": "pitted dates", "quantity": 250, "unit": "g", "preparation": "chopped", "notes": "Medjool dates are preferred for softness", "substitutions": [], "ingredient_id": "657c170c-11cc-41f7-a980-050a218a088e", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 250, "unit": "ml", "preparation": "boiling", "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "bicarbonate of soda", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 5g (1 tsp)", "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 80, "unit": "g", "preparation": "softened", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "dark muscovado sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": "Provides crucial molasses flavor; light brown sugar is a poor substitute", "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "large, room temperature", "notes": "approx 110g total without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "self-raising flour", "quantity": 180, "unit": "g", "preparation": null, "notes": null, "substitutions": ["180g plain flour + 2.5 tsp baking powder"], "ingredient_id": "ede3bc67-5e17-42bc-bd50-d5d40c332393", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "90237166-b129-4858-8c9c-2f8a7ab9a301", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Toffee Sauce", "items": [{"name": "unsalted butter", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "dark muscovado sugar", "quantity": 300, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "double cream", "quantity": 300, "unit": "ml", "preparation": null, "notes": "heavy cream (min 36% fat)", "substitutions": ["heavy whipping cream"], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "black treacle", "quantity": 15, "unit": "ml", "preparation": null, "notes": "approx 1 tbsp; adds bitter depth", "substitutions": [], "ingredient_id": "c76e81ce-ce17-4595-b9ff-30c87fb7c285", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt flakes", "quantity": null, "unit": null, "preparation": null, "notes": "generous pinch to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 180\u00b0C/350\u00b0F (160\u00b0C fan) and generously butter a 23cm (9-inch) square baking dish.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Place the chopped dates and boiling water in a bowl. Let stand for 5-10 minutes to soften.", "structured": {"action": "SOAK", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Stir the bicarbonate of soda into the date mixture. It will fizz slightly. Mash the mixture with a fork or blitz briefly in a food processor until it forms a chunky puree.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Mixture froths and darkens", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In a large bowl or stand mixer, beat the softened butter and dark muscovado sugar together until fluffy and pale brown.", "structured": {"action": "CREAM", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Pale, aerated texture", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Add the eggs one at a time, beating well between additions and scraping down the sides of the bowl. Mix in the vanilla extract.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "Gently fold in the flour using a spatula until no white streaks remain. Do not overmix.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "prep", "text": "Fold the warm date puree into the batter until evenly distributed. The batter will be quite liquid.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Pour the batter into the prepared baking dish and bake for 35-40 minutes, or until the top is springy and a skewer inserted comes out clean.", "structured": {"action": "BAKE", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT40M", "doneness_cues": {"visual": "Skewer comes out clean", "tactile": "Springy to touch"}}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "While the pudding bakes, make the sauce. Combine butter, muscovado sugar, and half the cream in a saucepan over medium heat.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "cook", "text": "Once the sugar has dissolved and the butter melted, stir in the treacle (if using) and the remaining cream. Simmer gently for 2-3 minutes until the sauce coats the back of a spoon.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Dark, glossy, coats back of spoon", "tactile": null}}, "tips": []}, {"step_number": 11, "phase": "finish", "text": "As soon as the sponge comes out of the oven, prick it all over with a skewer. Pour about one-third of the hot sauce over the sponge so it soaks in.", "structured": {"action": "SOAK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 12, "phase": "finish", "text": "Let the sponge rest for 10-15 minutes before slicing. Serve warm with the remaining sauce poured generously over each portion.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT50M", "total_time": "PT1H20M", "overnight_required": false, "yields": "9 servings", "yield_count": 9, "serving_size_g": 180}', '{"flags": ["Vegetarian"], "not_suitable_for": ["Vegans (contains dairy, eggs)", "Gluten intolerant"]}', '{"per_serving": {"calories": 656.93, "protein_g": 5.24, "carbohydrates_g": 87.1, "fat_g": 34.16, "saturated_fat_g": 20.98, "trans_fat_g": 0.42, "monounsaturated_fat_g": 9.48, "polyunsaturated_fat_g": 1.61, "fiber_g": 2.4, "sugar_g": 69.31, "sodium_mg": 499.64, "cholesterol_mg": 138.08, "potassium_mg": 363.79, "calcium_mg": 165.87, "iron_mg": 1.87, "magnesium_mg": 31.92, "phosphorus_mg": 188.41, "zinc_mg": 0.53, "vitamin_a_mcg": 333.3, "vitamin_c_mg": 0.2, "vitamin_d_mcg": 0.78, "vitamin_e_mg": 1.04, "vitamin_k_mcg": 3.7, "vitamin_b6_mg": 0.15, "vitamin_b12_mcg": 0.21, "thiamin_mg": 0.16, "riboflavin_mg": 0.23, "niacin_mg": 1.72, "folate_mcg": 51.71, "water_g": 69.54, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Cover tightly to prevent drying out. Reheat before serving.", "duration": "P4D"}, "freezer": {"notes": "Freeze sponge and sauce separately for best results.", "duration": "P2M"}, "reheating": "Warm sponge in microwave or oven; gently heat sauce in a pan until liquid.", "does_not_keep": false}', '[{"name": "Food processor", "required": false, "alternative": "Sharp knife and fork for mashing"}, {"name": "23cm square baking dish", "required": true, "alternative": "Individual pudding molds"}, {"name": "Saucepan", "required": true, "alternative": null}, {"name": "Stand mixer or electric hand whisk", "required": true, "alternative": "Bowl and wooden spoon (requires significant effort)"}, {"name": "Sieve", "required": true, "alternative": null}]', '[{"symptom": "Sponge has sunk in the middle", "likely_cause": "Oven door was opened too early or underbaked", "prevention": "Do not open the oven door for at least the first 25 minutes; ensure center springs back when touched", "fix": "Fill the sunken center with extra toffee sauce and berries; cosmetic only"}, {"symptom": "Sauce has split (oily layer on top)", "likely_cause": "Mixture boiled too vigorously or temperature shock", "prevention": "Simmer gently; do not boil rapidly", "fix": "Whisk in a tablespoon of boiling water or cold cream vigorously to re-emulsify"}]', '["The bicarb is not just for leavening; it softens the date skins and breaks down the fibers, creating that signature dark, sticky texture.", "Dark muscovado sugar is non-negotiable for an authentic flavor. Regular brown sugar lacks the necessary molasses depth.", "For a bistro-style finish, place the sauce-covered portions under a hot grill (broiler) for 1 minute until the sauce bubbles, then serve immediately with vanilla ice cream."]', '"Originating in the Lake District of England in the 1970s (though likely based on earlier pudding traditions), Sticky Toffee Pudding has become a modern British classic. It is a staple of ''Sunday Roast'' menus and pub fare, beloved for its comforting warmth and extreme sweetness."', 656.93);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('7f5f73d8-a53f-4097-8af5-e698ea08ada2', 'Topinambours à la Provençale', 'A rustic, comforting side dish where the nutty, artichoke-like flavor of sunchokes is softened by a sweet and tangy tomato braise. Garlic and fresh parsley provide a classic Provençal finish to this simple vegetarian plate.', 'side dish', 'French', 'Intermediate', '["french", "canned tomato", "five ingredient", "sunchoke", "dinner", "quick", "side dish", "vegetarian", "vegan", "gluten-free"]', '[{"group_name": "Vegetables", "items": [{"name": "jerusalem artichokes", "quantity": 600, "unit": "g", "preparation": "peeled and sliced into 1cm rounds", "notes": "also known as sunchokes", "substitutions": [], "ingredient_id": "071d7551-8bef-45ef-9c43-9fca9dd2ecae", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "finely minced", "notes": "approx. 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "canned diced tomatoes", "quantity": 400, "unit": "g", "preparation": "with juices", "notes": "high quality canned tomatoes preferred", "substitutions": [], "ingredient_id": "0ba01b79-628f-4d68-be62-dab1fbbd087c", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh flat-leaf parsley", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pantry Staples", "items": [{"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": "extra virgin", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 3g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly ground, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Peel the Jerusalem artichokes thoroughly. If they are very knobby, cut off the knobs to make peeling easier. Slice them into rounds approximately 1cm thick.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Sunchokes oxidize (turn brown) quickly. Keep them in a bowl of water until ready to cook."]}, {"step_number": 2, "phase": "cook", "text": "Heat the olive oil in a large saut\u00e9 pan over medium-high heat (approx 190\u00b0C/375\u00b0F). Add the sliced Jerusalem artichokes and saut\u00e9 for 5-7 minutes until they begin to develop golden brown edges.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT7M", "doneness_cues": {"visual": "Golden brown edges on the tuber slices", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to medium. Add the minced garlic and saut\u00e9 for 30-60 seconds, stirring constantly until fragrant, being careful not to burn it.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Garlic is fragrant but not dark brown", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour in the canned diced tomatoes with their juices. Season generously with salt and freshly ground black pepper. Stir to combine.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Cover the pan, reduce heat to low, and simmer for 20-25 minutes. The sunchokes should be tender when pierced with a knife, similar to a cooked potato.", "structured": {"action": "SIMMER", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT25M", "doneness_cues": {"visual": null, "tactile": "Slices yield easily to a knife tip"}}, "tips": ["If the sauce becomes too thick before the vegetables are tender, add 2-3 tablespoons of water."]}, {"step_number": 6, "phase": "finish", "text": "Remove from heat. Stir in the chopped fresh parsley just before serving to maintain its bright color and flavor.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT25M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 200}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Nut-Free", "Soy-Free", "Paleo", "Whole30"], "not_suitable_for": []}', '{"per_serving": {"calories": 201.37, "protein_g": 4.28, "carbohydrates_g": 31.64, "fat_g": 7.77, "saturated_fat_g": 1.05, "trans_fat_g": null, "monounsaturated_fat_g": 5.49, "polyunsaturated_fat_g": 0.81, "fiber_g": 3.87, "sugar_g": 17.07, "sodium_mg": 304.94, "cholesterol_mg": null, "potassium_mg": 682.77, "calcium_mg": 34.33, "iron_mg": 5.47, "magnesium_mg": 28.75, "phosphorus_mg": 125.31, "zinc_mg": 0.27, "vitamin_a_mcg": 17.36, "vitamin_c_mg": 12.16, "vitamin_d_mcg": null, "vitamin_e_mg": 1.4, "vitamin_k_mcg": 66.64, "vitamin_b6_mg": 0.17, "vitamin_b12_mcg": null, "thiamin_mg": 0.31, "riboflavin_mg": 0.1, "niacin_mg": 2.03, "folate_mcg": 25.36, "water_g": 122.52, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors meld and improve overnight.", "duration": "P3D"}, "freezer": {"notes": "Texture of sunchokes may become slightly softer upon thawing.", "duration": "P2M"}, "reheating": "Gently reheat in a pan over medium heat until warmed through.", "does_not_keep": false}', '[{"name": "Large saut\u00e9 pan or skillet with lid", "required": true, "alternative": null}, {"name": "Vegetable peeler or paring knife", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Sunchokes are tough after cooking time", "likely_cause": "Slices were cut too thick or the variety is denser", "prevention": "Ensure uniform 1cm slicing during prep", "fix": "Add 50ml water, cover, and continue simmering for another 5-10 minutes"}]', '["Jerusalem artichokes have a high inulin content which can cause digestion issues for some; thorough cooking helps break this down.", "This dish pairs exceptionally well with roast lamb or grilled white fish.", "If you want to enhance the richness, a knob of butter added at the end (if not strictly vegan) adds a glossy sheen and velvety texture.", "For the ''Five Ingredient'' count, we assume pantry staples like oil, salt, and pepper are excluded from the count."]', '"Rooted in the rustic cooking of Provence, this dish highlights the ''topinambour,'' a tuber that gained popularity in France during WWII when potatoes were scarce. Today it is prized for its distinct artichoke-like flavor and is often paired with the region''s staple ingredients: garlic, tomatoes, and herbs."', 201.37);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('7f6b3f4d-5415-4f22-8c01-1be0a0071112', 'Classic New York Cheesecake', 'A quintessential New York-style cheesecake featuring a dense, velvety filling with a tangy richness, sitting atop a buttery, crisp digestive biscuit crust. The texture is smooth and creamy, avoiding the fluffiness of other styles.', 'dessert', 'American', 'Intermediate', '["cheesecake", "dessert", "baking", "new york style", "american", "classic"]', '[{"group_name": "Crust", "items": [{"name": "digestive biscuits", "quantity": 250, "unit": "g", "preparation": "crushed into fine crumbs", "notes": null, "substitutions": [], "ingredient_id": "8fc2188f-4a8f-4ada-a35b-d02fdd09f47b", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "melted", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Filling", "items": [{"name": "full-fat cream cheese", "quantity": 900, "unit": "g", "preparation": "room temperature", "notes": "softened completely", "substitutions": [], "ingredient_id": "262c67de-76a4-4444-8c02-30ad4a179459", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 275, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "sour cream", "quantity": 240, "unit": "g", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "d171100e-1088-4266-8d50-06cdedda7193", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 30, "unit": "g", "preparation": null, "notes": "or all-purpose flour", "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "03fb65be-9b62-44e7-a121-694de64cdec0", "nutrition_source": "Aggregated Public Data"}, {"name": "eggs", "quantity": 4, "unit": null, "preparation": "large, room temperature", "notes": "approx 200g total (weighed without shell)", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 175\u00b0C (350\u00b0F). Line the bottom of a 23cm (9-inch) springform pan with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Mix the digestive biscuit crumbs, melted butter, and salt in a bowl until the mixture resembles wet sand.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Press the crumb mixture firmly into the bottom of the prepared pan (and slightly up the sides if desired). Use the bottom of a flat glass to compact it.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Bake the crust for 10 minutes at 175\u00b0C (350\u00b0F) until set and fragrant. Remove and let cool while preparing the filling.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Increase oven temperature to 230\u00b0C (450\u00b0F) briefly, or reduce to 160\u00b0C (320\u00b0F) for the main bake (see cooking steps below). Double-wrap the outside of the springform pan with heavy-duty aluminum foil to water-proof it for the water bath.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "In a large bowl, beat the room temperature cream cheese and cornstarch on medium-low speed until creamy and smooth. Scrape down the bowl.", "structured": {"action": "BEAT", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": ["Do not overmix or use high speed, which adds air bubbles and leads to cracks."]}, {"step_number": 7, "phase": "prep", "text": "Add the sugar, sour cream, vanilla extract, and lemon zest. Mix on low speed until fully incorporated and smooth.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "prep", "text": "Add the eggs one at a time, mixing on the lowest speed just until each egg is incorporated. Stop immediately once the last egg disappears.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Overbeating eggs incorporates air, which causes the cheesecake to rise and then collapse/crack."]}, {"step_number": 9, "phase": "cook", "text": "Pour the batter over the cooled crust. Place the foil-wrapped springform pan into the large roasting pan.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "cook", "text": "Pour boiling water into the roasting pan until it reaches halfway up the sides of the springform pan.", "structured": {"action": "BOIL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 11, "phase": "cook", "text": "Bake at 160\u00b0C (320\u00b0F) for 60 to 75 minutes. The edges should be set, but the center should still wobble slightly like Jell-O.", "structured": {"action": "BAKE", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT1H10M", "doneness_cues": {"visual": "Edges puffed and set, center wobbles gently", "tactile": "Surface looks matte, not wet"}}, "tips": []}, {"step_number": 12, "phase": "finish", "text": "Turn off the oven and crack the door open slightly (prop with a wooden spoon). Let the cheesecake cool inside the humid oven for 1 hour.", "structured": {"action": "COOL", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 13, "phase": "finish", "text": "Remove from the water bath and run a thin knife around the edge to release it from the pan. Cool completely at room temperature, then refrigerate for at least 6 hours (preferably overnight).", "structured": {"action": "CHILL", "temperature": null, "duration": "PT6H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT9H", "total_time": "PT9H45M", "overnight_required": true, "yields": "12 slices", "yield_count": 12, "serving_size_g": 165}', '{"flags": ["Vegetarian"], "not_suitable_for": ["Vegans", "Lactose intolerant", "Gluten intolerant"]}', '{"per_serving": {"calories": 581.78, "protein_g": 9.16, "carbohydrates_g": 43.7, "fat_g": 42, "saturated_fat_g": 22.01, "trans_fat_g": 0.88, "monounsaturated_fat_g": 10.23, "polyunsaturated_fat_g": 1.81, "fiber_g": 0.81, "sugar_g": 29.05, "sodium_mg": 581.73, "cholesterol_mg": 166.15, "potassium_mg": 152.14, "calcium_mg": 105.57, "iron_mg": 0.41, "magnesium_mg": 11.14, "phosphorus_mg": 134.92, "zinc_mg": 0.7, "vitamin_a_mcg": 343.62, "vitamin_c_mg": 0.18, "vitamin_d_mcg": 0.37, "vitamin_e_mg": 1.11, "vitamin_k_mcg": 2.42, "vitamin_b6_mg": 0.08, "vitamin_b12_mcg": 0.39, "thiamin_mg": 0.03, "riboflavin_mg": 0.29, "niacin_mg": 0.1, "folate_mcg": 17.07, "water_g": 70.37, "alcohol_g": 0.29, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container or loosely covered with foil to prevent condensation.", "duration": "P5D"}, "freezer": {"notes": "Freeze whole or in slices, wrapped tightly in plastic wrap and foil. Thaw in refrigerator overnight.", "duration": "P1M"}, "reheating": null, "does_not_keep": false}', '[{"name": "23cm (9-inch) Springform pan", "required": true, "alternative": null}, {"name": "Electric mixer (stand or hand)", "required": true, "alternative": "Whisk and strong arm"}, {"name": "Large roasting pan", "required": true, "alternative": "Any baking dish larger than the springform pan (for water bath)"}, {"name": "Aluminum foil", "required": true, "alternative": null}, {"name": "Food processor", "required": false, "alternative": "Ziploc bag and rolling pin"}, {"name": "Rubber spatula", "required": true, "alternative": null}]', '[{"symptom": "Cheesecake has a large crack on top", "likely_cause": "Overmixing the batter or cooling too quickly", "prevention": "Mix on low speed, do not overbeat eggs, and cool slowly in the oven with the door cracked", "fix": "Cover with a topping like sour cream glaze, fruit compote, or ganache"}, {"symptom": "Water leaked into the crust", "likely_cause": "Foil wrapping was insufficient", "prevention": "Use heavy-duty foil or place the springform pan inside a slightly larger cake pan, then place that in the water bath", "fix": "Cannot be fixed; the crust will be soggy but the filling is still edible"}]', '["Room temperature ingredients are non-negotiable. Cold cream cheese causes lumps that you can''t mix out without overworking the batter.", "The water bath (bain-marie) regulates the heat, keeping the baking gentle and even, which gives the cheesecake its signature creamy, non-chalky texture.", "Do not open the oven door during the first 45 minutes of baking, as sudden temperature drops can cause the cake to sink."]', '"The New York cheesecake is distinct from its Italian ricotta-based cousin, characterized by its heavy use of cream cheese and extra egg yolks or cream for a denser, richer texture. It became a staple of NYC deli culture in the early 20th century, with famous establishments like Junior''s setting the standard for this indulgent classic."', 581.78);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('7fc7bc26-d2d4-4e2f-a1e9-2c9a9a7397f2', 'Baked Potatoes with Caramelized Onions and Sorrel', 'Crisp-skinned, fluffy baked potatoes crowned with a sweet and tart compote. The deep, rich sweetness of slow-cooked caramelized onions provides a perfect counterpoint to the bright, lemony acidity of fresh spring sorrel.', 'side dish', 'French', 'Intermediate', '["potato", "sorrel", "side dish", "spring", "gluten-free", "nut-free", "vegetarian", "french"]', '[{"group_name": "Potatoes", "items": [{"name": "russet potatoes", "quantity": 4, "unit": null, "preparation": "scrubbed and dried", "notes": "large, approx. 250-300g each", "substitutions": [], "ingredient_id": "a7db25be-476c-48fe-8cb8-2ea66fb91587", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Topping", "items": [{"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onions", "quantity": 2, "unit": null, "preparation": "thinly sliced", "notes": "approx. 400g total", "substitutions": [], "ingredient_id": "cc868876-7ceb-46a8-b72a-c3e8a743ee97", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh sorrel leaves", "quantity": 100, "unit": "g", "preparation": "washed, stems removed, torn", "notes": "approx. 1 large bunch", "substitutions": [], "ingredient_id": "765ed343-bfc0-4671-9d31-fb127e371872", "nutrition_source": "Aggregated Public Data"}, {"name": "cr\u00e8me fra\u00eeche", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e521696c-b719-4569-b7f8-ec0b97abd492", "nutrition_source": "Aggregated Public Data"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly ground, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 200\u00b0C/400\u00b0F. Prick the scrubbed potatoes all over with a fork to allow steam to escape.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Rub the potatoes with olive oil and sprinkle generously with sea salt. Place directly on the oven rack (with a baking sheet on the rack below to catch drips) or on a baking sheet. Bake for 60 minutes or until the skin is crisp and the inside is tender.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT1H", "doneness_cues": {"visual": "Skin is papery and crisp", "tactile": "Soft when squeezed"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "While potatoes bake, melt the butter in a heavy-bottomed skillet over medium-low heat. Add the sliced onions and a pinch of salt.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 140, "fahrenheit": 284}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Cook the onions slowly, stirring occasionally, until they are deep golden brown and very soft. This process should take about 25 to 30 minutes. If they brown too quickly, lower the heat.", "structured": {"action": "CARAMELIZE", "temperature": null, "duration": "PT30M", "doneness_cues": {"visual": "Deep golden brown color", "tactile": "Soft and jammy texture"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Once the potatoes are ready, remove them from the oven. Carefully slice them open lengthwise and fluff the insides with a fork.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Return the skillet with onions to medium heat. Add the torn sorrel leaves and cook for just 1-2 minutes until wilted. The sorrel will change from bright green to an olive color; this is normal.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Leaves wilted and olive-green", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Stir in the cr\u00e8me fra\u00eeche (if using) and season with black pepper. Immediately spoon the onion-sorrel mixture over the hot, split potatoes and serve.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT1H", "total_time": "PT1H25M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 320}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 422.4, "protein_g": 7.71, "carbohydrates_g": 59.3, "fat_g": 18.31, "saturated_fat_g": 9.44, "trans_fat_g": null, "monounsaturated_fat_g": 5.37, "polyunsaturated_fat_g": 0.85, "fiber_g": 6.37, "sugar_g": 7.78, "sodium_mg": 509.46, "cholesterol_mg": 24.19, "potassium_mg": 1327.25, "calcium_mg": 85.59, "iron_mg": 2.81, "magnesium_mg": 65.2, "phosphorus_mg": 163.15, "zinc_mg": 0.81, "vitamin_a_mcg": 421.99, "vitamin_c_mg": 35.92, "vitamin_d_mcg": null, "vitamin_e_mg": 0.83, "vitamin_k_mcg": 8.2, "vitamin_b6_mg": 0.94, "vitamin_b12_mcg": 0.02, "thiamin_mg": 0.22, "riboflavin_mg": 0.09, "niacin_mg": 2.87, "folate_mcg": 38.86, "water_g": 217.99, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store potatoes and topping separately if possible.", "duration": "P3D"}, "freezer": {"notes": "Baked potatoes do not freeze well; texture becomes grainy.", "duration": null}, "reheating": "Reheat potatoes in a 180\u00b0C/350\u00b0F oven for 15 minutes. Gently warm the onion mixture in a pan.", "does_not_keep": false}', '[{"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Heavy-bottomed skillet", "required": true, "alternative": "Cast iron pan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Fork", "required": true, "alternative": null}]', '[{"symptom": "Onions are burning before caramelizing", "likely_cause": "Heat is too high or pan has hot spots", "prevention": "Use a heavy pan and keep heat low; add a splash of water if sticking", "fix": "Remove from heat immediately, add a tablespoon of water, stir, and return to very low heat"}, {"symptom": "Sorrel turned completely mushy and grey", "likely_cause": "Overcooked", "prevention": "Sorrel wilts instantly; add it only right before serving", "fix": "Cannot be fixed, but flavor will still be good (sour)"}]', '["Sorrel is naturally very tart due to oxalic acid. Taste your mixture before adding extra salt, as the acidity can enhance saltiness perception.", "If you cannot find fresh sorrel, baby spinach mixed with lemon zest and a squeeze of lemon juice makes a passable alternative.", "For the fluffiest potato texture, drop the baked potatoes from a height of 10cm onto the counter before cutting them open; this helps break up the starch structure.", "Do not wrap the potatoes in foil for baking; foil traps steam and results in a soggy skin rather than a crisp one."]', '"The combination of sorrel (oseille) and cream is a cornerstone of classic French countryside cooking, famously used in ''Saumon \u00e0 l''oseille'' by the Troisgros brothers. This dish adapts that flavor profile to a humble rustic staple, celebrating the arrival of spring greens."', 422.4);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('80619a41-5190-40a6-9e00-ca22d45ae52a', 'Soy-Glazed Brown Butter Brussels Sprout Spaghetti', 'An indulgent umami bomb that transforms humble ingredients into a restaurant-quality meal. Nutty browned butter and salty soy sauce create a glossy emulsion that clings to shredded, deeply caramelized Brussels sprouts and al dente spaghetti. A squeeze of lemon cuts through the richness.', 'dinner', 'Fusion', 'Easy', '["brussels sprout", "spaghetti", "soy sauce", "butter", "pastas", "lunch", "dinner", "vegetarian", "easy", "budget", "fusion", "comfort food"]', '[{"group_name": "Pasta", "items": [{"name": "spaghetti", "quantity": 400, "unit": "g", "preparation": "dry", "notes": "Standard or thick spaghetti works best", "substitutions": [], "ingredient_id": "8f9d3063-4bf0-46dc-9f13-5f49cd92d47d", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 4000, "unit": "ml", "preparation": "boiling", "notes": "For cooking pasta", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 25, "unit": "g", "preparation": null, "notes": "For pasta water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables & Aromatics", "items": [{"name": "brussels sprouts", "quantity": 450, "unit": "g", "preparation": "shredded or thinly sliced", "notes": "Trim ends before slicing", "substitutions": [], "ingredient_id": "2ee7388c-3256-477d-8d05-4ce09df9d8f1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx. 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Brown Butter Soy Sauce", "items": [{"name": "unsalted butter", "quantity": 85, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "soy sauce", "quantity": 45, "unit": "ml", "preparation": null, "notes": "Low sodium preferred", "substitutions": [], "ingredient_id": "1a157828-0624-4e67-815d-8e6bdf8b23c2", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "red pepper flakes", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "Freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Garnish", "items": [{"name": "parmesan cheese", "quantity": 40, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Bring a large pot of water to a boil and season heavily with salt (it should taste like the ocean). While water heats, trim the hard stems off the Brussels sprouts and slice them very thinly (shaved style) using a knife or mandoline.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add spaghetti to boiling water. Cook until just shy of al dente (about 1-2 minutes less than package directions), as it will finish cooking in the sauce. Reserve 250ml (1 cup) of starchy pasta water before draining.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "While pasta cooks, heat olive oil in a large skillet over medium-high heat. Add shredded Brussels sprouts in an even layer. Let them sit undisturbed for 2 minutes to char, then saut\u00e9 for another 3-4 minutes until tender and deeply caramelized. Remove sprouts from the pan and set aside.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT6M", "doneness_cues": {"visual": "Deep brown char on edges", "tactile": "Tender but not mushy"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Reduce heat to medium. Add the cubed butter to the now-empty skillet. Cook, swirling the pan occasionally, until the butter foams, then subsides, and the milk solids turn a golden hazelnut brown. Immediately add minced garlic and red pepper flakes (if using) and cook for 30 seconds until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Golden brown milk solids", "tactile": "Foaming subsides"}}, "tips": ["Watch the butter closely; it goes from browned to burnt in seconds."]}, {"step_number": 5, "phase": "assemble", "text": "Add the soy sauce to the browned butter (it will bubble vigorously). Add the drained pasta and the reserved cooked Brussels sprouts to the pan. Toss vigorously with tongs.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Pour in about 60-80ml of the reserved pasta water. Continue tossing over low heat until the butter and water emulsify into a glossy sauce that clings to the noodles. Add more pasta water if the mixture looks dry. Stir in lemon juice.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Serve immediately, garnished with generous amounts of freshly cracked black pepper and grated parmesan cheese if desired.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT10M", "total_time": "PT30M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 375}', '{"flags": ["Vegetarian", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 659.47, "protein_g": 21.59, "carbohydrates_g": 88.23, "fat_g": 25.6, "saturated_fat_g": 13.08, "trans_fat_g": null, "monounsaturated_fat_g": 8.51, "polyunsaturated_fat_g": 1.34, "fiber_g": 7.32, "sugar_g": 5.03, "sodium_mg": 3372.91, "cholesterol_mg": 52.49, "potassium_mg": 752.98, "calcium_mg": 222.66, "iron_mg": 2.97, "magnesium_mg": 99.38, "phosphorus_mg": 351.1, "zinc_mg": 1.86, "vitamin_a_mcg": 219.27, "vitamin_c_mg": 98.63, "vitamin_d_mcg": 0.05, "vitamin_e_mg": 2.21, "vitamin_k_mcg": 203.92, "vitamin_b6_mg": 0.34, "vitamin_b12_mcg": 0.16, "thiamin_mg": 0.18, "riboflavin_mg": 0.17, "niacin_mg": 1.26, "folate_mcg": 72.86, "water_g": 1116.59, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Reheat gently with a splash of water to loosen the butter sauce.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; emulsion may break and sprouts will lose texture.", "duration": null}, "reheating": "Pan-fry over medium heat for best texture, or microwave.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": "Wok"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Sauce is greasy or oily and not clinging to pasta", "likely_cause": "Broken emulsion due to insufficient water or lack of agitation", "prevention": "Ensure pasta water is starchy and toss vigorously", "fix": "Add another splash of hot pasta water and toss rapidly over high heat to re-emulsify"}, {"symptom": "Butter tastes acrid and bitter", "likely_cause": "Butter was burned rather than browned", "prevention": "Remove from heat immediately when it smells nutty and solids turn golden", "fix": "Cannot be fixed; discard butter and start that step over"}]', '["Shredding the Brussels sprouts allows them to cook very quickly and integrate with the pasta strands, ensuring you get a bit of vegetable in every bite.", "Do not skip the lemon juice; the acidity is necessary to cut through the richness of the butter and the salinity of the soy sauce.", "If you want extra protein, a fried egg with a runny yolk placed on top makes this even more indulgent."]', '"This dish exemplifies modern fusion comfort food, marrying the Italian technique of ''pasta al burro'' (butter pasta) with the East Asian flavor profile of soy sauce (shoyu). While ''Wafu'' pasta (Japanese-style pasta) has existed since the 1950s in Tokyo, this specific combination leans on the universal appeal of umami-rich browned butter paired with cruciferous vegetables."', 659.47);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('81f0a3f5-9127-41e9-879b-2a161bd70a8e', 'Alsatian Slow-Roasted Duck with Riesling Sauerkraut', 'A rustic yet elegant centerpiece featuring a whole duck with shatteringly crisp skin and tender meat, roasted directly over a bed of aromatic sauerkraut. The duck fat renders down into the fermented cabbage, apples, and Riesling, creating a luxurious, tangy, and deeply savory accompaniment.', 'dinner', 'French', 'Intermediate', '["duck", "sauerkraut", "dinner", "fall", "winter", "dairy-free", "gluten-free", "nut-free", "french", "sunday roast"]', '[{"group_name": "Duck", "items": [{"name": "whole duck", "quantity": 1, "unit": null, "preparation": "thawed, giblets removed", "notes": "approx. 2.2kg - 2.5kg", "substitutions": [], "ingredient_id": "13478315-8da6-4268-be1a-d8928a6500e3", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 15, "unit": "g", "preparation": "coarse", "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 5, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sauerkraut Base", "items": [{"name": "raw sauerkraut", "quantity": 1000, "unit": "g", "preparation": "drained", "notes": null, "substitutions": [], "ingredient_id": "d1d39781-bb71-40b2-b9fe-e8b934a4fdcc", "nutrition_source": "USDA FoodData Central"}, {"name": "duck fat", "quantity": 30, "unit": "g", "preparation": null, "notes": "or olive oil", "substitutions": [], "ingredient_id": "f11d095a-3279-472e-b30f-865d6418e103", "nutrition_source": "Aggregated Public Data"}, {"name": "yellow onion", "quantity": 2, "unit": null, "preparation": "thinly sliced", "notes": "approx. 300g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "granny smith apples", "quantity": 2, "unit": null, "preparation": "peeled, cored, and sliced", "notes": "approx. 300g", "substitutions": [], "ingredient_id": "9985672b-aa9f-4125-8a32-62d520c99d6f", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "smashed", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Braising Liquid & Aromatics", "items": [{"name": "dry riesling", "quantity": 350, "unit": "ml", "preparation": null, "notes": "Alsatian preferred", "substitutions": [], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "chicken stock", "quantity": 150, "unit": "ml", "preparation": null, "notes": "unsalted, gluten-free", "substitutions": [], "ingredient_id": "7e254f45-046f-4812-bcdd-7e31c9bb59b8", "nutrition_source": "Aggregated Public Data"}, {"name": "juniper berries", "quantity": 10, "unit": null, "preparation": null, "notes": "slightly crushed", "substitutions": [], "ingredient_id": "bbd559c9-41f8-4b18-8c45-8836fdfbd280", "nutrition_source": "Aggregated Public Data"}, {"name": "caraway seeds", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5fb07424-aa49-4da5-afeb-0636713c313f", "nutrition_source": "USDA FoodData Central"}, {"name": "bay leaves", "quantity": 2, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 4, "unit": null, "preparation": null, "notes": "sprigs", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "The day before (recommended): Remove the duck from packaging and pat thoroughly dry with paper towels. Prick the skin all over with a sharp needle or knife tip, focusing on fatty areas (breast and thighs), being careful not to pierce the meat. Season generously with salt inside and out. Place uncovered in the refrigerator overnight to dry the skin.", "structured": {"action": "CURE", "temperature": null, "duration": "P1D", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Preheat your oven to 160\u00b0C (320\u00b0F). If you did not dry-brine overnight, prick and season the duck now, letting it stand at room temperature for 30 minutes. Rinse the sauerkraut in cold water and drain well in a colander to remove excess brine.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a large roasting pan placed on the stovetop over medium heat, melt the duck fat. Add sliced onions and saut\u00e9 for 5-8 minutes until softened and translucent.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the apple slices, garlic, juniper berries, caraway seeds, bay leaves, and thyme. Cook for another 2 minutes until fragrant. Stir in the drained sauerkraut, then pour in the Riesling and chicken stock. Spread this mixture evenly across the bottom of the pan.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Place a roasting rack directly over the sauerkraut mixture. Place the duck, breast side up, on the rack. (The duck should not be submerged; it should sit above the kraut so the fat renders down into it).", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Roast in the center of the oven for approximately 2 hours. Halfway through, gently stir the sauerkraut underneath to prevent burning at the edges. Pierce the leg joint to check doneness; juices should run clear, or internal temperature of the thickest part of the thigh should reach 74\u00b0C (165\u00b0F).", "structured": {"action": "ROAST", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT2H", "doneness_cues": {"visual": "Skin golden, juices run clear", "tactile": "Leg joint moves freely"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Increase oven temperature to 220\u00b0C (425\u00b0F). Roast for an additional 15-20 minutes to deeply brown and crisp the skin. Watch closely to prevent burning.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT20M", "doneness_cues": {"visual": "Skin is deep amber and crispy", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove the duck from the oven and transfer to a cutting board. Rest for at least 20 minutes before carving. Meanwhile, taste the sauerkraut. If it is too dry, add a splash of water or stock. If it is too liquid, simmer on the stovetop to reduce.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT2H30M", "total_time": "PT3H15M", "overnight_required": true, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Dairy-Free", "Gluten-Free", "Nut-Free", "Paleo", "Low-Carb"], "not_suitable_for": []}', '{"per_serving": {"calories": 1147.84, "protein_g": 114.92, "carbohydrates_g": 55.78, "fat_g": 36.07, "saturated_fat_g": 11.16, "trans_fat_g": null, "monounsaturated_fat_g": 4.31, "polyunsaturated_fat_g": 4, "fiber_g": 11.75, "sugar_g": 17.3, "sodium_mg": 4060.32, "cholesterol_mg": 3025.63, "potassium_mg": 2033.81, "calcium_mg": 197.98, "iron_mg": 183.99, "magnesium_mg": 194.49, "phosphorus_mg": 1677.15, "zinc_mg": 18.85, "vitamin_a_mcg": 70512.6, "vitamin_c_mg": 76.02, "vitamin_d_mcg": null, "vitamin_e_mg": 0.55, "vitamin_k_mcg": 36.55, "vitamin_b6_mg": 4.96, "vitamin_b12_mcg": 317.25, "thiamin_mg": 3.41, "riboflavin_mg": 5.34, "niacin_mg": 38.8, "folate_mcg": 4413.35, "water_g": 787.12, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store duck meat removed from the bone. Flavor of sauerkraut improves after 24 hours.", "duration": "P3D"}, "freezer": {"notes": "Sauerkraut freezes well; duck meat texture may degrade slightly upon thawing.", "duration": "P2M"}, "reheating": "Reheat sauerkraut in a pot. Crisp duck skin under a broiler or in a hot pan before serving.", "does_not_keep": false}', '[{"name": "Large roasting pan with rack", "required": true, "alternative": "Large Dutch oven with vegetables acting as a rack"}, {"name": "Sharp knife or needle", "required": true, "alternative": "Skewer"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Sieve or colander", "required": true, "alternative": null}]', '[{"symptom": "Duck skin is flabby or chewy", "likely_cause": "Insufficient fat rendering or humidity in the oven was too high", "prevention": "Ensure skin is thoroughly pricked and dry-brined overnight", "fix": "Remove duck from the roasting rack, place on a clean baking sheet, and broil (grill) for 2-4 minutes under high heat, watching constantly."}]', '["Pricking the skin is the most critical step. You must pierce the skin and fat layer without penetrating the meat, or juices will escape and dry out the bird.", "If the sauerkraut becomes too greasy from the rendered duck fat, use a ladle to skim the excess fat from the surface of the pan before serving. Save this ''liquid gold'' for roasting potatoes later.", "For the wine, select a dry Alsatian Riesling or a Gew\u00fcrztraminer. Avoid sweet wines, as the apples already provide natural sweetness.", "Always check the ingredients on your sauerkraut. For this recipe, raw fermented sauerkraut from the refrigerated section is superior to canned versions."]', '"This dish is inspired by Choucroute Garnie, the emblematic dish of Alsace, a region straddling France and Germany. While the traditional version features various cuts of pork and sausages, using duck (specifically locally raised waterfowl) is a luxurious variation found in Strasbourg''s finer winstubs, highlighting the region''s love for fruit, fermentation, and game birds."', 1147.84);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('837bb72a-d998-4a6a-9faa-ae02c6bf0cda', 'Microwave-Steamed Black Cod with Ginger and Scallions', 'A rapid yet refined preparation that highlights the buttery, velvet texture of black cod (sablefish). Steam-cooking in the microwave preserves delicate moisture, while fresh ginger and scallions provide a classic Cantonese-style aromatic finish.', 'dinner', 'Chinese', 'Easy', '["fish", "soy sauce", "white wine", "dinner", "easy", "quick", "main course", "healthy", "microwave"]', '[{"group_name": "Fish", "items": [{"name": "black cod fillets", "quantity": 340, "unit": "g", "preparation": "skin-on or off", "notes": "two 170g portions", "substitutions": ["sea bass", "halibut", "cod"], "ingredient_id": "229ccaef-c763-440b-b44f-6e22222d3fd1", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "fine sea salt", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["shaoxing wine", "sake"], "ingredient_id": "0c041362-befe-4c15-88d2-ba97c8f46428", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics", "items": [{"name": "fresh ginger", "quantity": 15, "unit": "g", "preparation": "peeled and julienned", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "scallions", "quantity": 2, "unit": null, "preparation": "julienned", "notes": "about 30g total, green parts separated", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing Sauce", "items": [{"name": "soy sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": "light soy sauce preferred", "substitutions": ["tamari (for gluten-free)"], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "toasted sesame oil", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8fa9dd65-c49e-449c-b660-a9d9deb638b2", "nutrition_source": "Aggregated Public Data"}, {"name": "sugar", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "white pepper", "quantity": null, "unit": null, "preparation": null, "notes": "1 pinch", "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 15, "unit": "ml", "preparation": null, "notes": "hot", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the black cod fillets dry with paper towels. Season lightly with salt on both sides. Place the fish on a microwave-safe plate.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Scatter the julienned ginger and the white parts of the scallions over and around the fish. Drizzle the dry white wine over the fillets.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Cover the plate tightly with microwave-safe plastic wrap (poke two small holes for steam vent) or a fitted microwave cover. Microwave on high for 3 to 4 minutes. The fish should be opaque and flake easily with a fork. Aim for an internal temperature of 60\u00b0C/140\u00b0F for optimal texture, or 63\u00b0C/145\u00b0F for FDA safety standards.", "structured": {"action": "STEAM", "temperature": {"celsius": 63, "fahrenheit": 145}, "duration": "PT3M", "doneness_cues": {"visual": "Opaque and flakes easily", "tactile": "Firm but yielding"}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "While the fish cooks, combine soy sauce, hot water, sugar, white pepper, and toasted sesame oil in a small bowl. Stir until the sugar dissolves.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Carefully remove the plate from the microwave (caution: hot steam). Tilt the plate gently to drain and discard the cloudy cooking liquid, which can taste overly fishy. Top with the reserved green scallion parts and pour the sauce mixture over the fish. Serve immediately.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT0M", "total_time": "PT10M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 225}', '{"flags": ["Pescatarian", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 196.61, "protein_g": 30.93, "carbohydrates_g": 7.31, "fat_g": 3.81, "saturated_fat_g": 0.62, "trans_fat_g": null, "monounsaturated_fat_g": 0.17, "polyunsaturated_fat_g": 0.41, "fiber_g": 0.68, "sugar_g": 4.03, "sodium_mg": 2808.39, "cholesterol_mg": 73.1, "potassium_mg": 774.95, "calcium_mg": 40.27, "iron_mg": 0.95, "magnesium_mg": 60.94, "phosphorus_mg": 353.64, "zinc_mg": 0.86, "vitamin_a_mcg": 27.9, "vitamin_c_mg": 4.95, "vitamin_d_mcg": 1.53, "vitamin_e_mg": 1.2, "vitamin_k_mcg": 31.23, "vitamin_b6_mg": 0.43, "vitamin_b12_mcg": 1.55, "thiamin_mg": 0.14, "riboflavin_mg": 0.13, "niacin_mg": 3.64, "folate_mcg": 22.35, "water_g": 170.92, "alcohol_g": 0.67, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Texture degrades upon reheating; best consumed immediately.", "duration": "P2D"}, "freezer": {"notes": "Do not freeze cooked fish.", "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Microwave-safe plate", "required": true, "alternative": null}, {"name": "Microwave-safe cover or plastic wrap", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}]', '[{"symptom": "Fish edges are dry or rubbery", "likely_cause": "Overcooking due to high microwave wattage or thin fillets", "prevention": "Check doneness at the 2:30 or 3:00 minute mark; microwaves vary significantly in power", "fix": "Trim the dry edges and serve the moist center with extra sauce"}]', '["Black cod has a very high oil content, making it forgiving to cook, but standard cod or halibut are much leaner; reduce cooking time by 30-60 seconds if using leaner white fish.", "For the julienne ginger, peeling with a spoon removes the skin without wasting the flesh. Slice into thin coins first, then stack and slice into matchsticks.", "Draining the cooking liquid after microwaving is a crucial step often skipped by beginners; this liquid contains albumin and strong proteins that muddy the flavor of the final sauce.", "If you prefer a more traditional presentation, heat a tablespoon of neutral oil until smoking and pour it over the scallions at the very end to release their aroma."]', '"Steam-cooking fish is a cornerstone of Cantonese cuisine, prized for showcasing the freshness of ingredients. While traditional methods use bamboo steamers over a wok, the microwave essentially acts as a hyper-efficient steam chamber, heating the water molecules within the fish to cook it gently from the inside out."', 196.61);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('838e1e43-8f54-4cdf-9ce8-129097ff1c53', 'Earl Grey & Cardamom Pancakes with Tahini Cream', 'Aromatic, fluffy pancakes infused with the floral notes of Earl Grey tea and warming cardamom, topped with a nutty, tangy tahini-honey yoghurt sauce and bright seasonal fruits.', 'breakfast', 'Fusion', 'Intermediate', '["pancakes", "tahini", "honey", "fruit", "dessert", "breakfast", "fusion", "vegetarian"]', '[{"group_name": "Tea Infusion", "items": [{"name": "whole milk", "quantity": 320, "unit": "ml", "preparation": null, "notes": "Extra volume accounts for absorption by tea bags", "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "earl grey tea bags", "quantity": 4, "unit": null, "preparation": null, "notes": "High quality double-bergamot preferred", "substitutions": [], "ingredient_id": "e80c983d-af63-4651-9b91-503e1ece8450", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dry Ingredients", "items": [{"name": "all-purpose flour", "quantity": 250, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cardamom", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c56f6cd8-882c-487c-956f-3a91ee1fec07", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wet Ingredients", "items": [{"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": "melted and cooled", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": null}, {"name": "large egg", "quantity": 1, "unit": null, "preparation": "room temperature", "notes": "approx 50g without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 10, "unit": "g", "preparation": "solid", "notes": "For greasing the pan", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": null}]}, {"group_name": "Tahini Yoghurt & Toppings", "items": [{"name": "greek yoghurt", "quantity": 200, "unit": "g", "preparation": "thick, plain", "notes": null, "substitutions": [], "ingredient_id": "976f2817-172a-4fad-bfd8-c1ba8612eb01", "nutrition_source": "USDA FoodData Central"}, {"name": "tahini", "quantity": 60, "unit": "g", "preparation": "well-stirred, runny", "notes": null, "substitutions": [], "ingredient_id": "87ae6455-8e22-4c1b-bad7-89fa69c4dc57", "nutrition_source": "Aggregated Public Data"}, {"name": "honey", "quantity": 40, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh figs", "quantity": 4, "unit": null, "preparation": "quartered", "notes": "Substitute with strawberries or peaches if out of season", "substitutions": [], "ingredient_id": "c2c3cba0-d600-4d4c-9400-a800b4a6c408", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Heat the milk in a small saucepan over medium heat until it begins to steam (approx. 80\u00b0C/175\u00b0F). Do not boil. Remove from heat, add tea bags, cover, and let steep for 10-15 minutes.", "structured": {"action": "SIMMER", "temperature": {"celsius": 80, "fahrenheit": 176}, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Squeeze the tea bags firmly to extract the flavorful liquid and tannins, then discard bags. Measure 300ml of the infused milk. If the volume is low due to evaporation, top up with plain milk. Let cool to lukewarm.", "structured": {"action": "MEASURE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Cooling is crucial; hot milk will scramble the egg in the batter."]}, {"step_number": 3, "phase": "prep", "text": "In a medium bowl, whisk together the Greek yoghurt, tahini, honey, and lemon juice until smooth and creamy. Set aside in the refrigerator.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In a large bowl, whisk together the flour, sugar, baking powder, baking soda, cardamom, cinnamon, and salt until evenly combined.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Whisk the melted butter, egg, and vanilla into the cooled tea-infused milk. Pour this wet mixture into the dry ingredients. Stir gently with a spatula only until the flour streaks disappear. The batter should be thick and slightly lumpy.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": {"visual": "Lumpy batter with no dry flour pockets", "tactile": "Thick consistency"}}, "tips": ["Do not overmix, or the pancakes will become rubbery."]}, {"step_number": 6, "phase": "cook", "text": "Heat a non-stick pan over medium-low heat (approx 175\u00b0C/350\u00b0F). Lightly grease with a small amount of butter. Pour 60ml (1/4 cup) portions of batter into the pan. Cook until bubbles appear on the surface and pop.", "structured": {"action": "FRY", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT3M", "doneness_cues": {"visual": "Bubbles on surface, golden edges", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Flip carefully and cook the other side until golden brown and cooked through, about 1-2 minutes more.", "structured": {"action": "FRY", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Golden brown underside", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Plate a stack of 3 warm pancakes. Dollop generously with the tahini yoghurt sauce and top with fresh figs. Drizzle with extra honey if desired.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT20M", "total_time": "PT45M", "overnight_required": false, "yields": "12 pancakes", "yield_count": 4, "serving_size_g": 270}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Infants under 12 months (honey)", "Vegans (dairy, eggs, honey)", "Gluten-Free diets"]}', '{"per_serving": {"calories": 621.66, "protein_g": 19.25, "carbohydrates_g": 82.34, "fat_g": 24.68, "saturated_fat_g": 10.17, "trans_fat_g": 0.01, "monounsaturated_fat_g": 4.87, "polyunsaturated_fat_g": 1.23, "fiber_g": 6.16, "sugar_g": 28.74, "sodium_mg": 820.1, "cholesterol_mg": 85.19, "potassium_mg": 478.63, "calcium_mg": 450.54, "iron_mg": 3.18, "magnesium_mg": 88.1, "phosphorus_mg": 370.63, "zinc_mg": 2.01, "vitamin_a_mcg": 134.82, "vitamin_c_mg": 0.71, "vitamin_d_mcg": 1.29, "vitamin_e_mg": 0.51, "vitamin_k_mcg": 1.41, "vitamin_b6_mg": 0.12, "vitamin_b12_mcg": 0.87, "thiamin_mg": 0.13, "riboflavin_mg": 0.37, "niacin_mg": 1.01, "folate_mcg": 29.44, "water_g": 136.17, "alcohol_g": 0.43, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store pancakes and sauce in separate airtight containers.", "duration": "P3D"}, "freezer": {"notes": "Freeze cooked pancakes with parchment paper between layers.", "duration": "P2M"}, "reheating": "Toaster or oven at 175\u00b0C/350\u00b0F for 5 minutes.", "does_not_keep": false}', '[{"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Medium mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Non-stick frying pan or griddle", "required": true, "alternative": null}, {"name": "Spatula", "required": true, "alternative": null}]', '[{"symptom": "Pancakes are tough and rubbery", "likely_cause": "The batter was overmixed, developing too much gluten", "prevention": "Stop stirring the moment the dry flour streaks disappear; lumps are normal", "fix": "Cannot be fixed once cooked; serve with extra sauce to mask texture"}, {"symptom": "Pancakes are burnt outside but raw inside", "likely_cause": "Heat was too high", "prevention": "Lower heat to medium-low and let the pan stabilize before cooking", "fix": "Finish the undercooked pancakes in a 175\u00b0C/350\u00b0F oven for 3-5 minutes"}]', '["Steeping the tea in milk rather than water adds richness and prevents the batter from becoming too thin.", "For the fluffiest texture, let the batter rest for 5-10 minutes while the pan heats up; this allows the baking powder to activate fully.", "If your tahini is very thick (bottom of the jar), mix it with a splash of warm water before adding it to the yoghurt to prevent seizing.", "The bitterness of the tea and tahini balances the sweetness of the syrup\u2014don''t skip the salt in the batter, as it bridges these flavors."]', '"This recipe marries the Western tradition of fluffy breakfast pancakes with the flavor profile of the Middle East and South Asia. The use of Earl Grey (bergamot) and cardamom mimics the aromatic qualities of Chai, while the tahini-yoghurt topping is a nod to the sesame-rich sweets found across the Levant."', 621.66);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('83b9e56a-0075-4c61-9fb6-8a83f273a68e', 'Centennial Liberty Tart', 'A sophisticated evolution of the patriotic desserts popular during the Statue of Liberty''s 1986 Centennial. A crisp vanilla bean pâte sablée shell holds a velvety lemon-mascarpone mousseline, topped with a geometric arrangement of glazed summer berries.', 'dessert', 'American', 'Intermediate', '["blueberry", "strawberry", "dessert", "summer", "patriotic", "tart", "fourth of july"]', '[{"group_name": "P\u00e2te Sabl\u00e9e (Crust)", "items": [{"name": "all-purpose flour", "quantity": 200, "unit": "g", "preparation": null, "notes": "Plus extra for dusting", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "powdered sugar", "quantity": 60, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "egg yolk", "quantity": 1, "unit": null, "preparation": "large", "notes": "approx 18g", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla bean paste", "quantity": 3, "unit": "g", "preparation": null, "notes": "or extract", "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Lemon Mascarpone Cream", "items": [{"name": "mascarpone cheese", "quantity": 250, "unit": "g", "preparation": "cold", "notes": null, "substitutions": [], "ingredient_id": "fc428935-3bcd-4cef-8495-7ed35e7dae22", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy whipping cream", "quantity": 150, "unit": "ml", "preparation": "cold, 35% fat or higher", "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "powdered sugar", "quantity": 40, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 6, "unit": "g", "preparation": null, "notes": "approx 1 whole lemon", "substitutions": [], "ingredient_id": "a5fb6a2a-dcda-4ab2-8fe6-472d7fcc39d1", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Fruit & Finish", "items": [{"name": "strawberries", "quantity": 300, "unit": "g", "preparation": "hulled and halved lengthwise", "notes": "Select uniform sizes", "substitutions": ["raspberries", "red currants"], "ingredient_id": "b2199214-7c2d-4083-92ae-b0a8a044e25b", "nutrition_source": "USDA FoodData Central"}, {"name": "blueberries", "quantity": 150, "unit": "g", "preparation": "washed and thoroughly dried", "notes": null, "substitutions": ["blackberries"], "ingredient_id": "0f9f22a4-4f00-4950-9145-943d55b6dec8", "nutrition_source": "USDA FoodData Central"}, {"name": "apricot preserves", "quantity": 45, "unit": "ml", "preparation": null, "notes": "for glazing", "substitutions": [], "ingredient_id": "169d2f29-93de-4df0-826f-57629d5839bc", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine flour, powdered sugar, and salt in a food processor. Pulse briefly to mix.", "structured": {"action": "MIX", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Add cold cubed butter and pulse until the mixture resembles coarse breadcrumbs. Add the egg yolk and vanilla, pulsing just until the dough clumps together. Do not overwork.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Turn dough out, shape into a flat disc, wrap in plastic, and refrigerate for at least 1 hour to relax the gluten.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Roll the chilled dough on a lightly floured surface to 3mm thickness. Carefully lift and press into the tart pan. Trim edges, dock the bottom with a fork, and freeze for 15 minutes.", "structured": {"action": "ROLL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Preheat oven to 190\u00b0C/375\u00b0F. Line the frozen tart shell with parchment paper and fill with pie weights. Bake for 15 minutes.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Remove weights and paper. Bake for another 10-12 minutes until the bottom is golden brown and dry. Allow to cool completely on a wire rack.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT12M", "doneness_cues": {"visual": "Golden brown throughout", "tactile": "Dry to the touch"}}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "In a chilled bowl, whip the mascarpone, heavy cream, powdered sugar, lemon zest, and vanilla until medium-stiff peaks form. Do not over-whip or mascarpone may curdle.", "structured": {"action": "WHIP", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Medium-stiff peaks", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Spread the cream evenly into the cooled tart shell using an offset spatula.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Arrange blueberries in the top left quadrant and strawberries in rows across the remaining surface to evoke a flag motif, or arrange in concentric circles for a classic look.", "structured": {"action": "GARNISH", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Heat apricot preserves with water until liquid. Strain to remove chunks, then gently brush over the fruit for a glossy, protective finish.", "structured": {"action": "GLAZE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT50M", "passive_time": "PT2H", "total_time": "PT2H50M", "overnight_required": false, "yields": "1 9-inch tart", "yield_count": 8, "serving_size_g": 165}', '{"flags": ["Vegetarian", "Soy-Free", "Peanut-Free"], "not_suitable_for": ["Vegans", "Celiacs"]}', '{"per_serving": {"calories": 480.72, "protein_g": 5.59, "carbohydrates_g": 50.8, "fat_g": 32.58, "saturated_fat_g": 19.65, "trans_fat_g": 0.23, "monounsaturated_fat_g": 5.38, "polyunsaturated_fat_g": 1.01, "fiber_g": 2.22, "sugar_g": 22.01, "sodium_mg": 120.97, "cholesterol_mg": 76.39, "potassium_mg": 129.57, "calcium_mg": 98.94, "iron_mg": 0.63, "magnesium_mg": 13.69, "phosphorus_mg": 61.67, "zinc_mg": 0.38, "vitamin_a_mcg": 352.98, "vitamin_c_mg": 25.44, "vitamin_d_mcg": 0.42, "vitamin_e_mg": 0.81, "vitamin_k_mcg": 6.14, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": 0.1, "thiamin_mg": 0.05, "riboflavin_mg": 0.08, "niacin_mg": 0.56, "folate_mcg": 21.25, "water_g": 72.19, "alcohol_g": 0.34, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten within 24 hours as the crust will eventually soften.", "duration": "P2D"}, "freezer": {"notes": null, "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "9-inch tart pan with removable bottom", "required": true, "alternative": null}, {"name": "Food processor", "required": false, "alternative": "Pastry blender and mixing bowl"}, {"name": "Electric mixer", "required": true, "alternative": "Whisk and strong arm"}, {"name": "Rolling pin", "required": true, "alternative": null}, {"name": "Pie weights", "required": true, "alternative": "Dried beans or uncooked rice"}, {"name": "Pastry brush", "required": true, "alternative": null}]', '[{"symptom": "Filling is runny and won''t hold shape", "likely_cause": "The cream was under-whipped or the mixture got too warm", "prevention": "Ensure both mascarpone and cream are fridge-cold; stop whipping immediately when peaks hold", "fix": "Refrigerate the filled tart for 2 hours before slicing to help it set"}, {"symptom": "Pastry shell shrank during baking", "likely_cause": "Dough was not rested enough or wasn''t cold enough before baking", "prevention": "Freeze the lined tart pan for 15 minutes before putting it in the oven", "fix": "Cannot be fixed, but fill carefully to the new rim height"}]', '["Pat dry the fruit thoroughly after washing. Any water left on the berries will bleed into the cream and create a messy slice.", "For the cleanest cuts, wipe your knife with a warm, damp cloth between every slice.", "If mascarpone is unavailable, an equal weight of full-fat cream cheese can be used, though the texture will be slightly denser and tangier.", "The glaze is not just for looks; it seals the fruit, keeping it fresh and preventing it from drying out in the fridge."]', '"During the summer of 1986, America celebrated the Statue of Liberty''s centennial with a massive resurgence of patriotic culinary themes. While sheet cakes were common, French-influenced fruit tarts gained popularity in fine dining as a way to elevate the red, white, and blue motif using premium seasonal produce."', 480.72);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('83dc6efb-d073-44a0-873a-6b119741825c', 'Herb-Roasted Turkey Breast with Cranberry-White Wine Gastrique', 'Juicy, tender turkey breast with crispy, golden skin, infused with sage and thyme butter. It is served alongside a vibrant, jewel-toned sauce where the tartness of fresh cranberries and dry white wine cuts through the richness of the poultry.', 'dinner', 'American', 'Intermediate', '["roasts", "cranberry", "dry white wine", "turkey breast", "dinner", "fall", "thanksgiving", "holiday"]', '[{"group_name": "Herb-Butter Turkey", "items": [{"name": "bone-in, skin-on turkey breast", "quantity": 2500, "unit": "g", "preparation": "thawed, room temperature", "notes": "approx 2.5kg / 5.5lbs", "substitutions": [], "ingredient_id": "2b577d04-33ca-4919-938f-bfc8780a3a4b", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 85, "unit": "g", "preparation": "softened", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh sage leaves", "quantity": 10, "unit": "g", "preparation": "minced", "notes": null, "substitutions": [], "ingredient_id": "2babed06-aae7-4e90-8b4a-14acbde2f522", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh thyme leaves", "quantity": 5, "unit": "g", "preparation": "minced", "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": null, "notes": "from 1 lemon", "substitutions": [], "ingredient_id": "9e54e651-2396-4bef-9625-00ed1c90838f", "nutrition_source": "Aggregated Public Data"}, {"name": "kosher salt", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Cranberry-Wine Sauce", "items": [{"name": "fresh cranberries", "quantity": 340, "unit": "g", "preparation": null, "notes": null, "substitutions": ["frozen cranberries"], "ingredient_id": "792b7aa4-5582-400e-9d8b-cb9b5575d6fe", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 180, "unit": "ml", "preparation": null, "notes": "Sauvignon Blanc or Pinot Grigio", "substitutions": [], "ingredient_id": "0c041362-befe-4c15-88d2-ba97c8f46428", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "approx 30g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "orange juice", "quantity": 60, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "a15da11d-f8dd-46e3-9ac5-725a7912f1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "orange zest", "quantity": 1, "unit": null, "preparation": "strips", "notes": "approx 5g", "substitutions": [], "ingredient_id": "22ecf215-ce52-43b0-bf6e-d8b8ab63fe21", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Remove the turkey breast from the refrigerator 45-60 minutes before roasting to allow it to come to room temperature. Pat the skin thoroughly dry with paper towels.", "structured": {"action": "TEMPER", "temperature": null, "duration": "PT45M", "doneness_cues": null}, "tips": ["Dry skin is essential for crispiness. If you have time, leave it uncovered in the fridge overnight before this step."]}, {"step_number": 2, "phase": "prep", "text": "In a small bowl, combine softened butter, minced sage, thyme, minced garlic, lemon zest, 1 tsp of the salt, and the black pepper. Mash with a fork until a uniform paste forms.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Preheat the oven to 220\u00b0C (425\u00b0F). Carefully loosen the skin of the turkey breast from the meat using your fingers, being careful not to tear it. Spread 3/4 of the herb butter under the skin. Rub the remaining butter over the top of the skin and season liberally with the remaining salt.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Place the turkey breast on a rack in a roasting pan. Roast at 220\u00b0C (425\u00b0F) for 20 minutes to blast the skin. Then, reduce the oven temperature to 165\u00b0C (325\u00b0F) without opening the door. Continue roasting for 60-75 minutes until an instant-read thermometer inserted into the thickest part reads 74\u00b0C (165\u00b0F).", "structured": {"action": "ROAST", "temperature": {"celsius": 165, "fahrenheit": 329}, "duration": "PT1H15M", "doneness_cues": {"visual": "Skin is deep golden brown", "tactile": "Internal temp reaches 74\u00b0C"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "While the turkey roasts, prepare the sauce. Heat olive oil in a saucepan over medium heat. Add the minced shallot and saut\u00e9 for 2-3 minutes until softened but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Deglaze the pan with the white wine, scraping up any browned bits. Add the cranberries, sugar, orange juice, and orange zest strips. Bring to a boil, then reduce heat to low.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Simmer the sauce gently for 10-15 minutes, or until most of the cranberries have popped and the sauce coats the back of a spoon. Remove from heat and discard the orange zest strips.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": "Cranberries burst, sauce thickened", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Once the turkey reaches 74\u00b0C (165\u00b0F), remove from the oven. Transfer to a carving board and tent loosely with foil. Let it rest for at least 20 minutes to allow juices to redistribute before carving.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT1H45M", "total_time": "PT2H20M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 350}', '{"flags": ["Gluten-Free", "Soy-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 1008.38, "protein_g": 87.7, "carbohydrates_g": 39.7, "fat_g": 52.05, "saturated_fat_g": 18.49, "trans_fat_g": 0.42, "monounsaturated_fat_g": 20.47, "polyunsaturated_fat_g": 8.82, "fiber_g": 3.32, "sugar_g": 28.71, "sodium_mg": 1236.98, "cholesterol_mg": 297.13, "potassium_mg": 1042.12, "calcium_mg": 93.31, "iron_mg": 4.01, "magnesium_mg": 119.53, "phosphorus_mg": 744.74, "zinc_mg": 3.61, "vitamin_a_mcg": 202.72, "vitamin_c_mg": 17.63, "vitamin_d_mcg": 1.67, "vitamin_e_mg": 2.45, "vitamin_k_mcg": 5.47, "vitamin_b6_mg": 2.3, "vitamin_b12_mcg": 1.44, "thiamin_mg": 0.27, "riboflavin_mg": 0.41, "niacin_mg": 41.44, "folate_mcg": 22.87, "water_g": 380.05, "alcohol_g": 2.67, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store meat and sauce in separate airtight containers.", "duration": "P3D"}, "freezer": {"notes": "Turkey freezes well; sauce texture may loosen upon thawing.", "duration": "P2M"}, "reheating": "Reheat turkey gently with a splash of broth covered in foil at 150\u00b0C/300\u00b0F to prevent drying.", "does_not_keep": false}', '[{"name": "Roasting pan with rack", "required": true, "alternative": "Rimmed baking sheet with a wire cooling rack"}, {"name": "Digital meat thermometer", "required": true, "alternative": "Instant-read thermometer"}, {"name": "Medium saucepan", "required": true, "alternative": null}, {"name": "Kitchen twine", "required": false, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}]', '[{"symptom": "Turkey breast is dry", "likely_cause": "Overcooking; turkey breast has very little fat and dries out instantly past 74\u00b0C (165\u00b0F)", "prevention": "Use a digital thermometer and pull the meat exactly when it hits temperature", "fix": "Slice thinly and bathe in the cranberry-wine sauce or warm chicken stock before serving"}, {"symptom": "Skin is soggy", "likely_cause": "Skin wasn''t dried properly or oven temp was too low", "prevention": "Pat dry thoroughly; ensure the initial oven blast is hot (220\u00b0C/425\u00b0F)", "fix": "If meat is done but skin is pale, broil for 1-2 minutes, watching constantly to prevent burning"}]', '["Always roast bone-in for breast meat if possible; the bone acts as a heat insulator, keeping the meat moist while adding flavor.", "The ''high heat start'' method (blasting at 220\u00b0C then dropping to 165\u00b0C) creates the best skin texture without drying out the interior.", "For the wine, choose a dry white with high acidity like Sauvignon Blanc to balance the sugar in the cranberry sauce. Avoid oaked Chardonnays as they can turn bitter when reduced.", "Save the carcass! The roasted breast bone makes an incredible stock for soups or risottos the next day.", "Make sure to rest the meat. Cutting into it immediately will cause all the juices to run out onto the board, leaving the meat dry."]', '"Turkey is the quintessential centerpiece of the North American Thanksgiving table, originating from wild turkeys indigenous to the continent. This preparation modernizes the tradition by focusing solely on the breast\u2014often the most coveted part\u2014paired with a gastrique-style sauce that bridges the gap between savory gravy and sweet cranberry relish."', 1008.38);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('83fd5a08-1cb3-4583-a593-9637ea205c1c', 'Rustic Maple-Walnut Tart', 'A comforting, autumnal tart featuring a buttery Pâte Sablée shell filled with a rich, amber maple custard. The filling uses fresh breadcrumbs to create a unique, slightly chewy texture that suspends toasted walnuts in sweet harmony, reminiscent of a refined treacle tart.', 'dessert', 'Canadian', 'Intermediate', '["maple syrup", "walnut", "dessert", "fall", "thanksgiving", "tart", "canadian"]', '[{"group_name": "P\u00e2te Sabl\u00e9e (Pastry Shell)", "items": [{"name": "all-purpose flour", "quantity": 200, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 100, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "powdered sugar", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "egg yolk", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 18g", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}, {"name": "ice water", "quantity": 15, "unit": "ml", "preparation": null, "notes": "add gradually", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Maple-Walnut Filling", "items": [{"name": "pure maple syrup", "quantity": 300, "unit": "ml", "preparation": null, "notes": "Grade A Dark or Amber preferred", "substitutions": [], "ingredient_id": "1358a800-6e05-4bfd-ab71-03e78728c0bc", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh white breadcrumbs", "quantity": 60, "unit": "g", "preparation": null, "notes": "made from crustless white bread, pulsed fine", "substitutions": [], "ingredient_id": "a00b79b3-abcf-40ab-8817-c4c84ef9fd72", "nutrition_source": "Aggregated Public Data"}, {"name": "walnuts", "quantity": 150, "unit": "g", "preparation": "halves or roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "ab4fe25a-a215-4af7-8109-055c28e0bef2", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 60, "unit": "ml", "preparation": null, "notes": "35% fat minimum", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "melted and cooled", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "large", "notes": "approx 100g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "large pinch to balance sweetness", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a food processor, pulse flour, powdered sugar, and salt. Add cold cubed butter and pulse until the mixture resembles coarse meal. Add the egg yolk and drizzle in ice water just until the dough clumps together when pinched.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Turn dough onto a clean surface, shape into a flat disc, wrap in plastic, and refrigerate for at least 30 minutes to relax the gluten and firm the butter.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Preheat oven to 190\u00b0C (375\u00b0F). Roll the chilled dough on a lightly floured surface to a 3mm thickness. Carefully lift and press into the tart pan. Trim edges and freeze for 15 minutes.", "structured": {"action": "ROLL", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Line the tart shell with parchment paper and fill with pie weights. Blind bake for 15 minutes. Remove weights and paper, then bake for another 5 minutes until the bottom looks dry and pale golden. Reduce oven temperature to 175\u00b0C (350\u00b0F).", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "While the shell bakes, spread walnuts on a baking sheet and toast in the oven for 5-7 minutes until fragrant. Coarsely chop once cool enough to handle.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Lightly browned", "tactile": "Fragrant aroma"}}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "In a medium bowl, whisk eggs, melted butter, heavy cream, vanilla, and salt. Gradually whisk in the maple syrup until smooth. Stir in the fresh breadcrumbs and toasted walnuts.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Pour the filling into the par-baked tart shell. Ensure walnuts are evenly distributed. Bake at 175\u00b0C (350\u00b0F) for 30-35 minutes, or until the filling is set but still slightly wobbly in the very center.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT35M", "doneness_cues": {"visual": "Filling puffed and set edges", "tactile": "Slight wobble in center"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from oven and let cool completely on a wire rack before unmolding. The filling will firm up as it cools.", "structured": {"action": "COOL", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT1H30M", "total_time": "PT2H15M", "overnight_required": false, "yields": "1 23cm (9-inch) tart", "yield_count": 8, "serving_size_g": 115}', '{"flags": ["Vegetarian", "Soy-Free"], "not_suitable_for": ["Nut allergy sufferers", "Gluten intolerance", "Dairy intolerance"]}', '{"per_serving": {"calories": 570.98, "protein_g": 8.7, "carbohydrates_g": 68.54, "fat_g": 30.53, "saturated_fat_g": 11.81, "trans_fat_g": 0.1, "monounsaturated_fat_g": 6.9, "polyunsaturated_fat_g": 9.89, "fiber_g": 2.25, "sugar_g": 38.22, "sodium_mg": 234.6, "cholesterol_mg": 114.21, "potassium_mg": 261.98, "calcium_mg": 88.37, "iron_mg": 1.56, "magnesium_mg": 51.41, "phosphorus_mg": 147.06, "zinc_mg": 1.85, "vitamin_a_mcg": 170.74, "vitamin_c_mg": 0.29, "vitamin_d_mcg": 0.49, "vitamin_e_mg": 0.78, "vitamin_k_mcg": 2.01, "vitamin_b6_mg": 0.14, "vitamin_b12_mcg": 0.2, "thiamin_mg": 0.11, "riboflavin_mg": 0.13, "niacin_mg": 0.55, "folate_mcg": 34.82, "water_g": 23.62, "alcohol_g": 0.22, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store loosely covered; crust may soften slightly over time.", "duration": "P3D"}, "freezer": {"notes": "Freeze well-wrapped. Thaw in refrigerator overnight before serving.", "duration": "P1M"}, "reheating": "Serve room temperature or warm slightly in a 150\u00b0C oven for 5-10 minutes.", "does_not_keep": false}', '[{"name": "23cm (9-inch) tart pan with removable bottom", "required": true, "alternative": null}, {"name": "Food processor", "required": false, "alternative": "Pastry blender and knife"}, {"name": "Rolling pin", "required": true, "alternative": null}, {"name": "Pie weights or dried beans", "required": true, "alternative": null}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}]', '[{"symptom": "Filling is runny after cooling", "likely_cause": "Underbaked or maple syrup had too high water content", "prevention": "Ensure the tart bubbles gently in the oven and has only a slight wobble before removing; use pure maple syrup, not pancake syrup.", "fix": "Refrigerate the tart; it will firm up when cold, though texture may be softer."}, {"symptom": "Pastry bottom is soggy", "likely_cause": "Blind baking was insufficient or filling leaked", "prevention": "Ensure the bottom is dry and pale golden before adding liquid filling. Patch any cracks in raw dough before baking.", "fix": "Bake on the lowest rack of the oven or on a preheated pizza stone for the last 10 minutes."}]', '["Use fresh breadcrumbs, not dry commercially boxed ones. Pulse slices of crustless white sandwich bread in a processor for the correct soft texture that absorbs the syrup.", "The quality of maple syrup matters immensely here. Grade A Dark (formerly Grade B) provides a robust maple flavor that stands up to the walnuts.", "Serve with a dollop of unsweetened cr\u00e8me fra\u00eeche or sour cream to cut through the intense sweetness of the maple.", "If the crust edges brown too quickly during the final bake, cover the perimeter gently with a foil shield."]', '"This tart draws inspiration from the Quebecois ''Tarte au Sirop d''\u00c9rable'' and traditional English treacle tarts. The use of breadcrumbs as a thickener is a humble, historic technique that creates a unique, custardy texture distinct from pecan or sugar pies, highlighting the harvest flavors of North American autumns."', 570.98);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('845bc07c-21c8-4440-acd6-a86377623f64', 'Microwave Marmalade Sponge Pudding', 'A comforting, steamy British-style sponge cake ready in minutes. The batter rises rapidly into a fluffy, golden crumb studded with pockets of sticky, bittersweet orange marmalade that melt into a self-saucing glaze.', 'dessert', 'British', 'Easy', '["dessert", "cake", "microwave", "marmalade", "quick", "british", "comfort food"]', '[{"group_name": "Sponge Base", "items": [{"name": "unsalted butter", "quantity": 40, "unit": "g", "preparation": "melted", "notes": "plus extra for greasing", "substitutions": ["oil", "margarine"], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "caster sugar", "quantity": 40, "unit": "g", "preparation": null, "notes": "superfine sugar", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": "beaten", "notes": "approx 50g (medium/large)", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "all-purpose flour", "quantity": 40, "unit": "g", "preparation": null, "notes": "plain flour", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 1/2 tsp", "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "milk", "quantity": 15, "unit": "ml", "preparation": null, "notes": "whole or semi-skimmed", "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Flavor & Topping", "items": [{"name": "orange marmalade", "quantity": 60, "unit": "g", "preparation": "divided", "notes": "fine cut or thick cut based on preference", "substitutions": [], "ingredient_id": "086edec1-968e-4cf0-94b0-64261e4408cf", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place 40g of butter in a medium microwave-safe bowl (approx 500ml capacity). Microwave on high for 30-40 seconds until melted but not bubbling hot.", "structured": {"action": "HEAT", "temperature": null, "duration": "PT40S", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Whisk the sugar and beaten egg into the melted butter until well combined and slightly glossy.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Add the flour and baking powder. Mix gently until just combined, then stir in the milk to loosen the batter.", "structured": {"action": "MIX", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Drop half of the marmalade (30g) into the batter and swirl it once or twice with a spoon. Do not fully mix; you want distinct pockets of jam.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Over-mixing the marmalade will result in a uniform flavor rather than the desired sticky pockets."]}, {"step_number": 5, "phase": "cook", "text": "Microwave on high (based on 800-1000W) for 90 seconds to 2 minutes. The cake should rise significantly and look set on top, though it may still look slightly moist near the marmalade pockets.", "structured": {"action": "BAKE", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Surface is dry to touch and sponge has risen", "tactile": "Springs back when pressed lightly"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Let the sponge rest for 1 minute (it will be extremely hot). Top with the remaining marmalade while warm and serve immediately.", "structured": {"action": "REST", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT5M", "passive_time": "PT2M", "total_time": "PT7M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 130}', '{"flags": ["Vegetarian", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 408.52, "protein_g": 5.81, "carbohydrates_g": 56.67, "fat_g": 19.04, "saturated_fat_g": 11.06, "trans_fat_g": 0.01, "monounsaturated_fat_g": 5.68, "polyunsaturated_fat_g": 1.18, "fiber_g": 1, "sugar_g": 40.6, "sodium_mg": 254.23, "cholesterol_mg": 136.75, "potassium_mg": 107.3, "calcium_mg": 154.68, "iron_mg": 1, "magnesium_mg": 10.46, "phosphorus_mg": 115.05, "zinc_mg": 0.52, "vitamin_a_mcg": 180.43, "vitamin_c_mg": 4.5, "vitamin_d_mcg": 0.6, "vitamin_e_mg": 0.75, "vitamin_k_mcg": 1.56, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": 0.3, "thiamin_mg": 0.04, "riboflavin_mg": 0.15, "niacin_mg": 0.28, "folate_mcg": 17.93, "water_g": 31.36, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Texture degrades quickly; best eaten fresh.", "duration": "P2D"}, "freezer": {"notes": "Not recommended.", "duration": null}, "reheating": "Microwave for 15-20 seconds to restore warmth and texture.", "does_not_keep": false}', '[{"name": "Microwave-safe bowl or mug", "required": true, "alternative": "Ramekins"}, {"name": "Small whisk or fork", "required": true, "alternative": null}, {"name": "Microwave", "required": true, "alternative": null}]', '[{"symptom": "Cake texture is rubbery or tough", "likely_cause": "Overcooked or overmixed the gluten", "prevention": "Stop microwaving as soon as the surface looks dry; do not overmix the flour.", "fix": "Serve with extra custard or cream to mask the texture"}, {"symptom": "Batter overflowed the bowl", "likely_cause": "Bowl was too small for the aggressive rise of microwave baking", "prevention": "Use a bowl that is at least twice the volume of the raw batter.", "fix": "Clean the microwave; the cake is still edible."}]', '["Microwave wattages vary wildly. Start checking at 90 seconds. If the center is still raw batter, add 15-second bursts.", "For a true ''steamed pudding'' texture, cover the bowl loosely with a microwave-safe saucer while cooking. This traps steam and keeps the top moist.", "This recipe relies on the interaction between baking powder and the acidic marmalade for extra lift, so ensure your baking powder is fresh.", "Safety Warning: The sugar in the marmalade gets significantly hotter than the cake crumb (over 100\u00b0C/212\u00b0F). Allow the 1-minute rest time to avoid burning your tongue."]', '"This is a rapid, modern adaptation of the traditional British Steamed Sponge Pudding, which usually takes hours to steam on a stovetop. It retains the quintessential British love for Seville orange marmalade, balancing sweet sponge with bitter citrus peel."', 408.52);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('84ed9622-28bb-451b-b698-0214d1eb4b24', 'Provençal Fisherman''s Stew', 'A robust, saffron-scented seafood stew hailing from the south of France. Tender white fish, squid, and shellfish simmer in a rich tomato and fennel broth, thickened slightly by melting potatoes.', 'soup', 'French', 'Intermediate', '["french", "seafood", "stew", "one-pot", "dinner", "healthy", "gluten-free"]', '[{"group_name": "Vegetable Base", "items": [{"name": "olive oil", "quantity": 60, "unit": "ml", "preparation": "extra virgin", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "leek", "quantity": 1, "unit": null, "preparation": "white and light green parts only, sliced", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "f0bddafa-51db-4e56-954b-18624daa6fa4", "nutrition_source": "USDA FoodData Central"}, {"name": "fennel bulb", "quantity": 1, "unit": null, "preparation": "thinly sliced, fronds reserved", "notes": "approx. 250g", "substitutions": [], "ingredient_id": "a42d03de-0a8a-4a75-8299-5cf01d43b425", "nutrition_source": "USDA FoodData Central"}, {"name": "carrot", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx. 100g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "red bell pepper", "quantity": 1, "unit": null, "preparation": "seeded and diced", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 4, "unit": null, "preparation": "minced", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "waxy potatoes", "quantity": 400, "unit": "g", "preparation": "peeled and cut into 2cm chunks", "notes": "Yukon Gold or similar", "substitutions": [], "ingredient_id": "4920385c-ae78-4023-8318-c5dfe051fecc", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Broth", "items": [{"name": "dry white wine", "quantity": 150, "unit": "ml", "preparation": null, "notes": "Sauvignon Blanc or Pinot Grigio", "substitutions": [], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "canned plum tomatoes", "quantity": 400, "unit": "g", "preparation": "crushed by hand", "notes": null, "substitutions": [], "ingredient_id": "ec251138-544a-4496-8428-18ff36a89bfd", "nutrition_source": "USDA FoodData Central"}, {"name": "fish stock", "quantity": 1000, "unit": "ml", "preparation": null, "notes": "low-sodium preferred", "substitutions": [], "ingredient_id": "3912e04d-71a3-4a31-b033-cc5c5aa4452d", "nutrition_source": "Aggregated Public Data"}, {"name": "saffron threads", "quantity": null, "unit": null, "preparation": null, "notes": "large pinch", "substitutions": [], "ingredient_id": "7f9ec0c8-2db1-48ac-a2c9-9b1efce12cf3", "nutrition_source": "USDA FoodData Central"}, {"name": "orange zest", "quantity": 1, "unit": null, "preparation": "strip", "notes": "approx. 3g", "substitutions": [], "ingredient_id": "c1a067e6-674f-4f68-9fe9-3eda4b074356", "nutrition_source": "Aggregated Public Data"}, {"name": "bay leaf", "quantity": 1, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eab2ef3a-7a0e-4188-b746-645b795ada1e", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Seafood", "items": [{"name": "firm white fish fillets", "quantity": 600, "unit": "g", "preparation": "cut into 5cm pieces", "notes": "Cod, Halibut, or Snapper", "substitutions": [], "ingredient_id": "229ccaef-c763-440b-b44f-6e22222d3fd1", "nutrition_source": "USDA FoodData Central"}, {"name": "squid", "quantity": 200, "unit": "g", "preparation": "cleaned, bodies sliced into rings", "notes": null, "substitutions": [], "ingredient_id": "e126ab3d-72fc-463a-a50c-461c65ccdf4d", "nutrition_source": "USDA FoodData Central"}, {"name": "clams", "quantity": 300, "unit": "g", "preparation": "scrubbed and purged", "notes": "Littleneck or Manila", "substitutions": [], "ingredient_id": "59545409-30d0-466b-9b6f-84ae890c0214", "nutrition_source": "USDA FoodData Central"}, {"name": "mussels", "quantity": 300, "unit": "g", "preparation": "scrubbed and debearded", "notes": null, "substitutions": [], "ingredient_id": "8724ea32-079e-407e-a9ae-1fe49557dc47", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the seafood: Ensure clams and mussels are scrubbed clean and any open ones that don''t close when tapped are discarded. Pat fish and squid dry.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat the olive oil in a Dutch oven over medium heat. Add the leeks, fennel, carrots, and bell pepper. Saut\u00e9 for 8-10 minutes until softened but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Stir in the minced garlic and cook for 1 minute until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour in the white wine to deglaze the pot, scraping up any browned bits from the bottom.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the crushed tomatoes, fish stock, potatoes, saffron, orange zest strip, and bay leaf. Bring to a boil, then reduce heat and simmer gently for 20 minutes, or until potatoes are tender when pierced with a fork.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT20M", "doneness_cues": {"visual": null, "tactile": "Potatoes tender when pierced"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Add the firm white fish and squid to the broth. Simmer gently for 3 minutes.", "structured": {"action": "POACH", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Add the clams and mussels. Cover the pot tightly and steam for 4-5 minutes until the shells have opened.", "structured": {"action": "STEAM", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Shells opened wide", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from heat immediately. Discard the bay leaf, orange zest, and any unopened shellfish. Season with salt and pepper to taste. Serve garnished with reserved fennel fronds.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT30M", "total_time": "PT1H15M", "overnight_required": false, "yields": "4 generous servings", "yield_count": 4, "serving_size_g": 550}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Whole30"], "not_suitable_for": ["Shellfish allergy"]}', '{"per_serving": {"calories": 706.92, "protein_g": 68.2, "carbohydrates_g": 42.79, "fat_g": 23.53, "saturated_fat_g": 3.94, "trans_fat_g": 0.01, "monounsaturated_fat_g": 11.71, "polyunsaturated_fat_g": 3.13, "fiber_g": 8.62, "sugar_g": 10.9, "sodium_mg": 1349.86, "cholesterol_mg": 224.5, "potassium_mg": 2716.02, "calcium_mg": 200.71, "iron_mg": 7.9, "magnesium_mg": 165.19, "phosphorus_mg": 857.14, "zinc_mg": 3.81, "vitamin_a_mcg": 491.94, "vitamin_c_mg": 95.06, "vitamin_d_mcg": 1.35, "vitamin_e_mg": 6.37, "vitamin_k_mcg": 58.04, "vitamin_b6_mg": 0.97, "vitamin_b12_mcg": 19.49, "thiamin_mg": 0.95, "riboflavin_mg": 0.66, "niacin_mg": 8.47, "folate_mcg": 114.12, "water_g": 572.57, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Seafood degrades quickly; best consumed immediately.", "duration": "P2D"}, "freezer": {"notes": "Not recommended. Potatoes become mealy and seafood texture suffers.", "duration": null}, "reheating": "Gently reheat on the stovetop over low heat to avoid overcooking the fish.", "does_not_keep": false}', '[{"name": "Dutch oven or heavy-bottomed pot", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": null}]', '[{"symptom": "Fish has disintegrated into the soup", "likely_cause": "Pot was stirred too vigorously or boiled too hard after adding fish", "prevention": "Keep the heat at a very low simmer and shake the pot gently instead of stirring", "fix": "Serve as is; the flavor will be excellent even if the presentation is rustic"}, {"symptom": "Shellfish tastes gritty", "likely_cause": "Clams/mussels were not purged of sand properly", "prevention": "Soak clams in salted water for 30 minutes before cooking to purge sand", "fix": "Cannot be fixed once cooked; strain broth if eating around the grit is impossible"}]', '["The quality of your stock makes the dish. If you can''t find high-quality fish stock, substitute with clam juice mixed with water or a high-quality vegetable broth.", "Do not boil the soup rapidly once the fish is added. High heat causes the protein fibers in the fish to contract tight, resulting in a rubbery texture.", "Serve this traditionally with ''rouille'' (a garlic-saffron mayonnaise) and toasted baguette slices to soak up the broth.", "If using frozen fish, thaw completely and pat extremely dry before adding to the stew to prevent watering down the flavor."]', '"Inspired by the classic Bouillabaisse of Marseille, this stew reflects the frugal traditions of Mediterranean fishermen who used the bony rockfish they couldn''t sell at market to feed their families. The inclusion of saffron and orange zest marks it distinctly as a Proven\u00e7al dish."', 706.92);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('86016380-b62d-4c0e-9233-165667e6a76e', 'Warm Bacon and Bok Choy Salad', 'A savory warm salad where fresh, crisp baby bok choy is gently wilted by a hot dressing of rendered bacon fat, sesame oil, and soy sauce. The result is a smoky, umami-rich side dish with contrasting textures.', 'salad', 'Asian Fusion', 'Easy', '["five ingredient", "salad", "easy", "quick", "side dish", "dairy-free", "asian fusion"]', '[{"group_name": "Salad Base", "items": [{"name": "baby bok choy", "quantity": 400, "unit": "g", "preparation": "washed and ends trimmed", "notes": "approx. 4-5 heads", "substitutions": [], "ingredient_id": "562bdece-f897-4d03-be7a-94be5ef3f681", "nutrition_source": "Aggregated Public Data"}, {"name": "bacon", "quantity": 150, "unit": "g", "preparation": "sliced into 1cm strips", "notes": "thick-cut preferred", "substitutions": [], "ingredient_id": "893e633e-f6ec-482c-8dfd-2936be71f2fd", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dressing", "items": [{"name": "soy sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": "use tamari for gluten-free option", "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "toasted sesame oil", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a9a59164-d949-4acd-99da-689f0a32e2e7", "nutrition_source": "Aggregated Public Data"}, {"name": "rice vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": "unseasoned", "substitutions": [], "ingredient_id": "fcbf5252-1be9-4dd4-8c22-4fda1dbdca28", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Separate the bok choy leaves. Slice the larger white stems into 2cm pieces and leave the green leafy tops whole or halved. Pat dry thoroughly.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Place the bacon strips in a cold skillet. Turn heat to medium and cook, stirring occasionally, until the fat has rendered and the bacon is crispy (approx. 8-10 minutes).", "structured": {"action": "FRY", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Golden brown and crispy", "tactile": "Rigid"}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "While bacon cooks, whisk the soy sauce, rice vinegar, and sesame oil together in a small bowl.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Use a slotted spoon to remove crispy bacon to a paper towel-lined plate. Keep approximately 30ml (2 tablespoons) of the hot bacon fat in the pan; discard excess carefully.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour the soy sauce mixture carefully into the hot bacon fat (watch for splatter). Swirl immediately to emulsify into a warm vinaigrette.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Place the prepared bok choy in a large heat-proof bowl. Pour the hot dressing over the greens and toss immediately to slightly wilt the leaves. Top with the crispy bacon and serve.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT0M", "total_time": "PT15M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 130}', '{"flags": ["Dairy-Free", "Nut-Free", "Low-Carb", "Paleo"], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 187.94, "protein_g": 6.5, "carbohydrates_g": 3.45, "fat_g": 16.55, "saturated_fat_g": 4.72, "trans_fat_g": 0.06, "monounsaturated_fat_g": 5.96, "polyunsaturated_fat_g": 2.16, "fiber_g": 0.91, "sugar_g": 2.33, "sodium_mg": 1473.15, "cholesterol_mg": 24.75, "potassium_mg": 325.38, "calcium_mg": 79.75, "iron_mg": 0.79, "magnesium_mg": 4.88, "phosphorus_mg": 62.25, "zinc_mg": 0.43, "vitamin_a_mcg": 145.63, "vitamin_c_mg": 32.5, "vitamin_d_mcg": 0.15, "vitamin_e_mg": 0.16, "vitamin_k_mcg": null, "vitamin_b6_mg": 0.1, "vitamin_b12_mcg": 0.19, "thiamin_mg": 0.11, "riboflavin_mg": 0.03, "niacin_mg": 1.51, "folate_mcg": null, "water_g": 17.51, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten immediately as leaves will lose texture in storage.", "duration": "P1D"}, "freezer": {"notes": null, "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Large skillet or wok", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Slotted spoon", "required": true, "alternative": null}]', '[{"symptom": "Salad is too greasy", "likely_cause": "Too much rendered bacon fat was left in the pan before adding the dressing ingredients", "prevention": "Measure the bacon fat left in the pan; you only need about 30ml (2 tbsp) to carry the flavor", "fix": "Add a squeeze of fresh lime juice or more vinegar to cut the fat"}]', '["Starting bacon in a cold pan helps render the fat more evenly without burning the meat.", "Ensure the bok choy is very dry before adding the dressing; excess water will dilute the sauce and prevent the oil from clinging to the leaves.", "The heat of the dressing cooks the greens just enough to remove the raw bite while maintaining crunch. Do not saut\u00e9 the greens unless you prefer a fully cooked stir-fry texture.", "For a spicy kick, add a pinch of red pepper flakes to the hot oil just before adding the liquid ingredients."]', '"This dish utilizes the Western technique of a ''wilted salad''\u2014common in Southern US cuisine with dandelion greens and bacon\u2014and adapts it with East Asian flavor profiles. It highlights the texture of bok choy, a staple Chinese brassica cultivated for over 5,000 years."', 187.94);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('87ddfb28-cf76-4a57-8298-666cc1fa77f2', 'Alsatian-Style Slow Cooker Lentil & Apple Soup', 'A comforting, rustic stew where earthiness meets subtle sweetness. Smoky sausage and nutty brown lentils form a savory base, while tart Granny Smith apples melt into the broth, creating a velvety texture balanced by the sharp tang of Dijon mustard and cool sour cream.', 'soup', 'German', 'Easy', '["apple", "great leftovers", "lentil", "slow cooker", "soup", "dinner", "main course", "fall", "winter", "thanksgiving"]', '[{"group_name": "Base & Aromatics", "items": [{"name": "dried brown lentils", "quantity": 400, "unit": "g", "preparation": "rinsed and picked over", "notes": null, "substitutions": [], "ingredient_id": "fc77776c-fd4a-436e-a164-8fdf1198fea3", "nutrition_source": "Aggregated Public Data"}, {"name": "smoked sausage (kielbasa or similar)", "quantity": 450, "unit": "g", "preparation": "sliced into half-moons", "notes": "Ensure gluten-free if required", "substitutions": [], "ingredient_id": "5604355c-b51e-4f0d-ad3b-212f2e217a12", "nutrition_source": "Aggregated Public Data"}, {"name": "tart apples (granny smith)", "quantity": 2, "unit": null, "preparation": "peeled, cored, and diced", "notes": "approx 300g total", "substitutions": [], "ingredient_id": "e4936f5c-8828-4564-8b6f-27ccd85bfe85", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "carrots", "quantity": 2, "unit": null, "preparation": "diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "celery stalks", "quantity": 2, "unit": null, "preparation": "diced", "notes": "approx 100g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Liquid & Seasoning", "items": [{"name": "chicken stock", "quantity": 1500, "unit": "ml", "preparation": "low sodium", "notes": null, "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}, {"name": "dried thyme", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "3b938244-d506-46b2-9027-21bed955bcc5", "nutrition_source": "USDA FoodData Central"}, {"name": "dried bay leaves", "quantity": 2, "unit": null, "preparation": null, "notes": "remove before serving", "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}, {"name": "ground allspice", "quantity": 1, "unit": "g", "preparation": null, "notes": "approx 1/4 tsp", "substitutions": [], "ingredient_id": "d0b9d4b4-744d-472b-bb19-a779a23d70c6", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "dijon mustard", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "3e25e626-c9b4-4b62-9d08-7c650bcb3d2b", "nutrition_source": "Aggregated Public Data"}, {"name": "apple cider vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "sour cream", "quantity": 120, "unit": "g", "preparation": "for garnish", "notes": null, "substitutions": [], "ingredient_id": "773a6e88-6185-4784-92a7-104b7c1b7688", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the diced onion, carrots, celery, sliced sausage, and diced apples into the basin of the slow cooker.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["For deeper flavor, briefly sear the sausage and onions in a hot skillet before adding to the slow cooker to develop fond."]}, {"step_number": 2, "phase": "assemble", "text": "Add the rinsed lentils, dried thyme, bay leaves, allspice, and black pepper. Pour the chicken stock over the mixture and stir gently to combine.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Cover and cook on LOW for 7-8 hours or HIGH for 3-4 hours, until the lentils are tender and the vegetables are soft.", "structured": {"action": "BOIL", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT7H", "doneness_cues": {"visual": null, "tactile": "Lentils should be creamy but not disintegrated"}}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Discard the bay leaves. Stir in the Dijon mustard and apple cider vinegar. Taste and season with salt if necessary (the sausage and stock usually provide sufficient salinity).", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Do not skip the vinegar; the acid is crucial to brighten the rich, earthy flavors."]}, {"step_number": 5, "phase": "finish", "text": "Ladle into bowls and top with a dollop of sour cream and fresh chopped parsley.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT7H", "total_time": "PT7H20M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 400}', '{"flags": ["Gluten-Free", "Nut-Free", "Egg-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 399.13, "protein_g": 24.31, "carbohydrates_g": 36.76, "fat_g": 19.3, "saturated_fat_g": 5.55, "trans_fat_g": null, "monounsaturated_fat_g": 0.84, "polyunsaturated_fat_g": 0.16, "fiber_g": 8.74, "sugar_g": 10.17, "sodium_mg": 10943.8, "cholesterol_mg": 7, "potassium_mg": 716.54, "calcium_mg": 152.67, "iron_mg": 7.37, "magnesium_mg": 15.62, "phosphorus_mg": 265.56, "zinc_mg": 3.17, "vitamin_a_mcg": 247.45, "vitamin_c_mg": 6.72, "vitamin_d_mcg": 0.06, "vitamin_e_mg": 0.46, "vitamin_k_mcg": 52.15, "vitamin_b6_mg": 0.11, "vitamin_b12_mcg": 0.06, "thiamin_mg": 0.06, "riboflavin_mg": 0.1, "niacin_mg": 0.48, "folate_mcg": 24.13, "water_g": 121.13, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors improve significantly the next day.", "duration": "P4D"}, "freezer": {"notes": "Texture may soften slightly upon thawing; reheat gently.", "duration": "P3M"}, "reheating": "Simmer gently on the stovetop; add a splash of water if the stew has thickened.", "does_not_keep": false}', '[{"name": "Slow cooker (6 quart / 6 liter)", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Skillet", "required": false, "alternative": "Microwave (to sweat onions)"}]', '[{"symptom": "Lentils are still hard after cooking time", "likely_cause": "The lentils were old or acid was added too early", "prevention": "Check expiration dates on dry goods; ensure vinegar/mustard are added only at the end", "fix": "Add 100ml hot water and continue cooking on HIGH for 45-60 minutes"}]', '["The apples will largely disintegrate during the long cook, thickening the broth naturally and providing a subtle, sweet counterpoint to the smoky sausage.", "Brown lentils work best here; red lentils will turn to mush, and French green lentils (Puy) may remain too firm for a rustic stew texture.", "If using a particularly fatty sausage, you may want to skim the surface of the soup before stirring in the mustard."]', '"This dish draws inspiration from the Alsace region on the border of France and Germany, where the combination of fruit (apples), cured meats, and brassicas or pulses is a staple of hearty winter cooking."', 399.13);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('89758c10-b1b5-4f43-8ab4-1bfb13b14da5', 'Elegant Pheasant Breast with Brandy Cream Sauce', 'Tender, pan-seared pheasant breasts served in a luxurious sauce of sautéed wild mushrooms and sweet shallots, deglazed with aged brandy and finished with rich heavy cream. An earthy, sophisticated main course that highlights the delicate flavor of game birds.', 'dinner', 'New American', 'Intermediate', '["american", "mushroom", "pheasant", "shallot", "dinner", "main course", "summer", "game bird", "gluten-free"]', '[{"group_name": "Pheasant", "items": [{"name": "pheasant breasts", "quantity": 2, "unit": null, "preparation": "boneless, skin-on or skinless", "notes": "approx. 150g each", "substitutions": [], "ingredient_id": "2b577d04-33ca-4919-938f-bfc8780a3a4b", "nutrition_source": "Aggregated Public Data"}, {"name": "kosher salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, start with 2g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly ground", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Mushroom & Shallot Sauce", "items": [{"name": "cremini or wild mushrooms", "quantity": 150, "unit": "g", "preparation": "sliced", "notes": null, "substitutions": [], "ingredient_id": "8a4fb37c-f8db-4c2f-b14d-f2dc7aef4c24", "nutrition_source": "USDA FoodData Central"}, {"name": "shallots", "quantity": 2, "unit": null, "preparation": "finely minced", "notes": "approx. 50g total", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "brandy", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["cognac", "dark rum"], "ingredient_id": "cf43659a-78aa-4577-bdaa-2422290aa000", "nutrition_source": "Aggregated Public Data"}, {"name": "chicken stock", "quantity": 120, "unit": "ml", "preparation": null, "notes": "or game bird stock", "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 80, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 3, "unit": null, "preparation": "sprigs", "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh parsley", "quantity": 5, "unit": "g", "preparation": "chopped, for garnish", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the pheasant breasts completely dry with paper towels. Season generously on all sides with salt and freshly ground black pepper.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat the olive oil and butter in a heavy skillet over medium-high heat. Once the butter foams and subsides, add the pheasant breasts (skin-side down if applicable). Sear without moving for 3-4 minutes until golden brown.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Flip the breasts and cook for another 2-3 minutes until they are browned but slightly undercooked in the center (they will finish in the sauce). Remove pheasant to a plate and rest.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Reduce heat to medium. Add the sliced mushrooms to the pan juices. Saut\u00e9 for 5 minutes until they release their liquid and begin to brown. Add the minced shallots and thyme sprigs, saut\u00e9ing for another 2 minutes until shallots are softened and fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT7M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Remove the pan from the heat source momentarily and pour in the brandy to deglaze. Return to heat and let the alcohol bubble away rapidly, scraping up any browned bits (fond) from the bottom of the pan.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Add the chicken stock and simmer until the liquid reduces by half, concentrating the flavors.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Stir in the heavy cream and bring to a gentle simmer. Do not boil vigorously or the cream may split.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Return the resting pheasant breasts (and any accumulated juices on the plate) to the pan. Simmer gently for 2-3 minutes, basting the meat with the sauce, until the internal temperature reaches 74\u00b0C/165\u00b0F. Discard thyme sprigs, garnish with parsley, and serve immediately.", "structured": {"action": "BASTE", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": "PT3M", "doneness_cues": {"visual": "Sauce thickens to coat the back of a spoon", "tactile": "Meat feels firm to the touch"}}, "tips": ["Use an instant-read thermometer to avoid overcooking, as pheasant contains very little fat."]}]', '{"active_time": "PT25M", "passive_time": "PT5M", "total_time": "PT30M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 220}', '{"flags": ["Gluten-Free", "Nut-Free", "Soy-Free", "Egg-Free", "Low-Carb"], "not_suitable_for": ["Vegans", "Vegetarians"]}', '{"per_serving": {"calories": 619.63, "protein_g": 36.81, "carbohydrates_g": 9.48, "fat_g": 43.46, "saturated_fat_g": 18.08, "trans_fat_g": 0.65, "monounsaturated_fat_g": 16.61, "polyunsaturated_fat_g": 4.74, "fiber_g": 2.11, "sugar_g": 4.66, "sodium_mg": 2903.65, "cholesterol_mg": 157.32, "potassium_mg": 727.68, "calcium_mg": 72.31, "iron_mg": 2.51, "magnesium_mg": 58.57, "phosphorus_mg": 370.39, "zinc_mg": 1.87, "vitamin_a_mcg": 268.31, "vitamin_c_mg": 11.14, "vitamin_d_mcg": 1.39, "vitamin_e_mg": 2.08, "vitamin_k_mcg": 48.34, "vitamin_b6_mg": 0.98, "vitamin_b12_mcg": 0.62, "thiamin_mg": 0.18, "riboflavin_mg": 0.53, "niacin_mg": 17.74, "folate_mcg": 34.09, "water_g": 221.69, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Pheasant dries out easily upon reheating; sauce separates if overheated.", "duration": "P2D"}, "freezer": {"notes": "Cream-based sauces do not freeze well; texture will become grainy.", "duration": null}, "reheating": "Gently warm in a skillet over low heat, adding a splash of water or stock to re-emulsify the sauce.", "does_not_keep": false}', '[{"name": "Heavy-bottomed skillet or saut\u00e9 pan", "required": true, "alternative": "Stainless steel frying pan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Meat thermometer", "required": true, "alternative": null}]', '[{"symptom": "Pheasant is dry and tough", "likely_cause": "Overcooking; pheasant is much leaner than chicken", "prevention": "Remove from heat immediately once internal temp hits target; rely on carryover cooking", "fix": "Slice thinly against the grain and toss generously in the cream sauce to add moisture"}]', '["If available, use a mix of chanterelle or oyster mushrooms for a more complex, woody flavor profile suitable for game.", "Be careful when adding brandy near an open gas flame; turn the burner off while pouring to prevent flare-ups.", "If the sauce becomes too thick while the pheasant finishes cooking, whisk in a tablespoon of warm water or additional stock.", "Serve alongside wild rice or roasted fingerling potatoes to soak up the rich sauce."]', '"Pheasant hunting has a long tradition in American rural culinary history, particularly in the Midwest and Great Plains. This preparation borrows from the classic French ''Supreme'' sauce technique, adapting it to the leaner, gamier nature of wild birds popular in New American seasonal dining."', 619.63);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('8a42d3ea-0b08-4eab-a6ee-e554d72af114', 'Baasto Iyo Kaluun (Somali Spiced Tuna Pasta)', 'A comforting, aromatic fusion dish featuring al dente spaghetti tossed in a rich tomato sauce infused with Xawaash (a traditional Somali spice blend), green peppers, and tender flakes of tuna, finished with fresh cilantro.', 'dinner', 'Somali', 'Easy', '["pastas", "budget", "canned tuna", "cilantro", "marinara sauce", "somali", "spaghetti", "stovetop", "tomato sauce", "dinner", "easy", "quick", "weeknight"]', '[{"group_name": "Aromatics & Spices", "items": [{"name": "vegetable oil", "quantity": 30, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "green bell pepper", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx. 120g", "substitutions": [], "ingredient_id": "73526a0d-a2c7-4cac-8f5e-a77e5faf659d", "nutrition_source": "Aggregated Public Data"}, {"name": "xawaash spice blend", "quantity": 10, "unit": "g", "preparation": "powder", "notes": "Or substitute: 1 tsp cumin, 1 tsp coriander, 0.5 tsp turmeric, 0.25 tsp cinnamon, 0.25 tsp cardamom, 0.25 tsp black pepper", "substitutions": ["Garam masala mixed with cumin"], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sauce & Protein", "items": [{"name": "tomato paste", "quantity": 30, "unit": "g", "preparation": null, "notes": "concentrated double strength", "substitutions": [], "ingredient_id": "d0a34229-249b-49e5-a653-227bd7afb7fc", "nutrition_source": "Aggregated Public Data"}, {"name": "marinara sauce", "quantity": 700, "unit": "g", "preparation": "jarred", "notes": "Select a simple basil or plain variety", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "canned tuna in oil", "quantity": 300, "unit": "g", "preparation": "drained", "notes": "Solid white albacore preferred; weight is drained weight", "substitutions": [], "ingredient_id": "f926c937-a447-44e6-bc30-a71c55811250", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 60, "unit": "ml", "preparation": null, "notes": "Use pasta cooking water if available", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Pasta & Garnish", "items": [{"name": "spaghetti", "quantity": 450, "unit": "g", "preparation": "dry", "notes": null, "substitutions": [], "ingredient_id": "3994b041-8c11-4992-adf0-a373b17e1aee", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 30, "unit": "g", "preparation": null, "notes": "For pasta water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "lime wedges", "quantity": 4, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "d3d2677e-fe02-4404-add0-29d73df7e921", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Fill a large pot with water, add the salt, and bring to a rolling boil over high heat.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a large skillet, heat the vegetable oil over medium heat (175\u00b0C/350\u00b0F). Add the diced onion and green bell pepper. Saut\u00e9 until the onions are translucent and soft.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT6M", "doneness_cues": {"visual": "Onions are translucent", "tactile": "Vegetables are soft"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the minced garlic and Xawaash spice blend to the skillet. Cook, stirring constantly, for about 60 seconds until the spices are fragrant and toasted.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Spices darken slightly", "tactile": "Aromatic release"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Stir in the tomato paste and cook for 2 minutes to caramelize slightly and deepen the color from bright red to rusty red.", "structured": {"action": "CARAMELIZE", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Paste turns dark rust color", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour in the marinara sauce and water. Reduce heat to low, cover, and let simmer while you cook the pasta.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Add the spaghetti to the boiling water. Cook according to package instructions for al dente texture.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT9M", "doneness_cues": {"visual": null, "tactile": "Firm to the bite"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Two minutes before the pasta is ready, gently fold the drained tuna into the simmering sauce. Stir carefully to keep some chunks intact. Warm the tuna through.", "structured": {"action": "FOLD", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Tuna is integrated and hot", "tactile": null}}, "tips": ["Do not simmer the tuna for too long or it will become dry and chalky."]}, {"step_number": 8, "phase": "assemble", "text": "Drain the pasta. Combine the pasta with the sauce in the skillet (or return everything to the large pot). Toss until every strand is coated. Garnish with fresh cilantro and serve with lime wedges.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Evenly coated pasta", "tactile": null}}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT15M", "total_time": "PT35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 400}', '{"flags": ["Pescatarian", "Dairy-Free", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 475.66, "protein_g": 35.11, "carbohydrates_g": 51.17, "fat_g": 14.98, "saturated_fat_g": 2.39, "trans_fat_g": null, "monounsaturated_fat_g": 2.61, "polyunsaturated_fat_g": 2.39, "fiber_g": 7.57, "sugar_g": 10.34, "sodium_mg": 2975.71, "cholesterol_mg": 13.5, "potassium_mg": 887.74, "calcium_mg": 87.01, "iron_mg": 4.54, "magnesium_mg": 96.88, "phosphorus_mg": 373.47, "zinc_mg": 1.86, "vitamin_a_mcg": 100.2, "vitamin_c_mg": 59.86, "vitamin_d_mcg": null, "vitamin_e_mg": 0.23, "vitamin_k_mcg": 2.62, "vitamin_b6_mg": 0.31, "vitamin_b12_mcg": 1.65, "thiamin_mg": 0.43, "riboflavin_mg": 0.31, "niacin_mg": 11.72, "folate_mcg": 107.27, "water_g": 199.4, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Flavor improves the next day.", "duration": "P3D"}, "freezer": {"notes": "Pasta texture may degrade; sauce freezes well independently.", "duration": "P1M"}, "reheating": "Reheat on stovetop over low heat with a splash of water to loosen the sauce.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": "Dutch oven"}, {"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Sauce tastes metallic or acidic", "likely_cause": "The tomato base was not cooked down sufficiently", "prevention": "Allow the tomato paste to caramelize and the sauce to simmer for the full time", "fix": "Stir in a pinch of sugar or baking soda (0.5g) to neutralize acidity"}, {"symptom": "Tuna is dry and tough", "likely_cause": "Added too early and overcooked in the sauce", "prevention": "Add tuna only in the final moments just to warm it", "fix": "Add a drizzle of olive oil to the finished dish to add moisture back"}]', '["The Banana Tradition: In authentic Somali dining, this pasta is often served with a sliced ripe banana on the side or even on top. The sweetness of the banana contrasts beautifully with the savory, spiced sauce.", "Spice Depth: If you cannot find pre-made Xawaash, the homemade blend is essential. The cinnamon and cardamom are what distinguish this from a standard Italian marinara.", "Texture: Using tuna packed in oil yields a richer, moister sauce than water-packed tuna. If using water-packed, add an extra tablespoon of olive oil when finishing.", "Integration: Finish the pasta directly in the sauce. This allows the starch from the pasta to emulsify with the tomato and spices, creating a cohesive dish rather than noodles with sauce sitting on top."]', '"Baasto (pasta) became a Somali staple due to Italian colonization, but it was completely indigenized through the use of Xawaash spice blends and cilantro. It represents the culinary intersection of the Horn of Africa, blending European technique with the ancient spice trade flavors of the region."', 475.66);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('8a4b195a-2092-4d0c-bcd7-40616b7c016f', 'Warm Smashed Potato Salad with Zesty Herb Cream', 'A sophisticated textural hybrid that sits perfectly between a rustic mashed potato and a vibrant potato salad. Fork-crushed Yukon Gold potatoes absorb a bright lemon-mustard vinaigrette while warm, finished with a swirl of crème fraîche for a creamy, chunky mouthfeel that highlights fresh rosemary and scallions.', 'side dish', 'Modern American', 'Easy', '["parsley", "potato", "potato salad", "rosemary", "scallion", "dinner", "lunch", "side dish", "warm salad", "vegetarian"]', '[{"group_name": "Potatoes", "items": [{"name": "yukon gold potatoes", "quantity": 800, "unit": "g", "preparation": "whole, washed (peeling optional)", "notes": "Small to medium size preferred for even cooking", "substitutions": [], "ingredient_id": "a9d640ff-a969-4f0a-9a92-974f376ac272", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 30, "unit": "g", "preparation": null, "notes": "For the boiling water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Zesty Dressing", "items": [{"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 30, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "grated to a paste", "notes": "approx. 4g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "cr\u00e8me fra\u00eeche", "quantity": 60, "unit": "g", "preparation": null, "notes": "Can substitute full-fat Greek yogurt or sour cream", "substitutions": [], "ingredient_id": "e521696c-b719-4569-b7f8-ec0b97abd492", "nutrition_source": "Aggregated Public Data"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Fresh Aromatics", "items": [{"name": "scallions", "quantity": 3, "unit": null, "preparation": "thinly sliced", "notes": "approx. 45g, use both white and green parts", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh rosemary", "quantity": 5, "unit": "g", "preparation": "very finely minced", "notes": null, "substitutions": [], "ingredient_id": "fa90a3a7-86cd-40de-8f8c-0464231925c2", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Place whole potatoes in the large stockpot and cover with cold water by at least 2cm. Add the 30g of salt. Bring to a boil over high heat, then reduce to a simmer.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "While potatoes cook, whisk together olive oil, lemon juice, Dijon mustard, grated garlic, minced rosemary, and black pepper in the large mixing bowl until emulsified. Do not add the cr\u00e8me fra\u00eeche yet.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Check potatoes for doneness. A paring knife should slide into the center with zero resistance. Drain thoroughly in a colander.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Knife meets no resistance in center"}}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Return the drained potatoes to the hot empty pot for 1 minute to steam off excess moisture. This ensures the dressing absorbs properly rather than sliding off.", "structured": {"action": "STEAM", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": ["Dry potatoes equal fluffy results. Wet potatoes equal gluey salad."]}, {"step_number": 5, "phase": "assemble", "text": "Transfer the hot potatoes directly into the bowl with the vinaigrette. Using a potato masher or fork, gently smash the potatoes. Aim for a mix of creamy mash and chunky bite-sized pieces. Do not overwork.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": {"visual": "Chunky, rugged texture, not a smooth puree", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Fold in the scallions, parsley, and cr\u00e8me fra\u00eeche. Toss gently until just combined. Taste and adjust salt if necessary (potatoes soak up salt aggressively). Serve warm.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 250}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 374.08, "protein_g": 5.87, "carbohydrates_g": 45.41, "fat_g": 20.5, "saturated_fat_g": 5.27, "trans_fat_g": null, "monounsaturated_fat_g": 10.98, "polyunsaturated_fat_g": 1.61, "fiber_g": 7.89, "sugar_g": 3.65, "sodium_mg": 3003.01, "cholesterol_mg": null, "potassium_mg": 1386.49, "calcium_mg": 65.19, "iron_mg": 2.24, "magnesium_mg": 96.39, "phosphorus_mg": 206.08, "zinc_mg": 0.13, "vitamin_a_mcg": 68.37, "vitamin_c_mg": 53.04, "vitamin_d_mcg": null, "vitamin_e_mg": 2.27, "vitamin_k_mcg": 94.66, "vitamin_b6_mg": 0.04, "vitamin_b12_mcg": null, "thiamin_mg": 0.02, "riboflavin_mg": 0.02, "niacin_mg": 0.14, "folate_mcg": 15.88, "water_g": 21.83, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves overnight, but texture may become denser.", "duration": "P3D"}, "freezer": {"notes": "Do not freeze; emulsion will break and potatoes will become grainy.", "duration": null}, "reheating": "Gently warm in a microwave at 50% power or fold in a warm pan with a splash of water.", "does_not_keep": false}', '[{"name": "Large stockpot", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Potato masher or sturdy fork", "required": true, "alternative": "Bottom of a heavy jar"}]', '[{"symptom": "Texture is gummy or gluey", "likely_cause": "Potatoes were overworked or beaten too vigorously", "prevention": "Smash gently and stop while chunks remain; do not use a food processor or electric mixer", "fix": "Cannot be fixed completely, but folding in chopped crunchy vegetables (like celery) can mask the texture"}]', '["Dressing the potatoes while they are steaming hot is non-negotiable; as the starch molecules cool, they close up and won''t absorb the vinaigrette.", "Yukon Gold or similar yellow-fleshed potatoes are essential here because they have a natural creaminess that russets lack and a fluffiness that waxy red potatoes lack.", "If you want the rosemary flavor to be more subtle, infuse it into the olive oil by gently heating them together, then discarding the leaves before making the dressing."]', '"This dish reflects the Modern American ''farm-to-table'' philosophy, stripping away the heavy mayonnaise of traditional picnic salads in favor of bright acids and fresh herbs. It borrows the French technique of dressing warm vegetables to maximize flavor absorption."', 374.08);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('8a5b1550-61fb-4bab-b7c8-ac4d92552649', 'Alpine Rye Spätzle & Savoy Cabbage Gratin', 'Nutty, homemade rye drop-noodles tossed with sweet caramelized leeks and tender Savoy cabbage, baked in a rich cream sauce under a bubbling crust of aged Gruyère.', 'main course', 'German', 'Intermediate', '["eastern european", "german", "cabbage", "dinner", "main course", "comfort food", "winter", "vegetarian"]', '[{"group_name": "Rye Sp\u00e4tzle Batter", "items": [{"name": "dark rye flour", "quantity": 150, "unit": "g", "preparation": "fine grind", "notes": "Adds nutty flavor and density", "substitutions": [], "ingredient_id": "af2661d8-b555-4fef-bdee-51a5190eda92", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 150, "unit": "g", "preparation": null, "notes": "Standard wheat flour to provide gluten structure", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 4, "unit": null, "preparation": "large", "notes": "approx. 200g total without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "whole milk", "quantity": 120, "unit": "ml", "preparation": null, "notes": "Adjust slightly based on flour absorbency", "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "nutmeg", "quantity": 1, "unit": "g", "preparation": "freshly grated", "notes": null, "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables & Sauce", "items": [{"name": "unsalted butter", "quantity": 40, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "leeks", "quantity": 300, "unit": "g", "preparation": "cleaned, sliced into half-moons", "notes": "White and light green parts only", "substitutions": [], "ingredient_id": "f0bddafa-51db-4e56-954b-18624daa6fa4", "nutrition_source": "Aggregated Public Data"}, {"name": "savoy cabbage", "quantity": 500, "unit": "g", "preparation": "cored and shredded", "notes": "Napa cabbage can be substituted in a pinch", "substitutions": [], "ingredient_id": "dff437b6-b727-4312-86be-82ff42b14644", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 200, "unit": "ml", "preparation": null, "notes": "Min 35% fat", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "caraway seeds", "quantity": 2, "unit": "g", "preparation": null, "notes": "Optional but traditional", "substitutions": [], "ingredient_id": "5fb07424-aa49-4da5-afeb-0636713c313f", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 60, "unit": "ml", "preparation": null, "notes": "Riesling or Pinot Grigio preferred", "substitutions": [], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Assembly", "items": [{"name": "gruy\u00e8re cheese", "quantity": 200, "unit": "g", "preparation": "coarsely grated", "notes": null, "substitutions": [], "ingredient_id": "321085d2-bb82-45e1-8ae3-5a2ef5cea47f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh chives", "quantity": 10, "unit": "g", "preparation": "minced", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}, {"name": "freshly cracked black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a large mixing bowl, whisk together rye flour, all-purpose flour, salt, and nutmeg. Create a well in the center, add eggs and half the milk. Beat vigorously with a wooden spoon or whisk until bubbles form, adding remaining milk gradually until the batter is thick but flows slowly off the spoon (lava consistency). Let rest for 20 minutes.", "structured": {"action": "MIX", "temperature": null, "duration": "PT25M", "doneness_cues": null}, "tips": ["Rye flour absorbs moisture more slowly than wheat; the rest period is crucial for hydration.", "If the batter is too stiff after resting, add 1 tablespoon of water."]}, {"step_number": 2, "phase": "prep", "text": "While the batter rests, bring a large pot of salted water to a boil. Preheat your oven to 200\u00b0C/400\u00b0F.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Press the batter through a sp\u00e4tzle maker (or colander) into the boiling water in batches. Cook for 2-3 minutes until they float to the surface. Skim them out with a spider strainer, rinse briefly under cold water to stop cooking, and set aside in a colander.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Noodles float to the surface", "tactile": "Firm but tender"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "In the large saut\u00e9 pan, melt butter over medium heat. Saut\u00e9 the leeks and caraway seeds (if using) until the leeks are soft and translucent, about 5 minutes. Add the shredded cabbage and cook for another 5-7 minutes until wilted and tender-crisp.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT12M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Deglaze the pan with white wine, scraping up any fond. Simmer for 1 minute to cook off the alcohol. Pour in the heavy cream and season generously with black pepper. Bring to a simmer, then fold in the cooked sp\u00e4tzle to coat them in the sauce.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Remove pan from heat. Stir in half of the grated Gruy\u00e8re. Transfer the mixture to the baking dish (or smooth the top if using an oven-safe skillet). Top evenly with the remaining cheese.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Bake in the preheated oven for 20-25 minutes until the cheese is bubbling and deeply golden brown. Let stand for 5 minutes before garnishing with fresh chives and serving.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT25M", "doneness_cues": {"visual": "Cheese is golden brown and bubbling", "tactile": null}}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT30M", "total_time": "PT1H15M", "overnight_required": false, "yields": "4 generous servings", "yield_count": 4, "serving_size_g": 380}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Vegans", "Gluten intolerant"]}', '{"per_serving": {"calories": 903.81, "protein_g": 34.92, "carbohydrates_g": 78.81, "fat_g": 49.68, "saturated_fat_g": 28.43, "trans_fat_g": 0.64, "monounsaturated_fat_g": 14.16, "polyunsaturated_fat_g": 3.65, "fiber_g": 11.58, "sugar_g": 9.68, "sodium_mg": 992.26, "cholesterol_mg": 322, "potassium_mg": 823.65, "calcium_mg": 711.4, "iron_mg": 5.04, "magnesium_mg": 141.37, "phosphorus_mg": 700.79, "zinc_mg": 4.69, "vitamin_a_mcg": 675.92, "vitamin_c_mg": 49.13, "vitamin_d_mcg": 2.49, "vitamin_e_mg": 1.83, "vitamin_k_mcg": 91.54, "vitamin_b6_mg": 0.49, "vitamin_b12_mcg": 1.48, "thiamin_mg": 0.32, "riboflavin_mg": 0.65, "niacin_mg": 3.03, "folate_mcg": 152.88, "water_g": 234.59, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves the next day; texture becomes denser.", "duration": "P3D"}, "freezer": {"notes": "Thaw overnight before reheating to prevent sauce separation.", "duration": "P2M"}, "reheating": "Bake covered at 160\u00b0C/320\u00b0F for 20 minutes, or pan-fry slices in butter.", "does_not_keep": false}', '[{"name": "Sp\u00e4tzle maker", "required": true, "alternative": "Colander with large holes and a spatula"}, {"name": "Large stockpot", "required": true, "alternative": null}, {"name": "Large saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Baking dish (approx. 2L capacity)", "required": true, "alternative": null}, {"name": "Spider strainer or slotted spoon", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}]', '[{"symptom": "Sp\u00e4tzle batter falls apart in water", "likely_cause": "Batter is too wet or water is not boiling vigorously enough", "prevention": "Test a small teaspoon of batter first; if it disintegrates, whisk in 1-2 tbsp more flour", "fix": "Add flour to remaining batter immediately"}, {"symptom": "Gratin is watery", "likely_cause": "Cabbage was not cooked down enough before baking", "prevention": "Ensure cabbage volume reduces by half in the saut\u00e9 pan before adding cream", "fix": "Let the dish rest for 10-15 minutes after baking to allow liquids to reabsorb"}]', '["Using 100% rye flour results in a gummy texture; the 50/50 split with all-purpose flour maintains the earthy rye flavor while keeping the dumplings light.", "Do not skip the cold water rinse for the sp\u00e4tzle; this removes excess starch and prevents them from clumping into a giant mass before baking.", "For an extra crisp crust, mix 30g of breadcrumbs with the top layer of cheese.", "Savoy cabbage is superior to standard green cabbage here because its crinkled leaves catch the cream sauce better.", "If you don''t have a sp\u00e4tzle press, you can use the ''Brett'' method: spread batter on a wet cutting board and flick thin strips into the water with a knife."]', '"Sp\u00e4tzle are the definitive noodle of Swabia and the Alpine regions. While traditionally made with wheat, rye variations appear in cooler mountain climates where rye was the hardier crop. This gratin style (K\u00e4sesp\u00e4tzle) is a staple comfort food in German and Austrian huts (H\u00fctte) after a long day of hiking or skiing."', 903.81);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('8a5d4d85-2d03-44a8-850d-db3b764768af', 'Classic American Strawberry Shortcake', 'Tender, flaky, slightly sweet biscuits split open and piled high with juicy macerated strawberries and clouds of freshly whipped vanilla cream. A quintessential summer dessert that balances rich buttery pastry with bright fruit acidity.', 'dessert', 'American', 'Easy', '["kid-friendly", "shortcake", "step by step", "strawberry", "dessert", "summer", "quick", "baking"]', '[{"group_name": "Macerated Strawberries", "items": [{"name": "fresh strawberries", "quantity": 500, "unit": "g", "preparation": "hulled and sliced", "notes": "ripe summer berries are best", "substitutions": [], "ingredient_id": "b2199214-7c2d-4083-92ae-b0a8a044e25b", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 50, "unit": "g", "preparation": null, "notes": "adjust based on berry sweetness", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Shortcake Biscuits", "items": [{"name": "all-purpose flour", "quantity": 250, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 12, "unit": "g", "preparation": null, "notes": "ensure it is fresh for rise", "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 85, "unit": "g", "preparation": "very cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 160, "unit": "ml", "preparation": "cold", "notes": null, "substitutions": ["heavy cream", "half-and-half"], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "coarse sugar", "quantity": 10, "unit": "g", "preparation": null, "notes": "for sprinkling", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Whipped Cream", "items": [{"name": "heavy whipping cream", "quantity": 240, "unit": "ml", "preparation": "very cold", "notes": "35% fat or higher", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "powdered sugar", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a medium bowl, combine sliced strawberries, 50g sugar, and lemon juice. Toss to coat and let sit at room temperature to release their juices.", "structured": {"action": "MACERATE", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": ["This process creates a delicious natural syrup.", "Letting them sit for at least 20 minutes yields the best flavor."]}, {"step_number": 2, "phase": "prep", "text": "Preheat your oven to 220\u00b0C/425\u00b0F. Line a baking sheet with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a large mixing bowl, whisk together the flour, 30g sugar, baking powder, and salt.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Add the cold cubed butter to the flour mixture. Use a pastry blender or your fingertips to rub the butter into the flour until the mixture resembles coarse crumbs with some pea-sized pieces of butter remaining.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Coarse crumbs with pea-sized butter bits", "tactile": "Sandy texture but not greasy"}}, "tips": ["Do not overmix; visible butter pieces create flaky layers."]}, {"step_number": 5, "phase": "prep", "text": "Pour in the cold milk. Stir gently with a fork or spatula just until a shaggy dough forms and the dry ingredients are moistened.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "Turn dough onto a lightly floured surface. Gently pat (do not roll) into a rectangle about 2cm thick. Use a biscuit cutter to punch out rounds. Place on the prepared baking sheet, touching slightly. Sprinkle tops with coarse sugar if desired.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": {"visual": "2cm thick rounds", "tactile": null}}, "tips": ["Press the cutter straight down without twisting to ensure high rising biscuits.", "Gather scraps gently to cut remaining biscuits."]}, {"step_number": 7, "phase": "cook", "text": "Bake for 12-15 minutes until the tops are golden brown and the biscuits have risen significantly.", "structured": {"action": "BAKE", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT15M", "doneness_cues": {"visual": "Golden brown tops", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "While biscuits bake, combine heavy cream, powdered sugar, and vanilla in a clean bowl. Whip until soft-to-medium peaks form.", "structured": {"action": "WHIP", "temperature": null, "duration": null, "doneness_cues": {"visual": "Soft peaks that hold shape", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove biscuits from oven and transfer to a wire rack to cool slightly. They should be warm but not hot when serving.", "structured": {"action": "COOL", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "assemble", "text": "Slice the warm biscuits in half horizontally. Spoon the macerated strawberries and their syrup over the bottom halves. Top generously with whipped cream and the biscuit caps. Serve immediately.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT20M", "total_time": "PT45M", "overnight_required": false, "yields": "6 shortcakes", "yield_count": 6, "serving_size_g": 185}', '{"flags": ["Vegetarian", "Egg-Free", "Soy-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": ["Vegan", "Gluten-Free", "Dairy-Free"]}', '{"per_serving": {"calories": 503.59, "protein_g": 6.95, "carbohydrates_g": 58.83, "fat_g": 27.46, "saturated_fat_g": 16.92, "trans_fat_g": 0.5, "monounsaturated_fat_g": 7.24, "polyunsaturated_fat_g": 1.4, "fiber_g": 2.8, "sugar_g": 24.25, "sodium_mg": 431.78, "cholesterol_mg": 78.33, "potassium_mg": 251.57, "calcium_mg": 197.55, "iron_mg": 1.12, "magnesium_mg": 26.44, "phosphorus_mg": 157.92, "zinc_mg": 0.62, "vitamin_a_mcg": 274.4, "vitamin_c_mg": 49.56, "vitamin_d_mcg": 0.99, "vitamin_e_mg": 0.98, "vitamin_k_mcg": 4.31, "vitamin_b6_mg": 0.09, "vitamin_b12_mcg": 0.21, "thiamin_mg": 0.09, "riboflavin_mg": 0.17, "niacin_mg": 0.9, "folate_mcg": 34.36, "water_g": 130.98, "alcohol_g": 0.29, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store components separately. Assembled shortcakes will become soggy within hours.", "duration": "P1D"}, "freezer": {"notes": "Baked biscuits can be frozen. Reheat in oven before serving.", "duration": "P1M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Medium mixing bowl", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Pastry blender", "required": false, "alternative": "Two forks or fingertips"}, {"name": "Biscuit cutter (7cm)", "required": false, "alternative": "Rim of a glass or knife"}, {"name": "Electric mixer or whisk", "required": true, "alternative": null}]', '[{"symptom": "Biscuits are tough and flat", "likely_cause": "The dough was overworked or the butter melted before baking", "prevention": "Handle the dough as little as possible and keep ingredients very cold", "fix": "Cannot be fixed, but can be crumbled for a trifle"}, {"symptom": "Biscuits rose unevenly", "likely_cause": "Twisting the cutter sealed the edges", "prevention": "Press the cutter straight down and lift straight up", "fix": "None, cosmetic issue only"}]', '["Temperature is key for the biscuits: ensure your butter and milk are fridge-cold to create steam pockets for a flaky rise.", "If your strawberries are not very sweet or juicy, you can mash a few of them with a fork to help create more syrup.", "For an extra rich version, brush the tops of the unbaked biscuits with a little heavy cream before sprinkling with sugar.", "This recipe uses the American ''biscuit'' style base, which is more savory and substantial than sponge cake, providing a perfect texture contrast to the soft fruit and cream."]', '"Shortcake dates back to 16th century England, but the modern strawberry version is a distinctly American classic, popularized in the mid-19th century during ''Strawberry Fever''. Unlike sponge cake versions, the authentic American shortcake uses a biscuit or scone-like base to soak up the fruit juices."', 503.59);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('8abc780e-d973-4e44-b975-beda8607d52d', 'Creamy Cinnamon-Stewed Tomatoes on Sourdough', 'A deceptively simple yet sophisticated comfort dish where acidity meets velvet. Whole canned tomatoes are reduced with butter and a cinnamon stick until jammy, then enriched with heavy cream to create a luxuriant, blush-colored sauce served over crisp, tart sourdough toast.', 'breakfast', 'American', 'Easy', '["vegetables", "canned tomato", "cinnamon stick", "five ingredient", "heavy cream", "sourdough", "breakfast", "brunch", "lunch", "weeknight", "dinner", "side"]', '[{"group_name": "Stewed Tomatoes", "items": [{"name": "whole peeled tomatoes", "quantity": 400, "unit": "g", "preparation": "canned", "notes": "preferably San Marzano; do not drain", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "cold", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "cinnamon stick", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 3g", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 120, "unit": "ml", "preparation": "room temperature", "notes": "minimum 35% fat", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, start with 3g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "freshly cracked black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Serving", "items": [{"name": "sourdough bread", "quantity": 2, "unit": null, "preparation": "thick slices", "notes": "approx 50g each", "substitutions": [], "ingredient_id": "90f297c6-9ec3-45a6-850d-9aa9c65b45e7", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "cook", "text": "In a wide skillet, combine the entire contents of the tomato can (juice and fruit), the butter, and the cinnamon stick. Bring to a simmer over medium heat.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Continue to cook, crushing the tomatoes roughly with a wooden spoon, until the liquid has reduced by about half and the mixture looks glossy.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Liquid reduced by half, thickened consistency", "tactile": "Tomatoes break apart easily"}}, "tips": ["Do not mash into a puree; leave rustic chunks for texture."]}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to low. Stir in the heavy cream, salt, and pepper. Simmer gently until the sauce thickens and turns a uniform creamy orange-pink color. Remove the cinnamon stick.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT5M", "doneness_cues": {"visual": "Coats the back of a spoon (nappe)", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "While the sauce finishes, toast the sourdough slices until golden brown and sturdy enough to hold the weight of the sauce.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown", "tactile": "Crisp surface"}}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Place toast on warm plates. Ladle the creamy tomato mixture generously over the bread. Serve immediately.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT5M", "passive_time": "PT20M", "total_time": "PT25M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 320}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free", "Peanut-Free"], "not_suitable_for": ["Vegans (contains dairy)", "Gluten intolerant (contains sourdough)"]}', '{"per_serving": {"calories": 482.26, "protein_g": 7.96, "carbohydrates_g": 34.83, "fat_g": 34.78, "saturated_fat_g": 21.45, "trans_fat_g": 0.75, "monounsaturated_fat_g": 8.98, "polyunsaturated_fat_g": 1.4, "fiber_g": 5.77, "sugar_g": 10.15, "sodium_mg": 1157.6, "cholesterol_mg": 100.05, "potassium_mg": 547.84, "calcium_mg": 80.78, "iron_mg": 0.79, "magnesium_mg": 28.27, "phosphorus_mg": 88.15, "zinc_mg": 0.53, "vitamin_a_mcg": 349.56, "vitamin_c_mg": 27.82, "vitamin_d_mcg": 0.96, "vitamin_e_mg": 0.94, "vitamin_k_mcg": 4.26, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": 0.12, "thiamin_mg": 0.01, "riboflavin_mg": 0.12, "niacin_mg": 0.07, "folate_mcg": 3.03, "water_g": 37.28, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store sauce separate from toast. Reheat gently to avoid splitting.", "duration": "P3D"}, "freezer": {"notes": "Cream-based sauces do not freeze well; texture will degrade.", "duration": null}, "reheating": "Reheat gently on the stovetop over low heat.", "does_not_keep": false}', '[{"name": "Wide skillet or saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": null}, {"name": "Toaster or grill pan", "required": true, "alternative": null}]', '[{"symptom": "Sauce curdles or looks grainy", "likely_cause": "Heat was too high after adding cream, or tomatoes were too acidic", "prevention": "Lower heat before adding cream; ensure cream is not fridge-cold", "fix": "Remove from heat immediately and whisk in a tablespoon of cold liquid cream to re-emulsify"}]', '["The cinnamon stick provides a subtle, warming aromatic backdrop that enhances the natural sweetness of the tomatoes without making the dish taste like a dessert.", "Use high-quality canned tomatoes (like San Marzano D.O.P.) as they have a lower acidity and higher natural sweetness, which is crucial for this minimal ingredient list.", "If your tomatoes taste very acidic, a pinch of sugar (1-2g) added with the salt can balance the flavor profile significantly."]', '"This dish is a nod to old-school American culinary heritage, specifically recalling the style of James Beard, who championed the simple elegance of tomatoes stewed in cream. It transforms pantry staples into a meal that feels both rustic and refined."', 482.26);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('8b0c5806-eebb-42a3-9e92-b3e87a2fab58', 'Spicy Garlic Lemon Grilled Jumbo Shrimp', 'Plump, succulent jumbo shrimp infused with a vibrant Mediterranean marinade of extra virgin olive oil, zesty lemon, and pungent garlic. The red pepper flakes add a gentle heat that cuts through the richness, while the grill provides a smoky char that enhances the natural sweetness of the shellfish.', 'dinner', 'Mediterranean', 'Easy', '["jumbo shrimp", "dinner", "main course", "summer", "grilling", "seafood", "low carb"]', '[{"group_name": "Seafood", "items": [{"name": "jumbo shrimp", "quantity": 900, "unit": "g", "preparation": "peeled and deveined", "notes": "16-20 count per pound; tails left on for presentation", "substitutions": ["large scallops", "langoustines"], "ingredient_id": "a6bf7ab3-9b88-4c5b-a2fa-966c40a0e5a7", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Marinade & Finish", "items": [{"name": "extra virgin olive oil", "quantity": 80, "unit": "ml", "preparation": "liquid", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 4, "unit": null, "preparation": "minced", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 2, "unit": null, "preparation": "whole", "notes": "zest of both, juice of one for marinade, one sliced for grilling", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "red pepper flakes", "quantity": 3, "unit": "g", "preparation": null, "notes": "adjust to heat tolerance", "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 6, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "flat-leaf parsley", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": "for garnish", "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the peeled and deveined shrimp thoroughly dry with paper towels. Removing surface moisture is crucial for achieving a good sear and preventing the marinade from sliding off.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, combine the olive oil, minced garlic, red pepper flakes, salt, black pepper, the zest of two lemons, and the juice of one lemon (reserve the second lemon for grilling). Whisk to emulsify.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Add the shrimp to the bowl and toss to coat evenly. Let stand at room temperature for 15 to 20 minutes. Do not exceed 30 minutes, as the lemon juice will begin to cure the shrimp (ceviche effect), altering the texture.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "While the shrimp marinates, preheat your grill to medium-high heat (approx. 200\u00b0C/400\u00b0F). If using bamboo skewers, soak them in water now to prevent burning.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Thread the shrimp onto skewers, piercing through the tail and the thickest part of the body to prevent spinning. Place skewers on the hot grill. Grill for 2-3 minutes per side until pink, opaque, and slightly charred. The internal temperature should reach 63\u00b0C/145\u00b0F.", "structured": {"action": "GRILL", "temperature": {"celsius": 63, "fahrenheit": 145}, "duration": "PT5M", "doneness_cues": {"visual": "Pink and opaque exterior, pearly white interior", "tactile": "Firm with slight spring back"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove shrimp from the grill immediately to prevent rubberiness. Garnish with chopped parsley and serve alongside grilled lemon slices.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT20M", "total_time": "PT40M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 225}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Low-Carb", "Keto", "Paleo", "Whole30", "Sugar-Free"], "not_suitable_for": ["Shellfish allergy"]}', '{"per_serving": {"calories": 389.84, "protein_g": 46.14, "carbohydrates_g": 5.94, "fat_g": 21.47, "saturated_fat_g": 3.04, "trans_fat_g": null, "monounsaturated_fat_g": 14.84, "polyunsaturated_fat_g": 2.56, "fiber_g": 1.71, "sugar_g": 1.21, "sodium_mg": 853.94, "cholesterol_mg": 362.25, "potassium_mg": 707.5, "calcium_mg": 169.54, "iron_mg": 1.93, "magnesium_mg": 86.79, "phosphorus_mg": 498.05, "zinc_mg": 3.14, "vitamin_a_mcg": 31.95, "vitamin_c_mg": 29.02, "vitamin_d_mcg": null, "vitamin_e_mg": 3.2, "vitamin_k_mcg": 75.01, "vitamin_b6_mg": 0.1, "vitamin_b12_mcg": null, "thiamin_mg": 0.03, "riboflavin_mg": 0.02, "niacin_mg": 0.18, "folate_mcg": 11.35, "water_g": 219.4, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Texture may become slightly firmer upon reheating.", "duration": "P2D"}, "freezer": {"notes": "Freezing cooked shrimp is not recommended as it degrades the texture.", "duration": null}, "reheating": "Gently saut\u00e9 in a pan over low heat with a splash of water or oil just until warm, or eat cold over salads.", "does_not_keep": false}', '[{"name": "Outdoor Grill or Grill Pan", "required": true, "alternative": "Cast iron skillet"}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Metal or Bamboo Skewers", "required": true, "alternative": "Grill basket"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Microplane or Zester", "required": true, "alternative": null}]', '[{"symptom": "Shrimp texture is rubbery and tough", "likely_cause": "Overcooking", "prevention": "Remove shrimp from heat the moment they turn opaque and form a ''C'' shape. If they curl into a tight ''O'', they are overcooked.", "fix": "Cannot be fixed"}, {"symptom": "Shrimp stuck to the grill grates", "likely_cause": "Grill was not clean or not hot enough, or shrimp weren''t oiled enough", "prevention": "Clean grates thoroughly, oil them lightly before adding shrimp, and ensure high heat before cooking.", "fix": "Use a thin metal spatula to gently work them free from the bottom up"}]', '["If using wooden skewers, soaking them for 30 minutes is non-negotiable to prevent them from disintegrating over the fire.", "For the best flavor, use fresh garlic rather than jarred; the high heat brings out a sweetness in fresh garlic that jarred versions lack.", "Grilling lemon halves cut-side down for 2-3 minutes caramelizes the sugars and makes the juice sweeter and more complex for squeezing over the finished dish.", "Leave the tails on the shrimp; the shells contain chitin which adds subtle flavor during cooking and acts as a convenient handle for eating."]', '"Grilled seafood seasoned with olive oil, lemon, and garlic is a cornerstone of coastal Mediterranean cuisine, particularly in Greece and Southern Italy. This style of preparation emphasizes the freshness of the catch (ingredients are rarely masked by heavy sauces) and the communal, alfresco dining culture of the region."', 389.84);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('8c3d0523-56e3-4a5d-b9b2-57317f965bf5', 'Five-Spice Roast Duck with Miso-Ginger Sweet Potato', 'Crispy-skinned roast duck aromatic with star anise and cinnamon, balanced by a velvety, savory-sweet miso sweet potato puree and garlicky bok choy. A centerpiece dish contrasting rich textures with bright Asian aromatics.', 'dinner', 'Asian Fusion', 'Advanced', '["asian", "roasts", "duck", "ginger", "sweet potato", "dinner", "main course", "fusion"]', '[{"group_name": "Duck Preparation", "items": [{"name": "whole duck", "quantity": 2200, "unit": "g", "preparation": "thawed, neck and giblets removed", "notes": "approx 2-2.5kg", "substitutions": [], "ingredient_id": "8507b855-b997-45ac-94c7-3619f4f33cf5", "nutrition_source": "USDA FoodData Central"}, {"name": "boiling water", "quantity": 1500, "unit": "ml", "preparation": null, "notes": "for scalding skin", "substitutions": [], "ingredient_id": "f6c955d4-a232-4b75-b391-c11f82b39685", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 15, "unit": "g", "preparation": null, "notes": "for dry brining", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Cavity Aromatics", "items": [{"name": "ginger", "quantity": 30, "unit": "g", "preparation": "sliced", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "smashed", "notes": "approx 20g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "star anise", "quantity": 3, "unit": null, "preparation": null, "notes": "whole pods", "substitutions": [], "ingredient_id": "a3628b5f-82b9-4d80-b0cc-af35895a4f21", "nutrition_source": "Aggregated Public Data"}, {"name": "scallions", "quantity": 2, "unit": null, "preparation": "halved", "notes": "approx 30g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "five-spice powder", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "d1ea2b6c-ef58-4e15-b80d-9b3fc89c375f", "nutrition_source": "Aggregated Public Data"}, {"name": "hoisin sauce", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": ["Tamari mixed with brown sugar"], "ingredient_id": "31ea71a1-8cd0-4400-8d01-4643b43c1a05", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Honey Glaze", "items": [{"name": "honey", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "soy sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["Tamari for GF"], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "rice vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fcbf5252-1be9-4dd4-8c22-4fda1dbdca28", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Miso-Ginger Sweet Potato Puree", "items": [{"name": "sweet potatoes", "quantity": 800, "unit": "g", "preparation": "peeled and cubed", "notes": null, "substitutions": [], "ingredient_id": "579039f4-fa1e-4c91-8355-9dd037d188cd", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "white miso paste", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "46697260-96ba-4751-83c0-b40aebb81229", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 10, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["Coconut milk"], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garlic Bok Choy", "items": [{"name": "baby bok choy", "quantity": 400, "unit": "g", "preparation": "halved lengthwise", "notes": null, "substitutions": [], "ingredient_id": "562bdece-f897-4d03-be7a-94be5ef3f681", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "sesame oil", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e74beff5-5295-4a3f-82fb-9f8ef1d5da59", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Clean the duck. Using a sharp knife or skewer, prick the skin all over (breast, legs, back) without piercing the meat underneath. This allows fat to render.", "structured": {"action": "SCORE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Small punctures covering skin surface", "tactile": null}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Place the duck on a rack over a sink. Pour boiling water over the duck skin. The skin will immediately tighten and shrink. Pat thoroughly dry with paper towels.", "structured": {"action": "BLANCH", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Mix hoisin sauce, five-spice powder, ginger slices, smashed garlic, star anise, and scallions. Rub this mixture strictly inside the cavity of the duck. Seal the cavity with a skewer if possible.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Rub the exterior skin with the sea salt. Place the duck uncovered on a rack in the refrigerator for at least 24 hours to dry out the skin.", "structured": {"action": "CURE", "temperature": null, "duration": "P1D", "doneness_cues": {"visual": null, "tactile": "Skin feels dry and parchment-like"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Preheat oven to 170\u00b0C (340\u00b0F). Place the duck breast-side up on a rack in a roasting pan. Roast for 1 hour and 20 minutes.", "structured": {"action": "ROAST", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": "PT1H20M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "While duck roasts, boil sweet potatoes in salted water until very tender (about 15-20 minutes). Drain well.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Mash the sweet potatoes with butter, miso paste, grated ginger, and cream until smooth. Keep warm.", "structured": {"action": "MASH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "In a small saucepan, combine honey, soy sauce, and rice vinegar. Simmer for 2 minutes until slightly thickened to create the glaze.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Increase oven temperature to 220\u00b0C (425\u00b0F). Brush the duck with the glaze. Roast for another 10-15 minutes until skin is mahogany and crispy. Internal temperature at the thickest part of the thigh must reach 74\u00b0C (165\u00b0F).", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT15M", "doneness_cues": {"visual": "Dark mahogany skin", "tactile": "Crispy skin"}}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Remove duck from oven and let rest for at least 15 minutes before carving. While resting, heat oil in a skillet over high heat. Saut\u00e9 bok choy with minced garlic for 3-4 minutes until wilted but crunchy. Finish with sesame oil.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT4M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT50M", "passive_time": "P1DT2H", "total_time": "P1DT2H50M", "overnight_required": true, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Gluten-Free"], "not_suitable_for": ["Infants under 12 months (honey)"]}', '{"per_serving": {"calories": 1782.31, "protein_g": 86.86, "carbohydrates_g": 121.96, "fat_g": 104.92, "saturated_fat_g": 33.04, "trans_fat_g": 0.19, "monounsaturated_fat_g": 42.8, "polyunsaturated_fat_g": 9.79, "fiber_g": 16.2, "sugar_g": 39.67, "sodium_mg": 4192.93, "cholesterol_mg": 4911.2, "potassium_mg": 2789.33, "calcium_mg": 888.85, "iron_mg": 47.84, "magnesium_mg": 277.34, "phosphorus_mg": 1550.3, "zinc_mg": 11.38, "vitamin_a_mcg": 13184.3, "vitamin_c_mg": 42.84, "vitamin_d_mcg": 9.59, "vitamin_e_mg": 8.21, "vitamin_k_mcg": 23.24, "vitamin_b6_mg": 2.59, "vitamin_b12_mcg": 29.76, "thiamin_mg": 1.89, "riboflavin_mg": 3.06, "niacin_mg": 12.67, "folate_mcg": 613.57, "water_g": 737.16, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store duck meat and puree separately. Skin will lose crispness.", "duration": "P3D"}, "freezer": {"notes": "Puree freezes well; duck meat freezes well but texture degrades slightly.", "duration": "P2M"}, "reheating": "Reheat duck in a 200\u00b0C oven to recrisp skin. Reheat puree gently on stove.", "does_not_keep": false}', '[{"name": "Roasting pan with rack", "required": true, "alternative": "Wire cooling rack set over a rimmed baking sheet"}, {"name": "Large pot", "required": true, "alternative": "Wok for blanching"}, {"name": "Saucepan", "required": true, "alternative": null}, {"name": "Potato masher", "required": true, "alternative": "Ricers or Food Processor"}, {"name": "Skillet", "required": true, "alternative": null}, {"name": "Sharp knife", "required": true, "alternative": null}]', '[{"symptom": "Duck skin is soggy or chewy", "likely_cause": "Skin was not dried thoroughly enough before roasting or humidity in oven was too high", "prevention": "Ensure the 24-hour uncovered fridge drying step is not skipped; prick skin well to release fat", "fix": "Increase oven heat to 230\u00b0C (450\u00b0F) or use broiler/grill setting for 2-3 minutes, watching constantly to prevent burning"}]', '["Pricking the skin is the secret to non-greasy duck. Be careful to angle the knife almost parallel to the skin to avoid piercing the meat, which would release juices and steam the skin.", "Save the rendered duck fat from the roasting pan. It is liquid gold for roasting potatoes or saut\u00e9ing vegetables in future meals.", "If using a convection (fan) oven, reduce cooking temperatures by 20\u00b0C to prevent the glaze from burning before the meat is cooked.", "The miso in the potatoes adds a savory depth (umami) that cuts through the richness of the duck fat much better than plain butter."]', '"This dish borrows the technique of air-drying from traditional Peking Duck preparation to ensure crispy skin, while pairing it with Western-style purees infused with Japanese ingredients (miso). It represents a modern, global approach to the classic Sunday roast."', 1782.31);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('8d1f65f4-0572-45f8-947a-4f34af4bf1cb', 'Nigerian Puff Puff with Spiced Sugar', 'Golden, spherical fried dough balls with a sponge-like, airy interior and a slightly crisp exterior. Heavily scented with warm nutmeg and optionally tossed in an aromatic allspice and clove sugar coating, these are a beloved West African staple.', 'snack', 'Nigerian', 'Intermediate', '["finger foods", "pastries", "active dry yeast", "allspice", "clove", "nigerian", "nutmeg", "snack", "dessert", "thanksgiving"]', '[{"group_name": "Dough", "items": [{"name": "all-purpose flour", "quantity": 250, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "active dry yeast", "quantity": 7, "unit": "g", "preparation": null, "notes": "1 sachet", "substitutions": [], "ingredient_id": "b5658d19-b726-4ddb-b56e-74884c61e753", "nutrition_source": "USDA FoodData Central"}, {"name": "ground nutmeg", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 1.5 tsp, freshly grated preferred", "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1/2 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "warm water", "quantity": 220, "unit": "ml", "preparation": "35-40\u00b0C", "notes": "may need up to 240ml depending on humidity", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Frying", "items": [{"name": "vegetable oil", "quantity": 1000, "unit": "ml", "preparation": "neutral oil with high smoke point", "notes": "quantity depends on pot size; minimal depth of 8cm required", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}]}, {"group_name": "Spiced Sugar (Optional)", "items": [{"name": "granulated sugar", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "ground allspice", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "d0b9d4b4-744d-472b-bb19-a779a23d70c6", "nutrition_source": "USDA FoodData Central"}, {"name": "ground clove", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "7b3bf68a-3ae9-4dad-91f4-6c7a14ec5e0e", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a small bowl, combine the warm water (around 38\u00b0C/100\u00b0F), 1 teaspoon of the sugar, and the active dry yeast. Stir gently and let sit for 5-10 minutes until the mixture becomes frothy and bubbly.", "structured": {"action": "MIX", "temperature": {"celsius": 38, "fahrenheit": 100}, "duration": "PT10M", "doneness_cues": null}, "tips": ["If the yeast doesn''t foam, it is dead. Start over with fresh yeast."]}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, whisk together the flour, remaining sugar, ground nutmeg, and salt.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Pour the activated yeast mixture into the dry ingredients. Mix by hand or with a wooden spoon until a smooth, thick, stretchy batter forms. It should be thicker than pancake batter but looser than bread dough.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Smooth, glossy, no dry flour lumps", "tactile": "Sticky and stretchy"}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Cover the bowl with cling film or a clean kitchen towel. Place in a warm, draft-free area and let it proof for 45-60 minutes, or until the batter has doubled in size and is full of air bubbles.", "structured": {"action": "PROOF", "temperature": null, "duration": "PT1H", "doneness_cues": {"visual": "Doubled in volume, bubbly surface", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "While the batter finishes rising, heat the vegetable oil in a deep pot to 170\u00b0C (340\u00b0F). Ensure there is at least 8cm (3 inches) of oil depth.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": null, "doneness_cues": null}, "tips": ["Use a thermometer. If the oil is too hot, the outside burns before the inside cooks."]}, {"step_number": 6, "phase": "cook", "text": "Using your hand (traditional method) or a small cookie scoop, drop ping-pong sized balls of batter into the hot oil. Do not overcrowd the pan.", "structured": {"action": "FRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["To shape by hand: grab a handful of batter and squeeze it out between your thumb and index finger to form a round ball."]}, {"step_number": 7, "phase": "cook", "text": "Fry for 3-5 minutes, turning the balls frequently with a slotted spoon to ensure even browning. They should be a rich golden brown on all sides.", "structured": {"action": "FRY", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Deep golden brown floating on surface", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove the puff puffs with a slotted spoon and drain on a wire rack or paper towels.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Optional: While still warm, toss the puff puffs in a bowl with the sugar, allspice, and clove mixture until coated.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT1H", "total_time": "PT1H25M", "overnight_required": false, "yields": "24 balls", "yield_count": 24, "serving_size_g": 60}', '{"flags": ["Vegetarian", "Vegan", "Dairy-Free", "Egg-Free", "Soy-Free", "Peanut-Free"], "not_suitable_for": ["Individuals with gluten intolerance"]}', '{"per_serving": {"calories": 57.48, "protein_g": 1.2, "carbohydrates_g": 12.77, "fat_g": 0.18, "saturated_fat_g": 0.05, "trans_fat_g": null, "monounsaturated_fat_g": 0.03, "polyunsaturated_fat_g": 0.05, "fiber_g": 0.41, "sugar_g": 4.61, "sodium_mg": 33.13, "cholesterol_mg": null, "potassium_mg": 15.37, "calcium_mg": 2.67, "iron_mg": 0.14, "magnesium_mg": 2.93, "phosphorus_mg": 13.46, "zinc_mg": 0.1, "vitamin_a_mcg": 0.02, "vitamin_c_mg": 0.02, "vitamin_d_mcg": null, "vitamin_e_mg": 0.01, "vitamin_k_mcg": 0.09, "vitamin_b6_mg": 0.01, "vitamin_b12_mcg": null, "thiamin_mg": 0.05, "riboflavin_mg": 0.02, "niacin_mg": 0.25, "folate_mcg": 9.65, "water_g": 10.44, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Texture degrades quickly; store in airtight container.", "duration": "P2D"}, "freezer": {"notes": "Freeze in single layer then bag. Reheat in oven.", "duration": "P1M"}, "reheating": "Reheat in a 175\u00b0C (350\u00b0F) oven for 5-7 minutes to restore crispness. Microwave makes them chewy.", "does_not_keep": false}', '[{"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Heavy-bottomed pot or Dutch oven", "required": true, "alternative": "Deep fryer"}, {"name": "Kitchen thermometer", "required": true, "alternative": "Wooden chopstick (check for bubbles)"}, {"name": "Slotted spoon", "required": true, "alternative": null}, {"name": "Cling film or clean kitchen towel", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}]', '[{"symptom": "Puff Puffs are raw or doughy in the center", "likely_cause": "Oil temperature was too high", "prevention": "Maintain oil consistently at 170\u00b0C (340\u00b0F) using a thermometer", "fix": "Lower heat immediately; finish undercooked batch in a 175\u00b0C oven for 5 mins"}, {"symptom": "Puff Puffs are extremely oily and greasy", "likely_cause": "Oil temperature was too low", "prevention": "Ensure oil returns to temperature between batches", "fix": "Drain on wire rack in a warm oven to encourage oil drainage (partial fix only)"}, {"symptom": "Dough did not rise", "likely_cause": "Yeast was dead or water was too hot (killed yeast)", "prevention": "Check expiration date; water should feel warm like a bath, not scalding", "fix": "Cannot be fixed; must start over with fresh yeast"}]', '["The traditional round shape is achieved by the ''squeeze'' technique: grab the batter and extrude it through the circle formed by your thumb and index finger.", "Nutmeg is the defining flavor here. Use freshly grated whole nutmeg for a significantly more aromatic result than pre-ground powder.", "Do not overcrowd the frying pot. Too many balls at once drops the oil temperature drastically, resulting in soggy, greasy pastries.", "While traditionally eaten plain, the spiced sugar coating adds a festive, autumn-like flair suitable for holiday gatherings."]', '"Puff Puff is a quintessential Nigerian ''small chop'' (finger food), ubiquitous at weddings, parties, and on street corners. Similar versions exist across West and Central Africa (such as Ghanaian Bofrot or Cameroonian Gateau), showcasing the region''s shared culinary heritage of deep-fried yeast doughs."', 57.48);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('8d20d36e-9eaa-4a17-8676-ce6c0a3f47e4', 'Summer Squash and Black Bean Tacos with Goat Cheese', 'A vibrant, textural vegetarian taco filling featuring sautéed summer squash, bursting cherry tomatoes, and hearty black beans. The earthy filling is brightened with lime and cilantro, then finished with cool, tangy crumbles of goat cheese.', 'main course', 'Mexican', 'Easy', '["mexican", "tacos", "brunch", "dinner", "lunch", "appetizer", "main course", "spring", "summer", "gluten-free", "halal", "high fiber", "kosher", "low cholesterol", "low-sodium", "nut-free", "vegetarian"]', '[{"group_name": "Vegetables & Aromatics", "items": [{"name": "zucchini or summer squash", "quantity": 400, "unit": "g", "preparation": "diced into 1cm cubes", "notes": null, "substitutions": [], "ingredient_id": "d0aa0d47-cefe-4ece-a337-e656f79b74e9", "nutrition_source": "Aggregated Public Data"}, {"name": "cherry tomatoes", "quantity": 250, "unit": "g", "preparation": "halved", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "red onion", "quantity": 100, "unit": "g", "preparation": "finely diced", "notes": null, "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx. 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "lime", "quantity": 1, "unit": null, "preparation": "cut into wedges", "notes": null, "substitutions": [], "ingredient_id": "d3d2677e-fe02-4404-add0-29d73df7e921", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pantry & Spices", "items": [{"name": "black beans", "quantity": 240, "unit": "g", "preparation": "cooked, rinsed and drained", "notes": "one standard 400g can yields approx 240g drained", "substitutions": [], "ingredient_id": "ff8b9618-3332-4acf-99ad-a9df04dd2643", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "chili powder", "quantity": 2, "unit": "g", "preparation": null, "notes": "mild blend, approx 1 tsp", "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika", "quantity": 1, "unit": "g", "preparation": null, "notes": "approx 0.5 tsp", "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "adjust to taste; keep low for dietary requirements", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Serving", "items": [{"name": "corn tortillas", "quantity": 12, "unit": null, "preparation": null, "notes": "10-12cm diameter; approx 300g total", "substitutions": [], "ingredient_id": "da963b85-8f0b-4c36-b9b1-c31e17b488ae", "nutrition_source": "Aggregated Public Data"}, {"name": "goat cheese", "quantity": 120, "unit": "g", "preparation": "crumbled", "notes": null, "substitutions": [], "ingredient_id": "d76dc7f0-bd74-4e8b-ab88-1dc167eeb20b", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Drain and thoroughly rinse the black beans in a colander to remove excess sodium and starch. Shake dry.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat olive oil in a large skillet over medium heat (approx. 175\u00b0C/350\u00b0F). Add the diced red onion and saut\u00e9 until softened and translucent.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT4M", "doneness_cues": {"visual": "Onions are translucent", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Stir in the minced garlic, cumin, chili powder, and smoked paprika. Cook for 30 seconds until fragrant, being careful not to burn the garlic.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT30S", "doneness_cues": {"visual": "Spices are fragrant", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the diced squash and salt. Increase heat to medium-high and saut\u00e9, stirring occasionally, until the squash is tender-crisp and lightly browned.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT6M", "doneness_cues": {"visual": "Squash is golden on edges", "tactile": "Tender-crisp"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the black beans and halved cherry tomatoes to the pan. Cook gently until the beans are heated through and the tomatoes just begin to soften and release their juices.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Tomatoes slightly collapsed", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove from heat. Stir in half of the chopped cilantro and a squeeze of fresh lime juice.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Warm the corn tortillas. You can do this directly over a gas flame for a few seconds per side for char, or in a dry skillet over high heat.", "structured": {"action": "TOAST", "temperature": null, "duration": null, "doneness_cues": {"visual": "Light char marks or pliable", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Divide the vegetable mixture among the warm tortillas. Top with crumbled goat cheese and remaining cilantro. Serve immediately with extra lime wedges.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT0M", "total_time": "PT25M", "overnight_required": false, "yields": "12 tacos", "yield_count": 4, "serving_size_g": 320}', '{"flags": ["Vegetarian", "Gluten-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Low-Sodium"], "not_suitable_for": []}', '{"per_serving": {"calories": 444.31, "protein_g": 16.92, "carbohydrates_g": 55.08, "fat_g": 19.39, "saturated_fat_g": 7.78, "trans_fat_g": null, "monounsaturated_fat_g": 6.11, "polyunsaturated_fat_g": 2.03, "fiber_g": 12.46, "sugar_g": 6.81, "sodium_mg": 466.99, "cholesterol_mg": null, "potassium_mg": 628.07, "calcium_mg": 199.95, "iron_mg": 3.44, "magnesium_mg": 97.75, "phosphorus_mg": 445.95, "zinc_mg": 1.75, "vitamin_a_mcg": 212.3, "vitamin_c_mg": 18.73, "vitamin_d_mcg": null, "vitamin_e_mg": 2, "vitamin_k_mcg": 6.91, "vitamin_b6_mg": 0.27, "vitamin_b12_mcg": null, "thiamin_mg": 0.18, "riboflavin_mg": 0.15, "niacin_mg": 1.69, "folate_mcg": 47.16, "water_g": 121.83, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store filling separately from tortillas and cheese.", "duration": "P3D"}, "freezer": {"notes": "Squash becomes mushy upon thawing; freezing not recommended.", "duration": null}, "reheating": "Reheat filling in a skillet over medium heat until warm; warm fresh tortillas separately.", "does_not_keep": false}', '[{"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "Filling is watery/soggy", "likely_cause": "Tomatoes were cooked too long or squash released too much water without high enough heat", "prevention": "Cook squash over medium-high heat to sear rather than steam; add tomatoes at the very end", "fix": "Use a slotted spoon to serve the filling, leaving excess liquid in the pan"}]', '["To ensure this is truly low-sodium, rinse the canned beans very thoroughly; this can reduce sodium content by up to 40%.", "Don''t skip warming the corn tortillas. Cold corn tortillas are brittle and likely to break. Toasting them makes them pliable and enhances the corn flavor.", "For a smoky depth, let the squash sit undisturbed in the pan for a minute or two to develop a sear before stirring.", "If you cannot find ''summer squash'' specifically, standard green zucchini or yellow zucchini work perfectly interchangeably."]', '"While tacos originate from Mexico, this version embraces the ''Calabacitas'' (little squash) tradition common in Mexican and Southwestern cuisine, which typically combines squash, corn, peppers, and onions. The addition of goat cheese provides a modern twist, replacing the traditional Cotija or Queso Fresco with a tangier, creamier profile."', 444.31);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('8d9845e1-9e2e-41ae-b8a1-dfd2eda63638', 'Kokosmakronen (German Coconut Macaroons)', 'Traditional German Christmas cookies featuring a crisp, golden exterior and a chewy, moist coconut center. The addition of fresh lemon zest cuts through the sweetness, adding a bright, aromatic dimension to these flourless treats.', 'dessert', 'German', 'Easy', '["german", "egg white", "dessert", "cookies", "christmas", "gluten-free"]', '[{"group_name": "Meringue Base", "items": [{"name": "egg whites", "quantity": 100, "unit": "ml", "preparation": "room temperature", "notes": "approx. 3 large eggs", "substitutions": [], "ingredient_id": "17645f6b-c1ea-4e82-a4b4-5ae8cb6a5a53", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Flavor & Structure", "items": [{"name": "desiccated coconut", "quantity": 200, "unit": "g", "preparation": "unsweetened, shredded", "notes": "fine to medium texture", "substitutions": [], "ingredient_id": "dbd3e1d1-e181-4364-b869-f2e9c0f15317", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon zest", "quantity": 3, "unit": "g", "preparation": "finely grated", "notes": "approx. 1 medium lemon", "substitutions": [], "ingredient_id": "03fb65be-9b62-44e7-a121-694de64cdec0", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 2, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 150\u00b0C (300\u00b0F). Line two baking sheets with parchment paper or arrange wafer papers (Backoblaten) if using.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a clean, grease-free bowl, beat the egg whites and salt on medium-high speed until they form soft peaks.", "structured": {"action": "WHIP", "temperature": null, "duration": null, "doneness_cues": {"visual": "Soft peaks that flop over slightly when beater is lifted", "tactile": "Foamy and white"}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Gradually stream in the granulated sugar while continuing to whip on high speed until the meringue is stiff, glossy, and the sugar has largely dissolved.", "structured": {"action": "WHIP", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Stiff, glossy peaks that stand straight up", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Gently fold in the desiccated coconut, lemon zest, and vanilla extract (if using) with a spatula until evenly distributed. Do not overmix to avoid deflating the whites.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Using two teaspoons or a small cookie scoop, place walnut-sized mounds of the mixture onto the prepared baking sheets, spacing them about 2cm apart.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Bake in the preheated oven for 15-20 minutes, or until the tips are lightly golden brown and the exterior feels set to the touch.", "structured": {"action": "BAKE", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": "PT18M", "doneness_cues": {"visual": "Golden brown tips and edges", "tactile": "Dry and set exterior"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from the oven and allow the cookies to cool completely on the baking sheet. They will firm up as they cool.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT25M", "total_time": "PT45M", "overnight_required": false, "yields": "30 cookies", "yield_count": 30, "serving_size_g": 15}', '{"flags": ["Vegetarian", "Gluten-Free", "Dairy-Free", "Nut-Free", "Soy-Free", "Low-Sodium"], "not_suitable_for": ["Egg allergy"]}', '{"per_serving": {"calories": 68.98, "protein_g": 0.83, "carbohydrates_g": 6.95, "fat_g": 4.05, "saturated_fat_g": null, "trans_fat_g": null, "monounsaturated_fat_g": null, "polyunsaturated_fat_g": null, "fiber_g": 1.41, "sugar_g": 5.49, "sodium_mg": 18.53, "cholesterol_mg": null, "potassium_mg": 5.79, "calcium_mg": 0.3, "iron_mg": 0.01, "magnesium_mg": 0.39, "phosphorus_mg": 0.5, "zinc_mg": null, "vitamin_a_mcg": null, "vitamin_c_mg": null, "vitamin_d_mcg": null, "vitamin_e_mg": null, "vitamin_k_mcg": null, "vitamin_b6_mg": null, "vitamin_b12_mcg": null, "thiamin_mg": null, "riboflavin_mg": 0.02, "niacin_mg": null, "folate_mcg": 0.13, "water_g": 2.96, "alcohol_g": 0.02, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Not recommended; moisture ruins texture.", "duration": null}, "freezer": {"notes": "Freeze in airtight container; thaw at room temperature.", "duration": "P3M"}, "reheating": "No reheating required.", "does_not_keep": false}', '[{"name": "Stand mixer or hand mixer", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": "Backoblaten (German wafer paper)"}, {"name": "Microplane or zester", "required": true, "alternative": null}, {"name": "Spatula", "required": true, "alternative": null}, {"name": "Teaspoons or small cookie scoop", "required": true, "alternative": null}]', '[{"symptom": "Cookies are spreading into flat puddles", "likely_cause": "Egg whites were not whipped enough or coconut ratio was too low", "prevention": "Ensure stiff peaks before adding sugar; weigh coconut accurately", "fix": "If batter looks runny before baking, fold in an extra 10-20g of coconut"}, {"symptom": "Cookies are burning on the bottom", "likely_cause": "Oven temperature is too high or rack is too low", "prevention": "Use an oven thermometer; bake on the middle rack", "fix": "Cannot be fixed, but trim burnt bottoms with a serrated knife"}]', '["For the most authentic German experience, bake these on 50mm ''Backoblaten'' (wafer papers), which are often available in European specialty stores.", "Ensure your mixing bowl is wiped with a little vinegar or lemon juice before starting; any trace of fat or yolk will prevent the egg whites from whipping properly.", "If you want to add a luxurious finish, dip the bottoms of the cooled macaroons in tempered dark chocolate.", "Store these in a tin with a slice of apple for a day if they become too hard; the moisture from the apple will soften them slightly."]', '"Kokosmakronen are a staple of the ''Weihnachtspl\u00e4tzchen'' (Christmas cookie) platter in Germany. Dating back to the 17th century when almond macaroons evolved to incorporate tropical ingredients, they utilize egg whites left over from other rich holiday baking recipes that require only yolks."', 68.98);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('8db48d5f-83d8-4d11-b3ad-677de54e463e', 'Roasted Cod with Black Pepper Potatoes', 'Mild, flaky cod fillets served atop a bed of thinly sliced, golden-edged potatoes. The potatoes absorb the savory juices from the fish while broiling to a crisp finish, creating a comforting, textural contrast with just five key ingredients.', 'dinner', 'American', 'Easy', '["american", "black pepper", "cod", "five ingredient", "kid-friendly", "potato", "dinner", "weeknight", "main course", "spring"]', '[{"group_name": "Potatoes", "items": [{"name": "yukon gold potatoes", "quantity": 800, "unit": "g", "preparation": "scrubbed and thinly sliced (3mm)", "notes": "approx. 4-5 medium potatoes", "substitutions": [], "ingredient_id": "a9d640ff-a969-4f0a-9a92-974f376ac272", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": "divided use", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly cracked", "notes": "coarse grind preferred", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Fish", "items": [{"name": "cod fillets", "quantity": 680, "unit": "g", "preparation": "skinless, patted dry", "notes": "4 fillets, approx 170g each", "substitutions": [], "ingredient_id": "229ccaef-c763-440b-b44f-6e22222d3fd1", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": "wedged", "notes": "approx 60g", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 220\u00b0C (425\u00b0F) and set a rack in the upper third position.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Toss the sliced potatoes with 30ml (2 tbsp) of olive oil, half the salt, and half the black pepper directly on the baking sheet until evenly coated. Spread them out in a single, slightly overlapping layer.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Use a mandoline for uniform slices to ensure even cooking.", "Do not pile the potatoes too high or they will steam instead of roast."]}, {"step_number": 3, "phase": "cook", "text": "Roast the potatoes for 20 minutes, or until they are tender and the edges are beginning to brown.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT20M", "doneness_cues": {"visual": "Edges browning", "tactile": "Fork-tender"}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "While potatoes roast, pat the cod fillets very dry with paper towels. Rub with the remaining 15ml (1 tbsp) olive oil and season strictly with the remaining salt and cracked black pepper.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Remove the baking sheet from the oven. Carefully arrange the cod fillets on top of the potato layer.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Return to the oven and roast for 8-10 minutes, until the fish is opaque and begins to flake easily.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Switch the oven to high broiler setting. Broil for 2-3 minutes, watching closely, until the fish develops a golden color and the exposed potato edges crisp up. Ensure internal temperature of fish reaches 63\u00b0C (145\u00b0F).", "structured": {"action": "BROIL", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown spots", "tactile": "Fish flakes easily"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from oven and serve immediately with fresh lemon wedges squeezed over the top.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT30M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Whole30", "Paleo"], "not_suitable_for": []}', '{"per_serving": {"calories": 425.46, "protein_g": 35.28, "carbohydrates_g": 44.12, "fat_g": 12.71, "saturated_fat_g": 1.79, "trans_fat_g": null, "monounsaturated_fat_g": 8.37, "polyunsaturated_fat_g": 1.59, "fiber_g": 7.55, "sugar_g": 3.18, "sodium_mg": 613.63, "cholesterol_mg": 73.1, "potassium_mg": 2016.66, "calcium_mg": 60.63, "iron_mg": 2.32, "magnesium_mg": 144.47, "phosphorus_mg": 535.29, "zinc_mg": 0.78, "vitamin_a_mcg": 20.69, "vitamin_c_mg": 51.95, "vitamin_d_mcg": 1.53, "vitamin_e_mg": 2.74, "vitamin_k_mcg": 7.76, "vitamin_b6_mg": 0.42, "vitamin_b12_mcg": 1.55, "thiamin_mg": 0.14, "riboflavin_mg": 0.12, "niacin_mg": 3.52, "folate_mcg": 13.64, "water_g": 151.46, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best reheated in an oven or toaster oven to maintain potato crispness.", "duration": "P2D"}, "freezer": {"notes": "Not recommended; potatoes become mealy and fish texture degrades.", "duration": null}, "reheating": "Reheat in a 175\u00b0C (350\u00b0F) oven for 10-15 minutes.", "does_not_keep": false}', '[{"name": "Large rimmed baking sheet", "required": true, "alternative": "Roasting pan"}, {"name": "Chef''s knife or Mandoline", "required": true, "alternative": "Food processor with slicing disk"}, {"name": "Fish spatula", "required": false, "alternative": null}]', '[{"symptom": "Potatoes are still hard when fish is added", "likely_cause": "Potatoes were sliced too thickly or oven temperature runs low", "prevention": "Slice potatoes no thicker than 3-4mm; test doneness with a fork before adding fish", "fix": "Remove fish temporarily to a plate, continue roasting potatoes until tender, then return fish to pan to finish cooking"}]', '["Patting the fish dry is crucial. Excess moisture will steam the fish rather than roasting it, preventing that appetizing golden crust.", "Yukon Gold potatoes are preferred for this recipe as they have a creamy interior and hold their shape better than Russets when sliced thin.", "If your fillets are very thick (over 1 inch), increase the roasting time in step 6 by 3-4 minutes before switching to the broiler.", "Coarsely cracked black pepper adds a necessary textural crunch and heat that contrasts beautifully with the mild sweetness of the cod."]', '"This one-pan preparation is a modern staple in American coastal home cooking, particularly in New England where Atlantic cod is abundant. It emphasizes the ''meat and potatoes'' philosophy but lightens it for weeknight dining, relying on the high heat of roasting rather than the traditional batter-frying found in fish and chips."', 425.46);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('8dd8368b-258b-41e2-8aaf-afaf8f77c13c', 'Zucchini Avocado Salsa Salad', 'A vibrant, textural cross between a chunky pico de gallo and a fresh summer salad. Crisp raw zucchini mimics the crunch of cucumbers, paired with creamy avocado, juicy tomatoes, and a bright lime-cilantro dressing. Perfect as a light side dish or served over rice.', 'salad', 'Mexican', 'Easy', '["mexican", "avocado", "salad", "tomato", "zucchini", "easy", "quick", "side", "summer", "dairy-free", "gluten-free", "halal", "healthy", "low cholesterol", "low-sodium", "nut-free", "vegan", "vegetarian"]', '[{"group_name": "Vegetables", "items": [{"name": "zucchini", "quantity": 350, "unit": "g", "preparation": "small dice (approx. 2 medium zucchini)", "notes": "leave skin on for color", "substitutions": [], "ingredient_id": "d0aa0d47-cefe-4ece-a337-e656f79b74e9", "nutrition_source": "Aggregated Public Data"}, {"name": "roma tomatoes", "quantity": 250, "unit": "g", "preparation": "seeded and diced", "notes": "approx. 2-3 tomatoes", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "avocado", "quantity": 200, "unit": "g", "preparation": "diced firm-ripe", "notes": "approx. 1 large", "substitutions": [], "ingredient_id": "2f40a31e-80a0-4265-b6f3-99ed88ee4c24", "nutrition_source": "USDA FoodData Central"}, {"name": "jalape\u00f1o", "quantity": 15, "unit": "g", "preparation": "seeded and minced", "notes": "1 pepper, adjust to taste", "substitutions": [], "ingredient_id": "6cdb0615-378e-4bfa-b76d-f19bbd780e6c", "nutrition_source": "USDA FoodData Central"}, {"name": "red onion", "quantity": 40, "unit": "g", "preparation": "finely minced", "notes": "optional for extra bite", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Dressing", "items": [{"name": "lime juice", "quantity": 45, "unit": "ml", "preparation": "freshly squeezed", "notes": "about 1.5 - 2 limes", "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "optional, improves mouthfeel", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "start with pinch, adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the zucchini by washing it thoroughly and trimming the ends. Slice into small, uniform cubes (approximately 0.5cm / 1/4 inch). Do not peel, as the skin adds texture and vibrant color.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Slice the tomatoes in half and scoop out the watery seeds with a spoon (discard or save for stock). Dice the tomato flesh to match the size of the zucchini. Finely mince the jalape\u00f1o and red onion.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Removing tomato seeds prevents the salad from becoming soupy.", "Wear gloves when handling jalape\u00f1os to avoid skin irritation."]}, {"step_number": 3, "phase": "assemble", "text": "In a large mixing bowl, combine the diced zucchini, tomato, onion, jalape\u00f1o, and chopped cilantro. Whisk the lime juice, olive oil, salt, and pepper in a small container, then pour over the vegetables. Toss well to coat.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Dice the avocado just before serving to prevent browning. Gently fold the avocado into the salad. Taste and adjust salt or lime juice if needed.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["If making ahead, store the salad without the avocado and add it right before serving."]}, {"step_number": 5, "phase": "finish", "text": "Let the salad sit for 10 minutes to allow flavors to meld, then serve immediately as a side or over rice.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT10M", "total_time": "PT30M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Paleo", "Keto", "Whole30", "Low-Carb"], "not_suitable_for": []}', '{"per_serving": {"calories": 148.2, "protein_g": 2.94, "carbohydrates_g": 12.21, "fat_g": 11.45, "saturated_fat_g": 1.61, "trans_fat_g": null, "monounsaturated_fat_g": 7.64, "polyunsaturated_fat_g": 1.32, "fiber_g": 5.79, "sugar_g": 5.36, "sodium_mg": 212.03, "cholesterol_mg": null, "potassium_mg": 454.08, "calcium_mg": 18.07, "iron_mg": 0.57, "magnesium_mg": 24.65, "phosphorus_mg": 47.6, "zinc_mg": 0.47, "vitamin_a_mcg": 81.91, "vitamin_c_mg": 26.75, "vitamin_d_mcg": null, "vitamin_e_mg": 1.63, "vitamin_k_mcg": 13.81, "vitamin_b6_mg": 0.16, "vitamin_b12_mcg": null, "thiamin_mg": 0.05, "riboflavin_mg": 0.07, "niacin_mg": 0.94, "folate_mcg": 44.43, "water_g": 59.05, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best consumed fresh as avocado will oxidize and zucchini will release water.", "duration": "P1D"}, "freezer": {"notes": "Do not freeze; raw vegetables will lose texture.", "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Citrus juicer", "required": false, "alternative": null}]', '[{"symptom": "Salad is too watery", "likely_cause": "Tomatoes were not seeded properly or zucchini released water after sitting too long", "prevention": "Thoroughly seed tomatoes; do not add salt until ready to serve", "fix": "Gently strain the excess liquid from the bottom of the bowl before serving"}, {"symptom": "Avocado is mushy and brown", "likely_cause": "Avocado was overripe or added too early", "prevention": "Use firm-ripe avocados and add them at the very last second", "fix": "Cannot be fixed, but is still safe to eat"}]', '["Uniformity is key: try to cut the zucchini, avocado, and tomato into pieces of the same size for the best mouthfeel.", "This dish relies heavily on acidity. If your limes are dry, don''t hesitate to add a splash of white vinegar or lemon juice to compensate.", "For a protein boost, this salad mixes exceptionally well with black beans or chickpeas.", "To keep this strictly low-sodium, omit the added salt entirely; the acidity from the lime and heat from the chili provide ample flavor."]', '"While not a traditional Mexican classic like Pico de Gallo, this salad borrows the ''bandera'' (flag) color palette of green, white, and red common in Mexican cuisine. It adapts the concept of a raw salsa into a vegetable-forward side dish, popular in modern health-conscious cooking across the Americas."', 148.2);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('8ea1ffab-5829-4fae-bed7-010dbd9962c6', 'Nordic Raspberry & Custard Cardamom Buns', 'Soft, pillowy yeast dough infused with aromatic ground cardamom, holding a dual center of tart raspberry jam and rich vanilla crème pâtissière. Finished with a sweet glaze and a snow-like dusting of desiccated coconut.', 'baked good', 'Scandinavian', 'Intermediate', '["buns", "custard", "raspberry", "coconut", "cardamom", "bakery", "scandinavian", "sweet yeasted dough"]', '[{"group_name": "Cardamom Dough", "items": [{"name": "whole milk", "quantity": 300, "unit": "ml", "preparation": "lukewarm (37\u00b0C)", "notes": "Do not overheat or yeast will die", "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 75, "unit": "g", "preparation": "melted and cooled", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 500, "unit": "g", "preparation": null, "notes": "Plus extra for dusting", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 75, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "instant yeast", "quantity": 7, "unit": "g", "preparation": null, "notes": "1 standard sachet", "substitutions": [], "ingredient_id": "3472b450-e9ea-489e-94a2-3a72ec574514", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cardamom", "quantity": 1, "unit": "null", "preparation": null, "notes": "approx 3g or 1 tsp; freshly ground provides best flavor", "substitutions": [], "ingredient_id": "c56f6cd8-882c-487c-956f-3a91ee1fec07", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vanilla Custard", "items": [{"name": "whole milk", "quantity": 250, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "egg yolks", "quantity": 3, "unit": "null", "preparation": null, "notes": "approx 55g total", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 40, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 20, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla bean paste", "quantity": 5, "unit": "g", "preparation": null, "notes": "or 1 tsp extract", "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Assembly & Topping", "items": [{"name": "raspberry jam", "quantity": 120, "unit": "g", "preparation": null, "notes": "Thick consistency is best", "substitutions": [], "ingredient_id": "e0b33241-dd9c-431f-97a3-6dc62fa1b006", "nutrition_source": "Aggregated Public Data"}, {"name": "egg", "quantity": 1, "unit": "null", "preparation": null, "notes": "For egg wash", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "powdered sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 15, "unit": "ml", "preparation": null, "notes": "Adjust for consistency", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "desiccated coconut", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "dbd3e1d1-e181-4364-b869-f2e9c0f15317", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Make the custard: In a bowl, whisk egg yolks, sugar, and cornstarch until pale. Heat 250ml milk in a saucepan until just starting to steam (do not boil). Pour half the hot milk into the egg mixture while whisking constantly to temper.", "structured": {"action": "TEMPER", "temperature": {"celsius": 80, "fahrenheit": 176}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Pour the tempered egg mixture back into the saucepan. Whisk constantly over medium heat until the mixture thickens significantly and bubbles lazily. Remove from heat, stir in vanilla, cover surface with plastic wrap, and chill completely.", "structured": {"action": "BOIL", "temperature": null, "duration": null, "doneness_cues": {"visual": "Glossy, thick pudding consistency", "tactile": "Holds shape on the whisk"}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Prepare the dough: In a stand mixer bowl, combine flour, sugar, yeast, ground cardamom, and salt. Add the lukewarm milk and melted butter.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Knead the dough on low speed (or by hand) until it is smooth, elastic, and pulls away from the sides of the bowl. This develops the gluten structure needed for fluffy buns.", "structured": {"action": "KNEAD", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": null, "tactile": "Soft, slightly tacky but not sticky"}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Cover the bowl and let the dough rise in a warm, draft-free spot until doubled in size.", "structured": {"action": "PROOF", "temperature": null, "duration": "PT1H", "doneness_cues": {"visual": "Volume has doubled", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Punch down the dough and divide into 12 equal pieces (approx 75g each). Roll into tight balls and place on baking sheets lined with parchment paper. Flatten slightly with your palm.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Cover buns and let rise for a second time until puffy (about 30-45 minutes). Near the end of this time, preheat oven to 200\u00b0C/400\u00b0F.", "structured": {"action": "PROOF", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT45M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Use the bottom of a small glass or your fingers to press a deep indentation into the center of each bun. Fill the bottom of the indentation with 1 tsp raspberry jam, then top generously with the cooled custard.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Brush the exposed dough edges with beaten egg. Bake in the preheated oven until golden brown.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT12M", "doneness_cues": {"visual": "Deep golden brown crust", "tactile": null}}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Allow buns to cool completely. Whisk powdered sugar and water to form a glaze. Brush the glaze onto the dough (avoiding the custard center) and immediately dip or sprinkle with desiccated coconut.", "structured": {"action": "GLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT50M", "passive_time": "PT2H15M", "total_time": "PT3H5M", "overnight_required": false, "yields": "12 buns", "yield_count": 12, "serving_size_g": 125}', '{"flags": ["Vegetarian", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 376.32, "protein_g": 7.51, "carbohydrates_g": 60.15, "fat_g": 11.13, "saturated_fat_g": 4.64, "trans_fat_g": null, "monounsaturated_fat_g": 2.56, "polyunsaturated_fat_g": 0.73, "fiber_g": 2.17, "sugar_g": 25.04, "sodium_mg": 146.59, "cholesterol_mg": 83.02, "potassium_mg": 133.43, "calcium_mg": 69.48, "iron_mg": 0.79, "magnesium_mg": 16.34, "phosphorus_mg": 112.42, "zinc_mg": 0.67, "vitamin_a_mcg": 87.96, "vitamin_c_mg": 0.29, "vitamin_d_mcg": 0.93, "vitamin_e_mg": 0.37, "vitamin_k_mcg": 0.75, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": 0.35, "thiamin_mg": 0.22, "riboflavin_mg": 0.25, "niacin_mg": 1.32, "folate_mcg": 44.07, "water_g": 53.81, "alcohol_g": 0.14, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container due to the custard filling.", "duration": "P3D"}, "freezer": {"notes": "Freeze without the glaze and coconut. Thaw and glaze before serving.", "duration": "P1M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Stand mixer with dough hook", "required": false, "alternative": "Large mixing bowl and strong hands"}, {"name": "Saucepan", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Piping bag", "required": false, "alternative": "Ziploc bag with corner cut or two spoons"}, {"name": "Pastry brush", "required": true, "alternative": null}, {"name": "Kitchen scale", "required": true, "alternative": null}]', '[{"symptom": "Custard leaked out during baking", "likely_cause": "Indentation was too shallow or dough proofed too much after shaping, pushing the filling out", "prevention": "Press the indentation very firmly, almost hitting the tray, immediately before filling and baking", "fix": "Use a spoon to nudge escaped custard back to the center while still hot, though it will look messy"}, {"symptom": "Dough is heavy and dense", "likely_cause": "Yeast was dead or liquid was too hot and killed it", "prevention": "Ensure milk is body temperature (37\u00b0C) and check yeast expiration date", "fix": "Cannot be fixed once baked; use for bread pudding"}]', '["Freshly grinding green cardamom seeds using a mortar and pestle offers a significantly more potent and floral aroma than pre-ground powder.", "For the neatest appearance, use a piping bag to fill the centers with jam and custard rather than spoons.", "Ensure the custard is completely cold before filling the buns; warm custard will make the raw dough greasy and prevent it from baking through correctly.", "The coconut adheres best when the glaze is wet, so glaze and dip one bun at a time."]', '"This recipe is a variation of the Norwegian ''Skolebr\u00f8d'' or ''Skoleboller'' (School Buns), a beloved bakery staple in Norway. Traditionally packed in school lunches\u2014hence the name\u2014these buns celebrate the Nordic love affair with cardamom, a spice brought to Scandinavia by Vikings via Constantinople."', 376.32);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('8f2ab9c2-c162-4640-989d-99de30b326cb', 'Poached White Peaches in Spiced Cabernet & Raspberry Syrup', 'Tender white peaches bathe in a vibrant, ruby-red syrup infused with Cabernet Sauvignon, fresh raspberries, and warming spices. The result is a sophisticated yet simple dessert where the wine''s tannins balance the fruit''s natural sweetness.', 'dessert', 'French', 'Easy', '["peach", "raspberry", "easy", "dessert", "summer", "dairy-free", "fruit", "poached", "vegan", "french"]', '[{"group_name": "Fruit", "items": [{"name": "white peaches", "quantity": 4, "unit": null, "preparation": "ripe but firm", "notes": "approx. 150g each", "substitutions": [], "ingredient_id": "8d70adb0-d52e-4842-9c0b-ad4eacdf35ae", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh raspberries", "quantity": 125, "unit": "g", "preparation": "whole", "notes": null, "substitutions": [], "ingredient_id": "f4f5b84c-c364-40cd-b737-375755e481f9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Poaching Liquid", "items": [{"name": "cabernet sauvignon", "quantity": 500, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["Merlot", "Pinot Noir"], "ingredient_id": "8dcd3a06-85eb-4512-a98d-0400f163837f", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 125, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "granulated sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": ["raw sugar"], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": "peel removed in strips and juiced", "notes": "approx 45ml juice", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics", "items": [{"name": "cinnamon stick", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 5g", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "star anise", "quantity": 2, "unit": null, "preparation": null, "notes": "whole pods", "substitutions": [], "ingredient_id": "9010f167-112f-4c3b-80c3-b49783e568a1", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla bean", "quantity": 0.5, "unit": null, "preparation": "split lengthwise", "notes": "or 5ml vanilla bean paste", "substitutions": [], "ingredient_id": "90237166-b129-4858-8c9c-2f8a7ab9a301", "nutrition_source": "Aggregated Public Data"}, {"name": "whole cloves", "quantity": 3, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "7b3bf68a-3ae9-4dad-91f4-6c7a14ec5e0e", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Using a vegetable peeler, carefully remove the skin from the peaches, leaving the stem intact if possible. If the peaches are very firm, you can score the bottom with an X and blanch them in boiling water for 30 seconds to loosen the skin.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a medium saucepan, combine the Cabernet Sauvignon, water, sugar, lemon peel, lemon juice, raspberries, cinnamon stick, star anise, cloves, and split vanilla bean. Bring to a boil over medium-high heat, stirring to dissolve the sugar.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to a gentle simmer (around 85\u00b0C/185\u00b0F). Carefully lower the peeled peaches into the liquid. They should be mostly submerged. If using parchment paper, cut a circle (cartouche) with a small hole in the center and place it directly on the surface of the liquid to keep the peaches submerged.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Poach the peaches gently for 15 to 25 minutes. The time depends heavily on the ripeness of the fruit. Test by inserting a sharp knife tip into the flesh; it should meet no resistance.", "structured": {"action": "POACH", "temperature": null, "duration": "PT20M", "doneness_cues": {"visual": null, "tactile": "Knife slides in with zero resistance"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove the saucepan from the heat. Allow the peaches to cool completely within the syrup. This rest period allows the peaches to absorb the red wine color and flavor deeper into their flesh.", "structured": {"action": "COOL", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Serve the peaches in shallow bowls with a generous ladle of the poaching syrup and the cooked raspberries. Garnish with a fresh mint leaf if desired.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT40M", "total_time": "PT1H", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 250}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Soy-Free", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 352.53, "protein_g": 1.2, "carbohydrates_g": 65.84, "fat_g": 1.19, "saturated_fat_g": 0.36, "trans_fat_g": null, "monounsaturated_fat_g": 0.19, "polyunsaturated_fat_g": 0.47, "fiber_g": 3.6, "sugar_g": 56.18, "sodium_mg": 14.49, "cholesterol_mg": null, "potassium_mg": 169.88, "calcium_mg": 41.47, "iron_mg": 0.87, "magnesium_mg": 18.74, "phosphorus_mg": 24.19, "zinc_mg": 0.25, "vitamin_a_mcg": 43.16, "vitamin_c_mg": 64.96, "vitamin_d_mcg": null, "vitamin_e_mg": 1.26, "vitamin_k_mcg": 3.01, "vitamin_b6_mg": 0.11, "vitamin_b12_mcg": null, "thiamin_mg": 0.11, "riboflavin_mg": 0.06, "niacin_mg": 0.55, "folate_mcg": 10.58, "water_g": 316.4, "alcohol_g": 13.13, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store peaches submerged in the syrup to prevent browning and intensify the flavor.", "duration": "P5D"}, "freezer": {"notes": "Texture of the peaches will be softer upon thawing; best used for smoothies or sauces if frozen.", "duration": "P3M"}, "reheating": "Gently warm in a saucepan over low heat if serving warm, though delicious chilled.", "does_not_keep": false}', '[{"name": "Medium Saucepan", "required": true, "alternative": "Deep saut\u00e9 pan"}, {"name": "Vegetable Peeler", "required": true, "alternative": null}, {"name": "Parchment Paper", "required": false, "alternative": "Small lid or plate"}, {"name": "Slotted Spoon", "required": true, "alternative": null}]', '[{"symptom": "Peaches are mushy or falling apart", "likely_cause": "Peaches were too ripe before starting or overcooked", "prevention": "Select peaches that are fragrant but firm to the touch; reduce cooking time for softer fruit", "fix": "Pur\u00e9e the mixture into a sauce or coulis for ice cream"}, {"symptom": "Syrup is too thin or watery", "likely_cause": "Fruit released excess water or wine didn''t reduce enough", "prevention": "Not preventable during poaching as fruit varies", "fix": "Remove peaches, boil the syrup vigorously for 5-10 minutes to reduce and thicken"}]', '["For a deeper red color and stronger flavor, prepare this dish a day in advance and let the peaches sit in the syrup overnight in the refrigerator.", "If you do not have parchment paper for a cartouche, you can use a heat-safe ceramic plate that fits inside the pot to gently weigh the peaches down.", "The leftover syrup is liquid gold. Strain it and use it as a base for sangria, mix it into sparkling water, or drizzle it over dairy-free vanilla ice cream.", "While Cabernet is specified for its robust body, any drinkable dry red wine like Merlot or Shiraz works well. Avoid ''cooking wines'' with added salt."]', '"Poaching fruit in wine (P\u00eaches au vin rouge) is a classic French bistro dessert technique designed to utilize seasonal fruit that might be slightly under-ripe while preserving it for a few extra days. The addition of raspberries adds a tart brightness that cuts through the deep tannins of the red wine."', 352.53);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('8fb6e31c-3117-4ffb-908e-759dd6989186', 'Spicy Chicken Sausage and Potato Hash', 'A rustic, savory one-pan meal featuring crispy golden potatoes, caramelized onions, sweet bell peppers, and zesty chicken sausage. The dish offers a satisfying contrast of textures with a kick of heat, perfect for a hearty weeknight dinner.', 'dinner', 'American', 'Easy', '["one pot", "potato", "dinner", "comfort food", "quick & easy", "gluten-free"]', '[{"group_name": "Proteins & Vegetables", "items": [{"name": "spicy chicken sausage", "quantity": 450, "unit": "g", "preparation": "sliced into 1cm coins", "notes": "Pre-cooked or raw links; remove casings if crumbling is preferred", "substitutions": [], "ingredient_id": "05cd2108-84d5-4aa1-a941-50f4d966a577", "nutrition_source": "Aggregated Public Data"}, {"name": "potatoes", "quantity": 600, "unit": "g", "preparation": "diced into 1.5cm cubes", "notes": "Yukon Gold or Russet; about 3 medium potatoes", "substitutions": [], "ingredient_id": "5bf06478-4785-465e-9842-f70a24e22054", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "red bell pepper", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx. 150g; or green bell pepper for more bitterness", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Pantry & Seasoning", "items": [{"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "Plus more if needed for frying", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx. 1 tsp", "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic powder", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx. 1/2 tsp", "substitutions": [], "ingredient_id": "177a312f-ef99-4398-9108-98f7a608a245", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "Adjust to taste depending on sausage saltiness", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 5, "unit": "g", "preparation": "chopped", "notes": "Optional garnish", "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the ingredients: Dice the potatoes into uniform 1.5cm (1/2 inch) cubes, dice the onion and bell pepper, and slice the chicken sausage into coins.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat 15ml (1 tbsp) of olive oil in a large skillet over medium-high heat. Add the sausage slices and cook until browned and fully cooked through (reaching an internal temperature of 74\u00b0C/165\u00b0F if raw). Remove sausage from the pan and set aside.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": "PT5M", "doneness_cues": {"visual": "Browned and crispy edges", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the remaining 15ml (1 tbsp) of oil to the same pan. Add the diced potatoes in a single layer. Cook undisturbed for 4-5 minutes to develop a crust, then stir and cook for another 5-7 minutes until tender and golden brown.", "structured": {"action": "FRY", "temperature": null, "duration": "PT12M", "doneness_cues": {"visual": "Golden brown crust", "tactile": "Fork tender"}}, "tips": ["If potatoes stick, add a splash more oil.", "Covering the pan for 2 minutes midway helps steam the centers if they remain hard."]}, {"step_number": 4, "phase": "cook", "text": "Reduce heat to medium. Add the diced onion, bell pepper, smoked paprika, garlic powder, salt, and black pepper. Saut\u00e9 for 5 minutes until the onions are translucent and peppers are soft.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Onions translucent", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Return the cooked sausage to the pan. Toss everything together and cook for 2 more minutes to reheat the sausage and meld the flavors. Adjust salt and pepper to taste.", "structured": {"action": "MIX", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove from heat and garnish with fresh chopped parsley before serving.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT0M", "total_time": "PT25M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 320}', '{"flags": ["Gluten-Free", "Dairy-Free", "Nut-Free", "Egg-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 440.94, "protein_g": 25.11, "carbohydrates_g": 27.49, "fat_g": 24.76, "saturated_fat_g": 6.76, "trans_fat_g": null, "monounsaturated_fat_g": 5.5, "polyunsaturated_fat_g": 0.96, "fiber_g": 5.5, "sugar_g": 5.49, "sodium_mg": 1473.79, "cholesterol_mg": null, "potassium_mg": 1057.86, "calcium_mg": 173.38, "iron_mg": 10.78, "magnesium_mg": 60.84, "phosphorus_mg": 82.39, "zinc_mg": 3.78, "vitamin_a_mcg": 76.51, "vitamin_c_mg": 69.55, "vitamin_d_mcg": null, "vitamin_e_mg": 1.84, "vitamin_k_mcg": 27.82, "vitamin_b6_mg": 0.53, "vitamin_b12_mcg": null, "thiamin_mg": 0.08, "riboflavin_mg": 0.12, "niacin_mg": 2.03, "folate_mcg": 52.3, "water_g": 194.16, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Potatoes may lose crispness.", "duration": "P3D"}, "freezer": {"notes": "Texture of potatoes will degrade significantly upon thawing.", "duration": "P1M"}, "reheating": "Reheat in a skillet over medium heat to restore texture, or microwave for convenience.", "does_not_keep": false}', '[{"name": "Large heavy-bottomed skillet", "required": true, "alternative": "Cast iron pan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Spatula", "required": true, "alternative": null}]', '[{"symptom": "Potatoes are burnt outside but raw inside", "likely_cause": "Heat was too high or potato cubes were too large", "prevention": "Cut potatoes uniformly small (1.5cm) and use medium heat; cover pan briefly to steam", "fix": "Add a tablespoon of water, cover tightly with a lid, and steam for 2-3 minutes until tender"}]', '["Use a cast iron skillet if available; it retains heat well and creates the best crust on the potatoes.", "Do not overcrowd the pan when cooking potatoes. If your pan is small, cook potatoes in two batches to ensure they fry rather than steam.", "For a breakfast variation, crack 4 eggs into wells in the hash during the final few minutes, cover, and cook until whites are set.", "If using raw sausage meat instead of links, break it up with a spatula into crumbles during the first cooking step."]', '"Hash is a classic culinary tradition born from the resourceful use of leftovers, specifically chopped meat and potatoes. The term comes from the French verb ''hacher'' (to chop). While often associated with corned beef, this poultry version offers a lighter, modern take on the American diner staple."', 440.94);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('90402876-4c02-437f-a534-5f6bf932137e', 'Mediterranean White Bean and Rice Soup', 'A robust, restorative one-pot soup featuring a savory tomato-herb broth, tender vegetables, creamy cannellini beans, and fluffly rice. Finished with lemon for brightness, this dish thickens into a hearty stew the next day.', 'soup', 'Mediterranean', 'Easy', '["mediterranean", "one pot", "great leftovers", "rice", "soup", "vegetables", "white bean", "dinner", "appetizer", "main course", "gluten-free", "nut-free", "vegan", "comfort food"]', '[{"group_name": "Aromatics & Base", "items": [{"name": "extra virgin olive oil", "quantity": 30, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "carrots", "quantity": 2, "unit": null, "preparation": "diced", "notes": "approx. 120g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "celery stalks", "quantity": 2, "unit": null, "preparation": "diced", "notes": "approx. 100g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "minced", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Broth & Grains", "items": [{"name": "vegetable broth", "quantity": 1500, "unit": "ml", "preparation": null, "notes": "low-sodium preferred", "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "diced tomatoes", "quantity": 400, "unit": "g", "preparation": "canned", "notes": "include juices", "substitutions": [], "ingredient_id": "0ba01b79-628f-4d68-be62-dab1fbbd087c", "nutrition_source": "Aggregated Public Data"}, {"name": "long-grain white rice", "quantity": 150, "unit": "g", "preparation": "rinsed", "notes": null, "substitutions": [], "ingredient_id": "b671f3cd-cdec-4182-8911-82a06a22815a", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 1, "unit": "g", "preparation": null, "notes": "approx. 1 tsp", "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "dried thyme", "quantity": 0.5, "unit": "g", "preparation": null, "notes": "approx. 0.5 tsp", "substitutions": [], "ingredient_id": "3b938244-d506-46b2-9027-21bed955bcc5", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables & Finish", "items": [{"name": "zucchini", "quantity": 1, "unit": null, "preparation": "diced into 1cm cubes", "notes": "approx. 200g", "substitutions": [], "ingredient_id": "c34b610f-8869-4d77-a9b3-e01849d703b5", "nutrition_source": "USDA FoodData Central"}, {"name": "cannellini beans", "quantity": 400, "unit": "g", "preparation": "canned", "notes": "rinsed and drained; approx. 240g net weight", "substitutions": [], "ingredient_id": "338d5b1f-5e90-4e7f-b286-e827b78558e9", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh spinach", "quantity": 100, "unit": "g", "preparation": "rough chopped", "notes": null, "substitutions": [], "ingredient_id": "4734440a-226d-4d26-a110-3ed5c3bde93f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": "approx. half a lemon", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare vegetables: dice the onion, carrots, celery, and zucchini into uniform pieces (approx. 1cm). Mince the garlic. Rinse the rice under cold water until water runs clear.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat olive oil in a large pot over medium heat (approx. 175\u00b0C/350\u00b0F). Add onion, carrots, and celery. Saut\u00e9 for 6-8 minutes until onions are translucent and vegetables soften.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT8M", "doneness_cues": {"visual": "Onions translucent", "tactile": "Vegetables softened"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Stir in minced garlic, dried oregano, thyme, salt, and pepper. Cook for 1 minute until fragrant, being careful not to burn the garlic.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Garlic slightly golden", "tactile": "Aromatic"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour in the vegetable broth and canned tomatoes with their juices. Increase heat to bring the mixture to a rolling boil.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Stir in the rinsed rice. Reduce heat to low, cover, and simmer gently for 10 minutes.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Add the diced zucchini and drained cannellini beans. Continue to simmer, covered, for another 5-8 minutes, or until the rice is tender and zucchini is cooked through but not mushy.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": null, "tactile": "Rice is tender, zucchini offers slight resistance"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from heat. Stir in the fresh spinach and lemon juice. The residual heat will wilt the spinach in about 1-2 minutes. Taste and adjust salt if needed.", "structured": {"action": "STIR", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Ladle into bowls and garnish with fresh chopped parsley before serving.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT25M", "total_time": "PT45M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 450}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Nut-Free", "Dairy-Free", "Egg-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 349.12, "protein_g": 17.26, "carbohydrates_g": 67.82, "fat_g": 6.34, "saturated_fat_g": 1.06, "trans_fat_g": null, "monounsaturated_fat_g": 3.73, "polyunsaturated_fat_g": 0.68, "fiber_g": 11.47, "sugar_g": 8.23, "sodium_mg": 1869.69, "cholesterol_mg": null, "potassium_mg": 1040.57, "calcium_mg": 166.06, "iron_mg": 5.41, "magnesium_mg": 122.85, "phosphorus_mg": 235.67, "zinc_mg": 2.47, "vitamin_a_mcg": 325.87, "vitamin_c_mg": 19.68, "vitamin_d_mcg": null, "vitamin_e_mg": 1.37, "vitamin_k_mcg": 122.97, "vitamin_b6_mg": 0.23, "vitamin_b12_mcg": null, "thiamin_mg": 0.08, "riboflavin_mg": 0.11, "niacin_mg": 1, "folate_mcg": 60.66, "water_g": 110.58, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Soup will thicken significantly as rice absorbs liquid. Add water or broth when reheating.", "duration": "P4D"}, "freezer": {"notes": "Rice texture may become softer upon thawing.", "duration": "P3M"}, "reheating": "Gently warm on stovetop over medium-low heat; add splash of liquid to loosen.", "does_not_keep": false}', '[{"name": "Large Dutch oven or heavy-bottomed pot", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": null}, {"name": "Fine-mesh sieve", "required": true, "alternative": "Colander"}]', '[{"symptom": "Soup has become too thick (stew-like)", "likely_cause": "Rice released excess starch or absorbed liquid during cooling", "prevention": "Rinse rice thoroughly before cooking; serve immediately", "fix": "Stir in 120-240ml of hot water or extra vegetable broth to reach desired consistency"}, {"symptom": "Rice is mushy", "likely_cause": "Overcooked or simmered too vigorously", "prevention": "Check rice texture early; add zucchini later if rice cooks fast", "fix": "Cannot be fixed, but still edible and flavorful"}]', '["Rinsing the rice is crucial in this recipe to remove surface starch; otherwise, the broth will become gluey rather than silky.", "For a richer flavor profile (if not strictly vegan), add a Parmesan cheese rind during the simmering step and remove before serving.", "The acid from the lemon juice is essential\u2014it cuts through the starchiness of the beans and rice to brighten the entire dish.", "Cut all vegetables to roughly the same size as the beans to ensure every spoonful has a balanced mix of textures.", "If you plan to freeze this soup, undercook the rice slightly (by 3-4 minutes) so it doesn''t disintegrate upon reheating."]', '"This dish draws from the Mediterranean tradition of ''cucina povera'' (peasant cooking), similar to Italian Minestrone or Greek Fasolada. It relies on humble pantry staples\u2014beans, grains, and seasonal vegetables\u2014combined to create a nutritionally complete meal that sustained families through lean times."', 349.12);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('9085a8b0-313f-4620-9cb4-9261a091723e', 'Spicy Mint and Cilantro Chutney', 'A vibrant emerald-green condiment bursting with the freshness of cilantro and mint, punched up with serrano heat and lime zestiness. This versatile chutney strikes the perfect balance between spicy, tangy, and sweet, brightening everything from samosas to grilled meats.', 'condiment', 'Indian', 'Easy', '["condiments", "sauces and gravies", "cilantro", "jalape\u00f1o", "lime juice", "mint", "serrano", "easy", "quick", "vegan", "indian", "dip"]', '[{"group_name": "Fresh Herbs & Aromatics", "items": [{"name": "fresh cilantro", "quantity": 100, "unit": "g", "preparation": "thoroughly washed", "notes": "leaves and tender stems only, approx 2 large bunches", "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh mint leaves", "quantity": 40, "unit": "g", "preparation": "picked", "notes": "leaves only, no stems", "substitutions": [], "ingredient_id": "213e3d3b-d332-45a9-b35e-23ee29a27173", "nutrition_source": "USDA FoodData Central"}, {"name": "serrano pepper", "quantity": 15, "unit": "g", "preparation": "roughly chopped", "notes": "approx 1-2 peppers, seeds removed for less heat", "substitutions": ["jalape\u00f1o pepper", "thai bird chili"], "ingredient_id": "6cdb0615-378e-4bfa-b76d-f19bbd780e6c", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 10, "unit": "g", "preparation": "peeled and roughly chopped", "notes": "approx 2cm piece", "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 5, "unit": "g", "preparation": "peeled", "notes": "approx 1 medium clove", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Seasoning & Liquid", "items": [{"name": "fresh lime juice", "quantity": 30, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "sugar", "quantity": 5, "unit": "g", "preparation": null, "notes": "or jaggery/maple syrup to taste", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "roasted cumin powder", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 4, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "ice water", "quantity": 30, "unit": "ml", "preparation": null, "notes": "use crushed ice or very cold water", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Roughly chop the ginger and chilies to help the blender process them evenly.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Combine cilantro, mint, ginger, chilies, garlic, lime juice, sugar, cumin, salt, and half of the ice water in the blender jar.", "structured": {"action": "MEASURE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Put the liquids and aromatics at the bottom near the blades for easier blending."]}, {"step_number": 3, "phase": "cook", "text": "Blend on high speed until smooth. If the mixture is too thick to turn, add the remaining ice water in small increments (5ml at a time) until the desired consistency is reached.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": ["Using ice water prevents the blender heat from ''cooking'' the herbs, keeping the color bright green."]}, {"step_number": 4, "phase": "finish", "text": "Taste and adjust seasoning. Add more salt for savoriness, sugar for balance, or lime juice for brightness. Transfer to a serving bowl or airtight container immediately.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT0M", "total_time": "PT10M", "overnight_required": false, "yields": "200ml", "yield_count": 12, "serving_size_g": 15}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Nut-Free", "Paleo", "Whole30", "Raw"], "not_suitable_for": []}', '{"per_serving": {"calories": 8.9, "protein_g": 0.41, "carbohydrates_g": 1.91, "fat_g": 0.12, "saturated_fat_g": 0.01, "trans_fat_g": null, "monounsaturated_fat_g": 0.03, "polyunsaturated_fat_g": 0.03, "fiber_g": 0.57, "sugar_g": 0.62, "sodium_mg": 134.86, "cholesterol_mg": null, "potassium_mg": 77.72, "calcium_mg": 11.25, "iron_mg": 0.31, "magnesium_mg": 4.28, "phosphorus_mg": 5.11, "zinc_mg": 0.06, "vitamin_a_mcg": 176.63, "vitamin_c_mg": 5.02, "vitamin_d_mcg": null, "vitamin_e_mg": 0.02, "vitamin_k_mcg": 0.21, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.01, "niacin_mg": 0.09, "folate_mcg": 4.46, "water_g": 9.4, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container with a layer of cling film touching the surface to prevent oxidation.", "duration": "P5D"}, "freezer": {"notes": "Freeze in ice cube trays for easy portioning.", "duration": "P3M"}, "reheating": null, "does_not_keep": false}', '[{"name": "High-speed blender or food processor", "required": true, "alternative": null}, {"name": "Knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Chutney turned dark brown or olive green", "likely_cause": "Oxidation of herbs caused by heat from the blender or exposure to air", "prevention": "Use ice water when blending and ensure lime juice (acid) is added before blending", "fix": "Cannot fix color, but flavor will still be good. Serve immediately."}, {"symptom": "Texture is too watery", "likely_cause": "Too much water added during blending or wet herbs", "prevention": "Dry herbs thoroughly after washing; add water very slowly", "fix": "Blend in 15g of roasted peanuts, cashews, or roasted chana dal to thicken/emulsify"}, {"symptom": "Taste is bitter", "likely_cause": "Mint stems were included or herbs were over-blended", "prevention": "Use only mint leaves (stems are bitter); do not blend longer than necessary", "fix": "Add a pinch more sugar and lime juice to mask the bitterness"}]', '["Texture Trick: For a restaurant-style creamy texture that doesn''t separate, add 15g of roasted peanuts or roasted chana dal (split chickpeas) to the blender.", "Herb Handling: While cilantro stems are full of flavor and should be used, mint stems can be woody and bitter. Always pick mint leaves cleanly.", "Heat Management: The heat in peppers is mostly in the seeds and white pith. Remove these before blending if you prefer a mild chutney.", "Serving Suggestion: Mix 1 part chutney with 2 parts yogurt for a cooling dip ideal for tandoori chicken or kebabs."]', '"Known as ''Hari Chutney'' (Green Chutney) in India, this condiment is a staple of chaat (street food) and home cooking alike. It is based on Ayurvedic principles of digestion, utilizing ginger, cumin, and mint to stimulate appetite and aid digestion alongside rich or fried foods."', 8.9);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('90c67b9f-1305-485d-9311-e393ac2017b2', 'Seared Salmon & Endive Salad', 'A vibrant study in contrasts: hot, rich pan-seared salmon meets cool, bitter crisp endives and tender mixed greens. The dish is unified by a sharp, savory Dijon-shallot vinaigrette that cuts through the fatty fish and balances the chicory notes.', 'salad', 'Modern French', 'Easy', '["seafood", "fish", "salmon", "easy", "quick", "side", "salad", "gluten-free", "healthy"]', '[{"group_name": "Vinaigrette", "items": [{"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "white wine vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b2f8f0c0-6da9-47aa-932a-c2747b64b807", "nutrition_source": "Aggregated Public Data"}, {"name": "dijon mustard", "quantity": 10, "unit": "g", "preparation": null, "notes": "smooth type", "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "approx 20g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, start with 2g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Salad Base", "items": [{"name": "salmon fillets", "quantity": 300, "unit": "g", "preparation": "skin-off or skin-on based on preference", "notes": "2 fillets, 150g each", "substitutions": [], "ingredient_id": "671c418a-0b74-45a8-a8b9-e4fd2f40e8ff", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 10, "unit": "ml", "preparation": null, "notes": "for searing", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "belgian endives", "quantity": 2, "unit": null, "preparation": null, "notes": "approx 150g, bottoms trimmed and sliced crosswise", "substitutions": [], "ingredient_id": "d12a7fcc-be1b-4aca-9450-3d71177cf279", "nutrition_source": "USDA FoodData Central"}, {"name": "mixed greens", "quantity": 80, "unit": "g", "preparation": "washed and dried", "notes": "mesclun mix or arugula", "substitutions": [], "ingredient_id": "312b8da7-52bd-406b-89d2-0853c0e37faa", "nutrition_source": "USDA FoodData Central"}, {"name": "walnuts", "quantity": 30, "unit": "g", "preparation": "roughly chopped", "notes": "toasted", "substitutions": ["pecans", "pumpkin seeds"], "ingredient_id": "ab4fe25a-a215-4af7-8109-055c28e0bef2", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the vinaigrette: In a small bowl, whisk together the minced shallot, Dijon mustard, white wine vinegar, salt, and pepper. Slowly drizzle in the extra virgin olive oil while whisking continuously until the mixture is emulsified and creamy.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Prepare the greens: Slice the endives crosswise into 2cm strips. Combine the sliced endives and mixed greens in a large bowl. If using raw walnuts, quickly toast them in a dry pan over medium heat for 2-3 minutes until fragrant.", "structured": {"action": "SLICE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Cook the salmon: Pat the salmon fillets completely dry with paper towels and season generously with salt. Heat the cooking olive oil in a non-stick skillet over medium-high heat. Place salmon in the pan (skin-side down if using skin-on).", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Finish the salmon: Flip the fillets and cook for another 2-3 minutes depending on thickness. Aim for an internal temperature of 52\u00b0C (125\u00b0F) for medium-rare or up to 63\u00b0C (145\u00b0F) for well-done/FDA safety standards. Remove from heat and let rest.", "structured": {"action": "COOK", "temperature": {"celsius": 63, "fahrenheit": 145}, "duration": null, "doneness_cues": {"visual": "Opaque pink and flaking gently", "tactile": "Firm but yielding to light pressure"}}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Assemble the salad: Pour half the dressing over the greens mixture and toss gently to coat. Divide the greens onto plates. Top each with a warm salmon fillet. Drizzle the remaining vinaigrette over the fish and garnish with the chopped walnuts.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 320}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Low-Carb", "Keto", "Paleo", "Whole30", "Sugar-Free"], "not_suitable_for": ["Nut allergies (walnuts)"]}', '{"per_serving": {"calories": 684.73, "protein_g": 34.81, "carbohydrates_g": 8.19, "fat_g": 57.84, "saturated_fat_g": 9.35, "trans_fat_g": null, "monounsaturated_fat_g": 27.08, "polyunsaturated_fat_g": 15.95, "fiber_g": 4.78, "sugar_g": 1.97, "sodium_mg": 555.5, "cholesterol_mg": 82.5, "potassium_mg": 992.26, "calcium_mg": 92.33, "iron_mg": 2.42, "magnesium_mg": 84.02, "phosphorus_mg": 451.69, "zinc_mg": 1.74, "vitamin_a_mcg": 342.69, "vitamin_c_mg": 13.32, "vitamin_d_mcg": 16.5, "vitamin_e_mg": 9.78, "vitamin_k_mcg": 232.66, "vitamin_b6_mg": 1.12, "vitamin_b12_mcg": 4.85, "thiamin_mg": 0.46, "riboflavin_mg": 0.34, "niacin_mg": 13.63, "folate_mcg": 218.09, "water_g": 214.2, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten fresh. Store dressing separately from greens to prevent wilting. Cooked salmon keeps 3 days.", "duration": "P1D"}, "freezer": {"notes": "Do not freeze salad greens.", "duration": null}, "reheating": "Enjoy salmon cold on leftovers, or gently warm in a pan over low heat.", "does_not_keep": false}', '[{"name": "Non-stick skillet or frying pan", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Small bowl (for dressing)", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}]', '[{"symptom": "Salmon skin stuck to the pan", "likely_cause": "Pan was not hot enough or fish was moved too early", "prevention": "Ensure oil is shimmering before adding fish; do not touch fish for the first 3 minutes", "fix": "Scrape off skin and serve as skinless fillets; crisp the skin separately if salvaged"}, {"symptom": "Vinaigrette separated", "likely_cause": "Oil added too quickly", "prevention": "Add oil drop-by-drop initially while whisking vigorously", "fix": "Add a teaspoon of warm water and whisk vigorously to re-emulsify"}]', '["Patting the salmon dry is the single most important step for a good sear; moisture creates steam and prevents browning.", "Belgian endives oxidize (turn brown) quickly after cutting. Toss them with the dressing immediately or squeeze a little lemon juice on them if prepping in advance.", "For a milder onion flavor, soak the minced shallots in the vinegar for 5 minutes before adding the mustard and oil.", "This recipe works excellently with leftover cold poached salmon for an even faster meal."]', '"This salad draws from French bistro traditions, where the bitterness of chicory (endives) is classically paired with rich proteins and sharp mustard vinaigrettes (Salade Lyonnaise style, adapted here for seafood). It highlights the modern focus on functional plating\u2014combining temperature contrasts (hot fish, cold greens) for a more dynamic eating experience."', 684.73);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('91711b76-3619-421a-bff6-571f334dd500', 'Honey Orange Tarragon Chicken Breasts', 'Succulent boneless chicken breasts infused with the citrusy brightness of fresh orange and the anise-like warmth of tarragon. A honey glaze caramelizes under the broiler, creating a golden, aromatic finish perfect for a light yet sophisticated dinner.', 'dinner', 'French', 'Easy', '["chicken breast", "honey", "orange", "poultry", "tarragon", "dinner", "easy", "weeknight", "main course", "low calorie", "low-fat", "gluten-free", "healthy"]', '[{"group_name": "Poultry", "items": [{"name": "boneless, skinless chicken breasts", "quantity": 600, "unit": "g", "preparation": "trimmed", "notes": "4 small breasts or 2 large ones halved horizontally", "substitutions": [], "ingredient_id": "2b577d04-33ca-4919-938f-bfc8780a3a4b", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Marinade", "items": [{"name": "fresh orange juice", "quantity": 80, "unit": "ml", "preparation": null, "notes": "about 1 large orange", "substitutions": [], "ingredient_id": "a15da11d-f8dd-46e3-9ac5-725a7912f1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "orange zest", "quantity": 6, "unit": "g", "preparation": null, "notes": "zest of 1 orange", "substitutions": [], "ingredient_id": "c1a067e6-674f-4f68-9fe9-3eda4b074356", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 30, "unit": "g", "preparation": "liquid", "notes": null, "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh tarragon", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": "reserve a pinch for garnish", "substitutions": ["3g dried tarragon"], "ingredient_id": "d424d445-0a4e-45d1-9453-7523eb7b176b", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": null, "preparation": "freshly ground", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a small mixing bowl, whisk together the orange juice, orange zest, honey, olive oil, minced garlic, chopped tarragon, salt, and pepper until the honey is fully dissolved.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Place the chicken breasts in a baking dish. Pour the marinade over the chicken, turning to coat thoroughly. Let stand at room temperature for 20 minutes (or refrigerate for up to 2 hours for deeper flavor).", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Preheat your oven to 200\u00b0C (400\u00b0F).", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Bake the chicken in the preheated oven for 15-18 minutes, depending on thickness, until the internal temperature reaches roughly 70\u00b0C (158\u00b0F).", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT18M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Switch the oven to broil (grill) on high. Broil the chicken for 2-4 minutes until the surface is golden brown and caramelized, and the internal temperature reaches a safe 74\u00b0C (165\u00b0F). Watch closely to prevent burning the honey.", "structured": {"action": "BROIL", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown glaze spots", "tactile": "Firm to the touch"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove from the oven and tent loosely with foil. Let the chicken rest for 5 minutes to redistribute juices before serving.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT50M", "total_time": "PT1H05M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Gluten-Free", "Dairy-Free", "Low-Sodium"], "not_suitable_for": ["Infants under 12 months (honey)"]}', '{"per_serving": {"calories": 334.27, "protein_g": 32.07, "carbohydrates_g": 10.47, "fat_g": 17.87, "saturated_fat_g": 4.56, "trans_fat_g": 0.15, "monounsaturated_fat_g": 8.48, "polyunsaturated_fat_g": 3.35, "fiber_g": 0.49, "sugar_g": 7.85, "sodium_mg": 581.93, "cholesterol_mg": 96, "potassium_mg": 461.16, "calcium_mg": 53.75, "iron_mg": 2.08, "magnesium_mg": 49.61, "phosphorus_mg": 267.32, "zinc_mg": 1.25, "vitamin_a_mcg": 43.63, "vitamin_c_mg": 13.72, "vitamin_d_mcg": 0.6, "vitamin_e_mg": 0.96, "vitamin_k_mcg": 2.71, "vitamin_b6_mg": 0.82, "vitamin_b12_mcg": 0.51, "thiamin_mg": 0.11, "riboflavin_mg": 0.15, "niacin_mg": 14.98, "folate_mcg": 12.68, "water_g": 125.05, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Flavor improves slightly the next day.", "duration": "P3D"}, "freezer": {"notes": "Freeze in sauce to maintain moisture.", "duration": "P2M"}, "reheating": "Gently reheat in a skillet with a splash of water or stock to prevent drying out.", "does_not_keep": false}', '[{"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Baking dish", "required": true, "alternative": "Oven-safe skillet"}, {"name": "Microplane or zester", "required": true, "alternative": null}, {"name": "Meat thermometer", "required": true, "alternative": null}]', '[{"symptom": "Chicken is dry or tough", "likely_cause": "Lean chicken breast was overcooked", "prevention": "Use a meat thermometer and pull exactly when it hits safe temperature; accounting for carryover cooking.", "fix": "Slice the chicken thinly against the grain and toss with extra pan juices or a drizzle of olive oil."}, {"symptom": "Glaze is burnt", "likely_cause": "Honey caramelized too quickly under the broiler", "prevention": "Watch the broiling step constantly; move the rack lower if the heating element is too close.", "fix": "Trim off the burnt sections with a sharp knife before serving."}]', '["Always pat the chicken dry before adding the marinade if you want better adherence, though in this baking method, the excess liquid creates a nice pan sauce.", "If your chicken breasts are very thick (over 2.5cm/1 inch), pound them to an even thickness or butterfly them. This ensures even cooking and prevents the exterior from drying out before the center is safe.", "Tarragon has a strong flavor profile; if you are sensitive to anise flavors, start with half the amount or substitute with thyme for a more subtle herb finish."]', '"The combination of orange (canard \u00e0 l''orange) and tarragon (poulet \u00e0 l''estragon) draws heavily from classic French culinary traditions, adapting these rich flavor profiles into a lighter, modern preparation suitable for health-conscious home cooking."', 334.27);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('91778f31-c97b-4f6f-9127-ba43e3086fd5', 'Honey Mustard Glazed Green Beans', 'Crisp-tender fresh green beans tossed in a vibrant, sweet-and-savory emulsion of Dijon mustard and honey. A bright, glossy side dish that balances the natural earthiness of the beans with a tangy finish.', 'side dish', 'American', 'Easy', '["five ingredient", "green bean", "honey mustard", "easy", "quick", "side dish", "dairy-free", "gluten-free", "low calorie", "low-fat", "vegetarian", "thanksgiving", "healthy"]', '[{"group_name": "Vegetables", "items": [{"name": "fresh green beans", "quantity": 450, "unit": "g", "preparation": "trimmed", "notes": "approx. 1 lb", "substitutions": [], "ingredient_id": "8b7e6e4d-368f-454b-9f38-1d55c66b40e4", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dressing", "items": [{"name": "dijon mustard", "quantity": 30, "unit": "g", "preparation": null, "notes": "smooth or coarse grain", "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "honey", "quantity": 21, "unit": "g", "preparation": null, "notes": "approx. 1 tbsp", "substitutions": ["maple syrup", "agave nectar"], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "extra virgin", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "plus more for blanching water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, optional to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Bring a large pot of salted water to a rolling boil over high heat.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add the trimmed green beans to the boiling water. Cook until bright green and crisp-tender, usually 3 to 5 minutes depending on thickness.", "structured": {"action": "BLANCH", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Vibrant green color", "tactile": "Slight snap when bent"}}, "tips": ["Do not overcook; they will continue to soften slightly after draining."]}, {"step_number": 3, "phase": "prep", "text": "While beans cook, whisk together Dijon mustard, honey, olive oil, and salt in a small bowl until fully emulsified.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Drain the green beans thoroughly in a colander, shaking off excess water. Transfer beans to a serving bowl.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Pour the dressing over the hot beans and toss immediately to coat evenly. The residual heat will help the dressing adhere.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT0M", "total_time": "PT10M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 130}', '{"flags": ["Vegetarian", "Gluten-Free", "Dairy-Free", "Nut-Free", "Soy-Free", "Low-Fat", "Pescatarian"], "not_suitable_for": ["Infants under 12 months (honey)"]}', '{"per_serving": {"calories": 89.25, "protein_g": 2.38, "carbohydrates_g": 12.68, "fat_g": 4.25, "saturated_fat_g": 0.58, "trans_fat_g": null, "monounsaturated_fat_g": 2.75, "polyunsaturated_fat_g": 0.52, "fiber_g": 3.33, "sugar_g": 8.16, "sodium_mg": 383.19, "cholesterol_mg": null, "potassium_mg": 252.22, "calcium_mg": 50.96, "iron_mg": 1.43, "magnesium_mg": 28.45, "phosphorus_mg": 43.16, "zinc_mg": 0.28, "vitamin_a_mcg": 39.41, "vitamin_c_mg": 13.75, "vitamin_d_mcg": null, "vitamin_e_mg": 1, "vitamin_k_mcg": 50.84, "vitamin_b6_mg": 0.16, "vitamin_b12_mcg": null, "thiamin_mg": 0.09, "riboflavin_mg": 0.12, "niacin_mg": 0.83, "folate_mcg": 37.25, "water_g": 102.5, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. The beans may lose some brightness due to the acid in the mustard.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; texture will become mushy upon thawing.", "duration": null}, "reheating": "Serve cold, room temperature, or gently reheat in a pan over low heat.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}]', '[{"symptom": "Beans are olive-drab and mushy", "likely_cause": "Overcooking or acid discoloration", "prevention": "Cook only until bright green (3-5 mins) and serve immediately after adding the acidic mustard dressing", "fix": "Cannot be fixed; serve as ''braised'' style or puree into a soup base"}]', '["For a crunchier texture, shock the boiled beans in ice water to stop cooking, pat dry, and then toss with the dressing just before serving.", "Grainy mustard adds a pleasant textural pop compared to smooth Dijon.", "Ensure the beans are very dry after draining; water will dilute the glaze and prevent it from sticking."]', '"Green beans are a staple of the American table, particularly during Thanksgiving. This preparation moves away from the heavy cream-of-mushroom casseroles of the mid-20th century toward lighter, fresher preparations that highlight the vegetable''s natural crunch."', 89.25);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('9221f8a4-22d1-48c4-926d-816d6e32c1e6', 'Msemen (Moroccan Laminated Flatbread)', 'Golden, square-shaped flatbreads featuring distinct buttery layers and a crispy exterior. These savory-sweet breads offer a texture somewhere between a crêpe and a croissant, perfect for tearing apart and dipping in honey or soft cheese.', 'bread', 'Moroccan', 'Intermediate', '["moroccan", "breads", "breakfast", "snack", "street food", "vegetarian"]', '[{"group_name": "Dough", "items": [{"name": "all-purpose flour", "quantity": 350, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "fine semolina", "quantity": 100, "unit": "g", "preparation": null, "notes": "Plus extra for laminating", "substitutions": [], "ingredient_id": "1a84c379-e19f-49b5-88d9-e7abd6f569af", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 7, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "instant yeast", "quantity": 1, "unit": "g", "preparation": null, "notes": "Optional pinch for extensibility", "substitutions": [], "ingredient_id": "b5658d19-b726-4ddb-b56e-74884c61e753", "nutrition_source": "USDA FoodData Central"}, {"name": "warm water", "quantity": 280, "unit": "ml", "preparation": "approx 35\u00b0C", "notes": "Adjust slightly based on flour absorption", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Lamination Mixture", "items": [{"name": "vegetable oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": "For stretching the dough", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 80, "unit": "g", "preparation": "very soft or melted", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "fine semolina", "quantity": 40, "unit": "g", "preparation": null, "notes": "For sprinkling between layers", "substitutions": [], "ingredient_id": "1a84c379-e19f-49b5-88d9-e7abd6f569af", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a large mixing bowl, combine the all-purpose flour, 100g fine semolina, sugar, salt, and instant yeast. Make a well in the center.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Gradually pour in warm water while mixing with your hand or a wooden spoon until a shaggy dough forms. You may not need all the water, or you may need a splash more.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Transfer dough to a work surface and knead vigorously for 10 minutes. The dough must be smooth, soft, and slightly tacky but not sticky.", "structured": {"action": "KNEAD", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": ["Use the heel of your hand to push the dough away, then fold it back."]}, {"step_number": 4, "phase": "prep", "text": "Divide the dough into 8 equal balls (approx 90g each). Coat each ball generously with vegetable oil, place on a tray, cover with plastic wrap, and let rest for 15 minutes.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": ["Resting is crucial for gluten relaxation; do not skip or the dough will tear."]}, {"step_number": 5, "phase": "assemble", "text": "Oil your work surface. Take one dough ball and flatten it with your hands, stretching it outwards until it is paper-thin and translucent. Do not worry about small holes.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Brush the flattened sheet with soft butter and sprinkle lightly with the extra fine semolina. Fold the top third down to the center, and the bottom third up (like a letter). Repeat butter and semolina on the strip, then fold the right side in and left side over to form a square.", "structured": {"action": "LAMINATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Repeat with remaining balls. Let the formed squares rest on an oiled surface for another 10-15 minutes.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Preheat a heavy skillet or griddle over medium heat (approx 190\u00b0C/375\u00b0F). Take a rested square and flatten it with your hand to double its size, maintaining the square shape.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Place the msemen in the hot pan. Cook for about 2-3 minutes on the first side until golden brown spots appear, then flip.", "structured": {"action": "FRY", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown spots", "tactile": null}}, "tips": []}, {"step_number": 10, "phase": "cook", "text": "Cook the second side for another 2-3 minutes. Flip a few more times to ensure even cooking and puffing. Remove to a cooling rack.", "structured": {"action": "FRY", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT30M", "total_time": "PT1H15M", "overnight_required": false, "yields": "8 flatbreads", "yield_count": 8, "serving_size_g": 110}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": ["Celiac Disease", "Gluten Intolerance"]}', '{"per_serving": {"calories": 363.25, "protein_g": 6.95, "carbohydrates_g": 46.89, "fat_g": 16.5, "saturated_fat_g": 6.25, "trans_fat_g": null, "monounsaturated_fat_g": 2.43, "polyunsaturated_fat_g": 0.63, "fiber_g": 3.19, "sugar_g": 1.13, "sodium_mg": 344.52, "cholesterol_mg": 21.5, "potassium_mg": 106.31, "calcium_mg": 14.37, "iron_mg": 1.13, "magnesium_mg": 26.7, "phosphorus_mg": 94.55, "zinc_mg": 0.71, "vitamin_a_mcg": 68.4, "vitamin_c_mg": null, "vitamin_d_mcg": null, "vitamin_e_mg": 0.26, "vitamin_k_mcg": 0.99, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": 0.02, "thiamin_mg": 0.16, "riboflavin_mg": 0.08, "niacin_mg": 2.11, "folate_mcg": 34.55, "water_g": 43.45, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container or ziplock bag.", "duration": "P3D"}, "freezer": {"notes": "Freeze separated by parchment paper. Reheat directly from frozen.", "duration": "P2M"}, "reheating": "Reheat in a dry pan over medium heat until crispy again, or in a toaster oven.", "does_not_keep": false}', '[{"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Heavy-bottomed frying pan or cast iron skillet", "required": true, "alternative": "Griddle"}, {"name": "Clean work surface", "required": true, "alternative": "Large silicone mat"}, {"name": "Small bowls", "required": true, "alternative": null}]', '[{"symptom": "Dough snaps back and won''t stretch", "likely_cause": "Gluten is too tight", "prevention": "Knead thoroughly and allow adequate resting time", "fix": "Cover the dough and let it rest for another 10-15 minutes before trying again"}, {"symptom": "Bread is tough or hard after cooking", "likely_cause": "Cooked too long on low heat or dough was too dry", "prevention": "Ensure dough is soft/hydrated and cook on medium-high heat to crisp quickly without drying out", "fix": "Eat immediately while warm or reheat in microwave to soften"}]', '["The secret to layers is the ''semolina sprinkle'' between the folds; this creates a physical barrier that prevents the dough layers from fusing completely.", "Use oil for the work surface (it slides better) and butter for the inside layers (better flavor).", "Serve traditionally with a mixture of warm honey and melted butter.", "If using a stand mixer, knead with the dough hook on speed 2 for 8 minutes."]', '"Msemen (also known as Rghaif) is a staple of the Maghreb region. Often served for breakfast or ''Gouter'' (afternoon tea), it showcases the region''s historical mastery of wheat and semolina processing. It is ubiquitous in Moroccan street food stalls and home kitchens alike."', 363.25);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('92396215-b5e7-43f7-8447-3dbd10ba7e3c', 'Smoked Spanish Lentil Stew (Lentejas Estofadas)', 'A comforting, rustic Spanish stew that marries the earthiness of green lentils with the sweetness of leeks and the creamy texture of potatoes. Infused with smoky Pimentón de la Vera and floral saffron, this dish develops a richer, deeper flavor profile after resting overnight, making it the ultimate make-ahead meal.', 'dinner', 'Spanish', 'Easy', '["spanish", "great leftovers", "green lentil", "leek", "make-ahead", "paprika", "potato", "saffron", "dinner", "main course", "vegan", "vegetarian", "one-pot"]', '[{"group_name": "Base Vegetables", "items": [{"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": "liquid", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "leeks", "quantity": 2, "unit": null, "preparation": "cleaned and sliced into half-moons", "notes": "white and light green parts only, approx 300g", "substitutions": [], "ingredient_id": "c689e786-49ea-4b98-9526-3b7bb15a8edc", "nutrition_source": "USDA FoodData Central"}, {"name": "carrots", "quantity": 2, "unit": null, "preparation": "diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "minced", "notes": "approx 20g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "tomato puree", "quantity": 200, "unit": "g", "preparation": "canned or fresh grated", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Stew & Spices", "items": [{"name": "dried green lentils", "quantity": 350, "unit": "g", "preparation": "rinsed", "notes": "Spanish Pardina or French Green prefered", "substitutions": [], "ingredient_id": "353c2d02-3a53-45a2-963d-d5f705584e3f", "nutrition_source": "Aggregated Public Data"}, {"name": "potatoes", "quantity": 400, "unit": "g", "preparation": "peeled and cracked into chunks", "notes": "Starchy variety like Yukon Gold or Russet", "substitutions": [], "ingredient_id": "167cc239-8f97-4774-b14d-aa2cc2effbfb", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable broth", "quantity": 1500, "unit": "ml", "preparation": null, "notes": "or water, adjust for desired thickness", "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "smoked paprika (piment\u00f3n de la vera)", "quantity": 10, "unit": "g", "preparation": null, "notes": "approx 2 tsp; essential for smoky flavor", "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "saffron threads", "quantity": 1, "unit": null, "preparation": null, "notes": "small pinch, approx 0.1g", "substitutions": [], "ingredient_id": "7f9ec0c8-2db1-48ac-a2c9-9b1efce12cf3", "nutrition_source": "USDA FoodData Central"}, {"name": "bay leaf", "quantity": 1, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, start with 5g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Clean the leeks thoroughly to remove any grit between layers, then slice into half-moons. Peel the potatoes and prepare them using the ''chasquido'' method: insert the knife and snap the potato piece off rather than slicing cleanly. This releases starch to thicken the broth.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat the olive oil in a Dutch oven over medium heat (175\u00b0C/350\u00b0F). Add the sliced leeks, diced carrots, and a pinch of salt. Saut\u00e9 gently until the leeks are soft and translucent, about 8-10 minutes. Do not brown them deeply.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT10M", "doneness_cues": {"visual": "Leeks are translucent and soft", "tactile": "Vegetables yield to pressure"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the minced garlic and saut\u00e9 for another 1 minute until fragrant. Stir in the tomato puree and cook for 2-3 minutes to cook out the raw acidity and deepen the color.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Remove the pot from the direct heat briefly (or lower heat significantly) and stir in the smoked paprika. Stir constantly for 30 seconds to release the oils without burning the spice, which would turn it bitter.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": ["Paprika burns very quickly; removing the pot from heat is a safety net."]}, {"step_number": 5, "phase": "cook", "text": "Return the pot to heat. Add the rinsed lentils, prepared potatoes, and bay leaf. Pour in the vegetable broth (or water). Bring the mixture to a boil.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "While the soup comes to a boil, crush the saffron threads in a mortar or small bowl and dissolve in a tablespoon of warm water or broth. Add this saffron liquid to the pot.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Reduce heat to a gentle simmer (low heat, around 85-90\u00b0C/185-195\u00b0F). Cover loosely and cook for 40-50 minutes, or until the lentils are tender and the potatoes are cooked through.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT45M", "doneness_cues": {"visual": null, "tactile": "Lentils are soft but not mushy; potatoes offer no resistance"}}, "tips": ["Check liquid levels halfway through; add more water if the lentils have absorbed too much."]}, {"step_number": 8, "phase": "finish", "text": "Remove from heat. Taste and adjust salt. Let the stew rest for at least 15 minutes before serving to allow the starch to set the texture. For best results, cool completely and refrigerate to serve the next day.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT50M", "total_time": "PT1H10M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 350}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 398.79, "protein_g": 18.86, "carbohydrates_g": 66.45, "fat_g": 9.03, "saturated_fat_g": 1.26, "trans_fat_g": null, "monounsaturated_fat_g": 5.51, "polyunsaturated_fat_g": 1.06, "fiber_g": 16.53, "sugar_g": 10.21, "sodium_mg": 1557, "cholesterol_mg": null, "potassium_mg": 1420.84, "calcium_mg": 112.2, "iron_mg": 10.15, "magnesium_mg": 58.05, "phosphorus_mg": 177.06, "zinc_mg": 1.43, "vitamin_a_mcg": 360.31, "vitamin_c_mg": 32.96, "vitamin_d_mcg": null, "vitamin_e_mg": 2.2, "vitamin_k_mcg": 34.04, "vitamin_b6_mg": 0.43, "vitamin_b12_mcg": null, "thiamin_mg": 0.11, "riboflavin_mg": 0.07, "niacin_mg": 1.34, "folate_mcg": 47.68, "water_g": 118.52, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves significantly after 24 hours.", "duration": "P5D"}, "freezer": {"notes": "Potatoes may soften slightly upon thawing; reheat gently.", "duration": "P3M"}, "reheating": "Simmer gently on stove, adding a splash of water if the stew has thickened.", "does_not_keep": false}', '[{"name": "Dutch oven or heavy-bottomed pot", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Mortar and pestle", "required": false, "alternative": "Small bowl and spoon"}]', '[{"symptom": "Lentils are still hard after 50 minutes", "likely_cause": "Lentils are old or acid (tomato) was added in too high quantity too early", "prevention": "Use fresh dried lentils; ensure simmer is maintained", "fix": "Add a splash more water and continue simmering; pressure cook for 5 minutes if available"}, {"symptom": "Stew tastes bitter", "likely_cause": "Paprika was burnt during the saut\u00e9 step", "prevention": "Add paprika off-heat or with liquid immediately", "fix": "Cannot be fixed completely; try masking with a pinch of sugar or more tomato"}]', '["The ''chasquido'' (cracking) technique for potatoes is crucial for an authentic Spanish texture. By snapping the potato piece off at the end of the cut, you create a rough surface that releases more starch, naturally thickening the stew without flour.", "Use ''Piment\u00f3n de la Vera'' (Spanish smoked paprika). Generic paprika lacks the specific smokiness that mimics the flavor of chorizo in this vegetarian version.", "If eating immediately, a splash of sherry vinegar (Vinagre de Jerez) right before serving adds a bright acidity that lifts the earthy lentils."]', '"This dish is a variation of ''Lentejas a la Riojana'' or ''Lentejas Estofadas'', a staple of Spanish home cooking. Historically a peasant dish, it relies on affordable ingredients like lentils and potatoes, using precious spices like saffron and piment\u00f3n to create a flavor profile that feels luxurious and warming."', 398.79);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('92793785-406d-40b1-858a-0e20bc9ffd33', 'Rabbit Confit Tartine with Mâche & Sherry Vinaigrette', 'A rustic yet refined autumnal appetizer featuring tender, slow-cooked rabbit legs shredded over crusty toasted ciabatta. The richness of the duck fat is cut by a sharp sherry-shallot vinaigrette and the delicate, nutty crunch of fresh mâche.', 'appetizer', 'French', 'Advanced', '["french", "ciabatta", "duck fat", "rabbit", "appetizer", "fall", "labor day"]', '[{"group_name": "Rabbit Cure", "items": [{"name": "rabbit legs", "quantity": 2, "unit": null, "preparation": "whole", "notes": "approx 400-500g total", "substitutions": [], "ingredient_id": "865254c1-8e5c-4dd6-9118-463179db06e7", "nutrition_source": "USDA FoodData Central"}, {"name": "coarse sea salt", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 4, "unit": null, "preparation": null, "notes": "sprigs", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "juniper berries", "quantity": 6, "unit": null, "preparation": "crushed", "notes": "approx 2g", "substitutions": [], "ingredient_id": "d4309d81-8292-476a-9165-14c726a8b271", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "smashed cloves", "notes": "approx 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Confit", "items": [{"name": "duck fat", "quantity": 500, "unit": "g", "preparation": null, "notes": "enough to submerge legs completely", "substitutions": ["goose fat", "olive oil"], "ingredient_id": "abe0fb1c-a625-48e3-8260-88740ccea9d1", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Vinaigrette", "items": [{"name": "sherry vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "dcfa7371-7051-4604-a76e-4a46ae1f9e7b", "nutrition_source": "Aggregated Public Data"}, {"name": "dijon mustard", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "approx 25g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 90, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "036c7254-3de5-4c6e-a2e7-366ad4d05077", "nutrition_source": "Aggregated Public Data"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Assembly", "items": [{"name": "ciabatta bread", "quantity": 1, "unit": null, "preparation": null, "notes": "loaf, approx 300g", "substitutions": [], "ingredient_id": "9ca7b694-691f-4fb4-ac85-960ab71c8c9e", "nutrition_source": "Aggregated Public Data"}, {"name": "m\u00e2che (lamb''s lettuce)", "quantity": 100, "unit": "g", "preparation": "washed and dried", "notes": null, "substitutions": [], "ingredient_id": "40948e8c-c61e-4a3f-929e-af66957a4afc", "nutrition_source": "Aggregated Public Data"}, {"name": "chives", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "The day before serving, combine salt, crushed juniper berries, thyme, and smashed garlic. Rub the mixture thoroughly over the rabbit legs. Cover and refrigerate for 24 hours to cure.", "structured": {"action": "CURE", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "P1D", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Preheat oven to 110\u00b0C/230\u00b0F. Rinse the cure off the rabbit legs thoroughly with cold water and pat completely dry. This step prevents the final dish from being overly salty.", "structured": {"action": "PAT_DRY", "temperature": {"celsius": 110, "fahrenheit": 230}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Place rabbit legs in a heavy pot (Dutch oven) and cover completely with melted duck fat. Bring to a very gentle simmer on the stove, then transfer to the oven uncovered. Cook until the meat is extremely tender and pulling away from the bone, approximately 3 to 4 hours.", "structured": {"action": "CONFIT", "temperature": null, "duration": "PT3H30M", "doneness_cues": {"visual": null, "tactile": "Meat yields instantly to pressure"}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Remove rabbit from fat and let cool slightly. While still warm, shred the meat from the bones using two forks. Discard bones and gristle. Stir in 20-30ml of the warm duck fat to keep the meat moist. Season with black pepper (salt should not be needed due to curing).", "structured": {"action": "SHRED", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Slice the ciabatta into 2cm thick slices. Brush lightly with olive oil or reserved duck fat. Toast in a pan or oven until golden brown and crisp.", "structured": {"action": "TOAST", "temperature": null, "duration": null, "doneness_cues": {"visual": "Golden brown edges", "tactile": "Crisp surface"}}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "In a small bowl, whisk the sherry vinegar, dijon mustard, and minced shallot. Slowly drizzle in the olive oil while whisking vigorously to emulsify. Season with pepper.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "To assemble, pile a generous amount of shredded rabbit onto each toast. Toss the m\u00e2che lightly with just enough vinaigrette to coat the leaves (do not drown them). Top the rabbit with the dressed greens and garnish with fresh chives.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "P1DT4H", "total_time": "P1DT4H45M", "overnight_required": true, "yields": "8 tartines", "yield_count": 8, "serving_size_g": 180}', '{"flags": ["Dairy-Free", "Nut-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 869.28, "protein_g": 19.51, "carbohydrates_g": 20.38, "fat_g": 78.97, "saturated_fat_g": 23.76, "trans_fat_g": null, "monounsaturated_fat_g": 1.22, "polyunsaturated_fat_g": 0.89, "fiber_g": 1.21, "sugar_g": 0.43, "sodium_mg": 1624.23, "cholesterol_mg": 46.13, "potassium_mg": 346.68, "calcium_mg": 39.98, "iron_mg": 2.9, "magnesium_mg": 16.31, "phosphorus_mg": 159.88, "zinc_mg": 1.4, "vitamin_a_mcg": 79.74, "vitamin_c_mg": 7.13, "vitamin_d_mcg": null, "vitamin_e_mg": null, "vitamin_k_mcg": 0.25, "vitamin_b6_mg": 0.29, "vitamin_b12_mcg": 4.67, "thiamin_mg": 0.06, "riboflavin_mg": 0.13, "niacin_mg": 4.77, "folate_mcg": 7.65, "water_g": 37.83, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store the rabbit meat submerged in its own fat (rillettes style). Assemble tartines fresh.", "duration": "P1W"}, "freezer": {"notes": "Rabbit confit freezes exceptionally well in vacuum bags.", "duration": "P3M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Heavy-bottomed pot or Dutch oven", "required": true, "alternative": null}, {"name": "Wire rack", "required": true, "alternative": null}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}]', '[{"symptom": "Rabbit meat is salty", "likely_cause": "Cure was not rinsed off thoroughly enough", "prevention": "Wash the legs under cold running water for a full minute after curing", "fix": "Shred the meat and mix with unsalted butter or more duck fat to dilute the saltiness; serve on unsalted bread"}, {"symptom": "Meat is tough or dry", "likely_cause": "Confit temperature was too high (boiling instead of poaching)", "prevention": "Ensure the fat never boils; it should barely bubble", "fix": "Add more fat and continue cooking at a lower temperature, though texture may remain stringy"}]', '["Save the leftover duck fat. Strain it through cheesecloth and store in the fridge; it is liquid gold for roasting potatoes.", "The curing step is non-negotiable. It seasons the meat to the bone and draws out excess moisture, resulting in that signature dense, silky confit texture.", "For a true bistro touch, rub a raw clove of garlic on the hot toasted ciabatta before adding the rabbit.", "If m\u00e2che is unavailable, micro-arugula or watercress make excellent substitutes providing similar pepperiness or nuttiness."]', '"Confit is a centuries-old preservation method from Gascony, France, originally designed to store meat without refrigeration by submerging it in its own rendered fat. This tartine adapts that rustic peasant tradition into an elegant starter, balancing the heavy richness of the historic preservation technique with the fresh acidity of modern plating."', 869.28);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('92cefe3c-d118-4938-a793-00c220e42cdc', 'Char-Grilled Greek Octopus with Lemon and Thyme', 'Tender, smoky octopus tentacles with a crisp exterior, dressed in a bright emulsion of extra virgin olive oil, fresh lemon, garlic, and thyme. This method ensures a buttery texture without the rubberiness often associated with cephalopods.', 'appetizer', 'Greek', 'Intermediate', '["greek", "garlic", "octopus", "thyme", "appetizer", "dinner", "seafood", "summer", "grill"]', '[{"group_name": "Octopus Braise", "items": [{"name": "whole octopus", "quantity": 1500, "unit": "g", "preparation": "cleaned, beak and eyes removed", "notes": "Preferably frozen and thawed, as freezing helps tenderize", "substitutions": [], "ingredient_id": "16d70243-59aa-40db-8566-7e2c76ed0053", "nutrition_source": "USDA FoodData Central"}, {"name": "red wine vinegar", "quantity": 80, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "9e1b7e74-fdcb-4836-8349-4f7ad86d62df", "nutrition_source": "USDA FoodData Central"}, {"name": "bay leaves", "quantity": 2, "unit": null, "preparation": null, "notes": "approx 1g", "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}, {"name": "black peppercorns", "quantity": 5, "unit": "g", "preparation": "whole", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Lemon Thyme Dressing (Ladolemono)", "items": [{"name": "extra virgin olive oil", "quantity": 80, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 40, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced to a paste", "notes": "approx 6-8g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 5, "unit": "g", "preparation": "leaves picked", "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "flaky sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, for finishing", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Rinse the octopus thoroughly under cold running water. Place it in a large heavy-bottomed pot. Add the bay leaves, peppercorns, and red wine vinegar. Do not add water; the octopus will release its own liquid.", "structured": {"action": "PREPARE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Cover the pot and bring to a simmer over medium-low heat. Cook for 45 to 60 minutes. The octopus is done when a knife slides into the thickest part of a tentacle with zero resistance.", "structured": {"action": "BRAISE", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT1H", "doneness_cues": {"visual": null, "tactile": "Knife slides in easily like butter"}}, "tips": ["Check liquid levels halfway through; if the pot is dry, add a splash of water, but this is rarely necessary."]}, {"step_number": 3, "phase": "prep", "text": "Remove the octopus from the liquid and let it cool completely to room temperature. This rest period prevents the delicate skin from slipping off during grilling. Once cool, separate the tentacles from the head.", "structured": {"action": "COOL", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In a small bowl, whisk together the olive oil, lemon juice, minced garlic, fresh thyme, and dried oregano until emulsified.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Preheat your grill or grill pan to high heat (approx. 230\u00b0C/450\u00b0F). Brush the octopus tentacles lightly with a small amount of the olive oil mixture.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 230, "fahrenheit": 446}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Grill the tentacles for 3-4 minutes per side, just until the exterior is crisp and charred in spots. Do not overcook, or it will dry out.", "structured": {"action": "GRILL", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Crisp exterior, distinct char marks", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Transfer to a serving platter. Pour the remaining dressing over the hot octopus. Finish with a pinch of flaky sea salt and serve immediately.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT1H30M", "total_time": "PT2H", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Low-Carb", "Keto", "Paleo", "Whole30", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 498.63, "protein_g": 56.28, "carbohydrates_g": 11.03, "fat_g": 24.02, "saturated_fat_g": 3.66, "trans_fat_g": null, "monounsaturated_fat_g": 15.21, "polyunsaturated_fat_g": 3.04, "fiber_g": 0.77, "sugar_g": 0.3, "sodium_mg": 1059.39, "cholesterol_mg": 180, "potassium_mg": 1368.4, "calcium_mg": 222.64, "iron_mg": 20.64, "magnesium_mg": 119.83, "phosphorus_mg": 706.62, "zinc_mg": 6.38, "vitamin_a_mcg": 172.49, "vitamin_c_mg": 25.28, "vitamin_d_mcg": null, "vitamin_e_mg": 7.5, "vitamin_k_mcg": 17.61, "vitamin_b6_mg": 1.39, "vitamin_b12_mcg": 75, "thiamin_mg": 0.12, "riboflavin_mg": 0.16, "niacin_mg": 7.96, "folate_mcg": 64.01, "water_g": 330.93, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best enjoyed immediately. If reheating, do so gently to avoid toughening.", "duration": "P2D"}, "freezer": {"notes": "Brazed octopus can be frozen before grilling.", "duration": "P1M"}, "reheating": "Sear quickly in a hot skillet or grill pan.", "does_not_keep": false}', '[{"name": "Large heavy-bottomed pot with lid", "required": true, "alternative": null}, {"name": "Outdoor grill or cast-iron grill pan", "required": true, "alternative": "Cast iron skillet"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}]', '[{"symptom": "Octopus is rubbery and tough", "likely_cause": "The initial braising time was too short", "prevention": "Ensure the knife slides into the thickest part of the tentacle with absolutely no resistance before removing from the pot", "fix": "Return to the pot with a little water and continue simmering until tender"}, {"symptom": "Skin is peeling off excessively", "likely_cause": "Octopus was grilled while still hot or wet", "prevention": "Allow the octopus to cool and air dry slightly before grilling", "fix": "Cosmetic issue only; proceed with serving"}]', '["Buying frozen octopus is actually preferred by many chefs; the freezing process helps break down the fibrous connective tissue, acting as a natural tenderizer.", "Do not salt the water during the braising step. The octopus reduces significantly and concentrates its natural ocean salinity. Only salt at the very end if needed.", "If you have a wine cork handy (natural cork only), toss it into the braising liquid. While scientifically debated, many Greek grandmothers swear it contains enzymes that help tenderize the meat.", "The leftover braising liquid is intense and salty; it can be reduced and used as a base for a seafood pasta sauce, but be careful with the salt levels."]', '"Chtapodi sti Schara (grilled octopus) is a quintessential Greek summer dish, often seen hanging on clotheslines outside seaside tavernas to sun-dry before grilling. It captures the essence of the Aegean: simple, fresh ingredients prepared with patience to transform a tough catch into a delicacy."', 498.63);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('935b1e26-848c-4733-b283-e4a24bdb539d', 'Jamaican Rum Dark Chocolate Truffles', 'Decadent, velvet-textured dark chocolate ganache centers spiked with bold, funk-forward Jamaican rum. Finished with a dusting of bitter cocoa powder to balance the sweetness and warmth of the spirit.', 'confection', 'Fusion', 'Intermediate', '["truffles", "chocolate", "rum", "dessert", "no-bake", "gift-worthy", "party"]', '[{"group_name": "Ganache Base", "items": [{"name": "dark chocolate (70% cocoa solids)", "quantity": 300, "unit": "g", "preparation": "finely chopped", "notes": "Do not use chips; use high-quality bars or couverture f\u00e8ves", "substitutions": [], "ingredient_id": "08395d12-1a43-46f7-b602-36c2d07ce259", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream (35% fat)", "quantity": 150, "unit": "ml", "preparation": "liquid", "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "room temperature, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "jamaican rum", "quantity": 45, "unit": "ml", "preparation": null, "notes": "Preferably aged/dark rum for depth", "substitutions": [], "ingredient_id": "1a607a45-2f40-47c4-a400-12536a1c3826", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "finely ground", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Coating", "items": [{"name": "unsweetened cocoa powder", "quantity": 50, "unit": "g", "preparation": "sifted", "notes": "Dutch-processed preferred for color", "substitutions": [], "ingredient_id": "c06a8e5a-163a-4f21-ad00-a6d90e34c38c", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the finely chopped dark chocolate and sea salt into a medium heatproof bowl. Ensure there are no large chunks, as they will not melt evenly.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a small saucepan, heat the heavy cream over medium heat until it just begins to simmer around the edges (approx 85\u00b0C/185\u00b0F). Do not let it come to a rolling boil.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": null, "doneness_cues": {"visual": "Small bubbles forming at the edges, steam rising", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Pour the hot cream evenly over the chopped chocolate. Do not stir immediately. Let the mixture sit undisturbed for 5 minutes to allow the heat to penetrate the chocolate.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Using a silicone spatula, gently stir the mixture starting from the center in small concentric circles. As the emulsion forms, gradually widen the circles until the ganache is glossy, dark, and completely smooth.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": {"visual": "Glossy, uniform dark brown color, no streaks", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the room temperature butter, stirring gently until fully incorporated. Finally, pour in the Jamaican rum and stir until the ganache is once again smooth and glossy.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "Cover the surface of the ganache directly with plastic wrap (to prevent a skin forming) and refrigerate until firm enough to scoop, usually 3 to 4 hours.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT4H", "doneness_cues": {"visual": null, "tactile": "Firm to the touch, holds an indentation"}}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Place the cocoa powder in a shallow bowl. Using a small scoop or melon baller, scoop portions of the chilled ganache. Briefly roll each portion between your palms to form a sphere. If the ganache sticks, wear gloves or dust hands with cocoa.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Work quickly to prevent the heat of your hands from melting the chocolate.", "If the mixture becomes too soft, return it to the fridge for 10 minutes."]}, {"step_number": 8, "phase": "finish", "text": "Immediately toss the rolled truffle in the cocoa powder to coat completely. Shake off excess powder and place on a parchment-lined tray.", "structured": {"action": "DREDGE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT4H", "total_time": "PT4H45M", "overnight_required": false, "yields": "30 truffles", "yield_count": 30, "serving_size_g": 15}', '{"flags": ["Vegetarian", "Gluten-Free", "Egg-Free", "Nut-Free"], "not_suitable_for": ["Children under 18 (alcohol)", "Pregnant individuals (alcohol)"]}', '{"per_serving": {"calories": 89.33, "protein_g": 1.09, "carbohydrates_g": 6.35, "fat_g": 6.67, "saturated_fat_g": 3.99, "trans_fat_g": 0.07, "monounsaturated_fat_g": 1.92, "polyunsaturated_fat_g": 0.24, "fiber_g": 1.42, "sugar_g": 3.85, "sodium_mg": 28.68, "cholesterol_mg": 8.4, "potassium_mg": 87.03, "calcium_mg": 11.89, "iron_mg": 0.87, "magnesium_mg": 26.29, "phosphorus_mg": 41.37, "zinc_mg": 0.39, "vitamin_a_mcg": 27.69, "vitamin_c_mg": 0.03, "vitamin_d_mcg": 0.08, "vitamin_e_mg": 0.13, "vitamin_k_mcg": 0.99, "vitamin_b6_mg": 0.01, "vitamin_b12_mcg": 0.03, "thiamin_mg": 0.01, "riboflavin_mg": 0.02, "niacin_mg": 0.12, "folate_mcg": 0.76, "water_g": 3.22, "alcohol_g": null, "caffeine_mg": 12.43}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container to prevent absorbing fridge odors.", "duration": "P2W"}, "freezer": {"notes": "Thaw overnight in the refrigerator before serving.", "duration": "P2M"}, "reheating": "Serve at room temperature for best texture.", "does_not_keep": false}', '[{"name": "Heatproof mixing bowl", "required": true, "alternative": null}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Silicone spatula", "required": true, "alternative": null}, {"name": "Small cookie scoop or melon baller", "required": true, "alternative": "Two teaspoons"}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Latex or nitrile gloves", "required": false, "alternative": null}]', '[{"symptom": "Ganache is split (looks oily or grainy)", "likely_cause": "The cream was too hot or the mixture was stirred too vigorously, breaking the emulsion.", "prevention": "Let cream cool slightly after simmering; stir gently from the center.", "fix": "Add 15ml of warm liquid cream while stirring gently to bring the emulsion back together."}, {"symptom": "Ganache is too soft to roll", "likely_cause": "Too much liquid (rum) or insufficient chilling time.", "prevention": "Measure liquid ingredients precisely.", "fix": "Freeze the bowl for 20-30 minutes; if still too soft, melt 50g more chocolate, stir in, and re-chill."}]', '["The quality of the rum matters significantly here. A Jamaican pot-still rum provides funky, banana, and spice notes that pair exceptionally well with dark chocolate.", "For the smoothest mouthfeel, ensure the butter is truly soft before adding it to the warm ganache.", "These truffles taste best after sitting for 24 hours, allowing the rum flavor to mellow and distribute evenly throughout the chocolate.", "If you prefer a crunchy texture, you can roll the truffles in toasted coconut or crushed cacao nibs instead of cocoa powder."]', '"While the chocolate truffle is a French invention named after the prized fungus it resembles, this variation pays homage to the Caribbean''s history of sugar cane and rum production. Jamaican rum, known for its distinct ''hogo'' (high-ester funk), provides a complex counterpoint to the bitterness of dark chocolate."', 89.33);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('935b9a3a-fb2e-4a62-b9ce-5a36985a7775', 'Restorative Golden Garlic Broth', 'A translucent, golden elixir where pungent garlic transforms into sweet, buttery pearls through gentle simmering. This deeply comforting broth balances the natural sugars of slow-cooked alliums with fresh herbal notes, offering a gentle immune-boosting warmth without the aggressive heat of raw garlic.', 'soup', 'European Rustic', 'Easy', '["vegan", "vegetarian", "soup", "restorative", "comfort food", "low calorie", "garlic"]', '[{"group_name": "Base Aromatics", "items": [{"name": "extra virgin olive oil", "quantity": 30, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "celery stalk", "quantity": 1, "unit": null, "preparation": "sliced thin", "notes": "approx 50g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "The Garlic", "items": [{"name": "garlic heads", "quantity": 3, "unit": null, "preparation": "cloves separated and peeled", "notes": "approx 40-50 cloves / 120g total", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Liquid & Herbs", "items": [{"name": "water", "quantity": 1500, "unit": "ml", "preparation": null, "notes": "or low-sodium vegetable stock for richer flavor", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh thyme", "quantity": 5, "unit": null, "preparation": "whole sprigs", "notes": "approx 5g", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "bay leaves", "quantity": 2, "unit": null, "preparation": "dried", "notes": null, "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}, {"name": "black peppercorns", "quantity": 10, "unit": null, "preparation": "whole", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 10, "unit": "g", "preparation": null, "notes": "adjust to taste at the end", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the garlic by separating the heads into cloves. Peel them carefully to keep the cloves whole. A quick way is to crush the head slightly to separate, then blanch in boiling water for 30 seconds to loosen skins.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Do not smash the cloves; we want them whole to simmer gently."]}, {"step_number": 2, "phase": "cook", "text": "In a heavy pot over medium-low heat, warm the olive oil. Add the diced onion, sliced celery, and a pinch of salt. Sweat the vegetables for 8-10 minutes until they are translucent and soft, but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT10M", "doneness_cues": {"visual": "Translucent onions", "tactile": "Soft texture"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the peeled whole garlic cloves to the pot. Stir gently to coat them in the oil and aromatics. Cook for 2-3 minutes just to wake up the garlic oils, ensuring they do not take on any color.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour in the water (or vegetable stock). Add the thyme sprigs, bay leaves, and whole black peppercorns. Increase heat to bring the liquid to a gentle boil, then immediately reduce to a very low simmer.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Cover the pot partially with a lid and simmer gently for 40-45 minutes. The garlic cloves should become completely tender and creamy, resembling soft butter when pressed.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT45M", "doneness_cues": {"visual": null, "tactile": "Garlic mashes easily against pot side"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove the thyme stems and bay leaves. Stir in the lemon juice to brighten the flavor. Taste and adjust salt. Serve hot, ensuring each bowl gets plenty of the soft, sweet garlic cloves.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT45M", "total_time": "PT1H10M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Paleo", "Whole30", "Low-Carb"], "not_suitable_for": []}', '{"per_serving": {"calories": 132.93, "protein_g": 2.63, "carbohydrates_g": 15.08, "fat_g": 7.81, "saturated_fat_g": 1.1, "trans_fat_g": null, "monounsaturated_fat_g": 5.5, "polyunsaturated_fat_g": 0.89, "fiber_g": 1.88, "sugar_g": 2.18, "sodium_mg": 997.73, "cholesterol_mg": null, "potassium_mg": 241, "calcium_mg": 90.12, "iron_mg": 1.28, "magnesium_mg": 20.9, "phosphorus_mg": 63.81, "zinc_mg": 0.51, "vitamin_a_mcg": 17.86, "vitamin_c_mg": 19.54, "vitamin_d_mcg": null, "vitamin_e_mg": 1.18, "vitamin_k_mcg": 50.25, "vitamin_b6_mg": 0.44, "vitamin_b12_mcg": null, "thiamin_mg": 0.09, "riboflavin_mg": 0.06, "niacin_mg": 0.36, "folate_mcg": 17.68, "water_g": 444.43, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors deepen over time. Store in an airtight container.", "duration": "P5D"}, "freezer": {"notes": "Freeze without garnish. Garlic texture may become slightly softer upon thawing.", "duration": "P3M"}, "reheating": "Gently warm on the stovetop over medium heat.", "does_not_keep": false}', '[{"name": "Heavy-bottomed pot or Dutch oven", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Fine mesh sieve", "required": false, "alternative": "Slotted spoon"}]', '[{"symptom": "Broth tastes bitter or acrid", "likely_cause": "The garlic was burned or browned too darkly during the initial saut\u00e9 step", "prevention": "Keep heat low (medium-low) and stir constantly when adding garlic; do not let it turn brown", "fix": "Cannot be fixed. Burnt garlic permeates the liquid. You must restart."}, {"symptom": "Broth is too thin or watery", "likely_cause": "Natural result of a broth-based soup without starch thickeners", "prevention": "Accept the style, or use vegetable stock instead of water for body", "fix": "Mash 5-6 of the soft garlic cloves and stir them back into the broth to emulsify slightly"}]', '["The cooked garlic cloves lose their pungency and become surprisingly sweet. Encourage diners to smash them onto crusty bread or eat them whole.", "For a clearer consomm\u00e9 style, strain the solids out completely, but I recommend keeping the garlic for the full experience.", "If you are not strictly vegan, a parmesan rind simmered in the broth adds incredible umami depth.", "This is an excellent base for a poaching liquid; try poaching tofu or delicate vegetables in it for the last 5 minutes."]', '"While garlic is often used as a background note in Western cooking, this dish celebrates it as a vegetable in its own right. It draws inspiration from Spanish ''Sopa de Ajo'' (Garlic Soup) and French garlic confit traditions, focusing on the restorative properties of alliums which have been used in folk medicine for centuries to combat colds."', 132.93);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('93c1d13b-bb2a-4988-a034-bdb85d7cbc6b', 'Classic French Carrot Salad with Garlic and Parsley', 'A vibrant bistro staple featuring sweet shredded carrots macerated in a sharp vinaigrette. The combination of pungent raw garlic, fresh parsley, and nutty peanut oil transforms humble ingredients into a crisp, refreshing side dish that improves with time.', 'salad', 'French', 'Easy', '["vegetables", "carrot", "garlic", "parsley", "peanut oil", "red wine vinegar", "salad", "vegan", "vegetarian", "french cuisine", "side dish"]', '[{"group_name": "Vegetables", "items": [{"name": "carrots", "quantity": 500, "unit": "g", "preparation": "peeled and trimmed", "notes": "Choose firm, sweet medium-sized carrots", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "flat-leaf parsley", "quantity": 15, "unit": "g", "preparation": "finely chopped", "notes": "Leaves only", "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "minced or grated", "notes": "approx. 5g, adjust to taste", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vinaigrette", "items": [{"name": "peanut oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": "Or roasted peanut oil for stronger flavor", "substitutions": ["neutral vegetable oil", "sunflower oil"], "ingredient_id": "79fcc203-cdb8-46c3-8334-5318433bd063", "nutrition_source": "USDA FoodData Central"}, {"name": "red wine vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "9e1b7e74-fdcb-4836-8349-4f7ad86d62df", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "Fine sea salt", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Peel the carrots and remove the ends. Grate them using the medium holes of a box grater or the shredding attachment of a food processor.", "structured": {"action": "GRATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, combine the minced garlic, red wine vinegar, salt, and black pepper. Whisk briefly to dissolve the salt.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Slowly stream in the peanut oil while whisking continuously to create an emulsified vinaigrette.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Add the grated carrots and chopped parsley to the bowl with the vinaigrette. Toss vigorously until the carrots are evenly coated.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Let the salad rest in the refrigerator for at least 30 minutes before serving. This allows the carrots to soften slightly and absorb the garlic and vinegar flavors.", "structured": {"action": "REST", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT30M", "doneness_cues": null}, "tips": ["If the carrots are very dry, you can massage the dressing into them with clean hands to help break down the fibers."]}]', '{"active_time": "PT15M", "passive_time": "PT30M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 140}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Soy-Free", "Paleo", "Low-Carb"], "not_suitable_for": ["Individuals with peanut allergies"]}', '{"per_serving": {"calories": 155.25, "protein_g": 1.38, "carbohydrates_g": 12.8, "fat_g": 11.6, "saturated_fat_g": 1.95, "trans_fat_g": null, "monounsaturated_fat_g": 5.22, "polyunsaturated_fat_g": 3.74, "fiber_g": 3.71, "sugar_g": 5.97, "sodium_mg": 379.91, "cholesterol_mg": null, "potassium_mg": 430.64, "calcium_mg": 50.2, "iron_mg": 0.68, "magnesium_mg": 17.77, "phosphorus_mg": 48.53, "zinc_mg": 0.36, "vitamin_a_mcg": 1059.61, "vitamin_c_mg": 12.77, "vitamin_d_mcg": null, "vitamin_e_mg": 2.62, "vitamin_k_mcg": 78.51, "vitamin_b6_mg": 0.19, "vitamin_b12_mcg": null, "thiamin_mg": 0.09, "riboflavin_mg": 0.08, "niacin_mg": 1.29, "folate_mcg": 29.53, "water_g": 117.98, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves after the first day.", "duration": "P4D"}, "freezer": {"notes": "Do not freeze; texture will be compromised.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Box grater", "required": true, "alternative": "Food processor with shredding disc"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Vegetable peeler", "required": true, "alternative": null}]', '[{"symptom": "Salad tastes too acidic or harsh", "likely_cause": "The carrots were not naturally sweet enough to balance the vinegar", "prevention": "Taste your raw carrots before starting; if bitter, use a pinch of sugar", "fix": "Add a small pinch of sugar or a drop of maple syrup to balance the acidity"}]', '["Peanut oil (huile d''arachide) is traditional in French salads for its neutral flavor profile, but roasted peanut oil adds a wonderful nutty dimension.", "The resting time (maceration) is scientifically crucial; the salt draws moisture from the carrots, mingling with the oil to create a self-saucing effect.", "For a finer texture similar to French delicatessens, grate half the carrots on the fine setting and half on the medium setting."]', '"Known as ''Carottes R\u00e2p\u00e9es'' in France, this salad is a ubiquity in school lunches, bistros, and charcuteries across the country. It exemplifies the French philosophy of elevating simple, raw ingredients through precise seasoning and texture."', 155.25);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('94162b70-f478-477f-b897-c45acb4ffd9c', 'Vibrant Broccoli Basil Pesto', 'A vivid green, nutrient-dense twist on classic Genovese sauce. Tender blanched broccoli provides a creamy body and earthy sweetness, balanced by aromatic fresh basil, savory walnuts, and zesty lemon. This versatile condiment clings perfectly to pasta, spreads beautifully on toast, or serves as a fresh dip.', 'sauce', 'Italian', 'Easy', '["condiments", "basil", "broccoli", "parmesan", "easy", "quick", "fall", "gluten-free", "healthy", "low cholesterol", "low-sodium", "vegetarian"]', '[{"group_name": "Base", "items": [{"name": "broccoli florets", "quantity": 250, "unit": "g", "preparation": "fresh, cut into small pieces", "notes": "can use peeled stems as well", "substitutions": [], "ingredient_id": "b0a26615-a0a7-4b5c-9143-e9becf53b41a", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh basil leaves", "quantity": 30, "unit": "g", "preparation": "washed and dried", "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics & Body", "items": [{"name": "walnuts", "quantity": 40, "unit": "g", "preparation": "halves or pieces", "notes": null, "substitutions": ["pine nuts", "almonds", "sunflower seeds"], "ingredient_id": "ab4fe25a-a215-4af7-8109-055c28e0bef2", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "peeled", "notes": "approx. 6-8g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "parmesan cheese", "quantity": 40, "unit": "g", "preparation": "grated", "notes": "use vegetarian rennet cheese if required", "substitutions": ["nutritional yeast (for vegan)"], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Liquids & Seasoning", "items": [{"name": "extra virgin olive oil", "quantity": 80, "unit": "ml", "preparation": "high quality", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": "about half a lemon", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": null, "notes": "from 1 lemon", "substitutions": [], "ingredient_id": "a5fb6a2a-dcda-4ab2-8fe6-472d7fcc39d1", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "adjust to taste, cheese provides salt", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Bring a large pot of salted water to a boil. Prepare an ice water bath in a large bowl.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add the broccoli florets to the boiling water and blanch for 2-3 minutes until bright green and tender-crisp.", "structured": {"action": "BLANCH", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Bright green color", "tactile": "Knife pierces easily but still firm"}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Immediately transfer the broccoli to the ice bath using a slotted spoon. Let cool completely, then drain well and pat dry with paper towels to remove excess moisture.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": ["Removing excess water is crucial to prevent watery pesto."]}, {"step_number": 4, "phase": "cook", "text": "In a dry small skillet over medium heat, toast the walnuts for 3-4 minutes until fragrant and slightly darkened. Watch closely to prevent burning.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Lightly browned", "tactile": "Fragrant nutty aroma"}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "In a food processor, combine the garlic, toasted walnuts, and grated Parmesan. Pulse until finely chopped.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Add the dried broccoli, fresh basil, lemon juice, and lemon zest to the processor. Pulse until the mixture is coarsely combined.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "With the motor running on low, slowly stream in the olive oil until emulsified and smooth. Season with salt and pepper to taste.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["For a chunkier texture, pulse the oil in rather than streaming constantly."]}]', '{"active_time": "PT15M", "passive_time": "PT5M", "total_time": "PT20M", "overnight_required": false, "yields": "450g (approx. 2 cups)", "yield_count": 15, "serving_size_g": 30}', '{"flags": ["Vegetarian", "Gluten-Free", "Egg-Free", "Soy-Free", "Low-Carb", "Sugar-Free", "Keto"], "not_suitable_for": ["Nut allergies (walnuts)", "Dairy allergies (cheese)"]}', '{"per_serving": {"calories": 82.47, "protein_g": 1.94, "carbohydrates_g": 1.94, "fat_g": 7.82, "saturated_fat_g": 1.32, "trans_fat_g": null, "monounsaturated_fat_g": 4.34, "polyunsaturated_fat_g": 1.86, "fiber_g": 0.7, "sugar_g": 0.4, "sodium_mg": 89.07, "cholesterol_mg": 1.81, "potassium_mg": 77.33, "calcium_mg": 47.22, "iron_mg": 0.33, "magnesium_mg": 10.52, "phosphorus_mg": 40.89, "zinc_mg": 0.25, "vitamin_a_mcg": 16.02, "vitamin_c_mg": 16.16, "vitamin_d_mcg": 0.01, "vitamin_e_mg": 0.94, "vitamin_k_mcg": 28.75, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": 0.03, "thiamin_mg": 0.02, "riboflavin_mg": 0.03, "niacin_mg": 0.17, "folate_mcg": 14.92, "water_g": 19.1, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container with a thin layer of olive oil on top to prevent oxidation.", "duration": "P5D"}, "freezer": {"notes": "Freeze in ice cube trays for convenient single servings.", "duration": "P3M"}, "reheating": "Thaw at room temperature; do not heat directly to preserve fresh flavor.", "does_not_keep": false}', '[{"name": "Food processor", "required": true, "alternative": "High-speed blender"}, {"name": "Large pot", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Small skillet", "required": true, "alternative": null}, {"name": "Large bowl", "required": true, "alternative": "For ice bath"}]', '[{"symptom": "Pesto is watery or thin", "likely_cause": "Broccoli was not dried enough after blanching", "prevention": "Squeeze blanched broccoli in a clean tea towel to remove hidden water", "fix": "Add more walnuts or cheese to thicken the texture"}, {"symptom": "Taste is too bitter", "likely_cause": "Olive oil polyphenols were released by high-speed blending or garlic is too potent", "prevention": "Stir oil in by hand at the end instead of blending", "fix": "Add a pinch of sugar or more lemon juice to balance"}]', '["Blanching the broccoli serves two purposes: it locks in the vibrant green color (chlorophyll) and removes the raw sulfurous edge, making the pesto sweeter.", "To lower the sodium content further, reduce the Parmesan quantity and supplement with toasted nutritional yeast for savory depth.", "This pesto is thicker than traditional basil pesto. If using it for pasta, reserve some starchy pasta cooking water to thin the sauce when tossing.", "For a zero-waste approach, peel the thick broccoli stalks, chop them, and blanch them along with the florets."]', '"While ''pesto'' conventionally refers to Pesto alla Genovese from Liguria, the term simply means ''to pound'' or ''crush''. This variation adapts the Italian tradition to cool-weather produce, utilizing broccoli\u2014a vegetable cultivated in Italy since Roman times\u2014to create a modern, nutrient-dense ''condimento'' that bridges the gap between summer basil and autumn harvest."', 82.47);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('949de7a3-95ff-4340-b1b0-612d96c2951b', 'Brown Butter Cauliflower Amandine', 'A refined yet effortless side dish where tender-crisp steamed cauliflower is dressed in a nutty, golden-brown butter sauce speckled with crunchy toasted almonds and brightened with a squeeze of fresh lemon.', 'side dish', 'French', 'Easy', '["almond", "butter", "cauliflower", "five ingredient", "side dish", "fall", "vegetarian", "gluten-free", "low-carb"]', '[{"group_name": "Vegetable", "items": [{"name": "cauliflower", "quantity": 1, "unit": null, "preparation": "cut into bite-sized florets", "notes": "1 medium head, approx. 600-700g trimmed", "substitutions": [], "ingredient_id": "2d9d5068-77e7-4dfc-b24b-8e6a6275cb33", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sauce", "items": [{"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": "cubed", "notes": "cold or room temperature", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "sliced almonds", "quantity": 40, "unit": "g", "preparation": "flaked or slivered", "notes": null, "substitutions": [], "ingredient_id": "5bcbb4d4-6845-4825-bd21-1c13e52b989c", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": "about half a lemon", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Seasoning", "items": [{"name": "sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly ground", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh parsley", "quantity": 5, "unit": "g", "preparation": "finely chopped", "notes": "for garnish", "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Fill a large pot with about 3cm (1 inch) of water and bring to a boil. Place the cauliflower florets in a steamer basket over the water, ensuring the water does not touch the vegetable.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Cover the pot and steam the cauliflower until tender-crisp. A knife should slide in with slight resistance. Avoid overcooking to mush.", "structured": {"action": "STEAM", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Bright white and slightly translucent at edges", "tactile": "Knife meets slight resistance"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "While cauliflower steams, place the butter in a light-colored skillet over medium heat. Once melted and foaming, add the sliced almonds.", "structured": {"action": "MELT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": ["Using a light-colored pan helps you monitor the color change of the milk solids to prevent burning."]}, {"step_number": 4, "phase": "cook", "text": "Swirl the pan constantly. Cook until the milk solids turn a golden hazelnut brown and the almonds are toasted. Remove from heat immediately once the aroma becomes nutty.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown flecks (milk solids) and toasted almonds", "tactile": "Foam subsides slightly"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Immediately stir in the lemon juice and salt to stop the cooking process (be careful, it may sputter). Add the steamed cauliflower to the pan and toss gently to coat in the brown butter and almonds.", "structured": {"action": "TOSS", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Transfer to a serving platter. Garnish with black pepper and fresh parsley if using. Serve immediately while warm.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT0M", "total_time": "PT15M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Vegetarian", "Gluten-Free", "Keto", "Low-Carb", "Soy-Free", "Peanut-Free"], "not_suitable_for": ["Nut allergies (almonds)", "Dairy allergies (butter)"]}', '{"per_serving": {"calories": 207.98, "protein_g": 5.44, "carbohydrates_g": 10.75, "fat_g": 17.64, "saturated_fat_g": 8.18, "trans_fat_g": null, "monounsaturated_fat_g": 6.73, "polyunsaturated_fat_g": 1.74, "fiber_g": 4.62, "sugar_g": 3.66, "sodium_mg": 342.29, "cholesterol_mg": 32.25, "potassium_mg": 576.95, "calcium_mg": 69.49, "iron_mg": 1.16, "magnesium_mg": 52.96, "phosphorus_mg": 124.62, "zinc_mg": 0.78, "vitamin_a_mcg": 107.93, "vitamin_c_mg": 81.44, "vitamin_d_mcg": null, "vitamin_e_mg": 3.06, "vitamin_k_mcg": 47.15, "vitamin_b6_mg": 0.31, "vitamin_b12_mcg": 0.03, "thiamin_mg": 0.11, "riboflavin_mg": 0.22, "niacin_mg": 1.22, "folate_mcg": 100.17, "water_g": 157.13, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Butter may solidify; reheat gently.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; cauliflower will become mushy upon thawing.", "duration": null}, "reheating": "Warm gently in a skillet over low heat until butter melts and cauliflower is heated through.", "does_not_keep": false}', '[{"name": "Large pot with steamer basket", "required": true, "alternative": "Large pot with colander and lid"}, {"name": "Light-colored skillet", "required": true, "alternative": "Stainless steel frying pan (avoid non-stick dark pans to see butter color)"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Butter tastes acrid or burnt with black specks", "likely_cause": "The milk solids burned because the heat was too high or it was left on the stove too long", "prevention": "Remove pan from heat the moment you smell a nutty aroma and see golden brown color; residual heat continues cooking", "fix": "Cannot be fixed. Discard and start the butter sauce again (it is the primary flavor)"}]', '["Cut the cauliflower into uniform sizes to ensure even steaming.", "Beurre noisette (brown butter) moves from perfect to burnt in seconds. Have your lemon juice measured and ready near the stove to arrest the cooking immediately.", "If you want extra crunch, you can toast the almonds in a dry pan first, set them aside, and add them back to the finished brown butter, but cooking them in the butter infuses the fat with almond flavor.", "Ensure the cauliflower is well-drained after steaming so it doesn''t water down the rich butter sauce."]', '"This dish draws from the French technique ''\u00e0 l''Amandine'' (garnished with almonds), typically associated with trout or green beans. Applying this classic sauce to cauliflower elevates a humble brassica into an elegant side dish suitable for festive autumn tables."', 207.98);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('9509f824-7f93-4a3b-a06a-fcc31d307b34', 'Provençal Crown Roast of Lamb with Savory Vegetable Couscous', 'A magnificent festive centerpiece featuring two racks of lamb tied into a crown, crusted with a pungent, umami-rich paste of anchovies, capers, and fresh herbs. The center is filled with fluffy, vegetable-studded couscous that absorbs the roasting juices.', 'dinner', 'French', 'Advanced', '["french", "couscous", "crown roast of lamb", "dinner", "main course", "winter", "christmas"]', '[{"group_name": "Lamb & Marinade", "items": [{"name": "lamb racks", "quantity": 2, "unit": null, "preparation": "frenched, 7-8 ribs each", "notes": "approx. 1.5kg - 1.8kg total", "substitutions": [], "ingredient_id": "746d25dd-ae40-4199-9889-cb68dec89e9b", "nutrition_source": "USDA FoodData Central"}, {"name": "anchovy fillets in oil", "quantity": 6, "unit": null, "preparation": null, "notes": "approx. 25g", "substitutions": [], "ingredient_id": "be6d6563-a010-4028-863e-d518456aee98", "nutrition_source": "USDA FoodData Central"}, {"name": "capers", "quantity": 25, "unit": "g", "preparation": "drained", "notes": null, "substitutions": [], "ingredient_id": "e7301d2c-b906-4ef8-917e-787be0b25880", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "peeled", "notes": "approx. 20g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh rosemary", "quantity": 10, "unit": "g", "preparation": "leaves stripped", "notes": null, "substitutions": [], "ingredient_id": "fa90a3a7-86cd-40de-8f8c-0464231925c2", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 10, "unit": "g", "preparation": "leaves stripped", "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "9067636b-f9fe-4e66-9db9-5c750aca0d5d", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Couscous Stuffing", "items": [{"name": "couscous", "quantity": 200, "unit": "g", "preparation": "dry", "notes": null, "substitutions": [], "ingredient_id": "98ca56e9-68ee-4dd1-aab7-c26cca367098", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable or chicken stock", "quantity": 300, "unit": "ml", "preparation": "hot", "notes": null, "substitutions": [], "ingredient_id": "ba5595e6-e708-4989-9687-6837b15f9b83", "nutrition_source": "Aggregated Public Data"}, {"name": "shallots", "quantity": 2, "unit": null, "preparation": "finely diced", "notes": "approx. 50g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "carrot", "quantity": 1, "unit": null, "preparation": "brunoise (fine dice)", "notes": "approx. 80g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "zucchini", "quantity": 1, "unit": null, "preparation": "brunoise (fine dice)", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "d0aa0d47-cefe-4ece-a337-e656f79b74e9", "nutrition_source": "USDA FoodData Central"}, {"name": "dried apricots", "quantity": 40, "unit": "g", "preparation": "diced", "notes": null, "substitutions": [], "ingredient_id": "014c46d0-cd92-4004-9e0f-7ca8a59ff2f7", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Remove the lamb from the refrigerator 45 minutes before cooking to allow it to come to room temperature. Preheat the oven to 220\u00b0C (425\u00b0F).", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT45M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Prepare the rub: In a mortar and pestle (or food processor), crush the garlic, anchovies, capers, rosemary, and thyme into a coarse paste. Stir in the olive oil (60ml) and Dijon mustard until unified.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Shape the crown: Stand the two racks up with bones facing outward and curve them to meet, forming a circle. Tie securely with kitchen twine at the base and the middle. Wrap the exposed tips of the rib bones with small pieces of aluminum foil to prevent burning.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Rub the anchovy-herb paste generously over the meat, focusing on the interior of the crown and the fleshy eye of the chops. Place the crown in a roasting pan.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Roast the lamb at 220\u00b0C (425\u00b0F) for 10 minutes to sear the fat. Then, reduce oven temperature to 175\u00b0C (350\u00b0F) and continue roasting until an internal thermometer inserted into the thickest part of the meat reads 52\u00b0C (125\u00b0F) for medium-rare, approximately 25-35 minutes depending on size.", "structured": {"action": "ROAST", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": {"visual": "Golden brown crust", "tactile": "Thermometer reads 52\u00b0C"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "While lamb roasts, prepare the couscous: In a saucepan over medium heat, saut\u00e9 diced shallots and carrots in olive oil (30ml) for 5 minutes until softened. Add the zucchini and dried apricots, cooking for another 2 minutes.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT7M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Add the hot stock to the vegetable mixture and bring to a simmer. Remove from heat, stir in the dry couscous, cover tightly with a lid, and let stand for 5-10 minutes to steam.", "structured": {"action": "STEAM", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Once the lamb reaches target temperature, remove from oven. Transfer to a serving platter or board, tent loosely with foil, and let rest for at least 20 minutes. The internal temperature will rise to approx 54-57\u00b0C (130-135\u00b0F) during carryover cooking.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "assemble", "text": "Fluff the couscous with a fork and stir in the lemon juice and fresh herbs if desired. Spoon the hot couscous into the center cavity of the rested lamb crown for presentation. Carve by slicing between the ribs.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT20M", "total_time": "PT1H45M", "overnight_required": false, "yields": "1 crown roast (serves 6)", "yield_count": 6, "serving_size_g": 350}', '{"flags": ["Dairy-Free", "Egg-Free"], "not_suitable_for": ["Fish allergy sufferers"]}', '{"per_serving": {"calories": 458, "protein_g": 20.35, "carbohydrates_g": 56.63, "fat_g": 18.97, "saturated_fat_g": 2.4, "trans_fat_g": null, "monounsaturated_fat_g": 11.47, "polyunsaturated_fat_g": 2.75, "fiber_g": 14.81, "sugar_g": 5.28, "sodium_mg": 431.08, "cholesterol_mg": 2.5, "potassium_mg": 1557.47, "calcium_mg": 900.03, "iron_mg": 4.95, "magnesium_mg": 123.9, "phosphorus_mg": 298.4, "zinc_mg": 1.77, "vitamin_a_mcg": 1726.48, "vitamin_c_mg": 226.8, "vitamin_d_mcg": null, "vitamin_e_mg": 2.32, "vitamin_k_mcg": 11.94, "vitamin_b6_mg": 0.89, "vitamin_b12_mcg": 0.03, "thiamin_mg": 0.52, "riboflavin_mg": 1.28, "niacin_mg": 5.29, "folate_mcg": 99.03, "water_g": 266.13, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store meat and couscous separately if possible to maintain texture.", "duration": "P3D"}, "freezer": {"notes": "Lamb freezes well; couscous texture may degrade.", "duration": "P1M"}, "reheating": "Reheat lamb gently in a low oven (150\u00b0C) with a splash of stock to prevent drying.", "does_not_keep": false}', '[{"name": "Roasting pan with rack", "required": true, "alternative": null}, {"name": "Kitchen twine", "required": true, "alternative": "Ask butcher to tie the crown"}, {"name": "Mortar and pestle", "required": false, "alternative": "Food processor or chef''s knife"}, {"name": "Instant-read thermometer", "required": true, "alternative": null}, {"name": "Medium saucepan with lid", "required": true, "alternative": null}, {"name": "Aluminum foil", "required": true, "alternative": null}]', '[{"symptom": "Lamb is tough or dry", "likely_cause": "Overcooked beyond medium-rare or not rested properly", "prevention": "Use a digital thermometer and pull at 52\u00b0C (125\u00b0F); always rest meat for 20 minutes before cutting.", "fix": "Slice very thinly and serve with a warm jus or extra olive oil to add moisture."}]', '["Do not fear the anchovies. They will dissolve during roasting, leaving behind a deep savory umami layer rather than a fishy taste.", "Wrapping the bone tips with foil is non-negotiable for a professional presentation; otherwise, they will char and become brittle.", "Bringing the meat to room temperature before roasting ensures even cooking throughout the rack.", "The couscous is cooked separately to ensure it remains fluffy; cooking it inside the raw lamb often results in a greasy or gummy texture."]', '"The Crown Roast is a classic French butchery technique designed for visual spectacle, often reserved for Christmas or Easter feasts. The flavor profile here draws from Provence, utilizing the Mediterranean trinity of capers, anchovies, and garlic to cut through the rich fat of the lamb."', 458);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('96284805-fd7a-4c1d-8301-b0e9b0d0dd35', 'Golden Mushroom Pilaf with Sweet Pea Heart', 'A refined yet simple pilaf where earthy, caramelized mushrooms mingle with fluffy long-grain rice, visually anchored by a vibrant mound of sweet garden peas in the center. The butter-toasted rice provides a nutty backdrop to the savory fungi.', 'side dish', 'French', 'Easy', '["five ingredient", "long-grain rice", "mushroom", "dinner", "side dish", "vegetarian", "gluten-free"]', '[{"group_name": "Main Components", "items": [{"name": "long-grain white rice", "quantity": 250, "unit": "g", "preparation": "rinsed and drained", "notes": "Basmati or Jasmine recommended", "substitutions": [], "ingredient_id": "b671f3cd-cdec-4182-8911-82a06a22815a", "nutrition_source": "USDA FoodData Central"}, {"name": "cremini mushrooms", "quantity": 300, "unit": "g", "preparation": "sliced", "notes": "or white button mushrooms", "substitutions": [], "ingredient_id": "fdd23eb2-a71c-46d1-932b-295adf7d5ae5", "nutrition_source": "Aggregated Public Data"}, {"name": "frozen green peas", "quantity": 150, "unit": "g", "preparation": "thawed", "notes": null, "substitutions": [], "ingredient_id": "016d251b-46fd-4724-9e40-e8ae5a2a18bc", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable stock", "quantity": 500, "unit": "ml", "preparation": "hot", "notes": "or chicken stock if not vegetarian", "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": "divided", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pantry Staples", "items": [{"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly ground, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Rinse the rice under cold water until the water runs clear, then drain well. Clean and slice the mushrooms.", "structured": {"action": "MEASURE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Melt 30g of butter in the saucepan over medium-high heat. Add mushrooms and saut\u00e9 until they release their liquid and turn golden brown, about 5-7 minutes. Season with a pinch of salt and pepper.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT7M", "doneness_cues": {"visual": "Golden brown edges", "tactile": "Tender but not mushy"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the drained rice to the pan with the mushrooms. Stir constantly for 1-2 minutes to toast the grains and coat them in the fat.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Grains turn opaque/chalky white", "tactile": "Dry sound against pan"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour in the hot vegetable stock. Bring to a boil, then immediately reduce heat to low, cover with a tight-fitting lid, and simmer undisturbed for 15 minutes.", "structured": {"action": "SIMMER", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "While the rice cooks, gently warm the peas in a small separate pan with the remaining 15g of butter and a pinch of salt, just until heated through.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Bright green", "tactile": "Hot throughout"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove rice from heat and let stand covered for 5 minutes. Fluff with a fork.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "To serve, spoon the mushroom rice onto plates, creating a small well or nest in the center. Spoon the buttered peas into the center of the rice.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT15M", "total_time": "PT30M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 250}', '{"flags": ["Vegetarian", "Gluten-Free", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 364.04, "protein_g": 8.64, "carbohydrates_g": 60.47, "fat_g": 9.85, "saturated_fat_g": 5.88, "trans_fat_g": null, "monounsaturated_fat_g": 2.78, "polyunsaturated_fat_g": 0.5, "fiber_g": 2.98, "sugar_g": 4.31, "sodium_mg": 922.16, "cholesterol_mg": 24.19, "potassium_mg": 472.19, "calcium_mg": 48.55, "iron_mg": 1.53, "magnesium_mg": 26.53, "phosphorus_mg": 109.85, "zinc_mg": 0.95, "vitamin_a_mcg": 149.54, "vitamin_c_mg": 4.53, "vitamin_d_mcg": null, "vitamin_e_mg": 0.35, "vitamin_k_mcg": 10.26, "vitamin_b6_mg": 0.14, "vitamin_b12_mcg": 0.02, "thiamin_mg": 0.15, "riboflavin_mg": 0.07, "niacin_mg": 1.56, "folate_mcg": 27.51, "water_g": 38.92, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store peas separately if possible to maintain color vibrancy.", "duration": "P3D"}, "freezer": {"notes": "Rice texture may degrade slightly upon thawing.", "duration": "P1M"}, "reheating": "Microwave with a splash of water, or steam gently.", "does_not_keep": false}', '[{"name": "Heavy-bottomed saucepan with lid", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": null}]', '[{"symptom": "Rice is gummy or mushy", "likely_cause": "Rice was not rinsed enough to remove starch, or it was stirred during simmering", "prevention": "Rinse until clear and do not uncover or stir while simmering", "fix": "Spread onto a baking sheet to let steam escape and dry out slightly"}, {"symptom": "Mushrooms are pale and soggy", "likely_cause": "Pan was overcrowded or heat was too low", "prevention": "Use a wide pan and ensure fat is hot before adding mushrooms", "fix": "Cannot be fixed once mixed with rice; prevent in future"}]', '["Using hot stock instead of cold water helps the rice cook more evenly and prevents the temperature from dropping drastically when liquid is added.", "For a deeper flavor profile, allow the mushrooms to get quite dark brown; this caramelization mimics the savoriness of meat.", "The ''peas in the center'' presentation is a classic bistro style that adds a pop of color and sweetness to break up the rich, earthy rice.", "Ensure your peas are just barely cooked through to maintain their pop and bright green color against the brown rice mix."]', '"This dish draws inspiration from the European tradition of ''Riz Pilaf'', a method where grain is saut\u00e9ed in fat before liquid is added. The specific plating style with a central garnish is reminiscent of mid-20th-century continental plating, designed to highlight individual ingredients."', 364.04);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('96817adf-f58a-4a65-abe0-e0db58bd9944', 'Classic Fish Ceviche Tostadas', 'Vibrant, citrus-cured white fish piled high on freshly fried corn tortillas. The acidity of the lime ''cooks'' the delicate fish, while crunchy vegetables and creamy avocado provide a perfect textural balance against the crisp, golden shell.', 'appetizer', 'Mexican', 'Intermediate', '["mexican", "corn tortilla", "fish fillet", "tostada", "appetizer", "summer", "seafood", "raw"]', '[{"group_name": "Fish & Marinade", "items": [{"name": "white fish fillets (snapper, halibut, or sea bass)", "quantity": 500, "unit": "g", "preparation": "skinless, pin-boned, diced 1cm", "notes": "Must be sushi-grade or previously frozen for safety", "substitutions": [], "ingredient_id": "c922dd4c-7ddb-48bc-af35-c578838fcce8", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh lime juice", "quantity": 250, "unit": "ml", "preparation": null, "notes": "approx. 8-10 limes", "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Tostada Shells", "items": [{"name": "corn tortillas", "quantity": 8, "unit": null, "preparation": null, "notes": "approx. 200g total", "substitutions": [], "ingredient_id": "337d0b4a-e040-4e8f-906e-2e46fe1119e1", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable oil", "quantity": 500, "unit": "ml", "preparation": null, "notes": "for frying", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}, {"name": "fine salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste for dusting shells", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables & Finish", "items": [{"name": "red onion", "quantity": 100, "unit": "g", "preparation": "finely diced", "notes": null, "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "roma tomatoes", "quantity": 200, "unit": "g", "preparation": "seeded and diced", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh cilantro", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "serrano or jalape\u00f1o pepper", "quantity": 20, "unit": "g", "preparation": "minced, seeds removed for less heat", "notes": null, "substitutions": [], "ingredient_id": "e40b2f32-1599-4b72-a829-b858329933e8", "nutrition_source": "Aggregated Public Data"}, {"name": "avocado", "quantity": 2, "unit": null, "preparation": "sliced or cubed", "notes": "approx. 300g", "substitutions": [], "ingredient_id": "2f40a31e-80a0-4265-b6f3-99ed88ee4c24", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 2, "unit": "g", "preparation": null, "notes": "Mexican oregano preferred", "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the diced fish in a glass or ceramic bowl. Pour the lime juice over the fish, ensuring it is completely submerged. Stir in 10g of salt.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": ["Do not use aluminum bowls as the acid will react with the metal and create a metallic taste."]}, {"step_number": 2, "phase": "prep", "text": "Cover the bowl and refrigerate to cure. Allow the acid to denature the proteins until the fish turns opaque and firm, about 30 to 45 minutes.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT45M", "doneness_cues": {"visual": "Fish is opaque white throughout", "tactile": "Fish feels firm to the touch"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "While the fish cures, heat vegetable oil in a heavy pot to 180\u00b0C/350\u00b0F. Fry the corn tortillas one by one until golden and rigid, about 1-2 minutes per side.", "structured": {"action": "FRY", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Remove tortillas from the oil and drain on a wire rack or paper towels. Season immediately with fine salt while the oil is still glistening.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Once the fish is cured, drain off about half of the lime juice (or more, depending on desired wetness). Add the diced red onion, tomatoes, minced chili, chopped cilantro, and oregano. Mix gently to combine.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Taste the mixture and adjust salt if necessary. To serve, mound the ceviche onto the crispy tostada shells and top with avocado slices.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Assemble immediately before eating to prevent the tostada shell from becoming soggy."]}]', '{"active_time": "PT30M", "passive_time": "PT45M", "total_time": "PT1H15M", "overnight_required": false, "yields": "8 tostadas", "yield_count": 8, "serving_size_g": 180}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": ["Immunocompromised individuals (raw fish risk)", "Pregnant women (raw fish risk)"]}', '{"per_serving": {"calories": 179.21, "protein_g": 12.66, "carbohydrates_g": 17.13, "fat_g": 6.49, "saturated_fat_g": 0.88, "trans_fat_g": 0.08, "monounsaturated_fat_g": 3.72, "polyunsaturated_fat_g": 0.8, "fiber_g": 4.04, "sugar_g": 3.68, "sodium_mg": 791.55, "cholesterol_mg": 33.75, "potassium_mg": 511.16, "calcium_mg": 36.56, "iron_mg": 0.62, "magnesium_mg": 32.29, "phosphorus_mg": 177.75, "zinc_mg": 0.55, "vitamin_a_mcg": 54.37, "vitamin_c_mg": 20.04, "vitamin_d_mcg": 0.31, "vitamin_e_mg": 1.18, "vitamin_k_mcg": 9.73, "vitamin_b6_mg": 0.3, "vitamin_b12_mcg": 1.14, "thiamin_mg": 0.06, "riboflavin_mg": 0.1, "niacin_mg": 2.82, "folate_mcg": 43.97, "water_g": 119.12, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store ceviche and shells separately. Texture of fish degrades after 24 hours.", "duration": "P1D"}, "freezer": {"duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Glass or ceramic mixing bowl", "required": true, "alternative": "Stainless steel bowl (non-reactive)"}, {"name": "Heavy-bottomed pot or deep skillet", "required": true, "alternative": "Deep fryer"}, {"name": "Wire rack or paper towels", "required": true, "alternative": null}, {"name": "Citrus juicer", "required": false, "alternative": null}]', '[{"symptom": "Fish texture is mushy or chalky", "likely_cause": "Fish was marinated for too long", "prevention": "Limit marination time to 45 minutes maximum for small dice; strain juice if holding longer", "fix": "Drain immediately; texture cannot be fully restored but stopping acid helps"}, {"symptom": "Tostadas are chewy instead of crisp", "likely_cause": "Oil temperature was too low", "prevention": "Use a thermometer to ensure oil is at 180\u00b0C/350\u00b0F before frying", "fix": "Refry briefly at correct temperature if not yet topped"}]', '["The quality of ceviche depends entirely on the freshness of the fish. Use semi-firm white fish like snapper or halibut; avoid oily fish like mackerel.", "For food safety, freezing the fish at -20\u00b0C for 7 days prior to use is recommended to kill any potential parasites, even for ''fresh'' preparations.", "If the red onion flavor is too harsh, you can rinse the diced onion in cold water or soak it in the lime juice alongside the fish to mellow it out.", "Don''t throw away the leftover marinade (Leche de Tigre)! It is delicious mixed with a little clam juice or beer as a shooter."]', '"Ceviche origins are debated between Peru and other coastal Latin American nations, but the tostada presentation is distinctly Mexican. In coastal regions like Sinaloa and Baja, seafood is a staple, and tostadas provide an efficient, portable vessel for fresh catch cured in the abundant local limes."', 179.21);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('96d802b3-1853-489d-9554-0a67781bb3f5', 'Chicken Hariyali (Green Masala Chicken)', 'Succulent cubes of chicken breast simmered in a vibrant, herbaceous masala made from fresh cilantro, mint, and green chilies. The heat of the chilies is balanced by a creamy yogurt finish, creating a bright and peppery curry perfect for a weeknight dinner.', 'dinner', 'Indian', 'Intermediate', '["indian", "poultry", "chicken breast", "cilantro", "mint", "yogurt", "dinner", "weeknight", "main course", "gluten-free"]', '[{"group_name": "Green Masala Paste", "items": [{"name": "fresh cilantro", "quantity": 60, "unit": "g", "preparation": "washed and roughly chopped", "notes": "leaves and tender stems", "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh mint leaves", "quantity": 30, "unit": "g", "preparation": "picked leaves only", "notes": "discard woody stems", "substitutions": [], "ingredient_id": "17abecc0-a2a0-4478-8486-57b46e4305c9", "nutrition_source": "USDA FoodData Central"}, {"name": "green chilies", "quantity": 3, "unit": null, "preparation": "roughly chopped", "notes": "approx 15g; adjust for heat preference (Serrano or Thai Bird''s Eye)", "substitutions": [], "ingredient_id": "6cdb0615-378e-4bfa-b76d-f19bbd780e6c", "nutrition_source": "USDA FoodData Central"}, {"name": "ginger", "quantity": 15, "unit": "g", "preparation": "peeled and chopped", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "peeled", "notes": "approx 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": "helps preserve green color", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Main Curry", "items": [{"name": "chicken breast", "quantity": 600, "unit": "g", "preparation": "cut into 3cm cubes", "notes": null, "substitutions": [], "ingredient_id": "2b577d04-33ca-4919-938f-bfc8780a3a4b", "nutrition_source": "USDA FoodData Central"}, {"name": "ghee or vegetable oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "red onion", "quantity": 200, "unit": "g", "preparation": "finely diced", "notes": "about 2 medium onions", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "plain yogurt", "quantity": 150, "unit": "g", "preparation": "whisked until smooth", "notes": "full fat preferred for stability", "substitutions": [], "ingredient_id": "ba236210-8230-458e-a809-4c025a1bf020", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Spices", "items": [{"name": "ground coriander", "quantity": 8, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "turmeric powder", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "garam masala", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ffcea01-5f22-462b-94de-ad2a97049325", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 6, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine cilantro, mint, green chilies, ginger, garlic, and lemon juice in a blender. Blend into a smooth, vibrant green paste. Add a splash of water (15-30ml) only if necessary to get the blades moving.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Smooth, bright green puree", "tactile": null}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat ghee in a heavy-bottomed pot over medium heat. Add the finely diced onions and saut\u00e9 until they turn golden brown and translucent, taking care not to burn them.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT8M", "doneness_cues": {"visual": "Golden brown onions", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Pour the green masala paste into the pot with the onions. Cook for 3-4 minutes, stirring frequently, until the raw smell of the garlic and greens dissipates and the oil begins to separate slightly from the paste.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Oil separating at edges", "tactile": "Raw smell gone"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the cubed chicken breast, ground coriander, cumin, turmeric, and salt. Stir well to coat the chicken in the masala. Saut\u00e9 for 2-3 minutes to seal the meat.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Reduce heat to low-medium. Cover the pot and simmer gently until the chicken is cooked through. Chicken breast cooks quickly; ensure internal temperature reaches 74\u00b0C/165\u00b0F but check early to avoid dryness.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT10M", "doneness_cues": {"visual": "Chicken opaque throughout", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Turn the heat to the lowest setting (or remove from heat temporarily). Slowly whisk in the smooth yogurt to prevent curdling. Stir gently to combine.", "structured": {"action": "TEMPER", "temperature": {"celsius": 60, "fahrenheit": 140}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Stir in the garam masala. Simmer on very low heat for 1 more minute to meld flavors. Serve immediately.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT20M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 300}', '{"flags": ["Gluten-Free", "Nut-Free", "Low-Carb", "Egg-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 400.09, "protein_g": 34.62, "carbohydrates_g": 12.41, "fat_g": 23.66, "saturated_fat_g": 5.96, "trans_fat_g": 0.15, "monounsaturated_fat_g": 6.53, "polyunsaturated_fat_g": 3.11, "fiber_g": 3.43, "sugar_g": 4.43, "sodium_mg": 711.36, "cholesterol_mg": 100.88, "potassium_mg": 705.31, "calcium_mg": 122.95, "iron_mg": 3.72, "magnesium_mg": 67.48, "phosphorus_mg": 339.43, "zinc_mg": 1.94, "vitamin_a_mcg": 367.96, "vitamin_c_mg": 17.09, "vitamin_d_mcg": 0.64, "vitamin_e_mg": 0.55, "vitamin_k_mcg": 1, "vitamin_b6_mg": 0.94, "vitamin_b12_mcg": 0.65, "thiamin_mg": 0.15, "riboflavin_mg": 0.23, "niacin_mg": 15.22, "folate_mcg": 28.34, "water_g": 200, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. The green color may darken slightly upon reheating due to oxidation.", "duration": "P3D"}, "freezer": {"notes": "Yogurt-based sauces may separate slightly when thawed; reheat gently while whisking.", "duration": "P1M"}, "reheating": "Reheat gently on the stovetop over low heat to prevent the yogurt from curdling.", "does_not_keep": false}', '[{"name": "Blender or Food Processor", "required": true, "alternative": null}, {"name": "Heavy-bottomed pot or Dutch oven", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Yogurt has curdled/split in the sauce", "likely_cause": "The sauce was too hot or the yogurt was added too quickly", "prevention": "Whisk yogurt until smooth before adding and lower heat drastically (or remove pot from burner) before stirring it in", "fix": "Remove chicken, blend the sauce with an immersion blender to re-emulsify, then return chicken to pot"}]', '["To keep the green color vibrant, do not overcook the masala paste in step 3; cook just enough to remove the raw bite.", "Using chicken thighs instead of breast will result in a more tender dish that is more forgiving if simmered longer.", "The lemon juice in the paste acts as an antioxidant to help preserve the chlorophyll''s bright green color.", "For a richer texture, you can add 15g of soaked cashews or almonds to the blender in step 1."]', '"''Hariyali'' translates to ''greenery'' in Hindi. This dish originates from Punjab and North India, where winter greens and fresh herbs are abundant. It celebrates the fresh, herbaceous flavors of the harvest rather than the dried spice-heavy profiles of other curries."', 400.09);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('981f1b1e-a0b4-4b03-aad0-e640cdb33c11', 'Spiced Beef and Tofu Tacos with Lime Crema', 'A robust, protein-rich filling blending savory ground beef with crumbled firm tofu, heavily seasoned with earthy cumin and aromatic chili. Served in warm tortillas and finished with a tangy, cooling yogurt-sour cream sauce.', 'dinner', 'Tex-Mex', 'Easy', '["mexican", "ground beef", "tofu", "tortilla", "tex-mex", "fusion", "high-protein", "budget-friendly"]', '[{"group_name": "Filling", "items": [{"name": "lean ground beef", "quantity": 250, "unit": "g", "preparation": "chilled", "notes": null, "substitutions": [], "ingredient_id": "0258ca78-fe20-439b-94bc-30619460372b", "nutrition_source": "USDA FoodData Central"}, {"name": "firm tofu", "quantity": 250, "unit": "g", "preparation": "pressed and crumbled", "notes": "drain excess water before weighing", "substitutions": [], "ingredient_id": "35ac0b00-5c3a-40cc-bf3a-93c2e458798f", "nutrition_source": "USDA FoodData Central"}, {"name": "white onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx. 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 6, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "chili powder", "quantity": 8, "unit": "g", "preparation": null, "notes": "mild blend, not pure cayenne", "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "tomato paste", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "1a1bddc5-66c3-4f44-bb24-72b8ac828ca6", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Lime Crema", "items": [{"name": "greek yogurt", "quantity": 60, "unit": "g", "preparation": "plain, unsweetened", "notes": null, "substitutions": [], "ingredient_id": "61eae1a4-8517-4da8-8c29-34288cb7d8c7", "nutrition_source": "USDA FoodData Central"}, {"name": "sour cream", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "773a6e88-6185-4784-92a7-104b7c1b7688", "nutrition_source": "USDA FoodData Central"}, {"name": "lime juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Assembly", "items": [{"name": "flour tortillas", "quantity": 8, "unit": null, "preparation": null, "notes": "15cm / 6-inch diameter, approx 250g total", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "cilantro", "quantity": 15, "unit": "g", "preparation": "roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a small bowl, whisk together Greek yogurt, sour cream, and lime juice. Season with a pinch of salt and refrigerate until assembly.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Crumble the firm tofu into small pieces resembling the texture of ground beef. Pat dry with paper towels to remove surface moisture.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": {"visual": "Resembles coarse ground meat", "tactile": "Dry to the touch"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat a large skillet over medium-high heat. Add the ground beef and diced onion. Cook, breaking up the meat, until the beef is browned and onions are translucent, reaching an internal temperature of at least 71\u00b0C/160\u00b0F for the beef.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT6M", "doneness_cues": {"visual": "Beef is browned, no pink remains", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the crumbled tofu, minced garlic, cumin, chili powder, smoked paprika, tomato paste, and salt to the skillet. Stir well to coat.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Reduce heat to medium and cook for 5-7 minutes, stirring occasionally. This step allows the tofu to absorb the beef fat and spices while evaporating excess moisture.", "structured": {"action": "SIMMER", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT7M", "doneness_cues": {"visual": "Mixture looks unified and dry, not watery", "tactile": "Tofu is firm, not mushy"}}, "tips": ["If the pan looks too dry before the spices toast, add 15ml of water to help distribute the seasoning."]}, {"step_number": 6, "phase": "finish", "text": "Warm the tortillas in a dry skillet over medium-high heat for 15-30 seconds per side until pliable and slightly charred spots appear.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Divide the beef and tofu mixture among the warm tortillas. Top with the lime crema and fresh cilantro.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT10M", "total_time": "PT35M", "overnight_required": false, "yields": "8 tacos", "yield_count": 4, "serving_size_g": 220}', '{"flags": ["Nut-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 524.91, "protein_g": 32.03, "carbohydrates_g": 60.75, "fat_g": 17.38, "saturated_fat_g": 6.36, "trans_fat_g": 0.72, "monounsaturated_fat_g": 6.91, "polyunsaturated_fat_g": 1.96, "fiber_g": 4.59, "sugar_g": 3.41, "sodium_mg": 642.3, "cholesterol_mg": 61.63, "potassium_mg": 725.58, "calcium_mg": 237.36, "iron_mg": 5.44, "magnesium_mg": 72.26, "phosphorus_mg": 326.43, "zinc_mg": 5.11, "vitamin_a_mcg": 178.69, "vitamin_c_mg": 9.99, "vitamin_d_mcg": 0.05, "vitamin_e_mg": 1.3, "vitamin_k_mcg": 6.89, "vitamin_b6_mg": 0.49, "vitamin_b12_mcg": 1.8, "thiamin_mg": 0.19, "riboflavin_mg": 0.27, "niacin_mg": 4.36, "folate_mcg": 46.68, "water_g": 155.45, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store filling and sauce in separate airtight containers.", "duration": "P3D"}, "freezer": {"notes": "Freezing changes tofu texture slightly; filling becomes more spongy upon thawing.", "duration": "P2M"}, "reheating": "Reheat filling in a skillet over medium heat until steaming.", "does_not_keep": false}', '[{"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Filling texture is mushy or watery", "likely_cause": "Tofu released water that wasn''t cooked off", "prevention": "Press tofu firmly before crumbling and ensure the final cooking stage is long enough to evaporate liquid", "fix": "Increase heat to high and stir constantly for 2-3 minutes to drive off moisture"}]', '["Using a 50/50 mix of beef and tofu mimics the texture of pure beef while reducing saturated fat and cost. The tofu acts as a flavor sponge for the beef drippings.", "For the best texture, use ''Firm'' or ''Extra Firm'' tofu. Silken or soft tofu will disintegrate into a paste.", "Bloom the spices in the beef fat (saut\u00e9ing them briefly) before adding any liquid to maximize their aromatic impact.", "The lime crema provides necessary acidity to cut through the savory, earthy notes of the cumin and chili."]', '"This dish represents a modern style of Tex-Mex home cooking, often utilized to extend proteins economically or introduce plant-based ingredients into familiar formats. While the seasoning profile draws from Northern Mexican traditions (cumin, chili powder), the use of flour tortillas and ground beef is distinctively Texan-American."', 524.91);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('98a6e532-dbc6-4ca7-bf0b-eecbcda5ada2', 'Quick Creole Shrimp & Sausage Jambalaya', 'A streamlined, weeknight-friendly version of the Louisiana classic. This one-pot meal features plump shrimp, smoky andouille sausage, and the aromatic ''holy trinity'' of vegetables simmered in spicy tomato rice, delivering deep flavor in under an hour.', 'dinner', 'Creole', 'Easy', '["cajun", "creole", "southern", "shrimp", "dinner", "one-pot", "rice"]', '[{"group_name": "Proteins", "items": [{"name": "andouille sausage", "quantity": 250, "unit": "g", "preparation": "sliced into rounds", "notes": "substitute with smoked kielbasa if unavailable", "substitutions": [], "ingredient_id": "81514dd5-808c-4be0-bbb9-913164ad1db8", "nutrition_source": "Aggregated Public Data"}, {"name": "large shrimp", "quantity": 450, "unit": "g", "preparation": "peeled and deveined", "notes": "raw", "substitutions": [], "ingredient_id": "a6bf7ab3-9b88-4c5b-a2fa-966c40a0e5a7", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables (The Trinity)", "items": [{"name": "onion", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "green bell pepper", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "73526a0d-a2c7-4cac-8f5e-a77e5faf659d", "nutrition_source": "Aggregated Public Data"}, {"name": "celery stalks", "quantity": 2, "unit": null, "preparation": "diced", "notes": "approx 80g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pantry & Seasonings", "items": [{"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "long-grain white rice", "quantity": 300, "unit": "g", "preparation": null, "notes": "uncooked", "substitutions": [], "ingredient_id": "b671f3cd-cdec-4182-8911-82a06a22815a", "nutrition_source": "USDA FoodData Central"}, {"name": "chicken broth", "quantity": 700, "unit": "ml", "preparation": null, "notes": "low sodium preferred", "substitutions": [], "ingredient_id": "b7b1f4fd-8e57-472e-abae-d4f24d5b5c85", "nutrition_source": "Aggregated Public Data"}, {"name": "canned diced tomatoes", "quantity": 400, "unit": "g", "preparation": null, "notes": "undrained", "substitutions": [], "ingredient_id": "327bfc00-a1d9-4957-9fcd-159777b38445", "nutrition_source": "Aggregated Public Data"}, {"name": "cajun seasoning", "quantity": 15, "unit": "g", "preparation": null, "notes": "salt-free blends allow better control", "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "dried thyme", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "3b938244-d506-46b2-9027-21bed955bcc5", "nutrition_source": "USDA FoodData Central"}, {"name": "bay leaf", "quantity": 1, "unit": null, "preparation": null, "notes": "dried", "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}, {"name": "green onions", "quantity": 2, "unit": null, "preparation": "sliced", "notes": "for garnish", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Heat olive oil in a large Dutch oven over medium-high heat (approx 190\u00b0C/375\u00b0F). Add the sliced sausage and brown on both sides to render the fat.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT5M", "doneness_cues": {"visual": "Sausage is browned and crispy on edges", "tactile": null}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add the onion, bell pepper, and celery. Saut\u00e9 in the rendered fat until the vegetables soften and onions become translucent.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT5M", "doneness_cues": {"visual": "Onions are translucent", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Stir in the minced garlic, Cajun seasoning, and dried thyme. Cook for 1 minute until fragrant, being careful not to burn the garlic.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Spices are fragrant", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the uncooked rice. Stir constantly for about 1 minute to toast the grains and coat them in the seasoned oil.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour in the chicken broth and undrained diced tomatoes. Add the bay leaf. Scrape the bottom of the pot to release any browned bits (fond).", "structured": {"action": "DEGLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Bring the mixture to a boil, then reduce heat to low (simmer). Cover the pot tightly with a lid and cook for 15 minutes undisturbed.", "structured": {"action": "SIMMER", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Remove the lid quickly and arrange the raw shrimp on top of the rice mixture. Replace the lid immediately and continue to cook on low for another 5-7 minutes until shrimp are opaque and pink.", "structured": {"action": "STEAM", "temperature": null, "duration": "PT6M", "doneness_cues": {"visual": "Shrimp are opaque and pink", "tactile": "Shrimp are firm"}}, "tips": ["Ensure shrimp reaches an internal temperature of 63\u00b0C/145\u00b0F."]}, {"step_number": 8, "phase": "finish", "text": "Turn off the heat. Let the pot rest, covered, for 5 minutes. Remove the bay leaf, fluff the rice with a fork to mix the shrimp and sausage evenly, garnish with green onions, and serve.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT25M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Shellfish allergy"]}', '{"per_serving": {"calories": 1290.77, "protein_g": 45, "carbohydrates_g": 165.64, "fat_g": 79.3, "saturated_fat_g": 10.19, "trans_fat_g": null, "monounsaturated_fat_g": 5.88, "polyunsaturated_fat_g": 1.46, "fiber_g": 6.27, "sugar_g": 94.44, "sodium_mg": 25046.7, "cholesterol_mg": 181.13, "potassium_mg": 1142.02, "calcium_mg": 238.94, "iron_mg": 4.87, "magnesium_mg": 93.73, "phosphorus_mg": 449.39, "zinc_mg": 2.73, "vitamin_a_mcg": 138.8, "vitamin_c_mg": 48.45, "vitamin_d_mcg": null, "vitamin_e_mg": 2.86, "vitamin_k_mcg": 37.61, "vitamin_b6_mg": 0.39, "vitamin_b12_mcg": null, "thiamin_mg": 0.12, "riboflavin_mg": 0.12, "niacin_mg": 2.01, "folate_mcg": 30.21, "water_g": 192.3, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Shrimp texture may toughen upon reheating.", "duration": "P3D"}, "freezer": {"notes": "Rice texture may become slightly softer after freezing and thawing.", "duration": "P3M"}, "reheating": "Reheat gently on the stove with a splash of water or broth to rehydrate the rice.", "does_not_keep": false}', '[{"name": "Dutch oven or large deep skillet with lid", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": null}]', '[{"symptom": "Rice is still crunchy after cooking time", "likely_cause": "Heat was too high causing liquid to evaporate too fast, or lid was not tight enough", "prevention": "Keep heat on lowest setting during simmer and ensure lid seals well", "fix": "Add 30-50ml of hot water or broth, cover, and steam on very low heat for another 5 minutes"}, {"symptom": "Dish is too mushy or wet", "likely_cause": "Too much liquid used or rice was stirred excessively during cooking", "prevention": "Measure liquids precisely and do not stir rice once the lid goes on", "fix": "Remove lid and let it rest for 10 minutes; excess moisture will steam off and starches will set"}]', '["Resist the urge to uncover the pot during the main 15-minute simmer; steam is essential for cooking the rice evenly.", "If using a salt-heavy Cajun seasoning (like Tony Chachere''s), omit any extra salt and use low-sodium broth to avoid an overly salty dish.", "For a deeper flavor profile, you can sear the shrimp in the first step, remove them, and add them back at the very end just to warm through, though the steaming method in the recipe is faster and easier.", "The ''Holy Trinity'' (onions, bell peppers, celery) is the base of almost all Cajun and Creole cooking; ratio is usually 2:1:1 onion to pepper and celery."]', '"Jambalaya is a hallmark of Louisiana cuisine, heavily influenced by Spanish Paella and French Provencal cooking. This recipe is a ''Creole'' style jambalaya (red jambalaya) characterized by the use of tomatoes, which distinguishes it from the ''Cajun'' style (brown jambalaya) common in rural Louisiana which relies on the fond from browned meats for color."', 1290.77);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('98cd351b-5a03-4245-8503-26d3fe1329f7', 'Homemade Nonfat Yogurt', 'A clean, tangy, and remarkably creamy yogurt made completely fat-free. By precisely heating skim milk to denature its proteins, this recipe achieves a stable structure without the need for thickeners or gelatin.', 'breakfast', 'International', 'Intermediate', '["project", "milk", "plain yogurt", "fermentation", "healthy", "probiotic"]', '[{"group_name": "Base", "items": [{"name": "skim milk", "quantity": 1000, "unit": "ml", "preparation": "cold", "notes": "Ensure it is not ultra-pasteurized (UHT) as it may not set properly", "substitutions": [], "ingredient_id": "409272bf-eb3b-4031-a4a2-ec8c388291cb", "nutrition_source": "Aggregated Public Data"}, {"name": "plain yogurt with live active cultures", "quantity": 45, "unit": "g", "preparation": "room temperature", "notes": "Acts as the starter; approximately 3 tablespoons", "substitutions": [], "ingredient_id": "964528c1-9458-4782-98ec-6844ed14c47d", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pour the skim milk into a heavy-bottomed pot. Heat over medium heat, stirring frequently to prevent scorching on the bottom, until it reaches 82\u00b0C (180\u00b0F). This step is crucial to unravel the whey proteins for a thicker final texture.", "structured": {"action": "HEAT", "temperature": {"celsius": 82, "fahrenheit": 180}, "duration": "PT15M", "doneness_cues": {"visual": "Steam rising heavily, small bubbles at edge", "tactile": "Milk skins may form on surface"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Remove the pot from heat and let the milk cool down to 43\u00b0C-46\u00b0C (110\u00b0F-115\u00b0F). You can place the pot in an ice bath to speed this up, stirring constantly to cool evenly.", "structured": {"action": "COOL", "temperature": {"celsius": 43, "fahrenheit": 109}, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a small bowl, temper the yogurt starter by whisking it with about 100ml of the warm milk until smooth. Pour this mixture back into the main pot of milk and whisk gently to distribute the cultures evenly.", "structured": {"action": "TEMPER", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour the inoculated milk into your clean jars or incubation vessel. Cover and incubate at a steady 43\u00b0C (110\u00b0F) for 6 to 12 hours. Longer incubation results in a tangier, firmer yogurt; shorter times yield a milder flavor.", "structured": {"action": "FERMENT", "temperature": {"celsius": 43, "fahrenheit": 109}, "duration": "PT8H", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Once the yogurt has set (it should pull away slightly from the sides when tilted), transfer the jars to the refrigerator. Chill for at least 4 hours to halt fermentation and allow the structure to set completely before eating.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT4H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT8H", "total_time": "PT8H30M", "overnight_required": true, "yields": "1 liter", "yield_count": 5, "serving_size_g": 200}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Egg-Free", "Low-Sodium", "Low-Carb", "Sugar-Free"], "not_suitable_for": ["Lactose Intolerance", "Vegan"]}', '{"per_serving": {"calories": 76.65, "protein_g": 7.34, "carbohydrates_g": 10.84, "fat_g": 0.61, "saturated_fat_g": 0.07, "trans_fat_g": null, "monounsaturated_fat_g": 0.03, "polyunsaturated_fat_g": null, "fiber_g": 0, "sugar_g": 1.24, "sodium_mg": 92.94, "cholesterol_mg": 0.45, "potassium_mg": 319.71, "calcium_mg": 267.39, "iron_mg": 0.03, "magnesium_mg": 1.44, "phosphorus_mg": 192.15, "zinc_mg": 0.07, "vitamin_a_mcg": 307.08, "vitamin_c_mg": 0.07, "vitamin_d_mcg": null, "vitamin_e_mg": null, "vitamin_k_mcg": 0.01, "vitamin_b6_mg": null, "vitamin_b12_mcg": 0.05, "thiamin_mg": null, "riboflavin_mg": 0.02, "niacin_mg": 0.01, "folate_mcg": 0.99, "water_g": 7.11, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Keep tightly covered. Whey separation is normal; stir back in or drain.", "duration": "P2W"}, "freezer": {"notes": "Texture will change significantly upon thawing; best used for smoothies or baking.", "duration": "P1M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Heavy-bottomed pot", "required": true, "alternative": "Dutch oven"}, {"name": "Instant-read thermometer", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Incubation vessel", "required": true, "alternative": "Yogurt maker, oven with light on, or cooler with warm water"}, {"name": "Clean glass jars with lids", "required": true, "alternative": null}]', '[{"symptom": "Yogurt is runny or slimy", "likely_cause": "Incubation temperature was too low or milk was not heated to 82\u00b0C initially", "prevention": "Ensure milk reaches 82\u00b0C to denature proteins, and maintain steady 43\u00b0C during incubation", "fix": "Strain through cheesecloth to make Greek yogurt, or use in smoothies"}]', '["For Greek-style yogurt, line a colander with cheesecloth or a coffee filter and drain the finished yogurt in the fridge for 2-4 hours to remove whey.", "Save 3 tablespoons of your finished batch to use as the starter for your next batch. This can be repeated 3-4 times before the culture weakens.", "Do not add flavorings (vanilla, fruit, sweeteners) until after the yogurt has fully set and chilled. Adding them before fermentation can interfere with the bacterial growth.", "Sanitization is key. Ensure your pot, whisk, and jars are very clean (or sterilized) to prevent rogue bacteria from competing with your yogurt culture."]', '"Yogurt making is an ancient preservation technique originating in Mesopotamia around 5000 BC. While it is a staple across the Middle East, South Asia, and the Balkans, the specific isolation of nonfat milk for yogurt is a modern adaptation catering to lower-calorie dietary preferences without sacrificing the probiotic benefits of traditional fermentation."', 76.65);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('9930daf0-cd7c-41c5-a426-4731e279c1c3', 'Broiled Soy-Mustard Salmon with Asparagus & Herb Salad', 'Succulent salmon fillets glazed in a savory-sweet soy and Dijon emulsion, broiled alongside tender asparagus until caramelized. Finished with a vibrant, acidic herb salad to cut through the richness.', 'dinner', 'Fusion', 'Easy', '["seafood", "asparagus", "herbs", "salmon", "dinner", "weeknight", "main course", "spring"]', '[{"group_name": "Glaze", "items": [{"name": "dijon mustard", "quantity": 30, "unit": "g", "preparation": "smooth", "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "soy sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": "use tamari for gluten-free option", "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "honey", "quantity": 15, "unit": "g", "preparation": null, "notes": "or maple syrup", "substitutions": ["brown sugar"], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "toasted sesame oil", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a9a59164-d949-4acd-99da-689f0a32e2e7", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Salmon & Asparagus", "items": [{"name": "salmon fillets", "quantity": 600, "unit": "g", "preparation": "skin-on or off", "notes": "4 fillets, ~150g each", "substitutions": [], "ingredient_id": "6648fae7-4f63-45b3-b45d-19d927b57c2d", "nutrition_source": "Aggregated Public Data"}, {"name": "asparagus", "quantity": 450, "unit": "g", "preparation": "woody ends trimmed", "notes": "medium thickness preferred", "substitutions": [], "ingredient_id": "8a2a9426-3755-4553-953a-fd9cf42cef90", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": null, "unit": null, "preparation": null, "notes": "pinch for asparagus", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly ground", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Herb Salad", "items": [{"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "leaves picked", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh dill", "quantity": 10, "unit": "g", "preparation": "fronds picked", "notes": null, "substitutions": [], "ingredient_id": "4be2b047-475d-4c84-82d5-4883298c6121", "nutrition_source": "USDA FoodData Central"}, {"name": "scallions", "quantity": 2, "unit": null, "preparation": "thinly sliced", "notes": "approx 30g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "036c7254-3de5-4c6e-a2e7-366ad4d05077", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Adjust oven rack to the upper third position (approximately 15cm/6 inches from the heating element) and preheat the broiler to high.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 260, "fahrenheit": 500}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a small bowl, whisk together the Dijon mustard, soy sauce, honey, and sesame oil until emulsified into a smooth glaze.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Place asparagus on a rimmed baking sheet. Drizzle with 15ml olive oil, season with a pinch of salt and pepper, and toss to coat. Push asparagus to one side of the sheet to make room for the fish.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Pat salmon fillets dry with paper towels. Place them on the baking sheet alongside the asparagus. Brush the salmon generously with the soy-mustard glaze, coating the top and sides.", "structured": {"action": "GLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Broil for 6-9 minutes. The glaze should be bubbling and caramelized, the asparagus tender-crisp, and the salmon opaque. (Internal temperature for salmon should reach 52\u00b0C/125\u00b0F for medium or 60\u00b0C/140\u00b0F for well-done).", "structured": {"action": "BROIL", "temperature": {"celsius": 260, "fahrenheit": 500}, "duration": "PT8M", "doneness_cues": {"visual": "Glaze caramelized, salmon opaque", "tactile": "Salmon flakes easily with a fork"}}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "While salmon broils, toss the parsley, dill, and sliced scallions in a small bowl with lemon juice and extra virgin olive oil. Season lightly with salt.", "structured": {"action": "MIX", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove baking sheet from oven. Transfer salmon and asparagus to plates. Top the salmon immediately with a generous mound of the herb salad to serve.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT5M", "total_time": "PT20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 280}', '{"flags": ["Pescatarian", "Dairy-Free", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 502.89, "protein_g": 40.17, "carbohydrates_g": 16.4, "fat_g": 45.16, "saturated_fat_g": 0.75, "trans_fat_g": null, "monounsaturated_fat_g": 2.77, "polyunsaturated_fat_g": 0.47, "fiber_g": 3.1, "sugar_g": 6.96, "sodium_mg": 4153.51, "cholesterol_mg": null, "potassium_mg": 306.71, "calcium_mg": 465.15, "iron_mg": 21.01, "magnesium_mg": 471.23, "phosphorus_mg": 515.95, "zinc_mg": 2.06, "vitamin_a_mcg": 478.51, "vitamin_c_mg": 16.3, "vitamin_d_mcg": null, "vitamin_e_mg": 1.89, "vitamin_k_mcg": 126.49, "vitamin_b6_mg": 0.12, "vitamin_b12_mcg": null, "thiamin_mg": 0.17, "riboflavin_mg": 0.18, "niacin_mg": 1.24, "folate_mcg": 73.62, "water_g": 121.16, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Herb salad should be stored separately to prevent wilting.", "duration": "P2D"}, "freezer": {"notes": "Cooked salmon texture degrades significantly upon freezing; not recommended.", "duration": null}, "reheating": "Gently reheat salmon in a low oven or skillet. Asparagus is best eaten fresh or room temperature.", "does_not_keep": false}', '[{"name": "Rimmed baking sheet", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": "Small jar for dressing"}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Pastry brush", "required": true, "alternative": "Spoon"}]', '[{"symptom": "Glaze is burning before salmon is cooked", "likely_cause": "Rack position is too close to the broiler element or sugar content is carbonizing rapidly", "prevention": "Ensure rack is 15cm (6 inches) away from heat source", "fix": "Move the baking sheet to a lower rack or switch oven to ''Bake'' mode at 200\u00b0C/400\u00b0F to finish cooking gently"}]', '["Patting the salmon very dry before glazing ensures the sauce adheres properly and promotes better caramelization.", "If your asparagus spears are very pencil-thin, add them to the pan halfway through the salmon''s cooking time to prevent shriveling.", "The acid in the herb salad is crucial; it acts as a palate cleanser against the rich oils of the salmon and the salty depth of the soy sauce.", "For a crispier skin (if using skin-on), you can broil skin-side up for 2 minutes first, then flip and glaze the flesh side."]', '"This dish exemplifies modern fusion cuisine, marrying the Western technique of high-heat broiling with the classic East Asian flavor profile of soy and sesame, balanced by the French influence of Dijon mustard. It represents the efficiency of contemporary home cooking, prioritizing complex flavors with minimal active time."', 502.89);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('99da4ccc-9421-4b7f-8d84-946fccca2280', 'Korean Sticky Soy-Glazed Spareribs', 'Succulent pork spareribs slow-roasted until tender, then finished with a glossy, umami-rich glaze of soy sauce, ginger, garlic, and sesame oil. The result is a perfect balance of savory, sweet, and sticky textures that pulls away from the bone.', 'dinner', 'Korean', 'Intermediate', '["korean", "spare rib", "dinner", "weeknight", "asian", "glazed", "ginger", "sesame oil", "pork"]', '[{"group_name": "Ribs", "items": [{"name": "pork spareribs", "quantity": 1500, "unit": "g", "preparation": "whole rack", "notes": "about 1.5kg", "substitutions": [], "ingredient_id": "f8d49b90-c364-45c8-94d8-3c7bf354d88d", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "for initial seasoning", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Glaze", "items": [{"name": "soy sauce", "quantity": 80, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["tamari"], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "brown sugar", "quantity": 60, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "mirin", "quantity": 45, "unit": "ml", "preparation": null, "notes": "sweet rice wine", "substitutions": ["water with pinch of sugar"], "ingredient_id": "2a72c18d-8a1d-4259-8790-25d62f6fb5ba", "nutrition_source": "Aggregated Public Data"}, {"name": "gochujang", "quantity": 30, "unit": "g", "preparation": null, "notes": "korean chili paste", "substitutions": [], "ingredient_id": "01322d91-3959-4671-b230-25f5b14e132a", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 4, "unit": null, "preparation": "minced", "notes": "about 12-15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 15, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "sesame oil", "quantity": 15, "unit": "ml", "preparation": "toasted", "notes": null, "substitutions": [], "ingredient_id": "a9a59164-d949-4acd-99da-689f0a32e2e7", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Garnish", "items": [{"name": "scallions", "quantity": 2, "unit": null, "preparation": "thinly sliced", "notes": "green parts only", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "toasted sesame seeds", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36a7664a-f96c-44b9-9b6d-cdd5e9e54f55", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 160\u00b0C (325\u00b0F). Prepare a baking sheet by lining it with a large piece of heavy-duty aluminum foil tailored to fold over the ribs.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Flip the rib rack over to the bone side. Locate the thin, translucent membrane (silverskin) on the back. Use a paper towel to grip the edge and peel it off completely. This ensures tenderness and flavor penetration.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": {"visual": "Membrane removed cleanly", "tactile": null}}, "tips": ["If the membrane is slippery, use a paper towel for better grip."]}, {"step_number": 3, "phase": "cook", "text": "Season the ribs on both sides with the salt and black pepper. Place them meat-side up on the foil-lined baking sheet. Fold the foil sides up and crimp tightly to create a sealed packet.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Bake the sealed ribs in the preheated oven for 1 hour and 30 minutes, or until the meat is tender and has pulled back slightly from the bone tips.", "structured": {"action": "BAKE", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT1H30M", "doneness_cues": {"visual": "Meat pulled back from bone tips about 0.5-1cm", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "About 15 minutes before the ribs are done, combine soy sauce, brown sugar, mirin, gochujang, minced garlic, grated ginger, and sesame oil in a small saucepan over medium heat.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Simmer the sauce, stirring occasionally, until the sugar dissolves and the mixture thickens slightly into a glaze that coats the back of a spoon. Remove from heat.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Syrupy consistency, coats spoon", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove ribs from the oven. Carefully open the foil packet (watch for hot steam). Increase oven temperature to 220\u00b0C (425\u00b0F). Brush the ribs generously with half the glaze.", "structured": {"action": "GLAZE", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Return the ribs to the oven, uncovered. Bake for 10-15 minutes, basting with remaining glaze halfway through, until the sauce is bubbly, sticky, and slightly caramelized. Ensure pork reaches an internal temperature of at least 63\u00b0C (145\u00b0F), though 88\u00b0C+ (190\u00b0F+) yields better texture for ribs.", "structured": {"action": "ROAST", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": "Glaze is caramelized and bubbly", "tactile": "Tender"}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove from oven and let rest for 5 minutes. Slice between the bones, garnish with sliced scallions and toasted sesame seeds, and serve immediately.", "structured": {"action": "SERVE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT1H35M", "total_time": "PT2H", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 375}', '{"flags": ["Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 1208.22, "protein_g": 59.52, "carbohydrates_g": 30.64, "fat_g": 92.34, "saturated_fat_g": 28.26, "trans_fat_g": 0.83, "monounsaturated_fat_g": 32.03, "polyunsaturated_fat_g": 14.84, "fiber_g": 0.9, "sugar_g": 25.58, "sodium_mg": 4110, "cholesterol_mg": 300, "potassium_mg": 984.5, "calcium_mg": 95.74, "iron_mg": 3.95, "magnesium_mg": 70.59, "phosphorus_mg": 539.54, "zinc_mg": 9.47, "vitamin_a_mcg": 3.89, "vitamin_c_mg": 2.69, "vitamin_d_mcg": 8.63, "vitamin_e_mg": 1.45, "vitamin_k_mcg": 16.41, "vitamin_b6_mg": 2.2, "vitamin_b12_mcg": 1.43, "thiamin_mg": 1.21, "riboflavin_mg": 0.95, "niacin_mg": 17.59, "folate_mcg": 5.55, "water_g": 236.26, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Reheat gently to preserve glaze texture.", "duration": "P3D"}, "freezer": {"notes": "Freeze without garnish. Thaw overnight before reheating.", "duration": "P2M"}, "reheating": "Reheat in a 150\u00b0C/300\u00b0F oven loosely covered with foil for 15-20 minutes.", "does_not_keep": false}', '[{"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Aluminum foil", "required": true, "alternative": null}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Pastry brush", "required": true, "alternative": "Spoon"}, {"name": "Whisk", "required": true, "alternative": null}]', '[{"symptom": "Meat is tough and not pulling away from bone", "likely_cause": "Undercooked during the covered baking phase", "prevention": "Ensure the foil packet is tightly sealed to steam the meat; extend baking time by 15-20 minutes", "fix": "Reseal foil and bake longer before adding glaze"}]', '["Removing the silverskin membrane is non-negotiable for tender ribs; it acts as a barrier to seasoning and becomes chewy when cooked.", "For a deeper color and smokier flavor, you can finish the glazed ribs under a broiler for 2-3 minutes, but watch closely as the sugar burns instantly.", "If you have an Asian pear, grating a small amount (about 30g) into the marinade/glaze adds an enzyme that helps tenderize the meat naturally.", "Serve with steamed white rice and kimchi to cut through the richness of the pork fat."]', '"This recipe draws inspiration from Korean ''Dwaeji Galbi'' (pork ribs), typically marinated in a soy-fruit base and grilled. Here, we utilize a simplified oven-braise technique suitable for home kitchens that mimics the tenderness of traditional slow-cooking while maintaining the signature balance of salty, sweet, and nutty sesame flavors integral to Korean BBQ culture."', 1208.22);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('9a3abe62-4646-40a0-bae7-35155ddeae52', 'Lemon-Herbed Crawfish and Artichoke Farfalle', 'Succulent Louisiana crawfish tails and tender artichoke hearts tossed with farfalle in a bright, zesty lemon-garlic cream sauce. A perfect marriage of Cajun sweetness and Mediterranean acidity.', 'dinner', 'Creole-Italian Fusion', 'Intermediate', '["pastas", "crawfish", "farfalle", "pasta", "dinner", "main course", "seafood", "fusion"]', '[{"group_name": "Pasta", "items": [{"name": "farfalle pasta", "quantity": 350, "unit": "g", "preparation": "dry", "notes": null, "substitutions": [], "ingredient_id": "320e9771-354c-4aac-a6d8-68d26af424ad", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 4000, "unit": "ml", "preparation": null, "notes": "for boiling", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 30, "unit": "g", "preparation": null, "notes": "for pasta water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sauce & Proteins", "items": [{"name": "crawfish tails", "quantity": 300, "unit": "g", "preparation": "cooked and peeled", "notes": "thawed if frozen", "substitutions": [], "ingredient_id": "8ad5483b-a721-44bd-afe6-dd486309c49f", "nutrition_source": "Aggregated Public Data"}, {"name": "artichoke hearts", "quantity": 250, "unit": "g", "preparation": "canned or jarred", "notes": "drained and halved", "substitutions": [], "ingredient_id": "4cb78e4f-64da-4303-a041-a9aef2ad7d5b", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 50g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 120, "unit": "ml", "preparation": null, "notes": "Sauvignon Blanc or Pinot Grigio", "substitutions": ["chicken stock", "vegetable broth"], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 120, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": "zested and juiced", "notes": "approx 45ml juice", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh chives", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}, {"name": "red pepper flakes", "quantity": 2, "unit": "g", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}, {"name": "parmesan cheese", "quantity": 30, "unit": "g", "preparation": "grated", "notes": "optional", "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Bring a large stockpot of salted water to a rolling boil.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add the farfalle to the boiling water and cook for 1 minute less than the package instructions indicate for al dente. Reserve 100ml of pasta cooking water before draining.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "While pasta cooks, melt the butter in a large skillet over medium heat. Saut\u00e9 the minced shallot until translucent, then add the garlic and red pepper flakes, cooking for another 30 seconds until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Increase heat to medium-high and deglaze the pan with white wine. Simmer vigorously until the liquid reduces by half.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Reduce heat to medium-low. Stir in the heavy cream and lemon zest. Let it bubble gently for 2 minutes until slightly thickened.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Sauce coats the back of a spoon", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Add the artichoke hearts and cooked crawfish tails to the sauce. Cook for 1-2 minutes just to warm them through. Do not boil vigorously or the crawfish will become rubbery.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT2M", "doneness_cues": null}, "tips": ["If using raw crawfish, cook until opaque (internal temp 63\u00b0C/145\u00b0F) before adding artichokes."]}, {"step_number": 7, "phase": "finish", "text": "Toss the drained pasta into the skillet. Add the lemon juice and half the reserved pasta water. Stir vigorously over low heat until the sauce clings to the pasta. Add more pasta water if the sauce looks too thick.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from heat. Stir in the chopped parsley and chives. Season with salt and black pepper to taste.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT10M", "total_time": "PT35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Pescatarian", "Egg-Free", "Soy-Free"], "not_suitable_for": ["Shellfish allergy sufferers", "Lactose intolerant (contains cream/butter)"]}', '{"per_serving": {"calories": 678.84, "protein_g": 29.96, "carbohydrates_g": 74.23, "fat_g": 24.24, "saturated_fat_g": 13.73, "trans_fat_g": 0.37, "monounsaturated_fat_g": 5.96, "polyunsaturated_fat_g": 0.93, "fiber_g": 8.02, "sugar_g": 6.67, "sodium_mg": 3327.79, "cholesterol_mg": 63.19, "potassium_mg": 532.54, "calcium_mg": 253.83, "iron_mg": 3.23, "magnesium_mg": 49.4, "phosphorus_mg": 296.38, "zinc_mg": 1.82, "vitamin_a_mcg": 258.52, "vitamin_c_mg": 27.94, "vitamin_d_mcg": 0.52, "vitamin_e_mg": 0.77, "vitamin_k_mcg": 63.94, "vitamin_b6_mg": 0.14, "vitamin_b12_mcg": 0.16, "thiamin_mg": 0.04, "riboflavin_mg": 0.11, "niacin_mg": 0.21, "folate_mcg": 14.99, "water_g": 1055.81, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Seafood pasta is best eaten fresh; reheat gently to avoid rubbery texture.", "duration": "P2D"}, "freezer": {"notes": "Cream sauces and cooked pasta do not freeze well; texture will separate and become mushy.", "duration": null}, "reheating": "Reheat in a skillet over low heat with a splash of water or milk to re-emulsify the sauce.", "does_not_keep": false}', '[{"name": "Large stockpot", "required": true, "alternative": null}, {"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Microplane or zester", "required": true, "alternative": null}]', '[{"symptom": "Crawfish is rubbery or tough", "likely_cause": "Overcooking; most packaged crawfish tails are already cooked", "prevention": "Add crawfish at the very end only to warm them through", "fix": "Cannot be fixed, but chopping them smaller can mask the texture"}, {"symptom": "Sauce is broken or oily", "likely_cause": "Heat was too high after adding cream, or acid (lemon) curdled the dairy", "prevention": "Lower heat before adding cream; add lemon juice at the very end", "fix": "Whisk in a tablespoon of cold water or additional heavy cream off the heat"}]', '["Look for Louisiana crawfish tails for the best flavor; imported tails often lack sweetness.", "The shape of farfalle (bowties) is excellent for catching the creamy sauce and small bits of crawfish in the folds.", "If you want a true Cajun kick, substitute the salt and pepper for a dedicated Cajun seasoning blend, but be mindful of the salt content.", "Marinated artichoke hearts add a nice tang, but ensure they are drained well so the oil doesn''t make the dish greasy. Rinse them if you prefer a cleaner flavor."]', '"This dish represents a modern intersection of Creole ingredients and Italian technique. While crawfish \u00e9touff\u00e9e is the standard bearer for Louisiana crayfish, pasta variations became popular in the late 20th century as Italian-American influences permeated the Gulf Coast culinary scene."', 678.84);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('9bd0d407-d0b2-4fbf-a681-4df6fd217341', 'Spiced Almond & Oat Raisin Cookies', 'These rustic one-bowl cookies deliver the holy grail of textures: chewy centers with distinctively crisp, caramelized edges. Warm spices like cinnamon and nutmeg complement the nuttiness of almond flour, while plump raisins provide bursts of natural sweetness.', 'baked good', 'American', 'Easy', '["american", "almond flour", "almond milk", "christmas cookie", "cookie", "freezer friendly", "kid-friendly", "one bowl", "plan-ahead", "raisin", "rolled oat", "easy", "dessert", "dairy-free", "gluten-free", "vegan", "vegetarian"]', '[{"group_name": "Wet Ingredients", "items": [{"name": "coconut oil", "quantity": 60, "unit": "ml", "preparation": "melted and cooled", "notes": "can substitute melted vegan butter", "substitutions": [], "ingredient_id": "bfc74b81-e1e0-4607-9eec-8d0eff76d78c", "nutrition_source": "USDA FoodData Central"}, {"name": "light brown sugar", "quantity": 100, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "almond milk", "quantity": 45, "unit": "ml", "preparation": "room temperature", "notes": "unsweetened preferred", "substitutions": [], "ingredient_id": "4fbaf827-a17d-4f7a-9739-5e9ca5c6e761", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dry Ingredients & Mix-ins", "items": [{"name": "almond flour", "quantity": 100, "unit": "g", "preparation": "blanched", "notes": "superfine grind works best", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "rolled oats", "quantity": 135, "unit": "g", "preparation": null, "notes": "ensure certified gluten-free if required", "substitutions": [], "ingredient_id": "11381622-c748-499c-b9c5-58fcb9d70fd3", "nutrition_source": "Aggregated Public Data"}, {"name": "ground cinnamon", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "ground nutmeg", "quantity": 1, "unit": "g", "preparation": null, "notes": "approx 1/4 tsp", "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 1/2 tsp", "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 1/2 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "raisins", "quantity": 80, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "4e6af4a3-1bf3-47bd-9761-7bb6a77323dd", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 175\u00b0C (350\u00b0F) and line a large baking sheet with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, whisk together the melted coconut oil, brown sugar, almond milk, and vanilla extract until the mixture looks like wet sand.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Add the almond flour, rolled oats, cinnamon, nutmeg, baking soda, and salt to the bowl. Stir with a spatula until no dry streaks remain.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Fold in the raisins until evenly distributed throughout the dough.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Let the dough rest in the refrigerator for 30 minutes. This hydrates the oats and prevents the cookies from spreading too thin.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Scoop the dough (about 2 tablespoons per cookie) onto the prepared baking sheet, spacing them 5cm apart. Flatten each ball slightly with the palm of your hand.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Bake for 10-12 minutes. The edges should be golden brown and crisp, but the centers will still look slightly soft and underdone.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT12M", "doneness_cues": {"visual": "Golden brown edges", "tactile": "Centers soft to touch"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Allow the cookies to cool completely on the baking sheet. They are very fragile while hot and will firm up as they cool.", "structured": {"action": "COOL", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": ["Do not move them to a wire rack until they have cooled for at least 15 minutes."]}]', '{"active_time": "PT15M", "passive_time": "PT45M", "total_time": "PT1H", "overnight_required": false, "yields": "16 cookies", "yield_count": 16, "serving_size_g": 45}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Soy-Free", "Peanut-Free"], "not_suitable_for": ["Tree Nut allergies (Almond)"]}', '{"per_serving": {"calories": 128.69, "protein_g": 1.91, "carbohydrates_g": 20.85, "fat_g": 4.45, "saturated_fat_g": 3.21, "trans_fat_g": 0.09, "monounsaturated_fat_g": 0.25, "polyunsaturated_fat_g": 0.1, "fiber_g": 1.45, "sugar_g": 6.23, "sodium_mg": 127.96, "cholesterol_mg": null, "potassium_mg": 89.91, "calcium_mg": 19.61, "iron_mg": 0.64, "magnesium_mg": 15.31, "phosphorus_mg": 45.83, "zinc_mg": 0.37, "vitamin_a_mcg": 2.55, "vitamin_c_mg": 0.28, "vitamin_d_mcg": null, "vitamin_e_mg": 0.01, "vitamin_k_mcg": 0.08, "vitamin_b6_mg": 0.01, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.01, "niacin_mg": 0.14, "folate_mcg": 1.89, "water_g": 1.84, "alcohol_g": 0.11, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container to maintain chewiness.", "duration": "P1W"}, "freezer": {"notes": "Freeze raw dough balls or baked cookies. Thaw baked cookies at room temperature.", "duration": "P3M"}, "reheating": "Warm in a 150\u00b0C/300\u00b0F oven for 3 minutes to crisp up edges.", "does_not_keep": false}', '[{"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}, {"name": "Cookie scoop", "required": false, "alternative": "Two tablespoons"}]', '[{"symptom": "Cookies spread into a flat puddle", "likely_cause": "Dough was too warm or oil was too hot when mixing", "prevention": "Ensure dough is chilled thoroughly before baking", "fix": "Chill the remaining dough for an extra 15-30 minutes before baking the next batch"}]', '["If your raisins are very dry, soak them in warm water for 10 minutes and pat them thoroughly dry before adding to the dough to prevent them from becoming hard bullets.", "For perfectly round cookies, use a round cutter slightly larger than the cookie to scoot/swirl the hot cookies into shape immediately after taking them out of the oven.", "Almond flour burns faster than wheat flour. Keep an eye on the oven during the last 2 minutes of baking.", "Do not skip the salt; it is essential to cut through the sweetness of the raisins and brown sugar."]', '"The oatmeal raisin cookie is an American comfort food staple, evolving in the late 19th century when oats transitioned from animal feed to a breakfast health food. This version adapts the classic Fannie Farmer style to modern plant-based dietary needs without sacrificing the nostalgic texture."', 128.69);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('9c29a3ac-5842-4a69-b288-b6615af38da1', 'Rustic Bramley Apple & Blackberry Galette', 'A celebration of British autumn produce featuring tart Bramley apples and hedgerow blackberries encased in flaky, buttery homemade rough puff pastry. The sharp fruit filling breaks down into a luscious compote, balanced by the crisp pastry and a cloud of vanilla-flecked Chantilly cream.', 'dessert', 'British', 'Intermediate', '["tart", "apple", "blackberry", "puff pastry", "cream", "dessert", "british", "galette", "autumn"]', '[{"group_name": "Rough Puff Pastry", "items": [{"name": "plain flour", "quantity": 250, "unit": "g", "preparation": "chilled", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 250, "unit": "g", "preparation": "cold, cut into 1cm cubes", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "ice water", "quantity": 130, "unit": "ml", "preparation": null, "notes": "approximate, keep very cold", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Fruit Filling", "items": [{"name": "bramley apples", "quantity": 3, "unit": null, "preparation": "peeled, cored, and sliced 5mm thick", "notes": "approx 600g prepared weight", "substitutions": [], "ingredient_id": "9985672b-aa9f-4125-8a32-62d520c99d6f", "nutrition_source": "USDA FoodData Central"}, {"name": "blackberries", "quantity": 150, "unit": "g", "preparation": "fresh or frozen", "notes": null, "substitutions": [], "ingredient_id": "ce7c9c9b-08d3-4496-8b7f-e45c2ee8d6bf", "nutrition_source": "USDA FoodData Central"}, {"name": "caster sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 20, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Assembly", "items": [{"name": "egg", "quantity": 1, "unit": null, "preparation": "beaten", "notes": "for egg wash", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "demerara sugar", "quantity": 15, "unit": "g", "preparation": null, "notes": "for sprinkling", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Chantilly Cream", "items": [{"name": "double cream", "quantity": 300, "unit": "ml", "preparation": "chilled", "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "icing sugar", "quantity": 30, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla bean paste", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "90237166-b129-4858-8c9c-2f8a7ab9a301", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a large bowl, mix the flour and salt. Add the cold cubed butter and toss to coat in flour. Using your fingertips, rub the butter loosely into the flour, leaving large chunks of butter visible (this is crucial for flaky layers).", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Make a well in the center and pour in about 100ml of the ice water. Mix gently with a knife or hand until a rough dough forms, adding the remaining water only if dry flour remains. Do not overwork.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Shape the dough into a rough rectangle, wrap in plastic, and rest in the refrigerator for 20 minutes.", "structured": {"action": "REST", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "On a floured surface, roll the dough into a rectangle (approx 20cm x 40cm). Fold the top third down and the bottom third up (like a letter). Rotate the dough 90 degrees. Roll and fold again. Wrap and chill for another 30 minutes.", "structured": {"action": "LAMINATE", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Repeat the rolling and folding process two more times. Wrap and chill for a final 30 minutes before use.", "structured": {"action": "LAMINATE", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Preheat your oven to 200\u00b0C (400\u00b0F). Line a large baking sheet with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "prep", "text": "Toss the sliced Bramley apples and blackberries with the caster sugar, cornstarch, and lemon juice until evenly coated.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Roll the chilled pastry into a large rough circle, approximately 35cm in diameter and 3-4mm thick. Transfer to the prepared baking sheet.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "assemble", "text": "Pile the fruit filling into the center of the pastry, leaving a 5cm border. Fold the edges of the pastry up and over the fruit, pleating as you go, leaving the center exposed. Brush the pastry edges with beaten egg and sprinkle with demerara sugar.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "cook", "text": "Bake for 35-40 minutes until the pastry is deeply golden brown and the fruit filling is bubbling.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT40M", "doneness_cues": {"visual": "Pastry is deep golden brown", "tactile": "Pastry is crisp to the touch"}}, "tips": []}, {"step_number": 11, "phase": "finish", "text": "While the tart cools slightly, whisk the double cream, sifted icing sugar, and vanilla bean paste until soft peaks form.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": {"visual": "Soft peaks that hold their shape", "tactile": null}}, "tips": []}, {"step_number": 12, "phase": "finish", "text": "Slice the warm tart and serve immediately with a generous dollop of Chantilly cream.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT50M", "passive_time": "PT2H15M", "total_time": "PT3H5M", "overnight_required": false, "yields": "8 slices", "yield_count": 8, "serving_size_g": 185}', '{"flags": ["Vegetarian", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 599, "protein_g": 5.57, "carbohydrates_g": 57.69, "fat_g": 39.83, "saturated_fat_g": 24.62, "trans_fat_g": 0.47, "monounsaturated_fat_g": 10.93, "polyunsaturated_fat_g": 1.83, "fiber_g": 3.66, "sugar_g": 27.99, "sodium_mg": 216.2, "cholesterol_mg": 125.84, "potassium_mg": 195.07, "calcium_mg": 50.08, "iron_mg": 0.72, "magnesium_mg": 18.47, "phosphorus_mg": 84.46, "zinc_mg": 0.53, "vitamin_a_mcg": 379.19, "vitamin_c_mg": 8.1, "vitamin_d_mcg": 0.69, "vitamin_e_mg": 1.49, "vitamin_k_mcg": 8.86, "vitamin_b6_mg": 0.07, "vitamin_b12_mcg": 0.15, "thiamin_mg": 0.07, "riboflavin_mg": 0.15, "niacin_mg": 0.62, "folate_mcg": 19.81, "water_g": 132.11, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Pastry will lose crispness; reheat in oven to refresh.", "duration": "P2D"}, "freezer": {"notes": "Freeze unbaked assembled tart for best results.", "duration": "P1M"}, "reheating": "Reheat in a 180\u00b0C oven for 10-15 minutes to re-crisp the pastry.", "does_not_keep": false}', '[{"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Rolling pin", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Pastry brush", "required": true, "alternative": null}, {"name": "Stand mixer or hand whisk", "required": true, "alternative": "Balloon whisk"}]', '[{"symptom": "Pastry is tough or shrinking excessively", "likely_cause": "The dough was overworked or became too warm during lamination", "prevention": "Keep ingredients cold and rest dough sufficiently between folds to relax gluten", "fix": "Cannot be fixed once baked, but serve warm with extra cream to mask texture"}, {"symptom": "Filling is too runny", "likely_cause": "Bramley apples release significant moisture; insufficient cornstarch used", "prevention": "Ensure cornstarch coats the fruit well before assembling", "fix": "Let the tart cool completely; the pectin and starch will set the filling further"}]', '["Bramley apples are incredibly tart and fluff up when cooked. Do not substitute with eating apples like Granny Smith if you want the traditional British texture contrast.", "Keep your butter visible in the dough! If you rub it in completely like a crumble, you will lose the flaky layers.", "For the cleanest pastry lift, use a chilled metal baking sheet if available, or preheat the baking sheet inside the oven and slide the parchment paper onto it.", "Cornstarch is essential here because blackberries and Bramleys both release a lot of juice; without it, you will have a soggy bottom.", "The resting times are non-negotiable for rough puff pastry to prevent shrinkage during baking."]', '"This rustic galette highlights the Bramley apple, a cultivar unique to the UK and prized for its high acidity and fluffy cooked texture. Paired with wild blackberries, it represents the quintessential British autumn harvest, encased in a simplified ''rough'' puff pastry that mimics the layers of French feuilletage without the lengthy process."', 599);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('9d182437-6def-4b8d-b4a6-eec4a4d181c2', 'Rustic Sweet Potato and Kale Soup with Ditalini', 'A nourishing, one-pot winter warmer balancing the earthiness of lacinato kale with the natural sweetness of orange-fleshed potatoes. The starch from the pasta lightly thickens the broth, creating a comforting texture perfect for a light meal or hearty starter.', 'soup', 'Italian', 'Easy', '["one pot", "five ingredient", "great leftovers", "kale", "pasta", "soup", "sweet potato", "appetizer", "winter"]', '[{"group_name": "The Five Core Ingredients", "items": [{"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "sweet potatoes", "quantity": 300, "unit": "g", "preparation": "peeled and diced into 1.5cm cubes", "notes": null, "substitutions": [], "ingredient_id": "579039f4-fa1e-4c91-8355-9dd037d188cd", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable broth", "quantity": 1200, "unit": "ml", "preparation": "low-sodium preferred", "notes": null, "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "ditalini pasta", "quantity": 120, "unit": "g", "preparation": "dry", "notes": "or other small soup pasta like tubetti", "substitutions": ["orecchiette", "orzo", "small shells"], "ingredient_id": "52cdfe63-4362-4d80-9ed0-9fc7041f2721", "nutrition_source": "USDA FoodData Central"}, {"name": "lacinato kale", "quantity": 150, "unit": "g", "preparation": "stemmed and chopped", "notes": "also known as dinosaur or Tuscan kale", "substitutions": ["curly kale", "swiss chard"], "ingredient_id": "bb6a90eb-f157-455a-b438-d2333c784c60", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pantry Staples (To Taste)", "items": [{"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": "extra virgin", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}, {"name": "red pepper flakes", "quantity": null, "unit": null, "preparation": null, "notes": "optional for heat", "substitutions": [], "ingredient_id": "1f6019e9-c5ca-4eda-a3f9-e8df6535e5eb", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare your vegetables: peel and dice the sweet potatoes into 1.5cm cubes to ensure even cooking. Strip the kale leaves from tough stems and chop coarsely. Dice the onion.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat olive oil in a large pot over medium heat. Add the diced onion and a pinch of salt. Saut\u00e9 for 5-7 minutes until the onion is translucent and soft, but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": "PT7M", "doneness_cues": {"visual": "Translucent onion", "tactile": "Soft texture"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the diced sweet potatoes and vegetable broth to the pot. Increase heat to high to bring the liquid to a boil.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Once boiling, reduce heat to a simmer (approx. 85\u00b0C/185\u00b0F). Cook for 5 minutes. The potatoes should be slightly softened but still firm in the center.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Stir in the ditalini pasta. Simmer for about 8-10 minutes (refer to package instructions for al dente timing). The starch from the pasta will begin to body to the soup.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "When the pasta is 2 minutes away from being done, stir in the chopped kale. Cook until the kale is wilted and tender vibrant green.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Kale is bright green and wilted", "tactile": "Pasta is al dente"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from heat. Taste and season with salt, fresh black pepper, and optional red pepper flakes. Serve immediately.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT20M", "total_time": "PT35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Vegetarian", "Vegan", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 220.72, "protein_g": 5.3, "carbohydrates_g": 32.36, "fat_g": 8.66, "saturated_fat_g": 1.36, "trans_fat_g": null, "monounsaturated_fat_g": 5.65, "polyunsaturated_fat_g": 1.03, "fiber_g": 3.82, "sugar_g": 9.71, "sodium_mg": 2007.48, "cholesterol_mg": 12.3, "potassium_mg": 619.92, "calcium_mg": 109.98, "iron_mg": 2.05, "magnesium_mg": 46.19, "phosphorus_mg": 52.15, "zinc_mg": 0.57, "vitamin_a_mcg": 4406.98, "vitamin_c_mg": 21.71, "vitamin_d_mcg": null, "vitamin_e_mg": 1.31, "vitamin_k_mcg": 130.32, "vitamin_b6_mg": 0.09, "vitamin_b12_mcg": 0.03, "thiamin_mg": 0.09, "riboflavin_mg": 0.11, "niacin_mg": 0.69, "folate_mcg": 26.44, "water_g": 88.22, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Pasta will absorb liquid over time; add a splash of water or stock when reheating.", "duration": "P3D"}, "freezer": {"notes": "Freezing changes the texture of cooked pasta significantly; prefer freezing the soup base without pasta.", "duration": "P1M"}, "reheating": "Simmer gently on stovetop until heated through. Do not boil vigorously or pasta may disintegrate.", "does_not_keep": false}', '[{"name": "Large heavy-bottomed pot or Dutch oven", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": null}]', '[{"symptom": "Soup has turned into a stew/pasta absorbed all liquid", "likely_cause": "Pasta sat in the hot liquid too long after cooking or during storage", "prevention": "Serve immediately after cooking; store pasta separately if making ahead", "fix": "Stir in an extra 100-200ml of hot water or broth to loosen"}, {"symptom": "Sweet potatoes are disintegrating", "likely_cause": "Potatoes were cut too small or boiled vigorously", "prevention": "Keep potato dice at 1.5cm and maintain a gentle simmer, not a rolling boil", "fix": "Cannot be fixed, but the soup will still taste good, just thicker"}]', '["Uniformity is key: cut the sweet potatoes roughly the same size as the pasta shape to ensure every spoonful has a balanced mix of ingredients.", "If using a store-bought broth that is very salty, hold back on adding extra salt until the very end.", "For a deeper flavor profile without adding extra ingredients, allow the onions to caramelize slightly (turn golden) in step 2 before adding the liquid.", "Lacinato (Dino) kale is preferred over curly kale here because it holds its texture better in soups and has a sweeter, less bitter finish."]', '"This dish draws inspiration from the Italian ''Minestra'', a loose category of thick vegetable soups often featuring pasta or rice. While traditionally made with beans (like Ribollita), this modern variation highlights the synergy between New World sweet potatoes and Old World brassicas."', 220.72);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('9d61fe2a-b458-4da2-a038-90d6d4cda72b', 'Cheesy Leek Gratin Stuffed Potatoes', 'Crisp-skinned baked potatoes hollowed out and stuffed with a velvety mixture of fluffy potato flesh and buttery sautéed leeks, all drowned in a rich Mornay sauce and gratinéed until golden and bubbling.', 'main dish', 'British', 'Intermediate', '["comfort food", "vegetarian", "winter", "potato", "leek", "cheese", "baked"]', '[{"group_name": "Baked Potatoes", "items": [{"name": "baking potatoes", "quantity": 4, "unit": null, "preparation": "whole, scrubbed", "notes": "Russet, Maris Piper, or King Edward; approx. 300g each", "substitutions": [], "ingredient_id": "4920385c-ae78-4023-8318-c5dfe051fecc", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": "for rubbing", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 5, "unit": "g", "preparation": "coarse", "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Leek Filling", "items": [{"name": "leeks", "quantity": 2, "unit": null, "preparation": "white and light green parts only, sliced into half-moons", "notes": "approx. 300g prepared weight", "substitutions": [], "ingredient_id": "f0bddafa-51db-4e56-954b-18624daa6fa4", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx. 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme leaves", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Cheese Sauce (Mornay)", "items": [{"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 400, "unit": "ml", "preparation": "warm", "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "sharp cheddar cheese", "quantity": 150, "unit": "g", "preparation": "freshly grated", "notes": null, "substitutions": [], "ingredient_id": "6cc08e49-8e1b-4065-be23-f57782560a8b", "nutrition_source": "Aggregated Public Data"}, {"name": "dijon mustard", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "nutmeg", "quantity": 1, "unit": "g", "preparation": "freshly grated", "notes": null, "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}, {"name": "cayenne pepper", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Preheat oven to 200\u00b0C (400\u00b0F). Poke holes in the potatoes with a fork, rub with olive oil, and coat generously with sea salt. Place directly on the oven rack (with a tray below to catch drips) and bake for 60-75 minutes until the skin is crisp and the inside yields to pressure.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT1H15M", "doneness_cues": {"visual": null, "tactile": "Soft when squeezed"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "While potatoes bake, thoroughly wash the sliced leeks in a bowl of cold water to remove grit. Lift them out (leaving grit at the bottom) and pat dry.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a saut\u00e9 pan over medium heat, melt 30g butter. Add the leeks and a pinch of salt. Sweat gently until completely soft and sweet, but not browned. Stir in garlic and thyme for the last minute.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT10M", "doneness_cues": {"visual": "Translucent and soft", "tactile": "Tender"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "For the sauce: In a saucepan over medium heat, melt 30g butter. Whisk in the flour and cook for 1-2 minutes to cook out the raw taste (blond roux).", "structured": {"action": "MIX", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Gradually whisk in the warm milk to avoid lumps. Simmer gently for 5 minutes until thickened enough to coat the back of a spoon.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Coats back of spoon (nappe consistency)", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove sauce from heat. Stir in mustard, nutmeg, cayenne, and 100g of the cheddar cheese until smooth. Reserve the remaining 50g cheese for topping.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "When potatoes are done, cut them in half lengthwise. Carefully scoop out the flesh into a bowl, leaving a 5mm (1/4 inch) layer of potato attached to the skin to maintain structural integrity.", "structured": {"action": "SCORE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Mash the scooped potato flesh roughly. Fold in the saut\u00e9ed leeks and half of the cheese sauce. Taste and adjust salt and pepper.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Spoon the mixture back into the potato skins. Pour the remaining cheese sauce over the top and sprinkle with the reserved cheddar.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "cook", "text": "Return to the oven (or switch to broiler/grill) for 10-15 minutes until the cheese is bubbling and golden brown spots appear.", "structured": {"action": "BROIL", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT10M", "doneness_cues": {"visual": "Golden brown and bubbling", "tactile": null}}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT1H15M", "total_time": "PT1H50M", "overnight_required": false, "yields": "4 stuffed potatoes", "yield_count": 4, "serving_size_g": 380}', '{"flags": ["Vegetarian", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Vegans", "Dairy-Free"]}', '{"per_serving": {"calories": 637.24, "protein_g": 19.55, "carbohydrates_g": 69.24, "fat_g": 32.32, "saturated_fat_g": 17.63, "trans_fat_g": null, "monounsaturated_fat_g": 7.08, "polyunsaturated_fat_g": 1.22, "fiber_g": 9.02, "sugar_g": 11.48, "sodium_mg": 843.84, "cholesterol_mg": 42.25, "potassium_mg": 1541.57, "calcium_mg": 459.13, "iron_mg": 3.55, "magnesium_mg": 107.16, "phosphorus_mg": 490.99, "zinc_mg": 2.83, "vitamin_a_mcg": 348.01, "vitamin_c_mg": 37.28, "vitamin_d_mcg": 1.3, "vitamin_e_mg": 1.07, "vitamin_k_mcg": 8.65, "vitamin_b6_mg": 0.67, "vitamin_b12_mcg": 0.48, "thiamin_mg": 0.27, "riboflavin_mg": 0.28, "niacin_mg": 3.45, "folate_mcg": 62.13, "water_g": 337.47, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Sauce may thicken significantly.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; the potato texture becomes grainy and the sauce may split upon thawing.", "duration": null}, "reheating": "Reheat in a 180\u00b0C (350\u00b0F) oven for 20-25 minutes. Microwaving is possible but will soften the skin.", "does_not_keep": false}', '[{"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Medium saucepan", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Potato ricer or masher", "required": true, "alternative": "Fork"}]', '[{"symptom": "Cheese sauce is grainy or oily", "likely_cause": "The sauce was boiled after adding the cheese, causing the proteins to curdle and fat to separate.", "prevention": "Remove the white sauce from the heat completely before stirring in the cheese.", "fix": "Let it cool slightly and blend with an immersion blender to re-emulsify."}, {"symptom": "Potato skins collapse", "likely_cause": "Scooped out too much flesh or potato was overcooked.", "prevention": "Leave a generous wall of potato inside the skin when scooping.", "fix": "Place the skins in a muffin tin or ramekins to hold their shape while baking."}]', '["Always wash leeks after slicing. Dirt gets trapped deep between the layers that you can''t reach when the leek is whole.", "For the fluffiest texture, mash the potato flesh while it is still steaming hot. If it cools down, it becomes gummy.", "Grate your own cheese. Pre-shredded bags contain anti-caking agents (cellulose) that prevent the sauce from melting smoothly.", "Rubbing the potato skins with oil and salt before the initial bake ensures the skin is tasty and crisp\u2014often the best part of the dish."]', '"The ''Jacket Potato'' is a British institution, serving as everything from a cheap lunch to a comforting dinner. While typically topped simply with beans or tuna, this version elevates the humble spud with a technique similar to ''Potatoes Romanoff'' or a Twice-Baked Potato, incorporating French sauce techniques."', 637.24);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('9d7c3bd1-0294-425f-bf06-8fb209c02778', 'Classic Penne alla Vodka', 'A luxuriant, retro classic featuring al dente penne coated in a velvety, bright orange sauce. The vodka acts as a solvent to unlock hidden flavors in the tomato and emulsify the cream, resulting in a sharp yet rich profile with a hint of chili heat.', 'dinner', 'Italian', 'Intermediate', '["italian", "pasta", "cream", "penne", "vodka", "dinner", "main course", "vegetarian", "retro", "entertaining"]', '[{"group_name": "Aromatics & Base", "items": [{"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "divided", "notes": "15g for saut\u00e9ing, 15g for finishing", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx. 40g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx. 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "red pepper flakes", "quantity": 2, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sauce", "items": [{"name": "tomato paste", "quantity": 130, "unit": "g", "preparation": null, "notes": "double concentrated", "substitutions": [], "ingredient_id": "1a1bddc5-66c3-4f44-bb24-72b8ac828ca6", "nutrition_source": "Aggregated Public Data"}, {"name": "vodka", "quantity": 60, "unit": "ml", "preparation": null, "notes": "standard 40% ABV", "substitutions": [], "ingredient_id": "ca2fa4fe-d61a-4ff2-b755-38ba94fd7a80", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 180, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pasta & Finish", "items": [{"name": "penne rigate", "quantity": 450, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8d47942b-f31c-4275-b2e2-47d94726ef8a", "nutrition_source": "Aggregated Public Data"}, {"name": "parmigiano-reggiano", "quantity": 60, "unit": "g", "preparation": "finely grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh basil", "quantity": 10, "unit": "g", "preparation": "torn", "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": null, "unit": null, "preparation": null, "notes": "for pasta water and seasoning", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Bring a large stockpot of heavily salted water to a boil.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "While water heats, melt half the butter (15g) with the olive oil in a large skillet over medium heat. Add minced shallot and salt lightly. Saut\u00e9 until softened but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT5M", "doneness_cues": {"visual": "Shallots are translucent", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add minced garlic and red pepper flakes to the skillet. Stir for 30 seconds until fragrant, then add the tomato paste. Cook the paste, stirring constantly, until it turns a deep brick-red color and separates from the oil. This step is crucial for flavor depth.", "structured": {"action": "CARAMELIZE", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Paste darkens to brick red", "tactile": "Oil separates from solids"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Remove pan from heat briefly (for safety) and pour in the vodka. Return to medium heat and simmer rapidly to deglaze the pan and reduce the liquid by half, removing the harsh alcohol bite.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Liquid reduced by half", "tactile": null}}, "tips": ["Take care when adding alcohol near an open flame."]}, {"step_number": 5, "phase": "cook", "text": "Stir in the heavy cream. Reduce heat to low and simmer gently until the sauce thickens slightly and becomes uniform.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Add penne to the boiling water. Cook until very al dente (about 1-2 minutes less than package directions), as it will finish cooking in the sauce.", "structured": {"action": "BOIL", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Firm bite in center"}}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Reserve 120ml (1/2 cup) of pasta water, then drain the pasta. Immediately transfer the pasta to the skillet with the sauce. Add 60ml (1/4 cup) of pasta water.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Cook over medium-high heat, tossing vigorously, until the sauce clings to the pasta. Remove from heat. Stir in the remaining butter (15g) and half the parmesan cheese until melted and glossy.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Sauce is glossy and coats pasta", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Garnish with fresh torn basil and the remaining parmesan cheese. Serve immediately.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT5M", "total_time": "PT30M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 769.68, "protein_g": 23.8, "carbohydrates_g": 92.52, "fat_g": 32.45, "saturated_fat_g": 17.29, "trans_fat_g": 0.56, "monounsaturated_fat_g": 9.73, "polyunsaturated_fat_g": 1.48, "fiber_g": 8.27, "sugar_g": 9.16, "sodium_mg": 518.8, "cholesterol_mg": 77.18, "potassium_mg": 1135.73, "calcium_mg": 245.5, "iron_mg": 6.23, "magnesium_mg": 141.85, "phosphorus_mg": 491.33, "zinc_mg": 3.46, "vitamin_a_mcg": 369.78, "vitamin_c_mg": 16.98, "vitamin_d_mcg": 0.8, "vitamin_e_mg": 1.34, "vitamin_k_mcg": 15.38, "vitamin_b6_mg": 0.11, "vitamin_b12_mcg": 0.27, "thiamin_mg": 0.03, "riboflavin_mg": 0.15, "niacin_mg": 0.17, "folate_mcg": 8.78, "water_g": 53.46, "alcohol_g": 5.01, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Sauce may separate upon reheating; add a splash of water and stir gently.", "duration": "P3D"}, "freezer": {"notes": "Cream-based sauces generally do not freeze well; texture may become grainy.", "duration": null}, "reheating": "Reheat gently on the stove over low heat with a splash of water to loosen the emulsion.", "does_not_keep": false}', '[{"name": "Large stockpot", "required": true, "alternative": null}, {"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": "Dutch oven"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": null}]', '[{"symptom": "Sauce is oily or separated", "likely_cause": "The emulsion broke due to high heat or insufficient starch", "prevention": "Do not let the sauce boil vigorously after adding cream/butter", "fix": "Add a splash of hot pasta water and shake the pan vigorously to re-emulsify"}, {"symptom": "Sauce tastes metallic or acidic", "likely_cause": "Tomato paste wasn''t cooked long enough", "prevention": "Ensure tomato paste turns brick red before deglazing", "fix": "Stir in a pinch of sugar or a small knob of extra butter"}]', '["Do not skip the vodka. While it doesn''t make the dish ''boozy'', vodka acts as a solvent for flavor compounds in the tomatoes that are alcohol-soluble but not water-soluble, creating a flavor profile you cannot achieve with stock or water.", "Use ''double concentrate'' tomato paste for the correct texture. Canned crushed tomatoes will make the sauce too watery and dilute the creaminess.", "The ''Mantecatura'' step (Step 8) is vital. Adding cold butter and cheese off the heat creates an emulsion that makes the sauce stick to the pasta rather than sliding off."]', '"Penne alla Vodka rose to prominence in the 1980s, becoming a symbol of fashionable dining in Italy and the US. While its exact origins are disputed\u2014claimed by chefs in Bologna, Rome, and New York\u2014it remains a staple of ''disco era'' cuisine, celebrated for bridging the gap between tomato-based and cream-based pasta traditions."', 769.68);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('9e0c1262-ded0-4b6e-9d4b-4dab905bfebc', 'Solar Flare Fermented Pineapple Habanero Sauce', 'A vibrant, electric-yellow hot sauce that balances the floral heat of habaneros with the sweet acidity of fermented pineapple and ginger. The lacto-fermentation process adds a complex, savory funk that raw vinegar sauces lack, finishing with a lingering, sunny burn.', 'condiment', 'Caribbean', 'Intermediate', '["hot sauce", "fermented", "spicy", "condiment", "caribbean", "vegan", "gluten-free"]', '[{"group_name": "Fermentation Base", "items": [{"name": "habanero peppers", "quantity": 150, "unit": "g", "preparation": "stems removed, halved", "notes": "Leave seeds for maximum heat, remove for milder sauce", "substitutions": [], "ingredient_id": "5b3089aa-65dd-4281-8092-368179b0e6ba", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh pineapple", "quantity": 200, "unit": "g", "preparation": "peeled, cored, and cubed", "notes": null, "substitutions": [], "ingredient_id": "37da68de-6b6e-4619-9f28-52da1f26f4ce", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow bell pepper", "quantity": 150, "unit": "g", "preparation": "seeded and roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "b8ed9fc6-8806-4baf-a073-89a5b79f63f0", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 25, "unit": "g", "preparation": "peeled, slightly crushed", "notes": null, "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 15, "unit": "g", "preparation": "peeled and sliced", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Brine", "items": [{"name": "water", "quantity": 500, "unit": "ml", "preparation": "filtered or non-chlorinated", "notes": "Chlorine can inhibit fermentation", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt", "quantity": 15, "unit": "g", "preparation": null, "notes": "Do not use iodized table salt", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "apple cider vinegar", "quantity": 120, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "white sugar", "quantity": 10, "unit": "g", "preparation": null, "notes": "Optional, to balance acidity", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Wear gloves. Combine the habaneros, pineapple chunks, yellow bell pepper, garlic, and ginger in a clean 1-liter glass jar. Pack them down tightly.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Dissolve the salt into the water to create a brine. Pour this over the vegetables in the jar, ensuring everything is completely submerged. If floating occurs, use a fermentation weight or a water-filled ziplock bag to keep ingredients under the brine surface.", "structured": {"action": "BRINE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Cover the jar loosely with a lid (to allow gas to escape) or use an airlock. Store in a cool, dark place (18-24\u00b0C/65-75\u00b0F) for 5 to 7 days. The brine will become cloudy and small bubbles will form, indicating fermentation is active.", "structured": {"action": "REST", "temperature": {"celsius": 21, "fahrenheit": 70}, "duration": "P7D", "doneness_cues": {"visual": "Brine is cloudy, bubbles rising", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Strain the solids from the brine, reserving the brine liquid. Transfer the fermented solids to a blender. Add 60ml of the reserved brine and the apple cider vinegar.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Blend on high speed until completely smooth. If the consistency is too thick, add more reserved brine 1 tablespoon at a time until desired consistency is reached.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Pour the puree into a saucepan. Bring to a boil, then reduce heat and simmer gently for 10 minutes. This halts fermentation and stabilizes the sauce for storage.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from heat. If a silky texture is desired, pass through a fine-mesh sieve (optional). Funnel into sterilized glass bottles while hot. Allow to cool completely before refrigerating.", "structured": {"action": "COOL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "P7D", "total_time": "P7DT45M", "overnight_required": true, "yields": "500ml", "yield_count": 33, "serving_size_g": 15}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Nut-Free", "Soy-Free", "Paleo", "Whole30", "Keto"], "not_suitable_for": []}', '{"per_serving": {"calories": 9.28, "protein_g": 0.21, "carbohydrates_g": 4.11, "fat_g": 0.03, "saturated_fat_g": null, "trans_fat_g": null, "monounsaturated_fat_g": null, "polyunsaturated_fat_g": null, "fiber_g": 0.24, "sugar_g": 1.1, "sodium_mg": 179.18, "cholesterol_mg": null, "potassium_mg": 33.89, "calcium_mg": 3.4, "iron_mg": 0.06, "magnesium_mg": 2, "phosphorus_mg": 3.18, "zinc_mg": 0.03, "vitamin_a_mcg": 13.82, "vitamin_c_mg": 19.68, "vitamin_d_mcg": null, "vitamin_e_mg": null, "vitamin_k_mcg": 0.06, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": null, "niacin_mg": 0.08, "folate_mcg": 2.35, "water_g": 28.76, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor matures over time.", "duration": "P6M"}, "freezer": {"duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "1 liter glass jar with lid", "required": true, "alternative": "Any large non-reactive glass container"}, {"name": "Fermentation weight", "required": false, "alternative": "Small ziplock bag filled with water"}, {"name": "Blender", "required": true, "alternative": null}, {"name": "Saucepan", "required": true, "alternative": null}, {"name": "Fine mesh sieve", "required": false, "alternative": null}, {"name": "Glass bottles", "required": true, "alternative": null}, {"name": "Gloves", "required": true, "alternative": "Careful hand washing"}]', '[{"symptom": "White, thin, powdery film on top of brine", "likely_cause": "Kahm Yeast (common harmless yeast)", "prevention": "Ensure strictly anaerobic environment with an airlock", "fix": "Skim it off carefully; the vegetables underneath are safe if they smell good"}, {"symptom": "Fuzzy blue, green, or black spots on surface", "likely_cause": "Mold contamination", "prevention": "Keep all solids submerged below the brine line; sanitize equipment thoroughly", "fix": "Cannot be fixed. Discard entire batch immediately"}]', '["Always use gloves when handling habaneros. The capsaicin oil stays on skin and can cause severe pain if you touch your eyes.", "The fermentation period is flexible. 5 days gives a brighter, fresher flavor; 2 weeks yields a funkier, more complex sauce. Taste the brine daily after day 3.", "If you prefer a thinner, Tabasco-style sauce, strain the final mixture through cheesecloth and bottle only the liquid. Use the leftover pulp for marinades.", "Using non-chlorinated water is crucial. Tap water containing chlorine or chloramine can kill the lactobacillus bacteria needed for fermentation."]', '"Hot sauce is a global staple, but this recipe leans heavily on Caribbean traditions where fruit and fire coexist. The use of ''scotch bonnet'' or habanero peppers paired with tropical fruits like mango or pineapple is iconic to West Indian cuisine, serving as both a preservative method and a way to induce cooling perspiration in tropical climates."', 9.28);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('9e66c79b-9ede-42cd-b4bf-e03974876f67', 'Sugo all''Arrabbiata', 'A classic Roman tomato sauce defined by its fiery kick and aromatic garlic profile. ''Arrabbiata'' translates to ''angry,'' referencing the heat from the dried chilies, balanced by the sweetness of high-quality San Marzano tomatoes.', 'sauce', 'Italian', 'Easy', '["italian", "sauce", "garlic", "red pepper", "tomato", "side"]', '[{"group_name": "Aromatics", "items": [{"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "thinly sliced", "notes": "approx. 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "dried red chili flakes", "quantity": 5, "unit": "g", "preparation": null, "notes": "Adjust to heat preference, also known as peperoncino", "substitutions": ["fresh red chili (sliced)"], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Base", "items": [{"name": "whole peeled tomatoes", "quantity": 800, "unit": "g", "preparation": null, "notes": "San Marzano variety preferred; crushed by hand", "substitutions": ["crushed tomatoes", "tomato passata"], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finish", "items": [{"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pour the tomatoes and their juices into a bowl and crush them by hand until they are broken down but still slightly chunky. Slice the garlic cloves thinly.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Roughly crushed texture"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Combine olive oil, sliced garlic, and chili flakes in a large cool skillet. Turn heat to medium-low. This cold start allows the garlic to infuse the oil without burning immediately.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": null, "doneness_cues": {"visual": "Garlic turns pale gold", "tactile": "Aromatic sizzle"}}, "tips": ["Do not brown the garlic deeply; it will turn bitter."]}, {"step_number": 3, "phase": "cook", "text": "Once the garlic is pale gold and fragrant, immediately add the crushed tomatoes carefully (the oil may splatter). Season with salt.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Simmer gently, stirring occasionally, until the sauce thickens and the oil separates slightly, pooling on the surface. This indicates the raw tomato flavor has cooked out.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT20M", "doneness_cues": {"visual": "Oil separates and floats on top", "tactile": "Thickened consistency"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove from heat. Taste and adjust salt if necessary. Stir in fresh parsley just before tossing with pasta.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT20M", "total_time": "PT30M", "overnight_required": false, "yields": "600g (Coats 500g pasta)", "yield_count": 4, "serving_size_g": 150}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Paleo", "Whole30", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 145.46, "protein_g": 2.24, "carbohydrates_g": 9.8, "fat_g": 11.87, "saturated_fat_g": 1.65, "trans_fat_g": null, "monounsaturated_fat_g": 8.26, "polyunsaturated_fat_g": 1.3, "fiber_g": 4.2, "sugar_g": 7.95, "sodium_mg": 339.14, "cholesterol_mg": null, "potassium_mg": 527.43, "calcium_mg": 34.66, "iron_mg": 1.04, "magnesium_mg": 26.06, "phosphorus_mg": 58.94, "zinc_mg": 0.47, "vitamin_a_mcg": 29.03, "vitamin_c_mg": 31.9, "vitamin_d_mcg": null, "vitamin_e_mg": 2.12, "vitamin_k_mcg": 49.16, "vitamin_b6_mg": 0.08, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.02, "niacin_mg": 0.21, "folate_mcg": 4.26, "water_g": 4.53, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight glass container.", "duration": "P5D"}, "freezer": {"notes": "Freeze in portions. Thaw overnight in the refrigerator.", "duration": "P3M"}, "reheating": "Simmer gently in a pan, adding a splash of water if the sauce has thickened too much.", "does_not_keep": false}', '[{"name": "Large saut\u00e9 pan or skillet", "required": true, "alternative": "Wide saucepan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": null}]', '[{"symptom": "Sauce tastes bitter", "likely_cause": "The garlic was burned during the initial saut\u00e9", "prevention": "Start with a cold pan and use medium-low heat; watch the garlic constantly", "fix": "Cannot be fixed completely; adding a pinch of sugar may mask slight bitterness, but starting over is best"}]', '["The secret to this sauce is the ''soffritto'' of garlic and chili; slicing the garlic instead of mincing it prevents it from burning too quickly.", "Always reserve a cup of starchy pasta water when boiling your noodles. Splash some into the sauce when tossing the pasta to create a silky emulsion.", "San Marzano tomatoes are recommended because they have fewer seeds and a sweeter flesh, which balances the heat of the chilies without added sugar."]', '"Arrabbiata originated in the Lazio region, particularly Rome. The name means ''angry'' in Italian, a reference to the heat of the chili peppers that causes the eater''s face to turn red, much like an angry person."', 145.46);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('9e703122-122c-418f-999b-ba844937a79f', 'Rhubarb Streusel Coffee Cake', 'A tender, fine-crumbed cake balancing the sharp acidity of fresh rhubarb with a sweet, floral vanilla base. Topped with a generous layer of spiced butter streusel that provides a textural counterpoint to the soft fruit and moist cake.', 'baked good', 'American', 'Intermediate', '["pastries", "butter", "cake flour", "rhubarb", "snack", "dessert", "coffee cake", "spring baking"]', '[{"group_name": "Spiced Streusel Topping", "items": [{"name": "all-purpose flour", "quantity": 120, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "light brown sugar", "quantity": 100, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 85, "unit": "g", "preparation": "melted and cooled", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "large pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Rhubarb Layer", "items": [{"name": "fresh rhubarb", "quantity": 300, "unit": "g", "preparation": "trimmed and diced into 1cm pieces", "notes": "discard leaves entirely", "substitutions": [], "ingredient_id": "293d2132-013e-4594-801e-4d86e1d04df0", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 25, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 5, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Cake Base", "items": [{"name": "cake flour", "quantity": 200, "unit": "g", "preparation": null, "notes": "sifted", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 6, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 113, "unit": "g", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "large, room temperature", "notes": "approx 100g total without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "sour cream", "quantity": 120, "unit": "g", "preparation": "full fat, room temperature", "notes": null, "substitutions": ["Greek yogurt (full fat)"], "ingredient_id": "d171100e-1088-4266-8d50-06cdedda7193", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 175\u00b0C (350\u00b0F). Grease a 23cm (9-inch) square baking pan and line the bottom with parchment paper, leaving an overhang for easy removal.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Prepare the streusel: In a medium bowl, whisk together the all-purpose flour, brown sugar, cinnamon, and salt. Pour in the melted butter and mix with a fork until moist clumps form. Refrigerate this mixture while preparing the batter.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Moist, sandy clumps", "tactile": "Holds shape when pressed"}}, "tips": ["Chilling the streusel ensures the butter resolidifies, creating a crunchier texture rather than melting into the cake."]}, {"step_number": 3, "phase": "prep", "text": "Toss the diced rhubarb with 25g granulated sugar and cornstarch in a small bowl. Set aside.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "In a separate medium bowl, sift together the cake flour, baking powder, baking soda, and salt.", "structured": {"action": "SIFT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "In the bowl of a stand mixer fitted with the paddle attachment, cream the room temperature butter and 150g granulated sugar on medium-high speed until pale and fluffy, about 3-4 minutes.", "structured": {"action": "CREAM", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Pale yellow, almost white", "tactile": "Aerated and soft"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Reduce speed to medium. Add eggs one at a time, mixing fully after each addition. Scrape down the sides of the bowl. Add the vanilla extract and sour cream, mixing until just combined.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Reduce mixer speed to low. Add the dry flour mixture in two batches. Mix only until the flour streaks disappear. Do not overmix.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": {"visual": "Uniform batter with no dry pockets", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Spread the batter evenly into the prepared pan. Scatter the rhubarb mixture over the top of the batter, pressing the fruit pieces slightly into the surface. Finally, sprinkle the chilled streusel evenly over the rhubarb.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Bake in the center of the oven for 45 to 55 minutes, or until a tester inserted into the center comes out clean or with just a few moist crumbs (avoiding a piece of rhubarb). Ideally, the internal temperature of the cake crumb should reach 93\u00b0C (200\u00b0F).", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT50M", "doneness_cues": {"visual": "Golden brown topping", "tactile": "Internal temp 93\u00b0C"}}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Remove from oven and let cool in the pan on a wire rack for at least 30 minutes before lifting out via the parchment paper and slicing.", "structured": {"action": "COOL", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT1H15M", "total_time": "PT1H45M", "overnight_required": false, "yields": "9 squares", "yield_count": 9, "serving_size_g": 115}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Vegans (contains dairy, eggs)", "Coeliacs (contains gluten)"]}', '{"per_serving": {"calories": 450.14, "protein_g": 5.96, "carbohydrates_g": 60.59, "fat_g": 20.92, "saturated_fat_g": 12.53, "trans_fat_g": null, "monounsaturated_fat_g": 6.06, "polyunsaturated_fat_g": 1.11, "fiber_g": 1.68, "sugar_g": 30.8, "sodium_mg": 339.54, "cholesterol_mg": 93.83, "potassium_mg": 188.99, "calcium_mg": 110.39, "iron_mg": 0.88, "magnesium_mg": 16.33, "phosphorus_mg": 98.31, "zinc_mg": 0.52, "vitamin_a_mcg": 183.56, "vitamin_c_mg": 2.8, "vitamin_d_mcg": 0.25, "vitamin_e_mg": 0.79, "vitamin_k_mcg": 11.6, "vitamin_b6_mg": 0.05, "vitamin_b12_mcg": 0.18, "thiamin_mg": 0.06, "riboflavin_mg": 0.11, "niacin_mg": 0.59, "folate_mcg": 19.05, "water_g": 58.69, "alcohol_g": 0.19, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container to prevent drying out.", "duration": "P5D"}, "freezer": {"notes": "Wrap individual slices tightly in plastic wrap then foil.", "duration": "P3M"}, "reheating": "Warm gently in a microwave for 10-15 seconds or in a low oven to refresh the crumb.", "does_not_keep": false}', '[{"name": "Square baking pan (23cm / 9in)", "required": true, "alternative": null}, {"name": "Stand mixer or hand mixer", "required": true, "alternative": "Whisk and strong arm"}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Rubber spatula", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}]', '[{"symptom": "Cake is dense or gummy", "likely_cause": "Overmixing the batter after adding flour", "prevention": "Stop mixing the moment the dry ingredients are incorporated", "fix": "Cannot be fixed after baking"}, {"symptom": "Soggy area around fruit", "likely_cause": "Rhubarb released too much liquid that wasn''t bound", "prevention": "Ensure rhubarb is tossed with cornstarch before adding to the cake", "fix": "Bake 5-10 minutes longer; ensure cake cools completely to set juices"}, {"symptom": "Streusel sinks into the cake", "likely_cause": "Streusel butter was too warm or batter was too thin", "prevention": "Chill the streusel thoroughly; ensure cake flour is used for batter structure", "fix": "Cannot be fixed"}]', '["Room temperature ingredients (butter, eggs, sour cream) are non-negotiable here; they emulsify better, trapping more air for a lighter crumb.", "If using frozen rhubarb, do not thaw it completely before baking, as it will release too much water. Toss it in the cornstarch while still frozen and bake immediately, adding 5 minutes to bake time.", "Cake flour is preferred over all-purpose for the base because its lower protein content yields a velvety, tender crumb that contrasts beautifully with the crunchy topping."]', '"While ''coffee cake'' in the US implies a cake meant to be eaten with coffee (often containing cinnamon and streusel), its roots lie in the German ''Kaffeekuchen'' tradition. This recipe bridges the gap between a classic American sour cream coffee cake and the fruit-forward tray bakes found in Northern Europe."', 450.14);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('9f9a81a0-f67b-4bf2-a17f-2116a4ea2bf7', 'Spaghetti with Vibrant Green Chutney and Parmesan', 'A striking fusion dish where zest meets comfort. Bright, herbaceous cilantro and spicy serrano peppers form a fresh chutney that is emulsified with butter and parmesan into a glossy, vibrant green sauce that clings to every strand of spaghetti.', 'dinner', 'Fusion', 'Easy', '["spaghetti", "cilantro", "serrano", "lemon juice", "parmesan", "pastas", "dinner", "boil", "vegetarian", "noodles", "quick", "weeknight", "easy", "stovetop", "fusion"]', '[{"group_name": "Green Chutney Base", "items": [{"name": "fresh cilantro", "quantity": 60, "unit": "g", "preparation": "leaves and tender stems washed", "notes": "approx. 1 large bunch", "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "serrano pepper", "quantity": 1, "unit": null, "preparation": "rough chopped", "notes": "about 10g; remove seeds for less heat", "substitutions": [], "ingredient_id": "d629fcf3-13bd-4471-9c09-79fe9ceada68", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "peeled", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 5, "unit": "g", "preparation": "peeled", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 30, "unit": "ml", "preparation": null, "notes": "cold, to aid blending", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Pasta & Sauce", "items": [{"name": "spaghetti", "quantity": 225, "unit": "g", "preparation": "dry", "notes": null, "substitutions": [], "ingredient_id": "3994b041-8c11-4992-adf0-a373b17e1aee", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "parmesan cheese", "quantity": 40, "unit": "g", "preparation": "finely grated", "notes": "plus extra for garnish", "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "pasta water", "quantity": 120, "unit": "ml", "preparation": "reserved hot", "notes": "approximate usage", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "for boiling water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine cilantro, serrano pepper, garlic, ginger, lemon juice, and cold water in a blender. Blend until smooth and vibrant green. Set aside.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Bright green smooth paste", "tactile": "No large fibrous chunks"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Bring a large pot of heavily salted water to a boil. Add spaghetti and cook until just shy of al dente (about 1 minute less than package directions).", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT9M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Carefully reserve about 250ml (1 cup) of starchy pasta water before draining the noodles.", "structured": {"action": "MEASURE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "In a large skillet over medium-low heat, melt the butter. Add the green chutney paste and saut\u00e9 gently for 30-60 seconds just to release the aromatics\u2014do not let the color dull.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT1M", "doneness_cues": {"visual": "Butter is melted and bubbling with the green paste", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Add the drained spaghetti and 60ml (1/4 cup) of reserved pasta water to the skillet. Toss vigorously with tongs to coat the strands.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove pan from heat. Gradually sprinkle in the parmesan while tossing constantly. Add more pasta water a tablespoon at a time until a glossy, creamy green emulsion coats the pasta.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": {"visual": "Sauce is glossy and clings to pasta, not watery", "tactile": null}}, "tips": ["Adding cheese off-heat prevents it from clumping or becoming stringy."]}, {"step_number": 7, "phase": "finish", "text": "Plate immediately, garnished with extra parmesan and a cracked black pepper if desired.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT5M", "total_time": "PT20M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 320}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 440.85, "protein_g": 18.29, "carbohydrates_g": 38.82, "fat_g": 23.71, "saturated_fat_g": 14.38, "trans_fat_g": null, "monounsaturated_fat_g": 6.81, "polyunsaturated_fat_g": 0.92, "fiber_g": 3.42, "sugar_g": 0.76, "sodium_mg": 296.11, "cholesterol_mg": 61.98, "potassium_mg": 273.11, "calcium_mg": 261, "iron_mg": 1.1, "magnesium_mg": 47.13, "phosphorus_mg": 208.49, "zinc_mg": 1.2, "vitamin_a_mcg": 804.85, "vitamin_c_mg": 6.21, "vitamin_d_mcg": 0.1, "vitamin_e_mg": 0.58, "vitamin_k_mcg": 1.97, "vitamin_b6_mg": 0.14, "vitamin_b12_mcg": 0.28, "thiamin_mg": 0.36, "riboflavin_mg": 0.26, "niacin_mg": 2.18, "folate_mcg": 96.19, "water_g": 162.47, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "The vibrant green color will darken due to oxidation, though flavor remains safe.", "duration": "P2D"}, "freezer": {"notes": "Not recommended; emulsion will break and pasta will become mushy.", "duration": null}, "reheating": "Gently reheat in a pan with a splash of water to re-emulsify the sauce.", "does_not_keep": false}', '[{"name": "Large stockpot", "required": true, "alternative": null}, {"name": "Blender or food processor", "required": true, "alternative": null}, {"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Microplane or fine grater", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "Sauce is clumped and stringy", "likely_cause": "Pan was too hot when cheese was added", "prevention": "Always remove the pan from the heat source before adding the parmesan", "fix": "Add a splash of hot pasta water and toss vigorously to try and smooth it out"}, {"symptom": "Sauce is watery and not sticking", "likely_cause": "Insufficient starch or agitation", "prevention": "Use less water initially and toss more vigorously (mantecatura)", "fix": "Simmer for 30 seconds more while tossing to reduce excess liquid"}]', '["Temperature Control: Heat is the enemy of chlorophyll. Do not cook the chutney for too long or at too high a heat, or it will turn from vibrant emerald to dull army green.", "The Emulsion: The magic happens when starchy water meets butter and cheese. Vigorously tossing (aerating) the pasta creates the creamy texture without cream.", "Spice Adjustment: For a milder sauce, remove the seeds and white ribs from the serrano pepper before blending.", "Texture: If your blender struggles with the small amount of chutney liquid, double the chutney recipe and save half for sandwiches or dipping.", "Cheese Quality: Always grate your own Parmesan. Pre-grated cheese contains cellulose (anti-caking agent) which prevents a smooth melt."]', '"This dish exemplifies modern ''Desi'' (South Asian) fusion cuisine, popularized in urban India and the diaspora. It marries the technique of Italian ''Aglio e Olio'' or ''Al Burro'' with the ubiquitous ''Hari Chutney'' (green chutney) found in Indian street food, creating a comfort meal that satisfies both the craving for carbs and the need for bold, spicy aromatics."', 440.85);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('a08b4aec-5b3b-484e-810d-944318e66d50', 'Crispy Smoked Shiitake ''Bacon''', 'Umami-rich shiitake mushrooms transformed into crispy, savory ribbons with a deep smoky aroma and a hint of maple sweetness. A plant-based essential that rivals cured pork in texture and depth.', 'side dish', 'American', 'Easy', '["american", "vegetables", "five ingredient", "shiitake", "appetizer", "side dish", "vegan", "vegetarian", "keto-friendly"]', '[{"group_name": "Mushroom Bacon", "items": [{"name": "shiitake mushrooms", "quantity": 250, "unit": "g", "preparation": "fresh, stems removed", "notes": "Choose thick caps for best texture", "substitutions": [], "ingredient_id": "127ce8a8-238d-40e6-a4b0-c58c42a7c745", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "Grapeseed or avocado oil", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "tamari", "quantity": 15, "unit": "ml", "preparation": null, "notes": "Or soy sauce if not strictly gluten-free", "substitutions": ["Soy sauce", "Coconut aminos"], "ingredient_id": "1a157828-0624-4e67-815d-8e6bdf8b23c2", "nutrition_source": "USDA FoodData Central"}, {"name": "liquid smoke", "quantity": 5, "unit": "ml", "preparation": null, "notes": "Hickory or applewood", "substitutions": [], "ingredient_id": "5a57a4ee-7c53-4a3d-be12-a8f061f7a931", "nutrition_source": "Aggregated Public Data"}, {"name": "maple syrup", "quantity": 5, "unit": "ml", "preparation": null, "notes": "Optional, for balance", "substitutions": [], "ingredient_id": "c9ca1f35-b107-46c2-92a3-4c1c620f3c11", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Clean the shiitake mushrooms by brushing off any dirt with a pastry brush or paper towel. Do not wash with water. Remove the tough stems and slice the caps into strips approximately 3-5mm thick.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Uniform strips", "tactile": null}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat the neutral oil in a large skillet over medium-high heat (approx. 190\u00b0C/375\u00b0F). Add the mushroom slices in a single layer. If your pan is small, do this in two batches to avoid steaming.", "structured": {"action": "HEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": ["Crowding the pan causes mushrooms to steam rather than crisp."]}, {"step_number": 3, "phase": "cook", "text": "Fry the mushrooms undisturbed for 3-4 minutes until the bottoms are golden brown. Flip and cook for another 2-3 minutes until golden all over and significantly reduced in size.", "structured": {"action": "FRY", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Golden brown", "tactile": "Crispy edges"}}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Reduce heat to low. In a small cup, whisk the tamari, liquid smoke, and maple syrup together. Pour over the mushrooms and toss rapidly for 30-60 seconds until the liquid evaporates and glazes the mushrooms without burning.", "structured": {"action": "GLAZE", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Dark, glossy coating", "tactile": "Sticky but not wet"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove from the pan immediately and transfer to a paper towel-lined plate. Allow to cool for at least 5 minutes; they will crisp up further as they cool.", "structured": {"action": "COOL", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": null, "tactile": "Crunchy snap"}}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT5M", "total_time": "PT20M", "overnight_required": false, "yields": "4 garnish servings", "yield_count": 4, "serving_size_g": 30}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Paleo"], "not_suitable_for": []}', '{"per_serving": {"calories": 93.7, "protein_g": 1.66, "carbohydrates_g": 5.47, "fat_g": 7.83, "saturated_fat_g": 1.08, "trans_fat_g": null, "monounsaturated_fat_g": null, "polyunsaturated_fat_g": 0.01, "fiber_g": 1.58, "sugar_g": 2.37, "sodium_mg": 263.58, "cholesterol_mg": null, "potassium_mg": 209.58, "calcium_mg": 3.58, "iron_mg": 0.28, "magnesium_mg": 13.85, "phosphorus_mg": 73.53, "zinc_mg": 0.66, "vitamin_a_mcg": null, "vitamin_c_mg": null, "vitamin_d_mcg": 0.25, "vitamin_e_mg": null, "vitamin_k_mcg": null, "vitamin_b6_mg": 0.19, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.16, "niacin_mg": 2.53, "folate_mcg": 8.61, "water_g": 59.02, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container lined with a paper towel to absorb moisture.", "duration": "P5D"}, "freezer": {"notes": "Not recommended as texture will degrade.", "duration": null}, "reheating": "Re-crisp in a dry pan over medium heat for 1-2 minutes.", "does_not_keep": false}', '[{"name": "Large skillet or frying pan", "required": true, "alternative": "Wok"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Pastry brush", "required": false, "alternative": "Paper towel"}]', '[{"symptom": "Mushrooms are soggy or chewy instead of crisp", "likely_cause": "Pan was overcrowded or heat was too low, causing steaming", "prevention": "Cook in batches ensuring space between slices; use medium-high heat", "fix": "Spread on a baking sheet and bake at 175\u00b0C (350\u00b0F) for 5-10 minutes to dry out"}]', '["Consistency in slicing is key; uneven slices will result in some burning while others remain chewy.", "Do not salt the mushrooms at the beginning of cooking; salt draws out moisture and delays the browning process.", "For a ''Professional'' variation without liquid smoke: Fry the mushrooms, then use a smoking gun with applewood chips under a cloche for 5 minutes before serving.", "These are excellent crumbled over Caesar salads, loaded baked potatoes, or creamy pasta dishes."]', '"While ''facon'' has existed in various forms, using whole vegetables like shiitake mushrooms honors the Japanese ingredient''s natural high levels of guanylate (umami) while applying American curing and smoking flavor profiles to create a bridge between plant-based ethics and carnivorous nostalgia."', 93.7);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('a0966d27-e4b4-41ae-9699-c96fd19f9d83', 'One-Pan Roasted Chicken with Squash, Mushrooms & Lemon Crème Fraîche', 'A vibrant, low-effort traybake featuring crispy skin-on chicken thighs, caramelized butternut squash, and earthy mushrooms. The dish is finished with a cool, zesty lemon crème fraîche that cuts through the richness of the roast.', 'dinner', 'Modern European', 'Easy', '["chicken", "roast", "traybake", "squash", "mushrooms", "lemon", "easy"]', '[{"group_name": "Chicken & Vegetables", "items": [{"name": "chicken thighs, bone-in skin-on", "quantity": 4, "unit": null, "preparation": "room temperature", "notes": "approx. 150-175g each", "substitutions": ["chicken drumsticks", "chicken legs"], "ingredient_id": "39d19921-3bf5-49b0-9e1c-4f498caa7d6a", "nutrition_source": "Aggregated Public Data"}, {"name": "butternut squash", "quantity": 500, "unit": "g", "preparation": "peeled and cut into 2.5cm cubes", "notes": null, "substitutions": ["sweet potato", "kabocha squash"], "ingredient_id": "7f8919a5-2de5-47ce-91b2-d2a999ea11f7", "nutrition_source": "USDA FoodData Central"}, {"name": "cremini mushrooms", "quantity": 250, "unit": "g", "preparation": "halved if large, whole if small", "notes": null, "substitutions": ["white button mushrooms", "chestnut mushrooms"], "ingredient_id": "fdd23eb2-a71c-46d1-932b-295adf7d5ae5", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": "divided use", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "dried thyme", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx. 1 tsp", "substitutions": ["dried oregano", "dried sage"], "ingredient_id": "3b938244-d506-46b2-9027-21bed955bcc5", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic powder", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx. 1 tsp", "substitutions": [], "ingredient_id": "177a312f-ef99-4398-9108-98f7a608a245", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 6, "unit": "g", "preparation": null, "notes": "approx. 1 tsp, adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Lemon Cr\u00e8me Fra\u00eeche", "items": [{"name": "cr\u00e8me fra\u00eeche", "quantity": 120, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["sour cream", "greek yogurt"], "ingredient_id": "8425ddd1-204d-4f63-883d-f332a6508620", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": null, "notes": "zest of whole lemon, juice of half", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 5, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "grated or pressed", "notes": "approx. 3g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 220\u00b0C (425\u00b0F). Position a rack in the center of the oven.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Place the cubed butternut squash and mushrooms on a large rimmed baking sheet. Drizzle with 30ml (2 tbsp) of olive oil, half the dried thyme, half the garlic powder, and a generous pinch of salt and pepper. Toss to coat evenly and spread them out in a single layer.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Ensure the vegetables are not piled on top of each other to promote roasting rather than steaming."]}, {"step_number": 3, "phase": "prep", "text": "Pat the chicken thighs dry with paper towels to ensure crispy skin. Rub the chicken with the remaining 15ml (1 tbsp) olive oil, remaining thyme, remaining garlic powder, salt, and pepper.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Drying the skin is the most critical step for crispiness."]}, {"step_number": 4, "phase": "cook", "text": "Nestle the chicken thighs skin-side up amongst the vegetables on the baking sheet. Roast for 35-40 minutes until the squash is tender, the chicken skin is golden and crispy, and the internal temperature of the chicken reaches at least 74\u00b0C (165\u00b0F).", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT40M", "doneness_cues": {"visual": "Chicken skin is golden brown and crispy", "tactile": "Squash is fork-tender"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "While the chicken roasts, prepare the sauce. In a small bowl, whisk together the cr\u00e8me fra\u00eeche, lemon zest, 1 tbsp lemon juice, grated garlic, and chopped parsley. Season with a pinch of salt to taste.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove the tray from the oven. Let the chicken rest for 5 minutes. Serve the chicken and vegetables directly from the tray or plated, topped with a generous dollop of the lemon cr\u00e8me fra\u00eeche.", "structured": {"action": "SERVE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT40M", "total_time": "PT1H", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Gluten-Free", "Nut-Free", "Soy-Free", "Egg-Free", "Low-Carb"], "not_suitable_for": ["Vegans", "Dairy-Free"]}', '{"per_serving": {"calories": 518.53, "protein_g": 40.09, "carbohydrates_g": 21.21, "fat_g": 32.68, "saturated_fat_g": 7.91, "trans_fat_g": null, "monounsaturated_fat_g": 8.24, "polyunsaturated_fat_g": 1.27, "fiber_g": 3.81, "sugar_g": 4.85, "sodium_mg": 766.13, "cholesterol_mg": null, "potassium_mg": 1211.56, "calcium_mg": 132.25, "iron_mg": 4.53, "magnesium_mg": 91.62, "phosphorus_mg": 399.9, "zinc_mg": 4.89, "vitamin_a_mcg": 739.29, "vitamin_c_mg": 39.87, "vitamin_d_mcg": null, "vitamin_e_mg": 3.51, "vitamin_k_mcg": 37.62, "vitamin_b6_mg": 0.23, "vitamin_b12_mcg": null, "thiamin_mg": 0.14, "riboflavin_mg": 0.04, "niacin_mg": 1.58, "folate_mcg": 39.78, "water_g": 128.57, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store cr\u00e8me fra\u00eeche sauce in a separate airtight container.", "duration": "P3D"}, "freezer": {"notes": "Roasted vegetables do not freeze well; texture will become mushy.", "duration": null}, "reheating": "Reheat chicken and vegetables in an oven at 180\u00b0C/350\u00b0F for 10-15 minutes to recrisp skin. Do not heat the cr\u00e8me fra\u00eeche sauce.", "does_not_keep": false}', '[{"name": "Large rimmed baking sheet", "required": true, "alternative": "Two smaller baking sheets"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Microplane or zester", "required": true, "alternative": "Fine side of a box grater"}]', '[{"symptom": "Chicken skin is not crispy", "likely_cause": "Moisture on the skin or overcrowded pan created steam", "prevention": "Thoroughly pat chicken dry before seasoning and ensure ample space between items on the tray", "fix": "Switch oven to broiler/grill setting for the last 2-3 minutes, watching closely to prevent burning"}]', '["Cut the butternut squash into uniform 2.5cm (1 inch) cubes. If they are too large, the chicken will finish before the squash is tender.", "If your baking sheet is small, divide the ingredients between two sheets to avoid overcrowding. Overcrowding leads to steaming and soggy vegetables.", "The lemon cr\u00e8me fra\u00eeche is essential as it provides a temperature and acidity contrast to the hot, savory roasted elements.", "For extra flavor, toss the roasted vegetables in the pan juices immediately after removing the chicken to rest."]', '"The ''traybake'' is a staple of modern home cooking, evolving from traditional Sunday roasts into a weeknight-friendly format. By cooking proteins and vegetables simultaneously on high heat, this method emphasizes the Maillard reaction\u2014browning both the meat and the vegetables to create depth of flavor with minimal cleanup."', 518.53);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('a09940a9-698a-4a52-9426-a481aad572c9', 'Make-Ahead White Wine & Herb Gravy', 'A velvety, deeply savory gravy that marries the richness of concentrated stock with the brightness of dry white wine and sherry vinegar. Fresh rosemary, sage, and thyme infuse the sauce with aromatic warmth, making it the perfect stress-free foundation for holiday meals.', 'sauce', 'American', 'Easy', '["sauces and gravies", "dry white wine", "make-ahead", "rosemary", "sage", "sherry vinegar", "stovetop", "thyme", "easy", "thanksgiving"]', '[{"group_name": "Roux Base & Aromatics", "items": [{"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 60, "unit": "g", "preparation": null, "notes": "standard plain flour", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "approx. 40g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Liquids & Herbs", "items": [{"name": "dry white wine", "quantity": 120, "unit": "ml", "preparation": null, "notes": "Sauvignon Blanc or Pinot Grigio recommended", "substitutions": [], "ingredient_id": "0c041362-befe-4c15-88d2-ba97c8f46428", "nutrition_source": "USDA FoodData Central"}, {"name": "high-quality chicken or turkey stock", "quantity": 750, "unit": "ml", "preparation": "warmed", "notes": "Use a concentrated stock or bone broth for best results", "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh thyme", "quantity": 4, "unit": null, "preparation": "whole sprigs", "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh sage", "quantity": 3, "unit": null, "preparation": "whole leaves", "notes": null, "substitutions": [], "ingredient_id": "2babed06-aae7-4e90-8b4a-14acbde2f522", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh rosemary", "quantity": 1, "unit": null, "preparation": "whole sprig", "notes": null, "substitutions": [], "ingredient_id": "fa90a3a7-86cd-40de-8f8c-0464231925c2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "sherry vinegar", "quantity": 10, "unit": "ml", "preparation": null, "notes": "adds essential acidity", "substitutions": [], "ingredient_id": "dcfa7371-7051-4604-a76e-4a46ae1f9e7b", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Melt the butter in a heavy-bottomed saucepan over medium heat. Add the minced shallot and saut\u00e9 until translucent and softened, but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": "PT3M", "doneness_cues": {"visual": "Shallots are translucent and soft", "tactile": "Soft texture"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Sprinkle the flour over the butter and shallots. Whisk constantly for 2-3 minutes to cook out the raw flour taste. The roux should smell nutty and take on a pale blonde color.", "structured": {"action": "MIX", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Pale gold color", "tactile": "Smooth paste bubbling gently"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Pour in the white wine while whisking vigorously to deglaze the pan. Continue whisking until the mixture forms a thick, smooth paste.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Slowly stream in the warm stock, whisking constantly to prevent lumps. Add the sprigs of thyme, sage, and rosemary.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Bring the mixture to a gentle simmer. Reduce heat to low and let it bubble gently until thickened to a gravy consistency that coats the back of a spoon.", "structured": {"action": "SIMMER", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT15M", "doneness_cues": {"visual": "Coats the back of a spoon (nappe)", "tactile": "Thickened liquid"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove from heat. Strain the gravy through a fine-mesh sieve into a clean bowl or storage container to remove the herbs and shallots for a silky smooth texture.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Stir in the sherry vinegar. Taste and season with salt and freshly cracked black pepper. If making ahead, cool completely before refrigerating.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT15M", "total_time": "PT30M", "overnight_required": false, "yields": "600ml", "yield_count": 10, "serving_size_g": 60}', '{"flags": ["Nut-Free", "Peanut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": ["Those avoiding alcohol (wine)", "Gluten-intolerant (contains wheat flour)"]}', '{"per_serving": {"calories": 102.01, "protein_g": 2.38, "carbohydrates_g": 8.19, "fat_g": 6.51, "saturated_fat_g": 3.05, "trans_fat_g": null, "monounsaturated_fat_g": 1.41, "polyunsaturated_fat_g": 0.21, "fiber_g": 0.62, "sugar_g": 0.35, "sodium_mg": 3079.48, "cholesterol_mg": 12.9, "potassium_mg": 32.39, "calcium_mg": 14.28, "iron_mg": 0.48, "magnesium_mg": 5.44, "phosphorus_mg": 11.28, "zinc_mg": 0.11, "vitamin_a_mcg": 42.86, "vitamin_c_mg": 1.48, "vitamin_d_mcg": null, "vitamin_e_mg": 0.15, "vitamin_k_mcg": 0.63, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": 0.01, "thiamin_mg": 0.01, "riboflavin_mg": 0.01, "niacin_mg": 0.1, "folate_mcg": 3.66, "water_g": 14.98, "alcohol_g": 1.07, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. The texture will become gelatinous when cold but returns to liquid when heated.", "duration": "P4D"}, "freezer": {"notes": "Freeze in airtight bags or containers. Thaw overnight in the refrigerator before reheating.", "duration": "P3M"}, "reheating": "Reheat gently on the stove over low heat, whisking constantly. Add a splash of stock or water if too thick.", "does_not_keep": false}', '[{"name": "Heavy-bottomed saucepan", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Fine-mesh sieve", "required": true, "alternative": "Cheesecloth"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Lumps in the gravy", "likely_cause": "Stock was added too quickly or not whisked vigorously enough", "prevention": "Add stock in a slow, steady stream while whisking constantly", "fix": "Pass the gravy through a fine-mesh sieve or blitz briefly with an immersion blender"}]', '["The secret to a ''roast-level'' flavor without the roast is the sherry vinegar; its acidity cuts through the fat and mimics the complexity of wine-braised drippings.", "Using whole herb sprigs and straining them out later imparts the essential oils without leaving distracting woody bits in the final sauce.", "If you have turkey or chicken drippings on the day of serving, whisk them into this base gravy while reheating for an extra flavor boost.", "To make this vegetarian, substitute the poultry stock with a high-quality roasted vegetable stock or mushroom broth."]', '"While gravy is a ubiquitous element of the American Thanksgiving table, this recipe relies on the French technique of a ''velout\u00e9''\u2014a stock thickened with a roux. By preparing it in advance, home cooks can avoid the last-minute stress of managing pan drippings while the turkey rests."', 102.01);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('a0ba81f7-ad45-4de6-9cd7-d4324a87dda9', 'Market Garden Dog Biscuits', 'Crunchy, wholesome treats featuring flecks of vibrant orange carrot and fresh green parsley. The whole wheat base provides a nutty aroma and satisfying snap, while a hint of mozzarella adds savory appeal without overwhelming the palate. Excellent for breath freshening.', 'snack', 'American', 'Easy', '["american", "project", "flour", "mozzarella", "parsley", "dog treats", "healthy"]', '[{"group_name": "Base & Inclusions", "items": [{"name": "whole wheat flour", "quantity": 250, "unit": "g", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "af2661d8-b555-4fef-bdee-51a5190eda92", "nutrition_source": "USDA FoodData Central"}, {"name": "carrots", "quantity": 100, "unit": "g", "preparation": "finely grated", "notes": "approximately 1 large carrot", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "low-moisture mozzarella cheese", "quantity": 50, "unit": "g", "preparation": "shredded", "notes": null, "substitutions": [], "ingredient_id": "41aca251-8bbe-492d-9539-ba0ac6c15194", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 30, "unit": "g", "preparation": "finely chopped", "notes": "flat-leaf or curly", "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Binders", "items": [{"name": "egg", "quantity": 1, "unit": null, "preparation": "beaten", "notes": "large, approx 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 60, "unit": "ml", "preparation": null, "notes": "plus more if needed", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 180\u00b0C (350\u00b0F). Line a baking sheet with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, combine the whole wheat flour, grated carrots, shredded mozzarella, and chopped parsley. Stir to coat the wet ingredients in flour to prevent clumping.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a small separate vessel, whisk the egg, water, and olive oil together. Pour into the flour mixture.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "mix", "text": "Mix by hand or with a sturdy spoon until a stiff dough forms. If the dough is too crumbly, add water 1 teaspoon at a time until it holds together.", "structured": {"action": "KNEAD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "shape", "text": "Roll the dough out on a lightly floured surface to a thickness of approximately 6mm (1/4 inch). Cut into shapes using a cookie cutter.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Arrange biscuits on the prepared baking sheet. Bake for 25 to 30 minutes, or until the edges are golden brown and the surface feels dry.", "structured": {"action": "BAKE", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT30M", "doneness_cues": {"visual": "Golden brown edges", "tactile": "Hard to the touch"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Turn off the oven but leave the biscuits inside with the door slightly ajar to cool completely. This dehydrates the treats further for a better crunch.", "structured": {"action": "REST", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT30M", "total_time": "PT50M", "overnight_required": false, "yields": "24 biscuits", "yield_count": 24, "serving_size_g": 18}', '{"flags": ["Vegetarian", "Nut-Free", "Peanut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": ["Dogs with wheat allergies", "Dogs with lactose intolerance (contains small amount of cheese)"]}', '{"per_serving": {"calories": 56.92, "protein_g": 1.84, "carbohydrates_g": 8.37, "fat_g": 2.08, "saturated_fat_g": 0.52, "trans_fat_g": 0.02, "monounsaturated_fat_g": 1.14, "polyunsaturated_fat_g": 0.32, "fiber_g": 1.52, "sugar_g": 0.36, "sodium_mg": 20.81, "cholesterol_mg": 9.08, "potassium_mg": 68.12, "calcium_mg": 22.29, "iron_mg": 0.53, "magnesium_mg": 14.15, "phosphorus_mg": 51.37, "zinc_mg": 0.43, "vitamin_a_mcg": 48.12, "vitamin_c_mg": 1.91, "vitamin_d_mcg": 0.05, "vitamin_e_mg": 0.3, "vitamin_k_mcg": 22.03, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": 0.05, "thiamin_mg": 0.04, "riboflavin_mg": 0.04, "niacin_mg": 0.62, "folate_mcg": 7.15, "water_g": 11.14, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container to maintain crispness.", "duration": "P2W"}, "freezer": {"notes": "Thaw completely before serving.", "duration": "P3M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Box grater", "required": true, "alternative": null}, {"name": "Rolling pin", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Cookie cutter", "required": true, "alternative": "Knife (to cut squares)"}]', '[{"symptom": "Dough is too sticky to roll", "likely_cause": "Excess moisture from the carrots", "prevention": "Pat grated carrots dry with a paper towel before mixing", "fix": "Incorporate additional flour 1 tablespoon at a time until manageable"}]', '["Parsley is a natural breath freshener for dogs, but ensure you use culinary parsley (Petroselinum crispum), not spring parsley which can be toxic.", "For older dogs with dental issues, reduce bake time by 5 minutes to create a softer, chewier biscuit.", "Always grate carrots finely; large chunks can cause the biscuit to break apart during rolling and may create hot spots during baking.", "No preservatives are used here, so unlike store-bought treats, these must be refrigerated or frozen if not consumed within a few days."]', '"The commercial dog biscuit originated in London in the mid-19th century when James Spratt observed stray dogs eating hardtack. This homemade iteration returns to those wholesome roots, utilizing American pantry staples to create a preservative-free alternative to mass-market kibble."', 56.92);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('a0c4da1c-e50d-4608-b2ef-548cb69c0db4', 'Turnip and Potato Puree', 'A velvety, comforting mash that balances the earthy, slightly peppery bite of turnips with the creamy, neutral fluffiness of potatoes. Enriched generously with butter, this simple side dish highlights the natural sweetness of fall root vegetables.', 'side dish', 'American', 'Easy', '["five ingredient", "potato", "turnip", "side dish", "fall", "vegetarian", "thanksgiving", "gluten-free"]', '[{"group_name": "Root Vegetables", "items": [{"name": "potatoes", "quantity": 500, "unit": "g", "preparation": "peeled and cut into 2cm cubes", "notes": "Starchy variety like Russet or Yukon Gold", "substitutions": [], "ingredient_id": "5bf06478-4785-465e-9842-f70a24e22054", "nutrition_source": "USDA FoodData Central"}, {"name": "turnips", "quantity": 500, "unit": "g", "preparation": "peeled and cut into 2cm cubes", "notes": "Purple top turnips preferred", "substitutions": [], "ingredient_id": "b7a26052-3b0b-4df2-b816-9a3dd3c2fb32", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Seasoning & Fat", "items": [{"name": "unsalted butter", "quantity": 80, "unit": "g", "preparation": "cubed, room temperature", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 6, "unit": "g", "preparation": null, "notes": "plus more for boiling water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the peeled and cubed potatoes and turnips in a large pot. Cover with cold water by at least 2.5 cm (1 inch) and season the water generously with salt.", "structured": {"action": "MEASURE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Bring the water to a boil over high heat, then reduce to a simmer. Cook for 15-20 minutes until both vegetables are completely tender and can be easily pierced with a fork.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT20M", "doneness_cues": {"visual": null, "tactile": "Fork-tender, falling apart slightly"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Drain the vegetables thoroughly in a colander. Return them to the hot, empty pot and set over low heat for 1-2 minutes to steam off excess moisture. Shake the pot occasionally to prevent sticking.", "structured": {"action": "DRAIN", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Vegetables look dry and chalky on the surface", "tactile": null}}, "tips": ["Removing excess water is crucial for a fluffy texture and prevents the puree from becoming watery."]}, {"step_number": 4, "phase": "assemble", "text": "Remove from heat. Add the cubed butter, salt, and black pepper. Mash the mixture using a potato masher or pass through a ricer for a smoother consistency.", "structured": {"action": "MASH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Taste and adjust seasoning if necessary. Serve immediately while hot.", "structured": {"action": "SERVE", "temperature": {"celsius": 60, "fahrenheit": 140}, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT20M", "total_time": "PT40M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 250}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": ["Vegans (contains butter)"]}', '{"per_serving": {"calories": 251.53, "protein_g": 4.53, "carbohydrates_g": 23.71, "fat_g": 16.48, "saturated_fat_g": 10.15, "trans_fat_g": null, "monounsaturated_fat_g": 4.7, "polyunsaturated_fat_g": 0.72, "fiber_g": 5.44, "sugar_g": 4.76, "sodium_mg": 680.5, "cholesterol_mg": 43, "potassium_mg": 763.25, "calcium_mg": 81.27, "iron_mg": 4.46, "magnesium_mg": 43.34, "phosphorus_mg": 86.45, "zinc_mg": 0.8, "vitamin_a_mcg": 136.87, "vitamin_c_mg": 40.5, "vitamin_d_mcg": null, "vitamin_e_mg": 0.51, "vitamin_k_mcg": 1.94, "vitamin_b6_mg": 0.41, "vitamin_b12_mcg": 0.04, "thiamin_mg": 0.08, "riboflavin_mg": 0.09, "niacin_mg": 1.8, "folate_mcg": 40.64, "water_g": 222.28, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container.", "duration": "P4D"}, "freezer": {"notes": "Texture may become slightly grainy; reheat gently with a splash of milk or water.", "duration": "P2M"}, "reheating": "Reheat on the stove over low heat, stirring frequently, or microwave in short intervals.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Potato masher", "required": true, "alternative": "Potato ricer or food mill"}, {"name": "Vegetable peeler", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}]', '[{"symptom": "Puree is watery or soupy", "likely_cause": "Vegetables were not drained well enough or were not steam-dried after boiling", "prevention": "Ensure you return the drained vegetables to the hot pot to evaporate surface moisture before mashing", "fix": "Place the puree back in the pot over low heat and stir constantly to evaporate excess liquid, being careful not to scorch the bottom"}]', '["For an even richer flavor, you can brown the butter in a separate pan before adding it to the mash (Beurre Noisette).", "The ratio of turnip to potato can be adjusted; more potato yields a milder flavor, while more turnip increases the peppery bite.", "Using a food processor is not recommended as it can release too much starch from the potatoes, turning the puree gluey."]', '"Root vegetable mashes are a staple of Northern European and North American autumn cuisine. This dish, often called ''Neeps and Tatties'' in Scotland when served with haggis, was a practical way to make use of hardy storage crops during the colder months."', 251.53);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('a168c086-09df-4ea2-b5bc-b281c348f067', 'Simple Roasted Squash Wedges', 'Tender, caramelized winter squash wedges with crispy edges, highlighted by the earthy warmth of cumin or the aromatic sweetness of mace. A comforting side dish that celebrates natural sweetness.', 'side dish', 'American', 'Easy', '["cumin", "five ingredient", "squash", "quick", "side dish", "winter", "vegan", "vegetarian", "roast"]', '[{"group_name": "Vegetables", "items": [{"name": "winter squash", "quantity": 1, "unit": null, "preparation": "whole", "notes": "approx. 800g; acorn, delicata, or small butternut", "substitutions": [], "ingredient_id": "c5268e75-29ce-4bfa-ada6-4210fa85e6b5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Seasoning", "items": [{"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": "liquid", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 2, "unit": "g", "preparation": null, "notes": "optional", "substitutions": ["ground mace", "nutmeg", "cinnamon"], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 200\u00b0C (400\u00b0F). Ensure the oven rack is in the center position.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Wash the squash thoroughly. Carefully cut it in half lengthwise using a sharp chef''s knife. Use a spoon to scrape out the seeds and stringy pulp.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": {"visual": "Seeds fully removed", "tactile": null}}, "tips": ["If the squash is too hard to cut, microwave it whole for 2-3 minutes to soften the skin slightly."]}, {"step_number": 3, "phase": "prep", "text": "Slice the squash halves into wedges approximately 2-3 cm thick.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In a large mixing bowl, toss the squash wedges with olive oil, salt, black pepper, and optional ground cumin (or mace) until evenly coated.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Arrange the wedges in a single layer on a baking sheet. Do not overcrowd the pan to ensure roasting rather than steaming.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Roast at 200\u00b0C (400\u00b0F) for 15 minutes. Remove the pan, carefully flip the wedges, and return to the oven.", "structured": {"action": "ROAST", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Continue roasting for another 10-15 minutes until the squash is tender when pierced with a fork and the edges are browned.", "structured": {"action": "ROAST", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": "Golden brown edges", "tactile": "Fork tender"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Transfer to a serving platter and serve immediately.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT30M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Paleo", "Whole30"], "not_suitable_for": []}', '{"per_serving": {"calories": 136.8, "protein_g": 2.02, "carbohydrates_g": 17.56, "fat_g": 7.88, "saturated_fat_g": 1.11, "trans_fat_g": null, "monounsaturated_fat_g": 5.57, "polyunsaturated_fat_g": 0.93, "fiber_g": 3.12, "sugar_g": 4.42, "sodium_mg": 494.04, "cholesterol_mg": null, "potassium_mg": 712.45, "calcium_mg": 62.14, "iron_mg": 1.57, "magnesium_mg": 30.27, "phosphorus_mg": 48.89, "zinc_mg": 0.45, "vitamin_a_mcg": 136.39, "vitamin_c_mg": 24.64, "vitamin_d_mcg": null, "vitamin_e_mg": 1.34, "vitamin_k_mcg": 7.15, "vitamin_b6_mg": 0.32, "vitamin_b12_mcg": null, "thiamin_mg": 0.06, "riboflavin_mg": 0.12, "niacin_mg": 1.02, "folate_mcg": 48.09, "water_g": 179.68, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container.", "duration": "P4D"}, "freezer": {"notes": "Texture may become mushy upon thawing; best used in soups if frozen.", "duration": "P2M"}, "reheating": "Reheat in a 180\u00b0C (350\u00b0F) oven or air fryer for 5-10 minutes to restore texture.", "does_not_keep": false}', '[{"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Spoon", "required": true, "alternative": "Ice cream scoop (for removing seeds)"}]', '[{"symptom": "Squash is soggy, not crispy", "likely_cause": "Pan was overcrowded", "prevention": "Use two baking sheets if necessary to leave space between wedges", "fix": "Increase oven temperature to 220\u00b0C (425\u00b0F) or use convection mode for the last 5 minutes"}, {"symptom": "Squash is burnt on the outside but hard inside", "likely_cause": "Oven temperature too high or wedges cut too thick", "prevention": "Cut uniform wedges under 3cm thick", "fix": "Lower heat to 175\u00b0C (350\u00b0F) and cover loosely with foil to finish cooking through"}]', '["Acorn and delicata squash skins are edible and delicious when roasted. If using butternut squash, you may prefer to peel it first as the skin is tougher.", "Save the seeds! They can be rinsed, dried, and roasted separately for a crunchy snack.", "Mace offers a lighter, more citrus-like version of nutmeg flavor which pairs beautifully with the natural sugars in winter squash.", "For easier cleanup, line your baking sheet with parchment paper, though direct contact with the metal pan yields better browning."]', '"Winter squash has been a fundamental crop in the Americas for thousands of years, serving as one of the ''Three Sisters'' in Indigenous agriculture alongside corn and beans. Roasting is a traditional method that intensifies the vegetable''s natural sweetness, making it a staple of autumn and winter harvests."', 136.8);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('a2187ec1-2590-46d4-b29a-9496928024dd', 'Classic Buttered Parsley New Potatoes', 'Tender, waxy new potatoes enveloped in a glossy coat of melted butter and vibrant fresh parsley. The earthy sweetness of the spring harvest shines through in this simple, comforting side dish.', 'side dish', 'British', 'Easy', '["five ingredient", "new potato", "parsley", "easy", "side dish", "spring", "summer", "gluten-free", "nut-free", "vegetarian"]', '[{"group_name": "Main", "items": [{"name": "new potatoes", "quantity": 1000, "unit": "g", "preparation": "scrubbed whole", "notes": "choose small, uniform sizes like Jersey Royals", "substitutions": ["baby red potatoes", "fingerling potatoes"], "ingredient_id": "27826138-6473-4c3a-8516-9dfe87599f69", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 50, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": ["vegan butter block", "olive oil"], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "finely chopped", "notes": "flat-leaf preferred", "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 5g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Scrub the potatoes gently under cold running water to remove dirt without damaging the delicate skin. Leave whole if small, or halve larger ones to ensure even cooking.", "structured": {"action": "PEEL", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Place potatoes in a large pot and cover with cold water by at least 2cm. Add a generous pinch of salt. Bring to a boil over high heat, then reduce to a simmer.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Simmer gently for 10-15 minutes until tender. A knife should slide through the center with zero resistance.", "structured": {"action": "SIMMER", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT15M", "doneness_cues": {"visual": null, "tactile": "Knife meets no resistance"}}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Drain the potatoes in a colander. Immediately return them to the hot, empty pot and let them sit off the heat for 1-2 minutes. This ''steam drying'' step ensures the butter clings properly.", "structured": {"action": "DRAIN", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": ["Do not rinse with cold water; you want the residual heat to melt the butter."]}, {"step_number": 5, "phase": "finish", "text": "Add the butter, chopped parsley, and black pepper to the pot. Toss gently until the butter melts and coats every potato.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Taste and adjust salt if necessary. Serve immediately while hot.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT20M", "total_time": "PT30M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 265}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Egg-Free", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 304.73, "protein_g": 5.27, "carbohydrates_g": 44.57, "fat_g": 10.44, "saturated_fat_g": 6.33, "trans_fat_g": null, "monounsaturated_fat_g": 2.94, "polyunsaturated_fat_g": 0.39, "fiber_g": 6.75, "sugar_g": 0.04, "sodium_mg": 493.58, "cholesterol_mg": 26.88, "potassium_mg": 1155.53, "calcium_mg": 23.19, "iron_mg": 1.54, "magnesium_mg": 52.99, "phosphorus_mg": 130.97, "zinc_mg": 0.81, "vitamin_a_mcg": 101.42, "vitamin_c_mg": 44.99, "vitamin_d_mcg": null, "vitamin_e_mg": 0.32, "vitamin_k_mcg": 63.2, "vitamin_b6_mg": 0.01, "vitamin_b12_mcg": 0.02, "thiamin_mg": 0.01, "riboflavin_mg": 0.01, "niacin_mg": 0.06, "folate_mcg": 6.16, "water_g": 5.38, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Butter may solidify.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; texture becomes mealy.", "duration": null}, "reheating": "Gently reheat in a pan over low heat with a splash of water, or microwave.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Potatoes are falling apart", "likely_cause": "Overcooked or boiled too vigorously", "prevention": "Use waxy potato varieties and simmer gently rather than rolling boil", "fix": "Mash them with the butter and parsley for a smashed potato side instead"}, {"symptom": "Butter slides off, dish is watery", "likely_cause": "Potatoes were not steam-dried effectively", "prevention": "Allow potatoes to sit in the hot pot after draining to evaporate excess moisture", "fix": "Return pot to very low heat for 1 minute to evaporate liquid while tossing"}]', '["The secret to restaurant-quality new potatoes is the ''steam dry'': allowing moisture to evaporate from the hot skins before adding fat.", "Always start root vegetables in cold water; this ensures the center cooks at the same rate as the exterior.", "If using Jersey Royals or very fresh local potatoes, leave the skins on for maximum earthy flavor and nutrient retention.", "Mint is a classic British alternative or addition to parsley in this dish."]', '"In the United Kingdom and Ireland, the arrival of ''new potatoes'' (the first harvest of the season) is a culinary event. Often served simply with butter and herbs, they celebrate the transition from winter root vegetables to spring produce."', 304.73);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('a3866ce9-f341-49d3-b4d0-51d61fc5c59b', 'Mediterranean Broiled Feta & Vegetables', 'A rapid, high-heat sheet pan meal where bursting cherry tomatoes and tender zucchini create a natural sauce for warm, creamy feta. The broiler adds a smoky char and caramelization in minutes.', 'dinner', 'Mediterranean', 'Easy', '["vegetables", "cherry tomato", "feta", "grape tomato", "sheet-pan", "zucchini", "dinner", "easy", "lunch", "quick", "snack", "weeknight", "appetizer", "side", "summer", "vegetarian"]', '[{"group_name": "Vegetables & Cheese", "items": [{"name": "zucchini", "quantity": 500, "unit": "g", "preparation": "sliced into half-moons", "notes": "approx. 2-3 medium zucchini", "substitutions": [], "ingredient_id": "d0aa0d47-cefe-4ece-a337-e656f79b74e9", "nutrition_source": "Aggregated Public Data"}, {"name": "cherry tomatoes", "quantity": 300, "unit": "g", "preparation": "whole", "notes": "or grape tomatoes", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "feta cheese", "quantity": 200, "unit": "g", "preparation": "block", "notes": "sliced into two 2cm thick slabs or large chunks", "substitutions": [], "ingredient_id": "a9a8605c-3bf2-4ca3-8c58-80e87aff7cd8", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Marinade & Finish", "items": [{"name": "olive oil", "quantity": 45, "unit": "ml", "preparation": "extra virgin", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx. 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx. 1 tsp", "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "red pepper flakes", "quantity": 1, "unit": "g", "preparation": null, "notes": "optional, for heat", "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "adjust sparingly as feta is salty", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": "zested and juiced", "notes": null, "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh basil", "quantity": 10, "unit": "g", "preparation": "torn", "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Position an oven rack about 15-20cm (6-8 inches) from the heating element and preheat the broiler (grill setting) to high.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 260, "fahrenheit": 500}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, combine the sliced zucchini, whole cherry tomatoes, olive oil, minced garlic, dried oregano, red pepper flakes, salt, and black pepper. Toss vigorously until the vegetables are evenly coated in the oil and spices.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "assemble", "text": "Spread the vegetable mixture onto a rimmed baking sheet in a single even layer. Create clear spaces in the center and nestle the blocks of feta cheese directly onto the pan, ensuring they make contact with the metal.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Place the sheet pan under the broiler. Broil for 10-15 minutes, rotating the pan halfway through, until the zucchini is tender, the tomatoes have burst, and the feta is browned and starting to melt.", "structured": {"action": "BROIL", "temperature": null, "duration": "PT12M", "doneness_cues": {"visual": "Tomatoes burst, feta browned at edges, zucchini charred", "tactile": "Zucchini tender when pierced"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove from the oven. immediately zest the lemon over the hot tray and squeeze half the lemon juice over the vegetables. Garnish with fresh torn basil before serving.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT15M", "total_time": "PT25M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 260}', '{"flags": ["Vegetarian", "Gluten-Free", "Low-Carb", "Keto", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Low-Sodium diets"]}', '{"per_serving": {"calories": 280.52, "protein_g": 9.91, "carbohydrates_g": 13.05, "fat_g": 22.57, "saturated_fat_g": 8.25, "trans_fat_g": null, "monounsaturated_fat_g": 10.54, "polyunsaturated_fat_g": 1.55, "fiber_g": 3.66, "sugar_g": 6.05, "sodium_mg": 781.76, "cholesterol_mg": 44.5, "potassium_mg": 275.29, "calcium_mg": 280.45, "iron_mg": 1.1, "magnesium_mg": 24.15, "phosphorus_mg": 198.91, "zinc_mg": 1.66, "vitamin_a_mcg": 75.01, "vitamin_c_mg": 23.36, "vitamin_d_mcg": 0.2, "vitamin_e_mg": 1.94, "vitamin_k_mcg": 21.83, "vitamin_b6_mg": 0.29, "vitamin_b12_mcg": 0.85, "thiamin_mg": 0.09, "riboflavin_mg": 0.44, "niacin_mg": 0.62, "folate_mcg": 21.64, "water_g": 51.12, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. The feta will firm up upon cooling.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; zucchini becomes mushy and feta texture degrades.", "duration": null}, "reheating": "Reheat gently in a 180\u00b0C/350\u00b0F oven for 10 minutes or microwave briefly.", "does_not_keep": false}', '[{"name": "Rimmed baking sheet", "required": true, "alternative": "Large roasting pan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}]', '[{"symptom": "Garlic is burnt and bitter", "likely_cause": "Minced garlic pieces were left exposed on top of the vegetables under direct broiler heat", "prevention": "Ensure garlic is thoroughly mixed with the oil or tucked underneath zucchini slices before broiling", "fix": "Scrape off visible black garlic bits; add a pinch of sugar to the sauce to counteract bitterness"}, {"symptom": "Watery sauce on the pan", "likely_cause": "Zucchini released excess water or pan was overcrowded, causing steaming", "prevention": "Use a large enough sheet pan to allow air circulation; salt zucchini 10 mins prior and pat dry if using very large squash", "fix": "Remove solids to a serving platter, pour liquid into a small pot and reduce on stove for 2 mins"}]', '["Always use a block of feta in brine. Pre-crumbled feta contains cellulose (anti-caking agents) that prevents it from melting into a creamy consistency.", "Do not walk away while broiling. The difference between ''perfectly charred'' and ''burnt'' is often less than 60 seconds under high heat.", "Serve immediately with crusty sourdough bread to mop up the ''liquid gold''\u2014the emulsion of olive oil, tomato juices, and warm feta whey.", "If you want to turn this into a heartier meal, stir in cooked orzo or chickpeas directly on the sheet pan right after removing it from the oven."]', '"This recipe draws inspiration from Greek ''Bouyiourdi'', a traditional spicy baked feta appetizer often served in clay pots. This version adapts the concept for the American sheet-pan dinner method, utilizing the broiler to mimic the intense heat of a wood-fired oven."', 280.52);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('a39007cc-9142-4e7c-b459-cb54d3c83b80', 'Kourabiedes (Greek Butter Cookies)', 'Traditional Greek shortbread cookies characterized by a melt-in-your-mouth texture, rich butter flavor, and crunchy toasted almonds, all buried under a snow-like mound of powdered sugar.', 'baked good', 'Greek', 'Intermediate', '["greek", "butter", "dessert", "winter", "cookies", "christmas", "shortbread"]', '[{"group_name": "Dough Base", "items": [{"name": "unsalted butter", "quantity": 250, "unit": "g", "preparation": "room temperature", "notes": "High fat content European butter preferred", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "icing sugar", "quantity": 60, "unit": "g", "preparation": null, "notes": "Powdered sugar", "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "egg yolk", "quantity": 1, "unit": null, "preparation": null, "notes": "large, approx 18g", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}, {"name": "brandy", "quantity": 15, "unit": "ml", "preparation": null, "notes": "Or cognac; helps with crispness", "substitutions": ["Orange juice", "Vanilla extract"], "ingredient_id": "cf43659a-78aa-4577-bdaa-2422290aa000", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dry Ingredients & Add-ins", "items": [{"name": "all-purpose flour", "quantity": 450, "unit": "g", "preparation": null, "notes": "May need up to 500g depending on humidity", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "almonds", "quantity": 100, "unit": "g", "preparation": "whole or slivered", "notes": null, "substitutions": [], "ingredient_id": "5bcbb4d4-6845-4825-bd21-1c13e52b989c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Coating", "items": [{"name": "icing sugar", "quantity": 300, "unit": "g", "preparation": null, "notes": "For dusting/dredging", "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Spread almonds on a baking sheet and toast in an oven at 180\u00b0C/350\u00b0F for 8-10 minutes until fragrant. Let them cool completely, then roughly chop.", "structured": {"action": "TOAST", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT10M", "doneness_cues": {"visual": "Light golden brown", "tactile": "Crunchy"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Preheat oven to 170\u00b0C/340\u00b0F. Line two large baking sheets with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a stand mixer, whip the room temperature butter on high speed for at least 10-15 minutes until it turns white and resembles whipped cream. This aeration is crucial for the texture.", "structured": {"action": "WHIP", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": "Bright white color, fluffy texture", "tactile": null}}, "tips": ["Do not rush this step; yellow butter means dense cookies."]}, {"step_number": 4, "phase": "prep", "text": "Add the icing sugar (60g), egg yolk, brandy, and vanilla. Mix on medium speed for 2 minutes until fully incorporated.", "structured": {"action": "MIX", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Switch to low speed or mix by hand. Gradually add the flour and baking powder, followed by the chopped almonds. Stop mixing immediately when a soft dough forms; do not knead.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Soft, pliable, non-sticky dough"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Shape dough into small rounds or crescents (about 25g each). Place on baking sheets 2cm apart. Bake for 15-20 minutes. They should remain pale but be set.", "structured": {"action": "BAKE", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": "PT20M", "doneness_cues": {"visual": "Very light golden tint on bottom only", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Let cookies cool on the baking sheet for 5-10 minutes. While still warm (but not hot), transfer carefully to a surface covered with icing sugar. Sift more sugar generously over the top to bury them.", "structured": {"action": "DREDGE", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT1H", "total_time": "PT1H45M", "overnight_required": false, "yields": "30 cookies", "yield_count": 30, "serving_size_g": 35}', '{"flags": ["Vegetarian", "Soy-Free", "Peanut-Free"], "not_suitable_for": ["Nut allergies", "Gluten intolerance", "Alcohol restriction (contains brandy)"]}', '{"per_serving": {"calories": 183.97, "protein_g": 2.42, "carbohydrates_g": 24.23, "fat_g": 8.73, "saturated_fat_g": 4.42, "trans_fat_g": null, "monounsaturated_fat_g": 3.09, "polyunsaturated_fat_g": 0.75, "fiber_g": 0.82, "sugar_g": 11.95, "sodium_mg": 15.95, "cholesterol_mg": 24.4, "potassium_mg": 43.65, "calcium_mg": 21.97, "iron_mg": 0.34, "magnesium_mg": 12.55, "phosphorus_mg": 39.5, "zinc_mg": 0.23, "vitamin_a_mcg": 59.29, "vitamin_c_mg": null, "vitamin_d_mcg": 0.03, "vitamin_e_mg": 1.07, "vitamin_k_mcg": 0.63, "vitamin_b6_mg": 0.01, "vitamin_b12_mcg": 0.03, "thiamin_mg": 0.03, "riboflavin_mg": 0.05, "niacin_mg": 0.31, "folate_mcg": 6.49, "water_g": 3.72, "alcohol_g": 0.06, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Not recommended as humidity affects the powdered sugar coating.", "duration": null}, "freezer": {"notes": "Freeze baked cookies without powdered sugar coating. Thaw and sugar before serving.", "duration": "P3M"}, "reheating": "Do not reheat once sugared.", "does_not_keep": false}', '[{"name": "Stand mixer with paddle attachment", "required": true, "alternative": "Electric hand mixer"}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Sieve or sifter", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}]', '[{"symptom": "Cookies crumble into dust when touched", "likely_cause": "Cookies were handled while too hot or dough lacked binding moisture", "prevention": "Allow cookies to cool for at least 5-10 minutes on the tray before moving them to the sugar", "fix": "Let them cool completely on the tray, then sift sugar over them without lifting"}]', '["The secret to the ''melt-in-your-mouth'' texture is whipping the butter until it is completely white before adding other ingredients.", "Using clarified butter (ghee) or sheep''s milk butter offers a more authentic, nutty flavor profile.", "If the dough is too sticky to shape, chill it in the fridge for 20 minutes.", "Do not overbake; these cookies should not brown significantly on top, or they will become hard rather than sandy.", "The brandy acts as a tenderizer by inhibiting gluten formation, contributing to the crumbly texture."]', '"Kourabiedes are the quintessential Greek celebration cookie, ubiquitous during Christmas, Easter, and weddings. Their white, sugar-coated appearance symbolizes purity and good fortune. While families often have their own secret variations, the core of butter and almonds remains constant across Greece."', 183.97);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('a3ae6fe3-8eeb-4fc1-9ace-c87311247593', 'Spicy Jalapeño and Mint Sautéed Squid', 'Tender rings of squid flash-seared with fresh jalapeño and garlic, finished with a burst of bright lemon and cool mint. This dish balances heat, acidity, and herbaceous freshness for a vibrant light dinner.', 'dinner', 'Mediterranean Fusion', 'Easy', '["jalape\u00f1o", "mint", "squid", "dinner", "quick", "weeknight", "seafood", "spicy", "healthy"]', '[{"group_name": "Squid", "items": [{"name": "squid tubes and tentacles", "quantity": 400, "unit": "g", "preparation": "cleaned, tubes sliced into 1cm rings", "notes": "Use fresh if possible, or fully thawed", "substitutions": [], "ingredient_id": "e126ab3d-72fc-463a-a50c-461c65ccdf4d", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": "fine sea salt", "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics & Cooking", "items": [{"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": "extra virgin", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "thinly sliced", "notes": "about 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "jalape\u00f1o pepper", "quantity": 1, "unit": null, "preparation": "thinly sliced into rounds, seeds removed for less heat", "notes": "about 15-20g", "substitutions": [], "ingredient_id": "2b2a83e9-b050-460c-8f0d-5f7b46dc242f", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Finish", "items": [{"name": "fresh mint leaves", "quantity": 10, "unit": "g", "preparation": "roughly torn", "notes": null, "substitutions": [], "ingredient_id": "213e3d3b-d332-45a9-b35e-23ee29a27173", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Thoroughly pat the squid rings and tentacles dry with paper towels. This is critical to ensure they sear rather than steam.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["If the squid is wet, it will release liquid in the pan and become rubbery."]}, {"step_number": 2, "phase": "cook", "text": "Heat the olive oil in a large skillet or wok over high heat until it just begins to smoke (approx. 200\u00b0C/390\u00b0F).", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the squid in a single layer (work in batches if necessary to avoid overcrowding). Season immediately with salt and pepper. Saut\u00e9 vigorously for 1 minute until the squid turns opaque.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Squid turns opaque white", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the sliced garlic and jalape\u00f1o to the pan. Continue to saut\u00e9 for another 30-60 seconds until fragrant and the aromatics are softened, but not browned. Ensure the squid reaches an internal temperature of 63\u00b0C/145\u00b0F, though visual cues of opacity are reliable here.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 63, "fahrenheit": 145}, "duration": "PT45S", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove from heat immediately. Toss with the fresh lemon juice and torn mint leaves. Serve immediately.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT0M", "total_time": "PT15M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 225}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Low-Carb", "Keto", "Paleo", "Whole30", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 333.07, "protein_g": 31.87, "carbohydrates_g": 9.98, "fat_g": 17.9, "saturated_fat_g": 2.82, "trans_fat_g": null, "monounsaturated_fat_g": 11.18, "polyunsaturated_fat_g": 2.66, "fiber_g": 0.91, "sugar_g": 0.62, "sodium_mg": 673.15, "cholesterol_mg": 466, "potassium_mg": 577.47, "calcium_mg": 88.38, "iron_mg": 1.85, "magnesium_mg": 72.93, "phosphorus_mg": 454.69, "zinc_mg": 3.19, "vitamin_a_mcg": 30.74, "vitamin_c_mg": 15.46, "vitamin_d_mcg": null, "vitamin_e_mg": 4.58, "vitamin_k_mcg": 9.94, "vitamin_b6_mg": 0.19, "vitamin_b12_mcg": 2.6, "thiamin_mg": 0.06, "riboflavin_mg": 0.84, "niacin_mg": 4.49, "folate_mcg": 17.43, "water_g": 171.06, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Texture may become rubbery upon reheating; best eaten fresh.", "duration": "P2D"}, "freezer": {"notes": "Not recommended for freezing after cooking.", "duration": null}, "reheating": "Briefly saut\u00e9 over high heat for 30 seconds, just to warm through.", "does_not_keep": false}', '[{"name": "Large skillet or wok", "required": true, "alternative": "Cast iron pan"}, {"name": "Paper towels", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Squid is rubbery and tough", "likely_cause": "Overcooking or overcrowding the pan caused steaming instead of searing", "prevention": "Cook on very high heat for less than 2 minutes total; dry squid thoroughly before cooking", "fix": "Cannot be fixed to restore tenderness; slice very thinly to make it palatable"}]', '["The secret to tender squid is cooking it very quickly (under 2 minutes) or very slowly (over 30 minutes). This recipe relies on the ''quick'' method.", "Do not add the garlic at the very beginning, or the high heat required for the squid will burn the garlic before the seafood is done.", "Mint adds a surprising cooling effect that counters the jalape\u00f1o heat; do not substitute with dried mint.", "Serve with crusty bread to soak up the spicy, citrus-infused oil."]', '"This dish draws inspiration from Mediterranean coastal cooking where fresh cephalopods are paired with bright acids and herbs, while the addition of jalape\u00f1o introduces a modern, global kick often found in Californian fusion cuisine."', 333.07);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('a68c1e79-c0b9-491d-884d-2187f2474fed', 'Cornmeal Barquettes with Whipped Goat Cheese and Roasted Pepper', 'Crisp, golden cornmeal shells offering a savory crunch, filled with a tangy, aerated goat cheese mousse. Finished with sweet, smoky roasted red pepper confetti and fresh thyme for a vibrant pop of color and complex flavor contrast.', 'appetizer', 'Modern American', 'Intermediate', '["appetizer", "vegetarian", "finger food", "party", "cornmeal", "summer", "make-ahead"]', '[{"group_name": "Cornmeal Shells", "items": [{"name": "all-purpose flour", "quantity": 125, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "fine yellow cornmeal", "quantity": 100, "unit": "g", "preparation": null, "notes": "Do not use coarse polenta", "substitutions": [], "ingredient_id": "46ca2aab-cb23-4397-9711-528c234b2cf8", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": "large", "notes": "approx 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "cold water", "quantity": 30, "unit": "ml", "preparation": null, "notes": "use only if needed to bind", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Whipped Goat Cheese", "items": [{"name": "fresh goat cheese", "quantity": 150, "unit": "g", "preparation": "softened", "notes": null, "substitutions": ["Feta (texture will be grainier)"], "ingredient_id": "b054244f-221b-4674-90f8-0a3896462f1f", "nutrition_source": "USDA FoodData Central"}, {"name": "cream cheese", "quantity": 50, "unit": "g", "preparation": "softened", "notes": null, "substitutions": [], "ingredient_id": "262c67de-76a4-4444-8c02-30ad4a179459", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1/2 lemon", "substitutions": [], "ingredient_id": "03fb65be-9b62-44e7-a121-694de64cdec0", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh thyme leaves", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Roasted Pepper Topping", "items": [{"name": "red bell pepper", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 200g before processing", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "Aggregated Public Data"}, {"name": "extra virgin olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "036c7254-3de5-4c6e-a2e7-366ad4d05077", "nutrition_source": "Aggregated Public Data"}, {"name": "sherry vinegar", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "dcfa7371-7051-4604-a76e-4a46ae1f9e7b", "nutrition_source": "Aggregated Public Data"}, {"name": "flaky sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste for garnish", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the whole bell pepper directly over a gas flame or under a broiler set to high. Char evenly until the skin is blackened and blistered on all sides.", "structured": {"action": "BROIL", "temperature": null, "duration": null, "doneness_cues": {"visual": "Blackened skin", "tactile": "Softened flesh"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Transfer the charred pepper to a bowl and cover tightly with plastic wrap to steam for 10 minutes. This loosens the skin.", "structured": {"action": "STEAM", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a food processor, pulse the flour, cornmeal, and salt. Add cold cubed butter and pulse until the mixture resembles coarse wet sand.", "structured": {"action": "BLEND", "temperature": null, "duration": null, "doneness_cues": {"visual": "Coarse crumbs", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Add the egg and pulse just until the dough comes together. If too dry, add cold water 1 teaspoon at a time. Form into a disk, wrap, and chill for 30 minutes.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Preheat oven to 190\u00b0C/375\u00b0F. Roll out dough to 3mm thickness. Press into barquette molds or mini muffin tins. Prick the bottoms with a fork (docking).", "structured": {"action": "PREHEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Bake the shells for 12-15 minutes until golden brown and crisp. Remove from molds and let cool completely on a wire rack.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT15M", "doneness_cues": {"visual": "Golden edges", "tactile": "Firm to touch"}}, "tips": []}, {"step_number": 7, "phase": "prep", "text": "Peel the skin off the steamed pepper, remove seeds, and finely dice the flesh (brunoise). Toss with olive oil and sherry vinegar.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "prep", "text": "Whip the goat cheese, cream cheese, heavy cream, lemon zest, and thyme together until light and fluffy. Transfer to a piping bag.", "structured": {"action": "WHIP", "temperature": null, "duration": null, "doneness_cues": {"visual": "Smooth and aerated", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "assemble", "text": "Pipe the goat cheese mixture into the cooled cornmeal shells. Top generously with the marinated red pepper mixture and finish with flaky salt.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT50M", "passive_time": "PT1H", "total_time": "PT1H50M", "overnight_required": false, "yields": "24 barquettes", "yield_count": 24, "serving_size_g": 35}', '{"flags": ["Vegetarian", "Soy-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": ["Vegans (contains dairy, eggs)", "Celiacs (contains wheat)"]}', '{"per_serving": {"calories": 95.93, "protein_g": 2.38, "carbohydrates_g": 5.52, "fat_g": 7.33, "saturated_fat_g": 4.22, "trans_fat_g": 0.04, "monounsaturated_fat_g": 1.82, "polyunsaturated_fat_g": 0.32, "fiber_g": 0.42, "sugar_g": 0.75, "sodium_mg": 113, "cholesterol_mg": 24.44, "potassium_mg": 44.66, "calcium_mg": 15.77, "iron_mg": 0.32, "magnesium_mg": 5.47, "phosphorus_mg": 35.82, "zinc_mg": 0.18, "vitamin_a_mcg": 79.32, "vitamin_c_mg": 11.09, "vitamin_d_mcg": 0.09, "vitamin_e_mg": 0.31, "vitamin_k_mcg": 0.97, "vitamin_b6_mg": 0.05, "vitamin_b12_mcg": 0.05, "thiamin_mg": 0.02, "riboflavin_mg": 0.05, "niacin_mg": 0.26, "folate_mcg": 9.09, "water_g": 20.76, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store components separately. Assembled barquettes will soften after 2-3 hours.", "duration": "P2D"}, "freezer": {"notes": "Baked unfilled shells can be frozen.", "duration": "P1M"}, "reheating": "Re-crisp shells in oven at 150\u00b0C/300\u00b0F for 5 minutes before filling.", "does_not_keep": false}', '[{"name": "Barquette molds or mini muffin tin", "required": true, "alternative": "Mini tart pans"}, {"name": "Food processor", "required": true, "alternative": "Pastry blender and mixing bowl"}, {"name": "Electric mixer", "required": true, "alternative": "Whisk and strong arm"}, {"name": "Rolling pin", "required": true, "alternative": null}, {"name": "Piping bag", "required": false, "alternative": "Ziploc bag with corner cut"}]', '[{"symptom": "Dough shells shrink significantly during baking", "likely_cause": "Dough was not chilled long enough or was stretched when placing in molds", "prevention": "Chill dough thoroughly; ease dough into corners without pulling", "fix": "Cannot be fixed once baked; fill generously to hide gaps"}, {"symptom": "Filling is runny", "likely_cause": "Cheese was too warm or over-mixed", "prevention": "Use cold heavy cream and room temperature cheese; stop whipping once fluffy", "fix": "Refrigerate mixture for 20 minutes to firm up before piping"}]', '["To achieve a cleaner presentation, dry the roasted peppers with a paper towel before tossing in oil, otherwise the red juices may bleed into the white cheese.", "The addition of cream cheese is crucial; pure goat cheese can be grainy and chalky. The cream cheese provides the necessary emulsion for a smooth mouthfeel.", "If you don''t have barquette molds, you can bake flat rounds of the dough to make savory cookies, then pipe the cheese on top for a ''canap\u00e9'' style presentation.", "For an extra kick, add a pinch of smoked paprika or cayenne pepper to the cornmeal dough."]', '"The ''barquette'' (little boat) is a classic French pastry shape, typically used for savory hors d''oeuvres or sweet petit fours. This recipe bridges French technique with ingredients central to the Americas\u2014corn (maize) and peppers\u2014creating a refined yet rustic bite suitable for modern entertaining."', 95.93);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('a771d9a4-d445-42f2-a21d-0359f9970249', 'Cinnamon Roll Scones', 'A delightful hybrid of flaky, buttery scones and gooey cinnamon rolls. These scones feature tender, cream-infused layers spiraled with brown sugar and cinnamon, finished with a sweet vanilla glaze that settles into the crevices.', 'baked good', 'American', 'Intermediate', '["american", "breakfast", "baked good", "scone", "dessert", "vegetarian", "nut-free", "comfort food"]', '[{"group_name": "Scone Dough", "items": [{"name": "all-purpose flour", "quantity": 250, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 12, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 160, "unit": "ml", "preparation": "cold", "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Cinnamon Filling", "items": [{"name": "light brown sugar", "quantity": 65, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 6, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "melted", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Glaze", "items": [{"name": "confectioners'' sugar", "quantity": 120, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 30, "unit": "ml", "preparation": null, "notes": "plus more for consistency", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 200\u00b0C/400\u00b0F. Line a baking sheet with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a small bowl, whisk together the brown sugar and ground cinnamon for the filling. Set aside.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a large bowl, whisk together the flour, granulated sugar, baking powder, and salt.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Add the cold, cubed butter to the flour mixture. Use a pastry blender or your fingertips to cut the butter in until the mixture resembles coarse crumbs with some pea-sized pieces of butter remaining.", "structured": {"action": "CUT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Do not overwork the butter; keeping it cold is essential for flaky layers."]}, {"step_number": 5, "phase": "prep", "text": "Pour in the cold heavy cream. Stir gently with a fork or spatula just until a shaggy dough forms. Do not overmix.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Turn the dough out onto a lightly floured surface. Gently knead 3-4 times to bring it together, then roll into a rectangle approximately 30cm x 20cm (12x8 inches).", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Brush the dough surface with the melted butter, leaving a small border at the edges. Sprinkle the cinnamon-sugar mixture evenly over the butter.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Starting from the long edge, roll the dough into a cylinder (log). Press the seam gently to seal. Slice the log into 8 equal rounds.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Use a sharp knife and a sawing motion to avoid squashing the spiral."]}, {"step_number": 9, "phase": "cook", "text": "Place scones on the prepared baking sheet, spaced 5cm apart. Bake for 18-22 minutes until golden brown and firm to the touch.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT20M", "doneness_cues": {"visual": "Golden brown edges and tops", "tactile": "Firm to the touch, not doughy"}}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "While scones bake, whisk confectioners'' sugar, vanilla, and heavy cream until smooth. Drizzle over warm scones before serving.", "structured": {"action": "GLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT15M", "total_time": "PT40M", "overnight_required": false, "yields": "8 scones", "yield_count": 8, "serving_size_g": 95}', '{"flags": ["Vegetarian", "Nut-Free", "Egg-Free"], "not_suitable_for": ["Vegans (contains dairy)"]}', '{"per_serving": {"calories": 442.32, "protein_g": 4.09, "carbohydrates_g": 54.82, "fat_g": 23.59, "saturated_fat_g": 14.67, "trans_fat_g": 0.29, "monounsaturated_fat_g": 6.43, "polyunsaturated_fat_g": 1.05, "fiber_g": 1.25, "sugar_g": 29.67, "sodium_mg": 316.3, "cholesterol_mg": 65.81, "potassium_mg": 76.07, "calcium_mg": 127.53, "iron_mg": 0.69, "magnesium_mg": 10.57, "phosphorus_mg": 85.57, "zinc_mg": 0.31, "vitamin_a_mcg": 221.7, "vitamin_c_mg": 0.17, "vitamin_d_mcg": 0.38, "vitamin_e_mg": 0.68, "vitamin_k_mcg": 2.36, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": 0.07, "thiamin_mg": 0.04, "riboflavin_mg": 0.07, "niacin_mg": 0.44, "folate_mcg": 9.74, "water_g": 20.99, "alcohol_g": 0.22, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in airtight container; texture is best when reheated.", "duration": "P3D"}, "freezer": {"notes": "Freeze unbaked shaped scones or baked unglazed scones.", "duration": "P2M"}, "reheating": "Warm in oven at 150\u00b0C/300\u00b0F for 5-8 minutes to restore crust.", "does_not_keep": false}', '[{"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Mixing bowl (large)", "required": true, "alternative": null}, {"name": "Pastry blender or fork", "required": true, "alternative": "Food processor (pulse setting)"}, {"name": "Rolling pin", "required": true, "alternative": null}, {"name": "Sharp knife or bench scraper", "required": true, "alternative": null}, {"name": "Pastry brush", "required": true, "alternative": null}]', '[{"symptom": "Scones are tough or rubbery", "likely_cause": "The dough was overworked or the butter melted during mixing", "prevention": "Handle the dough as little as possible and ensure ingredients are very cold", "fix": "Cannot be fixed after baking; serve warm with extra butter to mask texture"}, {"symptom": "Scones spread and lost their spiral shape", "likely_cause": "Butter was too warm before baking", "prevention": "Chill the shaped scones in the fridge for 15 minutes before putting them in the oven", "fix": "Use a round cutter to trim edges after baking for better presentation"}]', '["Ensure your heavy cream and butter are straight from the fridge. The steam generated by melting butter pockets creates the scone''s lift.", "If the dough feels too sticky to roll, dust your hands and the rolling pin with flour, but avoid adding too much excess flour to the dough itself.", "For a sharper presentation, you can cut the ends off the log before slicing the 8 rounds, as the ends often have less filling."]', '"This recipe merges the British tradition of the afternoon tea scone with the rich, spiced indulgence of the American cinnamon roll. While scones originated in Scotland in the early 1500s, the addition of the cinnamon swirl transforms them into a distinctly modern, comfort-food hybrid popular in American bakeries."', 442.32);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('a7b5e285-5642-43ab-a625-2dde52888650', 'Traditional Welsh Cakes', 'Buttery, crumbly, and gently spiced cakes studded with sweet currants. Cooked on a griddle rather than baked, they offer a unique texture that is crisp on the outside and tender within.', 'baked good', 'Welsh', 'Easy', '["welsh cakes", "pikelets", "scones", "baking", "tea time", "british"]', '[{"group_name": "Dough Base", "items": [{"name": "self-raising flour", "quantity": 225, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 110, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "generous pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "caster sugar", "quantity": 85, "unit": "g", "preparation": null, "notes": "plus extra for dusting", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Flavorings", "items": [{"name": "mixed spice", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": ["cinnamon", "nutmeg"], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}, {"name": "currants", "quantity": 75, "unit": "g", "preparation": null, "notes": null, "substitutions": ["sultanas", "raisins"], "ingredient_id": "f700705f-0a9b-4f11-8a21-47d179b06b92", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Binding", "items": [{"name": "egg", "quantity": 1, "unit": null, "preparation": "large, beaten", "notes": "approx 50-60g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "milk", "quantity": 15, "unit": "ml", "preparation": null, "notes": "use only if dough is dry", "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Sift the self-raising flour, mixed spice, and salt into a large mixing bowl.", "structured": {"action": "SIFT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Add the cold, cubed butter and rub it into the flour mixture using your fingertips until the texture resembles fine breadcrumbs.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Resembles fine breadcrumbs", "tactile": "No large lumps of butter remaining"}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Stir in the caster sugar and currants until evenly distributed.", "structured": {"action": "STIR", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Add the beaten egg and mix to form a firm dough. If the mixture is too dry to come together, add a splash of milk sparingly.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Dough holds together but is not sticky"}}, "tips": ["Avoid overworking the dough, or the cakes will be tough."]}, {"step_number": 5, "phase": "prep", "text": "Roll the dough out on a lightly floured surface to a thickness of approximately 5-7mm.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "Cut into rounds using a 6cm cutter. Gather scraps, gently re-roll, and cut again until all dough is used.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Grease a heavy frying pan or griddle with a little butter or lard and place over medium-low heat. Cook the cakes in batches for about 2-3 minutes per side.", "structured": {"action": "FRY", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown and mottled surface", "tactile": null}}, "tips": ["Control the heat carefully; if too high, the outside burns before the inside cooks."]}, {"step_number": 8, "phase": "finish", "text": "Transfer the cakes to a wire rack and sprinkle immediately with extra caster sugar while still warm.", "structured": {"action": "COOL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT0M", "total_time": "PT25M", "overnight_required": false, "yields": "16 cakes", "yield_count": 16, "serving_size_g": 35}', '{"flags": ["Vegetarian"], "not_suitable_for": ["Vegans", "Gluten-Intolerant"]}', '{"per_serving": {"calories": 140.66, "protein_g": 2.1, "carbohydrates_g": 19.82, "fat_g": 6.12, "saturated_fat_g": 3.66, "trans_fat_g": null, "monounsaturated_fat_g": 1.75, "polyunsaturated_fat_g": 0.33, "fiber_g": 0.63, "sugar_g": 8.33, "sodium_mg": 32.23, "cholesterol_mg": 26.5, "potassium_mg": 59.44, "calcium_mg": 11.11, "iron_mg": 0.32, "magnesium_mg": 5.73, "phosphorus_mg": 28.85, "zinc_mg": 0.17, "vitamin_a_mcg": 52.65, "vitamin_c_mg": 0.23, "vitamin_d_mcg": 0.08, "vitamin_e_mg": 0.21, "vitamin_k_mcg": 0.69, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": 0.04, "thiamin_mg": 0.03, "riboflavin_mg": 0.03, "niacin_mg": 0.26, "folate_mcg": 5.99, "water_g": 6.83, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best stored at room temperature.", "duration": null}, "freezer": {"notes": "Freeze separated by parchment paper.", "duration": "P3M"}, "reheating": "Toast lightly or warm in a low oven.", "does_not_keep": false}', '[{"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Heavy-bottomed frying pan or griddle", "required": true, "alternative": "Electric skillet"}, {"name": "Round cutter (6cm)", "required": true, "alternative": "Glass rim"}, {"name": "Rolling pin", "required": true, "alternative": null}, {"name": "Wire rack", "required": true, "alternative": null}]', '[{"symptom": "Cakes are burnt on the outside but raw in the middle", "likely_cause": "Heat source was too high", "prevention": "Use a medium-low flame and a heavy-bottomed pan to distribute heat evenly", "fix": "Finish cooking in a low oven (150\u00b0C/300\u00b0F) for 5 minutes"}]', '["For a more traditional texture, replace half the butter with lard; this creates a shorter, flakier crumb.", "A ''bakestone'' or cast iron griddle is the authentic tool, but a heavy non-stick pan works well if the heat is kept low.", "These are best eaten the same day, but can be revived by popping them in a toaster."]', '"Known in Welsh as ''Picau ar y maen'' (cakes on the stone), these treats have been a staple of Welsh baking since the 19th century. Traditionally cooked on a cast-iron bakestone over an open fire, they were an accessible treat for miners and families, combining the convenience of a scone with the durability of a cookie."', 140.66);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('a7d03146-ae8d-4034-a088-1c7f32d51e5b', 'Grilled Halloumi and Heirloom Tomato Platter', 'Warm, salty halloumi cheese with a smoky char provides a stark, delicious contrast to cold, sweet heirloom tomatoes. Finished with a honey-za''atar dressing and fresh mint, this dish captures the essence of summer dining with a perfect balance of textures and temperatures.', 'dinner', 'Mediterranean', 'Easy', '["halloumi", "tomato", "dinner", "grilling", "summer", "vegetarian", "mediterranean", "quick"]', '[{"group_name": "Salad Base", "items": [{"name": "halloumi cheese", "quantity": 250, "unit": "g", "preparation": "sliced into 1cm thick slabs", "notes": null, "substitutions": [], "ingredient_id": "db61d3c6-6434-43eb-a751-b10bb03606cd", "nutrition_source": "Aggregated Public Data"}, {"name": "heirloom tomatoes", "quantity": 400, "unit": "g", "preparation": "sliced or wedged", "notes": "mix of colors and sizes", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "for brushing cheese", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Spiced Honey Dressing", "items": [{"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "za''atar spice blend", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5290caca-3bc3-4104-92f8-7fa859f85915", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 3g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "aleppo pepper or chili flakes", "quantity": 2, "unit": "g", "preparation": null, "notes": "adjust for heat preference", "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "use sparingly as cheese is salty", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish", "items": [{"name": "fresh mint leaves", "quantity": 10, "unit": "g", "preparation": "torn", "notes": null, "substitutions": [], "ingredient_id": "17abecc0-a2a0-4478-8486-57b46e4305c9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the dressing by whisking together the extra virgin olive oil, lemon juice, honey, minced garlic, za''atar, chili flakes, and a small pinch of sea salt in a small bowl until emulsified. Taste and adjust acidity if needed.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Slice the heirloom tomatoes into varying shapes (rounds and wedges) to create texture. Arrange them on a serving platter. Lightly season the tomatoes with a pinch of salt.", "structured": {"action": "SLICE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Pat the halloumi slices completely dry with paper towels. Moisture prevents browning. Brush both sides of the cheese slices with olive oil.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Preheat your grill or grill pan to medium-high heat (approx. 220\u00b0C/430\u00b0F). Grill the halloumi slices for 2-3 minutes per side, without moving them initially, until deep golden brown grill marks appear and the cheese softens.", "structured": {"action": "GRILL", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT6M", "doneness_cues": {"visual": "Deep golden char marks", "tactile": "Softened interior"}}, "tips": ["Do not flip the cheese until it releases naturally from the grates."]}, {"step_number": 5, "phase": "assemble", "text": "Immediately transfer the hot halloumi onto the bed of prepared tomatoes. Drizzle the spiced honey dressing generously over the cheese and tomatoes. Scatter fresh torn mint leaves over the top and serve immediately while the cheese is warm.", "structured": {"action": "PLATE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "2 main servings", "yield_count": 2, "serving_size_g": 350}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Egg-Free", "Soy-Free"], "not_suitable_for": ["Infants under 12 months (honey)"]}', '{"per_serving": {"calories": 740.41, "protein_g": 30.33, "carbohydrates_g": 17.89, "fat_g": 59.61, "saturated_fat_g": 24.24, "trans_fat_g": null, "monounsaturated_fat_g": 21.93, "polyunsaturated_fat_g": 3.26, "fiber_g": 4.61, "sugar_g": 15.49, "sodium_mg": 1804.43, "cholesterol_mg": null, "potassium_mg": 534.42, "calcium_mg": 922.41, "iron_mg": 1.79, "magnesium_mg": 27.63, "phosphorus_mg": 57.2, "zinc_mg": 0.48, "vitamin_a_mcg": 24.95, "vitamin_c_mg": 31.49, "vitamin_d_mcg": null, "vitamin_e_mg": 4.71, "vitamin_k_mcg": 19.15, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": null, "thiamin_mg": 0.02, "riboflavin_mg": 0.03, "niacin_mg": 0.19, "folate_mcg": 7.23, "water_g": 13.48, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Halloumi will become rubbery when cold; reheat gently before eating.", "duration": "P2D"}, "freezer": {"notes": "Fresh tomatoes and cooked halloumi do not freeze well.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Outdoor grill or cast-iron grill pan", "required": true, "alternative": "Non-stick frying pan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Pastry brush", "required": true, "alternative": null}, {"name": "Metal spatula", "required": true, "alternative": null}]', '[{"symptom": "Halloumi sticks to the grill", "likely_cause": "The grill was not hot enough or the cheese was not oiled", "prevention": "Ensure grill is smoking hot and cheese is brushed with oil before placing", "fix": "Use a thin metal spatula to carefully scrape underneath the char to release it; if mangled, chop into cubes and serve as a tossed salad"}]', '["The contrast between hot cheese and room-temperature tomatoes is key to this dish; do not grill the tomatoes.", "Halloumi has a very high salt content, so be very conservative when adding extra salt to the dressing or tomatoes.", "If you cannot find Za''atar, a mix of dried oregano, thyme, sesame seeds, and sumac makes a great substitute.", "Patting the halloumi dry is the single most important step for getting that professional golden crust rather than a steamed white surface."]', '"Halloumi is a semi-hard, unripened brined cheese from Cyprus that has a high melting point, making it ideal for grilling. This dish combines the Levantine tradition of pairing salty cheese with sweet fruit and bright herbs, a staple flavor profile in Eastern Mediterranean summers."', 740.41);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('a84c7472-0e16-4aab-b9c8-f001974504ee', 'Prosciutto-Wrapped Chicken with Broccoli Mousseline', 'Succulent chicken breasts encased in crisp, salty prosciutto and aromatic sage, served atop a vibrant, velvety broccoli purée. Sweet honey-glazed carrots provide a textural contrast and bright color to this elegant dinner centerpiece.', 'dinner', 'Modern French', 'Intermediate', '["broccoli", "chicken breast", "dinner", "main course", "gluten-free", "elegant", "date night"]', '[{"group_name": "Chicken", "items": [{"name": "boneless skinless chicken breasts", "quantity": 4, "unit": null, "preparation": "trimmed", "notes": "approx. 150g each", "substitutions": [], "ingredient_id": "2b577d04-33ca-4919-938f-bfc8780a3a4b", "nutrition_source": "Aggregated Public Data"}, {"name": "prosciutto di parma", "quantity": 8, "unit": null, "preparation": null, "notes": "thinly sliced", "substitutions": [], "ingredient_id": "6b3bd037-dea6-4a87-85dc-3b889880b65c", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh sage leaves", "quantity": 8, "unit": null, "preparation": null, "notes": "large whole leaves", "substitutions": [], "ingredient_id": "2babed06-aae7-4e90-8b4a-14acbde2f522", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Broccoli Mousseline", "items": [{"name": "broccoli", "quantity": 600, "unit": "g", "preparation": "cut into florets", "notes": null, "substitutions": [], "ingredient_id": "b0a26615-a0a7-4b5c-9143-e9becf53b41a", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 80, "unit": "ml", "preparation": "warm", "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Glazed Carrots", "items": [{"name": "baby carrots", "quantity": 300, "unit": "g", "preparation": "peeled", "notes": null, "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 150, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place chicken breasts between sheets of plastic wrap and gently pound the thickest parts until they are even in thickness (about 2cm). Season lightly with pepper (avoid salt as prosciutto is salty).", "structured": {"action": "POUND", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Even thickness ensures the chicken cooks at the same rate without drying out."]}, {"step_number": 2, "phase": "prep", "text": "Place two sage leaves on top of each chicken breast. Tightly wrap each breast with 2 slices of prosciutto, pressing the seams to seal.", "structured": {"action": "WRAP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Preheat oven to 200\u00b0C/400\u00b0F.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Bring a large pot of salted water to a boil. Prepare a bowl with ice water. Blanch broccoli florets for 4-5 minutes until very tender but still bright green. Immediately transfer to ice water to stop cooking.", "structured": {"action": "BLANCH", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": ["Shocking the broccoli in ice water is crucial to maintain a vibrant green color."]}, {"step_number": 5, "phase": "cook", "text": "Drain broccoli well. Transfer to a blender with warm heavy cream, 30g butter, and lemon juice. Pur\u00e9e on high speed until completely smooth and silky. Season with salt to taste. Keep warm.", "structured": {"action": "PUREE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Smooth, vibrant green paste", "tactile": "Silky texture without lumps"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "In a saucepan, combine carrots, water, 15g butter, and honey. Bring to a simmer over medium heat. Cover and cook for 8 minutes, then uncover and increase heat to reduce liquid until carrots are glazed and tender.", "structured": {"action": "GLAZE", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "While carrots finish, heat olive oil in the oven-safe skillet over medium-high heat. Sear chicken breasts, seam-side down first, for 3 minutes per side until prosciutto is golden and crispy.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT6M", "doneness_cues": {"visual": "Golden brown crispy prosciutto", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Transfer the skillet to the preheated oven. Roast for 8-12 minutes until chicken reaches an internal temperature of 74\u00b0C/165\u00b0F.", "structured": {"action": "ROAST", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove chicken from pan and let rest for 5 minutes. To serve, spread a swoosh of broccoli mousseline on the plate, slice chicken on a bias, place on top, and arrange glazed carrots alongside.", "structured": {"action": "PLATE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT15M", "total_time": "PT1H", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 380}', '{"flags": ["Gluten-Free", "Nut-Free", "Soy-Free", "Low-Carb"], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 601.7, "protein_g": 43.58, "carbohydrates_g": 22.63, "fat_g": 38.47, "saturated_fat_g": 15.84, "trans_fat_g": 0.4, "monounsaturated_fat_g": 12.98, "polyunsaturated_fat_g": 4.23, "fiber_g": 6.67, "sugar_g": 10.51, "sodium_mg": 633.55, "cholesterol_mg": 142.79, "potassium_mg": 1222.69, "calcium_mg": 152.28, "iron_mg": 3.17, "magnesium_mg": 86.51, "phosphorus_mg": 401.05, "zinc_mg": 2.17, "vitamin_a_mcg": 867.97, "vitamin_c_mg": 139.32, "vitamin_d_mcg": 0.92, "vitamin_e_mg": 3.06, "vitamin_k_mcg": 167, "vitamin_b6_mg": 1.16, "vitamin_b12_mcg": 0.56, "thiamin_mg": 0.25, "riboflavin_mg": 0.4, "niacin_mg": 16.58, "folate_mcg": 116.18, "water_g": 356.48, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store components separately. Re-crisp chicken in oven or pan.", "duration": "P3D"}, "freezer": {"notes": "Pur\u00e9e freezes well; chicken texture may degrade slightly upon thawing.", "duration": "P1M"}, "reheating": "Reheat chicken in 180\u00b0C oven until warm. Gently warm pur\u00e9e and carrots on stove.", "does_not_keep": false}', '[{"name": "Large oven-safe skillet", "required": true, "alternative": "Frying pan and baking dish"}, {"name": "High-speed blender", "required": true, "alternative": "Food processor (will result in coarser texture)"}, {"name": "Medium saucepan", "required": true, "alternative": null}, {"name": "Meat mallet", "required": true, "alternative": "Heavy rolling pin"}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Prosciutto unwraps during searing", "likely_cause": "Seam wasn''t sealed or chicken was moved too much", "prevention": "Always sear the seam-side down first and do not move the chicken until the crust forms", "fix": "Secure with a toothpick (remember to remove before serving) and continue cooking"}, {"symptom": "Broccoli pur\u00e9e is brown/olive drab", "likely_cause": "Overcooked during blanching or acid added too early", "prevention": "Shock in ice water immediately; add lemon juice only right before blending", "fix": "Cannot be fixed strictly, but adding a handful of fresh spinach during blending can restore green color"}]', '["Pat the broccoli very dry before blending; excess water will make the pur\u00e9e runny rather than velvety.", "For an even smoother mousseline, pass the broccoli pur\u00e9e through a fine-mesh sieve (chinois) after blending.", "If the prosciutto is very salty, you likely won''t need to salt the chicken meat itself, just the exterior after cooking if needed.", "Deglaze the chicken pan with a splash of white wine while the meat rests to create a quick jus to drizzle over the top."]', '"This dish draws from the French tradition of ''Mousseline,'' a term usually denoting a mixture lightened with cream or egg whites. The pairing of cured pork (prosciutto) with white meat is a classic technique across Southern Europe, notably in the Italian dish Saltimbocca, though this preparation uses a French plating philosophy."', 601.7);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('a8caeec7-4618-43da-bd2e-4f424a65c18b', 'Market Style Coastal Fish Chowder', 'A comforting, creamy soup balancing sweet corn, earthy potatoes, and tender white fish. Designed as a versatile framework, this recipe relies on a simple ratio of aromatics to liquid, inviting improvisation with whatever fresh seafood or vegetables are available.', 'soup', 'American', 'Easy', '["seafood", "corn", "dutch oven", "fish fillet", "fish stock", "no-recipe", "soup", "dinner", "weeknight", "main course"]', '[{"group_name": "Aromatics & Base", "items": [{"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "celery stalks", "quantity": 2, "unit": null, "preparation": "diced", "notes": "approx 100g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Liquids & Vegetables", "items": [{"name": "fish stock", "quantity": 500, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["vegetable stock", "clam juice mixed with water"], "ingredient_id": "3912e04d-71a3-4a31-b033-cc5c5aa4452d", "nutrition_source": "Aggregated Public Data"}, {"name": "yukon gold potatoes", "quantity": 400, "unit": "g", "preparation": "peeled and cut into 1.5cm cubes", "notes": null, "substitutions": [], "ingredient_id": "90fa399c-54a2-461c-b410-868fba3bac36", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh thyme sprigs", "quantity": 3, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "bay leaf", "quantity": 1, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}, {"name": "corn kernels", "quantity": 150, "unit": "g", "preparation": "fresh or frozen", "notes": null, "substitutions": [], "ingredient_id": "46ca2aab-cb23-4397-9711-528c234b2cf8", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finish", "items": [{"name": "whole milk", "quantity": 250, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 120, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "white fish fillet", "quantity": 500, "unit": "g", "preparation": "cut into 3cm chunks", "notes": "Cod, Haddock, or Pollock", "substitutions": [], "ingredient_id": "7c0b1fd4-2b0f-41d0-a728-f5ee24132e74", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "chives", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "f5d96837-c5d2-407c-8e45-b000ba07e27e", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Melt the butter in a Dutch oven over medium heat (175\u00b0C/350\u00b0F). Add the diced onion and celery with a pinch of salt.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT5M", "doneness_cues": {"visual": "Onions are translucent and soft", "tactile": "Vegetables yield to pressure"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add minced garlic and cook for 30 seconds until fragrant, then sprinkle the flour over the vegetables. Stir constantly to cook out the raw flour taste without browning it.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Flour coats vegetables evenly", "tactile": "Mixture becomes paste-like"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Slowly pour in the fish stock while stirring to prevent lumps. Add the potatoes, thyme sprigs, and bay leaf. Bring to a simmer.", "structured": {"action": "SIMMER", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT12M", "doneness_cues": {"visual": null, "tactile": "Potatoes are knife-tender"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Reduce heat to low. Stir in the milk, heavy cream, and corn. Allow the liquid to return to a gentle heat, but do not let it boil vigorously.", "structured": {"action": "TEMPER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Gently nestle the fish chunks into the soup. Cover and let poach gently until the fish is opaque and flakes easily. Target an internal temperature of 63\u00b0C/145\u00b0F.", "structured": {"action": "POACH", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT5M", "doneness_cues": {"visual": "Fish is opaque white", "tactile": "Fish flakes with gentle pressure"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove from heat. Discard thyme stems and bay leaf. Stir in lemon juice, season with salt and pepper to taste, and garnish with chives.", "structured": {"action": "SEASON", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT15M", "total_time": "PT35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Pescatarian"], "not_suitable_for": ["Dairy allergy", "Gluten allergy"]}', '{"per_serving": {"calories": 581.81, "protein_g": 36.29, "carbohydrates_g": 39.78, "fat_g": 31.95, "saturated_fat_g": 15.5, "trans_fat_g": 0.37, "monounsaturated_fat_g": 8.56, "polyunsaturated_fat_g": 3.88, "fiber_g": 3.84, "sugar_g": 9.11, "sodium_mg": 327.17, "cholesterol_mg": 139.34, "potassium_mg": 1381.14, "calcium_mg": 165.49, "iron_mg": 1.84, "magnesium_mg": 75, "phosphorus_mg": 516.37, "zinc_mg": 1.93, "vitamin_a_mcg": 290.88, "vitamin_c_mg": 25.77, "vitamin_d_mcg": 16.29, "vitamin_e_mg": 0.95, "vitamin_k_mcg": 15.02, "vitamin_b6_mg": 0.54, "vitamin_b12_mcg": 1.6, "thiamin_mg": 0.31, "riboflavin_mg": 0.38, "niacin_mg": 4.76, "folate_mcg": 61, "water_g": 258.95, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Reheat gently to avoid breaking the emulsion.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; dairy may separate and potatoes become grainy.", "duration": null}, "reheating": "Warm on low heat on the stove (approx 70\u00b0C/160\u00b0F), stirring frequently. Do not boil.", "does_not_keep": false}', '[{"name": "Dutch oven", "required": true, "alternative": "Heavy-bottomed stock pot"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": null}]', '[{"symptom": "Soup looks curdled or grainy", "likely_cause": "Dairy was boiled or added to acid too quickly", "prevention": "Keep heat low after adding milk; do not let it reach a rolling boil", "fix": "Remove solids with a slotted spoon, blend the liquid with an immersion blender to re-emulsify, then return solids"}, {"symptom": "Chowder is too thin", "likely_cause": "Not enough flour or potatoes didn''t release starch", "prevention": "Measure flour accurately; use starchy potatoes", "fix": "Mash a few cooked potato chunks against the side of the pot to release starch and thicken the broth naturally"}]', '["To embrace the ''No-Recipe'' improvisation style, memorize the ratio: 1 part fat/flour roux, 4 parts liquid, and enough solids to crowd the spoon.", "For a deeper savory profile, substitute half the salt with Old Bay seasoning or smoked paprika.", "If using frozen fish, thaw completely and pat dry before adding to prevent watering down the chowder.", "The potatoes act as a secondary thickener; if you prefer a very thick chowder, mash about 20% of the potatoes into the broth before adding the fish.", "Acid is critical in creamy soups; do not skip the final squeeze of lemon juice, as it cuts the richness and brightens the seafood flavor."]', '"Originating in the Northeastern United States, chowders were originally simple shipboard stews thickened with hardtack. This modern adaptation retains the soul of the New England classic\u2014creamy, white-fish forward\u2014but lightens the texture and speeds up the process for contemporary weeknight cooking."', 581.81);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('a8ddaf56-df53-4e74-8f68-2fde057f2d4b', 'Fresh Cranberry Orange Relish with Pecans', 'A vibrant, raw relish that captures the essence of the holidays with bright acidity and floral citrus notes. This uncooked condiment offers a refreshing, crunchy textural contrast to heavy roasted meats and is ready in minutes.', 'condiment', 'American', 'Easy', '["american", "condiments", "dips and spreads", "cranberry", "five ingredient", "food processor", "great leftovers", "kid-friendly", "make-ahead", "orange", "pecan", "easy", "quick", "side dish", "fall", "winter", "dairy-free", "gluten-free", "halal", "healthy", "kosher", "low-sodium", "vegetarian", "vegan", "christmas", "thanksgiving"]', '[{"group_name": "Fresh Produce", "items": [{"name": "fresh cranberries", "quantity": 340, "unit": "g", "preparation": "rinsed and picked over", "notes": "Standard 12oz bag", "substitutions": [], "ingredient_id": "792b7aa4-5582-400e-9d8b-cb9b5575d6fe", "nutrition_source": "USDA FoodData Central"}, {"name": "navel orange", "quantity": 1, "unit": null, "preparation": "whole, unpeeled", "notes": "approx. 200g; choose organic/unwaxed if possible", "substitutions": [], "ingredient_id": "0d1a416d-f205-434e-92c2-5f99dd791410", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pantry", "items": [{"name": "granulated sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": "Adjust up to 200g based on berry tartness", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "pecans", "quantity": 100, "unit": "g", "preparation": "toasted", "notes": "roughly chopped", "substitutions": [], "ingredient_id": "a5c5ee79-2bcd-4ab2-aed5-b09d0a3df4b5", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 1, "unit": "g", "preparation": null, "notes": "approx. 1/2 tsp", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the orange by cutting it into eighths (leaving the peel on). Remove any visible seeds and discard them. The peel adds essential aromatic oils and bitterness to balance the sugar.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Place the orange segments into the food processor bowl. Pulse until the orange is broken down into small chunks, but not pur\u00e9ed.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Add the fresh cranberries, granulated sugar, and cinnamon (if using) to the food processor with the orange. Pulse repeatedly until the mixture is finely chopped and uniform. Scrape down the sides of the bowl as needed.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": {"visual": "Particle size should resemble coarse salsa or relish", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Transfer the mixture to a serving bowl or storage container. Stir in the toasted pecans by hand to maintain their crunch. Taste and add more sugar if the cranberries are exceptionally tart.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Cover and refrigerate for at least 1 hour before serving. This resting period allows the sugar to dissolve completely and draw the juices out of the fruit, eliminating the gritty texture of raw sugar.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT1H", "total_time": "PT1H10M", "overnight_required": false, "yields": "Approx. 750g (3 cups)", "yield_count": 12, "serving_size_g": 60}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Soy-Free", "Low-Sodium"], "not_suitable_for": []}', '{"per_serving": {"calories": 127.36, "protein_g": 1.05, "carbohydrates_g": 19.22, "fat_g": 6.06, "saturated_fat_g": 0.52, "trans_fat_g": null, "monounsaturated_fat_g": 3.41, "polyunsaturated_fat_g": 1.82, "fiber_g": 2.46, "sugar_g": 16.35, "sodium_mg": 0.98, "cholesterol_mg": null, "potassium_mg": 103.11, "calcium_mg": 20.89, "iron_mg": 0.32, "magnesium_mg": 11.83, "phosphorus_mg": 26.25, "zinc_mg": 0.41, "vitamin_a_mcg": 4.41, "vitamin_c_mg": 20.31, "vitamin_d_mcg": null, "vitamin_e_mg": 0.49, "vitamin_k_mcg": 1.73, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": null, "thiamin_mg": 0.06, "riboflavin_mg": 0.02, "niacin_mg": 0.13, "folate_mcg": 2.12, "water_g": 25.04, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors improve after 24 hours as the sugar macerates the fruit.", "duration": "P2W"}, "freezer": {"notes": "Texture may soften slightly upon thawing.", "duration": "P2M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Food Processor", "required": true, "alternative": "High-powered blender (pulse carefully) or meat grinder"}, {"name": "Chef''s Knife", "required": true, "alternative": null}, {"name": "Cutting Board", "required": true, "alternative": null}, {"name": "Rubber Spatula", "required": true, "alternative": null}]', '[{"symptom": "Relish tastes too bitter", "likely_cause": "The orange had a very thick white pith or seeds were missed", "prevention": "Inspect orange slices carefully for seeds before processing; trim excess white pith if the skin is very thick", "fix": "Add more sugar and a pinch of salt to counteract bitterness; letting it sit for 24 hours also mellows the flavor"}, {"symptom": "Texture is mushy or watery", "likely_cause": "Over-processing in the food processor", "prevention": "Use the pulse function rather than running the motor continuously", "fix": "Strain slightly before serving, or stir in more chopped nuts for texture"}]', '["Since this recipe uses the whole orange including the peel, thoroughly wash the orange in warm water and scrub with a vegetable brush to remove wax and residue. Organic citrus is preferred.", "Toast the pecans in a dry pan at medium heat for 3-5 minutes until fragrant before adding them. This prevents them from becoming soggy too quickly in the relish.", "This relish is highly acidic, so avoid storing it in reactive metal containers like aluminum or cast iron; stick to glass or plastic.", "For a ''grown-up'' variation, stir in 15ml (1 tbsp) of Grand Marnier or spiced rum after processing.", "Leftovers are exceptional swirled into oatmeal, spread on turkey sandwiches, or used as a topping for cheesecake."]', '"Fresh cranberry relish is a distinctively American condiment, tracing its popularity to the mid-20th century when fresh cranberries became widely available in supermarkets. Unlike the cooked, jellied sauce often associated with Thanksgiving, this raw preparation (often called ''Cranberry Fluff'' or simply ''Fresh Relish'') highlights the native North American fruit''s natural astringency and crunch, providing a palate cleanser amidst rich holiday fare."', 127.36);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('a907a7c8-1b1a-43f0-896d-f4a8628152df', 'Butternut Squash Gratin with Black Walnut and Bacon Crisp', 'Velvety ribbons of sweet butternut squash baked in a garlic-infused cream sauce, finished with a smoky, earthy crumble of crisp bacon, black walnuts, and toasted breadcrumbs.', 'side dish', 'American', 'Intermediate', '["american", "casserole", "thanksgiving", "fall", "winter", "side dish", "comfort food"]', '[{"group_name": "Gratin Base", "items": [{"name": "butternut squash", "quantity": 1200, "unit": "g", "preparation": "peeled, seeded, and sliced 3mm thick", "notes": "approx 1 large squash", "substitutions": [], "ingredient_id": "7f8919a5-2de5-47ce-91b2-d2a999ea11f7", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 480, "unit": "ml", "preparation": null, "notes": "min 35% fat", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "smashed", "notes": "approx 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh sage", "quantity": 3, "unit": null, "preparation": "whole sprigs", "notes": "approx 2g", "substitutions": [], "ingredient_id": "2babed06-aae7-4e90-8b4a-14acbde2f522", "nutrition_source": "USDA FoodData Central"}, {"name": "nutmeg", "quantity": 1, "unit": "g", "preparation": "freshly grated", "notes": null, "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}, {"name": "gruy\u00e8re cheese", "quantity": 120, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "321085d2-bb82-45e1-8ae3-5a2ef5cea47f", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Bacon & Black Walnut Crisp", "items": [{"name": "thick-cut bacon", "quantity": 150, "unit": "g", "preparation": "diced", "notes": null, "substitutions": [], "ingredient_id": "893e633e-f6ec-482c-8dfd-2936be71f2fd", "nutrition_source": "USDA FoodData Central"}, {"name": "black walnuts", "quantity": 60, "unit": "g", "preparation": "roughly chopped", "notes": "can substitute English walnuts", "substitutions": [], "ingredient_id": "b084471c-e412-4a84-a2d8-80108ca8aff2", "nutrition_source": "USDA FoodData Central"}, {"name": "panko breadcrumbs", "quantity": 40, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84fbc204-4457-40ed-83c1-3e5a7bcd8f23", "nutrition_source": "Aggregated Public Data"}, {"name": "parmesan cheese", "quantity": 30, "unit": "g", "preparation": "finely grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 2, "unit": "g", "preparation": "leaves stripped and chopped", "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 190\u00b0C (375\u00b0F). Grease a 9x13 inch baking dish generously with butter.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a small saucepan, combine heavy cream, smashed garlic, sage sprigs, nutmeg, salt, and pepper. Bring to a bare simmer over medium heat, then remove from heat and let infuse for 10 minutes. Remove garlic and sage before using.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "assemble", "text": "Arrange half of the sliced squash in the prepared baking dish in overlapping shingles. Sprinkle with half of the Gruy\u00e8re cheese. Layer the remaining squash on top. Pour the infused cream mixture evenly over the entire dish.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Cover the dish tightly with foil. Bake for 40 minutes, or until the squash is tender when pierced with a knife.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT40M", "doneness_cues": {"visual": null, "tactile": "Knife slides in with no resistance"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "While the gratin bakes, fry the diced bacon in a frying pan over medium heat until crisp. Remove bacon with a slotted spoon to a paper towel, keeping 15ml (1 tbsp) of rendered fat in the pan.", "structured": {"action": "FRY", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "Add the panko breadcrumbs and chopped black walnuts to the pan with the reserved bacon fat. Toast over medium heat for 2-3 minutes until golden. Remove from heat and toss in a bowl with the cooked bacon, parmesan, and fresh thyme.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown crumbs", "tactile": "Crunchy texture"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove the foil from the gratin. Scatter the bacon-walnut mixture evenly over the top. Return to the oven and bake uncovered for another 15-20 minutes until bubbling and deeply browned.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT20M", "doneness_cues": {"visual": "Sauce bubbling around edges, golden top", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from the oven and let rest for at least 15 minutes before serving. This allows the sauce to thicken and the layers to set.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT1H5M", "total_time": "PT1H30M", "overnight_required": false, "yields": "8 servings", "yield_count": 8, "serving_size_g": 220}', '{"flags": [], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 489.86, "protein_g": 14.16, "carbohydrates_g": 24.69, "fat_g": 39.16, "saturated_fat_g": 19.88, "trans_fat_g": 0.77, "monounsaturated_fat_g": 11.4, "polyunsaturated_fat_g": 5.1, "fiber_g": 3.91, "sugar_g": 5.63, "sodium_mg": 570.7, "cholesterol_mg": 99.23, "potassium_mg": 688.7, "calcium_mg": 321.01, "iron_mg": 1.69, "magnesium_mg": 81.92, "phosphorus_mg": 273.32, "zinc_mg": 1.57, "vitamin_a_mcg": 1095.86, "vitamin_c_mg": 32.86, "vitamin_d_mcg": 1.14, "vitamin_e_mg": 3, "vitamin_k_mcg": 4.47, "vitamin_b6_mg": 0.38, "vitamin_b12_mcg": 0.48, "thiamin_mg": 0.23, "riboflavin_mg": 0.23, "niacin_mg": 2.67, "folate_mcg": 47.25, "water_g": 180.34, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Cover tightly; the topping may lose crispness.", "duration": "P4D"}, "freezer": {"notes": "Bake from frozen at 175\u00b0C (350\u00b0F) until heated through.", "duration": "P2M"}, "reheating": "Reheat in a 175\u00b0C (350\u00b0F) oven for 15-20 minutes to re-crisp the topping.", "does_not_keep": false}', '[{"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Mandoline slicer", "required": false, "alternative": "Sharp knife and steady hand"}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "9x13 inch baking dish", "required": true, "alternative": "Large oval gratin dish"}, {"name": "Frying pan", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}]', '[{"symptom": "Squash is still hard after baking", "likely_cause": "Slices were too thick or foil seal was loose", "prevention": "Use a mandoline for consistent 3mm slices; ensure foil is tight during the first bake", "fix": "Cover again with foil and bake for an additional 15-20 minutes before adding the topping"}]', '["Black walnuts have a bold, distinctively earthy flavor compared to English walnuts. If they are too strong for your palate, use a 50/50 mix or substitute entirely with English walnuts or pecans.", "Do not skip the resting period. If you cut into the gratin immediately, the cream sauce will be runny. Resting allows the starches to stabilize the emulsion.", "If you don''t have a mandoline, take your time to cut the squash as uniformly as possible. Varying thicknesses will result in uneven cooking.", "For a richer holiday presentation, you can submerge the sage leaves in the frying oil/bacon fat for 10 seconds to create crispy sage garnishes."]', '"This dish bridges the gap between a classic French gratin dauphinois and American harvest traditions. Black walnuts (Juglans nigra) are native to North America and have been a staple in Appalachian foraging and cooking for centuries, offering a uniquely wild, floral, and savory profile that pairs exceptionally well with winter squash."', 489.86);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('a92ccb2c-99b5-41ce-9f56-fa7e841f784a', 'Elderflower & Raspberry Gelée with Warm Berry Compote', 'A shimmering, translucent jewel of a dessert featuring floral elderflower notes and suspended fresh raspberries. The cool, delicate wobble of the jelly provides a striking thermal and textural contrast to the hot, tart berry compote.', 'dessert', 'Modern European', 'Intermediate', '["berry", "gelatin", "dessert", "side", "summer", "elegant", "gluten-free"]', '[{"group_name": "Elderflower Gel\u00e9e", "items": [{"name": "leaf gelatin", "quantity": 4, "unit": null, "preparation": "Gold grade", "notes": "approx 8g total; or 8g powdered gelatin", "substitutions": [], "ingredient_id": "a909aa0d-d907-4a92-8c81-fa4fe0f452f8", "nutrition_source": "USDA FoodData Central"}, {"name": "elderflower cordial", "quantity": 100, "unit": "ml", "preparation": null, "notes": "high quality", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 150, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "sparkling wine", "quantity": 250, "unit": "ml", "preparation": "chilled", "notes": "Prosecco or Cava; substitute sparkling grape juice for alcohol-free", "substitutions": ["Sparkling water", "White grape juice"], "ingredient_id": "208cd0ad-3a7a-4a7d-ba1c-8263ae62b958", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh raspberries", "quantity": 12, "unit": null, "preparation": null, "notes": "approx 60g", "substitutions": [], "ingredient_id": "f4f5b84c-c364-40cd-b737-375755e481f9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Warm Berry Compote", "items": [{"name": "mixed berries", "quantity": 200, "unit": "g", "preparation": "fresh or frozen", "notes": null, "substitutions": [], "ingredient_id": "72de0107-4608-4127-b409-4956fad5e9ed", "nutrition_source": "Aggregated Public Data"}, {"name": "caster sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": null, "notes": "strip only, approx 2g", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Submerge the gelatin leaves in a bowl of cold water and let them bloom for 5 minutes until soft and pliable. If using powder, sprinkle over 30ml of cold water and let bloom.", "structured": {"action": "MEASURE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a saucepan, combine the water and elderflower cordial. Heat gently until the liquid is hot but not boiling (approx 80\u00b0C/176\u00b0F).", "structured": {"action": "SIMMER", "temperature": {"celsius": 80, "fahrenheit": 176}, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Squeeze excess water from the softened gelatin leaves. Add them to the hot cordial mixture and whisk until completely dissolved. Remove from heat.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Pour the sparkling wine into the warm gelatin mixture. Stir gently to combine without creating excessive foam. Strain through a fine mesh sieve into a clean jug to remove any undissolved particles.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Place 3 raspberries into each of the 4 molds. Pour the liquid evenly into the molds.", "structured": {"action": "POUR", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["To suspend fruit in the middle: Fill halfway, chill until semi-set, add fruit, then top up."]}, {"step_number": 6, "phase": "finish", "text": "Refrigerate the molds for at least 4 hours, or until firmly set.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT4H", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Ten minutes before serving, prepare the compote. Combine mixed berries, sugar, lemon juice, and lemon zest strip in a saucepan. Cook over medium heat until the berries release their juices and the sauce slightly thickens.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT7M", "doneness_cues": {"visual": "Berries are soft and sauce coats the back of a spoon", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "To serve, dip the base of each mold into hot water for 5 seconds to loosen. Invert onto a plate. Remove the lemon zest strip from the compote and spoon the warm sauce around the cold jelly.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT4H", "total_time": "PT4H25M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Pescatarian"], "not_suitable_for": ["Vegans (contains gelatin)", "Vegetarians (contains gelatin)"]}', '{"per_serving": {"calories": 126.47, "protein_g": 2.33, "carbohydrates_g": 20.76, "fat_g": 0.23, "saturated_fat_g": 0.01, "trans_fat_g": null, "monounsaturated_fat_g": 0.01, "polyunsaturated_fat_g": 0.06, "fiber_g": 3.42, "sugar_g": 17.47, "sodium_mg": 11.37, "cholesterol_mg": null, "potassium_mg": 26.7, "calcium_mg": 18.93, "iron_mg": 0.47, "magnesium_mg": 4.56, "phosphorus_mg": 5.41, "zinc_mg": 0.07, "vitamin_a_mcg": 0.31, "vitamin_c_mg": 21.44, "vitamin_d_mcg": null, "vitamin_e_mg": 0.14, "vitamin_k_mcg": 1.17, "vitamin_b6_mg": 0.01, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.01, "niacin_mg": 0.1, "folate_mcg": 4.31, "water_g": 78.39, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Keep in molds until serving to maintain shape.", "duration": "P2D"}, "freezer": {"notes": "Do not freeze; gelatin structure will break.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Dariole molds or Ramekins", "required": true, "alternative": "Small glass tumblers"}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Fine mesh sieve", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}]', '[{"symptom": "Jelly sticks to the mold and won''t come out", "likely_cause": "Vacuum seal formed between jelly and mold", "prevention": "Lightly grease mold with neutral oil before filling", "fix": "Dip mold in hot water for 5-10 seconds, then gently pull one edge away from the side to break the seal"}, {"symptom": "Jelly is rubbery and tough", "likely_cause": "Too much gelatin or insufficient liquid", "prevention": "Measure gelatin precisely; 1 leaf sets roughly 125ml liquid for a soft set", "fix": "Melt down gently, add more warm liquid, and reset (results may vary)"}, {"symptom": "Jelly did not set", "likely_cause": "Liquid was boiled (destroying gelatin) or enzymes in fruit (kiwi/pineapple)", "prevention": "Never boil gelatin; avoid raw tropical fruits with enzymes", "fix": "Cannot be fixed"}]', '["Temperature contrast is the key to this dish. Ensure the compote is warm (not boiling hot) and the jelly is fridge-cold right before serving.", "Bloom strength matters. ''Gold'' grade leaf gelatin gives the cleanest melt-in-mouth texture. If using powder, ensure it is fully hydrated before heating.", "For a crystal-clear appearance, do not whisk the mixture vigorously after adding the sparkling wine, as this traps air bubbles that cloud the jelly.", "If using sparkling wine, the carbonation will mostly dissipate during mixing, but it leaves a pleasant acidity and ''bite'' that balances the sugar."]', '"The concept of fruit jellies (gel\u00e9es) dates back to medieval Europe, where animal collagen was laboriously extracted to create elaborate centerpieces. In modern French and British cuisine, elderflower is a quintessential early summer flavor, often paired with tart berries to cut through the sweetness."', 126.47);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('a98c4b6e-1722-4bff-b89b-d9668b6179b6', 'Creamy Millet Polenta with Roasted Eggplant & Chickpeas', 'A rustic, warming Italian-inspired dish where fluffy millet mimics traditional corn polenta. Topped with caramelized roasted eggplant, crispy chickpeas, and a bright tomato basil sauce.', 'main course', 'Italian', 'Intermediate', '["italian", "mediterranean", "dinner", "lunch", "main course", "fall", "winter", "gluten-free", "vegetarian", "comfort food"]', '[{"group_name": "Millet Polenta", "items": [{"name": "hulled millet", "quantity": 200, "unit": "g", "preparation": "rinsed well", "notes": null, "substitutions": [], "ingredient_id": "aafa5060-6334-496f-88a6-08f0594b2acc", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable stock", "quantity": 1000, "unit": "ml", "preparation": null, "notes": "or water for a lighter taste", "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 40, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "parmesan cheese", "quantity": 50, "unit": "g", "preparation": "grated", "notes": "ensure vegetarian rennet if strictly vegetarian", "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "approx 3g, to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Roasted Vegetables", "items": [{"name": "eggplant", "quantity": 1, "unit": null, "preparation": "medium dice (2cm cubes)", "notes": "approx 350g", "substitutions": [], "ingredient_id": "77c14307-dacf-4ab2-85d1-3594bff0ec99", "nutrition_source": "USDA FoodData Central"}, {"name": "chickpeas", "quantity": 240, "unit": "g", "preparation": "cooked, drained and rinsed", "notes": "1 standard can", "substitutions": [], "ingredient_id": "c73de242-2d46-4a95-8e75-146adb6cba2b", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 0.5 tsp", "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Tomato Sauce", "items": [{"name": "canned crushed tomatoes", "quantity": 400, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "49a62ca7-db63-4d23-9f6f-2cf873fba8a3", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh basil", "quantity": 10, "unit": "g", "preparation": "torn", "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 200\u00b0C/400\u00b0F. Line a baking sheet with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Toss the cubed eggplant and drained chickpeas with 30ml olive oil, oregano, smoked paprika, salt, and pepper on the baking sheet until well coated.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Roast the vegetables for 25-30 minutes, tossing halfway through, until the eggplant is tender and caramelized and chickpeas are slightly crispy.", "structured": {"action": "ROAST", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT30M", "doneness_cues": {"visual": "Eggplant golden brown, chickpeas crispy skin", "tactile": "Eggplant soft inside"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "While vegetables roast, bring vegetable stock to a boil in a heavy-bottomed pot. Add the rinsed millet and a pinch of salt.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Reduce heat to low, cover, and simmer the millet gently for 20-25 minutes. Stir occasionally to prevent sticking. It should absorb the liquid and break down into a soft mash.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT25M", "doneness_cues": {"visual": "Liquid absorbed, grains burst open", "tactile": "Soft and porridge-like"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "In a separate saucepan, heat 15ml olive oil over medium heat. Saut\u00e9 the minced garlic for 1 minute until fragrant but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Add crushed tomatoes to the garlic. Simmer on low heat for 10-15 minutes to thicken slightly. Stir in torn fresh basil at the end.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Once the millet is soft, remove from heat. Vigorously whisk in the butter and grated parmesan until the mixture is creamy and smooth.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["If the polenta is too stiff, add a splash of hot water or milk to reach desired consistency."]}, {"step_number": 9, "phase": "assemble", "text": "Divide the creamy millet polenta among bowls. Top with a ladle of tomato sauce and a generous scoop of roasted eggplant and chickpeas.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT20M", "total_time": "PT50M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Vegetarian", "Gluten-Free", "Soy-Free", "Nut-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 716.03, "protein_g": 26.53, "carbohydrates_g": 84.23, "fat_g": 29, "saturated_fat_g": 8.99, "trans_fat_g": null, "monounsaturated_fat_g": 11.91, "polyunsaturated_fat_g": 2.75, "fiber_g": 21.92, "sugar_g": 10.62, "sodium_mg": 1845.21, "cholesterol_mg": 30, "potassium_mg": 1241.69, "calcium_mg": 275.17, "iron_mg": 3.96, "magnesium_mg": 169.85, "phosphorus_mg": 454.59, "zinc_mg": 3.19, "vitamin_a_mcg": 240.99, "vitamin_c_mg": 13.49, "vitamin_d_mcg": 0.06, "vitamin_e_mg": 2.47, "vitamin_k_mcg": 26.67, "vitamin_b6_mg": 0.31, "vitamin_b12_mcg": 0.17, "thiamin_mg": 0.26, "riboflavin_mg": 0.24, "niacin_mg": 3.09, "folate_mcg": 66.69, "water_g": 93.78, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Millet will firm up significantly when cold; add a splash of water or milk when reheating.", "duration": "P3D"}, "freezer": {"notes": "Sauce and polenta freeze well; roasted vegetables may lose texture.", "duration": "P1M"}, "reheating": "Reheat on stovetop over low heat with a splash of water to restore creaminess.", "does_not_keep": false}', '[{"name": "Large heavy-bottomed pot", "required": true, "alternative": "Dutch oven"}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Saucepan", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}]', '[{"symptom": "Millet grains are still crunchy after 25 minutes", "likely_cause": "Insufficient liquid or heat was too high, causing evaporation", "prevention": "Keep the pot covered tight and maintain a very low simmer", "fix": "Add 50-100ml hot water and continue simmering for 5-10 minutes"}, {"symptom": "Eggplant is tough or spongy", "likely_cause": "Undercooked or not enough oil", "prevention": "Ensure oven is fully preheated and eggplant is well-coated in oil", "fix": "Return to oven for 5-10 minute intervals until soft"}]', '["Millet requires a higher liquid-to-grain ratio (1:4 or 1:5) than rice to achieve a polenta-like consistency. Do not skimp on the liquid.", "For extra smooth texture, you can use an immersion blender on the millet right before adding the cheese, though a rustic texture is traditional for this dish.", "Leftover millet polenta firms up when chilled. Slice it into squares and pan-fry them the next day for delicious crispy cakes.", "Rinsing the millet well before cooking removes natural saponins which can cause a slight bitterness."]', '"Before corn (maize) was introduced to Italy from the Americas in the 16th century, ''polenta'' was a staple dish made from ancient grains like millet, spelt, or barley. This recipe harkens back to those Northern Italian roots while incorporating Mediterranean flavors."', 716.03);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('aaac7d31-a43d-4e9c-9f9c-b8b20606eaf2', 'Raspberry Custard Clafoutis', 'A rustic yet elegant French dessert where tart fresh raspberries are baked in a rich, vanilla-scented batter that settles into a texture halfway between a pancake and a silky flan. Served warm with a dusting of powdered sugar.', 'dessert', 'French', 'Easy', '["clafoutis", "french dessert", "raspberry", "custard", "vegetarian", "nut-free", "summer baking"]', '[{"group_name": "Fruit & Preparation", "items": [{"name": "unsalted butter", "quantity": 15, "unit": "g", "preparation": "room temperature", "notes": "for greasing the dish", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 15, "unit": "g", "preparation": null, "notes": "for dusting the greased dish", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh raspberries", "quantity": 350, "unit": "g", "preparation": "washed and patted very dry", "notes": null, "substitutions": [], "ingredient_id": "f4f5b84c-c364-40cd-b737-375755e481f9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Custard Batter", "items": [{"name": "eggs", "quantity": 3, "unit": null, "preparation": "large, room temperature", "notes": "approx. 165g total weight", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "granulated sugar", "quantity": 80, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "small pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 200, "unit": "ml", "preparation": null, "notes": "min 35% fat", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish", "items": [{"name": "powdered sugar", "quantity": 10, "unit": "g", "preparation": null, "notes": "for dusting", "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 180\u00b0C/355\u00b0F. Generously grease your baking dish with the 15g of butter and dust with 15g of granulated sugar, shaking out the excess. This creates a caramelized crust.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "assemble", "text": "Arrange the raspberries in a single layer at the bottom of the prepared dish. Do not overcrowd; they should cover the bottom but have space for the batter to settle between them.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a large mixing bowl, whisk the eggs, 80g sugar, and salt vigorously until the mixture is pale and slightly frothy, about 2 minutes.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Whisk in the flour until just combined and smooth. Do not overwork the batter once the flour is added.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Slowly pour in the heavy cream, milk, and vanilla extract, whisking gently to combine into a smooth, thin batter.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Pour the batter gently over the raspberries. Bake for 35-40 minutes at 180\u00b0C/355\u00b0F. The clafoutis is done when it is puffed, golden brown around the edges, and the center is set but still jiggles slightly when the dish is nudged.", "structured": {"action": "BAKE", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT35M", "doneness_cues": {"visual": "Puffed and golden brown edges", "tactile": "Center has a slight jiggle (like set gelatin)"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from the oven and let cool on a wire rack for at least 15 minutes. The puff will deflate significantly; this is normal. Dust with powdered sugar just before serving.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT35M", "total_time": "PT50M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 135}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Vegans", "Lactose Intolerant"]}', '{"per_serving": {"calories": 307.51, "protein_g": 6.31, "carbohydrates_g": 32.53, "fat_g": 17.46, "saturated_fat_g": 10, "trans_fat_g": 0.43, "monounsaturated_fat_g": 4.75, "polyunsaturated_fat_g": 1.4, "fiber_g": 4.02, "sugar_g": 21.72, "sodium_mg": 118.31, "cholesterol_mg": 146.34, "potassium_mg": 182.01, "calcium_mg": 65.44, "iron_mg": 1.03, "magnesium_mg": 21.45, "phosphorus_mg": 108.75, "zinc_mg": 0.78, "vitamin_a_mcg": 203.87, "vitamin_c_mg": 15.48, "vitamin_d_mcg": 1.21, "vitamin_e_mg": 1.17, "vitamin_k_mcg": 5.93, "vitamin_b6_mg": 0.1, "vitamin_b12_mcg": 0.35, "thiamin_mg": 0.05, "riboflavin_mg": 0.24, "niacin_mg": 0.51, "folate_mcg": 29.25, "water_g": 100.89, "alcohol_g": 0.29, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Texture becomes denser when cold; reheat gently before serving.", "duration": "P3D"}, "freezer": {"notes": null, "duration": null}, "reheating": "Warm in a 150\u00b0C oven for 5-10 minutes or microwave briefly.", "does_not_keep": false}', '[{"name": "Ceramic baking dish or cast iron skillet (23-25cm)", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Sifter", "required": false, "alternative": null}]', '[{"symptom": "Texture is rubbery or tough", "likely_cause": "Overmixing the batter after adding flour developed too much gluten", "prevention": "Whisk flour in gently until just combined, or mix liquids first and flour last", "fix": "Cannot be fixed, but serve with extra fresh cream to mask texture"}, {"symptom": "Watery layer at the bottom", "likely_cause": "Raspberries were wet when added", "prevention": "Wash fruit well in advance and ensure they are thoroughly patted dry", "fix": "Cannot be fixed"}]', '["While traditionally made with unpitted cherries (which impart an almond flavor), raspberries pair beautifully with this high-cream custard base. Since we omit the pits, vanilla is key.", "Do not open the oven door during the first 25 minutes of baking, or the clafoutis may collapse prematurely.", "Serve lukewarm rather than hot; the custard texture and fruit flavor are much more pronounced after resting for 15-20 minutes.", "Ensure all dairy and eggs are at room temperature before mixing to prevent the butter in the batter (if using) or fat in the cream from clumping, though this recipe uses liquid fat (cream) mainly."]', '"Originating from the Limousin region of France, Clafoutis is a humble country dish designed to showcase seasonal fruit. While the name is strictly reserved for black cherries in purist circles (raspberry versions are technically ''flaugnarde''), it remains a staple of French home cooking."', 307.51);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('aabd5228-3692-4105-a239-0717149c4205', 'Parmesan-Crusted Sage Garlic Butter Turkey Goujons', 'Tender strips of turkey breast encased in a golden, cheese-heavy crust, finished with a glossy brushing of sage-infused garlic butter. A sophisticated twist on the classic tender, capturing the essence of a holiday roast in a crispy, handheld format.', 'dinner', 'Modern American', 'Easy', '["turkey", "weeknight dinner", "kid-friendly", "high protein", "holiday leftovers"]', '[{"group_name": "Turkey", "items": [{"name": "turkey breast cutlets", "quantity": 600, "unit": "g", "preparation": "cut into 2.5cm/1 inch strips", "notes": "pat dry thoroughly", "substitutions": [], "ingredient_id": "2b577d04-33ca-4919-938f-bfc8780a3a4b", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "for seasoning meat", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": null, "notes": "freshly ground", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Breading Station", "items": [{"name": "all-purpose flour", "quantity": 125, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "beaten", "notes": "large, approx 100g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "panko breadcrumbs", "quantity": 100, "unit": "g", "preparation": null, "notes": "Japanese style for extra crunch", "substitutions": [], "ingredient_id": "92441189-214a-4a8a-9cfc-dd578fe0d179", "nutrition_source": "USDA FoodData Central"}, {"name": "parmesan cheese", "quantity": 60, "unit": "g", "preparation": "finely grated", "notes": "freshly grated preferred", "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic powder", "quantity": 5, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "177a312f-ef99-4398-9108-98f7a608a245", "nutrition_source": "USDA FoodData Central"}, {"name": "dried rubbed sage", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "b57ab3d7-bbf1-40dc-b234-3061a3cfb715", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sage Garlic Butter", "items": [{"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": "melted", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh sage leaves", "quantity": 5, "unit": null, "preparation": "finely minced", "notes": "approx 3g", "substitutions": [], "ingredient_id": "2babed06-aae7-4e90-8b4a-14acbde2f522", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh garlic", "quantity": 2, "unit": null, "preparation": "minced or crushed", "notes": "cloves, approx 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "flaky sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, for finishing", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 220\u00b0C/425\u00b0F. Place a wire rack over a baking sheet and lightly grease the rack with oil spray to prevent sticking.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Set up a 3-bowl breading station. Bowl 1: Flour seasoned with a pinch of salt. Bowl 2: Beaten eggs. Bowl 3: Panko breadcrumbs, grated Parmesan, garlic powder, and dried sage mixed thoroughly.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Season the turkey strips with salt and pepper. Working one at a time, dredge a strip in flour (shake off excess), dip into the egg (let excess drip off), and press firmly into the parmesan-panko mixture to coat.", "structured": {"action": "DREDGE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Arrange the coated goujons on the prepared wire rack, ensuring they do not touch. Spray the tops lightly with cooking oil spray to encourage browning.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Bake for 12-15 minutes, flipping halfway through if not using a convection fan. Cook until the crust is golden brown and the internal temperature reaches 74\u00b0C/165\u00b0F.", "structured": {"action": "BAKE", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT15M", "doneness_cues": {"visual": "Golden brown crust", "tactile": "Internal temp 74\u00b0C/165\u00b0F"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "While the turkey bakes, melt the butter in a small saucepan over low heat. Add the minced fresh garlic and fresh sage. Saut\u00e9 gently for 1-2 minutes until fragrant but not browned, then remove from heat.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Immediately upon removing the turkey from the oven, brush the hot goujons generously with the warm sage garlic butter. Sprinkle with flaky sea salt and serve immediately.", "structured": {"action": "GLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT15M", "total_time": "PT40M", "overnight_required": false, "yields": "12-16 goujons", "yield_count": 4, "serving_size_g": 220}', '{"flags": ["Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Gluten-Free", "Dairy-Free", "Egg-Free"]}', '{"per_serving": {"calories": 685.03, "protein_g": 46.94, "carbohydrates_g": 45.17, "fat_g": 33.99, "saturated_fat_g": 14.96, "trans_fat_g": 0.16, "monounsaturated_fat_g": 11.58, "polyunsaturated_fat_g": 4.62, "fiber_g": 2.7, "sugar_g": 1.84, "sodium_mg": 978.64, "cholesterol_mg": 231.45, "potassium_mg": 505.51, "calcium_mg": 287.96, "iron_mg": 3.73, "magnesium_mg": 72.19, "phosphorus_mg": 503.05, "zinc_mg": 2.68, "vitamin_a_mcg": 211.19, "vitamin_c_mg": 1.2, "vitamin_d_mcg": 1.18, "vitamin_e_mg": 1.14, "vitamin_k_mcg": 12.13, "vitamin_b6_mg": 0.96, "vitamin_b12_mcg": 1.02, "thiamin_mg": 0.4, "riboflavin_mg": 0.43, "niacin_mg": 17.03, "folate_mcg": 56.2, "water_g": 137.2, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Crust will soften.", "duration": "P3D"}, "freezer": {"notes": "Freeze raw on a tray, then bag. Bake from frozen adding 5-10 minutes.", "duration": "P2M"}, "reheating": "Reheat in oven or air fryer at 180\u00b0C/350\u00b0F for 5-8 minutes to recrisp. Microwave is not recommended.", "does_not_keep": false}', '[{"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Wire rack", "required": true, "alternative": "Parchment paper (will result in less crispy bottom)"}, {"name": "Shallow bowls", "required": true, "alternative": null}, {"name": "Small saucepan", "required": true, "alternative": "Microwave-safe bowl"}, {"name": "Pastry brush", "required": true, "alternative": "Spoon"}, {"name": "Meat thermometer", "required": true, "alternative": null}]', '[{"symptom": "Turkey is dry and tough", "likely_cause": "Overcooking due to lean meat content", "prevention": "Check temperature early; remove exactly at 74\u00b0C/165\u00b0F. Turkey cooks faster than chicken.", "fix": "Dice the meat and mix with gravy or mayonnaise for a sandwich filling"}, {"symptom": "Breading is soggy", "likely_cause": "Baked directly on a flat sheet pan or too much egg wash", "prevention": "Use a wire rack over the baking sheet to allow air circulation underneath", "fix": "Air fry for 2-3 minutes to re-crisp"}]', '["For an Air Fryer adaptation: Cook at 200\u00b0C/400\u00b0F for 8-10 minutes, flipping halfway. Do not overcrowd the basket.", "Using a wire rack is the secret to mimicking a fried texture in the oven; it allows hot air to crisp the bottom of the goujon.", "The fresh sage in the butter provides a bright, herbal pop that contrasts with the dried sage in the crust, giving a multi-dimensional flavor.", "Serve with warm cranberry sauce or a white pepper country gravy for the full holiday experience."]', '"While ''goujon'' is a French term for a strip of fish or meat, this preparation is distinctly American, borrowing the flavor palette of a Thanksgiving roast\u2014sage, turkey, and savory gravy notes\u2014and applying it to the beloved format of the breaded chicken tender."', 685.03);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ac82dca7-53a1-42cd-96fd-0adddf74b4a7', 'Overnight Pumpkin Spice French Toast Casserole', 'A warming, custodial breakfast bake featuring cubes of buttery brioche soaked overnight in a rich pumpkin-spiced egg batter. Topped with a crunchy pecan streusel, it emerges from the oven golden, fragrant, and perfect for a cozy fall morning.', 'breakfast', 'American', 'Easy', '["casseroles", "brioche", "challah", "french toast", "make-ahead", "milk", "plan-ahead", "breakfast", "brunch", "dinner", "fall", "vegetarian"]', '[{"group_name": "Base", "items": [{"name": "brioche or challah bread", "quantity": 600, "unit": "g", "preparation": "stale, cubed into 2.5cm pieces", "notes": "Approx 1 large loaf; day-old bread absorbs liquid best", "substitutions": [], "ingredient_id": "4984ed41-b79d-4372-8336-32815e469548", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 15, "unit": "g", "preparation": "room temperature", "notes": "For greasing the pan", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Custard", "items": [{"name": "large eggs", "quantity": 8, "unit": null, "preparation": null, "notes": "approx 400g without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "whole milk", "quantity": 360, "unit": "ml", "preparation": "cold", "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 120, "unit": "ml", "preparation": "cold", "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "pumpkin puree", "quantity": 245, "unit": "g", "preparation": null, "notes": "Not pumpkin pie filling; 1 standard US cup", "substitutions": [], "ingredient_id": "d9c74a13-e1c6-488d-8214-ea685a0f6eb2", "nutrition_source": "USDA FoodData Central"}, {"name": "brown sugar", "quantity": 100, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "pumpkin pie spice", "quantity": 6, "unit": "g", "preparation": null, "notes": "Or mix cinnamon, nutmeg, ginger, and cloves", "substitutions": [], "ingredient_id": "b5ee5cce-bb5f-490b-b4e9-c82f2bd9d4cd", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Streusel Topping", "items": [{"name": "all-purpose flour", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "11e03c79-4bf6-47ed-babb-753b1a9789c9", "nutrition_source": "USDA FoodData Central"}, {"name": "brown sugar", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "cold unsalted butter", "quantity": 60, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "pecans", "quantity": 50, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "a5c5ee79-2bcd-4ab2-aed5-b09d0a3df4b5", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Grease a 9x13 inch (approx 3L) baking dish with butter. Arrange the cubed bread evenly in the dish.", "structured": {"action": "MEASURE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large bowl, whisk together the eggs, milk, heavy cream, pumpkin puree, brown sugar, vanilla extract, pumpkin pie spice, and salt until completely smooth and combined.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Pour the custard mixture evenly over the bread. Press the bread down gently with a spatula or spoon to ensure every piece is submerged and begins to soak up the liquid.", "structured": {"action": "SOAK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Cover the dish tightly with plastic wrap or foil. Refrigerate for at least 4 hours, preferably overnight (8-12 hours), to allow the bread to fully absorb the custard.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT8H", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "The next morning, remove the casserole from the refrigerator 30 minutes before baking to take the chill off. Preheat oven to 175\u00b0C/350\u00b0F.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "While the oven heats, prepare the streusel. Combine flour, brown sugar, pecans, and cinnamon in a small bowl. Cut in the cold butter using a fork or your fingers until the mixture resembles coarse crumbs.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Sprinkle the streusel topping evenly over the casserole. Bake for 45-55 minutes. The top should be golden brown, and the center should be set (not jiggly liquid) with an internal temperature of at least 74\u00b0C/165\u00b0F.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT50M", "doneness_cues": {"visual": "Golden brown top, puffed up", "tactile": "Center springs back, not liquid"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from the oven and let rest for 10 minutes before serving. This allows the custard to set firmly for easier slicing.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT8H45M", "total_time": "PT9H5M", "overnight_required": true, "yields": "8 servings", "yield_count": 8, "serving_size_g": 220}', '{"flags": ["Vegetarian"], "not_suitable_for": ["Vegans (contains dairy, eggs)", "Celiacs (contains gluten)", "Nut allergies (contains pecans)"]}', '{"per_serving": {"calories": 575.6, "protein_g": 16.14, "carbohydrates_g": 67.89, "fat_g": 26.25, "saturated_fat_g": 11.08, "trans_fat_g": 0.21, "monounsaturated_fat_g": 8.33, "polyunsaturated_fat_g": 2.95, "fiber_g": 3.74, "sugar_g": 26.12, "sodium_mg": 633.14, "cholesterol_mg": 227.61, "potassium_mg": 274.51, "calcium_mg": 127.87, "iron_mg": 2.14, "magnesium_mg": 31.01, "phosphorus_mg": 185.75, "zinc_mg": 1.27, "vitamin_a_mcg": 465.06, "vitamin_c_mg": 1.63, "vitamin_d_mcg": 1.83, "vitamin_e_mg": 1.35, "vitamin_k_mcg": 6.85, "vitamin_b6_mg": 0.15, "vitamin_b12_mcg": 0.69, "thiamin_mg": 0.15, "riboflavin_mg": 0.4, "niacin_mg": 0.76, "folate_mcg": 45.79, "water_g": 117.59, "alcohol_g": 0.43, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store baked casserole covered. Raw assembly must be baked within 12-14 hours.", "duration": "P3D"}, "freezer": {"notes": "Freeze baked portions tightly wrapped in foil.", "duration": "P2M"}, "reheating": "Reheat single servings in microwave for 1 minute or oven at 175\u00b0C/350\u00b0F covered with foil for 15-20 minutes.", "does_not_keep": false}', '[{"name": "9x13 inch Baking Dish", "required": true, "alternative": "3L Casserole Dish"}, {"name": "Large Mixing Bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Serrated Knife", "required": true, "alternative": null}]', '[{"symptom": "Casserole is soggy in the middle", "likely_cause": "Bread did not absorb enough liquid or baking time was too short", "prevention": "Ensure bread is stale/dry before soaking and bake until center registers 74\u00b0C", "fix": "Cover with foil (to prevent burning) and bake for an additional 10-15 minutes"}, {"symptom": "Top is burning before center is cooked", "likely_cause": "Oven rack too high or temperature calibration off", "prevention": "Bake in middle or lower third of oven", "fix": "Tent loosely with aluminum foil for the remainder of the baking time"}]', '["For the best texture, leave your cubed bread out on a baking sheet for a few hours (or overnight) before assembling to stale it properly. Dry bread soaks up more custard without dissolving.", "If you don''t have heavy cream, you can use all whole milk, but the final texture will be slightly less rich and more pudding-like.", "Serve with warm maple syrup or a dusting of powdered sugar. A dollop of whipped cream complements the pumpkin spice flavor perfectly.", "This recipe scales easily. If doubling, use two 9x13 pans rather than a deeper pan to ensure even cooking."]', '"While French Toast (Pain Perdu) originated as a way to reclaim stale bread in Europe, the casserole variation is a distinctly American evolution designed for convenience and communal dining. This version incorporates the modern American tradition of ''pumpkin spice''\u2014a blend popularized in the 20th century referencing pumpkin pie filling\u2014making it a staple for Thanksgiving mornings and autumn brunch gatherings."', 575.6);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('aca29ad7-1162-4e74-804e-7c61afcd16b6', 'Classic Chimichurri Verde', 'A vibrant, raw herb sauce staple of Argentinian cuisine. Fresh flat-leaf parsley and oregano provide a bright, grassy foundation, while red wine vinegar and garlic add a sharp, pungent kick that perfectly cuts through the richness of grilled meats.', 'sauce', 'Argentinian', 'Easy', '["oregano", "parsley", "quick", "sauce", "steak", "summer", "bbq", "raw"]', '[{"group_name": "Herbs & Aromatics", "items": [{"name": "fresh flat-leaf parsley", "quantity": 40, "unit": "g", "preparation": "leaves only, washed and dried", "notes": "approx 1 large bunch", "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh oregano", "quantity": 10, "unit": "g", "preparation": "leaves stripped", "notes": "or 3g dried oregano", "substitutions": [], "ingredient_id": "f0596861-6e9b-4e5d-9f5d-630c54cb3eb4", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "peeled", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh red chili", "quantity": 1, "unit": null, "preparation": "deseeded and finely minced", "notes": "approx 15g; optional for heat", "substitutions": ["1 tsp red pepper flakes"], "ingredient_id": "5080eb9a-d555-4558-94e5-d5700e96ff9b", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Liquids & Seasoning", "items": [{"name": "red wine vinegar", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "9e1b7e74-fdcb-4836-8349-4f7ad86d62df", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 120, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 4, "unit": "g", "preparation": null, "notes": "coarse kosher salt preferred", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste (approx 1g)", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Finely chop the parsley, oregano, and garlic by hand. Aim for a fine mince but avoid turning the herbs into a paste.", "structured": {"action": "MINCE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Do not use a food processor; it tears the herbs, causing them to release bitter compounds and oxidize quickly."]}, {"step_number": 2, "phase": "mix", "text": "In a mixing bowl, combine the chopped herbs, garlic, chili (if using), red wine vinegar, salt, and pepper. Stir well and let sit for 10 minutes.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": ["This brief rest allows the salt to dissolve and the vinegar to hydrate the dried oregano (if using), softening the garlic''s raw edge."]}, {"step_number": 3, "phase": "finish", "text": "Stream in the olive oil while whisking gently with a fork. Do not emulsify vigorously; the oil and vinegar should remain somewhat separated.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Transfer to a jar and let the sauce stand at room temperature for at least 20 minutes before serving to allow flavors to meld.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT30M", "total_time": "PT45M", "overnight_required": false, "yields": "250ml", "yield_count": 8, "serving_size_g": 30}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Keto", "Paleo", "Whole30", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 140.51, "protein_g": 0.35, "carbohydrates_g": 1.33, "fat_g": 15.09, "saturated_fat_g": 2.08, "trans_fat_g": null, "monounsaturated_fat_g": 10.97, "polyunsaturated_fat_g": 1.59, "fiber_g": 0.35, "sugar_g": 0.12, "sodium_mg": 198.2, "cholesterol_mg": null, "potassium_mg": 47.58, "calcium_mg": 31.72, "iron_mg": 0.95, "magnesium_mg": 3.49, "phosphorus_mg": 6.94, "zinc_mg": 0.08, "vitamin_a_mcg": 24.72, "vitamin_c_mg": 11.95, "vitamin_d_mcg": null, "vitamin_e_mg": 2.2, "vitamin_k_mcg": 91.27, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.01, "niacin_mg": 0.08, "folate_mcg": 7.68, "water_g": 12.59, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves after 24 hours. Oil may solidify; bring to room temperature before serving.", "duration": "P1W"}, "freezer": {"notes": "Freeze in ice cube trays. Herb texture will soften significantly upon thawing.", "duration": "P3M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Medium mixing bowl", "required": true, "alternative": null}, {"name": "Glass jar with lid", "required": false, "alternative": "Airtight container"}]', '[{"symptom": "Sauce tastes bitter", "likely_cause": "Olive oil was processed in a blender or herbs were bruised", "prevention": "Always hand chop herbs and whisk in oil by hand", "fix": "Add a small splash of warm water or a pinch of sugar to mask bitterness"}, {"symptom": "Sauce is too acidic", "likely_cause": "Vinegar to oil ratio is too high", "prevention": "Measure liquids carefully", "fix": "Add more olive oil 15ml at a time until balanced"}]', '["Traditional Argentine chimichurri is a ''broken'' sauce, not a creamy emulsion like pesto or mayonnaise. The oil should sit on top of the vinegar and herbs.", "While fresh oregano is used here for vibrancy, many traditional recipes use dried oregano. If using dried, increase the initial maceration time with the vinegar to 20 minutes to rehydrate it fully.", "For the most authentic flavor, look for ''Aji Molido'' (crushed Argentine red pepper) instead of standard red pepper flakes.", "This sauce is best served at room temperature. If refrigerated, the olive oil will congeal; simply leave it on the counter for 30 minutes before using."]', '"Chimichurri is the inseparable partner to ''asado'' (barbecue) in Argentina and Uruguay. Its name''s origin is debated, but its function is clear: the sharp acidity and herbal freshness cleanse the palate between bites of rich, fatty grilled beef and offal."', 140.51);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('acc92ead-d4d7-44d5-801c-63fbaa101811', 'Creamy Apple and Scallion Coleslaw', 'A crisp, refreshing twist on classic slaw where sweet, crunchy apples and piquant scallions cut through a rich, tangy dressing. The texture is lively and light, perfect for balancing heavy main courses.', 'side dish', 'American', 'Easy', '["slaws", "cabbage", "scallion", "side dish", "vegetarian", "bbq side", "summer", "picnic"]', '[{"group_name": "Vegetables & Fruit", "items": [{"name": "green cabbage", "quantity": 400, "unit": "g", "preparation": "shredded", "notes": "approx. half a small head", "substitutions": [], "ingredient_id": "3665bd9f-fcae-44a3-a11d-16c4ca6e52bd", "nutrition_source": "Aggregated Public Data"}, {"name": "red apple", "quantity": 2, "unit": null, "preparation": "cored and julienned", "notes": "approx. 300g; Gala or Fuji recommended", "substitutions": [], "ingredient_id": "9985672b-aa9f-4125-8a32-62d520c99d6f", "nutrition_source": "USDA FoodData Central"}, {"name": "scallions", "quantity": 4, "unit": null, "preparation": "thinly sliced", "notes": "approx. 40g; use both white and green parts", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "carrots", "quantity": 100, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Creamy Dressing", "items": [{"name": "mayonnaise", "quantity": 80, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "97b74a34-8c1f-4c58-b70e-42c1de6d12aa", "nutrition_source": "USDA FoodData Central"}, {"name": "greek yogurt", "quantity": 40, "unit": "g", "preparation": null, "notes": "plain, whole milk preferred", "substitutions": ["sour cream"], "ingredient_id": "61eae1a4-8517-4da8-8c29-34288cb7d8c7", "nutrition_source": "USDA FoodData Central"}, {"name": "apple cider vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": ["maple syrup", "white sugar"], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "3e25e626-c9b4-4b62-9d08-7c650bcb3d2b", "nutrition_source": "Aggregated Public Data"}, {"name": "celery seeds", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "30c3f84e-7e3c-43a2-affa-a10986bed987", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the cabbage by removing the outer leaves and core, then finely shredding it with a knife or mandoline. Grate the carrots and thinly slice the scallions on a bias.", "structured": {"action": "SHRED", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Slice the apples into thin matchsticks (julienne). Leave the skin on for color and texture.", "structured": {"action": "JULIENNE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Soak apple slices in cold water with a splash of lemon juice if not using immediately to prevent browning."]}, {"step_number": 3, "phase": "prep", "text": "In a small mixing bowl, whisk together the mayonnaise, Greek yogurt, apple cider vinegar, honey, Dijon mustard, celery seeds, salt, and black pepper until smooth and emulsified.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Combine the shredded cabbage, grated carrots, sliced scallions, and apple matchsticks in a large mixing bowl.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Pour the dressing over the vegetable mixture and toss thoroughly until every piece is evenly coated.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Cover and refrigerate for at least 30 minutes before serving. This allows the flavors to meld and the cabbage to soften slightly.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT30M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT30M", "total_time": "PT50M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 130}', '{"flags": ["Vegetarian", "Gluten-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 160.45, "protein_g": 2.13, "carbohydrates_g": 16.22, "fat_g": 10.42, "saturated_fat_g": 1.59, "trans_fat_g": 0.03, "monounsaturated_fat_g": 2.31, "polyunsaturated_fat_g": 6.02, "fiber_g": 3.71, "sugar_g": 10.47, "sodium_mg": 346.5, "cholesterol_mg": 5.93, "potassium_mg": 253.11, "calcium_mg": 56.06, "iron_mg": 0.79, "magnesium_mg": 16.02, "phosphorus_mg": 36.52, "zinc_mg": 0.26, "vitamin_a_mcg": 153.12, "vitamin_c_mg": 29.72, "vitamin_d_mcg": 0.03, "vitamin_e_mg": 0.68, "vitamin_k_mcg": 39.11, "vitamin_b6_mg": 0.05, "vitamin_b12_mcg": 0.02, "thiamin_mg": 0.03, "riboflavin_mg": 0.04, "niacin_mg": 0.26, "folate_mcg": 9.71, "water_g": 138.32, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Texture softens significantly after 24 hours. Stir well before reserving.", "duration": "P3D"}, "freezer": {"notes": "Do not freeze; mayonnaise and raw vegetables will separate and lose texture.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Box grater", "required": false, "alternative": "Food processor with shredding disc"}]', '[{"symptom": "Coleslaw is watery at the bottom", "likely_cause": "Salt drew moisture out of the cabbage over time", "prevention": "Serve immediately after chilling, or salt and drain cabbage before dressing", "fix": "Drain excess liquid from the bottom of the bowl and re-toss before serving"}, {"symptom": "Dressing is too bland", "likely_cause": "Under-seasoning relative to the volume of vegetables", "prevention": "Taste the dressing before adding it to the vegetables; it should taste slightly too salty and tart on its own", "fix": "Add a splash more vinegar and a pinch of salt"}]', '["Using a mix of mayonnaise and Greek yogurt lightens the texture and adds a probiotic tang that complements the apples.", "Cut the apples last, right before tossing, to ensure they stay crisp and white without needing a lemon juice soak.", "For the best texture, slice the cabbage as thinly as possible; thick chunks can be tough to chew.", "Celery seed is the ''secret'' ingredient that gives coleslaw its signature deli-style flavor\u2014do not skip it."]', '"While the term ''coleslaw'' originates from the Dutch ''koolsla'' (cabbage salad), this creamy, sweet-savory variation incorporating apples reflects a modern American approach to picnic staples, often served alongside barbecue to cut through rich, smoky meats."', 160.45);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('acecd3f4-fec7-4ab7-935d-1d617c5c4bfa', 'Classic Prosciutto and Mozzarella Stromboli', 'A golden, crusty Italian-American rolled bread filled with savory prosciutto di Parma, melted low-moisture mozzarella, and a thick, herbaceous tomato sauce. The result is a spiraled masterpiece with a crisp exterior and a gooey, savory interior.', 'dinner', 'Italian', 'Intermediate', '["stromboli", "prosciutto", "mozzarella", "tomato", "italian-american", "pizza roll", "comfort food"]', '[{"group_name": "Pizza Dough", "items": [{"name": "bread flour", "quantity": 300, "unit": "g", "preparation": null, "notes": "High protein flour yields a better chew", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "warm water", "quantity": 180, "unit": "ml", "preparation": "40\u00b0C/105\u00b0F", "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "instant yeast", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b5658d19-b726-4ddb-b56e-74884c61e753", "nutrition_source": "USDA FoodData Central"}, {"name": "sugar", "quantity": 6, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 8, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Rich Tomato Sauce", "items": [{"name": "tomato passata", "quantity": 150, "unit": "ml", "preparation": null, "notes": "Strained tomatoes", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic powder", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "177a312f-ef99-4398-9108-98f7a608a245", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "tomato paste", "quantity": 15, "unit": "g", "preparation": null, "notes": "To thicken the sauce", "substitutions": [], "ingredient_id": "1a1bddc5-66c3-4f44-bb24-72b8ac828ca6", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Filling & Assembly", "items": [{"name": "prosciutto di parma", "quantity": 120, "unit": "g", "preparation": "thinly sliced", "notes": null, "substitutions": [], "ingredient_id": "6b3bd037-dea6-4a87-85dc-3b889880b65c", "nutrition_source": "Aggregated Public Data"}, {"name": "low-moisture mozzarella cheese", "quantity": 200, "unit": "g", "preparation": "shredded", "notes": "Do not use fresh mozzarella in brine, it is too wet", "substitutions": [], "ingredient_id": "41aca251-8bbe-492d-9539-ba0ac6c15194", "nutrition_source": "USDA FoodData Central"}, {"name": "parmesan cheese", "quantity": 30, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh basil leaves", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": "beaten", "notes": "For egg wash, approx 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine warm water, sugar, and yeast in the bowl of a stand mixer. Let sit for 5 minutes until frothy to ensure yeast activity.", "structured": {"action": "PROOF", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Add flour, olive oil, and salt. Mix on low speed until a shaggy dough forms, then increase speed to medium-low and knead for 8-10 minutes until the dough is smooth and elastic.", "structured": {"action": "KNEAD", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": ["If kneading by hand, this will take about 12-15 minutes.", "The dough should pass the ''windowpane test''."]}, {"step_number": 3, "phase": "prep", "text": "Transfer dough to a lightly oiled bowl, cover with plastic wrap or a damp towel, and let rise in a warm place until doubled in size.", "structured": {"action": "PROOF", "temperature": {"celsius": 25, "fahrenheit": 77}, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "While dough rises, combine tomato passata, tomato paste, garlic powder, and oregano in a small saucepan. Simmer over low heat until reduced to a very thick, spreadable consistency.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": "Sauce should not be watery; it needs to be paste-like to prevent sogginess.", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Preheat oven to 200\u00b0C (400\u00b0F). Line a large baking sheet with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Punch down the risen dough. On a lightly floured surface, roll the dough out into a large rectangle, approximately 30x40cm (12x16 inches).", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Spread the reduced tomato sauce thinly over the dough, leaving a 3cm (1 inch) border on all sides. Layer the prosciutto evenly over the sauce, followed by the shredded mozzarella, parmesan, and basil leaves.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Do not overload the filling or the dough will tear during rolling."]}, {"step_number": 8, "phase": "assemble", "text": "Starting from the long edge, tightly roll the dough into a log. Pinch the seam and the ends firmly to seal completely. Place seam-side down on the prepared baking sheet.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Brush the entire exterior with the beaten egg. Use a sharp knife to cut 3-4 diagonal slits in the top to allow steam to escape.", "structured": {"action": "GLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "cook", "text": "Bake in the preheated oven for 20-25 minutes, or until the crust is deep golden brown and cheese is bubbling through the vents.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT25M", "doneness_cues": {"visual": "Deep golden brown crust, hollow sound when tapped.", "tactile": null}}, "tips": []}, {"step_number": 11, "phase": "finish", "text": "Remove from oven and let rest on the baking sheet for at least 10 minutes before slicing. This allows the cheese to set and prevents the filling from running out.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT1H30M", "total_time": "PT2H15M", "overnight_required": false, "yields": "1 large stromboli (4 servings)", "yield_count": 4, "serving_size_g": 215}', '{"flags": ["Nut-Free", "Soy-Free"], "not_suitable_for": ["Vegetarians", "Vegans", "Gluten-Free diets"]}', '{"per_serving": {"calories": 598.51, "protein_g": 33.35, "carbohydrates_g": 65.16, "fat_g": 22.11, "saturated_fat_g": 8.9, "trans_fat_g": 0.37, "monounsaturated_fat_g": 6.76, "polyunsaturated_fat_g": 1.51, "fiber_g": 3.34, "sugar_g": 4.61, "sodium_mg": 1520.26, "cholesterol_mg": 83.6, "potassium_mg": 563.49, "calcium_mg": 472.33, "iron_mg": 2.17, "magnesium_mg": 45.88, "phosphorus_mg": 458.83, "zinc_mg": 2.96, "vitamin_a_mcg": 165.7, "vitamin_c_mg": 7.25, "vitamin_d_mcg": 0.49, "vitamin_e_mg": 1.05, "vitamin_k_mcg": 15.24, "vitamin_b6_mg": 0.14, "vitamin_b12_mcg": 1.04, "thiamin_mg": 0.25, "riboflavin_mg": 0.34, "niacin_mg": 1.57, "folate_mcg": 71.18, "water_g": 91.68, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Wrap tightly in foil or plastic wrap once cooled.", "duration": "P3D"}, "freezer": {"notes": "Freeze slices individually; thaw before reheating.", "duration": "P2M"}, "reheating": "Reheat in a 175\u00b0C (350\u00b0F) oven for 10-15 minutes to restore crispness. Microwave is not recommended as it destroys the texture.", "does_not_keep": false}', '[{"name": "Stand mixer with dough hook", "required": false, "alternative": "Large mixing bowl and hands"}, {"name": "Large baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Rolling pin", "required": true, "alternative": "Clean wine bottle"}, {"name": "Pastry brush", "required": true, "alternative": "Paper towel or fingers"}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}]', '[{"symptom": "Stromboli is soggy inside or underbaked", "likely_cause": "Tomato sauce was too wet or too much filling was used", "prevention": "Reduce sauce until it is paste-like and use low-moisture mozzarella", "fix": "Bake longer at a lower temperature (175\u00b0C/350\u00b0F) to dry out the interior without burning the crust"}, {"symptom": "Filling leaked out during baking", "likely_cause": "Seams were not pinched tightly enough or steam vents were omitted", "prevention": "Pinch seams aggressively and ensure vents are cut on top", "fix": "Scoop leaked cheese back onto slices when serving; cannot fix the loaf itself"}]', '["Low-moisture mozzarella is critical here. Fresh mozzarella releases too much whey and will destroy the dough structure.", "If you want extra sauce, serve warm marinara on the side for dipping rather than putting too much inside the roll.", "Prosciutto is salty, so be conservative with adding extra salt to the filling.", "Letting the dough rest for 10 minutes after baking makes slicing significantly cleaner."]', '"Stromboli is a distinctly Italian-American invention, likely originating in Philadelphia in the 1950s. Unlike a calzone, which is folded like a taco, a stromboli is rolled like a burrito or jelly roll. It was named after the film ''Stromboli'' starring Ingrid Bergman, capitalizing on the movie''s notoriety."', 598.51);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('acffba7d-e0d8-4f60-8e8e-70d12518e68a', 'Scallion and Cumin Uyghur Nan', 'A golden, tandoor-style flatbread characterized by its distinct shape—a thick, chewy rim surrounding a thin, crisp center stamped with decorative patterns. The dough is enriched with the earthy aroma of roasted cumin seeds and the fresh, savory bite of scallions, creating a perfect balance of texture and flavor.', 'bread', 'Uyghur', 'Intermediate', '["bread flour", "cumin seed", "scallion", "vegetarian", "vegan", "uyghur", "central asian", "flatbread", "baking"]', '[{"group_name": "Dough", "items": [{"name": "bread flour", "quantity": 500, "unit": "g", "preparation": null, "notes": "High protein content is essential for the chewy texture", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "warm water", "quantity": 320, "unit": "ml", "preparation": "approx 35\u00b0C", "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "neutral oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "Vegetable or sunflower oil", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "instant yeast", "quantity": 7, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b5658d19-b726-4ddb-b56e-74884c61e753", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Topping", "items": [{"name": "scallions", "quantity": 4, "unit": null, "preparation": "finely chopped", "notes": "approx 60g, green and white parts", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "cumin seeds", "quantity": 8, "unit": "g", "preparation": "whole", "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 20, "unit": "ml", "preparation": null, "notes": "for glazing", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 10, "unit": "ml", "preparation": null, "notes": "mixed with the glazing oil", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine bread flour, instant yeast, and salt in a large bowl. Add the warm water (35\u00b0C/95\u00b0F) and 30ml oil. Mix until a shaggy dough forms.", "structured": {"action": "MIX", "temperature": {"celsius": 35, "fahrenheit": 95}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Knead the dough vigorously on a surface or in a mixer until smooth, elastic, and slightly tacky but not sticky. This develops the gluten structure required for the rim.", "structured": {"action": "KNEAD", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": null, "tactile": "Smooth, elastic, passes windowpane test"}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Place dough in a lightly oiled bowl, cover with a damp cloth, and let rise in a warm place until doubled in size.", "structured": {"action": "PROOF", "temperature": null, "duration": "PT1H", "doneness_cues": {"visual": "Doubled in volume", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Place a baking stone or steel on the middle rack of the oven. Preheat to the highest possible setting, ideally 250\u00b0C/480\u00b0F or higher, for at least 45 minutes.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 250, "fahrenheit": 482}, "duration": "PT45M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Punch down the dough and divide into 4 equal pieces (approx 215g each). Shape each into a tight round ball. Cover and rest for 15 minutes to relax the gluten.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Flatten a dough ball. Using your fingers, press the center down firmly to flatten it while leaving a 2cm thick rim around the edge. The center should be very thin (3-5mm).", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Thick rim, thin center", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Dock the thin center aggressively using a bread stamp (chekich) or a fork. This prevents the center from rising during baking. The rim should remain undocked.", "structured": {"action": "DOCK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Mix the glazing oil with the water. Brush the entire surface of the breads. Sprinkle the centers generously with chopped scallions and cumin seeds. Press the toppings lightly into the dough.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Slide the breads onto the hot baking stone. Bake until golden brown with some charred spots on the rim.", "structured": {"action": "BAKE", "temperature": {"celsius": 250, "fahrenheit": 482}, "duration": "PT12M", "doneness_cues": {"visual": "Golden brown, blistered rim", "tactile": null}}, "tips": []}]', '{"active_time": "PT40M", "passive_time": "PT1H30M", "total_time": "PT2H10M", "overnight_required": false, "yields": "4 flatbreads", "yield_count": 4, "serving_size_g": 225}', '{"flags": ["Vegetarian", "Vegan", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 583.49, "protein_g": 14.21, "carbohydrates_g": 98.08, "fat_g": 14.33, "saturated_fat_g": 2.04, "trans_fat_g": null, "monounsaturated_fat_g": 0.47, "polyunsaturated_fat_g": 0.59, "fiber_g": 4.45, "sugar_g": 0.73, "sodium_mg": 981.22, "cholesterol_mg": null, "potassium_mg": 228.28, "calcium_mg": 51.07, "iron_mg": 3.08, "magnesium_mg": 39.62, "phosphorus_mg": 161.68, "zinc_mg": 1.17, "vitamin_a_mcg": 8.78, "vitamin_c_mg": 2.98, "vitamin_d_mcg": null, "vitamin_e_mg": 0.23, "vitamin_k_mcg": 31.54, "vitamin_b6_mg": 0.1, "vitamin_b12_mcg": null, "thiamin_mg": 0.37, "riboflavin_mg": 0.14, "niacin_mg": 2.44, "folate_mcg": 83.25, "water_g": 111.1, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight bag to prevent drying out.", "duration": "P3D"}, "freezer": {"notes": "Wrap tightly in foil and then plastic. Reheat directly from frozen.", "duration": "P2M"}, "reheating": "Sprinkle lightly with water and reheat in a 180\u00b0C oven for 5-8 minutes until warm and crisp.", "does_not_keep": false}', '[{"name": "Baking stone or baking steel", "required": true, "alternative": "Heavy baking sheet inverted"}, {"name": "Bread stamp (Chekich)", "required": false, "alternative": "Fork"}, {"name": "Stand mixer with dough hook", "required": false, "alternative": "Large mixing bowl and hands"}, {"name": "Pastry brush", "required": true, "alternative": null}]', '[{"symptom": "Center of the bread puffs up like a balloon", "likely_cause": "Insufficient docking (holes were not deep enough or too few)", "prevention": "Press the fork or stamp all the way through the dough firmly; cover the entire center area.", "fix": "Open oven quickly and pierce the bubble with a sharp knife to deflate, then continue baking."}]', '["To mimic a tandoor oven''s intense heat at home, preheating your baking stone for at least 45 minutes is non-negotiable.", "Spraying the oven walls with water immediately after loading the bread can help create steam, improving the crust texture.", "If you do not have a chekich (bread stamp), use a fork to create a dense pattern of holes; this is functionally necessary, not just decorative.", "For a glossier, non-vegan finish, you can replace the oil/water glaze with a mixture of egg yolk and a splash of milk."]', '"Nan is the daily staple of the Uyghur people in the Xinjiang region. The distinctive rim and stamped center (chekich) are iconic, designed to maximize crust while allowing the bread to be stacked easily. This version, flavored with alliums and cumin, reflects the heavy influence of Silk Road spices on the region''s cuisine."', 583.49);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ad41be36-5b57-4783-a2bb-f835db28f06b', 'Rustic Buttermilk Rhubarb Cake', 'A tender, moist farmhouse-style crumb cake where the sharp acidity of spring rhubarb cuts through a rich, vanilla-scented batter. The fruit softens into jammy pockets during baking, topped with a crunchy sugar crust.', 'baked good', 'American', 'Easy', '["buttermilk", "rhubarb", "dessert", "spring", "rustic", "cake", "tea time"]', '[{"group_name": "Fruit Preparation", "items": [{"name": "fresh rhubarb", "quantity": 350, "unit": "g", "preparation": "trimmed and cut into 1cm pieces", "notes": "Choose thinner, redder stalks for best color", "substitutions": [], "ingredient_id": "293d2132-013e-4594-801e-4d86e1d04df0", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 15, "unit": "g", "preparation": null, "notes": "To coat fruit", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dry Ingredients", "items": [{"name": "all-purpose flour", "quantity": 250, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wet Ingredients", "items": [{"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "room temperature/softened", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 200, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "large egg", "quantity": 1, "unit": null, "preparation": "room temperature", "notes": "approx 50-55g without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "buttermilk", "quantity": 240, "unit": "ml", "preparation": "shaken well", "notes": null, "substitutions": [], "ingredient_id": "de1c3d44-e3e7-47d2-a315-83a46edfb165", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Topping", "items": [{"name": "demerara or turbinado sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": "For crunch", "substitutions": ["Granulated sugar"], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 175\u00b0C (350\u00b0F). Grease the 23cm (9-inch) cake pan with butter and line the bottom with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a small bowl, toss the chopped rhubarb with the 15g of flour. This coating prevents the fruit from sinking to the bottom of the cake during baking.", "structured": {"action": "DREDGE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a medium bowl, whisk together the 250g flour, baking powder, baking soda, and salt until well combined.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "In a large bowl or stand mixer fitted with the paddle attachment, beat the softened butter and granulated sugar on medium-high speed until pale and fluffy (about 3-4 minutes).", "structured": {"action": "CREAM", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Pale yellow, almost white", "tactile": "Airy and light texture"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the egg and vanilla extract to the butter mixture. Beat until fully incorporated, scraping down the sides of the bowl as needed.", "structured": {"action": "BEAT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Reduce mixer speed to low. Add the flour mixture in three parts, alternating with the buttermilk in two parts (dry-wet-dry-wet-dry). Mix only until the flour streaks disappear to avoid toughening the gluten.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Do not overmix at this stage; a few small lumps are acceptable."]}, {"step_number": 7, "phase": "assemble", "text": "Gently fold the flour-dusted rhubarb into the thick batter using a spatula. Transfer the batter to the prepared pan and smooth the top.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Sprinkle the demerara sugar evenly over the surface of the batter.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Bake in the center of the oven for 45-55 minutes. The cake is done when the top is golden brown and a tester inserted into the center comes out clean (internal temperature approx 93\u00b0C/200\u00b0F).", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT50M", "doneness_cues": {"visual": "Golden brown crust", "tactile": "Tester comes out clean"}}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Let the cake cool in the pan for 15 minutes, then run a knife around the edge and invert onto a rack to cool completely.", "structured": {"action": "COOL", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT50M", "total_time": "PT1H10M", "overnight_required": false, "yields": "1 23cm (9-inch) cake", "yield_count": 8, "serving_size_g": 115}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 367.1, "protein_g": 5.71, "carbohydrates_g": 57.72, "fat_g": 12.99, "saturated_fat_g": 7.73, "trans_fat_g": null, "monounsaturated_fat_g": 3.71, "polyunsaturated_fat_g": 0.74, "fiber_g": 1.68, "sugar_g": 30.98, "sodium_mg": 324.61, "cholesterol_mg": 55.36, "potassium_mg": 220.45, "calcium_mg": 114.19, "iron_mg": 0.69, "magnesium_mg": 17.09, "phosphorus_mg": 95.41, "zinc_mg": 0.5, "vitamin_a_mcg": 114.71, "vitamin_c_mg": 3.8, "vitamin_d_mcg": 0.13, "vitamin_e_mg": 0.55, "vitamin_k_mcg": 13.97, "vitamin_b6_mg": 0.04, "vitamin_b12_mcg": 0.15, "thiamin_mg": 0.06, "riboflavin_mg": 0.11, "niacin_mg": 0.58, "folate_mcg": 16.54, "water_g": 79.38, "alcohol_g": 0.22, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Cover tightly to prevent drying out. Bring to room temperature before eating.", "duration": "P5D"}, "freezer": {"notes": "Wrap individual slices in plastic wrap and foil.", "duration": "P3M"}, "reheating": "Warm gently in a low oven or microwave for 10-15 seconds to refresh the crumb.", "does_not_keep": false}', '[{"name": "23cm (9-inch) round cake pan", "required": true, "alternative": "23cm square baking dish"}, {"name": "Stand mixer or hand mixer", "required": true, "alternative": "Whisk and strong arm"}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Rubber spatula", "required": true, "alternative": null}, {"name": "Cooling rack", "required": true, "alternative": null}]', '[{"symptom": "Cake is dense or rubbery", "likely_cause": "Overmixing after adding flour or ingredients were too cold", "prevention": "Stop mixing as soon as flour disappears; ensure butter, egg, and buttermilk are at room temperature.", "fix": "Cannot be fixed, but can be served warm with custard to mask texture."}, {"symptom": "Rhubarb sank to the bottom", "likely_cause": "Batter was too thin or fruit wasn''t coated in flour", "prevention": "Ensure the fruit is tossed in flour before adding; do not reduce the flour quantity in the main batter.", "fix": "Invert the cake and serve it ''upside down'' fruit-side up."}]', '["Room temperature ingredients are critical for this method; if the buttermilk or eggs are cold, the butter will seize, leading to a grainy batter.", "If you cannot find buttermilk, mix 240ml of whole milk with 15ml of lemon juice or white vinegar and let sit for 10 minutes.", "For a more ''pastry'' like finish, you can dot the top with small cubes of cold butter before sprinkling the sugar.", "Serve warm with a dollop of unsweetened whipped cream to balance the sweet cake and tart fruit."]', '"Rhubarb, often called the ''pie plant,'' was popularized in early American and British baking as one of the first crops to appear in spring. This cake style mimics the simplicity of a ''buckle'' or ''slump,'' dishes designed to highlight seasonal produce without fussy technique."', 367.1);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ade99c76-388e-431e-b80c-69ed0d4c6f5a', 'Pan-Fried Skate Wings with Nutty Brown Butter & Olive Oil Mash', 'Sweet, delicate strands of skate wing pan-seared to a golden crisp, bathed in a classic beurre noisette elevated with toasted hazelnuts, capers, and lemon. Paired with a luxurious, dairy-free olive oil potato purée that highlights the grassy notes of premium extra virgin olive oil.', 'dinner', 'French', 'Intermediate', '["skate", "fish", "seafood", "butter sauce", "potatoes", "quick", "french", "dinner"]', '[{"group_name": "Olive Oil Mash", "items": [{"name": "yukon gold potatoes", "quantity": 600, "unit": "g", "preparation": "peeled and cut into 3cm chunks", "notes": "or other starchy variety like Maris Piper", "substitutions": [], "ingredient_id": "a9d640ff-a969-4f0a-9a92-974f376ac272", "nutrition_source": "Aggregated Public Data"}, {"name": "extra virgin olive oil", "quantity": 80, "unit": "ml", "preparation": "high quality", "notes": "robust flavor profile preferred", "substitutions": [], "ingredient_id": "036c7254-3de5-4c6e-a2e7-366ad4d05077", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "plus more for boiling water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "cooking water", "quantity": 30, "unit": "ml", "preparation": null, "notes": "reserved from potatoes", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Skate Wings", "items": [{"name": "skate wings", "quantity": 2, "unit": null, "preparation": "skinned and trimmed", "notes": "approx 200-250g each", "substitutions": [], "ingredient_id": "7c4e1c0b-a47e-4af1-ba09-de5bcb6f07b8", "nutrition_source": "Aggregated Public Data"}, {"name": "all-purpose flour", "quantity": 40, "unit": "g", "preparation": null, "notes": "for dredging", "substitutions": ["rice flour", "gluten-free blend"], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "grapeseed or canola", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}, {"name": "unsalted butter", "quantity": 15, "unit": "g", "preparation": null, "notes": "for frying", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "white pepper", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Nutty Brown Butter Sauce", "items": [{"name": "unsalted butter", "quantity": 80, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "hazelnuts", "quantity": 20, "unit": "g", "preparation": "toasted, skins removed, roughly chopped", "notes": "optional but recommended for texture", "substitutions": [], "ingredient_id": "4a2947d7-4339-48a9-89b7-039c446295e4", "nutrition_source": "Aggregated Public Data"}, {"name": "capers", "quantity": 15, "unit": "g", "preparation": "drained and rinsed", "notes": null, "substitutions": [], "ingredient_id": "e7301d2c-b906-4ef8-917e-787be0b25880", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": "about half a lemon", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "flat-leaf parsley", "quantity": 5, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Place peeled potatoes in a large pot and cover with cold water by 2cm. Season water generously with salt. Bring to a boil, then reduce heat and simmer until tender when pierced with a knife.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "While potatoes cook, pat the skate wings thoroughly dry with paper towels. Season both sides with salt and white pepper. Dredge lightly in flour, shaking off any excess.", "structured": {"action": "DREDGE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "finish", "text": "Drain potatoes, reserving about 30ml of the cooking liquid. Immediately pass potatoes through a ricer back into the hot pot. Whisk in the olive oil in a steady stream to emulsify. Add reserved water if needed for consistency. Season with salt to taste. Cover and keep warm.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Heat neutral oil and 15g butter in the large skillet over medium-high heat. Once the butter foams and subsides, carefully lay the skate wings in the pan. Fry undisturbed until golden brown.", "structured": {"action": "FRY", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Flip the fish carefully using a fish spatula. Cook on the second side until the flesh pulls away easily from the cartilage bone in the center. Transfer fish to warm plates.", "structured": {"action": "FRY", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": null, "tactile": "Flesh separates from cartilage"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Wipe out the skillet if there is burnt flour. Add the 80g of cold butter. Melt over medium heat, swirling constantly, until the milk solids turn a golden hazelnut brown and smell nutty.", "structured": {"action": "CARAMELIZE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Golden brown flecks", "tactile": "Foaming subsides"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Immediately remove from heat. Stir in hazelnuts, capers, lemon juice, and parsley (be careful, it will sputter). Spoon the foaming sauce generously over the plated skate wings.", "structured": {"action": "SAUCE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT40M", "passive_time": "PT0M", "total_time": "PT40M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 480}', '{"flags": ["Pescatarian", "Soy-Free", "Peanut-Free"], "not_suitable_for": ["Milk allergy (butter in sauce)", "Tree nut allergy (hazelnuts)"]}', '{"per_serving": {"calories": 1272.79, "protein_g": 49.72, "carbohydrates_g": 81.8, "fat_g": 86.67, "saturated_fat_g": 30.01, "trans_fat_g": null, "monounsaturated_fat_g": 11.15, "polyunsaturated_fat_g": 1.54, "fiber_g": 12.43, "sugar_g": 4.96, "sodium_mg": 1708.84, "cholesterol_mg": 102.13, "potassium_mg": 2641.42, "calcium_mg": 164.86, "iron_mg": 4.38, "magnesium_mg": 158.24, "phosphorus_mg": 694.49, "zinc_mg": 0.5, "vitamin_a_mcg": 367.45, "vitamin_c_mg": 70.36, "vitamin_d_mcg": null, "vitamin_e_mg": 1.21, "vitamin_k_mcg": 46.23, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": 0.09, "thiamin_mg": 0.03, "riboflavin_mg": 0.04, "niacin_mg": 0.36, "folate_mcg": 13.68, "water_g": 40.52, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Skate texture degrades rapidly; best consumed immediately. Mash keeps 3 days.", "duration": "P1D"}, "freezer": {"notes": "Do not freeze cooked skate; texture becomes rubbery.", "duration": null}, "reheating": "Gently reheat mash in a pot. Fish is best eaten fresh but can be warmed in a low oven.", "does_not_keep": true}', '[{"name": "Large heavy-bottomed skillet", "required": true, "alternative": "Stainless steel frying pan"}, {"name": "Large pot", "required": true, "alternative": null}, {"name": "Potato ricer", "required": true, "alternative": "Standard potato masher"}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Fish spatula", "required": true, "alternative": null}]', '[{"symptom": "Fish is soggy, not crisp", "likely_cause": "Pan was not hot enough or fish was not dried thoroughly before dredging", "prevention": "Ensure oil is shimmering and fish is bone-dry before flouring", "fix": "Cannot be fixed once cooked; remove skin before eating if unpleasant"}, {"symptom": "Butter sauce tastes bitter/burnt", "likely_cause": "Butter solids cooked too long past the ''noisette'' stage", "prevention": "Remove pan from heat immediately when solids turn light brown; have lemon juice ready to stop cooking", "fix": "Discard and start sauce over (butter burns rapidly)"}]', '["Skate wing meat has a unique structure; it consists of long strands of flesh separated by a flat layer of cartilage. To eat, scrape the meat off the cartilage with a fork.", "Always smell skate before cooking. If it smells like ammonia, it is past its prime and should not be eaten.", "For the mash, adding the olive oil while the potatoes are piping hot is crucial for the potatoes to absorb the flavor without becoming greasy.", "Beurre Noisette moves from nutty to burnt in seconds. Use a light-colored pan if possible to better judge the color change."]', '"Skate with brown butter (Raie au Beurre Noisette) is a quintessential French bistro dish. The acidity of the capers and lemon cuts through the richness of the browned butter and gelatinous quality of the wings, creating a perfect balance of textures and flavors."', 1272.79);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ae9684c5-4abf-4b6a-b745-6a611946a730', 'Classic Pork Ribs Adobo', 'Tender pork ribs braised in a pungent, savory, and tangy sauce of soy, vinegar, and aromatic garlic until falling off the bone, then finished under the broiler for a sticky, caramelized glaze. A beloved staple of Filipino cuisine that balances salty, sour, and slightly sweet notes.', 'dinner', 'Filipino', 'Intermediate', '["asian", "filipino", "pork rib", "dinner", "main course", "comfort food", "braised"]', '[{"group_name": "Meat & Marinade", "items": [{"name": "pork ribs", "quantity": 1500, "unit": "g", "preparation": "cut into individual ribs", "notes": "baby back or spare ribs", "substitutions": [], "ingredient_id": "c7a3823a-d8af-40aa-a343-12878a7c1094", "nutrition_source": "USDA FoodData Central"}, {"name": "soy sauce", "quantity": 120, "unit": "ml", "preparation": null, "notes": "standard salty soy sauce", "substitutions": [], "ingredient_id": "1a157828-0624-4e67-815d-8e6bdf8b23c2", "nutrition_source": "USDA FoodData Central"}, {"name": "cane vinegar", "quantity": 120, "unit": "ml", "preparation": null, "notes": "or white distilled vinegar", "substitutions": ["white vinegar", "apple cider vinegar"], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "crushed and peeled", "notes": "whole head, approx 50g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Braising Liquid", "items": [{"name": "water", "quantity": 240, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "whole black peppercorns", "quantity": 5, "unit": "g", "preparation": null, "notes": "approx 1 tbsp", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "dried bay leaves", "quantity": 4, "unit": null, "preparation": null, "notes": "approx 1g", "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}, {"name": "brown sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": "optional, for balance and glaze", "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "for searing", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine the soy sauce, vinegar, and crushed garlic in a large bowl. Add the ribs and toss to coat. Let marinate at room temperature for at least 30 minutes, or refrigerate for up to 4 hours.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Remove ribs from the marinade (reserve the marinade). Pat the ribs dry with paper towels to ensure a good sear.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat oil in a Dutch oven over medium-high heat. Sear the ribs in batches until browned on all sides, about 2-3 minutes per batch. Remove seared ribs and set aside.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Return all ribs to the pot. Pour in the reserved marinade, water, peppercorns, bay leaves, and sugar (if using). Bring to a boil, then lower heat to a simmer. Cover and braise for 60 to 90 minutes until the meat is tender and pulling away from the bone.", "structured": {"action": "BRAISE", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT1H30M", "doneness_cues": {"visual": "Meat pulling away from bone ends", "tactile": "Fork tender"}}, "tips": ["Do not stir immediately after adding the vinegar mixture; let it boil for a minute first to cook off the raw acid taste."]}, {"step_number": 5, "phase": "cook", "text": "Once tender, remove the ribs and place them on a foil-lined baking sheet. Increase the stove heat to high and boil the remaining sauce until reduced to a thick, syrupy glaze, about 10-15 minutes.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": "Sauce coats the back of a spoon", "tactile": "Syrupy consistency"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Preheat your oven''s broiler (grill setting). Brush the reduced glaze generously over the ribs.", "structured": {"action": "GLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Broil the ribs for 3-5 minutes until the sauce bubbles and caramelizes into a dark, sticky crust. Watch closely to prevent burning.", "structured": {"action": "BROIL", "temperature": {"celsius": 260, "fahrenheit": 500}, "duration": "PT5M", "doneness_cues": {"visual": "Dark caramelized spots and bubbling sauce", "tactile": null}}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT1H30M", "total_time": "PT2H", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 1116.65, "protein_g": 99.06, "carbohydrates_g": 15.12, "fat_g": 73.78, "saturated_fat_g": 21.04, "trans_fat_g": 0.19, "monounsaturated_fat_g": 23.92, "polyunsaturated_fat_g": 9.02, "fiber_g": 0.77, "sugar_g": 7.92, "sodium_mg": 2357.23, "cholesterol_mg": 326.25, "potassium_mg": 1524.35, "calcium_mg": 258.7, "iron_mg": 4.26, "magnesium_mg": 99.54, "phosphorus_mg": 1046.03, "zinc_mg": 13.04, "vitamin_a_mcg": 19.86, "vitamin_c_mg": 4.02, "vitamin_d_mcg": 4.5, "vitamin_e_mg": 0.89, "vitamin_k_mcg": 2.26, "vitamin_b6_mg": 2.19, "vitamin_b12_mcg": 2.66, "thiamin_mg": 2.03, "riboflavin_mg": 1.36, "niacin_mg": 32.84, "folate_mcg": 4.56, "water_g": 327.25, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Adobo improves in flavor after a day as the meat absorbs the sauce further.", "duration": "P4D"}, "freezer": {"notes": "Freeze in sauce to prevent drying out.", "duration": "P2M"}, "reheating": "Reheat gently on the stovetop with a splash of water, or in the microwave covered.", "does_not_keep": false}', '[{"name": "Dutch oven or heavy-bottomed pot", "required": true, "alternative": "Large deep skillet with lid"}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Aluminum foil", "required": false, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Measuring cups and spoons", "required": true, "alternative": null}, {"name": "Knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Meat is tough after braising", "likely_cause": "Cooking time was too short or heat was too high causing boiling instead of simmering", "prevention": "Maintain a gentle simmer and check for tenderness after 60 minutes", "fix": "Add a splash more water if sauce is dry, cover, and continue simmering until tender"}]', '["The ratio of soy sauce to vinegar is personal; 1:1 is a classic starting point, but feel free to adjust. Some prefer it saltier (more soy) or tangier (more vinegar).", "Letting the adobo rest before the final broil allows the meat fibers to relax and reabsorb juices.", "Using bone-in ribs adds significant depth and collagen to the sauce, creating a richer glaze than boneless cuts.", "Serve with plenty of steamed white rice to balance the potent salty-sour flavor profile."]', '"Adobo is considered the unofficial national dish of the Philippines. Derived from the Spanish word ''adobar'' (to marinade), the indigenous Filipino cooking method of preserving meat with vinegar and salt pre-dates Spanish colonization. Every household has its own version, ranging from dry and fried to wet and saucy."', 1116.65);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('b0ff9022-0b5e-41ed-9e85-b152aecc6312', 'Cardamom Phirni in Spiced Tuile Baskets with Strawberry Compôte', 'A sophisticated deconstruction of classic Indian flavors. Creamy, slow-cooked ground rice pudding (phirni) is chilled and served inside a delicate, crisp cardamom-infused tuile basket, topped with a tart, vibrant strawberry compôte to cut through the richness.', 'dessert', 'Indian Fusion', 'Advanced', '["dessert", "indian", "rice pudding", "strawberries", "cardamom", "baked", "fusion", "advanced"]', '[{"group_name": "Phirni (Rice Pudding)", "items": [{"name": "basmati rice", "quantity": 50, "unit": "g", "preparation": "soaked for 30 mins, drained", "notes": "Must be Basmati for aroma", "substitutions": [], "ingredient_id": "b671f3cd-cdec-4182-8911-82a06a22815a", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 1000, "unit": "ml", "preparation": null, "notes": "Full fat is essential for setting", "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "sugar", "quantity": 85, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "green cardamom pods", "quantity": 5, "unit": null, "preparation": "seeds only, crushed", "notes": "discard husks", "substitutions": [], "ingredient_id": "c56f6cd8-882c-487c-956f-3a91ee1fec07", "nutrition_source": "USDA FoodData Central"}, {"name": "saffron strands", "quantity": 1, "unit": null, "preparation": null, "notes": "generous pinch (~0.2g)", "substitutions": [], "ingredient_id": "7f9ec0c8-2db1-48ac-a2c9-9b1efce12cf3", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Strawberry Comp\u00f4te", "items": [{"name": "fresh strawberries", "quantity": 300, "unit": "g", "preparation": "hulled and quartered", "notes": null, "substitutions": [], "ingredient_id": "b2199214-7c2d-4083-92ae-b0a8a044e25b", "nutrition_source": "USDA FoodData Central"}, {"name": "sugar", "quantity": 40, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Cardamom Tuile Baskets", "items": [{"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": "very soft", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "icing sugar", "quantity": 60, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "egg whites", "quantity": 60, "unit": "g", "preparation": null, "notes": "approx 2 large eggs", "substitutions": [], "ingredient_id": "17645f6b-c1ea-4e82-a4b4-5ae8cb6a5a53", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "11e03c79-4bf6-47ed-babb-753b1a9789c9", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cardamom", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c56f6cd8-882c-487c-956f-3a91ee1fec07", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Grind the soaked, drained rice in a blender with a splash (approx. 20ml) of the milk to form a coarse paste. It should feel like wet sand, not a smooth flour.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": ["Do not over-blend into a smooth puree; the gritty texture is characteristic of Phirni."]}, {"step_number": 2, "phase": "cook", "text": "In a heavy-bottomed pan, bring the remaining milk to a boil. Reduce heat to medium-low, add the rice paste, and whisk vigorously immediately to prevent clumps.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Simmer gently, stirring frequently to prevent scorching on the bottom. Cook until the milk reduces and thickens to a custard consistency that coats the back of a spoon (nappe).", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT25M", "doneness_cues": {"visual": "Coats back of spoon", "tactile": "Thick creamy consistency"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Stir in sugar, crushed cardamom seeds, and saffron. Cook for another 5 minutes to dissolve sugar. Remove from heat, transfer to a bowl, cover with plastic wrap touching the surface (to prevent skin formation), and chill thoroughly.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT4H", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "For the comp\u00f4te: Combine strawberries, sugar, and lemon juice in a saucepan. Simmer over medium heat until berries soften and release juices, but still hold some shape. Let cool completely.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT12M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "For the baskets: Preheat oven to 180\u00b0C/350\u00b0F. Whisk softened butter and icing sugar until creamy. Gradually whisk in egg whites, followed by flour and ground cardamom until smooth.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Spread 2 tablespoons of batter onto a silicone mat into a thin 15cm circle. Bake only 2-3 at a time. Bake until edges are golden brown.", "structured": {"action": "BAKE", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT6M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from oven. Wait 15-30 seconds until the tuile is liftable but still pliable. Drape over an inverted glass or ramekin and gently press down to form a basket shape. Hold for 30 seconds until set. Repeat.", "structured": {"action": "SHAPE", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": ["If the cookies harden before you shape them, return the tray to the oven for 30 seconds to soften."]}, {"step_number": 9, "phase": "assemble", "text": "Just before serving, place a tuile basket on a plate. Fill with chilled Phirni. Top with a spoonful of strawberry comp\u00f4te and garnish with extra pistachios or rose petals if desired.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT1H15M", "passive_time": "PT4H30M", "total_time": "PT5H45M", "overnight_required": false, "yields": "6 filled baskets", "yield_count": 6, "serving_size_g": 180}', '{"flags": ["Vegetarian", "Egg-Free"], "not_suitable_for": ["Vegans (contains dairy)", "Celiacs (tuiles contain wheat flour)"]}', '{"per_serving": {"calories": 382.68, "protein_g": 8.44, "carbohydrates_g": 57.45, "fat_g": 13.88, "saturated_fat_g": 8.19, "trans_fat_g": null, "monounsaturated_fat_g": 3.74, "polyunsaturated_fat_g": 0.77, "fiber_g": 1.5, "sugar_g": 41.59, "sodium_mg": 91.03, "cholesterol_mg": 38.17, "potassium_mg": 343.06, "calcium_mg": 205.31, "iron_mg": 0.88, "magnesium_mg": 29.89, "phosphorus_mg": 177.24, "zinc_mg": 0.9, "vitamin_a_mcg": 145.58, "vitamin_c_mg": 30.16, "vitamin_d_mcg": 2.17, "vitamin_e_mg": 0.51, "vitamin_k_mcg": 2.34, "vitamin_b6_mg": 0.11, "vitamin_b12_mcg": 0.78, "thiamin_mg": 0.18, "riboflavin_mg": 0.4, "niacin_mg": 1.09, "folate_mcg": 40.37, "water_g": 206.48, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store components separately. Phirni and comp\u00f4te refrigerate well; baskets will soften if filled too early or refrigerated.", "duration": "P2D"}, "freezer": {"notes": "Not recommended. The texture of the rice pudding breaks down.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Heavy-bottomed saucepan", "required": true, "alternative": null}, {"name": "Blender or spice grinder", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Silicone baking mat", "required": true, "alternative": "Parchment paper"}, {"name": "Small glasses or ramekins", "required": true, "alternative": "Inverted muffin tin (for shaping baskets)"}, {"name": "Whisk", "required": true, "alternative": null}]', '[{"symptom": "Tuile baskets crack while shaping", "likely_cause": "The cookie cooled down too much before shaping", "prevention": "Bake only 2 at a time; work quickly once out of the oven", "fix": "Return the baking sheet to the oven for 30-45 seconds to soften the cookies again"}, {"symptom": "Phirni is too runny after chilling", "likely_cause": "Rice paste was too fine or mixture wasn''t reduced enough", "prevention": "Ensure rice is ground to coarse sand texture; cook until significantly thickened before chilling", "fix": "Return to pot and simmer longer, but be careful not to burn the sugar"}]', '["Texture is King: The rice for Phirni must be ''rava'' (semolina) consistency. If it''s too fine, you get glue; too coarse, you get gritty milk.", "The Tuile Timing: Shaping tuiles requires a ''Goldilocks'' moment. Too hot and they tear; too cold and they snap. Test the edge with a palette knife\u2014if it lifts without slumping, it''s ready to shape.", "Assembly Logic: Do not fill the baskets until the very last moment. The moisture from the pudding will make the crisp basket soggy within 10-15 minutes.", "Saffron Blooming: For maximum color, grind the saffron threads with a pinch of sugar before adding to the milk.", "Flavor Balance: The comp\u00f4te should be slightly tart (adjust lemon juice) to balance the high sugar content of the tuile and the creaminess of the pudding."]', '"Phirni is a quintessential North Indian dessert, traditionally served in unglazed clay pots (''shikoras'') which absorb excess moisture and impart an earthy aroma. This recipe elevates the humble festive dish by replacing the clay pot with a French-technique tuile basket, bridging the gap between rustic Mughal cuisine and modern patisserie."', 382.68);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('b1c2ec23-f2d0-4d7c-9fb1-91e0ad24e1eb', 'Velouté of Watercress with Caviar', 'A visually arresting emerald-green soup that balances the peppery bite of fresh watercress with a velvety potato-leek base. The dish is finished with a quenelle of crème fraîche and a decadent mound of caviar, adding a luxurious saline pop to every spoonful.', 'soup', 'French', 'Intermediate', '["french", "caviar", "cream", "great leftovers", "soup", "watercress", "dinner", "lunch", "appetizer", "elegant"]', '[{"group_name": "Soup Base", "items": [{"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "leeks (whites and light green parts only)", "quantity": 200, "unit": "g", "preparation": "washed and sliced", "notes": "approx. 2 medium leeks", "substitutions": [], "ingredient_id": "c689e786-49ea-4b98-9526-3b7bb15a8edc", "nutrition_source": "USDA FoodData Central"}, {"name": "yukon gold potatoes", "quantity": 250, "unit": "g", "preparation": "peeled and diced 1cm", "notes": null, "substitutions": [], "ingredient_id": "41f30ad1-82e5-4826-9de0-cd33ecd578c1", "nutrition_source": "USDA FoodData Central"}, {"name": "chicken stock", "quantity": 600, "unit": "ml", "preparation": null, "notes": "use high-quality vegetable stock for vegetarian adaptation (omit caviar)", "substitutions": ["Vegetable stock"], "ingredient_id": "7e254f45-046f-4812-bcdd-7e31c9bb59b8", "nutrition_source": "Aggregated Public Data"}, {"name": "watercress", "quantity": 300, "unit": "g", "preparation": "thick stems removed", "notes": "approx. 3-4 large bunches", "substitutions": [], "ingredient_id": "3d74325b-824d-447d-b50c-93abd1539cb0", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 100, "unit": "ml", "preparation": "35% fat or higher", "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish", "items": [{"name": "cr\u00e8me fra\u00eeche", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "d171100e-1088-4266-8d50-06cdedda7193", "nutrition_source": "USDA FoodData Central"}, {"name": "caviar", "quantity": 20, "unit": "g", "preparation": null, "notes": "Oscietra or Baeri recommended", "substitutions": [], "ingredient_id": "8684cff7-351b-49f8-a3de-780eabf25494", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, use sparingly due to caviar", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "white pepper", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare an ice bath in a large bowl. Bring a medium pot of salted water to a rolling boil.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Blanch the watercress in the boiling water for exactly 30 seconds until bright green, then immediately plunge into the ice bath to stop the cooking and set the chlorophyll. Drain well and squeeze out excess water.", "structured": {"action": "BLANCH", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": ["This step is the secret to the soup''s vibrant emerald color. If you cook the watercress in the stock too long, the soup will turn olive-drab."]}, {"step_number": 3, "phase": "cook", "text": "In the heavy-bottomed pot, melt the butter over medium-low heat. Add the sliced leeks and a pinch of salt. Sweat gently for 8-10 minutes without browning.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 110, "fahrenheit": 230}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the diced potatoes and stock to the pot. Bring to a simmer, cover, and cook for 15-20 minutes until the potatoes are completely tender and falling apart.", "structured": {"action": "SIMMER", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Remove the pot from heat. Add the blanched, squeezed watercress to the hot potato mixture. Transfer to a blender and puree on high speed until extremely smooth.", "structured": {"action": "PUREE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Pass the soup through a fine mesh sieve (chinois) back into the cleaned pot. This removes any fibrous watercress stems and ensures a Michelin-level silky texture.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Stir in the heavy cream and gently reheat to serving temperature (approx 75\u00b0C/167\u00b0F). Season with salt and white pepper, keeping in mind the saltiness of the caviar garnish.", "structured": {"action": "SEASON", "temperature": {"celsius": 75, "fahrenheit": 167}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Ladle the soup into warmed bowls. Place a dollop of cr\u00e8me fra\u00eeche in the center, create a small well in the cream, and top with a teaspoon of caviar. Serve immediately.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT20M", "total_time": "PT55M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 280}', '{"flags": ["Pescatarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": ["Vegans (dairy, fish roe)", "Vegetarians (fish roe)"]}', '{"per_serving": {"calories": 488.47, "protein_g": 13, "carbohydrates_g": 67.05, "fat_g": 20.04, "saturated_fat_g": 10.96, "trans_fat_g": 0.31, "monounsaturated_fat_g": 4.8, "polyunsaturated_fat_g": 1.26, "fiber_g": 5, "sugar_g": 6.56, "sodium_mg": 760.06, "cholesterol_mg": 79.63, "potassium_mg": 1016.56, "calcium_mg": 208.17, "iron_mg": 2.71, "magnesium_mg": 88.89, "phosphorus_mg": 216.07, "zinc_mg": 0.67, "vitamin_a_mcg": 344.4, "vitamin_c_mg": 40.94, "vitamin_d_mcg": 0.57, "vitamin_e_mg": 1.92, "vitamin_k_mcg": 212.45, "vitamin_b6_mg": 0.72, "vitamin_b12_mcg": 1.1, "thiamin_mg": 0.26, "riboflavin_mg": 0.24, "niacin_mg": 2.58, "folate_mcg": 59.76, "water_g": 146.95, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Color will darken from bright green to olive upon reheating; flavor improves.", "duration": "P2D"}, "freezer": {"notes": "Texture may become slightly grainy due to potatoes and cream; blend again upon reheating.", "duration": "P1M"}, "reheating": "Gently reheat on low on the stove to 70\u00b0C/158\u00b0F. Do not boil, or the soup will lose its vibrant color and the emulsion may split.", "does_not_keep": false}', '[{"name": "Large heavy-bottomed pot", "required": true, "alternative": null}, {"name": "Blender", "required": true, "alternative": "Immersion blender"}, {"name": "Fine mesh sieve (Chinois)", "required": true, "alternative": "Standard strainer"}, {"name": "Large bowl", "required": true, "alternative": null}, {"name": "Ice bath", "required": true, "alternative": null}]', '[{"symptom": "Soup is olive green or brown instead of bright green", "likely_cause": "The watercress was overcooked or the soup was kept hot for too long, causing chlorophyll degradation.", "prevention": "Strictly adhere to the blanch/shock method and add watercress only at the blending stage.", "fix": "Add a handful of raw spinach leaves and re-blend/strain to restore color without altering flavor significantly."}]', '["Use white pepper instead of black pepper to maintain the soup''s pristine green appearance without visible black specs.", "The potato variety matters; Yukon Gold (or similar waxy-starchy hybrid) provides creaminess without the gluey texture of pure russets or the hardness of waxy reds.", "Serve with a glass of Champagne or a crisp Chablis to cut through the richness of the cream and complement the brininess of the caviar.", "If the soup is too thick after blending, thin it with a splash of water or milk rather than more stock to preserve the pure watercress flavor."]', '"Watercress soup (Potage Cressonni\u00e8re) is a staple of French bourgeois cuisine, traditionally thickened with potato. By refining the texture through a chinois and adding caviar, this rustic dish is transformed into ''Potage Germiny,'' a style of soup often associated with Parisian fine dining in the early 20th century."', 488.47);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('b3357d6e-b116-4599-9ae0-54a20e440ec6', 'Lasagna Napoletana with Polpettine', 'A festive, incredibly hearty Southern Italian masterpiece. Unlike standard ragù lasagna, this Neapolitan style features layers of rich tomato sauce, creamy ricotta, gooey mozzarella, sliced hard-boiled eggs, and hundreds of tiny, fried meatballs.', 'main course', 'Italian', 'Advanced', '["lasagna", "italian", "main course", "pasta", "meatballs", "comfort food", "baked"]', '[{"group_name": "Tomato Sauce", "items": [{"name": "whole peeled tomatoes", "quantity": 1600, "unit": "g", "preparation": "crushed by hand", "notes": "2 large cans", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "cloves, crushed", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "onion", "quantity": 1, "unit": null, "preparation": "small, finely diced", "notes": "approx 100g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh basil", "quantity": 15, "unit": "g", "preparation": "leaves torn", "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Mini Meatballs (Polpettine)", "items": [{"name": "ground beef", "quantity": 250, "unit": "g", "preparation": "lean", "notes": null, "substitutions": [], "ingredient_id": "696b2887-6464-4698-a80a-6860f8633185", "nutrition_source": "Aggregated Public Data"}, {"name": "ground pork", "quantity": 250, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "95b412ba-c68f-4b61-ae87-42b44000956b", "nutrition_source": "USDA FoodData Central"}, {"name": "bread crumbs", "quantity": 80, "unit": "g", "preparation": "fine, dry", "notes": null, "substitutions": [], "ingredient_id": "92441189-214a-4a8a-9cfc-dd578fe0d179", "nutrition_source": "USDA FoodData Central"}, {"name": "parmesan cheese", "quantity": 50, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": "large", "notes": "approx 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "parsley", "quantity": 10, "unit": "g", "preparation": "fresh, minced", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 100, "unit": "ml", "preparation": null, "notes": "for frying", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}]}, {"group_name": "Assembly Layers", "items": [{"name": "lasagna sheets", "quantity": 500, "unit": "g", "preparation": "no-boil or par-boiled", "notes": "if using fresh pasta, blanch first", "substitutions": [], "ingredient_id": "7ad6742a-ab23-4424-9abf-7ff1e47643db", "nutrition_source": "Aggregated Public Data"}, {"name": "ricotta cheese", "quantity": 500, "unit": "g", "preparation": "drained", "notes": null, "substitutions": [], "ingredient_id": "7a68dbea-ec03-42ae-b0eb-983bf3d4c7b6", "nutrition_source": "USDA FoodData Central"}, {"name": "mozzarella cheese", "quantity": 400, "unit": "g", "preparation": "shredded or cubed", "notes": "low moisture preferred", "substitutions": [], "ingredient_id": "d10212b8-e285-49ec-9990-1433862b69d0", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 4, "unit": null, "preparation": "hard-boiled, peeled, sliced", "notes": "approx 200g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "parmesan cheese", "quantity": 80, "unit": "g", "preparation": "grated, for sprinkling", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the sauce. Heat olive oil in a large pot over medium heat. Saut\u00e9 the onions until translucent, then add crushed garlic for 1 minute. Add crushed tomatoes, basil, salt, and pepper. Simmer for 30 minutes until slightly thickened.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Prepare the meatballs. In a large bowl, mix ground beef, pork, bread crumbs, 50g parmesan, raw egg, minced parsley, salt, and pepper. Mix by hand until uniform.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Form mixture into very small balls, approximately the size of a hazelnut or small marble (1.5cm diameter). Heat vegetable oil in a frying pan and fry meatballs in batches until golden brown and cooked through. Drain on paper towels.", "structured": {"action": "FRY", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT15M", "doneness_cues": {"visual": "Golden brown exterior", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Place eggs in a saucepan of cold water. Bring to a boil, remove from heat, cover, and let stand for 10 minutes. Cool in ice water, peel, and slice into thin rounds.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Preheat oven to 190\u00b0C/375\u00b0F. Spread a thin layer of tomato sauce on the bottom of the baking dish.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Assemble the layers: Place pasta sheets, then dollop with ricotta. Scatter a generous handful of fried meatballs, sliced hard-boiled eggs, and mozzarella. Top with sauce and a dusting of parmesan. Repeat layers until the pan is full (usually 3-4 layers).", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Top the final layer of pasta with remaining sauce, mozzarella, and parmesan. Cover loosely with foil (tenting it so it doesn''t stick to the cheese). Bake for 25 minutes.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT25M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove foil and bake for another 15-20 minutes until the cheese is bubbling and golden brown spots appear.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT20M", "doneness_cues": {"visual": "Bubbling cheese with browned spots", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove from oven and let rest for at least 30 minutes before cutting. This is critical for the layers to set.", "structured": {"action": "REST", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT1H30M", "passive_time": "PT1H15M", "total_time": "PT2H45M", "overnight_required": false, "yields": "1 deep 9x13 inch pan (8-10 servings)", "yield_count": 8, "serving_size_g": 400}', '{"flags": [], "not_suitable_for": ["Vegetarians", "Vegans", "Gluten-Free", "Dairy-Free", "Egg-Free"]}', '{"per_serving": {"calories": 848.98, "protein_g": 48.99, "carbohydrates_g": 69.02, "fat_g": 42.22, "saturated_fat_g": 19.08, "trans_fat_g": 0.22, "monounsaturated_fat_g": 14.48, "polyunsaturated_fat_g": 2.77, "fiber_g": 6.84, "sugar_g": 10.85, "sodium_mg": 675.91, "cholesterol_mg": 219.93, "potassium_mg": 1064.83, "calcium_mg": 666.73, "iron_mg": 4.6, "magnesium_mg": 102.31, "phosphorus_mg": 625.36, "zinc_mg": 6.05, "vitamin_a_mcg": 258.98, "vitamin_c_mg": 31.13, "vitamin_d_mcg": 1.03, "vitamin_e_mg": 1.38, "vitamin_k_mcg": 34.62, "vitamin_b6_mg": 0.33, "vitamin_b12_mcg": 2.4, "thiamin_mg": 0.38, "riboflavin_mg": 0.65, "niacin_mg": 2.29, "folate_mcg": 39.69, "water_g": 134.56, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Tastes even better the next day as layers firm up.", "duration": "P4D"}, "freezer": {"notes": "Freeze cooked or uncooked. Thaw in fridge for 24 hours before reheating/baking.", "duration": "P3M"}, "reheating": "Cover with foil and reheat in oven at 160\u00b0C/320\u00b0F until warmed through to prevent drying.", "does_not_keep": false}', '[{"name": "Large baking dish (approx 23x33cm / 9x13 inch)", "required": true, "alternative": null}, {"name": "Large heavy-bottomed pot", "required": true, "alternative": null}, {"name": "Frying pan", "required": true, "alternative": null}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Small saucepan", "required": true, "alternative": null}]', '[{"symptom": "Lasagna collapses when sliced (soupiness)", "likely_cause": "Cut too soon after removing from oven", "prevention": "Allow the lasagna to rest for a full 30-45 minutes to let the cheese and juices set", "fix": "Let it stand longer; it will firm up as it cools"}]', '["The meatballs (polpettine) must be tiny\u2014think marble-sized. This ensures they distribute evenly within the layers rather than creating large lumps.", "Do not skip the frying step for the meatballs. Frying creates a crust that prevents them from becoming mushy when baked in the sauce.", "If using ''no-boil'' noodles, ensure they are completely covered by sauce, or they will remain tough. I prefer soaking no-boil noodles in hot tap water for 5 minutes before assembling.", "High-quality ricotta should be drained in a sieve for 30 minutes before using to prevent a watery lasagna.", "The hard-boiled eggs add a distinct creamy texture and richness that defines the Neapolitan style."]', '"This dish is a variation of Lasagna Napoletana, traditionally served during Carnevale (Carnival) in Southern Italy. It is a dish of abundance, designed to use up rich ingredients like meat and dairy before the fasting period of Lent begins."', 848.98);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('b357d20a-683f-4b29-a0ce-24c6e51f4104', 'Saffron Chicken and Almond Beignets', 'Crispy, airy batter encasing a savory-sweet core of spiced shredded chicken and toasted almonds. Inspired by the flavors of Moroccan Pastilla, these golden bites balance the warmth of saffron and cinnamon with the heat of harissa.', 'appetizer', 'Moroccan', 'Intermediate', '["moroccan", "almond", "chicken", "harissa", "appetizer", "fried", "party food"]', '[{"group_name": "Chicken Saffron Filling", "items": [{"name": "chicken breast", "quantity": 300, "unit": "g", "preparation": "boneless, skinless", "notes": null, "substitutions": [], "ingredient_id": "2b577d04-33ca-4919-938f-bfc8780a3a4b", "nutrition_source": "USDA FoodData Central"}, {"name": "onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx. 100g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "saffron threads", "quantity": 0.5, "unit": "g", "preparation": "crumbled", "notes": null, "substitutions": [], "ingredient_id": "7f9ec0c8-2db1-48ac-a2c9-9b1efce12cf3", "nutrition_source": "USDA FoodData Central"}, {"name": "ground ginger", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "401ddd0b-3597-4b46-bb54-f3bc755048bb", "nutrition_source": "USDA FoodData Central"}, {"name": "ground turmeric", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "cinnamon stick", "quantity": 1, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 300, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "egg yolk", "quantity": 1, "unit": null, "preparation": null, "notes": "binding agent", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Almond & Harissa Elements", "items": [{"name": "blanched almonds", "quantity": 60, "unit": "g", "preparation": "toasted and roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "5bcbb4d4-6845-4825-bd21-1c13e52b989c", "nutrition_source": "USDA FoodData Central"}, {"name": "powdered sugar", "quantity": 5, "unit": "g", "preparation": null, "notes": "optional, for traditional sweetness", "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "harissa paste", "quantity": 15, "unit": "g", "preparation": null, "notes": "adjust to spice tolerance", "substitutions": [], "ingredient_id": "f813ad06-ea79-4c91-b77c-fe4c1c3805d3", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Crispy Batter", "items": [{"name": "all-purpose flour", "quantity": 125, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 40, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "sparkling water", "quantity": 180, "unit": "ml", "preparation": "ice cold", "notes": null, "substitutions": [], "ingredient_id": "de973e91-f602-4c8c-b99f-9aaf5b5ac726", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 1000, "unit": "ml", "preparation": null, "notes": "for deep frying", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a medium saucepan, combine chicken breast, diced onion, saffron, ginger, turmeric, cinnamon stick, salt, and water. Bring to a simmer.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Remove the cooked chicken and set aside. Increase heat to reduce the remaining liquid in the pan until thick and syrup-like (approx. 2-3 tablespoons remaining). Discard the cinnamon stick.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Liquid is thick and coats the back of a spoon", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Shred the chicken finely. In a bowl, mix chicken with the reduced liquid, chopped almonds, parsley, cilantro, harissa paste, powdered sugar (if using), and egg yolk. Mix until sticky enough to hold shape.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Form the mixture into small walnut-sized balls (approx 25g each). Place on a tray and refrigerate to firm up.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Whisk flour, cornstarch, baking powder, and salt. Whisk in ice-cold sparkling water just until combined. Do not overmix; small lumps are acceptable.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": {"visual": "Consistency of heavy cream", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Heat neutral oil in a Dutch oven to 180\u00b0C (350\u00b0F).", "structured": {"action": "PREHEAT", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Dip chilled chicken balls into the batter, ensuring full coverage. Carefully drop into hot oil. Fry in batches, turning occasionally, until puffed and golden brown.", "structured": {"action": "FRY", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT4M", "doneness_cues": {"visual": "Golden brown color", "tactile": "Crispy exterior"}}, "tips": ["Do not overcrowd the pot or the oil temperature will drop."]}, {"step_number": 8, "phase": "finish", "text": "Remove with a slotted spoon and drain on a wire rack. Season immediately with a pinch of salt.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT50M", "passive_time": "PT30M", "total_time": "PT1H20M", "overnight_required": false, "yields": "16 beignets", "yield_count": 16, "serving_size_g": 110}', '{"flags": ["Dairy-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 102.91, "protein_g": 5.87, "carbohydrates_g": 10.86, "fat_g": 4.07, "saturated_fat_g": 0.77, "trans_fat_g": 0.02, "monounsaturated_fat_g": 2.04, "polyunsaturated_fat_g": 0.91, "fiber_g": 1.19, "sugar_g": 0.87, "sodium_mg": 130.07, "cholesterol_mg": 23.48, "potassium_mg": 105.21, "calcium_mg": 42.86, "iron_mg": 0.68, "magnesium_mg": 19.26, "phosphorus_mg": 73.82, "zinc_mg": 0.39, "vitamin_a_mcg": 31.55, "vitamin_c_mg": 2.07, "vitamin_d_mcg": 0.13, "vitamin_e_mg": 1.07, "vitamin_k_mcg": 15.59, "vitamin_b6_mg": 0.12, "vitamin_b12_mcg": 0.08, "thiamin_mg": 0.03, "riboflavin_mg": 0.07, "niacin_mg": 2.14, "folate_mcg": 8.7, "water_g": 51.38, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store filling separately from batter. If fried, reheat in oven to crisp.", "duration": "P3D"}, "freezer": {"notes": "Freeze fried beignets; reheat from frozen in oven.", "duration": "P1M"}, "reheating": "Reheat in a 190\u00b0C oven for 8-10 minutes until crispy. Do not microwave.", "does_not_keep": false}', '[{"name": "Medium saucepan", "required": true, "alternative": null}, {"name": "Dutch oven or deep fryer", "required": true, "alternative": null}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Digital thermometer", "required": true, "alternative": "Wooden skewer test"}, {"name": "Slotted spoon", "required": true, "alternative": null}, {"name": "Wire rack", "required": true, "alternative": null}]', '[{"symptom": "Batter coating is soggy or oily", "likely_cause": "Oil temperature was too low", "prevention": "Use a thermometer to maintain 180\u00b0C/350\u00b0F between batches", "fix": "Increase oil heat and refry briefly (carefully)"}, {"symptom": "Filling balls fall apart in oil", "likely_cause": "Filling was too dry or not chilled enough", "prevention": "Ensure the reduced onion sauce and egg yolk bind the mix; chill thoroughly", "fix": "Add another egg yolk to the mix and re-chill"}]', '["The filling is essentially a deconstructed ''Pastilla'' filling. The balance of sweet (almonds/cinnamon) and savory (onion/saffron) is key to the authentic flavor profile.", "Using ice-cold sparkling water for the batter inhibits gluten formation and creates gas pockets, resulting in a tempura-like lightness that stays crispy longer.", "Serve these immediately with a side of harissa-spiked mayonnaise or a yogurt-lemon dip to cut through the richness.", "If your saffron is not pre-ground, toast the threads gently in a dry pan for 30 seconds and crush them between your fingers to release maximum aroma."]', '"This dish reimagines the classic Moroccan Chicken Pastilla\u2014traditionally a phyllo pie dusted with sugar and cinnamon\u2014as a contemporary fritter. It retains the signature Maghrebi flavor triad of saffron, ginger, and sweet almonds, while utilizing the harissa (a Tunisian import now staple in Morocco) for a modern savory edge."', 102.91);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('b3787348-9908-4f53-90da-0b3a9bd9f750', 'Sautéed Soft-Shell Crabs with Sweet Corn Relish', 'Crispy, golden-fried soft-shell crabs offering a delicate crunch and sweet, briny meat, contrasted by a bright, textural relish of fresh corn, roasted red peppers, and sharp red onion. A quintessential celebration of late spring coastal cuisine.', 'dinner', 'American', 'Intermediate', '["new england", "corn", "crab", "red onion", "dinner", "main course", "spring", "seafood", "seasonal"]', '[{"group_name": "Relish", "items": [{"name": "fresh corn kernels", "quantity": 150, "unit": "g", "preparation": "raw", "notes": "approximately 2 ears", "substitutions": [], "ingredient_id": "b408622e-f1b7-4f90-90c5-e956cd32ab63", "nutrition_source": "USDA FoodData Central"}, {"name": "red bell pepper", "quantity": 1, "unit": null, "preparation": "roasted, peeled, and diced", "notes": "approx. 120g", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "Aggregated Public Data"}, {"name": "red onion", "quantity": 40, "unit": "g", "preparation": "finely diced", "notes": null, "substitutions": [], "ingredient_id": "1c270c6e-0acc-4c5c-9935-7eff3240fc4a", "nutrition_source": "Aggregated Public Data"}, {"name": "extra virgin olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "lime juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 5, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, start with 2g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Crabs & Dredge", "items": [{"name": "soft-shell crabs", "quantity": 4, "unit": null, "preparation": "cleaned (gills, aprons, face removed)", "notes": "approx. 80-100g each", "substitutions": [], "ingredient_id": "2ce537a0-fad3-40b0-a1aa-1eac21539b1f", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "cayenne pepper", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Frying", "items": [{"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "grapeseed or canola", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine the corn kernels, diced roasted red pepper, finely diced red onion, olive oil, lime juice, and parsley in a mixing bowl. Season with salt to taste. Let sit at room temperature to marry flavors.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Thoroughly pat the cleaned soft-shell crabs dry with paper towels. Moisture is the enemy of crispiness and causes dangerous popping. Whisk flour, salt, black pepper, and cayenne in a shallow dish.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat the neutral oil and butter in a large skillet over medium-high heat until the butter foams and subsides. The pan should reach approximately 190\u00b0C (375\u00b0F).", "structured": {"action": "HEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Dredge the crabs in the flour mixture, shaking off excess vigorously. Gently lay them into the hot skillet, top side down first (away from you to avoid splash).", "structured": {"action": "DREDGE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Saut\u00e9 for 3 to 4 minutes until golden brown and crispy. Watch out for popping liquid. Flip carefully and cook the other side for another 3 minutes until the shell is firm and red. Internal temperature should reach 63\u00b0C (145\u00b0F).", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Shell turns red and coating is golden brown", "tactile": "Firm to the touch"}}, "tips": ["Use a splatter guard if available; soft-shells contain water that can cause oil to burst."]}, {"step_number": 6, "phase": "finish", "text": "Remove crabs and drain briefly on paper towels. Serve immediately topped with the corn and roasted pepper relish.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT10M", "total_time": "PT40M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 320}', '{"flags": ["Pescatarian", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Shellfish allergy", "Gluten intolerance (unless GF flour is used)"]}', '{"per_serving": {"calories": 725.07, "protein_g": 41.59, "carbohydrates_g": 44.61, "fat_g": 45.65, "saturated_fat_g": 12.05, "trans_fat_g": null, "monounsaturated_fat_g": 14.78, "polyunsaturated_fat_g": 2.72, "fiber_g": 5.35, "sugar_g": 6.26, "sodium_mg": 1740.4, "cholesterol_mg": 32.25, "potassium_mg": 841.25, "calcium_mg": 181.17, "iron_mg": 3.68, "magnesium_mg": 45.34, "phosphorus_mg": 123.11, "zinc_mg": 0.76, "vitamin_a_mcg": 223.41, "vitamin_c_mg": 92.28, "vitamin_d_mcg": null, "vitamin_e_mg": 3.73, "vitamin_k_mcg": 55.6, "vitamin_b6_mg": 0.25, "vitamin_b12_mcg": 0.03, "thiamin_mg": 0.22, "riboflavin_mg": 0.13, "niacin_mg": 2.34, "folate_mcg": 75.52, "water_g": 145.24, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Crabs lose crispness immediately; relish keeps well for 2 days.", "duration": "P1D"}, "freezer": {"notes": "Do not freeze cooked soft-shell crabs.", "duration": null}, "reheating": "Reheat crabs in an oven at 175\u00b0C (350\u00b0F) for 5-7 minutes to recrisp.", "does_not_keep": true}', '[{"name": "Large skillet (cast iron preferred)", "required": true, "alternative": "Stainless steel frying pan"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Paper towels", "required": true, "alternative": null}, {"name": "Splatter guard", "required": false, "alternative": "Lid held ajar"}]', '[{"symptom": "Crabs are soggy instead of crispy", "likely_cause": "Oil temperature was too low or pan was overcrowded", "prevention": "Ensure butter stops foaming before adding crabs; cook in batches if pan is small", "fix": "Increase heat slightly and finish in the pan, or move to a wire rack in a hot oven"}, {"symptom": "Oil is popping violently", "likely_cause": "Excess water inside the crab or on the surface", "prevention": "Pat crabs extremely dry and poke small holes in claws to release steam before cooking", "fix": "Lower heat slightly and cover with a splatter screen"}]', '["To roast the pepper yourself: char directly over a gas flame until black, seal in a bowl for 10 minutes to steam, then rub off the skin.", "The ''pop'' is the most dangerous part of cooking soft-shells. Piercing the legs and claws with a pin prior to cooking allows steam to escape safely.", "If fresh corn is unavailable, thawed frozen fire-roasted corn is a superior alternative to canned corn for this relish.", "Cleaning: Ensure the ''apron'' (flap on the belly) is removed, the face is snipped off behind the eyes, and the gills (dead man''s fingers) are removed from under the side points."]', '"Soft-shell crabs are a seasonal delicacy, primarily harvested in late spring along the Atlantic Coast when blue crabs molt their hard exoskeletons. This preparation, pairing the rich, savory crab with the sweetness of corn, is a staple of New England and Chesapeake Bay summer dining."', 725.07);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('b425a83c-c74f-42de-86c8-334c5b40efab', 'Tahitian Vanilla Infused Oil', 'A luxuriously silky infusion capturing the unique floral, cherry-like, and anise notes of Tahitian vanilla. This versatile oil adds depth to vinaigrettes for seafood or replaces standard fats in delicate sponge cakes.', 'condiment', 'French', 'Easy', '["condiments", "oil", "vanilla bean", "easy", "gift", "pantry staple"]', '[{"group_name": "Infusion Base", "items": [{"name": "grapeseed oil", "quantity": 230, "unit": "g", "preparation": "or other neutral oil like almond", "notes": "approx 250ml", "substitutions": [], "ingredient_id": "00f43166-1b77-4e77-9e30-e912a59d118a", "nutrition_source": "USDA FoodData Central"}, {"name": "tahitian vanilla beans", "quantity": 2, "unit": null, "preparation": "whole", "notes": "approx 6-8g", "substitutions": [], "ingredient_id": "fa27169b-bdb5-4f0c-abab-0b67a3e924e6", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the vanilla beans on a cutting board. Use the back of a paring knife to flatten the pods, then slice them lengthwise to expose the seeds. Scrape the seeds out carefully.", "structured": {"action": "SCORE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Thousands of tiny black seeds exposed", "tactile": null}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Combine the oil, vanilla pods, and scraped seeds in a small saucepan. Heat gently over low heat until the oil reaches 60\u00b0C/140\u00b0F. Do not let it fry or bubble.", "structured": {"action": "HEAT", "temperature": {"celsius": 60, "fahrenheit": 140}, "duration": "PT5M", "doneness_cues": {"visual": "No bubbles, just warmth", "tactile": "Warm to the touch but not burning"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Remove from heat immediately. Cover the saucepan and let the oil steep at room temperature until fully cooled, allowing the flavor compounds to extract into the fat.", "structured": {"action": "STEEP", "temperature": null, "duration": "PT2H", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Transfer the oil (including the pods and seeds for aesthetics and continued infusion) into a sterilized glass bottle or jar using a funnel.", "structured": {"action": "STORE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT2H", "total_time": "PT2H15M", "overnight_required": false, "yields": "250ml", "yield_count": 16, "serving_size_g": 14}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Paleo", "Keto", "Whole30", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 129.6, "protein_g": 0, "carbohydrates_g": 0.11, "fat_g": 14.38, "saturated_fat_g": 1.38, "trans_fat_g": null, "monounsaturated_fat_g": 2.31, "polyunsaturated_fat_g": 10.05, "fiber_g": 0, "sugar_g": 0, "sodium_mg": 0.08, "cholesterol_mg": null, "potassium_mg": null, "calcium_mg": null, "iron_mg": null, "magnesium_mg": null, "phosphorus_mg": null, "zinc_mg": null, "vitamin_a_mcg": null, "vitamin_c_mg": null, "vitamin_d_mcg": null, "vitamin_e_mg": 4.14, "vitamin_k_mcg": null, "vitamin_b6_mg": null, "vitamin_b12_mcg": null, "thiamin_mg": null, "riboflavin_mg": null, "niacin_mg": null, "folate_mcg": null, "water_g": null, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Oil may become cloudy; bring to room temperature before use.", "duration": "P3M"}, "freezer": {"notes": "Freezing not recommended as it may alter delicate flavor compounds.", "duration": null}, "reheating": "Do not reheat; use ambient or warm gently if solidified.", "does_not_keep": false}', '[{"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Instant-read thermometer", "required": true, "alternative": null}, {"name": "Sterilized glass bottle or jar", "required": true, "alternative": null}, {"name": "Paring knife", "required": true, "alternative": null}, {"name": "Funnel", "required": false, "alternative": null}]', '[{"symptom": "Flavor is weak or barely detectable", "likely_cause": "Oil did not steep long enough or beans were old/dry", "prevention": "Allow oil to rest for 24-48 hours before first use; ensure beans are pliable", "fix": "Warm the oil gently again to 60\u00b0C/140\u00b0F and let cool slowly"}, {"symptom": "Burnt or acrid taste", "likely_cause": "Oil was heated too high", "prevention": "Use a thermometer and never exceed 80\u00b0C/175\u00b0F", "fix": "Cannot be fixed; discard to avoid ruining dishes"}]', '["Tahitian vanilla is more delicate and floral than Bourbon (Madagascar) vanilla, making it superior for cold applications like scallop crudo or fruit salads.", "Grapeseed oil is preferred for its neutral profile and light texture, but almond oil works beautifully if the oil is strictly for baking.", "Do not discard the pods after the oil is finished; they can be wiped dry and buried in sugar to create vanilla sugar.", "For a savory application, try drizzling this over roasted lobster or seared white fish."]', '"While vanilla originates from Mexico, the distinct variety Vanilla tahitensis is grown in French Polynesia. It is prized in French gastronomy for its complex aroma profile containing heliotropin, which gives it unique anise and floral notes not found in standard Planifolia beans."', 129.6);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('b4e107f0-fa96-4ba9-acce-791e1ce066e3', 'Warm Balsamic Pear and Pancetta Salad', 'A sophisticated interplay of temperatures and textures featuring caramelized pears glazed in balsamic vinegar, contrasting with salty, crispy pancetta and creamy gorgonzola dolce. Served over pepper rocket leaves with a sharp honey-mustard vinaigrette.', 'salad', 'Italian-Fusion', 'Easy', '["salad", "pear", "balsamic", "pancetta", "gorgonzola", "quick", "autumn", "starter"]', '[{"group_name": "Salad Base", "items": [{"name": "pancetta", "quantity": 80, "unit": "g", "preparation": "thinly sliced", "notes": "or unsmoked bacon", "substitutions": [], "ingredient_id": "68e45074-af78-4e6b-ba2e-9bb91cb07751", "nutrition_source": "Aggregated Public Data"}, {"name": "pears", "quantity": 2, "unit": null, "preparation": "firm but ripe", "notes": "approx 350g total, cored and wedged (Bosc or Anjou)", "substitutions": [], "ingredient_id": "ed5dd928-efa8-4c10-aeb3-3c08c94c62f8", "nutrition_source": "USDA FoodData Central"}, {"name": "wild rocket (arugula)", "quantity": 100, "unit": "g", "preparation": "washed and dried", "notes": null, "substitutions": [], "ingredient_id": "5cd3639d-c908-4325-8962-18beeabb26ee", "nutrition_source": "USDA FoodData Central"}, {"name": "gorgonzola cheese", "quantity": 60, "unit": "g", "preparation": "crumbled", "notes": "Piccante for firm, Dolce for creamy", "substitutions": [], "ingredient_id": "c480ce22-b715-4a79-b692-cd5c289bb4ea", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 10, "unit": "g", "preparation": null, "notes": "for frying pears", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "balsamic vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": "high quality aged vinegar preferred", "substitutions": [], "ingredient_id": "4da62caf-a01b-4477-b6bb-f4213102565d", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Honey-Mustard Dressing", "items": [{"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "apple cider vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 5, "unit": "g", "preparation": "smooth", "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "honey", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "pinch, to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Core the pears and slice them into eighths (wedges). Keep the skin on for texture and color.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a small bowl, whisk together the olive oil, apple cider vinegar, Dijon mustard, honey, and a pinch of salt and pepper until emulsified.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Place the pancetta slices in a cold large frying pan. Turn heat to medium and cook until the fat renders and the pancetta becomes golden and crispy. Remove to a paper towel-lined plate, leaving the rendered fat in the pan.", "structured": {"action": "FRY", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT5M", "doneness_cues": {"visual": "Golden brown and stiff", "tactile": "Crispy"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the butter to the rendered pancetta fat in the same pan over medium-high heat. Add the pear wedges in a single layer. Sear for 2-3 minutes per side until golden brown.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT5M", "doneness_cues": {"visual": "Golden brown edges", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour the balsamic vinegar over the pears. Toss gently for 30-60 seconds until the vinegar reduces to a glaze and coats the fruit. Remove from heat immediately.", "structured": {"action": "GLAZE", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Arrange the rocket on plates. Top with the warm balsamic pears, crumbled crispy pancetta, and pieces of gorgonzola. Drizzle generously with the dressing and serve immediately.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "2 main servings", "yield_count": 2, "serving_size_g": 320}', '{"flags": ["Gluten-Free", "Egg-Free", "Soy-Free", "Peanut-Free"], "not_suitable_for": ["Vegetarians (contains pancetta)", "Infants under 12 months (contains honey)"]}', '{"per_serving": {"calories": 640.05, "protein_g": 14.38, "carbohydrates_g": 36.1, "fat_g": 52.18, "saturated_fat_g": 12.17, "trans_fat_g": null, "monounsaturated_fat_g": 17.76, "polyunsaturated_fat_g": 2.84, "fiber_g": 6.39, "sugar_g": 24.54, "sodium_mg": 783.2, "cholesterol_mg": 10.75, "potassium_mg": 623, "calcium_mg": 108.2, "iron_mg": 1.64, "magnesium_mg": 43.36, "phosphorus_mg": 52.25, "zinc_mg": 0.92, "vitamin_a_mcg": 200.52, "vitamin_c_mg": 15.05, "vitamin_d_mcg": null, "vitamin_e_mg": 3.79, "vitamin_k_mcg": 76.51, "vitamin_b6_mg": 0.09, "vitamin_b12_mcg": 0.01, "thiamin_mg": 0.04, "riboflavin_mg": 0.1, "niacin_mg": 0.44, "folate_mcg": 61.05, "water_g": 213.04, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Dressed salad does not store well. Components can be stored separately for 2 days.", "duration": null}, "freezer": {"notes": null, "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Large frying pan", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Pears turned to mush", "likely_cause": "Pears were too ripe before cooking", "prevention": "Select pears that are firm to the touch, not soft near the stem", "fix": "Reduce cooking time to a high-heat flash sear only; cannot fix texture once mushy"}, {"symptom": "Dressing is separated", "likely_cause": "Insufficient whisking or added oil too quickly", "prevention": "Whisk vigorously or shake in a jar", "fix": "Add a teaspoon of warm water and whisk vigorously to re-emulsify"}]', '["Temperature contrast is vital here; ensure the pears are still warm when they hit the salad greens for the best experience.", "If Gorgonzola is too pungent for your taste, Dolcelatte is a milder, creamier alternative that still pairs beautifully with pear.", "For extra crunch, toast a handful of walnuts or pecans and scatter them over the finished salad.", "Leaving the skin on the pears helps them hold their shape during the frying process and adds nutritional value."]', '"This salad draws from the classic Italian pairing of ''formaggio e pere'' (cheese and pears), a combination celebrated in Italian proverbs for its perfection. The addition of crispy cured pork (pancetta) adds a savory ''umami'' depth typical of modern European bistro cuisine."', 640.05);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('b51ae434-f72a-4702-8925-e0518ba19ad9', 'Piquillo Peppers Stuffed With Salt Cod Brandade', 'Sweet, fire-roasted piquillo peppers filled with a silky, garlicky emulsion of salt cod and olive oil, resting on a velvety red pepper and white wine sauce. A classic Basque tapa that balances salinity with sweetness.', 'appetizer', 'Spanish', 'Intermediate', '["spanish", "cod", "potato", "appetizer", "fall", "tapas", "basque"]', '[{"group_name": "Salt Cod (Bacalao)", "items": [{"name": "dried salt cod", "quantity": 300, "unit": "g", "preparation": "whole fillet", "notes": "Requires 24-48h soaking", "substitutions": [], "ingredient_id": "8845e7e7-3d4d-49ae-9d5c-0a0e57c1171c", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": null, "unit": "ml", "preparation": null, "notes": "For soaking and poaching", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Brandade Filling", "items": [{"name": "potatoes", "quantity": 250, "unit": "g", "preparation": "peeled and cubed", "notes": "Starchy variety like Russet or Yukon Gold", "substitutions": [], "ingredient_id": "a87814d3-a635-474b-a78d-4d20b45066e5", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": null, "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 100, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "036c7254-3de5-4c6e-a2e7-366ad4d05077", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 60, "unit": "ml", "preparation": "warmed", "notes": null, "substitutions": ["whole milk"], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "jarred piquillo peppers", "quantity": 16, "unit": null, "preparation": "whole", "notes": "Use 12 for stuffing, 4 for sauce", "substitutions": [], "ingredient_id": "32a393f4-6b49-419d-8c84-8f1ab5b733db", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Sauce", "items": [{"name": "onion", "quantity": 100, "unit": "g", "preparation": "diced", "notes": null, "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 50, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "fish stock", "quantity": 100, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["water", "vegetable stock"], "ingredient_id": "3912e04d-71a3-4a31-b033-cc5c5aa4452d", "nutrition_source": "Aggregated Public Data"}, {"name": "reserved piquillo peppers", "quantity": 4, "unit": null, "preparation": null, "notes": "From the jar used above", "substitutions": [], "ingredient_id": "7291d1f7-5821-4180-90b9-79eec428e938", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "At least 24 hours in advance, rinse the salt cod thoroughly. Place in a large bowl, cover with cold water, and refrigerate. Change the water every 8 hours to remove excess salt.", "structured": {"action": "SOAK", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "P1D", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Drain the cod. Place it in a saucepan and cover with fresh cold water. Bring to a gentle simmer, then remove from heat immediately. Let it steep for 10 minutes. Drain, remove skin and bones, and flake the meat.", "structured": {"action": "POACH", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT15M", "doneness_cues": {"visual": "Fish flakes easily", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "While cod steeps, boil the peeled potato chunks in salted water until very tender. Drain and let steam dry for a minute.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": null, "tactile": "Fork tender"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "In a small skillet, gently heat the 100ml olive oil with 3 cloves of sliced garlic over low heat until the garlic is golden. Discard the garlic (or save for garnish) and keep the oil warm.", "structured": {"action": "INFUSE", "temperature": {"celsius": 70, "fahrenheit": 158}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Mash the potatoes and flaked cod together in a bowl while still warm. Vigorously beat in the warm garlic-infused oil and the warm cream, alternating small amounts, until the mixture (brandade) is creamy and emulsified. Season with pepper (salt is likely unnecessary).", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": {"visual": "Smooth, pale, and fluffy texture", "tactile": "Holds shape on a spoon"}}, "tips": ["If the mixture is too stiff, add a splash of the cod poaching liquid."]}, {"step_number": 6, "phase": "cook", "text": "For the sauce: Saut\u00e9 the diced onion and garlic in 30ml olive oil until soft. Add the 4 reserved piquillo peppers and white wine. Reduce wine by half, then add stock. Simmer for 10 minutes. Blend until smooth and strain if desired.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Preheat oven to 180\u00b0C (350\u00b0F). Fill a piping bag with the brandade mixture. Carefully stuff each of the remaining 12 piquillo peppers. Be gentle to avoid tearing the delicate skin.", "structured": {"action": "FILL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Spread the sauce on the bottom of a baking dish. Arrange the stuffed peppers on top. Bake for 10-15 minutes until heated through. Serve immediately.", "structured": {"action": "BAKE", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT15M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT50M", "passive_time": "P1D", "total_time": "P1DT50M", "overnight_required": true, "yields": "12 stuffed peppers", "yield_count": 4, "serving_size_g": 220}', '{"flags": ["Pescatarian", "Gluten-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 694.63, "protein_g": 52.3, "carbohydrates_g": 24.48, "fat_g": 40.33, "saturated_fat_g": 8.38, "trans_fat_g": 0.19, "monounsaturated_fat_g": 7.1, "polyunsaturated_fat_g": 1.64, "fiber_g": 7.44, "sugar_g": 7.99, "sodium_mg": 6425.7, "cholesterol_mg": 130.95, "potassium_mg": 1853.38, "calcium_mg": 197.59, "iron_mg": 2.75, "magnesium_mg": 119.24, "phosphorus_mg": 772.66, "zinc_mg": 1.54, "vitamin_a_mcg": 93.15, "vitamin_c_mg": 18, "vitamin_d_mcg": 3.24, "vitamin_e_mg": 3.36, "vitamin_k_mcg": 5.48, "vitamin_b6_mg": 0.74, "vitamin_b12_mcg": 7.53, "thiamin_mg": 0.23, "riboflavin_mg": 0.22, "niacin_mg": 5.7, "folate_mcg": 24.25, "water_g": 45.94, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container; reheat gently to avoid splitting the emulsion.", "duration": "P3D"}, "freezer": {"notes": "Texture of the peppers may degrade slightly upon thawing.", "duration": "P1M"}, "reheating": "Cover with foil and bake at 160\u00b0C until warmed through, or microwave on low power.", "does_not_keep": false}', '[{"name": "Large bowl", "required": true, "alternative": "Basin"}, {"name": "Medium saucepan", "required": true, "alternative": null}, {"name": "Skillet", "required": true, "alternative": null}, {"name": "Immersion blender", "required": true, "alternative": "Standard blender"}, {"name": "Piping bag", "required": false, "alternative": "Small spoon"}, {"name": "Baking dish", "required": true, "alternative": null}]', '[{"symptom": "Brandade is oily or separated", "likely_cause": "Oil was added too quickly or the mixture became too cold", "prevention": "Add oil in a slow, steady stream while whipping warm potato/cod mixture", "fix": "Add a tablespoon of hot water or hot milk and whisk vigorously to re-emulsify"}]', '["The quality of the piquillo peppers is paramount; look for ''Piquillo de Lodosa'' designation for the best sweetness and texture.", "Do not let the cod boil vigorously during poaching, or the flesh will become tough and stringy.", "If you want a lighter texture, you can fold whipped egg whites into the brandade before stuffing, though this makes it more like a souffl\u00e9.", "Reserve the oil from the piquillo pepper jar; you can whisk a few drops into the final sauce for extra color and flavor."]', '"Originating from the Navarre and Basque regions of Spain, this dish showcases the preservation history of the area. Salt cod (bacalao) allowed fish to be consumed inland, while the roasting and jarring of piquillo peppers preserved the harvest. The combination creates a perfect balance of the sea''s salinity and the land''s sweetness."', 694.63);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('b5c7d846-78b3-48c0-9548-13c27d6cf4eb', 'Kazandibi (Turkish Burnt Milk Pudding)', 'A sophisticated Ottoman classic featuring a velvety, mastic-scented milk pudding with a signature caramelized, dark-brown crust. The pudding is cooked, then deliberately burned on the bottom to create a smoky, toasted-marshmallow flavor profile before being chilled and rolled.', 'dessert', 'Turkish', 'Intermediate', '["turkish", "custards and puddings", "milk", "sugar", "dessert", "gluten-free"]', '[{"group_name": "Pudding Base", "items": [{"name": "whole milk", "quantity": 1000, "unit": "ml", "preparation": "cold", "notes": "Full fat is essential for texture", "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "sugar", "quantity": 160, "unit": "g", "preparation": null, "notes": "White granulated", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "rice flour", "quantity": 40, "unit": "g", "preparation": null, "notes": "Provides the traditional elasticity", "substitutions": [], "ingredient_id": "fa485141-bb6d-40c3-8313-fd740db37966", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 40, "unit": "g", "preparation": null, "notes": "Thickening agent", "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "mastic gum", "quantity": 2, "unit": null, "preparation": "frozen", "notes": "2-3 small tears/crystals, approx 1g total", "substitutions": [], "ingredient_id": "236cd9df-aa5c-4bab-845d-e05bce91eada", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Caramelization Layer", "items": [{"name": "unsalted butter", "quantity": 20, "unit": "g", "preparation": "softened", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": "For dusting the tray", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish", "items": [{"name": "ground cinnamon", "quantity": null, "unit": null, "preparation": null, "notes": "To taste, for dusting", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "ground pistachios", "quantity": null, "unit": null, "preparation": null, "notes": "To taste", "substitutions": [], "ingredient_id": "59207580-65c8-4564-9467-eb7286b8e5a7", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the mastic crystals in a mortar with a teaspoon of the sugar (taken from the pudding base amount). Grind firmly until it becomes a fine powder.", "structured": {"action": "CRUSH", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": ["Freezing the mastic for 15 minutes beforehand prevents it from becoming sticky while grinding."]}, {"step_number": 2, "phase": "cook", "text": "In a heavy-bottomed saucepan, combine the cold milk, remaining sugar, rice flour, cornstarch, and ground mastic. Whisk thoroughly before turning on the heat to ensure no lumps remain.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Cook over medium heat, stirring constantly with a whisk. As the mixture heats up, switch to a spatula to scrape the bottom. Bring to a gentle boil; once it bubbles and thickens to a consistency similar to heavy cream, cook for 2 more minutes to activate the starches completely.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT15M", "doneness_cues": {"visual": "Thick, glossy bubbling surface", "tactile": "Coats back of spoon heavily"}}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Grease the bottom and sides of a rectangular metal baking tray (approx 25x35cm) generously with the softened butter. Sprinkle the 30g of sugar evenly over the butter.", "structured": {"action": "PREPARE_PAN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour about 2 ladles of the hot pudding into the prepared tray\u2014just enough to cover the bottom thinly. Place the tray directly over two burners on the stove set to medium-high heat.", "structured": {"action": "POUR", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Rotate the tray constantly over the flame. The sugar and pudding layer will begin to bubble vigorously and caramelize. Continue rotating until the entire bottom is evenly dark brown (almost black in spots). You should smell a rich caramel/burnt sugar aroma.", "structured": {"action": "CARAMELIZE", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Deep dark brown color visible through the thin pudding layer", "tactile": "Smell of toasted marshmallow"}}, "tips": ["Use an oven mitt; the metal tray will get extremely hot.", "Do not be afraid of the dark color; this is the signature feature of the dish."]}, {"step_number": 7, "phase": "assemble", "text": "Remove tray from heat. Immediately pour the remaining pudding over the caramelized layer. Smooth the top gently with a spatula.", "structured": {"action": "POUR", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Allow to cool to room temperature, then refrigerate for at least 4 hours (preferably overnight) to set completely.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT4H", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "To serve, cut the pudding into large rectangles. Use a spatula to lift the edge of a rectangle and roll it upon itself (like a rug), exposing the dark caramelized bottom as the outer layer. Garnish with cinnamon or pistachios.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT4H", "total_time": "PT4H45M", "overnight_required": false, "yields": "6 rolls", "yield_count": 6, "serving_size_g": 180}', '{"flags": ["Vegetarian", "Gluten-Free", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 303.21, "protein_g": 5.88, "carbohydrates_g": 51.55, "fat_g": 8.62, "saturated_fat_g": 4.86, "trans_fat_g": null, "monounsaturated_fat_g": 2.36, "polyunsaturated_fat_g": 0.58, "fiber_g": 0.44, "sugar_g": 40.1, "sodium_mg": 73.52, "cholesterol_mg": 23.83, "potassium_mg": 236.93, "calcium_mg": 193.76, "iron_mg": 0.18, "magnesium_mg": 20.43, "phosphorus_mg": 152.44, "zinc_mg": 0.7, "vitamin_a_mcg": 99.8, "vitamin_c_mg": 0.07, "vitamin_d_mcg": 2.17, "vitamin_e_mg": 0.23, "vitamin_k_mcg": 0.81, "vitamin_b6_mg": 0.11, "vitamin_b12_mcg": 0.76, "thiamin_mg": 0.1, "riboflavin_mg": 0.3, "niacin_mg": 0.34, "folate_mcg": 9.14, "water_g": 148.79, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Keep covered to prevent skin formation or absorbing odors.", "duration": "P3D"}, "freezer": {"notes": null, "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Heavy-bottomed saucepan", "required": true, "alternative": null}, {"name": "Rectangular metal baking tray", "required": true, "alternative": "Large non-stick heatproof pan (must withstand direct flame)"}, {"name": "Mortar and pestle", "required": true, "alternative": "Small bowl and back of a spoon"}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Heat-resistant spatula", "required": true, "alternative": null}]', '[{"symptom": "Pudding cracks or breaks when rolling", "likely_cause": "The pudding was overcooked (too stiff) or the caramelized layer stuck too hard to the pan", "prevention": "Ensure the tray is well-buttered before burning; do not over-boil the starch mixture", "fix": "Serve as flat squares instead of rolls; the taste will be identical"}]', '["Mastic (damla sak\u0131z\u0131) has a very potent pine/resin flavor. Use sparingly; too much will make the dessert bitter.", "The ''burning'' step requires a metal tray. Do not attempt this with glass (Pyrex) or ceramic, as they will shatter over direct flame.", "If you cannot find mastic, the dish becomes ''Kazandibi'', but without the specific pine aroma. You can substitute with vanilla bean paste, though it changes the traditional profile.", "For the cleanest cuts, dip your knife in warm water between slices."]', '"Kazandibi (translating to ''bottom of the cauldron'') originated in the kitchens of the Ottoman Palace. It was originally a byproduct of making Tavuk G\u00f6\u011fs\u00fc (chicken breast pudding), where the chefs would scrape the caramelized bottom layer to serve as a delicacy. Today, it is beloved across Turkey for its interplay of textures: the wobbly, cool interior against the slightly bitter, chewy, burnt skin."', 303.21);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('b67f29d2-bffb-44f4-8d3b-8d9f3c2c1a80', 'Rustique Raspberry Tart', 'A vibrant celebration of fruit and pastry featuring a crisp, caramelized pâte sablée crust enriched with light brown sugar. The filling is a glossy, intense raspberry compote thickened to a jewel-like consistency, balancing sweet and tart notes perfectly.', 'dessert', 'French', 'Intermediate', '["butter", "cornstarch", "egg yolk", "flour", "light brown sugar", "sugar", "weeknight", "dessert", "tart", "raspberry", "french"]', '[{"group_name": "Brown Sugar P\u00e2te Sabl\u00e9e", "items": [{"name": "all-purpose flour", "quantity": 200, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "light brown sugar", "quantity": 50, "unit": "g", "preparation": null, "notes": "adds caramel depth", "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 110, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "egg yolk", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 18-20g", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "ice water", "quantity": 15, "unit": "ml", "preparation": null, "notes": "add gradually", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Raspberry Filling", "items": [{"name": "fresh or frozen raspberries", "quantity": 450, "unit": "g", "preparation": null, "notes": "reserve 100g fresh for topping if desired", "substitutions": [], "ingredient_id": "f4f5b84c-c364-40cd-b737-375755e481f9", "nutrition_source": "USDA FoodData Central"}, {"name": "white sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 25, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a food processor, pulse the flour, light brown sugar, and salt until combined. Add the cold cubed butter and pulse briefly until the mixture resembles coarse breadcrumbs.", "structured": {"action": "MIX", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Add the egg yolk and pulse again. If the dough does not clump together when pinched, add ice water one teaspoon at a time. Turn out onto a surface, form into a disc, wrap in plastic, and chill for 30 minutes.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Preheat oven to 190\u00b0C (375\u00b0F). Roll the chilled dough out to 3mm thickness. Carefully lift and press into the tart pan. Trim edges and dock the bottom with a fork. Freeze for 10 minutes to set the shape.", "structured": {"action": "ROLL", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Line the tart shell with parchment paper and fill with pie weights. Blind bake for 15 minutes. Remove weights and paper, then bake for another 10-12 minutes until the crust is golden brown and dry. Let cool completely.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT25M", "doneness_cues": {"visual": "Golden brown throughout", "tactile": "Dry and firm to touch"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "While the shell cools, combine 350g raspberries, white sugar, and lemon juice in a saucepan over medium heat. Simmer for 5-7 minutes until berries break down. Mash slightly for texture.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT7M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Mix cornstarch with water to create a slurry. Stir into the simmering fruit. Cook for 1-2 minutes, stirring constantly, until the mixture thickens and becomes glossy. Remove from heat.", "structured": {"action": "THICKEN", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Glossy and thick", "tactile": "Coats the back of a spoon"}}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Pour the warm raspberry filling into the cooled tart shell. Smooth the surface. Arrange reserved fresh berries on top immediately.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Refrigerate the tart for at least 1 hour to allow the filling to set completely before slicing.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT1H30M", "total_time": "PT2H15M", "overnight_required": false, "yields": "8 slices", "yield_count": 8, "serving_size_g": 135}', '{"flags": ["Vegetarian", "Soy-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 310.39, "protein_g": 3.75, "carbohydrates_g": 47.43, "fat_g": 12.36, "saturated_fat_g": 7.21, "trans_fat_g": null, "monounsaturated_fat_g": 3.54, "polyunsaturated_fat_g": 0.83, "fiber_g": 4.36, "sugar_g": 21.14, "sodium_mg": 102.97, "cholesterol_mg": 53.86, "potassium_mg": 127.43, "calcium_mg": 29.64, "iron_mg": 0.81, "magnesium_mg": 19.05, "phosphorus_mg": 56.14, "zinc_mg": 0.48, "vitamin_a_mcg": 103.75, "vitamin_c_mg": 15.22, "vitamin_d_mcg": 0.12, "vitamin_e_mg": 0.88, "vitamin_k_mcg": 5.44, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": 0.07, "thiamin_mg": 0.05, "riboflavin_mg": 0.05, "niacin_mg": 0.66, "folate_mcg": 22.32, "water_g": 61.77, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Crust will gradually soften after 24 hours.", "duration": "P3D"}, "freezer": {"notes": "Freeze dough only; baked fruit tart does not freeze well.", "duration": "P1M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Food processor", "required": true, "alternative": "Large mixing bowl and pastry cutter"}, {"name": "23cm (9-inch) tart pan with removable bottom", "required": true, "alternative": null}, {"name": "Rolling pin", "required": true, "alternative": null}, {"name": "Pie weights or dried beans", "required": true, "alternative": null}, {"name": "Saucepan", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Fine mesh sieve", "required": false, "alternative": "Skip if seeds are desired"}]', '[{"symptom": "Tart shell sides collapsed during baking", "likely_cause": "Dough was too warm or stretched during lining", "prevention": "Ensure dough is thoroughly chilled before baking; lift dough into corners rather than stretching it", "fix": "Cannot be fixed aesthetically, but still edible. Fill carefully."}]', '["Using light brown sugar in the crust adds a subtle molasses flavor and increases the crispness compared to standard powdered sugar.", "For a clearer, jewel-like filling, strain the cooked raspberries through a sieve to remove seeds before adding the cornstarch slurry.", "Always place the tart pan on a hot baking sheet inside the oven; this conducts heat directly to the bottom of the tart to prevent a soggy bottom."]', '"The fruit tart is a staple of French p\u00e2tisserie, traditionally showcasing seasonal produce atop a sturdy base. This variation utilizes a ''P\u00e2te Sabl\u00e9e'' (sandy dough), a technique perfected in 19th-century Normandy, which relies on the ''sabling'' method of coating flour in fat before adding moisture to inhibit gluten development."', 310.39);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('b7cd7db1-99b0-4adb-9e01-eb23f4a37495', 'Golden Carrot Tahini Soup', 'A velvety, vibrant soup that balances the earthy sweetness of carrots with the nutty richness of tahini and a bright zesty kick of lemon. The texture is luxuriously creamy without dairy, evoking the comforting profile of warm liquid hummus.', 'soup', 'Middle Eastern', 'Easy', '["one pot", "carrot", "great leftovers", "soup", "tahini", "easy", "weeknight", "appetizer", "side", "spring", "vegan", "vegetarian"]', '[{"group_name": "Aromatics & Vegetables", "items": [{"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": "liquid", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "minced", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "carrots", "quantity": 750, "unit": "g", "preparation": "peeled and chopped into 2cm rounds", "notes": null, "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Spices & Base", "items": [{"name": "ground cumin", "quantity": 5, "unit": "g", "preparation": null, "notes": "approx. 1 tsp", "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "ground coriander", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx. 0.5 tsp", "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable broth", "quantity": 1000, "unit": "ml", "preparation": "hot", "notes": null, "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly ground to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Finish", "items": [{"name": "tahini", "quantity": 60, "unit": "ml", "preparation": "stirred well", "notes": "approx. 60g", "substitutions": [], "ingredient_id": "87ae6455-8e22-4c1b-bad7-89fa69c4dc57", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 30, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": null, "unit": "ml", "preparation": "cold", "notes": "optional, to adjust consistency", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Heat the olive oil in a large pot over medium heat. Add the diced onion and a pinch of salt.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT5M", "doneness_cues": {"visual": "Onions are translucent and soft", "tactile": "Soft texture"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add the minced garlic, cumin, and coriander. Stir constantly for about 1 minute until highly fragrant, ensuring the garlic does not burn.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Spices darken slightly", "tactile": "Aromatic release"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the chopped carrots and pour in the vegetable broth. Increase heat to bring to a boil, then reduce heat to maintain a gentle simmer.", "structured": {"action": "SIMMER", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT25M", "doneness_cues": {"visual": null, "tactile": "Carrots are completely tender when pierced with a knife"}}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Remove the pot from the heat. Using an immersion blender, blend the soup directly in the pot until completely smooth and velvety.", "structured": {"action": "PUREE", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Uniform orange color, no chunks remaining", "tactile": null}}, "tips": ["If using a standard blender, fill only halfway and vent the lid to prevent pressure buildup from hot steam."]}, {"step_number": 5, "phase": "finish", "text": "Whisk in the tahini and fresh lemon juice. Taste and adjust seasoning with more salt or lemon if needed. If the soup is too thick, thin with a splash of water.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": {"visual": "Color lightens slightly to creamy orange", "tactile": null}}, "tips": ["Adding tahini off-heat prevents it from seizing or becoming bitter."]}]', '{"active_time": "PT15M", "passive_time": "PT25M", "total_time": "PT40M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 400}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Paleo", "Whole30"], "not_suitable_for": []}', '{"per_serving": {"calories": 284.18, "protein_g": 6.85, "carbohydrates_g": 29.32, "fat_g": 17.09, "saturated_fat_g": 2.57, "trans_fat_g": null, "monounsaturated_fat_g": 5.75, "polyunsaturated_fat_g": 1.05, "fiber_g": 8.29, "sugar_g": 13.56, "sodium_mg": 1868.31, "cholesterol_mg": null, "potassium_mg": 859.36, "calcium_mg": 241.05, "iron_mg": 3.7, "magnesium_mg": 90.87, "phosphorus_mg": 186.37, "zinc_mg": 1.39, "vitamin_a_mcg": 1632.79, "vitamin_c_mg": 19.5, "vitamin_d_mcg": null, "vitamin_e_mg": 2.38, "vitamin_k_mcg": 29.94, "vitamin_b6_mg": 0.36, "vitamin_b12_mcg": null, "thiamin_mg": 0.17, "riboflavin_mg": 0.14, "niacin_mg": 1.98, "folate_mcg": 44.51, "water_g": 232.84, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors meld and improve after 24 hours. Thicken with a splash of water when reheating if needed.", "duration": "P5D"}, "freezer": {"notes": "Freeze without garnishes. Texture remains stable upon thawing.", "duration": "P3M"}, "reheating": "Gently warm over low heat. Do not bring to a rolling boil to prevent tahini from separating.", "does_not_keep": false}', '[{"name": "Large heavy-bottomed pot", "required": true, "alternative": null}, {"name": "Immersion blender", "required": true, "alternative": "Standard blender"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Soup tastes bitter", "likely_cause": "Tahini was old, burnt, or the soup was boiled after adding tahini", "prevention": "Taste tahini before using; always add tahini after removing soup from heat", "fix": "Stir in 1 teaspoon of maple syrup or honey (if not vegan) to counteract bitterness"}, {"symptom": "Texture is grainy or separated", "likely_cause": "Tahini seized from high heat or acid shock", "prevention": "Whisk tahini with a little warm soup water before adding to the main pot", "fix": "Blend vigorously on high speed for another minute"}]', '["Carrot sweetness is key: Use standard supermarket carrots for consistency, but if using older carrots, you may need a pinch of sugar or maple syrup to mimic the ''gentle sweetness'' required.", "Tahini brands vary widely in bitterness and consistency. Use a runny, high-quality Middle Eastern brand (like Soom or Al Wadi) rather than the stiff paste often found in health food bulk bins.", "To garnish, drizzle with olive oil and sprinkle with toasted sesame seeds or za''atar for a textural contrast.", "This recipe mimics the flavor profile of hummus. For a protein boost, you can actually blend in a half-can of drained chickpeas during step 4."]', '"This dish draws from the Middle Eastern tradition of pairing sweet root vegetables with bitter, nutty sesame paste (tahini), a combination often found in mezze platters like ''Carrots with Tarator''. It deconstructs the flavors of hummus\u2014chickpeas, tahini, lemon, garlic\u2014and reimagines them with carrots as the sweet, starchy base."', 284.18);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('b9285e7b-517f-43a4-8c3d-06139aa3a5b3', 'Garden Harvest Deep-Dish Pizza', 'A robust Chicago-style deep-dish pizza featuring a nutty whole wheat and olive oil crust. Layers of nutty Swiss and melting mozzarella protect the crust, topped with garlic-sautéed spinach, fresh peppers, and a chunky vine-ripened tomato sauce.', 'dinner', 'Italian-American', 'Intermediate', '["italian", "pizza and calzones", "dinner", "weeknight", "main course", "vegetarian", "comfort food"]', '[{"group_name": "Whole Wheat Dough", "items": [{"name": "all-purpose flour", "quantity": 220, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "whole wheat flour", "quantity": 110, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "af2661d8-b555-4fef-bdee-51a5190eda92", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 200, "unit": "ml", "preparation": "warm (40\u00b0C)", "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "active dry yeast", "quantity": 7, "unit": "g", "preparation": null, "notes": "1 standard packet", "substitutions": [], "ingredient_id": "b5658d19-b726-4ddb-b56e-74884c61e753", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "sugar", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 6, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Spinach & Cheese Filling", "items": [{"name": "mozzarella cheese", "quantity": 225, "unit": "g", "preparation": "sliced or shredded", "notes": "low-moisture preferred", "substitutions": [], "ingredient_id": "f219ebe9-5ced-45e9-90b4-57fc34e327e8", "nutrition_source": "USDA FoodData Central"}, {"name": "swiss cheese", "quantity": 150, "unit": "g", "preparation": "sliced", "notes": null, "substitutions": [], "ingredient_id": "5a6588f0-4a22-4df2-803c-dfe0f9d88dd3", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh spinach", "quantity": 300, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "4734440a-226d-4d26-a110-3ed5c3bde93f", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "for saut\u00e9ing", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables & Sauce", "items": [{"name": "canned plum tomatoes", "quantity": 400, "unit": "g", "preparation": "whole peeled", "notes": "drained well", "substitutions": [], "ingredient_id": "18e8bb95-d862-47aa-a252-b454fd860e7e", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh plum tomatoes", "quantity": 2, "unit": null, "preparation": "sliced rounds", "notes": "approx 120g", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "green bell pepper", "quantity": 0.5, "unit": null, "preparation": "sliced into rings", "notes": "approx 60g", "substitutions": [], "ingredient_id": "627afa21-0392-4082-ab38-0f20446e190e", "nutrition_source": "Aggregated Public Data"}, {"name": "red bell pepper", "quantity": 0.5, "unit": null, "preparation": "sliced into rings", "notes": "approx 60g", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "Aggregated Public Data"}, {"name": "parmesan cheese", "quantity": 30, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh basil leaves", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Whisk warm water, sugar, and yeast in the bowl of a mixer. Let stand for 5 minutes until frothy.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Add olive oil, all-purpose flour, whole wheat flour, and salt. Knead on low speed (or by hand) until the dough is smooth and tacky, but not sticky.", "structured": {"action": "KNEAD", "temperature": null, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Place dough in a lightly oiled bowl, cover, and let rise in a warm spot until doubled in size.", "structured": {"action": "PROOF", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "While dough rises, saut\u00e9 spinach and minced garlic in olive oil over medium heat until fully wilted. Season with a pinch of salt.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Transfer wilted spinach to a clean towel or cheesecloth. Squeeze firmly to remove as much excess liquid as possible. Chop roughly.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Spinach should be dry and compact"}}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "Crush the canned plum tomatoes by hand into chunky pieces. Mix with dried oregano. Drain any excess liquid.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Preheat oven to 220\u00b0C (425\u00b0F). Generously oil the deep-dish pan. Press the dough into the bottom and 4cm up the sides of the pan.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Layer the ingredients in this exact order: Sliced Mozzarella and Swiss cheese on the bottom (directly on dough), followed by the dry spinach, then fresh sliced peppers and fresh tomato rounds.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Placing cheese first protects the crust from getting soggy."]}, {"step_number": 9, "phase": "assemble", "text": "Top with the crushed canned tomato sauce. Sprinkle with grated Parmesan.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "cook", "text": "Bake on the middle rack for 25-30 minutes, or until the crust is golden brown and the filling is bubbling.", "structured": {"action": "BAKE", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT30M", "doneness_cues": {"visual": "Golden brown crust edge", "tactile": null}}, "tips": []}, {"step_number": 11, "phase": "finish", "text": "Let the pizza rest for 10 minutes before slicing. Top with fresh basil leaves just before serving.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": ["Resting is crucial to prevent the filling from running out when sliced."]}]', '{"active_time": "PT45M", "passive_time": "PT1H15M", "total_time": "PT2H", "overnight_required": false, "yields": "1 25cm (10-inch) pizza", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Vegetarian", "Egg-Free", "Soy-Free"], "not_suitable_for": ["Vegans (dairy)", "Gluten intolerant"]}', '{"per_serving": {"calories": 763.9, "protein_g": 44.3, "carbohydrates_g": 82.92, "fat_g": 30.39, "saturated_fat_g": 10.3, "trans_fat_g": 0.37, "monounsaturated_fat_g": 14.75, "polyunsaturated_fat_g": 2.85, "fiber_g": 14.48, "sugar_g": 17.22, "sodium_mg": 1295.52, "cholesterol_mg": 50.1, "potassium_mg": 1953.4, "calcium_mg": 1122.36, "iron_mg": 9.17, "magnesium_mg": 211.4, "phosphorus_mg": 954.86, "zinc_mg": 6.88, "vitamin_a_mcg": 963.73, "vitamin_c_mg": 100.18, "vitamin_d_mcg": 0.04, "vitamin_e_mg": 4.53, "vitamin_k_mcg": 387.77, "vitamin_b6_mg": 0.4, "vitamin_b12_mcg": 1.76, "thiamin_mg": 0.43, "riboflavin_mg": 0.62, "niacin_mg": 3.72, "folate_mcg": 228.18, "water_g": 195.87, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Reheat in oven or toaster oven to maintain crust texture.", "duration": "P3D"}, "freezer": {"notes": "Wrap slices individually in foil.", "duration": "P1M"}, "reheating": "Bake at 175\u00b0C (350\u00b0F) for 10-15 minutes.", "does_not_keep": false}', '[{"name": "Deep-dish pizza pan or cast iron skillet (25cm/10-inch)", "required": true, "alternative": "Springform cake pan"}, {"name": "Stand mixer with dough hook", "required": false, "alternative": "Large bowl and hands"}, {"name": "Saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Clean kitchen towel or cheesecloth", "required": true, "alternative": null}]', '[{"symptom": "Pizza crust is soggy on the bottom", "likely_cause": "Excess moisture from spinach or vegetables released during baking", "prevention": "Ensure spinach is squeezed very dry and use low-moisture mozzarella", "fix": "Bake on the lowest oven rack for an additional 5-10 minutes to crisp the bottom"}, {"symptom": "Crust edge burns before filling is hot", "likely_cause": "Oven temperature too high or rack too high", "prevention": "Use middle rack and monitor color", "fix": "Cover the crust edges loosely with aluminum foil for the remainder of the bake"}]', '["Swiss cheese adds a distinct, nutty ''Alpine'' flavor that pairs beautifully with spinach, distinguishing this from a standard pizza.", "Do not use fresh mozzarella balls packed in water for deep dish; the water content is too high. Use block mozzarella.", "The order of assembly (Cheese -> Veg -> Sauce) is the inverse of thin crust pizza and is essential for deep dish physics.", "For the sauce, hand-crushing whole peeled tomatoes provides a better texture than using tomato puree or store-bought pasta sauce."]', '"Originating in Chicago in the 1940s, deep-dish pizza is characterized by a high edge that allows for large amounts of cheese and chunky tomato sauce. Unlike Neapolitan pizza which is eaten quickly, deep-dish is a knife-and-fork meal, often seen as a casserole-pizza hybrid."', 763.9);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('b92c9e72-ec0a-452d-93f2-47385520c781', 'Bill Blass''s Classic Meatloaf', 'A legendary recipe from the American fashion designer, known for its elegant simplicity and rich flavor. The secret lies in sautéing the aromatics in butter before mixing, creating a moist, savory interior wrapped in crispy bacon and tangy glaze.', 'dinner', 'American', 'Easy', '["beef", "pork", "bread crumb", "dinner", "easy", "main course", "comfort food", "americana"]', '[{"group_name": "Aromatics", "items": [{"name": "unsalted butter", "quantity": 113, "unit": "g", "preparation": "melted", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "celery", "quantity": 100, "unit": "g", "preparation": "finely chopped", "notes": "approx. 2 stalks", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 150, "unit": "g", "preparation": "finely chopped", "notes": "1 medium onion", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Meat Mixture", "items": [{"name": "ground beef chuck", "quantity": 900, "unit": "g", "preparation": "80/20 lean to fat ratio", "notes": null, "substitutions": [], "ingredient_id": "696b2887-6464-4698-a80a-6860f8633185", "nutrition_source": "Aggregated Public Data"}, {"name": "ground pork", "quantity": 225, "unit": "g", "preparation": "chilled", "notes": null, "substitutions": [], "ingredient_id": "95b412ba-c68f-4b61-ae87-42b44000956b", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 20, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "beaten", "notes": "approx. 100g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "dry breadcrumbs", "quantity": 60, "unit": "g", "preparation": "fine", "notes": null, "substitutions": [], "ingredient_id": "92441189-214a-4a8a-9cfc-dd578fe0d179", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 80, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "worcestershire sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "aa552099-60a9-4267-a732-5870a271c28f", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "dried thyme", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "3b938244-d506-46b2-9027-21bed955bcc5", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Topping", "items": [{"name": "bacon strips", "quantity": 6, "unit": null, "preparation": null, "notes": "approx. 150g", "substitutions": [], "ingredient_id": "339a356e-8f77-48fe-9293-b8e35fed3e6c", "nutrition_source": "USDA FoodData Central"}, {"name": "chili sauce", "quantity": 120, "unit": "ml", "preparation": "optional but recommended", "notes": "Heinz style or ketchup", "substitutions": [], "ingredient_id": "180ad647-bd4a-4ec3-af84-05e7e3e5a4b3", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 175\u00b0C (350\u00b0F). Prepare a baking sheet by lining it with parchment paper or foil for easier cleanup.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a skillet over medium heat, melt the butter. Add the chopped celery and onion. Saut\u00e9 until the onions are translucent and soft but not browned, about 10 minutes. Set aside to cool slightly.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT10M", "doneness_cues": {"visual": "Onions are translucent", "tactile": null}}, "tips": ["Cooling the vegetables prevents the eggs from scrambling when mixed later."]}, {"step_number": 3, "phase": "prep", "text": "In a large mixing bowl, combine the ground beef, ground pork, cooled vegetable mixture, parsley, beaten eggs, breadcrumbs, milk, Worcestershire sauce, salt, pepper, and thyme.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Gently mix ingredients with your hands until just combined. Do not overwork the meat.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Uniform texture but loose"}}, "tips": ["Overmixing compresses the protein, resulting in a tough meatloaf."]}, {"step_number": 5, "phase": "assemble", "text": "Turn the mixture onto the baking sheet and form it into a long oval loaf shape. Top the loaf with the chili sauce (or ketchup) and arrange the bacon strips lengthwise over the top.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Bake in the preheated oven for approximately 60 to 75 minutes. The internal temperature should reach 71\u00b0C (160\u00b0F) in the center of the loaf.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT1H15M", "doneness_cues": {"visual": "Bacon is crisp", "tactile": "Internal temp 71\u00b0C"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from the oven and let the meatloaf rest for 15 minutes before slicing. This allows the juices to redistribute.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT1H15M", "total_time": "PT1H40M", "overnight_required": false, "yields": "8 servings", "yield_count": 8, "serving_size_g": 220}', '{"flags": [], "not_suitable_for": ["Vegetarian", "Vegan", "Halal", "Kosher"]}', '{"per_serving": {"calories": 550.58, "protein_g": 37.56, "carbohydrates_g": 10.89, "fat_g": 38.82, "saturated_fat_g": 16.64, "trans_fat_g": 0.01, "monounsaturated_fat_g": 10.17, "polyunsaturated_fat_g": 2.31, "fiber_g": 1.28, "sugar_g": 3.45, "sodium_mg": 1083.52, "cholesterol_mg": 118.18, "potassium_mg": 627.24, "calcium_mg": 59.77, "iron_mg": 3.75, "magnesium_mg": 22.44, "phosphorus_mg": 384.67, "zinc_mg": 6.27, "vitamin_a_mcg": 137.87, "vitamin_c_mg": 14.6, "vitamin_d_mcg": 0.38, "vitamin_e_mg": 0.6, "vitamin_k_mcg": 48.86, "vitamin_b6_mg": 0.24, "vitamin_b12_mcg": 0.62, "thiamin_mg": 0.37, "riboflavin_mg": 0.24, "niacin_mg": 3.83, "folate_mcg": 28.85, "water_g": 71.51, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container.", "duration": "P3D"}, "freezer": {"notes": "Freeze slices individually wrapped in plastic wrap and foil.", "duration": "P3M"}, "reheating": "Pan-fry slices for a crispy exterior, or reheat gently in an oven covered with foil.", "does_not_keep": false}', '[{"name": "Large skillet", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Baking sheet or shallow roasting pan", "required": true, "alternative": "Loaf pan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Meatloaf is dry and tough", "likely_cause": "The meat mixture was overmixed or low-fat meat was used", "prevention": "Mix gently with fingertips only until combined; ensure beef is at least 20% fat", "fix": "Serve with a gravy or extra warm chili sauce"}, {"symptom": "Loaf is falling apart when sliced", "likely_cause": "Did not rest long enough or lack of binder", "prevention": "Let rest for full 15 minutes; ensure eggs and crumbs were measured correctly", "fix": "Cut thicker slices"}]', '["Saut\u00e9ing the onions and celery in butter first is the hallmark of the Bill Blass method\u2014it adds sweetness and removes the raw crunch found in lesser meatloaves.", "Baking this free-form on a sheet pan rather than in a loaf pan allows the bacon to crisp up better and excess grease to drain away.", "If you cannot find ''Chili Sauce'' (a ketchup-based condiment common in the US), a mixture of 100g ketchup and 20g horseradish makes a great substitute."]', '"This recipe became a society staple in New York after being popularized by designer Bill Blass. It represents the height of ''chic comfort food''\u2014a movement where simple, homespun American classics were elevated for high-society dinner parties."', 550.58);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('b9a33242-3048-442e-b06a-320554949444', 'Spring Harvest Brown Rice Pilaf', 'Nutty brown rice serves as the foundation for caramelized fennel and vibrant, crisp asparagus. Finished with salty Parmesan and a lift of lemon zest, this dish balances earthiness with fresh spring brightness.', 'side dish', 'Mediterranean', 'Easy', '["asparagus", "brown rice", "fennel", "easy", "side", "spring", "gluten-free", "vegetarian"]', '[{"group_name": "Brown Rice Base", "items": [{"name": "brown basmati rice", "quantity": 200, "unit": "g", "preparation": "rinsed", "notes": "or standard long-grain brown rice", "substitutions": [], "ingredient_id": "cad8e863-f4d0-4af7-b418-820a90fd6a23", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable broth", "quantity": 500, "unit": "ml", "preparation": "low-sodium", "notes": null, "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 15, "unit": "g", "preparation": null, "notes": "optional, for richness", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables & Aromatics", "items": [{"name": "fennel bulb", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx. 250g, reserve fronds for garnish", "substitutions": [], "ingredient_id": "a42d03de-0a8a-4a75-8299-5cf01d43b425", "nutrition_source": "USDA FoodData Central"}, {"name": "asparagus", "quantity": 250, "unit": "g", "preparation": "woody ends trimmed, cut into 2cm pieces", "notes": null, "substitutions": [], "ingredient_id": "8a2a9426-3755-4553-953a-fd9cf42cef90", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx. 30g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx. 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "parmesan cheese", "quantity": 40, "unit": "g", "preparation": "freshly grated", "notes": "use vegetarian rennet cheese if required", "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 0.5, "unit": null, "preparation": null, "notes": "zest only", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Combine the rinsed brown rice, vegetable broth, salt, and butter in a medium saucepan. Bring to a boil over high heat, then reduce heat to low, cover tightly with a lid, and simmer until water is absorbed and rice is tender. Do not stir during cooking.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT40M", "doneness_cues": {"visual": "Liquid fully absorbed, steam holes visible in rice surface", "tactile": null}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "While the rice cooks, prepare the vegetables. Remove the stalks and fronds from the fennel bulb (reserve fronds). Dice the bulb into 1cm cubes. Snap the woody ends off the asparagus and cut the spears into 2cm lengths. Mince the shallot and garlic.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "About 15 minutes before the rice is done, heat the olive oil in a large skillet over medium heat. Add the diced fennel and shallot. Saut\u00e9 until the fennel is tender and beginning to caramelize slightly.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT10M", "doneness_cues": {"visual": "Fennel is translucent with golden edges", "tactile": "Fennel yields to pressure"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the minced garlic and asparagus pieces to the skillet with the fennel. Saut\u00e9 until the asparagus is bright green and crisp-tender. Remove from heat immediately to prevent overcooking.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Asparagus is vibrant green", "tactile": "Asparagus is tender but retains snap"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Once the rice is cooked, remove from heat and let it stand covered for 5 minutes. Fluff with a fork, then fold in the saut\u00e9ed vegetable mixture, grated Parmesan, and lemon zest. Season with freshly cracked black pepper.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Garnish with reserved fennel fronds and serve warm.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT40M", "total_time": "PT1H", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 250}', '{"flags": ["Vegetarian", "Gluten-Free", "Egg-Free", "Soy-Free", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 244.21, "protein_g": 7.89, "carbohydrates_g": 24.03, "fat_g": 13.88, "saturated_fat_g": 4.69, "trans_fat_g": null, "monounsaturated_fat_g": 7.34, "polyunsaturated_fat_g": 1.29, "fiber_g": 4.4, "sugar_g": 5.76, "sodium_mg": 1044.66, "cholesterol_mg": 14.86, "potassium_mg": 512.24, "calcium_mg": 179.29, "iron_mg": 2.49, "magnesium_mg": 47.79, "phosphorus_mg": 198.84, "zinc_mg": 1.15, "vitamin_a_mcg": 133.32, "vitamin_c_mg": 13.21, "vitamin_d_mcg": 0.05, "vitamin_e_mg": 2.35, "vitamin_k_mcg": 70.79, "vitamin_b6_mg": 0.2, "vitamin_b12_mcg": 0.13, "thiamin_mg": 0.2, "riboflavin_mg": 0.18, "niacin_mg": 2.35, "folate_mcg": 57.4, "water_g": 160.84, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Flavors meld well over time.", "duration": "P4D"}, "freezer": {"notes": "Texture of asparagus may soften significantly upon thawing.", "duration": "P1M"}, "reheating": "Reheat in a pan with a splash of water to steam the rice back to fluffiness.", "does_not_keep": false}', '[{"name": "Medium saucepan with tight-fitting lid", "required": true, "alternative": null}, {"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Microplane or zester", "required": false, "alternative": null}]', '[{"symptom": "Asparagus is mushy and olive-green", "likely_cause": "Overcooked in the pan or residual heat", "prevention": "Cook asparagus only for 3-4 minutes and remove from heat immediately once bright green.", "fix": "Cannot be fixed texturally; serve immediately to prevent further softening."}, {"symptom": "Brown rice is tough or chewy", "likely_cause": "Insufficient liquid or cooking time", "prevention": "Ensure lid is tight-fitting; brown rice requires 40-50 mins usually.", "fix": "Add 30-50ml hot water, cover, and steam on low for another 5-10 minutes."}]', '["Reserve the delicate, dill-like fronds from the fennel tops; they pack an intense anise flavor and make a beautiful garnish.", "Cooking the vegetables separately from the rice ensures the fennel gets caramelized (flavor) and the asparagus stays crisp (texture), rather than steaming everything into a uniform softness.", "For an extra layer of depth, substitute 60ml of the vegetable broth with dry white wine when starting the rice.", "If using standard brown rice instead of basmati, you may need slightly more water and 5-10 minutes of extra cooking time."]', '"This dish draws inspiration from Italian ''risi e bisi'' and primavera styles, utilizing the Mediterranean technique of highlighting seasonal produce. Fennel and asparagus are classic pairings in coastal Italian cuisine, marking the transition from winter roots to spring greens."', 244.21);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ba5f63ac-a1ea-4031-a214-300a12431c44', 'Kalvsylta (Traditional Swedish Jellied Veal)', 'A classic Swedish Christmas smörgåsbord staple. Tender, minced veal is set in a savory, clarified broth spiced with allspice, white pepper, and cloves. The texture is firm enough to slice but melts in the mouth, traditionally served with pickled beets.', 'appetizer', 'Swedish', 'Intermediate', '["gelatin", "nordic", "winter", "christmas", "julbord", "charcuterie", "traditional"]', '[{"group_name": "Meat and Broth Base", "items": [{"name": "veal shoulder", "quantity": 1000, "unit": "g", "preparation": "whole piece", "notes": null, "substitutions": [], "ingredient_id": "154b7714-319a-47a1-802a-416797db0752", "nutrition_source": "USDA FoodData Central"}, {"name": "veal shank or knuckle", "quantity": 500, "unit": "g", "preparation": null, "notes": "bone-in for natural gelatin", "substitutions": [], "ingredient_id": "49addfc8-db77-484b-b82f-7c7aeb721619", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "peeled and halved", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "carrot", "quantity": 1, "unit": null, "preparation": "peeled and chopped", "notes": "approx 100g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 2000, "unit": "ml", "preparation": null, "notes": "enough to cover meat", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Aromatics", "items": [{"name": "bay leaves", "quantity": 3, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eab2ef3a-7a0e-4188-b746-645b795ada1e", "nutrition_source": "USDA FoodData Central"}, {"name": "whole allspice berries", "quantity": 10, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "d0b9d4b4-744d-472b-bb19-a779a23d70c6", "nutrition_source": "USDA FoodData Central"}, {"name": "whole white peppercorns", "quantity": 10, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "USDA FoodData Central"}, {"name": "whole cloves", "quantity": 3, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "7b3bf68a-3ae9-4dad-91f4-6c7a14ec5e0e", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing and Setting", "items": [{"name": "gelatin leaves", "quantity": 4, "unit": null, "preparation": null, "notes": "standard strength, approx 2g per leaf", "substitutions": [], "ingredient_id": "215c9614-3737-4c45-b7d3-048e3971d4a7", "nutrition_source": "USDA FoodData Central"}, {"name": "white vinegar (12%)", "quantity": 15, "unit": "ml", "preparation": null, "notes": "adjust to taste for acidity", "substitutions": [], "ingredient_id": "8d5bf07e-89a1-47ee-a6b7-d9cb03e96d64", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 10, "unit": "g", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "ground white pepper", "quantity": 2, "unit": "g", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Rinse the veal shoulder and shank under cold water. Place them in a large stockpot and cover with the water. Bring to a boil over high heat.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Once boiling, reduce heat immediately. Skim off the grey foam (scum) that rises to the surface carefully until the broth is clear.", "structured": {"action": "SIMMER", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the onion, carrot, bay leaves, allspice, white peppercorns, and cloves. Simmer gently, covered, until the meat is very tender and falling off the bone.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT1H30M", "doneness_cues": {"visual": null, "tactile": "Meat pulls apart easily with a fork"}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Lift the meat from the pot and set aside to cool slightly. Strain the broth through a fine mesh sieve (or cheesecloth) into a clean bowl. Discard vegetables and spices.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Bloom the gelatin leaves in a bowl of cold water for 5 minutes. While they soak, measure out 400-500ml of the hot strained broth. Stir the bloomed gelatin into this hot broth until fully dissolved.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "Cut the meat into smaller chunks (discarding bones and gristle). Pass the meat through a meat grinder using a medium die, or pulse in a food processor until finely minced but not a paste.", "structured": {"action": "MINCE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Grainy, rice-sized pieces", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Combine the minced meat with the gelatin-enriched broth. Season with vinegar, salt, and ground white pepper. Taste carefully; it should be slightly saltier than you think, as cold dulls the flavor.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Pour the mixture into loaf pans or molds. Tap the molds on the counter to remove air bubbles. Refrigerate until completely set, preferably overnight.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT6H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT6H", "total_time": "PT6H45M", "overnight_required": true, "yields": "2 loaves (approx 1.5kg total)", "yield_count": 20, "serving_size_g": 75}', '{"flags": ["Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Paleo", "Keto", "Whole30", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 83.48, "protein_g": 15.13, "carbohydrates_g": 1.73, "fat_g": 1.52, "saturated_fat_g": 0.49, "trans_fat_g": 0.02, "monounsaturated_fat_g": 0.54, "polyunsaturated_fat_g": 0.14, "fiber_g": 0.34, "sugar_g": 0.9, "sodium_mg": 272.48, "cholesterol_mg": 57, "potassium_mg": 238.83, "calcium_mg": 20.54, "iron_mg": 0.89, "magnesium_mg": 23.92, "phosphorus_mg": 165.41, "zinc_mg": 2.56, "vitamin_a_mcg": 41.92, "vitamin_c_mg": 0.92, "vitamin_d_mcg": 0.18, "vitamin_e_mg": 0.21, "vitamin_k_mcg": 0.94, "vitamin_b6_mg": 0.35, "vitamin_b12_mcg": 1.19, "thiamin_mg": 0.07, "riboflavin_mg": 0.24, "niacin_mg": 5.36, "folate_mcg": 11.26, "water_g": 168.93, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Keep covered to prevent absorbing fridge odors.", "duration": "P5D"}, "freezer": {"notes": "Do not freeze; the gelatin structure will break and become watery upon thawing.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Large stockpot", "required": true, "alternative": null}, {"name": "Meat grinder or Food processor", "required": true, "alternative": "Sharp knife for very fine hand-mincing"}, {"name": "Fine mesh sieve", "required": true, "alternative": null}, {"name": "Loaf pans or molds", "required": true, "alternative": null}, {"name": "Cheesecloth", "required": false, "alternative": null}]', '[{"symptom": "The sylta is too loose or runny after chilling", "likely_cause": "Insufficient natural gelatin extracted from bones or too much liquid used", "prevention": "Ensure you use the veal shank (bones) and measure the liquid ratio carefully", "fix": "Gently reheat the mixture until liquid, dissolve 2 more gelatin leaves, and re-chill"}]', '["The vinegar is not just for preservation; the slight acidity cuts through the richness of the veal fat. Do not skip it.", "For a clearer appearance, ensure you skim the broth very diligently in the first 15 minutes of boiling.", "Serve sliced on rye bread with beetroot salad (r\u00f6dbetssallad) and strong mustard for the authentic experience.", "If using a food processor instead of a grinder, pulse carefully. You want texture, not a p\u00e2t\u00e9."]', '"Kalvsylta is an ancient method of preserving meat in Sweden, dating back to when no part of the animal was wasted. While historically made from heads and feet for their natural setting properties, modern versions use leaner cuts fortified with gelatin. It is one of the essential cold cuts on the traditional Christmas ''Julbord''."', 83.48);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('bac6215b-d108-4824-b939-aaf770c9f421', 'Spiced Braised Lamb Shanks with Swede & Potato Mash', 'Succulent lamb shanks slow-braised in a deep, aromatic tomato and red wine reduction infused with North African spices. Served atop a rustic, buttery mash of swede (rutabaga) and floury potatoes that balances the heat with earthy sweetness.', 'dinner', 'Fusion', 'Intermediate', '["lamb", "slow cooked", "spiced", "main course", "comfort food", "winter", "gluten-free"]', '[{"group_name": "Lamb & Marinade", "items": [{"name": "lamb shanks", "quantity": 4, "unit": null, "preparation": "trimmed", "notes": "approx. 350-400g each", "substitutions": [], "ingredient_id": "15db66fa-11ef-45c7-a5e4-bb38c7bb6824", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 10, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 5, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Spiced Braising Sauce", "items": [{"name": "onion", "quantity": 2, "unit": null, "preparation": "finely diced", "notes": "medium size, approx. 300g total", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 6, "unit": null, "preparation": "minced", "notes": "approx. 18g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "ground coriander", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika", "quantity": 8, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "cinnamon stick", "quantity": 1, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "Aggregated Public Data"}, {"name": "chili flakes", "quantity": 5, "unit": "g", "preparation": null, "notes": "adjust for heat preference", "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "tomato paste", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "41400e7f-7a06-42d2-a625-072c380d60b2", "nutrition_source": "Aggregated Public Data"}, {"name": "dry red wine", "quantity": 250, "unit": "ml", "preparation": null, "notes": "Cabernet Sauvignon or Syrah recommended", "substitutions": ["beef stock", "pomegranate juice"], "ingredient_id": "0fc93141-8ba8-42e0-ac8b-b5af3851554c", "nutrition_source": "USDA FoodData Central"}, {"name": "canned crushed tomatoes", "quantity": 400, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "49a62ca7-db63-4d23-9f6f-2cf873fba8a3", "nutrition_source": "Aggregated Public Data"}, {"name": "chicken stock or lamb stock", "quantity": 500, "unit": "ml", "preparation": null, "notes": "low sodium preferred", "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Creamy Swede & Potato Mash", "items": [{"name": "swede (rutabaga)", "quantity": 500, "unit": "g", "preparation": "peeled and cut into 2cm cubes", "notes": null, "substitutions": [], "ingredient_id": "4607a35e-e29d-4d24-8f6d-cb286e0e1f48", "nutrition_source": "USDA FoodData Central"}, {"name": "potatoes", "quantity": 500, "unit": "g", "preparation": "peeled and cut into 3cm chunks", "notes": "floury variety like Maris Piper or Russet", "substitutions": [], "ingredient_id": "167cc239-8f97-4774-b14d-aa2cc2effbfb", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 80, "unit": "ml", "preparation": "warmed", "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "nutmeg", "quantity": null, "unit": null, "preparation": null, "notes": "small pinch, freshly grated", "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 160\u00b0C/320\u00b0F. Pat the lamb shanks dry with paper towels to ensure a good sear, then season generously with salt and pepper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat olive oil in a large Dutch oven over medium-high heat. Sear the lamb shanks, working in batches if necessary to avoid overcrowding, until deep golden brown on all sides (approx. 8-10 mins). Remove lamb and set aside.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Deep golden brown crust", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to medium. Add the diced onion to the pot (in the rendered lamb fat) and saut\u00e9 for 5 minutes until softened. Add garlic, cumin, coriander, paprika, chili flakes, and the cinnamon stick. Stir constantly for 1 minute until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT6M", "doneness_cues": {"visual": "Onions translucent", "tactile": "Spices aromatic"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Stir in the tomato paste and cook for 2 minutes to darken its color. Pour in the red wine to deglaze, scraping the bottom of the pot with a wooden spoon to release any browned bits (fond). Simmer for 3 minutes to burn off the alcohol.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Return the lamb shanks to the pot along with any resting juices. Add the crushed tomatoes and stock. The liquid should cover about 3/4 of the meat. Bring to a simmer.", "structured": {"action": "SIMMER", "temperature": null, "duration": null, "doneness_cues": {"visual": "Liquid bubbling gently", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Cover the pot with a heavy lid and transfer to the preheated oven. Braise for 2.5 to 3 hours, turning the shanks halfway through. The meat is done when it is falling off the bone and reaches an internal temperature well above 85\u00b0C/185\u00b0F (connective tissue breakdown).", "structured": {"action": "BRAISE", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT3H", "doneness_cues": {"visual": null, "tactile": "Fork-tender, pulling away from bone"}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "About 30 minutes before the lamb is ready, place the cubed swede in a large pot of salted cold water. Bring to a boil. After 10 minutes of boiling the swede, add the potato chunks. Boil together for another 15-20 minutes until both are completely tender.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT30M", "doneness_cues": {"visual": null, "tactile": "Knife slides through easily"}}, "tips": ["Swede is denser than potato, which is why it needs a head start."]}, {"step_number": 8, "phase": "finish", "text": "Drain the vegetables well and return them to the hot pot for 1 minute to steam off excess moisture. Add butter, warm cream, and nutmeg. Mash until smooth and creamy. Season with salt and pepper to taste.", "structured": {"action": "MASH", "temperature": null, "duration": null, "doneness_cues": {"visual": "Smooth consistency", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove lamb from the oven. Skim excess fat from the surface of the sauce. If the sauce is too thin, remove the meat and boil the sauce on the stove for 5-10 minutes to reduce and thicken. Serve shanks over a bed of mash, generously spooning the sauce over the top.", "structured": {"action": "REDUCE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Sauce coats the back of a spoon", "tactile": null}}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT3H", "total_time": "PT3H45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 650}', '{"flags": ["Gluten-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 1396.96, "protein_g": 120.72, "carbohydrates_g": 61.06, "fat_g": 76.13, "saturated_fat_g": 13.53, "trans_fat_g": 0.25, "monounsaturated_fat_g": 11.64, "polyunsaturated_fat_g": 2.14, "fiber_g": 13.2, "sugar_g": 16.65, "sodium_mg": 6497.95, "cholesterol_mg": 54.85, "potassium_mg": 2774.1, "calcium_mg": 257.74, "iron_mg": 14.29, "magnesium_mg": 206.64, "phosphorus_mg": 970.63, "zinc_mg": 20.65, "vitamin_a_mcg": 329.11, "vitamin_c_mg": 76.07, "vitamin_d_mcg": 0.32, "vitamin_e_mg": 3.21, "vitamin_k_mcg": 15.12, "vitamin_b6_mg": 0.74, "vitamin_b12_mcg": 0.06, "thiamin_mg": 0.3, "riboflavin_mg": 0.21, "niacin_mg": 2.9, "folate_mcg": 62.63, "water_g": 361.29, "alcohol_g": 5.81, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves after 24 hours as spices meld.", "duration": "P3D"}, "freezer": {"notes": "Freeze sauce and meat together; freeze mash separately in airtight containers.", "duration": "P3M"}, "reheating": "Reheat gently in a covered pot on the stove with a splash of water, or in a 160\u00b0C oven until piping hot.", "does_not_keep": false}', '[{"name": "Large Dutch Oven or heavy-bottomed pot with lid", "required": true, "alternative": "Deep roasting tray with foil"}, {"name": "Chef''s Knife", "required": true, "alternative": null}, {"name": "Potato Masher or Ricer", "required": true, "alternative": null}, {"name": "Large Saucepan", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Meat is tough after cooking time", "likely_cause": "The collagen hasn''t had enough time or consistent heat to break down into gelatin", "prevention": "Ensure the lid is tight and oven temperature is accurate", "fix": "Return to the oven for another 30-45 minutes. You cannot overcook a shank quickly; it only gets softer."}]', '["Patting the meat dry before searing is crucial. Moisture creates steam, which prevents the Maillard reaction (browning) that adds depth to the sauce.", "Swede (rutabaga) has a naturally lower starch content than potatoes. Combining them gives you the best of both worlds: the fluffy texture of potato and the sweet, savory depth of the swede.", "For an extra glossy ''restaurant style'' sauce, finish the reduced sauce with a knob of cold butter right before serving (monter au beurre).", "This dish tastes arguably better the next day, as the spice profile has time to mature and permeate the meat further."]', '"This dish represents a modern fusion of the British ''meat and two veg'' tradition with the bold spice profiles of the Levant and North Africa. The use of swede (known as ''neeps'' in Scotland) roots the dish in Northern European winter comfort, while spices like cumin and cinnamon transform the braise into something warming and exotic."', 1396.96);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('bb07c961-02b0-485c-8e65-146364e9ca94', 'Viennese Sour Cherry and Quark Phyllo Strudel', 'A refined interpretation of the classic Weichselstrudel. Layers of shatteringly crisp buttery phyllo dough encase a rich, zesty quark cheese filling studded with tart Morello cherries and toasted almond breadcrumbs.', 'dessert', 'Austrian', 'Intermediate', '["austrian", "eastern european", "german", "almond", "phyllo", "sour cherry", "breakfast", "dessert", "christmas"]', '[{"group_name": "Cherry Filling", "items": [{"name": "jarred sour cherries", "quantity": 680, "unit": "g", "preparation": "pitted", "notes": "drained weight approx 350g", "substitutions": [], "ingredient_id": "db71eb8e-285b-4f91-9545-55559cd7951d", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Breadcrumb Mixture", "items": [{"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "fine breadcrumbs", "quantity": 60, "unit": "g", "preparation": null, "notes": "dry, unseasoned", "substitutions": [], "ingredient_id": "92441189-214a-4a8a-9cfc-dd578fe0d179", "nutrition_source": "USDA FoodData Central"}, {"name": "ground almonds", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f22355c5-a702-4d04-97e6-173029c8bea1", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Cheese Filling", "items": [{"name": "quark", "quantity": 500, "unit": "g", "preparation": "20% fat or higher", "notes": "substitute with well-drained ricotta or farmer cheese", "substitutions": ["ricotta", "farmer cheese"], "ingredient_id": "2590decc-443f-4aad-8379-c6de0e4ed40c", "nutrition_source": "Aggregated Public Data"}, {"name": "granulated sugar", "quantity": 70, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "egg yolks", "quantity": 2, "unit": null, "preparation": null, "notes": "approx 36g, keep whites for another use", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}, {"name": "sour cream", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "d171100e-1088-4266-8d50-06cdedda7193", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 3g", "substitutions": [], "ingredient_id": "03fb65be-9b62-44e7-a121-694de64cdec0", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "semolina", "quantity": 20, "unit": "g", "preparation": null, "notes": "helps absorb moisture", "substitutions": [], "ingredient_id": "b841baf9-1ce9-4385-b083-b2fbee23f786", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Phyllo Assembly", "items": [{"name": "phyllo dough", "quantity": 10, "unit": null, "preparation": "thawed sheets", "notes": "approx 250g", "substitutions": [], "ingredient_id": "c070937d-c91b-4f22-90f4-6ec707a13cd2", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 100, "unit": "g", "preparation": "melted", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "powdered sugar", "quantity": 10, "unit": "g", "preparation": "for dusting", "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the sour cherries in a sieve over a bowl and let them drain thoroughly for at least 30 minutes. Gently toss the drained cherries with cornstarch just before assembly.", "structured": {"action": "DRAIN", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Preheat your oven to 190\u00b0C (375\u00b0F). Melt the 30g of butter in a frying pan over medium heat. Add breadcrumbs and toast, stirring constantly, until golden brown. Remove from heat and stir in ground almonds, 30g sugar, and cinnamon. Let cool.", "structured": {"action": "TOAST", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT5M", "doneness_cues": {"visual": "Golden brown", "tactile": "Crisp"}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a mixing bowl, combine the quark (or drained ricotta), 70g sugar, egg yolks, sour cream, lemon zest, vanilla, and semolina. Whisk until smooth and creamy.", "structured": {"action": "MIX", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Lay a sheet of parchment paper on your work surface. Place one sheet of phyllo dough on the paper and brush liberally with melted butter. Repeat this process, stacking 8-10 sheets of phyllo on top of each other, brushing every layer with butter. Keep remaining phyllo covered with a damp towel while working to prevent drying.", "structured": {"action": "LAMINATE", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": ["Work quickly as phyllo dries out in minutes.", "Don''t worry if a sheet tears; just patch it together in the stack."]}, {"step_number": 5, "phase": "assemble", "text": "Sprinkle the toasted breadcrumb mixture over the top sheet of buttered phyllo, leaving a 5cm (2-inch) border around the edges.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Spread the cheese mixture carefully over the breadcrumbs (the crumbs help anchor the cheese). Scatter the drained cherries evenly over the cheese.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Fold the short sides of the phyllo in over the filling. Using the parchment paper to help lift, roll the strudel up from the long side, fairly tightly but without squeezing out the filling. Place seam-side down on the baking sheet.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Brush the top and sides of the strudel with the remaining melted butter. Bake for 30-35 minutes until the pastry is deep golden brown and crisp.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT35M", "doneness_cues": {"visual": "Deep golden brown surface", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Let the strudel cool on the baking sheet for at least 20 minutes to allow the cheese filling to set. Dust generously with powdered sugar before slicing.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT15M", "total_time": "PT1H30M", "overnight_required": false, "yields": "1 large strudel (8-10 slices)", "yield_count": 8, "serving_size_g": 160}', '{"flags": ["Vegetarian", "Soy-Free"], "not_suitable_for": ["Vegans (Dairy, Eggs)", "Celiacs (Gluten)", "Nut Allergies (Almonds)"]}', '{"per_serving": {"calories": 501.06, "protein_g": 14.26, "carbohydrates_g": 54.5, "fat_g": 25.91, "saturated_fat_g": 15.13, "trans_fat_g": null, "monounsaturated_fat_g": 5.94, "polyunsaturated_fat_g": 1.23, "fiber_g": 2.55, "sugar_g": 25.51, "sodium_mg": 278.64, "cholesterol_mg": 86.23, "potassium_mg": 175.88, "calcium_mg": 112.37, "iron_mg": 2.19, "magnesium_mg": 17.38, "phosphorus_mg": 87.56, "zinc_mg": 0.51, "vitamin_a_mcg": 134.71, "vitamin_c_mg": 0.37, "vitamin_d_mcg": 0.26, "vitamin_e_mg": 0.55, "vitamin_k_mcg": 9.45, "vitamin_b6_mg": 0.08, "vitamin_b12_mcg": 0.16, "thiamin_mg": 0.28, "riboflavin_mg": 0.24, "niacin_mg": 2.09, "folate_mcg": 45.09, "water_g": 97.02, "alcohol_g": 0.22, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Pastry will lose crispness. Reheat in oven to restore texture.", "duration": "P3D"}, "freezer": {"notes": "Freeze unbaked for best results. If baked, freeze slices and reheat from frozen.", "duration": "P1M"}, "reheating": "Bake at 180\u00b0C (350\u00b0F) for 10-15 minutes to re-crisp.", "does_not_keep": false}', '[{"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Clean kitchen towel", "required": true, "alternative": "Plastic wrap"}, {"name": "Pastry brush", "required": true, "alternative": null}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Sieve or colander", "required": true, "alternative": null}, {"name": "Frying pan", "required": true, "alternative": null}]', '[{"symptom": "Strudel is soggy on the bottom", "likely_cause": "Cherries were not drained well enough or breadcrumb barrier was too thin", "prevention": "Ensure cherries drain for full 30 mins; do not skip the breadcrumb layer as it absorbs moisture", "fix": "Bake on the lowest oven rack for an additional 5-10 minutes to crisp the bottom"}, {"symptom": "Phyllo cracks excessively while rolling", "likely_cause": "Dough dried out or not enough butter between layers", "prevention": "Keep unused dough under a damp towel; work faster", "fix": "Patch with extra butter and a scrap piece of dough before baking"}]', '["If using ricotta instead of quark, you must strain it in cheesecloth for at least 2 hours, or the filling will be too watery.", "The breadcrumb/almond layer is not just for flavor; it is a structural engineering requirement to prevent the wet cheese and fruit from dissolving the thin pastry.", "Serve slightly warm with vanilla sauce (Kanarimilch) or whipped cream for the traditional Austrian experience.", "Sour cherries (Weichsel) are essential for the flavor balance; sweet cherries will make the dessert cloying."]', '"Strudel gained popularity in the 18th century under the Habsburg Empire, influenced by Ottoman baklava pastry techniques. While Apple Strudel is the most famous export, Topfenstrudel (cheese curd) and Weichselstrudel (sour cherry) are beloved staples in Viennese coffee houses."', 501.06);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('bb142a0d-364d-4693-a9d5-129dd6d939cb', 'Smoked Duck & Citrus Wild Rice Salad', 'A sophisticated grain bowl balancing the rich, savory depth of smoked duck with the vibrant acidity of blood orange and pink grapefruit. Nutty wild rice provides a hearty base, while toasted pecans and pomegranate seeds offer a textural crunch, tied together with a zesty honey-citrus vinaigrette.', 'salad', 'Fusion', 'Intermediate', '["grain bowl", "dinner", "main course", "gluten-free", "healthy", "fusion"]', '[{"group_name": "Base", "items": [{"name": "wild rice blend", "quantity": 200, "unit": "g", "preparation": "dry", "notes": "Or brown rice mix", "substitutions": [], "ingredient_id": "e99f7d25-554d-4078-b6af-e2b53484a492", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 600, "unit": "ml", "preparation": null, "notes": "Or vegetable stock for more flavor", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Protein", "items": [{"name": "hot-smoked duck breast", "quantity": 2, "unit": null, "preparation": "skin-on", "notes": "approx 400g total weight", "substitutions": [], "ingredient_id": "10ea2903-e622-46ac-90ab-261904af3399", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Fresh Elements", "items": [{"name": "blood oranges", "quantity": 2, "unit": null, "preparation": "segmented", "notes": "approx 250g", "substitutions": [], "ingredient_id": "68255621-f24a-4ddd-a795-10f36645222e", "nutrition_source": "USDA FoodData Central"}, {"name": "pink grapefruit", "quantity": 1, "unit": null, "preparation": "segmented", "notes": "approx 200g", "substitutions": [], "ingredient_id": "1317cddf-704a-4c24-8451-29af2f3ef227", "nutrition_source": "USDA FoodData Central"}, {"name": "radishes", "quantity": 4, "unit": null, "preparation": "thinly sliced", "notes": "approx 60g", "substitutions": [], "ingredient_id": "2d6f93d3-117b-49ab-9e11-1058462db7ce", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh mint leaves", "quantity": 15, "unit": "g", "preparation": "torn", "notes": null, "substitutions": [], "ingredient_id": "17abecc0-a2a0-4478-8486-57b46e4305c9", "nutrition_source": "USDA FoodData Central"}, {"name": "scallions", "quantity": 3, "unit": null, "preparation": "sliced", "notes": "approx 45g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish & Crunch", "items": [{"name": "pecans", "quantity": 60, "unit": "g", "preparation": "toasted", "notes": null, "substitutions": [], "ingredient_id": "a5c5ee79-2bcd-4ab2-aed5-b09d0a3df4b5", "nutrition_source": "USDA FoodData Central"}, {"name": "pomegranate seeds", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "793af9f7-6371-4f4b-822d-b2bac2f93aa5", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Citrus Vinaigrette", "items": [{"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh orange juice", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a15da11d-f8dd-46e3-9ac5-725a7912f1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "white wine vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b2f8f0c0-6da9-47aa-932a-c2747b64b807", "nutrition_source": "Aggregated Public Data"}, {"name": "dijon mustard", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "honey", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste (min 1g)", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Rinse the wild rice blend thoroughly under cold water. Combine rice, water (or stock), and salt in a medium saucepan. Bring to a boil, then reduce heat to low, cover, and simmer until tender but chewy, usually 45-50 minutes.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT45M", "doneness_cues": {"visual": "Water absorbed", "tactile": "Grains tender with slight bite"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "While rice cooks, prepare the citrus. Cut the top and bottom off the oranges and grapefruit. Slice off the peel and pith, then carefully cut between the membranes to release the segments (supremes). Squeeze the remaining membrane juice into a small bowl for the dressing.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Clean segments with no pith", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Whisk together the olive oil, reserved citrus juice (supplement with fresh orange juice to reach 30ml), vinegar, Dijon mustard, honey, and black pepper until emulsified.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": {"visual": "Creamy and unified liquid", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Score the skin of the smoked duck breast in a crosshatch pattern. Place skin-side down in a cold skillet. Turn heat to medium and render the fat until the skin is golden and crispy, about 6-8 minutes. Flip and warm the flesh side for 1-2 minutes.", "structured": {"action": "SEAR", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT8M", "doneness_cues": {"visual": "Skin golden brown and crispy", "tactile": "Fat rendered"}}, "tips": ["Starting in a cold pan helps render fat more effectively than a hot pan."]}, {"step_number": 5, "phase": "finish", "text": "Remove duck from the pan and let it rest for 5 minutes. Once rested, slice thinly against the grain.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "In a large bowl, toss the slightly cooled wild rice with half the vinaigrette. Gently fold in the citrus segments, sliced radishes, scallions, torn mint, and pomegranate seeds.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Divide the rice mixture among serving bowls. Fan the sliced duck breast over the top. Garnish with toasted pecans and drizzle with the remaining vinaigrette.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT45M", "total_time": "PT1H10M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 380}', '{"flags": ["Gluten-Free", "Dairy-Free", "Egg-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Infants under 12 months (honey)"]}', '{"per_serving": {"calories": 615.88, "protein_g": 30.79, "carbohydrates_g": 59.02, "fat_g": 30.86, "saturated_fat_g": 4.12, "trans_fat_g": null, "monounsaturated_fat_g": 17.18, "polyunsaturated_fat_g": 5.21, "fiber_g": 8.91, "sugar_g": 20.09, "sodium_mg": 379.31, "cholesterol_mg": null, "potassium_mg": 935.3, "calcium_mg": 57.35, "iron_mg": 6.78, "magnesium_mg": 143.07, "phosphorus_mg": 463.73, "zinc_mg": 4.58, "vitamin_a_mcg": 38.01, "vitamin_c_mg": 33.44, "vitamin_d_mcg": null, "vitamin_e_mg": 2.99, "vitamin_k_mcg": 36.46, "vitamin_b6_mg": 0.28, "vitamin_b12_mcg": null, "thiamin_mg": 0.21, "riboflavin_mg": 0.19, "niacin_mg": 3.87, "folate_mcg": 77.78, "water_g": 244.29, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store dressing separately to keep greens fresh. Duck is best consumed immediately but keeps well.", "duration": "P2D"}, "freezer": {"notes": "Rice can be frozen, but fresh ingredients will not survive freezing.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Medium saucepan with lid", "required": true, "alternative": null}, {"name": "Skillet", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Rice is still hard after 45 minutes", "likely_cause": "Heat was too low or lid wasn''t tight enough, allowing steam to escape", "prevention": "Ensure a tight-fitting lid and maintain a gentle simmer", "fix": "Add 30-50ml boiling water and continue cooking for 10 minutes"}, {"symptom": "Duck skin is chewy", "likely_cause": "Fat didn''t render completely or pan was too hot too fast", "prevention": "Start duck in a cold pan to slowly melt the fat layer", "fix": "Return to pan skin-side down over medium-low heat until crisp"}]', '["Save the rendered duck fat from the skillet; it is liquid gold for roasting potatoes or saut\u00e9ing vegetables later.", "Supreming citrus (removing pith and membrane) is crucial for texture; pith can add unwanted bitterness.", "The wild rice can be cooked a day in advance; just bring it to room temperature before assembling for the best flavor release."]', '"This dish exemplifies modern fusion cuisine, marrying the French technique of duck preparation and citrus supreming with the hearty, nutty grains native to North American cuisine. It reflects a shift toward texturally complex, nutrient-dense main course salads."', 615.88);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('bc3f873c-49fe-46d6-9624-66274c40f923', 'Brioche Pain Perdu with Spiced Plum Syrup', 'Thick slabs of buttery brioche soaked in a rich vanilla custard, pan-fried to a golden crisp, and drenched in a tart, ruby-red plum compote infused with warming cinnamon bark.', 'breakfast', 'French', 'Intermediate', '["french", "brioche", "cinnamon", "french toast", "plum", "breakfast", "brunch", "dinner", "vegetarian"]', '[{"group_name": "Spiced Plum Syrup", "items": [{"name": "red plums", "quantity": 400, "unit": "g", "preparation": "pitted and wedged", "notes": "about 4-5 medium plums", "substitutions": [], "ingredient_id": "dc87a646-585b-4105-8ea6-de7569b368ee", "nutrition_source": "Aggregated Public Data"}, {"name": "granulated sugar", "quantity": 80, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "cinnamon stick", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 5g", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Custard Base", "items": [{"name": "eggs", "quantity": 3, "unit": null, "preparation": "large", "notes": "approx 150g total without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "whole milk", "quantity": 120, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Assembly", "items": [{"name": "brioche loaf", "quantity": 400, "unit": "g", "preparation": "stale", "notes": "sliced into 8 thick (2.5cm) slices", "substitutions": [], "ingredient_id": "b6c47adf-1713-4ed4-8222-436318619746", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 40, "unit": "g", "preparation": "divided", "notes": "for frying", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine plum wedges, sugar, water, and the cinnamon stick in a saucepan over medium heat.", "structured": {"action": "MIX", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Simmer the plum mixture gently until the fruit softens and releases its juices into a ruby syrup, about 10-12 minutes. Stir in lemon juice, remove from heat, and discard the cinnamon stick.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT12M", "doneness_cues": {"visual": "Plums are soft but holding shape; syrup coats the back of a spoon", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a shallow dish, vigorously whisk together eggs, milk, cream, sugar, vanilla, ground cinnamon, and salt until completely homogeneous.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Place brioche slices into the custard. Soak for 30-60 seconds per side, depending on the staleness of the bread. The bread should be heavy with liquid but not falling apart.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": null, "tactile": "Bread feels heavy and saturated but structurally sound"}}, "tips": ["If using fresh, soft brioche, reduce soaking time to 10 seconds per side."]}, {"step_number": 5, "phase": "cook", "text": "Melt half the butter in a large skillet over medium heat. Once foaming subsides, add bread slices (do not overcrowd). Fry for 3-4 minutes per side until deep golden brown and the center is set (internal temp reaches 74\u00b0C/165\u00b0F).", "structured": {"action": "FRY", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": "PT8M", "doneness_cues": {"visual": "Deep golden brown crust", "tactile": "Center springs back slightly when pressed"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Plate the warm French toast and spoon the warm plum syrup generously over the top. Serve immediately.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT10M", "total_time": "PT35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 280}', '{"flags": ["Vegetarian"], "not_suitable_for": ["Vegans"]}', '{"per_serving": {"calories": 699.8, "protein_g": 14.11, "carbohydrates_g": 66.45, "fat_g": 32.9, "saturated_fat_g": 10.24, "trans_fat_g": 0.2, "monounsaturated_fat_g": 5.33, "polyunsaturated_fat_g": 1.31, "fiber_g": 5.19, "sugar_g": 39.88, "sodium_mg": 763.28, "cholesterol_mg": 180.95, "potassium_mg": 470.4, "calcium_mg": 175.8, "iron_mg": 4.71, "magnesium_mg": 35.33, "phosphorus_mg": 112.05, "zinc_mg": 0.98, "vitamin_a_mcg": 469.11, "vitamin_c_mg": 25.11, "vitamin_d_mcg": 1.38, "vitamin_e_mg": 0.83, "vitamin_k_mcg": 1.93, "vitamin_b6_mg": 0.09, "vitamin_b12_mcg": 0.51, "thiamin_mg": 0.03, "riboflavin_mg": 0.26, "niacin_mg": 0.1, "folate_mcg": 20.88, "water_g": 84.59, "alcohol_g": 0.43, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store syrup and toast separately. Re-crisp toast in a pan or toaster oven.", "duration": "P2D"}, "freezer": {"notes": "Freeze cooked toast in a single layer, then bag. Syrup freezes well.", "duration": "P1M"}, "reheating": "Oven at 180\u00b0C/350\u00b0F for 5-8 minutes or toaster.", "does_not_keep": false}', '[{"name": "Heavy-bottomed saucepan", "required": true, "alternative": null}, {"name": "Large non-stick skillet", "required": true, "alternative": null}, {"name": "Shallow baking dish", "required": true, "alternative": "Pie dish"}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Spatula", "required": true, "alternative": null}]', '[{"symptom": "French toast is soggy or raw in the middle", "likely_cause": "Heat was too high (burning outside before inside cooks) or bread was soaked too long", "prevention": "Lower heat to allow heat penetration; use stale bread", "fix": "Transfer to a 180\u00b0C (350\u00b0F) oven for 5-8 minutes to finish cooking the center"}]', '["Pain Perdu literally means ''lost bread''. This recipe is the perfect vehicle for rescuing a brioche loaf that has gone stale.", "If your plums are very tart, you may need to adjust the sugar in the syrup by an extra 10-20g.", "For an extra crisp crust, you can sprinkle a small pinch of sugar on the bread right before flipping it in the pan to caramelize.", "Clarified butter or ghee can be used for frying if you find your butter is burning before the toast is cooked."]', '"Originating in France as a way to avoid wasting food, Pain Perdu turns stale bread into a luxurious dish. While often eaten as a dessert in France, this hearty version with brioche and fruit compote bridges the gap to the American-style brunch."', 699.8);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('bc865de0-b1ca-421a-957a-0893a41a33fc', 'High-Banking Coffee Velodrome Cake', 'A sculptural masterpiece for cycling enthusiasts. This moist, dense espresso-infused sponge is carved to mimic the banked turns of a velodrome track, coated in a smooth café au lait buttercream surface, and finished with precise white royal icing lane markers.', 'dessert', 'European', 'Advanced', '["cake", "novelty cake", "coffee", "velodrome", "baking", "sculpted cake"]', '[{"group_name": "Espresso Sponge", "items": [{"name": "unsalted butter", "quantity": 350, "unit": "g", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "caster sugar", "quantity": 350, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 6, "unit": null, "preparation": "room temperature", "notes": "approx 330g total weight", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "all-purpose flour", "quantity": 350, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "instant espresso powder", "quantity": 15, "unit": "g", "preparation": null, "notes": "dissolved in 30ml boiling water and cooled", "substitutions": [], "ingredient_id": "3df58f53-0c05-4d37-b2b2-e2239ef09add", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Coffee Buttercream (Track Surface)", "items": [{"name": "unsalted butter", "quantity": 250, "unit": "g", "preparation": "softened", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "icing sugar", "quantity": 500, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "instant coffee granules", "quantity": 10, "unit": "g", "preparation": null, "notes": "dissolved in 10ml hot water", "substitutions": [], "ingredient_id": "e8080510-818f-4e47-9ed0-e7169a63c2c1", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "White Royal Icing (Lane Markers)", "items": [{"name": "egg white", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 30g, pasteurized", "substitutions": [], "ingredient_id": "17645f6b-c1ea-4e82-a4b4-5ae8cb6a5a53", "nutrition_source": "Aggregated Public Data"}, {"name": "icing sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 170\u00b0C/340\u00b0F. Grease and line the rectangular cake tin with baking parchment.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Cream the butter and sugar until pale and fluffy. Beat in the eggs one at a time. Fold in the flour and baking powder, then stir in the cooled dissolved espresso. Pour into the tin and bake for 45-50 minutes until a skewer comes out clean.", "structured": {"action": "BAKE", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": "PT50M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "While the cake cools completely, prepare the buttercream. Beat butter until white, add icing sugar in stages, then whisk in the dissolved coffee and cream until smooth and spreadable.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Carving the Velodrome: Trim the top of the cake flat. Cut the rectangle into a large oval. Save the four corner offcuts. Slice the offcuts into wedges and stack them on the two curved ends of the oval to create the raised ''banking'' slope. Use a small amount of buttercream to glue these wedges in place.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Apply a thin ''crumb coat'' of coffee buttercream over the entire structure, smoothing the banking to create a continuous slope. Chill for 30 minutes to set.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Apply a final, thick layer of coffee buttercream. Use a flexible acetate scraper or a piece of clean card to smooth the curves of the track, mimicking the wood surface.", "structured": {"action": "GLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Whisk the egg white, lemon juice, and icing sugar to stiff peaks to make royal icing. Transfer to a piping bag. Pipe the ''cote d''azur'' (inner band), the measurement line (black/dark coffee line), and the sprinter''s line (white) around the track circumference.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT1H30M", "passive_time": "PT2H", "total_time": "PT3H30M", "overnight_required": false, "yields": "1 large cake (16 servings)", "yield_count": 16, "serving_size_g": 140}', '{"flags": ["Vegetarian"], "not_suitable_for": []}', '{"per_serving": {"calories": 631.73, "protein_g": 5.54, "carbohydrates_g": 80.26, "fat_g": 33.27, "saturated_fat_g": 20.05, "trans_fat_g": 0.03, "monounsaturated_fat_g": 9.72, "polyunsaturated_fat_g": 1.64, "fiber_g": 0.59, "sugar_g": 61.8, "sodium_mg": 104.99, "cholesterol_mg": 159.47, "potassium_mg": 100.4, "calcium_mg": 63.93, "iron_mg": 0.77, "magnesium_mg": 11.5, "phosphorus_mg": 91.24, "zinc_mg": 0.47, "vitamin_a_mcg": 297.21, "vitamin_c_mg": 0.13, "vitamin_d_mcg": 0.44, "vitamin_e_mg": 1.12, "vitamin_k_mcg": 2.83, "vitamin_b6_mg": 0.04, "vitamin_b12_mcg": 0.25, "thiamin_mg": 0.04, "riboflavin_mg": 0.15, "niacin_mg": 0.57, "folate_mcg": 16.72, "water_g": 27.57, "alcohol_g": null, "caffeine_mg": 1.14}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight cake carrier to prevent buttercream from absorbing fridge odors.", "duration": "P5D"}, "freezer": {"notes": "Freeze un-iced sponge only. Fully decorated cake does not freeze well due to structural risks.", "duration": "P1M"}, "reheating": "Serve at room temperature.", "does_not_keep": false}', '[{"name": "Rectangular cake tin (23x33cm / 9x13 inch)", "required": true, "alternative": null}, {"name": "Stand mixer or electric hand whisk", "required": true, "alternative": null}, {"name": "Serrated bread knife", "required": true, "alternative": null}, {"name": "Offset spatula", "required": true, "alternative": null}, {"name": "Piping bag with small round nozzle", "required": true, "alternative": null}, {"name": "Cake board (large oval or rectangle)", "required": true, "alternative": null}]', '[{"symptom": "Banked turns are sliding off", "likely_cause": "Buttercream ''glue'' is too soft or cake pieces are too heavy", "prevention": "Chill the cake thoroughly before carving; use skewers/dowels to pin the banks in place", "fix": "Insert toothpicks to hold the slope in place, chill for 1 hour until hard, then remove toothpicks before icing"}]', '["To achieve a true ''wood'' track finish, you can lightly brush the final buttercream layer with a clean pastry brush while spinning the board.", "The sponge must be completely cool before carving, or it will crumble. Ideally, chill the baked sponge for 2 hours for easier sculpting.", "If you want to represent the ''apron'' (the flat center), fill the middle of the oval with crushed chocolate cookies or darker coffee grounds for texture."]', '"The velodrome is the cathedral of track cycling, originating in the late 19th century. The distinct banking (up to 45 degrees in Olympic tracks) allows cyclists to maintain high speeds against centrifugal force. This cake mimics that iconic architecture using the structure of a classic British Madeira sponge."', 631.73);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('bd3c3e2d-270f-44c2-85eb-c816cc776833', 'Boeuf à la Mode', 'A quintessential French Sunday roast where a tough cut of beef transforms into meltingly tender meat through a slow braise in red wine and brandy. The rich, mahogany sauce is naturally thickened by gelatinous aromatics and savory bacon, offering deep, warming flavors perfect for cold weather.', 'dinner', 'French', 'Intermediate', '["french", "one pot", "roast", "beef", "brandy", "dry red wine", "dinner", "main course", "fall", "winter", "christmas"]', '[{"group_name": "Marinade", "items": [{"name": "dry red wine", "quantity": 500, "unit": "ml", "preparation": "room temperature", "notes": "Pinot Noir or Cotes du Rhone", "substitutions": [], "ingredient_id": "0fc93141-8ba8-42e0-ac8b-b5af3851554c", "nutrition_source": "USDA FoodData Central"}, {"name": "brandy", "quantity": 60, "unit": "ml", "preparation": null, "notes": "Cognac or Armagnac", "substitutions": [], "ingredient_id": "812e4827-eb36-4cb7-8c85-c59b54541641", "nutrition_source": "Aggregated Public Data"}, {"name": "onion", "quantity": 1, "unit": null, "preparation": "roughly chopped", "notes": "about 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "carrot", "quantity": 1, "unit": null, "preparation": "roughly chopped", "notes": "about 100g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 4, "unit": null, "preparation": "sprigs", "notes": "about 5g", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "bay leaves", "quantity": 2, "unit": null, "preparation": null, "notes": "dried or fresh", "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Beef & Bacon", "items": [{"name": "boneless beef chuck roast", "quantity": 1500, "unit": "g", "preparation": "whole piece, tied", "notes": "Or rump roast", "substitutions": [], "ingredient_id": "aebf4219-b6a4-45b0-bd82-11203774257f", "nutrition_source": "USDA FoodData Central"}, {"name": "thick-cut bacon", "quantity": 150, "unit": "g", "preparation": "cut into lardons (strips)", "notes": null, "substitutions": [], "ingredient_id": "ea4115b0-8e34-4942-99dd-20d4de64201e", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "for searing", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "approx 10g to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Braising Aromatics", "items": [{"name": "carrots", "quantity": 4, "unit": null, "preparation": "peeled and cut into large chunks", "notes": "about 400g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "celery stalks", "quantity": 2, "unit": null, "preparation": "diced", "notes": "about 100g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "smashed", "notes": "about 20g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "beef stock", "quantity": 300, "unit": "ml", "preparation": "high quality", "notes": null, "substitutions": [], "ingredient_id": "37fecca5-bd32-49f6-af32-175cb501674d", "nutrition_source": "Aggregated Public Data"}, {"name": "tomato paste", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "d0a34229-249b-49e5-a653-227bd7afb7fc", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine the red wine, brandy, chopped onion, chopped carrot, thyme sprigs, and bay leaves in a large bowl. Submerge the beef roast in this marinade, cover, and refrigerate for at least 12 hours (up to 24 hours). Turn the meat once halfway through.", "structured": {"action": "MARINATE", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT12H", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Preheat your oven to 150\u00b0C/300\u00b0F. Remove the beef from the marinade and pat it thoroughly dry with paper towels (wet meat will not brown). Strain the marinade through a sieve, reserving the liquid and discarding the vegetables/herbs used for marinating. Season the beef generously with salt and pepper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a large Dutch oven over medium heat, cook the bacon lardons until the fat has rendered and the bacon is crisp. Remove bacon with a slotted spoon and set aside, leaving the fat in the pot.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Golden brown and crisp", "tactile": "Crunchy"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Increase heat to medium-high. Add the beef roast to the pot and sear deeply on all sides until a dark brown crust forms. Do not rush this step; it builds the flavor base. Remove beef and set aside.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": "Deep dark mahogany crust", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Lower heat to medium. Add the fresh carrots, celery, and garlic to the pot. Saut\u00e9 for 5 minutes until slightly softened. Stir in the tomato paste and cook for 1 minute to darken.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT6M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Pour in the reserved marinade liquid and the beef stock. Scrape the bottom of the pot with a wooden spoon to release any browned bits (fond). Bring to a simmer.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Liquid bubbling", "tactile": "Bottom of pot is smooth"}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Return the beef roast and the cooked bacon to the pot. The liquid should reach about halfway up the meat. Cover with a heavy lid and transfer to the preheated oven. Braise for 3 to 3.5 hours, turning the meat every hour.", "structured": {"action": "BRAISE", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": "PT3H30M", "doneness_cues": {"visual": null, "tactile": "Fork tender, internal temp approx 85\u00b0C/185\u00b0F"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove the pot from the oven. Transfer the beef to a cutting board and tent loosely with foil to rest for 15 minutes. If the sauce is too thin, simmer it on the stovetop over medium-high heat until it coats the back of a spoon.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Slice the beef against the grain into thick slabs. Arrange on a platter and spoon the sauce and vegetables generously over the top.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT16H", "total_time": "PT16H45M", "overnight_required": true, "yields": "6 servings", "yield_count": 6, "serving_size_g": 350}', '{"flags": ["Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Vegetarians", "Vegans", "Those avoiding alcohol"]}', '{"per_serving": {"calories": 792.51, "protein_g": 64.66, "carbohydrates_g": 16.72, "fat_g": 44.75, "saturated_fat_g": 15.9, "trans_fat_g": 1.73, "monounsaturated_fat_g": 16.39, "polyunsaturated_fat_g": 5.29, "fiber_g": 4.16, "sugar_g": 5.88, "sodium_mg": 1316.79, "cholesterol_mg": 172.5, "potassium_mg": 1416.3, "calcium_mg": 105.44, "iron_mg": 7.33, "magnesium_mg": 78.92, "phosphorus_mg": 609.16, "zinc_mg": 21.71, "vitamin_a_mcg": 725.16, "vitamin_c_mg": 12.97, "vitamin_d_mcg": 0.25, "vitamin_e_mg": 2.81, "vitamin_k_mcg": 20.34, "vitamin_b6_mg": 1.28, "vitamin_b12_mcg": 6.83, "thiamin_mg": 1.36, "riboflavin_mg": 0.55, "niacin_mg": 13.63, "folate_mcg": 45.12, "water_g": 371.8, "alcohol_g": 7.75, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves significantly after 24 hours.", "duration": "P4D"}, "freezer": {"notes": "Freeze slices in sauce to prevent drying out.", "duration": "P3M"}, "reheating": "Gently warm in a covered pot over low heat, adding a splash of water if the sauce is too thick.", "does_not_keep": false}', '[{"name": "Large Dutch oven with lid", "required": true, "alternative": "Heavy-bottomed oven-safe pot"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Kitchen twine", "required": true, "alternative": null}, {"name": "Fine mesh sieve", "required": false, "alternative": null}]', '[{"symptom": "Meat is tough and chewy", "likely_cause": "The braising time was too short or the temperature was too high (boiling instead of braising)", "prevention": "Ensure a low oven temperature and test for fork-tenderness before removing", "fix": "Return the meat to the liquid, cover, and continue cooking for another 30-45 minutes"}]', '["Patting the meat dry after marinating is the single most critical step for flavor. If the meat is wet, it will steam instead of searing, and you will lose the rich fond development.", "Traditionally, this dish involves ''larding''\u2014threading strips of fat through the meat using a special needle. Using a chuck roast, which has good internal marbling, mimics this effect without the special tools.", "The brandy adds a distinct sweetness and complexity that separates this from a standard pot roast. Do not skip it; if you must, substitute with a splash of sherry vinegar at the end to brighten the heavy sauce.", "This dish tastes arguably better the next day as the gelatin settles and flavors meld. Reheat gently.", "Serve with potato gratin, mashed potatoes, or buttered egg noodles to soak up the sauce."]', '"Boeuf \u00e0 la Mode is a cornerstone of French bourgeois cuisine, dating back to the 17th century. The name refers to the ''fashionable'' method of preparing a large cut of beef by larding it with fat and slow-cooking it until spoon-tender. It represents the French culinary philosophy of patience, transforming humble, tough cuts into elegant centerpieces."', 792.51);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('be523f7a-a862-48fb-8c91-bc907a1ab2c9', 'Farfalle al Pesto Genovese with Potatoes and Green Beans', 'A classic Ligurian masterpiece where fresh basil pesto clings to al dente bow-tie pasta, tender green beans, and creamy potato chunks. The starch from the potatoes helps create a silky, emulsified sauce.', 'dinner', 'Italian', 'Easy', '["italian", "pastas", "basil", "farfalle", "green bean", "parmesan", "pine nut", "potato", "dinner", "weeknight", "main course", "vegetarian"]', '[{"group_name": "Pesto", "items": [{"name": "fresh basil leaves", "quantity": 50, "unit": "g", "preparation": "washed and dried", "notes": "approx 2 large packed cups", "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}, {"name": "pine nuts", "quantity": 30, "unit": "g", "preparation": null, "notes": "lightly toasted optional", "substitutions": [], "ingredient_id": "971298ad-a9d7-49f7-811b-46afedad18d4", "nutrition_source": "Aggregated Public Data"}, {"name": "parmesan cheese", "quantity": 50, "unit": "g", "preparation": "grated", "notes": "Parmigiano-Reggiano preferred", "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "peeled", "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 100, "unit": "ml", "preparation": "high quality", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "coarse sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pasta & Vegetables", "items": [{"name": "farfalle pasta", "quantity": 320, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "320e9771-354c-4aac-a6d8-68d26af424ad", "nutrition_source": "Aggregated Public Data"}, {"name": "waxy potatoes", "quantity": 200, "unit": "g", "preparation": "peeled and diced into 1.5cm cubes", "notes": "Yukon Gold or similar", "substitutions": [], "ingredient_id": "5bf06478-4785-465e-9842-f70a24e22054", "nutrition_source": "USDA FoodData Central"}, {"name": "green beans", "quantity": 150, "unit": "g", "preparation": "trimmed and cut into 3cm lengths", "notes": null, "substitutions": [], "ingredient_id": "e99ec12b-2d03-4965-bdb7-82cde4c76e61", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 4000, "unit": "ml", "preparation": null, "notes": "for boiling", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": null}, {"name": "salt", "quantity": 30, "unit": "g", "preparation": null, "notes": "for pasta water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the pesto: Combine basil, pine nuts, grated Parmesan, garlic, and coarse salt in a food processor. Pulse until coarsely chopped.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": ["If using a mortar and pestle, start with garlic and salt, then nuts, then basil, then cheese."]}, {"step_number": 2, "phase": "prep", "text": "With the processor running slowly, stream in the olive oil until a creamy, emulsified paste forms. Transfer to a large mixing bowl (large enough to hold all the pasta later).", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Bring the water to a rolling boil in a large pot and add the salt. Add the diced potatoes and cook for 2 minutes before adding anything else.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the farfalle pasta to the boiling water with the potatoes. Stir immediately to prevent sticking.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT8M", "doneness_cues": null}, "tips": ["Check pasta package directions; we will cook for the recommended time minus 1 minute."]}, {"step_number": 5, "phase": "cook", "text": "When there are 4 minutes remaining on the pasta timer, add the green beans to the pot.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Reserve 120ml (1/2 cup) of the starchy cooking water. Drain the pasta, potatoes, and beans thoroughly.", "structured": {"action": "DRAIN", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Add 2 tablespoons of the hot pasta water to the pesto bowl to temper it. Add the drained pasta and vegetables to the bowl. Toss vigorously to coat everything in sauce.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Sauce becomes creamy and coats pasta evenly", "tactile": null}}, "tips": ["Never cook the pesto over direct heat, or the basil will turn black and the cheese will separate."]}, {"step_number": 8, "phase": "finish", "text": "Add more reserved pasta water a splash at a time if the sauce feels too thick. Serve immediately.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT5M", "total_time": "PT30M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Vegetarian", "Egg-Free", "Soy-Free"], "not_suitable_for": ["Nut allergies (pine nuts)"]}', '{"per_serving": {"calories": 647.81, "protein_g": 19.03, "carbohydrates_g": 67.64, "fat_g": 33.94, "saturated_fat_g": 5.9, "trans_fat_g": null, "monounsaturated_fat_g": 19.2, "polyunsaturated_fat_g": 2.77, "fiber_g": 6.02, "sugar_g": 4.24, "sodium_mg": 3357.19, "cholesterol_mg": 8.5, "potassium_mg": 386.87, "calcium_mg": 225.14, "iron_mg": 4.01, "magnesium_mg": 42.53, "phosphorus_mg": 169.23, "zinc_mg": 1.09, "vitamin_a_mcg": 72, "vitamin_c_mg": 12.92, "vitamin_d_mcg": 0.06, "vitamin_e_mg": 3.73, "vitamin_k_mcg": 67.16, "vitamin_b6_mg": 0.17, "vitamin_b12_mcg": 0.15, "thiamin_mg": 0.02, "riboflavin_mg": 0.08, "niacin_mg": 0.67, "folate_mcg": 17.91, "water_g": 57.66, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Pesto may darken slightly due to oxidation; stir well before reheating gently.", "duration": "P3D"}, "freezer": {"notes": "Freezing pasta with potatoes affects texture; best eaten fresh. Pesto alone freezes well.", "duration": "P2M"}, "reheating": "Reheat gently in a pan with a splash of water. Do not microwave high heat to avoid oil separation.", "does_not_keep": false}', '[{"name": "Large stockpot", "required": true, "alternative": null}, {"name": "Food processor or mortar and pestle", "required": true, "alternative": "Blender"}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}]', '[{"symptom": "Pesto turns dark brown", "likely_cause": "Oxidation of basil leaves from heat or air exposure", "prevention": "Ensure basil is dry before blending; do not heat pesto directly; blanch basil for 10 seconds if prepping well in advance", "fix": "The flavor is still good, just cosmetic. Stir in a little fresh chopped parsley to brighten the green."}, {"symptom": "Sauce separates (oily)", "likely_cause": "Pesto was heated too aggressively or not enough starchy water was used", "prevention": "Always toss pasta and pesto in a bowl off the heat, not in the hot pot", "fix": "Add a splash of hot starchy water and toss vigorously to re-emulsify"}]', '["Using waxy potatoes (like Yukon Gold) is crucial; starchy russets will disintegrate into soup in the boiling water.", "For the brightest green color, you can quickly blanch the basil leaves in boiling water for 5 seconds and shock them in ice water before making the pesto.", "The potato starch released into the cooking water acts as a binder, making the pesto creamier than usual\u2014don''t skip the potato!", "Cut the green beans and farfalle to roughly similar sizes to ensure every forkful is balanced.", "If you find raw garlic too pungent, remove the germ (the green sprout inside) or blanch the garlic clove with the potatoes for 1 minute."]', '"Originating from Liguria, Italy, this dish (often called ''Trenette al Pesto'' when made with long noodles) creates a perfect synergy of ingredients. The region is famous for Genovese basil, and the addition of potatoes and beans was a traditional way to bulk up the expensive pasta and sauce with humble, garden-available produce."', 647.81);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('bf752e13-3add-4d26-bf84-a9630fe8a0b9', 'Roasted Peppers with Braised Fennel and Peas', 'Sweet bell peppers roasted until tender, acting as a vibrant vessel for a savory filling of caramelized fennel, sweet garden peas, and aromatic herbs. A light yet satisfying dish emphasizing natural vegetable sweetness.', 'side dish', 'Mediterranean', 'Easy', '["side dish", "vegetable", "pepper", "fennel", "peas", "vegan", "mediterranean"]', '[{"group_name": "Vegetables", "items": [{"name": "red or yellow bell peppers", "quantity": 2, "unit": null, "preparation": "large, halved lengthwise, seeds removed", "notes": "approx 400g total weight", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "Aggregated Public Data"}, {"name": "fennel bulb", "quantity": 1, "unit": null, "preparation": "trimmed and thinly sliced", "notes": "approx 300g; reserve fronds for garnish", "substitutions": [], "ingredient_id": "a42d03de-0a8a-4a75-8299-5cf01d43b425", "nutrition_source": "USDA FoodData Central"}, {"name": "green peas", "quantity": 150, "unit": "g", "preparation": "fresh or frozen", "notes": "if frozen, do not thaw", "substitutions": [], "ingredient_id": "881b19fa-ab56-40da-b76e-46e9098ff18f", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "diced", "notes": "small, approx 80g", "substitutions": [], "ingredient_id": "cc868876-7ceb-46a8-b72a-c3e8a743ee97", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pantry & Seasoning", "items": [{"name": "olive oil", "quantity": 45, "unit": "ml", "preparation": "divided use", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable broth", "quantity": 60, "unit": "ml", "preparation": null, "notes": "or water", "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": "zested and juiced", "notes": "approx 15ml juice", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 3g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly ground, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 200\u00b0C (400\u00b0F). Lightly grease a baking dish suitable for holding the four pepper halves snuggly.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Rub the pepper halves lightly with 15ml of olive oil and a pinch of salt. Place them cut-side up in the baking dish.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a large saut\u00e9 pan, heat the remaining 30ml olive oil over medium heat. Add the diced onion and thinly sliced fennel. Saut\u00e9 for 8-10 minutes until softened and beginning to brown at the edges.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Softened and slightly browned edges", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the minced garlic and cook for 1 minute until fragrant. Pour in the vegetable broth to deglaze the pan, scraping up any browned bits.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Stir in the peas and cook for 2 minutes just to warm through. Remove from heat. Stir in the lemon zest, lemon juice, salt, and pepper.", "structured": {"action": "MIX", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Divide the fennel and pea mixture evenly among the four bell pepper halves, mounding it slightly.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Cover the baking dish with foil and bake for 20 minutes. Remove the foil and bake for another 15 minutes, or until the peppers are tender and the filling is slightly crisp on top.", "structured": {"action": "ROAST", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT35M", "doneness_cues": {"visual": null, "tactile": "Peppers are tender when pierced with a fork"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Allow to cool for 5 minutes. Garnish with the reserved fennel fronds before serving.", "structured": {"action": "GARNISH", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT35M", "total_time": "PT1H", "overnight_required": false, "yields": "4 stuffed halves", "yield_count": 4, "serving_size_g": 210}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 196.9, "protein_g": 4.52, "carbohydrates_g": 21.5, "fat_g": 11.97, "saturated_fat_g": 1.73, "trans_fat_g": null, "monounsaturated_fat_g": 8.3, "polyunsaturated_fat_g": 1.57, "fiber_g": 7.63, "sugar_g": 11.15, "sodium_mg": 408.61, "cholesterol_mg": null, "potassium_mg": 688.69, "calcium_mg": 67.72, "iron_mg": 1.87, "magnesium_mg": 39.88, "phosphorus_mg": 110.81, "zinc_mg": 0.9, "vitamin_a_mcg": 211.51, "vitamin_c_mg": 165.45, "vitamin_d_mcg": null, "vitamin_e_mg": 3.72, "vitamin_k_mcg": 68.51, "vitamin_b6_mg": 0.43, "vitamin_b12_mcg": null, "thiamin_mg": 0.17, "riboflavin_mg": 0.17, "niacin_mg": 2.28, "folate_mcg": 93.05, "water_g": 209.27, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Flavor improves slightly the next day.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; peppers become mushy and peas lose texture upon thawing.", "duration": null}, "reheating": "Reheat in a 180\u00b0C (350\u00b0F) oven for 10-15 minutes or microwave gently.", "does_not_keep": false}', '[{"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Large saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Baking dish", "required": true, "alternative": "Roasting sheet"}]', '[{"symptom": "Fennel is tough or stringy", "likely_cause": "Fennel was sliced too thickly or not saut\u00e9ed long enough before roasting", "prevention": "Slice fennel paper-thin and ensure it is fully softened during the saut\u00e9 step", "fix": "Cover the peppers with foil and bake for an additional 10-15 minutes to steam the filling"}]', '["Select peppers with flat bottoms if possible so they sit stable in the baking dish; otherwise, you can slice a tiny sliver off the bottom to level them (be careful not to create a hole).", "Don''t discard the fennel fronds; they pack a concentrated anise flavor and make the dish look professional when used as a garnish.", "For a non-vegan variation, top with crumbled feta cheese or parmesan during the last 10 minutes of roasting.", "If using frozen peas, there is no need to thaw them before adding to the pan in step 5."]', '"Stuffed vegetables, or ''verdure ripiene'', are a staple of Mediterranean cuisine, particularly in Italy and Greece. This specific combination highlights the affinity between the anise notes of fennel and the natural sweetness of roasted peppers, a pairing often found in Sicilian vegetable cookery."', 196.9);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('bff47f95-e5be-4f16-8e8b-20c8fc618109', 'Braised Rabbit with Green Garlic & Spring Peas', 'A celebration of spring featuring tender farm-raised rabbit braised in white wine and crème fraîche. The dish is finished with a vibrant verdant sauce made from green garlic tops and fresh herbs, balancing the earthy meat with bright, grassy sweetness.', 'dinner', 'French', 'Intermediate', '["rabbit", "french", "spring", "braise", "dinner", "green garlic", "seasonal"]', '[{"group_name": "Rabbit", "items": [{"name": "rabbit legs and saddles", "quantity": 1200, "unit": "g", "preparation": "cut into serving pieces", "notes": "roughly 1 whole rabbit", "substitutions": [], "ingredient_id": "0210f44b-c209-4607-8d22-ee1d67f7e2b8", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 8g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}, {"name": "grapeseed oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "for searing", "substitutions": [], "ingredient_id": "00f43166-1b77-4e77-9e30-e912a59d118a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics & Braise", "items": [{"name": "green garlic", "quantity": 6, "unit": null, "preparation": null, "notes": "approx 150g; if unavailable use 1 leek and 2 garlic cloves", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "Aggregated Public Data"}, {"name": "dry white wine", "quantity": 150, "unit": "ml", "preparation": null, "notes": "Sauvignon Blanc or similar", "substitutions": [], "ingredient_id": "0c041362-befe-4c15-88d2-ba97c8f46428", "nutrition_source": "USDA FoodData Central"}, {"name": "chicken stock", "quantity": 300, "unit": "ml", "preparation": null, "notes": "low sodium", "substitutions": [], "ingredient_id": "2b577d04-33ca-4919-938f-bfc8780a3a4b", "nutrition_source": "USDA FoodData Central"}, {"name": "thyme", "quantity": 4, "unit": null, "preparation": "fresh sprigs", "notes": "about 2g", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "bay leaf", "quantity": 1, "unit": null, "preparation": "dried", "notes": null, "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sauce & Finish", "items": [{"name": "cr\u00e8me fra\u00eeche", "quantity": 100, "unit": "ml", "preparation": "full fat", "notes": null, "substitutions": [], "ingredient_id": "df6e2dd4-e9e6-46bc-8d89-7f046d07a5ce", "nutrition_source": "Aggregated Public Data"}, {"name": "dijon mustard", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "shelled peas", "quantity": 150, "unit": "g", "preparation": "fresh or frozen", "notes": null, "substitutions": [], "ingredient_id": "881b19fa-ab56-40da-b76e-46e9098ff18f", "nutrition_source": "USDA FoodData Central"}, {"name": "broad beans", "quantity": 100, "unit": "g", "preparation": "shelled and skins removed", "notes": "fava beans", "substitutions": [], "ingredient_id": "49680faf-438d-4042-9ae8-6641a010e915", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh tarragon", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "d424d445-0a4e-45d1-9453-7523eb7b176b", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the green garlic: Separate the white/pale green bulbs from the dark green leaves. Thinly slice the whites. Rough chop the greens. Blanch the greens in boiling water for 30 seconds, then shock in ice water to set the vibrant green color. Squeeze dry and set aside for the sauce.", "structured": {"action": "BLANCH", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Pat the rabbit pieces dry with paper towels. Season generously on all sides with salt and freshly cracked black pepper.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat grapeseed oil in a Dutch oven over medium-high heat. Sear the rabbit pieces in batches, taking care not to overcrowd the pan, until deep golden brown (about 3-4 minutes per side). Remove rabbit to a plate.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT8M", "doneness_cues": {"visual": "Deep golden brown crust", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Reduce heat to medium. Add the sliced green garlic whites to the pot. Saut\u00e9 for 2-3 minutes until softened and aromatic, but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Deglaze with white wine, scraping up the fond (browned bits) from the bottom of the pot. Simmer until the liquid reduces by half.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Liquid volume reduced by 50%", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Return the rabbit (and any accumulated juices) to the pot. Add chicken stock, thyme, and bay leaf. Bring to a boil, then reduce heat to low. Cover and simmer gently for 40-50 minutes, or until the meat is tender and separates easily from the bone (internal temp 71\u00b0C/160\u00b0F).", "structured": {"action": "BRAISE", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT45M", "doneness_cues": {"visual": null, "tactile": "Fork tender"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "While rabbit cooks, make the green emulsion: In a blender, combine the blanched green garlic tops, 30ml of the cooking liquid (carefully ladled out), and fresh tarragon. Blend on high until completely smooth and bright green.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Vibrant green smooth paste", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove the rabbit pieces to a warm platter. Discard thyme sprigs and bay leaf. Increase heat to medium-high to reduce the braising liquid slightly. Stir in cr\u00e8me fra\u00eeche and Dijon mustard. Add the fresh peas and broad beans; simmer for 2-3 minutes until tender.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove pot from heat. Stir in the blended green garlic emulsion and lemon juice. Return the rabbit to the pot to coat in the sauce, or pour the sauce and vegetables over the plated rabbit. Serve immediately.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT50M", "total_time": "PT1H35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Gluten-Free", "Low-Carb", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 768.43, "protein_g": 88.64, "carbohydrates_g": 28.61, "fat_g": 30.92, "saturated_fat_g": 10.16, "trans_fat_g": 0.08, "monounsaturated_fat_g": 6.01, "polyunsaturated_fat_g": 8.32, "fiber_g": 5.2, "sugar_g": 5.58, "sodium_mg": 1046.83, "cholesterol_mg": 291, "potassium_mg": 1702.28, "calcium_mg": 172.46, "iron_mg": 12.47, "magnesium_mg": 141.79, "phosphorus_mg": 955.03, "zinc_mg": 1.78, "vitamin_a_mcg": 116.16, "vitamin_c_mg": 30.14, "vitamin_d_mcg": 0.3, "vitamin_e_mg": 2.74, "vitamin_k_mcg": 20.57, "vitamin_b6_mg": 0.96, "vitamin_b12_mcg": 0.26, "thiamin_mg": 0.35, "riboflavin_mg": 0.42, "niacin_mg": 28.56, "folate_mcg": 66.27, "water_g": 377.78, "alcohol_g": 3.34, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container with plenty of sauce to keep the meat moist.", "duration": "P3D"}, "freezer": {"notes": "Cream-based sauces may separate slightly upon thawing; reheat gently while whisking.", "duration": "P2M"}, "reheating": "Reheat slowly in a covered pot on the stove over low heat to avoid toughening the delicate meat.", "does_not_keep": false}', '[{"name": "Dutch oven or heavy-bottomed braiser", "required": true, "alternative": null}, {"name": "Blender or immersion blender", "required": true, "alternative": null}, {"name": "Sieve or fine-mesh strainer", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Rabbit meat is tough or chewy", "likely_cause": "The braise was too short or the heat was too high (boiling instead of simmering)", "prevention": "Ensure a very gentle simmer and check for tenderness at the 40-minute mark.", "fix": "Add a splash more stock if needed and continue braising on low heat for 15-20 minute increments."}]', '["Blanching the green garlic tops is non-negotiable; if you blend them raw, they may oxidize and turn the sauce brown.", "Rabbit saddles cook faster than legs. If possible, remove the saddles 10 minutes before the legs are done to prevent dryness.", "This dish pairs exceptionally well with a crusty baguette to mop up the sauce, or over a bed of polenta.", "If you cannot find rabbit, chicken thighs make a suitable substitute, though the flavor profile will be less gamey.", "Taste the braising liquid before adding salt at the end; stock and reduction often provide enough salinity."]', '"Rabbit is a staple of French country cooking (''cuisine de campagne''), historically valued for its availability and sustainability on farms. This preparation utilizes the entire green garlic plant, a fleeting springtime ingredient that appears before garlic bulbs cure, symbolizing the transition from winter storage crops to fresh spring verdure."', 768.43);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('c0a81042-1477-434e-8e11-8dcd446cb6f4', 'Eggplant and Ricotta Gratin with Velvet Béchamel', 'A sophisticated white lasagna alternative where tender, roasted eggplant steaks replace pasta. Layers of herb-infused ricotta and a silky, nutmeg-scented béchamel sauce melt together under a golden crust of Parmesan cheese.', 'main course', 'Italian', 'Intermediate', '["casseroles", "eggplant", "great leftovers", "dinner", "main course", "summer", "vegetarian", "italian", "gratin"]', '[{"group_name": "Roasted Eggplant", "items": [{"name": "globe eggplant", "quantity": 3, "unit": null, "preparation": "sliced into 1cm rounds", "notes": "approx. 1.2kg total weight", "substitutions": [], "ingredient_id": "77c14307-dacf-4ab2-85d1-3594bff0ec99", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 10, "unit": "g", "preparation": null, "notes": "for sweating eggplant", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "B\u00e9chamel Sauce", "items": [{"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 750, "unit": "ml", "preparation": "warm", "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "nutmeg", "quantity": null, "unit": null, "preparation": "freshly grated", "notes": "generous pinch", "substitutions": [], "ingredient_id": "5d071c04-111e-4498-a8d3-3ab605997536", "nutrition_source": "USDA FoodData Central"}, {"name": "white pepper", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Ricotta Filling & Topping", "items": [{"name": "whole milk ricotta", "quantity": 500, "unit": "g", "preparation": "drained", "notes": null, "substitutions": [], "ingredient_id": "7a68dbea-ec03-42ae-b0eb-983bf3d4c7b6", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh basil", "quantity": 15, "unit": "g", "preparation": "chiffonade", "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": null, "notes": "zest of 1 lemon", "substitutions": [], "ingredient_id": "9e54e651-2396-4bef-9625-00ed1c90838f", "nutrition_source": "Aggregated Public Data"}, {"name": "parmigiano reggiano", "quantity": 100, "unit": "g", "preparation": "freshly grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Arrange eggplant slices on baking sheets or wire racks. Sprinkle with salt and let sit for 20 minutes to draw out bitter moisture. Preheat oven to 220\u00b0C/425\u00b0F.", "structured": {"action": "CURE", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Pat the eggplant slices thoroughly dry with paper towels. Brush both sides lightly with olive oil and arrange in a single layer on baking sheets. Roast for 25 minutes until tender and golden brown. Remove and lower oven temperature to 190\u00b0C/375\u00b0F.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT25M", "doneness_cues": {"visual": "Golden brown spots", "tactile": "Soft center"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "To make the b\u00e9chamel, melt butter in a saucepan over medium heat. Whisk in flour and cook for 2 minutes without browning to cook out the raw flour taste.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Gradually stream in the warm milk while whisking constantly to prevent lumps. Simmer gently for 5-7 minutes until the sauce thickens enough to coat the back of a spoon. Remove from heat and season with nutmeg, salt, and white pepper.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Coats back of spoon (nappe consistency)", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "In a bowl, mix the drained ricotta with the lemon zest, chopped basil, and a pinch of salt. Mix until smooth.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Spread a thin layer of b\u00e9chamel on the bottom of the baking dish. Layer one-third of the roasted eggplant, dollop with half the ricotta mixture, and top with one-third of the remaining b\u00e9chamel. Repeat layers, finishing with the final layer of eggplant, the remaining b\u00e9chamel, and the grated Parmesan cheese.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Bake at 190\u00b0C/375\u00b0F for 30-35 minutes until the dish is bubbling and the top is deeply golden brown. If browning too quickly, tent loosely with foil.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT35M", "doneness_cues": {"visual": "Bubbling edges and browned top", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Let the gratin rest for at least 15-20 minutes before slicing. This allows the layers to set and prevents the sauce from running out when cut.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT55M", "total_time": "PT1H40M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 350}', '{"flags": ["Vegetarian", "Egg-Free", "Soy-Free", "Nut-Free"], "not_suitable_for": ["Vegans (Dairy)", "Celiac Disease (Gluten)"]}', '{"per_serving": {"calories": 515.89, "protein_g": 19.38, "carbohydrates_g": 32.44, "fat_g": 35.38, "saturated_fat_g": 16.69, "trans_fat_g": 0.27, "monounsaturated_fat_g": 14.18, "polyunsaturated_fat_g": 2.29, "fiber_g": 6.51, "sugar_g": 13.72, "sodium_mg": 994.42, "cholesterol_mg": 86.17, "potassium_mg": 844.11, "calcium_mg": 537.17, "iron_mg": 1.03, "magnesium_mg": 69.15, "phosphorus_mg": 412.25, "zinc_mg": 1.79, "vitamin_a_mcg": 269.01, "vitamin_c_mg": 5.6, "vitamin_d_mcg": 1.88, "vitamin_e_mg": 2.52, "vitamin_k_mcg": 25.7, "vitamin_b6_mg": 0.32, "vitamin_b12_mcg": 1.49, "thiamin_mg": 0.17, "riboflavin_mg": 0.61, "niacin_mg": 1.73, "folate_mcg": 59.49, "water_g": 366.29, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves the next day. Reheat gently to prevent oil separation.", "duration": "P4D"}, "freezer": {"notes": "Bake from frozen at 180\u00b0C/350\u00b0F for 45-50 minutes covered, then uncover to brown.", "duration": "P2M"}, "reheating": "Oven at 170\u00b0C/340\u00b0F covered with foil for 20 minutes.", "does_not_keep": false}', '[{"name": "Rimmed baking sheets", "required": true, "alternative": "Large frying pan (batch cooking)"}, {"name": "Medium saucepan", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Ceramic baking dish (approx. 23x33cm)", "required": true, "alternative": null}, {"name": "Pastry brush", "required": false, "alternative": null}]', '[{"symptom": "The finished dish is watery and soupy", "likely_cause": "Insufficient moisture removal from the eggplant before assembly", "prevention": "Ensure eggplant is sweated with salt and roasted until truly dry before layering", "fix": "Let the dish rest for an additional 20 minutes; the liquids will reabsorb as it cools"}]', '["Do not skip the resting period after baking. Like lasagna, this dish needs time for the hydrocolloids in the sauce and cheese to stabilize, ensuring clean cuts rather than a mess.", "Warm your milk before adding it to the roux (butter/flour mixture). Cold milk shocks the starch and makes creating a smooth, lump-free sauce much more difficult.", "The lemon zest in the ricotta is essential. It provides a bright acidic counterpoint to the heavy dairy fats, cutting through the richness for a more balanced palate.", "For an extra crisp top, turn on the broiler/grill for the last 2 minutes of baking, but watch closely to prevent burning."]', '"This dish draws inspiration from the Italian ''Melanzane alla Parmigiana'' but substitutes the traditional tomato sauce with a French-influenced B\u00e9chamel, creating a ''Melanzane Bianche'' (White Eggplant). It highlights the versatility of eggplant as a meaty, substantial vegetable capable of carrying rich dairy flavors."', 515.89);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('c16fbb16-290d-44f3-980a-c4fb8843088b', 'Moroccan Preserved Lemons with Cardamom and Peppercorns', 'Bright, intensely savory, and deeply aromatic lemons cured in their own brine. The floral notes of green cardamom and the sharp heat of black pepper cut through the salinity, creating a complex condiment essential for tagines, stews, and salads.', 'preserve', 'Moroccan', 'Easy', '["middle eastern", "moroccan", "condiments", "cardamom", "kosher salt", "lemon", "preserved", "fermentation", "vegan", "gluten-free"]', '[{"group_name": "Lemons", "items": [{"name": "organic lemons", "quantity": 600, "unit": "g", "preparation": "whole", "notes": "approx. 4-6 medium lemons; organic is crucial as you eat the skin", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh lemon juice", "quantity": 150, "unit": "ml", "preparation": null, "notes": "additional juice to top off the jar", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Curing Agent", "items": [{"name": "kosher salt", "quantity": 100, "unit": "g", "preparation": null, "notes": "coarse grain preferred", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics", "items": [{"name": "green cardamom pods", "quantity": 3, "unit": "g", "preparation": "lightly crushed", "notes": "approx. 10 pods", "substitutions": [], "ingredient_id": "c56f6cd8-882c-487c-956f-3a91ee1fec07", "nutrition_source": "USDA FoodData Central"}, {"name": "black peppercorns", "quantity": 5, "unit": "g", "preparation": "whole", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "bay leaf", "quantity": 1, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Sterilize your glass jar and lid by boiling them in water or running them through a high-heat dishwasher cycle. Ensure they are completely dry before use.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Thoroughly scrub the lemons with a vegetable brush under warm water to remove any wax or residue. Pat dry completely.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Trim the very tips (nubs) off the ends of the lemons. Slice each lemon lengthwise into quarters, but do not cut all the way through the base; keep the four wedges attached at the bottom so the lemon opens like a flower.", "structured": {"action": "SCORE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Generously pack the inside of each scored lemon with kosher salt. Reshape the lemon to close it up.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Sprinkle a layer of salt, a few peppercorns, and a couple of crushed cardamom pods at the bottom of the jar. Press a salt-stuffed lemon firmly into the bottom of the jar to release its juices.", "structured": {"action": "LAYER", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Repeat the process, layering salt-stuffed lemons, spices, and salt, pressing down hard with a wooden spoon or muddler each time to eliminate air pockets and extract juice.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Pour the additional fresh lemon juice over the packed lemons until they are completely submerged. Leave about 1-2 cm of headspace at the top of the jar. Seal tightly.", "structured": {"action": "BRINE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Store in a cool, dark place for at least 3 weeks (21 days). Shake the jar gently once a day for the first week to distribute the salt. The rinds will become translucent and soft when ready.", "structured": {"action": "FERMENT", "temperature": null, "duration": "P21D", "doneness_cues": {"visual": "Rinds become translucent", "tactile": "Texture becomes soft and yielding"}}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "P21D", "total_time": "P21DT20M", "overnight_required": false, "yields": "1 large jar (approx. 500g)", "yield_count": 30, "serving_size_g": 15}', '{"flags": ["Vegetarian", "Vegan", "Pescatarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Keto", "Paleo", "Whole30", "Sugar-Free"], "not_suitable_for": ["Low-Sodium diets"]}', '{"per_serving": {"calories": 7.68, "protein_g": 0.27, "carbohydrates_g": 2.4, "fat_g": 0.09, "saturated_fat_g": 0.01, "trans_fat_g": null, "monounsaturated_fat_g": 0.01, "polyunsaturated_fat_g": 0.02, "fiber_g": 0.65, "sugar_g": 0.63, "sodium_mg": 1293.83, "cholesterol_mg": null, "potassium_mg": 36.44, "calcium_mg": 7.56, "iron_mg": 0.17, "magnesium_mg": 2.47, "phosphorus_mg": 4.06, "zinc_mg": 0.03, "vitamin_a_mcg": 0.3, "vitamin_c_mg": 12.56, "vitamin_d_mcg": null, "vitamin_e_mg": 0.04, "vitamin_k_mcg": 0.27, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.01, "niacin_mg": 0.03, "folate_mcg": 3.23, "water_g": 22.45, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Once opened, keep refrigerated. Ensure lemons remain submerged in brine.", "duration": "P6M"}, "freezer": {"notes": "Freezing alters texture; not recommended.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "1-liter glass jar with airtight lid", "required": true, "alternative": "Two 500ml jars"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Vegetable brush", "required": true, "alternative": null}, {"name": "Wooden spoon or muddler", "required": true, "alternative": null}]', '[{"symptom": "White film developing on top of liquid", "likely_cause": "Harmless kahm yeast forming due to air exposure", "prevention": "Ensure lemons are fully submerged under the brine at all times", "fix": "Skim it off carefully; if the lemons underneath smell fresh and citrusy, they are safe. If moldy (fuzzy/colorful), discard."}, {"symptom": "Lemons are turning brown or mushy", "likely_cause": "Oxidation or contamination", "prevention": "Keep jar sealed tight and ensure all equipment was sterilized", "fix": "Discard. Do not consume."}]', '["Before using preserved lemons in a recipe, rinse them thoroughly to remove excess salt. For most dishes, discard the fleshy pulp and use only the finely diced rind.", "The curing liquid (brine) is liquid gold. Use a teaspoon of it in salad dressings, bloody marys, or hummus for a salty citrus kick.", "Cracking the cardamom pods is essential to allow the brine to penetrate the pod and extract the seeds'' flavor into the lemons.", "If you don''t have enough juice to cover the lemons after pressing them down, you must add more fresh lemon juice. Never add water."]', '"L''hamd marakad (preserved lemons) are a cornerstone of Moroccan gastronomy, providing the distinct savory acidity found in tagines and salads. Historically developed as a method to preserve the abundance of the citrus harvest without refrigeration, the fermentation process transforms the bitter pith into a floral, mellow delicacy."', 7.68);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('c24e027b-cb8e-4422-82c2-f8a63f3272d9', 'Spicy Beer-Braised Lime Chicken', 'Juicy boneless chicken thighs braised in a bold, tangy reduction of lager, hot sauce, and Worcestershire. The sauce creates a glossy glaze that balances heat, acidity, and malty depth.', 'dinner', 'American', 'Easy', '["american", "poultry", "beer", "boneless chicken thigh", "chicken", "worcestershire sauce", "dinner", "easy", "weeknight", "spicy"]', '[{"group_name": "Chicken & Marinade Base", "items": [{"name": "boneless, skinless chicken thighs", "quantity": 800, "unit": "g", "preparation": "trimmed", "notes": "approx. 6-8 thighs", "substitutions": [], "ingredient_id": "d7fc1bf9-fc05-429b-bfa6-2ad857cb0bb6", "nutrition_source": "USDA FoodData Central"}, {"name": "lager beer", "quantity": 250, "unit": "ml", "preparation": null, "notes": "standard American lager or pilsner; avoid IPAs", "substitutions": [], "ingredient_id": "3c4b4d80-5ee5-4488-b81b-fdc88c3e8227", "nutrition_source": "USDA FoodData Central"}, {"name": "worcestershire sauce", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e3b693e4-5eb2-4dfd-988f-cbca12ac6cb7", "nutrition_source": "USDA FoodData Central"}, {"name": "vinegar-based hot sauce", "quantity": 45, "unit": "ml", "preparation": null, "notes": "such as Frank''s or Tabasco", "substitutions": [], "ingredient_id": "1d3ad934-930f-42de-83f5-7fc063eda5dd", "nutrition_source": "Aggregated Public Data"}, {"name": "lime juice", "quantity": 60, "unit": "ml", "preparation": null, "notes": "freshly squeezed, approx 2 limes", "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 20, "unit": "g", "preparation": null, "notes": "balances the beer bitterness", "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics & Finishing", "items": [{"name": "garlic", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "canola or grapeseed", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "smoked paprika", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": "for garnish", "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a mixing bowl, whisk together the beer, Worcestershire sauce, hot sauce, lime juice, honey, minced garlic, smoked paprika, salt, and black pepper to create the marinade.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Add the chicken thighs to the marinade, ensuring they are submerged. Cover and refrigerate for at least 30 minutes (up to 4 hours for deeper flavor).", "structured": {"action": "MARINATE", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Remove chicken from the bowl, shaking off excess liquid, but RESERVE all the marinade. Pat the chicken dry with paper towels to ensure a good sear.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Heat the neutral oil in a large skillet over medium-high heat. Sear the chicken thighs for 3-4 minutes per side until golden brown.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Golden brown crust", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour the reserved marinade into the skillet. Bring to a vigorous boil immediately to ensure food safety.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Liquid bubbling rapidly", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Reduce heat to medium-low. Simmer uncovered for 15-20 minutes, turning chicken occasionally, until the sauce has reduced by half and thickened, and chicken reaches an internal temperature of 74\u00b0C/165\u00b0F.", "structured": {"action": "BRAISE", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Transfer chicken to a serving platter. If the sauce is still too thin, increase heat and reduce for another 2 minutes until it coats the back of a spoon.", "structured": {"action": "REDUCE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Syrupy consistency", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Pour the reduced sauce over the chicken and garnish with chopped fresh cilantro before serving.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT45M", "total_time": "PT1H05M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 280}', '{"flags": ["Dairy-Free", "Nut-Free", "Egg-Free"], "not_suitable_for": ["Gluten-Free (unless GF beer/Worcestershire used)", "Infants under 12 months (honey)"]}', '{"per_serving": {"calories": 487.44, "protein_g": 48.81, "carbohydrates_g": 12.74, "fat_g": 26.32, "saturated_fat_g": 8.07, "trans_fat_g": 0.04, "monounsaturated_fat_g": 9.34, "polyunsaturated_fat_g": 3.3, "fiber_g": 1.38, "sugar_g": 5.79, "sodium_mg": 1579.33, "cholesterol_mg": 226.75, "potassium_mg": 858.56, "calcium_mg": 60.22, "iron_mg": 3.88, "magnesium_mg": 64.67, "phosphorus_mg": 473.88, "zinc_mg": 4.69, "vitamin_a_mcg": 100.92, "vitamin_c_mg": 32.74, "vitamin_d_mcg": null, "vitamin_e_mg": 0.78, "vitamin_k_mcg": 8.89, "vitamin_b6_mg": 1.13, "vitamin_b12_mcg": 1.95, "thiamin_mg": 0.36, "riboflavin_mg": 0.55, "niacin_mg": 13.25, "folate_mcg": 14.44, "water_g": 213.55, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container with plenty of sauce.", "duration": "P3D"}, "freezer": {"notes": "Sauce may separate slightly upon thawing; reheat gently.", "duration": "P2M"}, "reheating": "Reheat in a skillet over low heat with a splash of water until warmed through.", "does_not_keep": false}', '[{"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": "Dutch oven"}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Sauce tastes bitter", "likely_cause": "The beer reduced too much or a bitter IPA was used", "prevention": "Use a mild lager and don''t skip the honey", "fix": "Stir in an extra teaspoon of honey or butter to mask the bitterness"}, {"symptom": "Chicken does not brown during sear", "likely_cause": "Chicken was too wet from the marinade", "prevention": "Thoroughly pat the chicken dry with paper towels before placing in hot oil", "fix": "Skip the browning and rely on the glaze for color, or brown longer but risk overcooking"}]', '["Patting the chicken dry in step 3 is critical. Wet protein steams instead of searing, denying you that essential flavor foundation.", "Do not use IPAs or heavily hopped beers. The cooking process concentrates the hops, resulting in an unpleasantly bitter metallic taste. Stick to Mexican lagers, pilsners, or American blondes.", "The sauce contains sugar (honey) and reduced beer, so watch the heat during the reduction phase to prevent burning.", "This dish pairs exceptionally well with rice or crusty bread to soak up the intense, salty-sour sauce."]', '"This recipe draws on the American tradition of ''drunken'' chicken, combining the convenience of pantry staples like Worcestershire and hot sauce with the tenderizing properties of beer and lime. It reflects the casual, bold flavor profiles found in modern American tailgate and backyard cooking."', 487.44);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('c26b1c67-93a5-4d9e-bb1a-1e3d615557d6', 'Strawberries with Warm Almond Crème Anglaise', 'A study in elegant contrasts: cool, vibrant fresh strawberries meet a velvety, warm custard sauce infused with the nutty depth of almonds. This dessert balances the natural acidity of the fruit with the rich, soothing sweetness of a classic French pouring custard.', 'dessert', 'French', 'Intermediate', '["gluten-free", "vegetarian", "french", "summer", "quick", "dessert", "custard"]', '[{"group_name": "Fresh Strawberries", "items": [{"name": "fresh strawberries", "quantity": 500, "unit": "g", "preparation": "hulled and halved (or quartered if large)", "notes": null, "substitutions": [], "ingredient_id": "b2199214-7c2d-4083-92ae-b0a8a044e25b", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 15, "unit": "g", "preparation": null, "notes": "only if berries are tart", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Almond Custard (Cr\u00e8me Anglaise)", "items": [{"name": "whole milk", "quantity": 250, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 125, "unit": "ml", "preparation": null, "notes": "35% fat or higher", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "egg yolks", "quantity": 4, "unit": null, "preparation": "room temperature", "notes": "approx. 72g", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "pure almond extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "39141299-c561-4745-8ff7-cf7c62c75675", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 2, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "small pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish", "items": [{"name": "sliced almonds", "quantity": 30, "unit": "g", "preparation": "toasted", "notes": null, "substitutions": [], "ingredient_id": "5bcbb4d4-6845-4825-bd21-1c13e52b989c", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the prepared strawberries in a mixing bowl. If they are tart, toss them with the optional sugar and let them sit while you prepare the custard.", "structured": {"action": "MACERATE", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a heavy-bottomed saucepan, combine the milk, cream, and salt. Heat over medium heat until it just begins to simmer around the edges (about 85\u00b0C/185\u00b0F). Do not let it come to a rolling boil.", "structured": {"action": "SCALD", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "While the dairy heats, whisk the egg yolks and sugar together in a separate heat-proof bowl until the mixture is pale yellow and slightly thickened.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Slowly pour about half of the hot milk mixture into the yolks while whisking constantly to temper the eggs. This prevents them from scrambling.", "structured": {"action": "TEMPER", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour the tempered egg mixture back into the saucepan with the remaining hot milk. Cook over low heat, stirring constantly with a spatula, scraping the bottom and corners.", "structured": {"action": "COOK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Continue cooking until the custard reaches 82\u00b0C-84\u00b0C (180\u00b0F-183\u00b0F) and thickens enough to coat the back of the spoon (''nappe''). If you run a finger through the sauce on the spoon, the line should hold its shape.", "structured": {"action": "SIMMER", "temperature": {"celsius": 83, "fahrenheit": 181}, "duration": null, "doneness_cues": {"visual": "Coats back of spoon", "tactile": "Line holds shape on spoon"}}, "tips": ["Do not exceed 85\u00b0C/185\u00b0F or the eggs will curdle."]}, {"step_number": 7, "phase": "finish", "text": "Immediately remove from heat and pour through a fine-mesh sieve into a clean bowl to catch any cooked egg bits. Stir in the almond extract and vanilla extract.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Divide the strawberries among serving bowls. Pour the warm almond custard generously over the fruit and top with toasted sliced almonds for crunch.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 225}', '{"flags": ["Vegetarian", "Gluten-Free", "Soy-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 360.36, "protein_g": 8.15, "carbohydrates_g": 34.57, "fat_g": 22.2, "saturated_fat_g": 10.37, "trans_fat_g": 0.39, "monounsaturated_fat_g": 7.88, "polyunsaturated_fat_g": 2.48, "fiber_g": 3.44, "sugar_g": 29.39, "sodium_mg": 142.51, "cholesterol_mg": 235.96, "potassium_mg": 379.17, "calcium_mg": 154.95, "iron_mg": 1.35, "magnesium_mg": 45.9, "phosphorus_mg": 206.93, "zinc_mg": 1.14, "vitamin_a_mcg": 227.02, "vitamin_c_mg": 73.69, "vitamin_d_mcg": 2.29, "vitamin_e_mg": 3.08, "vitamin_k_mcg": 4.06, "vitamin_b6_mg": 0.17, "vitamin_b12_mcg": 0.68, "thiamin_mg": 0.11, "riboflavin_mg": 0.38, "niacin_mg": 0.84, "folate_mcg": 63.96, "water_g": 196.86, "alcohol_g": 0.17, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store custard in an airtight container with plastic wrap touching the surface to prevent skin formation.", "duration": "P3D"}, "freezer": {"notes": "Custard sauces do not freeze well; texture will separate.", "duration": null}, "reheating": "Gently warm over a water bath or on very low heat, stirring constantly to avoid scrambling.", "does_not_keep": false}', '[{"name": "Medium heavy-bottomed saucepan", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Heat-proof spatula", "required": true, "alternative": null}, {"name": "Instant-read thermometer", "required": false, "alternative": "Spoon test"}, {"name": "Fine-mesh sieve", "required": true, "alternative": null}]', '[{"symptom": "Custard looks grainy or lumpy", "likely_cause": "The eggs were overheated (scrambled)", "prevention": "Keep heat low and stir constantly; remove from heat immediately at 82\u00b0C/180\u00b0F", "fix": "Immediately pour into a blender and blend on high for 30 seconds to smooth out the texture"}, {"symptom": "Custard is too thin", "likely_cause": "Undercooked; did not reach 82\u00b0C/180\u00b0F", "prevention": "Use a thermometer to ensure target temperature is reached", "fix": "Return to low heat and cook gently until thickened"}]', '["Temperature control is key for Cr\u00e8me Anglaise. If you don''t have a thermometer, the ''rose'' test (blowing on the back of the coated spoon creates a rose pattern) is a classic indicator of doneness.", "For a more intense almond flavor without extract, you can steep 50g of toasted chopped almonds in the hot milk for 20 minutes, then strain before adding to the eggs.", "If you prefer a cold dessert, chill the custard for 4 hours and serve over macerated strawberries.", "Leftover whites can be used to make financiers or meringues to accompany this dish."]', '"Cr\u00e8me Anglaise (English Cream) is a fundamental sauce in French gastronomy. Despite its name implying British origins, it was perfected in French kitchens as the base for \u00cele Flottante and ice cream bases. Pairing it warm with fresh fruit is a simple, rustic presentation often found in European country cooking."', 360.36);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('c358b88b-3621-4cb5-8fbb-ffaf7662a1ac', 'Roasted Peppers with Basil Vinaigrette', 'Sweet, vibrant bell peppers roasted until tender and smoky, then peeled and marinated in a sharp garlic-infused red wine vinaigrette. Finished with fresh basil, this dish balances natural sweetness with acidity and herbaceous aromatics.', 'side dish', 'Italian', 'Easy', '["vegetables", "basil", "bell pepper", "red wine vinegar", "side dish", "summer", "italian", "vegan", "gluten-free"]', '[{"group_name": "Vegetables", "items": [{"name": "bell peppers", "quantity": 4, "unit": null, "preparation": "whole", "notes": "mix of red, yellow, or orange; approx 800g total", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh basil leaves", "quantity": 15, "unit": "g", "preparation": "torn or chiffonade", "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "minced or grated", "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vinaigrette", "items": [{"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "red wine vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "9e1b7e74-fdcb-4836-8349-4f7ad86d62df", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 230\u00b0C/450\u00b0F. Line a baking sheet with foil or parchment paper for easy cleanup.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 230, "fahrenheit": 446}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Place whole bell peppers on the baking sheet. Roast for 35-40 minutes, rotating them every 10-15 minutes using tongs, until the skins are completely wrinkled and charred black in spots.", "structured": {"action": "ROAST", "temperature": {"celsius": 230, "fahrenheit": 446}, "duration": "PT40M", "doneness_cues": {"visual": "Skins blistered and blackened", "tactile": "Flesh feels collapsed and soft"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Remove peppers from the oven and immediately transfer them to a large heat-proof bowl. Cover tightly with plastic wrap or a plate to trap the steam. Let sit for 15-20 minutes.", "structured": {"action": "STEAM", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": ["Steaming loosens the skin from the flesh, making peeling effortless."]}, {"step_number": 4, "phase": "prep", "text": "Once cool enough to handle, peel off the charred skins (do not rinse under water). Remove the stems and seeds. Slice the roasted flesh into 2cm wide strips.", "structured": {"action": "PEEL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": ["Avoid rinsing the peppers under water to remove seeds, as this washes away the flavorful roasted oils."]}, {"step_number": 5, "phase": "assemble", "text": "In the same bowl (wipe out seeds first but keep any pepper juices), whisk together the olive oil, red wine vinegar, minced garlic, salt, and black pepper until emulsified.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Add the pepper strips and torn basil to the vinaigrette. Toss gently to coat. Let stand at room temperature for at least 15 minutes before serving to allow flavors to meld.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT50M", "total_time": "PT1H15M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 150}', '{"flags": ["Vegetarian", "Vegan", "Pescatarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Paleo", "Whole30", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 155.51, "protein_g": 2.21, "carbohydrates_g": 12.75, "fat_g": 11.89, "saturated_fat_g": 1.68, "trans_fat_g": null, "monounsaturated_fat_g": 8.24, "polyunsaturated_fat_g": 1.52, "fiber_g": 4.35, "sugar_g": 8.43, "sodium_mg": 299.94, "cholesterol_mg": null, "potassium_mg": 443.04, "calcium_mg": 24.53, "iron_mg": 1.11, "magnesium_mg": 27.3, "phosphorus_mg": 56.71, "zinc_mg": 0.55, "vitamin_a_mcg": 323.97, "vitamin_c_mg": 257.08, "vitamin_d_mcg": null, "vitamin_e_mg": 4.81, "vitamin_k_mcg": 32.57, "vitamin_b6_mg": 0.6, "vitamin_b12_mcg": null, "thiamin_mg": 0.1, "riboflavin_mg": 0.19, "niacin_mg": 2.01, "folate_mcg": 94.63, "water_g": 192.17, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors improve after 24 hours. Store in an airtight container.", "duration": "P5D"}, "freezer": {"notes": "Texture degrades significantly upon freezing; not recommended.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Plastic wrap or large plate", "required": true, "alternative": "Lid"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}]', '[{"symptom": "Peppers are difficult to peel", "likely_cause": "Peppers were not roasted long enough or were not steamed properly after roasting", "prevention": "Ensure skins are blackened and blistered before removing from oven, and cover bowl tightly immediately to trap steam", "fix": "Use a paring knife to gently scrape off stubborn skin patches, or serve rustic with some skin remaining"}]', '["Use high-quality Extra Virgin Olive Oil; since this dish is simple, the quality of the oil significantly impacts the flavor.", "Do not discard the juices that collect in the bowl while the peppers steam; whisk them into the vinaigrette for extra sweetness.", "This dish tastes best at room temperature, making it perfect for preparing ahead of a dinner party.", "For added complexity, try roasting a whole clove of garlic alongside the peppers and mashing it into the dressing."]', '"This dish is reminiscent of the Italian ''Peperonata'' or ''Peperoni Arrostiti'', a staple of antipasto platters across the Mediterranean. It celebrates the natural sweetness of summer produce, preserved simply with oil and vinegar to extend the harvest season."', 155.51);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('c3d9006d-acf8-40c6-b186-c513e41d7338', 'Baked Potatoes with Braised Chard, White Beans, and Tahini Yogurt', 'Crispy-skinned baked potatoes split open to reveal a fluffy interior, topped with savory garlic-braised Swiss chard and creamy cannellini beans. Finished with a nutty, tangy tahini-yogurt drizzle and a dust of aromatic spices.', 'dinner', 'Middle Eastern', 'Easy', '["vegetarian", "beans", "chard", "potatoes", "middle eastern", "dinner", "healthy", "gluten-free"]', '[{"group_name": "Baked Potatoes", "items": [{"name": "floury potatoes", "quantity": 4, "unit": null, "preparation": "whole, scrubbed dry", "notes": "approx 250g each (Russet or Maris Piper)", "substitutions": [], "ingredient_id": "4920385c-ae78-4023-8318-c5dfe051fecc", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Beans and Chard", "items": [{"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "ground coriander", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "swiss chard", "quantity": 300, "unit": "g", "preparation": "washed, stems sliced, leaves chopped separately", "notes": null, "substitutions": [], "ingredient_id": "cb0f8ccb-3b9d-416c-995f-d0a7924af74c", "nutrition_source": "USDA FoodData Central"}, {"name": "cannellini beans", "quantity": 480, "unit": "g", "preparation": "cooked, drained and rinsed", "notes": "2 standard 400g tins", "substitutions": [], "ingredient_id": "338d5b1f-5e90-4e7f-b286-e827b78558e9", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable stock or water", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "ee8aa9f6-84a0-45aa-80c6-a9ee5b0ed561", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Tahini Yogurt", "items": [{"name": "greek yogurt", "quantity": 120, "unit": "g", "preparation": "plain, full fat", "notes": null, "substitutions": [], "ingredient_id": "82632959-c937-4e83-9925-6511fb6eb9ae", "nutrition_source": "USDA FoodData Central"}, {"name": "tahini", "quantity": 60, "unit": "g", "preparation": "well-stirred", "notes": null, "substitutions": [], "ingredient_id": "87ae6455-8e22-4c1b-bad7-89fa69c4dc57", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 30, "unit": "ml", "preparation": "ice cold", "notes": "adjust for consistency", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 200\u00b0C (400\u00b0F).", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Pierce the potatoes all over with a fork. Rub them with olive oil and sea salt, place on a baking sheet, and bake for 50-60 minutes until the skin is crisp and the inside is tender when pierced.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT1H", "doneness_cues": {"visual": null, "tactile": "Soft and yielding when squeezed"}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "While potatoes bake, separate chard stems from leaves. Slice the stems into small 1cm pieces and roughly chop the leaves. Keep them separate.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In a small bowl, whisk together Greek yogurt, tahini, lemon juice, and salt. Gradually whisk in ice-cold water until the dressing reaches a pourable consistency. Set aside.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": {"visual": "Smooth and pourable", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "In a large skillet, heat olive oil over medium heat. Add the diced onion and chard stems. Saut\u00e9 for 6-8 minutes until softened.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Onions translucent, stems tender", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Add minced garlic, cumin, and coriander to the skillet. Stir constantly for 1 minute until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Add the chard leaves, drained cannellini beans, and vegetable stock. Cover the pan and simmer for 3-4 minutes until the leaves are wilted. Uncover and cook for another minute to evaporate excess liquid. Stir in lemon juice and season to taste.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Cut a cross into the top of each baked potato and squeeze the sides to open them up. Fluff the insides slightly with a fork.", "structured": {"action": "SCORE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Spoon the bean and chard mixture generously over the potatoes. Drizzle with the tahini yogurt dressing and serve immediately.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT50M", "total_time": "PT1H15M", "overnight_required": false, "yields": "4 stuffed potatoes", "yield_count": 4, "serving_size_g": 480}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": ["Vegans (contains dairy yogurt)"]}', '{"per_serving": {"calories": 690.74, "protein_g": 34.97, "carbohydrates_g": 111.91, "fat_g": 21.54, "saturated_fat_g": 3.28, "trans_fat_g": null, "monounsaturated_fat_g": 8.55, "polyunsaturated_fat_g": 1.42, "fiber_g": 25.02, "sugar_g": 6.89, "sodium_mg": 1512.69, "cholesterol_mg": 1.8, "potassium_mg": 2564.2, "calcium_mg": 433.55, "iron_mg": 12.5, "magnesium_mg": 330.88, "phosphorus_mg": 574.07, "zinc_mg": 5.27, "vitamin_a_mcg": 235.55, "vitamin_c_mg": 60.59, "vitamin_d_mcg": null, "vitamin_e_mg": 3.28, "vitamin_k_mcg": 634.47, "vitamin_b6_mg": 0.69, "vitamin_b12_mcg": null, "thiamin_mg": 0.25, "riboflavin_mg": 0.17, "niacin_mg": 3.23, "folate_mcg": 67.51, "water_g": 363.68, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store potatoes and bean mixture in separate airtight containers. Keep dressing separate.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; potatoes become grainy and yogurt sauce splits.", "duration": null}, "reheating": "Reheat potatoes and beans in oven at 180\u00b0C until hot. Add cold dressing after heating.", "does_not_keep": false}', '[{"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}]', '[{"symptom": "Tahini dressing seizes and becomes clumpy", "likely_cause": "Initial mixing of tahini with insufficient liquid or wrong temperature", "prevention": "Use ice-cold water and add it very gradually while whisking vigorously", "fix": "Add more cold water 1 teaspoon at a time and whisk violently until it smooths out again"}]', '["For the fluffiest potatoes, drop them onto the counter from a height of 10cm immediately after taking them out of the oven (before cutting). This helps break up the internal structure.", "If you want a smoky depth, add a pinch of smoked paprika or Aleppo pepper to the bean mixture.", "Swiss chard stems are delicious and crunchy; do not discard them. They just need a head start in the pan compared to the delicate leaves.", "To make this vegan, swap the Greek yogurt for a coconut or soy-based plain yogurt, or simply use a lemon-tahini dressing without yogurt."]', '"This dish draws heavily on Levantine flavors, combining the staple legume-heavy diet of the Mediterranean interior with the ubiquitous tahini sauce of the region. While the baked potato vessel is more Western, the filling of leafy greens and beans seasoned with cumin and coriander mimics traditional stews found in Lebanon and Turkey."', 690.74);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('c498ccdf-d34c-4944-8d90-9cf7a8b92df2', 'Spicy Sausage and Rosemary Rigatoni with Blistered Tomatoes', 'A rustic, robust pasta dish balancing the heat of spicy Italian sausage with the bright acidity of blistered cherry tomatoes and the brine of Kalamata olives. Fresh rosemary adds a piney, aromatic depth that cuts through the richness, while starchy pasta water creates a glossy, clinging sauce.', 'dinner', 'Italian', 'Easy', '["italian", "pastas", "sausage", "dinner", "easy", "quick", "weeknight", "main course"]', '[{"group_name": "Pasta", "items": [{"name": "rigatoni or penne", "quantity": 320, "unit": "g", "preparation": "dry", "notes": "Short pasta with ridges works best to catch the sauce", "substitutions": [], "ingredient_id": "9acd8d49-8848-4e5f-90e4-33b9b31f83c9", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 4000, "unit": "ml", "preparation": null, "notes": "For boiling pasta", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 25, "unit": "g", "preparation": null, "notes": "For pasta water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sauce Base", "items": [{"name": "spicy italian sausage", "quantity": 350, "unit": "g", "preparation": "casings removed", "notes": "Bulk sausage meat or links with casings taken off", "substitutions": [], "ingredient_id": "9b35f00b-8eb7-4906-83ef-8a3a244ab02a", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "Extra virgin", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "cherry tomatoes", "quantity": 400, "unit": "g", "preparation": "whole", "notes": "High quality, sweet variety", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "kalamata olives", "quantity": 80, "unit": "g", "preparation": "pitted and halved", "notes": null, "substitutions": [], "ingredient_id": "d018fb0f-3c49-492f-814a-5a9d81cb522e", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Aromatics & Finish", "items": [{"name": "garlic", "quantity": 3, "unit": null, "preparation": "thinly sliced", "notes": "approx 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh rosemary", "quantity": 2, "unit": null, "preparation": "leaves stripped and chopped", "notes": "sprigs, approx 4g chopped", "substitutions": [], "ingredient_id": "fa90a3a7-86cd-40de-8f8c-0464231925c2", "nutrition_source": "USDA FoodData Central"}, {"name": "red chili flakes", "quantity": 2, "unit": "g", "preparation": null, "notes": "Adjust to taste", "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 60, "unit": "ml", "preparation": null, "notes": "Pinot Grigio or Sauvignon Blanc; optional", "substitutions": [], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "pecorino romano", "quantity": 40, "unit": "g", "preparation": "freshly grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Bring a large pot of water to a rolling boil. Once boiling, add the salt.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "While water heats, heat olive oil in a large skillet over medium-high heat. Add the sausage meat, breaking it up with a spoon into bite-sized chunks. Cook until well-browned and fat has rendered, ensuring internal temperature reaches at least 74\u00b0C/165\u00b0F.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": "PT6M", "doneness_cues": {"visual": "Deep golden brown crust on meat", "tactile": "Firm to the touch"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to medium. Add sliced garlic, chopped rosemary, and chili flakes to the sausage fat. Saut\u00e9 briefly until fragrant, being careful not to burn the garlic.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Garlic turns pale gold", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the cherry tomatoes and olives. If using wine, pour it in now to deglaze, scraping up any browned bits from the bottom of the pan. Cover the pan loosely and let simmer until tomatoes begin to burst and release their juices.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Tomatoes are shriveled and saucy", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Meanwhile, cook the pasta in the boiling salted water until 2 minutes shy of al dente (it will finish cooking in the sauce). Reserve 1 cup (240ml) of starchy pasta water, then drain.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": ["Check pasta package instructions for timing, but always taste test early."]}, {"step_number": 6, "phase": "assemble", "text": "Transfer the drained pasta directly into the skillet with the sausage and tomatoes. Add 120ml (approx 1/2 cup) of the reserved pasta water. Increase heat to high and toss vigorously until the sauce emulsifies and coats the pasta beautifully.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Sauce looks glossy and clings to pasta", "tactile": null}}, "tips": ["If the sauce looks dry, add more pasta water in small increments."]}, {"step_number": 7, "phase": "finish", "text": "Remove from heat. Stir in half of the Pecorino Romano cheese. Taste and adjust seasoning with salt if necessary (sausage and olives are salty, so taste first). Serve immediately topped with the remaining cheese.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT0M", "total_time": "PT25M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 380}', '{"flags": ["Nut-Free", "Egg-Free", "Soy-Free"], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 726.59, "protein_g": 32.18, "carbohydrates_g": 66.16, "fat_g": 34.07, "saturated_fat_g": 10.57, "trans_fat_g": 0.09, "monounsaturated_fat_g": 13.67, "polyunsaturated_fat_g": 4.83, "fiber_g": 4.82, "sugar_g": 7.2, "sodium_mg": 3446.48, "cholesterol_mg": 77.68, "potassium_mg": 933.98, "calcium_mg": 214.36, "iron_mg": 3.84, "magnesium_mg": 129.29, "phosphorus_mg": 528.75, "zinc_mg": 4.87, "vitamin_a_mcg": 41.71, "vitamin_c_mg": 15.04, "vitamin_d_mcg": 0.93, "vitamin_e_mg": 0.98, "vitamin_k_mcg": 5.98, "vitamin_b6_mg": 0.39, "vitamin_b12_mcg": 0.91, "thiamin_mg": 0.32, "riboflavin_mg": 0.27, "niacin_mg": 5.61, "folate_mcg": 5.52, "water_g": 1049.78, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Pasta may absorb liquid; add a splash of water when reheating.", "duration": "P3D"}, "freezer": {"notes": "Freezing is possible but pasta texture may degrade upon reheating.", "duration": "P1M"}, "reheating": "Reheat in a pan over medium heat with a splash of water to re-emulsify the sauce.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": "Dutch oven"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "Sauce is oily or greasy", "likely_cause": "Emulsification broke or too much fat rendered from sausage without enough starch water", "prevention": "Ensure you add enough starchy pasta water and toss vigorously while boiling", "fix": "Add another splash of hot pasta water and toss aggressively off the heat to bring the emulsion back together"}]', '["Do not drain the sausage fat unless it is excessive (more than 2 tbsp); that fat carries all the spice and paprika flavor which forms the base of the sauce.", "Using whole cherry tomatoes instead of canned tomatoes provides a fresher, sweeter acidity that balances the heavy sausage perfectly.", "The ''mantecatura'' step (tossing pasta with water and cheese at the end) is the secret to restaurant-quality texture. Never skip the pasta water.", "For extra texture, you can add a handful of toasted breadcrumbs (pangrattato) right before serving."]', '"This dish draws inspiration from the ''Puttanesca'' tradition of Southern Italy, utilizing pantry staples like olives and chilies, but fortifies it with sausage for a heartier meal. It reflects the ''cucina povera'' philosophy where a few strong ingredients are used to flavor a large amount of pasta."', 726.59);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('c55a0b96-dc2d-481a-95bc-5e05357ba8cf', 'Braised Oxtail and Steak Poutine', 'The ultimate indulgence: crispy double-fried potatoes topped with fresh squeaky cheese curds, smothered in a rich, gelatinous shredded oxtail gravy, and crowned with slices of perfectly seared ribeye steak.', 'dinner', 'Canadian', 'Advanced', '["poutine", "oxtail", "steak", "comfort food", "canadian", "fusion", "deep fried"]', '[{"group_name": "Oxtail Gravy Base", "items": [{"name": "beef oxtail", "quantity": 1000, "unit": "g", "preparation": "pieces", "notes": "trimmed of excess hard fat", "substitutions": [], "ingredient_id": "9c8ce899-4460-4126-81b5-4a72ba88bf63", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "onion", "quantity": 1, "unit": null, "preparation": "diced", "notes": "medium, approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "carrot", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx 100g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "celery stalk", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx 50g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "smashed", "notes": null, "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "red wine", "quantity": 250, "unit": "ml", "preparation": null, "notes": "dry, full-bodied like Cabernet", "substitutions": [], "ingredient_id": "0fc93141-8ba8-42e0-ac8b-b5af3851554c", "nutrition_source": "USDA FoodData Central"}, {"name": "beef stock", "quantity": 1500, "unit": "ml", "preparation": null, "notes": "low sodium preferred", "substitutions": [], "ingredient_id": "787d0598-6162-4b49-a834-8ca6a9a25e15", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh thyme", "quantity": 4, "unit": null, "preparation": null, "notes": "sprigs", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "bay leaves", "quantity": 2, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Gravy Roux & Finish", "items": [{"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 45, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly ground, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}, {"name": "apple cider vinegar", "quantity": 5, "unit": "ml", "preparation": null, "notes": "to balance richness", "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Steak", "items": [{"name": "ribeye steaks", "quantity": 2, "unit": null, "preparation": null, "notes": "approx 300g each, thick cut", "substitutions": [], "ingredient_id": "96c215fb-499c-4b55-9824-1153b8acdebd", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": null, "unit": null, "preparation": null, "notes": "generous amount for seasoning", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "high smoke point", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "ae1e9713-8f4a-4a91-9619-baa177e12fc6", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh rosemary", "quantity": 1, "unit": null, "preparation": null, "notes": "sprig", "substitutions": [], "ingredient_id": "fa90a3a7-86cd-40de-8f8c-0464231925c2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Fries & Assembly", "items": [{"name": "russet potatoes", "quantity": 1200, "unit": "g", "preparation": "peeled and cut into batons", "notes": "1cm thickness", "substitutions": [], "ingredient_id": "a7db25be-476c-48fe-8cb8-2ea66fb91587", "nutrition_source": "USDA FoodData Central"}, {"name": "frying oil", "quantity": 2000, "unit": "ml", "preparation": null, "notes": "peanut, canola, or vegetable", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}, {"name": "white cheddar cheese curds", "quantity": 350, "unit": "g", "preparation": "room temperature", "notes": "MUST be fresh for squeak", "substitutions": [], "ingredient_id": "c5948fd5-2804-4d18-98e4-da7884e00680", "nutrition_source": "USDA FoodData Central"}, {"name": "chives", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat oxtail dry and season heavily with salt. Heat oil in a Dutch oven over high heat. Sear oxtail on all sides until deeply browned. Remove meat and set aside.", "structured": {"action": "SEAR", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Reduce heat to medium. Add onions, carrots, and celery to the pot. Saut\u00e9 until softened and browned. Add smashed garlic and cook for 1 minute until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Deglaze with red wine, scraping up fond (browned bits) from the bottom. Simmer until reduced by half. Return oxtail to the pot, add beef stock, thyme, and bay leaves. Bring to a boil, then cover and simmer on low until meat is falling off the bone.", "structured": {"action": "BRAISE", "temperature": null, "duration": "PT3H30M", "doneness_cues": {"visual": null, "tactile": "Meat pulls away from bone effortlessly"}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "While oxtail braises, rinse cut potato batons in cold water until water runs clear. Soak in cold water for at least 1 hour to remove excess starch. Drain and pat completely dry with paper towels.", "structured": {"action": "SOAK", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Heat frying oil to 130\u00b0C (265\u00b0F). Blanch potatoes in batches for about 6-8 minutes until soft but not browned. Remove and drain on a wire rack. Let cool completely.", "structured": {"action": "FRY", "temperature": {"celsius": 130, "fahrenheit": 266}, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "When oxtail is tender, remove meat from pot. Strain the liquid into a bowl, discarding solids. Shred the meat, discarding bones and excess fat. Skim fat from the strained liquid.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "In the same pot, melt butter over medium heat. Whisk in flour and cook for 2 minutes to make a roux. Slowly whisk in the strained braising liquid. Simmer until thickened to a gravy consistency. Stir in the shredded oxtail meat. Keep warm.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Season steaks with salt. Heat a cast iron skillet over high heat with oil until smoking. Sear steaks for 3-4 minutes per side. In the last minute, add butter, garlic, and rosemary; baste the steaks continually. Aim for 52\u00b0C (125\u00b0F) internal for medium-rare.", "structured": {"action": "SEAR", "temperature": null, "duration": null, "doneness_cues": {"visual": "Deep brown crust", "tactile": "Firm but yielding"}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove steaks and let rest for 10 minutes. While steaks rest, increase fryer oil temperature to 190\u00b0C (375\u00b0F). Fry the blanched potatoes a second time until golden brown and crispy (approx 3-4 minutes). Toss immediately with salt.", "structured": {"action": "FRY", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "assemble", "text": "Slice the steaks against the grain. Assemble dishes: Pile hot fries into bowls, top immediately with room-temperature cheese curds, ladle boiling hot oxtail gravy over the curds (to soften them), and arrange steak slices on top. Garnish with chives.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT1H30M", "passive_time": "PT3H30M", "total_time": "PT5H", "overnight_required": false, "yields": "4 generous servings", "yield_count": 4, "serving_size_g": 550}', '{"flags": [], "not_suitable_for": ["Vegetarian", "Vegan", "Gluten-Free"]}', '{"per_serving": {"calories": 1866.79, "protein_g": 151.82, "carbohydrates_g": 84.67, "fat_g": 98.07, "saturated_fat_g": 39.01, "trans_fat_g": 0.68, "monounsaturated_fat_g": 20.36, "polyunsaturated_fat_g": 3.62, "fiber_g": 6.21, "sugar_g": 10.64, "sodium_mg": 5266.55, "cholesterol_mg": 170.44, "potassium_mg": 4049.98, "calcium_mg": 222.76, "iron_mg": 13.55, "magnesium_mg": 297.79, "phosphorus_mg": 743.41, "zinc_mg": 17.35, "vitamin_a_mcg": 359.69, "vitamin_c_mg": 26.84, "vitamin_d_mcg": 0.26, "vitamin_e_mg": 0.69, "vitamin_k_mcg": 14.37, "vitamin_b6_mg": 1.31, "vitamin_b12_mcg": 1.55, "thiamin_mg": 0.53, "riboflavin_mg": 0.29, "niacin_mg": 6.2, "folate_mcg": 65.43, "water_g": 522.31, "alcohol_g": 5.81, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store components (fries, gravy, steak) separately to prevent sogginess.", "duration": "P3D"}, "freezer": {"notes": "Gravy freezes excellently. Do not freeze fries or assembled dish.", "duration": "P3M"}, "reheating": "Reheat gravy on stove. Reheat steak gently in low oven. Re-fry or air fry potatoes to crisp.", "does_not_keep": false}', '[{"name": "Dutch oven or heavy pot", "required": true, "alternative": null}, {"name": "Deep fryer or large heavy-bottomed pot", "required": true, "alternative": null}, {"name": "Cast iron skillet", "required": true, "alternative": "Heavy stainless steel pan"}, {"name": "Fine mesh strainer", "required": true, "alternative": null}, {"name": "Thermometer", "required": true, "alternative": "Instant-read thermometer"}, {"name": "Wire rack", "required": true, "alternative": null}]', '[{"symptom": "Fries are soggy or limp", "likely_cause": "Oil temperature dropped too much or potatoes were not dried properly before frying", "prevention": "Fry in small batches to maintain temp; ensure potatoes are bone-dry before the first fry", "fix": "Refry at 200\u00b0C for 1-2 minutes, but watch closely to prevent burning"}, {"symptom": "Gravy is too thin", "likely_cause": "Too much liquid or insufficient roux", "prevention": "Measure liquid ratio carefully; reduce liquid longer before adding roux", "fix": "Make a slurry of cornstarch and cold water, whisk into boiling gravy until thickened"}]', '["Temperature Contrast: The secret to a great poutine is the heat of the gravy melting the outside of the cold/room-temp curds while the center stays firm and squeaky.", "Browning: Do not rush the searing of the oxtail. That deep brown crust provides the foundational umami flavor for the entire gravy.", "Double Fry: The two-stage frying process is non-negotiable. The first low-temp fry cooks the inside; the second high-temp fry creates the glass-like crust.", "Oxtail Texture: Oxtail is rich in collagen. As it braises, this converts to gelatin, giving the gravy a luxurious, sticky mouthfeel that stock alone cannot achieve.", "Cheese Curds: If you cannot find fresh cheese curds, tear chunks of mozzarella, but know it won''t be authentic. Never use grated cheese\u2014it melts too quickly into a greasy mess."]', '"Poutine originated in rural Quebec, Canada, in the 1950s. While initially a humble truck-stop snack, it has evolved into a culinary icon. This version elevates the dish by incorporating the French technique of braising oxtail, marrying the rustic comfort of the original with the sophistication of a steakhouse dinner."', 1866.79);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('c6b5ae91-21b8-4aa8-b0b7-59b0a3692528', 'Classic Weeknight Spaghetti Bolognese', 'A robust and hearty meat sauce clinging to al dente spaghetti, featuring savory ground beef, sweet aromatic vegetables, and rich tomatoes balanced with Italian herbs. This streamlined version captures the essence of the slow-cooked Italian classic in a fraction of the time.', 'dinner', 'Italian', 'Easy', '["spaghetti bolognese", "pasta", "beef", "italian", "weeknight dinner", "comfort food"]', '[{"group_name": "Soffritto & Aromatics", "items": [{"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": "liquid", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "carrot", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx. 100g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "celery stalk", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx. 50g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx. 9g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Meat & Sauce", "items": [{"name": "ground beef", "quantity": 500, "unit": "g", "preparation": "raw", "notes": "15-20% fat content preferred for flavor", "substitutions": [], "ingredient_id": "696b2887-6464-4698-a80a-6860f8633185", "nutrition_source": "Aggregated Public Data"}, {"name": "tomato paste", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "41400e7f-7a06-42d2-a625-072c380d60b2", "nutrition_source": "Aggregated Public Data"}, {"name": "dry red wine", "quantity": 120, "unit": "ml", "preparation": null, "notes": "Cabernet or Merlot", "substitutions": ["beef stock", "water"], "ingredient_id": "0fc93141-8ba8-42e0-ac8b-b5af3851554c", "nutrition_source": "USDA FoodData Central"}, {"name": "canned crushed tomatoes", "quantity": 800, "unit": "g", "preparation": null, "notes": "high quality", "substitutions": [], "ingredient_id": "49a62ca7-db63-4d23-9f6f-2cf873fba8a3", "nutrition_source": "Aggregated Public Data"}, {"name": "dried oregano", "quantity": 5, "unit": "g", "preparation": null, "notes": "approx. 1 tsp", "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "dried bay leaf", "quantity": 1, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eab2ef3a-7a0e-4188-b746-645b795ada1e", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, start with 5g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Pasta & Finish", "items": [{"name": "dried spaghetti", "quantity": 400, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8f9d3063-4bf0-46dc-9f13-5f49cd92d47d", "nutrition_source": "Aggregated Public Data"}, {"name": "parmesan cheese", "quantity": null, "unit": null, "preparation": "grated", "notes": "for serving", "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh basil leaves", "quantity": null, "unit": null, "preparation": null, "notes": "for garnish", "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Finely dice the onion, carrot, and celery. Mince the garlic. Ensuring these vegetables are cut small helps them melt into the sauce.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat the olive oil in a large Dutch oven or deep skillet over medium heat. Add the onion, carrot, and celery. Saut\u00e9 for 6-8 minutes until the vegetables are softened and the onions are translucent.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT8M", "doneness_cues": {"visual": "Onions are translucent", "tactile": "Vegetables are soft"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Increase heat to medium-high. Add the ground beef and cook, breaking it up with a wooden spoon, until browned and no pink remains (internal temp 71\u00b0C/160\u00b0F+).", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT8M", "doneness_cues": {"visual": "Meat is fully browned", "tactile": "Meat is crumbly"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Stir in the tomato paste and minced garlic. Cook for 1-2 minutes until the tomato paste darkens slightly and the garlic is fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Paste turns brick red", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour in the red wine (if using) or stock to deglaze the pan, scraping up any browned bits from the bottom. Simmer for 2 minutes until the liquid reduces by half.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Add the crushed tomatoes, dried oregano, bay leaf, salt, and pepper. Stir to combine. Reduce heat to low, cover partially, and simmer for at least 20 minutes (up to 45 for deeper flavor), stirring occasionally.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT25M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "While the sauce simmers, bring a large pot of salted water to a boil. Add the spaghetti and cook according to package instructions until al dente.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Reserve 120ml (approx. 1/2 cup) of starchy pasta water, then drain the spaghetti. Remove the bay leaf from the sauce.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "assemble", "text": "Add the cooked spaghetti directly to the sauce skillet. Toss vigorously for 1-2 minutes over low heat, adding splashes of reserved pasta water if needed to help the sauce emulsify and cling to the noodles.", "structured": {"action": "MIX", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Serve immediately topped with freshly grated Parmesan cheese and torn fresh basil.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT35M", "total_time": "PT1H", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Nut-Free", "Egg-Free", "Soy-Free"], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 791.9, "protein_g": 43.25, "carbohydrates_g": 99.94, "fat_g": 22.87, "saturated_fat_g": 6, "trans_fat_g": null, "monounsaturated_fat_g": 5.64, "polyunsaturated_fat_g": 0.87, "fiber_g": 9.24, "sugar_g": 14.14, "sodium_mg": 989.51, "cholesterol_mg": 1.27, "potassium_mg": 1413.18, "calcium_mg": 162.96, "iron_mg": 7.15, "magnesium_mg": 110.23, "phosphorus_mg": 492.72, "zinc_mg": 6.98, "vitamin_a_mcg": 345.07, "vitamin_c_mg": 25.25, "vitamin_d_mcg": 0.01, "vitamin_e_mg": 1.54, "vitamin_k_mcg": 23.77, "vitamin_b6_mg": 0.14, "vitamin_b12_mcg": 0.02, "thiamin_mg": 0.05, "riboflavin_mg": 0.05, "niacin_mg": 0.42, "folate_mcg": 20.44, "water_g": 102.21, "alcohol_g": 2.79, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store sauce and pasta separately if possible to prevent pasta from becoming mushy.", "duration": "P3D"}, "freezer": {"notes": "Sauce freezes excellently; freeze without pasta for best results.", "duration": "P3M"}, "reheating": "Reheat sauce in a saucepan over medium heat; add a splash of water if too thick. Toss with fresh warm pasta.", "does_not_keep": false}', '[{"name": "Large Dutch oven or deep skillet", "required": true, "alternative": "Large saucepan"}, {"name": "Large pot", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": "Heat-resistant spatula"}]', '[{"symptom": "Sauce is too watery", "likely_cause": "Tomatoes released too much liquid or not simmered long enough", "prevention": "Simmer uncovered for the last 10 minutes", "fix": "Simmer vigorously for 5 more minutes before adding pasta"}, {"symptom": "Sauce tastes flat or acidic", "likely_cause": "Tomatoes are highly acidic", "prevention": "Use high-quality canned tomatoes", "fix": "Stir in a pinch of sugar or a small splash of milk to neutralize acidity; add more salt"}]', '["Finishing the pasta IN the sauce is the secret to restaurant-quality texture. Never put plain noodles on a plate and spoon sauce on top; the flavors won''t marry.", "If you have a Parmesan cheese rind, throw it into the sauce while it simmers for a massive umami boost. Remove before serving.", "For a richer sauce, add a splash of milk (approx. 60ml) after the wine reduces and before adding the tomatoes\u2014this is a traditional technique in Bologna to tenderize the meat.", "Don''t rinse your pasta after draining! The starch on the surface is essential for helping the sauce stick to the noodles."]', '"While ''Spaghetti Bolognese'' is a beloved global staple, it is an adaptation of the Italian ''Rag\u00f9 alla Bolognese'' from Bologna. The authentic dish is typically served with fresh tagliatelle rather than dried spaghetti and relies on a long, slow cook with less tomato and more milk/wine. This recipe bridges the gap, offering the comforting weeknight style popular in home kitchens worldwide."', 791.9);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('c8817a44-0dd1-4908-9be8-b3a2a2800bbf', 'Caramelized Onion and Corn Savory Bread Pudding', 'A sophisticated autumn casserole featuring sweet caramelized onions and tender corn kernels suspended in a rich, savory egg custard absorbed by crusty French bread. The result is a texturally complex dish with a golden, crisp top and a creamy, souffle-like interior.', 'side dish', 'American', 'Intermediate', '["casseroles", "bread pudding", "corn", "french bread", "onion", "side dish", "fall", "vegetarian", "thanksgiving", "comfort food"]', '[{"group_name": "Aromatics & Vegetables", "items": [{"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": "divided", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onions", "quantity": 3, "unit": null, "preparation": "thinly sliced", "notes": "approx 450g total", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "corn kernels", "quantity": 300, "unit": "g", "preparation": "fresh or frozen (thawed)", "notes": "drain if using canned", "substitutions": [], "ingredient_id": "46ca2aab-cb23-4397-9711-528c234b2cf8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme leaves", "quantity": 5, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Bread Base", "items": [{"name": "french bread or baguette", "quantity": 450, "unit": "g", "preparation": "cut into 2.5cm cubes", "notes": "stale or day-old works best", "substitutions": [], "ingredient_id": "ca5a72ee-64da-4cfb-af75-23bf0dae354a", "nutrition_source": "Aggregated Public Data"}, {"name": "gruy\u00e8re cheese", "quantity": 150, "unit": "g", "preparation": "shredded", "notes": null, "substitutions": [], "ingredient_id": "321085d2-bb82-45e1-8ae3-5a2ef5cea47f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Custard", "items": [{"name": "large eggs", "quantity": 5, "unit": null, "preparation": null, "notes": "approx 250g total without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 240, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 240, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the bread cubes on a baking sheet. If the bread is fresh, dry it out in a 150\u00b0C (300\u00b0F) oven for 10-15 minutes until firm but not browned. Set aside to cool.", "structured": {"action": "TOAST", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Melt 30g of butter in a large skillet over medium-low heat. Add the sliced onions and a pinch of salt. Cook slowly, stirring occasionally, until deep golden brown and caramelized.", "structured": {"action": "CARAMELIZE", "temperature": null, "duration": "PT25M", "doneness_cues": {"visual": "Deep golden brown color", "tactile": "Soft and jammy texture"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Increase heat to medium. Add the corn, minced garlic, and thyme to the onions. Saut\u00e9 for 3-4 minutes until the corn is tender and garlic is fragrant. Remove from heat.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In a large bowl, whisk together the eggs, heavy cream, milk, Dijon mustard, remaining salt, and pepper until completely smooth.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Grease a 9x13 inch baking dish with the remaining butter. Toss the bread cubes, onion-corn mixture, and two-thirds of the Gruy\u00e8re cheese in the prepared dish.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Pour the custard evenly over the bread mixture. Press the bread down gently with a spatula to ensure it absorbs the liquid. Let stand at room temperature for at least 30 minutes.", "structured": {"action": "REST", "temperature": null, "duration": "PT30M", "doneness_cues": {"visual": "Bread looks saturated and swollen", "tactile": null}}, "tips": ["Do not skip this step; it prevents dry pockets in the pudding."]}, {"step_number": 7, "phase": "cook", "text": "Preheat oven to 175\u00b0C (350\u00b0F). Top the pudding with the remaining cheese. Bake for 45-55 minutes until puffy, golden brown, and the center is set (internal temperature reaches 74\u00b0C/165\u00b0F).", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT50M", "doneness_cues": {"visual": "Puffed and golden brown", "tactile": "Center springs back when touched"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from the oven and let rest for 10 minutes before serving. This allows the custard to set firmly for cleaner slicing.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT1H25M", "total_time": "PT2H10M", "overnight_required": false, "yields": "8 servings", "yield_count": 8, "serving_size_g": 220}', '{"flags": ["Vegetarian", "Soy-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": ["Vegans (contains dairy, eggs)", "Gluten Intolerant"]}', '{"per_serving": {"calories": 494.67, "protein_g": 18.25, "carbohydrates_g": 46.84, "fat_g": 26.61, "saturated_fat_g": 14.97, "trans_fat_g": 0.39, "monounsaturated_fat_g": 7.48, "polyunsaturated_fat_g": 1.83, "fiber_g": 2.8, "sugar_g": 7.91, "sodium_mg": 762.58, "cholesterol_mg": 185.87, "potassium_mg": 328.43, "calcium_mg": 284.86, "iron_mg": 1.15, "magnesium_mg": 37.12, "phosphorus_mg": 272.88, "zinc_mg": 1.63, "vitamin_a_mcg": 281.32, "vitamin_c_mg": 8.48, "vitamin_d_mcg": 1.61, "vitamin_e_mg": 0.85, "vitamin_k_mcg": 2.82, "vitamin_b6_mg": 0.22, "vitamin_b12_mcg": 0.77, "thiamin_mg": 0.13, "riboflavin_mg": 0.35, "niacin_mg": 0.85, "folate_mcg": 46.25, "water_g": 154.85, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Cover tightly with foil or plastic wrap.", "duration": "P3D"}, "freezer": {"notes": "Freeze in individual portions; texture may become slightly softer upon thawing.", "duration": "P2M"}, "reheating": "Reheat in a 160\u00b0C (325\u00b0F) oven covered with foil for 15-20 minutes until warmed through.", "does_not_keep": false}', '[{"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": null}, {"name": "9x13 inch baking dish (approx 3 liter capacity)", "required": true, "alternative": "Large oval gratin dish"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Serrated knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Bread pudding is soggy or watery at the bottom", "likely_cause": "Bread was too fresh or didn''t soak up the custard adequately", "prevention": "Ensure bread is thoroughly dried/stale before mixing and allow the full 30-minute soak time", "fix": "Bake for an additional 10-15 minutes, covering the top loosely with foil if it browns too quickly"}]', '["For a richer depth, use Brioche or Challah instead of French bread, though reduce the salt slightly as these breads are richer.", "Patience with the onions is key; high heat will burn them before the sugars develop. Low and slow creates the necessary sweetness to contrast the savory custard.", "If preparing for Thanksgiving, the onion and corn mixture can be made a day in advance and refrigerated.", "Adding a splash of dry white wine to deglaze the pan after cooking the onions adds a fantastic layer of acidity to cut the richness."]', '"Savory bread puddings, often called stratas when containing a high egg ratio, are a staple of American comfort food, evolving from the European tradition of using stale bread to avoid waste. This specific variation borrows from Southern and Creole flavor profiles, utilizing corn and slow-cooked aromatics common in Thanksgiving spreads."', 494.67);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('c9ab0e8b-b20c-496c-afeb-1d1beac4b8af', 'Steak Frites with Triple-Cooked Chips', 'The quintessential bistro classic featuring a thick-cut, crusty sirloin steak served alongside scientifically perfected chips—glass-like crunch on the outside, fluffy cloud-like interior.', 'dinner', 'French Bistro', 'Advanced', '["steak", "chips", "sirloin", "grill", "date night", "bistro", "high protein"]', '[{"group_name": "Steak", "items": [{"name": "sirloin steaks", "quantity": 2, "unit": null, "preparation": "room temperature", "notes": "approx. 250g-300g each, 4cm thick", "substitutions": [], "ingredient_id": "6ab398fc-b106-4c49-a2c7-0c643f644581", "nutrition_source": "USDA FoodData Central"}, {"name": "grapeseed oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "or other high smoke point oil", "substitutions": [], "ingredient_id": "00f43166-1b77-4e77-9e30-e912a59d118a", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 40, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": "crushed", "notes": null, "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 3, "unit": null, "preparation": "sprigs", "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "flaky sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "generous amount to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Triple-Cooked Chips", "items": [{"name": "starchy potatoes", "quantity": 800, "unit": "g", "preparation": "peeled and cut into 2cm batons", "notes": "Maris Piper, Russet, or Sebago", "substitutions": [], "ingredient_id": "4920385c-ae78-4023-8318-c5dfe051fecc", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral frying oil", "quantity": 2000, "unit": "ml", "preparation": null, "notes": "peanut or vegetable oil for deep frying", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}, {"name": "white vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": "prevents disintegration during boiling", "substitutions": [], "ingredient_id": "8d5bf07e-89a1-47ee-a6b7-d9cb03e96d64", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place cut potatoes in a pot, cover with cold water, add vinegar and a pinch of salt. Bring to a boil and simmer until the edges are breaking apart but the center remains intact (approx. 20-25 mins).", "structured": {"action": "BOIL", "temperature": null, "duration": "PT25M", "doneness_cues": {"visual": "Edges looking friable/rough", "tactile": "Soft but not mush"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Gently drain potatoes and arrange on a wire rack. Allow to steam dry and cool completely, preferably in the refrigerator for at least 1 hour to remove surface moisture.", "structured": {"action": "COOL", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat oil in a deep pot to 130\u00b0C/266\u00b0F. Fry potatoes in batches until a pale crust forms (about 5-7 minutes). They should not brown yet. Remove and drain on rack. Cool for 30 minutes.", "structured": {"action": "FRY", "temperature": {"celsius": 130, "fahrenheit": 266}, "duration": "PT7M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "While chips cool, pat steaks bone-dry with paper towels. Season heavily with salt on all sides. Heat cast iron skillet until smoking hot.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add oil to the smoking pan. Sear steaks, flipping every minute to build an even crust. Continue until internal temperature reaches 50\u00b0C/122\u00b0F for medium-rare.", "structured": {"action": "SEAR", "temperature": {"celsius": 50, "fahrenheit": 122}, "duration": null, "doneness_cues": {"visual": "Deep dark brown crust", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "In the last minute of cooking, add butter, garlic, and thyme. Baste the steak foaming butter over the meat continuously.", "structured": {"action": "BASTE", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove steaks to a warm plate and rest for 10 minutes. While resting, increase oil heat to 190\u00b0C/375\u00b0F.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Fry the cooled chips a second time at 190\u00b0C/375\u00b0F until deep golden brown and extremely crisp (approx 3-4 minutes). Drain, season immediately with salt, and serve with the steak.", "structured": {"action": "FRY", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT4M", "doneness_cues": {"visual": "Deep golden brown", "tactile": "Hard shell sound when tapped"}}, "tips": []}]', '{"active_time": "PT50M", "passive_time": "PT2H", "total_time": "PT2H50M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 450}', '{"flags": ["Gluten-Free", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 941.34, "protein_g": 78.79, "carbohydrates_g": 64.75, "fat_g": 42.13, "saturated_fat_g": 15.25, "trans_fat_g": null, "monounsaturated_fat_g": 7.1, "polyunsaturated_fat_g": 11.27, "fiber_g": 10.04, "sugar_g": 4.65, "sodium_mg": 1773.26, "cholesterol_mg": 43, "potassium_mg": 2624.29, "calcium_mg": 128.32, "iron_mg": 7.01, "magnesium_mg": 152.76, "phosphorus_mg": 831.12, "zinc_mg": 12.28, "vitamin_a_mcg": 142.75, "vitamin_c_mg": 41.65, "vitamin_d_mcg": null, "vitamin_e_mg": 4.83, "vitamin_k_mcg": 7.87, "vitamin_b6_mg": 0.86, "vitamin_b12_mcg": 0.04, "thiamin_mg": 0.29, "riboflavin_mg": 0.14, "niacin_mg": 4.37, "folate_mcg": 73.85, "water_g": 333.63, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Steak stores well; chips lose texture immediately.", "duration": "P2D"}, "freezer": {"notes": "Do not freeze cooked chips.", "duration": null}, "reheating": "Reheat steak gently in pan; chips must be refried or air-fried to restore crunch.", "does_not_keep": false}', '[{"name": "Heavy-bottomed cast iron skillet or grill pan", "required": true, "alternative": null}, {"name": "Deep heavy pot or Dutch oven", "required": true, "alternative": "Deep fryer"}, {"name": "Digital instant-read thermometer", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}, {"name": "Spider strainer or slotted spoon", "required": true, "alternative": null}]', '[{"symptom": "Chips are soggy or greasy", "likely_cause": "Oil temperature dropped too low when adding potatoes", "prevention": "Fry in smaller batches and ensure thermometer reads 190\u00b0C/375\u00b0F before adding chips", "fix": "Refry at correct high temperature briefly to drive out oil"}, {"symptom": "Steak has a grey band inside the crust", "likely_cause": "Steak was too cold when cooking or not flipped often enough", "prevention": "Temper steak and flip every 60 seconds", "fix": "Cannot be fixed"}]', '["The ''micro-cracks'' created during the vigorous boil are essential; they trap oil during the final fry to create that glass-like crunch.", "Flipping the steak every minute (the ''constant flip'' method) cooks the meat more evenly and develops a better crust than flipping once.", "Adding vinegar to the potato water prevents the potato from disintegrating completely before the starch is gelatinized.", "Always salt chips immediately after the final fry; the hot surface oil helps the salt adhere."]', '"While ''Steak Frites'' is the national dish of bistro dining in France, the triple-cooked chip method is a modern British gastronomic innovation attributed to Heston Blumenthal, elevating the humble potato to a technical masterpiece."', 941.34);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ca9d39cf-48e8-4ab4-b597-b38f72c84fac', 'Zero-Waste Asparagus End & Herb Vinaigrette', 'A vibrant, emerald-green emulsion that transforms discarded woody asparagus trimmings into a silky, herbaceous dressing. It offers a fresh vegetable sweetness balanced by bright lemon acidity and the peppery bite of fresh herbs.', 'sauce', 'Modern', 'Easy', '["asparagus", "herbs", "easy", "quick", "weeknight", "side dish", "spring", "vegetarian", "zero waste", "sustainable"]', '[{"group_name": "Asparagus Base", "items": [{"name": "asparagus woody ends", "quantity": 200, "unit": "g", "preparation": "washed", "notes": "Trimmings from about 2 bunches", "substitutions": [], "ingredient_id": "8a2a9426-3755-4553-953a-fd9cf42cef90", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 500, "unit": "ml", "preparation": null, "notes": "For boiling", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": null}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "For boiling water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vinaigrette Emulsion", "items": [{"name": "extra virgin olive oil", "quantity": 80, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh lemon juice", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "leaves and tender stems", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh chives", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}, {"name": "dijon mustard", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": null, "notes": "small clove, approx 3g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Bring a small saucepan of salted water to a boil. Prepare an ice water bath in a separate bowl.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add the tough asparagus ends to the boiling water. Cook until very tender, easily pierced with a fork.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": null, "tactile": "Very soft and yielding to a fork"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Immediately drain the asparagus ends and transfer them into the ice bath to stop cooking and set the bright green color.", "structured": {"action": "BLANCH", "temperature": {"celsius": 0, "fahrenheit": 32}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Drain the cooled asparagus well. Chop roughly.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "In a high-speed blender, combine the boiled asparagus ends, olive oil, lemon juice, parsley, chives, Dijon mustard, and garlic. Blend on high until completely smooth and emulsified.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Bright green and creamy", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Pass the mixture through a fine mesh sieve into a bowl or jar, pressing with a spatula to extract the liquid while leaving behind any remaining fibrous woody pulp. Season with salt and pepper to taste.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Silky smooth texture"}}, "tips": ["Do not skip straining; even powerful blenders may leave fibrous strings from the woody ends."]}]', '{"active_time": "PT15M", "passive_time": "PT5M", "total_time": "PT20M", "overnight_required": false, "yields": "250ml", "yield_count": 8, "serving_size_g": 30}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Paleo"], "not_suitable_for": []}', '{"per_serving": {"calories": 96.15, "protein_g": 0.68, "carbohydrates_g": 1.58, "fat_g": 10.08, "saturated_fat_g": 1.39, "trans_fat_g": null, "monounsaturated_fat_g": 7.31, "polyunsaturated_fat_g": 1.07, "fiber_g": 0.65, "sugar_g": 0.6, "sodium_mg": 348.14, "cholesterol_mg": null, "potassium_mg": 67.34, "calcium_mg": 10.76, "iron_mg": 0.72, "magnesium_mg": 4.93, "phosphorus_mg": 15.16, "zinc_mg": 0.16, "vitamin_a_mcg": 18.88, "vitamin_c_mg": 5, "vitamin_d_mcg": null, "vitamin_e_mg": 1.74, "vitamin_k_mcg": 37.13, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": null, "thiamin_mg": 0.04, "riboflavin_mg": 0.04, "niacin_mg": 0.27, "folate_mcg": 15.68, "water_g": 28.1, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Color may darken slightly over time due to oxidation.", "duration": "P3D"}, "freezer": {"notes": "Freeze in ice cube trays for quick portions.", "duration": "P1M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Small saucepan", "required": true, "alternative": null}, {"name": "High-speed blender", "required": true, "alternative": "Food processor"}, {"name": "Fine mesh sieve", "required": true, "alternative": "Cheesecloth"}, {"name": "Bowl", "required": true, "alternative": "Large container for ice bath"}]', '[{"symptom": "Vinaigrette is stringy or fibrous", "likely_cause": "The woody ends were not boiled long enough or the mixture wasn''t strained", "prevention": "Boil ends until mushy and always pass through a fine sieve", "fix": "Pass through a finer sieve or cheesecloth"}, {"symptom": "Sauce color is dull or brown", "likely_cause": "Asparagus was overcooked without shocking or the herbs oxidized", "prevention": "Use an ice bath immediately after boiling; blend herbs at the last second", "fix": "Blend in a handful of fresh raw spinach to restore green color"}]', '["This recipe embraces ''root-to-stem'' cooking. Use the tender tops of the asparagus for your main dish and this sauce to dress them.", "If the vinaigrette is too thick, thin it out with a teaspoon of cold water or more lemon juice.", "The flavor improves after sitting for 15 minutes as the garlic and herbs meld.", "For a creamier, vegan-mayo consistency, drizzle the oil in slowly while the blender is running rather than dumping it all in at once."]', '"This recipe reflects the modern sustainable cooking movement, specifically the ''root-to-stem'' philosophy which seeks to minimize food waste by utilizing edible but often discarded vegetable parts. By treating the fibrous asparagus ends with proper technique (blanching and pureeing), a tough byproduct is transformed into a refined sauce."', 96.15);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('cb115123-acfa-4565-8b04-79e83264c98c', 'Midnight Speckle Black Pepper Ice Cream', 'A sophisticated frozen dessert where the floral, piney aroma of toasted black peppercorns cuts through rich, sweet cream. The heat is a slow, gentle finish rather than a sharp bite, balanced by a touch of honey for texture.', 'dessert', 'French', 'Intermediate', '["ice creams and sorbets", "black peppercorn", "heavy cream", "milk", "dessert", "gluten-free", "frozen", "custard"]', '[{"group_name": "Aromatics", "items": [{"name": "whole black peppercorns", "quantity": 10, "unit": "g", "preparation": "whole", "notes": "Preferably Tellicherry for fruitier notes", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla bean", "quantity": 0.5, "unit": null, "preparation": "split and scraped", "notes": "Or 5ml vanilla bean paste", "substitutions": [], "ingredient_id": "fa27169b-bdb5-4f0c-abab-0b67a3e924e6", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Custard Base", "items": [{"name": "heavy cream", "quantity": 480, "unit": "ml", "preparation": "cold", "notes": "Min 35% fat", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 240, "unit": "ml", "preparation": "cold", "notes": null, "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "egg yolks", "quantity": 6, "unit": null, "preparation": "room temperature", "notes": "approx 110g", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 50, "unit": "g", "preparation": null, "notes": "Mild variety like clover or acacia", "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "Large pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Toast the whole peppercorns in a dry saucepan over medium heat until fragrant, about 2-3 minutes. Shake the pan constantly to prevent burning.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Slightly darkened", "tactile": "Aromatic"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Roughly crack the toasted peppercorns using a mortar and pestle. Do not grind them into a powder; you want large pieces to infuse flavor without making the cream gritty.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": {"visual": "Coarse rubble", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In the saucepan, combine the heavy cream, milk, honey, cracked peppercorns, vanilla (pod and seeds), and salt. Bring to a bare simmer over medium heat (approx 85\u00b0C/185\u00b0F), then remove from heat, cover, and let steep for 30 minutes.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "In a separate bowl, whisk the egg yolks and sugar until pale and slightly thickened. Reheat the cream mixture until it just begins to steam again.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": {"visual": "Pale yellow ribbons", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Temper the yolks by slowly pouring about one-third of the hot cream mixture into the eggs while whisking constantly. Pour the tempered egg mixture back into the saucepan with the remaining cream.", "structured": {"action": "TEMPER", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Cook over low heat, stirring constantly with a spatula or wooden spoon, until the custard thickens enough to coat the back of the spoon (nappe) and reaches 82\u00b0C/180\u00b0F. Do not boil.", "structured": {"action": "COOK", "temperature": {"celsius": 82, "fahrenheit": 180}, "duration": null, "doneness_cues": {"visual": "Coats back of spoon", "tactile": "Thickened texture"}}, "tips": []}, {"step_number": 7, "phase": "prep", "text": "Immediately strain the custard through a fine mesh sieve into a clean bowl to remove the peppercorns and vanilla pod. Discard the solids.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Place the bowl in an ice bath to cool down quickly, stirring occasionally. Once cool, cover with plastic wrap touching the surface and refrigerate for at least 4 hours, preferably overnight.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT4H", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Churn the chilled custard in your ice cream maker according to the manufacturer''s instructions until it reaches soft-serve consistency.", "structured": {"action": "CHURN", "temperature": null, "duration": "PT25M", "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Transfer to a freezer-safe container and freeze for at least 4 hours to firm up before serving.", "structured": {"action": "FREEZE", "temperature": null, "duration": "PT4H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT8H", "total_time": "PT8H45M", "overnight_required": true, "yields": "1 liter", "yield_count": 8, "serving_size_g": 120}', '{"flags": ["Vegetarian", "Gluten-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Infants under 12 months (honey)"]}', '{"per_serving": {"calories": 338.17, "protein_g": 4.98, "carbohydrates_g": 22.14, "fat_g": 26.32, "saturated_fat_g": 15.69, "trans_fat_g": 0.74, "monounsaturated_fat_g": 7.32, "polyunsaturated_fat_g": 1.59, "fiber_g": 0.33, "sugar_g": 20.96, "sodium_mg": 84.86, "cholesterol_mg": 219.3, "potassium_mg": 131.72, "calcium_mg": 97.31, "iron_mg": 0.6, "magnesium_mg": 10.15, "phosphorus_mg": 115.85, "zinc_mg": 0.6, "vitamin_a_mcg": 313.13, "vitamin_c_mg": 0.39, "vitamin_d_mcg": 2.09, "vitamin_e_mg": 0.94, "vitamin_k_mcg": 4.16, "vitamin_b6_mg": 0.09, "vitamin_b12_mcg": 0.5, "thiamin_mg": 0.05, "riboflavin_mg": 0.25, "niacin_mg": 0.09, "folate_mcg": 24.31, "water_g": 69.47, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"duration": null}, "freezer": {"notes": "Best consumed within 1 week for optimal texture; press parchment paper against surface to prevent ice crystals.", "duration": "P2W"}, "reheating": null, "does_not_keep": false}', '[{"name": "Heavy-bottomed saucepan", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Instant-read thermometer", "required": true, "alternative": null}, {"name": "Fine mesh sieve", "required": true, "alternative": null}, {"name": "Ice cream maker", "required": true, "alternative": "Standard freezer (for no-churn method, though texture will differ)"}, {"name": "Heatproof bowls", "required": true, "alternative": null}, {"name": "Mortar and pestle", "required": true, "alternative": "Heavy pan bottom on cutting board"}]', '[{"symptom": "Custard has small lumps of cooked egg", "likely_cause": "Heat was too high or mixture wasn''t stirred enough during thickening", "prevention": "Keep heat low and stir constantly; use a thermometer", "fix": "Strain through a very fine sieve immediately; use an immersion blender to smooth out texture"}]', '["Toasting the peppercorns is non-negotiable; it removes the raw bite and brings out complex floral and citrusy aromas essential for a dessert.", "The addition of honey acts as an invert sugar, which helps prevent the ice cream from freezing into a rock-hard block, keeping it scoopable.", "This flavor pairs exceptionally well with fresh strawberries, roasted figs, or as a garnish atop a warm apple tart.", "For a more intense spice, you can leave the cracked peppercorns in the custard while it chills overnight, then strain right before churning."]', '"While savory ice creams are often considered modern avant-garde creations, the use of spices like pepper in sweets dates back to medieval European banquets and ancient Roman cuisine where spices showcased wealth. This recipe borrows the French ''Cr\u00e8me Anglaise'' technique to deliver a flavor profile that bridges the gap between the savory and pastry worlds."', 338.17);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('cb2294bf-b9b8-41f8-91ea-caf0e27b0e24', 'Seared Scallops with Sweet Corn & Basil Linguine', 'Sweet, golden-seared sea scallops sit atop al dente linguine tossed in a naturally creamy, emulsified corn sauce. The sweetness of the corn is balanced by savory shallots, a splash of white wine, and a bright finish of fresh lemon and basil.', 'dinner', 'Modern Italian', 'Intermediate', '["pasta", "seafood", "corn", "scallop", "dinner", "weeknight", "main course", "summer"]', '[{"group_name": "Scallops", "items": [{"name": "large sea scallops", "quantity": 300, "unit": "g", "preparation": "dry", "notes": "side muscle removed; approx 8-10 scallops", "substitutions": [], "ingredient_id": "8fb59e3e-09e4-459e-b1eb-74db57e57b64", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 15, "unit": "ml", "preparation": "or grapeseed oil", "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Corn Sauce & Pasta", "items": [{"name": "linguine", "quantity": 250, "unit": "g", "preparation": "dried", "notes": null, "substitutions": [], "ingredient_id": "34acf633-f24c-4fb4-87cd-bd487c2346f7", "nutrition_source": "Aggregated Public Data"}, {"name": "sweet corn kernels", "quantity": 300, "unit": "g", "preparation": "fresh or frozen", "notes": "divided use; about 2-3 ears", "substitutions": [], "ingredient_id": "46ca2aab-cb23-4397-9711-528c234b2cf8", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 30g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 60, "unit": "ml", "preparation": "Sauvignon Blanc or Pinot Grigio", "notes": null, "substitutions": [], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh basil leaves", "quantity": 10, "unit": "g", "preparation": "chiffonade", "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "red pepper flakes", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat scallops extremely dry with paper towels. Season generously with salt on both sides. If using fresh corn, cut kernels from the cob and scrape the cobs with the back of a knife to release the corn milk; reserve milk with kernels.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Divide the corn kernels. Take half of the corn (150g) and blend it with 60ml of water until completely smooth. Set this puree aside\u2014it will act as the thickener for the sauce.", "structured": {"action": "BLEND", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Bring a large pot of salted water to a boil. Add linguine and cook for 2 minutes less than the package instructions (it will finish cooking in the sauce). Reserve 250ml of starchy pasta water before draining.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "While pasta boils, heat oil in a stainless steel skillet over high heat until shimmering. Place scallops in the pan without crowding. Sear undisturbed for 2 minutes until a golden crust forms. Flip and sear for 1 minute on the other side. Remove scallops to a plate and set aside.", "structured": {"action": "SEAR", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown crust", "tactile": "Firm edges, slightly soft center"}}, "tips": ["Do not touch the scallops once placed in the pan until it is time to flip, or the crust will not form.", "Internal temperature should reach 52\u00b0C/125\u00b0F for medium-rare/medium texture."]}, {"step_number": 5, "phase": "cook", "text": "Reduce heat to medium. In the same skillet (don''t wipe it out), add the remaining whole corn kernels, shallot, garlic, and red pepper flakes. Saut\u00e9 for 2-3 minutes until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Deglaze the pan with white wine, scraping up any browned bits from the scallops. Simmer for 1 minute to reduce by half. Stir in the corn puree and 120ml of the reserved pasta water. Bring to a simmer.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Add the drained pasta to the skillet. Toss vigorously with tongs for 1-2 minutes. The sauce should thicken and cling to the noodles. If too thick, add more pasta water. Turn off the heat and stir in the cold butter, lemon juice, and half the basil until emulsified and glossy.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Sauce is glossy and coats the back of a spoon", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Nestle the seared scallops back into the pasta to warm through slightly. Garnish with remaining basil and serve immediately.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT0M", "total_time": "PT35M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 450}', '{"flags": ["Pescatarian", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 971.31, "protein_g": 39.62, "carbohydrates_g": 127.46, "fat_g": 30.49, "saturated_fat_g": 13.17, "trans_fat_g": 0.02, "monounsaturated_fat_g": 6.01, "polyunsaturated_fat_g": 1.68, "fiber_g": 8.1, "sugar_g": 14.07, "sodium_mg": 1010.46, "cholesterol_mg": 84.38, "potassium_mg": 978.26, "calcium_mg": 65.61, "iron_mg": 4.43, "magnesium_mg": 97.27, "phosphorus_mg": 873.36, "zinc_mg": 2.23, "vitamin_a_mcg": 192.5, "vitamin_c_mg": 16.52, "vitamin_d_mcg": null, "vitamin_e_mg": 0.83, "vitamin_k_mcg": 23.35, "vitamin_b6_mg": 0.35, "vitamin_b12_mcg": 2.15, "thiamin_mg": 0.26, "riboflavin_mg": 0.13, "niacin_mg": 3.86, "folate_mcg": 98.3, "water_g": 266.7, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Scallops are best eaten immediately; texture degrades upon reheating.", "duration": "P2D"}, "freezer": {"notes": "Do not freeze.", "duration": null}, "reheating": "Gently warm in a pan with a splash of water over low heat. Do not microwave scallops.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": "Dutch oven"}, {"name": "Stainless steel skillet or cast iron pan", "required": true, "alternative": "Non-stick skillet (will yield less sear)"}, {"name": "Blender or food processor", "required": true, "alternative": "Immersion blender"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}]', '[{"symptom": "Scallops did not get a crust", "likely_cause": "Scallops were too wet or pan was not hot enough", "prevention": "Ensure scallops are ''dry'' (no chemical additives) and pat thoroughly with paper towels before seasoning.", "fix": "Remove from pan immediately to avoid overcooking; they will still taste good without the crust."}, {"symptom": "Sauce is clumpy or separated", "likely_cause": "Pan was too hot when butter was added, or not enough starch", "prevention": "Turn off heat completely before mounting with cold butter.", "fix": "Add a splash of cold water and shake the pan vigorously to re-emulsify."}]', '["Look for ''dry'' scallops at the fishmonger. ''Wet'' scallops are treated with sodium tripolyphosphate, which causes them to release moisture during cooking and inhibits searing.", "Using half pureed corn and half whole kernels provides a creamy sauce texture without needing heavy cream, keeping the dish light for summer.", "The starch in the pasta water is the binding agent for this sauce. Do not skip reserving the water, and ensure the water is well-salted before boiling the pasta."]', '"This dish bridges Italian pasta techniques with New England coastal ingredients. While traditional Italian cuisine rarely pairs cheese with seafood, using corn puree and butter to create creaminess is a modern technique that highlights the natural sweetness of summer produce."', 971.31);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('cb557aef-fa62-4aff-8a2d-a142e7365f87', 'Spaghetti al Tonno e Olive', 'A vibrant, savory pantry staple featuring al dente spaghetti tossed in a quick tomato-based sauce with oil-packed tuna, briny Kalamata olives, and zesty capers. The dish balances umami depth with fresh herb brightness.', 'dinner', 'Italian', 'Easy', '["pasta", "tuna", "olives", "quick", "easy", "italian", "pantry-meal", "weeknight"]', '[{"group_name": "Pasta", "items": [{"name": "spaghetti", "quantity": 400, "unit": "g", "preparation": "dried", "notes": "Bronze-die cut preferred for sauce adherence", "substitutions": ["linguine", "penne", "fusilli"], "ingredient_id": "931f2cf7-c04e-4814-a866-1c20f809d475", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 4000, "unit": "ml", "preparation": null, "notes": "For boiling", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt", "quantity": 25, "unit": "g", "preparation": null, "notes": "For pasta water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sauce", "items": [{"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": "Divided use", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "thinly sliced", "notes": "approx. 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "chili flakes", "quantity": 2, "unit": "g", "preparation": null, "notes": "Adjust to taste", "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "canned cherry tomatoes", "quantity": 400, "unit": "g", "preparation": "with juices", "notes": "Or high-quality crushed tomatoes", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "tuna in olive oil", "quantity": 300, "unit": "g", "preparation": "drained", "notes": "Ideally high-quality jarred tuna or ventresca", "substitutions": ["canned salmon"], "ingredient_id": "f926c937-a447-44e6-bc30-a71c55811250", "nutrition_source": "USDA FoodData Central"}, {"name": "kalamata olives", "quantity": 80, "unit": "g", "preparation": "pitted and halved", "notes": null, "substitutions": ["black gaeta olives", "green olives"], "ingredient_id": "98021e35-139a-43ad-abbe-a49f958ea06f", "nutrition_source": "Aggregated Public Data"}, {"name": "capers", "quantity": 30, "unit": "g", "preparation": "rinsed", "notes": null, "substitutions": [], "ingredient_id": "e7301d2c-b906-4ef8-917e-787be0b25880", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": null, "notes": "Zest of 1 lemon, approx 3g", "substitutions": [], "ingredient_id": "03fb65be-9b62-44e7-a121-694de64cdec0", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Bring a large stockpot of water to a rolling boil. While heating, slice the garlic, halve the olives, and chop the parsley.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Once boiling, add the salt and the spaghetti. Cook according to package directions, but subtract 2 minutes from the recommended cooking time to ensure it is very al dente (it will finish cooking in the sauce).", "structured": {"action": "BOIL", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": null, "tactile": "Firm center, pliable exterior"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "While pasta cooks, heat 30ml of olive oil in a large skillet over medium heat. Add sliced garlic and chili flakes. Saut\u00e9 gently until garlic is pale gold and fragrant, being careful not to burn it.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT2M", "doneness_cues": {"visual": "Garlic is pale gold", "tactile": "Aromatic"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the canned tomatoes (and their juices) and capers to the skillet. Increase heat to medium-high and simmer briskly to reduce the liquid slightly while crushing the tomatoes with the back of a spoon.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Sauce has thickened slightly", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Reduce heat to low. Stir in the drained tuna and olives. Break the tuna into large chunks but do not shred it completely. Warm through gently for 1 minute to preserve the tuna''s texture.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Reserve 120ml (approx half a cup) of starchy pasta water. Drain the pasta and immediately transfer it directly into the skillet with the sauce.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Toss the pasta vigorously in the sauce over medium heat, adding reserved pasta water a splash at a time until a glossy emulsion coats the noodles. Stir in half the parsley and the lemon zest.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Sauce clings to pasta, no watery pool at bottom", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from heat. Drizzle with the remaining 15ml of fresh olive oil and garnish with the remaining parsley before serving immediately.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT0M", "total_time": "PT15M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Pescatarian", "Dairy-Free", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 708.37, "protein_g": 36.21, "carbohydrates_g": 80, "fat_g": 25.05, "saturated_fat_g": 2.77, "trans_fat_g": null, "monounsaturated_fat_g": 10.46, "polyunsaturated_fat_g": 3.42, "fiber_g": 6, "sugar_g": 6.62, "sodium_mg": 2992.61, "cholesterol_mg": 13.5, "potassium_mg": 650.13, "calcium_mg": 77.03, "iron_mg": 4.01, "magnesium_mg": 50.46, "phosphorus_mg": 439.41, "zinc_mg": 0.98, "vitamin_a_mcg": 23.71, "vitamin_c_mg": 20.19, "vitamin_d_mcg": null, "vitamin_e_mg": 1.91, "vitamin_k_mcg": 70.71, "vitamin_b6_mg": 0.14, "vitamin_b12_mcg": 1.65, "thiamin_mg": 0.05, "riboflavin_mg": 0.12, "niacin_mg": 9.49, "folate_mcg": 11.43, "water_g": 1056.69, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Pasta may absorb sauce and soften; reheat with a splash of water.", "duration": "P2D"}, "freezer": {"notes": "Not recommended; texture of pasta and tuna degrades.", "duration": null}, "reheating": "Gently warm in a pan over low heat with a tablespoon of water or olive oil.", "does_not_keep": false}', '[{"name": "Large stockpot", "required": true, "alternative": null}, {"name": "Large saut\u00e9 pan or skillet", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Sauce is too dry or sticky", "likely_cause": "Pasta absorbed too much liquid or not enough pasta water was added", "prevention": "Always reserve more pasta water than you think you need", "fix": "Add a splash of hot water or olive oil and toss vigorously"}, {"symptom": "Tuna is dry and chalky", "likely_cause": "Tuna was cooked for too long in the sauce", "prevention": "Add tuna only at the very end, just to warm it through", "fix": "Add extra olive oil to mask the dryness"}, {"symptom": "Garlic tastes bitter", "likely_cause": "Garlic was burned during the initial saut\u00e9", "prevention": "Add tomatoes immediately once garlic turns pale gold to stop the cooking", "fix": "Cannot be fixed; must restart the base aromatic step"}]', '["Use tuna packed in olive oil, not water. The oil carries flavor and helps emulsify the sauce. If you use high-end jarred tuna, you can even use the oil from the jar for the saut\u00e9 step.", "Do not rinse the capers too aggressively; a little residual brine adds a nice depth to the sauce, functioning as liquid salt.", "The secret to this dish is the ''mantecatura'' (step 7)\u2014vigorously tossing the pasta with the sauce and starch water creates a creamy texture without any dairy.", "If you prefer a ''bianco'' (white) version, omit the tomatoes and use 60ml of white wine and extra pasta water instead."]', '"This dish is a classic example of Italian ''cucina povera'' (cooking of the poor), relying on shelf-stable pantry ingredients to create a nutritious meal. While specific regional variations exist from Rome to Sicily, the combination of tuna and olive oil is a universal staple of Italian coastal home cooking."', 708.37);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('cb9193cc-86e5-4997-9b4f-8317abcb30de', 'Chatpata Aloo Masala', 'A vibrant, dry-style curry featuring tender potato cubes tossed in a bold, aromatic spice blend. The dish balances the heat of green chilies with the earthy warmth of cumin and the sharp tang of amchur (dried mango powder), creating a texture that is crisp on the outside and buttery soft within.', 'side dish', 'Indian', 'Easy', '["potato", "spicy", "pakistani", "indian", "vegetarian", "vegan", "gluten-free"]', '[{"group_name": "Potatoes", "items": [{"name": "waxy potatoes", "quantity": 800, "unit": "g", "preparation": "peeled and cubed into 2.5cm pieces", "notes": "Yukon Gold or red potatoes hold shape best", "substitutions": [], "ingredient_id": "a87814d3-a635-474b-a78d-4d20b45066e5", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 2000, "unit": "ml", "preparation": null, "notes": "for boiling", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 10, "unit": "g", "preparation": null, "notes": "for boiling water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Tempering & Spices", "items": [{"name": "mustard oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": "or neutral vegetable oil", "substitutions": ["ghee", "canola oil"], "ingredient_id": "71a6eb9b-27fb-43d3-8e41-394612198076", "nutrition_source": "USDA FoodData Central"}, {"name": "cumin seeds", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "black mustard seeds", "quantity": 4, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "6bc4809f-da0c-4b24-a7e4-09873d83ecc3", "nutrition_source": "Aggregated Public Data"}, {"name": "asafoetida (hing)", "quantity": 0.5, "unit": "g", "preparation": "powder", "notes": "generous pinch; ensure GF if required", "substitutions": [], "ingredient_id": "cdff6f65-07c2-4d31-8709-de34deba641c", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh curry leaves", "quantity": 12, "unit": null, "preparation": null, "notes": "leaves stripped from stem", "substitutions": [], "ingredient_id": "f534ee61-c884-44ac-a80a-303780ce406e", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Aromatics & Masala", "items": [{"name": "ginger", "quantity": 15, "unit": "g", "preparation": "julienned or minced", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "green chilies", "quantity": 2, "unit": null, "preparation": "slit lengthwise", "notes": "Thai bird''s eye or serrano", "substitutions": [], "ingredient_id": "6cdb0615-378e-4bfa-b76d-f19bbd780e6c", "nutrition_source": "USDA FoodData Central"}, {"name": "turmeric powder", "quantity": 1.5, "unit": "g", "preparation": null, "notes": "approx 0.5 tsp", "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "kashmiri chili powder", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 1 tsp; mild heat, bright red color", "substitutions": [], "ingredient_id": "a5db2139-313d-49e3-8b1c-2c84839faf83", "nutrition_source": "Aggregated Public Data"}, {"name": "coriander powder", "quantity": 4, "unit": "g", "preparation": null, "notes": "approx 2 tsp", "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "amchur (dried mango powder)", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 1 tsp; essential for tang", "substitutions": ["lemon juice (15ml)"], "ingredient_id": "e4857e92-3b09-4ffc-b0f5-3f5ea0eae64d", "nutrition_source": "USDA FoodData Central"}, {"name": "garam masala", "quantity": 1.5, "unit": "g", "preparation": null, "notes": "approx 0.5 tsp", "substitutions": [], "ingredient_id": "8ffcea01-5f22-462b-94de-ad2a97049325", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish", "items": [{"name": "fresh coriander", "quantity": 15, "unit": "g", "preparation": "roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "8c7693be-b538-445c-80f9-3d5bf4c6dcc0", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the cubed potatoes in a large pot and cover with water and 10g salt. Bring to a boil over high heat, then reduce to simmer until potatoes are just fork-tender but firm (approx. 8-10 minutes). Do not overcook. Drain and set aside to steam dry.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT10M", "doneness_cues": {"visual": null, "tactile": "Fork pierces potato with slight resistance"}}, "tips": ["Allowing the potatoes to cool completely or even chilling them before frying helps them hold their shape better."]}, {"step_number": 2, "phase": "cook", "text": "Heat the oil in a heavy-bottomed wok or skillet over medium-high heat. If using mustard oil, heat until it smokes slightly to remove the raw pungency, then lower heat.", "structured": {"action": "HEAT", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT2M", "doneness_cues": {"visual": "Oil shimmers or smokes lightly (if mustard)", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add mustard seeds. Once they crackle/pop, add cumin seeds, asafoetida, and curry leaves. Saut\u00e9 for 30 seconds until aromatic, being careful not to burn the spices.", "structured": {"action": "TEMPER", "temperature": null, "duration": "PT30S", "doneness_cues": {"visual": "Mustard seeds popping", "tactile": "Aromatic smell released"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the ginger and green chilies. Saut\u00e9 for 1 minute until the raw smell of ginger dissipates.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Reduce heat to low. Add turmeric, chili powder, and coriander powder. Stir immediately for 15-20 seconds. If the pan is too dry, add a tablespoon of water to prevent the spices from burning.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT20S", "doneness_cues": null}, "tips": ["Powdered spices burn very quickly in hot oil; ensure the heat is low or move the pan off the burner briefly."]}, {"step_number": 6, "phase": "cook", "text": "Add the boiled potatoes and the remaining salt (approx 3g). Increase heat to medium-high and toss gently to coat the potatoes in the masala. Pan-fry for 5-7 minutes, stirring occasionally, until potatoes develop a slight crispy crust.", "structured": {"action": "FRY", "temperature": null, "duration": "PT6M", "doneness_cues": {"visual": "Potatoes golden and coated in spices", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Turn off the heat. Sprinkle the amchur (dried mango powder) and garam masala over the potatoes. Toss well to combine.", "structured": {"action": "SEASON", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": ["Amchur is acidic and can turn bitter if cooked too long, which is why it is added at the end."]}, {"step_number": 8, "phase": "finish", "text": "Garnish with fresh chopped coriander and serve hot.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT20M", "total_time": "PT35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 225}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Individuals sensitive to nightshades"]}', '{"per_serving": {"calories": 292.18, "protein_g": 5.34, "carbohydrates_g": 39.5, "fat_g": 12.97, "saturated_fat_g": 1.38, "trans_fat_g": null, "monounsaturated_fat_g": 6.91, "polyunsaturated_fat_g": 2.44, "fiber_g": 17.38, "sugar_g": 2.47, "sodium_mg": 1294.52, "cholesterol_mg": null, "potassium_mg": 1001.94, "calcium_mg": 48.1, "iron_mg": 1.99, "magnesium_mg": 62.47, "phosphorus_mg": 131.07, "zinc_mg": 0.87, "vitamin_a_mcg": 5206.1, "vitamin_c_mg": 54.16, "vitamin_d_mcg": null, "vitamin_e_mg": 0.11, "vitamin_k_mcg": 0.7, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.01, "niacin_mg": 0.14, "folate_mcg": 1.88, "water_g": 509.81, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Flavors often improve the next day.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; thawed potatoes become grainy and watery.", "duration": null}, "reheating": "Reheat in a pan over medium heat with a splash of water to refresh the moisture, or microwave covered.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": "Pressure cooker"}, {"name": "Heavy-bottomed skillet or wok (Kadhai)", "required": true, "alternative": "Large frying pan"}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Spices taste bitter or burnt", "likely_cause": "The oil was too hot when powdered spices were added", "prevention": "Turn heat to low or remove pan from heat before adding turmeric and chili powder", "fix": "Cannot be fixed; must restart the spice tempering (tadka)"}, {"symptom": "Potatoes are mushy and breaking apart", "likely_cause": "Overcooked during the boiling stage", "prevention": "Boil potatoes only until fork-tender, not soft; use waxy potatoes", "fix": "Avoid tossing excessively; gently fold or just shake the pan to mix"}]', '["Texture Secret: If time permits, boil the potatoes a few hours in advance and refrigerate them. Cold potatoes have retrograded starch, meaning they hold their shape significantly better when stir-fried.", "Spice Bloom: Blooming the spices (tempering) in hot oil is the most critical step. If the oil isn''t hot enough, the mustard seeds won''t pop and will taste bitter. If too hot, the cumin burns instantly.", "Acid Balance: If you cannot find Amchur (dried mango powder), use fresh lemon juice, but add it only after removing the pan from the heat to preserve its brightness.", "Serving Suggestion: This dish pairs exceptionally well with ''Poori'' (fried bread) or simple Dal and Rice."]', '"This style of ''sukhi'' (dry) vegetable preparation is a staple in North Indian and Pakistani households, often found in tiffin boxes for lunch. It relies on the technique of ''Baghar'' or ''Tadka''\u2014tempering spices in hot oil to release essential oils\u2014which defines the flavor profile of South Asian cuisine."', 292.18);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('cbd93027-9f50-4a29-b78c-f4c871935625', 'Peppercorn-Crusted Steak Diane with Pommes Sautées', 'Tender, pan-seared steaks coated in crushed peppercorns, served with a luxurious, creamy Diane sauce enriched with cognac, mustard, and herbs. Accompanied by golden, crispy sautéed potatoes with rosemary.', 'dinner', 'French', 'Intermediate', '["steak", "diane sauce", "saut\u00e9 potatoes", "classic", "main course", "french", "date night"]', '[{"group_name": "Saut\u00e9ed Potatoes (Pommes Saut\u00e9es)", "items": [{"name": "waxy potatoes", "quantity": 500, "unit": "g", "preparation": "peeled and cut into 2cm cubes", "notes": "Yukon Gold or Charlotte variety", "substitutions": [], "ingredient_id": "41f30ad1-82e5-4826-9de0-cd33ecd578c1", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "lightly crushed", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh rosemary", "quantity": 2, "unit": null, "preparation": "whole sprigs", "notes": "approx 4g", "substitutions": [], "ingredient_id": "fa90a3a7-86cd-40de-8f8c-0464231925c2", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 3g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Steak", "items": [{"name": "beef fillet steaks", "quantity": 2, "unit": null, "preparation": "room temperature", "notes": "approx 180g each, filet mignon or tenderloin", "substitutions": ["ribeye steak", "sirloin steak"], "ingredient_id": "a821f612-21c1-4514-969d-c3a2101cd8d5", "nutrition_source": "Aggregated Public Data"}, {"name": "whole black peppercorns", "quantity": 15, "unit": "g", "preparation": "coarsely crushed", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "grapeseed or canola", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "generous pinch per side", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Diane Sauce", "items": [{"name": "shallot", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "approx 25g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 3g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "cognac", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["brandy", "beef stock (non-alcoholic)"], "ingredient_id": "e8d39011-867f-4e0a-91fb-95af681339a6", "nutrition_source": "Aggregated Public Data"}, {"name": "beef stock", "quantity": 120, "unit": "ml", "preparation": "high quality", "notes": null, "substitutions": [], "ingredient_id": "390b2a8f-1613-4b2d-ae97-8403bbc9f505", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 80, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2f2247dc-52b3-4782-a330-b355c8c10e4f", "nutrition_source": "Aggregated Public Data"}, {"name": "worcestershire sauce", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "aa552099-60a9-4267-a732-5870a271c28f", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh chives", "quantity": 5, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place potato cubes in a pot of cold salted water. Bring to a boil and cook for 5-7 minutes until slightly tender but not falling apart. Drain well and let steam dry in the colander for 5 minutes.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT7M", "doneness_cues": {"visual": null, "tactile": "knife penetrates with slight resistance"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Pat steaks dry with paper towels. Season generously with salt on both sides. Press the coarsely crushed peppercorns firmly into both sides of the meat to create a crust.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a large non-stick pan, heat 15ml vegetable oil and 30g butter over medium-high heat. Add the par-boiled potatoes in a single layer. Fry, turning occasionally, until golden brown and crispy (about 12-15 minutes). Add crushed garlic and rosemary in the last 2 minutes.", "structured": {"action": "FRY", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT15M", "doneness_cues": {"visual": "deep golden brown crust", "tactile": null}}, "tips": ["Do not overcrowd the pan or potatoes will steam instead of crisp."]}, {"step_number": 4, "phase": "cook", "text": "While potatoes finish, heat the heavy-bottomed skillet over high heat. Add 15ml neutral oil. Once smoking, carefully place steaks in the pan. Sear for 2-3 minutes per side for medium-rare.", "structured": {"action": "SEAR", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT6M", "doneness_cues": {"visual": "dark brown crust", "tactile": "steak feels soft with slight spring"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove steaks from the pan and set aside on a warm plate to rest (aim for internal temp 52\u00b0C/125\u00b0F for rare, 57\u00b0C/135\u00b0F for medium-rare). Do not clean the pan.", "structured": {"action": "REST", "temperature": {"celsius": 57, "fahrenheit": 135}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Reduce heat to medium. Add minced shallots to the steak pan (add a small knob of butter if dry). Saut\u00e9 for 1 minute until softened. Add minced garlic and cook for 30 seconds.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Remove pan from heat or turn off gas flame temporarily. Add Cognac. Return to heat and carefully ignite to flamb\u00e9, or simply boil rapidly until alcohol smell dissipates and liquid reduces by half.", "structured": {"action": "FLAMB\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "flames subside, liquid syrupy", "tactile": null}}, "tips": ["Safety: Keep a lid nearby to extinguish flames if they get too high.", "Turn off extractor fan before flamb\u00e9ing."]}, {"step_number": 8, "phase": "cook", "text": "Stir in beef stock, Dijon mustard, and Worcestershire sauce. Simmer for 2-3 minutes to reduce slightly. Lower heat and stir in heavy cream. Simmer gently until sauce coats the back of a spoon.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "glossy, nappe consistency", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Return steaks and any resting juices to the pan, turning to coat in the sauce. Warm through for 30 seconds. Sprinkle with chives and serve immediately with the crispy potatoes.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT10M", "total_time": "PT55M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 450}', '{"flags": ["Gluten-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": ["Infants under 12 months (if honey used in sauce adjustments)", "Pregnant individuals (alcohol in sauce, though mostly cooked off)"]}', '{"per_serving": {"calories": 1756.48, "protein_g": 62.8, "carbohydrates_g": 219.42, "fat_g": 65.43, "saturated_fat_g": 28.93, "trans_fat_g": 1.09, "monounsaturated_fat_g": 13.66, "polyunsaturated_fat_g": 2.61, "fiber_g": 17.79, "sugar_g": 11.9, "sodium_mg": 1442.71, "cholesterol_mg": 203.38, "potassium_mg": 3324.1, "calcium_mg": 281.44, "iron_mg": 9.72, "magnesium_mg": 210.47, "phosphorus_mg": 891.01, "zinc_mg": 8.12, "vitamin_a_mcg": 346.18, "vitamin_c_mg": 14.69, "vitamin_d_mcg": 0.82, "vitamin_e_mg": 1.93, "vitamin_k_mcg": 18.03, "vitamin_b6_mg": 3.17, "vitamin_b12_mcg": 6.37, "thiamin_mg": 0.71, "riboflavin_mg": 0.8, "niacin_mg": 17.47, "folate_mcg": 78.02, "water_g": 187, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store sauce and steak separately if possible. Potatoes lose crispness.", "duration": "P2D"}, "freezer": {"notes": "Cream sauces and cooked potatoes do not freeze well.", "duration": null}, "reheating": "Gently reheat steak in a low oven. Reheat sauce on low heat on stovetop, adding a splash of water if separated. Re-fry potatoes to crisp.", "does_not_keep": false}', '[{"name": "Heavy-bottomed skillet or Cast Iron Pan", "required": true, "alternative": "Stainless steel frying pan"}, {"name": "Large non-stick pan", "required": true, "alternative": "Cast iron skillet"}, {"name": "Medium pot", "required": true, "alternative": "Saucepan"}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Mortar and Pestle", "required": false, "alternative": "Rolling pin and zip-lock bag"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Sauce separates or looks greasy", "likely_cause": "The sauce was boiled too vigorously after adding the cream", "prevention": "Keep heat on low after adding dairy", "fix": "Whisk in a teaspoon of cold water or cream off the heat to re-emulsify"}, {"symptom": "Peppercorns are bitter", "likely_cause": "Peppercorns burned during the high-heat sear", "prevention": "Use coarsely crushed pepper, not fine powder, and avoid oil reaching smoke point before adding steak", "fix": "Cannot be fixed; scrape off burned pepper and rely on sauce for flavor"}]', '["Steam-drying the potatoes after boiling is the secret to the crispiest crust; moisture is the enemy of browning.", "For a true ''Diane'' flavor, do not skip the Worcestershire sauce; it provides the essential umami backbone.", "If you cannot flamb\u00e9 safely, simply simmer the Cognac for an extra minute to ensure the harsh alcohol bite evaporates.", "Use a mortar and pestle for the peppercorns to get a coarse ''mignonette'' texture rather than a fine powder, which burns easily."]', '"Steak Diane was a staple of mid-20th century continental cuisine, famous for its tableside theatrical preparation in New York and London dining rooms. Named after the Roman goddess of the hunt, Diana, the sauce was originally a piquant condiment for venison before evolving into this creamy brandy-infused accompaniment for beef."', 1756.48);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('cc2dcf46-1cf0-4fca-a72e-c63c3a837b5a', 'Golden Cardamom Leek Fritters', 'Crispy, golden-brown discs of tender leeks, lightly spiced with warming cardamom and brightened with fresh dill and parsley. The sweetness of the leeks pairs unexpectedly well with the floral notes of cardamom.', 'appetizer', 'Middle Eastern Fusion', 'Intermediate', '["appetizer", "vegetarian", "middle eastern", "fried", "crispy", "savory"]', '[{"group_name": "Leek Base", "items": [{"name": "leeks", "quantity": 1000, "unit": "g", "preparation": "cleaned, white and light green parts only", "notes": "approx. 4 large leeks", "substitutions": [], "ingredient_id": "f0bddafa-51db-4e56-954b-18624daa6fa4", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 500, "unit": "ml", "preparation": "for steaming/boiling", "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Binder & Aromatics", "items": [{"name": "large eggs", "quantity": 2, "unit": null, "preparation": "beaten", "notes": "approx. 100-110g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "panko breadcrumbs", "quantity": 60, "unit": "g", "preparation": null, "notes": "or matzo meal", "substitutions": ["matzo meal", "regular breadcrumbs", "chickpea flour (for GF)"], "ingredient_id": "84fbc204-4457-40ed-83c1-3e5a7bcd8f23", "nutrition_source": "Aggregated Public Data"}, {"name": "ground cardamom", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx. 1 tsp", "substitutions": [], "ingredient_id": "c56f6cd8-882c-487c-956f-3a91ee1fec07", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh dill", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "4be2b047-475d-4c84-82d5-4883298c6121", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh flat-leaf parsley", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx. 4g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Frying", "items": [{"name": "neutral oil", "quantity": 100, "unit": "ml", "preparation": "for shallow frying", "notes": "grapeseed or sunflower oil", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Slice the cleaned leeks into 1cm (0.5 inch) rounds. Wash thoroughly in a bowl of cold water to remove any hidden grit between layers, then drain.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Place leeks in a pot with water. Bring to a boil, then reduce heat and simmer until the leeks are very tender, about 15-20 minutes.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT20M", "doneness_cues": {"visual": null, "tactile": "Leeks mash easily with a fork"}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Drain the leeks in a colander. Once cool enough to handle, transfer them to a clean kitchen towel and squeeze vigorously to remove as much liquid as possible. This is the most important step for crispiness.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": {"visual": "Volume reduces significantly", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Roughly chop the squeezed leeks. In a large mixing bowl, combine the leeks, beaten eggs, breadcrumbs, ground cardamom, minced garlic, chopped herbs, salt, and pepper. Mix until a cohesive batter forms.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Heat the neutral oil in a large skillet over medium-high heat (approx. 175\u00b0C/350\u00b0F). The oil should be about 0.5cm deep.", "structured": {"action": "HEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Scoop tablespoons of the mixture and carefully drop them into the hot oil. Flatten slightly with a spatula. Fry in batches for 3-4 minutes per side until deeply golden brown and crispy.", "structured": {"action": "FRY", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Deep golden brown crust", "tactile": "Crispy exterior"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove fritters from the pan and place on a wire rack to drain excess oil. Sprinkle immediately with a pinch of flaky salt if desired.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT20M", "total_time": "PT1H5M", "overnight_required": false, "yields": "12 fritters", "yield_count": 12, "serving_size_g": 150}', '{"flags": ["Vegetarian", "Dairy-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 153.11, "protein_g": 2.94, "carbohydrates_g": 15.43, "fat_g": 9.46, "saturated_fat_g": 1.46, "trans_fat_g": null, "monounsaturated_fat_g": 0.32, "polyunsaturated_fat_g": 0.16, "fiber_g": 1.79, "sugar_g": 3.48, "sodium_mg": 204.75, "cholesterol_mg": 31, "potassium_mg": 168.49, "calcium_mg": 53.09, "iron_mg": 2.03, "magnesium_mg": 24.99, "phosphorus_mg": 43.97, "zinc_mg": 0.24, "vitamin_a_mcg": 124.11, "vitamin_c_mg": 11.41, "vitamin_d_mcg": 0.17, "vitamin_e_mg": 0.09, "vitamin_k_mcg": 13.83, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": 0.07, "thiamin_mg": 0.01, "riboflavin_mg": 0.04, "niacin_mg": 0.03, "folate_mcg": 6.46, "water_g": 49.69, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best reheated in an oven or air fryer to recrisp.", "duration": "P3D"}, "freezer": {"notes": "Freeze separated by parchment paper.", "duration": "P2M"}, "reheating": "Reheat in a 180\u00b0C/350\u00b0F oven for 10 minutes until crispy.", "does_not_keep": false}', '[{"name": "Large heavy-bottomed skillet", "required": true, "alternative": "Cast iron pan"}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Clean kitchen towel", "required": true, "alternative": "Cheesecloth"}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}]', '[{"symptom": "Fritters are falling apart in the pan", "likely_cause": "The mixture is too wet because the leeks weren''t squeezed enough, or not enough binder was used", "prevention": "Squeeze the boiled leeks until they are nearly dry before mixing", "fix": "Add 1-2 tablespoons more breadcrumbs to the remaining batter and let it sit for 5 minutes"}, {"symptom": "Fritters are soggy", "likely_cause": "Oil temperature was too low", "prevention": "Ensure oil shimmers and a test piece sizzles immediately before frying", "fix": "Increase heat; finish soggy fritters in a hot oven (200\u00b0C/400\u00b0F) to crisp up"}]', '["The cardamom provides a warm, floral backdrop that elevates the natural sweetness of the leeks; do not skip it, but ensure your spice is fresh.", "For the crispiest result, do not overcrowd the pan. Frying too many at once drops the oil temperature and leads to oil absorption.", "Serve these with a dollop of thick greek yogurt mixed with lemon zest and a pinch of sumac for a perfect acid contrast."]', '"Inspired by Sephardic ''Keftes de Prasa'', traditionally served during Passover and Rosh Hashanah. While the traditional version often uses beef, this vegetarian interpretation highlights the vegetable''s versatility, adding cardamom for a Persian aromatic twist."', 153.11);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ce53bb4d-2a19-4265-bbf5-e95d5ff239e7', 'Smoky Roasted Red Pepper & Eggplant Spread (Ajvar)', 'A lush, velvety Balkan relish boasting deep smoky notes from charred vegetables, balanced by the fruitiness of olive oil and a piquant vinegar tang. This versatile spread bridges the gap between a savory dip and a rich condiment.', 'condiment', 'Balkan', 'Intermediate', '["mediterranean", "condiments", "dips and spreads", "eggplant", "red pepper", "easy", "gluten-free", "vegan", "vegetarian"]', '[{"group_name": "Vegetables", "items": [{"name": "red bell peppers", "quantity": 1000, "unit": "g", "preparation": "whole", "notes": "approx. 4-5 large peppers", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "USDA FoodData Central"}, {"name": "eggplant", "quantity": 300, "unit": "g", "preparation": "whole", "notes": "1 medium eggplant", "substitutions": [], "ingredient_id": "77c14307-dacf-4ab2-85d1-3594bff0ec99", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "cloves, minced", "notes": "approx. 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "red chili pepper", "quantity": 1, "unit": null, "preparation": "minced", "notes": "optional, for heat", "substitutions": [], "ingredient_id": "5080eb9a-d555-4558-94e5-d5700e96ff9b", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Seasoning & Finish", "items": [{"name": "olive oil", "quantity": 80, "unit": "ml", "preparation": null, "notes": "extra virgin preferred", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "white wine vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": "adjust to taste for acidity", "substitutions": [], "ingredient_id": "b2f8f0c0-6da9-47aa-932a-c2747b64b807", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 230\u00b0C/450\u00b0F (or use a broiler/grill setting).", "structured": {"action": "PREHEAT", "temperature": {"celsius": 230, "fahrenheit": 446}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Place whole red peppers and the eggplant on a baking sheet. Roast until the skins are blackened and blistered, turning occasionally to ensure even charring. This creates the essential smoky flavor.", "structured": {"action": "ROAST", "temperature": {"celsius": 230, "fahrenheit": 446}, "duration": "PT30M", "doneness_cues": {"visual": "Skins completely blackened and blistered", "tactile": "Flesh feels very soft and collapsed"}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Transfer the hot roasted vegetables to a large bowl and cover tightly with plastic wrap or a lid. Let them steam in their own heat for 15-20 minutes. This loosens the skins for easy peeling.", "structured": {"action": "STEAM", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Peel the charred skins off the peppers and eggplant. Remove stems, seeds, and cores. Discard the skins and seeds but try to retain any clear juices released by the peppers.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Do not rinse the vegetables under water to remove seeds, as this washes away the smoky flavor."]}, {"step_number": 5, "phase": "prep", "text": "Place the cleaned pepper and eggplant flesh, minced garlic, and chili (if using) into a food processor. Pulse until finely chopped or smooth, depending on your textural preference.", "structured": {"action": "PUREE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Uniform texture, ranging from chunky relish to smooth paste", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Transfer the vegetable mixture to a heavy-bottomed pot over medium-low heat. Stir in the olive oil, vinegar, salt, and pepper.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Simmer gently while stirring frequently to prevent sticking. Cook until the mixture thickens, the oil emulsifies into the spread, and excess liquid evaporates. It should leave a trail when a spoon is dragged through it.", "structured": {"action": "REDUCE", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT20M", "doneness_cues": {"visual": "Thickened consistency, oil absorbed, deep red-orange color", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Taste and adjust seasoning with more salt or vinegar if needed. Remove from heat and transfer to sterilized jars. Cool completely before sealing.", "structured": {"action": "COOL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT45M", "total_time": "PT1H30M", "overnight_required": false, "yields": "500ml", "yield_count": 16, "serving_size_g": 30}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Low-Carb"], "not_suitable_for": []}', '{"per_serving": {"calories": 67.22, "protein_g": 0.89, "carbohydrates_g": 5.33, "fat_g": 5.23, "saturated_fat_g": 0.73, "trans_fat_g": null, "monounsaturated_fat_g": 3.66, "polyunsaturated_fat_g": 0.64, "fiber_g": 1.93, "sugar_g": 3.32, "sodium_mg": 124.53, "cholesterol_mg": null, "potassium_mg": 182.37, "calcium_mg": 8.29, "iron_mg": 0.37, "magnesium_mg": 10.47, "phosphorus_mg": 22.53, "zinc_mg": 0.2, "vitamin_a_mcg": 100.04, "vitamin_c_mg": 83.81, "vitamin_d_mcg": null, "vitamin_e_mg": 1.77, "vitamin_k_mcg": 6.85, "vitamin_b6_mg": 0.21, "vitamin_b12_mcg": null, "thiamin_mg": 0.04, "riboflavin_mg": 0.07, "niacin_mg": 0.74, "folate_mcg": 32.91, "water_g": 75.49, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in a sterilized jar with a thin layer of olive oil on top to prevent oxidation.", "duration": "P2W"}, "freezer": {"notes": "Texture may slightly separate upon thawing; stir vigorously to emulsify.", "duration": "P3M"}, "reheating": "Serve at room temperature or gently warm.", "does_not_keep": false}', '[{"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Large bowl", "required": true, "alternative": null}, {"name": "Plastic wrap or lid", "required": true, "alternative": "Clean kitchen towel"}, {"name": "Food processor", "required": true, "alternative": "Immersion blender or meat grinder"}, {"name": "Heavy-bottomed pot", "required": true, "alternative": null}]', '[{"symptom": "Spread is watery or runny", "likely_cause": "Insufficient reduction time; vegetables retained too much moisture", "prevention": "Ensure peppers are drained well after peeling", "fix": "Continue simmering on low heat, stirring constantly, until excess moisture evaporates"}, {"symptom": "Flavor is bitter", "likely_cause": "Burnt garlic or too much charred skin left in the mix", "prevention": "Add garlic only at the processing stage; peel vegetables thoroughly", "fix": "Add a pinch of sugar or a splash more vinegar to balance the bitterness"}]', '["For the most authentic flavor, roast the peppers over an open flame or charcoal grill to maximize smokiness.", "Do not skip the steaming step after roasting; it makes the tedious peeling process significantly easier.", "This spread improves with age. Letting it sit in the fridge for 24 hours allows the garlic and vinegar to marry with the roasted vegetables.", "Serve as a dip with flatbread, a spread for sandwiches, or a sauce alongside grilled meats."]', '"Known as Ajvar in the Balkans, this ''vegetable caviar'' is a staple autumn preserve in countries like Serbia, North Macedonia, and Croatia. Families historically gather to roast bushels of peppers, preserving the harvest to enjoy the taste of summer throughout the winter."', 67.22);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ce629383-fe55-4997-a14b-11012f23e2fe', 'Golden Spiced Turkey Patties with Coconut Curry Sauce', 'Succulent, pan-seared turkey patties infused with ginger and cilantro, simmered in a creamy, aromatic coconut-turmeric sauce. Finished with toasted slivered almonds for a nutty, textural crunch.', 'dinner', 'Fusion', 'Easy', '["ground turkey", "dinner", "main course", "fusion", "curry", "dairy-free"]', '[{"group_name": "Toasted Almonds", "items": [{"name": "slivered almonds", "quantity": 30, "unit": "g", "preparation": "raw", "notes": null, "substitutions": [], "ingredient_id": "5bcbb4d4-6845-4825-bd21-1c13e52b989c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Turkey Patties", "items": [{"name": "ground turkey", "quantity": 500, "unit": "g", "preparation": "chilled", "notes": "Preferably dark meat (thigh) for moisture", "substitutions": [], "ingredient_id": "e249d5fe-71d4-4703-a054-7f5b828f930b", "nutrition_source": "USDA FoodData Central"}, {"name": "panko breadcrumbs", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": ["gluten-free breadcrumbs", "almond flour"], "ingredient_id": "84fbc204-4457-40ed-83c1-3e5a7bcd8f23", "nutrition_source": "Aggregated Public Data"}, {"name": "green onion", "quantity": 2, "unit": null, "preparation": "finely sliced", "notes": "approx. 30g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "Aggregated Public Data"}, {"name": "ginger root", "quantity": 10, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx. 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": "beaten", "notes": "medium size, approx. 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["tamari", "coconut aminos"], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "neutral oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "for searing", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Curry Sauce", "items": [{"name": "yellow curry paste", "quantity": 30, "unit": "g", "preparation": null, "notes": "Adjust based on spice tolerance", "substitutions": [], "ingredient_id": "f534ee61-c884-44ac-a80a-303780ce406e", "nutrition_source": "Aggregated Public Data"}, {"name": "coconut milk", "quantity": 400, "unit": "ml", "preparation": "full fat", "notes": "1 standard can", "substitutions": [], "ingredient_id": "c037ee7e-e3ed-4340-b8fb-d8ad284ba96e", "nutrition_source": "USDA FoodData Central"}, {"name": "fish sauce", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "95a9a747-50ee-4be0-84be-0dfc96111e2a", "nutrition_source": "Aggregated Public Data"}, {"name": "lime juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "brown sugar", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place slivered almonds in a dry skillet over medium heat. Toast, shaking the pan frequently, until golden brown and fragrant. Remove immediately to a small bowl to cool.", "structured": {"action": "TOAST", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown color", "tactile": "Crisp texture"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, combine ground turkey, panko, sliced green onion, grated ginger, minced garlic, beaten egg, and soy sauce. Gently mix with your hands until just combined. Do not overwork.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Ingredients evenly distributed", "tactile": "Mixture holds together"}}, "tips": ["Overworking the meat matrix causes proteins to cross-link too tightly, resulting in rubbery patties."]}, {"step_number": 3, "phase": "prep", "text": "Divide the mixture into 8 equal portions and shape them into patties approximately 1.5 cm thick. Press a small indentation in the center of each to prevent doming during cooking.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Heat the neutral oil in the large skillet over medium-high heat. Add the patties and sear until browned on both sides, about 3 minutes per side. They do not need to be fully cooked through at this stage. Remove patties to a plate.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT6M", "doneness_cues": {"visual": "Deep golden brown crust", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Reduce heat to medium. Add the yellow curry paste to the skillet (add a splash more oil if dry) and saut\u00e9 for 1 minute until aromatic and the oils separate slightly.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Paste darkens slightly", "tactile": "Aromatic oils release"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Pour in the coconut milk, scraping the bottom of the pan to deglaze any browned bits (fond). Stir in fish sauce, lime juice, and brown sugar. Bring to a gentle simmer.", "structured": {"action": "DEGLAZE", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Return the patties and any resting juices to the skillet. Simmer gently in the sauce for 5-7 minutes, or until the internal temperature of the turkey reaches 74\u00b0C (165\u00b0F).", "structured": {"action": "SIMMER", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": "PT7M", "doneness_cues": {"visual": "Sauce slightly thickened", "tactile": "Meat firm to touch"}}, "tips": ["Always check poultry internal temperature with a probe thermometer for safety."]}, {"step_number": 8, "phase": "finish", "text": "Plate the patties with a generous ladle of sauce. Garnish with the toasted almonds and extra fresh cilantro if desired.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT5M", "total_time": "PT30M", "overnight_required": false, "yields": "4 servings (8 patties)", "yield_count": 4, "serving_size_g": 240}', '{"flags": ["Dairy-Free"], "not_suitable_for": ["Individuals with nut allergies (almonds, coconut)"]}', '{"per_serving": {"calories": 583.47, "protein_g": 32.52, "carbohydrates_g": 20.04, "fat_g": 43.37, "saturated_fat_g": 24.85, "trans_fat_g": 0.13, "monounsaturated_fat_g": 7.15, "polyunsaturated_fat_g": 4.19, "fiber_g": 3.71, "sugar_g": 7.66, "sodium_mg": 823.03, "cholesterol_mg": 132.75, "potassium_mg": 680.45, "calcium_mg": 78.61, "iron_mg": 4.05, "magnesium_mg": 93.51, "phosphorus_mg": 417.37, "zinc_mg": 4.07, "vitamin_a_mcg": 48.98, "vitamin_c_mg": 5.95, "vitamin_d_mcg": 0.75, "vitamin_e_mg": 2.37, "vitamin_k_mcg": 15.71, "vitamin_b6_mg": 0.79, "vitamin_b12_mcg": 1.36, "thiamin_mg": 0.14, "riboflavin_mg": 0.35, "niacin_mg": 9.53, "folate_mcg": 39.45, "water_g": 180.98, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store patties and sauce in an airtight container. Reheat gently to avoid drying out the turkey.", "duration": "P3D"}, "freezer": {"notes": "Freeze patties and sauce separately for best texture.", "duration": "P2M"}, "reheating": "Gently warm in a saucepan over low heat with a splash of water or coconut milk until heated through.", "does_not_keep": false}', '[{"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Measuring spoons", "required": true, "alternative": null}]', '[{"symptom": "Patties are dry or tough", "likely_cause": "Used lean turkey breast instead of thigh, or overcooked", "prevention": "Use ground dark meat and stop cooking exactly at 74\u00b0C (165\u00b0F)", "fix": "Break patties into chunks and mix thoroughly with the sauce to absorb moisture; serve as a ragout"}]', '["Ground turkey is much leaner than beef; utilizing a ''panade'' (the breadcrumb and egg mixture) is scientifically crucial to retain moisture during the protein coagulation process.", "Bloom the curry paste in oil before adding liquid. Fat-soluble flavor compounds in the spices need direct heat to fully release their complexity.", "If the sauce breaks (oil separates from the coconut milk), whisk in a teaspoon of warm water vigorously to re-emulsify."]', '"This dish represents a modern fusion style, applying French pan-sauce techniques to Southeast Asian flavor profiles. While the patty format echoes the Western ''salisbury steak'', the flavor architecture utilizes the Thai balance of sweet, sour, salty, and spicy."', 583.47);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ce76bd98-6982-4d1f-8b33-b48fd7dad321', 'Zesty Lime and Sea Salt Compound Butter', 'A vibrant and aromatic finishing butter that balances the tart, floral oils of fresh lime zest with the satisfying crunch of flake sea salt. An optional addition of fresh mint transforms this into a ''Mojito'' style spread perfect for grilled corn, seafood, or warm crusty bread.', 'condiment', 'Modern', 'Easy', '["dips and spreads", "lime", "unsalted butter", "easy", "weeknight", "gluten-free", "nut-free", "vegetarian", "keto", "condiment", "summer", "grilling"]', '[{"group_name": "Base", "items": [{"name": "unsalted butter", "quantity": 125, "unit": "g", "preparation": "room temperature/softened", "notes": "high-fat European style preferred", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "flake sea salt", "quantity": 3, "unit": "g", "preparation": "crushed slightly", "notes": "Maldon or Fleur de Sel; reduce to 1.5g if using fine table salt", "substitutions": ["kosher salt"], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics", "items": [{"name": "limes", "quantity": 2, "unit": null, "preparation": "washed and dried", "notes": "zest only (approx 4-6g)", "substitutions": [], "ingredient_id": "d3d2677e-fe02-4404-add0-29d73df7e921", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh lime juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": "add carefully to avoid separating the butter", "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh mint leaves", "quantity": 4, "unit": "g", "preparation": "washed, dried, and finely minced", "notes": null, "substitutions": [], "ingredient_id": "213e3d3b-d332-45a9-b35e-23ee29a27173", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Ensure the butter is thoroughly softened at room temperature (around 20\u00b0C/68\u00b0F) so it is pliable but not melted. If using fresh mint, ensure leaves are completely dry before mincing to prevent water pockets.", "structured": {"action": "TEMPER", "temperature": {"celsius": 20, "fahrenheit": 68}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Using a microplane, zest the limes directly over the butter in the mixing bowl. This captures the essential oils that spray during zesting.", "structured": {"action": "ZEST", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Rotate the lime constantly to avoid the bitter white pith."]}, {"step_number": 3, "phase": "mix", "text": "Add the salt (and optional minced mint and lime juice). Use the spatula to mash and fold the ingredients into the butter until evenly distributed.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Transfer the butter mixture onto a sheet of parchment paper or plastic wrap. Fold the paper over the butter and use a bench scraper or the edge of a ruler to push against the bottom paper layer, forming a tight cylinder or log.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Twist the ends of the paper to seal and refrigerate for at least 1 hour to set the shape and allow flavors to meld.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT1H", "total_time": "PT1H10M", "overnight_required": false, "yields": "130g log", "yield_count": 8, "serving_size_g": 15}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Keto", "Low-Carb", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 112.73, "protein_g": 0.16, "carbohydrates_g": 0.2, "fat_g": 12.68, "saturated_fat_g": 7.89, "trans_fat_g": null, "monounsaturated_fat_g": 3.66, "polyunsaturated_fat_g": 0.47, "fiber_g": 0.06, "sugar_g": 0.03, "sodium_mg": 147.4, "cholesterol_mg": 33.59, "potassium_mg": 7.99, "calcium_mg": 5.35, "iron_mg": 0.03, "magnesium_mg": 0.8, "phosphorus_mg": 4.32, "zinc_mg": 0.02, "vitamin_a_mcg": 107.96, "vitamin_c_mg": 0.53, "vitamin_d_mcg": null, "vitamin_e_mg": 0.37, "vitamin_k_mcg": 1.1, "vitamin_b6_mg": null, "vitamin_b12_mcg": 0.03, "thiamin_mg": null, "riboflavin_mg": 0.01, "niacin_mg": 0.02, "folate_mcg": 1.15, "water_g": 4.05, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Keep tightly wrapped to prevent absorbing fridge odors.", "duration": "P2W"}, "freezer": {"notes": "Slice into coins before freezing for easy single-serving use.", "duration": "P3M"}, "reheating": "Serve at room temperature or melt directly onto hot food.", "does_not_keep": false}', '[{"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Silicone spatula", "required": true, "alternative": null}, {"name": "Microplane or fine grater", "required": true, "alternative": "Box grater (fine side)"}, {"name": "Parchment paper or plastic wrap", "required": true, "alternative": null}]', '[{"symptom": "Butter looks curdled or separated", "likely_cause": "Lime juice was added too quickly or the butter was too cold", "prevention": "Ensure butter is very soft and add liquid acid (juice) drop by drop", "fix": "Let sit at room temperature for 10 minutes, then whip vigorously with a whisk"}, {"symptom": "Bitter taste", "likely_cause": "Zested too deep into the white pith", "prevention": "Stop zesting as soon as the white layer appears", "fix": "Cannot be fixed; add more butter and salt to dilute the bitterness"}]', '["Always use unsalted butter so you can control the salinity. The crunch of undissolved flake salt is a key textural component of this recipe.", "If serving with seafood, omit the mint and add a pinch of chili flakes for a savory kick.", "This butter is exceptional on grilled corn on the cob (elote style base) or melted over seared scallops.", "For a ''whipped'' texture, use an electric mixer and beat for 3-4 minutes before shaping."]', '"Compound butters (Beurre Compos\u00e9) are a staple of French culinary tradition, used to instantly add sauce-like complexity to simple grilled meats and vegetables. This variation borrows flavor profiles from Latin American cuisine, specifically the lime-salt combination often found in margaritas and ceviche cures."', 112.73);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('cf4ce03c-bd85-485f-91d8-9ee80fd2a22a', 'Georgian Red Bean Salad with Walnut-Cilantro Dressing (Lobio)', 'A vibrant and hearty salad featuring creamy kidney beans coated in a rich, tangy walnut and herb paste. The earthiness of the beans is lifted by fresh cilantro, sharp red onion, and the bright pop of pomegranate seeds, bringing the distinctive flavors of the Caucasus mountains to your table.', 'salad', 'Georgian', 'Easy', '["kidney bean", "side", "summer", "dairy-free", "gluten-free", "halal", "healthy", "high fiber", "kosher", "low cholesterol", "low sodium", "low sugar", "vegan", "vegetarian"]', '[{"group_name": "Salad Base", "items": [{"name": "red kidney beans, cooked", "quantity": 500, "unit": "g", "preparation": "rinsed and drained if canned", "notes": "approx. 2 standard cans", "substitutions": [], "ingredient_id": "c47acd32-84b1-49d8-bb34-ee2a51c96683", "nutrition_source": "USDA FoodData Central"}, {"name": "red onion", "quantity": 80, "unit": "g", "preparation": "finely diced", "notes": null, "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 30, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Walnut Dressing (Baje)", "items": [{"name": "walnuts", "quantity": 75, "unit": "g", "preparation": "toasted", "notes": null, "substitutions": [], "ingredient_id": "ab4fe25a-a215-4af7-8109-055c28e0bef2", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": null, "notes": "approx 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "red wine vinegar", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "9e1b7e74-fdcb-4836-8349-4f7ad86d62df", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "ground coriander", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "blue fenugreek (utskho suneli)", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 0.5 tsp; sub standard fenugreek if unavailable", "substitutions": [], "ingredient_id": "224501d9-d278-4443-ac4b-93837873a1d5", "nutrition_source": "USDA FoodData Central"}, {"name": "cayenne pepper", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "warm water", "quantity": 30, "unit": "ml", "preparation": null, "notes": "to adjust consistency", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Garnish", "items": [{"name": "pomegranate seeds", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "793af9f7-6371-4f4b-822d-b2bac2f93aa5", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place walnuts in a dry skillet over medium heat. Toast for 3-5 minutes until fragrant and slightly darkened, being careful not to burn them. Allow to cool completely.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Slightly darkened", "tactile": "Fragrant"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Finely dice the red onion. If the onion is very sharp, soak the diced pieces in cold water for 10 minutes, then drain and pat dry to reduce pungency.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a food processor, combine the cooled walnuts, garlic, coriander, blue fenugreek, cayenne, and salt. Pulse until the nuts are finely ground.", "structured": {"action": "BLEND", "temperature": null, "duration": null, "doneness_cues": {"visual": "Fine meal texture", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the red wine vinegar and olive oil to the processor. Blend while slowly drizzling in the warm water until a thick, creamy paste forms. It should coat the back of a spoon but not be runny.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "In a large mixing bowl, combine the kidney beans, diced onion, chopped cilantro, and parsley. Pour the walnut dressing over the mixture and fold gently until the beans are evenly coated.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Let the salad rest for at least 30 minutes to allow the flavors to meld. Serve garnished with fresh pomegranate seeds.", "structured": {"action": "REST", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT30M", "total_time": "PT50M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 220}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Soy-Free", "Halal", "Sugar-Free"], "not_suitable_for": ["Tree Nut allergies (walnuts)"]}', '{"per_serving": {"calories": 279.63, "protein_g": 6.2, "carbohydrates_g": 12.49, "fat_g": 24.18, "saturated_fat_g": 3.7, "trans_fat_g": null, "monounsaturated_fat_g": 9.21, "polyunsaturated_fat_g": 10.12, "fiber_g": 3.11, "sugar_g": 3.2, "sodium_mg": 302.94, "cholesterol_mg": 5, "potassium_mg": 744.22, "calcium_mg": 57.82, "iron_mg": 3.76, "magnesium_mg": 86.22, "phosphorus_mg": 197.36, "zinc_mg": 1.4, "vitamin_a_mcg": 172.99, "vitamin_c_mg": 9.19, "vitamin_d_mcg": null, "vitamin_e_mg": 1.4, "vitamin_k_mcg": 68.9, "vitamin_b6_mg": 0.22, "vitamin_b12_mcg": 0.03, "thiamin_mg": 0.22, "riboflavin_mg": 0.17, "niacin_mg": 0.87, "folate_mcg": 74.5, "water_g": 165.72, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors meld and improve significantly after 24 hours.", "duration": "P4D"}, "freezer": {"notes": null, "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Food processor or Mortar & Pestle", "required": true, "alternative": "Chef''s knife and cutting board (for fine mincing)"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Skillet", "required": false, "alternative": "Oven (for toasting nuts)"}]', '[{"symptom": "Dressing is too thick or pasty", "likely_cause": "Walnuts absorbed too much moisture or varying oil content in nuts", "prevention": "Add water incrementally", "fix": "Whisk in additional warm water or bean liquid 1 teaspoon at a time until creamy"}, {"symptom": "Salad tastes bland", "likely_cause": "Beans were not salted enough or vinegar acidity is low", "prevention": "Taste beans before mixing", "fix": "Add a splash more vinegar and a pinch of salt; let sit for another 10 minutes"}]', '["Blue Fenugreek (Utskho Suneli) is the secret to authentic Georgian flavor. If you cannot find it, a mix of regular fenugreek and a tiny pinch of curry powder is a passable substitute.", "Using high-quality walnuts is crucial as they provide the fat and body of the sauce. Avoid pre-chopped nuts which may be oxidized.", "This dish is traditionally served at room temperature, not ice-cold, to allow the nut oils and spices to express themselves fully.", "For an extra kick, add a teaspoon of adjika (Georgian chili paste) to the dressing.", "This recipe works excellently with other beans, such as butter beans or black beans, though red kidney is traditional."]', '"Inspired by ''Lobio'', a cornerstone of Georgian cuisine, this salad highlights the country''s love affair with walnuts and fresh herbs. While Lobio often refers to a hot bean stew served in clay pots, this chilled variation (often called Lobio Nigozit) preserves the same flavor profile\u2014earthy beans, tart vinegar, and rich nuts\u2014in a lighter format perfect for warmer weather."', 279.63);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('cfa88dd9-fdc6-497e-8262-82552707595a', 'Buttered Sauteed Cucumbers and Onions', 'A surprisingly elegant side dish where cucumbers are transformed by heat into tender, zucchini-like morsels while retaining a fresh snap. The sweetness of the onions and richness of butter create a comforting base, finished with cool yogurt and herbaceous parsley.', 'side dish', 'German', 'Easy', '["cucumber", "onion", "yogurt", "easy", "quick", "side dish", "summer", "gluten-free", "nut-free", "vegetarian"]', '[{"group_name": "Vegetables", "items": [{"name": "english cucumbers", "quantity": 2, "unit": null, "preparation": "peeled, seeded, and sliced into 1cm half-moons", "notes": "approx 600g total weight", "substitutions": ["slicing cucumbers", "zucchini"], "ingredient_id": "457adec2-3e06-4efe-a26e-9e6ea9f84924", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "halved and thinly sliced", "notes": "medium size, approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": ["olive oil", "ghee"], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Finish (Optional)", "items": [{"name": "plain greek yogurt", "quantity": 60, "unit": "g", "preparation": "chilled", "notes": null, "substitutions": ["sour cream", "cr\u00e8me fra\u00eeche"], "ingredient_id": "2c5306ec-9f54-424e-880d-99546bbd9172", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 5, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": ["fresh dill", "chives"], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the cucumbers by peeling them (leave stripes of skin for texture if desired), slicing them in half lengthwise, and scooping out the watery seeds with a small spoon. Slice into 1cm thick half-moons.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Seeds removed, uniform crescent shapes", "tactile": null}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Melt the butter in a large skillet over medium heat (approx 175\u00b0C/350\u00b0F). Add the sliced onions and salt.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Cook the onions for 5-6 minutes until they are softened and translucent, but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT6M", "doneness_cues": {"visual": "Translucent and glossy onions", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Increase heat to medium-high. Add the prepared cucumbers and pepper. Saut\u00e9 for 3-5 minutes, tossing occasionally, until cucumbers are tender-crisp. Avoid overcooking to mush.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Cucumbers look vibrant green and glossy", "tactile": "Tender but still offers resistance"}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove pan from heat. If using, stir in the lemon juice to brighten the flavors.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Transfer to a serving dish. Top with a dollop of cold Greek yogurt and sprinkle with fresh chopped parsley immediately before serving.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT0M", "total_time": "PT15M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Egg-Free", "Low-Carb"], "not_suitable_for": ["Vegans (contains butter and yogurt)"]}', '{"per_serving": {"calories": 102.11, "protein_g": 3.08, "carbohydrates_g": 9.98, "fat_g": 6.37, "saturated_fat_g": 3.89, "trans_fat_g": null, "monounsaturated_fat_g": 1.79, "polyunsaturated_fat_g": 0.29, "fiber_g": 1.56, "sugar_g": 4.63, "sodium_mg": 302.54, "cholesterol_mg": 16.88, "potassium_mg": 313.12, "calcium_mg": 55.12, "iron_mg": 0.64, "magnesium_mg": 26.61, "phosphorus_mg": 70.54, "zinc_mg": 0.47, "vitamin_a_mcg": 64.35, "vitamin_c_mg": 9.12, "vitamin_d_mcg": null, "vitamin_e_mg": 0.25, "vitamin_k_mcg": 46.6, "vitamin_b6_mg": 0.12, "vitamin_b12_mcg": 0.13, "thiamin_mg": 0.07, "riboflavin_mg": 0.11, "niacin_mg": 0.25, "folate_mcg": 21.14, "water_g": 192.51, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Reheat gently; texture may become softer upon reheating.", "duration": "P2D"}, "freezer": {"notes": "Not recommended; cucumbers become mushy when thawed.", "duration": null}, "reheating": "Warm gently in a pan over low heat until just heated through.", "does_not_keep": false}', '[{"name": "Large skillet or frying pan", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Spoon or spatula", "required": true, "alternative": null}]', '[{"symptom": "Dish is watery", "likely_cause": "Seeds were not removed from the cucumbers or pan was overcrowded", "prevention": "Always scrape out seeds; cook on higher heat to evaporate moisture", "fix": "Use a slotted spoon to serve, leaving excess liquid in the pan"}]', '["Removing the seeds is the most critical step. Cucumber seeds contain high water content that will dilute the butter and prevent proper saut\u00e9ing.", "This dish is best served immediately. If allowed to sit too long, the salt will continue to draw moisture out of the cucumbers.", "If you prefer a richer sauce, stir the yogurt directly into the pan after removing it from the heat, but do not let it boil or the yogurt will curdle.", "English cucumbers (hothouse) are preferred for their thinner skin, but standard slicing cucumbers work fine if peeled completely."]', '"Cooked cucumbers, or ''Schmorgurken'', are a classic component of German and Eastern European cuisine, often utilized when gardens produce an abundance of large cucumbers in late summer. While often braised with meat, this lighter saut\u00e9ed version highlights the vegetable''s natural sweetness."', 102.11);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('d030ba73-a09f-41df-bdb3-1ac33c1a96be', 'Smoky Spiced Roasted Eggplant Dip (Baingan Bharta Style)', 'A rustic, smoky, and deeply savory dip featuring roasted eggplant mashed with caramelized onions, tangy tomatoes, and aromatic warming spices. The texture is luscious and chunky, perfect for scooping with flatbreads or crackers.', 'appetizer', 'Indian', 'Intermediate', '["curry powder", "eggplant", "tomato", "appetizer", "vegetarian", "vegan", "dip", "indian", "gluten-free"]', '[{"group_name": "Main Produce", "items": [{"name": "large eggplant", "quantity": 1, "unit": null, "preparation": "whole", "notes": "approx. 500-600g; look for shiny skin and light weight", "substitutions": [], "ingredient_id": "77c14307-dacf-4ab2-85d1-3594bff0ec99", "nutrition_source": "USDA FoodData Central"}, {"name": "red onion", "quantity": 1, "unit": null, "preparation": "finely chopped", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "roma tomatoes", "quantity": 2, "unit": null, "preparation": "chopped", "notes": "approx. 200g total", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "green chili", "quantity": 1, "unit": null, "preparation": "minced", "notes": "Serrano or Jalape\u00f1o; deseed for less heat", "substitutions": [], "ingredient_id": "6cdb0615-378e-4bfa-b76d-f19bbd780e6c", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Aromatics & Spices", "items": [{"name": "vegetable oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["ghee", "mustard oil"], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "ginger paste", "quantity": 10, "unit": "g", "preparation": null, "notes": "or equal amount fresh minced ginger", "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic paste", "quantity": 10, "unit": "g", "preparation": null, "notes": "or 2-3 cloves minced", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "curry powder", "quantity": 7, "unit": "g", "preparation": null, "notes": "high quality Madras style preferred", "substitutions": ["garam masala mixed with coriander powder"], "ingredient_id": "e714e2f1-2295-4e8c-8ccf-65c38381e71e", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika", "quantity": 2, "unit": "g", "preparation": null, "notes": "optional, boosts smokiness if oven-roasting", "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "fresh cilantro", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 230\u00b0C (450\u00b0F). Prick the eggplant all over with a fork to prevent it from bursting. Brush lightly with a small amount of oil.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 230, "fahrenheit": 446}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Place the eggplant on a baking sheet and roast until the skin is charred, blackened, and the flesh is completely collapsed and soft. Turn occasionally for even cooking.", "structured": {"action": "ROAST", "temperature": {"celsius": 230, "fahrenheit": 446}, "duration": "PT40M", "doneness_cues": {"visual": "Skin is charred and blackened", "tactile": "Flesh is collapsed and very soft to the touch"}}, "tips": ["If you have a gas stove, you can roast the eggplant directly over the open flame for 10-15 minutes for a superior smoky flavor."]}, {"step_number": 3, "phase": "prep", "text": "Remove eggplant from the oven. Let it cool until safe to handle. Peel off the charred skin (it''s okay if small black specks remain). Mash the flesh thoroughly in a bowl.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Cooled to room temperature"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Heat oil in a large skillet over medium heat (175\u00b0C/350\u00b0F). Add the chopped onion and saut\u00e9 until golden brown and caramelized.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT8M", "doneness_cues": {"visual": "Onions are golden brown", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the ginger, garlic, and green chili (if using). Saut\u00e9 for 1 minute until fragrant. Stir in the chopped tomatoes, curry powder, smoked paprika, and salt. Cook until the tomatoes break down and the oil begins to separate from the masala paste.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT6M", "doneness_cues": {"visual": "Tomatoes mashed, oil separating from spice paste", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Add the mashed roasted eggplant to the pan. Mix vigorously to combine with the tomato-spice base. Cook for another 5 minutes, stirring frequently, to let the flavors meld and excess moisture evaporate.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": null, "tactile": "Thick, dip-like consistency"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from heat. Stir in fresh cilantro and lemon juice. Taste and adjust salt if needed. Serve warm or at room temperature.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT45M", "total_time": "PT1H10M", "overnight_required": false, "yields": "500g (approx. 2 cups)", "yield_count": 4, "serving_size_g": 125}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Paleo", "Whole30", "Low-Carb"], "not_suitable_for": []}', '{"per_serving": {"calories": 140.69, "protein_g": 2.89, "carbohydrates_g": 16.81, "fat_g": 8.27, "saturated_fat_g": 1.2, "trans_fat_g": null, "monounsaturated_fat_g": 0.2, "polyunsaturated_fat_g": 0.23, "fiber_g": 7.04, "sugar_g": 8.88, "sodium_mg": 495.78, "cholesterol_mg": null, "potassium_mg": 576.65, "calcium_mg": 42.53, "iron_mg": 1.09, "magnesium_mg": 36.73, "phosphorus_mg": 70.57, "zinc_mg": 0.53, "vitamin_a_mcg": 91.81, "vitamin_c_mg": 24.1, "vitamin_d_mcg": null, "vitamin_e_mg": 1.05, "vitamin_k_mcg": 7.7, "vitamin_b6_mg": 0.22, "vitamin_b12_mcg": null, "thiamin_mg": 0.09, "riboflavin_mg": 0.08, "niacin_mg": 1.12, "folate_mcg": 40.56, "water_g": 170.73, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors deepen the next day. Store in an airtight container.", "duration": "P4D"}, "freezer": {"notes": "Not recommended as the texture becomes watery upon thawing.", "duration": null}, "reheating": "Gently warm in a pan over low heat or microwave, adding a splash of water if dry.", "does_not_keep": false}', '[{"name": "Baking sheet", "required": true, "alternative": "Gas stove burner (for open flame roasting)"}, {"name": "Large skillet or frying pan", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}]', '[{"symptom": "Eggplant tastes bitter", "likely_cause": "The eggplant contained too many mature seeds or was undercooked", "prevention": "Choose eggplants that feel light for their size (indicates fewer seeds) and roast until completely collapsed", "fix": "Add a pinch of sugar or extra caramelized onions to balance the bitterness"}, {"symptom": "Dip is too watery", "likely_cause": "Tomatoes or eggplant released too much liquid that wasn''t cooked off", "prevention": "Cook the tomato mixture until oil separates before adding eggplant", "fix": "Continue cooking over medium-high heat while stirring constantly to evaporate excess moisture"}]', '["The key to this dish is the ''bharta'' (mash) texture and smokiness. Do not be afraid to char the eggplant skin thoroughly; the smoky flavor permeates the flesh.", "If using a standard grocery store curry powder, look for ''Madras'' blends which have a better heat and coriander profile than generic yellow powders.", "For the most authentic flavor, replace the vegetable oil with mustard oil, heating it until it smokes slightly before adding onions to remove its raw pungency.", "This dish is actually better served warm or at room temperature rather than piping hot, allowing the spice complexity to shine.", "When selecting an eggplant, press the skin gently; if it bounces back, it is fresh. If the indentation remains, it is old."]', '"This recipe is a variation of Baingan Bharta, a beloved dish from the Punjab region of India and Pakistan. Traditionally roasted over charcoal or cow dung fires in rural villages, the dish transforms the humble eggplant into a rich, smoky delicacy that is a staple of North Indian cuisine."', 140.69);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('d0474610-2fec-458a-99a8-3d38127eadd4', 'Golden Spatchcocked Turkey With Roasted Roots', 'A whole turkey, butterflied for even cooking and perfectly crisp skin, roasted atop a bed of hearty potatoes and carrots that caramelize in the savory drippings. This method ensures juicy meat and rich, garlic-infused vegetables in significantly less time than traditional roasting.', 'dinner', 'American', 'Intermediate', '["five ingredient", "garlic", "root vegetables", "turkey", "dinner", "fall", "winter", "gluten-free", "halal", "kosher", "christmas", "thanksgiving", "roast", "spatchcock"]', '[{"group_name": "Turkey", "items": [{"name": "whole turkey", "quantity": 5000, "unit": "g", "preparation": "thawed, giblets removed", "notes": "Approx. 4-5kg bird fits best on standard pans", "substitutions": [], "ingredient_id": "cdb1c974-22da-499b-8647-8302625c52fb", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": "Or melted duck fat for richer flavor", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 30, "unit": "g", "preparation": null, "notes": "Coarse grain", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 5, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables", "items": [{"name": "garlic", "quantity": 2, "unit": null, "preparation": "heads", "notes": "Cut in half horizontally (approx 100g total)", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "potatoes", "quantity": 1000, "unit": "g", "preparation": "washed and quartered", "notes": "Yukon Gold or similar waxy variety", "substitutions": [], "ingredient_id": "5bf06478-4785-465e-9842-f70a24e22054", "nutrition_source": "USDA FoodData Central"}, {"name": "carrots", "quantity": 500, "unit": "g", "preparation": "peeled and cut into large chunks", "notes": null, "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 220\u00b0C (425\u00b0F). Ensure a rack is positioned in the middle of the oven.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Place the turkey breast-side down on a cutting board. Using poultry shears, cut along both sides of the backbone to remove it entirely. Flip the bird over and press firmly on the breastbone until it cracks and the bird lies flat.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": {"visual": "Backbone removed", "tactile": "Breastbone cracks, bird lies flat"}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Pat the turkey skin extremely dry with paper towels. Rub the entire bird with half of the olive oil and season generously with salt and pepper.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Skin is dry and oiled"}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In a large bowl, toss the potatoes, carrots, and garlic heads with the remaining olive oil, salt, and pepper until coated.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Scatter the vegetables across the baking sheet. Place the flattened turkey directly on top of the vegetables.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Roast for approximately 70-90 minutes. The turkey is done when an instant-read thermometer inserted into the thickest part of the thigh reads 74\u00b0C (165\u00b0F) and the juices run clear.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT1H15M", "doneness_cues": {"visual": "Golden brown skin", "tactile": "Internal temp 74\u00b0C"}}, "tips": ["Rotate the pan halfway through cooking for even browning.", "If the skin browns too quickly, tent loosely with foil."]}, {"step_number": 7, "phase": "finish", "text": "Remove from the oven and transfer the turkey to a carving board. Let it rest for at least 20 minutes before carving. Return the vegetables to the oven if they need more crisping while the meat rests.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT1H30M", "total_time": "PT2H", "overnight_required": false, "yields": "8 servings", "yield_count": 8, "serving_size_g": 450}', '{"flags": ["Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Paleo", "Whole30", "Low-Carb"], "not_suitable_for": ["Vegetarian", "Vegan"]}', '{"per_serving": {"calories": 1703.37, "protein_g": 135.9, "carbohydrates_g": 26.03, "fat_g": 114.11, "saturated_fat_g": 31.74, "trans_fat_g": null, "monounsaturated_fat_g": 5.49, "polyunsaturated_fat_g": 0.94, "fiber_g": 5.3, "sugar_g": 3.09, "sodium_mg": 2006.78, "cholesterol_mg": null, "potassium_mg": 2112.56, "calcium_mg": 159.49, "iron_mg": 10.82, "magnesium_mg": 40.48, "phosphorus_mg": 89.49, "zinc_mg": 0.74, "vitamin_a_mcg": 811.61, "vitamin_c_mg": 33.09, "vitamin_d_mcg": null, "vitamin_e_mg": 1.51, "vitamin_k_mcg": 14, "vitamin_b6_mg": 0.54, "vitamin_b12_mcg": null, "thiamin_mg": 0.1, "riboflavin_mg": 0.1, "niacin_mg": 2, "folate_mcg": 33.61, "water_g": 166.72, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store meat and vegetables in airtight containers.", "duration": "P3D"}, "freezer": {"notes": "Remove meat from bones before freezing. Vegetables may become soft upon thawing.", "duration": "P3M"}, "reheating": "Reheat in a 175\u00b0C oven covered with foil to prevent drying, or steam gently.", "does_not_keep": false}', '[{"name": "Poultry shears", "required": true, "alternative": "Heavy-duty chef''s knife"}, {"name": "Large rimmed baking sheet", "required": true, "alternative": "Roasting pan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Meat thermometer", "required": true, "alternative": null}]', '[{"symptom": "Skin is soggy or not crispy", "likely_cause": "Excess moisture on the skin before roasting", "prevention": "Pat the turkey skin completely dry with paper towels; allow it to sit uncovered in the fridge for 1 hour if time permits", "fix": "Increase oven temp to 230\u00b0C (450\u00b0F) for the last 5-10 minutes (watch closely)"}]', '["Save the removed backbone to make a quick turkey stock or gravy base while the bird roasts.", "Spatchcocking (butterflying) exposes the leg meat to higher heat while keeping the breast lower, helping both finish at the same time.", "Using olive oil instead of butter keeps this recipe Kosher (meat) and Dairy-Free, but duck fat adds a luxurious depth if available."]', '"The centerpiece of American Thanksgiving and British Christmas dinners, the turkey is native to North America. The spatchcock method, dating back to 18th-century Ireland, modernizes the tradition by solving the perennial problem of uneven cooking in large birds."', 1703.37);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('d08a05be-aa5e-471a-b7af-fb914d52dda4', 'Massaman-Style Chicken Curry', 'A luxurious, velvety Thai curry that bridges the gap between bright red curry and rich Indian aromatics. Tender chicken thighs and creamy Yukon Gold potatoes braise in a coconut sauce deepened with toasted cumin, coriander, and warm spices, finished with the classic crunch of roasted peanuts.', 'dinner', 'Thai', 'Intermediate', '["thai", "curry", "cardamom", "chicken thigh", "cinnamon stick", "clove", "coconut milk", "coriander seed", "cumin seed", "fish sauce", "great leftovers", "red curry paste", "stovetop", "tamarind", "yukon gold potato", "dinner", "dairy-free", "gluten-free"]', '[{"group_name": "Spice Blend", "items": [{"name": "coriander seeds", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "cumin seeds", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "green cardamom pods", "quantity": 5, "unit": null, "preparation": "whole", "notes": "approx 1g", "substitutions": [], "ingredient_id": "c56f6cd8-882c-487c-956f-3a91ee1fec07", "nutrition_source": "USDA FoodData Central"}, {"name": "cloves", "quantity": 3, "unit": null, "preparation": "whole", "notes": "approx 0.5g", "substitutions": [], "ingredient_id": "7b3bf68a-3ae9-4dad-91f4-6c7a14ec5e0e", "nutrition_source": "USDA FoodData Central"}, {"name": "cinnamon stick", "quantity": 1, "unit": null, "preparation": "whole", "notes": "approx 5g", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Curry Base", "items": [{"name": "coconut milk", "quantity": 400, "unit": "ml", "preparation": "full fat, divided", "notes": "do not shake can before opening if possible", "substitutions": [], "ingredient_id": "c037ee7e-e3ed-4340-b8fb-d8ad284ba96e", "nutrition_source": "USDA FoodData Central"}, {"name": "red curry paste", "quantity": 60, "unit": "g", "preparation": null, "notes": "adjust based on spice preference", "substitutions": [], "ingredient_id": "e714e2f1-2295-4e8c-8ccf-65c38381e71e", "nutrition_source": "USDA FoodData Central"}, {"name": "chicken stock", "quantity": 120, "unit": "ml", "preparation": null, "notes": "or water", "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Solids", "items": [{"name": "chicken thighs", "quantity": 600, "unit": "g", "preparation": "boneless, skinless, cut into 4cm chunks", "notes": null, "substitutions": [], "ingredient_id": "d7fc1bf9-fc05-429b-bfa6-2ad857cb0bb6", "nutrition_source": "USDA FoodData Central"}, {"name": "yukon gold potatoes", "quantity": 400, "unit": "g", "preparation": "peeled and cut into 4cm chunks", "notes": null, "substitutions": [], "ingredient_id": "90fa399c-54a2-461c-b410-868fba3bac36", "nutrition_source": "Aggregated Public Data"}, {"name": "yellow onion", "quantity": 150, "unit": "g", "preparation": "peeled and cut into thick wedges", "notes": null, "substitutions": [], "ingredient_id": "cc868876-7ceb-46a8-b72a-c3e8a743ee97", "nutrition_source": "Aggregated Public Data"}, {"name": "roasted peanuts", "quantity": 50, "unit": "g", "preparation": "unsalted", "notes": null, "substitutions": [], "ingredient_id": "e69dc0eb-7563-4023-9bc5-a07cc9cdc3d0", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Seasoning", "items": [{"name": "fish sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "95a9a747-50ee-4be0-84be-0dfc96111e2a", "nutrition_source": "Aggregated Public Data"}, {"name": "tamarind concentrate", "quantity": 30, "unit": "ml", "preparation": null, "notes": "sourness varies by brand, add to taste", "substitutions": [], "ingredient_id": "254bdaf4-58fe-4717-9ff5-4ae88119aac3", "nutrition_source": "Aggregated Public Data"}, {"name": "palm sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": "or brown sugar", "substitutions": ["brown sugar"], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Toast the coriander and cumin seeds in a dry small pan over medium heat until fragrant (about 1-2 minutes). Let cool slightly, then grind into a fine powder using a mortar and pestle or spice grinder. Set aside.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Seeds darken slightly", "tactile": "Aromatic"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a heavy-bottomed pot over medium heat, add about 100ml of the thick coconut cream from the top of the can. Cook, stirring occasionally, until the water evaporates and the coconut oil separates (it will look curdled and shiny).", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Oil separates from solids", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the red curry paste and the ground coriander/cumin spice blend to the cracked coconut cream. Fry, stirring constantly, until the paste darkens and becomes very aromatic.", "structured": {"action": "FRY", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Paste darkens, oil turns red", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the chicken thigh chunks to the pot. Stir well to coat the meat in the curry paste mixture and cook for 2 minutes to sear the outside slightly.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour in the remaining coconut milk and the chicken stock. Add the whole cinnamon stick, cloves, cardamom pods, potatoes, onion wedges, and roasted peanuts. Ensure solids are mostly submerged.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Reduce heat to low, cover, and simmer gently until the potatoes are tender and the chicken is cooked through (internal temperature of chicken should reach 74\u00b0C/165\u00b0F).", "structured": {"action": "SIMMER", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": "PT40M", "doneness_cues": {"visual": null, "tactile": "Potatoes pierce easily with a fork"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Stir in the fish sauce, tamarind concentrate, and palm sugar. Simmer for 5 more minutes uncovered to meld flavors. Taste and adjust: it should be a balance of salty, sour, and sweet.", "structured": {"action": "SEASON", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT45M", "total_time": "PT1H15M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 400}', '{"flags": ["Gluten-Free", "Dairy-Free"], "not_suitable_for": ["Peanut allergy", "Shellfish allergy (fish sauce/shrimp paste)"]}', '{"per_serving": {"calories": 696.91, "protein_g": 40.04, "carbohydrates_g": 53.23, "fat_g": 39.75, "saturated_fat_g": 23.9, "trans_fat_g": 0.04, "monounsaturated_fat_g": 8.17, "polyunsaturated_fat_g": 4.6, "fiber_g": 14.66, "sugar_g": 17.5, "sodium_mg": 7727.11, "cholesterol_mg": 141, "potassium_mg": 1347.99, "calcium_mg": 163.22, "iron_mg": 8.43, "magnesium_mg": 147.74, "phosphorus_mg": 532.77, "zinc_mg": 4.31, "vitamin_a_mcg": 11.62, "vitamin_c_mg": 21.36, "vitamin_d_mcg": null, "vitamin_e_mg": 4.26, "vitamin_k_mcg": 20.55, "vitamin_b6_mg": 0.73, "vitamin_b12_mcg": 0.92, "thiamin_mg": 0.22, "riboflavin_mg": 0.34, "niacin_mg": 10.11, "folate_mcg": 38.06, "water_g": 183.66, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors deepen significantly the next day.", "duration": "P3D"}, "freezer": {"notes": "Potatoes may become slightly grainy upon thawing.", "duration": "P1M"}, "reheating": "Reheat gently on the stovetop over medium-low heat until piping hot. Add a splash of water if the sauce has thickened too much.", "does_not_keep": false}', '[{"name": "Heavy-bottomed pot or Dutch oven", "required": true, "alternative": null}, {"name": "Small frying pan", "required": true, "alternative": "Wok"}, {"name": "Mortar and pestle", "required": true, "alternative": "Spice grinder"}]', '[{"symptom": "Curry tastes too sour or too salty", "likely_cause": "Imbalance of the three key seasoning agents (fish sauce, tamarind, sugar)", "prevention": "Add seasoning gradually in the final step, tasting as you go", "fix": "If too sour, add more sugar. If too salty, add a splash of water and sugar. If too sweet, add more tamarind or lime juice."}]', '["Using Red Curry Paste plus dry spices (cumin, coriander, cardamom, cloves) effectively creates a Massaman profile if you cannot find specific Massaman curry paste.", "Cracking the coconut cream (frying it until the oil separates) is a traditional technique that enhances the flavor and color of the curry. If using low-fat milk or homogenized milk that won''t separate, simply fry the paste in 1 tablespoon of coconut oil instead.", "The potatoes and chicken should be cut to roughly the same size to ensure they finish cooking at the same time.", "This curry tastes significantly better the next day as the spices have time to permeate the potatoes and meat."]', '"Massaman curry (Gaeng Massaman) has Persian and Indian roots, evidenced by the use of dried spices like cardamom, cinnamon, and cloves which are rare in other Thai curries. It originated in Southern Thailand near the border with Malaysia and was historically associated with the Muslim community."', 696.91);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('d0b811f2-aaaf-4ef5-94b6-01f1bc95df09', 'Classic Seville Orange Marmalade', 'A quintessential British preserve featuring a crystal-clear amber jelly and tender shreds of bitter orange peel. This recipe balances the sharp, astringent tang of Seville oranges with the sweetness of sugar, creating a complex spread with the perfect set.', 'preserve', 'British', 'Intermediate', '["marmalade", "preserves", "citrus", "seville oranges", "british", "breakfast", "spread", "winter"]', '[{"group_name": "Fruit", "items": [{"name": "seville oranges", "quantity": 1000, "unit": "g", "preparation": "whole, scrubbed clean", "notes": "Approx. 6-8 oranges", "substitutions": [], "ingredient_id": "89aa49e2-278a-4338-8cd0-a5355268564b", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": "whole", "notes": "juice only, approx 50ml", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Base", "items": [{"name": "water", "quantity": 2500, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "granulated sugar", "quantity": 2000, "unit": "g", "preparation": null, "notes": "or preserving sugar", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Juice the Seville oranges and the lemon. Pour the juice into the large pan or bowl used for soaking.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Reserve the pips (seeds) and any pith caught in the juicer. Place these inside a square of muslin cloth. Tie the cloth securely with string to form a bag. This bag contains high levels of pectin essential for the set.", "structured": {"action": "PREPARE_INGREDIENTS", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Slice the orange peel into shreds. Thickness is a matter of preference: fine (1mm), medium (3mm), or thick (5mm). Add the sliced peel to the juice.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Add the water and the muslin bag of pips to the juice and peel. Cover and leave to soak at room temperature overnight (or for at least 8 hours). This softens the peel and begins pectin extraction.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT8H", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Transfer the mixture to a maslin pan. Bring to a boil, then reduce heat and simmer uncovered for about 2 hours, or until the peel is very tender and the contents have reduced by about one-third. The peel must be soft before sugar is added, as sugar hardens the peel.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT2H", "doneness_cues": {"visual": null, "tactile": "Peel disintegrates easily when pressed between fingers"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Remove the muslin bag. Place it in a bowl and allow to cool slightly, then squeeze it firmly (wearing rubber gloves if hot) over the pan to extract every drop of the jelly-like pectin slime. Discard the contents of the bag.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Add the sugar to the pan. Stir over low heat until every grain of sugar has dissolved. Do not boil until the sugar is completely dissolved.", "structured": {"action": "STIR", "temperature": {"celsius": 60, "fahrenheit": 140}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Increase heat to high and bring to a rolling boil. Boil rapidly for 15-20 minutes until the setting point is reached (104.5\u00b0C / 220\u00b0F).", "structured": {"action": "BOIL", "temperature": {"celsius": 105, "fahrenheit": 221}, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Test for set: Place a teaspoon of marmalade on a chilled saucer. Let it cool for a minute, then push it with your finger. If it wrinkles, it is ready. If not, boil for another 5 minutes and re-test.", "structured": {"action": "TEST", "temperature": null, "duration": null, "doneness_cues": {"visual": "Surface wrinkles when pushed", "tactile": null}}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Remove from heat. Skim off any scum from the surface with a spoon. Let the marmalade stand for 15 minutes. This cooling period thickens the liquid slightly so the peel remains suspended rather than floating to the top of the jar.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 11, "phase": "finish", "text": "Ladle into warm, sterilized jars. Cover with wax discs (wax side down) and seal immediately with lids.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT1H30M", "passive_time": "PT14H", "total_time": "PT15H30M", "overnight_required": true, "yields": "2.5kg (approx 6-7 jars)", "yield_count": 7, "serving_size_g": 15}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Low-Sodium"], "not_suitable_for": []}', '{"per_serving": {"calories": 1174.93, "protein_g": 1.05, "carbohydrates_g": 302.09, "fat_g": 0.24, "saturated_fat_g": 0.03, "trans_fat_g": null, "monounsaturated_fat_g": 0.04, "polyunsaturated_fat_g": 0.05, "fiber_g": 0.63, "sugar_g": 297.84, "sodium_mg": 17.64, "cholesterol_mg": null, "potassium_mg": 280.21, "calcium_mg": 26.14, "iron_mg": 0.33, "magnesium_mg": 18.43, "phosphorus_mg": 25.43, "zinc_mg": 0.09, "vitamin_a_mcg": 12.93, "vitamin_c_mg": 46.79, "vitamin_d_mcg": null, "vitamin_e_mg": 0.3, "vitamin_k_mcg": 0.14, "vitamin_b6_mg": 0.05, "vitamin_b12_mcg": null, "thiamin_mg": 0.06, "riboflavin_mg": 0.09, "niacin_mg": 0.29, "folate_mcg": 35.07, "water_g": 488.84, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Once opened.", "duration": "P1M"}, "freezer": {"notes": "Not recommended as sugar structure may crystallize.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Maslin pan", "required": true, "alternative": "Large heavy-bottomed stockpot (8-10L capacity)"}, {"name": "Muslin cloth or cheesecloth", "required": true, "alternative": "Clean cotton handkerchief"}, {"name": "Kitchen string", "required": true, "alternative": null}, {"name": "Sharp knife", "required": true, "alternative": null}, {"name": "Citrus juicer", "required": false, "alternative": null}, {"name": "Sugar thermometer", "required": false, "alternative": "Cold plate test method"}, {"name": "Sterilized jars with lids", "required": true, "alternative": null}, {"name": "Wax discs", "required": false, "alternative": null}, {"name": "Small saucers", "required": true, "alternative": null}]', '[{"symptom": "Marmalade is runny/didn''t set", "likely_cause": "Did not reach setting temperature or insufficient natural pectin", "prevention": "Ensure rolling boil reaches 105\u00b0C/220\u00b0F and perform the wrinkle test accurately", "fix": "Return to pan, add juice of 1 extra lemon or a splash of liquid pectin, and re-boil to setting point"}, {"symptom": "Peel is tough", "likely_cause": "Sugar was added before the peel was fully softened during the simmer phase", "prevention": "Test peel softness thoroughly before adding sugar; once sugar is in, the peel will not soften further", "fix": "Cannot be fixed"}, {"symptom": "Cloudy marmalade", "likely_cause": "Scum was not skimmed off or impurities in sugar", "prevention": "Skim diligently at the end and use refined white sugar", "fix": "Purely cosmetic; safe to eat"}]', '["The 15-minute rest after boiling is crucial. If you jar it immediately, the peel will float to the top; resting allows the viscosity to increase enough to suspend the peel evenly.", "Squeezing the muslin bag of pips is messy but vital. The viscous ''slime'' that comes out is pure pectin, which gives Seville marmalade its superior set.", "Do not reduce the sugar quantity. Sugar acts as the preservative; reducing it will prevent the set and cause the marmalade to spoil.", "Seville oranges are only in season for a short window (usually January-February). You can freeze the whole fruit to make marmalade later in the year."]', '"Seville orange marmalade is a cornerstone of the British breakfast table, dating back to the 17th century. While legend attributes its invention to a Scottish grocer''s wife in Dundee using a cargo of bitter Spanish oranges to save them from waste, it has evolved into a seasonal ritual for home cooks across the UK."', 1174.93);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('d0c887fa-6d77-4be5-8a20-09f196216405', 'Khao Tang Na Tang (Thai Rice Crackers with Creamy Shrimp & Chicken Dip)', 'Crispy, airy rice crackers served with a rich, savory-sweet coconut dip featuring minced chicken, shrimp, and roasted peanuts. This classic Thai appetizer balances the crunch of the rice with a luscious, aromatic sauce infused with coriander root, garlic, and white pepper.', 'appetizer', 'Thai', 'Intermediate', '["chicken", "shrimp", "appetizer", "thai", "party food", "dip"]', '[{"group_name": "Aromatic Paste (Sam Kluer)", "items": [{"name": "coriander roots", "quantity": 4, "unit": null, "preparation": "cleaned and chopped", "notes": "approx 8g; use stems if roots unavailable", "substitutions": [], "ingredient_id": "8c7693be-b538-445c-80f9-3d5bf4c6dcc0", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 5, "unit": null, "preparation": "peeled", "notes": "approx 25g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "white peppercorns", "quantity": 5, "unit": "g", "preparation": "whole", "notes": null, "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dip Base", "items": [{"name": "coconut milk", "quantity": 400, "unit": "ml", "preparation": "full-fat", "notes": null, "substitutions": [], "ingredient_id": "c037ee7e-e3ed-4340-b8fb-d8ad284ba96e", "nutrition_source": "USDA FoodData Central"}, {"name": "chicken breast", "quantity": 150, "unit": "g", "preparation": "minced", "notes": null, "substitutions": [], "ingredient_id": "2b577d04-33ca-4919-938f-bfc8780a3a4b", "nutrition_source": "USDA FoodData Central"}, {"name": "shrimp", "quantity": 150, "unit": "g", "preparation": "peeled, deveined, and minced", "notes": null, "substitutions": [], "ingredient_id": "a6bf7ab3-9b88-4c5b-a2fa-966c40a0e5a7", "nutrition_source": "USDA FoodData Central"}, {"name": "roasted peanuts", "quantity": 100, "unit": "g", "preparation": "coarsely ground", "notes": null, "substitutions": [], "ingredient_id": "ba36d967-879c-446b-ba1e-b1fa36e475db", "nutrition_source": "Aggregated Public Data"}, {"name": "shallots", "quantity": 50, "unit": "g", "preparation": "finely sliced", "notes": null, "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "for saut\u00e9ing", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Seasoning & Garnish", "items": [{"name": "palm sugar", "quantity": 60, "unit": "g", "preparation": "shaved", "notes": "adjust to taste", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "fish sauce", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "95a9a747-50ee-4be0-84be-0dfc96111e2a", "nutrition_source": "Aggregated Public Data"}, {"name": "tamarind paste", "quantity": 15, "unit": "g", "preparation": "concentrate", "notes": "optional for acidity balance", "substitutions": [], "ingredient_id": "c9dd70fa-d98b-459d-bd61-21b5778f1d4a", "nutrition_source": "USDA FoodData Central"}, {"name": "spur chilies (prik chee fa)", "quantity": 2, "unit": null, "preparation": "sliced diagonally", "notes": "red, for garnish", "substitutions": [], "ingredient_id": "5080eb9a-d555-4558-94e5-d5700e96ff9b", "nutrition_source": "Aggregated Public Data"}, {"name": "coriander leaves", "quantity": 5, "unit": "g", "preparation": "picked", "notes": null, "substitutions": [], "ingredient_id": "8c7693be-b538-445c-80f9-3d5bf4c6dcc0", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Rice Crackers", "items": [{"name": "dried rice cakes (uncooked khao tang)", "quantity": 200, "unit": "g", "preparation": null, "notes": "available in Asian markets", "substitutions": [], "ingredient_id": "835c75bb-29cf-4adc-ad5f-8e8764110647", "nutrition_source": "Aggregated Public Data"}, {"name": "neutral oil", "quantity": 500, "unit": "ml", "preparation": null, "notes": "for deep frying", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}]}]', '[{"step_number": 1, "phase": "prep", "text": "Make the ''Sam Kluer'' paste: Pound white peppercorns in a mortar until fine. Add coriander roots and garlic cloves, pounding until a smooth, uniform paste forms.", "structured": {"action": "POUND", "temperature": null, "duration": null, "doneness_cues": {"visual": "Smooth paste", "tactile": "Uniform consistency"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat 15ml vegetable oil in a wok or saucepan over medium heat. Add the pounded paste and sliced shallots. Saut\u00e9 until the shallots soften and the mixture is highly aromatic.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT3M", "doneness_cues": {"visual": "Shallots are translucent", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the minced chicken and shrimp to the pan. Stir vigorously to break up any clumps and cook until the meat turns opaque.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Meat is opaque", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour in the coconut milk, then season with palm sugar, fish sauce, and tamarind paste. Bring to a gentle simmer. Add the coarsely ground peanuts and stir to combine.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT10M", "doneness_cues": {"visual": "Sauce has thickened slightly and turned a rich golden color", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Reduce heat to low and let the dip simmer gently until it reaches a coating consistency. Taste and adjust seasoning; it should be predominantly sweet and salty with a hint of nutty richness. Remove from heat.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": null, "tactile": "Coats the back of a spoon"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Clean the wok or use a separate pot. Heat frying oil to 190\u00b0C/375\u00b0F. Fry the dried rice cakes in batches. They will expand instantly. Flip once and remove immediately (within 5-10 seconds) to drain on a wire rack.", "structured": {"action": "FRY", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": {"visual": "Puffed, white, and crispy", "tactile": null}}, "tips": ["Do not overcrowd the oil; the crackers expand significantly."]}, {"step_number": 7, "phase": "assemble", "text": "Transfer the warm dip to a serving bowl. Garnish with sliced red spur chilies and coriander leaves. Serve alongside the crispy rice crackers for dipping.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT0M", "total_time": "PT45M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 180}', '{"flags": ["Gluten-Free", "Dairy-Free", "Pescatarian"], "not_suitable_for": ["People with peanut allergies", "People with shellfish allergies"]}', '{"per_serving": {"calories": 428.34, "protein_g": 15.86, "carbohydrates_g": 46.87, "fat_g": 21.42, "saturated_fat_g": 15.13, "trans_fat_g": 0.03, "monounsaturated_fat_g": 1.67, "polyunsaturated_fat_g": 0.72, "fiber_g": 2.78, "sugar_g": 14, "sodium_mg": 400.8, "cholesterol_mg": 56.25, "potassium_mg": 407.19, "calcium_mg": 47.67, "iron_mg": 3.66, "magnesium_mg": 59.02, "phosphorus_mg": 203.11, "zinc_mg": 1.37, "vitamin_a_mcg": 157.85, "vitamin_c_mg": 14.04, "vitamin_d_mcg": 0.1, "vitamin_e_mg": 0.18, "vitamin_k_mcg": 0.27, "vitamin_b6_mg": 0.24, "vitamin_b12_mcg": 0.09, "thiamin_mg": 0.06, "riboflavin_mg": 0.04, "niacin_mg": 3.08, "folate_mcg": 15.06, "water_g": 94.01, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store dip and crackers in separate airtight containers. Crackers will lose crispness if refrigerated; store at room temp if possible.", "duration": "P3D"}, "freezer": {"notes": "Dip freezes well. Thaw and reheat gently.", "duration": "P1M"}, "reheating": "Reheat dip over low heat or microwave until warm. Crackers do not reheat well; fry fresh batch if stale.", "does_not_keep": false}', '[{"name": "Mortar and pestle", "required": true, "alternative": "Small food processor"}, {"name": "Wok or deep frying pan", "required": true, "alternative": null}, {"name": "Wire rack", "required": true, "alternative": null}, {"name": "Thermometer", "required": false, "alternative": null}, {"name": "Spider strainer or slotted spoon", "required": true, "alternative": null}]', '[{"symptom": "Rice crackers are tough or hard, not airy", "likely_cause": "Oil temperature was too low", "prevention": "Ensure oil reaches 190\u00b0C/375\u00b0F before adding dried rice cakes", "fix": "Heat oil properly and try again with a test piece; cannot fix already fried crackers"}, {"symptom": "Dip is too thin/watery", "likely_cause": "Coconut milk was low fat or sauce wasn''t reduced enough", "prevention": "Use full-fat coconut milk", "fix": "Simmer longer to evaporate moisture, or add more ground peanuts to thicken"}]', '["The foundation of Thai flavor is the ''Sam Kluer'' (Three Buddies): coriander root, garlic, and white pepper. Do not skip the white pepper; black pepper changes the flavor profile entirely.", "If you cannot find dried rice cakes (raw khao tang), you can dehydrate cooked jasmine rice in a low oven (80\u00b0C) for 3-4 hours until rock hard before frying.", "Roast raw peanuts yourself in a dry pan before grinding for a vastly superior aroma compared to pre-roasted store-bought peanuts.", "The consistency of the dip should be similar to a Bolognese sauce\u2014thick enough to sit on top of the cracker without running off immediately."]', '"Khao Tang Na Tang is a traditional Royal Thai appetizer dating back to the Ayutthaya period. Originally a way to use leftover rice (sun-dried to preserve it), it was elevated with a rich, coconut-based dipping sauce (''Na Tang'') often reserved for guests and ceremonies. The balance of salty, sweet, and nutty flavors represents the harmony sought in central Thai cuisine."', 428.34);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('d2c6c5b8-ea47-48c2-af3e-19886d8a4e37', 'Roasted Butternut Squash & Shallots with Date-Cranberry Agrodolce', 'Golden, caramelized cubes of roasted squash and jammy shallots provide a savory base for a festive, jewel-toned relish. The sweetness of Medjool dates and the tart pop of cranberries are balanced by salty, creamy feta in this vibrant side dish.', 'side dish', 'Modern Mediterranean', 'Easy', '["vegetable", "squash", "relish", "festive", "side", "autumn", "holiday", "vegetarian"]', '[{"group_name": "Roasted Vegetables", "items": [{"name": "butternut squash", "quantity": 1000, "unit": "g", "preparation": "peeled and cubed into 2.5cm pieces", "notes": "approx. 1 large squash", "substitutions": [], "ingredient_id": "7f8919a5-2de5-47ce-91b2-d2a999ea11f7", "nutrition_source": "USDA FoodData Central"}, {"name": "shallots", "quantity": 300, "unit": "g", "preparation": "peeled and halved lengthwise", "notes": "keep root intact to hold layers together", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme leaves", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 6, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste (min 1g)", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Date & Cranberry Relish", "items": [{"name": "medjool dates", "quantity": 80, "unit": "g", "preparation": "pitted and roughly chopped", "notes": "approx. 4-5 dates", "substitutions": [], "ingredient_id": "657c170c-11cc-41f7-a980-050a218a088e", "nutrition_source": "USDA FoodData Central"}, {"name": "dried cranberries", "quantity": 40, "unit": "g", "preparation": null, "notes": "unsweetened preferred", "substitutions": [], "ingredient_id": "788f186b-788f-4fcd-aff0-ab8983926e97", "nutrition_source": "USDA FoodData Central"}, {"name": "apple cider vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "orange zest", "quantity": null, "unit": null, "preparation": null, "notes": "zest of half an orange", "substitutions": [], "ingredient_id": "c1a067e6-674f-4f68-9fe9-3eda4b074356", "nutrition_source": "Aggregated Public Data"}, {"name": "extra virgin olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "chili flakes", "quantity": null, "unit": null, "preparation": null, "notes": "pinch, optional for heat", "substitutions": [], "ingredient_id": "a4bf8b34-30b2-4d24-a120-b5b191811f64", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Topping", "items": [{"name": "feta cheese", "quantity": 100, "unit": "g", "preparation": "crumbled", "notes": "Greek feta preferred", "substitutions": [], "ingredient_id": "a9a8605c-3bf2-4ca3-8c58-80e87aff7cd8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 220\u00b0C (425\u00b0F). Prepare the vegetables: peel and cube the squash into uniform 2.5cm (1 inch) pieces. Peel the shallots and cut them in half lengthwise.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, toss the squash and shallots with olive oil, thyme, salt, and black pepper until thoroughly coated.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Spread the vegetables in a single, even layer on a rimmed baking sheet. Do not overcrowd. Roast for 30-35 minutes, flipping halfway through, until the squash is tender and caramelized at the edges.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT35M", "doneness_cues": {"visual": "Squash edges browned, shallots softened", "tactile": "Fork-tender"}}, "tips": ["Use two baking sheets if necessary to ensure vegetables roast rather than steam."]}, {"step_number": 4, "phase": "prep", "text": "While vegetables roast, prepare the relish. In a small bowl, combine chopped dates, dried cranberries, apple cider vinegar, orange zest, extra virgin olive oil, and parsley. Stir well and let sit for at least 10 minutes to allow flavors to meld and fruits to plump slightly.", "structured": {"action": "MACERATE", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Transfer the hot roasted vegetables to a serving platter. Spoon the date and cranberry relish evenly over the top.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Garnish immediately with crumbled feta cheese. The residual heat from the vegetables will slightly warm the cheese without melting it completely.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT35M", "total_time": "PT1H", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 220}', '{"flags": ["Vegetarian", "Gluten-Free", "Egg-Free", "Soy-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 310.83, "protein_g": 4.97, "carbohydrates_g": 40.95, "fat_g": 16.44, "saturated_fat_g": 4.01, "trans_fat_g": null, "monounsaturated_fat_g": 9.94, "polyunsaturated_fat_g": 1.51, "fiber_g": 5.72, "sugar_g": 19.53, "sodium_mg": 589.61, "cholesterol_mg": 14.83, "potassium_mg": 789.17, "calcium_mg": 190.98, "iron_mg": 1.89, "magnesium_mg": 75.12, "phosphorus_mg": 137.34, "zinc_mg": 0.92, "vitamin_a_mcg": 917.72, "vitamin_c_mg": 42.99, "vitamin_d_mcg": 0.07, "vitamin_e_mg": 4.4, "vitamin_k_mcg": 38.33, "vitamin_b6_mg": 0.42, "vitamin_b12_mcg": 0.28, "thiamin_mg": 0.23, "riboflavin_mg": 0.2, "niacin_mg": 2.52, "folate_mcg": 64.92, "water_g": 208.72, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store relish and roasted vegetables separately if possible to maintain texture.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; squash becomes mushy and feta texture degrades.", "duration": null}, "reheating": "Reheat vegetables in a 180\u00b0C oven for 10 minutes; add relish and cheese after heating.", "does_not_keep": false}', '[{"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Large rimmed baking sheet", "required": true, "alternative": "Two smaller roasting pans"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Vegetable peeler", "required": true, "alternative": null}]', '[{"symptom": "Squash is soggy rather than browned", "likely_cause": "The baking sheet was overcrowded, causing the vegetables to steam instead of roast", "prevention": "Use two baking sheets or roast in batches to ensure air circulation around each piece", "fix": "Increase oven temp to 230\u00b0C/450\u00b0F and roast for 5 more minutes on the convection setting if available"}]', '["Cut the butternut squash into uniform sizes to ensure even cooking; mixing small and large chunks will result in some being mushy while others are hard.", "For the best flavor, buy block feta in brine and crumble it yourself. Pre-crumbled feta often contains anti-caking agents that affect the texture.", "The relish relies on the balance of acid and sugar. If your dates are very sweet, add a squeeze of fresh lemon juice to the relish to sharpen the flavor profile.", "If preparing ahead for a dinner party, roast the vegetables 90% of the way, then blast them in the oven for 5-8 minutes right before serving to reheat and crisp up."]', '"This dish exemplifies modern Mediterranean cooking, where the sweetness of dried fruits (common in North African tagines) meets the European tradition of roasted root vegetables. The contrast of warm, earthy squash with bright, acidic fruit and briny cheese makes it a staple profile in contemporary harvest cuisine."', 310.83);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('d332123d-a429-4f1a-b457-bcb09594075f', 'Kentucky Bourbon Pecan Pie', 'A sophisticated elevation of the Southern classic. Toasted pecans are suspended in a rich, dark custard infused with Kentucky bourbon and vanilla bean, set atop a buttery, blind-baked pastry crust to ensure crispness.', 'dessert', 'American', 'Intermediate', '["southern", "bourbon", "corn syrup", "egg", "pecan", "pecan pie", "dessert", "fall", "thanksgiving"]', '[{"group_name": "P\u00e2te Bris\u00e9e (Crust)", "items": [{"name": "all-purpose flour", "quantity": 170, "unit": "g", "preparation": "chilled", "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "sugar", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "ice water", "quantity": 60, "unit": "ml", "preparation": null, "notes": "approximate, use just enough to bind", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Bourbon Filling", "items": [{"name": "pecan halves", "quantity": 200, "unit": "g", "preparation": "raw", "notes": null, "substitutions": [], "ingredient_id": "a5c5ee79-2bcd-4ab2-aed5-b09d0a3df4b5", "nutrition_source": "USDA FoodData Central"}, {"name": "large eggs", "quantity": 3, "unit": null, "preparation": null, "notes": "approx 150g total without shell, room temperature", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "dark corn syrup", "quantity": 300, "unit": "g", "preparation": null, "notes": "provides viscosity and prevents crystallization", "substitutions": [], "ingredient_id": "afcbec4e-1b32-41b6-825d-453531fdd55e", "nutrition_source": "USDA FoodData Central"}, {"name": "light brown sugar", "quantity": 100, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": "melted and cooled", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "bourbon whiskey", "quantity": 30, "unit": "ml", "preparation": null, "notes": "use a quality brand like Maker''s Mark or Woodford Reserve", "substitutions": [], "ingredient_id": "6b50db10-fa85-4831-90f9-6cf2c78546c2", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "flaked sea salt preferred", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pulse flour, sugar, and salt in a food processor. Add cold cubed butter and pulse briefly until mixture resembles coarse meal with pea-sized butter bits remaining.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Drizzle in ice water one tablespoon at a time, pulsing until the dough just begins to hold together when pinched. Form into a disk, wrap in plastic, and refrigerate for at least 30 minutes.", "structured": {"action": "REST", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Preheat oven to 190\u00b0C (375\u00b0F). Roll dough out on a floured surface to a 30cm (12-inch) circle. Transfer to pie dish, trim overhang, and crimp edges. Freeze for 10 minutes to set the shape.", "structured": {"action": "ROLL", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Line the crust with parchment paper and fill with pie weights. Par-bake (blind bake) for 15 minutes. Remove weights and paper, then bake for another 5 minutes until the bottom looks dry. Lower oven temperature to 175\u00b0C (350\u00b0F).", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "While the crust cools slightly, spread pecans on a baking sheet and toast in the oven for 5-7 minutes until fragrant. Set aside to cool.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "In a large bowl, whisk together eggs, dark corn syrup, brown sugar, melted butter, bourbon, vanilla, and salt until completely smooth and emulsified.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Arrange the toasted pecans in the bottom of the par-baked crust. Pour the filling mixture evenly over the pecans. The nuts will rise to the surface.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Bake at 175\u00b0C (350\u00b0F) for 40-50 minutes. The pie is done when the edges are set and puffed, but the center still has a slight wobble (like gelatin) when gently shaken. It should not be liquid.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT45M", "doneness_cues": {"visual": "Edges puffed, center wobbles like gelatin", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove from oven and place on a wire rack. Cool completely for at least 2 hours before slicing. This rest period is mandatory for the filling to set.", "structured": {"action": "COOL", "temperature": null, "duration": "PT2H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT2H", "total_time": "PT2H45M", "overnight_required": false, "yields": "1 9-inch pie", "yield_count": 8, "serving_size_g": 135}', '{"flags": ["Vegetarian"], "not_suitable_for": ["Nut allergies", "Gluten intolerance", "Alcohol restrictions"]}', '{"per_serving": {"calories": 606.32, "protein_g": 7.05, "carbohydrates_g": 62.65, "fat_g": 37.73, "saturated_fat_g": 13.21, "trans_fat_g": 0.01, "monounsaturated_fat_g": 16.02, "polyunsaturated_fat_g": 6.51, "fiber_g": 2.97, "sugar_g": 43.76, "sodium_mg": 382.39, "cholesterol_mg": 116.78, "potassium_mg": 191.46, "calcium_mg": 54.04, "iron_mg": 1.45, "magnesium_mg": 41.97, "phosphorus_mg": 139.61, "zinc_mg": 1.56, "vitamin_a_mcg": 180.38, "vitamin_c_mg": 0.28, "vitamin_d_mcg": 0.38, "vitamin_e_mg": 1.07, "vitamin_k_mcg": 2.53, "vitamin_b6_mg": 0.1, "vitamin_b12_mcg": 0.21, "thiamin_mg": 0.2, "riboflavin_mg": 0.14, "niacin_mg": 0.61, "folate_mcg": 20.62, "water_g": 37.82, "alcohol_g": 0.43, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Cover loosely with foil or plastic wrap once fully cooled.", "duration": "P4D"}, "freezer": {"notes": "Wrap tightly in plastic wrap and then foil. Thaw in refrigerator overnight.", "duration": "P2M"}, "reheating": "Serve at room temperature or warm gently in a 150\u00b0C oven for 10 minutes.", "does_not_keep": false}', '[{"name": "9-inch pie dish", "required": true, "alternative": "9-inch tart pan"}, {"name": "Food processor", "required": false, "alternative": "Pastry blender and mixing bowl"}, {"name": "Rolling pin", "required": true, "alternative": null}, {"name": "Pie weights", "required": true, "alternative": "Dried beans or uncooked rice"}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Wire rack", "required": true, "alternative": null}]', '[{"symptom": "Filling is runny after cooling", "likely_cause": "Underbaked pie", "prevention": "Ensure the internal temperature reaches 93\u00b0C (200\u00b0F) or the center jiggle is firm, not wave-like.", "fix": "Refrigerate; cold pecan pie sets firmer than room temperature pie."}, {"symptom": "Crust is soggy", "likely_cause": "Skipped blind baking or filling sat in raw crust too long", "prevention": "Always par-bake the crust for custard pies.", "fix": "Cannot be fixed."}, {"symptom": "Crust edges are burning before filling sets", "likely_cause": "High sugar content in dough or oven hot spots", "prevention": "Use a pie shield or foil ring around the edges after 20 minutes of baking.", "fix": "Cover edges with foil immediately."}]', '["Toasting the pecans before adding them to the filling releases their natural oils and ensures they stay crisp in the liquid custard.", "Dark corn syrup is preferred over light for its molasses content, which complements the bourbon notes.", "Do not skip the cooling step. Pecan pie filling is essentially a sugar-egg custard; cutting it hot will result in a landslide on the plate.", "For clean slices, run your knife under hot water and wipe dry between cuts.", "If using salted butter, reduce the added salt in the filling to 1g."]', '"Pecan pie is a quintessential dish of the American South, popularized in the mid-20th century by Karo syrup recipes, though its roots lie in the abundance of native pecan groves in states like Texas and Georgia. The addition of bourbon is a modern nod to Kentucky''s distilling heritage, adding a mature complexity to the sugar-forward dessert."', 606.32);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('d332a7d2-37cb-44fd-b2ae-9d4eceb1f572', 'Velvet Rum Blender Mousse', 'A luxuriously smooth and airy chocolate mousse prepared in minutes using a high-speed blender. The heat of the cream gently cooks the base while melting the chocolate, resulting in a dense yet spoonable texture with a warming, sophisticated dark rum finish.', 'dessert', 'French', 'Easy', '["mousse", "quick", "dessert", "gluten-free", "french", "blender", "dinner party"]', '[{"group_name": "Mousse Base", "items": [{"name": "semi-sweet chocolate chips or chopped couverture (55-70%)", "quantity": 170, "unit": "g", "preparation": "small pieces", "notes": "Do not use large blocks without chopping first", "substitutions": [], "ingredient_id": "50bb3cbf-ad86-434d-b084-2da797a26b02", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream (35% fat)", "quantity": 180, "unit": "ml", "preparation": "cold prior to heating", "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "room temperature", "notes": "large, approx 100g total. Pasteurized suggested.", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "granulated sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "dark aged rum", "quantity": 30, "unit": "ml", "preparation": null, "notes": "Use a quality sipping rum for best flavor", "substitutions": [], "ingredient_id": "55a7e674-08da-4bf6-9f1b-d58b826126eb", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "large pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish (Optional)", "items": [{"name": "whipped cream", "quantity": null, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5015e61b-c5ee-48a1-82ce-6d78e35896cb", "nutrition_source": "USDA FoodData Central"}, {"name": "chocolate shavings", "quantity": null, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "08395d12-1a43-46f7-b602-36c2d07ce259", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine the chocolate chips, sugar, room temperature eggs, dark rum, vanilla extract, and salt in the blender canister. Pulse once or twice just to combine the solids.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Eggs must be at room temperature to prevent the hot cream from cooling too rapidly, which would fail to melt the chocolate."]}, {"step_number": 2, "phase": "cook", "text": "Heat the heavy cream in a small saucepan over medium heat until it reaches a vigorous simmer (approx. 85\u00b0C/185\u00b0F). Small bubbles should appear around the edges, but do not let it boil over.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "With the blender running on low speed, carefully remove the lid plug and pour the hot cream into the mixture in a steady stream. Increase speed to high immediately after pouring.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Blend on high for 45-60 seconds until the mixture is completely smooth, glossy, and slightly aerated. The friction and heat will melt the chocolate and thicken the eggs.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Glossy, uniform color, no visible chocolate flecks", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Immediately pour the mixture into ramekins or serving glasses. Tap the glasses gently on the counter to release large air bubbles.", "structured": {"action": "POUR", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Refrigerate for at least 2 hours to allow the cocoa butter to set and the texture to firm up into a mousse.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT2H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT2H", "total_time": "PT2H15M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 125}', '{"flags": ["Gluten-Free", "Vegetarian"], "not_suitable_for": ["Pregnant women (raw/undercooked eggs)", "Immunocompromised individuals (raw/undercooked eggs)", "Children (alcohol content)"]}', '{"per_serving": {"calories": 527.16, "protein_g": 7.21, "carbohydrates_g": 41.83, "fat_g": 35.56, "saturated_fat_g": 14.23, "trans_fat_g": 0.57, "monounsaturated_fat_g": 6.53, "polyunsaturated_fat_g": 1.37, "fiber_g": 3.05, "sugar_g": 35.3, "sodium_mg": 146.61, "cholesterol_mg": 153.73, "potassium_mg": 307.63, "calcium_mg": 73.22, "iron_mg": 1.41, "magnesium_mg": 18.68, "phosphorus_mg": 111.77, "zinc_mg": 0.65, "vitamin_a_mcg": 248.64, "vitamin_c_mg": 0.27, "vitamin_d_mcg": 1.27, "vitamin_e_mg": 0.8, "vitamin_k_mcg": 2.2, "vitamin_b6_mg": 0.07, "vitamin_b12_mcg": 0.34, "thiamin_mg": 0.03, "riboflavin_mg": 0.22, "niacin_mg": 0.11, "folate_mcg": 13.93, "water_g": 53.42, "alcohol_g": 0.43, "caffeine_mg": 5.38}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Cover tightly with plastic wrap touching the surface to prevent skin formation.", "duration": "P3D"}, "freezer": {"notes": "Texture degrades significantly upon thawing.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "High-speed blender", "required": true, "alternative": null}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Ramekins or serving glasses", "required": true, "alternative": null}, {"name": "Spatula", "required": true, "alternative": null}]', '[{"symptom": "Grainy or speckled texture", "likely_cause": "The cream was not hot enough to melt the chocolate fully, or the chocolate pieces were too large.", "prevention": "Ensure cream is simmering vigorously and chocolate is chopped small.", "fix": "Pour mixture back into saucepan, warm gently over very low heat stirring constantly until smooth, then re-blend."}, {"symptom": "Mousse is too runny after chilling", "likely_cause": "Not enough chocolate solids relative to liquid, or low-quality chocolate used.", "prevention": "Use baking chocolate bars or high-quality couverture, not chocolate chips containing stabilizers if possible.", "fix": "Cannot be fixed once chilled; serve as a pudding or tart filling."}]', '["Use ''sipping quality'' rum (like an aged dark rum or agricole); since this recipe doesn''t bake the alcohol off, the raw flavor profile of the spirit is prominent.", "For the safest result, use pasteurized shell eggs, as the heat from the cream cooks the eggs slightly but does not hold them at pasteurization temperatures for the required duration.", "If you prefer a mocha variation, dissolve 1 teaspoon of instant espresso powder into the hot cream before blending.", "Texture control: For a denser, pot-de-cr\u00e8me style, reduce cream by 30ml. For a lighter foam, fold in whipped cream after the blending step (once cooled slightly)."]', '"While Chocolate Mousse is a cornerstone of French patisserie traditionally made by folding beaten egg whites into chocolate (mousse au chocolat traditionally meaning ''foam''), this blender technique gained popularity in mid-20th century American home cooking for its reliability and speed, bridging the gap between a custard and an aerated mousse."', 527.16);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('d460fde0-bfde-4b8f-9d86-47a474067a88', 'Baked Lemon Thyme Cod and Chips', 'A lighter, oven-baked interpretation of the British seaside classic. Flaky cod fillets are crusted in zesty lemon and aromatic thyme panko crumbs, served alongside crisp, golden potato wedges roasted with olive oil rather than deep-fried.', 'dinner', 'British', 'Easy', '["fish", "chips", "baked", "lighter", "cod", "lemon", "thyme", "healthy", "british"]', '[{"group_name": "Chips", "items": [{"name": "floury potatoes (such as maris piper or russet)", "quantity": 800, "unit": "g", "preparation": "scrubbed and cut into 2cm thick wedges", "notes": "peeling is optional", "substitutions": [], "ingredient_id": "a7db25be-476c-48fe-8cb8-2ea66fb91587", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "divided use", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "approx 1 tsp total", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Fish", "items": [{"name": "cod fillets", "quantity": 600, "unit": "g", "preparation": "skinless, pat dried", "notes": "4 fillets approx 150g each", "substitutions": ["haddock", "pollock", "hake"], "ingredient_id": "229ccaef-c763-440b-b44f-6e22222d3fd1", "nutrition_source": "USDA FoodData Central"}, {"name": "panko breadcrumbs", "quantity": 60, "unit": "g", "preparation": null, "notes": "provides superior crunch compared to standard crumbs", "substitutions": ["fresh wholemeal breadcrumbs"], "ingredient_id": "84fbc204-4457-40ed-83c1-3e5a7bcd8f23", "nutrition_source": "Aggregated Public Data"}, {"name": "plain flour", "quantity": 40, "unit": "g", "preparation": null, "notes": "for dredging", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "beaten", "notes": "approx 100g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": "zested", "notes": null, "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme leaves", "quantity": 4, "unit": "g", "preparation": "picked from stems", "notes": null, "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 220\u00b0C/425\u00b0F (200\u00b0C fan). Line two large baking sheets with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Rinse the potato wedges under cold water to remove excess starch, then pat them thoroughly dry with a clean kitchen towel. This step is crucial for crispiness.", "structured": {"action": "PAT_DRY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Toss the dried potatoes with 20ml of olive oil, salt, and pepper directly on one of the baking sheets. Spread them out in a single layer so they aren''t touching.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Bake the chips on the top rack for 20 minutes while you prepare the fish. They need a head start as they take longer to cook.", "structured": {"action": "BAKE", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Set up a breading station: Place flour in one shallow bowl. In a second bowl, place beaten eggs. In a third bowl, mix the panko breadcrumbs, lemon zest, thyme leaves, remaining 10ml olive oil, and a pinch of salt.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "Dredge each cod fillet in flour (shaking off excess), dip into the egg wash, and then press firmly into the lemon-thyme crumb mixture to coat evenly.", "structured": {"action": "BREAD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "After the chips have baked for 20 minutes, remove the tray and flip them. Place the breaded fish fillets on the second prepared baking sheet.", "structured": {"action": "ROAST", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Return the chips to the oven and place the fish tray on the rack below them. Bake both for another 12-15 minutes until the fish is opaque and flakes easily (internal temp 63\u00b0C/145\u00b0F) and chips are golden brown.", "structured": {"action": "BAKE", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": "Fish coating golden, flesh opaque", "tactile": "Fish flakes easily with a fork"}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Serve immediately with extra lemon wedges and fresh peas if desired.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT35M", "total_time": "PT1H", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Pescatarian", "Dairy-Free", "Nut-Free", "Soy-Free", "Peanut-Free"], "not_suitable_for": ["Keto", "Paleo"]}', '{"per_serving": {"calories": 480.43, "protein_g": 37.34, "carbohydrates_g": 57.72, "fat_g": 11.43, "saturated_fat_g": 2.1, "trans_fat_g": 0.01, "monounsaturated_fat_g": 6.54, "polyunsaturated_fat_g": 1.76, "fiber_g": 4.19, "sugar_g": 2.95, "sodium_mg": 749.54, "cholesterol_mg": 157.5, "potassium_mg": 1537.64, "calcium_mg": 76.62, "iron_mg": 3.42, "magnesium_mg": 102.94, "phosphorus_mg": 479.66, "zinc_mg": 1.68, "vitamin_a_mcg": 60.66, "vitamin_c_mg": 25.76, "vitamin_d_mcg": 1.85, "vitamin_e_mg": 2.36, "vitamin_k_mcg": 8.78, "vitamin_b6_mg": 1.11, "vitamin_b12_mcg": 1.59, "thiamin_mg": 0.31, "riboflavin_mg": 0.3, "niacin_mg": 5.36, "folate_mcg": 55.68, "water_g": 318.84, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Coating will lose crispness; reheat in oven or air fryer.", "duration": "P2D"}, "freezer": {"notes": "Not recommended as texture suffers significantly.", "duration": null}, "reheating": "Reheat in a 180\u00b0C/350\u00b0F oven for 10-15 minutes to restore crunch.", "does_not_keep": false}', '[{"name": "Large baking sheets", "required": true, "alternative": "Roasting pans"}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Shallow bowls", "required": true, "alternative": "Deep plates (for breading station)"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Microplane or zester", "required": true, "alternative": "Fine side of box grater"}]', '[{"symptom": "Chips are soggy", "likely_cause": "Potatoes were too wet before oiling or the pan was overcrowded", "prevention": "Dry potatoes thoroughly after rinsing and ensure they are in a single layer with space between them", "fix": "Spread onto a second tray and bake for 5-10 extra minutes, or use the broiler/grill briefly (watch closely)"}]', '["Mixing a small amount of oil into the breadcrumbs before coating the fish helps the panko brown evenly in the oven, mimicking the color of fried fish.", "For the fluffiest chips, use a floury potato variety like Maris Piper, King Edward, or Russet. Waxy potatoes will not crisp up as well.", "If you want even more flavor in the crust, add a teaspoon of garlic powder or onion granules to the panko mixture."]', '"Fish and chips is the quintessential British comfort food, traditionally deep-fried in beef dripping and served wrapped in newspaper. This version respects the flavor profile\u2014mild white fish and hearty potatoes\u2014but adapts the cooking method for a lighter, home-kitchen-friendly meal that retains the beloved crunch."', 480.43);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('d4c7da76-e148-49e6-ad0e-bc12e353f10d', 'Summer Garden Cucumber and Tomato Salad', 'A vibrant, crisp salad celebrating the peak of summer produce. Finely diced Persian cucumbers and vine-ripened tomatoes are tossed with fresh herbs and a bright lemon vinaigrette. The texture is uniformly crunchy, offering a refreshing palate cleanser.', 'salad', 'Mediterranean', 'Easy', '["cucumber", "parsley", "tomato", "side dish", "summer", "vegan", "raw", "mediterranean"]', '[{"group_name": "Vegetables", "items": [{"name": "persian cucumbers", "quantity": 350, "unit": "g", "preparation": "small dice (0.5cm)", "notes": "about 4-5 small cucumbers; English cucumbers also work", "substitutions": [], "ingredient_id": "84cc106c-269c-44b7-af59-33b3c121e483", "nutrition_source": "USDA FoodData Central"}, {"name": "vine-ripened tomatoes", "quantity": 350, "unit": "g", "preparation": "seeded and small dice (0.5cm)", "notes": "about 3 medium tomatoes", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "red onion", "quantity": 60, "unit": "g", "preparation": "fine brunoise", "notes": "approx. 1/4 small onion", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Herbs & Dressing", "items": [{"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "finely chopped", "notes": "leaves only, no stems", "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh mint", "quantity": 5, "unit": "g", "preparation": "chiffonade", "notes": "optional but recommended", "substitutions": [], "ingredient_id": "213e3d3b-d332-45a9-b35e-23ee29a27173", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 30, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": "high quality", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 4, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the finely diced red onion in a small bowl of ice water. Let it soak for 10 minutes. This removes the harsh sulfurous bite and crisps the texture.", "structured": {"action": "SOAK", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": ["If you enjoy the sharp bite of raw onion, you can skip this step."]}, {"step_number": 2, "phase": "prep", "text": "While onions soak, dice the cucumbers and tomatoes into uniform 0.5cm cubes. For the tomatoes, remove the watery seeds before dicing to prevent a soggy salad.", "structured": {"action": "DICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "assemble", "text": "Drain the onions thoroughly and pat dry. Combine cucumbers, tomatoes, onions, chopped parsley, and mint in a large mixing bowl.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Add the lemon juice, salt, and black pepper. Toss well to combine. Finally, drizzle with olive oil and toss gently once more to coat the vegetables.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Adding the oil last ensures the vegetables can absorb the acid and salt first."]}, {"step_number": 5, "phase": "finish", "text": "Serve immediately for maximum crunch, or let rest for 15 minutes to allow flavors to meld (note: liquid will pool at the bottom).", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT10M", "total_time": "PT30M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Vegetarian", "Vegan", "Pescatarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Low-Carb", "Paleo", "Whole30", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 134.45, "protein_g": 1.67, "carbohydrates_g": 7.8, "fat_g": 11.65, "saturated_fat_g": 1.67, "trans_fat_g": null, "monounsaturated_fat_g": 8.24, "polyunsaturated_fat_g": 1.22, "fiber_g": 2.75, "sugar_g": 5.48, "sodium_mg": 397.56, "cholesterol_mg": null, "potassium_mg": 387.41, "calcium_mg": 34.57, "iron_mg": 0.85, "magnesium_mg": 25.39, "phosphorus_mg": 47.81, "zinc_mg": 0.39, "vitamin_a_mcg": 22.01, "vitamin_c_mg": 24.19, "vitamin_d_mcg": null, "vitamin_e_mg": 1.69, "vitamin_k_mcg": 75.04, "vitamin_b6_mg": 0.07, "vitamin_b12_mcg": null, "thiamin_mg": 0.04, "riboflavin_mg": 0.04, "niacin_mg": 0.14, "folate_mcg": 23.77, "water_g": 109.21, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Texture degrades quickly; best consumed fresh. Drain excess liquid before serving leftovers.", "duration": "P1D"}, "freezer": {"notes": "Do not freeze.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Small bowl", "required": true, "alternative": "Cup for soaking onions"}, {"name": "Fine-mesh sieve", "required": false, "alternative": null}]', '[{"symptom": "Salad is too watery/soupy", "likely_cause": "Tomato seeds were not removed or salad sat too long after salting", "prevention": "Seed tomatoes thoroughly and season just before serving", "fix": "Strain the excess liquid through a sieve and re-season with a splash of oil and lemon"}, {"symptom": "Onions overpower the fresh vegetables", "likely_cause": "Onions were not soaked or cut too large", "prevention": "Soak onions in ice water and cut into fine brunoise", "fix": "Pick out larger onion pieces if possible; otherwise cannot be fixed"}]', '["Uniformity is key: Take the time to cut all vegetables to the exact same size (small dice) for the perfect mouthfeel.", "Persian or English cucumbers are superior here as they have thinner skins and fewer seeds than standard slicing cucumbers.", "If preparing ahead for a party, combine all chopped vegetables in a bowl but do not add the dressing (lemon, salt, oil) until the very last minute.", "The soaking of the red onion is a professional technique that transforms the ingredient from aggressive to pleasantly crisp and mild."]', '"This style of chopped salad is ubiquitous throughout the Levant and Mediterranean, known variously as Israeli Salad, Salad Shirazi (Persian), or Shepherd''s Salad (Turkish). It reflects the region''s reliance on fresh, raw produce and is a staple accompaniment to every meal from breakfast to dinner."', 134.45);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('d4f278cd-979d-467e-9cef-b542feaa1fae', 'Spaghetti with Clams, Bacon, Peas & Green Herb Purée', 'A vibrant surf-and-turf pasta where smoky rendered bacon and briny canned clams meet sweet garden peas. The dish is finished with a raw, aromatic emulsion of fresh basil and parsley that brightens the rich, savory sauce.', 'dinner', 'Modern Italian', 'Intermediate', '["bacon", "basil", "clam", "parsley", "spaghetti", "dinner", "main course", "pasta", "quick"]', '[{"group_name": "Herb Pur\u00e9e", "items": [{"name": "fresh basil leaves", "quantity": 30, "unit": "g", "preparation": "washed and dried", "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh flat-leaf parsley", "quantity": 30, "unit": "g", "preparation": "leaves and tender stems only", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pasta Base", "items": [{"name": "spaghetti", "quantity": 450, "unit": "g", "preparation": "dried", "notes": null, "substitutions": ["linguine", "bucatini"], "ingredient_id": "8f9d3063-4bf0-46dc-9f13-5f49cd92d47d", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 4000, "unit": "ml", "preparation": null, "notes": "for boiling", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt", "quantity": 30, "unit": "g", "preparation": null, "notes": "for pasta water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sauce", "items": [{"name": "smoked bacon", "quantity": 150, "unit": "g", "preparation": "diced small", "notes": null, "substitutions": [], "ingredient_id": "339a356e-8f77-48fe-9293-b8e35fed3e6c", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "approx 30g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "red chili flakes", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 80, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["chicken stock", "vegetable broth"], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "canned clams", "quantity": 280, "unit": "g", "preparation": null, "notes": "2 standard cans; reserve juice separately", "substitutions": [], "ingredient_id": "c944d4c1-4ca2-4796-b45d-498471bf085c", "nutrition_source": "Aggregated Public Data"}, {"name": "frozen peas", "quantity": 150, "unit": "g", "preparation": "thawed", "notes": null, "substitutions": [], "ingredient_id": "016d251b-46fd-4724-9e40-e8ae5a2a18bc", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Drain the canned clams, ensuring you catch and reserve all the clam liquid (liquor) in a separate bowl. Set the clam meat aside.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a blender, combine the basil, parsley, olive oil, garlic clove, and lemon juice. Pulse until a vibrant green pur\u00e9e forms. Season with a pinch of salt and set aside.", "structured": {"action": "BLEND", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Bring a large pot of salted water to a rolling boil (100\u00b0C/212\u00b0F). Add the spaghetti and cook for 1-2 minutes less than the package instructions for al dente.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "While the water heats, place the diced bacon in a large, cold saut\u00e9 pan. Turn heat to medium and render until the fat releases and the bacon becomes crisp.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": {"visual": "Golden brown and crispy", "tactile": "Firm texture"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the minced shallot and chili flakes to the bacon fat. Saut\u00e9 for 1-2 minutes until the shallot is translucent but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Increase heat to medium-high and deglaze the pan with white wine. Let it bubble aggressively to evaporate the alcohol, then add the reserved clam juice. Simmer for 3 minutes to reduce slightly.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Add the peas and the drained clam meat to the pan. Cook for just 1 minute to warm them through\u2014do not overcook the clams as they will become rubbery.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Transfer the cooked spaghetti directly into the saut\u00e9 pan using tongs (do not drain the sink). Add 60ml of the starchy pasta water. Toss vigorously over medium heat until the sauce emulsifies and coats the noodles.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove the pan from the heat entirely. Pour in the herb pur\u00e9e and toss continuously until the pasta is coated in a bright green sauce. Serve immediately.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Adding the herb pur\u00e9e off-heat preserves the raw flavor and bright green color."]}]', '{"active_time": "PT25M", "passive_time": "PT0M", "total_time": "PT25M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 380}', '{"flags": ["Dairy-Free", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 928.65, "protein_g": 47.62, "carbohydrates_g": 97.68, "fat_g": 34.46, "saturated_fat_g": 7.73, "trans_fat_g": null, "monounsaturated_fat_g": 18.17, "polyunsaturated_fat_g": 3.53, "fiber_g": 5.55, "sugar_g": 5.25, "sodium_mg": 4030.55, "cholesterol_mg": 40.13, "potassium_mg": 1296.05, "calcium_mg": 157.74, "iron_mg": 6.39, "magnesium_mg": 135.61, "phosphorus_mg": 802.45, "zinc_mg": 3.77, "vitamin_a_mcg": 270.27, "vitamin_c_mg": 17.48, "vitamin_d_mcg": null, "vitamin_e_mg": 2.61, "vitamin_k_mcg": 172.81, "vitamin_b6_mg": 0.23, "vitamin_b12_mcg": 0.44, "thiamin_mg": 0.26, "riboflavin_mg": 0.16, "niacin_mg": 4.78, "folate_mcg": 42.85, "water_g": 1058.23, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor profile changes significantly upon reheating; herbs lose vibrancy.", "duration": "P2D"}, "freezer": {"notes": "Not recommended; emulsion will break and texture will suffer.", "duration": null}, "reheating": "Gently warm in a pan with a splash of water; do not microwave if possible to avoid rubbery clams.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Large saut\u00e9 pan or skillet", "required": true, "alternative": null}, {"name": "Blender or Food Processor", "required": true, "alternative": "Mortar and pestle"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "The sauce is dry and clumpy", "likely_cause": "Not enough liquid to form an emulsion with the starch", "prevention": "Always reserve extra pasta water before draining", "fix": "Add hot pasta water 15ml at a time while tossing vigorously until creamy"}]', '["Canned clams are already cooked. The biggest mistake is boiling them in the sauce too long, which turns them into rubber. Add them at the very last moment.", "Starting the bacon in a cold pan helps render the fat more evenly than tossing it into a hot pan, resulting in better crispiness.", "The herb pur\u00e9e acts as a ''fresh pesto'' minus the cheese and nuts. It provides a temperature and flavor contrast to the hot, savory bacon fat.", "If using frozen peas, there is no need to boil them beforehand; they will cook perfectly in the residual heat of the sauce."]', '"This dish is a modern riff on ''Spaghetti alle Vongole'', combining the Italian tradition of seafood pasta with the American affinity for ''surf and turf'' pairings. The addition of peas and bacon nods to the classic ''Pasta e Piselli'', creating a hybrid dish that balances saline depth with garden freshness."', 928.65);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('d5c1c875-7de0-4e96-813b-f119191f994e', 'Translucent Glacé Clementine Segments', 'Jewel-like, semi-transparent citrus segments with a satisfying gummy-like chew. These slow-candied treats retain the brightness of fresh fruit while transforming the membrane into a delicate, sugary shell. Perfect for topping yogurt, decorating cakes, or eating as sweetmeats.', 'confection', 'French', 'Intermediate', '["candies", "project", "sugar", "vegan", "christmas", "new year''s day", "giftable"]', '[{"group_name": "Fruit", "items": [{"name": "clementines", "quantity": 5, "unit": null, "preparation": "peeled and segmented", "notes": "approx 350g total weight; choose firm, unbruised fruit", "substitutions": [], "ingredient_id": "9eefbfec-8a2c-4396-a7b8-1d76bb065934", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 1000, "unit": "ml", "preparation": null, "notes": "for blanching", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Syrup", "items": [{"name": "white granulated sugar", "quantity": 400, "unit": "g", "preparation": "refined", "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 400, "unit": "ml", "preparation": null, "notes": "for syrup base", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "glucose syrup", "quantity": 50, "unit": "g", "preparation": null, "notes": "optional; prevents crystallization and improves chewiness", "substitutions": ["light corn syrup"], "ingredient_id": "a37884dd-47fa-4fa8-a5f6-a2da640865b4", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Carefully peel the clementines, removing as much of the white spongy pith from the exterior as possible without piercing the membrane of the segments. Separate into individual segments gently.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Prepare a cartouche: Cut a circle of parchment paper the same diameter as your wide saucepan and cut a small vent hole in the center. This will keep the fruit submerged during cooking.", "structured": {"action": "MEASURE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Bring the blanching water to a boil. Add the segments and blanch for exactly 60 seconds. Drain immediately and handle gently. This step softens the tough membrane to allow sugar penetration.", "structured": {"action": "BLANCH", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "In the wide saucepan, combine the sugar, syrup water, and glucose syrup. Heat over medium heat until the sugar dissolves completely.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the blanched segments to the syrup in a single layer. Place the parchment cartouche directly on the surface of the liquid. Lower heat to the absolute minimum setting. The liquid should barely tremble, not boil vigorously.", "structured": {"action": "POACH", "temperature": {"celsius": 80, "fahrenheit": 176}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Simmer gently for 45 to 60 minutes. The segments are done when they look swollen, heavy, and the membranes appear translucent rather than opaque white.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT1H", "doneness_cues": {"visual": "Segments appear glassy and translucent", "tactile": "Fruit feels soft but intact"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove the pan from heat. Let the segments cool completely inside the syrup at room temperature for at least 8 hours or overnight. This rest period is crucial for the osmotic exchange that creates the chewy texture.", "structured": {"action": "REST", "temperature": null, "duration": "PT8H", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove segments with a slotted spoon and place them on a wire rack set over a tray. Let them dry in a cool, dry place for 12 to 24 hours until they are tacky to the touch but no longer wet. Roll in extra sugar if a frosted look is desired, or leave plain for the glass effect.", "structured": {"action": "DRAIN", "temperature": null, "duration": "P1D", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "P1D", "total_time": "P1DT45M", "overnight_required": true, "yields": "approx. 40 segments", "yield_count": 8, "serving_size_g": 30}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Soy-Free", "Nut-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 220.56, "protein_g": 0.38, "carbohydrates_g": 56.76, "fat_g": 0.14, "saturated_fat_g": 0.02, "trans_fat_g": null, "monounsaturated_fat_g": 0.03, "polyunsaturated_fat_g": 0.03, "fiber_g": 0.79, "sugar_g": 55.4, "sodium_mg": 8.75, "cholesterol_mg": null, "potassium_mg": 75.13, "calcium_mg": 20.19, "iron_mg": 0.09, "magnesium_mg": 7, "phosphorus_mg": 8.75, "zinc_mg": 0.08, "vitamin_a_mcg": 14.88, "vitamin_c_mg": 13.24, "vitamin_d_mcg": null, "vitamin_e_mg": 0.09, "vitamin_k_mcg": null, "vitamin_b6_mg": 0.09, "vitamin_b12_mcg": 0.16, "thiamin_mg": 0.03, "riboflavin_mg": 0.03, "niacin_mg": 0.17, "folate_mcg": 17.44, "water_g": 217.57, "alcohol_g": null, "caffeine_mg": 2.38}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container layered with parchment paper to prevent sticking.", "duration": "P1M"}, "freezer": {"notes": "Freeze in a single layer first, then bag.", "duration": "P6M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Wide saucepan or skillet", "required": true, "alternative": "Large pot (but stacking fruit risks crushing)"}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Wire cooling rack", "required": true, "alternative": null}, {"name": "Slotted spoon", "required": true, "alternative": null}, {"name": "Digital scale", "required": true, "alternative": null}]', '[{"symptom": "Segments disintegrated or turned to mush", "likely_cause": "The syrup boiled too vigorously", "prevention": "Keep heat at the lowest possible setting; use a heat diffuser if necessary", "fix": "Strain the mixture; use the orange-flavored syrup for cocktails or yogurt, and the solids as jam"}, {"symptom": "Sugar crystallized on the fruit while cooling", "likely_cause": "Syrup was agitated too much or lacked glucose/invert sugar", "prevention": "Include the glucose syrup in the recipe and avoid stirring once simmering starts", "fix": "Gently reheat the syrup to dissolve crystals, then cool again"}]', '["Do not discard the leftover poaching liquid! You now have a rich Clementine Syrup perfect for cocktails, moistening sponge cakes, or drizzling over pancakes.", "If the weather is very humid, the segments may remain sticky. You can dry them in an oven (or dehydrator) set to the lowest possible temperature (usually 50\u00b0C/120\u00b0F) for 2-3 hours.", "For a more complex flavor, add a star anise pod, a cinnamon stick, or a split vanilla bean to the syrup during the simmering stage.", "The glucose syrup helps keep the texture chewy rather than hard and prevents the sugar from recrystallizing into a gritty white coating."]', '"This technique is a simplified variation of ''Fruits Confits'', a preservation art form perfected in Apt, in the Provence region of France. While traditional candying involves boiling fruit in increasingly strong sugar syrups over several weeks, this ''quick confit'' method achieves a similar translucency and texture suitable for home kitchens."', 220.56);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('d5d5512d-ab3b-4e74-9eea-526a6b7aa33b', 'Kakavia with Retsina and Squid', 'A rustic, aromatic Greek fisherman''s stew. The unique pine resin notes of Retsina wine cut through the rich olive oil emulsion, while tender white fish and delicate squid rings poach gently in a saffron-scented tomato broth.', 'soup', 'Greek', 'Intermediate', '["greek", "fish", "squid", "dinner", "main course", "winter", "stew", "seafood"]', '[{"group_name": "Vegetable Base", "items": [{"name": "extra virgin olive oil", "quantity": 80, "unit": "ml", "preparation": null, "notes": "high quality is essential for the broth emulsion", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "finely chopped", "notes": "about 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "leek", "quantity": 1, "unit": null, "preparation": "white and light green parts only, sliced", "notes": "about 100g", "substitutions": [], "ingredient_id": "f0bddafa-51db-4e56-954b-18624daa6fa4", "nutrition_source": "USDA FoodData Central"}, {"name": "fennel bulb", "quantity": 1, "unit": null, "preparation": "diced, reserve fronds for garnish", "notes": "about 200g", "substitutions": [], "ingredient_id": "a42d03de-0a8a-4a75-8299-5cf01d43b425", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "about 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "yukon gold potatoes", "quantity": 400, "unit": "g", "preparation": "peeled and cut into 2cm chunks", "notes": null, "substitutions": [], "ingredient_id": "a9d640ff-a969-4f0a-9a92-974f376ac272", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Broth & Aromatics", "items": [{"name": "retsina wine", "quantity": 150, "unit": "ml", "preparation": null, "notes": "can substitute dry white wine with a sprig of fresh rosemary", "substitutions": [], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "fish stock", "quantity": 800, "unit": "ml", "preparation": null, "notes": "high quality or homemade preferred", "substitutions": [], "ingredient_id": "3912e04d-71a3-4a31-b033-cc5c5aa4452d", "nutrition_source": "Aggregated Public Data"}, {"name": "crushed tomatoes", "quantity": 400, "unit": "g", "preparation": "canned", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "bay leaf", "quantity": 1, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}, {"name": "saffron threads", "quantity": 1, "unit": "g", "preparation": null, "notes": "a small pinch", "substitutions": [], "ingredient_id": "7f9ec0c8-2db1-48ac-a2c9-9b1efce12cf3", "nutrition_source": "USDA FoodData Central"}, {"name": "orange zest", "quantity": 1, "unit": null, "preparation": "strip", "notes": "about 5g", "substitutions": [], "ingredient_id": "c1a067e6-674f-4f68-9fe9-3eda4b074356", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Seafood & Finish", "items": [{"name": "white fish fillets", "quantity": 500, "unit": "g", "preparation": "cod, haddock, or halibut, cut into large 5cm chunks", "notes": "firm flesh preferred", "substitutions": [], "ingredient_id": "7c0b1fd4-2b0f-41d0-a728-f5ee24132e74", "nutrition_source": "USDA FoodData Central"}, {"name": "squid", "quantity": 250, "unit": "g", "preparation": "cleaned, bodies sliced into rings, tentacles left whole", "notes": null, "substitutions": [], "ingredient_id": "e126ab3d-72fc-463a-a50c-461c65ccdf4d", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 30, "unit": "ml", "preparation": null, "notes": "about half a lemon", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Heat the olive oil in a Dutch oven over medium heat. Add the onion, leek, and fennel. Saut\u00e9 gently until softened and translucent but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT8M", "doneness_cues": {"visual": "Vegetables are translucent and soft", "tactile": "Soft resistance"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add the minced garlic and cook for another minute until fragrant. Pour in the Retsina wine to deglaze, scraping up any fond from the bottom of the pot. Simmer until the wine has reduced by half.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Liquid volume reduced by 50%", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Stir in the crushed tomatoes, fish stock, potatoes, bay leaf, orange zest strip, and saffron. Bring to a boil, then reduce heat to low and cover. Simmer until the potatoes are just tender when pierced with a knife.", "structured": {"action": "SIMMER", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT20M", "doneness_cues": {"visual": null, "tactile": "Potatoes pierced easily with knife tip"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Gently nestle the white fish chunks into the broth. Cover and poach for 4 minutes. Do not stir vigorously, or the fish will break apart; shake the pot gently instead.", "structured": {"action": "POACH", "temperature": null, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the squid rings and tentacles. Continue to simmer gently for exactly 2 to 3 minutes until the squid turns opaque and the fish is flaky and opaque throughout (internal temperature of fish should reach 63\u00b0C/145\u00b0F).", "structured": {"action": "SIMMER", "temperature": {"celsius": 63, "fahrenheit": 145}, "duration": "PT3M", "doneness_cues": {"visual": "Squid is opaque white, fish flakes easily", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove from heat. Discard the bay leaf and orange zest strip. Stir in the fresh lemon juice, chopped parsley, and reserved fennel fronds. Taste and adjust salt if necessary.", "structured": {"action": "SEASON", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT40M", "total_time": "PT1H10M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Infants (alcohol content, though mostly cooked off)"]}', '{"per_serving": {"calories": 676.52, "protein_g": 46.02, "carbohydrates_g": 40.95, "fat_g": 31.72, "saturated_fat_g": 4.93, "trans_fat_g": null, "monounsaturated_fat_g": 17.22, "polyunsaturated_fat_g": 5.23, "fiber_g": 8.32, "sugar_g": 10.6, "sodium_mg": 463.21, "cholesterol_mg": 220.63, "potassium_mg": 2266.1, "calcium_mg": 137.9, "iron_mg": 3.35, "magnesium_mg": 140.1, "phosphorus_mg": 646.2, "zinc_mg": 2.66, "vitamin_a_mcg": 122.97, "vitamin_c_mg": 60.42, "vitamin_d_mcg": 15, "vitamin_e_mg": 4.22, "vitamin_k_mcg": 105.28, "vitamin_b6_mg": 0.54, "vitamin_b12_mcg": 2.06, "thiamin_mg": 0.23, "riboflavin_mg": 0.44, "niacin_mg": 5.58, "folate_mcg": 50.42, "water_g": 231.99, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Reheat very gently to avoid overcooking seafood.", "duration": "P2D"}, "freezer": {"notes": "Not recommended; potatoes become grainy and fish texture degrades.", "duration": null}, "reheating": "Simmer gently on stove until reaching 74\u00b0C/165\u00b0F.", "does_not_keep": false}', '[{"name": "Dutch oven or heavy-bottomed pot", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Vegetable peeler", "required": true, "alternative": null}]', '[{"symptom": "Squid is rubbery and tough", "likely_cause": "The squid was cooked for too long", "prevention": "Add squid at the very last moment; it needs only 2-3 minutes of gentle heat", "fix": "Cannot be fixed easily; removing pieces and slicing them paper-thin can mitigate the texture"}]', '["The emulsion of olive oil and tomato broth is key to Kakavia; don''t skimp on the oil quantity.", "If you cannot find Retsina, a dry Sauvignon Blanc with a sprig of fresh rosemary added during the simmer will mimic the resinous profile.", "Handle the pot gently once the fish is added. Greek cooks often swirl the pot by the handles rather than stirring with a spoon to keep fish chunks intact.", "Serve with crusty bread to soak up the juices."]', '"Kakavia is the Greek answer to Bouillabaisse, originating from ancient Ionian fishermen who would cook their unsold catch in a communal pot with seawater. While modern versions use stock, the generous use of olive oil and lemon remains a hallmark of this coastal staple."', 676.52);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('d6348508-774d-4032-b05d-053f5404a38a', 'Chili-Lime Steamed Mussels with Roasted Cauliflower', 'Plump, briny mussels and nutty, golden-seared cauliflower florets steamed in a fragrant broth of white wine, garlic, and fresh chilies. Finished with bright lime juice and aromatic basil.', 'dinner', 'Thai Fusion', 'Easy', '["cauliflower", "mussel", "dinner", "lunch", "quick", "thai fusion", "seafood", "one pot"]', '[{"group_name": "Fresh Produce & Proteins", "items": [{"name": "fresh live mussels", "quantity": 1000, "unit": "g", "preparation": "scrubbed and debearded", "notes": "discard any with cracked shells", "substitutions": [], "ingredient_id": "8724ea32-079e-407e-a9ae-1fe49557dc47", "nutrition_source": "USDA FoodData Central"}, {"name": "cauliflower", "quantity": 300, "unit": "g", "preparation": "cut into small 2cm florets", "notes": "small size is critical for even cooking", "substitutions": [], "ingredient_id": "2d9d5068-77e7-4dfc-b24b-8e6a6275cb33", "nutrition_source": "USDA FoodData Central"}, {"name": "red bird''s eye chili", "quantity": 2, "unit": null, "preparation": "thinly sliced", "notes": "adjust quantity to taste; approx 4g", "substitutions": [], "ingredient_id": "5080eb9a-d555-4558-94e5-d5700e96ff9b", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx 30g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh basil", "quantity": 15, "unit": "g", "preparation": "rough chop", "notes": "Thai basil preferred, sweet basil acceptable", "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pantry & Liquids", "items": [{"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 120, "unit": "ml", "preparation": null, "notes": "Sauvignon Blanc or Pinot Grigio", "substitutions": ["chicken broth", "vegetable broth"], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "lime juice", "quantity": 30, "unit": "ml", "preparation": null, "notes": "freshly squeezed, plus wedges for serving", "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "fish sauce", "quantity": 5, "unit": "ml", "preparation": null, "notes": "optional, for depth", "substitutions": [], "ingredient_id": "95a9a747-50ee-4be0-84be-0dfc96111e2a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Clean the mussels thoroughly under cold running water. Scrub the shells and pull out the fibrous ''beard'' by tugging it towards the hinge of the shell. Discard any mussels that are cracked or do not close when tapped.", "structured": {"action": "CLEAN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Keeping mussels on ice or in the fridge until the very last second ensures freshness."]}, {"step_number": 2, "phase": "cook", "text": "Heat the olive oil in a large pot over medium-high heat (approx. 190\u00b0C/375\u00b0F). Add the cauliflower florets and sear, stirring occasionally, until they develop golden-brown edges.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT4M", "doneness_cues": {"visual": "Golden brown edges on cauliflower", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Lower the heat slightly. Add the minced garlic, shallots, and sliced chilies. Saut\u00e9 for 1 minute until fragrant, being careful not to burn the garlic.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Shallots are translucent", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Increase heat to high. Add the white wine (and fish sauce if using) to deglaze the pan. Immediately add the cleaned mussels and cover the pot tightly with the lid. Steam until the mussels have opened.", "structured": {"action": "STEAM", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT4M", "doneness_cues": {"visual": "Mussel shells are wide open", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove from heat. Discard any mussels that have not opened. Stir in the lime juice and fresh basil. Serve immediately with extra lime wedges.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Serve with crusty bread to soak up the spicy, acidic broth."]}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "2 main servings", "yield_count": 2, "serving_size_g": 650}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Low-Carb"], "not_suitable_for": ["Shellfish allergy"]}', '{"per_serving": {"calories": 721.98, "protein_g": 63.72, "carbohydrates_g": 34.12, "fat_g": 26.75, "saturated_fat_g": 4.38, "trans_fat_g": null, "monounsaturated_fat_g": 13.55, "polyunsaturated_fat_g": 4.73, "fiber_g": 3.85, "sugar_g": 5.36, "sodium_mg": 1594.57, "cholesterol_mg": 140, "potassium_mg": 2177.3, "calcium_mg": 198.4, "iron_mg": 21.33, "magnesium_mg": 206.07, "phosphorus_mg": 1078.17, "zinc_mg": 8.63, "vitamin_a_mcg": 262.99, "vitamin_c_mg": 126.67, "vitamin_d_mcg": null, "vitamin_e_mg": 5.14, "vitamin_k_mcg": 64.25, "vitamin_b6_mg": 0.68, "vitamin_b12_mcg": 60, "thiamin_mg": 0.91, "riboflavin_mg": 1.16, "niacin_mg": 8.94, "folate_mcg": 307.43, "water_g": 578.04, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten immediately; texture degrades rapidly.", "duration": "P1D"}, "freezer": {"notes": "Do not freeze cooked mussels.", "duration": null}, "reheating": "Gently warm in a covered pan with a splash of water, but fresh is significantly better.", "does_not_keep": true}', '[{"name": "Large Dutch oven or pot with tight-fitting lid", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Mussels taste gritty", "likely_cause": "Sand or sediment inside the shell was not purged effectively before harvest", "prevention": "Buy farm-raised mussels which are usually clean; scrub shells well", "fix": "Remove meat from shells and rinse quickly in the cooking broth, letting sediment settle at the bottom of the pot before serving"}, {"symptom": "Cauliflower is too hard", "likely_cause": "Florets were cut too large relative to the steaming time of the mussels", "prevention": "Cut cauliflower into small, bite-sized pieces (2cm max)", "fix": "Remove cooked mussels to a bowl, cover to keep warm, and continue cooking cauliflower in the broth for 2-3 minutes"}]', '["The searing step for the cauliflower is crucial; if you skip it and just steam, the cauliflower will be bland. The caramelization adds a nutty depth that stands up to the brine.", "Thai basil has a distinct anise flavor that pairs perfectly with chili; if using Italian sweet basil, add a pinch of star anise to the oil in step 2 to mimic that profile.", "Always check the ''harvest date'' on your mussel tag; they should ideally be cooked within a few days of harvest for the sweetest flavor.", "Safety Note: Ensure mussels reach an internal temperature of at least 63\u00b0C/145\u00b0F for 15 seconds, though visual indicators (shells opening) are the standard culinary cue."]', '"While mussels mouclade or marini\u00e8re are French classics, this dish borrows the Southeast Asian ''hot and sour'' flavor profile (Tom Yum inspiration). The addition of cauliflower transforms it from a starter into a texturally varied main course, reflecting modern fusion trends where vegetables share the spotlight with proteins."', 721.98);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('d773d08d-c7ee-483a-8a20-bff92e17c438', 'Creamy Coconut Vegetable Curry', 'A vibrant, golden curry featuring tender potatoes, cauliflower, and sweet peas in a rich, aromatic coconut sauce. This dish strikes the perfect balance between comfort and freshness, offering complex flavors in a fraction of the time usually required for Indian cuisine.', 'dinner', 'Indian', 'Easy', '["curry", "vegetables", "main course", "quick", "vegan", "gluten-free", "one-pot"]', '[{"group_name": "Aromatics & Spices", "items": [{"name": "coconut oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "or vegetable oil", "substitutions": ["ghee", "canola oil"], "ingredient_id": "bfc74b81-e1e0-4607-9eec-8d0eff76d78c", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx. 9g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 10, "unit": "g", "preparation": "grated or minced", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "mild curry powder", "quantity": 12, "unit": "g", "preparation": null, "notes": "about 2 tbsp", "substitutions": [], "ingredient_id": "e714e2f1-2295-4e8c-8ccf-65c38381e71e", "nutrition_source": "USDA FoodData Central"}, {"name": "ground turmeric", "quantity": 3, "unit": "g", "preparation": null, "notes": "about 1 tsp", "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables & Liquids", "items": [{"name": "potatoes", "quantity": 300, "unit": "g", "preparation": "peeled and cut into 2cm cubes", "notes": "Yukon Gold or similar waxy variety", "substitutions": [], "ingredient_id": "5bf06478-4785-465e-9842-f70a24e22054", "nutrition_source": "USDA FoodData Central"}, {"name": "cauliflower florets", "quantity": 300, "unit": "g", "preparation": "cut into bite-sized pieces", "notes": null, "substitutions": [], "ingredient_id": "2d9d5068-77e7-4dfc-b24b-8e6a6275cb33", "nutrition_source": "USDA FoodData Central"}, {"name": "full-fat coconut milk", "quantity": 400, "unit": "ml", "preparation": null, "notes": "1 standard can", "substitutions": [], "ingredient_id": "c037ee7e-e3ed-4340-b8fb-d8ad284ba96e", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable broth", "quantity": 120, "unit": "ml", "preparation": null, "notes": "use only if sauce is too thick", "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "frozen peas", "quantity": 150, "unit": "g", "preparation": "no need to thaw", "notes": null, "substitutions": [], "ingredient_id": "016d251b-46fd-4724-9e40-e8ae5a2a18bc", "nutrition_source": "USDA FoodData Central"}, {"name": "baby spinach", "quantity": 60, "unit": "g", "preparation": "roughly chopped if leaves are large", "notes": null, "substitutions": [], "ingredient_id": "4734440a-226d-4d26-a110-3ed5c3bde93f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "lime juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": "approx. half a lime", "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare all vegetables. Dice the onion, mince the garlic and ginger, peel and cube the potatoes (2cm/0.75in), and cut cauliflower into bite-sized florets.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat the coconut oil in a large heavy-bottomed pot over medium heat (approx. 175\u00b0C/350\u00b0F). Add the diced onion and a pinch of salt. Saut\u00e9 for 5-6 minutes until the onion is translucent and soft.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT6M", "doneness_cues": {"visual": "Onions are translucent and soft", "tactile": "Soft texture"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the minced garlic, ginger, curry powder, and turmeric. Stir constantly for 1 minute until fragrant. Be careful not to burn the spices.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Spices are slightly darker", "tactile": "Aromatic"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the cubed potatoes and cauliflower florets to the pot. Stir to coat the vegetables in the spice mixture.", "structured": {"action": "STIR", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour in the coconut milk. If the vegetables aren''t mostly submerged, add the vegetable broth. Bring to a gentle boil, then reduce heat to low to maintain a simmer. Cover and cook for 12-15 minutes, or until potatoes are tender when pierced with a fork.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": "Sauce is bubbling gently", "tactile": "Potatoes offer no resistance to a fork"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove the lid. Stir in the frozen peas and baby spinach. Simmer for 2-3 minutes uncovered until the peas are bright green and spinach is wilted.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from heat. Stir in the lime juice. Taste and add more salt if necessary. Garnish with fresh chopped cilantro before serving.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["The acidity of the lime is crucial to cut through the richness of the coconut milk."]}]', '{"active_time": "PT20M", "passive_time": "PT15M", "total_time": "PT35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 325}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 394.76, "protein_g": 9.3, "carbohydrates_g": 32.22, "fat_g": 28.52, "saturated_fat_g": 24.45, "trans_fat_g": null, "monounsaturated_fat_g": 1.56, "polyunsaturated_fat_g": 0.57, "fiber_g": 10.18, "sugar_g": 8.66, "sodium_mg": 811.72, "cholesterol_mg": null, "potassium_mg": 1073.61, "calcium_mg": 111.32, "iron_mg": 6.53, "magnesium_mg": 100.99, "phosphorus_mg": 228.11, "zinc_mg": 1.75, "vitamin_a_mcg": 168.39, "vitamin_c_mg": 60.38, "vitamin_d_mcg": null, "vitamin_e_mg": 1.35, "vitamin_k_mcg": 96.51, "vitamin_b6_mg": 0.5, "vitamin_b12_mcg": null, "thiamin_mg": 0.23, "riboflavin_mg": 0.16, "niacin_mg": 2.77, "folate_mcg": 132.4, "water_g": 283.14, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. The flavors often improve after a day.", "duration": "P4D"}, "freezer": {"notes": "Potatoes may become slightly grainy upon thawing.", "duration": "P2M"}, "reheating": "Reheat gently on the stove over medium-low heat, adding a splash of water if the sauce has thickened.", "does_not_keep": false}', '[{"name": "Large heavy-bottomed pot or Dutch oven", "required": true, "alternative": "Deep saut\u00e9 pan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": null}]', '[{"symptom": "Sauce is too thin", "likely_cause": "Coconut milk brand was low in fat or vegetables released too much water", "prevention": "Use full-fat coconut milk; don''t cover the pot during the final simmer", "fix": "Simmer uncovered for an extra 5-10 minutes, or mash a few potato chunks against the side of the pot to thicken the sauce naturally"}, {"symptom": "Potatoes are hard but cauliflower is mushy", "likely_cause": "Potatoes were cut too large relative to the cauliflower", "prevention": "Cut potatoes into smaller 2cm cubes and keep cauliflower florets slightly larger", "fix": "Remove cooked cauliflower with a slotted spoon, continue cooking potatoes until done, then return cauliflower to pot"}]', '["Always use full-fat canned coconut milk for this recipe. ''Lite'' coconut milk or the beverage kind in cartons will result in a watery sauce lacking depth.", "Cut your vegetables to uniform sizes. This ensures they cook evenly and creates a better mouthfeel in the final dish.", "Bloom your spices! Adding the curry powder to the hot oil/onion mixture (Step 3) rather than the liquid releases fat-soluble flavor compounds that make the curry much more robust.", "For extra protein, you can easily add a drained can of chickpeas along with the potatoes."]', '"While this recipe utilizes the flavor profile of South Indian cuisine (coconut milk, turmeric, ginger), it is a streamlined adaptation designed for Western home kitchens. It fits into the tradition of ''Sabzi''\u2014vegetable-based dishes that are a staple in Indian households, serving as a primary source of nutrition and comfort."', 394.76);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('d86598cc-0836-45a2-b026-049ad9b7d38d', 'Healthy Tex-Mex Beef Burrito Bowl', 'A nutrient-dense bowl featuring spiced lean beef, fiber-rich brown rice, and black beans, topped with fresh vegetables and zesty salsa for a balanced, satisfying meal.', 'main', 'Tex-Mex', 'Easy', '["healthy", "high-protein", "meal-prep", "gluten-free", "fiber-rich", "dinner-bowl"]', '[{"group_name": "Protein & Veggie Base", "items": [{"name": "lean ground beef", "quantity": 500, "unit": "g", "preparation": "90/10 or 93/7 ratio", "notes": null, "substitutions": ["ground turkey", "ground chicken"], "ingredient_id": "0258ca78-fe20-439b-94bc-30619460372b", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": "medium", "preparation": "diced", "notes": null, "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "bell pepper", "quantity": 2, "unit": "medium", "preparation": "sliced into strips", "notes": "any color", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 3, "unit": "cloves", "preparation": "minced", "notes": null, "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Spice Blend & Simmer", "items": [{"name": "chili powder", "quantity": 1, "unit": "tbsp", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 1, "unit": "tsp", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "smoked paprika", "quantity": 1, "unit": "tsp", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 0.5, "unit": "tsp", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "black beans", "quantity": 1, "unit": "can (400g)", "preparation": "rinsed and drained", "notes": "low sodium preferred", "substitutions": ["pinto beans"], "ingredient_id": "ff8b9618-3332-4acf-99ad-a9df04dd2643", "nutrition_source": "USDA FoodData Central"}, {"name": "beef broth", "quantity": 120, "unit": "ml", "preparation": null, "notes": "low sodium", "substitutions": ["water"], "ingredient_id": "dc6fbbfb-806f-474b-932d-c3fa9d5fa699", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Bowl Assembly", "items": [{"name": "brown rice", "quantity": 3, "unit": "cups", "preparation": "cooked", "notes": "substitute with cauliflower rice for lower carb", "substitutions": ["quinoa"], "ingredient_id": "cad8e863-f4d0-4af7-b418-820a90fd6a23", "nutrition_source": "USDA FoodData Central"}, {"name": "romaine lettuce", "quantity": 2, "unit": "cups", "preparation": "shredded", "notes": null, "substitutions": [], "ingredient_id": "312b8da7-52bd-406b-89d2-0853c0e37faa", "nutrition_source": "Aggregated Public Data"}, {"name": "salsa roja", "quantity": 0.5, "unit": "cup", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0ba83f0f-8e25-4857-8f9a-8e182ad5f136", "nutrition_source": "USDA FoodData Central"}, {"name": "avocado", "quantity": 1, "unit": "large", "preparation": "sliced", "notes": null, "substitutions": [], "ingredient_id": "2f40a31e-80a0-4265-b6f3-99ed88ee4c24", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "Prep", "text": "Cook the brown rice according to package instructions if not using pre-cooked rice. Shred the lettuce and slice the avocado.", "structured": {"action": "simmer", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": "Rice is tender and water is absorbed", "tactile": null}}, "tips": ["Cook the rice in vegetable broth for extra flavor."]}, {"step_number": 2, "phase": "Cook", "text": "In a large skillet over medium-high heat, brown the ground beef until cooked through. Drain any excess fat. Add the diced onion and bell peppers, saut\u00e9ing for 4-5 minutes until softened.", "structured": {"action": "saut\u00e9", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Beef is browned and peppers are tender-crisp", "tactile": null}}, "tips": ["Use a very lean beef to minimize the need for draining."]}, {"step_number": 3, "phase": "Season", "text": "Stir in the minced garlic and all spices (chili powder, cumin, paprika, oregano). Toast for 1 minute until fragrant. Add the rinsed black beans and beef broth.", "structured": {"action": "toast", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": null, "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "Simmer", "text": "Reduce heat to low and simmer for 5 minutes, allowing the flavors to meld and the liquid to reduce slightly.", "structured": {"action": "simmer", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Sauce clings to the meat and beans", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "Assemble", "text": "Divide the cooked brown rice into 4 bowls. Top with a generous scoop of the beef and bean mixture. Add shredded lettuce, salsa, and avocado slices on top.", "structured": {"action": "assemble", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": null, "tactile": null}}, "tips": ["Finish with a squeeze of fresh lime juice and fresh cilantro for a bright pop of flavor."]}]', '{"active_time": "PT20M", "passive_time": "PT15M", "total_time": "PT35M", "overnight_required": false, "yields": "4 bowls", "yield_count": 4, "serving_size_g": 1}', '{"flags": ["gluten-free", "nut-free", "high-fiber", "dairy-free-optional"], "not_suitable_for": []}', '{"per_serving": {"calories": 745.42, "protein_g": 45.79, "carbohydrates_g": 70.93, "fat_g": 32.47, "saturated_fat_g": 10.31, "trans_fat_g": 1.44, "monounsaturated_fat_g": 16.07, "polyunsaturated_fat_g": 2.52, "fiber_g": 16.87, "sugar_g": 7.69, "sodium_mg": 982.78, "cholesterol_mg": 111.25, "potassium_mg": 1578.35, "calcium_mg": 144.92, "iron_mg": 7.96, "magnesium_mg": 152.38, "phosphorus_mg": 588.36, "zinc_mg": 9.76, "vitamin_a_mcg": 280.79, "vitamin_c_mg": 107.34, "vitamin_d_mcg": null, "vitamin_e_mg": 4.16, "vitamin_k_mcg": 48.53, "vitamin_b6_mg": 1.26, "vitamin_b12_mcg": 3.54, "thiamin_mg": 0.58, "riboflavin_mg": 0.65, "niacin_mg": 12.43, "folate_mcg": 204.56, "water_g": 430.21, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store the beef and bean mixture separately from the fresh toppings.", "duration": "P4D"}, "freezer": {"notes": "The meat and bean mixture freezes well; do not freeze the fresh toppings.", "duration": "P2M"}, "reheating": "Reheat the rice and meat mixture in the microwave or on the stove before adding fresh toppings.", "does_not_keep": false}', '[{"name": "Large skillet", "required": true, "alternative": null}, {"name": "Medium saucepan (for rice)", "required": true, "alternative": "Microwavable rice pouch"}]', '[]', '["Replacing corn tortillas with brown rice and black beans significantly increases the fiber content, keeping you full longer.", "To keep this dairy-free and lower in saturated fat, we replaced the cheese with avocado for creamy healthy fats.", "This is an excellent meal prep recipe; the flavors of the beef and beans actually improve after a day in the fridge."]', '"The burrito bowl is a modern American adaptation of traditional Mexican ingredients, popularized as a healthier and more customizable alternative to the classic flour-tortilla-wrapped burrito."', 745.42);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('d87da083-222c-4ad5-9846-abeddbe23549', 'Chorizo and Black Bean Fideo Soup', 'A comforting, hearty Mexican meal featuring toasted fideo noodles simmered in a velvety purée of black beans, tomatoes, and spices. The rich, savory broth is studded with crispy crumbled chorizo, creating a deeply satisfying texture and flavor profile perfect for weeknights.', 'soup', 'Mexican', 'Easy', '["mexican", "one pot", "black bean", "canned tomato", "chorizo", "great leftovers", "pasta", "soup", "stovetop", "dinner", "easy", "lunch", "quick", "weeknight", "main course"]', '[{"group_name": "Bean & Tomato Base", "items": [{"name": "canned black beans", "quantity": 425, "unit": "g", "preparation": "rinsed and drained", "notes": "1 standard can", "substitutions": [], "ingredient_id": "55955de4-23d3-4861-a95f-af5966ff9ab4", "nutrition_source": "USDA FoodData Central"}, {"name": "canned crushed tomatoes", "quantity": 400, "unit": "g", "preparation": "with juices", "notes": "fire-roasted preferred", "substitutions": [], "ingredient_id": "49a62ca7-db63-4d23-9f6f-2cf873fba8a3", "nutrition_source": "Aggregated Public Data"}, {"name": "chicken stock", "quantity": 500, "unit": "ml", "preparation": null, "notes": "divided use", "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}, {"name": "white onion", "quantity": 1, "unit": null, "preparation": "roughly chopped", "notes": "small, approx 100g", "substitutions": [], "ingredient_id": "ee82a9b0-15f7-45cd-bd5f-ba0b65eb1100", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": "peeled", "notes": "approx 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 1, "unit": null, "preparation": null, "notes": "Mexican oregano preferred, approx 1g", "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Soup Solids", "items": [{"name": "mexican chorizo", "quantity": 250, "unit": "g", "preparation": "raw, casing removed", "notes": "fresh uncured sausage, not dried Spanish chorizo", "substitutions": [], "ingredient_id": "6a5f6763-d6d8-490a-a802-b081b094e76f", "nutrition_source": "Aggregated Public Data"}, {"name": "fideo noodles", "quantity": 150, "unit": "g", "preparation": "dry", "notes": "or angel hair pasta broken into 3cm pieces", "substitutions": ["angel hair pasta", "vermicelli"], "ingredient_id": "52cdfe63-4362-4d80-9ed0-9fc7041f2721", "nutrition_source": "USDA FoodData Central"}, {"name": "chicken stock", "quantity": 500, "unit": "ml", "preparation": null, "notes": "additional liquid for cooking", "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnishes (Optional)", "items": [{"name": "crema", "quantity": null, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b326a6b3-b843-4259-8387-12e599fe33c5", "nutrition_source": "Aggregated Public Data"}, {"name": "avocado", "quantity": null, "unit": null, "preparation": "sliced", "notes": null, "substitutions": [], "ingredient_id": "35c8f26f-d008-407a-9bf3-48c8aa641729", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": null, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "USDA FoodData Central"}, {"name": "lime wedges", "quantity": null, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "d3d2677e-fe02-4404-add0-29d73df7e921", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a blender, combine the drained black beans, crushed tomatoes, onion, garlic, oregano, cumin, and 250ml of the chicken stock. Blend on high until completely smooth and creamy.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat a large Dutch oven over medium-high heat. Add the raw chorizo (removed from casing) and cook, breaking it apart with a spoon, until fully browned and the fat has rendered. The internal temperature should reach at least 74\u00b0C/165\u00b0F.", "structured": {"action": "FRY", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT6M", "doneness_cues": {"visual": "Deep red-brown and crispy", "tactile": "Crumbly texture"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Remove the cooked chorizo with a slotted spoon and set aside, leaving the rendered orange fat in the pot. Reduce heat to medium.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the dry fideo noodles to the hot chorizo fat. Stir constantly to toast the pasta until it turns a golden brown color and smells nutty. Do not let it burn.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown color", "tactile": "Toasty aroma"}}, "tips": ["Toasting the pasta prevents it from becoming mushy and adds a depth of flavor characteristic of Mexican fideo dishes."]}, {"step_number": 5, "phase": "cook", "text": "Pour the black bean pur\u00e9e from the blender into the pot with the toasted noodles. It may splatter slightly. Stir well to combine, scraping up any browned bits from the bottom.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Stir in the remaining 750ml of chicken stock (the unused 250ml from the first batch plus the additional 500ml). Bring to a boil, then reduce heat to low and simmer uncovered until the noodles are tender.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": null, "tactile": "Noodles are soft but not disintegrating"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Stir half of the crispy chorizo back into the soup. Taste and season with salt if needed (chorizo and stock are salty, so check first). Serve in bowls topped with the remaining crispy chorizo and optional garnishes like avocado, crema, and lime.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT15M", "total_time": "PT35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Vegetarians (contains pork chorizo)", "Vegans"]}', '{"per_serving": {"calories": 600.41, "protein_g": 30.49, "carbohydrates_g": 43.64, "fat_g": 36.52, "saturated_fat_g": 11.84, "trans_fat_g": 0.06, "monounsaturated_fat_g": 3.19, "polyunsaturated_fat_g": 1.35, "fiber_g": 12.25, "sugar_g": 11.02, "sodium_mg": 12221.5, "cholesterol_mg": 19.8, "potassium_mg": 1043.35, "calcium_mg": 114.66, "iron_mg": 4.96, "magnesium_mg": 73.65, "phosphorus_mg": 159.93, "zinc_mg": 3.98, "vitamin_a_mcg": 178.26, "vitamin_c_mg": 21.32, "vitamin_d_mcg": null, "vitamin_e_mg": 1.49, "vitamin_k_mcg": 3.7, "vitamin_b6_mg": 0.16, "vitamin_b12_mcg": 0.05, "thiamin_mg": 0.13, "riboflavin_mg": 0.15, "niacin_mg": 1.24, "folate_mcg": 101.14, "water_g": 148.95, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "The noodles will absorb liquid over time. Add a splash of water or stock when reheating to loosen the consistency.", "duration": "P3D"}, "freezer": {"notes": "Texture of noodles may soften slightly upon thawing.", "duration": "P2M"}, "reheating": "Reheat gently on the stovetop over medium heat, adding liquid as needed.", "does_not_keep": false}', '[{"name": "Blender or Food Processor", "required": true, "alternative": null}, {"name": "Dutch Oven or Large Heavy-Bottomed Pot", "required": true, "alternative": null}, {"name": "Tongs or Slotted Spoon", "required": true, "alternative": null}]', '[{"symptom": "Soup is too thick or pasty", "likely_cause": "The beans thickened too much or the pasta absorbed too much liquid", "prevention": "Do not simmer longer than necessary", "fix": "Stir in additional hot water or stock 50ml at a time until desired consistency is reached"}, {"symptom": "Noodles are burnt", "likely_cause": "Heat was too high during the toasting step or stirring wasn''t constant", "prevention": "Watch the noodles closely; they transition from golden to black very quickly", "fix": "Discard the noodles and start the toasting step over; burnt taste will ruin the soup"}]', '["If you cannot find ''Fideo'' labeled pasta, angel hair or thin spaghetti broken into 3-4cm lengths works perfectly.", "The step of frying the noodles is non-negotiable; it creates a barrier that keeps the pasta firm in the hot liquid and adds a nutty flavor dimension.", "For a spicier version, blend a whole chipotle pepper in adobo sauce with the bean mixture in step 1.", "This dish thickens significantly as it cools. It makes excellent leftovers but will essentially become a pasta stew rather than a soup the next day."]', '"Sopa de Fideo is a staple in Mexican home cooking, often one of the first dishes children learn to love. While typically made with a tomato-based broth, this ''Enfrijoladas'' inspired variation incorporates black beans for a richer, creamier base commonly found in central Mexico."', 600.41);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('d8abf297-bd2e-4268-b5f0-8d9810005c36', 'Raspberry White Chocolate Macarons', 'Delicate, airy almond meringue shells with a blush hue and tangy raspberry speckles, sandwiched around a luxurious, velvety white chocolate ganache infused with intense freeze-dried raspberry tartness.', 'confection', 'French', 'Advanced', '["french", "project", "dessert", "gluten-free", "make-ahead", "confection"]', '[{"group_name": "Macaron Shells", "items": [{"name": "almond flour", "quantity": 130, "unit": "g", "preparation": "super fine", "notes": "blanched", "substitutions": [], "ingredient_id": "5bcbb4d4-6845-4825-bd21-1c13e52b989c", "nutrition_source": "USDA FoodData Central"}, {"name": "confectioners'' sugar", "quantity": 130, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "freeze-dried raspberry powder", "quantity": 5, "unit": "g", "preparation": "finely ground", "notes": "ensure no large seeds remain", "substitutions": [], "ingredient_id": "db4897d8-0822-453c-a8b5-3e12351bb8ff", "nutrition_source": "USDA FoodData Central"}, {"name": "egg whites", "quantity": 100, "unit": "g", "preparation": "room temperature", "notes": "aged 24 hours preferably; approx 3 large eggs", "substitutions": [], "ingredient_id": "17645f6b-c1ea-4e82-a4b4-5ae8cb6a5a53", "nutrition_source": "USDA FoodData Central"}, {"name": "superfine sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": "caster sugar", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Raspberry White Chocolate Ganache", "items": [{"name": "white chocolate", "quantity": 150, "unit": "g", "preparation": "finely chopped", "notes": "high quality couverture (min 28% cocoa butter)", "substitutions": [], "ingredient_id": "b6c0dcbc-6448-42d2-88b1-2979e857db6c", "nutrition_source": "USDA FoodData Central"}, {"name": "heavy cream", "quantity": 60, "unit": "ml", "preparation": null, "notes": "min 35% fat", "substitutions": [], "ingredient_id": "c0632db1-0bb6-4224-8025-59c94c92a244", "nutrition_source": "Aggregated Public Data"}, {"name": "freeze-dried raspberry powder", "quantity": 10, "unit": "g", "preparation": "finely ground", "notes": null, "substitutions": [], "ingredient_id": "db4897d8-0822-453c-a8b5-3e12351bb8ff", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place almond flour, confectioners'' sugar, and 5g freeze-dried raspberry powder in a food processor. Pulse several times to combine and break down any lumps, but do not process to the point of releasing almond oil. Sift this mixture twice into a large bowl. Discard any large almond pieces or seeds remaining in the sieve.", "structured": {"action": "SIFT", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Whip the room temperature egg whites in a clean, grease-free bowl on medium speed until they become foamy. Gradually add the superfine sugar, one tablespoon at a time, while continuing to whip.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Increase speed to medium-high and whip until stiff, glossy peaks form. The meringue should clump inside the whisk attachment when lifted.", "structured": {"action": "WHIP", "temperature": null, "duration": null, "doneness_cues": {"visual": "Stiff glossy peaks that stand straight up", "tactile": "Sugar fully dissolved"}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Perform the macronage: Gently fold the dry almond mixture into the meringue in three additions. Use a spatula to scrape the sides and cut through the center. Continue folding until the batter flows like molten lava and can form a figure-eight without breaking.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": {"visual": "Batter flows in a continuous ribbon (lava consistency)", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Transfer batter to a piping bag fitted with a round tip. Pipe 3cm circles onto baking sheets lined with silicone mats or parchment, spacing them 2cm apart. Tap the baking sheet firmly on the counter 3-4 times to release air bubbles.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "Let the macarons rest at room temperature for 30-60 minutes until a dry skin forms on the surface. You should be able to touch them gently without batter sticking to your finger.", "structured": {"action": "REST", "temperature": null, "duration": "PT45M", "doneness_cues": {"visual": null, "tactile": "Dry, non-sticky skin"}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Preheat oven to 150\u00b0C/300\u00b0F. Bake one sheet at a time for 14-16 minutes. They are done when they have developed ''feet'' and do not wiggle on their feet when gently nudged.", "structured": {"action": "BAKE", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from oven and allow shells to cool completely on the baking sheet before peeling them off the mat.", "structured": {"action": "COOL", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Make the ganache: Place chopped white chocolate in a heatproof bowl. Heat the heavy cream in a small saucepan until it just begins to simmer (do not boil over). Pour hot cream over the chocolate and let sit for 1 minute.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Stir the chocolate and cream from the center outwards until smooth and emulsified. Mix in the 10g of freeze-dried raspberry powder. Cover with plastic wrap touching the surface and refrigerate until pipeable (about 30-45 minutes).", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 11, "phase": "assemble", "text": "Pair similar-sized shells. Pipe a coin-sized dollop of ganache onto the flat side of one shell and sandwich gently with its pair. Refrigerate in an airtight container for at least 24 hours before serving to allow texture to mature.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT1H", "passive_time": "P1D1H", "total_time": "P1D2H", "overnight_required": true, "yields": "30 sandwiched macarons", "yield_count": 30, "serving_size_g": 35}', '{"flags": ["Gluten-Free", "Vegetarian"], "not_suitable_for": ["Nut allergies (almond)", "Dairy allergies"]}', '{"per_serving": {"calories": 95.33, "protein_g": 1.66, "carbohydrates_g": 11.8, "fat_g": 4.92, "saturated_fat_g": 1.13, "trans_fat_g": null, "monounsaturated_fat_g": 1.82, "polyunsaturated_fat_g": 0.58, "fiber_g": 0.55, "sugar_g": 10.95, "sodium_mg": 10.87, "cholesterol_mg": 1.05, "potassium_mg": 55.08, "calcium_mg": 25.17, "iron_mg": 0.18, "magnesium_mg": 12.67, "phosphorus_mg": 31.54, "zinc_mg": 0.18, "vitamin_a_mcg": 13.83, "vitamin_c_mg": 0.11, "vitamin_d_mcg": null, "vitamin_e_mg": 1.16, "vitamin_k_mcg": 0.46, "vitamin_b6_mg": 0.01, "vitamin_b12_mcg": 0.03, "thiamin_mg": 0.01, "riboflavin_mg": 0.08, "niacin_mg": 0.2, "folate_mcg": 2.39, "water_g": 3.57, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Allow to mature for 24 hours before eating for best texture.", "duration": "P5D"}, "freezer": {"notes": "Freeze in airtight container. Thaw in fridge overnight.", "duration": "P1M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Digital kitchen scale", "required": true, "alternative": null}, {"name": "Fine mesh sieve", "required": true, "alternative": null}, {"name": "Stand mixer or electric hand mixer", "required": true, "alternative": null}, {"name": "Rubber spatula", "required": true, "alternative": null}, {"name": "Piping bag", "required": true, "alternative": null}, {"name": "Round piping tip (1cm diameter)", "required": true, "alternative": "Cut tip of piping bag"}, {"name": "Baking sheets", "required": true, "alternative": null}, {"name": "Silicone baking mats or parchment paper", "required": true, "alternative": null}, {"name": "Oven thermometer", "required": true, "alternative": null}, {"name": "Food processor", "required": true, "alternative": null}]', '[{"symptom": "Shells cracked on top", "likely_cause": "Oven temperature too high or shells did not rest long enough to form a skin", "prevention": "Ensure shells are dry to the touch before baking; check oven with an external thermometer", "fix": "Cannot be fixed, but still edible"}, {"symptom": "Shells are hollow", "likely_cause": "Meringue was over-whipped or oven temperature was too low", "prevention": "Stop whipping meringue as soon as stiff peaks form; ensure oven is fully preheated", "fix": "Maturation in the fridge for 24h often fills slight hollows as the shell absorbs moisture"}]', '["Maturation is non-negotiable. Freshly baked macarons are crunchy and disjointed; after 24 hours in the fridge, the moisture from the ganache fuses with the shell to create that signature chewy-soft interior.", "Freeze-dried raspberry powder is hygroscopic (absorbs moisture). Work quickly when weighing it, and seal the remainder immediately to prevent clumping.", "Avoid using liquid food coloring, as it adds excess moisture to the sensitive batter. The raspberry powder will provide a pale natural pink, but use gel paste if a more vibrant color is desired.", "Clean your mixing bowl and whisk with a little vinegar or lemon juice before starting the meringue to remove any trace fats that could inhibit volume."]', '"While the macaron''s origins are debated between Italian monasteries and French queens, the modern ''macaron parisien''\u2014two almond meringue discs sandwiched with filling\u2014was popularized by Pierre Desfontaines of Ladur\u00e9e in the early 20th century. This variation balances the sweetness of the classic French confection with the sharp, modern brightness of freeze-dried fruit."', 95.33);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('d9d10913-2d8b-4394-b781-4de876614c19', 'Midnight Truffle Shock-Cooled Brownies', 'These brownies defy the boundary between baked good and confection. Using unsweetened chocolate provides a sophisticated, bitter backbone, while an aggressive ice-bath cooling technique arrests the cooking instantly, collapsing the crumb into a dense, fudgy texture reminiscent of a high-end chocolate truffle.', 'baked good', 'American', 'Intermediate', '["american", "brownie", "unsweetened chocolate", "walnut", "dessert", "dense"]', '[{"group_name": "Chocolate Base", "items": [{"name": "unsalted butter", "quantity": 225, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "unsweetened chocolate (100% cacao)", "quantity": 170, "unit": "g", "preparation": "chopped roughly", "notes": "Do not use chips or semi-sweet", "substitutions": [], "ingredient_id": "1359cc6d-de14-4e6e-9f00-bf23ea1e00d1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Structure & Flavor", "items": [{"name": "granulated sugar", "quantity": 400, "unit": "g", "preparation": null, "notes": "High quantity required to balance 100% cacao", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 4, "unit": null, "preparation": "room temperature", "notes": "large, approx 200g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "fine sea salt", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dry Goods & Mix-ins", "items": [{"name": "all-purpose flour", "quantity": 95, "unit": "g", "preparation": null, "notes": "Standard protein content", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "walnut halves", "quantity": 100, "unit": "g", "preparation": "toasted and roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "ab4fe25a-a215-4af7-8109-055c28e0bef2", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 160\u00b0C/320\u00b0F. Line a 20cm (8-inch) square baking pan with parchment paper, leaving an overhang on two sides for lifting.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Toast the walnuts in the oven for 8-10 minutes until fragrant. Remove, let cool, and chop roughly.", "structured": {"action": "TOAST", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a medium saucepan over low heat, melt the butter and unsweetened chocolate together, stirring constantly until smooth. Remove from heat immediately.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Glossy and completely smooth", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Whisk the sugar into the warm chocolate mixture. It will look grainy; this is normal. Add the vanilla and salt.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Add the eggs one at a time, whisking vigorously after each addition. The batter should become glossy and pull away slightly from the sides of the pan.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Batter transforms from grainy to shiny and satiny", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Stir in the flour until just barely combined. Fold in the toasted walnuts gently. Do not overmix.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Pour batter into the prepared pan. Bake for 25-30 minutes. A toothpick inserted into the center should come out with moist crumbs attached, not wet batter.", "structured": {"action": "BAKE", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT30M", "doneness_cues": {"visual": "Top is set and slightly cracked", "tactile": "Moist crumbs on toothpick"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "While the brownies bake, fill a large roasting pan or basin with ice and cold water (about 3cm deep).", "structured": {"action": "PREPARE_BATH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "IMMEDIATELY upon removing the brownies from the oven, place the hot pan directly into the ice bath. Be careful not to splash water into the brownies. Let sit in the ice bath for 15 minutes.", "structured": {"action": "COOL", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": null, "tactile": "Pan bottom is cold to touch"}}, "tips": ["This ''shock'' stops cooking instantly and compresses the texture."]}, {"step_number": 10, "phase": "finish", "text": "Remove from the water bath. Allow to cool completely at room temperature for at least 45 minutes before lifting out and cutting.", "structured": {"action": "REST", "temperature": null, "duration": "PT45M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT1H", "total_time": "PT1H25M", "overnight_required": false, "yields": "16 squares", "yield_count": 16, "serving_size_g": 75}', '{"flags": ["Vegetarian"], "not_suitable_for": ["Nut allergies", "Gluten intolerance"]}', '{"per_serving": {"calories": 329.89, "protein_g": 4.54, "carbohydrates_g": 34.41, "fat_g": 21.8, "saturated_fat_g": 10.57, "trans_fat_g": 0.01, "monounsaturated_fat_g": 5.29, "polyunsaturated_fat_g": 4.77, "fiber_g": 2.5, "sugar_g": 25.26, "sodium_mg": 93.87, "cholesterol_mg": 76.73, "potassium_mg": 180.29, "calcium_mg": 23.49, "iron_mg": 0.93, "magnesium_mg": 41.2, "phosphorus_mg": 92.33, "zinc_mg": 0.8, "vitamin_a_mcg": 116.36, "vitamin_c_mg": 0.08, "vitamin_d_mcg": 0.25, "vitamin_e_mg": 0.51, "vitamin_k_mcg": 1.21, "vitamin_b6_mg": 0.07, "vitamin_b12_mcg": 0.14, "thiamin_mg": 0.04, "riboflavin_mg": 0.11, "niacin_mg": 0.38, "folate_mcg": 15.98, "water_g": 13.19, "alcohol_g": 0.22, "caffeine_mg": 4.99}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Texture becomes chewier when cold.", "duration": "P1W"}, "freezer": {"notes": "Wrap individually in parchment and foil.", "duration": "P3M"}, "reheating": "Eat room temperature or warm gently for 10 seconds.", "does_not_keep": false}', '[{"name": "20cm square baking pan", "required": true, "alternative": "8x8 inch metal baking pan"}, {"name": "Large roasting pan or basin", "required": true, "alternative": "Clean kitchen sink plugged"}, {"name": "Medium saucepan", "required": true, "alternative": null}, {"name": "Heatproof mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Silicone spatula", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}]', '[{"symptom": "Brownies are greasy or butter pooled on top", "likely_cause": "The chocolate and butter mixture was too hot when eggs were added, or the emulsion broke", "prevention": "Ensure chocolate base is warm, not hot, and whisk eggs vigorously to emulsify", "fix": "Cannot be fixed after baking; absorb excess grease with a paper towel"}]', '["The ice bath is non-negotiable for this recipe. It shocks the butter and chocolate into solidifying rapidly, creating the signature dense, truffle-like mouthfeel.", "Using 100% unsweetened chocolate allows us to add enough sugar to get a crust without making the interior cloyingly sweet.", "Because there is no chemical leavening (baking powder/soda), the vigorous whisking of the eggs provides the only lift.", "Cut these with a hot knife (dipped in hot water and wiped dry) for perfectly clean edges."]', '"The brownie is a quintessentially American invention, first appearing in the late 19th century. This specific variation borrows technique from French ganache making, utilizing a thermal shock to manipulate the crystallization of fats for a denser, more luxurious texture than the traditional cake-like brownie."', 329.89);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('da2444d3-328e-4618-9dfa-ac13122a82ed', 'Classic Potato Latkes', 'Crispy, golden-brown potato pancakes featuring lacy, shattered-glass edges and a tender, steaming onion-scented interior. These traditional fritters balance savory depth with the natural sweetness of russet potatoes.', 'side dish', 'Ashkenazi Jewish', 'Intermediate', '["jewish", "potato", "winter", "kosher", "hanukkah", "comfort food", "fried"]', '[{"group_name": "Vegetables", "items": [{"name": "russet potatoes", "quantity": 1000, "unit": "g", "preparation": "peeled", "notes": "High starch content is essential for structure", "substitutions": [], "ingredient_id": "5bf06478-4785-465e-9842-f70a24e22054", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 250, "unit": "g", "preparation": "peeled", "notes": "Approx. 1 large onion", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Binder & Seasoning", "items": [{"name": "large eggs", "quantity": 2, "unit": null, "preparation": "beaten", "notes": "approx 100g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "matzo meal", "quantity": 30, "unit": "g", "preparation": null, "notes": "provides traditional texture", "substitutions": ["all-purpose flour", "potato starch"], "ingredient_id": "ba4dc343-44a8-4365-a655-e5be9f495ff4", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 8, "unit": "g", "preparation": null, "notes": "plus more for finishing", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Frying", "items": [{"name": "vegetable oil", "quantity": 250, "unit": "ml", "preparation": null, "notes": "Canola or grapeseed; quantity may vary based on pan size", "substitutions": ["schmaltz (rendered chicken fat)"], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}]}]', '[{"step_number": 1, "phase": "prep", "text": "Using the large holes of a box grater or a food processor, grate the potatoes and onion together. Alternating the onion with the potato helps prevent the potato from oxidizing and turning pink.", "structured": {"action": "GRATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Transfer the grated mixture to a cheesecloth or clean tea towel. Twist and squeeze vigorously to extract as much liquid as possible into a bowl. This step is critical for crispiness.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Let the extracted liquid sit in the bowl for 5 minutes to allow the potato starch to settle at the bottom. Carefully pour off and discard the water, leaving the white, pasty starch at the bottom of the bowl.", "structured": {"action": "DRAIN", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Return the dried grated potato and onion to the bowl with the reserved starch. Add eggs, matzo meal, salt, and pepper. Mix by hand until thoroughly combined.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour oil into a heavy skillet to a depth of roughly 6mm (1/4 inch). Heat over medium-high heat until the oil reaches 180\u00b0C/350\u00b0F or a shred of potato sizzles immediately upon contact.", "structured": {"action": "HEAT", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Scoop about 60ml (1/4 cup) of mixture per latke into the hot oil. Flatten slightly with a spatula to ensure even cooking. Fry for 3-4 minutes per side until deeply golden brown and crisp.", "structured": {"action": "FRY", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Deep golden brown edges", "tactile": "Rigid and crisp structure"}}, "tips": ["Do not crowd the pan; fry in batches to maintain oil temperature."]}, {"step_number": 7, "phase": "finish", "text": "Transfer fried latkes to a wire rack set over a baking sheet. Sprinkle immediately with a pinch of salt while hot to enhance flavor.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT15M", "total_time": "PT1H", "overnight_required": false, "yields": "12 latkes", "yield_count": 12, "serving_size_g": 85}', '{"flags": ["Vegetarian", "Dairy-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 78.48, "protein_g": 3.69, "carbohydrates_g": 14.48, "fat_g": 0.9, "saturated_fat_g": 0.3, "trans_fat_g": null, "monounsaturated_fat_g": 0.31, "polyunsaturated_fat_g": 0.2, "fiber_g": 2.55, "sugar_g": 0.93, "sodium_mg": 279.7, "cholesterol_mg": 31, "potassium_mg": 390.5, "calcium_mg": 35.61, "iron_mg": 2.95, "magnesium_mg": 23.17, "phosphorus_mg": 56.7, "zinc_mg": 0.44, "vitamin_a_mcg": 13.38, "vitamin_c_mg": 11.04, "vitamin_d_mcg": 0.17, "vitamin_e_mg": 0.09, "vitamin_k_mcg": 0.38, "vitamin_b6_mg": 0.24, "vitamin_b12_mcg": 0.07, "thiamin_mg": 0.03, "riboflavin_mg": 0.08, "niacin_mg": 0.89, "folate_mcg": 22.07, "water_g": 94.35, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Texture will soften; reheat in a 200\u00b0C/400\u00b0F oven to re-crisp.", "duration": "P2D"}, "freezer": {"notes": "Freeze in a single layer, then transfer to a bag. Reheat from frozen in oven.", "duration": "P2M"}, "reheating": "Place on a wire rack in a 190\u00b0C (375\u00b0F) oven for 10-15 minutes until crisp. Do not microwave.", "does_not_keep": false}', '[{"name": "Box grater", "required": true, "alternative": "Food processor with shredding disk"}, {"name": "Cheesecloth", "required": true, "alternative": "Clean tea towel or strong nut milk bag"}, {"name": "Heavy-bottomed skillet", "required": true, "alternative": "Cast iron pan"}, {"name": "Wire rack", "required": true, "alternative": "Paper towel lined plate"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Slotted spatula", "required": true, "alternative": null}]', '[{"symptom": "Latkes are soggy or greasy", "likely_cause": "Oil temperature dropped too low or potatoes were not squeezed dry enough", "prevention": "Ensure oil is 180\u00b0C/350\u00b0F before adding each batch; do not overcrowd pan", "fix": "Place on a wire rack in a 200\u00b0C/400\u00b0F oven for 5-10 minutes to help crisp up"}, {"symptom": "Latkes falling apart in oil", "likely_cause": "Mixture too wet or insufficient binder", "prevention": "Squeeze potatoes very dry; ensure eggs and flour/meal are well distributed", "fix": "Add another tablespoon of matzo meal or flour to the remaining batter"}]', '["The secret to the crispiest latke is the ''starch recovery'' step. Never skip saving the white starch at the bottom of the potato water.", "For the most traditional flavor, use schmaltz (rendered chicken fat) or a 50/50 mix of schmaltz and vegetable oil.", "Serve immediately with cold applesauce and sour cream for the classic hot-cold, savory-sweet contrast.", "If frying a large batch, keep the finished latkes warm in a 120\u00b0C/250\u00b0F oven while you finish the rest.", "Use Russet or other high-starch baking potatoes; waxy potatoes will result in a gummy texture."]', '"Latkes are synonymous with Hanukkah, the Festival of Lights, where eating foods fried in oil commemorates the miracle of the oil that burned for eight days in the Holy Temple. While potato latkes became the standard in 19th-century Eastern Europe due to the availability of potatoes, earlier versions were often made from cheese or buckwheat."', 78.48);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('dab1d87b-8306-4369-9552-a0b9d37a1ecb', 'Spiced Pear and Pistachio Phyllo Strudel', 'A sophisticated twist on the Austrian classic, featuring tender, cardamom-spiced pears and emerald green pistachios encased in shattering layers of golden, buttered phyllo pastry. A perfect festive centerpiece.', 'dessert', 'European', 'Intermediate', '["pear", "phyllo", "pistachio", "dessert", "winter", "vegetarian", "christmas"]', '[{"group_name": "Filling", "items": [{"name": "firm pears (bosc or anjou)", "quantity": 600, "unit": "g", "preparation": "peeled, cored, and diced into 1cm cubes", "notes": "approx. 4 medium pears", "substitutions": [], "ingredient_id": "ed5dd928-efa8-4c10-aeb3-3c08c94c62f8", "nutrition_source": "USDA FoodData Central"}, {"name": "shelled pistachios", "quantity": 100, "unit": "g", "preparation": "roughly chopped", "notes": "unsalted, roasted", "substitutions": [], "ingredient_id": "59207580-65c8-4564-9467-eb7286b8e5a7", "nutrition_source": "USDA FoodData Central"}, {"name": "brown sugar", "quantity": 80, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cardamom", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "c56f6cd8-882c-487c-956f-3a91ee1fec07", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 1, "unit": "g", "preparation": null, "notes": "approx 0.5 tsp", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pastry & Assembly", "items": [{"name": "phyllo dough sheets", "quantity": 10, "unit": null, "preparation": "thawed", "notes": "approx 250g total weight", "substitutions": [], "ingredient_id": "c070937d-c91b-4f22-90f4-6ec707a13cd2", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 120, "unit": "g", "preparation": "melted", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "panko breadcrumbs", "quantity": 40, "unit": "g", "preparation": "fine", "notes": null, "substitutions": ["ground almonds", "cookie crumbs"], "ingredient_id": "84fbc204-4457-40ed-83c1-3e5a7bcd8f23", "nutrition_source": "Aggregated Public Data"}, {"name": "powdered sugar", "quantity": 10, "unit": "g", "preparation": null, "notes": "for dusting", "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 190\u00b0C (375\u00b0F). Line a baking sheet with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, combine the diced pears, chopped pistachios, brown sugar, cornstarch, lemon juice, cardamom, cinnamon, vanilla, and salt. Toss well to coat the fruit evenly. Set aside to macerate slightly while preparing the dough.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": ["The cornstarch is crucial to absorb pear juices and prevent a soggy bottom."]}, {"step_number": 3, "phase": "assemble", "text": "Lay one sheet of phyllo dough on a clean, dry surface or a large sheet of parchment. Keep the remaining phyllo covered with a slightly damp towel to prevent drying out. Brush the sheet lightly with melted butter and sprinkle with a small amount of breadcrumbs.", "structured": {"action": "LAMINATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Repeat this process, stacking the phyllo sheets one on top of the other, brushing each with butter and sprinkling with breadcrumbs, until you have used all 10 sheets. Do not butter the very top layer yet.", "structured": {"action": "LAMINATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Spoon the pear mixture along the longer edge of the phyllo stack, leaving a 5cm (2-inch) border on the sides and bottom.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Fold the side borders in over the filling. Roll the strudel up tightly from the filled long edge, encasing the fruit completely. Place the strudel seam-side down on the prepared baking sheet.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Brush the entire exterior of the strudel generously with the remaining melted butter. Using a sharp knife, score the top of the pastry diagonally every 4cm (1.5 inches) to allow steam to escape (do not cut all the way through).", "structured": {"action": "SCORE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Bake in the preheated oven for 35-40 minutes, or until the phyllo is deep golden brown and crisp to the touch.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT35M", "doneness_cues": {"visual": "Deep golden brown pastry", "tactile": "Hollow sound when tapped lightly"}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove from the oven and let cool on the pan for at least 20 minutes to allow the filling to set. Dust with powdered sugar before slicing and serving.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT40M", "total_time": "PT1H25M", "overnight_required": false, "yields": "8 slices", "yield_count": 8, "serving_size_g": 165}', '{"flags": ["Vegetarian", "Egg-Free", "Soy-Free"], "not_suitable_for": ["Vegans (contains butter)"]}', '{"per_serving": {"calories": 384.77, "protein_g": 5.82, "carbohydrates_g": 48.27, "fat_g": 19.9, "saturated_fat_g": 8.79, "trans_fat_g": null, "monounsaturated_fat_g": 7.47, "polyunsaturated_fat_g": 2.61, "fiber_g": 4.58, "sugar_g": 19.74, "sodium_mg": 218.46, "cholesterol_mg": 32.25, "potassium_mg": 260.81, "calcium_mg": 37.68, "iron_mg": 1.83, "magnesium_mg": 27.16, "phosphorus_mg": 98.64, "zinc_mg": 0.55, "vitamin_a_mcg": 106.62, "vitamin_c_mg": 4.71, "vitamin_d_mcg": null, "vitamin_e_mg": 0.83, "vitamin_k_mcg": 5.17, "vitamin_b6_mg": 0.25, "vitamin_b12_mcg": 0.03, "thiamin_mg": 0.29, "riboflavin_mg": 0.16, "niacin_mg": 1.58, "folate_mcg": 40.06, "water_g": 78.55, "alcohol_g": 0.22, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Phyllo loses crispness rapidly in the fridge. Re-crisp in oven before serving.", "duration": "P2D"}, "freezer": {"notes": "Freeze unbaked for best results. Bake from frozen, adding 10-15 minutes to time.", "duration": "P1M"}, "reheating": "Oven at 180\u00b0C/350\u00b0F for 10-15 minutes to recrisp.", "does_not_keep": false}', '[{"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Pastry brush", "required": true, "alternative": null}, {"name": "Sharp knife", "required": true, "alternative": null}, {"name": "Clean kitchen towel", "required": true, "alternative": "Damp paper towels"}]', '[{"symptom": "Strudel is soggy on the bottom", "likely_cause": "Excess moisture from pears or insufficient breadcrumbs between layers", "prevention": "Ensure pears are tossed with cornstarch; do not skip the breadcrumb layer between phyllo sheets", "fix": "Bake on the lowest oven rack for an extra 5-10 minutes; serve slices with a custard sauce to mask the texture"}]', '["Thaw phyllo dough in the refrigerator overnight, never on the counter, to prevent the sheets from sticking together.", "Bosc pears are preferred over Bartlett because they hold their shape better during baking and release less liquid.", "The breadcrumbs between the layers act as a barrier, absorbing butter and creating separation for maximum flake.", "Serve warm with a dollop of mascarpone or vanilla bean cr\u00e8me anglaise for a luxurious finish.", "If the phyllo tears while rolling, simply patch it with a little melted butter and an extra scrap of dough; it will not be visible after baking."]', '"While Strudel is synonymous with Austrian cuisine (Apfelstrudel gained popularity in the 18th century Habsburg Empire), its roots trace back to the Middle East. The thin, stretched dough is a direct descendant of Turkish baklava pastry. This recipe bridges that history by utilizing pistachios and cardamom, flavors prominent in the dough''s geographical origins."', 384.77);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('db05d05e-baab-4383-a863-5861889ff0cc', 'Doenjang Boston Brown Bread', 'A savory-leaning interpretation of the New England classic. The earthy funk of Korean doenjang amplifies the rye and molasses notes, curbing the traditional sweetness while adding a complex umami depth. Steamed to a moist, pudding-like consistency.', 'bread', 'Fusion', 'Intermediate', '["new england", "breads", "buttermilk", "doenjang", "molasses", "rye flour", "steamed", "fusion"]', '[{"group_name": "Dry Mix", "items": [{"name": "rye flour", "quantity": 120, "unit": "g", "preparation": "medium grind", "notes": null, "substitutions": [], "ingredient_id": "af2661d8-b555-4fef-bdee-51a5190eda92", "nutrition_source": "USDA FoodData Central"}, {"name": "cornmeal", "quantity": 140, "unit": "g", "preparation": "stone ground preferred", "notes": null, "substitutions": [], "ingredient_id": "7fb6be00-5ba2-483a-af74-961f21de4055", "nutrition_source": "Aggregated Public Data"}, {"name": "whole wheat flour", "quantity": 130, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "af2661d8-b555-4fef-bdee-51a5190eda92", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wet Mix", "items": [{"name": "buttermilk", "quantity": 480, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "de1c3d44-e3e7-47d2-a315-83a46edfb165", "nutrition_source": "USDA FoodData Central"}, {"name": "molasses", "quantity": 200, "unit": "g", "preparation": "mild or robust flavor", "notes": null, "substitutions": [], "ingredient_id": "c76e81ce-ce17-4595-b9ff-30c87fb7c285", "nutrition_source": "USDA FoodData Central"}, {"name": "doenjang", "quantity": 45, "unit": "g", "preparation": null, "notes": "Korean fermented soybean paste", "substitutions": ["miso paste (white or red)"], "ingredient_id": "93076b4f-80eb-42d8-a5a0-78d680761a26", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Preparation", "items": [{"name": "unsalted butter", "quantity": 15, "unit": "g", "preparation": "softened", "notes": "for greasing cans", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Generously grease the inside of two clean 400-500ml steel cans with softened butter. Place a trivet or a folded kitchen towel at the bottom of a large stockpot to prevent the cans from rattling. Fill the pot with enough water to reach halfway up the sides of the cans, but remove the cans before heating. Bring the water to a boil.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, whisk together the rye flour, cornmeal, whole wheat flour, and baking soda until thoroughly combined and free of lumps.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a separate bowl or large measuring jug, whisk the buttermilk and molasses. Add the doenjang and whisk vigorously until the paste is completely dissolved into the liquid. It must be smooth to ensure even seasoning.", "structured": {"action": "DISSOLVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "mix", "text": "Pour the wet ingredients into the dry ingredients. Fold gently with a spatula just until no dry streaks of flour remain. Do not overmix, or the bread will become tough.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Divide the batter evenly between the prepared cans. They should be about two-thirds full. Cover the top of each can with a piece of aluminum foil greased with butter on the underside. Tie the foil tightly around the rim of the can with kitchen twine to create a steam-proof seal.", "structured": {"action": "FILL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Place the sealed cans into the pot of boiling water. Reduce heat to a gentle simmer. Cover the pot with a lid and steam for 2 hours and 15 minutes to 2 hours and 30 minutes. Check water level periodically, adding boiling water if it drops significantly.", "structured": {"action": "STEAM", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT2H30M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Check for doneness by inserting a skewer through the foil into the center of the bread. It should come out clean. The internal temperature should reach roughly 90\u00b0C/194\u00b0F.", "structured": {"action": "MEASURE", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": null, "doneness_cues": {"visual": "Skewer comes out clean", "tactile": "Firm to touch through foil"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove cans from the water and let them rest on a wire rack for 10-15 minutes. Run a thin knife around the edge to loosen, then invert the cans to slide the bread out. Slice and serve warm.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT2H30M", "total_time": "PT2H50M", "overnight_required": false, "yields": "2 loaves", "yield_count": 2, "serving_size_g": 85}', '{"flags": ["Vegetarian", "Nut-Free", "Peanut-Free"], "not_suitable_for": ["Gluten-Free diets", "Vegans (contains buttermilk)"]}', '{"per_serving": {"calories": 1216.33, "protein_g": 28.7, "carbohydrates_g": 253.18, "fat_g": 14.81, "saturated_fat_g": 6.25, "trans_fat_g": null, "monounsaturated_fat_g": 2.74, "polyunsaturated_fat_g": 1.81, "fiber_g": 22.75, "sugar_g": 91.58, "sodium_mg": 2448.63, "cholesterol_mg": 25.73, "potassium_mg": 2517.25, "calcium_mg": 534.4, "iron_mg": 14.2, "magnesium_mg": 592.6, "phosphorus_mg": 987.55, "zinc_mg": 7.56, "vitamin_a_mcg": 100.3, "vitamin_c_mg": 2.4, "vitamin_d_mcg": null, "vitamin_e_mg": 0.96, "vitamin_k_mcg": 3.14, "vitamin_b6_mg": 0.98, "vitamin_b12_mcg": 0.55, "thiamin_mg": 0.49, "riboflavin_mg": 0.6, "niacin_mg": 7.77, "folate_mcg": 47.23, "water_g": 254.87, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Wrap tightly in plastic wrap to maintain moisture.", "duration": "P1W"}, "freezer": {"notes": "Slice before freezing for easier reheating.", "duration": "P3M"}, "reheating": "Toast lightly or steam for 5 minutes to restore softness.", "does_not_keep": false}', '[{"name": "Large stockpot or Dutch oven", "required": true, "alternative": "Deep roasting pan"}, {"name": "Clean steel cans (400-500ml capacity)", "required": true, "alternative": "Pudding mold or heat-safe ceramic bowls"}, {"name": "Aluminum foil", "required": true, "alternative": null}, {"name": "Kitchen twine", "required": true, "alternative": null}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Wire rack", "required": true, "alternative": null}]', '[{"symptom": "Bread is gummy or raw in the center", "likely_cause": "Insufficient steaming time or water did not maintain a simmer", "prevention": "Ensure water remains at a simmer throughout and cover the pot lid tightly to trap steam", "fix": "Return to the steamer (resealed) for another 20-30 minutes"}, {"symptom": "Bread stuck inside the can", "likely_cause": "Insufficient greasing or can has internal ridges", "prevention": "Butter cans liberally; ensure cans are straight-sided without a lip", "fix": "Open the bottom of the can with a can opener and push the loaf through"}]', '["Doenjang is saltier and funkier than miso. Its inclusion here bridges the gap between the malty molasses and the grassy rye flour, creating a flavor profile reminiscent of salted caramel and dark stout beer.", "Traditional ''Thirded'' bread uses equal volumes of the three flours. We use metric weights here for precision, but the ratios remain close to tradition.", "If you cannot find clean tins, a heat-proof pudding mold or a ceramic bowl covered tightly will work, though the cooking time may increase by 15-20 minutes depending on the width of the vessel.", "Do not skip the resting period after steaming. The structure of the bread sets as it cools slightly; unmolding too early may cause it to crumble."]', '"Boston Brown Bread dates back to early colonial New England, utilizing ''thirded'' flour (wheat, rye, and corn) when wheat was scarce. Traditionally cooked in a hearth or on a stove in metal molds (often repurposed coffee cans) due to the lack of ovens in some homes, it remains a Saturday night staple alongside baked beans. This version introduces a Korean fermentation element, Doenjang, respecting the preservation-heavy history of New England cuisine."', 1216.33);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('dc373709-c1ba-44e6-adb9-a1e414d0cbf3', 'Lemon Drizzle Muffins', 'Bright, fluffy muffins infused with fresh lemon zest and topped with a tangy, crunchy lemon sugar glaze that soaks into the crumb while warm.', 'baked good', 'British', 'Easy', '["muffins", "lemon", "drizzle", "dessert", "baking", "british", "snack", "afternoon tea"]', '[{"group_name": "Dry Ingredients", "items": [{"name": "all-purpose flour", "quantity": 250, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "69f85167-e848-489c-b0e8-f6be21f27665", "nutrition_source": "Aggregated Public Data"}, {"name": "fine sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 2, "unit": null, "preparation": null, "notes": "zest of 2 lemons, about 6-8g", "substitutions": [], "ingredient_id": "a5fb6a2a-dcda-4ab2-8fe6-472d7fcc39d1", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Wet Ingredients", "items": [{"name": "eggs", "quantity": 2, "unit": null, "preparation": "room temperature, large", "notes": "approx 100g without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "plain yogurt or sour cream", "quantity": 120, "unit": "g", "preparation": null, "notes": "full fat preferred for moisture", "substitutions": [], "ingredient_id": "7aa0c485-bcc4-4d96-a4e0-c2a2200ad814", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable oil", "quantity": 100, "unit": "ml", "preparation": null, "notes": "neutral oil like sunflower or canola", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 30, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "d9823951-2391-49ba-90b4-7d8272161b6f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Lemon Drizzle", "items": [{"name": "lemon juice", "quantity": 60, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 50, "unit": "g", "preparation": null, "notes": "caster sugar works well too", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 190\u00b0C (375\u00b0F) and line a 12-cup muffin tin with paper liners.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, rub the lemon zest into the 150g of sugar with your fingertips until the sugar resembles wet sand and is fragrant.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["This releases the lemon oils into the sugar for a stronger flavor."]}, {"step_number": 3, "phase": "prep", "text": "Add the flour, baking powder, and salt to the lemon-sugar mixture and whisk well to combine.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In a separate medium bowl, whisk together the eggs, yogurt, vegetable oil, 30ml lemon juice, and vanilla extract until smooth.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour the wet ingredients into the dry ingredients and gently fold with a spatula until just combined. Do not overmix; a few lumps are fine.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Stop mixing as soon as you no longer see streaks of dry flour."]}, {"step_number": 6, "phase": "cook", "text": "Divide the batter evenly among the 12 muffin cups.", "structured": {"action": "PORTION", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Bake for 18 to 22 minutes, or until the tops are golden and a toothpick inserted into the center comes out clean.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT20M", "doneness_cues": {"visual": "Golden tops", "tactile": "Toothpick comes out clean"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "While muffins are baking, mix the 60ml lemon juice and 50g granulated sugar in a small bowl for the drizzle. Do not dissolve the sugar completely.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove muffins from the oven and immediately poke several holes in each muffin using a skewer or toothpick.", "structured": {"action": "SCORE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Spoon the lemon drizzle over the hot muffins, allowing it to soak in while the sugar crystals remain on top for crunch.", "structured": {"action": "GLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 11, "phase": "finish", "text": "Allow muffins to cool in the pan for 10 minutes before transferring to a wire rack.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT25M", "total_time": "PT45M", "overnight_required": false, "yields": "12 muffins", "yield_count": 12, "serving_size_g": 95}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 241.57, "protein_g": 4.11, "carbohydrates_g": 34.25, "fat_g": 10, "saturated_fat_g": 1.82, "trans_fat_g": null, "monounsaturated_fat_g": 0.32, "polyunsaturated_fat_g": 0.25, "fiber_g": 0.65, "sugar_g": 17.7, "sodium_mg": 172.94, "cholesterol_mg": 31, "potassium_mg": 70.42, "calcium_mg": 78.08, "iron_mg": 0.51, "magnesium_mg": 6.37, "phosphorus_mg": 76.42, "zinc_mg": 0.26, "vitamin_a_mcg": 17.94, "vitamin_c_mg": 3.66, "vitamin_d_mcg": 0.17, "vitamin_e_mg": 0.11, "vitamin_k_mcg": 0.09, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": 0.07, "thiamin_mg": 0.03, "riboflavin_mg": 0.05, "niacin_mg": 0.28, "folate_mcg": 10.91, "water_g": 16.5, "alcohol_g": 0.14, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container to prevent drying out.", "duration": "P4D"}, "freezer": {"notes": "Freeze without the drizzle for best results, or wrap tightly with drizzle applied.", "duration": "P3M"}, "reheating": "Microwave for 10-15 seconds to restore fluffiness.", "does_not_keep": false}', '[{"name": "12-cup muffin tin", "required": true, "alternative": null}, {"name": "Paper muffin liners", "required": false, "alternative": "Butter and flour for greasing"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Medium mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Silicone spatula", "required": true, "alternative": null}, {"name": "Microplane or fine grater", "required": true, "alternative": null}, {"name": "Citrus juicer", "required": false, "alternative": null}, {"name": "Skewer or toothpick", "required": true, "alternative": null}]', '[{"symptom": "Muffins are tough or have tunnels inside", "likely_cause": "The batter was overmixed after adding wet ingredients", "prevention": "Fold gently using a spatula just until flour disappears", "fix": "Serve warm with butter to mask the texture"}, {"symptom": "Muffins are soggy", "likely_cause": "Left in the tin too long after drizzling", "prevention": "Remove from tin after 10 minutes to let steam escape", "fix": "Dry out in a low oven (100\u00b0C) for 5 minutes"}]', '["Rubbing the zest into the sugar is the secret to a professional bakery flavor; it extracts essential oils that would otherwise be lost.", "Using oil instead of butter ensures the muffins stay moist for days, even when refrigerated.", "For the classic ''drizzle'' crunch, use granulated sugar for the topping rather than caster or powdered sugar.", "These muffins freeze beautifully; just wrap them individually after they have completely cooled."]', '"The ''Lemon Drizzle'' is a stalwart of British baking, traditionally a loaf cake served at afternoon tea. This muffin variation adapts that beloved tart-and-sweet profile into a portable format, retaining the signature crunchy sugar topping that defines the style."', 241.57);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('dc63e663-6c05-48f9-8bb6-7a7f4a6f104c', 'Sapphire Consommé with Orange-Basil Sorbet', 'A striking interplay of temperature and color. The velvety, deep-purple chilled blueberry soup offers earthy sweetness, cut sharply by the icy, aromatic brightness of a fresh orange and sweet basil sorbet.', 'dessert', 'Fusion', 'Intermediate', '["blueberry", "orange", "sorbet", "soup", "dessert", "summer", "vegan", "gluten-free", "refined"]', '[{"group_name": "Blueberry Soup", "items": [{"name": "fresh blueberries", "quantity": 600, "unit": "g", "preparation": "washed", "notes": "Frozen wild blueberries also work very well", "substitutions": [], "ingredient_id": "0f9f22a4-4f00-4950-9145-943d55b6dec8", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 500, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "white sugar", "quantity": 80, "unit": "g", "preparation": null, "notes": "Adjust based on berry sweetness", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": null, "notes": "Strip from half a lemon", "substitutions": [], "ingredient_id": "9e54e651-2396-4bef-9625-00ed1c90838f", "nutrition_source": "Aggregated Public Data"}, {"name": "cinnamon stick", "quantity": 1, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "Aggregated Public Data"}, {"name": "cornstarch", "quantity": 10, "unit": "g", "preparation": null, "notes": "Dissolved in 15ml cold water", "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Orange & Basil Sorbet", "items": [{"name": "fresh orange juice", "quantity": 400, "unit": "ml", "preparation": "strained", "notes": "Approx 4-5 oranges", "substitutions": [], "ingredient_id": "a15da11d-f8dd-46e3-9ac5-725a7912f1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 100, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh basil leaves", "quantity": 20, "unit": "g", "preparation": "whole", "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}, {"name": "glucose syrup", "quantity": 30, "unit": "g", "preparation": null, "notes": "Prevents ice crystals; corn syrup is a valid substitute", "substitutions": [], "ingredient_id": "a37884dd-47fa-4fa8-a5f6-a2da640865b4", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish", "items": [{"name": "fresh blueberries", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0f9f22a4-4f00-4950-9145-943d55b6dec8", "nutrition_source": "USDA FoodData Central"}, {"name": "small basil leaves", "quantity": 12, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "417f8397-9065-4cd6-8820-0ab7363fbb08", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the sorbet syrup. Combine water, sugar, and glucose syrup in a saucepan. Bring to a simmer to dissolve the sugar completely.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Remove syrup from heat. Immediately add the fresh basil leaves, cover, and let steep until the liquid cools to room temperature. This preserves the bright green flavor without cooking the herb.", "structured": {"action": "STEEP", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Strain the basil syrup into the fresh orange juice. Whisk to combine. Chill this base in the refrigerator until it reaches 4\u00b0C/39\u00b0F.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Churn the orange-basil mixture in an ice cream maker according to manufacturer instructions until it reaches a soft-serve consistency. Transfer to a freezer-safe container and freeze for at least 2 hours to firm up.", "structured": {"action": "CHURN", "temperature": null, "duration": "PT25M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "While the sorbet freezes, start the soup. In a clean saucepan, combine blueberries, 500ml water, sugar, lemon zest strip, and cinnamon stick. Bring to a boil, then reduce heat and simmer gently until berries burst and soften.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Remove the cinnamon stick and lemon zest. Stir in the cornstarch slurry (cornstarch mixed with a splash of water) and cook for 1 more minute until slightly thickened. It should coat the back of a spoon lightly.", "structured": {"action": "THICKEN", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Liquid becomes glossy and slightly viscous", "tactile": "Coats back of spoon (nappe)"}}, "tips": []}, {"step_number": 7, "phase": "prep", "text": "Transfer the hot soup to a blender. Blend on high speed until very smooth. Be careful when blending hot liquids; vent the lid.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "prep", "text": "Pass the blended soup through a fine mesh sieve into a clean bowl. Use a ladle or spatula to push the liquid through, discarding the skins and seeds. This step is crucial for a Michelin-quality mouthfeel.", "structured": {"action": "STRAIN", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Cover the soup directly with plastic wrap (touching the surface) to prevent a skin from forming. Chill in the refrigerator until completely cold, ideally 4 hours.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT4H", "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "assemble", "text": "To serve, pour the chilled soup into shallow bowls. Place a generous quenelle or scoop of the orange-basil sorbet in the center. Garnish with reserved fresh berries and small basil leaves.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT6H", "total_time": "PT6H45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 220}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Soy-Free", "Nut-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 328.14, "protein_g": 2.13, "carbohydrates_g": 82.71, "fat_g": 0.78, "saturated_fat_g": 0.07, "trans_fat_g": null, "monounsaturated_fat_g": 0.13, "polyunsaturated_fat_g": 0.31, "fiber_g": 4.34, "sugar_g": 70.61, "sodium_mg": 10.91, "cholesterol_mg": null, "potassium_mg": 345.83, "calcium_mg": 34, "iron_mg": 0.86, "magnesium_mg": 26.03, "phosphorus_mg": 39.91, "zinc_mg": 0.41, "vitamin_a_mcg": 29.4, "vitamin_c_mg": 69.39, "vitamin_d_mcg": null, "vitamin_e_mg": 1.01, "vitamin_k_mcg": 54.29, "vitamin_b6_mg": 0.19, "vitamin_b12_mcg": 0.19, "thiamin_mg": 0.16, "riboflavin_mg": 0.11, "niacin_mg": 1.13, "folate_mcg": 56.02, "water_g": 386.75, "alcohol_g": null, "caffeine_mg": 2.85}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store soup and sorbet separately. Soup in airtight container.", "duration": "P3D"}, "freezer": {"notes": "Sorbet best consumed within 1 week for optimal texture.", "duration": "P1M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Heavy-bottomed saucepan", "required": true, "alternative": null}, {"name": "Blender", "required": true, "alternative": null}, {"name": "Fine mesh sieve", "required": true, "alternative": "Cheesecloth"}, {"name": "Ice cream maker", "required": false, "alternative": "Shallow metal pan for granita method"}, {"name": "Citrus juicer", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}]', '[{"symptom": "Sorbet is rock hard", "likely_cause": "Low sugar/alcohol content or freezer temperature is too low", "prevention": "Ensure glucose syrup is used; it helps control ice crystal size", "fix": "Let sit at room temperature for 10-15 minutes before scooping, or pulse briefly in a food processor"}, {"symptom": "Soup is too thick/gelatinous", "likely_cause": "Over-reduced liquid or too much cornstarch/natural pectin", "prevention": "Measure cornstarch accurately; do not over-boil", "fix": "Whisk in a splash of cold water or apple juice to loosen it before serving"}]', '["For the smoothest texture, strain the orange juice before mixing the sorbet base. Pulp interferes with the delicate crystal structure.", "If you do not have an ice cream maker, pour the base into a shallow pan and freeze, scraping with a fork every 30 minutes to create a granita texture instead.", "The soup can be seasoned with a pinch of cardamom or star anise instead of cinnamon for a more exotic profile.", "Serve immediately upon plating; the heat contrast (even if the soup is chilled, the sorbet is colder) causes the sorbet to melt into the soup, creating a creamy, evolving sauce."]', '"This dish draws inspiration from the Nordic tradition of ''Bl\u00e5b\u00e4rssoppa'' (blueberry soup), typically served warm or cold as an energy booster. Here, it is elevated with Mediterranean citrus and herbs, transforming a rustic staple into a refined plated dessert."', 328.14);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('de1c9c8c-d737-42f8-b11f-3c430b310f8e', 'Pear & Raspberry Frangipane Tart', 'A sophisticated French dessert layering textures and flavors: a crisp, buttery pâte sablée base spreads with tart homemade raspberry jam, topped with velvety almond cream (frangipane) and tender, vanilla-poached pears.', 'dessert', 'French', 'Advanced', '["pear", "raspberry", "tart", "dessert", "frangipane", "poached fruit", "french", "baking"]', '[{"group_name": "Poached Pears", "items": [{"name": "bosc or williams pears", "quantity": 3, "unit": null, "preparation": "peeled, halved, and cored", "notes": "firm but ripe, approx 500g total", "substitutions": [], "ingredient_id": "ed5dd928-efa8-4c10-aeb3-3c08c94c62f8", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 1000, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "granulated sugar", "quantity": 300, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla bean", "quantity": 1, "unit": null, "preparation": null, "notes": "split lengthwise", "substitutions": [], "ingredient_id": "90237166-b129-4858-8c9c-2f8a7ab9a301", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": "zested and juiced", "notes": "approx 40ml juice", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "P\u00e2te Sabl\u00e9e (Pastry)", "items": [{"name": "all-purpose flour", "quantity": 250, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 125, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "icing sugar", "quantity": 80, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "almond flour", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": "room temperature", "notes": "approx 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Raspberry Jam Layer", "items": [{"name": "fresh or frozen raspberries", "quantity": 200, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4f5b84c-c364-40cd-b737-375755e481f9", "nutrition_source": "USDA FoodData Central"}, {"name": "jam sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": ["granulated sugar with 2g pectin"], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Frangipane Filling", "items": [{"name": "unsalted butter", "quantity": 100, "unit": "g", "preparation": "softened", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "almond flour", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 2, "unit": null, "preparation": "room temperature", "notes": "approx 100g total", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "all-purpose flour", "quantity": 20, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "dark rum", "quantity": 15, "unit": "ml", "preparation": null, "notes": "or 2ml almond extract", "substitutions": [], "ingredient_id": "fcfa2efa-bfc7-479b-9e45-790a71bf91f9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Assembly & Finish", "items": [{"name": "flaked almonds", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5bcbb4d4-6845-4825-bd21-1c13e52b989c", "nutrition_source": "USDA FoodData Central"}, {"name": "apricot jam", "quantity": 50, "unit": "g", "preparation": "warmed", "notes": "for glazing", "substitutions": [], "ingredient_id": "a1e5e7ad-8e40-46f1-8918-57dba1352c38", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine water, 300g sugar, vanilla bean, and lemon zest/juice in a saucepan. Bring to a boil, then reduce heat to a gentle simmer.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add the peeled pear halves to the simmering syrup. Cover with a parchment cartouche (circle of paper) to keep them submerged. Poach until tender but firm (knife glides in easily). Remove from heat and let cool in the liquid.", "structured": {"action": "POACH", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT20M", "doneness_cues": {"visual": null, "tactile": "Knife enters with zero resistance"}}, "tips": ["Cooling in the liquid allows the pears to absorb the vanilla flavor and become translucent."]}, {"step_number": 3, "phase": "prep", "text": "In a small saucepan, combine raspberries, 100g jam sugar, and 10ml lemon juice. Boil vigorously until thickened to a jam consistency. Transfer to a bowl to cool completely.", "structured": {"action": "BOIL", "temperature": {"celsius": 105, "fahrenheit": 221}, "duration": "PT8M", "doneness_cues": {"visual": "Mixture coats the back of a spoon and wrinkles when touched", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "For the pastry: Pulse flour, icing sugar, almond flour, salt, and cold butter in a processor until it resembles breadcrumbs. Add the egg and pulse briefly until dough clumps together. Form into a disc, wrap in plastic, and chill.", "structured": {"action": "MIX", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Roll out the chilled dough on a lightly floured surface to 3mm thickness. Line the tart tin, trim excess, and prick the base with a fork. Freeze the lined tin for 20 minutes to prevent shrinkage.", "structured": {"action": "ROLL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Preheat oven to 180\u00b0C/355\u00b0F. Line the tart shell with parchment paper and fill with baking beans. Blind bake for 15 minutes. Remove paper and beans, then bake for another 5 minutes until pale golden. Cool slightly.", "structured": {"action": "BAKE", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "prep", "text": "Make frangipane: Cream 100g softened butter and 100g sugar until pale. Beat in eggs one at a time. Fold in 100g almond flour, 20g flour, and rum/extract until smooth.", "structured": {"action": "CREAM", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Spread the cooled raspberry jam evenly over the base of the tart shell. Spread the frangipane carefully over the jam layer, smoothing the top.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "assemble", "text": "Drain pears and pat dry. Slice them crosswise (keeping the shape intact) and fan them slightly. Press them gently into the frangipane in a spoke pattern. Scatter flaked almonds in the gaps.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "cook", "text": "Bake at 180\u00b0C/355\u00b0F until the frangipane is puffed and golden brown, and the pastry is crisp.", "structured": {"action": "BAKE", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT35M", "doneness_cues": {"visual": "Deep golden brown filling, set in the center", "tactile": null}}, "tips": []}, {"step_number": 11, "phase": "finish", "text": "While warm, brush the pears with warmed apricot jam for a professional shine. Let cool completely in the tin before serving.", "structured": {"action": "GLAZE", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT1H30M", "passive_time": "PT2H", "total_time": "PT3H30M", "overnight_required": false, "yields": "One 23cm tart (8-10 slices)", "yield_count": 8, "serving_size_g": 180}', '{"flags": ["Vegetarian"], "not_suitable_for": ["Nut allergies", "Gluten intolerance", "Lactose intolerance"]}', '{"per_serving": {"calories": 784.67, "protein_g": 9.24, "carbohydrates_g": 129.22, "fat_g": 27.25, "saturated_fat_g": 15.03, "trans_fat_g": 0.01, "monounsaturated_fat_g": 8.56, "polyunsaturated_fat_g": 2.03, "fiber_g": 5.7, "sugar_g": 80.8, "sodium_mg": 140.32, "cholesterol_mg": 130.22, "potassium_mg": 256.38, "calcium_mg": 56.59, "iron_mg": 1.48, "magnesium_mg": 36.74, "phosphorus_mg": 133.12, "zinc_mg": 0.93, "vitamin_a_mcg": 224.23, "vitamin_c_mg": 15.9, "vitamin_d_mcg": 0.38, "vitamin_e_mg": 2.15, "vitamin_k_mcg": 6.88, "vitamin_b6_mg": 0.1, "vitamin_b12_mcg": 0.22, "thiamin_mg": 0.1, "riboflavin_mg": 0.2, "niacin_mg": 1.05, "folate_mcg": 35.35, "water_g": 235.8, "alcohol_g": 0.63, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Cover loosely with foil or store in an airtight container to prevent the crust from softening.", "duration": "P3D"}, "freezer": {"notes": "Freeze unbaked (assembled) or baked. Thaw in fridge overnight.", "duration": "P1M"}, "reheating": "Refresh in a 160\u00b0C oven for 10 minutes to crisp the crust.", "does_not_keep": false}', '[{"name": "23cm (9-inch) fluted tart tin with removable bottom", "required": true, "alternative": null}, {"name": "Stand mixer or electric hand mixer", "required": true, "alternative": "Whisk and strong arm"}, {"name": "Heavy-bottomed saucepan", "required": true, "alternative": null}, {"name": "Rolling pin", "required": true, "alternative": null}, {"name": "Ceramic baking beans or uncooked rice", "required": true, "alternative": "Dried beans"}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Food processor", "required": false, "alternative": "Pastry cutter or hands"}]', '[{"symptom": "Soggy bottom crust", "likely_cause": "The jam released moisture into the crust or blind baking was insufficient.", "prevention": "Ensure jam is boiled down to a thick consistency and blind bake the crust until dry to the touch before filling.", "fix": "Bake on the lowest rack of the oven with heat from the bottom for an extra 5-10 minutes."}, {"symptom": "Frangipane split (curdled) during mixing", "likely_cause": "Ingredients were at different temperatures (e.g., cold eggs into soft butter).", "prevention": "Ensure butter and eggs are both at room temperature.", "fix": "Add a tablespoon of the flour from the recipe and beat vigorously to bring the emulsion back together."}]', '["Always dry the poached pears thoroughly on paper towels before placing them on the frangipane; excess liquid will ruin the almond cream texture.", "If you don''t have apricot jam for the glaze, you can reduce the pear poaching liquid until it becomes a thick syrup.", "The tart tastes best after resting for at least 4 hours, or even the next day, as the flavors meld and the almond cream sets fully.", "When making the pastry, stop mixing as soon as the dough clumps. Overworking develops gluten and makes the crust tough instead of short (crumbly)."]', '"This recipe is a variation of the ''Tarte Bourdaloue'', a classic Parisian dessert created in the 19th century on Rue Bourdaloue. While the original uses almond cream and pears, the addition of raspberry jam introduces a sharp acidity that cuts through the richness of the nuts and butter, a modern twist on the Belle \u00c9poque favorite."', 784.67);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('de78a86b-ccfe-4b23-8751-04d9f47c8b31', 'Classic Beef Bourguignon', 'A quintessential French stew featuring succulent beef chuck braised slowly in a velvety, mahogany red wine sauce. Deeply savory with caramelized notes from lardons and mushrooms, finished with pearl onions for a tender, melt-in-the-mouth experience.', 'dinner', 'French', 'Intermediate', '["beef stew meat", "great leftovers", "red wine", "dinner", "main course", "fall", "winter", "french classics", "comfort food"]', '[{"group_name": "The Meat & Base", "items": [{"name": "beef chuck roast", "quantity": 1500, "unit": "g", "preparation": "cut into 5cm cubes", "notes": "trimmed of hard fat/gristle", "substitutions": [], "ingredient_id": "e13154c7-fcc2-4dbd-a047-ec71e1fabd3f", "nutrition_source": "USDA FoodData Central"}, {"name": "thick-cut bacon", "quantity": 170, "unit": "g", "preparation": "cut into lardons (strips)", "notes": null, "substitutions": [], "ingredient_id": "339a356e-8f77-48fe-9293-b8e35fed3e6c", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "for searing", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Vegetables & Aromatics", "items": [{"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "carrots", "quantity": 2, "unit": null, "preparation": "sliced thickly", "notes": "approx 150g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "minced", "notes": "approx 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "tomato paste", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "41400e7f-7a06-42d2-a625-072c380d60b2", "nutrition_source": "Aggregated Public Data"}, {"name": "all-purpose flour", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Braising Liquid", "items": [{"name": "red wine", "quantity": 750, "unit": "ml", "preparation": "Pinot Noir or Burgundy", "notes": "Full bodied, dry", "substitutions": [], "ingredient_id": "0fc93141-8ba8-42e0-ac8b-b5af3851554c", "nutrition_source": "USDA FoodData Central"}, {"name": "beef stock", "quantity": 500, "unit": "ml", "preparation": "unsalted or low sodium", "notes": null, "substitutions": [], "ingredient_id": "787d0598-6162-4b49-a834-8ca6a9a25e15", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh thyme", "quantity": 4, "unit": null, "preparation": null, "notes": "sprigs", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "bay leaf", "quantity": 2, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eab2ef3a-7a0e-4188-b746-645b795ada1e", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish (The Grand Dipl\u00f4me)", "items": [{"name": "pearl onions", "quantity": 20, "unit": null, "preparation": "peeled", "notes": "approx 200g, frozen is acceptable", "substitutions": [], "ingredient_id": "5761b096-ea16-446e-8f23-acdd99737d4b", "nutrition_source": "Aggregated Public Data"}, {"name": "cremini mushrooms", "quantity": 250, "unit": "g", "preparation": "quartered", "notes": null, "substitutions": [], "ingredient_id": "fdd23eb2-a71c-46d1-932b-295adf7d5ae5", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 160\u00b0C/325\u00b0F. Pat the beef cubes extremely dry with paper towels; moisture inhibits browning.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a large Dutch oven over medium heat, saut\u00e9 the bacon lardons until the fat has rendered and the bacon is crisp. Remove bacon with a slotted spoon to a side plate, leaving the fat in the pot.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Bacon is browned and crisp", "tactile": "Bacon is firm"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Increase heat to medium-high. Working in batches to avoid overcrowding, sear the beef in the bacon fat until deeply browned on all sides. Remove seared beef to the plate with the bacon.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": "Dark brown crust on all sides", "tactile": null}}, "tips": ["Do not crowd the pan, or the meat will steam instead of sear.", "Add a splash of vegetable oil if the pot becomes too dry."]}, {"step_number": 4, "phase": "cook", "text": "Lower heat to medium. Add sliced carrots and diced onions to the remaining fat. Saut\u00e9 until onions are softened and lightly browned. Add minced garlic and cook for 1 minute until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Stir in the tomato paste and flour. Cook for 1-2 minutes, stirring constantly, to cook out the raw flour taste and coat the vegetables.", "structured": {"action": "MIX", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Pour in the red wine and beef stock. Scrape the bottom of the pot vigorously to release the fond (browned bits). Return the beef and bacon to the pot along with thyme sprigs and bay leaves. Bring to a simmer.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Liquid is bubbling gently", "tactile": "No stuck bits on bottom of pot"}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Cover the pot with a lid and transfer to the preheated oven. Braise for 2.5 to 3 hours, or until the beef is fork-tender.", "structured": {"action": "BRAISE", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT3H", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "While the stew braises, prepare the garnish. In a separate skillet, heat the butter over medium heat. Saut\u00e9 the pearl onions and mushrooms until browned and tender, about 10 minutes. Set aside.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Mushrooms are golden brown", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove the pot from the oven. Discard thyme sprigs and bay leaves. Stir in the saut\u00e9ed mushrooms and pearl onions. Simmer on the stovetop for 5 minutes to meld flavors. Garnish with fresh parsley before serving.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT50M", "passive_time": "PT3H", "total_time": "PT3H50M", "overnight_required": false, "yields": "6 generous bowls", "yield_count": 6, "serving_size_g": 350}', '{"flags": ["Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Vegetarians (contains beef, bacon)", "Those abstaining from alcohol (wine-heavy)"]}', '{"per_serving": {"calories": 899.8, "protein_g": 83.75, "carbohydrates_g": 20.93, "fat_g": 45.08, "saturated_fat_g": 16.68, "trans_fat_g": 1, "monounsaturated_fat_g": 18.33, "polyunsaturated_fat_g": 2.67, "fiber_g": 2.31, "sugar_g": 5.92, "sodium_mg": 1504.08, "cholesterol_mg": 251.07, "potassium_mg": 1770.56, "calcium_mg": 108.84, "iron_mg": 8.16, "magnesium_mg": 92.95, "phosphorus_mg": 763.36, "zinc_mg": 26.33, "vitamin_a_mcg": 259.58, "vitamin_c_mg": 10.36, "vitamin_d_mcg": 0.25, "vitamin_e_mg": 0.75, "vitamin_k_mcg": 35.16, "vitamin_b6_mg": 1.19, "vitamin_b12_mcg": 8.99, "thiamin_mg": 0.34, "riboflavin_mg": 0.61, "niacin_mg": 14.87, "folate_mcg": 29.71, "water_g": 323.83, "alcohol_g": 11.63, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves significantly after 24 hours.", "duration": "P4D"}, "freezer": {"notes": "Freeze without potatoes (if adding as a side) for best texture.", "duration": "P3M"}, "reheating": "Reheat gently on the stovetop over low heat, adding a splash of water or stock if the sauce has over-thickened.", "does_not_keep": false}', '[{"name": "Dutch Oven (5-7 liter)", "required": true, "alternative": "Heavy-bottomed pot and oven-safe casserole dish"}, {"name": "Large Skillet", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Chef''s Knife", "required": true, "alternative": null}]', '[{"symptom": "The meat is tough and chewy", "likely_cause": "The collagen has not yet broken down into gelatin", "prevention": "Ensure the cooking time is sufficient; chuck roast requires time, not high heat", "fix": "Return the pot to the oven or stove and cook for another 30-45 minutes until fork-tender"}]', '["The quality of the wine matters. Use a wine you would happily drink; a dry Pinot Noir or Cotes du Rhone is traditional and ideal.", "Drying the meat before searing is the single most important step for flavor development. Wet meat steams; dry meat browns.", "This dish tastes significantly better the next day as the flavors have time to mature and marry. It is the ultimate make-ahead meal.", "If using frozen pearl onions, thaw and pat them dry before saut\u00e9ing to ensure they brown rather than boil in their own liquid."]', '"Originating from the Burgundy region of France, this dish began as a peasant meal using tougher cuts of meat and local wine. It was elevated to haute cuisine status by Auguste Escoffier and later popularized globally by Julia Child, becoming a symbol of French gastronomic comfort."', 899.8);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('decec75f-171c-46ac-afc6-f6fd1a01988c', 'Velouté of Wild Mushrooms (No Cream)', 'A deeply savory, velvety soup that achieves a luxurious texture through a classic French roux and pureed mushrooms rather than heavy cream. Intense umami flavor comes from properly caramelized fungi and a splash of sherry.', 'soup', 'French', 'Intermediate', '["french", "soup", "dinner", "lunch", "appetizer", "fall", "winter", "vegetarian", "thanksgiving", "great leftovers"]', '[{"group_name": "Vegetables & Aromatics", "items": [{"name": "mixed mushrooms (cremini, shiitake, oyster)", "quantity": 600, "unit": "g", "preparation": "cleaned and sliced", "notes": "Use Cremini for color, Shiitake for depth", "substitutions": [], "ingredient_id": "8a4fb37c-f8db-4c2f-b14d-f2dc7aef4c24", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx. 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 1, "unit": "g", "preparation": "leaves picked", "notes": "approx. 1 tsp", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Base & Thickener", "items": [{"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "dry sherry or dry white wine", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "386eb850-d9bc-44ab-9713-8f2ec7d336c8", "nutrition_source": "Aggregated Public Data"}, {"name": "low-sodium vegetable stock", "quantity": 750, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "whole milk", "quantity": 120, "unit": "ml", "preparation": null, "notes": "Can substitute 2% milk", "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "To taste (approx 3g)", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "Freshly cracked, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Melt the butter in a heavy pot over medium-high heat. Add the sliced mushrooms.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Cook the mushrooms undisturbed for 4-5 minutes until browned, then stir and cook another 3-4 minutes. Proper browning is essential for flavor.", "structured": {"action": "CARAMELIZE", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Deep golden brown edges", "tactile": "Mushrooms have shrunk significantly"}}, "tips": ["Do not salt the mushrooms yet; salt draws out moisture and prevents browning."]}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to medium. Add the diced onion, garlic, and thyme. Cook until onions are soft and translucent.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Sprinkle the flour over the vegetables. Stir constantly for 2 minutes to cook out the raw flour taste.", "structured": {"action": "ROAST", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Vegetables are coated in a pasty layer", "tactile": "Nutty aroma develops"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour in the sherry (if using) to deglaze, scraping up any browned bits. Slowly whisk in the vegetable stock to prevent lumps.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Bring to a simmer, then lower heat. Cover and simmer gently for 15 minutes to marry flavors and thicken.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from heat. Use an immersion blender to puree about half of the soup, leaving some mushroom chunks for texture. Stir in the milk. Season with salt and pepper to taste.", "structured": {"action": "PUREE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Creamy consistency with visible mushroom pieces", "tactile": null}}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT15M", "total_time": "PT40M", "overnight_required": false, "yields": "4 bowls", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free", "Low-Sodium"], "not_suitable_for": ["Vegans (contains butter/milk)", "Gluten-Free diets (contains wheat flour)"]}', '{"per_serving": {"calories": 198.53, "protein_g": 7.66, "carbohydrates_g": 19.47, "fat_g": 10.93, "saturated_fat_g": 6.44, "trans_fat_g": null, "monounsaturated_fat_g": 2.89, "polyunsaturated_fat_g": 0.69, "fiber_g": 2.47, "sugar_g": 8.29, "sodium_mg": 1212.36, "cholesterol_mg": 27.19, "potassium_mg": 656.45, "calcium_mg": 65.92, "iron_mg": 1.26, "magnesium_mg": 27.09, "phosphorus_mg": 187.83, "zinc_mg": 1.04, "vitamin_a_mcg": 141.14, "vitamin_c_mg": 8.01, "vitamin_d_mcg": 0.69, "vitamin_e_mg": 0.31, "vitamin_k_mcg": 1.49, "vitamin_b6_mg": 0.23, "vitamin_b12_mcg": 0.22, "thiamin_mg": 0.17, "riboflavin_mg": 0.67, "niacin_mg": 5.61, "folate_mcg": 36.61, "water_g": 202.24, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Thickeness increases when chilled; thin with a splash of water or stock when reheating.", "duration": "P4D"}, "freezer": {"notes": "Texture may separate slightly upon thawing; blend briefly to emulsify.", "duration": "P2M"}, "reheating": "Reheat gently on the stove over medium-low heat, whisking frequently.", "does_not_keep": false}', '[{"name": "Heavy-bottomed pot or Dutch oven", "required": true, "alternative": null}, {"name": "Immersion blender", "required": true, "alternative": "Standard countertop blender"}, {"name": "Wooden spoon", "required": true, "alternative": null}, {"name": "Knife and cutting board", "required": true, "alternative": null}]', '[{"symptom": "Soup tastes bland", "likely_cause": "Mushrooms were not browned sufficiently or under-salted", "prevention": "Ensure mushrooms get deep golden brown in step 2 before adding onions.", "fix": "Add a teaspoon of soy sauce or a drop of vinegar to wake up the flavors."}, {"symptom": "Texture is lumpy or floury", "likely_cause": "Flour clumped when stock was added", "prevention": "Add stock slowly while stirring the flour-coated vegetables.", "fix": "Puree the entire batch until completely smooth, then add saut\u00e9ed fresh mushrooms back in if texture is desired."}]', '["Don''t crowd the mushrooms in step 1. If your pot is small, brown them in two batches to ensure they sear rather than steam.", "The flour and butter create a ''singer'' method (dusting ingredients with flour), which is easier than making a separate roux for this type of rustic soup.", "For a deeper color and flavor, use dark vegetable stock or mushroom soaking liquid if using dried mushrooms.", "This recipe is intentionally thick (a Velout\u00e9). If you prefer a thinner soup, warm an extra 100ml of stock or milk and whisk it in at the end."]', '"This soup is based on the French ''Velout\u00e9'' mother sauce technique, where a light stock is thickened with a blond roux. While modern ''Cream of Mushroom'' soups often rely heavily on heavy cream, traditional farmhouse French cookery often utilized the thickening power of flour and the richness of butter to create substantial textures with economical ingredients."', 198.53);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('df2ac04f-a86d-4bdd-a36c-45b7aea2f95b', 'Pan-Seared Striped Bass with Horseradish Chive Cream', 'Crisp-skinned, flaky striped bass fillets served with a cool, tangy sauce of sour cream, pungent horseradish, and fresh chives. The temperature contrast between the hot, buttery fish and the chilled, zesty cream creates a sophisticated yet quick dinner.', 'dinner', 'American', 'Easy', '["horseradish", "sour cream", "striped bass", "dinner", "easy", "quick", "main course", "seafood", "gluten-free"]', '[{"group_name": "Creamy Horseradish Sauce", "items": [{"name": "sour cream", "quantity": 120, "unit": "g", "preparation": "chilled", "notes": null, "substitutions": [], "ingredient_id": "d171100e-1088-4266-8d50-06cdedda7193", "nutrition_source": "USDA FoodData Central"}, {"name": "prepared horseradish", "quantity": 30, "unit": "g", "preparation": null, "notes": "drained slightly if very wet", "substitutions": [], "ingredient_id": "72f7fb8a-7b34-41ea-9e5f-8fec2553cae8", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh chives", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 2g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Striped Bass", "items": [{"name": "striped bass fillets", "quantity": 600, "unit": "g", "preparation": "skin-on, descaled", "notes": "4 fillets, approx 150g each", "substitutions": [], "ingredient_id": "d2240c9f-047d-4fdd-9701-b2cd006ae6b3", "nutrition_source": "USDA FoodData Central"}, {"name": "grapeseed oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "or other high-heat neutral oil", "substitutions": ["canola oil", "avocado oil"], "ingredient_id": "00f43166-1b77-4e77-9e30-e912a59d118a", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "generous pinch for skin", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a small mixing bowl, combine the sour cream, prepared horseradish, chopped chives, and lemon juice. Season with salt and black pepper to taste. Whisk until smooth and refrigerate until serving.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Pat the striped bass fillets extremely dry with paper towels, especially the skin side. Moisture is the enemy of crispiness. Using a sharp knife, score the skin lightly 2-3 times (do not cut deep into the flesh) to prevent curling. Season both sides generously with salt.", "structured": {"action": "SCORE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["If the fish has been in the fridge, let it sit at room temperature for 10 minutes before cooking."]}, {"step_number": 3, "phase": "cook", "text": "Heat the oil in a heavy-bottomed skillet over medium-high heat until shimmering but not smoking. Carefully place the fillets in the pan, skin-side down, laying them away from you to avoid splatter.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Immediately press down gently on each fillet with a spatula for 10-15 seconds to ensure the skin stays flat against the pan. Cook undisturbed for 4-5 minutes until the skin is golden brown, crispy, and the flesh is opaque 3/4 of the way up the side.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Skin is golden brown; flesh is mostly opaque", "tactile": "Skin feels rigid and crisp"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Flip the fillets carefully. If using butter, add it to the pan now and tilt the pan to baste the fish for 1-2 minutes until just cooked through. The internal temperature should reach 63\u00b0C/145\u00b0F.", "structured": {"action": "BASTE", "temperature": {"celsius": 63, "fahrenheit": 145}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove the fish from the pan and plate immediately, skin-side up to maintain crispiness. Serve with a dollop of the chilled horseradish chive sauce on the side or underneath the fish.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 215}', '{"flags": ["Pescatarian", "Gluten-Free", "Nut-Free", "Low-Carb", "Keto"], "not_suitable_for": ["Dairy-Free"]}', '{"per_serving": {"calories": 311.88, "protein_g": 27.71, "carbohydrates_g": 2.66, "fat_g": 20.77, "saturated_fat_g": 7.53, "trans_fat_g": null, "monounsaturated_fat_g": 5.01, "polyunsaturated_fat_g": 6.8, "fiber_g": 0.39, "sugar_g": 0.75, "sodium_mg": 453.69, "cholesterol_mg": 147.82, "potassium_mg": 457.6, "calcium_mg": 63.51, "iron_mg": 1.39, "magnesium_mg": 66.89, "phosphorus_mg": 331.77, "zinc_mg": 0.84, "vitamin_a_mcg": 138.82, "vitamin_c_mg": 5.04, "vitamin_d_mcg": 0.06, "vitamin_e_mg": 2.44, "vitamin_k_mcg": 1.21, "vitamin_b6_mg": 0.46, "vitamin_b12_mcg": 5.83, "thiamin_mg": 0.16, "riboflavin_mg": 0.1, "niacin_mg": 3.21, "folate_mcg": 22.09, "water_g": 153.92, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Fish is best eaten immediately; sauce keeps for 3-4 days.", "duration": "P2D"}, "freezer": {"notes": "Do not freeze cooked fish or dairy-based sauce.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Heavy-bottomed skillet (stainless steel or cast iron)", "required": true, "alternative": null}, {"name": "Fish spatula", "required": true, "alternative": "Thin metal spatula"}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Paper towels", "required": true, "alternative": null}]', '[{"symptom": "Fish skin sticks to the pan", "likely_cause": "The pan was not hot enough before adding fish, or you tried to flip it too early.", "prevention": "Ensure oil is shimmering before adding fish. Do not move the fish until a crust has formed.", "fix": "Remove the pan from heat and wait 1 minute; the cooling pan often releases the proteins. If skin tears, serve skinless side up."}]', '["Scoring the skin prevents the fillets from curling up into a ''U'' shape when the proteins contract from the heat.", "For the sauce, ''prepared horseradish'' is grated root in vinegar. Avoid ''horseradish sauce'' which is already mixed with mayo/cream and is too mild.", "Striped bass is sustainable and has a clean flavor, but this recipe also works beautifully with Red Snapper or Black Sea Bass.", "Always plate skin-side up. If you put the sauce on top of the skin, you will ruin the crispy texture you worked for."]', '"Striped bass is a prized catch along the Atlantic coast of North America, historically important in American culinary tradition since colonial times. Pairing fatty fish with sharp, acidic condiments like horseradish is a classic European technique used to cut through richness."', 311.88);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('dfab05f6-9dc4-4602-84fb-d4240ebd6095', 'Brown Butter Sea Salt Rice Crispy Treats', 'An elevated interpretation of the childhood classic, featuring deep, nutty notes from caramelized brown butter, balanced by flaky sea salt and rich vanilla bean paste. The texture is perfectly chewy and gooey, never hard.', 'dessert', 'American', 'Easy', '["brown butter", "five ingredient", "marshmallow", "easy", "dessert", "gluten-free", "no-bake", "american classics"]', '[{"group_name": "Base", "items": [{"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "cubed", "notes": "Cold or room temp", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "mini marshmallows", "quantity": 300, "unit": "g", "preparation": "fresh", "notes": "Ensure fresh for best texture", "substitutions": [], "ingredient_id": "430032c6-b60b-4130-855e-b8a3d879c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla bean paste", "quantity": 5, "unit": "ml", "preparation": null, "notes": "Or high-quality extract", "substitutions": ["vanilla extract"], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 3, "unit": "g", "preparation": "flaky", "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "gluten-free crisp rice cereal", "quantity": 160, "unit": "g", "preparation": null, "notes": "Check label to ensure no barley malt", "substitutions": [], "ingredient_id": "950e6c79-15ed-4147-9b9e-63f366c7aff8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Line a 20cm x 20cm (8x8 inch) baking pan with parchment paper, leaving an overhang on two sides for easy removal.", "structured": {"action": "PREPARE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In the large pot over medium heat, melt the butter. Continue cooking, swirling the pan frequently, until the butter foams, the milk solids turn a golden-brown color, and it smells nutty (about 5-7 minutes). Watch closely to prevent burning.", "structured": {"action": "CARAMELIZE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT7M", "doneness_cues": {"visual": "Golden brown specs (noisette) at bottom", "tactile": "Foaming subsides slightly"}}, "tips": ["Use a light-colored pan if possible to see the color change easier."]}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to low. Reserve 50g of marshmallows for later. Add the remaining 250g marshmallows to the brown butter. Stir constantly with a silicone spatula until completely melted and smooth.", "structured": {"action": "MELT", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Remove from heat immediately. Stir in the vanilla bean paste and sea salt.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Add the crisp rice cereal and the reserved 50g of mini marshmallows. Fold gently but quickly until the cereal is evenly coated.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Adding fresh marshmallows at the end creates pockets of gooey texture."]}, {"step_number": 6, "phase": "shape", "text": "Transfer the mixture to the prepared pan. Using a piece of greased parchment paper or lightly oiled hands, gently press the mixture into the corners to level it. Do not pack it down tightly.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Allow to cool at room temperature for at least 1 hour before slicing into squares.", "structured": {"action": "COOL", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT1H", "total_time": "PT1H20M", "overnight_required": false, "yields": "16 squares", "yield_count": 16, "serving_size_g": 45}', '{"flags": ["Gluten-Free", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": ["Vegans (contains gelatin and dairy)"]}', '{"per_serving": {"calories": 178.53, "protein_g": 1.35, "carbohydrates_g": 20.08, "fat_g": 11.58, "saturated_fat_g": 8.03, "trans_fat_g": 0.04, "monounsaturated_fat_g": 2.55, "polyunsaturated_fat_g": 0.29, "fiber_g": 1.02, "sugar_g": 17.34, "sodium_mg": 232.17, "cholesterol_mg": 17.75, "potassium_mg": 39.2, "calcium_mg": 35.5, "iron_mg": 0.61, "magnesium_mg": 6.38, "phosphorus_mg": 22.44, "zinc_mg": 0.24, "vitamin_a_mcg": 55.66, "vitamin_c_mg": 0.06, "vitamin_d_mcg": null, "vitamin_e_mg": 0.22, "vitamin_k_mcg": 1.07, "vitamin_b6_mg": 0.01, "vitamin_b12_mcg": 0.09, "thiamin_mg": 0.01, "riboflavin_mg": 0.03, "niacin_mg": 0.07, "folate_mcg": 2.02, "water_g": 2.27, "alcohol_g": 0.11, "caffeine_mg": 2}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Not recommended; refrigeration makes them hard.", "duration": null}, "freezer": {"notes": "Layer with parchment paper in an airtight container.", "duration": "P6W"}, "reheating": null, "does_not_keep": false}', '[{"name": "Large heavy-bottomed pot", "required": true, "alternative": "Dutch oven"}, {"name": "20cm x 20cm (8x8 inch) baking pan", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Silicone spatula", "required": true, "alternative": null}]', '[{"symptom": "Treats are rock hard", "likely_cause": "Marshmallows were cooked too long or at too high heat, or mixture was compressed too tightly in pan", "prevention": "Melt marshmallows on low heat just until smooth and press very gently into the pan", "fix": "Microwave individual squares for 5-10 seconds to soften before eating"}]', '["The secret to soft treats is low heat. High heat caramelizes the sugar in the marshmallows, turning it into hard candy once cooled.", "Browning the butter is the ''elevation'' step. It adds a toffee-like complexity that cuts through the simple sugar sweetness.", "To ensure this is truly Gluten-Free, you must buy specific GF rice cereal. Standard Rice Krispies contain barley malt, which has gluten.", "For ultra-clean cuts, lightly oil your knife before slicing the cooled block.", "Don''t skip the salt; it is essential to balance the sweetness of the marshmallows."]', '"Originating in the late 1930s in the United States, this ''no-bake'' confection became a staple of American home economics due to its simplicity and speed. This version applies French culinary technique (beurre noisette) to mature the flavor profile of the nostalgic childhood snack."', 178.53);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('dfbae951-ca9c-4978-98dc-4cbe7de3f5ee', 'Velvety Golden Coconut & Tofu Curry', 'A vibrant, aromatic one-pot curry featuring crisp-tender vegetables and sponge-like tofu cubes absorbing a rich, turmeric-spiked coconut broth. The sauce strikes a delicate balance between savory spices, creamy sweetness, and a bright lime finish.', 'dinner', 'Fusion', 'Easy', '["curry", "vegetables", "broccoli", "coconut milk", "curry powder", "great leftovers", "dinner", "main course", "vegan", "vegetarian", "one-pot"]', '[{"group_name": "Aromatics & Spices", "items": [{"name": "coconut oil", "quantity": 30, "unit": "ml", "preparation": "liquid", "notes": null, "substitutions": [], "ingredient_id": "bfc74b81-e1e0-4607-9eec-8d0eff76d78c", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 15, "unit": "g", "preparation": "grated or minced", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "mild curry powder", "quantity": 15, "unit": "g", "preparation": null, "notes": "high quality blend", "substitutions": [], "ingredient_id": "e714e2f1-2295-4e8c-8ccf-65c38381e71e", "nutrition_source": "USDA FoodData Central"}, {"name": "ground turmeric", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Main Components", "items": [{"name": "firm tofu", "quantity": 400, "unit": "g", "preparation": "pressed and cubed (2cm)", "notes": "extra firm preferred", "substitutions": [], "ingredient_id": "c4eda7fb-2427-41ae-a450-5ba5546eb700", "nutrition_source": "USDA FoodData Central"}, {"name": "broccoli florets", "quantity": 250, "unit": "g", "preparation": "bite-sized pieces", "notes": null, "substitutions": [], "ingredient_id": "b0a26615-a0a7-4b5c-9143-e9becf53b41a", "nutrition_source": "USDA FoodData Central"}, {"name": "red bell pepper", "quantity": 150, "unit": "g", "preparation": "sliced into strips", "notes": "approx 1 medium pepper", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "USDA FoodData Central"}, {"name": "carrots", "quantity": 100, "unit": "g", "preparation": "sliced into coins", "notes": null, "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Liquids & Seasoning", "items": [{"name": "full-fat coconut milk", "quantity": 400, "unit": "ml", "preparation": null, "notes": "do not shake, separate cream if possible", "substitutions": [], "ingredient_id": "c037ee7e-e3ed-4340-b8fb-d8ad284ba96e", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable stock", "quantity": 120, "unit": "ml", "preparation": null, "notes": "low sodium preferred", "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "tamari or soy sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": "use Tamari for Gluten-Free", "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "maple syrup", "quantity": 10, "unit": "ml", "preparation": null, "notes": "or brown sugar", "substitutions": [], "ingredient_id": "1358a800-6e05-4bfd-ab71-03e78728c0bc", "nutrition_source": "Aggregated Public Data"}, {"name": "lime juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Wrap the block of tofu in a clean kitchen towel or paper towels and place a heavy object on top (like a skillet) for 10-15 minutes to press out excess water. Cut into 2cm cubes.", "structured": {"action": "DRAIN", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat half the coconut oil in a large pot over medium-high heat (190\u00b0C/375\u00b0F). Add the tofu cubes and sear, undisturbed, until golden brown on at least two sides. Remove tofu from the pot and set aside.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT5M", "doneness_cues": {"visual": "Golden brown crust", "tactile": "Firm surface"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Lower heat to medium (175\u00b0C/350\u00b0F). Add the remaining oil, diced onion, and carrots. Saut\u00e9 until the onion is translucent and soft.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the minced garlic, ginger, curry powder, and turmeric. Stir constantly for 60 seconds until fragrant to bloom the spices, taking care not to burn them.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Spices darken slightly", "tactile": "Highly aromatic"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Deglaze the pot with the vegetable stock, scraping up any fond. Pour in the coconut milk, tamari, and maple syrup. Bring to a gentle simmer.", "structured": {"action": "SIMMER", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Add the broccoli florets and red bell pepper strips. Simmer gently for 5-7 minutes until vegetables are tender-crisp. Return the tofu to the pot for the last 2 minutes to warm through.", "structured": {"action": "POACH", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Broccoli is bright green", "tactile": "Vegetables yield to knife tip"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from heat. Stir in the fresh lime juice. Taste and adjust salt or acidity as needed before serving.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT15M", "total_time": "PT35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 380}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 537.89, "protein_g": 23.57, "carbohydrates_g": 29.35, "fat_g": 41.08, "saturated_fat_g": 28.77, "trans_fat_g": null, "monounsaturated_fat_g": 3.78, "polyunsaturated_fat_g": 5.61, "fiber_g": 10.74, "sugar_g": 12.14, "sodium_mg": 1379.71, "cholesterol_mg": null, "potassium_mg": 1030.84, "calcium_mg": 780.83, "iron_mg": 6.61, "magnesium_mg": 135.39, "phosphorus_mg": 387.15, "zinc_mg": 3.05, "vitamin_a_mcg": 295.07, "vitamin_c_mg": 113.71, "vitamin_d_mcg": null, "vitamin_e_mg": 2.43, "vitamin_k_mcg": 73.19, "vitamin_b6_mg": 0.48, "vitamin_b12_mcg": null, "thiamin_mg": 0.31, "riboflavin_mg": 0.25, "niacin_mg": 2.4, "folate_mcg": 116.75, "water_g": 292.33, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors deepen significantly overnight. Store in an airtight container.", "duration": "P4D"}, "freezer": {"notes": "Tofu texture becomes more spongy/chewy upon freezing; vegetables may lose crispness.", "duration": "P1M"}, "reheating": "Gently reheat on the stovetop over low heat, adding a splash of water if the sauce has thickened.", "does_not_keep": false}', '[{"name": "Large heavy-bottomed pot or Dutch oven", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Wooden spoon or spatula", "required": true, "alternative": null}]', '[{"symptom": "Sauce looks curdled or split", "likely_cause": "Boiled too vigorously after adding coconut milk", "prevention": "Keep heat at a gentle simmer; do not let it reach a rolling boil once milk is added", "fix": "Whisk in a tablespoon of warm water or additional coconut milk vigorously off the heat; the taste remains unaffected"}, {"symptom": "Tofu is bland inside", "likely_cause": "Insufficient pressing or lack of salt in the cooking liquid", "prevention": "Press tofu thoroughly to create space for sauce absorption", "fix": "Let the curry sit for 20 minutes before serving to allow tofu to absorb sauce"}]', '["Blooming the spices (Step 4) is the most critical technical step; frying the spices in fat releases fat-soluble flavor compounds that boiling water cannot extract.", "For the creamiest texture, use full-fat canned coconut milk, not the beverage type found in cartons.", "The acid from the lime juice added at the very end brightens the dish and cuts through the richness of the coconut fat\u2014do not skip it.", "If you prefer softer vegetables, add the broccoli at the same time as the carrots."]', '"While this dish uses Thai ingredients like coconut milk and ginger, the use of yellow ''curry powder'' is a distinct culinary marker of British-Indian fusion influence. This style of ''yellow curry'' has become a global staple for its comforting, mild heat and versatility with local vegetables."', 537.89);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('e0391db7-6cf4-4fe0-a522-6692a2eb7999', 'Chilled Lobster and Citrus Coleslaw', 'A luxurious upgrade to the classic picnic staple, featuring tender chunks of poached lobster meat folded into crisp green and red cabbage. The dressing is a creamy, lemon-spiked emulsion with hints of celery seed and Dijon, offering a refreshing balance of sweet seafood and bright acidity.', 'salad', 'American', 'Intermediate', '["american", "slaws", "cabbage", "lobster", "mayonnaise", "side dish", "summer", "raw"]', '[{"group_name": "Lobster", "items": [{"name": "lobster tails", "quantity": 3, "unit": null, "preparation": "raw, shell-on", "notes": "approx 150g each, total 450g raw weight", "substitutions": [], "ingredient_id": "34f2d550-b220-4b17-9c47-fc3e5674cc19", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 3000, "unit": "ml", "preparation": null, "notes": "for poaching", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 30, "unit": "g", "preparation": null, "notes": "for poaching water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables", "items": [{"name": "green cabbage", "quantity": 300, "unit": "g", "preparation": "finely shredded", "notes": "core removed", "substitutions": [], "ingredient_id": "3665bd9f-fcae-44a3-a11d-16c4ca6e52bd", "nutrition_source": "Aggregated Public Data"}, {"name": "red cabbage", "quantity": 100, "unit": "g", "preparation": "finely shredded", "notes": "for color", "substitutions": [], "ingredient_id": "9a6d138d-1f4e-48f1-af70-ad08153ff908", "nutrition_source": "USDA FoodData Central"}, {"name": "carrot", "quantity": 80, "unit": "g", "preparation": "julienned or grated", "notes": null, "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "scallions", "quantity": 2, "unit": null, "preparation": "thinly sliced", "notes": "approx 30g, white and green parts", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Citrus Dressing", "items": [{"name": "mayonnaise", "quantity": 120, "unit": "g", "preparation": null, "notes": "high quality", "substitutions": [], "ingredient_id": "97b74a34-8c1f-4c58-b70e-42c1de6d12aa", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "apple cider vinegar", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "3e25e626-c9b4-4b62-9d08-7c650bcb3d2b", "nutrition_source": "Aggregated Public Data"}, {"name": "sugar", "quantity": 5, "unit": "g", "preparation": null, "notes": "optional, to balance acidity", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "celery seeds", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "30c3f84e-7e3c-43a2-affa-a10986bed987", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh chives", "quantity": 5, "unit": "g", "preparation": "chopped", "notes": "for garnish", "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Bring the water and salt to a rolling boil in a large stockpot. Prepare a large bowl filled with ice and water nearby to stop the cooking process later.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add the lobster tails to the boiling water. Reduce heat to a simmer and cook for 6-8 minutes, or until the shells turn bright red and the meat is opaque. The internal temperature should reach 60\u00b0C (140\u00b0F).", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT8M", "doneness_cues": {"visual": "Shells bright red, meat opaque", "tactile": "Flesh feels firm"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Immediately transfer the lobster tails to the prepared ice bath. Let them cool completely for at least 5 minutes to arrest carry-over cooking.", "structured": {"action": "COOL", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "While lobster cools, combine the mayonnaise, lemon juice, apple cider vinegar, Dijon mustard, sugar (if using), celery seeds, and black pepper in a small bowl. Whisk until smooth and creamy.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Remove the lobster meat from the shells using kitchen shears to cut down the back of the tail. Chop the meat into generous bite-sized chunks (approx 2cm pieces).", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "In a large mixing bowl, combine the shredded green cabbage, red cabbage, grated carrot, sliced scallions, and chopped lobster meat.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Pour the dressing over the cabbage and lobster mixture. Toss gently but thoroughly to ensure every ingredient is evenly coated.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Cover the bowl and refrigerate for at least 30 minutes to allow the flavors to meld and the cabbage to soften slightly. Garnish with fresh chives before serving.", "structured": {"action": "CHILL", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT30M", "total_time": "PT1H", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 220}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free"], "not_suitable_for": ["Shellfish allergy"]}', '{"per_serving": {"calories": 340.53, "protein_g": 20.87, "carbohydrates_g": 10.99, "fat_g": 23.83, "saturated_fat_g": 3.74, "trans_fat_g": 0.07, "monounsaturated_fat_g": 5.38, "polyunsaturated_fat_g": 13.81, "fiber_g": 3.42, "sugar_g": 6.06, "sodium_mg": 3691.01, "cholesterol_mg": 155.48, "potassium_mg": 528.04, "calcium_mg": 181.22, "iron_mg": 1.45, "magnesium_mg": 71.03, "phosphorus_mg": 228.56, "zinc_mg": 4.34, "vitamin_a_mcg": 202.68, "vitamin_c_mg": 46.56, "vitamin_d_mcg": 0.06, "vitamin_e_mg": 2.18, "vitamin_k_mcg": 77.03, "vitamin_b6_mg": 0.21, "vitamin_b12_mcg": 1.44, "thiamin_mg": 0.06, "riboflavin_mg": 0.06, "niacin_mg": 2.15, "folate_mcg": 26.69, "water_g": 969.64, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best consumed within 24 hours as cabbage releases water and dressing thins.", "duration": "P2D"}, "freezer": {"notes": "Do not freeze; mayonnaise will split and vegetables will lose texture.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Large stockpot", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Kitchen shears", "required": true, "alternative": "Heavy knife"}]', '[{"symptom": "Lobster meat is rubbery and tough", "likely_cause": "The lobster was overcooked during the poaching step", "prevention": "Adhere strictly to cooking times and use an ice bath immediately", "fix": "Chop the meat into very small pieces so the texture is less noticeable when mixed with the crunchy cabbage"}, {"symptom": "Coleslaw is watery", "likely_cause": "Cabbage released water after sitting too long or was wet after washing", "prevention": "Dry cabbage thoroughly after washing; consume within 24 hours", "fix": "Drain excess liquid from the bottom of the bowl and stir in a spoonful of extra mayonnaise before serving"}]', '["To ensure the most tender lobster, you can detach the meat from the shell before cooking and poach it gently in butter (butter poaching), though water poaching keeps the dish lighter for summer.", "If you have time, toss the shredded cabbage with a teaspoon of salt and let it drain in a colander for 20 minutes before dressing. This removes excess moisture and keeps the slaw crunchy longer.", "Do not dress this slaw more than 2 hours before serving if possible; the acid in the dressing will eventually make the lobster meat mushy.", "For an authentic coastal flavor, add a pinch of Old Bay seasoning to the dressing."]', '"This dish marries two staples of American coastal cuisine: the mayonnaise-based coleslaw found at nearly every barbecue, and the New England tradition of fresh, cold lobster salads. It elevates the humble side dish to a centerpiece, reflecting the summer dining style of Maine and Massachusetts where seafood is abundant."', 340.53);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('e1e66848-79ba-498c-9496-0b54f89aa9b3', 'Spicy Falafel & Baked Bean Bowl', 'A hearty fusion dish featuring crispy, herb-packed pan-fried falafel served over a bed of savory, sriracha-spiked baked beans. The heat is balanced by a crisp, creamy coleslaw, creating a perfect interplay of textures and temperatures.', 'main course', 'Fusion', 'Easy', '["falafel", "baked beans", "vegetarian", "easy", "main course", "quick", "fusion", "budget-friendly"]', '[{"group_name": "Quick Falafel", "items": [{"name": "canned chickpeas", "quantity": 480, "unit": "g", "preparation": "drained and patted very dry", "notes": "two standard 400g cans drained", "substitutions": [], "ingredient_id": "bc61d002-fe4c-464e-97fc-4323b3f26855", "nutrition_source": "Aggregated Public Data"}, {"name": "onion", "quantity": 1, "unit": null, "preparation": "roughly chopped", "notes": "small red onion, approx 60g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": null, "notes": "approx 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "rough stems removed", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "ground coriander", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": ["chickpea flour", "oat flour"], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": "for frying", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sriracha Baked Beans", "items": [{"name": "canned baked beans", "quantity": 400, "unit": "g", "preparation": null, "notes": "in tomato sauce", "substitutions": [], "ingredient_id": "aa354290-96c6-437d-8069-4e87d7c95ac9", "nutrition_source": "USDA FoodData Central"}, {"name": "sriracha sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "180ad647-bd4a-4ec3-af84-05e7e3e5a4b3", "nutrition_source": "Aggregated Public Data"}, {"name": "smoked paprika", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Creamy Coleslaw", "items": [{"name": "cabbage", "quantity": 200, "unit": "g", "preparation": "shredded", "notes": null, "substitutions": [], "ingredient_id": "56b28b77-6754-4d1f-aaa0-0e99b7ef7931", "nutrition_source": "USDA FoodData Central"}, {"name": "carrot", "quantity": 1, "unit": null, "preparation": "grated", "notes": "approx 60g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "mayonnaise", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["greek yogurt"], "ingredient_id": "97b74a34-8c1f-4c58-b70e-42c1de6d12aa", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine shredded cabbage, grated carrot, mayonnaise, lemon juice, and salt in a bowl. Toss well and refrigerate to let flavors meld while cooking.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Place the drained and thoroughly dried chickpeas, onion, garlic, parsley, cumin, coriander, flour, and a pinch of salt into a food processor. Pulse until the mixture is coarse and grainy but holds together when squeezed. Do not puree into a paste.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Coarse texture resembling wet sand", "tactile": "Holds shape when squeezed"}}, "tips": ["If the mixture is too wet to hold shape, add another teaspoon of flour."]}, {"step_number": 3, "phase": "cook", "text": "Form the chickpea mixture into 12 small patties. Heat olive oil in a large frying pan over medium heat. Fry the falafel patties for 3-4 minutes per side until golden brown and crispy.", "structured": {"action": "FRY", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT8M", "doneness_cues": {"visual": "Deep golden brown crust", "tactile": "Crispy exterior"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "While the falafel cooks, combine the canned baked beans, sriracha, and smoked paprika in a small saucepan. Simmer gently over low heat until hot and slightly thickened.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "To serve, spoon the warm spicy beans into shallow bowls. Top with 3 falafel patties and a generous mound of coleslaw. Garnish with extra sriracha if desired.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT10M", "total_time": "PT40M", "overnight_required": false, "yields": "4 bowls", "yield_count": 4, "serving_size_g": 380}', '{"flags": ["Vegetarian", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 514.65, "protein_g": 18.43, "carbohydrates_g": 66.3, "fat_g": 24.52, "saturated_fat_g": 3.25, "trans_fat_g": 0.02, "monounsaturated_fat_g": 10.77, "polyunsaturated_fat_g": 6.55, "fiber_g": 22.8, "sugar_g": 18.56, "sodium_mg": 1413.39, "cholesterol_mg": 11.73, "potassium_mg": 1374.95, "calcium_mg": 242.95, "iron_mg": 13.43, "magnesium_mg": 57.31, "phosphorus_mg": 168.18, "zinc_mg": 5.92, "vitamin_a_mcg": 162.44, "vitamin_c_mg": 32.65, "vitamin_d_mcg": 0.02, "vitamin_e_mg": 2.5, "vitamin_k_mcg": 127.69, "vitamin_b6_mg": 0.21, "vitamin_b12_mcg": 0.01, "thiamin_mg": 0.13, "riboflavin_mg": 0.11, "niacin_mg": 1.07, "folate_mcg": 51.36, "water_g": 156.86, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store falafel, beans, and slaw in separate containers to maintain texture.", "duration": "P3D"}, "freezer": {"notes": "Falafel only. Beans and slaw do not freeze well.", "duration": "P1M"}, "reheating": "Reheat falafel in an oven or air fryer at 180\u00b0C to recrisp. Warm beans on the stovetop.", "does_not_keep": false}', '[{"name": "Food processor", "required": true, "alternative": "Potato masher and fine chopping skills"}, {"name": "Large frying pan", "required": true, "alternative": null}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Kitchen knife", "required": true, "alternative": null}]', '[{"symptom": "Falafel crumbles or falls apart in the pan", "likely_cause": "Chickpeas were too wet or mixture was not pressed firmly enough", "prevention": "Pat chickpeas extremely dry with paper towels before blending; press patties firmly when shaping", "fix": "Add more flour to the remaining mixture and refrigerate for 10 minutes before frying"}]', '["Canned chickpeas are softer than the traditional soaked-raw method. Drying them thoroughly before blending is the secret to a crispy result.", "For a deeper flavor profile, toast the cumin and coriander seeds briefly in a dry pan before grinding.", "The slaw provides necessary acidity and crunch to cut through the richness of the beans and falafel; do not skip the lemon juice."]', '"This recipe bridges Middle Eastern street food with British comfort staples. While traditional falafel uses raw soaked chickpeas, this ''quick'' style adapts to the pantry staple of canned beans, pairing them with the Western tradition of stewed beans for a hearty, vegetarian protein bowl."', 514.65);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('e2195766-fbaa-476c-a108-54664e580c51', 'Decadent Molten Chocolate Lava Cakes', 'Rich, single-serving chocolate cakes with a firm outer shell that yields a warm, flowing center of liquid chocolate ganache. A romantic bistro classic that feels sophisticated but comes together in minutes.', 'dessert', 'French', 'Intermediate', '["bittersweet chocolate", "egg", "dessert", "valentine''s day", "romantic", "quick"]', '[{"group_name": "Ramekin Prep", "items": [{"name": "unsalted butter", "quantity": 15, "unit": "g", "preparation": "softened", "notes": "for greasing", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "cocoa powder", "quantity": 10, "unit": "g", "preparation": "powder", "notes": "for dusting", "substitutions": [], "ingredient_id": "c06a8e5a-163a-4f21-ad00-a6d90e34c38c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Batter", "items": [{"name": "bittersweet chocolate (60-70%)", "quantity": 170, "unit": "g", "preparation": "chopped", "notes": "high quality couverture recommended", "substitutions": ["semisweet chocolate"], "ingredient_id": "119741fa-b6ad-458d-9cbb-fe79c9d2d687", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 113, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "large eggs", "quantity": 2, "unit": null, "preparation": "room temperature", "notes": "approx. 100g total (without shell)", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "large egg yolks", "quantity": 2, "unit": null, "preparation": "room temperature", "notes": "approx. 36g total", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 30, "unit": "g", "preparation": null, "notes": "sifted", "substitutions": ["gluten-free 1-to-1 baking flour"], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "large pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 220\u00b0C (425\u00b0F). Generously grease four 6-oz ramekins with the softened butter and dust with cocoa powder, tapping out the excess. This ensures the cakes release easily.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Combine the chopped chocolate and 113g cubed butter in a heatproof bowl. Melt gently over a double boiler or in the microwave in 20-second bursts, stirring until completely smooth. Set aside to cool slightly.", "structured": {"action": "MELT", "temperature": null, "duration": null, "doneness_cues": {"visual": "Glossy and smooth liquid", "tactile": "Warm to the touch, no lumps"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a separate medium bowl, beat the whole eggs, egg yolks, sugar, and salt together until the mixture is pale yellow and slightly thickened.", "structured": {"action": "BEAT", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Pale yellow color", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Pour the melted chocolate mixture into the egg mixture. Whisk gently until combined. Add the flour and fold it in with a spatula just until no streaks of flour remain. Do not overmix.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": {"visual": "Uniform dark brown batter", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Divide the batter evenly among the prepared ramekins. Place ramekins on a baking sheet. Bake for 12 to 14 minutes. The sides should be firm and rise away from the ramekin, but the center should still look soft and jiggle slightly when shaken.", "structured": {"action": "BAKE", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT13M", "doneness_cues": {"visual": "Edges firm, center jiggles", "tactile": "Top has a thin crust"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove from oven and let stand for 1 minute. Place a small dessert plate over the top of a ramekin and carefully invert it to release the cake. Dust with powdered sugar and serve immediately.", "structured": {"action": "PLATE", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT13M", "total_time": "PT28M", "overnight_required": false, "yields": "4 individual cakes", "yield_count": 4, "serving_size_g": 115}', '{"flags": ["Vegetarian", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Individuals avoiding undercooked eggs", "Vegans"]}', '{"per_serving": {"calories": 647.97, "protein_g": 10.43, "carbohydrates_g": 42.29, "fat_g": 50.47, "saturated_fat_g": 28.22, "trans_fat_g": 0.01, "monounsaturated_fat_g": 9.58, "polyunsaturated_fat_g": 1.86, "fiber_g": 6.57, "sugar_g": 28.43, "sodium_mg": 144.12, "cholesterol_mg": 259, "potassium_mg": 451.04, "calcium_mg": 65.64, "iron_mg": 5.25, "magnesium_mg": 18.22, "phosphorus_mg": 118.73, "zinc_mg": 0.78, "vitamin_a_mcg": 301.67, "vitamin_c_mg": null, "vitamin_d_mcg": 0.99, "vitamin_e_mg": 1.25, "vitamin_k_mcg": 2.46, "vitamin_b6_mg": 0.08, "vitamin_b12_mcg": 0.45, "thiamin_mg": 0.04, "riboflavin_mg": 0.18, "niacin_mg": 0.19, "folate_mcg": 28.6, "water_g": 29.91, "alcohol_g": null, "caffeine_mg": 5.75}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store unbaked batter in ramekins. Bake directly from cold, adding 2-3 minutes to bake time.", "duration": "P2D"}, "freezer": {"duration": null}, "reheating": "Microwave for 15-20 seconds if baked and cooled, though best eaten fresh.", "does_not_keep": true}', '[{"name": "Ramekins (6 oz / 180ml)", "required": true, "alternative": "Muffin tin (will change bake time)"}, {"name": "Mixing bowls", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Saucepan", "required": false, "alternative": "Microwave-safe bowl"}]', '[{"symptom": "No lava center (cake is solid)", "likely_cause": "Overbaked", "prevention": "Check 1-2 minutes earlier next time; all ovens vary slightly", "fix": "Serve with extra sauce or ice cream; it is still a delicious brownie"}, {"symptom": "Cake collapsed when unmolding", "likely_cause": "Underbaked or stuck to ramekin", "prevention": "Grease ramekins thoroughly; ensure sides are firm before removing from oven", "fix": "Serve inside the ramekin with a spoon"}]', '["The quality of chocolate defines this dish. Use a bar with 60-70% cocoa solids, not chocolate chips (which contain stabilizers that affect the melt).", "Temperature precision is key. If your oven runs cool, the center won''t heat through before the outside burns. An oven thermometer is recommended.", "Serve immediately. The molten center begins to cook through from residual heat the moment it leaves the oven.", "For an extra flavor dimension, add 5ml of espresso or orange liqueur to the chocolate mixture."]', '"Often claimed by chef Jean-Georges Vongerichten as a happy accident in New York in 1987, though French chef Michel Bras had a similar invention (using a frozen ganache core) slightly earlier. It became the definitive fine-dining dessert of the 1990s."', 647.97);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('e2485a85-d6fe-43ff-9b3b-501de9dba6fe', 'Lemon-Braised Fennel with Long-Grain Rice', 'Delicate anise notes of meltingly tender braised fennel infuse fluffy long-grain rice in this comforting one-pot side. Brightened with fresh lemon juice and herbaceous dill, it transforms simple ingredients into an elegant accompaniment.', 'side dish', 'Greek', 'Easy', '["broth", "fennel", "long-grain rice", "weeknight", "side dish", "vegetarian", "vegan", "greek", "one-pot"]', '[{"group_name": "Vegetables & Aromatics", "items": [{"name": "fennel bulbs", "quantity": 2, "unit": null, "preparation": "trimmed, cored, and thinly sliced", "notes": "approx 450g total; reserve fronds for garnish", "substitutions": [], "ingredient_id": "a42d03de-0a8a-4a75-8299-5cf01d43b425", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "cc868876-7ceb-46a8-b72a-c3e8a743ee97", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": "extra virgin", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Rice & Braise", "items": [{"name": "long-grain white rice", "quantity": 200, "unit": "g", "preparation": null, "notes": "Basmati or Jasmine recommended", "substitutions": [], "ingredient_id": "2e654ed5-87a8-42bc-8533-90972c8137e1", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable broth", "quantity": 480, "unit": "ml", "preparation": "hot", "notes": null, "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "adjust based on broth salinity", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "fresh dill", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": ["fresh parsley"], "ingredient_id": "4be2b047-475d-4c84-82d5-4883298c6121", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": "from roughly half a lemon", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Rinse the rice in a fine-mesh sieve under cold running water until the water runs clear. Drain well.", "structured": {"action": "MEASURE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": ["Rinsing removes excess surface starch, preventing the rice from becoming gummy or sticky."]}, {"step_number": 2, "phase": "cook", "text": "Heat the olive oil in a large saut\u00e9 pan or Dutch oven over medium heat. Add the diced onion and sliced fennel. Saut\u00e9 for 8-10 minutes until the fennel softens and begins to brown slightly at the edges.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT10M", "doneness_cues": {"visual": "Fennel is translucent with golden edges", "tactile": "Softened texture"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the minced garlic and the drained rice to the pan. Stir constantly for 1-2 minutes until the garlic is fragrant and the rice grains are coated in oil and smell nutty.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour in the hot vegetable broth, salt, and pepper. Bring the liquid to a boil, then immediately reduce the heat to the lowest setting. Cover the pot with a tight-fitting lid.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Simmer gently on low heat for 15 minutes without lifting the lid. The goal is for the rice to absorb the liquid and the fennel to become tender.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove the pot from the heat. Keep the lid on and let the dish rest for 5-10 minutes. This creates steam that finishes the rice perfectly.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Uncover and fluff the rice with a fork. Stir in the lemon juice and fresh chopped dill. Garnish with reserved fennel fronds and serve immediately.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Rice is fluffy and separate", "tactile": "Tender grains"}}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT25M", "total_time": "PT40M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 220}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 313.78, "protein_g": 5.97, "carbohydrates_g": 54.72, "fat_g": 8.27, "saturated_fat_g": 1.3, "trans_fat_g": null, "monounsaturated_fat_g": 5.68, "polyunsaturated_fat_g": 1.08, "fiber_g": 5.03, "sugar_g": 8.1, "sodium_mg": 1122.39, "cholesterol_mg": null, "potassium_mg": 656.66, "calcium_mg": 94.43, "iron_mg": 3.55, "magnesium_mg": 36.21, "phosphorus_mg": 125.68, "zinc_mg": 0.83, "vitamin_a_mcg": 95.54, "vitamin_c_mg": 21.68, "vitamin_d_mcg": null, "vitamin_e_mg": 1.8, "vitamin_k_mcg": 75.67, "vitamin_b6_mg": 0.18, "vitamin_b12_mcg": null, "thiamin_mg": 0.31, "riboflavin_mg": 0.07, "niacin_mg": 2.88, "folate_mcg": 150.49, "water_g": 114.39, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Reheat with a splash of water to steam the rice.", "duration": "P3D"}, "freezer": {"notes": "Texture of fennel may become softer upon thawing.", "duration": "P1M"}, "reheating": "Microwave with a damp paper towel covering, or stovetop with a splash of water.", "does_not_keep": false}', '[{"name": "Large saut\u00e9 pan or Dutch oven with lid", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Fine-mesh sieve", "required": true, "alternative": "Bowl for rinsing rice"}]', '[{"symptom": "Rice is crunchy or undercooked", "likely_cause": "Lid was loose allowing steam to escape, or heat was too low to generate steam", "prevention": "Use a heavy lid; ensure liquid simmers before covering", "fix": "Add 30-50ml hot water, cover tightly, and cook on very low for 5 more minutes"}, {"symptom": "Rice is mushy", "likely_cause": "Too much liquid or rice was stirred during the simmer phase", "prevention": "Measure liquids precisely and do not disturb rice while simmering", "fix": "Remove lid and let stand for 10 minutes to allow excess moisture to evaporate"}]', '["Don''t throw away the fennel fronds (the green wispy tops). Chop them up and use them like an herb at the end for an extra punch of fresh anise flavor.", "If using a store-bought vegetable broth that is very salty, reduce the added salt in the recipe to 2g or season strictly to taste at the end.", "Slicing the fennel thinly (approx 0.5cm) is key. If the slices are too thick, the rice will overcook before the fennel is tender.", "For a protein boost, this dish serves as an excellent bed for chickpeas or grilled white fish."]', '"This dish is inspired by the Greek classic ''Marathorizo'' (Fennel Rice). Fennel grows wild throughout Greece, and this simple preparation highlights the philosophy of using fresh, local produce to create flavor-packed vegetarian dishes during fasting periods or simple family meals."', 313.78);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('e4585fb7-5065-4c67-883d-f5634d15a2eb', 'Lemon Balsamic Broiled Cornish Hens', 'Succulent, spatchcocked Cornish game hens featuring a crispy, mahogany skin glazed with tangy balsamic vinegar and bright lemon zest. This high-heat method ensures juicy meat and a rapid cooking time perfect for weeknights.', 'dinner', 'American', 'Intermediate', '["balsamic vinegar", "cornish hen", "extra virgin olive oil", "five ingredient", "lemon", "parsley", "poultry", "dinner", "weeknight", "main course"]', '[{"group_name": "Poultry", "items": [{"name": "cornish game hens", "quantity": 2, "unit": null, "preparation": "thawed", "notes": "approx. 650g each", "substitutions": [], "ingredient_id": "807a842a-31e2-41bb-82eb-6109cd41a05a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Glaze & Seasoning", "items": [{"name": "balsamic vinegar", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "4da62caf-a01b-4477-b6bb-f4213102565d", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": "zested and juiced", "notes": "approx. 45ml juice", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Position an oven rack in the upper third of the oven (about 15-20cm from the heat source) and preheat the broiler to high (or set oven to 260\u00b0C/500\u00b0F if broiler is unavailable).", "structured": {"action": "PREHEAT", "temperature": {"celsius": 260, "fahrenheit": 500}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Prepare the hens by spatchcocking them: place breast-side down, use kitchen shears to cut along both sides of the backbone to remove it. Flip the hen breast-side up and press down firmly on the breastbone until it cracks and the bird lies flat. Pat dry thoroughly with paper towels.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Breastbone cracks and bird lies flat"}}, "tips": ["Removing the backbone ensures the birds cook evenly and quickly under high heat.", "Save the backbones for chicken stock."]}, {"step_number": 3, "phase": "prep", "text": "In a small bowl, whisk together the balsamic vinegar, olive oil, lemon juice, lemon zest, salt, and pepper until emulsified.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Place the flattened hens on a rimmed baking sheet. Brush half of the balsamic mixture all over the hens, ensuring the skin is well coated.", "structured": {"action": "GLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Broil the hens for 25-35 minutes. Rotate the pan halfway through for even browning. Keep a close eye on the skin; if it darkens too quickly before the meat is done, lower the oven rack or reduce temperature to 200\u00b0C/400\u00b0F. Cook until internal temperature reaches 74\u00b0C (165\u00b0F) in the thickest part of the thigh.", "structured": {"action": "BROIL", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": "PT30M", "doneness_cues": {"visual": "Skin is dark mahogany and crisp", "tactile": "Juices run clear"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove from oven and brush with the remaining glaze immediately. Let the hens rest for 10 minutes before serving. Garnish with fresh chopped parsley.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT0M", "total_time": "PT55M", "overnight_required": false, "yields": "2 hens", "yield_count": 2, "serving_size_g": 350}', '{"flags": ["Dairy-Free", "Gluten-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Paleo", "Low-Carb"], "not_suitable_for": []}', '{"per_serving": {"calories": 981.01, "protein_g": 117.45, "carbohydrates_g": 22.23, "fat_g": 44.33, "saturated_fat_g": 10.96, "trans_fat_g": null, "monounsaturated_fat_g": 18.26, "polyunsaturated_fat_g": 8.74, "fiber_g": 2.18, "sugar_g": 4.95, "sodium_mg": 2451.57, "cholesterol_mg": 1703, "potassium_mg": 1645.4, "calcium_mg": 102.81, "iron_mg": 39.27, "magnesium_mg": 130.01, "phosphorus_mg": 1300.31, "zinc_mg": 21.73, "vitamin_a_mcg": 17322.4, "vitamin_c_mg": 147.07, "vitamin_d_mcg": null, "vitamin_e_mg": 2.32, "vitamin_k_mcg": 133.67, "vitamin_b6_mg": 2.79, "vitamin_b12_mcg": 74.1, "thiamin_mg": 0.62, "riboflavin_mg": 6.46, "niacin_mg": 43.46, "folate_mcg": 2260.67, "water_g": 564.16, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Skin will lose crispness.", "duration": "P3D"}, "freezer": {"notes": "Best if meat is removed from bone before freezing.", "duration": "P3M"}, "reheating": "Reheat in a 190\u00b0C (375\u00b0F) oven for 10-15 minutes to recrisp skin.", "does_not_keep": false}', '[{"name": "Kitchen shears", "required": true, "alternative": "Sharp chef''s knife"}, {"name": "Rimmed baking sheet", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Meat thermometer", "required": true, "alternative": null}, {"name": "Pastry brush", "required": true, "alternative": "Spoon"}]', '[{"symptom": "Skin is burning before meat is cooked", "likely_cause": "Oven rack is too high or sugar in balsamic is caramelizing too fast", "prevention": "Position rack slightly lower initially; monitor closely", "fix": "Tent the dark spots loosely with aluminum foil and move the pan to a lower rack to finish cooking"}, {"symptom": "Soggy skin", "likely_cause": "Hens were not patted dry enough or overcrowded pan", "prevention": "Ensure hens are very dry before oiling; use a large enough sheet pan", "fix": "Place under broiler alone for 1-2 minutes at the very end (watch carefully)"}]', '["Spatchcocking (butterflying) is essential here: it increases surface area for browning and reduces cooking time by nearly 40%.", "Balsamic vinegar contains natural sugars that will char. This ''char'' is desirable for flavor, but watch it closely to prevent it from turning into bitter ash.", "Allowing the meat to rest is non-negotiable; cutting into it immediately will cause all the juices to drain out, leaving dry meat."]', '"Cornish game hens are actually a specific breed of broiler chicken, harvested young for their tenderness. While the preparation here borrows Mediterranean flavors (lemon, olive oil, balsamic), the concept of the individual roasted bird is a staple of American banquet and Sunday dinner dining."', 981.01);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('e4b2a2eb-a566-4bed-9dbd-588a282c2363', 'Quick Broccoli and Spinach Saag with Spiced Butter', 'A vibrant, emerald-green curry that hacks the traditional slow-cooked method by using broccoli to provide the creamy body typically associated with mustard greens. Enriched with generous knobs of butter and tempered with warming aromatic spices.', 'main course', 'Indian', 'Easy', '["vegetarian", "curry", "quick", "spinach", "butter", "saag", "indian", "gluten-free"]', '[{"group_name": "Greens Base", "items": [{"name": "fresh spinach", "quantity": 300, "unit": "g", "preparation": "washed", "notes": "baby spinach or roughly chopped mature spinach", "substitutions": [], "ingredient_id": "4734440a-226d-4d26-a110-3ed5c3bde93f", "nutrition_source": "USDA FoodData Central"}, {"name": "broccoli", "quantity": 350, "unit": "g", "preparation": "cut into florets", "notes": "approx 1 medium head", "substitutions": [], "ingredient_id": "b0a26615-a0a7-4b5c-9143-e9becf53b41a", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 100, "unit": "ml", "preparation": null, "notes": "for blending", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Aromatics & Spices", "items": [{"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": "cubed", "notes": "divided into 40g for cooking, 20g for finishing", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "cumin seeds", "quantity": 4, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "onion", "quantity": 150, "unit": "g", "preparation": "finely diced", "notes": "1 medium onion", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "ginger", "quantity": 15, "unit": "g", "preparation": "grated or paste", "notes": "approx 1 tbsp", "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 15, "unit": "g", "preparation": "minced or paste", "notes": "approx 3-4 cloves", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "green chili", "quantity": 1, "unit": null, "preparation": "finely chopped", "notes": "adjust to heat preference, approx 5g", "substitutions": [], "ingredient_id": "6cdb0615-378e-4bfa-b76d-f19bbd780e6c", "nutrition_source": "USDA FoodData Central"}, {"name": "ground coriander", "quantity": 4, "unit": "g", "preparation": null, "notes": "approx 2 tsp", "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "turmeric powder", "quantity": 1, "unit": "g", "preparation": null, "notes": "approx 1/4 tsp", "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 6, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "garam masala", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "8ffcea01-5f22-462b-94de-ad2a97049325", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Bring a large pot of salted water to a rolling boil. Prepare a bowl of ice water nearby.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add broccoli florets to the boiling water. Cook for 3 minutes until bright green and slightly tender. Add the spinach and cook for just 30 seconds until wilted.", "structured": {"action": "BLANCH", "temperature": null, "duration": "PT3M30S", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Drain the vegetables immediately and plunge them into the ice water to stop the cooking process and lock in the vibrant green color. Drain well after cooling.", "structured": {"action": "SHOCK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Transfer the drained vegetables to a blender. Add 100ml water (or just enough to facilitate blending) and pulse into a coarse puree. Do not over-blend into a smoothie texture; some texture is desirable.", "structured": {"action": "BLEND", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["If the mixture is too thick, add water 1 tablespoon at a time."]}, {"step_number": 5, "phase": "cook", "text": "Heat 40g of butter in a skillet over medium heat. Add cumin seeds and let them crackle for 30 seconds.", "structured": {"action": "TEMPER", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Add diced onions. Saut\u00e9 for 5-7 minutes until they turn translucent and start to brown at the edges. Add ginger, garlic, and green chili, cooking for another minute until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Onions are golden brown", "tactile": "Soft texture"}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Stir in the coriander powder and turmeric. Cook for 30 seconds to toast the spices, ensuring they do not burn.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Pour the green broccoli-spinach puree into the skillet. Stir to combine with the aromatics. Simmer on low heat for 5 minutes to meld the flavors. Season with salt.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Turn off the heat. Stir in the garam masala, the remaining 20g of butter, and heavy cream (if using). Serve immediately.", "structured": {"action": "FINISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT5M", "total_time": "PT30M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 300}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Egg-Free", "Low-Carb"], "not_suitable_for": ["Vegans (contains dairy butter)"]}', '{"per_serving": {"calories": 213.31, "protein_g": 6.08, "carbohydrates_g": 15.67, "fat_g": 16.06, "saturated_fat_g": 9.5, "trans_fat_g": 0.09, "monounsaturated_fat_g": 4.51, "polyunsaturated_fat_g": 0.87, "fiber_g": 5.47, "sugar_g": 3.82, "sodium_mg": 680.13, "cholesterol_mg": 40.73, "potassium_mg": 843.05, "calcium_mg": 158.09, "iron_mg": 3.84, "magnesium_mg": 92.81, "phosphorus_mg": 130.74, "zinc_mg": 1.06, "vitamin_a_mcg": 513.68, "vitamin_c_mg": 106.63, "vitamin_d_mcg": 0.12, "vitamin_e_mg": 2.69, "vitamin_k_mcg": 453.28, "vitamin_b6_mg": 0.41, "vitamin_b12_mcg": 0.04, "thiamin_mg": 0.17, "riboflavin_mg": 0.29, "niacin_mg": 1.29, "folate_mcg": 209.46, "water_g": 218.32, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Color may darken upon reheating due to oxidation.", "duration": "P3D"}, "freezer": {"notes": "Texture may become slightly watery; reheat gently to emulsify.", "duration": "P1M"}, "reheating": "Simmer gently on stovetop; add a splash of water if too thick.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Blender or Food Processor", "required": true, "alternative": "Immersion blender"}, {"name": "Heavy-bottomed skillet or kadhai", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}]', '[{"symptom": "Curry tastes bitter", "likely_cause": "Spinach was overcooked or broccoli stems were too mature", "prevention": "Blanch quickly and shock in ice water immediately", "fix": "Add a teaspoon of sugar, honey, or extra cream to mask the bitterness"}, {"symptom": "Texture is too watery", "likely_cause": "Vegetables were not drained well after shocking", "prevention": "Squeeze excess water from spinach before blending", "fix": "Simmer for an additional 5-10 minutes to evaporate excess moisture"}]', '["Using broccoli is a modern restaurant trick to give saag the thick, creamy body of slow-cooked mustard greens (sarson) without the bitterness or 2-hour cooking time.", "For an authentic finish, serve with makki ki roti (cornmeal flatbread) or a crisp naan.", "Do not cover the pot once the green puree is added; covering traps acids which will turn the vibrant green color into a dull olive drab.", "If you want to add protein, pan-fried paneer cubes or tofu can be folded in at the very end."]', '"Saag is a staple of Punjabi cuisine in North India, traditionally made from mustard greens and cooked slowly in earthen pots. This version adapts the dish for modern, fast-paced kitchens using broccoli to replicate the traditional texture while maintaining the signature spiced butter flavor profile known as ''tadka''."', 213.31);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('e55da28c-c703-492e-b013-39862dd4a34c', 'Swordfish au Poivre with Cognac Cream', 'Thick, meaty swordfish steaks encrusted with coarse crushed peppercorns, seared to a golden finish and bathed in a luxurious, amber-hued sauce of reduced Cognac, caramelized shallots, and heavy cream.', 'dinner', 'French', 'Intermediate', '["french", "seafood", "cognac", "shallot", "swordfish", "dinner", "date night", "high protein"]', '[{"group_name": "Swordfish", "items": [{"name": "swordfish steaks", "quantity": 360, "unit": "g", "preparation": "fresh, 2.5cm thick", "notes": "2 steaks, approx 180g each", "substitutions": [], "ingredient_id": "e58fca66-1dff-4abc-a507-c14a2b99a65e", "nutrition_source": "USDA FoodData Central"}, {"name": "black peppercorns", "quantity": 10, "unit": "g", "preparation": "whole", "notes": "coarsely crushed just before use", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "grapeseed or canola for high heat", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Cognac Cream Sauce", "items": [{"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "approx 30g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "cognac", "quantity": 60, "unit": "ml", "preparation": null, "notes": "VS or VSOP quality", "substitutions": [], "ingredient_id": "db4bfda4-18fd-4428-a410-465e89398474", "nutrition_source": "Aggregated Public Data"}, {"name": "heavy cream", "quantity": 120, "unit": "ml", "preparation": "min 35% fat", "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "chives", "quantity": 5, "unit": "g", "preparation": "minced", "notes": "for garnish", "substitutions": [], "ingredient_id": "f5d96837-c5d2-407c-8e45-b000ba07e27e", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the swordfish steaks very dry with paper towels. Season both sides liberally with salt. Press the coarsely crushed peppercorns firmly into both sides of the fish to create a crust.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat the neutral oil in a heavy skillet over medium-high heat. Once the oil shimmers and is just beginning to smoke, carefully place the steaks in the pan. Sear undisturbed until a deep golden crust forms, about 3-4 minutes.", "structured": {"action": "SEAR", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Flip the steaks and add half the butter (15g) to the pan, basting the fish slightly. Cook for another 2-3 minutes until the internal temperature reaches 58\u00b0C (136\u00b0F) for medium or 63\u00b0C (145\u00b0F) for well-done. Remove fish to a warm plate and rest.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 63, "fahrenheit": 145}, "duration": null, "doneness_cues": {"visual": "Opaque throughout but moist", "tactile": "Firm with slight give"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Reduce heat to medium. Add the remaining butter and the minced shallots to the pan juices. Saut\u00e9 for 2 minutes until the shallots are softened and translucent, scraping up any fond (browned bits) from the bottom.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Remove the pan from the heat source temporarily. Add the Cognac. Return to heat and carefully tilt the pan or use a long lighter to ignite the alcohol fumes (Flamb\u00e9). Let the flame die down naturally, then simmer until liquid is reduced by half.", "structured": {"action": "FLAMB\u00c9", "temperature": null, "duration": null, "doneness_cues": {"visual": "Flames subside, liquid syrupy", "tactile": null}}, "tips": ["Ensure your exhaust fan is OFF before flamb\u00e9ing to prevent fire spread.", "Keep a lid nearby to smother flames if they get too high."]}, {"step_number": 6, "phase": "cook", "text": "Stir in the heavy cream. Simmer gently for 2-3 minutes until the sauce coats the back of a spoon (nappe consistency). Stir in the lemon juice and taste for salt.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Pour the sauce over the rested swordfish steaks. Garnish with minced chives and serve immediately.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT5M", "total_time": "PT30M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 260}', '{"flags": ["Pescatarian", "Gluten-Free", "Low-Carb", "Keto", "Egg-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 728.3, "protein_g": 38.28, "carbohydrates_g": 8.02, "fat_g": 53.5, "saturated_fat_g": 25.44, "trans_fat_g": 0.84, "monounsaturated_fat_g": 14.41, "polyunsaturated_fat_g": 3.52, "fiber_g": 1.82, "sugar_g": 3.38, "sodium_mg": 1136.55, "cholesterol_mg": 218.85, "potassium_mg": 939.78, "calcium_mg": 83.03, "iron_mg": 1.48, "magnesium_mg": 69.63, "phosphorus_mg": 515.95, "zinc_mg": 1.49, "vitamin_a_mcg": 420.8, "vitamin_c_mg": 3.99, "vitamin_d_mcg": 25.98, "vitamin_e_mg": 4.6, "vitamin_k_mcg": 16.8, "vitamin_b6_mg": 1.07, "vitamin_b12_mcg": 3.18, "thiamin_mg": 0.15, "riboflavin_mg": 0.23, "niacin_mg": 14.11, "folate_mcg": 15.53, "water_g": 186.35, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Fish texture may become firm upon reheating. Gently warm in a pan with a splash of water.", "duration": "P2D"}, "freezer": {"notes": "Cream-based sauces generally do not freeze well; texture may split.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Heavy-bottomed skillet", "required": true, "alternative": "Stainless steel frying pan"}, {"name": "Mortar and pestle", "required": false, "alternative": "Heavy pot bottom and cutting board"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Kitchen lighter or long match", "required": true, "alternative": "Stove ignition"}]', '[{"symptom": "Swordfish is dry and tough", "likely_cause": "Overcooking; swordfish has very little intramuscular fat", "prevention": "Use a meat thermometer and pull the fish at 55-58\u00b0C (130-136\u00b0F) as carryover cooking will finish it", "fix": "Cut into smaller bites and toss heavily in the cream sauce to add moisture"}, {"symptom": "Sauce is too thin", "likely_cause": "Cream wasn''t reduced enough or heat was too low", "prevention": "Simmer briskly after adding cream until large bubbles form", "fix": "Simmer for another 1-2 minutes; do not boil aggressively or it may split"}]', '["Use a mix of black, white, and pink peppercorns for a more complex aroma, but stick to black for the classic punch.", "Swordfish is the ''steak'' of the sea; treat it like a beef filet. Do not constantly move it while searing, or you will lose the crust.", "If you do not consume alcohol, you can substitute the Cognac with a splash of beef stock and a teaspoon of Worcestershire sauce, though the flavor profile will shift from ''Au Poivre'' to savory gravy.", "The squeeze of lemon at the end is crucial; the acidity cuts through the fat of the cream and the density of the fish."]', '"This dish is a maritime adaptation of the French bistro classic ''Steak au Poivre,'' traditionally made with beef filet mignon. By swapping beef for swordfish\u2014a fish known for its firm, meaty texture\u2014the dish retains the bold, peppery aggression of the original while offering a lighter, seafood-forward elegance typical of coastal French cuisine."', 728.3);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('e58595d0-5732-4a07-b6b0-215d987fb68c', 'Fresh Pineapple Glazed Holiday Ham', 'A modern revitalization of the mid-century classic. This recipe replaces canned rings with caramelized wedges of fresh pineapple and uses a glaze spiked with fresh ginger and cider vinegar to cut through the richness of the smoked meat.', 'main course', 'American', 'Intermediate', '["meat", "dark brown sugar", "ham", "pineapple", "pineapple juice", "dinner", "main course", "easter", "holiday", "gluten-free"]', '[{"group_name": "Ham", "items": [{"name": "bone-in spiral-cut smoked ham", "quantity": 4000, "unit": "g", "preparation": "room temperature", "notes": "approx 3.5-4.5kg", "substitutions": [], "ingredient_id": "2d3c75f4-d704-4999-8f00-a0405f7b7007", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 240, "unit": "ml", "preparation": null, "notes": "for the roasting pan", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Fresh Pineapple Component", "items": [{"name": "fresh pineapple", "quantity": 1, "unit": null, "preparation": "peeled, cored, and sliced into wedges", "notes": "approx 1kg whole fruit", "substitutions": [], "ingredient_id": "37da68de-6b6e-4619-9f28-52da1f26f4ce", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sweet-Tart Glaze", "items": [{"name": "pineapple juice", "quantity": 240, "unit": "ml", "preparation": null, "notes": "100% juice", "substitutions": [], "ingredient_id": "fde6ddf5-0e6e-4b41-9e27-d362f13a0d03", "nutrition_source": "USDA FoodData Central"}, {"name": "dark brown sugar", "quantity": 150, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "apple cider vinegar", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh ginger", "quantity": 15, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "whole cloves", "quantity": 10, "unit": null, "preparation": null, "notes": "plus more for studding ham if desired", "substitutions": [], "ingredient_id": "7b3bf68a-3ae9-4dad-91f4-6c7a14ec5e0e", "nutrition_source": "USDA FoodData Central"}, {"name": "cinnamon stick", "quantity": 1, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Remove the ham from the refrigerator 1 hour before cooking to let it come to room temperature. Preheat your oven to 165\u00b0C/325\u00b0F.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 165, "fahrenheit": 329}, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a medium saucepan, combine pineapple juice, dark brown sugar, cider vinegar, Dijon mustard, grated ginger, whole cloves, and the cinnamon stick. Bring to a boil, then reduce heat and simmer until reduced by half and syrupy, about 15-20 minutes. Strain out the solids and set aside.", "structured": {"action": "REDUCE", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT20M", "doneness_cues": {"visual": "Reduced by half, coats the back of a spoon", "tactile": "Syrupy consistency"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Place the ham cut-side down in the roasting pan. Pour the water into the bottom of the pan (this creates steam to prevent drying). Cover the ham tightly with aluminum foil to seal in moisture.", "structured": {"action": "PREPARE_MEAT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Bake the ham covered for approximately 12-15 minutes per 500g (1 lb), or until the internal temperature reaches roughly 45\u00b0C/110\u00b0F. For a 4kg ham, this is about 1 hour 45 minutes.", "structured": {"action": "BAKE", "temperature": {"celsius": 165, "fahrenheit": 329}, "duration": "PT1H45M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Remove the ham from the oven and increase oven temperature to 220\u00b0C/425\u00b0F. Discard the foil. Brush the ham generously with the glaze. Arrange the fresh pineapple wedges around the base of the ham and tuck a few pieces between the spiral slices if space permits.", "structured": {"action": "GLAZE", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Return the pan to the oven uncovered. Roast for 15-20 minutes, basting with pan juices and more glaze halfway through, until the glaze is caramelized, the pineapple is tender, and the internal temperature of the ham reaches 60\u00b0C/140\u00b0F.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT20M", "doneness_cues": {"visual": "Dark golden brown glaze, slightly charred pineapple edges", "tactile": "Internal temp 60\u00b0C"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from oven and let the ham rest for at least 15-20 minutes before carving. This allows the juices to redistribute. Serve with the roasted pineapple wedges.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT40M", "passive_time": "PT2H30M", "total_time": "PT3H10M", "overnight_required": false, "yields": "12 servings", "yield_count": 12, "serving_size_g": 250}', '{"flags": ["Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Paleo"], "not_suitable_for": []}', '{"per_serving": {"calories": 575.25, "protein_g": 62.35, "carbohydrates_g": 62.39, "fat_g": 9.27, "saturated_fat_g": 5.99, "trans_fat_g": 0.07, "monounsaturated_fat_g": 2.05, "polyunsaturated_fat_g": 0.68, "fiber_g": 1.67, "sugar_g": 58.11, "sodium_mg": 3567.76, "cholesterol_mg": 166.67, "potassium_mg": 1249.64, "calcium_mg": 50.8, "iron_mg": 3.08, "magnesium_mg": 81.85, "phosphorus_mg": 963.43, "zinc_mg": 6.08, "vitamin_a_mcg": 42.6, "vitamin_c_mg": 48.68, "vitamin_d_mcg": 2.33, "vitamin_e_mg": 0.85, "vitamin_k_mcg": 1, "vitamin_b6_mg": 1.49, "vitamin_b12_mcg": 1.23, "thiamin_mg": 1.95, "riboflavin_mg": 0.66, "niacin_mg": 20.99, "folate_mcg": 25.6, "water_g": 330.2, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store slices in an airtight container with leftover glaze poured over to keep moist.", "duration": "P5D"}, "freezer": {"notes": "Freeze thick slices or the ham bone separately for soup stocks.", "duration": "P2M"}, "reheating": "Reheat gently in a covered pan with a splash of water or broth at 150\u00b0C/300\u00b0F until warm.", "does_not_keep": false}', '[{"name": "Large roasting pan with rack", "required": true, "alternative": null}, {"name": "Medium saucepan", "required": true, "alternative": null}, {"name": "Pastry brush", "required": true, "alternative": "Spoon"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Meat thermometer", "required": true, "alternative": null}, {"name": "Aluminum foil", "required": true, "alternative": null}]', '[{"symptom": "Ham is dry", "likely_cause": "Overcooked or not covered tightly enough during the initial bake", "prevention": "Use a meat thermometer and ensure the foil seal is airtight during the first phase", "fix": "Slice the meat and soak it in warm ham stock or diluted glaze for 10 minutes before serving"}, {"symptom": "Glaze is burning before ham is hot", "likely_cause": "Oven temperature too high or sugar content too high in glaze", "prevention": "Apply glaze only in the final 20 minutes of cooking", "fix": "Cover the dark spots loosely with a small piece of foil to deflect heat"}]', '["Select a ''city ham'' (wet-cured and smoked), not a country ham (dry-cured and very salty) or a fresh ham (raw pork leg).", "Fresh pineapple contains the enzyme bromelain, which tenderizes meat. While perfect for this roasting method, do not prep this dish the night before and let the raw fruit sit on the meat, or the texture may become mushy.", "If using a spiral-cut ham, avoid glazing between the slices until the very end, or the sugars may act as a glue, making it difficult to pull the slices apart later.", "Save the ham bone! It is culinary gold for making split pea soup or flavoring a pot of collard greens later in the week."]', '"The tradition of serving ham for Easter and spring holidays typically stems from historical curing cycles, where hams cured over the winter were ready to eat in early spring. The addition of pineapple became a mid-20th-century American icon, symbolizing hospitality and modern convenience, though this recipe returns to the root by utilizing fresh fruit."', 575.25);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('e5c86fc6-16b3-42f5-a283-d9e9883aad30', 'Banana Maple Oat Flapjacks', 'A chewy, golden British-style oat bar that naturally incorporates the sweetness of mashed banana. These flapjacks replace traditional golden syrup with maple syrup and brown sugar to maintain a low FODMAP profile while delivering a comforting toffee flavor and soft texture.', 'snack', 'British', 'Easy', '["low fodmap", "banana", "oats", "flapjack", "dessert", "snack", "british", "kid-friendly"]', '[{"group_name": "Wet Ingredients", "items": [{"name": "unsalted butter", "quantity": 100, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": ["coconut oil (for dairy-free)", "dairy-free block margarine"], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "maple syrup", "quantity": 80, "unit": "ml", "preparation": null, "notes": "Pure maple syrup is low FODMAP", "substitutions": [], "ingredient_id": "c9ca1f35-b107-46c2-92a3-4c1c620f3c11", "nutrition_source": "USDA FoodData Central"}, {"name": "soft light brown sugar", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "ripe banana", "quantity": 150, "unit": "g", "preparation": "peeled weight", "notes": "approx 1.5 medium bananas; ensure no brown spots for strictest FODMAP, though recipe amount is safe per serving either way", "substitutions": [], "ingredient_id": "d01cd7bd-9b20-4ccf-8475-27ca2843edf6", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dry Ingredients", "items": [{"name": "rolled oats", "quantity": 250, "unit": "g", "preparation": "jumbo or porridge oats", "notes": "Certified gluten-free oats if required", "substitutions": [], "ingredient_id": "11381622-c748-499c-b9c5-58fcb9d70fd3", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1/2 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 180\u00b0C/350\u00b0F (160\u00b0C/320\u00b0F fan). Line a 20cm (8-inch) square baking tin with parchment paper, leaving an overhang for easy removal.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Mash the weighed banana thoroughly in a bowl until smooth with minimal lumps.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": {"visual": "Smooth consistency similar to puree", "tactile": "No large chunks remaining"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a saucepan over low heat, melt the butter, brown sugar, and maple syrup together. Stir gently until the sugar has dissolved and the mixture bubbles slightly.", "structured": {"action": "MELT", "temperature": {"celsius": 60, "fahrenheit": 140}, "duration": null, "doneness_cues": {"visual": "Uniform glossy liquid", "tactile": "No sugar granules felt on spoon"}}, "tips": []}, {"step_number": 4, "phase": "mix", "text": "Remove the pan from heat. Stir in the mashed banana, then fold in the oats, salt, and cinnamon until every oat is thoroughly coated in the wet mixture.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": {"visual": "No dry white oats visible", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "shape", "text": "Transfer the mixture to the lined tin. Using the back of a spoon or a measuring cup, press the mixture down very firmly into the corners and edges to compact it.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Bake in the center of the oven for 20-25 minutes until the edges are golden brown and the top is set but slightly soft.", "structured": {"action": "BAKE", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT25M", "doneness_cues": {"visual": "Golden brown edges", "tactile": "Firm edges, slight give in center"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from the oven. While still hot, lightly score the surface into 16 squares with a sharp knife. Allow to cool completely in the tin before cutting through and removing.", "structured": {"action": "COOL", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT25M", "total_time": "PT40M", "overnight_required": false, "yields": "16 squares", "yield_count": 16, "serving_size_g": 45}', '{"flags": ["Vegetarian", "Low-Sodium", "Egg-Free", "Nut-Free", "Soy-Free", "Wheat-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 140.59, "protein_g": 2.22, "carbohydrates_g": 20.11, "fat_g": 6.2, "saturated_fat_g": 3.32, "trans_fat_g": 0.16, "monounsaturated_fat_g": 1.47, "polyunsaturated_fat_g": 0.2, "fiber_g": 1.92, "sugar_g": 7.94, "sodium_mg": 51.74, "cholesterol_mg": 13.44, "potassium_mg": 108.68, "calcium_mg": 21.81, "iron_mg": 0.78, "magnesium_mg": 25.72, "phosphorus_mg": 67.9, "zinc_mg": 0.63, "vitamin_a_mcg": 43.06, "vitamin_c_mg": 0.82, "vitamin_d_mcg": null, "vitamin_e_mg": 0.16, "vitamin_k_mcg": 0.54, "vitamin_b6_mg": 0.04, "vitamin_b12_mcg": 0.01, "thiamin_mg": 0.01, "riboflavin_mg": 0.07, "niacin_mg": 0.08, "folate_mcg": 2.11, "water_g": 9.71, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Chilling produces a chewier texture.", "duration": "P1W"}, "freezer": {"notes": "Freeze separated by parchment paper.", "duration": "P3M"}, "reheating": "Eat room temp or warm slightly in microwave for 10 seconds to soften.", "does_not_keep": false}', '[{"name": "Square baking tin (20cm / 8 inch)", "required": true, "alternative": null}, {"name": "Saucepan", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Potato masher or fork", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}]', '[{"symptom": "Flapjacks crumble apart when picked up", "likely_cause": "Mixture wasn''t compressed firmly enough or was cut while too warm", "prevention": "Press mixture down with significant force before baking and cool completely", "fix": "Chill in the fridge for 2 hours to solidify the butter"}]', '["FODMAP Safety: Ripe bananas are high in fructans, but the portion size here (approx 9g banana per square) is well within the Monash University green light zone (up to ~35g ripe banana is usually tolerated).", "Texture Control: For a chewier flapjack, bake for 20 minutes. For a crunchier bar, bake for 25-28 minutes.", "The ''Press'': The most common mistake with flapjacks is not pressing the oats down hard enough in the tin. You want to remove air pockets so the natural sugars bind the oats into a solid bar."]', '"Flapjacks are a quintessential British traybake dating back to the early 17th century (though the oat version became standard later). Unlike the American pancake of the same name, British flapjacks are dense, oven-baked bars formed from rolled oats, butter, and syrup."', 140.59);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('e5d087bb-3aa4-4a4a-bdfd-bd10738a213b', 'Lemon Miso Glazed Salmon', 'Buttery salmon fillets marinated in a sweet and savory umami-rich paste, roasted until tender with a caramelized, slightly charred crust. The addition of fresh lemon zest cuts through the richness of the fish and miso.', 'dinner', 'Japanese', 'Easy', '["japanese", "seafood", "lemon juice", "lemon zest", "make-ahead", "mirin", "miso", "plan-ahead", "salmon fillet", "dinner", "easy", "weeknight"]', '[{"group_name": "Salmon", "items": [{"name": "salmon fillets", "quantity": 600, "unit": "g", "preparation": "skin-on or skin-off", "notes": "4 fillets, approx 150g each", "substitutions": [], "ingredient_id": "6648fae7-4f63-45b3-b45d-19d927b57c2d", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable oil", "quantity": 5, "unit": "ml", "preparation": null, "notes": "for greasing pan", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Miso Marinade", "items": [{"name": "shiro miso", "quantity": 60, "unit": "g", "preparation": "white miso paste", "notes": null, "substitutions": [], "ingredient_id": "34c2a692-eab9-413c-a3f8-456e450fb7ec", "nutrition_source": "Aggregated Public Data"}, {"name": "mirin", "quantity": 30, "unit": "ml", "preparation": null, "notes": "sweet rice wine", "substitutions": [], "ingredient_id": "2a72c18d-8a1d-4259-8790-25d62f6fb5ba", "nutrition_source": "Aggregated Public Data"}, {"name": "sake", "quantity": 15, "unit": "ml", "preparation": null, "notes": "dry japanese rice wine", "substitutions": [], "ingredient_id": "1cfffbd2-7ea5-4cbc-bc35-c57e12233152", "nutrition_source": "USDA FoodData Central"}, {"name": "sugar", "quantity": 15, "unit": "g", "preparation": "granulated", "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": null, "unit": null, "preparation": null, "notes": "zest of 1 lemon, approx 3g", "substitutions": [], "ingredient_id": "a5fb6a2a-dcda-4ab2-8fe6-472d7fcc39d1", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Finishing", "items": [{"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "scallions", "quantity": 1, "unit": null, "preparation": "thinly sliced", "notes": "green parts only", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "toasted sesame seeds", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "05a632f9-d310-4dc1-aa03-2f2ac26f30c8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a small mixing bowl, whisk together the shiro miso, mirin, sake, sugar, and lemon zest until the sugar has largely dissolved and the paste is smooth.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Pat the salmon fillets dry with paper towels. Coat the fillets generously with the miso marinade on all sides. Place in a dish, cover, and refrigerate for at least 30 minutes (up to 24 hours for deeper flavor).", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Preheat your oven to 200\u00b0C (400\u00b0F). Line a baking sheet with parchment paper and lightly grease it with vegetable oil to prevent sticking.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Remove salmon from the fridge. Use your fingers to gently wipe off the excess marinade, leaving only a thin, translucent layer. Arrange fillets skin-side down on the prepared baking sheet.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Roast in the center of the oven for 10-12 minutes. The salmon is done when it flakes easily with a fork and reaches an internal temperature of 63\u00b0C (145\u00b0F).", "structured": {"action": "ROAST", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT12M", "doneness_cues": {"visual": "Opaque and flakes easily", "tactile": "Firm but yielding"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Optional: If more char is desired, switch the oven to Broil (Grill) for the final 60-90 seconds, watching constantly to prevent burning.", "structured": {"action": "BROIL", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from oven and drizzle with fresh lemon juice. Garnish with sliced scallions and toasted sesame seeds before serving.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT30M", "total_time": "PT45M", "overnight_required": false, "yields": "4 fillets", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Pescatarian", "Dairy-Free", "Egg-Free", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 473.99, "protein_g": 38.49, "carbohydrates_g": 16.51, "fat_g": 40.38, "saturated_fat_g": 0.22, "trans_fat_g": null, "monounsaturated_fat_g": 0.09, "polyunsaturated_fat_g": 0.11, "fiber_g": 0.88, "sugar_g": 8.03, "sodium_mg": 3994.9, "cholesterol_mg": null, "potassium_mg": 81.46, "calcium_mg": 426.85, "iron_mg": 18.43, "magnesium_mg": 453.04, "phosphorus_mg": 455.87, "zinc_mg": 1.42, "vitamin_a_mcg": 408.41, "vitamin_c_mg": 3.13, "vitamin_d_mcg": null, "vitamin_e_mg": 0.03, "vitamin_k_mcg": 7.76, "vitamin_b6_mg": 0.01, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.01, "niacin_mg": 0.05, "folate_mcg": 3.73, "water_g": 10.41, "alcohol_g": 0.61, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best consumed immediately. Texture degrades upon reheating.", "duration": "P2D"}, "freezer": {"notes": "Not recommended as the texture of roasted fish becomes mushy.", "duration": null}, "reheating": "Gently reheat in a low oven (150\u00b0C/300\u00b0F) covered with foil just until warm.", "does_not_keep": false}', '[{"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": "Aluminum foil (greased)"}, {"name": "Microplane or Zester", "required": true, "alternative": null}]', '[{"symptom": "Marinade is burnt/blackened", "likely_cause": "Excess marinade was left on the fish or oven rack was too high", "prevention": "Wipe off almost all marinade before roasting; sugar in miso burns quickly", "fix": "Scrape off the burnt layer; the fish underneath is likely still good"}, {"symptom": "Salmon is dry", "likely_cause": "Overcooked", "prevention": "Check for doneness early; salmon continues to cook slightly after removal", "fix": "Flake the fish and mix with a bit of mayonnaise or butter to restore moisture"}]', '["Wiping the marinade off seems counter-intuitive, but the salt and sugar penetrate the flesh during the marination time. Leaving a thick gloop on top will result in a burnt crust.", "For the ''Plan-Ahead'' approach, you can marinate the fish in the morning or the night before. The longer it sits, the firmer the texture will become (almost like a light cure).", "Shiro miso (white) is preferred here for its higher sugar content and milder flavor compared to Aka miso (red).", "If using skin-on salmon, do not expect crispy skin with this method as the fish sits in the marinade. The skin helps insulate the meat during roasting.", "Serve with steamed jasmine rice and blistered snap peas for a complete meal."]', '"This dish is a home-cook friendly adaptation of ''Gindara Miso'' (Miso Black Cod), made famous globally by Chef Nobu Matsuhisa. While the traditional recipe uses sake lees and takes days to cure, this version captures the essence of the sweet-savory ''Saikyo Yaki'' style using accessible ingredients for a weeknight dinner."', 473.99);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('e5d93476-53f3-467a-9c4e-f5f525b6592e', 'Brown Butter Chocolate Chip Cookie Cake', 'A dense, chewy oversized cookie with deep caramel notes from browned butter. The extra egg yolk ensures a fudgy, tender crumb, while the crisp golden edges provide the perfect textural contrast to the soft center.', 'dessert', 'American', 'Intermediate', '["american", "cakes", "bittersweet chocolate", "brown butter", "chocolate chip cookie", "kid-friendly", "party", "semisweet chocolate chip", "easy", "dessert", "birthday"]', '[{"group_name": "Wet Ingredients", "items": [{"name": "unsalted butter", "quantity": 170, "unit": "g", "preparation": "cold or room temp", "notes": "Will be browned", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "dark brown sugar", "quantity": 200, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated white sugar", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "large egg", "quantity": 1, "unit": null, "preparation": "room temperature", "notes": "approx. 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "egg yolk", "quantity": 1, "unit": null, "preparation": "room temperature", "notes": "approx. 18g", "substitutions": [], "ingredient_id": "f2620643-65a0-4dda-ad74-f40982f9cf84", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dry Ingredients & Mix-ins", "items": [{"name": "all-purpose flour", "quantity": 215, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 8, "unit": "g", "preparation": null, "notes": "Adds tenderness", "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "semisweet chocolate chips", "quantity": 170, "unit": "g", "preparation": null, "notes": "Reserve a handful for topping", "substitutions": ["bittersweet chocolate chunks", "milk chocolate chips"], "ingredient_id": "d5e5830a-bf2e-4bb2-b6b2-81be34a8fba1", "nutrition_source": "Aggregated Public Data"}, {"name": "flaky sea salt", "quantity": null, "unit": null, "preparation": null, "notes": "Optional, for finishing", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 175\u00b0C (350\u00b0F). Grease a 9-inch round cake pan lightly with butter or non-stick spray.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Place the butter in a light-colored saucepan over medium heat. Cook, swirling the pan occasionally, until the butter foams, then quiets down, and brown specks form at the bottom with a nutty aroma (about 5-8 minutes).", "structured": {"action": "HEAT", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Golden brown specks on bottom", "tactile": "Nutty aroma"}}, "tips": ["Use a light-colored pan to easily see the color change so you don''t burn the butter."]}, {"step_number": 3, "phase": "prep", "text": "Pour the browned butter (including all the toasted brown bits) into a large heatproof mixing bowl. Let it cool for 10 minutes until warm but not hot.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Whisk the brown sugar and granulated sugar into the cooled butter until combined. The mixture may look slightly gritty, which is normal.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Add the whole egg, egg yolk, and vanilla extract. Whisk vigorously for about 1 minute until the mixture becomes smooth, glossy, and slightly thickened.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Glossy and pale", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "Add the flour, cornstarch, baking soda, and fine sea salt. Switch to a spatula and mix just until no flour streaks remain.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Do not overmix at this stage, or the cake will be tough."]}, {"step_number": 7, "phase": "prep", "text": "Fold in the chocolate chips, reserving a small handful to press into the top later.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Transfer the dough to the prepared pan. Press it down into an even layer using your spatula or fingertips. Press the reserved chocolate chips into the top surface.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Bake for 20-25 minutes. The edges should be golden brown and set, while the center should still look slightly soft and underbaked. Do not overbake.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT25M", "doneness_cues": {"visual": "Golden edges, soft center", "tactile": null}}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Remove from the oven and sprinkle with flaky sea salt if desired. Place the pan on a wire rack and let cool completely in the pan before slicing. The center will firm up as it cools.", "structured": {"action": "COOL", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT50M", "total_time": "PT1H15M", "overnight_required": false, "yields": "1 9-inch cake", "yield_count": 10, "serving_size_g": 90}', '{"flags": ["Vegetarian", "Nut-Free"], "not_suitable_for": ["Vegans", "Gluten Intolerant"]}', '{"per_serving": {"calories": 402.18, "protein_g": 4.15, "carbohydrates_g": 53.13, "fat_g": 20.15, "saturated_fat_g": 12.5, "trans_fat_g": null, "monounsaturated_fat_g": 4.39, "polyunsaturated_fat_g": 0.77, "fiber_g": 1.67, "sugar_g": 33.24, "sodium_mg": 281.02, "cholesterol_mg": 74.59, "potassium_mg": 137.28, "calcium_mg": 29.3, "iron_mg": 0.84, "magnesium_mg": 12.43, "phosphorus_mg": 123.6, "zinc_mg": 0.28, "vitamin_a_mcg": 131.14, "vitamin_c_mg": null, "vitamin_d_mcg": 0.2, "vitamin_e_mg": 0.51, "vitamin_k_mcg": 1.28, "vitamin_b6_mg": 0.03, "vitamin_b12_mcg": 0.11, "thiamin_mg": 0.03, "riboflavin_mg": 0.05, "niacin_mg": 0.31, "folate_mcg": 11.28, "water_g": 10.93, "alcohol_g": 0.34, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container to prevent drying out.", "duration": "P5D"}, "freezer": {"notes": "Wrap individual slices tightly in plastic wrap and foil.", "duration": "P2M"}, "reheating": "Microwave for 10-15 seconds to restore warmth and chewiness.", "does_not_keep": false}', '[{"name": "Light-colored saucepan", "required": true, "alternative": "Stainless steel skillet"}, {"name": "9-inch round cake pan", "required": true, "alternative": "9-inch cast iron skillet or pie dish"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Silicone spatula", "required": true, "alternative": null}]', '[{"symptom": "Cookie cake is dry or hard", "likely_cause": "Overbaking", "prevention": "Pull the cake from the oven when the center still looks slightly raw; carryover heat finishes the cooking.", "fix": "Serve warmed with ice cream to mask the dryness."}, {"symptom": "Butter burned instead of browned", "likely_cause": "Heat was too high or pan wasn''t watched", "prevention": "Use medium heat and swirl constantly once foaming starts.", "fix": "Cannot be fixed. Discard and start over to avoid acrid taste."}]', '["Browning the butter evaporates water, meaning you lose volume. The recipe accounts for this, but don''t skip scraping the pan\u2014the brown bits are pure flavor.", "The extra egg yolk adds fat and emulsifiers, creating a richer, fudgier texture closer to a brownie than a standard crisp cookie.", "Cornstarch is the secret weapon here; it softens the harsh proteins in the flour to keep the cookie cake tender even if slightly overbaked.", "For a birthday treat, pipe buttercream frosting around the rim after the cake has completely cooled."]', '"The chocolate chip cookie, invented by Ruth Wakefield in the 1930s, is a quintessential American dessert. The ''cookie cake'' variation emerged in American shopping malls in the 1970s and 80s as a popular alternative to traditional birthday cakes, celebrating the country''s love for soft, gooey textures over airy sponges."', 402.18);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('e65e6b3e-04d3-40f6-b967-3ad1a2a077ce', 'Rustic Ribollita (Tuscan Bread Soup)', 'A robust and comforting Tuscan classic where day-old bread melts into a savory broth loaded with creamy cannellini beans, cavolo nero, and aromatic vegetables. The bread acts as a thickener, creating a silky, spoon-standing texture that transforms humble leftovers into a gastronomic centerpiece.', 'soup', 'Italian', 'Intermediate', '["mediterranean", "italian", "one pot", "vegetarian", "vegan", "budget-friendly", "comfort food", "high fiber"]', '[{"group_name": "Soffritto & Aromatics", "items": [{"name": "extra virgin olive oil", "quantity": 80, "unit": "ml", "preparation": "plus extra for serving", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 2, "unit": null, "preparation": "diced", "notes": "approx 300g total", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "carrots", "quantity": 2, "unit": null, "preparation": "diced", "notes": "approx 150g total", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "celery stalks", "quantity": 2, "unit": null, "preparation": "diced", "notes": "approx 120g total", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "minced", "notes": null, "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh thyme", "quantity": 4, "unit": null, "preparation": null, "notes": "sprigs", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Soup Base", "items": [{"name": "cannellini beans", "quantity": 480, "unit": "g", "preparation": "cooked/canned", "notes": "drained and rinsed weight (approx 2 cans)", "substitutions": [], "ingredient_id": "338d5b1f-5e90-4e7f-b286-e827b78558e9", "nutrition_source": "Aggregated Public Data"}, {"name": "whole peeled tomatoes", "quantity": 400, "unit": "g", "preparation": "canned", "notes": "crushed by hand", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "cavolo nero (lacinato kale)", "quantity": 300, "unit": "g", "preparation": "tough stems removed, leaves roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "bb6a90eb-f157-455a-b438-d2333c784c60", "nutrition_source": "USDA FoodData Central"}, {"name": "savoy cabbage", "quantity": 250, "unit": "g", "preparation": "shredded", "notes": null, "substitutions": [], "ingredient_id": "dff437b6-b727-4312-86be-82ff42b14644", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable stock", "quantity": 1500, "unit": "ml", "preparation": "hot", "notes": null, "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Bread & Finish", "items": [{"name": "stale country bread", "quantity": 350, "unit": "g", "preparation": "torn into large chunks", "notes": "sourdough or rustic Italian loaf preferred", "substitutions": [], "ingredient_id": "dc2725fb-42eb-4769-a033-2297b90bcbf7", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Heat the olive oil in a Dutch oven over medium heat. Add the diced onion, carrot, and celery with a pinch of salt.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": "PT10M", "doneness_cues": {"visual": "Vegetables are softened and translucent but not browned", "tactile": null}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add the minced garlic and thyme sprigs. Stir constantly for about 1-2 minutes until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Garlic is aromatic and pale gold", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the hand-crushed tomatoes and their juices along with the cannellini beans. Simmer for 5 minutes.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Remove the pot briefly from heat or lower heat significantly. Use a potato masher to crush about half of the beans directly in the pot. This releases starch to thicken the soup.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Mixture becomes thicker and pasty"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour in the hot vegetable stock. Stir in the chopped cavolo nero and savoy cabbage. Bring to a boil, then reduce heat to low.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Cover and simmer gently for 30 minutes until the greens are very tender.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Add the stale bread chunks. Submerge them into the liquid. Cook for another 5-10 minutes, stirring occasionally to help the bread break down slightly.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Bread is swollen and soft, soup is thick", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from heat. Discard the thyme sprigs. Let the soup rest for at least 15 minutes before serving to allow flavors to meld.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Serve warm, drizzled generously with high-quality olive oil and plenty of black pepper.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT50M", "total_time": "PT1H35M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 400}', '{"flags": ["Vegetarian", "Vegan", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 523.52, "protein_g": 23.63, "carbohydrates_g": 78.2, "fat_g": 16.18, "saturated_fat_g": 2.21, "trans_fat_g": null, "monounsaturated_fat_g": 9.77, "polyunsaturated_fat_g": 1.6, "fiber_g": 16.49, "sugar_g": 12.64, "sodium_mg": 1866.68, "cholesterol_mg": null, "potassium_mg": 1459.91, "calcium_mg": 301.31, "iron_mg": 6.84, "magnesium_mg": 145.56, "phosphorus_mg": 274.25, "zinc_mg": 2.74, "vitamin_a_mcg": 405.71, "vitamin_c_mg": 51.55, "vitamin_d_mcg": null, "vitamin_e_mg": 2.51, "vitamin_k_mcg": 213.37, "vitamin_b6_mg": 0.27, "vitamin_b12_mcg": null, "thiamin_mg": 0.11, "riboflavin_mg": 0.12, "niacin_mg": 0.88, "folate_mcg": 63.84, "water_g": 171.41, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves significantly after 24 hours. The soup will thicken; thin with water or stock when reheating.", "duration": "P4D"}, "freezer": {"notes": "Bread texture may become slightly mushier upon thawing, but flavor remains excellent.", "duration": "P3M"}, "reheating": "Gently reheat on the stove over low heat. If too thick, add a splash of water.", "does_not_keep": false}', '[{"name": "Dutch oven or heavy-bottomed pot", "required": true, "alternative": "Large stockpot"}, {"name": "Potato masher", "required": false, "alternative": "Back of a wooden spoon or fork"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Soup has turned into a solid porridge", "likely_cause": "The bread was very dry and absorbed more liquid than expected", "prevention": "Add bread gradually or increase initial stock quantity", "fix": "Stir in extra hot vegetable stock or water 50ml at a time until desired consistency is reached"}]', '["The name ''Ribollita'' means ''reboiled.'' This soup is traditionally made one day, chilled, and reheated the next. The flavor complexity doubles after an overnight rest.", "Do not use sliced sandwich bread. You need a dense, rustic loaf (ideally sourdough or ciabatta) with a thick crust to maintain some texture without dissolving into glue.", "If you have a parmesan rind (and are not strictly vegan), add it during step 5 for a massive umami boost. Remove before serving.", "The quality of the finishing olive oil makes or breaks this dish. Use your best peppery, grassy extra virgin olive oil for the final drizzle."]', '"Originating from the peasant kitchens of Tuscany, Ribollita was created to prevent food waste by utilizing leftover minestrone and stale bread. In the Middle Ages, servants would gather bread-trenchers (bread used as plates) from noble banquets and boil them with vegetables for their own dinner."', 523.52);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('e67b1bc0-3bce-456a-b39e-be7d41e9bdf0', 'Seared Steak Soba Noodle Salad', 'Chilled buckwheat noodles tossed in a vibrant ginger-lime vinaigrette, topped with savory strips of seared steak, crisp bok choy, and sweet carrots. A perfect balance of savory meat, earthy noodles, and refreshing acidity.', 'salad', 'Japanese Fusion', 'Intermediate', '["meat", "noodles", "vegetables", "bok choy", "carrot", "ginger", "lime", "mint", "salad", "scallion", "sesame oil", "soba noodle", "soy sauce", "steak", "dinner", "lunch", "weeknight"]', '[{"group_name": "Steak", "items": [{"name": "beef sirloin or ribeye steak", "quantity": 500, "unit": "g", "preparation": "room temperature", "notes": "approx 2.5cm thick", "substitutions": [], "ingredient_id": "6ab398fc-b106-4c49-a2c7-0c643f644581", "nutrition_source": "Aggregated Public Data"}, {"name": "neutral oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "vegetable or grapeseed", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "generous pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Dressing", "items": [{"name": "soy sauce", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "1a157828-0624-4e67-815d-8e6bdf8b23c2", "nutrition_source": "USDA FoodData Central"}, {"name": "lime juice", "quantity": 45, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "sesame oil", "quantity": 30, "unit": "ml", "preparation": "toasted", "notes": null, "substitutions": [], "ingredient_id": "e74beff5-5295-4a3f-82fb-9f8ef1d5da59", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 15, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "honey", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": ["brown sugar", "maple syrup"], "ingredient_id": "c28eb19b-d201-4613-8f48-6a449cc81c71", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 3g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Salad Base", "items": [{"name": "soba noodles", "quantity": 300, "unit": "g", "preparation": "dried", "notes": null, "substitutions": [], "ingredient_id": "8080cc31-f977-46d8-a72b-dd84a250ba92", "nutrition_source": "Aggregated Public Data"}, {"name": "baby bok choy", "quantity": 200, "unit": "g", "preparation": "quartered lengthwise", "notes": null, "substitutions": [], "ingredient_id": "562bdece-f897-4d03-be7a-94be5ef3f681", "nutrition_source": "Aggregated Public Data"}, {"name": "carrot", "quantity": 100, "unit": "g", "preparation": "julienned or shredded", "notes": null, "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "scallions", "quantity": 2, "unit": null, "preparation": "thinly sliced", "notes": "approx 30g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh mint leaves", "quantity": 10, "unit": "g", "preparation": "rough chopped", "notes": null, "substitutions": [], "ingredient_id": "17abecc0-a2a0-4478-8486-57b46e4305c9", "nutrition_source": "USDA FoodData Central"}, {"name": "toasted sesame seeds", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0edc9256-6bac-4718-9f80-12351b1bc941", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Whisk together soy sauce, lime juice, toasted sesame oil, grated ginger, honey, and minced garlic in a small bowl until the honey is fully dissolved. Set aside.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Pat the steak dry with paper towels and season generously with salt and pepper. Heat neutral oil in a heavy skillet over high heat until shimmering. Sear the steak for 3-4 minutes per side until deeply browned and internal temperature reaches 52\u00b0C/125\u00b0F for medium-rare.", "structured": {"action": "SEAR", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT8M", "doneness_cues": {"visual": "Deep brown crust", "tactile": "Slight resistance when pressed"}}, "tips": []}, {"step_number": 3, "phase": "finish", "text": "Transfer steak to a cutting board and let rest for at least 10 minutes. This allows juices to redistribute.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Bring a large pot of water to a boil. Add soba noodles and cook according to package instructions (usually 3-4 minutes). In the last 1 minute of cooking, toss in the quartered bok choy to blanch.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Drain noodles and bok choy immediately. Rinse vigorously under cold running water, rubbing the noodles gently to remove excess starch and stop the cooking process.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Noodles are cool and not slimy"}}, "tips": ["Vigorous rinsing is critical for soba texture; otherwise, they become gummy."]}, {"step_number": 6, "phase": "assemble", "text": "Slice the rested steak against the grain into thin strips. In a large bowl, toss the cold noodles, blanched bok choy, carrots, half the scallions, and half the mint with the dressing.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Divide noodle mixture among plates. Top with steak slices. Garnish with remaining scallions, mint, and toasted sesame seeds.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT10M", "total_time": "PT35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Dairy-Free", "Nut-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 400.65, "protein_g": 38.87, "carbohydrates_g": 26.41, "fat_g": 16.97, "saturated_fat_g": 3.35, "trans_fat_g": null, "monounsaturated_fat_g": 3.24, "polyunsaturated_fat_g": 3.48, "fiber_g": 1.93, "sugar_g": 5.35, "sodium_mg": 1269.31, "cholesterol_mg": null, "potassium_mg": 809.54, "calcium_mg": 111.31, "iron_mg": 3.54, "magnesium_mg": 53.59, "phosphorus_mg": 317.63, "zinc_mg": 5.31, "vitamin_a_mcg": 288.62, "vitamin_c_mg": 23.35, "vitamin_d_mcg": null, "vitamin_e_mg": 0.35, "vitamin_k_mcg": 20.34, "vitamin_b6_mg": 0.1, "vitamin_b12_mcg": null, "thiamin_mg": 0.05, "riboflavin_mg": 0.05, "niacin_mg": 0.84, "folate_mcg": 16.94, "water_g": 54.86, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Keep dressing separate if possible to prevent noodles from becoming soggy.", "duration": "P2D"}, "freezer": {"notes": "Noodles and fresh vegetables do not freeze well.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Cast iron skillet or heavy-bottomed pan", "required": true, "alternative": null}, {"name": "Large pot", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Noodles are gummy or clumped together", "likely_cause": "Insufficient rinsing after boiling", "prevention": "Wash noodles vigorously in cold water, rubbing strands together to remove surface starch", "fix": "Rinse again under cold water before adding dressing"}]', '["Always slice the steak against the grain (perpendicular to the muscle fibers) to ensure every bite is tender.", "Soba noodles cook very quickly. Watch them closely and prioritize stopping the cooking with cold water immediately.", "For an extra depth of flavor, toast the sesame seeds in a dry pan for 1-2 minutes until fragrant before garnishing.", "If the dressing tastes too sharp, add another teaspoon of honey or a splash of water to mellow the acidity.", "Ensure the steak is dry before searing; moisture creates steam and prevents a good crust."]', '"Soba (buckwheat) noodles have been a staple in Tokyo (Edo) since the Tokugawa period. This dish applies the concept of ''Bukkake Soba''\u2014cold noodles with toppings and sauce\u2014fused with Western steakhouse elements for a protein-rich modern meal."', 400.65);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('e7746924-d9c5-49a5-aaa4-dab3b654a6a8', 'Balsamic New Potato & Red Pepper Salad', 'A vibrant, lighter alternative to creamy potato salads. Tender waxy potatoes absorb a tangy balsamic vinaigrette while warm, contrasted by the crisp sweetness of fresh red bell peppers and the mild onion bite of abundant chives.', 'salad', 'European', 'Easy', '["chive", "new potato", "potato salad", "red bell pepper", "vegan", "summer", "picnic"]', '[{"group_name": "Salad Base", "items": [{"name": "new potatoes", "quantity": 800, "unit": "g", "preparation": "whole or halved if large", "notes": "waxy variety like Red Bliss or Fingerling", "substitutions": [], "ingredient_id": "a42f15cd-1712-408f-ac5a-725056bb71b5", "nutrition_source": "Aggregated Public Data"}, {"name": "red bell pepper", "quantity": 1, "unit": null, "preparation": "diced small (0.5cm)", "notes": "approx 150g", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh chives", "quantity": 15, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Balsamic Vinaigrette", "items": [{"name": "olive oil", "quantity": 60, "unit": "ml", "preparation": "extra virgin", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "balsamic vinegar", "quantity": 30, "unit": "ml", "preparation": "good quality", "notes": null, "substitutions": [], "ingredient_id": "4da62caf-a01b-4477-b6bb-f4213102565d", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 5, "unit": "g", "preparation": null, "notes": "helps emulsify", "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "plus more for boiling water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly ground", "notes": "to taste, approx 1g", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Wash the potatoes thoroughly. Leave whole if small, or cut into uniform 3-4 cm chunks. Dice the red bell pepper into small 0.5 cm cubes and finely chop the chives.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Place potatoes in a large pot and cover with cold water by at least 2 cm. Add a generous pinch of salt. Bring to a boil over high heat, then reduce to a simmer.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Simmer the potatoes until tender when pierced with a fork, approximately 15-20 minutes depending on size. Do not overcook to the point of crumbling.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": null, "tactile": "Fork slides in easily with no resistance"}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "While potatoes cook, whisk together the olive oil, balsamic vinegar, Dijon mustard, salt, and black pepper in a large mixing bowl until fully emulsified.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Drain the potatoes well. While they are still hot, transfer them immediately to the bowl with the vinaigrette and toss gently to coat. The heat helps the potatoes absorb the dressing.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Allow the potatoes to cool to room temperature (about 20 minutes). Once cooled, fold in the diced red bell peppers and fresh chives. Serve immediately or chill for later.", "structured": {"action": "COOL", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": ["Adding fresh herbs to hot potatoes will turn them dark and wilted; waiting for them to cool keeps the chives bright green."]}]', '{"active_time": "PT20M", "passive_time": "PT25M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 250}', '{"flags": ["Vegan", "Vegetarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 323.53, "protein_g": 4.03, "carbohydrates_g": 43.95, "fat_g": 15.39, "saturated_fat_g": 2.1, "trans_fat_g": null, "monounsaturated_fat_g": 10.96, "polyunsaturated_fat_g": 1.64, "fiber_g": 4.59, "sugar_g": 4.51, "sodium_mg": 338.88, "cholesterol_mg": null, "potassium_mg": 2071.89, "calcium_mg": 58.91, "iron_mg": 2.29, "magnesium_mg": 127.41, "phosphorus_mg": 253.75, "zinc_mg": 1.74, "vitamin_a_mcg": 83.47, "vitamin_c_mg": 94.18, "vitamin_d_mcg": null, "vitamin_e_mg": 2.76, "vitamin_k_mcg": 11.28, "vitamin_b6_mg": 0.11, "vitamin_b12_mcg": null, "thiamin_mg": 0.02, "riboflavin_mg": 0.04, "niacin_mg": 0.37, "folate_mcg": 17.29, "water_g": 40.34, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors meld over time, but peppers may lose some crispness.", "duration": "P3D"}, "freezer": {"notes": "Do not freeze; potatoes become mealy and peppers mushy.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Small whisk or jar", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Potatoes are falling apart", "likely_cause": "Potatoes were overcooked or a starchy variety (like Russet) was used instead of waxy.", "prevention": "Use waxy new potatoes and check for doneness early.", "fix": "Handle very gently and mash slightly for a ''smashed'' potato salad style."}, {"symptom": "Dressing tastes too sharp", "likely_cause": "Balsamic vinegar acidity varies by brand.", "prevention": "Taste dressing before adding potatoes.", "fix": "Add a teaspoon of maple syrup or sugar to balance the acidity."}]', '["Dressing the potatoes while they are hot is the secret to a flavorful interior, not just a coated exterior.", "For the best texture, ensure the red peppers are diced very small so they distribute evenly in every bite.", "If you want a more robust meal, this salad pairs exceptionally well with grilled fish or roast chicken.", "Leftovers can be saut\u00e9ed in a pan the next day for a delicious crispy potato hash."]', '"While creamy potato salads are a staple of American picnics, vinegar-based potato salads have deep roots in German and French cuisine. This version utilizes balsamic vinegar for a modern, sweeter acidity profile that highlights the earthiness of the new potatoes."', 323.53);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('e7b1e59c-2641-4c39-8d8b-4d954fc585d6', 'Cocoa-Molasses Ginger Drops', 'Intense, bite-sized cookies that marry the earthy bitterness of dark cocoa and robust molasses with the sharp, resonant heat of fresh ginger. A crisp sugar shell yields to a deeply chewy interior.', 'dessert', 'American', 'Intermediate', '["christmas cookie", "cocoa powder", "make-ahead", "molasses", "dessert", "winter", "christmas"]', '[{"group_name": "Aromatics & Fats", "items": [{"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": "softened", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger root", "quantity": 25, "unit": "g", "preparation": "peeled and finely grated", "notes": "measure after grating for accuracy", "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "dark brown sugar", "quantity": 100, "unit": "g", "preparation": "packed", "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Liquids", "items": [{"name": "unsulphured molasses", "quantity": 85, "unit": "g", "preparation": null, "notes": "do not use blackstrap", "substitutions": [], "ingredient_id": "c76e81ce-ce17-4595-b9ff-30c87fb7c285", "nutrition_source": "USDA FoodData Central"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": "large", "notes": "approx 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Dry Ingredients", "items": [{"name": "all-purpose flour", "quantity": 195, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "dutch-process cocoa powder", "quantity": 30, "unit": "g", "preparation": null, "notes": "sifted", "substitutions": [], "ingredient_id": "c06a8e5a-163a-4f21-ad00-a6d90e34c38c", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 6, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "freshly ground black pepper", "quantity": 1, "unit": "g", "preparation": null, "notes": "finely ground", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Finishing", "items": [{"name": "granulated sugar", "quantity": 60, "unit": "g", "preparation": null, "notes": "for rolling", "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Whisk together the flour, cocoa powder, baking soda, salt, cinnamon, and black pepper in a medium bowl until uniformly combined.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a stand mixer fitted with the paddle attachment, beat the softened butter, dark brown sugar, and freshly grated ginger on medium speed until creamy and fragrant.", "structured": {"action": "CREAM", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Lightened in color", "tactile": "Smooth texture"}}, "tips": ["Creaming the ginger with the butter infuses the fat with the spicy oils better than adding it later."]}, {"step_number": 3, "phase": "prep", "text": "Add the molasses and egg to the butter mixture. Mix on medium-low until fully incorporated, scraping down the sides of the bowl as needed.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Add the dry ingredients in two batches, mixing on low speed just until no streaks of flour remain. Do not overmix.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": {"visual": "Uniform dark dough", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Cover the bowl tightly with plastic wrap and chill in the refrigerator for at least 1 hour. This hydrates the flour and firms the sticky dough for rolling.", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Preheat your oven to 175\u00b0C (350\u00b0F). Line baking sheets with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Scoop small portions of dough (approx 12-14g each) and roll them into smooth balls between your palms. Roll each ball in the granulated sugar to coat completely.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Arrange the sugar-coated balls on the baking sheets, spaced 5cm (2 inches) apart. Bake for 9-11 minutes. They should look crackled and set around the edges but slightly soft in the center.", "structured": {"action": "BAKE", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT10M", "doneness_cues": {"visual": "Crackled tops, matte finish", "tactile": "Edges firm, center gives slightly"}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Allow the cookies to cool on the baking sheet for 5 minutes to set their structure, then transfer to a wire rack to cool completely.", "structured": {"action": "COOL", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT1H15M", "total_time": "PT1H50M", "overnight_required": false, "yields": "36 small cookies", "yield_count": 36, "serving_size_g": 18}', '{"flags": ["Vegetarian", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 71.12, "protein_g": 0.94, "carbohydrates_g": 10.97, "fat_g": 2.9, "saturated_fat_g": 1.73, "trans_fat_g": null, "monounsaturated_fat_g": 0.84, "polyunsaturated_fat_g": 0.15, "fiber_g": 0.51, "sugar_g": 6.17, "sodium_mg": 82.38, "cholesterol_mg": 12.03, "potassium_mg": 62.84, "calcium_mg": 11.4, "iron_mg": 0.35, "magnesium_mg": 11.92, "phosphorus_mg": 16.64, "zinc_mg": 0.13, "vitamin_a_mcg": 24.09, "vitamin_c_mg": 0.04, "vitamin_d_mcg": 0.03, "vitamin_e_mg": 0.1, "vitamin_k_mcg": 0.33, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": 0.02, "thiamin_mg": 0.01, "riboflavin_mg": 0.01, "niacin_mg": 0.12, "folate_mcg": 2.54, "water_g": 3.36, "alcohol_g": null, "caffeine_mg": 1.92}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"duration": null}, "freezer": {"notes": "Freeze raw dough balls or baked cookies.", "duration": "P3M"}, "reheating": "Room temperature preferred", "does_not_keep": false}', '[{"name": "Stand mixer or hand mixer", "required": true, "alternative": null}, {"name": "Microplane or fine grater", "required": true, "alternative": "Sharp knife for very fine mince"}, {"name": "Baking sheets", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Wire rack", "required": true, "alternative": null}, {"name": "Sieve", "required": false, "alternative": "Whisk"}]', '[{"symptom": "Cookies are flat and greasy", "likely_cause": "The dough was too warm when it went into the oven", "prevention": "Ensure the full 1 hour chill time is respected; if the kitchen is hot, chill the rolled balls for 10 minutes before baking", "fix": "Refrigerate remaining dough before baking the next batch"}, {"symptom": "Cookies are tough or cakey rather than chewy", "likely_cause": "Overmixing the flour or overbaking", "prevention": "Stop mixing as soon as the flour disappears; pull from oven while centers look slightly underdone", "fix": "Cannot be fixed"}]', '["Using fresh ginger is non-negotiable for the ''grown-up'' flavor profile; powdered ginger lacks the necessary sharp, citrusy heat.", "Dutch-process cocoa provides a darker color and lowers the acidity, allowing the baking soda to react primarily with the molasses for a better puff and crackle.", "The pinch of black pepper acts as a flavor bridge, connecting the earthiness of the cocoa with the heat of the ginger.", "These cookies improve after 24 hours as the moisture from the molasses migrates, making them chewier."]', '"This recipe sits at the intersection of traditional European gingerbread and American molasses crinkles. By introducing cocoa, it pulls the flavor profile toward ''Pain d''\u00e9pices'' nuances while retaining the satisfying chew of a modern holiday cookie."', 71.12);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('e7de9d63-60cf-4953-960a-0f2d0247ed42', 'Rustic Smoked Tuna and Cannellini Spread', 'A creamy, savory spread marrying the mild nuttiness of white beans with the intense wood-fired aroma of smoked tuna. Brightened with fresh lemon and piney rosemary, this rustic pâté offers a sophisticated yet effortless topping for warm crostini.', 'appetizer', 'Italian', 'Easy', '["italian", "cannellini bean", "five ingredient", "appetizer", "side", "winter", "new year''s day"]', '[{"group_name": "Base", "items": [{"name": "cannellini beans", "quantity": 240, "unit": "g", "preparation": "cooked, rinsed and drained", "notes": "approx. 1 standard 400g can", "substitutions": [], "ingredient_id": "338d5b1f-5e90-4e7f-b286-e827b78558e9", "nutrition_source": "Aggregated Public Data"}, {"name": "smoked tuna", "quantity": 120, "unit": "g", "preparation": "drained if in oil", "notes": "fillets or canned", "substitutions": ["high-quality canned tuna + 2g smoked paprika"], "ingredient_id": "0bd78364-f224-4df6-8d1c-1d03dc89c1e9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics & Seasoning", "items": [{"name": "extra virgin olive oil", "quantity": 30, "unit": "ml", "preparation": "plus extra for drizzling", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh rosemary", "quantity": 2, "unit": "g", "preparation": "finely chopped", "notes": "leaves from 1 large sprig", "substitutions": [], "ingredient_id": "fa90a3a7-86cd-40de-8f8c-0464231925c2", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 4g, optional", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the ingredients by rinsing the cannellini beans thoroughly until the water runs clear. Drain the smoked tuna and flake it gently. Strip the rosemary leaves from the woody stem and chop finely.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a food processor, combine the drained beans, smoked tuna, olive oil, lemon juice, chopped rosemary, and minced garlic (if using).", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Pulse the mixture until it reaches your desired consistency. For a rustic spread, pulse 5-6 times to leave some texture. For a smooth mousse-like dip, process continuously for 30-45 seconds.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT45S", "doneness_cues": {"visual": "Uniform consistency, no large chunks of garlic", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Taste the spread and season with freshly cracked black pepper. Salt is likely unnecessary due to the cured fish and canned beans, but adjust if needed. Pulse once to incorporate.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Transfer to a serving bowl. Drizzle with a little extra virgin olive oil and garnish with a small sprig of rosemary before serving.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT0M", "total_time": "PT10M", "overnight_required": false, "yields": "400g", "yield_count": 4, "serving_size_g": 100}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Low-Carb"], "not_suitable_for": []}', '{"per_serving": {"calories": 257.08, "protein_g": 15.98, "carbohydrates_g": 33.86, "fat_g": 10.75, "saturated_fat_g": 1.63, "trans_fat_g": null, "monounsaturated_fat_g": 6.35, "polyunsaturated_fat_g": 2.03, "fiber_g": 7.43, "sugar_g": 0.53, "sodium_mg": 391.11, "cholesterol_mg": 3.9, "potassium_mg": 591.35, "calcium_mg": 93.65, "iron_mg": 3.86, "magnesium_mg": 82.45, "phosphorus_mg": 191.36, "zinc_mg": 1.84, "vitamin_a_mcg": 7.97, "vitamin_c_mg": 2.54, "vitamin_d_mcg": null, "vitamin_e_mg": 1.09, "vitamin_k_mcg": 4.74, "vitamin_b6_mg": 0.04, "vitamin_b12_mcg": 0.36, "thiamin_mg": 0.01, "riboflavin_mg": 0.02, "niacin_mg": 2.03, "folate_mcg": 3.75, "water_g": 23.36, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Keep in an airtight container. Bring to room temperature before serving to release flavors.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; texture becomes grainy and water separates.", "duration": null}, "reheating": null, "does_not_keep": false}', '[{"name": "Food processor", "required": true, "alternative": "Potato masher or sturdy fork"}, {"name": "Citrus juicer", "required": false, "alternative": "Hand squeeze"}, {"name": "Rubber spatula", "required": true, "alternative": null}]', '[{"symptom": "Spread is too dry or crumbly", "likely_cause": "Beans were too dry or tuna had low oil content", "prevention": "Reserve a tablespoon of the bean liquid before draining", "fix": "Add olive oil or water one teaspoon at a time while pulsing until creamy"}]', '["If you cannot find smoked tuna, use high-quality jarred tuna in olive oil and add 1/2 teaspoon of smoked paprika or a drop of liquid smoke.", "For the best flavor profile, allow the spread to sit at room temperature for 15 minutes before serving so the rosemary oils infuse the mixture.", "This recipe adheres to the ''Five Ingredient'' concept (excluding pantry staples like pepper/garlic), focusing on the quality of the tuna and beans.", "Serve on warm garlic-rubbed bruschetta or with endive leaves for a lighter, gluten-free option."]', '"Inspired by the Tuscan tradition of ''Fagioli al Tonno'', a classic bean and tuna salad. This version transforms the rustic salad into an antipasto spread, incorporating the smoking techniques often found in coastal Italian preservation methods."', 257.08);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('e7f3676b-0412-4bba-8a33-ba87d978e9d6', 'Butter-Braised Cod with Garlicky Herb Yogurt', 'Tender, flaky cod fillets gently poached in a rich emulsion of butter, white wine, and sweet softened shallots. Finished with a cool, vibrant yogurt sauce packed with fresh dill and garlic that cuts through the buttery richness.', 'dinner', 'Mediterranean', 'Easy', '["mediterranean", "seafood", "cod", "garlic", "shallot", "yogurt", "dinner", "easy", "quick", "main course", "gluten-free"]', '[{"group_name": "Garlicky Herb Yogurt", "items": [{"name": "greek yogurt", "quantity": 200, "unit": "g", "preparation": "full-fat", "notes": "cold", "substitutions": [], "ingredient_id": "61eae1a4-8517-4da8-8c29-34288cb7d8c7", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "grated or finely minced", "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh dill", "quantity": 10, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "4be2b047-475d-4c84-82d5-4883298c6121", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh mint", "quantity": 5, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "213e3d3b-d332-45a9-b35e-23ee29a27173", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": "about half a lemon", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Braised Fish", "items": [{"name": "cod fillets", "quantity": 680, "unit": "g", "preparation": "thick-cut, skin removed", "notes": "4 fillets, approx 170g each", "substitutions": ["halibut", "pollock", "haddock"], "ingredient_id": "229ccaef-c763-440b-b44f-6e22222d3fd1", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": "cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "shallots", "quantity": 3, "unit": null, "preparation": "thinly sliced into rings", "notes": "approx 100g total", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 80, "unit": "ml", "preparation": null, "notes": "Sauvignon Blanc or Pinot Grigio", "substitutions": ["chicken stock", "water with extra lemon"], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt", "quantity": 4, "unit": "g", "preparation": null, "notes": "divided for seasoning fish and sauce", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the yogurt sauce first to allow flavors to meld. In a small bowl, whisk together the Greek yogurt, grated garlic, chopped dill, mint, lemon juice, and a pinch of salt. Set aside in the refrigerator or at room temperature.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Pat the cod fillets thoroughly dry with paper towels. Season both sides generously with salt and black pepper.", "structured": {"action": "SEASON", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In a large skillet, melt half the butter (30g) over medium heat. Add the sliced shallots and saut\u00e9, stirring frequently, until they are softened and just beginning to turn golden, about 3-4 minutes.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT4M", "doneness_cues": {"visual": "Shallots are translucent and slightly golden edges", "tactile": "Soft texture"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour the white wine into the skillet to deglaze, scraping up any fond from the bottom. Add the remaining butter (30g) and let it melt into the sauce. Bring the liquid to a gentle simmer.", "structured": {"action": "DEGLAZE", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Nestle the seasoned cod fillets into the skillet among the shallots. Cover the pan with a tight-fitting lid. Reduce heat to low and simmer gently until the fish is opaque and flakes easily with a fork, approximately 6 to 8 minutes depending on thickness. Target an internal temperature of 55\u00b0C (130\u00b0F) for optimal texture, or 63\u00b0C (145\u00b0F) for FDA safety standards.", "structured": {"action": "BRAISE", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT8M", "doneness_cues": {"visual": "Fish is opaque all the way through", "tactile": "Flakes easily with gentle pressure"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Transfer the cod fillets to plates. Spoon the buttery shallots and pan juices over the fish. Top each fillet with a generous dollop of the herbed yogurt sauce and serve immediately.", "structured": {"action": "PLATE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT5M", "total_time": "PT30M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 280}', '{"flags": ["Pescatarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Egg-Free", "Low-Carb"], "not_suitable_for": ["Dairy-Free", "Vegan"]}', '{"per_serving": {"calories": 341.44, "protein_g": 35.17, "carbohydrates_g": 11.97, "fat_g": 13.46, "saturated_fat_g": 7.85, "trans_fat_g": 0.01, "monounsaturated_fat_g": 3.71, "polyunsaturated_fat_g": 0.87, "fiber_g": 1.47, "sugar_g": 2.39, "sodium_mg": 697.25, "cholesterol_mg": 107.85, "potassium_mg": 830.41, "calcium_mg": 97.85, "iron_mg": 1.27, "magnesium_mg": 63.73, "phosphorus_mg": 369.27, "zinc_mg": 0.94, "vitamin_a_mcg": 162.44, "vitamin_c_mg": 13.42, "vitamin_d_mcg": 1.53, "vitamin_e_mg": 1.46, "vitamin_k_mcg": 2.26, "vitamin_b6_mg": 0.52, "vitamin_b12_mcg": 1.57, "thiamin_mg": 0.16, "riboflavin_mg": 0.14, "niacin_mg": 3.64, "folate_mcg": 26.9, "water_g": 207.61, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Fish is best eaten immediately. Texture degrades upon reheating.", "duration": "P1D"}, "freezer": {"notes": null, "duration": null}, "reheating": "Gently warm in a covered skillet with a splash of water over low heat. Do not microwave.", "does_not_keep": false}', '[{"name": "Large skillet with lid", "required": true, "alternative": "Dutch oven"}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Microplane or grater", "required": false, "alternative": "Mince by hand"}]', '[{"symptom": "Fish is dry or rubbery", "likely_cause": "Overcooked due to high heat or too much time", "prevention": "Check the fish at the 5-minute mark; it cooks very quickly, especially if fillets are thin.", "fix": "Break the fish into smaller chunks and mix heavily with the sauce to mask dryness."}]', '["Temperature Contrast: The magic of this dish is the interplay between the hot, buttery fish and the cold, acidic yogurt sauce. Do not heat the yogurt.", "Wine Selection: Use a crisp, dry white wine like Sauvignon Blanc or Pinot Grigio. Avoid oaked Chardonnays, which can make the sauce taste bitter.", "Handling Cod: Cod is extremely delicate once cooked. Use a wide fish spatula to lift it from the pan to prevent the fillets from breaking apart.", "Serving Suggestion: Serve with crusty bread or boiled baby potatoes to soak up the delicious butter-wine emulsion."]', '"This dish draws inspiration from the Eastern Mediterranean coast, where seafood is often prepared simply with olive oil or butter and brightened with dairy and citrus. The technique of finishing warm fish with cool yogurt (often seen in Turkish or Greek cuisine) preserves the probiotics in the yogurt and creates a refreshing palate sensation."', 341.44);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('e8c53285-b1a6-40fe-ba50-29b79fb706f2', 'Lemon Berry Phyllo Mille-Feuille', 'A sophisticated deconstructed pastry featuring shattered layers of golden, butter-brushed phyllo dough, alternating with bright, silky lemon curd and a stabilizing mascarpone chantilly. Fresh berries add a burst of acidity and color to this texturally complex dessert.', 'dessert', 'French', 'Intermediate', '["lemon", "phyllo", "dessert", "french", "berries", "summer", "refined"]', '[{"group_name": "Lemon Curd", "items": [{"name": "lemon juice", "quantity": 120, "unit": "ml", "preparation": "freshly squeezed", "notes": "approx 3-4 lemons", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 6, "unit": "g", "preparation": "finely grated", "notes": null, "substitutions": [], "ingredient_id": "a5fb6a2a-dcda-4ab2-8fe6-472d7fcc39d1", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "whole eggs", "quantity": 200, "unit": "g", "preparation": null, "notes": "approx 4 large eggs", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 100, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Phyllo Layers", "items": [{"name": "phyllo dough", "quantity": 8, "unit": null, "preparation": "sheets", "notes": "approx 150g, thawed if frozen", "substitutions": [], "ingredient_id": "c070937d-c91b-4f22-90f4-6ec707a13cd2", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 80, "unit": "g", "preparation": "melted", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "icing sugar", "quantity": 20, "unit": "g", "preparation": null, "notes": "for dusting", "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Mascarpone Chantilly", "items": [{"name": "heavy cream", "quantity": 120, "unit": "ml", "preparation": "cold, 35%+ fat", "notes": null, "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "mascarpone cheese", "quantity": 80, "unit": "g", "preparation": "cold", "notes": null, "substitutions": [], "ingredient_id": "fc428935-3bcd-4cef-8495-7ed35e7dae22", "nutrition_source": "Aggregated Public Data"}, {"name": "icing sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla bean paste", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "90237166-b129-4858-8c9c-2f8a7ab9a301", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Assembly", "items": [{"name": "mixed fresh berries", "quantity": 200, "unit": "g", "preparation": "washed and dried", "notes": "raspberries, blackberries, or blueberries", "substitutions": [], "ingredient_id": "72de0107-4608-4127-b409-4956fad5e9ed", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Combine lemon juice, zest, granulated sugar, and eggs in a heatproof bowl set over a saucepan of simmering water (bain-marie). Ensure the water does not touch the bottom of the bowl.", "structured": {"action": "WHISK", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": null, "doneness_cues": {"visual": "Mixture thickens to coat the back of a spoon", "tactile": "Thick custard consistency"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Cook the curd while whisking constantly for 10-12 minutes until it reaches 82\u00b0C (180\u00b0F) or thickens significantly. Remove from heat.", "structured": {"action": "SIMMER", "temperature": {"celsius": 82, "fahrenheit": 180}, "duration": "PT12M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "finish", "text": "Strain the hot curd through a fine mesh sieve to remove zest and any coagulated egg. Whisk in the cold cubed butter one piece at a time until smooth and emulsified. Press plastic wrap directly onto the surface and refrigerate until completely set (approx 2 hours).", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2H", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Preheat oven to 190\u00b0C (375\u00b0F). Place a sheet of phyllo on a clean surface (keep others covered with a damp towel). Brush lightly with melted butter. Top with another sheet. Repeat until you have a stack of 4 sheets.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Cut the stacked phyllo into 12 even rectangles (approx 7x10cm). Place on a parchment-lined baking sheet. Top with another sheet of parchment and a second baking sheet (to keep them flat). Bake for 10-12 minutes until golden brown.", "structured": {"action": "BAKE", "temperature": null, "duration": "PT12M", "doneness_cues": {"visual": "Golden brown and crisp throughout", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "In a chilled bowl, whip the heavy cream, mascarpone, icing sugar, and vanilla bean paste until stiff peaks form. Be careful not to over-whip or the mascarpone may curdle.", "structured": {"action": "WHIP", "temperature": null, "duration": null, "doneness_cues": {"visual": "Stiff peaks hold their shape", "tactile": "Firm but creamy"}}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "To serve, place a small dab of cream on the plate to anchor the first phyllo crisp. Pipe dots of lemon curd and mascarpone cream onto the crisp. Arrange fresh berries in gaps. Top with a second crisp and repeat. Finish with a third crisp and a dusting of icing sugar.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Assemble immediately before serving to prevent the phyllo from absorbing moisture and becoming soggy."]}]', '{"active_time": "PT50M", "passive_time": "PT2H", "total_time": "PT2H50M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 240}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Vegans", "Gluten-Free diets"]}', '{"per_serving": {"calories": 920.13, "protein_g": 11.75, "carbohydrates_g": 88.79, "fat_g": 62.93, "saturated_fat_g": 36.76, "trans_fat_g": 0.39, "monounsaturated_fat_g": 16.27, "polyunsaturated_fat_g": 3.13, "fiber_g": 3.55, "sugar_g": 60.97, "sodium_mg": 275.44, "cholesterol_mg": 316.65, "potassium_mg": 170.35, "calcium_mg": 122.31, "iron_mg": 2.51, "magnesium_mg": 16.65, "phosphorus_mg": 157.91, "zinc_mg": 0.97, "vitamin_a_mcg": 618.35, "vitamin_c_mg": 30, "vitamin_d_mcg": 1.48, "vitamin_e_mg": 1.93, "vitamin_k_mcg": 5.2, "vitamin_b6_mg": 0.13, "vitamin_b12_mcg": 0.57, "thiamin_mg": 0.24, "riboflavin_mg": 0.44, "niacin_mg": 1.63, "folate_mcg": 65.25, "water_g": 103.88, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store components separately. Assembled dish must be eaten immediately.", "duration": "P3D"}, "freezer": {"notes": "Phyllo dough can be frozen before baking; curd and cream do not freeze well.", "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Heavy-bottomed saucepan", "required": true, "alternative": null}, {"name": "Heatproof bowl", "required": true, "alternative": "Double boiler"}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Fine mesh sieve", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Pastry brush", "required": true, "alternative": null}, {"name": "Stand mixer or electric hand mixer", "required": true, "alternative": null}, {"name": "Piping bag", "required": false, "alternative": "Zip-top bag with corner cut"}]', '[{"symptom": "Curd looks curdled or grainy", "likely_cause": "Heat was too high or eggs were scrambled", "prevention": "Cook over gentle steam; do not let bowl touch water; whisk constantly", "fix": "Immediately strain and blend with an immersion blender while adding the cold butter"}, {"symptom": "Phyllo is soggy or chewy", "likely_cause": "Underbaked or humidity absorption", "prevention": "Bake until deep golden; store in airtight container if not using immediately", "fix": "Re-crisp in a 180\u00b0C/350\u00b0F oven for 2-3 minutes"}]', '["Using cold butter to finish the curd (mounting) creates a glossier appearance and a silkier mouthfeel than melting it in at the start.", "Baking the phyllo between two baking sheets is the professional technique to ensure perfectly flat, stackable layers.", "For a sharper cut on the phyllo dough, use a pizza wheel or a very sharp knife and cut before baking.", "The mascarpone cream provides a necessary fatty richness to balance the high acidity of the lemon curd."]', '"While the Mille-Feuille (thousand sheets) is a French pastry classic dating back to the 17th century, the use of phyllo dough introduces a Mediterranean influence. This variation replaces the dense richness of puff pastry with the shatteringly thin, crisp texture of Greek-style dough, creating a lighter, more modern finish."', 920.13);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('e9036a7f-3b0a-4589-933f-727f04375fd3', 'Lamb Pot-au-Feu with Cockles and Roasted Rump', 'A refined surf-and-turf interpretation of the French farmhouse classic. Meltingly tender braised lamb shoulder and root vegetables simmer in an aromatic broth, finished with the briny sweetness of fresh cockles and topped with slices of perfectly roasted, pink lamb rump.', 'dinner', 'French', 'Advanced', '["lamb", "stew", "french", "pot au feu", "cockles", "surf and turf", "winter"]', '[{"group_name": "Stew Base (Shoulder)", "items": [{"name": "lamb shoulder", "quantity": 600, "unit": "g", "preparation": "cut into 3cm cubes", "notes": "boneless weight", "substitutions": [], "ingredient_id": "88f516f5-f8d5-4245-8d3a-50376dacfdc2", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "onions", "quantity": 2, "unit": null, "preparation": "quartered", "notes": "approx. 300g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "smashed", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 150, "unit": "ml", "preparation": null, "notes": "Sauvignon Blanc or Chardonnay", "substitutions": [], "ingredient_id": "5e1efe68-ff2d-432c-9239-ff83f37c5e07", "nutrition_source": "Aggregated Public Data"}, {"name": "lamb stock", "quantity": 800, "unit": "ml", "preparation": null, "notes": "or high-quality chicken stock", "substitutions": ["chicken stock", "beef stock"], "ingredient_id": "f6084980-7930-4c18-ba4b-87ea32c37572", "nutrition_source": "Aggregated Public Data"}, {"name": "bouquet garni", "quantity": 1, "unit": null, "preparation": null, "notes": "bundle of thyme, parsley stalks, bay leaf", "substitutions": [], "ingredient_id": "35bd6873-5403-4b94-81a3-3995092bd1cc", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Vegetables & Cockles", "items": [{"name": "baby carrots", "quantity": 300, "unit": "g", "preparation": "peeled and trimmed", "notes": null, "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "baby turnips", "quantity": 200, "unit": "g", "preparation": "peeled and halved", "notes": null, "substitutions": [], "ingredient_id": "b7a26052-3b0b-4df2-b816-9a3dd3c2fb32", "nutrition_source": "USDA FoodData Central"}, {"name": "leeks", "quantity": 2, "unit": null, "preparation": "white parts only, washed and cut into 3cm lengths", "notes": "approx. 150g", "substitutions": [], "ingredient_id": "c689e786-49ea-4b98-9526-3b7bb15a8edc", "nutrition_source": "USDA FoodData Central"}, {"name": "waxy potatoes", "quantity": 300, "unit": "g", "preparation": "peeled and quartered", "notes": "Charlotte or Yukon Gold", "substitutions": [], "ingredient_id": "4920385c-ae78-4023-8318-c5dfe051fecc", "nutrition_source": "USDA FoodData Central"}, {"name": "live cockles", "quantity": 500, "unit": "g", "preparation": "purged and scrubbed", "notes": null, "substitutions": ["vongole", "littleneck clams"], "ingredient_id": "561ebef2-6735-4dfe-a5e4-de3ffaaebcfd", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Roasted Lamb Rump", "items": [{"name": "lamb rump", "quantity": 400, "unit": "g", "preparation": "room temperature", "notes": "usually 2 whole rumps", "substitutions": [], "ingredient_id": "e09d98c6-36ff-4b5f-81f5-a07f54dfaa70", "nutrition_source": "Aggregated Public Data"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "thyme sprigs", "quantity": 4, "unit": null, "preparation": null, "notes": "approx. 2g", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt flakes", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 5g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place cockles in a bowl of cold salted water for 30 minutes to purge sand. Discard any with broken shells or those that do not close when tapped.", "structured": {"action": "BRINE", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Season the diced lamb shoulder with salt and pepper. In a large Dutch oven, heat olive oil over medium-high heat and sear the lamb in batches until browned on all sides. Remove lamb and set aside.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": {"visual": "Golden brown crust", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In the same pot, reduce heat to medium. Add quartered onions and smashed garlic. Saut\u00e9 for 3-4 minutes until softened but not browned. Deglaze with white wine, scraping up any fond from the bottom.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Return the seared shoulder to the pot. Add the bouquet garni and cover with lamb stock. Bring to a boil, skim off any foam, then reduce heat to low. Cover and simmer gently for 1 hour.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the potatoes, carrots, and turnips to the pot. Continue to simmer for another 20 minutes. Then add the leeks and simmer for a final 10-15 minutes until all vegetables are tender.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT35M", "doneness_cues": {"visual": null, "tactile": "Vegetables piercable with knife"}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "While vegetables finish, preheat oven to 200\u00b0C (400\u00b0F). Score the fat cap of the lamb rumps. Season generously. In a hot skillet, sear the rumps fat-side down to render, then sear all sides. Add butter and thyme, baste briefly.", "structured": {"action": "SEAR", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Transfer the skillet to the oven (or move rumps to a roasting tray). Roast for 8-12 minutes until internal temperature reaches 52\u00b0C (125\u00b0F) for medium-rare. Remove and rest in a warm place for 10 minutes.", "structured": {"action": "ROAST", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT10M", "doneness_cues": {"visual": null, "tactile": "Internal temp 52\u00b0C"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Just before serving, increase the heat under the stew. Add the drained cockles to the pot. Cover tightly and steam for 3-4 minutes until shells open. Discard any unopened cockles.", "structured": {"action": "STEAM", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Shells wide open", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "assemble", "text": "Slice the rested lamb rump against the grain. Ladle the stew (shoulder, vegetables, cockles, and broth) into shallow bowls. Fan slices of roasted rump on top. Garnish with fresh herbs if desired.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT50M", "passive_time": "PT1H40M", "total_time": "PT2H30M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 550}', '{"flags": ["Gluten-Free", "Pescatarian", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": ["Shellfish allergy sufferers"]}', '{"per_serving": {"calories": 1710.05, "protein_g": 174.51, "carbohydrates_g": 44.94, "fat_g": 102.88, "saturated_fat_g": 30.53, "trans_fat_g": null, "monounsaturated_fat_g": 7.25, "polyunsaturated_fat_g": 1.24, "fiber_g": 7.55, "sugar_g": 12.82, "sodium_mg": 3124.21, "cholesterol_mg": 16.13, "potassium_mg": 1248.75, "calcium_mg": 188.49, "iron_mg": 29.87, "magnesium_mg": 87.29, "phosphorus_mg": 387.19, "zinc_mg": 8.1, "vitamin_a_mcg": 709.93, "vitamin_c_mg": 33.53, "vitamin_d_mcg": null, "vitamin_e_mg": 2.14, "vitamin_k_mcg": 34.58, "vitamin_b6_mg": 0.52, "vitamin_b12_mcg": 0.01, "thiamin_mg": 0.2, "riboflavin_mg": 0.38, "niacin_mg": 6.01, "folate_mcg": 74.08, "water_g": 373.16, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store the roasted lamb rump and stew separately if possible. Reheat gently to avoid overcooking the cockles.", "duration": "P2D"}, "freezer": {"notes": "Stew base freezes well; do not freeze the cockles or roasted rump.", "duration": "P1M"}, "reheating": "Gently warm the stew on the stove; serve leftover rump cold or flash-sear to warm.", "does_not_keep": false}', '[{"name": "Large Dutch oven or heavy-bottomed pot", "required": true, "alternative": null}, {"name": "Heavy skillet (cast iron or stainless steel)", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Meat thermometer", "required": true, "alternative": null}, {"name": "Slotted spoon", "required": true, "alternative": null}]', '[{"symptom": "Cockles are gritty", "likely_cause": "Insufficient purging time", "prevention": "Purge in salted water (30g salt per liter) for at least 30 mins, changing water once.", "fix": "Remove meat from shells, rinse meat in clean broth, strain the main stew broth through muslin cloth."}, {"symptom": "Lamb shoulder is tough", "likely_cause": "Under-cooked or simmered too violently", "prevention": "Maintain a very gentle simmer and ensure enough cooking time before adding vegetables.", "fix": "Remove vegetables and keep warm; continue simmering meat until tender."}]', '["The brine from the cockles will season the broth significantly. Under-season the stew base slightly in the beginning to account for this salty finish.", "For the lamb rump, rendering the fat cap properly is crucial. Start in a cold pan if necessary to render fat without burning the meat, then crank the heat to sear.", "This dish relies on timing. If the stew is ready before the rump rests, simply turn off the heat on the stew (before adding cockles). Reheat to a boil, then add cockles right before plating.", "Serve with crusty sourdough bread and rouille or aioli for a true nod to French coastal stews."]', '"This recipe bridges two French traditions: the rustic ''Pot-au-Feu'' (usually beef and root vegetables) and the coastal affinity for mixing meat and shellfish. The addition of cockles introduces an iodine mineral note that cuts through the richness of the lamb fat, a technique often seen in modern bistro cooking in Brittany and Normandy."', 1710.05);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('e9e36a86-d501-4b01-b41e-ac152c87e40a', 'Classic Tartiflette (Savoyard Potato & Reblochon Gratin)', 'The quintessential après-ski comfort food from the French Alps. Tender waxy potatoes are layered with smoky bacon lardons, caramelized onions, and crème fraîche, all crowned with a melting half-wheel of nutty, pungent Reblochon cheese that bakes into a golden, crispy crust.', 'dinner', 'French', 'Intermediate', '["potato", "bacon", "cheese", "gratin", "main course", "french", "winter", "comfort food"]', '[{"group_name": "Vegetables", "items": [{"name": "waxy potatoes", "quantity": 1000, "unit": "g", "preparation": "peeled", "notes": "Yukon Gold, Charlotte, or similar firm variety", "substitutions": [], "ingredient_id": "81bea7b5-3359-4a3c-bc0b-61d8188f73e9", "nutrition_source": "Aggregated Public Data"}, {"name": "yellow onions", "quantity": 2, "unit": null, "preparation": "sliced", "notes": "approx. 300g total", "substitutions": [], "ingredient_id": "cc868876-7ceb-46a8-b72a-c3e8a743ee97", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "halved", "notes": "for rubbing the dish", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Lardons & Fats", "items": [{"name": "smoked bacon lardons", "quantity": 200, "unit": "g", "preparation": "cubed", "notes": "thick-cut smoked bacon chopped into strips", "substitutions": [], "ingredient_id": "339a356e-8f77-48fe-9293-b8e35fed3e6c", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 15, "unit": "g", "preparation": null, "notes": "use only if bacon is very lean", "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dairy & Liquids", "items": [{"name": "dry white wine", "quantity": 80, "unit": "ml", "preparation": null, "notes": "Savoy wine like Apremont or Roussette is ideal", "substitutions": [], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "cr\u00e8me fra\u00eeche", "quantity": 200, "unit": "ml", "preparation": null, "notes": "heavy cream can be substituted", "substitutions": [], "ingredient_id": "d171100e-1088-4266-8d50-06cdedda7193", "nutrition_source": "USDA FoodData Central"}, {"name": "reblochon cheese", "quantity": 450, "unit": "g", "preparation": "whole wheel", "notes": "Must be Reblochon de Savoie AOP for authenticity", "substitutions": [], "ingredient_id": "97c9f545-7d54-4ce0-a3cf-aeb1e21c0e59", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Seasoning", "items": [{"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, be careful as bacon and cheese are salty", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly ground", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the peeled potatoes in a large pot of salted water. Bring to a boil and cook for 15-20 minutes until tender but still holding their shape (knife should meet a little resistance). Drain and let cool slightly.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT20M", "doneness_cues": {"visual": null, "tactile": "Knife-tender but firm"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "While potatoes cook, heat a large skillet over medium heat. Add the bacon lardons and fry until the fat renders and edges begin to crisp. If the pan is dry, add the optional butter.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": null, "doneness_cues": {"visual": "Fat rendered, edges crispy", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the sliced onions to the skillet with the bacon. Saut\u00e9 for 5-8 minutes until the onions are soft and translucent. Deglaze the pan with the white wine and cook for 2 minutes until the liquid has mostly evaporated. Season with black pepper.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Preheat your oven to 200\u00b0C (400\u00b0F). Slice the cooled potatoes into rounds about 1cm thick.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Rub the inside of your baking dish with the cut side of the garlic clove. Arrange a layer of potato slices in the dish, followed by the bacon and onion mixture. Repeat if necessary, but typically one layer of each is sufficient for even cooking.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Pour the cr\u00e8me fra\u00eeche evenly over the potatoes. Slice the Reblochon cheese wheel horizontally (like a burger bun) to create two circles. Place the cheese circles rind-side up on top of the potatoes.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Bake in the preheated oven for 20-25 minutes. The cheese should be completely melted, bubbling, and the rind should be golden brown and crispy.", "structured": {"action": "BAKE", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT25M", "doneness_cues": {"visual": "Golden brown rind, bubbling sauce", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from the oven and let the dish rest for 5-10 minutes before serving. This allows the sauce to thicken slightly and makes serving easier.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT25M", "total_time": "PT55M", "overnight_required": false, "yields": "6 generous servings", "yield_count": 6, "serving_size_g": 350}', '{"flags": ["Gluten-Free", "Egg-Free", "Nut-Free", "Soy-Free"], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 853.4, "protein_g": 38.7, "carbohydrates_g": 80.13, "fat_g": 41.07, "saturated_fat_g": 21.69, "trans_fat_g": null, "monounsaturated_fat_g": 13.92, "polyunsaturated_fat_g": 2.34, "fiber_g": 7.67, "sugar_g": 8.16, "sodium_mg": 1504.03, "cholesterol_mg": 139.54, "potassium_mg": 2023.77, "calcium_mg": 576.13, "iron_mg": 0.93, "magnesium_mg": 35.59, "phosphorus_mg": 611.72, "zinc_mg": 4.22, "vitamin_a_mcg": 178.56, "vitamin_c_mg": 55.89, "vitamin_d_mcg": 0.44, "vitamin_e_mg": 0.46, "vitamin_k_mcg": 2.42, "vitamin_b6_mg": 0.18, "vitamin_b12_mcg": 1.65, "thiamin_mg": 0.16, "riboflavin_mg": 0.38, "niacin_mg": 3.61, "folate_mcg": 20.21, "water_g": 62.81, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Reheat gently to prevent the emulsion from splitting.", "duration": "P3D"}, "freezer": {"notes": "Not recommended. Freezing alters the texture of the potatoes and causes the cream sauce to separate.", "duration": null}, "reheating": "Reheat in a 160\u00b0C/320\u00b0F oven covered with foil for 20 minutes to maintain texture.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Large skillet or frying pan", "required": true, "alternative": null}, {"name": "Baking dish (approx. 20x30cm)", "required": true, "alternative": "Cast iron skillet"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "The dish is extremely greasy or oily", "likely_cause": "The emulsion broke due to high heat or excessive fat from the bacon", "prevention": "Drain excess fat from the bacon pan before adding onions; allow dish to rest before serving", "fix": "Use a piece of crusty bread to sop up excess surface oil before plating, or tilt dish carefully to drain"}, {"symptom": "Potatoes are hard after baking", "likely_cause": "Potatoes were not boiled enough during the prep phase", "prevention": "Ensure potatoes are knife-tender before assembling the gratin", "fix": "Cover with foil to prevent burning and bake for an additional 15-20 minutes"}]', '["Do not remove the rind of the Reblochon! It provides the signature earthy flavor and texture. You can lightly scrape the surface with a knife if it looks very rustic.", "Serve this rich dish with a sharp, acidic side to cut the fat\u2014cornichons (pickled gherkins) and a green salad with a mustard vinaigrette are the traditional accompaniments.", "Choose a waxy potato variety (like Yukon Gold or Charlotte) rather than a floury baking potato; they hold their shape better when sliced and mixed with the heavy sauce.", "If you cannot find Reblochon (it is restricted in some countries due to raw milk regulations), a decent substitute is a young Fontina, Taleggio, or a dedicated ''Tartiflette cheese'' often sold in supermarkets."]', '"While often thought of as an ancient Alpine tradition, Tartiflette was actually popularized in the 1980s by the ''Syndicat Interprofessionnel du Reblochon'' to boost cheese sales. It is inspired by a much older dish called ''P\u00e9la'' made in the Aravis valley, but has since become the iconic winter dish of the Savoy region."', 853.4);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('eb0146d1-436a-4551-94d9-9e8146b3c026', 'Spicy Harissa Spatchcock Chicken with Caramelized Squash', 'A vibrant, texturally contrasting centerpiece featuring a flattened, juicy whole chicken with shattering-crisp skin, roasted alongside sweet, tender butternut squash. Infused with North African spices for a slow-building heat.', 'dinner', 'Mediterranean', 'Intermediate', '["chicken", "spatchcock", "roast", "squash", "spicy", "sheet pan", "autumn"]', '[{"group_name": "Chicken", "items": [{"name": "whole chicken", "quantity": 1800, "unit": "g", "preparation": "room temperature", "notes": "Backbone removed (reserved)", "substitutions": [], "ingredient_id": "69a078cb-b5ac-4d3d-85f0-39e2a05f3b9e", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Spice Rub", "items": [{"name": "smoked paprika", "quantity": 8, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "ground coriander", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "cayenne pepper", "quantity": 2, "unit": "g", "preparation": null, "notes": "Adjust for heat level", "substitutions": [], "ingredient_id": "58780fb1-30a8-45d7-9983-b7a6bc626333", "nutrition_source": "Aggregated Public Data"}, {"name": "kosher salt", "quantity": 12, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 4, "unit": "g", "preparation": null, "notes": "Aluminum-free; promotes browning", "substitutions": [], "ingredient_id": "5c0b5fc8-b210-4e39-b3a6-479541ac45d2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables", "items": [{"name": "butternut squash", "quantity": 800, "unit": "g", "preparation": "peeled and cubed (2cm)", "notes": null, "substitutions": [], "ingredient_id": "7f8919a5-2de5-47ce-91b2-d2a999ea11f7", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 4, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Optional Crackling & Finish", "items": [{"name": "chicken skin", "quantity": null, "unit": null, "preparation": "cut into strips", "notes": "Harvested from reserved backbone/neck", "substitutions": [], "ingredient_id": "ea657c3c-6604-4cbf-b1a1-898b0aee7b9a", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": "wedged", "notes": null, "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place the chicken breast-side down. Using kitchen shears, cut along both sides of the backbone to remove it entirely. Flip the chicken over and press firmly on the breastbone until it cracks and lies flat (spatchcocking).", "structured": {"action": "CUT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Save the backbone for stock.", "If making the optional crackling, peel the skin off the backbone and neck area now and set aside."]}, {"step_number": 2, "phase": "prep", "text": "In a small bowl, whisk together smoked paprika, cumin, coriander, cayenne, kosher salt, and baking powder. Pat the chicken extremely dry with paper towels, rub with olive oil, then coat evenly with the spice mixture.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["The baking powder changes the pH of the skin, allowing it to dehydrate and crisp faster."]}, {"step_number": 3, "phase": "cook", "text": "Preheat oven to 220\u00b0C (425\u00b0F). Toss the cubed butternut squash with olive oil and salt. spread evenly on a rimmed baking sheet. Place a wire rack directly over the squash, then place the chicken on the rack, skin-side up.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Roast for 40-50 minutes. The high heat will crisp the skin and roast the squash simultaneously. The chicken juices will drip down, seasoning the squash.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT45M", "doneness_cues": {"visual": "Skin is deep golden brown and crispy", "tactile": "Internal temperature of thickest part of thigh reaches 74\u00b0C"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "OPTIONAL: While chicken roasts, place the reserved skin scraps in a cold, small frying pan. Turn heat to medium-low. Render the fat slowly until the skin scraps are golden brown and crunchy (gribenes). Drain on paper towels and season with salt.", "structured": {"action": "FRY", "temperature": null, "duration": null, "doneness_cues": {"visual": "Golden brown and shrunken", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove chicken from the oven when the breast reads 70\u00b0C (158\u00b0F) and thigh reads 74\u00b0C (165\u00b0F). Let rest for 10 minutes before carving. Garnish squash and chicken with fresh cilantro, lemon wedges, and the optional crispy skin crumble.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT45M", "total_time": "PT1H10M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Gluten-Free", "Dairy-Free", "Paleo", "Whole30", "Nut-Free"], "not_suitable_for": ["Vegetarians", "Vegans"]}', '{"per_serving": {"calories": 832.57, "protein_g": 94.36, "carbohydrates_g": 28.3, "fat_g": 37.82, "saturated_fat_g": 7.14, "trans_fat_g": null, "monounsaturated_fat_g": 17.31, "polyunsaturated_fat_g": 6.7, "fiber_g": 6.05, "sugar_g": 5.24, "sodium_mg": 1953.54, "cholesterol_mg": 360, "potassium_mg": 1940.82, "calcium_mg": 221.74, "iron_mg": 7.72, "magnesium_mg": 185.79, "phosphorus_mg": 891.43, "zinc_mg": 9.59, "vitamin_a_mcg": 1314.52, "vitamin_c_mg": 68.66, "vitamin_d_mcg": null, "vitamin_e_mg": 6.63, "vitamin_k_mcg": 23.69, "vitamin_b6_mg": 1.85, "vitamin_b12_mcg": 1.62, "thiamin_mg": 0.59, "riboflavin_mg": 0.89, "niacin_mg": 30.82, "folate_mcg": 102.42, "water_g": 534.17, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Skin will lose crispness; reheat in oven or air fryer.", "duration": "P3D"}, "freezer": {"notes": "Remove meat from bone before freezing. Squash texture may degrade.", "duration": "P3M"}, "reheating": "Reheat in a 180\u00b0C/350\u00b0F oven for 10-15 minutes to recrisp skin.", "does_not_keep": false}', '[{"name": "Kitchen shears", "required": true, "alternative": "Heavy chef''s knife"}, {"name": "Rimmed baking sheet", "required": true, "alternative": null}, {"name": "Wire rack", "required": true, "alternative": "Bed of sliced onions"}, {"name": "Small frying pan", "required": false, "alternative": "None (for optional crackling)"}, {"name": "Meat thermometer", "required": true, "alternative": null}]', '[{"symptom": "Chicken skin is soggy", "likely_cause": "Surface moisture on the bird before roasting", "prevention": "Pat dry thoroughly; air-dry in fridge uncovered for 12 hours if possible", "fix": "Broil for 1-2 minutes, watching constantly to prevent burning"}, {"symptom": "Squash is burning before chicken is done", "likely_cause": "Squash cubes cut too small or oven has hot spots", "prevention": "Cut squash into larger 2.5cm chunks", "fix": "Remove the baking sheet, transfer chicken directly to oven rack (place foil below to catch drips), and remove squash"}]', '["Spatchcocking reduces cooking time by nearly 40% compared to a trussed bird and ensures the breast and thighs cook evenly.", "For the ultimate skin, salt the bird and leave it uncovered in the refrigerator for 24 hours (dry brining). Skip the salt in the rub if you do this.", "The rendered fat from the chicken (schmaltz) dripping onto the squash creates a flavor depth that oil alone cannot achieve.", "If you want extra heat, mix a tablespoon of harissa paste with the olive oil before rubbing the chicken."]', '"While spatchcocking (or butterflying) dates back to 18th-century Ireland, this recipe borrows flavors from the Maghreb region of North Africa. The combination of earthy cumin, bright coriander, and heat creates a warming profile typical of Moroccan or Tunisian roasts."', 832.57);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('eb3fc8c5-3883-46be-9f29-e21a2846dd58', 'Classic Viennese Apple Strudel (Apfelstrudel)', 'A masterpiece of Austrian pastry featuring paper-thin, hand-stretched dough encasing a tender, spiced apple filling. The crisp, flaky exterior shatters upon the first bite, revealing layers of warm apples, rum-soaked raisins, and buttery toasted breadcrumbs.', 'dessert', 'Austrian', 'Advanced', '["austrian", "apple", "butter", "sugar", "dessert", "fall", "pastry", "classic"]', '[{"group_name": "Strudel Dough", "items": [{"name": "all-purpose flour", "quantity": 250, "unit": "g", "preparation": null, "notes": "Type 700 or high-gluten flour preferred for elasticity", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "warm water", "quantity": 100, "unit": "ml", "preparation": "approx 40\u00b0C", "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "neutral oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "vegetable or canola", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "white vinegar", "quantity": 3, "unit": "ml", "preparation": null, "notes": "helps relax gluten", "substitutions": [], "ingredient_id": "8d5bf07e-89a1-47ee-a6b7-d9cb03e96d64", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable oil", "quantity": 5, "unit": "ml", "preparation": null, "notes": "for coating dough while resting", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Buttered Breadcrumbs", "items": [{"name": "unsalted butter", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "fine breadcrumbs", "quantity": 80, "unit": "g", "preparation": null, "notes": "plain, unseasoned", "substitutions": [], "ingredient_id": "92441189-214a-4a8a-9cfc-dd578fe0d179", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Apple Filling", "items": [{"name": "tart apples", "quantity": 1000, "unit": "g", "preparation": "peeled, cored, and sliced", "notes": "Granny Smith, Boskoop, or Braeburn; weight before prep approx 1.2kg", "substitutions": [], "ingredient_id": "9985672b-aa9f-4125-8a32-62d520c99d6f", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 80, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "raisins", "quantity": 60, "unit": "g", "preparation": null, "notes": "optional", "substitutions": [], "ingredient_id": "4e6af4a3-1bf3-47bd-9761-7bb6a77323dd", "nutrition_source": "USDA FoodData Central"}, {"name": "dark rum", "quantity": 30, "unit": "ml", "preparation": null, "notes": "for soaking raisins; use warm water if avoiding alcohol", "substitutions": [], "ingredient_id": "55a7e674-08da-4bf6-9f1b-d58b826126eb", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Assembly & Finish", "items": [{"name": "unsalted butter", "quantity": 80, "unit": "g", "preparation": "melted", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "powdered sugar", "quantity": 20, "unit": "g", "preparation": "for dusting", "notes": null, "substitutions": [], "ingredient_id": "348e3418-0252-4e05-80e2-4ee53081f4c8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine raisins and rum in a small bowl. Let soak while preparing the dough.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a stand mixer or bowl, combine flour, salt, warm water, vinegar, and 30ml oil. Knead vigorously for 10 minutes until the dough is silky, smooth, and very elastic. If hand kneading, slam the dough against the counter occasionally.", "structured": {"action": "KNEAD", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Form the dough into a ball, coat lightly with the extra 5ml of oil, place on a plate, and cover with a warm inverted bowl. Let rest for at least 30 minutes (up to 1 hour) to relax the gluten completely.", "structured": {"action": "REST", "temperature": null, "duration": "PT30M", "doneness_cues": null}, "tips": ["Do not skip this step; resting makes stretching possible without tearing."]}, {"step_number": 4, "phase": "cook", "text": "While dough rests, melt 50g butter in a skillet over medium heat. Add breadcrumbs and toast, stirring constantly, until golden brown and fragrant. Remove from heat and let cool.", "structured": {"action": "TOAST", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT5M", "doneness_cues": {"visual": "Golden brown", "tactile": "Crispy"}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Peel, core, and cut apples into thin slices or small chunks. Toss immediately with lemon juice. Mix sugar and cinnamon in a separate small bowl. Do not mix sugar into apples yet to prevent drawing out moisture too early.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "Preheat oven to 190\u00b0C/375\u00b0F. Prepare a large workspace (dining table) by covering it with the tablecloth and dusting it generously with flour.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Place dough on the floured cloth. Roll out slightly with a rolling pin. Then, using the backs of your hands (knuckles), gently stretch the dough from the center outwards, walking around the table. Stretch until the dough is paper-thin and translucent (you should be able to read a newspaper through it). Aim for a rectangle approx 60x90cm.", "structured": {"action": "STRETCH", "temperature": null, "duration": null, "doneness_cues": {"visual": "Translucent enough to read text through", "tactile": null}}, "tips": ["Remove rings or jewelry to prevent tearing.", "If a small hole forms, pinch it back together immediately."]}, {"step_number": 8, "phase": "assemble", "text": "Brush the stretched dough liberally with about half of the melted assembly butter. Sprinkle the toasted breadcrumbs over the dough, leaving a 5cm border around the edges. The crumbs act as a barrier to keep the pastry crisp.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "assemble", "text": "Drain raisins. Mix the sugar-cinnamon blend and raisins into the apples. Spread the apple filling over the breadcrumbs on one side (the short side) of the dough rectangle, occupying about 1/3 of the surface area.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "assemble", "text": "Trim thick dough edges if necessary. Fold the side flaps over the filling. Using the tablecloth, lift the filling side and roll the strudel over onto itself tightly, like a Swiss roll, finishing with the seam side down.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 11, "phase": "cook", "text": "Transfer carefully to a parchment-lined baking sheet (you may need to curve it into a horseshoe shape to fit). Brush the entire surface with the remaining melted butter. Bake for 35-45 minutes until deep golden brown.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT40M", "doneness_cues": {"visual": "Deep golden brown crust", "tactile": "Hollow sound when tapped"}}, "tips": []}, {"step_number": 12, "phase": "finish", "text": "Remove from oven and let cool for at least 20 minutes to allow the filling to set. Dust generously with powdered sugar before slicing.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT1H", "passive_time": "PT1H", "total_time": "PT2H45M", "overnight_required": false, "yields": "1 large strudel (8-10 servings)", "yield_count": 8, "serving_size_g": 180}', '{"flags": ["Vegetarian", "Soy-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 454.75, "protein_g": 5.24, "carbohydrates_g": 67.32, "fat_g": 18.66, "saturated_fat_g": 9.06, "trans_fat_g": null, "monounsaturated_fat_g": 3.95, "polyunsaturated_fat_g": 0.9, "fiber_g": 5.14, "sugar_g": 26.2, "sodium_mg": 176.59, "cholesterol_mg": 34.94, "potassium_mg": 257.68, "calcium_mg": 43.35, "iron_mg": 1.27, "magnesium_mg": 20.62, "phosphorus_mg": 74.39, "zinc_mg": 0.46, "vitamin_a_mcg": 114.99, "vitamin_c_mg": 6.91, "vitamin_d_mcg": null, "vitamin_e_mg": 0.65, "vitamin_k_mcg": 4.84, "vitamin_b6_mg": 0.09, "vitamin_b12_mcg": 0.06, "thiamin_mg": 0.17, "riboflavin_mg": 0.11, "niacin_mg": 1.27, "folate_mcg": 23.7, "water_g": 129.55, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Texture suffers significantly; pastry will lose crispness.", "duration": "P2D"}, "freezer": {"notes": "Freeze unbaked for best results. If baked, reheating will not restore original texture perfectly.", "duration": "P1M"}, "reheating": "Reheat in a 180\u00b0C/350\u00b0F oven for 10-15 minutes to recrisp.", "does_not_keep": false}', '[{"name": "Large clean tablecloth or cotton sheet", "required": true, "alternative": "Very large silicone mat (less effective)"}, {"name": "Stand mixer with dough hook", "required": false, "alternative": "Large bowl and hand kneading"}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Rolling pin", "required": true, "alternative": null}, {"name": "Pastry brush", "required": true, "alternative": null}, {"name": "Skillet", "required": true, "alternative": null}, {"name": "Peeler", "required": true, "alternative": null}]', '[{"symptom": "Dough keeps tearing while stretching", "likely_cause": "Gluten was not developed enough or dough is too cold/dry", "prevention": "Knead longer and ensure the dough rests in a warm spot for the full time", "fix": "Patch holes by pinching; if unworkable, re-ball, rest 30 mins, and try again"}, {"symptom": "Strudel is soggy at the bottom", "likely_cause": "Apples released too much juice or insufficient breadcrumbs", "prevention": "Do not sugar apples until the very last second; use tart apples with lower water content", "fix": "Serve with vanilla sauce to mask texture"}]', '["The ''newspaper test'' is the gold standard for strudel dough. If you can''t read a headline through the dough, it is too thick.", "Acid is essential in the dough (vinegar) to relax the gluten proteins, making the extreme stretching possible.", "Do not mix the sugar with the apples until just before assembly. Sugar is hygroscopic and will draw water out of the apples immediately, leading to a soggy pastry.", "If you are intimidated by homemade dough, phyllo pastry is a functional but noticeably different substitute. The homemade version is thicker but more elastic.", "Serve warm, ideally with ''Kanarimilch'' (warm vanilla custard sauce) or a dollop of unsweetened whipped cream."]', '"Apfelstrudel gained popularity in the 18th century during the Habsburg Empire. While iconic to Vienna, the technique of paper-thin dough actually traces its roots to the Turkish baklava, brought to Austria via Hungary during Ottoman interactions."', 454.75);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ebf6842c-dc80-47dc-9633-a1a234a78adb', 'Halibut Steaks with Red Wine, Olive, and Caper Sauce', 'Tender, flaky halibut steaks pan-seared to golden perfection, served with a bold Mediterranean pan sauce featuring dry red wine, briny Kalamata olives, and tangy capers, finished with butter for a velvety texture.', 'dinner', 'Mediterranean', 'Easy', '["caper", "halibut", "olive", "dinner", "easy", "seafood", "mediterranean", "gluten-free", "date night"]', '[{"group_name": "Halibut", "items": [{"name": "halibut steaks", "quantity": 4, "unit": null, "preparation": "skin-on or skinless", "notes": "approx. 170g each", "substitutions": [], "ingredient_id": "827bb16e-2155-49d8-a5df-0c0620559d27", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "generous pinch per side", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly ground", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "divided use", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Red Wine Olive Sauce", "items": [{"name": "dry red wine", "quantity": 120, "unit": "ml", "preparation": null, "notes": "Pinot Noir or Merlot work best", "substitutions": [], "ingredient_id": "0fc93141-8ba8-42e0-ac8b-b5af3851554c", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "finely minced", "notes": "approx. 30g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx. 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "kalamata olives", "quantity": 60, "unit": "g", "preparation": "pitted and roughly chopped", "notes": null, "substitutions": [], "ingredient_id": "b333e168-fd6b-420c-87b8-2cbd76476220", "nutrition_source": "Aggregated Public Data"}, {"name": "capers", "quantity": 30, "unit": "g", "preparation": "drained", "notes": null, "substitutions": [], "ingredient_id": "e7301d2c-b906-4ef8-917e-787be0b25880", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 45, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 10, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the halibut steaks very dry with paper towels. This ensures a good sear rather than steaming. Season liberally with salt and black pepper on both sides.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Removing surface moisture is the single most important step for preventing fish from sticking."]}, {"step_number": 2, "phase": "cook", "text": "Heat 20ml of olive oil in a large skillet over medium-high heat until the oil shimmers but does not smoke. Carefully place the fish in the pan.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Sear the fish undisturbed for 3-4 minutes until a golden crust forms and the fish releases easily from the pan. Flip and cook for another 2-3 minutes until the internal temperature reaches 55\u00b0C-60\u00b0C (130\u00b0F-140\u00b0F) for medium doneness, or up to 63\u00b0C (145\u00b0F) for full safety.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT7M", "doneness_cues": {"visual": "Golden brown crust, opaque flesh", "tactile": "Firm but yielding to light pressure"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Transfer the fish to a warm plate and set aside. In the same pan, reduce heat to medium and add the remaining 10ml olive oil and minced shallot. Saut\u00e9 for 1 minute until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the minced garlic and cook for another 30 seconds, being careful not to burn it.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Deglaze the pan with the red wine, scraping up any browned bits (fond) from the bottom. Simmer briskly until the liquid reduces by about half.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Reduce heat to low. Stir in the olives and capers. Add the cold cubed butter one piece at a time, whisking constantly until the sauce is glossy and emulsified.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["This technique is called ''monter au beurre''. Do not let the sauce boil after adding butter, or it will break and become oily."]}, {"step_number": 8, "phase": "assemble", "text": "Stir in the fresh parsley, taste and adjust seasoning if needed (capers and olives are salty, so you may not need extra salt). Spoon the sauce generously over the rested halibut steaks and serve immediately.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT0M", "total_time": "PT25M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 220}', '{"flags": ["Pescatarian", "Gluten-Free", "Low-Carb", "Keto"], "not_suitable_for": ["Dairy-Free (unless butter is omitted)"]}', '{"per_serving": {"calories": 426.15, "protein_g": 35.78, "carbohydrates_g": 9.05, "fat_g": 25.98, "saturated_fat_g": 8.52, "trans_fat_g": null, "monounsaturated_fat_g": 10.17, "polyunsaturated_fat_g": 2.72, "fiber_g": 0.94, "sugar_g": 0.68, "sodium_mg": 1086.91, "cholesterol_mg": 146.59, "potassium_mg": 834.42, "calcium_mg": 56.82, "iron_mg": 1.05, "magnesium_mg": 52.08, "phosphorus_mg": 429.61, "zinc_mg": 1.18, "vitamin_a_mcg": 168.17, "vitamin_c_mg": 5.03, "vitamin_d_mcg": null, "vitamin_e_mg": 4.67, "vitamin_k_mcg": 49.89, "vitamin_b6_mg": 0.73, "vitamin_b12_mcg": 3.05, "thiamin_mg": 0.14, "riboflavin_mg": 0.14, "niacin_mg": 9.93, "folate_mcg": 34.16, "water_g": 169.03, "alcohol_g": 2.79, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store fish and sauce in separate airtight containers if possible. Reheat gently to avoid overcooking fish.", "duration": "P2D"}, "freezer": {"notes": "Not recommended; delicate fish texture degrades and butter sauce may break upon thawing.", "duration": null}, "reheating": "Gently warm in a skillet over low heat with a splash of water, or steam briefly.", "does_not_keep": false}', '[{"name": "Large heavy-bottomed skillet", "required": true, "alternative": "Non-stick frying pan"}, {"name": "Fish spatula", "required": true, "alternative": "Wide flat spatula"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Fish stuck to the pan", "likely_cause": "Pan wasn''t hot enough or fish wasn''t dry enough before searing", "prevention": "Ensure oil is shimmering hot and fish is patted bone-dry before cooking", "fix": "Don''t force it; remove pan from heat for 1 minute to let moisture release the bond, then gently pry up"}, {"symptom": "Sauce looks oily or separated", "likely_cause": "Sauce got too hot after adding butter", "prevention": "Remove pan from heat or keep on very low flame while whisking in butter", "fix": "Whisk in a teaspoon of cold water vigorously to re-emulsify"}]', '["Halibut is a lean fish that can dry out quickly. It is better to slightly undercook it in the pan and let the residual heat finish it while you make the sauce.", "Using cold butter is crucial for the sauce; as it melts slowly, the milk solids help bind the fat and wine into a creamy emulsion.", "If red wine feels too heavy for you, a dry white wine or ros\u00e9 works equally well with this flavor profile, though red provides a classic ''meaty'' contrast to the white fish.", "Serve this with roasted potatoes or a simple arugula salad to cut through the richness of the sauce."]', '"This dish draws heavily from Provencal and Mediterranean traditions, where bold briny ingredients like capers and olives are used to season mild white fish. While white wine is the standard pairing for fish, the use of red wine in the sauce (a technique often seen in dishes like ''Matelote'') adds a depth and earthiness that stands up to the meaty texture of halibut steaks."', 426.15);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ecec9993-324e-443f-863b-95fed447e68d', 'Roasted Eggplant and Rosemary Hummus', 'A smoky, velvety fusion of classic hummus and baba ganoush. The roasted aubergine adds a silky lightness to the chickpeas, while fresh rosemary provides a piney, aromatic depth that cuts through the rich tahini.', 'side dish', 'Middle Eastern Fusion', 'Easy', '["aubergine", "hummus", "chickpeas", "garlic", "rosemary", "side dish", "dip", "vegan", "mediterranean"]', '[{"group_name": "Roasted Vegetables", "items": [{"name": "eggplant", "quantity": 1, "unit": null, "preparation": "medium size", "notes": "approximately 350-400g", "substitutions": [], "ingredient_id": "77c14307-dacf-4ab2-85d1-3594bff0ec99", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "whole, unpeeled", "notes": "about 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh rosemary", "quantity": 2, "unit": null, "preparation": "sprigs", "notes": "about 4g", "substitutions": [], "ingredient_id": "fa90a3a7-86cd-40de-8f8c-0464231925c2", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": "for roasting", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Hummus Base", "items": [{"name": "cooked chickpeas", "quantity": 240, "unit": "g", "preparation": "rinsed and drained", "notes": "1 standard 400g can", "substitutions": [], "ingredient_id": "9e76f37b-da5c-4dc8-8e18-6b9b92ef6094", "nutrition_source": "USDA FoodData Central"}, {"name": "tahini paste", "quantity": 60, "unit": "g", "preparation": "well-stirred", "notes": null, "substitutions": [], "ingredient_id": "87ae6455-8e22-4c1b-bad7-89fa69c4dc57", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 30, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 30, "unit": "ml", "preparation": "plus extra for garnish", "notes": null, "substitutions": [], "ingredient_id": "036c7254-3de5-4c6e-a2e7-366ad4d05077", "nutrition_source": "Aggregated Public Data"}, {"name": "ground cumin", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1/2 tsp", "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "ice water", "quantity": 30, "unit": "ml", "preparation": null, "notes": "adjust for consistency", "substitutions": [], "ingredient_id": "e133c9f2-8e34-45d1-9b59-996ab4a59d8a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 200\u00b0C (400\u00b0F). Line a baking sheet with parchment paper for easy cleanup.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Slice the eggplant in half lengthwise. Score the flesh in a diamond pattern without piercing the skin. Place cut-side up on the baking sheet along with the unpeeled garlic cloves and rosemary sprigs.", "structured": {"action": "SCORE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Brush the eggplant generously with 15ml olive oil and season with a pinch of salt. Roast in the oven for 40-45 minutes, or until the eggplant collapses and is very tender.", "structured": {"action": "ROAST", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT45M", "doneness_cues": {"visual": "Eggplant is collapsed and browned", "tactile": "Flesh is extremely soft when poked"}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Remove from the oven. Discard the rosemary sprigs (they have infused the oil/eggplant). Let the vegetables cool for 10 minutes until safe to handle.", "structured": {"action": "COOL", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Scoop the roasted eggplant flesh out of the skins with a spoon. Squeeze the roasted garlic out of its paper husks. Discard skins and husks.", "structured": {"action": "PEEL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "In a food processor, combine the chickpeas, tahini, lemon juice, roasted garlic, cumin, and salt. Process until broken down.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Add the roasted eggplant flesh and the 30ml of extra virgin olive oil. Process on high until smooth and creamy.", "structured": {"action": "PUREE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "With the motor running, slowly drizzle in ice water, one tablespoon at a time, until the hummus reaches your desired fluffiness and consistency. Taste and adjust salt or lemon if needed.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Ice water shocks the fat in the tahini, creating a lighter, whiter, and fluffier texture."]}, {"step_number": 9, "phase": "finish", "text": "Transfer to a serving bowl. Use the back of a spoon to create swoops on the surface. Drizzle with olive oil and garnish with a sprig of fresh rosemary before serving.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT45M", "total_time": "PT1H5M", "overnight_required": false, "yields": "600g", "yield_count": 10, "serving_size_g": 60}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Low-Carb"], "not_suitable_for": []}', '{"per_serving": {"calories": 129.47, "protein_g": 3.94, "carbohydrates_g": 10.15, "fat_g": 8.65, "saturated_fat_g": 1.23, "trans_fat_g": null, "monounsaturated_fat_g": 1.27, "polyunsaturated_fat_g": 0.48, "fiber_g": 3.83, "sugar_g": 2.6, "sodium_mg": 140.53, "cholesterol_mg": null, "potassium_mg": 199.91, "calcium_mg": 74.7, "iron_mg": 1.66, "magnesium_mg": 39.35, "phosphorus_mg": 86.26, "zinc_mg": 0.76, "vitamin_a_mcg": 1.33, "vitamin_c_mg": 2.77, "vitamin_d_mcg": null, "vitamin_e_mg": 0.43, "vitamin_k_mcg": 3.21, "vitamin_b6_mg": 0.08, "vitamin_b12_mcg": null, "thiamin_mg": 0.05, "riboflavin_mg": 0.03, "niacin_mg": 0.4, "folate_mcg": 50.62, "water_g": 52.82, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container with a thin layer of olive oil on top to prevent oxidation.", "duration": "P5D"}, "freezer": {"notes": "Texture may become slightly grainy; stir vigorously upon thawing.", "duration": "P3M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Food processor", "required": true, "alternative": "High-powered blender"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Spoon", "required": true, "alternative": null}]', '[{"symptom": "Hummus is too watery", "likely_cause": "The roasted eggplant retained too much moisture", "prevention": "Let the scooped eggplant flesh sit in a strainer for 5 minutes before blending", "fix": "Add more tahini or a few more chickpeas to thicken the mixture"}, {"symptom": "Bitter taste", "likely_cause": "Burnt garlic or eggplant skin was blended in", "prevention": "Remove garlic if it browns too quickly during roasting; ensure no charred skin enters the blender", "fix": "Add a drizzle of maple syrup or more lemon juice to mask the bitterness"}]', '["For a smokier flavor profile, you can char the eggplant skin over an open gas flame for 5 minutes before finishing it in the oven.", "If your tahini is very thick or the oil has separated, whisk it with the lemon juice separately before adding to the processor to prevent seizing.", "Using warm chickpeas (either freshly boiled or microwaved briefly) helps create a smoother emulsion than cold chickpeas."]', '"This recipe sits at the intersection of two Levantine staples: Hummus (chickpea-based) and Baba Ganoush (eggplant-based, often called Moutabal when mixed with tahini). It combines the earthy substance of chickpeas with the smoky, savory depth of roasted aubergine."', 129.47);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ed0684cb-22ba-4dc3-b2c1-d91920c16d62', 'Rustic Chicken and Farro Stew with Swiss Chard', 'A soul-warming, hearty soup that marries the nutty chew of pearled farro with succulent chicken thighs and sweet, melted leeks. Bright Swiss chard and a splash of lemon cut through the richness, creating a perfectly balanced one-pot meal.', 'soup', 'American', 'Intermediate', '["american", "carrot", "chicken soup", "chicken thigh", "farro", "leek", "swiss chard", "dinner", "weeknight", "main course", "hearty"]', '[{"group_name": "Chicken & Aromatics", "items": [{"name": "boneless, skinless chicken thighs", "quantity": 600, "unit": "g", "preparation": "trimmed and cut into 2cm pieces", "notes": null, "substitutions": [], "ingredient_id": "d7fc1bf9-fc05-429b-bfa6-2ad857cb0bb6", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "leeks", "quantity": 2, "unit": null, "preparation": "white and light green parts only, sliced into half-moons and washed thoroughly", "notes": "approx 200g", "substitutions": [], "ingredient_id": "f0bddafa-51db-4e56-954b-18624daa6fa4", "nutrition_source": "USDA FoodData Central"}, {"name": "carrots", "quantity": 200, "unit": "g", "preparation": "diced small", "notes": null, "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Soup Base", "items": [{"name": "chicken stock", "quantity": 1500, "unit": "ml", "preparation": "low-sodium preferred", "notes": null, "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}, {"name": "pearled farro", "quantity": 200, "unit": "g", "preparation": null, "notes": "rinsed", "substitutions": [], "ingredient_id": "70e9b16f-d2bc-41f2-a36c-c346c9095808", "nutrition_source": "Aggregated Public Data"}, {"name": "dried thyme", "quantity": 1, "unit": "g", "preparation": null, "notes": "approx 1/2 tsp", "substitutions": [], "ingredient_id": "3b938244-d506-46b2-9027-21bed955bcc5", "nutrition_source": "USDA FoodData Central"}, {"name": "bay leaf", "quantity": 1, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eab2ef3a-7a0e-4188-b746-645b795ada1e", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, start with 5g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly ground, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Finish", "items": [{"name": "swiss chard", "quantity": 1, "unit": null, "preparation": "stems diced, leaves chopped roughly", "notes": "bunch, approx 250g total", "substitutions": [], "ingredient_id": "cb0f8ccb-3b9d-416c-995f-d0a7924af74c", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": "freshly squeezed, plus wedges for serving", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the vegetables: wash the leeks thoroughly to remove grit, dice the carrots, and separate the Swiss chard stems from the leaves. Dice the chard stems and roughly chop the leaves. Cut the chicken into bite-sized chunks.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat olive oil in a large Dutch oven over medium-high heat. Add the chicken pieces, season with a pinch of salt and pepper, and cook until golden brown on the outside, about 5-7 minutes. Remove chicken to a plate (it does not need to be cooked through yet).", "structured": {"action": "SEAR", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT7M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to medium. Add the leeks, carrots, and diced chard stems to the pot. Saut\u00e9 until the vegetables are softened and aromatic, about 6-8 minutes. Stir in the minced garlic and thyme, cooking for another minute until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT9M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour in the chicken stock and scrape the bottom of the pot to release any flavorful browned bits. Add the rinsed farro, bay leaf, and the seared chicken along with any accumulated juices. Bring to a boil, then reduce heat to a simmer.", "structured": {"action": "DEGLAZE", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Cover the pot partially and simmer gently until the farro is tender but still chewy (al dente) and the chicken is cooked through (internal temp 74\u00b0C/165\u00b0F), approximately 25-30 minutes.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT30M", "doneness_cues": {"visual": "Chicken is opaque throughout", "tactile": "Farro is tender with a slight bite"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Stir in the chopped Swiss chard leaves and cook for 2-3 minutes until wilted and vibrant green. Remove from heat.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Discard the bay leaf. Stir in the fresh lemon juice. Taste and adjust seasoning with additional salt and pepper if needed. Serve immediately.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT30M", "total_time": "PT1H5M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Celiac disease (contains wheat/farro)"]}', '{"per_serving": {"calories": 579.91, "protein_g": 46.64, "carbohydrates_g": 55.42, "fat_g": 22.42, "saturated_fat_g": 2.74, "trans_fat_g": 0.03, "monounsaturated_fat_g": 7.76, "polyunsaturated_fat_g": 2.31, "fiber_g": 9.05, "sugar_g": 7, "sodium_mg": 15806.8, "cholesterol_mg": 141, "potassium_mg": 1070.81, "calcium_mg": 108.85, "iron_mg": 5.84, "magnesium_mg": 106.53, "phosphorus_mg": 345.99, "zinc_mg": 2.84, "vitamin_a_mcg": 682.21, "vitamin_c_mg": 30.12, "vitamin_d_mcg": null, "vitamin_e_mg": 2.89, "vitamin_k_mcg": 538.97, "vitamin_b6_mg": 0.86, "vitamin_b12_mcg": 0.92, "thiamin_mg": 0.21, "riboflavin_mg": 0.39, "niacin_mg": 9.13, "folate_mcg": 25.84, "water_g": 222.1, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Farro will continue to absorb broth; add a splash of water when reheating.", "duration": "P4D"}, "freezer": {"notes": "Greens may soften slightly upon thawing.", "duration": "P3M"}, "reheating": "Simmer gently on stovetop until hot. Add water or stock if stew has thickened too much.", "does_not_keep": false}', '[{"name": "Dutch oven or large heavy-bottomed pot", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Wooden spoon", "required": true, "alternative": null}, {"name": "Fine-mesh sieve", "required": true, "alternative": "Colander (if holes are small enough)"}]', '[{"symptom": "Farro is still hard after 30 minutes", "likely_cause": "The farro used is semi-pearled or whole rather than pearled, or the simmer was too low", "prevention": "Check package instructions for farro type; soak whole farro overnight if using", "fix": "Add a splash more stock or water and continue simmering until tender"}, {"symptom": "Soup tastes flat", "likely_cause": "Insufficient salt or acidity to balance the starch", "prevention": "Season incrementally throughout the cooking process", "fix": "Add salt 1/4 teaspoon at a time and another squeeze of lemon juice"}]', '["Washing leeks is critical; grit often hides between the inner layers. Slice them first, then swish vigorously in a bowl of water before lifting them out to leave the dirt behind.", "If you want a clearer broth, cook the farro in a separate pot of water and add it at the end, though you will lose some starchiness that gives this stew its comforting body.", "The chard stems are delicious and provide a nice textural contrast to the soft leaves\u2014don''t throw them away! They cook at the same rate as carrots.", "For an extra layer of flavor, throw a parmesan rind into the pot during the simmer phase (remove before serving)."]', '"While farro is an ancient grain with roots in the Fertile Crescent and Roman diet, this preparation reflects the modern American approach to ''clean comfort food.'' It combines Old World grains with the familiar, homey profile of classic chicken soup, utilizing robust winter greens like chard that are staples in farm-to-table cooking."', 579.91);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ed3e95aa-67b5-4030-9f1f-9c12edf05a39', 'Classic Chinese-American Pork Egg Rolls', 'These egg rolls feature the iconic thick, bubbly, and crispy skin characteristic of Chinese-American takeout. The filling is a savory, juicy mixture of ground pork, crunchy cabbage, and chewy noodles, seasoned with ginger and sesame. Designed to be freezer-friendly for instant appetizers.', 'appetizer', 'Chinese American', 'Intermediate', '["finger foods", "carrot", "chinese american", "freezer friendly", "great leftovers", "green cabbage", "ground pork", "rice noodle", "sesame oil", "small plate", "appetizer"]', '[{"group_name": "Filling Base", "items": [{"name": "ground pork", "quantity": 450, "unit": "g", "preparation": "fatty blend preferred (80/20)", "notes": null, "substitutions": [], "ingredient_id": "95b412ba-c68f-4b61-ae87-42b44000956b", "nutrition_source": "USDA FoodData Central"}, {"name": "green cabbage", "quantity": 300, "unit": "g", "preparation": "finely shredded", "notes": null, "substitutions": [], "ingredient_id": "3665bd9f-fcae-44a3-a11d-16c4ca6e52bd", "nutrition_source": "Aggregated Public Data"}, {"name": "carrot", "quantity": 100, "unit": "g", "preparation": "julienned or grated", "notes": null, "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "dry vermicelli rice noodles", "quantity": 50, "unit": "g", "preparation": "dry weight", "notes": "can substitute bean thread (glass) noodles for more chew", "substitutions": [], "ingredient_id": "9f0e8ac0-732e-404a-ada2-c29791e7d269", "nutrition_source": "USDA FoodData Central"}, {"name": "scallions", "quantity": 3, "unit": null, "preparation": "chopped", "notes": "about 45g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Aromatics & Seasoning", "items": [{"name": "ginger", "quantity": 15, "unit": "g", "preparation": "fresh, minced", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "cloves, minced", "notes": "about 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "soy sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "oyster sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "322ccc47-a56e-40df-b324-59f7944393b8", "nutrition_source": "Aggregated Public Data"}, {"name": "sesame oil", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a9a59164-d949-4acd-99da-689f0a32e2e7", "nutrition_source": "Aggregated Public Data"}, {"name": "shaoxing wine", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["dry sherry"], "ingredient_id": "bb7adcb8-7e07-46ec-a3ac-e02f9ffb6f9f", "nutrition_source": "Aggregated Public Data"}, {"name": "sugar", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "white pepper", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wrappers & Frying", "items": [{"name": "egg roll wrappers", "quantity": 12, "unit": null, "preparation": null, "notes": "Square wheat-based wrappers, approx 400g total", "substitutions": [], "ingredient_id": "309430c5-0bb0-47f4-92c9-768f163f5799", "nutrition_source": "USDA FoodData Central"}, {"name": "cornstarch", "quantity": 10, "unit": "g", "preparation": null, "notes": "mixed with 30ml water for sealing", "substitutions": [], "ingredient_id": "e37d9484-8bf9-4d9a-a6c8-22a597cbb237", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 1000, "unit": "ml", "preparation": null, "notes": "for deep frying (vegetable, canola, or peanut)", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}]}]', '[{"step_number": 1, "phase": "prep", "text": "Soak the rice noodles in hot water for 10 minutes until pliable. Drain thoroughly and use kitchen shears to cut them into short 2-3cm lengths. Set aside.", "structured": {"action": "SOAK", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat a large wok or skillet over medium-high heat. Add the ground pork and stir-fry, breaking it up into small crumbles, until cooked through and fat has rendered.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": null, "doneness_cues": {"visual": "Pork is browned and no pink remains", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the minced ginger and garlic to the pork, cooking for 30 seconds until fragrant. Add the cabbage and carrots. Stir-fry for 2-3 minutes until vegetables are wilted but still retain crunch.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Reduce heat to medium. Add the noodles, scallions, soy sauce, oyster sauce, sesame oil, Shaoxing wine, sugar, and white pepper. Toss well to combine everything uniformly. Remove from heat.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Transfer the filling to a large baking sheet and spread it out. Prop up one end of the sheet slightly to allow excess liquid to drain away from the solids. Let cool completely to room temperature. This prevents soggy rolls.", "structured": {"action": "COOL", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Place an egg roll wrapper in a diamond shape. Place about 3 tablespoons (approx 70g) of filling in the center. Fold the bottom corner up over the filling, tucking it tightly. Fold the left and right corners in towards the center (like an envelope). Brush the top corner with the cornstarch slurry, then roll tightly upwards to seal.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Heat oil in a Dutch oven or heavy pot to 175\u00b0C/350\u00b0F. Fry egg rolls in batches of 3-4, ensuring they are not crowded. Cook for 3-5 minutes, turning occasionally, until golden brown and blistered.", "structured": {"action": "FRY", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT4M", "doneness_cues": {"visual": "Golden brown with bubbled surface", "tactile": "Shell is rigid"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove egg rolls and place on a wire rack to drain. Ensure internal temperature reaches 74\u00b0C/165\u00b0F. Serve warm.", "structured": {"action": "REST", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT30M", "total_time": "PT1H15M", "overnight_required": false, "yields": "12 egg rolls", "yield_count": 12, "serving_size_g": 85}', '{"flags": ["Dairy-Free", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 242.38, "protein_g": 10.53, "carbohydrates_g": 28.13, "fat_g": 9.4, "saturated_fat_g": 3.05, "trans_fat_g": null, "monounsaturated_fat_g": 3.62, "polyunsaturated_fat_g": 0.94, "fiber_g": 1.74, "sugar_g": 2.23, "sodium_mg": 711.34, "cholesterol_mg": 30, "potassium_mg": 232.99, "calcium_mg": 42.99, "iron_mg": 1.85, "magnesium_mg": 20.17, "phosphorus_mg": 116.34, "zinc_mg": 1.2, "vitamin_a_mcg": 74.79, "vitamin_c_mg": 11.1, "vitamin_d_mcg": null, "vitamin_e_mg": 0.09, "vitamin_k_mcg": 8.89, "vitamin_b6_mg": 0.19, "vitamin_b12_mcg": 0.27, "thiamin_mg": 0.46, "riboflavin_mg": 0.22, "niacin_mg": 3.56, "folate_mcg": 34.84, "water_g": 68.59, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in airtight container; reheating required for texture.", "duration": "P3D"}, "freezer": {"notes": "Freeze raw on a baking sheet, then bag. Fry directly from frozen (add 2-3 minutes to cook time).", "duration": "P3M"}, "reheating": "Reheat in oven or air fryer at 175\u00b0C/350\u00b0F for 10-15 minutes to restore crispiness. Do not microwave.", "does_not_keep": false}', '[{"name": "Wok or large skillet", "required": true, "alternative": null}, {"name": "Dutch oven or heavy pot", "required": true, "alternative": "Deep fryer"}, {"name": "Digital thermometer", "required": true, "alternative": null}, {"name": "Wire rack", "required": true, "alternative": "Paper towel-lined plate"}, {"name": "Sheet pan", "required": true, "alternative": null}]', '[{"symptom": "Egg rolls burst open during frying", "likely_cause": "Wrapper was wrapped too loosely or the filling was too wet/hot", "prevention": "Cool filling completely, drain excess liquid, and wrap tightly without air pockets", "fix": "Cannot fix burst rolls; ensure oil is clean before frying the next batch"}, {"symptom": "Wrapper is greasy and not crispy", "likely_cause": "Oil temperature was too low", "prevention": "Use a thermometer to maintain oil at 175\u00b0C/350\u00b0F between batches", "fix": "Increase heat and re-fry briefly (double fry) to drive out oil"}]', '["The secret to the ''chewy'' interior layer is the interaction between the hot filling and the inner wrapper dough; do not over-dry the filling, but ensure no standing liquid remains.", "For the classic bubbly skin, ensure you are using wheat-flour ''Egg Roll'' wrappers, not the thin rice-paper ''Spring Roll'' wrappers or translucent wrappers.", "If preparing for a party, you can par-fry these for 2 minutes until pale gold, drain, and then finish frying for 2 minutes right before serving.", "Serve with duck sauce, hot mustard, or a mixture of soy sauce and rice vinegar."]', '"While spring rolls exist across Asia, the thick-skinned ''Egg Roll'' is a distinct staple of Chinese-American cuisine, likely popularized in New York in the early 20th century. It is heavier and heartier than its delicate mainland Chinese counterparts, designed to be a substantial finger food."', 242.38);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('edacf129-6dec-4db1-bea5-c83adc2b648a', 'Cerveza-Braised Pork Carnitas', 'Succulent, fall-apart pork shoulder slow-braised in Mexican lager and bright citrus until tender. The meat is shredded and finished under the broiler to create caramelized, crispy edges while maintaining a juicy interior—the ultimate texture for street-style tacos.', 'dinner', 'Mexican', 'Intermediate', '["tacos", "pork", "braised", "mexican", "slowcookerfriendly", "crowd_pleaser"]', '[{"group_name": "Pork", "items": [{"name": "boneless pork shoulder", "quantity": 2000, "unit": "g", "preparation": "cut into 5cm chunks", "notes": "Boston butt cut preferred for fat content", "substitutions": [], "ingredient_id": "2435c811-13bb-4d94-b94c-ac0381ef4b0f", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable oil", "quantity": 30, "unit": "ml", "preparation": "liquid", "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Spice Blend", "items": [{"name": "kosher salt", "quantity": 20, "unit": "g", "preparation": null, "notes": "adjust to taste if using table salt", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cumin", "quantity": 10, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "dried oregano", "quantity": 5, "unit": "g", "preparation": null, "notes": "Mexican oregano preferred", "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "chili powder", "quantity": 10, "unit": "g", "preparation": null, "notes": "mild blend, usually ancho based", "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 5, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Braising Liquid & Aromatics", "items": [{"name": "mexican lager beer", "quantity": 355, "unit": "ml", "preparation": null, "notes": "Modelo Especial or similar; room temperature", "substitutions": [], "ingredient_id": "3c4b4d80-5ee5-4488-b81b-fdc88c3e8227", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh orange juice", "quantity": 120, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a15da11d-f8dd-46e3-9ac5-725a7912f1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "white onion", "quantity": 1, "unit": null, "preparation": "roughly chopped", "notes": "approx 200g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 6, "unit": null, "preparation": "crushed", "notes": "approx 30g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "bay leaves", "quantity": 2, "unit": null, "preparation": null, "notes": "dried", "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 150\u00b0C (300\u00b0F). Combine the salt, cumin, oregano, chili powder, and black pepper in a small bowl. Pat the pork chunks dry and massage the spice blend thoroughly into the meat.", "structured": {"action": "SEASON", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat the vegetable oil in a large Dutch oven over medium-high heat. Sear the pork chunks in batches to avoid overcrowding, turning them until browned on all sides. Remove browned pork and set aside.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": {"visual": "Deep golden brown crust", "tactile": null}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the chopped onion and crushed garlic to the pot. Saut\u00e9 for 2-3 minutes until fragrant and slightly softened, scraping up the browned bits (fond) from the bottom of the pot.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour in the beer and orange juice. Return the pork and any accumulated juices to the pot. Add the bay leaves. Bring the liquid to a gentle simmer.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Cover the Dutch oven with a heavy lid and transfer to the preheated oven. Braise for 3 to 3.5 hours, or until the pork is extremely tender and shreds easily with a fork. Internal temperature should exceed 90\u00b0C (195\u00b0F).", "structured": {"action": "BRAISE", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": "PT3H30M", "doneness_cues": {"visual": null, "tactile": "Meat offers zero resistance to a fork"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove the pot from the oven. Discard the bay leaves. Transfer the pork to a large baking sheet using a slotted spoon. Shred the meat into bite-sized pieces using two forks. Ladle about 100ml of the braising liquid over the shredded meat.", "structured": {"action": "SHRED", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Place the baking sheet under a broiler (grill) set to high for 5-8 minutes. Watch closely to prevent burning; you want the edges to become crisp and caramelized while the interior stays moist.", "structured": {"action": "BROIL", "temperature": null, "duration": null, "doneness_cues": {"visual": "Charred tips and crispy edges", "tactile": null}}, "tips": ["This step is crucial for authentic carnitas texture."]}]', '{"active_time": "PT45M", "passive_time": "PT3H30M", "total_time": "PT4H15M", "overnight_required": false, "yields": "8 servings", "yield_count": 8, "serving_size_g": 220}', '{"flags": ["Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Gluten-Free diets (unless GF beer is used)"]}', '{"per_serving": {"calories": 819.79, "protein_g": 68.6, "carbohydrates_g": 16.63, "fat_g": 73.07, "saturated_fat_g": 4.37, "trans_fat_g": null, "monounsaturated_fat_g": 4.72, "polyunsaturated_fat_g": 1.1, "fiber_g": 1.95, "sugar_g": 2.51, "sodium_mg": 1653.62, "cholesterol_mg": 27.51, "potassium_mg": 1763.61, "calcium_mg": 56.38, "iron_mg": 5.69, "magnesium_mg": 22.89, "phosphorus_mg": 1034.98, "zinc_mg": 14.72, "vitamin_a_mcg": 23.22, "vitamin_c_mg": 10.97, "vitamin_d_mcg": null, "vitamin_e_mg": 0.65, "vitamin_k_mcg": 7.19, "vitamin_b6_mg": 0.22, "vitamin_b12_mcg": 0.52, "thiamin_mg": 0.16, "riboflavin_mg": 0.11, "niacin_mg": 1.68, "folate_mcg": 13.64, "water_g": 63.26, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container with some of the braising liquid to keep moist.", "duration": "P4D"}, "freezer": {"notes": "Freeze flat in vacuum-sealed bags for best results.", "duration": "P3M"}, "reheating": "Pan-fry with a splash of water or reserved fat until crispy and hot.", "does_not_keep": false}', '[{"name": "Dutch Oven (5-6L)", "required": true, "alternative": "Heavy-bottomed pot and transfer to roasting pan"}, {"name": "Chef''s Knife", "required": true, "alternative": null}, {"name": "Cutting Board", "required": true, "alternative": null}, {"name": "Baking Sheet", "required": true, "alternative": "Cast iron skillet"}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Meat is tough and not shredding", "likely_cause": "The connective tissue hasn''t had enough time to break down", "prevention": "Ensure the oven temperature is low and consistent; do not rush the cooking time", "fix": "Return to the oven covered, add a splash more liquid if dry, and cook for another 30-45 minutes"}]', '["Do not trim all the fat off the pork shoulder before cooking; the fat renders out and keeps the meat moist during the long braise.", "For the beer, choose a Mexican lager or pilsner for a lighter taste, or a Negra Modelo for a deeper, maltier flavor. Avoid IPAs as they become bitter when reduced.", "The remaining braising liquid is liquid gold. Strain it and keep it to pour over leftovers or use as a base for a soup.", "Authentic Carnitas are often cooked in lard (confit style), but this braise-then-broil method replicates that texture with less mess for home cooks."]', '"Carnitas, meaning ''little meats'', originate from the state of Michoac\u00e1n, Mexico. Traditionally cooked in copper cauldrons with lard, this dish is a staple of Mexican street food, celebrated for the interplay between the juicy interior and the crispy, caramelized exterior."', 819.79);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('edbfed79-9443-4dcd-9bac-c5c0b0232b6d', 'Braised Chicken with Caramelized Fennel and Pernod', 'Succulent bone-in chicken thighs braised in a rich, anise-scented reduction of caramelized fennel and onions. The dish is finished with a vibrant, herbaceous fennel frond pistou that cuts through the deep savory notes, offering a modern French bistro experience suitable for a weeknight.', 'dinner', 'French', 'Intermediate', '["chicken", "fennel", "dinner", "weeknight", "main course", "gluten-free", "french", "one-pot"]', '[{"group_name": "Chicken & Aromatics", "items": [{"name": "chicken thighs", "quantity": 4, "unit": null, "preparation": "bone-in, skin-on", "notes": "approx. 800g total", "substitutions": [], "ingredient_id": "d7fc1bf9-fc05-429b-bfa6-2ad857cb0bb6", "nutrition_source": "Aggregated Public Data"}, {"name": "fennel bulbs", "quantity": 2, "unit": null, "preparation": "large, cored and sliced 1cm thick", "notes": "reserve fronds for pur\u00e9e (approx 600g trimmed)", "substitutions": [], "ingredient_id": "a42d03de-0a8a-4a75-8299-5cf01d43b425", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "julienned", "notes": "approx. 200g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": null, "notes": "smashed", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "for searing if skin is lean", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Braising Liquid", "items": [{"name": "pernod", "quantity": 60, "unit": "ml", "preparation": null, "notes": "anise liqueur", "substitutions": ["Pastis", "Ouzo", "Dry white wine + 1 tsp fennel seeds"], "ingredient_id": "56ad2185-85bf-464c-a924-a710377e97d3", "nutrition_source": "Aggregated Public Data"}, {"name": "chicken stock", "quantity": 250, "unit": "ml", "preparation": "high quality, low sodium", "notes": null, "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}, {"name": "kosher salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly ground", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Fennel Frond Pur\u00e9e", "items": [{"name": "reserved fennel fronds", "quantity": 30, "unit": "g", "preparation": "rough chopped", "notes": null, "substitutions": [], "ingredient_id": "a42d03de-0a8a-4a75-8299-5cf01d43b425", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": null, "notes": "flat-leaf", "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 45, "unit": "ml", "preparation": "extra virgin", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "small", "notes": null, "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat chicken thighs completely dry with paper towels and season generously with salt and pepper on both sides. Separate fennel fronds from bulbs; set fronds aside for the pur\u00e9e. Slice bulbs and onions.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Dry skin ensures a crispy sear rather than steaming."]}, {"step_number": 2, "phase": "cook", "text": "In a large Dutch oven over medium-high heat (190\u00b0C/375\u00b0F), add a splash of olive oil. Place chicken skin-side down. Sear undisturbed for 6-8 minutes until deep golden brown. Flip and sear the other side for 2 minutes. Remove chicken and set aside.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Reduce heat to medium (160\u00b0C/320\u00b0F). Add the sliced fennel bulb and onion to the rendered chicken fat. Saut\u00e9 for 8-10 minutes, stirring occasionally, until softened and caramelized around the edges.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT10M", "doneness_cues": {"visual": "Golden brown edges on onions", "tactile": "Softened vegetables"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the smashed garlic and cook for 1 minute until fragrant. Deglaze the pan with Pernod, scraping up any browned bits (fond) from the bottom. Allow the alcohol to reduce by half, about 2 minutes.", "structured": {"action": "DEGLAZE", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pour in the chicken stock and bring to a simmer. Return the chicken thighs to the pan, skin-side up, nestling them into the vegetables but keeping the skin above the liquid line. Cover and simmer on low for 25-30 minutes, or until chicken internal temperature reaches 74\u00b0C/165\u00b0F.", "structured": {"action": "BRAISE", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT30M", "doneness_cues": {"visual": "Internal temp 74C", "tactile": "Chicken tender"}}, "tips": []}, {"step_number": 6, "phase": "prep", "text": "While chicken braises, prepare the pur\u00e9e. Combine reserved fennel fronds, parsley, lemon juice, small garlic clove, and extra virgin olive oil in a blender. Pulse until smooth. Season with a pinch of salt.", "structured": {"action": "BLEND", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove the lid from the pot. If the sauce is too thin, remove chicken and boil liquid for 3-5 minutes to thicken. Return chicken. Plate the chicken and vegetables, drizzling the bright green fennel frond pur\u00e9e over the top just before serving.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT30M", "total_time": "PT1H05M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Gluten-Free", "Dairy-Free", "Nut-Free", "Paleo"], "not_suitable_for": []}', '{"per_serving": {"calories": 507.99, "protein_g": 43.56, "carbohydrates_g": 22.72, "fat_g": 24.92, "saturated_fat_g": 4.45, "trans_fat_g": 0.04, "monounsaturated_fat_g": 14.08, "polyunsaturated_fat_g": 3.75, "fiber_g": 6.01, "sugar_g": 12.43, "sodium_mg": 2971.22, "cholesterol_mg": 188, "potassium_mg": 1253.24, "calcium_mg": 116.69, "iron_mg": 3.29, "magnesium_mg": 81.31, "phosphorus_mg": 472.24, "zinc_mg": 3.65, "vitamin_a_mcg": 105.46, "vitamin_c_mg": 30.29, "vitamin_d_mcg": null, "vitamin_e_mg": 3.48, "vitamin_k_mcg": 175.92, "vitamin_b6_mg": 1.1, "vitamin_b12_mcg": 1.22, "thiamin_mg": 0.23, "riboflavin_mg": 0.47, "niacin_mg": 12.27, "folate_mcg": 66.64, "water_g": 348.14, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. The flavors often deepen overnight.", "duration": "P3D"}, "freezer": {"notes": "Texture of fennel may soften slightly upon thawing.", "duration": "P2M"}, "reheating": "Reheat gently on the stove over low heat to prevent the chicken from drying out.", "does_not_keep": false}', '[{"name": "Large Dutch Oven or Braiser", "required": true, "alternative": "Deep saut\u00e9 pan with heavy lid"}, {"name": "Blender or Food Processor", "required": true, "alternative": "Immersion blender"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Chef''s Knife", "required": true, "alternative": null}]', '[{"symptom": "Chicken skin is flabby/soft", "likely_cause": "The pot was covered during the entire braise, trapping steam against the skin", "prevention": "Ensure skin remains above the liquid line; optional finish under broiler for 2 mins", "fix": "Place under a hot broiler for 2-3 minutes to re-crisp (watch carefully to avoid burning)"}, {"symptom": "Sauce tastes bitter", "likely_cause": "Fennel or garlic was burned during the saut\u00e9 phase", "prevention": "Control heat during caramelization and stir frequently", "fix": "Add a teaspoon of honey or maple syrup to counteract bitterness"}]', '["Pernod adds a distinctive anise profile, but the alcohol evaporates leaving a sweet, aromatic depth. If avoiding alcohol completely, increase the stock volume and add 1 teaspoon of crushed fennel seeds.", "Do not discard the fennel stalks when trimming; they can be tough, but are excellent for making stock later. Use only the bulb for the braise and fronds for the pur\u00e9e.", "For the brightest green pur\u00e9e, you can quickly blanch the fronds and parsley in boiling water for 10 seconds then shock in ice water before blending, though this is optional for a weeknight meal.", "This dish pairs exceptionally well with roasted potatoes or a simple arugula salad to catch the extra sauce."]', '"This recipe draws from the Proven\u00e7al tradition of combining poultry with anise flavors, common in the South of France. The use of Pernod (a successor to absinthe) pays homage to French ap\u00e9ritif culture, utilizing its botanical complexity to transform a simple braise into something aromatic and sophisticated."', 507.99);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ee3adfde-b88a-4b2f-b589-0bb39f54adac', 'Pomegranate Molasses Glazed Turkey with Brown Butter Gravy', 'A stunning holiday centerpiece featuring a deep, mahogany lacquer created by reducing pomegranate juice, honey, and soy sauce. The bird undergoes a dual-temperature roast for crispy skin and juicy meat, finished with a rich, nutty brown butter gravy that perfectly balances the tart glaze.', 'main course', 'Modern American', 'Advanced', '["poultry", "project", "brown butter", "honey", "pomegranate juice", "thanksgiving", "dinner", "glazed", "festive"]', '[{"group_name": "Pomegranate Glaze", "items": [{"name": "pomegranate juice", "quantity": 1000, "unit": "ml", "preparation": "unsweetened", "notes": "100% juice required for proper reduction", "substitutions": [], "ingredient_id": "9fbf5b84-64fe-449a-aa4e-5ed59a0cfd69", "nutrition_source": "Aggregated Public Data"}, {"name": "honey", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "soy sauce", "quantity": 60, "unit": "ml", "preparation": null, "notes": "provides umami depth and salt", "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh thyme", "quantity": 6, "unit": null, "preparation": "sprigs", "notes": "approx 5g", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "black peppercorns", "quantity": 5, "unit": "g", "preparation": "whole", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "The Turkey", "items": [{"name": "whole turkey", "quantity": 6000, "unit": "g", "preparation": "thawed, giblets removed", "notes": "approx 12-14 lbs", "substitutions": [], "ingredient_id": "dfd7145e-0407-4328-882b-c8c30b7f02e2", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 85, "unit": "g", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 20, "unit": "g", "preparation": null, "notes": "adjust if turkey is pre-brined", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "onion", "quantity": 1, "unit": null, "preparation": "quartered", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "apple", "quantity": 1, "unit": null, "preparation": "quartered", "notes": "approx 150g", "substitutions": [], "ingredient_id": "9985672b-aa9f-4125-8a32-62d520c99d6f", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic head", "quantity": 1, "unit": null, "preparation": "halved horizontally", "notes": "approx 50g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Brown Butter Gravy", "items": [{"name": "unsalted butter", "quantity": 115, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "all-purpose flour", "quantity": 60, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "turkey stock", "quantity": 1000, "unit": "ml", "preparation": "warm", "notes": null, "substitutions": [], "ingredient_id": "36823f14-40af-490c-8da7-6203be8a6697", "nutrition_source": "Aggregated Public Data"}, {"name": "pan drippings", "quantity": null, "unit": null, "preparation": "fat skimmed", "notes": "use all available liquid from roasting pan", "substitutions": [], "ingredient_id": "a2e03009-9d5b-4d65-a5ac-5b3085a5d19f", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a medium saucepan, combine pomegranate juice, honey, soy sauce, thyme sprigs, and peppercorns. Bring to a boil, then reduce heat and simmer until reduced to approximately 250ml (1 cup). It should have a syrup-like consistency that coats the back of a spoon. Strain and set aside to cool slightly.", "structured": {"action": "REDUCE", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT45M", "doneness_cues": {"visual": "Reduced by 75%, syrupy consistency", "tactile": "Coats back of spoon"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Preheat oven to 220\u00b0C/425\u00b0F. Pat the turkey very dry with paper towels inside and out. Season the cavity generously with salt, then stuff with onion, apple, garlic, and extra thyme. Rub the room temperature butter under the breast skin and over the entire exterior. Season exterior with remaining salt.", "structured": {"action": "SEASON", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": ["Tuck the wings under the body to prevent burning.", "Tie the legs together with kitchen twine for even cooking."]}, {"step_number": 3, "phase": "cook", "text": "Place turkey on a rack in a roasting pan. Roast at 220\u00b0C/425\u00b0F for 20-25 minutes to bronz the skin and start fat rendering.", "structured": {"action": "ROAST", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": "PT25M", "doneness_cues": {"visual": "Skin is golden brown", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Lower the oven temperature to 165\u00b0C/325\u00b0F. Continue roasting. Rotate the pan halfway through this phase to ensure even coloring.", "structured": {"action": "ROAST", "temperature": {"celsius": 165, "fahrenheit": 329}, "duration": "PT2H", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "When the turkey has about 45 minutes left (internal temp reaches roughly 55\u00b0C/130\u00b0F), begin brushing the pomegranate glaze over the bird every 15 minutes. Watch closely; if the sugar darkens too quickly, tent loosely with foil.", "structured": {"action": "GLAZE", "temperature": {"celsius": 165, "fahrenheit": 329}, "duration": "PT45M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove turkey when a thermometer inserted into the thickest part of the thigh registers 74\u00b0C/165\u00b0F. Transfer to a carving board and rest for at least 30 minutes before carving to allow juices to redistribute.", "structured": {"action": "REST", "temperature": null, "duration": "PT30M", "doneness_cues": {"visual": "Internal temp 74\u00b0C/165\u00b0F", "tactile": null}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "While turkey rests, make the gravy. Melt butter in a saucepan over medium heat. Continue cooking, swirling constantly, until the milk solids turn golden brown and smell nutty (beurre noisette). Immediately whisk in flour and cook for 1 minute.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": null, "doneness_cues": {"visual": "Golden brown specs", "tactile": "Nutty aroma"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Pour the degreased pan drippings and warm turkey stock into the brown butter roux, whisking constantly to prevent lumps. Simmer for 5-10 minutes until thickened. Whisk in 1-2 tablespoons of leftover glaze if available for extra tang.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT1H15M", "passive_time": "PT3H30M", "total_time": "PT4H45M", "overnight_required": false, "yields": "1 whole turkey (serves 10-12)", "yield_count": 12, "serving_size_g": 250}', '{"flags": ["Nut-Free", "Peanut-Free"], "not_suitable_for": ["Infants under 12 months (honey)"]}', '{"per_serving": {"calories": 1172.49, "protein_g": 71.32, "carbohydrates_g": 34.88, "fat_g": 80.3, "saturated_fat_g": 29.93, "trans_fat_g": null, "monounsaturated_fat_g": 26.76, "polyunsaturated_fat_g": 8.85, "fiber_g": 1.78, "sugar_g": 35.51, "sodium_mg": 2571.25, "cholesterol_mg": 4700.83, "potassium_mg": 2147.4, "calcium_mg": 765.6, "iron_mg": 26.18, "magnesium_mg": 83.5, "phosphorus_mg": 914.04, "zinc_mg": 8.48, "vitamin_a_mcg": 945.48, "vitamin_c_mg": 15.2, "vitamin_d_mcg": null, "vitamin_e_mg": 0.42, "vitamin_k_mcg": 2.26, "vitamin_b6_mg": 0.73, "vitamin_b12_mcg": 8.48, "thiamin_mg": 0.58, "riboflavin_mg": 2.38, "niacin_mg": 0.25, "folate_mcg": 360.18, "water_g": 392.54, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store meat off the bone in airtight containers.", "duration": "P4D"}, "freezer": {"notes": "Freeze gravy and meat separately.", "duration": "P3M"}, "reheating": "Reheat sliced turkey gently with a splash of stock covered in foil at 150\u00b0C/300\u00b0F.", "does_not_keep": false}', '[{"name": "Large roasting pan with rack", "required": true, "alternative": null}, {"name": "Saucepan (medium)", "required": true, "alternative": null}, {"name": "Saucepan (small)", "required": true, "alternative": null}, {"name": "Instant-read thermometer", "required": true, "alternative": null}, {"name": "Pastry brush", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Kitchen twine", "required": true, "alternative": null}]', '[{"symptom": "Glaze is burning before turkey is cooked", "likely_cause": "Sugar content in pomegranate juice and honey reacting to heat", "prevention": "Only apply glaze in the final 45 minutes of cooking", "fix": "Cover dark spots with small patches of aluminum foil immediately"}, {"symptom": "Gravy is lumpy", "likely_cause": "Adding hot liquid to hot roux too fast without whisking", "prevention": "Add liquid slowly while whisking vigorously", "fix": "Strain through a fine-mesh sieve or blitz with an immersion blender"}]', '["Safety Note: Raw poultry must be handled with care to avoid cross-contamination. Wash hands and surfaces thoroughly after contact.", "The glaze will thicken significantly as it cools. If it becomes too stiff to brush, warm it gently on the stove for a minute.", "For the smoothest gravy, ensure your stock is warm before adding it to the browned butter roux.", "If using a frozen turkey, ensure it is completely thawed before cooking (allow approx. 24 hours in the fridge for every 2.5kg of weight).", "Save the turkey carcass and the vegetable scraps from the roasting pan to make an excellent stock for soup the next day."]', '"This recipe bridges the traditional American Thanksgiving roast with the flavors of the Levant. The use of pomegranate reduction mimics ''narsharab'' or pomegranate molasses, a staple in Middle Eastern cuisine often paired with poultry to cut through richness with its potent acidity."', 1172.49);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ee3c41b1-dd73-4cb1-b9c5-70e17e774b46', 'Rainbow Garden Cheese Frittata', 'A fluffy, golden egg pie speckled with colorful, mild vegetables and melted cheddar. The texture is soft and creamy, not rubbery, making it an excellent vehicle for vegetables that kids will enjoy eating.', 'breakfast', 'Italian', 'Easy', '["frittata", "cheese", "vegetables", "kid-friendly", "quick", "breakfast", "healthy"]', '[{"group_name": "Base", "items": [{"name": "large eggs", "quantity": 8, "unit": null, "preparation": null, "notes": "approx. 400-450g total weight", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "whole milk", "quantity": 60, "unit": "ml", "preparation": null, "notes": "adds creaminess", "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx. 1/2 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, optional for picky eaters", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables & Cheese", "items": [{"name": "mild cheddar cheese", "quantity": 100, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "6cc08e49-8e1b-4065-be23-f57782560a8b", "nutrition_source": "Aggregated Public Data"}, {"name": "red bell pepper", "quantity": 80, "unit": "g", "preparation": "diced small", "notes": null, "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "USDA FoodData Central"}, {"name": "zucchini", "quantity": 80, "unit": "g", "preparation": "diced small", "notes": null, "substitutions": [], "ingredient_id": "c34b610f-8869-4d77-a9b3-e01849d703b5", "nutrition_source": "USDA FoodData Central"}, {"name": "frozen peas", "quantity": 50, "unit": "g", "preparation": "thawed", "notes": null, "substitutions": [], "ingredient_id": "fa661e9d-c4df-42f0-99c8-ca41610251a9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven broiler (grill setting) to high. If you do not have a broiler, preheat the oven to 200\u00b0C (400\u00b0F).", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, crack the eggs and add the milk, salt, and pepper. Whisk vigorously until the yolks and whites are fully combined and the mixture is slightly frothy. (Kid Step: Great for kids to practice whisking).", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat the olive oil in the oven-safe skillet over medium heat. Add the diced red pepper and zucchini. Saut\u00e9 for 4-5 minutes until the vegetables are soft and any excess moisture has evaporated.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT5M", "doneness_cues": null}, "tips": ["Cooking the vegetables first prevents a watery frittata."]}, {"step_number": 4, "phase": "cook", "text": "Add the thawed peas to the skillet and stir briefly. Pour the egg mixture over the vegetables. Using a spatula, gently lift the edges of the setting egg to allow uncooked egg to flow underneath.", "structured": {"action": "POUR", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Cook undisturbed on the stove-top over medium-low heat for about 4-5 minutes, or until the edges are set but the center is still slightly runny.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Edges are firm/opaque, center is liquid", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Sprinkle the grated cheddar cheese evenly over the top. (Kid Step: Kids can sprinkle the cheese carefully).", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Transfer the skillet to the oven. Broil (or bake) for 3-5 minutes until the eggs are fully puffed, set in the center, and the cheese is melted and bubbling.", "structured": {"action": "BROIL", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Puffed, golden cheese, no liquid egg when shaken", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from the oven using oven mitts (handle will be extremely hot). Let the frittata rest for 5 minutes before slicing into wedges.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT15M", "total_time": "PT30M", "overnight_required": false, "yields": "4-6 servings", "yield_count": 6, "serving_size_g": 140}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Low-Carb", "Keto"], "not_suitable_for": ["Vegans"]}', '{"per_serving": {"calories": 204.27, "protein_g": 13.56, "carbohydrates_g": 3.78, "fat_g": 14.79, "saturated_fat_g": 5.98, "trans_fat_g": 0.03, "monounsaturated_fat_g": 4.35, "polyunsaturated_fat_g": 1.61, "fiber_g": 0.87, "sugar_g": 2.11, "sodium_mg": 409.1, "cholesterol_mg": 249, "potassium_mg": 199.88, "calcium_mg": 174.49, "iron_mg": 1.53, "magnesium_mg": 20.33, "phosphorus_mg": 237.29, "zinc_mg": 1.66, "vitamin_a_mcg": 186.37, "vitamin_c_mg": 20.95, "vitamin_d_mcg": 1.46, "vitamin_e_mg": 1.3, "vitamin_k_mcg": 5.83, "vitamin_b6_mg": 0.19, "vitamin_b12_mcg": 0.64, "thiamin_mg": 0.07, "riboflavin_mg": 0.36, "niacin_mg": 0.39, "folate_mcg": 45.64, "water_g": 91.25, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container once fully cooled.", "duration": "P3D"}, "freezer": {"notes": "Texture may become slightly spongy upon thawing; reheat gently.", "duration": "P2M"}, "reheating": "Microwave slices for 30-45 seconds or warm in a toaster oven at 150\u00b0C (300\u00b0F) until heated through.", "does_not_keep": false}', '[{"name": "Oven-safe non-stick skillet (25cm/10in)", "required": true, "alternative": "Cast iron skillet"}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": "Fork"}, {"name": "Silicon spatula", "required": true, "alternative": null}]', '[{"symptom": "Frittata is watery or weeps liquid", "likely_cause": "Vegetables were not cooked long enough to release their water before adding eggs", "prevention": "Ensure peppers and zucchini are saut\u00e9ed until they look dry before adding the egg mixture", "fix": "Drain excess liquid from the plate; texture will be fine"}, {"symptom": "Bottom is burnt but top is raw", "likely_cause": "Stove heat was too high during the initial stovetop cooking phase", "prevention": "Keep heat at medium-low; the goal is just to set the bottom, not brown it deeply", "fix": "Slice off the burnt bottom layer before serving"}]', '["To involve kids: Let them choose the vegetable colors (bell peppers come in red, yellow, orange) to increase buy-in.", "For extra fluffiness, do not overbeat the eggs, but ensure the white and yolk are completely homogenous before cooking.", "Safety alert: The handle of the skillet will remain hot for a long time after coming out of the oven. Always leave a potholder or towel draped over the handle as a visual warning.", "Leftovers make excellent cold lunchbox items for the next day."]', '"The frittata is an Italian egg-based dish similar to an omelet or crustless quiche, enriched with additional ingredients like meats, cheeses, or vegetables. Unlike a French omelet, which is folded, a frittata is cooked slowly and finished in the oven, making it a rustic, communal dish often served at room temperature in Italy."', 204.27);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ee553308-12cb-481d-a6ca-5e1cfd69cb84', 'Macanese Grilled Prawns with Turmeric Sambal & Soy Beurre Blanc', 'Succulent tiger prawns butterflied and filled with a fragrant, golden paste of fresh turmeric, lemongrass, and shallots. Grilled over charcoal to impart smokiness and served with a velvety, umami-laden butter emulsion that pays homage to Macau''s Portuguese-Cantonese heritage.', 'dinner', 'Macanese', 'Intermediate', '["prawns", "seafood", "grilled", "asian-inspired", "macanese", "fusion", "gluten-free"]', '[{"group_name": "Prawns", "items": [{"name": "large tiger prawns", "quantity": 12, "unit": null, "preparation": "whole, shell-on", "notes": "approx 800g total weight", "substitutions": [], "ingredient_id": "2d8221bd-a2d1-4233-894f-cb6b0cf40234", "nutrition_source": "Aggregated Public Data"}, {"name": "neutral oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": "for brushing", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "fine sea salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Macanese Stuffing Paste", "items": [{"name": "shallots", "quantity": 3, "unit": null, "preparation": "peeled", "notes": "approx 60g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 4, "unit": null, "preparation": "peeled", "notes": "approx 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh turmeric", "quantity": 10, "unit": "g", "preparation": "peeled", "notes": "or 1 tsp ground turmeric", "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "lemongrass", "quantity": 1, "unit": null, "preparation": "white part only, chopped", "notes": "approx 15g", "substitutions": [], "ingredient_id": "6dde667b-d122-48d9-a70f-a4f820fc5bd5", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh red chili", "quantity": 2, "unit": null, "preparation": "deseeded", "notes": "approx 20g", "substitutions": [], "ingredient_id": "5080eb9a-d555-4558-94e5-d5700e96ff9b", "nutrition_source": "USDA FoodData Central"}, {"name": "shrimp paste", "quantity": 5, "unit": "g", "preparation": null, "notes": "belacan or balich\u00e3o", "substitutions": [], "ingredient_id": "02034d13-a948-4cfd-ba06-d78d03006e5e", "nutrition_source": "Aggregated Public Data"}, {"name": "coconut milk", "quantity": 30, "unit": "ml", "preparation": null, "notes": "thick cream from top of can", "substitutions": [], "ingredient_id": "c037ee7e-e3ed-4340-b8fb-d8ad284ba96e", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Soy Butter Sauce", "items": [{"name": "unsalted butter", "quantity": 100, "unit": "g", "preparation": "cold, cubed", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "tamari soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": "use gluten-free if required", "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "white pepper", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "cdc9ddd1-ed48-431b-a39c-171f424578c9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish", "items": [{"name": "spring onions", "quantity": 2, "unit": null, "preparation": "finely sliced", "notes": "approx 20g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "lime wedges", "quantity": 4, "unit": null, "preparation": null, "notes": "for serving", "substitutions": [], "ingredient_id": "d3d2677e-fe02-4404-add0-29d73df7e921", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the aromatics. Combine shallots, garlic, turmeric, lemongrass, red chili, and shrimp paste in a food processor. Pulse until a fine, vibrant paste forms. Stir in the coconut milk to bind the mixture.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Prepare the prawns. Using kitchen shears, cut through the back shell from head to tail, leaving the head attached. Use a knife to slice deep into the back meat to butterfly it open (do not cut all the way through). Remove the dark vein. Rinse and pat dry thoroughly.", "structured": {"action": "BUTTERFLY", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "assemble", "text": "Spoon the spice paste generously into the cavity of each butterflied prawn. Press the filling down gently so it adheres to the meat. Brush the outer shells with neutral oil and season lightly with salt. Let rest at room temperature while preparing the grill.", "structured": {"action": "STUFF", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Preheat your grill to medium-high heat (approx 200\u00b0C/400\u00b0F). If using charcoal, ensure coals are glowing red with a light ash coating.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "While the grill heats, make the sauce. In a small saucepan over low heat, warm the soy sauce and lemon juice. Whisk in the cold cubed butter, one piece at a time, ensuring the mixture stays emulsified and creamy (do not let it boil). Season with white pepper. Remove from heat and keep in a warm spot.", "structured": {"action": "EMULSIFY", "temperature": {"celsius": 60, "fahrenheit": 140}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Grill the prawns. Place them shell-side down first to protect the meat. Grill for 3-4 minutes until the shell turns bright orange and the meat begins to turn opaque. Carefully flip onto the flesh side for just 1-2 minutes to char the stuffing and finish cooking. Internal temperature should reach 63\u00b0C/145\u00b0F.", "structured": {"action": "GRILL", "temperature": null, "duration": "PT6M", "doneness_cues": {"visual": "Shells bright orange, meat opaque white", "tactile": "Firm to the touch"}}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Transfer prawns to a serving platter. Drizzle generously with the warm soy butter sauce. Garnish with spring onions and serve immediately with lime wedges.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT20M", "total_time": "PT55M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 280}', '{"flags": ["Pescatarian", "Gluten-Free"], "not_suitable_for": ["Shellfish allergy"]}', '{"per_serving": {"calories": 513.57, "protein_g": 49.84, "carbohydrates_g": 11.39, "fat_g": 33.82, "saturated_fat_g": 15.35, "trans_fat_g": null, "monounsaturated_fat_g": 5.95, "polyunsaturated_fat_g": 0.82, "fiber_g": 1.78, "sugar_g": 2.64, "sodium_mg": 2231.66, "cholesterol_mg": 53.75, "potassium_mg": 204.11, "calcium_mg": 57.54, "iron_mg": 2.52, "magnesium_mg": 16.54, "phosphorus_mg": 43.28, "zinc_mg": 0.4, "vitamin_a_mcg": 183.5, "vitamin_c_mg": 19.68, "vitamin_d_mcg": null, "vitamin_e_mg": 0.76, "vitamin_k_mcg": 12.66, "vitamin_b6_mg": 0.1, "vitamin_b12_mcg": 0.04, "thiamin_mg": 0.03, "riboflavin_mg": 0.03, "niacin_mg": 0.2, "folate_mcg": 12.22, "water_g": 37.77, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store prawns and sauce separately. Reheat gently to avoid splitting the sauce.", "duration": "P2D"}, "freezer": {"notes": "Not recommended; texture of prawns and stability of butter sauce will degrade.", "duration": null}, "reheating": "Gently warm prawns in a pan over low heat; whisk sauce over a warm water bath.", "does_not_keep": false}', '[{"name": "Food processor or mortar and pestle", "required": true, "alternative": null}, {"name": "Outdoor grill or grill pan", "required": true, "alternative": "Oven broiler"}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Sharp knife (Chef or Paring)", "required": true, "alternative": null}, {"name": "Kitchen shears", "required": true, "alternative": null}]', '[{"symptom": "Stuffing falls out during grilling", "likely_cause": "Paste was too wet or prawns were flipped too aggressively", "prevention": "Ensure coconut milk is thick; press stuffing firmly; flip gently", "fix": "Spoon any fallen stuffing back onto the prawns after flipping them onto the serving plate"}, {"symptom": "Butter sauce separates (looks oily)", "likely_cause": "Heat was too high or butter was added too quickly", "prevention": "Keep heat very low; whisk in cold butter slowly", "fix": "Remove from heat, add a teaspoon of cold water or cream, and whisk vigorously to re-emulsify"}]', '["To achieve a true Macanese flavor profile, try to source ''Balich\u00e3o'' (Macanese shrimp paste), but standard Belacan or fine shrimp sauce is a worthy substitute.", "Do not discard the prawn heads; the ''tomalley'' inside mixes with the butter sauce and grilled stuffing to create the most flavorful part of the dish.", "If using wooden skewers to keep the prawns straight, soak them in water for 30 minutes beforehand to prevent burning.", "For the sauce, the butter must be cold when adding it to the warm liquid; this technique (mounting with butter) creates a thick, creamy emulsion without cream."]', '"Macanese cuisine is often cited as one of the world''s first fusion cuisines, evolving over 400 years in Macau. This dish reflects that history by combining Portuguese grilling techniques and love for seafood with local Chinese ingredients and spices (turmeric, coconut, chili) acquired along the maritime spice routes."', 513.57);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ee5d6249-0f08-407b-8304-799dd666ac44', 'Apple Cider & Blackberry Whole Wheat Muffins', 'Rustic, wholesome muffins featuring a nutty whole wheat crumb tenderized with Greek yogurt and aromatic apple cider. Bursts of tart blackberries and the floral sweetness of honey create a deeply flavorful, guilt-free treat perfect for autumn mornings.', 'baked good', 'American', 'Intermediate', '["apple cider", "honey", "muffin", "whole wheat flour", "dessert", "breakfast", "autumn"]', '[{"group_name": "Dry Ingredients", "items": [{"name": "whole wheat flour", "quantity": 250, "unit": "g", "preparation": null, "notes": "Standard or white whole wheat flour", "substitutions": [], "ingredient_id": "af2661d8-b555-4fef-bdee-51a5190eda92", "nutrition_source": "USDA FoodData Central"}, {"name": "baking powder", "quantity": 8, "unit": "g", "preparation": null, "notes": "approx 2 tsp", "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "baking soda", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx 1/2 tsp", "substitutions": [], "ingredient_id": "43f6961e-dc10-42f7-a024-e7f9c60cbdca", "nutrition_source": "USDA FoodData Central"}, {"name": "ground cinnamon", "quantity": 4, "unit": "g", "preparation": null, "notes": "approx 1.5 tsp", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 1/2 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Wet Ingredients", "items": [{"name": "apple cider", "quantity": 120, "unit": "ml", "preparation": "room temperature", "notes": "Unfiltered apple juice/cider, not vinegar", "substitutions": [], "ingredient_id": "56eee60d-4cb7-489f-8e00-04b151786323", "nutrition_source": "Aggregated Public Data"}, {"name": "honey", "quantity": 170, "unit": "g", "preparation": "fluid", "notes": null, "substitutions": [], "ingredient_id": "97be7b4a-7a8c-4f99-b1be-874b267b8c22", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 85, "unit": "g", "preparation": "melted and cooled", "notes": null, "substitutions": ["coconut oil", "olive oil"], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "greek yogurt", "quantity": 120, "unit": "g", "preparation": "room temperature", "notes": "Plain, full-fat preferred", "substitutions": [], "ingredient_id": "cb272815-f202-42e9-a1ee-21757d749f90", "nutrition_source": "USDA FoodData Central"}, {"name": "large eggs", "quantity": 2, "unit": null, "preparation": "room temperature", "notes": "approx 100g total without shell", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Mix-ins", "items": [{"name": "blackberries", "quantity": 150, "unit": "g", "preparation": "fresh or frozen", "notes": "Do not thaw if frozen; chop if very large", "substitutions": [], "ingredient_id": "ce7c9c9b-08d3-4496-8b7f-e45c2ee8d6bf", "nutrition_source": "USDA FoodData Central"}, {"name": "whole wheat flour", "quantity": 5, "unit": "g", "preparation": null, "notes": "To toss with berries", "substitutions": [], "ingredient_id": "af2661d8-b555-4fef-bdee-51a5190eda92", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 220\u00b0C/425\u00b0F. Line a 12-cup muffin tin with paper liners or grease generously with butter.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 220, "fahrenheit": 428}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large bowl, whisk together the flour, baking powder, baking soda, cinnamon, and salt until thoroughly aerated.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Aerating the flour helps prevent heavy muffins."]}, {"step_number": 3, "phase": "prep", "text": "In a medium bowl, whisk the melted butter, honey, eggs, Greek yogurt, apple cider, and vanilla extract until completely smooth and emulsified.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour the wet ingredients into the dry ingredients. Use a spatula to gently fold the mixture until just barely combined and streaks of flour remain.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Do not overmix. Overmixing develops gluten and makes whole wheat tough."]}, {"step_number": 5, "phase": "cook", "text": "Toss the blackberries with the small reserve of flour (5g) to prevent sinking. Gently fold them into the batter until just distributed. Do not overwork.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Divide the batter evenly among the 12 muffin cups, filling them almost to the top.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Bake at 220\u00b0C/425\u00b0F for 5 minutes. Then, without opening the oven door, reduce the temperature to 190\u00b0C/375\u00b0F and bake for an additional 13-15 minutes.", "structured": {"action": "BAKE", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT15M", "doneness_cues": {"visual": "Golden brown domed tops", "tactile": "Springy to the touch, toothpick comes out clean"}}, "tips": ["The initial high heat creates a rapid rise for a bakery-style dome."]}, {"step_number": 8, "phase": "finish", "text": "Let the muffins cool in the tin for 5 minutes, then transfer to a wire rack to cool completely.", "structured": {"action": "COOL", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT20M", "total_time": "PT40M", "overnight_required": false, "yields": "12 muffins", "yield_count": 12, "serving_size_g": 85}', '{"flags": ["Vegetarian", "Soy-Free", "Peanut-Free"], "not_suitable_for": ["Infants under 12 months (honey)"]}', '{"per_serving": {"calories": 195.97, "protein_g": 4.38, "carbohydrates_g": 30.72, "fat_g": 7.21, "saturated_fat_g": 4.06, "trans_fat_g": 0.01, "monounsaturated_fat_g": 2.08, "polyunsaturated_fat_g": 0.67, "fiber_g": 3.66, "sugar_g": 13.18, "sodium_mg": 230.75, "cholesterol_mg": 47.23, "potassium_mg": 140.85, "calcium_mg": 71.99, "iron_mg": 1.18, "magnesium_mg": 30.32, "phosphorus_mg": 118.69, "zinc_mg": 0.91, "vitamin_a_mcg": 72.21, "vitamin_c_mg": 2.82, "vitamin_d_mcg": 0.17, "vitamin_e_mg": 0.52, "vitamin_k_mcg": 3.52, "vitamin_b6_mg": 0.07, "vitamin_b12_mcg": 0.14, "thiamin_mg": 0.08, "riboflavin_mg": 0.12, "niacin_mg": 1.27, "folate_mcg": 14.71, "water_g": 32.23, "alcohol_g": 0.14, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container lined with paper towels to absorb excess moisture.", "duration": "P5D"}, "freezer": {"notes": "Wrap individually in plastic wrap, then place in a freezer bag.", "duration": "P3M"}, "reheating": "Warm in a 150\u00b0C/300\u00b0F oven for 5 minutes or microwave for 15 seconds.", "does_not_keep": false}', '[{"name": "Standard 12-cup muffin tin", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Medium mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Silicone spatula", "required": true, "alternative": null}, {"name": "Muffin liners", "required": false, "alternative": "Cooking spray/Butter for greasing"}, {"name": "Wire cooling rack", "required": true, "alternative": null}]', '[{"symptom": "Muffins are dense or rubbery", "likely_cause": "Batter was overmixed after adding flour", "prevention": "Stop mixing as soon as no dry flour is visible; lumps are okay.", "fix": "Cannot be fixed once baked; serve warm with butter to mask texture."}, {"symptom": "Berries sank to the bottom", "likely_cause": "Batter too thin or berries not coated", "prevention": "Toss berries in a little flour before adding; ensure batter is thick enough.", "fix": "Cannot be fixed."}]', '["Room temperature ingredients (eggs, yogurt, cider) are crucial for a uniform emulsion, which leads to a better rise.", "For an extra crunch, sprinkle coarse sugar or rolled oats on top before baking.", "If using frozen blackberries, do not thaw them first, or they will bleed into the batter and turn it grey."]', '"Muffins are a staple of American breakfast culture, evolving from British yeast cakes into the ''quick breads'' we know today. This recipe nods to autumnal harvests by pairing orchard cider with late-season berries and hearty grains."', 195.97);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('eea825aa-90e0-4db1-aede-b44c338338ed', 'Pan-Seared Lemon Garlic Asparagus', 'Bright, crisp-tender asparagus spears pan-seared in nutty browned butter with aromatic garlic and a finishing splash of fresh lemon juice. A vibrant side dish that comes together in minutes.', 'side dish', 'American', 'Easy', '["vegetarian", "side dish", "quick", "easy", "spring", "low carb"]', '[{"group_name": "Vegetables", "items": [{"name": "fresh asparagus", "quantity": 500, "unit": "g", "preparation": "woody ends removed", "notes": "choose medium-thickness spears for best texture", "substitutions": [], "ingredient_id": "8a2a9426-3755-4553-953a-fd9cf42cef90", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx. 9g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 0.5, "unit": null, "preparation": "juiced", "notes": "approx. 15-20ml juice", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pantry", "items": [{"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "cold or room temperature", "notes": null, "substitutions": ["olive oil", "ghee"], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "adjust to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly cracked", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare the asparagus by snapping off the woody ends. Hold the spear at the base and bend until it snaps naturally where it becomes tender.", "structured": {"action": "TRIM", "temperature": null, "duration": null, "doneness_cues": {"visual": null, "tactile": "Snap should be crisp, not stringy"}}, "tips": ["If spears are very thick, you can peel the bottom inch with a vegetable peeler instead of snapping."]}, {"step_number": 2, "phase": "cook", "text": "Heat the butter in a large skillet over medium-high heat. Wait until the butter foams and subsides slightly, indicating the pan is hot enough.", "structured": {"action": "HEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Add the asparagus spears in a single layer. Sear without moving them for about 2-3 minutes to develop caramelization, then toss and cook for another 2-3 minutes until crisp-tender.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Bright green with spotty golden-brown blistering", "tactile": "Pierces easily with a fork but retains a crunch"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Reduce heat to medium. Add the minced garlic and toss constantly for 30-60 seconds to soften without burning.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Garlic is fragrant and pale gold, not dark brown", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Remove from heat immediately. Drizzle with lemon juice, season with salt and pepper, and toss to combine.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT10M", "passive_time": "PT0M", "total_time": "PT10M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 135}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Low-Carb", "Keto"], "not_suitable_for": []}', '{"per_serving": {"calories": 85.87, "protein_g": 3.1, "carbohydrates_g": 6.76, "fat_g": 6.29, "saturated_fat_g": 3.85, "trans_fat_g": null, "monounsaturated_fat_g": 1.76, "polyunsaturated_fat_g": 0.31, "fiber_g": 3.04, "sugar_g": 2.65, "sodium_mg": 294.97, "cholesterol_mg": 16.13, "potassium_mg": 281.54, "calcium_mg": 39.96, "iron_mg": 2.81, "magnesium_mg": 19.51, "phosphorus_mg": 72.36, "zinc_mg": 0.72, "vitamin_a_mcg": 98.98, "vitamin_c_mg": 13.4, "vitamin_d_mcg": null, "vitamin_e_mg": 1.61, "vitamin_k_mcg": 52.97, "vitamin_b6_mg": 0.15, "vitamin_b12_mcg": 0.01, "thiamin_mg": 0.19, "riboflavin_mg": 0.18, "niacin_mg": 1.25, "folate_mcg": 66.52, "water_g": 128.64, "alcohol_g": null, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Texture may soften slightly upon reheating.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; texture becomes mushy.", "duration": null}, "reheating": "Briefly saut\u00e9 in a hot pan for 1-2 minutes to restore texture.", "does_not_keep": false}', '[{"name": "Large skillet or frying pan", "required": true, "alternative": "Wok"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Asparagus is mushy or limp", "likely_cause": "Overcrowded pan or overcooked", "prevention": "Cook in a single layer (use two batches if necessary) and stop heat while it still has a ''bite''.", "fix": "Cannot be fixed, but can be pureed into a soup base."}, {"symptom": "Garlic tastes bitter", "likely_cause": "Garlic burned", "prevention": "Add garlic only in the last minute of cooking; it cooks much faster than the asparagus.", "fix": "Wipe the asparagus off with a paper towel and toss with fresh oil/butter."}]', '["Thickness matters: Pencil-thin asparagus cooks in 2-3 minutes; jumbo spears may need 7-8 minutes.", "The ''snap'' method ensures you never eat stringy asparagus, but it does create some waste. Save the woody ends for vegetable stock.", "For a light meal, serve this topped with a poached egg or alongside toasted sourdough with ricotta.", "Dry the asparagus thoroughly after washing; wet vegetables will steam rather than sear."]', '"Asparagus has been cultivated for over 2,500 years and is widely celebrated in European and American cuisine as the herald of spring. Simple preparations like this highlight the vegetable''s natural sweetness and grassy notes without masking them."', 85.87);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('eeb6f0a4-5ef3-4ffb-b9da-f8672e9de48e', 'Sizzling Ginger & Tomato Chicken Rice Soup', 'A soul-warming fusion soup that bridges the gap between comforting rice porridge and zesty Tom Yum. Golden-fried ginger strips provide a smoky, spicy crunch, while bursting cherry tomatoes and lime juice cut through the savory depth of chicken and fish sauce.', 'soup', 'Asian Fusion', 'Easy', '["one pot", "chicken soup", "weeknight", "fusion", "comfort food", "gluten-free adaptable", "dairy-free"]', '[{"group_name": "Aromatics & Base", "items": [{"name": "neutral oil", "quantity": 30, "unit": "ml", "preparation": "room temperature", "notes": "grapeseed or canola", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh ginger", "quantity": 50, "unit": "g", "preparation": "julienned into thin matchsticks", "notes": "peeled", "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "boneless skinless chicken thighs", "quantity": 500, "unit": "g", "preparation": "cut into 2cm pieces", "notes": null, "substitutions": [], "ingredient_id": "d7fc1bf9-fc05-429b-bfa6-2ad857cb0bb6", "nutrition_source": "USDA FoodData Central"}, {"name": "tomato paste", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "41400e7f-7a06-42d2-a625-072c380d60b2", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Soup & Grains", "items": [{"name": "chicken stock", "quantity": 1500, "unit": "ml", "preparation": null, "notes": "low sodium preferred", "substitutions": [], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}, {"name": "jasmine rice", "quantity": 150, "unit": "g", "preparation": "uncooked, rinsed", "notes": null, "substitutions": [], "ingredient_id": "b671f3cd-cdec-4182-8911-82a06a22815a", "nutrition_source": "USDA FoodData Central"}, {"name": "fish sauce", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "95a9a747-50ee-4be0-84be-0dfc96111e2a", "nutrition_source": "Aggregated Public Data"}, {"name": "soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["tamari for gluten-free"], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "cherry tomatoes", "quantity": 250, "unit": "g", "preparation": "whole", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Finishing", "items": [{"name": "lime", "quantity": 1, "unit": null, "preparation": "juiced", "notes": "approx 30ml juice", "substitutions": [], "ingredient_id": "d3d2677e-fe02-4404-add0-29d73df7e921", "nutrition_source": "USDA FoodData Central"}, {"name": "toasted sesame oil", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8fa9dd65-c49e-449c-b660-a9d9deb638b2", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh cilantro", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "red chili flakes", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare your ingredients: cut chicken into bite-sized pieces, julienne the ginger into fine matchsticks, and mince the garlic. Rinse the jasmine rice until the water runs clear.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat neutral oil in the heavy-bottomed pot over medium-high heat. Add the julienned ginger and fry, stirring constantly, until golden brown and crisp. Use a slotted spoon to remove half of the ginger and set aside on a paper towel for garnishing. Leave the remaining ginger and oil in the pot.", "structured": {"action": "FRY", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT4M", "doneness_cues": {"visual": "Golden brown", "tactile": "Crispy"}}, "tips": ["Watch the ginger closely; it transitions from golden to burnt very quickly."]}, {"step_number": 3, "phase": "cook", "text": "Add the chicken pieces to the pot with the remaining ginger oil. Sear for 3-4 minutes until the chicken is opaque. Add garlic and tomato paste, stirring vigorously to coat the chicken and caramelize the paste until it deepens in color (about 2 minutes).", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Tomato paste turns brick red", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour in the chicken stock, fish sauce, and soy sauce. Scrape the bottom of the pot to release any fond (browned bits). Bring to a boil, then stir in the rinsed rice. Reduce heat to low to maintain a gentle simmer.", "structured": {"action": "DEGLAZE", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Cover and simmer for 15 minutes. Uncover, add the whole cherry tomatoes, and simmer for another 5-7 minutes. The rice should be tender, the chicken cooked through (internal temp 74\u00b0C/165\u00b0F), and the tomatoes just starting to burst skins.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT20M", "doneness_cues": {"visual": null, "tactile": "Rice is tender"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove from heat. Stir in the lime juice and toasted sesame oil. Taste and adjust salt if needed. Ladle into bowls and top generously with the reserved crispy ginger, fresh cilantro, and chili flakes if using.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT25M", "total_time": "PT45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Dairy-Free", "Pescatarian", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 515.9, "protein_g": 36.94, "carbohydrates_g": 45.06, "fat_g": 23.33, "saturated_fat_g": 2.97, "trans_fat_g": 0.03, "monounsaturated_fat_g": 2, "polyunsaturated_fat_g": 1.33, "fiber_g": 3.15, "sugar_g": 4.74, "sodium_mg": 16069.7, "cholesterol_mg": 117.5, "potassium_mg": 700.2, "calcium_mg": 47.34, "iron_mg": 2.91, "magnesium_mg": 64.1, "phosphorus_mg": 310.91, "zinc_mg": 2.68, "vitamin_a_mcg": 98.63, "vitamin_c_mg": 18.25, "vitamin_d_mcg": null, "vitamin_e_mg": 0.54, "vitamin_k_mcg": 4.4, "vitamin_b6_mg": 0.71, "vitamin_b12_mcg": 0.76, "thiamin_mg": 0.16, "riboflavin_mg": 0.29, "niacin_mg": 7.77, "folate_mcg": 11.33, "water_g": 135.99, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Rice will continue to absorb liquid; add a splash of water or stock when reheating.", "duration": "P3D"}, "freezer": {"notes": "Texture of rice may degrade slightly upon freezing.", "duration": "P1M"}, "reheating": "Simmer gently on stovetop, adding water to loosen consistency.", "does_not_keep": false}', '[{"name": "Heavy-bottomed pot or Dutch oven", "required": true, "alternative": "Large deep saut\u00e9 pan"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Slotted spoon", "required": true, "alternative": null}]', '[{"symptom": "Soup has turned into a thick porridge", "likely_cause": "The rice absorbed too much liquid or the heat was too high during simmering", "prevention": "Rinse rice thoroughly before cooking to remove excess surface starch", "fix": "Stir in an additional 100-200ml of hot water or stock to reach desired consistency"}]', '["Frying the ginger first is the critical step. It flavors the oil that cooks the chicken and provides a textural contrast at the end that makes the dish pop.", "Do not skip rinsing the rice. Excess starch will make the soup slimy rather than silky.", "For a deeper umami punch, use bone-in chicken thighs and simmer for 10 minutes longer before adding the rice.", "The tomatoes should be ''jammy'' but not disintegrated\u2014add them only in the last stage of cooking.", "If you love heat, saut\u00e9 a sliced fresh chili along with the garlic in step 3."]', '"This dish draws inspiration from two culinary traditions: the comforting texture of Chinese ''Pao Fan'' (submerged rice) or Congee, and the hot-sour aromatic profile of Thai Tom Yum. It represents modern home-cooking fusion, utilizing pantry staples to create complex flavors rapidly."', 515.9);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('eebd6ad9-9676-4988-b9c9-410d0fc44a2e', 'Cinnamon & Sage Infused Cream Pasta', 'A luxuriously cozy pasta dish where the warmth of a cinnamon stick and earthy fresh herbs transform simple heavy cream into a sophisticated, savory sauce. The subtle spice pairs unexpectedly well with wilted greens and parmesan, creating a comforting winter profile.', 'dinner', 'Fusion', 'Easy', '["pastas", "heavy cream", "herbs", "pasta", "weeknight", "main course", "vegetarian", "comfort food", "winter"]', '[{"group_name": "Aromatic Cream Base", "items": [{"name": "heavy cream", "quantity": 350, "unit": "ml", "preparation": null, "notes": "minimum 35% fat content for stability", "substitutions": [], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "cinnamon stick", "quantity": 1, "unit": null, "preparation": null, "notes": "whole stick, approx 5g", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh sage leaves", "quantity": 5, "unit": "g", "preparation": null, "notes": "roughly 10-12 leaves", "substitutions": [], "ingredient_id": "2babed06-aae7-4e90-8b4a-14acbde2f522", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh thyme sprigs", "quantity": 4, "unit": null, "preparation": null, "notes": "approx 3g", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "whole", "notes": "smashed but whole", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Pasta & Greens", "items": [{"name": "dried pasta", "quantity": 400, "unit": "g", "preparation": null, "notes": "fettuccine, pappardelle, or penne work best", "substitutions": ["gluten-free pasta"], "ingredient_id": "9acd8d49-8848-4e5f-90e4-33b9b31f83c9", "nutrition_source": "Aggregated Public Data"}, {"name": "kale or swiss chard", "quantity": 200, "unit": "g", "preparation": "stems removed, leaves chopped", "notes": null, "substitutions": [], "ingredient_id": "79b678f0-56b8-4845-9e4f-3809b53bf739", "nutrition_source": "USDA FoodData Central"}, {"name": "parmesan cheese", "quantity": 60, "unit": "g", "preparation": "finely grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a deep saut\u00e9 pan, combine the heavy cream, smashed garlic clove, cinnamon stick, sage leaves, and thyme sprigs. Bring to a very gentle simmer over medium-low heat. Do not let it boil vigorously.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT5M", "doneness_cues": {"visual": "Small bubbles forming around the edges", "tactile": null}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Once simmering, remove the pan from the heat. Cover with a lid and let the cream steep for 15 minutes to infuse the flavors.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "While the cream steeps, bring a large pot of salted water to a boil. Add the pasta and cook until 1 minute shy of al dente according to package directions.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Uncover the cream mixture. Remove and discard the garlic, cinnamon stick, and herb sprigs. Return the infused cream to medium heat.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the chopped greens (kale or chard) to the warm cream. Simmer gently until the greens are wilted and tender, about 3-4 minutes.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Greens have reduced in volume and turned dark green", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Transfer the cooked pasta directly into the sauce using tongs, reserving about 120ml (1/2 cup) of pasta water. Toss the pasta vigorously with the cream and greens.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from heat. Stir in the grated parmesan cheese. If the sauce looks too thick or sticky, add reserved pasta water 1 tablespoon (15ml) at a time until silky and glossy. Season generously with salt and black pepper.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": {"visual": "Sauce coats the back of a spoon without running off instantly", "tactile": null}}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT15M", "total_time": "PT35M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 758.2, "protein_g": 23.58, "carbohydrates_g": 79.22, "fat_g": 39.08, "saturated_fat_g": 23.2, "trans_fat_g": 1.09, "monounsaturated_fat_g": 9.15, "polyunsaturated_fat_g": 1.81, "fiber_g": 5.91, "sugar_g": 5.33, "sodium_mg": 433.43, "cholesterol_mg": 109.08, "potassium_mg": 736.71, "calcium_mg": 440.08, "iron_mg": 4.18, "magnesium_mg": 142.86, "phosphorus_mg": 555.37, "zinc_mg": 3.76, "vitamin_a_mcg": 513.22, "vitamin_c_mg": 49.19, "vitamin_d_mcg": 1.48, "vitamin_e_mg": 1.2, "vitamin_k_mcg": 198.87, "vitamin_b6_mg": 0.14, "vitamin_b12_mcg": 0.32, "thiamin_mg": 0.08, "riboflavin_mg": 0.4, "niacin_mg": 0.72, "folate_mcg": 36.03, "water_g": 101.03, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Sauce will thicken significantly; reheat with a splash of water or milk.", "duration": "P3D"}, "freezer": {"notes": "Cream-based sauces tend to split when frozen and thawed.", "duration": null}, "reheating": "Reheat gently on the stovetop over low heat, adding a splash of water to loosen the emulsion.", "does_not_keep": false}', '[{"name": "Large stockpot", "required": true, "alternative": null}, {"name": "Deep saut\u00e9 pan or skillet", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Sauce has separated or looks oily", "likely_cause": "The cream was boiled too vigorously or the heat was too high when adding cheese", "prevention": "Keep heat low when infusing and remove from heat entirely before adding cheese", "fix": "Stir in a splash of cold heavy cream or water and whisk vigorously off the heat to re-emulsify"}]', '["The cinnamon should be a background note that provides warmth, not a dominant dessert-like flavor. Taste the cream after 10 minutes of steeping; if the cinnamon is strong, remove the stick early.", "For a protein addition, seared scallops or roasted chickpeas pair beautifully with the sweet-savory profile of the sauce.", "Do not rinse the pasta after boiling. The starch on the noodles is essential for binding the cream sauce.", "If using spinach instead of kale, add it at the very last second as it wilts instantly compared to the heartier kale."]', '"While cinnamon is often associated with sweets in Western cuisine, it is a traditional savory spice in Greek (as in pastitsio) and Middle Eastern cooking. This recipe borrows that savory application, using the spice''s essential oils to highlight the natural sweetness of dairy."', 758.2);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ef266f1f-8b22-47f3-8196-efbf84c80544', 'Cajun-Style Duck and Okra Perloo', 'A robust South Carolina Lowcountry dish where long-grain rice absorbs the savory essence of rendered duck fat, crushed tomatoes, and the ''holy trinity'' of aromatics. Topped with crispy-skinned, rosy-pink duck breast and tender, non-mucilaginous okra.', 'dinner', 'American Southern', 'Intermediate', '["dinner", "southern", "duck", "one-pot", "gluten-free"]', '[{"group_name": "Duck", "items": [{"name": "duck breast", "quantity": 2, "unit": null, "preparation": "skin-on, boneless", "notes": "approx. 400-500g total", "substitutions": [], "ingredient_id": "10ea2903-e622-46ac-90ab-261904af3399", "nutrition_source": "Aggregated Public Data"}, {"name": "kosher salt", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables & Aromatics", "items": [{"name": "okra", "quantity": 250, "unit": "g", "preparation": "sliced into 1cm rounds", "notes": null, "substitutions": [], "ingredient_id": "4b2867df-2cef-4146-b0df-55b20994dc3c", "nutrition_source": "USDA FoodData Central"}, {"name": "onion", "quantity": 150, "unit": "g", "preparation": "diced small (yellow or white)", "notes": null, "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "green bell pepper", "quantity": 120, "unit": "g", "preparation": "diced small", "notes": null, "substitutions": [], "ingredient_id": "627afa21-0392-4082-ab38-0f20446e190e", "nutrition_source": "Aggregated Public Data"}, {"name": "celery", "quantity": 80, "unit": "g", "preparation": "diced small", "notes": null, "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx. 12g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Rice & Broth", "items": [{"name": "long grain white rice", "quantity": 300, "unit": "g", "preparation": "rinsed", "notes": null, "substitutions": [], "ingredient_id": "b671f3cd-cdec-4182-8911-82a06a22815a", "nutrition_source": "USDA FoodData Central"}, {"name": "chicken broth", "quantity": 500, "unit": "ml", "preparation": "hot", "notes": null, "substitutions": [], "ingredient_id": "7e254f45-046f-4812-bcdd-7e31c9bb59b8", "nutrition_source": "Aggregated Public Data"}, {"name": "crushed tomatoes", "quantity": 400, "unit": "g", "preparation": "canned", "notes": null, "substitutions": [], "ingredient_id": "49a62ca7-db63-4d23-9f6f-2cf873fba8a3", "nutrition_source": "Aggregated Public Data"}, {"name": "smoked paprika", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f4c3bdd7-6528-40d2-84b3-a6325df15e8e", "nutrition_source": "USDA FoodData Central"}, {"name": "dried thyme", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "3b938244-d506-46b2-9027-21bed955bcc5", "nutrition_source": "USDA FoodData Central"}, {"name": "cayenne pepper", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "58780fb1-30a8-45d7-9983-b7a6bc626333", "nutrition_source": "Aggregated Public Data"}, {"name": "bay leaf", "quantity": 1, "unit": null, "preparation": null, "notes": "dried", "substitutions": [], "ingredient_id": "2246afeb-7fb0-4d0e-89bd-6e2f08b3d23f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Using a sharp knife, score the skin of the duck breasts in a crosshatch pattern, being careful not to cut into the meat. Season generously with salt and pepper on both sides.", "structured": {"action": "SCORE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Place duck breasts skin-side down in a cold Dutch oven. Turn heat to medium-low and render the fat for 8-10 minutes until the skin is golden and crispy. Flip and cook for 2-3 minutes until internal temperature reaches 52\u00b0C/125\u00b0F for medium-rare.", "structured": {"action": "SEAR", "temperature": {"celsius": 52, "fahrenheit": 126}, "duration": "PT12M", "doneness_cues": {"visual": "Golden brown crispy skin", "tactile": "Flesh offers slight resistance"}}, "tips": ["Starting in a cold pan is crucial for rendering out the fat properly.", "Internal temp will rise to 54-55\u00b0C (medium-rare) during resting."]}, {"step_number": 3, "phase": "cook", "text": "Remove duck to a plate to rest. Keep approximately 45ml (3 tbsp) of rendered duck fat in the pot; discard or save the rest. Increase heat to medium-high.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the okra to the hot duck fat. Saut\u00e9 vigorously for 5-6 minutes until edges are browned and the vegetable looks dry, not slimy. Remove okra and set aside.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT6M", "doneness_cues": {"visual": "Browned edges, lack of stringy slime", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "In the same pot, add onion, celery, and green pepper (the trinity). Saut\u00e9 for 5 minutes until softened. Add minced garlic, smoked paprika, thyme, and cayenne. Cook for 1 minute until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT6M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Add the rinsed rice to the pot. Stir constantly for 2 minutes to toast the grains and coat them in the oils.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Pour in the hot chicken broth and crushed tomatoes. Add the bay leaf and return the okra to the pot. Stir to combine, bringing the liquid to a boil.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Reduce heat to the lowest setting. Cover tightly with the lid. Simmer undisturbed for 18-20 minutes until the liquid is absorbed and rice is tender.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove pot from heat and let it stand, covered, for 10 minutes. While rice rests, slice the duck breast thinly against the grain.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Fluff the rice with a fork, discard the bay leaf, and serve topped with the sliced duck breast.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT40M", "passive_time": "PT20M", "total_time": "PT1H", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Dairy-Free", "Gluten-Free", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 542.51, "protein_g": 35.31, "carbohydrates_g": 85.15, "fat_g": 7.29, "saturated_fat_g": 1.36, "trans_fat_g": null, "monounsaturated_fat_g": 0.21, "polyunsaturated_fat_g": 0.29, "fiber_g": 7.45, "sugar_g": 9.2, "sodium_mg": 1174.06, "cholesterol_mg": null, "potassium_mg": 1104.97, "calcium_mg": 150.39, "iron_mg": 8.76, "magnesium_mg": 117.96, "phosphorus_mg": 406.2, "zinc_mg": 2.56, "vitamin_a_mcg": 147.37, "vitamin_c_mg": 92.25, "vitamin_d_mcg": null, "vitamin_e_mg": 0.73, "vitamin_k_mcg": 36.07, "vitamin_b6_mg": 0.38, "vitamin_b12_mcg": null, "thiamin_mg": 0.22, "riboflavin_mg": 0.12, "niacin_mg": 2.11, "folate_mcg": 59.98, "water_g": 119.2, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store rice and duck separately if possible to maintain skin texture on reheating.", "duration": "P3D"}, "freezer": {"notes": "Rice freezes well; duck breast texture may degrade slightly upon thawing.", "duration": "P1M"}, "reheating": "Reheat rice in a pan with a splash of water. Sear duck slices briefly in a hot pan just to warm through.", "does_not_keep": false}', '[{"name": "Dutch oven or heavy-bottomed pot with lid", "required": true, "alternative": null}, {"name": "Sharp chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Meat thermometer", "required": true, "alternative": null}]', '[{"symptom": "Okra texture is slimy or viscous", "likely_cause": "Okra was stewed in liquid without being fried in fat first", "prevention": "Ensure step 4 (high heat saut\u00e9 in fat) is done thoroughly before adding liquids", "fix": "Cannot be fixed once mixed with rice; texture is traditional in some gumbo styles, so proceed as is"}, {"symptom": "Rice is crunchy after cook time", "likely_cause": "Lid was not tight enough or heat was too high, evaporating liquid too fast", "prevention": "Use a heavy lid; do not peek during simmering", "fix": "Add 30-50ml hot water, cover quickly, and steam on very low heat for another 5 minutes"}]', '["Scoring the duck skin allows the fat to render efficiently, providing the cooking medium for the entire dish. Do not skip this step.", "Resting the duck breast before slicing is critical; cutting it straight from the pan will cause juices to run out, resulting in dry meat.", "The step of frying the okra in the duck fat (before adding liquid) is a technique specifically designed to ''lock'' the mucilage (slime) inside the pod.", "If you prefer the duck fully cooked through (well-done), you can dice the seared duck and fold it into the rice during step 7 instead of slicing it on top."]', '"This dish is a variation of Perloo (or Pilau), a staple of the South Carolina Lowcountry with deep roots in West African cuisine. It highlights the historical connection between rice cultivation, the introduction of okra by enslaved Africans, and French acadian influence in the preparation of game birds."', 542.51);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ef2b3118-17ea-4973-bb3f-316f7e752b6c', 'Broiled Sardine and Baby Spinach Salad', 'Smoky, crisp-skinned sardine fillets rest atop a bed of tender baby spinach, contrasted by the buttery crunch of golden pine nuts. A bright lemon-olive oil emulsion cuts through the richness of the oily fish, creating a balanced, elegant, and nutrient-dense light meal.', 'salad', 'Italian', 'Easy', '["italian", "salad", "sardine", "spinach", "easy", "quick", "weeknight", "gluten-free"]', '[{"group_name": "Sardines", "items": [{"name": "fresh sardine fillets", "quantity": 250, "unit": "g", "preparation": "butterfly fillets, skin-on", "notes": "approx. 8-10 fillets", "substitutions": ["canned sardines in oil (drained)", "mackerel fillets", "anchovies"], "ingredient_id": "70d88539-194b-465f-a02a-c7f7fc2f6a9e", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 10, "unit": "ml", "preparation": null, "notes": "for brushing", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "finely ground", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste (approx 0.5g)", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Salad Base", "items": [{"name": "pine nuts", "quantity": 20, "unit": "g", "preparation": "whole", "notes": null, "substitutions": ["slivered almonds", "chopped walnuts"], "ingredient_id": "971298ad-a9d7-49f7-811b-46afedad18d4", "nutrition_source": "Aggregated Public Data"}, {"name": "baby spinach", "quantity": 100, "unit": "g", "preparation": "washed and dried", "notes": null, "substitutions": ["arugula", "mixed greens"], "ingredient_id": "4734440a-226d-4d26-a110-3ed5c3bde93f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Lemon Vinaigrette", "items": [{"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "grated or minced to paste", "notes": "approx 4g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "red pepper flakes", "quantity": 1, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Place pine nuts in a dry small frying pan over medium heat. Toast, shaking the pan frequently, until golden brown and fragrant. Immediately remove from the hot pan to stop cooking.", "structured": {"action": "TOAST", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown color", "tactile": "Fragrant nutty aroma"}}, "tips": ["Pine nuts go from raw to burnt in seconds; do not walk away."]}, {"step_number": 2, "phase": "prep", "text": "Set the oven to broil (grill) on high setting. Arrange sardine fillets skin-side up on a baking sheet. Brush skins with olive oil and season generously with sea salt and black pepper.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Broil the sardines on the top rack, about 10-15 cm from the heating element, until the skin is blistered and crisp and the flesh is opaque. Target an internal temperature of 63\u00b0C/145\u00b0F.", "structured": {"action": "BROIL", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Skin is blistered and charred in spots", "tactile": "Flesh flakes easily with a fork"}}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "While sardines cook, whisk together extra virgin olive oil, lemon juice, grated garlic, and red pepper flakes in a small bowl until emulsified. Taste and adjust salt if necessary.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Toss the baby spinach with half of the dressing in a large bowl. Divide spinach between serving plates. Top with warm broiled sardines and sprinkle with toasted pine nuts. Drizzle remaining dressing over the fish.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT0M", "total_time": "PT15M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 190}', '{"flags": ["Pescatarian", "Gluten-Free", "Dairy-Free", "Low-Carb", "Keto", "Paleo", "Whole30", "Sugar-Free"], "not_suitable_for": ["Shellfish allergy (cross-contamination risk)", "Nut allergy"]}', '{"per_serving": {"calories": 1455.15, "protein_g": 3.69, "carbohydrates_g": 4.59, "fat_g": 158.85, "saturated_fat_g": 41.98, "trans_fat_g": null, "monounsaturated_fat_g": 62.35, "polyunsaturated_fat_g": 42.9, "fiber_g": 1.8, "sugar_g": 0.66, "sodium_mg": 428.97, "cholesterol_mg": 887.5, "potassium_mg": 371.08, "calcium_mg": 57.74, "iron_mg": 2.1, "magnesium_mg": 64.5, "phosphorus_mg": 83.77, "zinc_mg": 0.9, "vitamin_a_mcg": 244.97, "vitamin_c_mg": 17.96, "vitamin_d_mcg": 10.38, "vitamin_e_mg": 5.14, "vitamin_k_mcg": 258.9, "vitamin_b6_mg": 0.14, "vitamin_b12_mcg": null, "thiamin_mg": 0.05, "riboflavin_mg": 0.1, "niacin_mg": 0.43, "folate_mcg": 99.14, "water_g": 53.87, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Dressed salad does not keep. Store cooked sardines separately for up to 2 days.", "duration": null}, "freezer": {"notes": "Not suitable for freezing.", "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Small frying pan", "required": true, "alternative": "Toaster oven tray"}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": "Fork"}]', '[{"symptom": "Pine nuts are burnt black", "likely_cause": "Heat was too high or pan was not shaken enough", "prevention": "Watch constantly and remove from pan immediately once golden", "fix": "Discard and start over; burnt nuts taste extremely bitter"}, {"symptom": "Sardine skin is soggy", "likely_cause": "Oven wasn''t preheated fully or fish was too far from broiler", "prevention": "Ensure broiler is glowing red before inserting tray; keep tray near top", "fix": "Pat dry carefully and use a kitchen blowtorch if available"}]', '["If using canned sardines, skip the oil brushing step and broil for just 1-2 minutes to warm through and crisp the edges.", "For extra brightness, add zest from the lemon into the dressing before juicing it.", "Fresh sardines are delicate; handle them gently when transferring from the baking sheet to the salad to prevent them from breaking apart."]', '"This dish draws heavily from Sicilian and Southern Italian traditions, where ''sarde'' (sardines) are a staple protein often paired with the sweetness of pine nuts and the acidity of local lemons (agrumi)."', 1455.15);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ef8d3ff3-add0-43e9-bf01-d4455bca9a9c', 'Roasted Orchard Compote with Whisky & Ginger', 'A sophisticated twist on traditional stewed fruit. By roasting the apples and pears first, the natural sugars caramelize, creating a depth of flavor that pairs perfectly with the spicy warmth of candied ginger and the oaky notes of whisky.', 'dessert', 'Modern American', 'Easy', '["apple", "pear", "dessert", "side dish", "fall", "dairy-free", "gluten-free", "healthy", "high fiber", "vegan", "low-sodium"]', '[{"group_name": "Fruit Base", "items": [{"name": "apples", "quantity": 500, "unit": "g", "preparation": "peeled, cored, and cut into 2cm cubes", "notes": "Use firm varieties like Honeycrisp or Braeburn (approx. 3 medium apples)", "substitutions": ["quince"], "ingredient_id": "9985672b-aa9f-4125-8a32-62d520c99d6f", "nutrition_source": "USDA FoodData Central"}, {"name": "pears", "quantity": 500, "unit": "g", "preparation": "peeled, cored, and cut into 2cm cubes", "notes": "Use firm varieties like Bosc or Anjou (approx. 3 medium pears)", "substitutions": [], "ingredient_id": "ed5dd928-efa8-4c10-aeb3-3c08c94c62f8", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "coconut oil", "quantity": 15, "unit": "g", "preparation": "melted", "notes": null, "substitutions": ["vegan butter", "neutral oil"], "ingredient_id": "bfc74b81-e1e0-4607-9eec-8d0eff76d78c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Whisky Ginger Glaze", "items": [{"name": "maple syrup", "quantity": 60, "unit": "ml", "preparation": null, "notes": "Grade A dark color preferred", "substitutions": [], "ingredient_id": "1358a800-6e05-4bfd-ab71-03e78728c0bc", "nutrition_source": "Aggregated Public Data"}, {"name": "whisky", "quantity": 45, "unit": "ml", "preparation": null, "notes": "Bourbon or Rye works best", "substitutions": ["apple cider", "water"], "ingredient_id": "9ed9df30-333e-49cd-b72a-de1fbb793afe", "nutrition_source": "Aggregated Public Data"}, {"name": "candied ginger", "quantity": 30, "unit": "g", "preparation": "finely minced", "notes": null, "substitutions": [], "ingredient_id": "c152276a-6b59-4995-8015-d4b54c38f05a", "nutrition_source": "Aggregated Public Data"}, {"name": "ground cinnamon", "quantity": 2, "unit": "g", "preparation": null, "notes": "approx. 1/2 tsp", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 1, "unit": "g", "preparation": null, "notes": "pinch to enhance sweetness", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 200\u00b0C (400\u00b0F). Line a rimmed baking sheet with parchment paper for easy cleanup.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, toss the cubed apples and pears with the lemon juice immediately to prevent browning. Drizzle with the melted coconut oil and toss again until evenly coated.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Spread the fruit in a single layer on the prepared baking sheet. Roast for 20-25 minutes, stirring halfway through, until the fruit is tender and edges are beginning to turn golden brown.", "structured": {"action": "ROAST", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT25M", "doneness_cues": {"visual": "Edges golden brown", "tactile": "Fruit yields to gentle pressure but holds shape"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "While the fruit roasts, combine maple syrup, whisky, minced candied ginger, cinnamon, and salt in a small saucepan over medium-low heat. Simmer gently for 3-4 minutes to infuse the flavors and slightly reduce the liquid. Remove from heat and stir in the vanilla extract.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT4M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Transfer the hot roasted fruit back into the mixing bowl (or directly into the saucepan if large enough). Pour the warm whisky-ginger syrup over the fruit and fold gently to combine without crushing the fruit pieces.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Let the compote rest for at least 10 minutes before serving. This allows the fruit to absorb the spiced syrup.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT25M", "total_time": "PT40M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 180}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Low-Sodium", "Low-Fat"], "not_suitable_for": []}', '{"per_serving": {"calories": 268.89, "protein_g": 0.86, "carbohydrates_g": 53.63, "fat_g": 4.14, "saturated_fat_g": 3.16, "trans_fat_g": null, "monounsaturated_fat_g": 0.35, "polyunsaturated_fat_g": 0.24, "fiber_g": 7.28, "sugar_g": 40.08, "sodium_mg": 105.63, "cholesterol_mg": null, "potassium_mg": 318.44, "calcium_mg": 34.26, "iron_mg": 0.44, "magnesium_mg": 18.83, "phosphorus_mg": 29.75, "zinc_mg": 0.42, "vitamin_a_mcg": 5.08, "vitamin_c_mg": 12.6, "vitamin_d_mcg": null, "vitamin_e_mg": 0.4, "vitamin_k_mcg": 8.43, "vitamin_b6_mg": 0.09, "vitamin_b12_mcg": null, "thiamin_mg": 0.04, "riboflavin_mg": 0.08, "niacin_mg": 0.33, "folate_mcg": 13.28, "water_g": 216.17, "alcohol_g": 0.43, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Flavors meld further over time.", "duration": "P5D"}, "freezer": {"notes": "Texture may become softer upon thawing.", "duration": "P3M"}, "reheating": "Gently warm in a saucepan over low heat or microwave in short bursts.", "does_not_keep": false}', '[{"name": "Rimmed baking sheet", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}]', '[{"symptom": "Fruit turned into mush", "likely_cause": "Wrong fruit variety used or overcooked", "prevention": "Use firm baking apples (Honeycrisp, Granny Smith) and firm pears (Bosc); check doneness at 15 minutes", "fix": "Puree strictly to make a smooth applesauce instead"}, {"symptom": "Compote is too dry", "likely_cause": "Fruit had low water content or oven was too hot", "prevention": "Ensure fruit is fresh; monitor oven temperature", "fix": "Stir in 30-45ml of warm apple cider or water"}]', '["This compote bridges the gap between sweet and savory. It works beautifully as a dessert over coconut ice cream, or as a side dish for roast pork or duck.", "For the best texture, cut the pears slightly larger than the apples, as pears tend to soften faster in the oven.", "If you want to burn off more alcohol for a milder taste, add the whisky to the saucepan first and boil for 30 seconds before adding the maple syrup.", "Leftover syrup from the bottom of the pan makes an excellent sweetener for oatmeal or tea."]', '"While compotes originated in medieval Europe as a way to preserve fruit in sugar syrup, this version utilizes roasting\u2014a modern technique that concentrates flavor\u2014and incorporates New World bourbon whisky for a distinctly North American autumn profile."', 268.89);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('f04b057a-aec1-4beb-baab-a110aa902c2d', 'Ultimate Longsilog Breakfast Sandwich', 'A handheld reimagining of the classic Filipino breakfast (Longsilog). Sweet and garlicky skinless longganisa sausage patties are paired with a crispy fried egg and tangy atchara (pickled papaya) inside a warm, toasted pandesal roll. The perfect balance of savory, sweet, and acid.', 'breakfast', 'Filipino', 'Easy', '["sandwiches", "breakfast", "brunch", "easy", "filipino", "pork"]', '[{"group_name": "Skinless Longganisa Patties", "items": [{"name": "ground pork", "quantity": 300, "unit": "g", "preparation": "chilled", "notes": "at least 20% fat content for juiciness", "substitutions": [], "ingredient_id": "95b412ba-c68f-4b61-ae87-42b44000956b", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 6, "unit": null, "preparation": "minced", "notes": "approx 24g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "brown sugar", "quantity": 45, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "soy sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "cane vinegar", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["apple cider vinegar", "white vinegar"], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 3, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Assembly", "items": [{"name": "pandesal rolls", "quantity": 4, "unit": null, "preparation": null, "notes": "large size, approx 50g each", "substitutions": ["brioche buns", "soft potato rolls"], "ingredient_id": "a7145818-4713-4a6d-8dc2-54704cb5f44c", "nutrition_source": "Aggregated Public Data"}, {"name": "eggs", "quantity": 4, "unit": null, "preparation": null, "notes": "large", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "banana ketchup", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["tomato ketchup mixed with a pinch of sugar"], "ingredient_id": "88c421b6-c41d-4929-a7e6-58872d33e2e7", "nutrition_source": "Aggregated Public Data"}, {"name": "atchara", "quantity": 40, "unit": "g", "preparation": null, "notes": "pickled green papaya", "substitutions": ["quick pickled cucumber", "pickled daikon"], "ingredient_id": "71d6124c-3ce7-484b-8ec3-76a8bf451756", "nutrition_source": "Aggregated Public Data"}, {"name": "cooking oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c7015f51-6968-416e-9bf6-701813a23f85", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a mixing bowl, combine ground pork, minced garlic, brown sugar, soy sauce, vinegar, and black pepper. Mix thoroughly until the mixture becomes tacky and sticky.", "structured": {"action": "MIX", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Divide the pork mixture into 4 equal portions and shape them into flat, round patties slightly wider than your bread rolls (they will shrink during cooking). Let them rest for at least 15 minutes to marinate.", "structured": {"action": "SHAPE", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": ["If you have time, chill the patties in the fridge for 30 minutes to help them hold their shape better."]}, {"step_number": 3, "phase": "cook", "text": "Heat oil in a skillet over medium heat. Add the patties and cook for 3-4 minutes per side until dark golden brown and caramelized. The sugar content makes them burn easily, so watch the heat. Internal temperature should reach 71\u00b0C/160\u00b0F.", "structured": {"action": "FRY", "temperature": {"celsius": 71, "fahrenheit": 160}, "duration": "PT8M", "doneness_cues": {"visual": "dark golden brown caramelization", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Remove patties and set aside. In the same pan (keep the flavorful rendered fat!), crack the eggs and fry to your preference. Sunny-side up or over-easy works best for a runny yolk sauce.", "structured": {"action": "FRY", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "whites set, yolk runny", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Slice the pandesal rolls in half and lightly toast them. Spread banana ketchup on one side. Layer the longganisa patty, the fried egg, and a generous forkful of atchara on top. Close the sandwich and serve immediately.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT15M", "total_time": "PT40M", "overnight_required": false, "yields": "4 sandwiches", "yield_count": 4, "serving_size_g": 210}', '{"flags": ["Dairy-Free", "Nut-Free"], "not_suitable_for": ["Vegans", "Vegetarians", "Gluten-Free"]}', '{"per_serving": {"calories": 528.61, "protein_g": 24.34, "carbohydrates_g": 50.18, "fat_g": 27.51, "saturated_fat_g": 9.01, "trans_fat_g": 0.09, "monounsaturated_fat_g": 10.3, "polyunsaturated_fat_g": 4.41, "fiber_g": 1.87, "sugar_g": 21.96, "sodium_mg": 1043.7, "cholesterol_mg": 240, "potassium_mg": 347.57, "calcium_mg": 64.19, "iron_mg": 1.83, "magnesium_mg": 24.17, "phosphorus_mg": 241.27, "zinc_mg": 2.38, "vitamin_a_mcg": 87.7, "vitamin_c_mg": 2.4, "vitamin_d_mcg": 1, "vitamin_e_mg": 1.35, "vitamin_k_mcg": 1.48, "vitamin_b6_mg": 0.45, "vitamin_b12_mcg": 0.97, "thiamin_mg": 0.58, "riboflavin_mg": 0.41, "niacin_mg": 3.35, "folate_mcg": 27.67, "water_g": 90.03, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store cooked patties and assembled sandwiches separately. Best assembled fresh.", "duration": "P3D"}, "freezer": {"notes": "Raw formed patties freeze excellently.", "duration": "P1M"}, "reheating": "Reheat patties in a pan over medium heat; toast bread fresh.", "does_not_keep": false}', '[{"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Frying pan or skillet", "required": true, "alternative": null}, {"name": "Spatula", "required": true, "alternative": null}]', '[{"symptom": "Patties are burnt on the outside but raw inside", "likely_cause": "Heat was too high; the high sugar content caramelizes very quickly", "prevention": "Cook over medium to medium-low heat", "fix": "Finish cooking the patties in an oven or toaster oven at 175\u00b0C/350\u00b0F for 5 minutes"}]', '["Customization: You can replace the longganisa patty with a thick slice of fried Spam or corned beef hash patty for different ''Silog'' variations.", "The Bread: Traditional Pandesal is best, but a soft Brioche bun mimics the sweetness and texture well if you cannot find it.", "Texture: Don''t skip the Atchara (pickles). The longganisa is rich and sweet; the acidic crunch of the pickle is essential for balance.", "Garlic Lovers: For an extra kick, mix garlic powder into mayonnaise for a quick garlic aioli spread."]', '"This sandwich is a portable evolution of ''Longsilog'', a portmanteau of Longganisa (sausage), Sinangag (garlic fried rice), and Itlog (egg). While the traditional version requires a plate and spoon, this adaptation captures the quintessential Filipino breakfast flavor profile\u2014sweet, salty, and garlicky\u2014in a format suited for modern, busy mornings."', 528.61);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('f069a614-7e73-41ea-b5d9-01258bd1ca17', 'Warm Zesty Smashed Potato Salad', 'A textural hybrid combining the fluffy comfort of mashed potatoes with the bright, vinaigrette-dressed lightness of a warm potato salad. Crushed rather than pureed, these potatoes absorb a tangy lemon-mustard cream dressing while maintaining satisfying chunks, finished with fresh herbs and biting scallions.', 'side dish', 'Modern American', 'Easy', '["parsley", "potato", "potato salad", "rosemary", "scallion", "dinner", "lunch", "side dish", "warm salad", "comfort food"]', '[{"group_name": "Potatoes", "items": [{"name": "yukon gold or yellow potatoes", "quantity": 1000, "unit": "g", "preparation": "whole, scrubbed", "notes": "do not peel; skin adds texture", "substitutions": [], "ingredient_id": "90fa399c-54a2-461c-b410-868fba3bac36", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt", "quantity": 30, "unit": "g", "preparation": null, "notes": "for boiling water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Creamy Zesty Dressing", "items": [{"name": "cr\u00e8me fra\u00eeche", "quantity": 80, "unit": "g", "preparation": null, "notes": null, "substitutions": ["sour cream", "full-fat greek yogurt"], "ingredient_id": "df6e2dd4-e9e6-46bc-8d89-7f046d07a5ce", "nutrition_source": "Aggregated Public Data"}, {"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "whole grain mustard", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a60cae45-41bd-42f4-b2e3-f280bc62bba1", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 30, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "apple cider vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": null, "unit": null, "preparation": null, "notes": "from 1 lemon", "substitutions": [], "ingredient_id": "a5fb6a2a-dcda-4ab2-8fe6-472d7fcc39d1", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste (min 1g)", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Aromatics & Herbs", "items": [{"name": "scallions", "quantity": 4, "unit": null, "preparation": "thinly sliced", "notes": "separate whites and greens (~50g total)", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh rosemary", "quantity": 5, "unit": "g", "preparation": "finely minced", "notes": null, "substitutions": [], "ingredient_id": "fa90a3a7-86cd-40de-8f8c-0464231925c2", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Wash potatoes thoroughly. Prepare the herbs: mince the rosemary, chop the parsley, and slice the scallions, separating the white parts from the green tops.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Place whole potatoes in the large stockpot and cover with cold water by 2-3 cm. Add the 30g of sea salt. Bring to a boil over high heat, then reduce to a simmer. Cook for 20-25 minutes until completely tender when pierced with a knife.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT25M", "doneness_cues": {"visual": null, "tactile": "Knife slides through with zero resistance"}}, "tips": ["Starting with cold water ensures even cooking.", "Do not chop potatoes before boiling; cooking them whole prevents them from becoming waterlogged."]}, {"step_number": 3, "phase": "prep", "text": "While potatoes cook, whisk together cr\u00e8me fra\u00eeche, olive oil, whole grain mustard, lemon juice, vinegar, lemon zest, minced rosemary, and the white parts of the scallions in the large mixing bowl. Season with cracked black pepper.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Drain the potatoes in a colander. Return them to the empty hot pot and let them sit for 1-2 minutes off the heat to steam dry. This removes excess moisture and helps them absorb the dressing.", "structured": {"action": "STEAM", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Transfer the hot potatoes directly into the bowl with the dressing. Using a potato masher or fork, gently crush the potatoes. Aim for a mix of creamy broken bits and large chunks; do not puree into a smooth mash.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": {"visual": "Chunky, rustic texture with skins visible", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Fold the mixture gently to coat all chunks in the dressing. Let stand for 5 minutes to absorb flavors. Garnish generously with the chopped parsley and scallion greens before serving warm.", "structured": {"action": "FOLD", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT20M", "total_time": "PT35M", "overnight_required": false, "yields": "4-6 servings", "yield_count": 4, "serving_size_g": 220}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": ["Vegans (contains dairy)"]}', '{"per_serving": {"calories": 365.72, "protein_g": 6.31, "carbohydrates_g": 47.11, "fat_g": 19.03, "saturated_fat_g": 5.8, "trans_fat_g": null, "monounsaturated_fat_g": 8.24, "polyunsaturated_fat_g": 1.22, "fiber_g": 4.84, "sugar_g": 2.64, "sodium_mg": 3351.7, "cholesterol_mg": null, "potassium_mg": 897.63, "calcium_mg": 60.05, "iron_mg": 2.16, "magnesium_mg": 6.84, "phosphorus_mg": 128.07, "zinc_mg": 0.12, "vitamin_a_mcg": 83.97, "vitamin_c_mg": 49.13, "vitamin_d_mcg": null, "vitamin_e_mg": 1.74, "vitamin_k_mcg": 94.56, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": null, "thiamin_mg": 0.01, "riboflavin_mg": 0.02, "niacin_mg": 0.14, "folate_mcg": 16.77, "water_g": 26.87, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavor improves overnight; gently reheat or bring to room temperature before serving.", "duration": "P3D"}, "freezer": {"notes": "Do not freeze; the emulsion will break and potatoes will become grainy.", "duration": null}, "reheating": "Microwave gently at 50% power or warm in a covered pan with a splash of water.", "does_not_keep": false}', '[{"name": "Large stockpot", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Potato masher", "required": true, "alternative": "Large sturdy fork"}]', '[{"symptom": "Potatoes are gummy or gluey", "likely_cause": "Potatoes were overworked or a food processor was used", "prevention": "Never use a blender; only mash by hand and stop while still chunky", "fix": "Spread into a baking dish, top with breadcrumbs, and bake to create a crisp gratin texture to mask the gumminess"}, {"symptom": "Salad is watery/soupy", "likely_cause": "Potatoes were not steamed dry after draining", "prevention": "Allow potatoes to sit in the hot, empty pot for 2 minutes after draining to evaporate surface moisture", "fix": "Let it sit for 15 minutes; the starch will eventually absorb more liquid, or smash more of the chunks to thicken the sauce"}]', '["Dressing the potatoes while they are steaming hot is critical; as the starch molecules cool, they close up, but when hot, they drink up the vinaigrette.", "The ''white'' parts of the scallion provide a sharper onion bite similar to shallots, while the greens offer a fresh, grassy finish.", "Yukon Gold or yellow potatoes are the ideal choice here; russets will fall apart too much, and red waxy potatoes won''t absorb enough dressing.", "This dish bridges the gap between seasons\u2014hearty enough for winter, but bright enough for spring."]', '"This recipe is a modern fusion of the American comfort staple, mashed potatoes, and the French style of dressing warm potatoes with vinaigrette (Pommes \u00e0 l''Huile). It deconstructs the picnic potato salad to create a sophisticated side dish suitable for plated dinners."', 365.72);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('f0dc554b-c20d-4890-bcd2-6bcfcf9e0209', 'Tortilla de Patata con Cebolla', 'The quintessence of Spanish tapas: a thick, golden omelette featuring tender, olive-oil-poached potatoes and sweet caramelized onions encased in creamy, barely-set egg. A mastery of simple ingredients yielding a rich, comforting texture.', 'appetizer', 'Spanish', 'Intermediate', '["tortilla", "spanish", "potato", "egg", "onion", "tapas", "gluten-free"]', '[{"group_name": "Vegetable Base", "items": [{"name": "potatoes", "quantity": 800, "unit": "g", "preparation": "peeled and thinly sliced (3mm)", "notes": "Yukon Gold, Kennebec, or Monalisa varieties preferred", "substitutions": [], "ingredient_id": "a87814d3-a635-474b-a78d-4d20b45066e5", "nutrition_source": "Aggregated Public Data"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "diced or thinly sliced", "notes": "approx 200g", "substitutions": [], "ingredient_id": "cc868876-7ceb-46a8-b72a-c3e8a743ee97", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Confit Medium", "items": [{"name": "extra virgin olive oil", "quantity": 500, "unit": "ml", "preparation": null, "notes": "Quantity is for poaching; most will be drained and reused", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Binder", "items": [{"name": "eggs", "quantity": 6, "unit": null, "preparation": "large, room temperature", "notes": "approx 300g total weight", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "salt", "quantity": 8, "unit": "g", "preparation": null, "notes": "plus extra for seasoning eggs", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Peel the potatoes and slice them into thin, uneven chips (roughly 3mm thick). Peel and dice or slice the onions. Salt the vegetables lightly.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Thin, uniform slices", "tactile": null}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In the frying pan, heat the olive oil over medium heat. Carefully add the potatoes and onions. The oil should almost cover them. Lower heat to maintain a gentle bubble\u2014we are poaching (confit), not deep frying.", "structured": {"action": "POACH", "temperature": {"celsius": 120, "fahrenheit": 248}, "duration": "PT15M", "doneness_cues": {"visual": "Oil bubbling gently, not aggressively", "tactile": null}}, "tips": ["If the oil is too hot, the potatoes will brown too quickly before softening."]}, {"step_number": 3, "phase": "cook", "text": "Cook gently, stirring occasionally, until potatoes are tender enough to break with a spoon but not falling apart. Drain the mixture through a sieve into a heat-proof bowl, reserving the oil for future use.", "structured": {"action": "STRAIN", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": null, "tactile": "Potatoes break easily under pressure"}}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "In a large bowl, whisk the eggs vigorously with a pinch of salt until slightly frothy. Immediately add the hot, drained potato and onion mixture to the eggs. Fold to combine.", "structured": {"action": "WHISK", "temperature": null, "duration": null, "doneness_cues": {"visual": "Uniform yellow mixture", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Let the egg and potato mixture rest for 15 minutes. This allows the hot potatoes to slightly thicken the eggs and absorb flavor, essential for the creamy texture.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": "Mixture looks thickened and cohesive", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Wipe the pan clean and heat 15ml (1 tablespoon) of the reserved oil over medium-high heat until shimmering. Pour in the mixture. Shake the pan vigorously to prevent sticking.", "structured": {"action": "FRY", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Lower the heat to medium-low. Use a spatula to tuck the edges of the tortilla inwards to create the classic rounded shape. Cook until the bottom is golden and the sides are beginning to set, but the center is still runny.", "structured": {"action": "SHAPE", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Edges rounded, bottom golden", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "The Flip: Place a large plate or flat lid over the pan. Firmly hold the plate and pan together, then invert swiftly. Slide the tortilla back into the pan (uncooked side down). Use the spatula to tuck the edges in again to maintain the round shape.", "structured": {"action": "FLIP", "temperature": null, "duration": null, "doneness_cues": {"visual": "Tortilla inverted successfully", "tactile": null}}, "tips": ["Do this over the sink if you are nervous about spills."]}, {"step_number": 9, "phase": "finish", "text": "Cook for another 1-2 minutes for a soft, creamy center (''baveuse''), or 3-4 minutes for a fully set tortilla. Transfer to a clean plate.", "structured": {"action": "FRY", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": null, "tactile": "Springy to the touch"}}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Allow to cool for at least 15 minutes before serving. It is traditionally served warm or at room temperature, not piping hot.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT15M", "total_time": "PT45M", "overnight_required": false, "yields": "1 round tortilla (8 wedges)", "yield_count": 8, "serving_size_g": 125}', '{"flags": ["Vegetarian", "Gluten-Free", "Dairy-Free", "Nut-Free", "Soy-Free", "Paleo", "Whole30"], "not_suitable_for": []}', '{"per_serving": {"calories": 698.63, "protein_g": 7.08, "carbohydrates_g": 20.22, "fat_g": 66.44, "saturated_fat_g": 9.8, "trans_fat_g": 0.02, "monounsaturated_fat_g": 47, "polyunsaturated_fat_g": 7.28, "fiber_g": 8.52, "sugar_g": 2.35, "sodium_mg": 445, "cholesterol_mg": 139.5, "potassium_mg": 542.71, "calcium_mg": 35.62, "iron_mg": 1.57, "magnesium_mg": 28.01, "phosphorus_mg": 132.75, "zinc_mg": 0.83, "vitamin_a_mcg": 60, "vitamin_c_mg": 21.03, "vitamin_d_mcg": 0.75, "vitamin_e_mg": 9.39, "vitamin_k_mcg": 37.74, "vitamin_b6_mg": 0.06, "vitamin_b12_mcg": 0.33, "thiamin_mg": 0.02, "riboflavin_mg": 0.17, "niacin_mg": 0.03, "folate_mcg": 17.63, "water_g": 28.58, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best eaten fresh, but can be refrigerated. Texture becomes denser.", "duration": "P2D"}, "freezer": {"notes": "Do not freeze; texture of potatoes will degrade significantly.", "duration": null}, "reheating": "Serve at room temperature or warm gently in a low oven; do not microwave to avoid rubbery eggs.", "does_not_keep": false}', '[{"name": "Non-stick frying pan (20-24cm)", "required": true, "alternative": "Well-seasoned carbon steel pan"}, {"name": "Large flat plate or lid", "required": true, "alternative": "Large cutting board (for flipping)"}, {"name": "Slotted spoon", "required": true, "alternative": null}, {"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Fine-mesh sieve", "required": true, "alternative": "Colander"}]', '[{"symptom": "Tortilla sticks to the pan during the flip", "likely_cause": "Pan surface damaged or heat was too low to sear the proteins", "prevention": "Use a dedicated non-stick pan and ensure oil is hot before pouring eggs", "fix": "Scrape it out, call it ''Tortilla Rota'' (broken tortilla), and serve as a scramble"}, {"symptom": "Center is dry and rubbery", "likely_cause": "Overcooked", "prevention": "Reduce cooking time on the second side; residual heat continues to cook the eggs", "fix": "Serve with mayonnaise or aioli to add moisture"}]', '["The soaking step (Step 5) is non-negotiable. It allows the hot potatoes to pre-cook the eggs slightly, creating the signature custardy interior.", "Do not discard the frying oil. It is now infused with potato and onion flavor, perfect for cooking other dishes.", "For the most authentic shape, use a smaller, deeper pan (20cm) rather than a wide, shallow one.", "If using a mandoline for potatoes, watch your fingers carefully."]', '"The Tortilla Espa\u00f1ola is the national dish of Spain, originating in the 19th century as a humble, caloric meal for the poor during the Carlist Wars. While the inclusion of onion (''con cebolla'' vs ''sin cebolla'') is a subject of passionate national debate, this version embraces the sweetness and moisture that onions provide."', 698.63);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('f155a3e9-968c-4879-b58a-d8dd3958bac7', 'Roasted Banana & Cocoa Butter Gelato', 'A luxuriously creamy dairy-free gelato where roasted bananas provide caramelized depth and natural pectin. The cocoa butter provides structural firmness and a velvety mouthfeel lacking in many vegan ice creams, bridging the gap between coconut milk and cashew milk.', 'dessert', 'Modern Vegan', 'Intermediate', '["vegan", "dairy-free", "ice cream", "banana", "cashew", "coconut", "dessert", "make-ahead", "plan-ahead"]', '[{"group_name": "Fruit Base", "items": [{"name": "ripe bananas", "quantity": 4, "unit": null, "preparation": "peeled", "notes": "approximately 450g before roasting; skins must be spotty or brown", "substitutions": [], "ingredient_id": "d01cd7bd-9b20-4ccf-8475-27ca2843edf6", "nutrition_source": "USDA FoodData Central"}, {"name": "brown sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": "for roasting", "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Cream Base", "items": [{"name": "full-fat coconut milk", "quantity": 400, "unit": "ml", "preparation": "canned", "notes": "do not use ''lite'' coconut milk", "substitutions": [], "ingredient_id": "c037ee7e-e3ed-4340-b8fb-d8ad284ba96e", "nutrition_source": "USDA FoodData Central"}, {"name": "unsweetened cashew milk", "quantity": 240, "unit": "ml", "preparation": null, "notes": "use a creamy variety or homemade", "substitutions": [], "ingredient_id": "deb23330-6bb4-40b6-8bc4-62b12ce22724", "nutrition_source": "Aggregated Public Data"}, {"name": "food-grade cocoa butter", "quantity": 50, "unit": "g", "preparation": "solid", "notes": "chopped chunks or wafers", "substitutions": [], "ingredient_id": "06b4ad66-f77e-4a4c-90d6-2521285342b2", "nutrition_source": "USDA FoodData Central"}, {"name": "brown sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": "adjust based on banana sweetness", "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "vodka or dark rum", "quantity": 15, "unit": "ml", "preparation": null, "notes": "alcohol lowers freezing point for softer scoop", "substitutions": [], "ingredient_id": "ca2fa4fe-d61a-4ff2-b755-38ba94fd7a80", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 200\u00b0C/400\u00b0F. Line a baking sheet with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Slice the peeled bananas in half lengthwise and place them on the baking sheet. Sprinkle with the 30g of brown sugar.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Roast the bananas for 20-25 minutes until they are soft, golden brown, and bubbling with caramelization.", "structured": {"action": "ROAST", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT25M", "doneness_cues": {"visual": "Golden brown and bubbling", "tactile": "Very soft/mushy"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "While bananas roast, combine the cocoa butter and 100ml of the coconut milk in a small saucepan over low heat. Stir gently until the cocoa butter is completely melted. Remove from heat immediately.", "structured": {"action": "MELT", "temperature": null, "duration": null, "doneness_cues": {"visual": "Uniform liquid oil", "tactile": "Smooth no solids"}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Transfer the hot roasted bananas (and any juices from the pan), the melted cocoa butter mixture, remaining coconut milk, cashew milk, remaining 100g brown sugar, salt, and vanilla into a high-speed blender. Blend on high for 60 seconds until completely smooth and emulsified.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": ["Blending while the fats (cocoa butter) are warm ensures a proper emulsion, preventing a greasy mouthfeel."]}, {"step_number": 6, "phase": "finish", "text": "Pour the mixture into a sealed container and refrigerate for at least 4 hours, or ideally overnight, until the base is completely cold (4\u00b0C/40\u00b0F).", "structured": {"action": "CHILL", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT4H", "doneness_cues": null}, "tips": ["If the mixture thickens significantly in the fridge due to the cocoa butter, give it a quick whisk before churning."]}, {"step_number": 7, "phase": "finish", "text": "Stir in the alcohol (if using) into the cold base. Pour into your ice cream maker and churn according to manufacturer instructions, usually 20-25 minutes, until it resembles soft serve.", "structured": {"action": "MIX", "temperature": null, "duration": "PT25M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Transfer to a freezer-safe container. Press parchment paper directly onto the surface to prevent ice crystals. Freeze for at least 4 hours to firm up before scooping.", "structured": {"action": "FREEZE", "temperature": null, "duration": "PT4H", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT12H", "total_time": "PT12H45M", "overnight_required": true, "yields": "1 liter", "yield_count": 8, "serving_size_g": 125}', '{"flags": ["Vegan", "Dairy-Free", "Gluten-Free", "Soy-Free", "Egg-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 297.49, "protein_g": 2.08, "carbohydrates_g": 31.99, "fat_g": 18.94, "saturated_fat_g": 14.34, "trans_fat_g": null, "monounsaturated_fat_g": 2.58, "polyunsaturated_fat_g": 0.36, "fiber_g": 2.56, "sugar_g": 24.45, "sodium_mg": 157.74, "cholesterol_mg": null, "potassium_mg": 356.38, "calcium_mg": 159.5, "iron_mg": 1.08, "magnesium_mg": 35.3, "phosphorus_mg": 63.19, "zinc_mg": 0.43, "vitamin_a_mcg": 46.69, "vitamin_c_mg": 6.29, "vitamin_d_mcg": null, "vitamin_e_mg": 0.24, "vitamin_k_mcg": 1.88, "vitamin_b6_mg": 0.23, "vitamin_b12_mcg": null, "thiamin_mg": 0.03, "riboflavin_mg": 0.04, "niacin_mg": 0.78, "folate_mcg": 19.41, "water_g": 78.06, "alcohol_g": 1.06, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Do not store in refrigerator; transfer to freezer immediately after churning.", "duration": null}, "freezer": {"notes": "Store in an airtight container with a piece of parchment paper pressed against the surface to prevent ice crystals.", "duration": "P1M"}, "reheating": null, "does_not_keep": false}', '[{"name": "Oven", "required": true, "alternative": null}, {"name": "Baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "High-speed blender", "required": true, "alternative": "Food processor (may yield slightly grainier texture)"}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Ice cream maker", "required": true, "alternative": "Shallow pan for granita method (requires manual scraping)"}, {"name": "Airtight freezer container", "required": true, "alternative": null}]', '[{"symptom": "Ice cream is rock hard after freezing", "likely_cause": "Low water content and high cocoa butter freezing point", "prevention": "Add the optional alcohol or allow to sit at room temperature for 10-15 minutes before serving", "fix": "Microwave for 10 seconds on low power to soften slightly"}, {"symptom": "Waxy film on roof of mouth", "likely_cause": "Cocoa butter did not emulsify properly or mixture wasn''t blended hot", "prevention": "Ensure high-speed blending when ingredients are warm", "fix": "Cannot be fixed once frozen"}]', '["The ripeness of the bananas is non-negotiable; they must have brown spots. Green or yellow bananas will result in a starchy, bland gelato.", "Cocoa butter is the secret ingredient here; it mimics the ''bite'' and slow melt of dairy cream better than coconut oil, which melts too quickly.", "If you want a ''stracciatella'' effect, drizzle melted chocolate into the churner during the last minute of mixing.", "Roasting the bananas evaporates excess water, which concentrates the flavor and significantly reduces iciness in the final product."]', '"While traditional gelato relies on milk, cream, and eggs, this recipe utilizes modern plant-based pastry techniques. The use of cocoa butter to structure vegan fats is a technique borrowed from high-end chocolatiers and vegan patisserie to replicate the mouthfeel of dairy fats without using hydrogenated oils."', 297.49);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('f31bf994-c967-40af-a8f6-b1822ba4e9eb', 'Dark Cherry & Hazelnut Biscotti', 'Traditional twice-baked Italian cookies featuring a shattering, crisp texture perfect for dipping in coffee or Vin Santo. The earthy crunch of toasted hazelnuts pairs elegantly with the chewy, tart sweetness of dark dried cherries and a hint of orange zest.', 'baked good', 'Italian', 'Intermediate', '["biscotti", "cookies", "dessert", "hazelnut", "cherry", "italian", "coffee-companion"]', '[{"group_name": "Inclusions", "items": [{"name": "raw hazelnuts", "quantity": 130, "unit": "g", "preparation": "whole, skin-on or blanched", "notes": null, "substitutions": [], "ingredient_id": "4a2947d7-4339-48a9-89b7-039c446295e4", "nutrition_source": "Aggregated Public Data"}, {"name": "dried tart cherries", "quantity": 110, "unit": "g", "preparation": "roughly chopped if large", "notes": null, "substitutions": [], "ingredient_id": "005de8eb-74c0-482b-866a-d194645f353e", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Dough", "items": [{"name": "all-purpose flour", "quantity": 315, "unit": "g", "preparation": null, "notes": "plus extra for dusting", "substitutions": [], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "granulated sugar", "quantity": 200, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": "melted and cooled slightly", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "eggs", "quantity": 3, "unit": null, "preparation": "large, room temperature", "notes": "approx. 150g total (without shell)", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "baking powder", "quantity": 8, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c119cded-8cf7-4a52-80b8-03c25d8efa50", "nutrition_source": "USDA FoodData Central"}, {"name": "fine sea salt", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5245d064-3efa-48b3-9dca-6dfa7c398bb2", "nutrition_source": "USDA FoodData Central"}, {"name": "orange zest", "quantity": 1, "unit": null, "preparation": null, "notes": "from 1 medium orange", "substitutions": [], "ingredient_id": "a644a589-02d1-4b90-98c5-ec79373a767b", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 175\u00b0C (350\u00b0F). Spread the hazelnuts on a baking sheet and toast for 8-10 minutes until fragrant and skins begin to crack.", "structured": {"action": "TOAST", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT10M", "doneness_cues": {"visual": "Skins cracking and nuts golden", "tactile": "Hot and fragrant"}}, "tips": ["If using skin-on hazelnuts, wrap warm nuts in a kitchen towel and rub vigorously to remove loose skins."]}, {"step_number": 2, "phase": "prep", "text": "Reduce oven temperature to 160\u00b0C (320\u00b0F). Line a large baking sheet with parchment paper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "In a large bowl, whisk together the melted butter, sugar, eggs, vanilla extract, and orange zest until well combined and slightly lightened in color.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Sift in the flour, baking powder, and salt. Mix gently with a spatula until just combined and few flour streaks remain. Do not overmix.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": {"visual": "Shaggy, sticky dough formed", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Fold in the toasted hazelnuts (chopped roughly if preferred, or left whole) and dried cherries until evenly distributed.", "structured": {"action": "FOLD", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "shape", "text": "Divide the dough in half. With flour-dusted hands, shape each half into a log approximately 25cm (10 inches) long and 5cm (2 inches) wide directly on the prepared baking sheet. Space them at least 8cm apart as they will spread.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Two smooth, flattened logs", "tactile": null}}, "tips": ["The dough will be sticky; keep hands well-floured or slightly damp to prevent sticking."]}, {"step_number": 7, "phase": "cook", "text": "Bake for 25-30 minutes at 160\u00b0C (320\u00b0F) until the logs are golden brown and firm to the touch in the center.", "structured": {"action": "BAKE", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT25M", "doneness_cues": {"visual": null, "tactile": "Firm center, springs back slightly"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove from oven and let the logs cool on the sheet for exactly 15-20 minutes. Maintain oven temperature at 160\u00b0C (320\u00b0F).", "structured": {"action": "COOL", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": ["Cooling is critical. If sliced too hot, they crumble; too cold, they crack."]}, {"step_number": 9, "phase": "finish", "text": "Transfer logs to a cutting board. Using a serrated knife and a sawing motion, cut logs diagonally into 1.5cm (0.5 inch) thick slices. Arrange slices cut-side down back on the baking sheet.", "structured": {"action": "SLICE", "temperature": null, "duration": null, "doneness_cues": {"visual": "Clean slices without heavy crumbling", "tactile": null}}, "tips": []}, {"step_number": 10, "phase": "cook", "text": "Bake for a second time for 15-20 minutes, flipping the biscotti halfway through, until they are dry and crisp. They will harden further as they cool.", "structured": {"action": "BAKE", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT15M", "doneness_cues": {"visual": null, "tactile": "Hard and dry to the touch"}}, "tips": []}, {"step_number": 11, "phase": "finish", "text": "Transfer to a wire rack to cool completely before storing.", "structured": {"action": "COOL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT1H10M", "total_time": "PT1H45M", "overnight_required": false, "yields": "24 biscotti", "yield_count": 24, "serving_size_g": 35}', '{"flags": ["Vegetarian", "Peanut-Free", "Soy-Free"], "not_suitable_for": ["Nut allergies"]}', '{"per_serving": {"calories": 157.23, "protein_g": 3.04, "carbohydrates_g": 23.19, "fat_g": 6.09, "saturated_fat_g": 1.73, "trans_fat_g": null, "monounsaturated_fat_g": 0.83, "polyunsaturated_fat_g": 0.26, "fiber_g": 1.03, "sugar_g": 11.72, "sodium_mg": 94.12, "cholesterol_mg": 28.63, "potassium_mg": 78.51, "calcium_mg": 34.19, "iron_mg": 0.59, "magnesium_mg": 13.71, "phosphorus_mg": 51.88, "zinc_mg": 0.32, "vitamin_a_mcg": 33.93, "vitamin_c_mg": 1.44, "vitamin_d_mcg": 0.13, "vitamin_e_mg": 0.14, "vitamin_k_mcg": 0.47, "vitamin_b6_mg": 0.02, "vitamin_b12_mcg": 0.06, "thiamin_mg": 0.02, "riboflavin_mg": 0.04, "niacin_mg": 0.21, "folate_mcg": 6.93, "water_g": 7.62, "alcohol_g": 0.07, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Do not refrigerate; humidity softens the texture.", "duration": null}, "freezer": {"notes": "Freeze baked biscotti in airtight containers. Thaw at room temperature.", "duration": "P3M"}, "reheating": "If they soften, recrisp in a 150\u00b0C oven for 5 minutes.", "does_not_keep": false}', '[{"name": "Large baking sheet", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": "Silicone baking mat"}, {"name": "Serrated bread knife", "required": true, "alternative": "Very sharp chef''s knife (less ideal)"}, {"name": "Stand mixer or hand mixer", "required": false, "alternative": "Whisk and sturdy spatula"}, {"name": "Wire cooling rack", "required": true, "alternative": null}]', '[{"symptom": "Dough crumbles excessively when slicing", "likely_cause": "The logs were sliced while still too hot or using a dull/straight-edge knife", "prevention": "Allow logs to cool for 20 minutes; use a sharp serrated bread knife", "fix": "Wait 10 more minutes for the remaining log to cool; use a gentle sawing motion"}, {"symptom": "Biscotti are not crunchy enough", "likely_cause": "Second bake was too short or oven humidity was high", "prevention": "Ensure they are golden on the cut sides before removing", "fix": "Return to oven at 140\u00b0C (285\u00b0F) for 10-15 minutes to dry out further"}]', '["Use a serrated bread knife for slicing. A straight-edged chef''s knife will compress the dough and cause the hazelnuts to shatter the cookie structure.", "For a glossy finish, you can brush the logs with an egg wash (1 egg beaten with 1 tbsp water) before the first bake, though this softens the crust slightly.", "Orange zest acts as a bridge flavor, connecting the earthy hazelnut with the tart cherry. Do not skip it.", "If your dried cherries are very hard or old, soak them in warm water for 10 minutes and pat strictly dry before using to prevent tough rocks in your cookies."]', '"Biscotti, specifically ''Biscotti di Prato'' or Cantucci, originated in Tuscany, Italy. The name derives from the Latin ''bis coctus'', meaning twice-cooked. Historically, this double-baking method was used to create durable, travel-ready food for Roman legions, as the lack of moisture prevented mold and spoilage."', 157.23);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('f325b193-435c-4d78-abaa-f3b741647729', 'Zero-Waste Creamy Asparagus Soup', 'A vibrant, velvety soup that maximizes flavor by utilizing asparagus woody ends to create a rich vegetable base stock. The result is deeply aromatic, bright green, and naturally thickened with potato rather than cream.', 'soup', 'French', 'Easy', '["asparagus", "great leftovers", "leek", "potato", "soup", "dinner", "weeknight", "appetizer", "spring", "healthy", "vegan", "vegetarian"]', '[{"group_name": "Asparagus Prep", "items": [{"name": "fresh asparagus", "quantity": 1000, "unit": "g", "preparation": "whole", "notes": "Woody ends reserved for stock; tender stalks chopped for soup", "substitutions": [], "ingredient_id": "8a2a9426-3755-4553-953a-fd9cf42cef90", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 1500, "unit": "ml", "preparation": null, "notes": "For the stock", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Soup Base", "items": [{"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": "extra virgin", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "leeks", "quantity": 2, "unit": null, "preparation": "white and light green parts only, sliced", "notes": "approx 200g cleaned weight", "substitutions": [], "ingredient_id": "f0bddafa-51db-4e56-954b-18624daa6fa4", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "yukon gold potatoes", "quantity": 250, "unit": "g", "preparation": "peeled and diced", "notes": "approx 2 medium potatoes", "substitutions": [], "ingredient_id": "a9d640ff-a969-4f0a-9a92-974f376ac272", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Finishing", "items": [{"name": "lemon juice", "quantity": 15, "unit": "ml", "preparation": "freshly squeezed", "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly ground", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Snap the woody ends off the asparagus spears. Reserve the tough ends for the stock. Chop the tender stalks into 2-inch pieces and set aside.", "structured": {"action": "SNAP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Place the woody asparagus ends in a large pot and cover with 1500ml of water. Bring to a boil, then reduce heat and simmer for 20 minutes to extract flavor.", "structured": {"action": "SIMMER", "temperature": {"celsius": 95, "fahrenheit": 203}, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Strain the asparagus stock through a fine mesh sieve into a bowl, pressing on the solids to extract all liquid. Discard the boiled woody ends. Wipe out the pot.", "structured": {"action": "STRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "In the same pot, heat the olive oil over medium heat. Add the sliced leeks and a pinch of salt. Saut\u00e9 gently for 5-7 minutes until softened but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT7M", "doneness_cues": {"visual": "Leeks are translucent", "tactile": "Soft texture"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the minced garlic and diced potatoes to the pot. Stir for 1 minute until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Pour in the prepared asparagus stock (you should have about 1000-1200ml; add water if needed). Bring to a simmer and cook for 10-15 minutes until potatoes are tender.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT15M", "doneness_cues": {"visual": null, "tactile": "Potatoes pierce easily with a fork"}}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Add the reserved tender asparagus stalks to the pot. Simmer for only 3-5 minutes. The asparagus should be tender but still bright green.", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Bright vibrant green", "tactile": null}}, "tips": ["Do not overcook at this stage or the soup will turn olive-drab."]}, {"step_number": 8, "phase": "finish", "text": "Remove from heat immediately. Blend the soup until completely smooth using an immersion blender. Stir in the lemon juice, salt, and pepper.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": ["If using a standard blender, vent the lid and blend in batches to prevent explosion from steam."]}]', '{"active_time": "PT25M", "passive_time": "PT25M", "total_time": "PT50M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Vegetarian", "Vegan", "Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Paleo", "Whole30"], "not_suitable_for": []}', '{"per_serving": {"calories": 206.48, "protein_g": 7.89, "carbohydrates_g": 30.84, "fat_g": 8.05, "saturated_fat_g": 1.14, "trans_fat_g": null, "monounsaturated_fat_g": 5.48, "polyunsaturated_fat_g": 0.92, "fiber_g": 8.44, "sugar_g": 7.55, "sodium_mg": 520.78, "cholesterol_mg": null, "potassium_mg": 1009.79, "calcium_mg": 107.34, "iron_mg": 6.92, "magnesium_mg": 80.58, "phosphorus_mg": 208.06, "zinc_mg": 1.45, "vitamin_a_mcg": 157.45, "vitamin_c_mg": 35.13, "vitamin_d_mcg": null, "vitamin_e_mg": 3.92, "vitamin_k_mcg": 108.76, "vitamin_b6_mg": 0.26, "vitamin_b12_mcg": null, "thiamin_mg": 0.36, "riboflavin_mg": 0.35, "niacin_mg": 2.47, "folate_mcg": 130.85, "water_g": 612.95, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Color may darken slightly upon reheating due to oxidation.", "duration": "P4D"}, "freezer": {"notes": "Texture may slightly separate; blend briefly after thawing and reheating.", "duration": "P3M"}, "reheating": "Reheat gently on the stove; do not boil vigorously to preserve the green color.", "does_not_keep": false}', '[{"name": "Large pot or Dutch oven", "required": true, "alternative": null}, {"name": "Fine mesh sieve or strainer", "required": true, "alternative": null}, {"name": "Blender (Immersion or Stand)", "required": true, "alternative": "Food processor (result will be less smooth)"}, {"name": "Vegetable peeler", "required": false, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}]', '[{"symptom": "Soup has stringy fibers", "likely_cause": "Asparagus was too mature or not peeled near the base", "prevention": "Snap asparagus naturally where it breaks; peel the bottom inch of thick spears", "fix": "Pass the final blended soup through a fine mesh sieve (chinois)"}]', '["Reserve a few raw asparagus tips, blanch them separately for 1 minute, and use them as a garnish for a professional look.", "This soup is excellent served cold (Vichyssoise style) on hot days. If serving cold, you may need slightly more salt as cold suppresses flavor perception.", "For an extra velvety texture, swirl in a tablespoon of high-quality olive oil or coconut cream right before serving.", "Using the woody ends for stock extracts free glutamates, adding a savory depth (umami) that water or commercial vegetable broth cannot match."]', '"Asparagus soup is a harbinger of spring in European cuisine, particularly celebrated in French and German traditions (Spargelsuppe). This ''nose-to-tail'' vegetable approach reflects modern sustainable cooking while adhering to classic peasant cooking wisdom where nothing is wasted."', 206.48);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('f3735820-6a0f-42f8-82ec-4f32321e12db', 'Sopa de Pollo con Fideos', 'A comforting, rustic Mexican chicken soup characterized by thin noodles that are toasted golden brown before simmering. The broth is infused with a roasted tomato base and finished with bright, textural garnishes like creamy avocado and salty cheese.', 'soup', 'Mexican', 'Intermediate', '["mexican", "chicken", "chicken soup", "tomato", "main course", "comfort food", "one pot"]', '[{"group_name": "Tomato Recaudo (Base)", "items": [{"name": "roma tomatoes", "quantity": 400, "unit": "g", "preparation": "roughly chopped", "notes": "about 4 medium tomatoes", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "white onion", "quantity": 100, "unit": "g", "preparation": "roughly chopped", "notes": "about 1/2 small onion", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 2, "unit": null, "preparation": null, "notes": "approx 10g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Soup & Chicken", "items": [{"name": "vegetable oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "boneless skinless chicken thighs", "quantity": 500, "unit": "g", "preparation": "cut into 2cm pieces", "notes": null, "substitutions": [], "ingredient_id": "d7fc1bf9-fc05-429b-bfa6-2ad857cb0bb6", "nutrition_source": "USDA FoodData Central"}, {"name": "fideo noodles", "quantity": 200, "unit": "g", "preparation": null, "notes": "or vermicelli/capellini broken into 3cm lengths", "substitutions": ["angel hair pasta", "vermicelli"], "ingredient_id": "1cc9392b-b25e-4be0-97a7-f607e53bc682", "nutrition_source": "USDA FoodData Central"}, {"name": "chicken broth", "quantity": 1500, "unit": "ml", "preparation": "low sodium", "notes": null, "substitutions": [], "ingredient_id": "b7b1f4fd-8e57-472e-abae-d4f24d5b5c85", "nutrition_source": "Aggregated Public Data"}, {"name": "carrots", "quantity": 150, "unit": "g", "preparation": "diced small", "notes": null, "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, start with 5g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnishes", "items": [{"name": "avocado", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx 200g", "substitutions": [], "ingredient_id": "2f40a31e-80a0-4265-b6f3-99ed88ee4c24", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "serrano or jalape\u00f1o pepper", "quantity": 1, "unit": null, "preparation": "thinly sliced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "6cdb0615-378e-4bfa-b76d-f19bbd780e6c", "nutrition_source": "Aggregated Public Data"}, {"name": "queso fresco", "quantity": 60, "unit": "g", "preparation": "crumbled", "notes": null, "substitutions": ["mild feta", "cotija"], "ingredient_id": "06a3e21a-6384-47ca-b519-1fc3a0af27b4", "nutrition_source": "USDA FoodData Central"}, {"name": "lime wedges", "quantity": 4, "unit": null, "preparation": null, "notes": "for serving", "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine the Roma tomatoes, white onion, garlic, and water in a blender. Blend on high until completely smooth to create the ''recaudo''. Set aside.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Heat half the oil in a Dutch oven over medium-high heat. Season chicken pieces with a pinch of salt. Sear the chicken until browned on the outside but not fully cooked through. Remove chicken to a plate.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT6M", "doneness_cues": {"visual": "Golden brown crust", "tactile": null}}, "tips": ["Don''t overcrowd the pan; sear in batches if necessary to avoid steaming the meat."]}, {"step_number": 3, "phase": "cook", "text": "Add the remaining oil to the pot. Add the fideo noodles (or broken vermicelli). Stir constantly and fry until the noodles turn a deep golden brown and smell nutty. Watch closely as they can burn in seconds.", "structured": {"action": "FRY", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Deep golden brown color", "tactile": "Crispy texture"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Pour the blended tomato mixture directly onto the hot noodles (it will splatter). Cook, stirring frequently, until the mixture darkens and thickens, about 5 minutes. This ''searing'' of the sauce is crucial for flavor.", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT5M", "doneness_cues": {"visual": "Sauce turns from bright red to rusty orange/red", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Return the chicken and any accumulated juices to the pot. Add the chicken broth and diced carrots. Bring to a boil, then reduce heat to low and simmer until the chicken is cooked through (internal temp 74\u00b0C/165\u00b0F) and noodles are tender.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Taste the broth and adjust salt if needed. Serve hot in bowls, topped generously with diced avocado, crumbled queso fresco, cilantro, sliced green chiles, and a squeeze of fresh lime juice.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT25M", "total_time": "PT55M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 1713.6, "protein_g": 38.76, "carbohydrates_g": 217.3, "fat_g": 74.96, "saturated_fat_g": 24.47, "trans_fat_g": 0.17, "monounsaturated_fat_g": 7.97, "polyunsaturated_fat_g": 2.59, "fiber_g": 7.5, "sugar_g": 195.64, "sodium_mg": 52088.6, "cholesterol_mg": 142.35, "potassium_mg": 1205.98, "calcium_mg": 168.88, "iron_mg": 3.36, "magnesium_mg": 78.35, "phosphorus_mg": 442.66, "zinc_mg": 3.37, "vitamin_a_mcg": 440.41, "vitamin_c_mg": 39.2, "vitamin_d_mcg": 0.41, "vitamin_e_mg": 1.72, "vitamin_k_mcg": 20, "vitamin_b6_mg": 0.86, "vitamin_b12_mcg": 1.06, "thiamin_mg": 0.35, "riboflavin_mg": 0.45, "niacin_mg": 9.34, "folate_mcg": 102.96, "water_g": 263.02, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Noodles will continue to absorb broth; add a splash of water or stock when reheating.", "duration": "P3D"}, "freezer": {"notes": "Freeze without garnishes. Texture of noodles may soften slightly upon thawing.", "duration": "P2M"}, "reheating": "Simmer gently on stove until hot. Avoid boiling vigorously to preserve noodle integrity.", "does_not_keep": false}', '[{"name": "Blender", "required": true, "alternative": null}, {"name": "Dutch oven or large heavy-bottomed pot", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Noodles are mushy or disintegrating", "likely_cause": "Noodles were not fried enough or soup was simmered too vigorously", "prevention": "Ensure noodles are fried until distinctly golden and brown before adding liquid; simmer gently.", "fix": "Cannot be fixed, but broth will still taste good. Serve immediately."}, {"symptom": "Broth tastes flat or watery", "likely_cause": "Tomato base was not cooked down enough", "prevention": "Cook the tomato puree until it changes color and thickens before adding broth.", "fix": "Add a bouillon cube or more salt; a squeeze of lime at the end helps brighten flavors."}]', '["Toasting the noodles is the non-negotiable step in this recipe. It prevents the pasta from becoming a starchy paste and adds a distinct nutty flavor.", "If using whole dried angel hair or capellini, break them inside a kitchen towel to prevent noodle shards from flying around the kitchen.", "For a spicier broth, blend one seeded chipotle pepper or a jalape\u00f1o directly into the tomato recaudo in step 1."]', '"Known as ''Sopa de Fideo'', this dish is a staple of Mexican home cooking (comida casera). While often served as a simple first course (''sopa aguada'') with just noodles and broth, adding chicken transforms it into a hearty main dish reminiscent of ''Caldo Tlalpe\u00f1o'' but with a pasta focus."', 1713.6);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('f3cfe802-51fd-488e-aef8-193cfa44d313', 'Slow-Roasted Sausage and Savoy Cabbage Casserole', 'A deeply comforting rustic dish where savoy cabbage melts into sweet, caramelized tenderness alongside savory sausages. The slow roasting process concentrates the flavors, turning simple ingredients into a rich, succulent meal.', 'dinner', 'European', 'Easy', '["five ingredient", "savoy cabbage", "dinner", "weeknight", "main course", "one pot", "comfort food"]', '[{"group_name": "Main Components", "items": [{"name": "fresh pork sausages", "quantity": 600, "unit": "g", "preparation": "whole", "notes": "high quality Italian or Bratwurst style", "substitutions": ["chicken sausages", "turkey sausages"], "ingredient_id": "62fcde4d-d123-4d87-8460-70bf9a3a0b9c", "nutrition_source": "USDA FoodData Central"}, {"name": "savoy cabbage", "quantity": 1, "unit": null, "preparation": "cored and roughly chopped", "notes": "approx. 800g head", "substitutions": [], "ingredient_id": "dff437b6-b727-4312-86be-82ff42b14644", "nutrition_source": "Aggregated Public Data"}, {"name": "waxy potatoes", "quantity": 500, "unit": "g", "preparation": "peeled and cut into chunks", "notes": "Yukon Gold or similar", "substitutions": [], "ingredient_id": "de37c496-907a-4970-9fa2-09f3bb7a9595", "nutrition_source": "USDA FoodData Central"}, {"name": "yellow onions", "quantity": 2, "unit": null, "preparation": "sliced", "notes": "approx. 300g total", "substitutions": [], "ingredient_id": "cc868876-7ceb-46a8-b72a-c3e8a743ee97", "nutrition_source": "Aggregated Public Data"}, {"name": "chicken stock", "quantity": 250, "unit": "ml", "preparation": "liquid", "notes": null, "substitutions": ["vegetable stock", "water"], "ingredient_id": "804679b6-2d84-49b5-98cd-1ec2d84c01e5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Pantry Staples", "items": [{"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": "liquid", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "adjust to taste based on stock salinity", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat your oven to 160\u00b0C (320\u00b0F). Prepare the vegetables: slice the onions, peel and chunk the potatoes, and roughly chop the cabbage.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a large Dutch oven over medium-high heat, add the olive oil and brown the sausages on all sides. They do not need to be cooked through, just colored. Remove sausages and set aside.", "structured": {"action": "SEAR", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "In the same pot with the rendered fat, add the sliced onions and potatoes. Saut\u00e9 for 5 minutes until the onions begin to soften and pick up the fond from the bottom of the pot.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Add the chopped Savoy cabbage to the pot. It will seem like a lot of volume, but it will shrink. Toss to combine with onions and potatoes. Season with salt and pepper.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Nestle the browned sausages back into the vegetable mixture. Pour the chicken stock over the ingredients.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Cover the pot with a lid (or tight foil) and bake in the preheated oven at 160\u00b0C (320\u00b0F) for 1 hour. This steam-roasting phase tenderizes the cabbage and potatoes.", "structured": {"action": "BRAISE", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Remove the lid and increase oven temperature to 200\u00b0C (400\u00b0F). Roast for another 30 minutes until the sausages are browned, the cabbage edges are caramelized, and the liquid has reduced to a rich glaze. Ensure internal temperature of sausages reaches at least 74\u00b0C (165\u00b0F).", "structured": {"action": "ROAST", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT30M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT20M", "passive_time": "PT1H30M", "total_time": "PT1H50M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 450}', '{"flags": ["Gluten-Free", "Dairy-Free", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 813.41, "protein_g": 28.97, "carbohydrates_g": 43.52, "fat_g": 59.77, "saturated_fat_g": 20.1, "trans_fat_g": null, "monounsaturated_fat_g": 28.56, "polyunsaturated_fat_g": 6.43, "fiber_g": 9.88, "sugar_g": 10.51, "sodium_mg": 4457.18, "cholesterol_mg": 106.5, "potassium_mg": 1439.79, "calcium_mg": 115.8, "iron_mg": 3.78, "magnesium_mg": 102.37, "phosphorus_mg": 321.54, "zinc_mg": 3.77, "vitamin_a_mcg": 100.14, "vitamin_c_mg": 78.83, "vitamin_d_mcg": 1.05, "vitamin_e_mg": 1.23, "vitamin_k_mcg": 146.7, "vitamin_b6_mg": 0.67, "vitamin_b12_mcg": 0.65, "thiamin_mg": 0.78, "riboflavin_mg": 0.32, "niacin_mg": 7.1, "folate_mcg": 185.59, "water_g": 350.22, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors improve the next day.", "duration": "P3D"}, "freezer": {"notes": "Potatoes may change texture slightly upon thawing.", "duration": "P2M"}, "reheating": "Reheat in a 180\u00b0C oven covered with foil for 20 minutes, or gently on the stovetop.", "does_not_keep": false}', '[{"name": "Dutch Oven or Casserole Dish with lid", "required": true, "alternative": "Deep baking dish with heavy foil"}, {"name": "Chef''s Knife", "required": true, "alternative": null}, {"name": "Cutting Board", "required": true, "alternative": null}]', '[{"symptom": "Casserole is too watery", "likely_cause": "The cabbage released more moisture than expected or the lid was too tight", "prevention": "Ensure you bake uncovered for the final phase to evaporate liquid", "fix": "Remove solids with a slotted spoon, place the pot on the stovetop, and boil the liquid rapidly to reduce it into a sauce"}]', '["Savoy cabbage is superior for this recipe compared to standard green cabbage because its crinkled leaves trap the juices and it becomes sweeter when roasted.", "Since this is a five-ingredient focused recipe, the quality of the sausage defines the dish. Use a sausage with good fat content and fennel or herb seasoning.", "If you are not strictly bound to five ingredients, adding a splash of apple cider vinegar or a tablespoon of mustard to the stock adds excellent acidity."]', '"This style of ''one-pot'' braise is common across Northern Europe, particularly in Germany and Alsace, where robust brassicas and preserved meats provided essential sustenance during colder months."', 813.41);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('f45090e0-ac2d-4675-a94c-4df4f1d74df2', 'The Thanksgiving Encore Sandwich', 'A structural masterpiece of holiday leftovers featuring a texturally diverse build: crisp pan-fried stuffing patties, succulent turkey breast, and tender dark meat braised in savory gravy, all balanced by a bright, tart cranberry mayonnaise on toasted sourdough.', 'lunch', 'American', 'Intermediate', '["american", "sandwiches", "bread", "cranberry sauce", "gravy", "thanksgiving leftover", "turkey", "dinner", "lunch", "main course", "fall", "thanksgiving"]', '[{"group_name": "Cranberry Mayonnaise", "items": [{"name": "mayonnaise", "quantity": 60, "unit": "g", "preparation": "cold", "notes": null, "substitutions": [], "ingredient_id": "97b74a34-8c1f-4c58-b70e-42c1de6d12aa", "nutrition_source": "USDA FoodData Central"}, {"name": "cranberry sauce", "quantity": 60, "unit": "g", "preparation": "jellied or whole berry", "notes": "leftover", "substitutions": [], "ingredient_id": "78861409-b89d-4cd2-ab32-eaa35328bf74", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly cracked, to taste (approx 0.5g)", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Fried Stuffing", "items": [{"name": "leftover stuffing", "quantity": 250, "unit": "g", "preparation": "chilled", "notes": null, "substitutions": [], "ingredient_id": "c129d536-2205-4190-bf0b-afa7d1ffface", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "for frying", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Turkey & Gravy", "items": [{"name": "turkey gravy", "quantity": 150, "unit": "ml", "preparation": null, "notes": "leftover", "substitutions": [], "ingredient_id": "d26b6e4e-b380-4a93-8d98-a3ccc7212bff", "nutrition_source": "USDA FoodData Central"}, {"name": "dark meat turkey", "quantity": 150, "unit": "g", "preparation": "shredded", "notes": "thigh or leg meat", "substitutions": [], "ingredient_id": "d83bf726-cf0a-4324-838b-3d7c184b222b", "nutrition_source": "USDA FoodData Central"}, {"name": "white meat turkey", "quantity": 200, "unit": "g", "preparation": "thickly sliced", "notes": "breast meat", "substitutions": [], "ingredient_id": "7251e2e2-876a-4d71-a345-bb6106bd65f8", "nutrition_source": "USDA FoodData Central"}, {"name": "vegetable stock", "quantity": 30, "unit": "ml", "preparation": null, "notes": "optional, to loosen gravy if too thick", "substitutions": [], "ingredient_id": "ce079dcb-dfed-45e3-b27b-77116dbec689", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Assembly", "items": [{"name": "sourdough bread", "quantity": 4, "unit": null, "preparation": "thick slices", "notes": "approx 160g total", "substitutions": [], "ingredient_id": "90f297c6-9ec3-45a6-850d-9aa9c65b45e7", "nutrition_source": "Aggregated Public Data"}, {"name": "butter", "quantity": 20, "unit": "g", "preparation": "softened", "notes": "for spreading on bread", "substitutions": [], "ingredient_id": "ae1e9713-8f4a-4a91-9619-baa177e12fc6", "nutrition_source": "USDA FoodData Central"}, {"name": "arugula", "quantity": 20, "unit": "g", "preparation": "fresh", "notes": "washed and dried", "substitutions": [], "ingredient_id": "5cd3639d-c908-4325-8962-18beeabb26ee", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a small mixing bowl, combine mayonnaise, cranberry sauce, lemon juice, and black pepper. Whisk vigorously until the mixture is uniform and turns a pale pink hue.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Shape the chilled stuffing into two flat patties roughly the size of your bread slices. Heat 30g butter in a non-stick skillet over medium heat. Fry the stuffing patties until golden brown and extremely crispy on both sides, ensuring they are heated through.", "structured": {"action": "FRY", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT6M", "doneness_cues": {"visual": "Deep golden brown crust", "tactile": "Crisp exterior, hot interior"}}, "tips": ["If the stuffing is too dry to hold a shape, mix in a teaspoon of gravy or beaten egg before forming."]}, {"step_number": 3, "phase": "cook", "text": "While the stuffing fries, bring the gravy to a gentle simmer in a saucepan. Stir in the shredded dark meat to coat and heat through to at least 74\u00b0C/165\u00b0F. Keep warm on low heat.", "structured": {"action": "SIMMER", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Briefly lay the sliced white turkey breast on top of the simmering gravy mixture (steaming it gently) or flash-heat in the skillet for 30 seconds per side just to remove the chill. Do not overcook.", "structured": {"action": "STEAM", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Butter one side of each bread slice. Toast in the skillet or under a broiler until golden brown.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "To assemble, spread a generous layer of cranberry mayonnaise on the untoasted side of all four slices. Place arugula on the bottom slices, followed by the crispy stuffing patty. Layer the warm white meat on top, then spoon over the dark meat and gravy mixture. Close with the top slice.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT0M", "total_time": "PT25M", "overnight_required": false, "yields": "2 sandwiches", "yield_count": 2, "serving_size_g": 420}', '{"flags": [], "not_suitable_for": ["Gluten intolerance", "Egg allergy"]}', '{"per_serving": {"calories": 1349.43, "protein_g": 49.92, "carbohydrates_g": 125.96, "fat_g": 69.74, "saturated_fat_g": 22.06, "trans_fat_g": 3.01, "monounsaturated_fat_g": 21.52, "polyunsaturated_fat_g": 21.78, "fiber_g": 3.57, "sugar_g": 14.58, "sodium_mg": 6090.75, "cholesterol_mg": 185.1, "potassium_mg": 1013.1, "calcium_mg": 196.56, "iron_mg": 5.24, "magnesium_mg": 91.42, "phosphorus_mg": 639.02, "zinc_mg": 4.25, "vitamin_a_mcg": 350.6, "vitamin_c_mg": 3.02, "vitamin_d_mcg": 0.49, "vitamin_e_mg": 3.8, "vitamin_k_mcg": 78.88, "vitamin_b6_mg": 0.96, "vitamin_b12_mcg": 2.44, "thiamin_mg": 0.44, "riboflavin_mg": 0.83, "niacin_mg": 15.36, "folate_mcg": 129.79, "water_g": 257.07, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best consumed immediately; components can be stored separately for 3 days.", "duration": null}, "freezer": {"notes": "Do not freeze assembled sandwich.", "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Non-stick skillet", "required": true, "alternative": null}, {"name": "Small saucepan", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Spatula", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}]', '[{"symptom": "Stuffing patty crumbles in the pan", "likely_cause": "Stuffing was too dry or not packed tightly enough when cold", "prevention": "Ensure stuffing is chilled before shaping; add a small amount of liquid or egg binder if it feels loose", "fix": "Convert to a ''hash'' style loose filling and pile it onto the sandwich with a spoon"}, {"symptom": "White meat is dry", "likely_cause": "Overheated during the reheating phase", "prevention": "Only heat until the chill is gone, relying on the hot gravy and stuffing to provide overall sandwich warmth", "fix": "Add extra mayonnaise or dip the meat briefly in the gravy"}]', '["Temperature contrast is key: The mayonnaise should be cool, while the stuffing and gravy must be piping hot to create a dynamic eating experience.", "Forming the stuffing into a flat patty (similar to a latke) prevents the sandwich from becoming a messy pile and adds a crucial crunch element that soft leftovers usually lack.", "Use two types of turkey texture: The shredded dark meat holds the sauce/gravy effectively, while the sliced breast provides structural height and a clean bite.", "If your gravy has gelatinized in the fridge, let it melt down slowly with a splash of water or stock before adding the meat to avoid scorching."]', '"The ''Day After'' sandwich is a modern American secular tradition, often rivaling the Thanksgiving feast itself in popularity. It represents the philosophy of abundance and resourcefulness, transforming the previous night''s formal roast into a casual, comfort-food staple."', 1349.43);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('f4c21caa-925b-4a45-96ba-788bf4422554', 'Birria de Res Quesatacos with Consommé', 'Tender, slow-braised beef shredded and folded into corn tortillas dipped in chili-infused fat, pan-fried to a crisp, and served with a rich, savory dipping broth and a side of spicy salsa roja.', 'main course', 'Mexican', 'Intermediate', '["tacos", "birria", "beef", "mexican", "main course", "quesabirria", "comfort food"]', '[{"group_name": "Beef Base", "items": [{"name": "beef chuck roast", "quantity": 1000, "unit": "g", "preparation": "cut into 3-inch chunks", "notes": null, "substitutions": [], "ingredient_id": "e13154c7-fcc2-4dbd-a047-ec71e1fabd3f", "nutrition_source": "USDA FoodData Central"}, {"name": "beef shank", "quantity": 500, "unit": "g", "preparation": "bone-in", "notes": "Essential for body/collagen in the consomm\u00e9", "substitutions": [], "ingredient_id": "cbb8c6ea-0449-4e9d-83c1-5b3c60c74a5e", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 15, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Adobo & Consomm\u00e9 Aromatics", "items": [{"name": "dried guajillo chilies", "quantity": 5, "unit": null, "preparation": "stemmed and seeded", "notes": "approx 30g", "substitutions": [], "ingredient_id": "e8254ba2-5d4e-4758-9037-73153d41dafb", "nutrition_source": "USDA FoodData Central"}, {"name": "dried ancho chilies", "quantity": 2, "unit": null, "preparation": "stemmed and seeded", "notes": "approx 15g", "substitutions": [], "ingredient_id": "31d5e9d5-d288-426a-920a-a7b77822dc2f", "nutrition_source": "USDA FoodData Central"}, {"name": "white onion", "quantity": 1, "unit": null, "preparation": "quartered", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 6, "unit": null, "preparation": "peeled", "notes": null, "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "mexican oregano", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "687f54eb-e811-4e5e-ac2e-e2735458480c", "nutrition_source": "USDA FoodData Central"}, {"name": "cumin seeds", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "whole cloves", "quantity": 3, "unit": null, "preparation": null, "notes": "approx 0.5g", "substitutions": [], "ingredient_id": "7b3bf68a-3ae9-4dad-91f4-6c7a14ec5e0e", "nutrition_source": "USDA FoodData Central"}, {"name": "cinnamon stick", "quantity": 1, "unit": null, "preparation": "whole", "notes": "approx 5cm piece", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "apple cider vinegar", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "33184869-c099-4e9d-b4e3-e9339321f3f1", "nutrition_source": "USDA FoodData Central"}, {"name": "beef stock or water", "quantity": 1500, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "787d0598-6162-4b49-a834-8ca6a9a25e15", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Salsa Roja (Spicy Table Sauce)", "items": [{"name": "dried chiles de \u00e1rbol", "quantity": 15, "unit": null, "preparation": "stemmed", "notes": "Very spicy, approx 8g", "substitutions": [], "ingredient_id": "04e25096-2354-47fb-8109-ed574c64615c", "nutrition_source": "USDA FoodData Central"}, {"name": "roma tomato", "quantity": 2, "unit": null, "preparation": null, "notes": "approx 200g", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "white vinegar", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8d5bf07e-89a1-47ee-a6b7-d9cb03e96d64", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Assembly", "items": [{"name": "corn tortillas", "quantity": 14, "unit": null, "preparation": "12-14cm diameter", "notes": null, "substitutions": [], "ingredient_id": "41ffce81-01e5-4efa-801b-0ff221a40723", "nutrition_source": "Aggregated Public Data"}, {"name": "oaxaca cheese", "quantity": 300, "unit": "g", "preparation": "shredded", "notes": "Substitute with Low-Moisture Mozzarella if unavailable", "substitutions": [], "ingredient_id": "16a525ac-b987-4e5f-8496-b05fcf65457b", "nutrition_source": "USDA FoodData Central"}, {"name": "white onion", "quantity": 1, "unit": null, "preparation": "finely diced for garnish", "notes": null, "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "cilantro", "quantity": 30, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}, {"name": "limes", "quantity": 3, "unit": null, "preparation": "cut into wedges", "notes": null, "substitutions": [], "ingredient_id": "d3d2677e-fe02-4404-add0-29d73df7e921", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Season the beef chunks and shank generously with salt. Let them sit at room temperature while preparing the chilies.", "structured": {"action": "SEASON", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a dry skillet over medium heat (175\u00b0C/350\u00b0F), toast the Guajillo and Ancho chilies for 1-2 minutes per side until fragrant but not blackened. Remove stems and seeds.", "structured": {"action": "TOAST", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Place toasted chilies in a bowl and cover with boiling water. Let soak for 15 minutes to rehydrate.", "structured": {"action": "SOAK", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In a blender, combine rehydrated chilies, onion, garlic, oregano, cumin, cloves, cinnamon, apple cider vinegar, and 250ml of the chili soaking liquid. Blend until completely smooth.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Preheat oven to 160\u00b0C/325\u00b0F. In a large Dutch oven, sear the beef in oil over medium-high heat until browned on all sides.", "structured": {"action": "SEAR", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Pour the blended adobo sauce over the beef. Add the beef stock (or water) until meat is just covered. Bring to a simmer, cover with a lid, and transfer to the oven.", "structured": {"action": "BRAISE", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Braise in the oven for 3 to 3.5 hours, until the meat is fork-tender and falling off the bone.", "structured": {"action": "BRAISE", "temperature": null, "duration": "PT3H30M", "doneness_cues": {"visual": null, "tactile": "Fork-tender, shreds with zero resistance"}}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "While beef cooks, prepare Salsa Roja: Boil tomatoes and Arbol chilies in water for 10 minutes. Drain, then blend with garlic, vinegar, and salt until smooth. Set aside.", "structured": {"action": "BOIL", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove beef from the pot. Shred the meat, discarding bones and excess gristle. Season the shredded meat with a ladle of the pot liquid (consomm\u00e9).", "structured": {"action": "SHRED", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Skim the bright red fat from the top of the consomm\u00e9. Heat a skillet over medium heat. Dip each tortilla into the reserved red fat, then place in the skillet.", "structured": {"action": "FRY", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 11, "phase": "assemble", "text": "Add cheese to the tortilla. Once melted, top with shredded beef. Fold the tortilla over and fry until crispy on both sides.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 12, "phase": "finish", "text": "Serve immediately with a cup of hot consomm\u00e9 topped with onions and cilantro for dipping, lime wedges, and the salsa roja.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT3H30M", "total_time": "PT4H15M", "overnight_required": false, "yields": "12-14 tacos", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Gluten-Free", "High-Protein", "Nut-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 1490.93, "protein_g": 136.56, "carbohydrates_g": 132.29, "fat_g": 54.29, "saturated_fat_g": 17.17, "trans_fat_g": 1.28, "monounsaturated_fat_g": 17.29, "polyunsaturated_fat_g": 5.21, "fiber_g": 15.9, "sugar_g": 18.55, "sodium_mg": 5536.04, "cholesterol_mg": 282.75, "potassium_mg": 3899.83, "calcium_mg": 523.67, "iron_mg": 17.74, "magnesium_mg": 274.29, "phosphorus_mg": 1488.18, "zinc_mg": 37.01, "vitamin_a_mcg": 1988.4, "vitamin_c_mg": 33.82, "vitamin_d_mcg": 0.25, "vitamin_e_mg": 1.46, "vitamin_k_mcg": 32.45, "vitamin_b6_mg": 1.88, "vitamin_b12_mcg": 13.53, "thiamin_mg": 0.52, "riboflavin_mg": 1.03, "niacin_mg": 19.79, "folate_mcg": 67.65, "water_g": 422.26, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store meat in the consomm\u00e9 to prevent drying out. Separate fat layer when cold for frying later.", "duration": "P4D"}, "freezer": {"notes": "Freeze meat and consomm\u00e9 together in airtight containers.", "duration": "P3M"}, "reheating": "Reheat gently on the stove until simmering; refresh crispness of taco shells in a pan.", "does_not_keep": false}', '[{"name": "Dutch oven or heavy-bottomed pot with lid", "required": true, "alternative": "Slow cooker (adjust time to 8 hours low)"}, {"name": "High-speed blender", "required": true, "alternative": null}, {"name": "Large skillet or comal", "required": true, "alternative": null}, {"name": "Fine mesh strainer", "required": true, "alternative": null}]', '[{"symptom": "Consomm\u00e9 tastes bitter", "likely_cause": "Dried chilies were toasted too long and burnt", "prevention": "Toast chilies only until fragrant (1-2 mins); if they turn black, discard and start over", "fix": "Add a teaspoon of honey or sugar to counteract bitterness, though strong burning cannot be fully fixed"}, {"symptom": "Meat is tough", "likely_cause": "Braising time was insufficient", "prevention": "Check meat after 3 hours; if it doesn''t shred easily, continue cooking", "fix": "Return meat to liquid and cook for another 30-45 minutes"}]', '["The fat that rises to the top of the pot is ''liquid gold''. Do not discard it; it is essential for frying the tortillas to get that signature orange-red color and crisp texture.", "Using a mix of chuck roast (meatiness) and shank (collagen) creates a consomm\u00e9 with a rich, sticky mouthfeel that coats the taco perfectly.", "For a smoother consomm\u00e9, you can strain the liquid after removing the beef, but many traditional preparations leave the bits of spice and aromatics for texture.", "If you have time, make the beef a day ahead. The flavors mature significantly overnight, and the fat is easier to separate when cold."]', '"Originally from the state of Jalisco, Mexico, Birria was traditionally made with goat meat (chivo) and steamed. The beef version (Birria de Res) gained explosive popularity in Tijuana and later Los Angeles, evolving into the ''Quesabirria'' style where the braising liquid is used as a dip."', 1490.93);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('f6488b11-5b29-4e63-a8c9-e3cdd8e31bc5', 'Classic Lachha Paratha', 'A visually striking, multi-layered North Indian flatbread. Known for its visible concentric rings, this bread features a crispy, flaky exterior that shatters upon touch, revealing a tender, soft interior. The lamination technique relies on fat and flour separation similar to puff pastry.', 'bread', 'Indian', 'Intermediate', '["paratha", "indian", "flatbread", "vegetarian", "laminated dough", "street food"]', '[{"group_name": "Dough", "items": [{"name": "whole wheat flour (atta)", "quantity": 250, "unit": "g", "preparation": "fine grind", "notes": "Indian Atta flour yields best results; standard whole wheat is a coarser substitute", "substitutions": ["50% all-purpose flour + 50% whole wheat flour"], "ingredient_id": "af2661d8-b555-4fef-bdee-51a5190eda92", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 5, "unit": "g", "preparation": null, "notes": "fine sea salt", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 160, "unit": "ml", "preparation": "warm (40\u00b0C)", "notes": "quantity may vary slightly based on humidity", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "ghee", "quantity": 15, "unit": "g", "preparation": "melted", "notes": "added to dough for tenderness", "substitutions": ["vegetable oil", "avocado oil"], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Lamination & Cooking", "items": [{"name": "ghee", "quantity": 45, "unit": "g", "preparation": "melted", "notes": "for brushing layers and frying", "substitutions": ["neutral oil", "clarified butter"], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "whole wheat flour", "quantity": 20, "unit": "g", "preparation": "dry", "notes": "for dusting layers", "substitutions": [], "ingredient_id": "af2661d8-b555-4fef-bdee-51a5190eda92", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a mixing bowl, combine the flour and salt. Add 15g of melted ghee and mix with your fingers until the flour resembles coarse crumbs. Gradually add warm water while mixing until a dough begins to form.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Knead the dough on a clean surface for 6-8 minutes until it is smooth, soft, and pliable. It should not be sticky. If too dry, add water 1 teaspoon at a time.", "structured": {"action": "KNEAD", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": null, "tactile": "Soft, pliable, springs back slowly when indented"}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "Cover the dough with a damp kitchen towel or plastic wrap and let it rest at room temperature. This relaxes the gluten, making it easier to roll.", "structured": {"action": "REST", "temperature": null, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "assemble", "text": "Divide the dough into 4 equal portions. Roll one portion into a thin circle, approximately 20cm (8 inches) in diameter. The thinner you roll it, the more layers you will achieve.", "structured": {"action": "ROLL", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "assemble", "text": "Brush the surface liberally with melted ghee and dust lightly with dry flour. This creates the barrier necessary for layer separation.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Create the layers using the fan-fold method: Make small pleats (accordion folds) about 1cm wide starting from one edge to the other. You should end up with a long, pleated strip.", "structured": {"action": "SHAPE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Hold one end of the pleated strip and roll it tightly inward like a cinnamon roll or coil. Tuck the outer end underneath the center of the coil to seal. Repeat for all portions. Let coils rest covered for 10 minutes.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Heat a heavy skillet or tawa over medium heat. Gently flatten a coil with your hand, then roll it out carefully to a 15cm (6 inch) circle. Do not press too hard, or the layers will merge.", "structured": {"action": "ROLL", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Place the paratha on the hot skillet. Cook for about 1 minute until small bubbles appear. Flip and cook for another minute. Brush the top side with ghee, flip again, and press gently with a spatula to crisp up the layers. Repeat flipping and brushing until golden brown spots appear on both sides.", "structured": {"action": "FRY", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Golden brown leopard spots", "tactile": "Crispy exterior"}}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Remove from heat. To release the layers, place the hot paratha between your hands (use a towel if sensitive to heat) and clap your hands together gently to crush the bread slightly from the sides. Serve immediately.", "structured": {"action": "CRUSH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT30M", "total_time": "PT1H5M", "overnight_required": false, "yields": "4 flatbreads", "yield_count": 4, "serving_size_g": 95}', '{"flags": ["Vegetarian", "Egg-Free", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 331.65, "protein_g": 6.62, "carbohydrates_g": 50.3, "fat_g": 13.48, "saturated_fat_g": 7.87, "trans_fat_g": null, "monounsaturated_fat_g": 3.7, "polyunsaturated_fat_g": 1.24, "fiber_g": 8.84, "sugar_g": 0.7, "sodium_mg": 489.68, "cholesterol_mg": 32.25, "potassium_mg": 269.85, "calcium_mg": 26.98, "iron_mg": 2.51, "magnesium_mg": 79.69, "phosphorus_mg": 221.63, "zinc_mg": 2.01, "vitamin_a_mcg": 102.6, "vitamin_c_mg": null, "vitamin_d_mcg": null, "vitamin_e_mg": 0.71, "vitamin_k_mcg": 2.33, "vitamin_b6_mg": 0.13, "vitamin_b12_mcg": 0.03, "thiamin_mg": 0.2, "riboflavin_mg": 0.13, "niacin_mg": 3.62, "folate_mcg": 19.35, "water_g": 50.8, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container or wrapped in foil.", "duration": "P3D"}, "freezer": {"notes": "Freeze par-cooked parathas separated by parchment paper.", "duration": "P2M"}, "reheating": "Reheat on a hot skillet for 1-2 minutes per side until crisp.", "does_not_keep": false}', '[{"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Rolling pin", "required": true, "alternative": "Clean wine bottle"}, {"name": "Tawa or Cast Iron Skillet", "required": true, "alternative": "Heavy-bottomed non-stick pan"}, {"name": "Pastry brush", "required": false, "alternative": "Back of a spoon"}, {"name": "Clean kitchen towel", "required": true, "alternative": null}]', '[{"symptom": "Paratha is chewy or hard rather than flaky", "likely_cause": "Dough was not rested enough or cooked on too low heat", "prevention": "Ensure the 20-minute rest period and cook on medium-high heat to flash-cook the layers", "fix": "Keep cooked parathas wrapped in a cloth to steam-soften slightly"}, {"symptom": "Layers are not visible", "likely_cause": "Rolling too firmly during the final shape or insufficient flour/fat between pleats", "prevention": "Use a gentle hand when rolling the final circle and ensure adequate dusting during lamination", "fix": "Cannot be fixed for this batch"}]', '["The ''crush'' or ''clap'' at the very end is the secret to restaurant-style parathas; it physically separates the layers that may have stuck together during cooking.", "Using warm water (40\u00b0C/105\u00b0F) helps hydrate the bran in whole wheat flour faster, resulting in a softer dough without extended kneading.", "If you want a Vegan version, substitute the ghee for a high-heat neutral oil like avocado or grapeseed, though the flavor profile will lack the traditional nutty aroma.", "Do not stack hot parathas directly on top of each other without a cloth, or the steam will destroy the crispiness of the bottom ones."]', '"Lachha Paratha originates from Punjab in North India. The word ''Lachha'' literally translates to ''ring'' or ''coil,'' referring to the circular layers visible in the final bread. It is a staple accompaniment to rich curries like Butter Chicken or Paneer Butter Masala, designed to scoop up thick gravies."', 331.65);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('f6d6c407-7642-4465-a22f-aa044a64b3d7', 'Chilled Lump Crab and Asparagus Salad', 'A refined, springtime salad featuring sweet, jumbo lump crab meat and tender-crisp blanched asparagus. The dish is brightened with a zesty lemon vinaigrette and finished with salty, umami-rich shavings of aged Parmesan cheese.', 'salad', 'Mediterranean', 'Easy', '["asparagus", "lemon", "lump crab meat", "salad", "gluten-free", "spring", "starter"]', '[{"group_name": "Salad Base", "items": [{"name": "asparagus", "quantity": 350, "unit": "g", "preparation": "woody ends trimmed", "notes": "medium thickness spears preferred", "substitutions": [], "ingredient_id": "8a2a9426-3755-4553-953a-fd9cf42cef90", "nutrition_source": "USDA FoodData Central"}, {"name": "lump crab meat", "quantity": 225, "unit": "g", "preparation": "picked over for shells", "notes": "jumbo lump preferred for texture", "substitutions": [], "ingredient_id": "b05473df-f53b-4ca3-8753-82dfc9fe52a4", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Lemon Vinaigrette", "items": [{"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": "room temperature", "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": "zested and juiced", "notes": "approx 30-40ml juice", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "dijon mustard", "quantity": 5, "unit": "g", "preparation": "smooth", "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 1, "unit": "g", "preparation": "freshly cracked", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Garnish", "items": [{"name": "parmesan cheese", "quantity": 30, "unit": "g", "preparation": "block form", "notes": "for shaving", "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh chives", "quantity": 5, "unit": "g", "preparation": "finely chopped", "notes": "optional", "substitutions": [], "ingredient_id": "374e5fac-6ec9-46da-b09a-8098486212c1", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Prepare an ice bath by filling a large bowl with cold water and ice. Bring a large pot of salted water to a rolling boil.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Cut the trimmed asparagus spears into 5cm (2-inch) pieces on a bias. Add them to the boiling water and blanch until bright green and tender-crisp, about 2-3 minutes depending on thickness.", "structured": {"action": "BLANCH", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Bright vibrant green", "tactile": "Slight snap when bent"}}, "tips": ["Do not overcook; the asparagus should retain a slight crunch."]}, {"step_number": 3, "phase": "prep", "text": "Immediately drain the asparagus and plunge into the ice bath to stop the cooking process. Once cool (about 2 minutes), drain well and pat dry with paper towels.", "structured": {"action": "SHOCK", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "In a small mixing bowl, whisk together the lemon juice, lemon zest, Dijon mustard, salt, and pepper. Slowly stream in the olive oil while whisking vigorously to emulsify.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "prep", "text": "Gently pick through the crab meat with your fingertips to ensure no shell fragments remain, being careful not to break up the large lumps.", "structured": {"action": "INSPECT", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "In a large bowl, toss the dry asparagus with half of the dressing. Arrange the asparagus on serving plates.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Gently fold the crab meat with the remaining dressing. Pile the crab on top of the asparagus. Finish by using a vegetable peeler to shave large curls of Parmesan cheese over the top and garnish with chives.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT0M", "total_time": "PT25M", "overnight_required": false, "yields": "2 servings", "yield_count": 2, "serving_size_g": 280}', '{"flags": ["Pescatarian", "Gluten-Free", "Nut-Free", "Peanut-Free", "Soy-Free", "Low-Carb", "Keto"], "not_suitable_for": ["Shellfish allergy"]}', '{"per_serving": {"calories": 418.37, "protein_g": 33.6, "carbohydrates_g": 11.81, "fat_g": 27.67, "saturated_fat_g": 5.7, "trans_fat_g": null, "monounsaturated_fat_g": 17.57, "polyunsaturated_fat_g": 2.59, "fiber_g": 5.14, "sugar_g": 4.43, "sodium_mg": 1342.54, "cholesterol_mg": 10.2, "potassium_mg": 786.32, "calcium_mg": 357.6, "iron_mg": 5.26, "magnesium_mg": 36.42, "phosphorus_mg": 578.77, "zinc_mg": 1.41, "vitamin_a_mcg": 114.46, "vitamin_c_mg": 38.85, "vitamin_d_mcg": 0.08, "vitamin_e_mg": 5.32, "vitamin_k_mcg": 87.42, "vitamin_b6_mg": 0.21, "vitamin_b12_mcg": 0.18, "thiamin_mg": 0.27, "riboflavin_mg": 0.31, "niacin_mg": 1.81, "folate_mcg": 96.81, "water_g": 205.49, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Best consumed immediately. Crab degrades quickly once dressed.", "duration": "P1D"}, "freezer": {"notes": "Do not freeze.", "duration": null}, "reheating": null, "does_not_keep": true}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Large bowl", "required": true, "alternative": "Clean sink basin"}, {"name": "Whisk", "required": true, "alternative": "Fork"}, {"name": "Vegetable peeler", "required": true, "alternative": "Sharp knife"}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}]', '[{"symptom": "Asparagus is mushy and olive-green", "likely_cause": "Overcooked during blanching or cooled too slowly", "prevention": "Use a timer and ensure the ice bath is ready before boiling starts", "fix": "Cannot be fixed; serve as is or chop finely to mix into a spread instead of a salad"}, {"symptom": "Crunchy bits in the crab", "likely_cause": "Shell fragments were not removed", "prevention": "Tactile inspection of meat before dressing", "fix": "Pick through the plated dish to remove shells"}]', '["Always buy ''jumbo lump'' or ''lump'' crab meat for salads; ''flake'' or ''claw'' meat will disintegrate into a mush when tossed.", "Ensure the asparagus is completely dry before adding the dressing. Watery asparagus will dilute the vinaigrette and prevent it from clinging.", "Using a vegetable peeler on the side of a Parmesan block creates elegant, translucent ribbons that look professional and provide a better texture than grated cheese.", "If using canned crab meat, drain it thoroughly and rinse gently, but fresh pasteurized crab is significantly better for this preparation."]', '"This dish highlights the intersection of coastal ingredients and early harvest produce, a hallmark of Mediterranean and Modern American coastal cuisine. The pairing of sweet shellfish with grassy asparagus is a classic rite of spring."', 418.37);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('f7b8e7ab-5959-45ea-b58b-abc4912e77d0', 'Authentic Thai Fish Cakes (Tod Mun Pla)', 'Springy, golden-brown fish cakes bursting with the aroma of red curry and fresh kaffir lime leaves. The texture strikes a perfect balance between the tender, savory fish paste and the satisfying crunch of thinly sliced long beans.', 'appetizer', 'Thai', 'Intermediate', '["fish", "thai", "appetizer", "fried", "street food", "high-protein"]', '[{"group_name": "Fish Paste", "items": [{"name": "firm white fish fillets", "quantity": 500, "unit": "g", "preparation": "chilled, chopped roughly", "notes": "Tilapia, Cod, Pollack, or Clown Knifefish", "substitutions": ["Shrimp mousse", "Chicken breast (for non-traditional)"], "ingredient_id": "c922dd4c-7ddb-48bc-af35-c578838fcce8", "nutrition_source": "USDA FoodData Central"}, {"name": "red curry paste", "quantity": 50, "unit": "g", "preparation": null, "notes": "Adjust based on spice tolerance", "substitutions": [], "ingredient_id": "e714e2f1-2295-4e8c-8ccf-65c38381e71e", "nutrition_source": "USDA FoodData Central"}, {"name": "egg", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 50g", "substitutions": [], "ingredient_id": "312649b9-51fd-4715-89b3-e3c2833752a0", "nutrition_source": "Aggregated Public Data"}, {"name": "fish sauce", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "95a9a747-50ee-4be0-84be-0dfc96111e2a", "nutrition_source": "Aggregated Public Data"}, {"name": "white sugar", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "kaffir lime leaves", "quantity": 5, "unit": null, "preparation": "very finely julienned", "notes": "approx 3g", "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "Aggregated Public Data"}, {"name": "snake beans or green beans", "quantity": 50, "unit": "g", "preparation": "thinly sliced into rounds", "notes": null, "substitutions": [], "ingredient_id": "e99ec12b-2d03-4965-bdb7-82cde4c76e61", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Frying", "items": [{"name": "vegetable oil", "quantity": 1000, "unit": "ml", "preparation": null, "notes": "For deep frying", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}]}, {"group_name": "Cucumber Relish (Ajad)", "items": [{"name": "rice vinegar", "quantity": 60, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fcbf5252-1be9-4dd4-8c22-4fda1dbdca28", "nutrition_source": "Aggregated Public Data"}, {"name": "white sugar", "quantity": 50, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "cucumber", "quantity": 100, "unit": "g", "preparation": "diced small", "notes": null, "substitutions": [], "ingredient_id": "84cc106c-269c-44b7-af59-33b3c121e483", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "sliced", "notes": "approx 20g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "red chili", "quantity": 1, "unit": null, "preparation": "sliced", "notes": "approx 5g", "substitutions": [], "ingredient_id": "5080eb9a-d555-4558-94e5-d5700e96ff9b", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Combine the chilled fish fillets, red curry paste, egg, fish sauce, and sugar in a food processor. Blend until the mixture becomes smooth, sticky, and gathers into a mass.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Paste looks shiny and sticky", "tactile": "Mixture resists being pulled apart"}}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Transfer the paste to a mixing bowl. Add the julienned kaffir lime leaves and sliced beans. Mix by hand, picking up the paste and slapping it back into the bowl vigorously to develop springy texture.", "structured": {"action": "MIX", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": null, "tactile": "Paste feels firm and elastic"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "To make the relish: In a small saucepan or microwave-safe bowl, dissolve the sugar and salt in the rice vinegar. Let it cool, then pour over the cucumber, shallots, and chili just before serving.", "structured": {"action": "MIX", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Heat the vegetable oil in a wok or deep fryer to 170\u00b0C (340\u00b0F). Wet your hands with water to prevent sticking, then shape the paste into flattened disks about 5cm wide and 1cm thick.", "structured": {"action": "SHAPE", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Carefully lower the cakes into the oil in batches. Fry until they puff up slightly and turn golden brown, ensuring an internal temperature of at least 74\u00b0C (165\u00b0F).", "structured": {"action": "FRY", "temperature": {"celsius": 170, "fahrenheit": 338}, "duration": "PT3M", "doneness_cues": {"visual": "Golden brown and floating", "tactile": "Firm to the touch"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove the fish cakes with a slotted spoon and drain on wire racks or paper towels. Serve immediately with the cucumber relish.", "structured": {"action": "DRAIN", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT40M", "passive_time": "PT0M", "total_time": "PT40M", "overnight_required": false, "yields": "15 cakes", "yield_count": 15, "serving_size_g": 150}', '{"flags": ["Pescatarian", "Dairy-Free", "Nut-Free", "Gluten-Free"], "not_suitable_for": ["Shellfish allergy sufferers (check curry paste and fish sauce labels)"]}', '{"per_serving": {"calories": 58.75, "protein_g": 6.53, "carbohydrates_g": 6.85, "fat_g": 0.95, "saturated_fat_g": 0.2, "trans_fat_g": null, "monounsaturated_fat_g": 0.44, "polyunsaturated_fat_g": 0.22, "fiber_g": 1.98, "sugar_g": 4.64, "sodium_mg": 176.65, "cholesterol_mg": 30.4, "potassium_mg": 162.24, "calcium_mg": 26.04, "iron_mg": 0.93, "magnesium_mg": 18.01, "phosphorus_mg": 98.06, "zinc_mg": 0.33, "vitamin_a_mcg": 12.99, "vitamin_c_mg": 1.64, "vitamin_d_mcg": 0.23, "vitamin_e_mg": 1.03, "vitamin_k_mcg": 3.86, "vitamin_b6_mg": 0.11, "vitamin_b12_mcg": 0.64, "thiamin_mg": 0.02, "riboflavin_mg": 0.04, "niacin_mg": 1.24, "folate_mcg": 8.84, "water_g": 38.33, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Reheat in an oven or air fryer to restore crispness.", "duration": "P3D"}, "freezer": {"notes": "Freeze raw shaped patties on a tray, then bag. Fry directly from frozen at a slightly lower temperature.", "duration": "P1M"}, "reheating": "Air fry at 180\u00b0C for 3-5 minutes or bake at 200\u00b0C for 5-8 minutes.", "does_not_keep": false}', '[{"name": "Food processor", "required": true, "alternative": "Heavy cleaver and chopping board"}, {"name": "Wok or deep fryer", "required": true, "alternative": null}, {"name": "Slotted spoon", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Kitchen thermometer", "required": false, "alternative": "Wooden chopstick test"}]', '[{"symptom": "Fish cakes are mushy and not springy", "likely_cause": "The fish paste was not worked enough to release the myosin proteins", "prevention": "Ensure fish is very cold and slap/knead the paste vigorously for at least 3-5 minutes", "fix": "Return uncooked paste to the processor and blend with a few ice cubes"}, {"symptom": "Fish cakes are too salty", "likely_cause": "Curry paste brand had high sodium content", "prevention": "Taste a tiny amount of raw paste (spit out) or fry a test piece first", "fix": "Serve with extra cucumber and unseasoned rice to balance"}]', '["Keep ingredients icy cold. If the fish gets warm during processing, the emulsion will break and the texture will be grainy.", "Wet your hands with cold water continuously while shaping to prevent the sticky paste from adhering to your skin.", "The ''slapping'' technique is non-negotiable for authentic texture. It mimics the traditional mortar and pestle pounding.", "Do not slice the beans too thick; they need to cook through in the short frying time to avoid being raw and grassy.", "For extra lift, you can add 1/4 teaspoon of baking powder to the mix, though traditional recipes rely on the egg and kneading."]', '"Tod Mun Pla is a ubiquitous street food in Thailand, showcasing the nation''s expertise in balancing flavors and utilizing freshwater fish. Historically, it was a way to use the scraped meat of bony river fish, transformed by red curry paste and rigorous kneading into a texture that is uniquely ''bouncy'' (known as ''deng'' in Thai culinary terms)."', 58.75);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('f84698f8-8076-43b6-9125-256563cc78b1', 'Classic Steamed Currant Pudding with Butterscotch Sauce', 'A comforting, quintessentially British sponge pudding, traditionally known as Spotted Dick. The addition of suet and breadcrumbs creates a uniquely light yet moist texture, speckled with dried currants and served with a rich, salty-sweet butterscotch sauce.', 'dessert', 'British', 'Intermediate', '["pudding", "dessert", "steamed", "butterscotch sauce", "traditional", "british", "winter warmer"]', '[{"group_name": "Pudding Dry Mix", "items": [{"name": "self-raising flour", "quantity": 250, "unit": "g", "preparation": "sifted", "notes": null, "substitutions": ["250g plain flour + 15g baking powder"], "ingredient_id": "c44eca83-374b-437f-b52e-979b3beacb3a", "nutrition_source": "USDA FoodData Central"}, {"name": "shredded suet", "quantity": 125, "unit": "g", "preparation": null, "notes": "Beef suet for strict tradition, vegetable suet for vegetarian adaptation", "substitutions": [], "ingredient_id": "601a4323-fbd9-4c8b-b3f0-09235aac041a", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh white breadcrumbs", "quantity": 75, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c4052e66-d9d4-41e7-a365-cd88abcd9202", "nutrition_source": "USDA FoodData Central"}, {"name": "caster sugar", "quantity": 75, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "large pinch", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Fruit and Liquid", "items": [{"name": "currants", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": ["raisins", "sultanas"], "ingredient_id": "f700705f-0a9b-4f11-8a21-47d179b06b92", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": 1, "unit": null, "preparation": null, "notes": "zest of 1 lemon, approx 5g", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "whole milk", "quantity": 150, "unit": "ml", "preparation": null, "notes": "plus extra if needed", "substitutions": [], "ingredient_id": "0d4b43bc-f9a5-4b03-8dbb-9ddc3e1ae2f5", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Butterscotch Sauce", "items": [{"name": "unsalted butter", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "dark brown soft sugar", "quantity": 100, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "double cream", "quantity": 125, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["heavy cream"], "ingredient_id": "266353a6-1595-489c-a61a-cc070d4323e1", "nutrition_source": "USDA FoodData Central"}, {"name": "vanilla extract", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "d9823951-2391-49ba-90b4-7d8272161b6f", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Generously butter the inside of the pudding basin. Place a large pot on the stove with a trivet or inverted saucer inside, and fill with enough water to come halfway up the side of your basin. Begin heating the water.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a large mixing bowl, combine the flour, shredded suet, breadcrumbs, sugar, salt, currants, and lemon zest. Stir until the fruit is evenly distributed.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "mix", "text": "Gradually pour in the milk while stirring. Mix to form a firm but soft dropping consistency dough. If it is too dry, add a splash more milk; if too wet, it will be heavy.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": null}, "tips": ["Dropping consistency means the dough drops reluctantly from a spoon, rather than pouring or sticking fast."]}, {"step_number": 4, "phase": "assemble", "text": "Spoon the mixture into the prepared basin. Cut a sheet of parchment paper and a sheet of foil. Lay them together and make a pleat (fold) in the center to allow the pudding to expand as it rises. Place over the basin (foil side up) and tie securely with kitchen twine under the rim.", "structured": {"action": "ASSEMBLE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Lower the basin onto the trivet in the boiling water. The water should reach halfway up the basin sides. Cover the pot with a tight-fitting lid and steam gently for 90 minutes. Check water level halfway through and top up with boiling water if necessary.", "structured": {"action": "STEAM", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT1H30M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Ten minutes before serving, prepare the sauce. Melt the butter and brown sugar in a saucepan over medium heat. Stir until the sugar has dissolved and the mixture is bubbling.", "structured": {"action": "SIMMER", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Pour in the cream and vanilla extract. Whisk gently and let it bubble for 2-3 minutes until slightly thickened. Stir in the sea salt.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT3M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Carefully remove the pudding basin from the steamer. Remove the foil and paper. Invert a deep serving plate over the basin and flip to release the pudding. Slice and serve hot with the butterscotch sauce.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT30M", "passive_time": "PT1H30M", "total_time": "PT2H", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 220}', '{"flags": ["Nut-Free", "Peanut-Free", "Soy-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 757.84, "protein_g": 8.14, "carbohydrates_g": 88.61, "fat_g": 42.4, "saturated_fat_g": 24.75, "trans_fat_g": 0.26, "monounsaturated_fat_g": 12.71, "polyunsaturated_fat_g": 1.98, "fiber_g": 2.61, "sugar_g": 47.01, "sodium_mg": 361.88, "cholesterol_mg": 76.17, "potassium_mg": 339.77, "calcium_mg": 103.88, "iron_mg": 1.58, "magnesium_mg": 27.53, "phosphorus_mg": 123.82, "zinc_mg": 0.68, "vitamin_a_mcg": 212.13, "vitamin_c_mg": 1.74, "vitamin_d_mcg": 0.66, "vitamin_e_mg": 1, "vitamin_k_mcg": 4.03, "vitamin_b6_mg": 0.13, "vitamin_b12_mcg": 0.24, "thiamin_mg": 0.16, "riboflavin_mg": 0.19, "niacin_mg": 1.54, "folate_mcg": 29.38, "water_g": 52.25, "alcohol_g": 0.27, "caffeine_mg": null}, "sources": ["USDA FoodData Central"]}', '{"refrigerator": {"notes": "Keep pudding wrapped tightly; store sauce in an airtight jar.", "duration": "P5D"}, "freezer": {"notes": "Freeze pudding slices individually. Sauce may separate upon thawing but can be whisked while heating.", "duration": "P3M"}, "reheating": "Microwave pudding slices for 30-60 seconds. Reheat sauce gently on stove or microwave, stirring frequently.", "does_not_keep": false}', '[{"name": "Pudding basin (1.2 liter / 2 pint capacity)", "required": true, "alternative": "Heatproof glass bowl"}, {"name": "Large pot with lid (for steaming)", "required": true, "alternative": null}, {"name": "Trivet or saucer", "required": true, "alternative": "Folded foil strip"}, {"name": "Kitchen twine", "required": true, "alternative": null}, {"name": "Parchment paper", "required": true, "alternative": null}, {"name": "Aluminum foil", "required": true, "alternative": null}, {"name": "Mixing bowl", "required": true, "alternative": null}, {"name": "Saucepan", "required": true, "alternative": null}, {"name": "Zester or grater", "required": true, "alternative": null}]', '[{"symptom": "Pudding is heavy or tough", "likely_cause": "Over-mixing the dough or old self-raising flour", "prevention": "Mix gently until just combined and ensure leavening agents are fresh", "fix": "Cannot be fixed; serve with extra sauce to mask texture"}, {"symptom": "Water inside the pudding basin", "likely_cause": "The foil/paper lid was not tied tightly enough", "prevention": "Tie the string very tightly under the rim and trim excess paper to prevent wicking", "fix": "Slice off the soggy top layer before serving"}]', '["The pleat in the foil lid is crucial; the pudding will expand significantly during steaming, and without room to grow, it becomes dense.", "For a true ''Spotted Dick'' appearance, ensure the currants are well-tossed in the flour mixture before adding liquid to prevent them sinking to the bottom.", "Suet is the traditional fat here because it has a high melting point, which creates small pockets of air in the sponge as it steams, resulting in a distinctively open texture that butter cannot replicate.", "If you do not have a steamer, this can be cooked in a slow cooker on ''High'' for 3-4 hours with water halfway up the basin."]', '"This dish is a variation of the famous British ''Spotted Dick,'' first attested in the mid-19th century. The ''spotted'' refers to the currants, while ''dick'' is widely believed to be a dialectal corruption of ''dough'' or ''pudding.'' It was traditionally a way to make a filling, energy-dense dessert using economical ingredients like suet and dried fruit."', 757.84);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('f898a590-8f8e-4dd3-8a3d-7d661e4d6bfc', 'Pot-Roasted Chicken with Sherry-Mustard Pan Vinaigrette', 'A succulent whole chicken braised in its own juices within a Dutch oven, resulting in tender meat and concentrated fond. The dish is finished with a vibrant, tangy warm vinaigrette created directly in the pot by emulsifying the rich schmaltz with sharp sherry vinegar and Dijon mustard.', 'dinner', 'French', 'Intermediate', '["dijon mustard", "dutch oven", "roast chicken", "sherry vinegar", "whole chicken", "dinner", "main course", "french", "one pot"]', '[{"group_name": "Chicken & Aromatics", "items": [{"name": "whole chicken", "quantity": 1600, "unit": "g", "preparation": "room temperature, patted dry", "notes": "approx 1.5-1.8kg bird", "substitutions": [], "ingredient_id": "2b577d04-33ca-4919-938f-bfc8780a3a4b", "nutrition_source": "USDA FoodData Central"}, {"name": "kosher salt", "quantity": 12, "unit": "g", "preparation": null, "notes": "plus more to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": 2, "unit": "g", "preparation": "freshly ground", "notes": null, "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "shallots", "quantity": 4, "unit": null, "preparation": "peeled and halved", "notes": "approx 100g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "head, halved horizontally", "notes": "approx 50g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sherry-Mustard Vinaigrette", "items": [{"name": "sherry vinegar", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["Champagne vinegar", "Red wine vinegar"], "ingredient_id": "dcfa7371-7051-4604-a76e-4a46ae1f9e7b", "nutrition_source": "Aggregated Public Data"}, {"name": "dijon mustard", "quantity": 15, "unit": "g", "preparation": "smooth", "notes": null, "substitutions": [], "ingredient_id": "82425d1d-cf01-4316-9f94-a82f0be2cb88", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh tarragon", "quantity": 5, "unit": "g", "preparation": "chopped", "notes": "or flat-leaf parsley", "substitutions": [], "ingredient_id": "d424d445-0a4e-45d1-9453-7523eb7b176b", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Position a rack in the lower third of the oven and preheat to 180\u00b0C (350\u00b0F).", "structured": {"action": "PREHEAT", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Generously season the chicken inside and out with the salt and black pepper.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Heat the olive oil in the Dutch oven over medium-high heat. Place the chicken breast-side down and sear until the skin is deep golden brown, about 5-8 minutes. This step builds the flavor base for your sauce.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT8M", "doneness_cues": {"visual": "Deep golden brown skin", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Flip the chicken breast-side up. Scatter the shallots and halved garlic head around the bird. Cover the pot with its lid.", "structured": {"action": "BRAISE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Transfer the covered Dutch oven to the preheated oven. Roast for 50-60 minutes, or until the thickest part of the thigh registers 74\u00b0C (165\u00b0F). The covered environment gently steams the meat in its own juices.", "structured": {"action": "ROAST", "temperature": {"celsius": 74, "fahrenheit": 165}, "duration": "PT1H", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove the chicken from the pot and transfer to a cutting board to rest for at least 15 minutes. Leave the roasted garlic, shallots, and rendered juices in the pot.", "structured": {"action": "REST", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "While the pot is still warm (but off direct heat), add the sherry vinegar and Dijon mustard directly into the pan juices. Whisk vigorously to emulsify the rendered chicken fat with the vinegar. The sauce should become creamy and opaque. Stir in the chopped herbs.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": {"visual": "Creamy, opaque, emulsified sauce", "tactile": null}}, "tips": ["Squeeze the soft roasted garlic cloves out of their skins into the sauce for extra flavor."]}, {"step_number": 8, "phase": "finish", "text": "Carve the chicken and serve immediately, spooning the warm vinaigrette and roasted shallots over the meat.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT1H15M", "total_time": "PT1H40M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Gluten-Free", "Dairy-Free", "Low-Carb", "Paleo", "Whole30", "Nut-Free", "Soy-Free", "Sugar-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 773.18, "protein_g": 85.11, "carbohydrates_g": 12.72, "fat_g": 41.07, "saturated_fat_g": 11.21, "trans_fat_g": 0.4, "monounsaturated_fat_g": 18.02, "polyunsaturated_fat_g": 8.28, "fiber_g": 1.41, "sugar_g": 2.19, "sodium_mg": 1469.48, "cholesterol_mg": 256, "potassium_mg": 1063.53, "calcium_mg": 97.21, "iron_mg": 5.22, "magnesium_mg": 113.6, "phosphorus_mg": 730.92, "zinc_mg": 3.45, "vitamin_a_mcg": 98.76, "vitamin_c_mg": 6.53, "vitamin_d_mcg": 1.6, "vitamin_e_mg": 1.65, "vitamin_k_mcg": 3.49, "vitamin_b6_mg": 2.36, "vitamin_b12_mcg": 1.36, "thiamin_mg": 0.28, "riboflavin_mg": 0.38, "niacin_mg": 39.78, "folate_mcg": 24.96, "water_g": 305.34, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store meat off the bone in an airtight container. Keep sauce separate if possible, as it may separate.", "duration": "P3D"}, "freezer": {"notes": "Meat freezes well; the vinaigrette may break upon thawing and require re-emulsification.", "duration": "P3M"}, "reheating": "Gently warm chicken in a pan with a splash of water or stock. Warm the sauce separately and whisk vigorously to re-emulsify.", "does_not_keep": false}', '[{"name": "Dutch Oven (5-6 liter)", "required": true, "alternative": "Heavy-bottomed pot with tight-fitting lid"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Carving knife", "required": true, "alternative": null}, {"name": "Meat thermometer", "required": true, "alternative": null}]', '[{"symptom": "Vinaigrette tastes greasy or separated", "likely_cause": "The emulsion broke because the fat-to-acid ratio was too high or the temperature dropped too quickly.", "prevention": "Ensure there is enough vinegar to balance the fat; whisk vigorously while the fat is still warm.", "fix": "Add a splash of warm water (1 tsp at a time) and whisk rapidly to re-bind the emulsion."}]', '["Searing the breast side first is crucial\u2014it renders the skin fat which becomes the base of your vinaigrette.", "Sherry vinegar is the gold standard here for its nutty complexity, but cider vinegar works in a pinch for a more rustic flavor.", "If the chicken releases very little juice (common with air-chilled birds), add a splash of chicken stock or water before whisking in the vinegar.", "Don''t discard the roasted garlic skins until you''ve squeezed the sweet, mellow paste into your sauce or spread it on crusty bread."]', '"This technique draws from the French tradition of ''poulet en cocotte,'' where the bird is cooked in a sealed environment to retain moisture. The finish is a variation of a warm vinaigrette sauce, a classic bistro method to cut through the richness of roasted meats using acid and mustard."', 773.18);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('f9351b14-0155-4be8-acd7-ddda62cdfe7c', 'Spicy Gochujang Pork Chops with Cucumber Relish', 'Juicy pork chops marinated in a savory-sweet and spicy fermented chili paste, charred to perfection and balanced by a cooling, crisp cucumber and scallion relish.', 'dinner', 'Korean Fusion', 'Intermediate', '["pork", "barbecue", "grill", "relish", "asian-inspired", "spicy", "summer", "high-protein"]', '[{"group_name": "Pork & Marinade", "items": [{"name": "bone-in pork chops", "quantity": 4, "unit": null, "preparation": "fresh", "notes": "approx. 250g each, 2-3cm thick", "substitutions": ["boneless pork loin chops", "pork shoulder steaks"], "ingredient_id": "8a301973-01d1-48b5-94b8-c9a6c7df3a37", "nutrition_source": "Aggregated Public Data"}, {"name": "gochujang", "quantity": 60, "unit": "g", "preparation": null, "notes": "Korean fermented chili paste", "substitutions": [], "ingredient_id": "01322d91-3959-4671-b230-25f5b14e132a", "nutrition_source": "Aggregated Public Data"}, {"name": "soy sauce", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": ["tamari"], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "brown sugar", "quantity": 30, "unit": "g", "preparation": null, "notes": null, "substitutions": ["honey", "maple syrup"], "ingredient_id": "36d35eb7-2cba-4de4-8ec0-8b95c235c0e0", "nutrition_source": "USDA FoodData Central"}, {"name": "toasted sesame oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8fa9dd65-c49e-449c-b660-a9d9deb638b2", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx. 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "ginger", "quantity": 15, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "mirin", "quantity": 15, "unit": "ml", "preparation": null, "notes": "sweet rice wine", "substitutions": ["water", "apple juice"], "ingredient_id": "2a72c18d-8a1d-4259-8790-25d62f6fb5ba", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Cucumber Relish", "items": [{"name": "cucumber", "quantity": 1, "unit": null, "preparation": "diced", "notes": "English or Persian variety, approx. 300g", "substitutions": [], "ingredient_id": "457adec2-3e06-4efe-a26e-9e6ea9f84924", "nutrition_source": "USDA FoodData Central"}, {"name": "scallions", "quantity": 2, "unit": null, "preparation": "thinly sliced", "notes": "approx. 30g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "USDA FoodData Central"}, {"name": "rice vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fcbf5252-1be9-4dd4-8c22-4fda1dbdca28", "nutrition_source": "Aggregated Public Data"}, {"name": "sugar", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8ae7f905-b311-4f45-9527-5e3840369506", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "roasted sesame seeds", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "f9ac565c-bf29-463d-93f6-d0d93d91cdeb", "nutrition_source": "USDA FoodData Central"}, {"name": "gochugaru", "quantity": 2, "unit": "g", "preparation": null, "notes": "Korean red pepper flakes", "substitutions": [], "ingredient_id": "2fcad8a6-9db2-4702-80cc-60b4e5c4ff98", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Salad Bed", "items": [{"name": "mixed salad greens", "quantity": 150, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "7fce5c84-58b0-45f5-97d7-4887dd813e70", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable oil", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "rice vinegar", "quantity": 5, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fcbf5252-1be9-4dd4-8c22-4fda1dbdca28", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "In a large mixing bowl, whisk together the gochujang, soy sauce, brown sugar, sesame oil, minced garlic, grated ginger, and mirin until smooth.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "Add the pork chops to the bowl, turning them to ensure they are thoroughly coated. Cover and refrigerate for at least 1 hour, or up to 24 hours for deeper flavor.", "structured": {"action": "MARINATE", "temperature": {"celsius": 4, "fahrenheit": 39}, "duration": "PT1H", "doneness_cues": null}, "tips": ["If you are short on time, even 30 minutes at room temperature will help."]}, {"step_number": 3, "phase": "prep", "text": "While the pork marinates, combine diced cucumber, sliced scallions, rice vinegar, sugar, salt, sesame seeds, and gochugaru in a small bowl. Toss to combine and set aside in the refrigerator to chill.", "structured": {"action": "MIX", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Preheat your grill to medium-high heat or heat a cast-iron skillet over medium-high heat with a splash of oil.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Remove pork chops from the marinade, shaking off excess sauce to prevent burning. Grill or sear the chops for 4-5 minutes per side, until well-charred and cooked through.", "structured": {"action": "GRILL", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Char marks present, meat is opaque", "tactile": "Firm to the touch"}}, "tips": ["The sugar in the marinade burns easily, so watch the heat carefully."]}, {"step_number": 6, "phase": "cook", "text": "Check the internal temperature of the pork at the thickest part. It should reach at least 63\u00b0C (145\u00b0F). Remove from heat.", "structured": {"action": "MEASURE", "temperature": {"celsius": 63, "fahrenheit": 145}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Let the pork rest on a board or warm plate for 5 minutes to allow juices to redistribute.", "structured": {"action": "REST", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "assemble", "text": "Toss the mixed greens with vegetable oil and rice vinegar. Serve the rested pork chops alongside the salad, topped generously with the cucumber relish.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT1H10M", "total_time": "PT1H45M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Dairy-Free", "Nut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 665.14, "protein_g": 51.63, "carbohydrates_g": 27.95, "fat_g": 37.99, "saturated_fat_g": 11.73, "trans_fat_g": 0.2, "monounsaturated_fat_g": 12.52, "polyunsaturated_fat_g": 5.16, "fiber_g": 1.94, "sugar_g": 19.55, "sodium_mg": 2507.16, "cholesterol_mg": 157.5, "potassium_mg": 1028.73, "calcium_mg": 145.96, "iron_mg": 2.51, "magnesium_mg": 72.33, "phosphorus_mg": 565.02, "zinc_mg": 6.85, "vitamin_a_mcg": 171.07, "vitamin_c_mg": 9.57, "vitamin_d_mcg": 1.75, "vitamin_e_mg": 0.6, "vitamin_k_mcg": 27.9, "vitamin_b6_mg": 1.18, "vitamin_b12_mcg": 1.38, "thiamin_mg": 1.3, "riboflavin_mg": 0.81, "niacin_mg": 16.99, "folate_mcg": 11.88, "water_g": 252.44, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store pork and relish in separate airtight containers. The relish may lose crispness after 24 hours.", "duration": "P3D"}, "freezer": {"notes": "Freeze raw marinated pork. Cooked pork can be frozen but may dry out upon reheating. Do not freeze the relish.", "duration": "P2M"}, "reheating": "Reheat pork gently in a skillet over low heat with a splash of water to prevent drying out.", "does_not_keep": false}', '[{"name": "Large mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Grill or cast-iron skillet", "required": true, "alternative": "Heavy-bottomed frying pan"}, {"name": "Tongs", "required": true, "alternative": null}, {"name": "Meat thermometer", "required": true, "alternative": null}]', '[{"symptom": "Marinade is burning before the meat is cooked", "likely_cause": "Heat is too high or too much sugar/paste was left on the meat", "prevention": "Wipe off excess marinade before cooking; cook over medium rather than high heat", "fix": "Move to a cooler part of the grill or lower the stove heat immediately; finish cooking in the oven at 180\u00b0C/350\u00b0F if the crust is already dark"}, {"symptom": "Pork chops are dry and tough", "likely_cause": "Overcooking", "prevention": "Use a meat thermometer and pull exactly at 63\u00b0C/145\u00b0F", "fix": "Slice thinly and toss with extra relish juices to add moisture"}]', '["Gochujang varies in spice level. Check the container''s heat indicator (usually 1 to 5) and adjust the amount or add honey if yours is very spicy.", "Scoring the fat cap on the pork chops (slicing through the fat strip on the edge every 2cm) prevents the chops from curling up in the pan.", "For the salad, a light dressing is preferred because the relish and pork are flavor-dense. A simple sesame oil drizzle is often enough.", "Make extra marinade to boil down separately as a glazing sauce if you prefer ''saucy'' chops, but never use raw marinade that touched pork without boiling it first."]', '"Gochujang is a fundamental ingredient in Korean cuisine, a savory, sweet, and spicy fermented condiment made from chili powder, glutinous rice, and soybeans. This dish applies classic Korean BBQ (Gogi-gu-i) flavors to a Western-style thick-cut pork chop presentation, bridging traditional fermentation techniques with modern grilling."', 665.14);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('fa2dccb2-cb13-40e6-9899-0ee42c080ccd', 'Slow-Braised Masala Brisket Curry', 'A deeply savory, robust curry featuring tender chunks of buffalo or beef brisket slow-cooked in a caramelized onion and tomato gravy. Fragrant with cardamom, cinnamon, and a warming blend of ground spices, the sauce clings luxuriously to the gelatinous meat.', 'dinner', 'Indian', 'Intermediate', '["curry", "stew", "beef", "buffalo", "indian", "comfort food", "spicy"]', '[{"group_name": "Meat & Marinade", "items": [{"name": "beef brisket or buffalo meat", "quantity": 1000, "unit": "g", "preparation": "cut into 4cm cubes", "notes": "Trim excess hard fat but leave some for flavor", "substitutions": [], "ingredient_id": "f6e328f8-bc0d-4678-9286-954e3bb5f3e3", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 10, "unit": "g", "preparation": null, "notes": "approx 2 tsp", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 45, "unit": "ml", "preparation": "divided", "notes": "grapeseed or vegetable oil", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Whole Spices", "items": [{"name": "cinnamon stick", "quantity": 1, "unit": null, "preparation": null, "notes": "approx 5g", "substitutions": [], "ingredient_id": "a789fa1a-78af-4718-b6f8-1a3bb6a6c92d", "nutrition_source": "USDA FoodData Central"}, {"name": "green cardamom pods", "quantity": 6, "unit": null, "preparation": null, "notes": "lightly crushed", "substitutions": [], "ingredient_id": "c56f6cd8-882c-487c-956f-3a91ee1fec07", "nutrition_source": "USDA FoodData Central"}, {"name": "cloves", "quantity": 4, "unit": null, "preparation": null, "notes": "whole", "substitutions": [], "ingredient_id": "7b3bf68a-3ae9-4dad-91f4-6c7a14ec5e0e", "nutrition_source": "USDA FoodData Central"}, {"name": "bay leaf", "quantity": 2, "unit": null, "preparation": null, "notes": "dried", "substitutions": [], "ingredient_id": "eab2ef3a-7a0e-4188-b746-645b795ada1e", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Base & Aromatics", "items": [{"name": "red onions", "quantity": 400, "unit": "g", "preparation": "finely diced", "notes": null, "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "USDA FoodData Central"}, {"name": "ginger garlic paste", "quantity": 40, "unit": "g", "preparation": null, "notes": "or 20g minced ginger + 20g minced garlic", "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "green chilies", "quantity": 2, "unit": null, "preparation": "slit lengthwise", "notes": "approx 10g, adjust to taste", "substitutions": [], "ingredient_id": "6cdb0615-378e-4bfa-b76d-f19bbd780e6c", "nutrition_source": "USDA FoodData Central"}, {"name": "crushed tomatoes", "quantity": 400, "unit": "g", "preparation": null, "notes": "fresh or canned", "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Ground Spices", "items": [{"name": "coriander powder", "quantity": 10, "unit": "g", "preparation": null, "notes": "approx 2 tsp", "substitutions": [], "ingredient_id": "225e04a2-508a-4752-ac80-1f8437a6c970", "nutrition_source": "USDA FoodData Central"}, {"name": "cumin powder", "quantity": 5, "unit": "g", "preparation": null, "notes": "approx 1 tsp", "substitutions": [], "ingredient_id": "b9c9e3cb-61b7-4bbc-87c0-7858d42d7935", "nutrition_source": "USDA FoodData Central"}, {"name": "kashmiri chili powder", "quantity": 10, "unit": "g", "preparation": null, "notes": "mild paprika can substitute for color", "substitutions": [], "ingredient_id": "95bf3619-4042-48ea-8f4d-86f61e1721c6", "nutrition_source": "USDA FoodData Central"}, {"name": "turmeric powder", "quantity": 3, "unit": "g", "preparation": null, "notes": "approx 0.5 tsp", "substitutions": [], "ingredient_id": "1ee1ad9b-8638-45be-82a4-683925a61d05", "nutrition_source": "USDA FoodData Central"}, {"name": "garam masala", "quantity": 5, "unit": "g", "preparation": null, "notes": "approx 1 tsp, added at finish", "substitutions": [], "ingredient_id": "8ffcea01-5f22-462b-94de-ad2a97049325", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Liquid & Garnish", "items": [{"name": "water", "quantity": 500, "unit": "ml", "preparation": null, "notes": "hot water preferred", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh cilantro", "quantity": 15, "unit": "g", "preparation": "chopped", "notes": null, "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Pat the brisket cubes dry with paper towels and season thoroughly with the salt. Heat 30ml of oil in the Dutch oven over medium-high heat until shimmering.", "structured": {"action": "SEASON", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Sear the meat in batches, browning deeply on all sides. Do not overcrowd the pot. Remove browned meat and set aside.", "structured": {"action": "SEAR", "temperature": null, "duration": null, "doneness_cues": {"visual": "Deep golden brown crust", "tactile": "Meat releases from pan"}}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Lower heat to medium. Add the remaining 15ml oil. Add cinnamon, cardamom, cloves, and bay leaf. Saut\u00e9 briefly until fragrant and the pods swell slightly.", "structured": {"action": "BLOOM", "temperature": null, "duration": "PT1M", "doneness_cues": {"visual": "Spices sizzle and darken slightly", "tactile": "Aromatic oil"}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the finely diced onions. Cook slowly, stirring frequently, until the onions turn a deep golden brown. This is critical for the sauce base.", "structured": {"action": "CARAMELIZE", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT20M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Stir in the ginger-garlic paste and slit green chilies. Cook for 2 minutes until the raw smell of garlic disappears.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Reduce heat to low. Add coriander, cumin, Kashmiri chili powder, and turmeric. Stir constantly to toast the spices without burning them.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Add the crushed tomatoes. Increase heat to medium and cook until the moisture evaporates and oil begins to separate from the sides of the masala paste (bhoona).", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Oil separates and pools at edges", "tactile": null}}, "tips": []}, {"step_number": 8, "phase": "cook", "text": "Return the seared meat and its resting juices to the pot. Stir to coat well with the masala. Add 500ml hot water and bring to a boil.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 9, "phase": "cook", "text": "Cover tightly, reduce heat to the lowest setting, and simmer gently until the meat is fork-tender. Check occasionally and add a splash more water if the curry becomes too dry.", "structured": {"action": "BRAISE", "temperature": {"celsius": 85, "fahrenheit": 185}, "duration": "PT2H30M", "doneness_cues": {"visual": null, "tactile": "Meat pulls apart easily with a fork"}}, "tips": []}, {"step_number": 10, "phase": "finish", "text": "Remove lid. If the sauce is too thin, simmer uncovered to reach desired consistency. Stir in the garam masala and fresh cilantro. Turn off heat and let rest for 10 minutes before serving.", "structured": {"action": "REST", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}]', '{"active_time": "PT45M", "passive_time": "PT3H", "total_time": "PT3H45M", "overnight_required": false, "yields": "6 servings", "yield_count": 6, "serving_size_g": 350}', '{"flags": ["Gluten-Free", "Dairy-Free", "Egg-Free", "Nut-Free", "Soy-Free", "Paleo", "Whole30"], "not_suitable_for": []}', '{"per_serving": {"calories": 407.74, "protein_g": 36.18, "carbohydrates_g": 14.21, "fat_g": 24.17, "saturated_fat_g": 7.22, "trans_fat_g": 0.83, "monounsaturated_fat_g": 8.08, "polyunsaturated_fat_g": 0.88, "fiber_g": 4.92, "sugar_g": 5.83, "sodium_mg": 842.3, "cholesterol_mg": 111.67, "potassium_mg": 983.92, "calcium_mg": 85.56, "iron_mg": 5.34, "magnesium_mg": 68.77, "phosphorus_mg": 407.33, "zinc_mg": 8.89, "vitamin_a_mcg": 84.1, "vitamin_c_mg": 19.07, "vitamin_d_mcg": 0.17, "vitamin_e_mg": 1, "vitamin_k_mcg": 5.39, "vitamin_b6_mg": 1.12, "vitamin_b12_mcg": 2.93, "thiamin_mg": 0.17, "riboflavin_mg": 0.3, "niacin_mg": 10.48, "folate_mcg": 19.83, "water_g": 266.56, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Flavors deepen significantly after 24 hours.", "duration": "P4D"}, "freezer": {"notes": "Thaw overnight in the refrigerator before reheating.", "duration": "P3M"}, "reheating": "Gently simmer on the stovetop with a splash of water to loosen the sauce.", "does_not_keep": false}', '[{"name": "Dutch oven or heavy-bottomed pot", "required": true, "alternative": "Large pot with lid"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Wooden spoon or spatula", "required": true, "alternative": null}]', '[{"symptom": "Meat is tough or chewy", "likely_cause": "Collagen has not yet broken down", "prevention": "Maintain a low simmer for the full duration", "fix": "Add a splash of water, cover, and continue cooking for another 30-45 minutes"}, {"symptom": "Sauce tastes bitter", "likely_cause": "Spices or onions burned during the saut\u00e9 phase", "prevention": "Cook onions on medium heat and stir powdered spices constantly on low heat", "fix": "Stir in a teaspoon of sugar or a splash of coconut milk to mask bitterness"}]', '["Caramelizing the onions (step 4) is the most important step for flavor depth; do not rush this process or the curry will taste flat.", "This dish tastes significantly better the next day as the spices mature and penetrate the meat fibers.", "Brisket is collagen-rich; if you cannot find it, chuck roast or beef shin are excellent alternatives.", "For a richer finish, you can stir in a tablespoon of ghee right at the end with the garam masala."]', '"This style of ''Bhoona'' cooking involves frying spices in oil to release essential oils, then slow-cooking meat in its own juices with minimal added liquid. It is a technique ubiquitous across North India and Pakistan, often used for tougher cuts of meat like buffalo or mutton that require long cooking times to become tender."', 407.74);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('fa4a214c-5a54-4074-8af7-3356697561b4', 'Stout-Braised Beef Cheeks with Pearl Barley Risotto', 'Succulent beef cheeks slow-cooked in dark stout until meltingly tender, served atop a creamy, nutty pearl barley risotto. The richness is cut by a vibrant horseradish and lemon gremolata garnish.', 'dinner', 'Modern European', 'Advanced', '["risotto", "beef", "barley", "braised", "main course", "winter warmer", "comfort food", "gastropub"]', '[{"group_name": "Braised Beef Cheeks", "items": [{"name": "beef cheeks", "quantity": 800, "unit": "g", "preparation": "trimmed of excess fat and silverskin", "notes": "allow 200g raw weight per person", "substitutions": [], "ingredient_id": "33950cf0-20ef-4681-9e93-8bc7e6f5f246", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}, {"name": "onion", "quantity": 1, "unit": null, "preparation": "rough chopped", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "carrot", "quantity": 1, "unit": null, "preparation": "rough chopped", "notes": "approx 100g", "substitutions": [], "ingredient_id": "9d020677-cb7a-444c-98e3-1a982ae39df4", "nutrition_source": "USDA FoodData Central"}, {"name": "celery stalk", "quantity": 1, "unit": null, "preparation": "rough chopped", "notes": "approx 60g", "substitutions": [], "ingredient_id": "174de298-3765-49e2-821b-415a9f6213d1", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "crushed", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "stout beer", "quantity": 440, "unit": "ml", "preparation": null, "notes": "Guinness or similar dark beer", "substitutions": [], "ingredient_id": "91260640-ac41-426c-b6ec-5b696e575d70", "nutrition_source": "Aggregated Public Data"}, {"name": "beef stock", "quantity": 500, "unit": "ml", "preparation": "high quality or homemade", "notes": null, "substitutions": [], "ingredient_id": "390b2a8f-1613-4b2d-ae97-8403bbc9f505", "nutrition_source": "Aggregated Public Data"}, {"name": "fresh thyme", "quantity": 4, "unit": null, "preparation": null, "notes": "sprigs", "substitutions": [], "ingredient_id": "f7fca6a3-4acc-467b-8c01-ba2a5b816703", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Barley Risotto", "items": [{"name": "pearl barley", "quantity": 300, "unit": "g", "preparation": "rinsed", "notes": null, "substitutions": [], "ingredient_id": "87e95008-069a-4ea0-ab7f-72ddd39a8ef7", "nutrition_source": "USDA FoodData Central"}, {"name": "unsalted butter", "quantity": 60, "unit": "g", "preparation": "cubed, divided use", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 2, "unit": null, "preparation": "finely diced", "notes": "approx 60g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "dry white wine", "quantity": 120, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "5bfd1062-ff60-4231-878c-966a8c355246", "nutrition_source": "Aggregated Public Data"}, {"name": "chicken stock", "quantity": 1000, "unit": "ml", "preparation": "hot", "notes": "approximate need, keep extra on hand", "substitutions": [], "ingredient_id": "ba5595e6-e708-4989-9687-6837b15f9b83", "nutrition_source": "Aggregated Public Data"}, {"name": "parmesan cheese", "quantity": 60, "unit": "g", "preparation": "freshly grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Gremolata Garnish", "items": [{"name": "fresh parsley", "quantity": 15, "unit": "g", "preparation": "finely chopped", "notes": null, "substitutions": [], "ingredient_id": "3f818392-5426-4c7d-93de-f2451df41f2f", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": "zested", "notes": "zest only", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh horseradish", "quantity": 10, "unit": "g", "preparation": "finely grated", "notes": "adjust to taste", "substitutions": [], "ingredient_id": "3435f8a5-626e-4cb0-b00e-b0d87515ba9e", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 150\u00b0C (300\u00b0F). Pat the beef cheeks dry and season generously with salt and pepper.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "In a Dutch oven over high heat, sear the beef cheeks in vegetable oil until deeply browned on all sides. Remove beef and set aside.", "structured": {"action": "SEAR", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Lower heat to medium. Add onions, carrots, and celery to the pot. Saut\u00e9 until softened and lightly browned.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT8M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Deglaze the pot with the stout, scraping the bottom to release fond. Return beef cheeks to the pot. Add beef stock, thyme, and garlic. Bring to a simmer, cover, and transfer to the oven.", "structured": {"action": "BRAISE", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": "PT3H30M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "About 45 minutes before the beef is done, start the risotto. Melt 30g butter in a wide pan over medium heat. Sweat the shallots until translucent but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Add pearl barley and toast for 2 minutes until nutty. Pour in wine and stir until fully evaporated.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "cook", "text": "Begin adding hot chicken stock one ladle at a time, stirring frequently. Allow liquid to absorb before adding the next ladle. Continue until barley is tender but retains a slight chew (al dente).", "structured": {"action": "SIMMER", "temperature": null, "duration": "PT35M", "doneness_cues": {"visual": null, "tactile": "Barley is tender with a slight bite"}}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Remove beef from oven. Ideally, the meat should yield easily to pressure (internal temp approx 90\u00b0C/195\u00b0F+ for collagen breakdown). Remove cheeks and strain the liquid into a clean pan. Reduce liquid over high heat until it coats the back of a spoon (nappe consistency).", "structured": {"action": "REDUCE", "temperature": null, "duration": "PT10M", "doneness_cues": {"visual": "Sauce coats back of spoon", "tactile": null}}, "tips": []}, {"step_number": 9, "phase": "finish", "text": "Remove risotto from heat. Beat in the remaining 30g butter and parmesan cheese vigorously to create a creamy emulsion (mantecatura). Season with salt to taste.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 10, "phase": "assemble", "text": "Mix the parsley, lemon zest, and horseradish. Plate a mound of risotto, top with a glazed beef cheek, drizzle with reduced sauce, and finish with the horseradish gremolata.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT50M", "passive_time": "PT3H30M", "total_time": "PT4H20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 480}', '{"flags": ["Nut-Free", "Peanut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": ["Coeliacs (Barley contains gluten)", "Lactose intolerant"]}', '{"per_serving": {"calories": 1401.21, "protein_g": 92.65, "carbohydrates_g": 97.54, "fat_g": 65.51, "saturated_fat_g": 25.65, "trans_fat_g": null, "monounsaturated_fat_g": 4.78, "polyunsaturated_fat_g": 1.03, "fiber_g": 14.28, "sugar_g": 20.87, "sodium_mg": 1200.36, "cholesterol_mg": 42.45, "potassium_mg": 853.63, "calcium_mg": 257.19, "iron_mg": 8.48, "magnesium_mg": 98.46, "phosphorus_mg": 437.35, "zinc_mg": 12.23, "vitamin_a_mcg": 366.88, "vitamin_c_mg": 14.84, "vitamin_d_mcg": 0.08, "vitamin_e_mg": 0.65, "vitamin_k_mcg": 72.49, "vitamin_b6_mg": 0.4, "vitamin_b12_mcg": 0.21, "thiamin_mg": 0.21, "riboflavin_mg": 0.19, "niacin_mg": 3.96, "folate_mcg": 47.53, "water_g": 103.52, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store beef and risotto in separate airtight containers. Risotto will thicken significantly when chilled.", "duration": "P3D"}, "freezer": {"notes": "Beef freezes excellently in its sauce. Barley risotto texture may degrade slightly upon freezing.", "duration": "P3M"}, "reheating": "Reheat beef gently in a pot. Reheat risotto with a splash of water or stock to loosen the starch.", "does_not_keep": false}', '[{"name": "Dutch oven with lid", "required": true, "alternative": "Heavy bottomed pot and oven-safe dish with foil"}, {"name": "Wide saucepan", "required": true, "alternative": "Deep skillet"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Microplane or zester", "required": true, "alternative": null}, {"name": "Tongs", "required": true, "alternative": null}]', '[{"symptom": "Beef cheeks are tough", "likely_cause": "Collagen has not yet broken down; cooking time was insufficient", "prevention": "Test texture before removing from oven; they must be fork-tender", "fix": "Return to the oven (covered) for another 30-45 minutes"}, {"symptom": "Risotto is gummy or pasty", "likely_cause": "Over-agitated or overcooked barley", "prevention": "Stir frequently but not constantly; stop cooking when al dente", "fix": "Stir in a splash of hot stock and serve immediately"}]', '["Beef cheeks are rich in collagen. Unlike steak, you cannot cook them to ''medium-rare''; they must be cooked well past well-done until the connective tissue turns into gelatin.", "Barley is more forgiving than Arborio rice. It doesn''t release starch as quickly, so you can add stock in larger batches, but the final ''beating in'' of butter and cheese is crucial for that risotto consistency.", "For a deeper gloss on the beef, toss the cooked cheeks in the reduced sauce just before plating to glaze them completely.", "If you cannot find fresh horseradish, a high-quality jarred creamed horseradish can be mixed into the risotto at the end instead of used as a garnish."]', '"This dish bridges the gap between the humble Italian ''orzotto'' (barley risotto) and the British tradition of braising cheaper cuts of meat in ale. Barley has been a staple grain in Europe for millennia, often favored in colder northern climates where wine grapes (for traditional risotto) were scarce."', 1401.21);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('faffa8f1-9304-4b89-8037-d7833d3ffa7e', 'Creamy Sesame Soba with Seared Tofu & Shiitakes', 'A robust, earthy noodle bowl featuring chewy buckwheat noodles tossed in a rich, nutty (but nut-free) tahini sauce. Crisp-edged tofu and savory shiitake mushrooms provide protein and umami, while blanched broccoli adds a fresh crunch.', 'lunch', 'Japanese Fusion', 'Easy', '["asian", "broccoli", "shiitake", "soba noodle", "dinner", "easy", "lunch", "quick", "main course", "dairy-free", "halal", "healthy", "high fiber", "kosher", "low cholesterol", "nut-free", "vegan", "vegetarian"]', '[{"group_name": "Proteins & Vegetables", "items": [{"name": "firm tofu", "quantity": 400, "unit": "g", "preparation": "pressed and cubed", "notes": "1 standard block", "substitutions": [], "ingredient_id": "1ba9238a-ce4f-4ca5-920d-7f483d9987aa", "nutrition_source": "USDA FoodData Central"}, {"name": "dried soba noodles", "quantity": 250, "unit": "g", "preparation": "dry", "notes": null, "substitutions": [], "ingredient_id": "8080cc31-f977-46d8-a72b-dd84a250ba92", "nutrition_source": "Aggregated Public Data"}, {"name": "broccoli", "quantity": 300, "unit": "g", "preparation": "cut into small florets", "notes": null, "substitutions": [], "ingredient_id": "b0a26615-a0a7-4b5c-9143-e9becf53b41a", "nutrition_source": "USDA FoodData Central"}, {"name": "shiitake mushrooms", "quantity": 200, "unit": "g", "preparation": "stems removed, sliced", "notes": "fresh, not dried", "substitutions": [], "ingredient_id": "127ce8a8-238d-40e6-a4b0-c58c42a7c745", "nutrition_source": "USDA FoodData Central"}, {"name": "neutral oil", "quantity": 30, "unit": "ml", "preparation": "divided", "notes": "grapeseed or canola", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Nut-Free \"Nutty\" Sauce", "items": [{"name": "tahini", "quantity": 60, "unit": "ml", "preparation": "well stirred", "notes": "sesame paste", "substitutions": [], "ingredient_id": "87ae6455-8e22-4c1b-bad7-89fa69c4dc57", "nutrition_source": "Aggregated Public Data"}, {"name": "soy sauce", "quantity": 45, "unit": "ml", "preparation": null, "notes": "use tamari if gluten-free required", "substitutions": [], "ingredient_id": "a3c13611-4174-49d9-b957-12e63638e78c", "nutrition_source": "Aggregated Public Data"}, {"name": "rice vinegar", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fcbf5252-1be9-4dd4-8c22-4fda1dbdca28", "nutrition_source": "Aggregated Public Data"}, {"name": "toasted sesame oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "8fa9dd65-c49e-449c-b660-a9d9deb638b2", "nutrition_source": "Aggregated Public Data"}, {"name": "maple syrup", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "c9ca1f35-b107-46c2-92a3-4c1c620f3c11", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh ginger", "quantity": 10, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "d57750c1-f582-4793-8aea-40d9d3ac3677", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 2, "unit": null, "preparation": "minced", "notes": "approx 6g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "water", "quantity": 30, "unit": "ml", "preparation": null, "notes": "to thin sauce", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Garnish", "items": [{"name": "green onions", "quantity": 2, "unit": null, "preparation": "thinly sliced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "dcfaf926-661e-4117-aeea-145370b787f7", "nutrition_source": "Aggregated Public Data"}, {"name": "toasted sesame seeds", "quantity": 5, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "0edc9256-6bac-4718-9f80-12351b1bc941", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Wrap the tofu block in a clean kitchen towel or paper towels and place a heavy object (like a skillet) on top. Let it press for 15 minutes to remove excess moisture. Cube into 2cm pieces.", "structured": {"action": "DRAIN", "temperature": null, "duration": "PT15M", "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "prep", "text": "In a small mixing bowl, whisk together tahini, soy sauce, rice vinegar, sesame oil, maple syrup, grated ginger, minced garlic, and water until smooth and creamy.", "structured": {"action": "WHISK", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Bring a large pot of water to a boil. Add soba noodles and cook according to package instructions (usually 4-5 minutes). In the last 2 minutes of cooking, add the broccoli florets to the same pot to blanch. Drain and immediately rinse vigorously under cold running water to stop cooking and remove excess starch.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "While noodles cook, heat 15ml of neutral oil in a large skillet over medium-high heat. Add tofu cubes in a single layer. Fry undisturbed for 2-3 minutes until golden, then flip and brown the other sides. Remove tofu from pan and set aside.", "structured": {"action": "FRY", "temperature": {"celsius": 190, "fahrenheit": 374}, "duration": "PT6M", "doneness_cues": {"visual": "Golden brown crust", "tactile": "Crispy exterior"}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "In the same skillet, add the remaining 15ml oil. Add sliced shiitake mushrooms. Saut\u00e9 for 4-5 minutes until browned and tender.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 180, "fahrenheit": 356}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Reduce heat to low. Return the tofu to the pan with the mushrooms. Add the drained noodles and broccoli. Pour the sauce over everything and toss gently using tongs until evenly coated and warmed through.", "structured": {"action": "TOSS", "temperature": null, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Divide into bowls. Garnish generously with sliced green onions and toasted sesame seeds before serving.", "structured": {"action": "GARNISH", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT15M", "total_time": "PT40M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Vegan", "Vegetarian", "Dairy-Free", "Egg-Free", "Nut-Free", "High Fiber"], "not_suitable_for": ["Sesame allergy"]}', '{"per_serving": {"calories": 405.04, "protein_g": 18.39, "carbohydrates_g": 32.32, "fat_g": 25.77, "saturated_fat_g": 3.82, "trans_fat_g": null, "monounsaturated_fat_g": 1.32, "polyunsaturated_fat_g": 3.07, "fiber_g": 5.84, "sugar_g": 8.84, "sodium_mg": 1874.39, "cholesterol_mg": null, "potassium_mg": 647.94, "calcium_mg": 546.07, "iron_mg": 8.44, "magnesium_mg": 121.33, "phosphorus_mg": 314.52, "zinc_mg": 2.54, "vitamin_a_mcg": 25.13, "vitamin_c_mg": 68.3, "vitamin_d_mcg": 0.2, "vitamin_e_mg": 0.63, "vitamin_k_mcg": 86.69, "vitamin_b6_mg": 0.36, "vitamin_b12_mcg": null, "thiamin_mg": 0.16, "riboflavin_mg": 0.31, "niacin_mg": 2.73, "folate_mcg": 72.68, "water_g": 211.41, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Sauce may thicken; loosen with a splash of warm water when reheating.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; tofu texture becomes spongy and noodles mushy.", "duration": null}, "reheating": "Microwave on medium power or stir-fry gently in a pan with a splash of water.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Large skillet or wok", "required": true, "alternative": null}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Small mixing bowl", "required": true, "alternative": null}, {"name": "Whisk", "required": true, "alternative": null}]', '[{"symptom": "Soba noodles are gummy or clumped together", "likely_cause": "Noodles were not rinsed thoroughly after boiling", "prevention": "Rinse cooked noodles vigorously under cold running water to remove surface starch", "fix": "Rinse again under warm water to separate, though texture may be compromised"}]', '["To ensure this dish is 100% nut-free while maintaining a ''nutty'' profile, we rely on tahini (sesame seed paste). Always check labels to ensure your tahini is produced in a nut-free facility if allergies are severe.", "Soba noodles vary in composition. ''Ni-hachi'' soba is 20% wheat and 80% buckwheat, offering a good balance of chew and flavor. 100% buckwheat soba is gluten-free but more brittle; handle gently.", "Pressing the tofu is crucial. If you skip this step, the tofu will steam instead of sear, resulting in a soggy texture rather than a crisp contrast to the noodles.", "If using dried shiitakes instead of fresh, rehydrate them in hot water for 20 minutes before slicing. You can use a splash of the soaking liquid to thin the sauce for extra umami."]', '"Soba (buckwheat noodles) has been a staple in Tokyo (Edo) culture since the Tokugawa period, valued for its nutritional profile compared to white rice. This preparation uses a ''goma-dare'' style sauce, highlighting the Buddhist vegetarian tradition (Shojin Ryori) of using sesame to provide richness without animal fats."', 405.04);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('fe54a633-a043-4b05-9a8f-80ecee5e19ed', 'Pan-Fried Sea Bream with Heritage Tomato & Nasturtium Pesto', 'A celebration of summer textures and temperatures. Crispy-skinned sea bream fillets rest atop a sweet and savory base of roasted red onions and juicy heritage tomatoes. The dish is finished with crunchy sourdough croutons and a vibrant, peppery nasturtium leaf pesto that cuts through the richness of the fish.', 'dinner', 'Modern European', 'Intermediate', '["fish", "sea bream", "salad", "pesto", "tomatoes", "roast", "pan-fry", "summer", "modern european"]', '[{"group_name": "Roasted Onions & Croutons", "items": [{"name": "red onions", "quantity": 3, "unit": null, "preparation": "cut into wedges", "notes": "approx. 400g total", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "sourdough bread", "quantity": 150, "unit": "g", "preparation": "torn into bite-sized chunks", "notes": null, "substitutions": [], "ingredient_id": "90f297c6-9ec3-45a6-850d-9aa9c65b45e7", "nutrition_source": "Aggregated Public Data"}, {"name": "olive oil", "quantity": 30, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Nasturtium Pesto", "items": [{"name": "nasturtium leaves", "quantity": 50, "unit": "g", "preparation": "washed and dried", "notes": null, "substitutions": [], "ingredient_id": "52309fb6-5fa1-4383-a329-4443e13456fd", "nutrition_source": "Aggregated Public Data"}, {"name": "pine nuts", "quantity": 30, "unit": "g", "preparation": "lightly toasted", "notes": null, "substitutions": ["almonds", "walnuts"], "ingredient_id": "971298ad-a9d7-49f7-811b-46afedad18d4", "nutrition_source": "Aggregated Public Data"}, {"name": "parmesan cheese", "quantity": 30, "unit": "g", "preparation": "grated", "notes": null, "substitutions": [], "ingredient_id": "f637b882-56bc-4ac8-86d5-c508da7d6712", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": null, "notes": "approx. 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "extra virgin olive oil", "quantity": 80, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon juice", "quantity": 10, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Tomato Salad", "items": [{"name": "heritage tomatoes", "quantity": 600, "unit": "g", "preparation": "mixed colors, sliced", "notes": null, "substitutions": [], "ingredient_id": "9579a1ee-33e0-430e-8c34-b9fa2f32c020", "nutrition_source": "Aggregated Public Data"}, {"name": "extra virgin olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "sea salt flakes", "quantity": 3, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "cracked black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Sea Bream", "items": [{"name": "sea bream fillets", "quantity": 4, "unit": null, "preparation": "skin-on, pin-boned", "notes": "approx. 140g each", "substitutions": [], "ingredient_id": "6a48f21f-c58c-4584-a81e-600a6cd4b283", "nutrition_source": "Aggregated Public Data"}, {"name": "vegetable oil", "quantity": 20, "unit": "ml", "preparation": null, "notes": "for frying", "substitutions": [], "ingredient_id": "a0f5fd8e-28e3-46ca-9b60-49060768c107", "nutrition_source": null}, {"name": "unsalted butter", "quantity": 20, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 0.5, "unit": null, "preparation": null, "notes": "cut into wedges for serving", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Preheat the oven to 200\u00b0C (400\u00b0F). Toss the red onion wedges with half the olive oil and salt on a baking sheet.", "structured": {"action": "PREHEAT", "temperature": {"celsius": 200, "fahrenheit": 392}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Roast the onions for 20 minutes. Add the torn sourdough chunks to the same tray, drizzle with remaining olive oil, and roast for another 10-12 minutes until onions are soft and croutons are golden crisp.", "structured": {"action": "ROAST", "temperature": null, "duration": "PT32M", "doneness_cues": {"visual": "Onions caramelized at edges, bread golden brown", "tactile": "Croutons crisp"}}, "tips": []}, {"step_number": 3, "phase": "prep", "text": "While onions roast, combine nasturtium leaves, toasted pine nuts, Parmesan, and garlic in a food processor. Pulse while streaming in the extra virgin olive oil until a vibrant green sauce forms. Stir in lemon juice and season to taste.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "prep", "text": "Slice the heritage tomatoes into irregular shapes. Place in a bowl, season generously with sea salt flakes and black pepper, and drizzle with 15ml olive oil. Let them stand at room temperature to release their juices.", "structured": {"action": "MARINATE", "temperature": null, "duration": "PT10M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Pat the sea bream fillets thoroughly dry with paper towels. Season both sides with salt. Heat vegetable oil in a skillet over medium-high heat. Place fish skin-side down and press firmly with a spatula for 30 seconds to prevent curling.", "structured": {"action": "SEAR", "temperature": null, "duration": "PT30S", "doneness_cues": null}, "tips": []}, {"step_number": 6, "phase": "cook", "text": "Cook undisturbed for 4-5 minutes until the skin is crispy and the flesh is opaque 2/3 of the way up. Flip carefully, add the butter to the pan, and cook for 1 minute on the flesh side until cooked through (internal temp 60\u00b0C/140\u00b0F).", "structured": {"action": "FRY", "temperature": {"celsius": 60, "fahrenheit": 140}, "duration": "PT6M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "assemble", "text": "Arrange the roasted onions, tomatoes (with their juices), and croutons on plates. Drizzle with nasturtium pesto. Place the sea bream skin-side up on top. Garnish with fresh nasturtium flowers if available.", "structured": {"action": "PLATE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT35M", "passive_time": "PT30M", "total_time": "PT1H5M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 380}', '{"flags": ["Pescatarian"], "not_suitable_for": ["Nut allergies (pesto)", "Gluten intolerance (croutons)"]}', '{"per_serving": {"calories": 699.87, "protein_g": 34.91, "carbohydrates_g": 36.49, "fat_g": 46.7, "saturated_fat_g": 8.61, "trans_fat_g": null, "monounsaturated_fat_g": 24.56, "polyunsaturated_fat_g": 3.51, "fiber_g": 6.19, "sugar_g": 10.93, "sodium_mg": 1151.53, "cholesterol_mg": 15.85, "potassium_mg": 960.33, "calcium_mg": 192.39, "iron_mg": 2.04, "magnesium_mg": 81.21, "phosphorus_mg": 484.76, "zinc_mg": 1.53, "vitamin_a_mcg": 93.19, "vitamin_c_mg": 42.21, "vitamin_d_mcg": 0.04, "vitamin_e_mg": 4.68, "vitamin_k_mcg": 20.53, "vitamin_b6_mg": 0.16, "vitamin_b12_mcg": 0.1, "thiamin_mg": 0.06, "riboflavin_mg": 0.06, "niacin_mg": 0.17, "folate_mcg": 21.19, "water_g": 102.44, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store components separately. Fish is best eaten immediately. Pesto keeps for 5 days.", "duration": "P2D"}, "freezer": {"notes": "Pesto can be frozen. Do not freeze the salad or cooked fish.", "duration": "P1M"}, "reheating": "Reheat fish gently in a low oven. Serve salad room temperature.", "does_not_keep": false}', '[{"name": "Large baking sheet", "required": true, "alternative": null}, {"name": "Food processor or mortar and pestle", "required": true, "alternative": null}, {"name": "Large non-stick or cast iron skillet", "required": true, "alternative": null}, {"name": "Fish spatula", "required": true, "alternative": "Wide flat spatula"}, {"name": "Mixing bowls", "required": true, "alternative": null}]', '[{"symptom": "Fish skin is soggy or stuck to pan", "likely_cause": "Pan wasn''t hot enough or fish wasn''t dry enough before cooking", "prevention": "Ensure fish skin is bone-dry and oil is shimmering hot before adding fish", "fix": "Remove carefully; if skin tears, remove it entirely and serve the flesh (flavor is still good)"}, {"symptom": "Pesto is brown/dull", "likely_cause": "Oxidation from heat during blending or sitting too long", "prevention": "Pulse in short bursts to avoid heating the blades; cover surface with oil if storing", "fix": "Cannot be fixed visually, but taste remains fine"}]', '["Nasturtium has a distinct peppery flavor similar to watercress or radish. If unavailable, watercress or arugula (rocket) make excellent substitutes.", "Heritage tomatoes are key here for flavor complexity; if using standard tomatoes, add a pinch of sugar to the marinade to balance acidity.", "Do not crowd the fish in the pan. If your skillet is small, cook in two batches to ensure the skin fries rather than steams.", "Salting the tomatoes early draws out moisture which mixes with the oil to create a natural, delicious ''tomato water'' dressing."]', '"This dish epitomizes modern farm-to-table summer cooking, likely influenced by British or Northern European coastal cuisine where nasturtiums grow prolifically in gardens. It balances the Mediterranean technique of crispy-skin fish with the garden-fresh, peppery notes of heritage botanicals."', 699.87);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ff027ed1-2b7f-4d6c-9ca0-69b642befc56', 'Sautéed Spring Peas and Mushrooms with Fresh Mint', 'A vibrant celebration of spring produce, combining the earthiness of browned cremini mushrooms with the sweetness of tender peas. Brightened with fresh mint and lemon zest, this dish offers a perfect textural contrast and clean, fresh flavors.', 'side dish', 'French', 'Easy', '["mushroom", "easy", "side dish", "spring", "vegetarian", "easter", "gluten-free", "quick"]', '[{"group_name": "Vegetables", "items": [{"name": "cremini mushrooms", "quantity": 250, "unit": "g", "preparation": "cleaned and quartered", "notes": "or white button mushrooms", "substitutions": ["white button mushrooms", "shiitake mushrooms"], "ingredient_id": "fdd23eb2-a71c-46d1-932b-295adf7d5ae5", "nutrition_source": "Aggregated Public Data"}, {"name": "green peas", "quantity": 300, "unit": "g", "preparation": "fresh or frozen", "notes": "if frozen, do not thaw", "substitutions": ["english peas", "petit pois"], "ingredient_id": "881b19fa-ab56-40da-b76e-46e9098ff18f", "nutrition_source": "USDA FoodData Central"}, {"name": "shallot", "quantity": 1, "unit": null, "preparation": "finely diced", "notes": "approx 30g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Fat & Seasoning", "items": [{"name": "unsalted butter", "quantity": 30, "unit": "g", "preparation": "divided", "notes": null, "substitutions": ["olive oil (for vegan)"], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "olive oil", "quantity": 15, "unit": "ml", "preparation": null, "notes": "helps prevent butter burning", "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste, approx 3g", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": "freshly ground", "notes": "to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Finishing", "items": [{"name": "fresh mint leaves", "quantity": 10, "unit": "g", "preparation": "chiffonade (thinly sliced)", "notes": null, "substitutions": [], "ingredient_id": "213e3d3b-d332-45a9-b35e-23ee29a27173", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon zest", "quantity": null, "unit": null, "preparation": null, "notes": "from half a lemon", "substitutions": [], "ingredient_id": "a5fb6a2a-dcda-4ab2-8fe6-472d7fcc39d1", "nutrition_source": "Aggregated Public Data"}, {"name": "lemon juice", "quantity": 5, "unit": "ml", "preparation": null, "notes": "optional, for brightness", "substitutions": [], "ingredient_id": "84822702-05df-495b-91a5-3fe45e48c8d9", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "cook", "text": "Heat the olive oil and half of the butter (15g) in a large skillet over medium-high heat until the butter foams but does not brown.", "structured": {"action": "HEAT", "temperature": {"celsius": 175, "fahrenheit": 347}, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add the quartered mushrooms to the pan in a single layer. Let them cook undisturbed for 3-4 minutes to develop a golden-brown crust.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT4M", "doneness_cues": {"visual": "Golden brown on bottom", "tactile": "Slightly softened"}}, "tips": ["Do not overcrowd the pan, or the mushrooms will steam instead of brown."]}, {"step_number": 3, "phase": "cook", "text": "Stir the mushrooms and add the diced shallot. Cook for 2 minutes until the shallot softens and becomes translucent, reducing heat slightly if necessary to prevent burning.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 160, "fahrenheit": 320}, "duration": "PT2M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the minced garlic and cook for just 30 seconds until fragrant, being careful not to burn it.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT30S", "doneness_cues": {"visual": "Garlic is fragrant but not dark", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Stir in the peas and the remaining butter (15g). Cook for 2-3 minutes until the peas are tender and bright green (if using frozen) or cooked through (if using fresh).", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT3M", "doneness_cues": {"visual": "Peas are vibrant bright green", "tactile": "Peas pop when pressed"}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Remove from heat. Immediately stir in the lemon zest, lemon juice (if using), and fresh mint. Season generously with salt and pepper to taste.", "structured": {"action": "SEASON", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT0M", "total_time": "PT15M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 140}', '{"flags": ["Vegetarian", "Gluten-Free", "Nut-Free", "Soy-Free", "Egg-Free", "Peanut-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 170.58, "protein_g": 5.94, "carbohydrates_g": 15.66, "fat_g": 10.24, "saturated_fat_g": 4.37, "trans_fat_g": null, "monounsaturated_fat_g": 4.53, "polyunsaturated_fat_g": 0.78, "fiber_g": 5.2, "sugar_g": 5.91, "sodium_mg": 301.37, "cholesterol_mg": 16.13, "potassium_mg": 496.27, "calcium_mg": 43.46, "iron_mg": 1.63, "magnesium_mg": 29.35, "phosphorus_mg": 91.58, "zinc_mg": 1.01, "vitamin_a_mcg": 85.18, "vitamin_c_mg": 32.75, "vitamin_d_mcg": null, "vitamin_e_mg": 0.82, "vitamin_k_mcg": 21.88, "vitamin_b6_mg": 0.17, "vitamin_b12_mcg": 0.01, "thiamin_mg": 0.21, "riboflavin_mg": 0.11, "niacin_mg": 1.64, "folate_mcg": 54.76, "water_g": 70.57, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Mint may discolor upon reheating; add fresh herbs after warming.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; texture of mushrooms and peas will degrade.", "duration": null}, "reheating": "Gently reheat in a pan with a splash of water or butter over medium-low heat.", "does_not_keep": false}', '[{"name": "Large skillet or saut\u00e9 pan", "required": true, "alternative": "Wok"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}, {"name": "Microplane or zester", "required": false, "alternative": "Small side of box grater"}]', '[{"symptom": "Mushrooms are soggy and pale", "likely_cause": "Pan was overcrowded or heat was too low", "prevention": "Use a large enough skillet to hold mushrooms in a single layer; cook on medium-high heat.", "fix": "Remove peas/liquid if possible, increase heat to high to evaporate moisture, though texture may be compromised."}, {"symptom": "Peas are wrinkled and grey", "likely_cause": "Overcooked or acidic ingredients (lemon) added too early", "prevention": "Cook peas only until heated through; add lemon juice right before serving.", "fix": "Cannot be fixed visually; serve immediately."}]', '["If using fresh garden peas, blanch them in boiling salted water for 1 minute before adding to the skillet to ensure even cooking with the mushrooms.", "For a richer finish, substitute the final addition of butter with 20ml of heavy cream.", "Tarragon or basil can be excellent alternatives to mint if you prefer a more savory herbal profile."]', '"The combination of peas (petits pois) and lettuce or onions is a staple of French ''\u00e0 la Fran\u00e7aise'' cooking. This recipe simplifies that concept by using mushrooms for umami and quick saut\u00e9ing to preserve the vibrant color and snap of the vegetables, typical of modern spring bistro fare."', 170.58);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ff7ee337-f9ab-449d-9301-fbf9e3a2291e', 'Orecchiette with Swiss Chard, Red Peppers, and Goat Cheese', 'Vibrant orecchiette pasta cradles sweet sautéed red peppers and earthy Swiss chard, finished with tangy dollops of melting goat cheese and a bright lemon zest. A perfect balance of textures and fresh flavors.', 'dinner', 'Italian', 'Easy', '["italian", "dinner", "weeknight", "main course", "spring", "healthy", "vegetarian", "pasta"]', '[{"group_name": "Pasta", "items": [{"name": "dried orecchiette pasta", "quantity": 400, "unit": "g", "preparation": "dry", "notes": null, "substitutions": [], "ingredient_id": "44a505c6-0cdd-4972-844f-a2329a525f70", "nutrition_source": "Aggregated Public Data"}, {"name": "water", "quantity": 4000, "unit": "ml", "preparation": null, "notes": "for boiling", "substitutions": [], "ingredient_id": "52e7e8d1-3737-410a-8018-22d0b768cbd5", "nutrition_source": "Aggregated Public Data"}, {"name": "kosher salt", "quantity": 30, "unit": "g", "preparation": null, "notes": "for pasta water", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Vegetables & Aromatics", "items": [{"name": "swiss chard", "quantity": 1, "unit": null, "preparation": null, "notes": "large bunch (approx 300g), stems and leaves separated", "substitutions": [], "ingredient_id": "cb0f8ccb-3b9d-416c-995f-d0a7924af74c", "nutrition_source": "Aggregated Public Data"}, {"name": "red bell peppers", "quantity": 2, "unit": null, "preparation": "diced", "notes": "approx 300g total", "substitutions": [], "ingredient_id": "8c4f8af4-14ec-4b21-8e25-e2e592f9144d", "nutrition_source": "Aggregated Public Data"}, {"name": "yellow onion", "quantity": 1, "unit": null, "preparation": "diced", "notes": "approx 150g", "substitutions": [], "ingredient_id": "a41c8927-b981-495e-ac59-c5e9b583c1c9", "nutrition_source": "Aggregated Public Data"}, {"name": "garlic cloves", "quantity": 3, "unit": null, "preparation": "minced", "notes": "approx 15g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}]}, {"group_name": "Sauce & Finish", "items": [{"name": "extra virgin olive oil", "quantity": 45, "unit": "ml", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "e9f370c4-07c8-4d8d-8a9f-0edea38db44c", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh goat cheese", "quantity": 120, "unit": "g", "preparation": "crumbled", "notes": null, "substitutions": ["feta", "ricotta"], "ingredient_id": "b054244f-221b-4674-90f8-0a3896462f1f", "nutrition_source": "USDA FoodData Central"}, {"name": "lemon", "quantity": 1, "unit": null, "preparation": null, "notes": "zested and juiced (approx 15ml juice)", "substitutions": [], "ingredient_id": "8787c956-d31c-4dfa-9c29-db1aae17ca59", "nutrition_source": "USDA FoodData Central"}, {"name": "red pepper flakes", "quantity": 2, "unit": "g", "preparation": null, "notes": null, "substitutions": [], "ingredient_id": "fc0b80e8-d1dc-4e69-a42d-0789346d4eb8", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": null, "unit": null, "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "black pepper", "quantity": null, "unit": null, "preparation": null, "notes": "freshly ground, to taste", "substitutions": [], "ingredient_id": "c25dc1c9-4ea7-403c-976e-ab1d06578b7a", "nutrition_source": "Aggregated Public Data"}]}]', '[{"step_number": 1, "phase": "prep", "text": "Separate the Swiss chard stems from the leaves. Finely chop the stems and roughly chop the leaves into bite-sized ribbons. Keep them separate.", "structured": {"action": "CHOP", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Bring a large pot of salted water to a rolling boil (100\u00b0C/212\u00b0F). Add the orecchiette and cook according to package directions until al dente.", "structured": {"action": "BOIL", "temperature": {"celsius": 100, "fahrenheit": 212}, "duration": null, "doneness_cues": {"visual": null, "tactile": "firm to the bite but cooked through"}}, "tips": ["Reserve about 120ml (1/2 cup) of starchy pasta water before draining."]}, {"step_number": 3, "phase": "cook", "text": "While the water boils, heat the olive oil in a large saut\u00e9 pan over medium heat. Add the diced onion, red bell peppers, and chopped chard stems. Saut\u00e9 until the vegetables are softened but not browned.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT6M", "doneness_cues": {"visual": "onions are translucent, peppers are tender", "tactile": null}}, "tips": []}, {"step_number": 4, "phase": "cook", "text": "Add the minced garlic and red pepper flakes to the pan. Stir constantly for about 1 minute until fragrant.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 5, "phase": "cook", "text": "Add the chopped chard leaves to the pan. Cook until just wilted.", "structured": {"action": "SAUT\u00c9", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "leaves are dark green and reduced in volume", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "assemble", "text": "Add the drained pasta and half of the reserved pasta water to the skillet. Toss vigorously to coat the pasta in the vegetable mixture.", "structured": {"action": "MIX", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 7, "phase": "finish", "text": "Remove from heat. Stir in the lemon juice and half of the goat cheese until it begins to melt and create a creamy coating. If the mixture is dry, add more reserved pasta water.", "structured": {"action": "EMULSIFY", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}, {"step_number": 8, "phase": "finish", "text": "Season with salt and black pepper to taste. Serve immediately topped with the remaining crumbled goat cheese and lemon zest.", "structured": {"action": "SERVE", "temperature": null, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT25M", "passive_time": "PT0M", "total_time": "PT25M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 350}', '{"flags": ["Vegetarian", "Nut-Free", "Soy-Free", "Egg-Free"], "not_suitable_for": []}', '{"per_serving": {"calories": 596.87, "protein_g": 22.36, "carbohydrates_g": 87, "fat_g": 19.87, "saturated_fat_g": 6.05, "trans_fat_g": null, "monounsaturated_fat_g": 9.72, "polyunsaturated_fat_g": 1.59, "fiber_g": 6.69, "sugar_g": 8.69, "sodium_mg": 3432.44, "cholesterol_mg": 13.8, "potassium_mg": 707.54, "calcium_mg": 201.32, "iron_mg": 5.12, "magnesium_mg": 92.21, "phosphorus_mg": 152.67, "zinc_mg": 0.88, "vitamin_a_mcg": 444.33, "vitamin_c_mg": 134.09, "vitamin_d_mcg": 0.12, "vitamin_e_mg": 4.47, "vitamin_k_mcg": 634.52, "vitamin_b6_mg": 0.49, "vitamin_b12_mcg": 0.06, "thiamin_mg": 0.13, "riboflavin_mg": 0.28, "niacin_mg": 1.31, "folate_mcg": 58.75, "water_g": 1211.53, "alcohol_g": null, "caffeine_mg": null}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Store in an airtight container. Add a splash of water when reheating to loosen the sauce.", "duration": "P3D"}, "freezer": {"notes": "Not recommended; goat cheese texture may become grainy and pasta mushy.", "duration": null}, "reheating": "Gently warm on the stove over low heat with a splash of water or broth.", "does_not_keep": false}', '[{"name": "Large pot", "required": true, "alternative": null}, {"name": "Large saut\u00e9 pan or skillet", "required": true, "alternative": "Dutch oven"}, {"name": "Colander", "required": true, "alternative": null}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "The dish is dry and the cheese isn''t coating the pasta", "likely_cause": "Not enough pasta water was added or the pasta absorbed the moisture too quickly", "prevention": "Always reserve more pasta water than you think you need", "fix": "Add hot water (or vegetable broth) 1 tablespoon at a time while tossing until creamy"}, {"symptom": "Swiss chard stems are crunchy/hard", "likely_cause": "Stems were not cooked long enough before adding the leaves", "prevention": "Cook stems with the onions and peppers; add leaves only at the very end", "fix": "Add a splash of water to the pan and cover for 2 minutes to steam them rapidly"}]', '["Orecchiette (''little ears'') is the ideal shape for this dish because the cup-like center scoops up the goat cheese and small vegetable pieces.", "Do not skip the lemon zest; the acidity cuts through the rich goat cheese and earthy chard, balancing the flavor profile.", "If you cannot find Swiss chard, kale is a robust alternative, but it will require 2-3 extra minutes of cooking time to tenderize.", "For a deeper flavor, let the red peppers caramelize slightly before adding the garlic."]', '"This dish draws inspiration from the Puglia region of Italy, where orecchiette and bitter greens (typically cime di rapa) are a staple pairing. The addition of goat cheese introduces a modern, creamy element that contrasts with the traditional olive oil-based sauce."', 596.87);
INSERT INTO recipes (id, name, description, category, cuisine, difficulty, tags, ingredients, instructions, meta, dietary, nutrition, storage, equipment, troubleshooting, chef_notes, cultural_context, calories) VALUES ('ffd81a13-cff7-466e-aa8c-89cdbc7fa4e5', 'Velvet Avocado Curry Soup', 'A luxuriously smooth soup where the buttery texture of ripe avocados meets the aromatic warmth of mild curry. Finished with light cream and bright lime to cut the richness, this dish balances savory depth with refreshing notes.', 'soup', 'Modern Fusion', 'Easy', '["one pot", "avocado", "chicken stock", "curry powder", "great leftovers", "light cream", "soup", "appetizer", "quick", "fusion"]', '[{"group_name": "Aromatics & Base", "items": [{"name": "unsalted butter", "quantity": 15, "unit": "g", "preparation": "melted", "notes": null, "substitutions": [], "ingredient_id": "eaea8246-f7e7-43d0-98b1-6e668894fea1", "nutrition_source": "USDA FoodData Central"}, {"name": "shallots", "quantity": 2, "unit": null, "preparation": "finely diced", "notes": "approx. 60g", "substitutions": [], "ingredient_id": "fdfc0723-3dbf-44af-b667-f5e4bd6005a8", "nutrition_source": "USDA FoodData Central"}, {"name": "garlic clove", "quantity": 1, "unit": null, "preparation": "minced", "notes": "approx. 5g", "substitutions": [], "ingredient_id": "30109e1e-d8e8-4f76-a6f4-82ac5b071fde", "nutrition_source": "USDA FoodData Central"}, {"name": "curry powder", "quantity": 5, "unit": "g", "preparation": null, "notes": "mild yellow curry powder", "substitutions": [], "ingredient_id": "e714e2f1-2295-4e8c-8ccf-65c38381e71e", "nutrition_source": "USDA FoodData Central"}, {"name": "chicken stock", "quantity": 500, "unit": "ml", "preparation": "high quality", "notes": null, "substitutions": ["vegetable stock"], "ingredient_id": "7e254f45-046f-4812-bcdd-7e31c9bb59b8", "nutrition_source": "Aggregated Public Data"}]}, {"group_name": "Finish", "items": [{"name": "ripe avocados", "quantity": 2, "unit": null, "preparation": "pitted and scooped", "notes": "large, approx. 400g flesh total", "substitutions": [], "ingredient_id": "35c8f26f-d008-407a-9bf3-48c8aa641729", "nutrition_source": "USDA FoodData Central"}, {"name": "light cream", "quantity": 100, "unit": "ml", "preparation": "single cream", "notes": null, "substitutions": ["coconut milk", "heavy cream"], "ingredient_id": "3faf3fcd-98a0-4d98-8a9c-f81898bb99bb", "nutrition_source": "USDA FoodData Central"}, {"name": "lime juice", "quantity": 15, "unit": "ml", "preparation": null, "notes": "freshly squeezed", "substitutions": [], "ingredient_id": "531b7deb-b63c-41c9-8c01-b7bec6fcd2d0", "nutrition_source": "USDA FoodData Central"}, {"name": "salt", "quantity": 3, "unit": "g", "preparation": null, "notes": "to taste", "substitutions": [], "ingredient_id": "2631739c-2de4-4389-a6e3-ed3d06d0406f", "nutrition_source": "USDA FoodData Central"}, {"name": "fresh cilantro", "quantity": null, "unit": null, "preparation": "chopped", "notes": "for garnish", "substitutions": [], "ingredient_id": "a9eea519-8ecc-4b3c-9dec-8dcaaa33cd87", "nutrition_source": "USDA FoodData Central"}]}]', '[{"step_number": 1, "phase": "cook", "text": "In a heavy-bottomed pot, melt butter over medium heat. Add diced shallots and saut\u00e9 until translucent and soft, avoiding browning.", "structured": {"action": "SAUT\u00c9", "temperature": {"celsius": 150, "fahrenheit": 302}, "duration": "PT4M", "doneness_cues": {"visual": "Shallots are translucent", "tactile": "Soft texture"}}, "tips": []}, {"step_number": 2, "phase": "cook", "text": "Add the minced garlic and curry powder. Stir constantly for 60 seconds to bloom the spices and release their aroma without burning.", "structured": {"action": "TOAST", "temperature": null, "duration": "PT1M", "doneness_cues": null}, "tips": []}, {"step_number": 3, "phase": "cook", "text": "Pour in the chicken stock. Increase heat to bring to a simmer, then reduce heat and let gently simmer to marry flavors.", "structured": {"action": "SIMMER", "temperature": {"celsius": 90, "fahrenheit": 194}, "duration": "PT5M", "doneness_cues": null}, "tips": []}, {"step_number": 4, "phase": "finish", "text": "Remove the pot from the heat completely. This is crucial to prevent the avocado from becoming bitter. Stir in the scooped avocado flesh and light cream.", "structured": {"action": "MIX", "temperature": null, "duration": null, "doneness_cues": {"visual": "Avocado is submerged", "tactile": null}}, "tips": []}, {"step_number": 5, "phase": "finish", "text": "Using an immersion blender, blend the mixture directly in the pot until completely smooth and velvety.", "structured": {"action": "BLEND", "temperature": null, "duration": "PT2M", "doneness_cues": {"visual": "Uniform pale green color, no chunks", "tactile": null}}, "tips": []}, {"step_number": 6, "phase": "finish", "text": "Stir in the lime juice and salt. Taste and adjust seasoning. If the soup has cooled too much, return to very low heat briefly, but do not allow it to bubble. Garnish with cilantro and serve.", "structured": {"action": "SEASON", "temperature": {"celsius": 65, "fahrenheit": 149}, "duration": null, "doneness_cues": null}, "tips": []}]', '{"active_time": "PT15M", "passive_time": "PT5M", "total_time": "PT20M", "overnight_required": false, "yields": "4 servings", "yield_count": 4, "serving_size_g": 250}', '{"flags": ["Gluten-Free", "Egg-Free", "Peanut-Free", "Soy-Free", "Low-Carb"], "not_suitable_for": []}', '{"per_serving": {"calories": 265.23, "protein_g": 7.68, "carbohydrates_g": 22.87, "fat_g": 17.38, "saturated_fat_g": 5.26, "trans_fat_g": null, "monounsaturated_fat_g": 7.18, "polyunsaturated_fat_g": 2.18, "fiber_g": 7.04, "sugar_g": 7.11, "sodium_mg": 733.01, "cholesterol_mg": 10.56, "potassium_mg": 512.1, "calcium_mg": 81.48, "iron_mg": 0.69, "magnesium_mg": 38.03, "phosphorus_mg": 100.18, "zinc_mg": 0.75, "vitamin_a_mcg": 75.44, "vitamin_c_mg": 20.12, "vitamin_d_mcg": 0.05, "vitamin_e_mg": 3.18, "vitamin_k_mcg": 2, "vitamin_b6_mg": 0.16, "vitamin_b12_mcg": 0.13, "thiamin_mg": 0.05, "riboflavin_mg": 0.12, "niacin_mg": 0.8, "folate_mcg": 43.08, "water_g": 109.68, "alcohol_g": null, "caffeine_mg": 0.75}, "sources": ["Aggregated Public Data", "USDA FoodData Central"]}', '{"refrigerator": {"notes": "Avocado oxidizes quickly. Press plastic wrap directly onto the surface of the soup to prevent browning. Reheat very gently; do not boil.", "duration": "P1D"}, "freezer": {"notes": "Do not freeze; emulsion will break and texture will become grainy.", "duration": null}, "reheating": "Warm on low heat to 60\u00b0C maximum to prevent bitterness.", "does_not_keep": false}', '[{"name": "Heavy-bottomed pot", "required": true, "alternative": null}, {"name": "Immersion blender", "required": true, "alternative": "Standard countertop blender"}, {"name": "Chef''s knife", "required": true, "alternative": null}, {"name": "Cutting board", "required": true, "alternative": null}]', '[{"symptom": "Soup tastes bitter", "likely_cause": "Avocado was cooked at too high a temperature or boiled", "prevention": "Remove pot from heat before adding avocado; never boil after blending", "fix": "Add a pinch of sugar and more lime juice to mask the bitterness; difficult to fully fix"}, {"symptom": "Soup turns brown quickly", "likely_cause": "Oxidation due to exposure to air and lack of acid", "prevention": "Ensure lime juice is added immediately after blending; cover surface with plastic wrap if storing", "fix": "Cannot be fixed visually, but safe to eat"}]', '["Ripeness is key: The avocados must be buttery ripe. If they are firm, the soup will be grainy and lack the signature creaminess.", "Do not boil: Cooking avocado at high heat creates distinct bitter compounds. The soup should only be warmed gently.", "Texture adjustment: If the soup is too thick (depending on avocado size), thin it out with a splash of extra stock or water."]', '"While avocado soup has roots in Latin American cuisine, this iteration embraces a modern global palate by incorporating curry powder\u2014a British invention modeling Indian spice blends. The result is a fusion dish that highlights the avocado''s natural fat as a carrier for complex spices."', 265.23);
